:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

/* ── Layout ── */
.vitals {
  max-width: 680px;
  margin: 0 auto;
  padding: 32px 20px 56px;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

/* ── Header ── */
.vitals-head {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.head-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}
.eyebrow {
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--teal-d);
}
.vitals-head h1 {
  font-size: 1.6rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-top: 2px;
}

/* ── BMI pill ── */
.bmi-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 14px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--muted);
  box-shadow: var(--shadow-1);
  white-space: nowrap;
  transition: background 0.2s, border-color 0.2s, color 0.2s;
}
.bmi-pill strong {
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--ink);
}
.bmi-cat {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--teal-50);
  color: var(--teal-d);
  text-transform: capitalize;
}
.bmi-pill[data-cat="under"] {
  border-color: rgba(217, 138, 43, 0.4);
}
.bmi-pill[data-cat="under"] .bmi-cat {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.bmi-pill[data-cat="normal"] {
  border-color: rgba(47, 158, 111, 0.4);
}
.bmi-pill[data-cat="normal"] .bmi-cat {
  background: rgba(47, 158, 111, 0.16);
  color: var(--ok);
}
.bmi-pill[data-cat="over"] {
  border-color: rgba(217, 138, 43, 0.4);
}
.bmi-pill[data-cat="over"] .bmi-cat {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.bmi-pill[data-cat="obese"] {
  border-color: rgba(212, 80, 62, 0.4);
}
.bmi-pill[data-cat="obese"] .bmi-cat {
  background: rgba(212, 80, 62, 0.14);
  color: var(--danger);
}

/* ── Patient row ── */
.patient {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 12px 16px;
  box-shadow: var(--shadow-1);
}
.avatar {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: 50%;
  background: linear-gradient(150deg, var(--teal-50), #d9efec);
  color: var(--teal-700);
  font-size: 0.84rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}
.patient-meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.patient-name {
  font-size: 0.98rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.patient-sub {
  font-size: 0.82rem;
  color: var(--muted);
}

/* ── Timestamp ── */
.stamp {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--muted);
  display: inline-flex;
  align-items: center;
  gap: 7px;
}
.stamp::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--coral);
  flex-shrink: 0;
}
.stamp.is-saved {
  color: var(--ok);
}
.stamp.is-saved::before {
  background: var(--ok);
}

/* ── Form grid ── */
.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.span-2 {
  grid-column: 1 / -1;
}

/* ── Field ── */
.field {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px;
  box-shadow: var(--shadow-1);
  border-left: 3px solid var(--line);
  transition: border-color 0.18s, box-shadow 0.18s;
}
.field.is-warn {
  border-left-color: var(--warn);
}
.field.is-danger {
  border-left-color: var(--danger);
}
.field.is-ok {
  border-left-color: var(--ok);
}
.field-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}
.field-head label {
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--ink);
  transition: color 0.18s;
}
.field.is-warn .field-head label {
  color: var(--warn);
}
.field.is-danger .field-head label {
  color: var(--danger);
}

/* ── Flag chip ── */
.flag {
  font-size: 0.68rem;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 999px;
  white-space: nowrap;
  letter-spacing: 0.02em;
}
.flag[data-level="warn"] {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.flag[data-level="danger"] {
  background: rgba(212, 80, 62, 0.14);
  color: var(--danger);
}

/* ── Inputs ── */
.input-wrap,
.bp-input {
  display: flex;
  align-items: baseline;
  gap: 8px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 10px 12px;
  background: #fbfdfc;
  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;
}
.input-wrap:focus-within,
.bp-input:focus-within {
  border-color: var(--teal);
  background: var(--white);
  box-shadow: 0 0 0 3px rgba(18, 156, 147, 0.14);
}
.field.is-warn .input-wrap,
.field.is-warn .bp-input.is-flagged {
  border-color: rgba(217, 138, 43, 0.5);
}
.field.is-danger .input-wrap,
.field.is-danger .bp-input.is-flagged {
  border-color: rgba(212, 80, 62, 0.5);
}
.input-wrap input,
.bp-input input {
  border: none;
  outline: none;
  background: transparent;
  font: inherit;
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--ink);
  width: 100%;
  min-width: 0;
  letter-spacing: -0.01em;
}
.input-wrap input::placeholder,
.bp-input input::placeholder {
  color: var(--muted);
  font-weight: 600;
  opacity: 0.55;
}
/* hide native spinners for a cleaner clinical look */
input[type="number"]::-webkit-outer-spin-button,
input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
input[type="number"] {
  -moz-appearance: textfield;
  appearance: textfield;
}
.unit {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--muted);
  white-space: nowrap;
  flex-shrink: 0;
}

/* ── Blood pressure paired row ── */
.bp-row {
  display: flex;
  align-items: center;
  gap: 12px;
}
.bp-input {
  flex: 1;
  min-width: 0;
}
.bp-sep {
  font-size: 1.4rem;
  font-weight: 300;
  color: var(--line-2);
}

/* ── Hint ── */
.hint {
  font-size: 0.78rem;
  color: var(--muted);
  margin-top: 9px;
}

/* ── Footer ── */
.form-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-top: 4px;
}
.legend {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
  flex-wrap: wrap;
}
.dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  margin-left: 8px;
}
.dot:first-child {
  margin-left: 0;
}
.dot.ok {
  background: var(--ok);
}
.dot.warn {
  background: var(--warn);
}
.dot.danger {
  background: var(--danger);
}
.foot-actions {
  display: flex;
  gap: 10px;
}

/* ── Buttons ── */
.btn {
  border: none;
  border-radius: 10px;
  padding: 11px 20px;
  font: inherit;
  font-weight: 700;
  font-size: 0.88rem;
  cursor: pointer;
  transition: transform 0.12s, background 0.15s, border-color 0.15s, color 0.15s;
}
.btn:active {
  transform: translateY(1px);
}
.btn:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}
.btn.ghost {
  background: var(--white);
  border: 1px solid var(--line-2);
  color: var(--ink-2);
}
.btn.ghost:hover {
  background: var(--teal-50);
  border-color: var(--teal);
  color: var(--teal-d);
}
.btn.solid {
  background: var(--teal-d);
  color: #fff;
  box-shadow: 0 6px 16px rgba(12, 122, 115, 0.22);
}
.btn.solid:hover {
  background: var(--teal-700);
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
  line-height: 1.45;
}

@media (max-width: 520px) {
  .vitals {
    padding: 24px 16px 48px;
  }
  .head-top {
    flex-direction: column;
    align-items: stretch;
  }
  .bmi-pill {
    align-self: flex-start;
  }
  .grid {
    grid-template-columns: 1fr;
  }
  .bp-row {
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
  }
  .bp-sep {
    display: none;
  }
  .form-foot {
    flex-direction: column;
    align-items: stretch;
  }
  .foot-actions {
    justify-content: flex-end;
  }
}

