:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --pending: #6b7280;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

/* ── App bar ── */
.appbar {
  background: var(--white);
  border-bottom: 1px solid var(--line);
  padding: 14px 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 20;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--ink);
}
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: linear-gradient(150deg, var(--teal), var(--teal-d));
  color: #fff;
  font-size: 1.1rem;
  font-weight: 700;
}
.brand-name {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.brand-name em {
  font-style: normal;
  color: var(--teal-d);
}
.appbar-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.ghost-btn {
  border: 1px solid var(--line);
  background: var(--white);
  color: var(--ink-2);
  border-radius: 11px;
  padding: 9px 14px;
  font: inherit;
  font-weight: 600;
  font-size: 0.85rem;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.ghost-btn:hover {
  background: var(--teal-50);
  border-color: var(--teal);
}
.icon-btn {
  width: 40px;
  height: 40px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--white);
  color: var(--ink-2);
  font-size: 1.1rem;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.icon-btn:hover {
  background: var(--teal-50);
  border-color: var(--teal);
}
.avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: none;
  background: var(--teal-d);
  color: #fff;
  font-weight: 700;
  font-size: 0.82rem;
  cursor: pointer;
}

/* ── Layout ── */
.chart {
  max-width: 1020px;
  margin: 0 auto;
  padding: 22px 28px 56px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

/* ── Allergy alert ── */
.alert {
  display: flex;
  align-items: center;
  gap: 14px;
  background: var(--coral-soft);
  border: 1px solid rgba(212, 80, 62, 0.4);
  border-left: 5px solid var(--danger);
  border-radius: var(--r-md);
  padding: 14px 18px;
  box-shadow: var(--shadow-1);
}
.alert-ic {
  width: 34px;
  height: 34px;
  flex: none;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: var(--danger);
  color: #fff;
  font-size: 1.1rem;
}
.alert-text {
  flex: 1;
  font-size: 0.92rem;
  color: #7a2419;
}
.alert-text strong {
  color: var(--danger);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 0.8rem;
}
.alert-sev {
  font-weight: 700;
  color: var(--danger);
}
.alert-mild {
  font-weight: 600;
  color: var(--warn);
}
.alert-close {
  flex: none;
  width: 30px;
  height: 30px;
  border: none;
  border-radius: 8px;
  background: rgba(212, 80, 62, 0.12);
  color: var(--danger);
  font-size: 0.85rem;
  cursor: pointer;
  transition: background 0.15s;
}
.alert-close:hover {
  background: rgba(212, 80, 62, 0.22);
}
.alert-reopen {
  align-self: flex-start;
  border: 1px solid rgba(212, 80, 62, 0.4);
  background: var(--white);
  color: var(--danger);
  border-radius: 999px;
  padding: 8px 14px;
  font: inherit;
  font-weight: 700;
  font-size: 0.82rem;
  cursor: pointer;
}
.alert-reopen:hover {
  background: var(--coral-soft);
}

/* ── Patient header ── */
.patient-head {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 26px;
  flex-wrap: wrap;
  box-shadow: var(--shadow-1);
}
.ph-id {
  display: flex;
  align-items: center;
  gap: 16px;
}
.ph-avatar {
  width: 64px;
  height: 64px;
  flex: none;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(150deg, var(--teal), var(--teal-d));
  color: #fff;
  font-weight: 800;
  font-size: 1.3rem;
}
.ph-name h1 {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.ph-line {
  color: var(--muted);
  font-size: 0.9rem;
  margin-top: 2px;
}
.ph-flag {
  display: inline-block;
  margin-top: 8px;
  background: var(--teal-50);
  color: var(--teal-d);
  border-radius: 999px;
  padding: 3px 11px;
  font-size: 0.74rem;
  font-weight: 700;
}
.ph-meta {
  display: grid;
  grid-template-columns: repeat(3, auto);
  gap: 12px 30px;
}
.ph-meta dt {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  font-weight: 600;
}
.ph-meta dd {
  font-size: 0.9rem;
  font-weight: 600;
  margin-top: 2px;
}

/* ── Tabs ── */
.tabs {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--line);
  overflow-x: auto;
}
.tab {
  border: none;
  background: transparent;
  color: var(--muted);
  font: inherit;
  font-weight: 600;
  font-size: 0.92rem;
  padding: 12px 16px;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  white-space: nowrap;
  transition: color 0.15s, border-color 0.15s;
}
.tab:hover {
  color: var(--ink);
}
.tab.is-active {
  color: var(--teal-d);
  border-bottom-color: var(--teal);
}

/* ── Panels ── */
.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 22px 24px;
}
.panel[hidden] {
  display: none;
}
.card-h {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}
.muted-h {
  margin-top: 22px;
  color: var(--muted);
}
.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.card {
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 18px;
}

/* ── Problems / encounters ── */
.problems,
.encounters {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.problems li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid var(--line);
}
.problems li:last-child {
  border-bottom: none;
}
.p-name {
  font-weight: 600;
  font-size: 0.92rem;
}
.p-meta {
  font-size: 0.8rem;
  color: var(--muted);
  margin-top: 2px;
}
.encounters li {
  display: flex;
  gap: 14px;
  padding: 10px 0;
  border-bottom: 1px solid var(--line);
  font-size: 0.9rem;
}
.encounters li:last-child {
  border-bottom: none;
}
.e-date {
  flex: none;
  width: 92px;
  color: var(--teal-d);
  font-weight: 600;
  font-size: 0.84rem;
}

/* ── Snapshot ── */
.snapshot {
  margin-top: 18px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.snap {
  background: var(--teal-50);
  border-radius: var(--r-sm);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.snap-k {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--teal-700);
  font-weight: 600;
}
.snap-v {
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--ink);
}

/* ── Badges ── */
.badge {
  font-size: 0.74rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  white-space: nowrap;
}
.badge.ok {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}
.badge.warn {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.badge.pending {
  background: rgba(107, 114, 128, 0.14);
  color: var(--pending);
}
.badge.danger {
  background: rgba(212, 80, 62, 0.14);
  color: var(--danger);
}

/* ── Timeline ── */
.timeline {
  list-style: none;
  position: relative;
  padding-left: 24px;
}
.timeline::before {
  content: "";
  position: absolute;
  left: 6px;
  top: 6px;
  bottom: 6px;
  width: 2px;
  background: var(--line-2);
}
.timeline li {
  position: relative;
  display: flex;
  gap: 16px;
  padding: 10px 0;
}
.timeline li::before {
  content: "";
  position: absolute;
  left: -22px;
  top: 14px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--teal);
  border: 2px solid var(--white);
  box-shadow: 0 0 0 2px var(--teal-50);
}
.t-date {
  flex: none;
  width: 100px;
  color: var(--teal-d);
  font-weight: 600;
  font-size: 0.84rem;
  padding-top: 1px;
}
.t-title {
  font-weight: 600;
  font-size: 0.92rem;
}
.t-desc {
  font-size: 0.84rem;
  color: var(--muted);
  margin-top: 2px;
}

/* ── Tables ── */
.table-wrap {
  overflow-x: auto;
}
.med-table,
.vitals-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}
.med-table th,
.vitals-table th {
  text-align: left;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
  font-weight: 600;
  padding: 8px 12px;
  border-bottom: 1px solid var(--line-2);
}
.med-table td,
.vitals-table td {
  padding: 11px 12px;
  border-bottom: 1px solid var(--line);
}
.vitals-table th[scope="row"] {
  text-transform: none;
  letter-spacing: 0;
  font-size: 0.88rem;
  color: var(--ink);
  border-bottom: 1px solid var(--line);
}
.med-table tbody tr:hover,
.vitals-table tbody tr:hover {
  background: var(--teal-50);
}

/* ── Discontinued meds ── */
.dc-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.dc-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid var(--line);
  font-size: 0.9rem;
  color: var(--ink-2);
  text-decoration: line-through;
  text-decoration-color: var(--line-2);
}
.dc-list li:last-child {
  border-bottom: none;
}
.dc-reason {
  font-size: 0.8rem;
  color: var(--muted);
  text-decoration: none;
}

/* ── Allergies ── */
.allergy-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.al-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 16px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line);
  border-left-width: 4px;
}
.al-row.sev-high {
  border-left-color: var(--danger);
  background: rgba(212, 80, 62, 0.05);
}
.al-row.sev-mid {
  border-left-color: var(--warn);
  background: rgba(217, 138, 43, 0.05);
}
.al-row.sev-low {
  border-left-color: var(--ok);
  background: rgba(47, 158, 111, 0.05);
}
.al-name {
  font-weight: 600;
  font-size: 0.94rem;
}
.al-meta {
  font-size: 0.82rem;
  color: var(--muted);
  margin-top: 2px;
}

/* ── Trends & sparkline ── */
.trend {
  font-weight: 700;
  font-size: 0.9rem;
}
.trend.up {
  color: var(--ok);
}
.trend.down {
  color: var(--teal-d);
}
.trend.flat {
  color: var(--muted);
}
.spark-card {
  margin-top: 20px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 18px;
}
.spark-label {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
  margin-bottom: 12px;
}
.spark {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  height: 72px;
}
.spark span {
  flex: 1;
  height: var(--h);
  border-radius: 6px 6px 0 0;
  background: linear-gradient(180deg, var(--teal), var(--teal-d));
  min-width: 14px;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}

@media (max-width: 760px) {
  .grid-2 {
    grid-template-columns: 1fr;
  }
  .snapshot {
    grid-template-columns: repeat(2, 1fr);
  }
  .ph-meta {
    grid-template-columns: repeat(2, auto);
  }
  .patient-head {
    align-items: flex-start;
  }
}

