// ── Toast ──────────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2600);
}

// ── Tab switching ────────────────────────────────────────────────────────────
const tabs = Array.from(document.querySelectorAll(".tab"));
const panels = Array.from(document.querySelectorAll(".panel"));

function activateTab(name) {
  for (const tab of tabs) {
    const on = tab.dataset.tab === name;
    tab.classList.toggle("is-active", on);
    tab.setAttribute("aria-selected", on ? "true" : "false");
  }
  for (const panel of panels) {
    const on = panel.dataset.panel === name;
    panel.classList.toggle("is-active", on);
    panel.hidden = !on;
  }
}

document.querySelector(".tabs").addEventListener("click", (e) => {
  const tab = e.target.closest(".tab");
  if (!tab) return;
  activateTab(tab.dataset.tab);
});

// ── Allergy alert: dismiss / re-open ─────────────────────────────────────────
const alert = document.getElementById("allergyAlert");
const alertClose = document.getElementById("alertClose");
const alertReopen = document.getElementById("alertReopen");

alertClose.addEventListener("click", () => {
  alert.hidden = true;
  alertReopen.hidden = false;
  showToast("Allergy alert collapsed — allergies remain on file.");
});

alertReopen.addEventListener("click", () => {
  alert.hidden = false;
  alertReopen.hidden = true;
  alertReopen.blur();
});

// ── Print chart ──────────────────────────────────────────────────────────────
document.getElementById("printBtn").addEventListener("click", () => {
  showToast("Preparing chart for print — opening the print dialog…");
});

snippets.css:
:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow: 0 2px 8px rgba(0, 0, 0, 0.4), 0 16px 40px rgba(0, 0, 0, 0.45);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  background: var(--bg);
  color: var(--ink);
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 32px 16px;
  background-image:
    radial-gradient(900px 500px at 12% -10%, rgba(198, 255, 58, 0.07), transparent 60%),
    radial-gradient(800px 480px at 110% 10%, rgba(255, 106, 43, 0.08), transparent 55%);
}

.demo-root {
  width: 100%;
  display: grid;
  place-items: center;
}

/* ---- CARD ---- */
.class-card {
  width: 100%;
  max-width: 460px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--shadow);
}

button {
  font-family: inherit;
  cursor: pointer;
}

:focus-visible {
  outline: 2px solid var(--neon);
  outline-offset: 2px;
  border-radius: var(--r-sm);
}

.eyebrow,
.section-label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---- HERO ---- */
.hero {
  position: relative;
  padding: 18px;
  min-height: 220px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background:
    linear-gradient(135deg, rgba(255, 106, 43, 0.35), transparent 55%),
    linear-gradient(220deg, rgba(198, 255, 58, 0.22), transparent 50%),
    var(--surface-2);
  isolation: isolate;
}

.hero__overlay {
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(120% 90% at 80% 0%, rgba(255, 106, 43, 0.4), transparent 60%),
    repeating-linear-gradient(
      115deg,
      rgba(255, 255, 255, 0.03) 0 2px,
      transparent 2px 14px
    );
}

.hero__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.eyebrow {
  color: var(--neon);
  background: rgba(13, 15, 18, 0.5);
  padding: 6px 10px;
  border-radius: 999px;
  backdrop-filter: blur(6px);
}

.intensity {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 6px 11px;
  border-radius: 999px;
  background: rgba(13, 15, 18, 0.6);
  border: 1px solid var(--line-2);
  backdrop-filter: blur(6px);
}

.intensity__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--orange);
  box-shadow: 0 0 0 0 rgba(255, 106, 43, 0.6);
  animation: pulse 1.8s infinite;
}

@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(255, 106, 43, 0.6); }
  70% { box-shadow: 0 0 0 8px rgba(255, 106, 43, 0); }
  100% { box-shadow: 0 0 0 0 rgba(255, 106, 43, 0); }
}

.intensity--high {
  color: var(--orange);
}

.hero__title {
  font-size: 38px;
  font-weight: 900;
  line-height: 1.02;
  letter-spacing: -0.02em;
  text-transform: uppercase;
}

.hero__sub {
  margin-top: 8px;
  font-size: 13.5px;
  color: var(--ink-2);
  max-width: 34ch;
}

/* ---- BODY ---- */
.body {
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* trainer */
.trainer {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
}

.trainer__avatar {
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 800;
  font-size: 15px;
  color: #0d0f12;
  background: linear-gradient(140deg, var(--neon), var(--neon-d));
}

.trainer__meta {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
  flex: 1;
  min-width: 0;
}

.trainer__label {
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

.trainer__name {
  font-size: 16px;
  font-weight: 700;
}

.trainer__rating {
  font-size: 12px;
  color: var(--warn);
}

.btn-ghost {
  flex: 0 0 auto;
  font-size: 12.5px;
  font-weight: 700;
  color: var(--ink);
  background: transparent;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  padding: 8px 14px;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}

.btn-ghost:hover {
  background: var(--elevated);
  border-color: var(--line-2);
}

.btn-ghost.is-following {
  color: #0d0f12;
  background: var(--neon);
  border-color: var(--neon);
}

/* meta grid */
.meta-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.meta {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 12px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
}

.meta__label {
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.meta__value {
  font-size: 14.5px;
  font-weight: 700;
}

/* difficulty */
.difficulty__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.difficulty__tag {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--orange);
  background: var(--orange-soft);
  padding: 4px 10px;
  border-radius: 999px;
}

.meter {
  display: flex;
  gap: 6px;
}

.meter__bar {
  flex: 1;
  height: 10px;
  border-radius: 999px;
  background: var(--elevated);
  transition: background 0.2s;
}

.meter__bar.is-on {
  background: linear-gradient(90deg, var(--orange), var(--neon));
}

/* bring */
.bring__list {
  list-style: none;
  margin-top: 10px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 12px;
}

.bring__list li {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 13.5px;
  font-weight: 500;
  color: var(--ink-2);
}

.bring__ic {
  width: 28px;
  height: 28px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  font-size: 14px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
}

/* spots */
.spots__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 10px;
}

.spots__count {
  font-size: 13px;
  color: var(--ink-2);
}

.spots__count strong {
  color: var(--ink);
  font-weight: 800;
}

.progress {
  height: 12px;
  border-radius: 999px;
  background: var(--elevated);
  overflow: hidden;
}

.progress__fill {
  display: block;
  height: 100%;
  width: 70%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--neon-d), var(--neon));
  transition: width 0.45s cubic-bezier(0.22, 1, 0.36, 1), background 0.3s;
}

.progress.is-full .progress__fill {
  background: linear-gradient(90deg, var(--orange), var(--danger));
}

.spots__hint {
  margin-top: 8px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--neon);
}

.spots__hint.is-warn {
  color: var(--warn);
}

.spots__hint.is-full {
  color: var(--orange);
}

/* roster */
.roster__row {
  margin-top: 10px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.avatars {
  list-style: none;
  display: flex;
  flex: 0 0 auto;
}

.avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 11.5px;
  font-weight: 800;
  color: #0d0f12;
  background: var(--clr, var(--muted));
  background: color-mix(in srgb, var(--clr, #888) 85%, white);
  border: 2px solid var(--surface);
  margin-left: calc(var(--i) == 0 ? 0 : -10px);
  margin-left: -10px;
}

.avatar:first-child {
  margin-left: 0;
}

.avatar--more {
  color: var(--ink);
  background: var(--elevated);
  font-weight: 700;
  font-size: 11px;
}

.roster__names {
  font-size: 12.5px;
  color: var(--muted);
  min-width: 0;
}

/* ---- CTA ---- */
.cta {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 18px calc(16px + env(safe-area-inset-bottom));
  background: var(--surface-2);
  border-top: 1px solid var(--line);
}

.cta__price {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
  flex: 0 0 auto;
}

.cta__amount {
  font-size: 16px;
  font-weight: 800;
}

.cta__note {
  font-size: 11.5px;
  color: var(--muted);
}

.btn-book {
  flex: 1;
  border: none;
  border-radius: var(--r-md);
  padding: 15px 18px;
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: #0d0f12;
  background: var(--neon);
  transition: transform 0.12s, background 0.18s, box-shadow 0.18s;
  box-shadow: 0 8px 22px rgba(198, 255, 58, 0.22);
}

.btn-book:hover {
  background: var(--neon-d);
}

.btn-book:active {
  transform: translateY(1px) scale(0.99);
}

.btn-book.is-booked {
  color: var(--ink);
  background: var(--elevated);
  box-shadow: none;
  border: 1px solid var(--line-2);
}

.btn-book.is-booked:hover {
  background: rgba(248, 113, 113, 0.14);
  border-color: rgba(248, 113, 113, 0.4);
  color: var(--danger);
}

.btn-book.is-waitlist {
  color: #0d0f12;
  background: var(--orange);
  box-shadow: 0 8px 22px rgba(255, 106, 43, 0.25);
}

.btn-book.is-waitlist:hover {
  background: #ff7e47;
}

/* ---- TOAST ---- */
.toast-wrap {
  position: fixed;
  left: 50%;
  bottom: 22px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 50;
  width: max-content;
  max-width: 90vw;
}

.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  background: var(--elevated);
  border: 1px solid var(--line-2);
  border-left: 3px solid var(--neon);
  border-radius: var(--r-md);
  color: var(--ink);
  font-size: 13.5px;
  font-weight: 600;
  box-shadow: var(--shadow);
  animation: toast-in 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.toast.is-out {
  animation: toast-out 0.25s forwards ease-in;
}

.toast--warn {
  border-left-color: var(--orange);
}

@keyframes toast-in {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes toast-out {
  to { opacity: 0; transform: translateY(10px); }
}

/* ---- RESPONSIVE ---- */
@media (max-width: 520px) {
  body {
    padding: 0;
    place-items: stretch;
  }

  .class-card {
    max-width: none;
    min-height: 100vh;
    border: none;
    border-radius: 0;
    box-shadow: none;
    display: flex;
    flex-direction: column;
  }

  .body {
    flex: 1;
  }

  .hero__title {
    font-size: 32px;
  }

  .meta-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 360px) {
  .bring__list {
    grid-template-columns: 1fr;
  }

  .cta {
    flex-wrap: wrap;
  }

  .cta__price {
    flex: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

