(function () {
  "use strict";

  // ---- State ----
  var TOTAL = 20;
  var state = {
    booked: 14,
    total: TOTAL,
    isBookedByMe: false,
    isWaitlisted: false,
    following: false,
  };

  // ---- Elements ----
  var $ = function (sel) { return document.querySelector(sel); };

  var els = {
    book: $("[data-book]"),
    bookLabel: $(".btn-book__label"),
    progress: $("[data-progress]"),
    fill: $("[data-fill]"),
    bookedEl: $("[data-booked]"),
    totalEl: $("[data-total]"),
    hint: $("[data-hint]"),
    follow: $("[data-follow]"),
    toastWrap: $("[data-toast-wrap]"),
    avatars: $("[data-avatars]"),
    more: $("[data-more]"),
    names: $("[data-names]"),
  };

  // ---- Toast helper ----
  function toast(msg, kind) {
    if (!els.toastWrap) return;
    var t = document.createElement("div");
    t.className = "toast" + (kind === "warn" ? " toast--warn" : "");
    t.textContent = msg;
    els.toastWrap.appendChild(t);
    setTimeout(function () {
      t.classList.add("is-out");
      t.addEventListener("animationend", function () { t.remove(); });
    }, 2600);
  }

  // ---- Render ----
  function spotsLeft() {
    return Math.max(0, state.total - state.booked);
  }

  function isFull() {
    return state.booked >= state.total;
  }

  function render() {
    var left = spotsLeft();
    var pct = Math.min(100, (state.booked / state.total) * 100);

    els.fill.style.width = pct + "%";
    els.bookedEl.textContent = String(state.booked);
    els.totalEl.textContent = String(state.total);
    els.progress.setAttribute("aria-valuenow", String(state.booked));
    els.progress.classList.toggle("is-full", isFull());

    // hint
    els.hint.classList.remove("is-warn", "is-full");
    if (isFull()) {
      if (state.isWaitlisted) {
        els.hint.textContent = "Class is full — you're on the waitlist.";
      } else {
        els.hint.textContent = "Class is full — join the waitlist.";
      }
      els.hint.classList.add("is-full");
    } else if (left <= 6) {
      els.hint.textContent = left + " spots left — fills up fast.";
      els.hint.classList.add("is-warn");
    } else {
      els.hint.textContent = left + " spots available.";
    }

    // CTA
    els.book.classList.remove("is-booked", "is-waitlist");
    if (state.isBookedByMe) {
      els.book.classList.add("is-booked");
      els.bookLabel.textContent = "Booked ✓ — Cancel?";
      els.book.setAttribute("aria-pressed", "true");
    } else if (state.isWaitlisted) {
      els.book.classList.add("is-waitlist");
      els.bookLabel.textContent = "On waitlist — Leave?";
      els.book.setAttribute("aria-pressed", "true");
    } else if (isFull()) {
      els.book.classList.add("is-waitlist");
      els.bookLabel.textContent = "Join waitlist";
      els.book.setAttribute("aria-pressed", "false");
    } else {
      els.bookLabel.textContent = "Book this class";
      els.book.setAttribute("aria-pressed", "false");
    }
  }

  // ---- Roster ----
  var myAvatar = null;
  function addMyAvatar() {
    if (myAvatar) return;
    myAvatar = document.createElement("li");
    myAvatar.className = "avatar";
    myAvatar.textContent = "ME";
    myAvatar.style.setProperty("--clr", "#c6ff3a");
    myAvatar.style.marginLeft = "-10px";
    els.avatars.insertBefore(myAvatar, els.more);
    bumpMore(1);
  }
  function removeMyAvatar() {
    if (!myAvatar) return;
    myAvatar.remove();
    myAvatar = null;
    bumpMore(-1);
  }
  function bumpMore(delta) {
    var cur = parseInt((els.more.textContent || "+0").replace("+", ""), 10) || 0;
    els.more.textContent = "+" + Math.max(0, cur + delta);
  }

  // ---- Actions ----
  function onBook() {
    if (state.isBookedByMe) {
      // cancel booking
      state.isBookedByMe = false;
      state.booked = Math.max(0, state.booked - 1);
      removeMyAvatar();
      toast("Booking cancelled. Your credit is back.", "warn");
    } else if (state.isWaitlisted) {
      // leave waitlist
      state.isWaitlisted = false;
      toast("Left the waitlist.", "warn");
    } else if (isFull()) {
      // join waitlist
      state.isWaitlisted = true;
      toast("You're on the waitlist — we'll text you if a spot opens.");
    } else {
      // book
      state.isBookedByMe = true;
      state.booked += 1;
      addMyAvatar();
      toast("You're in! HIIT Burn 45 · Mon 6:30 AM.");
    }
    render();
  }

  function onFollow() {
    state.following = !state.following;
    els.follow.classList.toggle("is-following", state.following);
    els.follow.textContent = state.following ? "Following" : "Follow";
    toast(
      state.following
        ? "Following coach Mara Reyes."
        : "Unfollowed Mara Reyes.",
      state.following ? undefined : "warn"
    );
  }

  // ---- Wire up ----
  els.book.addEventListener("click", onBook);
  els.follow.addEventListener("click", onFollow);

  render();
})();

snippets.css:
:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(0, 0, 0, 0.4);
  --shadow-2: 0 10px 30px rgba(0, 0, 0, 0.45);
  --shadow-3: 0 24px 60px rgba(0, 0, 0, 0.6);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button,
input,
select {
  font-family: inherit;
}

:focus-visible {
  outline: 2px solid var(--neon);
  outline-offset: 2px;
  border-radius: var(--r-sm);
}

.app {
  max-width: 1120px;
  margin: 0 auto;
  padding: 28px 24px 64px;
}

/* ---------- Topbar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 24px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-mark {
  width: 48px;
  height: 48px;
  border-radius: var(--r-md);
  background: var(--neon);
  color: #0c0f06;
  display: grid;
  place-items: center;
  font-weight: 900;
  font-size: 18px;
  letter-spacing: 0.5px;
  box-shadow: 0 6px 18px rgba(198, 255, 58, 0.3);
}

.eyebrow {
  display: block;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
}

.brand-text h1 {
  margin: 2px 0 0;
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: var(--r-md);
  padding: 11px 18px;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.08s ease, background 0.15s ease, border-color 0.15s ease,
    box-shadow 0.15s ease;
  white-space: nowrap;
}

.btn:active {
  transform: translateY(1px);
}

.btn-neon {
  background: var(--neon);
  color: #0c0f06;
  box-shadow: 0 8px 22px rgba(198, 255, 58, 0.24);
}

.btn-neon:hover {
  background: var(--neon-d);
}

.btn-ghost {
  background: transparent;
  color: var(--ink-2);
  border-color: var(--line-2);
}

.btn-ghost:hover {
  background: var(--surface-2);
  color: var(--ink);
}

.btn-danger {
  background: var(--danger);
  color: #2a0d0d;
}

.btn-danger:hover {
  filter: brightness(1.05);
}

.plus {
  font-size: 18px;
  font-weight: 800;
  line-height: 1;
}

/* ---------- Stats ---------- */
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 22px;
}

.stat {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 18px;
  box-shadow: var(--shadow-1);
}

.stat-label {
  display: block;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
}

.stat-value {
  display: block;
  margin-top: 6px;
  font-size: 28px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

/* ---------- Toolbar ---------- */
.toolbar {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}

.search {
  position: relative;
  flex: 1 1 260px;
  max-width: 360px;
}

.search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  color: var(--muted);
  pointer-events: none;
}

.search input {
  width: 100%;
  background: var(--surface);
  border: 1px solid var(--line-2);
  border-radius: var(--r-md);
  color: var(--ink);
  padding: 12px 14px 12px 42px;
  font-size: 14px;
}

.search input::placeholder {
  color: var(--muted);
}

.filters {
  display: flex;
  align-items: flex-end;
  gap: 12px;
  flex-wrap: wrap;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
}

select,
input[type="text"],
input[type="time"],
input[type="number"],
input[type="search"] {
  background: var(--surface);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  color: var(--ink);
  padding: 10px 12px;
  font-size: 14px;
  min-height: 42px;
}

.filters select {
  min-width: 150px;
}

select:hover,
input:hover {
  border-color: rgba(255, 255, 255, 0.26);
}

/* ---------- Table ---------- */
.table-wrap {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--shadow-2);
}

table.classes {
  width: 100%;
  border-collapse: collapse;
}

.classes thead th {
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
  padding: 14px 18px;
  background: var(--surface-2);
  border-bottom: 1px solid var(--line);
}

.col-actions {
  text-align: right;
}

.classes tbody tr {
  border-bottom: 1px solid var(--line);
  transition: background 0.12s ease;
}

.classes tbody tr:last-child {
  border-bottom: none;
}

.classes tbody tr:hover {
  background: var(--surface-2);
}

.classes td {
  padding: 14px 18px;
  font-size: 14px;
  vertical-align: middle;
}

.cell-class {
  display: flex;
  align-items: center;
  gap: 12px;
}

.type-dot {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  font-weight: 800;
  font-size: 13px;
  flex-shrink: 0;
  background: var(--neon-50);
  color: var(--neon);
}

.cls-name {
  font-weight: 700;
  letter-spacing: -0.01em;
}

.cls-type {
  font-size: 12px;
  color: var(--muted);
  font-weight: 600;
}

.schedule {
  font-weight: 600;
}

.schedule .sched-time {
  display: block;
  color: var(--muted);
  font-size: 12.5px;
  font-weight: 500;
}

.cap {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 92px;
}

.cap-num {
  font-weight: 700;
  font-size: 13px;
}

.cap-bar {
  height: 6px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.cap-fill {
  height: 100%;
  border-radius: 999px;
  background: var(--neon);
}

.cap-fill.high {
  background: var(--orange);
}

.cap-fill.full {
  background: var(--danger);
}

/* badges */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.badge::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.badge-active {
  background: rgba(52, 211, 153, 0.14);
  color: var(--ok);
}

.badge-draft {
  background: rgba(251, 191, 36, 0.14);
  color: var(--warn);
}

.badge-cancelled {
  background: rgba(248, 113, 113, 0.14);
  color: var(--danger);
}

/* row actions */
.row-actions {
  display: flex;
  gap: 6px;
  justify-content: flex-end;
}

.icon-btn {
  background: transparent;
  border: 1px solid var(--line-2);
  color: var(--ink-2);
  border-radius: var(--r-sm);
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  cursor: pointer;
  font-size: 16px;
  line-height: 1;
  transition: background 0.12s ease, color 0.12s ease, border-color 0.12s ease;
}

.icon-btn:hover {
  background: var(--surface-2);
  color: var(--ink);
}

.icon-btn.danger:hover {
  background: var(--orange-soft);
  color: var(--orange);
  border-color: rgba(255, 106, 43, 0.4);
}

.icon-btn svg {
  width: 16px;
  height: 16px;
}

/* inline confirm */
.confirm {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--ink-2);
  font-weight: 600;
}

.confirm .mini {
  padding: 6px 12px;
  font-size: 12.5px;
  border-radius: var(--r-sm);
}

.empty {
  padding: 48px 24px;
  text-align: center;
  color: var(--muted);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}

.empty p {
  margin: 0;
  font-weight: 600;
}

/* ---------- Modal ---------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(6, 8, 11, 0.7);
  backdrop-filter: blur(4px);
  display: grid;
  place-items: center;
  padding: 20px;
  z-index: 50;
  animation: fade 0.16s ease;
}

.modal {
  width: 100%;
  max-width: 620px;
  background: var(--surface);
  border: 1px solid var(--line-2);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-3);
  max-height: 92vh;
  overflow: auto;
  animation: pop 0.18s cubic-bezier(0.2, 0.8, 0.3, 1.2);
}

.modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 22px;
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  background: var(--surface);
}

.modal-head h2 {
  margin: 0;
  font-size: 19px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.modal-head .icon-btn {
  font-size: 22px;
  width: 36px;
  height: 36px;
}

form {
  padding: 22px;
}

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.span-2 {
  grid-column: 1 / -1;
}

.err {
  font-size: 12px;
  font-weight: 600;
  color: var(--danger);
  min-height: 0;
  display: none;
}

.field.invalid input,
.field.invalid select {
  border-color: var(--danger);
}

.field.invalid .err {
  display: block;
}

.switch-row {
  display: flex;
  gap: 8px;
}

.seg {
  flex: 1;
  background: var(--surface-2);
  border: 1px solid var(--line-2);
  color: var(--ink-2);
  border-radius: var(--r-sm);
  padding: 10px;
  font-weight: 700;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.12s ease;
}

.seg:hover {
  color: var(--ink);
}

.seg.on {
  background: var(--neon-50);
  border-color: var(--neon);
  color: var(--neon);
}

.modal-foot {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 24px;
}

/* ---------- Toasts ---------- */
.toast-stack {
  position: fixed;
  bottom: 22px;
  right: 22px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  z-index: 80;
}

.toast {
  background: var(--elevated);
  border: 1px solid var(--line-2);
  border-left: 4px solid var(--neon);
  border-radius: var(--r-md);
  padding: 12px 16px;
  font-size: 14px;
  font-weight: 600;
  color: var(--ink);
  box-shadow: var(--shadow-2);
  animation: slidein 0.22s ease;
  max-width: 320px;
}

.toast.danger {
  border-left-color: var(--orange);
}

.toast.leaving {
  animation: slideout 0.22s ease forwards;
}

@keyframes fade {
  from {
    opacity: 0;
  }
}

@keyframes pop {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.98);
  }
}

@keyframes slidein {
  from {
    opacity: 0;
    transform: translateX(20px);
  }
}

@keyframes slideout {
  to {
    opacity: 0;
    transform: translateX(20px);
  }
}

@keyframes rowin {
  from {
    background: var(--neon-50);
  }
}

tr.flash {
  animation: rowin 0.9s ease;
}

/* ---------- Responsive ---------- */
@media (max-width: 880px) {
  .stats {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 760px) {
  .col-room,
  .col-cap,
  td.cell-room,
  td.cell-cap {
    display: none;
  }
}

@media (max-width: 520px) {
  .app {
    padding: 20px 14px 56px;
  }

  .brand-text h1 {
    font-size: 21px;
  }

  .topbar {
    gap: 12px;
  }

  .addBtn,
  #addBtn {
    flex: 1;
  }

  .toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .search {
    max-width: none;
  }

  .filters {
    width: 100%;
  }

  .filters select {
    flex: 1;
    min-width: 0;
  }

  .grid {
    grid-template-columns: 1fr;
  }

  .span-2 {
    grid-column: 1;
  }

  .classes thead {
    display: none;
  }

  .classes tbody tr {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 8px 12px;
    padding: 14px 16px;
    align-items: center;
  }

  .classes td {
    padding: 0;
  }

  .cell-class {
    grid-column: 1 / -1;
  }

  .cell-trainer,
  .cell-schedule {
    font-size: 13px;
    color: var(--ink-2);
  }

  td.cell-status {
    grid-column: 1;
  }

  td.cell-actions {
    grid-column: 2;
  }

  td.cell-room,
  td.cell-cap {
    display: none;
  }

  .stat-value {
    font-size: 24px;
  }
}

