(function () {
  "use strict";

  /* ---------------- In-memory store ---------------- */
  var uid = 0;
  function id() {
    uid += 1;
    return "c" + uid;
  }

  var classes = [
    {
      id: id(),
      name: "Sunrise HIIT",
      type: "HIIT",
      trainer: "Mara Velez",
      day: "Monday",
      time: "06:30",
      duration: 45,
      room: "Studio A",
      capacity: 24,
      booked: 22,
      status: "active",
    },
    {
      id: id(),
      name: "Power Strength",
      type: "Strength",
      trainer: "Theo Brandt",
      day: "Monday",
      time: "18:00",
      duration: 60,
      room: "Strength Floor",
      capacity: 18,
      booked: 18,
      status: "active",
    },
    {
      id: id(),
      name: "Rhythm Ride",
      type: "Spin",
      trainer: "Devon Cole",
      day: "Tuesday",
      time: "19:15",
      duration: 50,
      room: "Spin Loft",
      capacity: 30,
      booked: 19,
      status: "active",
    },
    {
      id: id(),
      name: "Flow & Restore",
      type: "Yoga",
      trainer: "Priya Nandakumar",
      day: "Wednesday",
      time: "08:00",
      duration: 60,
      room: "Mind & Body",
      capacity: 20,
      booked: 11,
      status: "active",
    },
    {
      id: id(),
      name: "Knockout Boxing",
      type: "Boxing",
      trainer: "Imani Okafor",
      day: "Thursday",
      time: "20:00",
      duration: 45,
      room: "Studio B",
      capacity: 16,
      booked: 6,
      status: "draft",
    },
    {
      id: id(),
      name: "Core Pilates",
      type: "Pilates",
      trainer: "Luca Ferreira",
      day: "Friday",
      time: "12:00",
      duration: 40,
      room: "Mind & Body",
      capacity: 14,
      booked: 0,
      status: "cancelled",
    },
  ];

  /* ---------------- Elements ---------------- */
  var $ = function (sel, root) {
    return (root || document).querySelector(sel);
  };
  var tbody = $("#tbody");
  var empty = $("#empty");
  var searchEl = $("#search");
  var filterType = $("#filterType");
  var filterTrainer = $("#filterTrainer");
  var backdrop = $("#backdrop");
  var form = $("#form");
  var modalTitle = $("#modalTitle");
  var toasts = $("#toasts");

  var fieldIds = [
    "fName",
    "fType",
    "fTrainer",
    "fDay",
    "fTime",
    "fDuration",
    "fRoom",
    "fCapacity",
  ];

  var TYPES = ["HIIT", "Strength", "Spin", "Yoga", "Boxing", "Pilates", "Mobility"];
  var DAY_ABBR = {
    Monday: "Mon",
    Tuesday: "Tue",
    Wednesday: "Wed",
    Thursday: "Thu",
    Friday: "Fri",
    Saturday: "Sat",
    Sunday: "Sun",
  };

  var currentStatus = "active";

  /* ---------------- Helpers ---------------- */
  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        '"': "&quot;",
        "'": "&#39;",
      }[c];
    });
  }

  function fmtTime(t) {
    if (!t) return "";
    var parts = t.split(":");
    var h = parseInt(parts[0], 10);
    var m = parts[1];
    var ap = h >= 12 ? "PM" : "AM";
    var h12 = h % 12;
    if (h12 === 0) h12 = 12;
    return h12 + ":" + m + " " + ap;
  }

  function toast(msg, kind) {
    var el = document.createElement("div");
    el.className = "toast" + (kind ? " " + kind : "");
    el.textContent = msg;
    toasts.appendChild(el);
    setTimeout(function () {
      el.classList.add("leaving");
      setTimeout(function () {
        if (el.parentNode) el.parentNode.removeChild(el);
      }, 220);
    }, 2600);
  }

  function trainers() {
    var set = {};
    classes.forEach(function (c) {
      set[c.trainer] = true;
    });
    return Object.keys(set).sort();
  }

  /* ---------------- Stats ---------------- */
  function renderStats() {
    $("#statTotal").textContent = classes.length;
    $("#statActive").textContent = classes.filter(function (c) {
      return c.status === "active";
    }).length;
    $("#statCapacity").textContent = classes
      .filter(function (c) {
        return c.status === "active";
      })
      .reduce(function (sum, c) {
        return sum + c.capacity;
      }, 0);
    $("#statTrainers").textContent = trainers().length;
  }

  /* ---------------- Filter selects ---------------- */
  function syncFilterOptions() {
    var prevTrainer = filterTrainer.value;
    // types are fixed
    if (filterType.options.length <= 1) {
      TYPES.forEach(function (t) {
        var o = document.createElement("option");
        o.value = t;
        o.textContent = t;
        filterType.appendChild(o);
      });
    }
    filterTrainer.innerHTML = '<option value="">All trainers</option>';
    trainers().forEach(function (t) {
      var o = document.createElement("option");
      o.value = t;
      o.textContent = t;
      filterTrainer.appendChild(o);
    });
    if (prevTrainer) filterTrainer.value = prevTrainer;
  }

  /* ---------------- Render rows ---------------- */
  function visible() {
    var q = searchEl.value.trim().toLowerCase();
    var ft = filterType.value;
    var fr = filterTrainer.value;
    return classes.filter(function (c) {
      if (ft && c.type !== ft) return false;
      if (fr && c.trainer !== fr) return false;
      if (q) {
        var hay = (c.name + " " + c.type + " " + c.trainer + " " + c.room + " " + c.day).toLowerCase();
        if (hay.indexOf(q) === -1) return false;
      }
      return true;
    });
  }

  function capFillClass(pct) {
    if (pct >= 100) return "full";
    if (pct >= 80) return "high";
    return "";
  }

  function rowHtml(c) {
    var pct = c.capacity ? Math.round((c.booked / c.capacity) * 100) : 0;
    if (pct > 100) pct = 100;
    var initials = c.type.slice(0, 2).toUpperCase();
    return (
      '<td class="cell-class">' +
      '<div class="cell-class">' +
      '<span class="type-dot">' +
      esc(initials) +
      "</span>" +
      "<span>" +
      '<span class="cls-name">' +
      esc(c.name) +
      "</span><br>" +
      '<span class="cls-type">' +
      esc(c.type) +
      "</span>" +
      "</span>" +
      "</div>" +
      "</td>" +
      '<td class="cell-trainer">' +
      esc(c.trainer) +
      "</td>" +
      '<td class="cell-schedule"><span class="schedule">' +
      esc(DAY_ABBR[c.day] || c.day) +
      '<span class="sched-time">' +
      fmtTime(c.time) +
      " · " +
      c.duration +
      " min</span></span></td>" +
      '<td class="cell-room col-room">' +
      esc(c.room) +
      "</td>" +
      '<td class="cell-cap col-cap"><div class="cap">' +
      '<span class="cap-num">' +
      c.booked +
      " / " +
      c.capacity +
      "</span>" +
      '<span class="cap-bar"><span class="cap-fill ' +
      capFillClass(pct) +
      '" style="width:' +
      pct +
      '%"></span></span>' +
      "</div></td>" +
      '<td class="cell-status"><span class="badge badge-' +
      c.status +
      '">' +
      c.status.charAt(0).toUpperCase() +
      c.status.slice(1) +
      "</span></td>" +
      '<td class="cell-actions"><div class="row-actions" data-id="' +
      c.id +
      '">' +
      '<button class="icon-btn" data-act="edit" aria-label="Edit ' +
      esc(c.name) +
      '" title="Edit">' +
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 013 3L7 19l-4 1 1-4z"/></svg>' +
      "</button>" +
      '<button class="icon-btn danger" data-act="del" aria-label="Delete ' +
      esc(c.name) +
      '" title="Delete">' +
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M19 6l-1 14H6L5 6"/></svg>' +
      "</button>" +
      "</div></td>"
    );
  }

  function render() {
    var rows = visible();
    tbody.innerHTML = "";
    rows.forEach(function (c) {
      var tr = document.createElement("tr");
      tr.dataset.id = c.id;
      tr.innerHTML = rowHtml(c);
      tbody.appendChild(tr);
    });
    empty.hidden = rows.length !== 0;
    renderStats();
  }

  /* ---------------- Modal ---------------- */
  var lastFocused = null;

  function setStatusSeg(status) {
    currentStatus = status;
    var segs = form.querySelectorAll(".seg");
    Array.prototype.forEach.call(segs, function (s) {
      s.classList.toggle("on", s.dataset.status === status);
    });
  }

  function clearErrors() {
    fieldIds.forEach(function (fid) {
      var f = $("#" + fid);
      if (f) f.closest(".field").classList.remove("invalid");
    });
  }

  function openModal(cls) {
    lastFocused = document.activeElement;
    form.reset();
    clearErrors();
    if (cls) {
      modalTitle.textContent = "Edit class";
      $("#fId").value = cls.id;
      $("#fName").value = cls.name;
      $("#fType").value = cls.type;
      $("#fTrainer").value = cls.trainer;
      $("#fDay").value = cls.day;
      $("#fTime").value = cls.time;
      $("#fDuration").value = cls.duration;
      $("#fRoom").value = cls.room;
      $("#fCapacity").value = cls.capacity;
      setStatusSeg(cls.status);
    } else {
      modalTitle.textContent = "Add class";
      $("#fId").value = "";
      setStatusSeg("active");
    }
    backdrop.hidden = false;
    document.body.style.overflow = "hidden";
    setTimeout(function () {
      $("#fName").focus();
    }, 30);
  }

  function closeModal() {
    backdrop.hidden = true;
    document.body.style.overflow = "";
    if (lastFocused && lastFocused.focus) lastFocused.focus();
  }

  function setError(fid, msg) {
    var f = $("#" + fid);
    var field = f.closest(".field");
    field.classList.add("invalid");
    var err = field.querySelector(".err");
    if (err) err.textContent = msg;
  }

  function validate() {
    clearErrors();
    var ok = true;
    var v = {
      name: $("#fName").value.trim(),
      type: $("#fType").value,
      trainer: $("#fTrainer").value,
      day: $("#fDay").value,
      time: $("#fTime").value,
      duration: parseInt($("#fDuration").value, 10),
      room: $("#fRoom").value,
      capacity: parseInt($("#fCapacity").value, 10),
    };
    if (!v.name) {
      setError("fName", "Class name is required.");
      ok = false;
    }
    if (!v.type) {
      setError("fType", "Pick a type.");
      ok = false;
    }
    if (!v.trainer) {
      setError("fTrainer", "Pick a trainer.");
      ok = false;
    }
    if (!v.day) {
      setError("fDay", "Pick a day.");
      ok = false;
    }
    if (!v.time) {
      setError("fTime", "Set a start time.");
      ok = false;
    }
    if (!v.duration || v.duration < 15) {
      setError("fDuration", "Min 15 minutes.");
      ok = false;
    }
    if (!v.room) {
      setError("fRoom", "Pick a room.");
      ok = false;
    }
    if (!v.capacity || v.capacity < 1) {
      setError("fCapacity", "Capacity must be at least 1.");
      ok = false;
    }
    return ok ? v : null;
  }

  /* ---------------- Events ---------------- */
  $("#addBtn").addEventListener("click", function () {
    openModal(null);
  });
  $("#closeModal").addEventListener("click", closeModal);
  $("#cancelModal").addEventListener("click", closeModal);
  backdrop.addEventListener("click", function (e) {
    if (e.target === backdrop) closeModal();
  });
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && !backdrop.hidden) closeModal();
  });

  form.addEventListener("click", function (e) {
    var seg = e.target.closest(".seg");
    if (seg) {
      e.preventDefault();
      setStatusSeg(seg.dataset.status);
    }
  });

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var v = validate();
    if (!v) {
      toast("Please fix the highlighted fields.", "danger");
      return;
    }
    var editId = $("#fId").value;
    if (editId) {
      var c = classes.find(function (x) {
        return x.id === editId;
      });
      if (c) {
        if (v.capacity < c.booked) c.booked = v.capacity;
        c.name = v.name;
        c.type = v.type;
        c.trainer = v.trainer;
        c.day = v.day;
        c.time = v.time;
        c.duration = v.duration;
        c.room = v.room;
        c.capacity = v.capacity;
        c.status = currentStatus;
      }
      closeModal();
      render();
      flash(editId);
      toast("Class updated.");
    } else {
      var nc = {
        id: id(),
        name: v.name,
        type: v.type,
        trainer: v.trainer,
        day: v.day,
        time: v.time,
        duration: v.duration,
        room: v.room,
        capacity: v.capacity,
        booked: 0,
        status: currentStatus,
      };
      classes.unshift(nc);
      // reset filters that would hide the new row
      if (filterType.value && filterType.value !== nc.type) filterType.value = "";
      if (filterTrainer.value && filterTrainer.value !== nc.trainer)
        filterTrainer.value = "";
      searchEl.value = "";
      syncFilterOptions();
      closeModal();
      render();
      flash(nc.id);
      toast("Class added.");
    }
  });

  function flash(rid) {
    var tr = tbody.querySelector('tr[data-id="' + rid + '"]');
    if (tr) tr.classList.add("flash");
  }

  /* row actions: edit / delete (inline confirm) */
  tbody.addEventListener("click", function (e) {
    var btn = e.target.closest("button[data-act]");
    if (!btn) return;
    var wrap = btn.closest(".row-actions");
    var rid = wrap.dataset.id;
    var cls = classes.find(function (x) {
      return x.id === rid;
    });
    if (!cls) return;

    if (btn.dataset.act === "edit") {
      openModal(cls);
      return;
    }

    if (btn.dataset.act === "del") {
      showConfirm(wrap, rid, cls.name);
    }
  });

  function showConfirm(wrap, rid, name) {
    var original = wrap.innerHTML;
    wrap.innerHTML =
      '<span class="confirm">Delete?' +
      '<button class="btn btn-danger mini" data-c="yes">Yes</button>' +
      '<button class="btn btn-ghost mini" data-c="no">No</button>' +
      "</span>";
    wrap.querySelector('[data-c="no"]').addEventListener("click", function () {
      wrap.innerHTML = original;
    });
    wrap.querySelector('[data-c="yes"]').addEventListener("click", function () {
      classes = classes.filter(function (x) {
        return x.id !== rid;
      });
      syncFilterOptions();
      render();
      toast('"' + name + '" deleted.', "danger");
    });
  }

  /* filters */
  searchEl.addEventListener("input", render);
  filterType.addEventListener("change", render);
  filterTrainer.addEventListener("change", render);

  function clearFilters() {
    searchEl.value = "";
    filterType.value = "";
    filterTrainer.value = "";
    render();
  }
  $("#clearFilters").addEventListener("click", clearFilters);
  $("#emptyClear").addEventListener("click", clearFilters);

  /* ---------------- Init ---------------- */
  syncFilterOptions();
  render();
})();

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
  /* leaflet text scale — toggled by JS */
  --scale: 1;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
  padding: 28px 16px 64px;
}

/* ── Sheet ─────────────────────────────────────────────────────────────────── */
.sheet {
  max-width: 640px;
  margin: 0 auto;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-1);
  padding: 26px 28px 30px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  /* the text-scale lever: everything sized in em flexes with this */
  font-size: calc(1rem * var(--scale));
  transition: font-size 0.18s ease;
}

/* ── Toolbar ───────────────────────────────────────────────────────────────── */
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--line);
  font-size: 1rem; /* keep toolbar fixed regardless of scale */
}
.size-toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.size-label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--muted);
  margin-right: 4px;
}
.size-btn {
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink-2);
  border-radius: var(--r-sm);
  min-width: 38px;
  height: 34px;
  padding: 0 8px;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  line-height: 1;
  transition: background 0.15s, border-color 0.15s, color 0.15s, transform 0.1s;
}
.size-btn:nth-child(3) {
  font-size: 1.02rem;
}
.size-btn:nth-child(4) {
  font-size: 1.16rem;
}
.size-btn:hover {
  border-color: var(--teal);
  color: var(--teal-d);
  background: var(--teal-50);
}
.size-btn:active {
  transform: translateY(1px);
}
.size-btn[aria-pressed="true"] {
  background: var(--teal-d);
  border-color: var(--teal-d);
  color: #fff;
}
.print-btn {
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink-2);
  border-radius: var(--r-sm);
  padding: 0 16px;
  height: 34px;
  font: inherit;
  font-weight: 600;
  font-size: 0.86rem;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background 0.15s, border-color 0.15s, color 0.15s, transform 0.1s;
}
.print-btn:hover {
  border-color: var(--teal);
  color: var(--teal-d);
  background: var(--teal-50);
}
.print-btn:active {
  transform: translateY(1px);
}
.print-btn span {
  font-size: 1.05rem;
}

:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}

/* ── Header ────────────────────────────────────────────────────────────────── */
.med-head {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}
.med-icon {
  flex-shrink: 0;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: linear-gradient(150deg, var(--teal-50), #d4ede9);
  color: var(--teal-700);
  font-size: 1.7em;
  font-weight: 800;
}
.med-head-text {
  min-width: 0;
}
.eyebrow {
  font-size: 0.74em;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--teal-d);
}
.med-head h1 {
  font-size: 1.7em;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin-top: 2px;
}
.strength {
  color: var(--teal-d);
  font-weight: 700;
}
.generic {
  color: var(--muted);
  font-size: 0.9em;
  margin-top: 4px;
}
.head-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}
.pill {
  font-size: 0.76em;
  font-weight: 700;
  padding: 5px 11px;
  border-radius: 999px;
  background: var(--teal-50);
  color: var(--teal-d);
  white-space: nowrap;
}
.pill-soft {
  background: #eef3f2;
  color: var(--ink-2);
}

.patient-line {
  font-size: 0.86em;
  color: var(--ink-2);
  background: #f7fbfa;
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  padding: 10px 14px;
}
.patient-line strong {
  color: var(--ink);
  font-weight: 700;
}

/* ── Generic block ─────────────────────────────────────────────────────────── */
.block h2,
.warn-body h2,
.missed h2 {
  font-size: 1.04em;
  font-weight: 800;
  letter-spacing: -0.01em;
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.dot {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  flex-shrink: 0;
}
.dot-teal {
  background: var(--teal);
}
.dot-coral {
  background: var(--coral);
}
.block p {
  font-size: 0.95em;
  color: var(--ink-2);
}
.block-intro {
  margin-bottom: 10px;
}
.block-note {
  margin-top: 12px;
  font-size: 0.86em !important;
  color: var(--muted);
  font-style: italic;
}

/* ── How to take — steps ───────────────────────────────────────────────────── */
.steps {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.steps li {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  background: #f7fbfa;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 16px;
}
.step-num {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: var(--teal-d);
  color: #fff;
  font-size: 0.82em;
  font-weight: 800;
}
.step-title {
  font-size: 0.96em;
  font-weight: 700;
  color: var(--ink);
}
.step-sub {
  font-size: 0.86em;
  color: var(--muted);
  margin-top: 2px;
}

/* ── Side effects list ─────────────────────────────────────────────────────── */
.se-list {
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 16px;
}
.se-list li {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 0.92em;
  color: var(--ink-2);
  padding: 9px 12px;
  background: var(--coral-soft);
  border-radius: var(--r-sm);
}
.se-ico {
  color: var(--coral);
  font-weight: 800;
  font-size: 1.1em;
  line-height: 1;
}

/* ── Warnings callout ──────────────────────────────────────────────────────── */
.warn-callout {
  display: flex;
  gap: 16px;
  background: linear-gradient(180deg, #fff3f0, #ffe9e3);
  border: 1px solid rgba(212, 80, 62, 0.32);
  border-left: 5px solid var(--danger);
  border-radius: var(--r-md);
  padding: 18px 20px;
}
.warn-icon {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: var(--danger);
  color: #fff;
  font-size: 1.3em;
  font-weight: 800;
}
.warn-body h2 {
  color: #b23a2a;
  margin-bottom: 8px;
}
.warn-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.warn-list li {
  position: relative;
  padding-left: 18px;
  font-size: 0.92em;
  color: var(--ink);
  font-weight: 500;
}
.warn-list li::before {
  content: "";
  position: absolute;
  left: 2px;
  top: 0.62em;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--danger);
}
.warn-foot {
  margin-top: 12px;
  font-size: 0.88em;
  color: var(--ink-2);
}
.warn-foot strong {
  color: #b23a2a;
}

/* ── Do / Don't chips ──────────────────────────────────────────────────────── */
.dod-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.dod-head {
  font-size: 0.8em;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 10px;
}
.dod-head.do {
  color: var(--ok);
}
.dod-head.dont {
  color: var(--danger);
}
.chips {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.chip {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 0.88em;
  font-weight: 600;
  padding: 9px 12px;
  border-radius: var(--r-sm);
  border: 1px solid transparent;
}
.chip span {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  font-size: 0.72em;
  font-weight: 800;
  color: #fff;
}
.chip-do {
  background: rgba(47, 158, 111, 0.1);
  border-color: rgba(47, 158, 111, 0.25);
  color: #1f7a53;
}
.chip-do span {
  background: var(--ok);
}
.chip-dont {
  background: rgba(212, 80, 62, 0.08);
  border-color: rgba(212, 80, 62, 0.22);
  color: #a8392a;
}
.chip-dont span {
  background: var(--danger);
}

/* ── Missed a dose ─────────────────────────────────────────────────────────── */
.missed {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  background: var(--teal-50);
  border: 1px solid rgba(18, 156, 147, 0.28);
  border-radius: var(--r-md);
  padding: 18px 20px;
}
.missed-icon {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: var(--teal-d);
  color: #fff;
  font-size: 1.15em;
}
.missed h2 {
  color: var(--teal-700);
  margin-bottom: 6px;
}
.missed p {
  font-size: 0.92em;
  color: var(--ink-2);
}
.missed strong {
  color: var(--teal-700);
}

/* ── Footer ────────────────────────────────────────────────────────────────── */
.sheet-foot {
  border-top: 1px solid var(--line);
  padding-top: 16px;
  text-align: center;
}
.sheet-foot p {
  font-size: 0.82em;
  color: var(--muted);
}
.sheet-foot .ref {
  font-size: 0.76em;
  margin-top: 4px;
  letter-spacing: 0.01em;
}

/* ── Toast ─────────────────────────────────────────────────────────────────── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}

/* ── Responsive ────────────────────────────────────────────────────────────── */
@media (max-width: 520px) {
  body {
    padding: 16px 10px 48px;
  }
  .sheet {
    padding: 20px 18px 24px;
    border-radius: var(--r-md);
  }
  .toolbar {
    justify-content: center;
  }
  .se-list,
  .dod-grid {
    grid-template-columns: 1fr;
  }
  .med-head h1 {
    font-size: 1.5em;
  }
}

/* ── Print ─────────────────────────────────────────────────────────────────── */
@media print {
  body {
    background: #fff;
    padding: 0;
  }
  .toolbar,
  .toast {
    display: none !important;
  }
  .sheet {
    box-shadow: none;
    border: none;
    border-radius: 0;
    max-width: none;
    font-size: 1rem;
  }
  .warn-callout,
  .missed,
  .steps li,
  .se-list li {
    break-inside: avoid;
  }
}

