// ── Toast ────────────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2600);
}

// ── Time helpers ─────────────────────────────────────────────────────────────
const DAY_NAMES = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

// "HH:MM" → minutes since midnight, or null when empty/closed.
function toMinutes(value) {
  if (!value) return null;
  const [h, m] = value.split(":").map(Number);
  if (Number.isNaN(h) || Number.isNaN(m)) return null;
  return h * 60 + m;
}

function fmtClock(date) {
  return date.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
}

function fmtTime(mins) {
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  const d = new Date();
  d.setHours(h, m, 0, 0);
  return fmtClock(d);
}

// ── Live open / closed status ────────────────────────────────────────────────
// Returns { state: "open" | "soon-close" | "soon-open" | "closed", label }.
function computeStatus(card, now) {
  const day = now.getDay(); // 0 = Sun … 6 = Sat
  const minutesNow = now.getHours() * 60 + now.getMinutes();

  const todayCell = card.querySelector(`tr[data-day="${day}"] td`);
  const open = toMinutes(todayCell?.dataset.open);
  const close = toMinutes(todayCell?.dataset.close);

  // Open today and currently within hours.
  if (open !== null && close !== null && minutesNow >= open && minutesNow < close) {
    if (close - minutesNow <= 60) {
      return { state: "soon-close", label: `Closes ${fmtTime(close)}` };
    }
    return { state: "open", label: `Open · until ${fmtTime(close)}` };
  }

  // Closed now — does it open later today?
  if (open !== null && minutesNow < open) {
    if (open - minutesNow <= 60) {
      return { state: "soon-open", label: `Opens ${fmtTime(open)}` };
    }
    return { state: "closed", label: `Opens ${fmtTime(open)}` };
  }

  // Otherwise, find the next day with hours (within the coming week).
  for (let step = 1; step <= 7; step++) {
    const d = (day + step) % 7;
    const cell = card.querySelector(`tr[data-day="${d}"] td`);
    const o = toMinutes(cell?.dataset.open);
    if (o !== null) {
      const when = step === 1 ? "tomorrow" : DAY_NAMES[d];
      return { state: "closed", label: `Opens ${when}` };
    }
  }

  return { state: "closed", label: "Closed" };
}

function paintCard(card, now) {
  const day = now.getDay();

  // Highlight today's row.
  card.querySelectorAll("tr[data-day]").forEach((row) => {
    row.classList.toggle("is-today", Number(row.dataset.day) === day);
  });

  // Live badge.
  const { state, label } = computeStatus(card, now);
  const badge = card.querySelector("[data-status]");
  badge.hidden = false;
  badge.className = "badge";
  if (state === "open") badge.classList.add("is-open");
  else if (state === "soon-close" || state === "soon-open") badge.classList.add("is-soon");
  else badge.classList.add("is-closed");
  badge.textContent = label;
}

function refresh() {
  const now = new Date();
  document.getElementById("now-line").textContent =
    `${DAY_NAMES[now.getDay()]}, ${fmtClock(now)} — your local time`;
  document.querySelectorAll(".loc-card").forEach((card) => paintCard(card, now));
}

refresh();
// Re-evaluate every 30s so the badge flips at opening/closing time without a reload.
setInterval(refresh, 30000);

// ── Actions ──────────────────────────────────────────────────────────────────
document.querySelector(".grid").addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action]");
  if (!btn) return;
  const name = btn.dataset.name;
  if (btn.dataset.action === "directions") {
    showToast(`Opening directions to Northpoint — ${name}…`);
  } else if (btn.dataset.action === "call") {
    showToast(`Calling Northpoint — ${name}…`);
  }
});

snippets.css:
:root {
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --sh-sm: 0 1px 2px rgba(28, 24, 20, 0.05);
  --sh-md: 0 8px 24px -12px rgba(28, 24, 20, 0.22);
  --sh-lg: 0 24px 60px -28px rgba(28, 24, 20, 0.34);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--sans);
  line-height: 1.5;
  color: var(--ink);
  background:
    radial-gradient(1100px 520px at 85% -10%, var(--rose-soft), transparent 60%),
    radial-gradient(900px 480px at -5% 0%, var(--gold-soft), transparent 55%),
    var(--bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

.inv {
  max-width: 1120px;
  margin: 0 auto;
  padding: clamp(20px, 4vw, 48px) clamp(16px, 4vw, 40px) 56px;
}

/* ============ HEADER ============ */
.inv__head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--line);
}

.kicker {
  margin: 0 0 6px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold-d);
}

.inv__title {
  margin: 0;
  font-family: var(--serif);
  font-weight: 600;
  font-size: clamp(30px, 5.4vw, 46px);
  line-height: 1.04;
  letter-spacing: 0.01em;
  color: var(--ink);
}

.inv__sub {
  margin: 6px 0 0;
  font-size: 13.5px;
  color: var(--muted);
}

.inv__meta {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  font-size: 12.5px;
  font-weight: 500;
  color: var(--ink-2);
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  box-shadow: var(--sh-sm);
}

.chip__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 3px rgba(95, 138, 107, 0.18);
}

/* ============ BUTTONS ============ */
.btn {
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.01em;
  padding: 9px 16px;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.14s ease, box-shadow 0.18s ease,
    background 0.18s ease, border-color 0.18s ease, color 0.18s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.btn--ghost {
  background: var(--white);
  color: var(--ink-2);
  border-color: var(--line-2);
  box-shadow: var(--sh-sm);
}

.btn--ghost:hover {
  border-color: var(--gold);
  color: var(--gold-d);
}

/* ============ SUMMARY CARDS ============ */
.cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin: 26px 0 30px;
}

.card {
  position: relative;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 18px 20px 16px;
  box-shadow: var(--sh-md);
  overflow: hidden;
}

.card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: var(--gold);
  opacity: 0.7;
}

.card--low::before {
  background: var(--warn);
}
.card--out::before {
  background: var(--danger);
}
.card--value::before {
  background: var(--rose);
}

.card__label {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}

.card__value {
  margin: 8px 0 2px;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 34px;
  line-height: 1;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.card--low .card__value {
  color: var(--warn);
}
.card--out .card__value {
  color: var(--danger);
}

.card__note {
  margin: 6px 0 0;
  font-size: 12px;
  color: var(--muted);
}

/* ============ TOOLBAR ============ */
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

.tabs {
  display: inline-flex;
  gap: 4px;
  padding: 4px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  box-shadow: var(--sh-sm);
}

.tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-2);
  background: transparent;
  border: none;
  padding: 8px 16px;
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease;
}

.tab:hover {
  color: var(--gold-d);
}

.tab.is-active {
  background: var(--ink);
  color: var(--cream);
  box-shadow: var(--sh-md);
}

.tab:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.tab__count {
  font-size: 11.5px;
  font-weight: 600;
  min-width: 20px;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--gold-soft);
  color: var(--gold-d);
  font-variant-numeric: tabular-nums;
}

.tab.is-active .tab__count {
  background: rgba(247, 241, 232, 0.16);
  color: var(--cream);
}

.search {
  position: relative;
  flex: 1;
  min-width: 230px;
  max-width: 360px;
}

.search__icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--muted);
  pointer-events: none;
}

.search__input {
  width: 100%;
  font-family: var(--sans);
  font-size: 13.5px;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: 999px;
  padding: 11px 16px 11px 38px;
  box-shadow: var(--sh-sm);
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}

.search__input::placeholder {
  color: var(--muted);
}

.search__input:focus {
  outline: none;
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.16);
}

/* ============ PANEL + TABLE ============ */
.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-lg);
  overflow: hidden;
}

.table-wrap {
  overflow-x: auto;
}

.table-wrap:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: -2px;
}

.tbl {
  width: 100%;
  border-collapse: collapse;
  min-width: 760px;
}

.tbl thead th {
  text-align: left;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--muted);
  padding: 16px 16px 12px;
  background: var(--cream);
  border-bottom: 1px solid var(--line-2);
  white-space: nowrap;
}

.tbl__num {
  text-align: right;
}
.tbl__act {
  text-align: right;
}

.tbl tbody td {
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
  font-size: 13.5px;
  color: var(--ink-2);
  vertical-align: middle;
}

.tbl tbody tr {
  transition: background 0.18s ease;
}

.tbl tbody tr:last-child td {
  border-bottom: none;
}

.tbl tbody tr:hover {
  background: rgba(176, 141, 87, 0.05);
}

.tbl tbody tr.row--low {
  background: rgba(192, 138, 62, 0.07);
}
.tbl tbody tr.row--low:hover {
  background: rgba(192, 138, 62, 0.12);
}
.tbl tbody tr.row--out {
  background: rgba(179, 80, 62, 0.07);
}
.tbl tbody tr.row--out:hover {
  background: rgba(179, 80, 62, 0.12);
}

.tbl tbody tr.flash {
  animation: flash 0.6s ease;
}

@keyframes flash {
  0% {
    background: rgba(176, 141, 87, 0.28);
  }
  100% {
    background: transparent;
  }
}

/* product cell */
.prod {
  display: flex;
  align-items: center;
  gap: 12px;
}

.prod__sw {
  flex: none;
  width: 38px;
  height: 38px;
  border-radius: var(--r-sm);
  display: grid;
  place-items: center;
  font-family: var(--serif);
  font-weight: 700;
  font-size: 15px;
  color: var(--white);
  letter-spacing: 0.02em;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.25);
}

.prod__name {
  font-weight: 600;
  color: var(--ink);
  font-size: 13.5px;
  line-height: 1.2;
}

.prod__brand {
  margin-top: 2px;
  font-size: 11.5px;
  color: var(--muted);
}

.sku {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 12px;
  letter-spacing: 0.02em;
  color: var(--muted);
  white-space: nowrap;
}

.num {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  white-space: nowrap;
}

.retail {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--ink);
  white-space: nowrap;
}

.supplier {
  font-size: 12.5px;
  color: var(--muted);
  white-space: nowrap;
}

/* stepper */
.stepper {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 2px;
}

.step {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: none;
  background: transparent;
  color: var(--ink-2);
  font-size: 16px;
  line-height: 1;
  font-weight: 600;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background 0.15s ease, color 0.15s ease;
}

.step:hover:not(:disabled) {
  background: var(--white);
  color: var(--gold-d);
  box-shadow: var(--sh-sm);
}

.step:active:not(:disabled) {
  transform: scale(0.92);
}

.step:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 1px;
}

.step:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.stepper__val {
  min-width: 30px;
  text-align: center;
  font-size: 13.5px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}

/* status pill */
.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.02em;
  padding: 4px 11px;
  border-radius: 999px;
  white-space: nowrap;
}

.pill::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.pill--ok {
  color: var(--ok);
  background: rgba(95, 138, 107, 0.12);
}
.pill--low {
  color: var(--warn);
  background: rgba(192, 138, 62, 0.14);
}
.pill--out {
  color: var(--danger);
  background: rgba(179, 80, 62, 0.13);
}

/* reorder action */
.reorder {
  font-family: var(--sans);
  font-size: 12px;
  font-weight: 600;
  color: var(--gold-d);
  background: var(--white);
  border: 1px solid var(--gold);
  border-radius: 999px;
  padding: 6px 13px;
  cursor: pointer;
  transition: background 0.16s ease, color 0.16s ease, transform 0.12s ease;
  white-space: nowrap;
}

.reorder:hover {
  background: var(--gold);
  color: var(--white);
}

.reorder:active {
  transform: translateY(1px);
}

.reorder:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.reorder.is-done {
  border-color: var(--line-2);
  color: var(--muted);
  cursor: default;
}
.reorder.is-done:hover {
  background: var(--white);
  color: var(--muted);
}

.act-cell {
  text-align: right;
}

.dash {
  color: var(--line-2);
}

/* empty + footer */
.empty {
  text-align: center;
  padding: 40px 20px;
  font-size: 14px;
  color: var(--muted);
}

.link {
  background: none;
  border: none;
  font: inherit;
  color: var(--gold-d);
  font-weight: 600;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.inv__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-top: 18px;
  padding: 0 4px;
  font-size: 12.5px;
  color: var(--muted);
}

.inv__foot-note {
  color: var(--rose);
}

/* ============ TOAST ============ */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 16px);
  background: var(--ink);
  color: var(--cream);
  font-size: 13.5px;
  font-weight: 500;
  padding: 12px 20px;
  border-radius: 999px;
  box-shadow: var(--sh-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  z-index: 50;
  max-width: calc(100vw - 32px);
}

.toast.is-show {
  opacity: 1;
  transform: translate(-50%, 0);
}

.toast__accent {
  color: var(--gold-soft);
  font-weight: 700;
}

/* ============ RESPONSIVE ============ */
@media (max-width: 920px) {
  .cards {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 520px) {
  .inv__head {
    align-items: flex-start;
  }

  .cards {
    grid-template-columns: 1fr 1fr;
    gap: 12px;
  }

  .card {
    padding: 14px 15px 13px;
    border-radius: var(--r-md);
  }

  .card__value {
    font-size: 28px;
  }

  .toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .tabs {
    justify-content: space-between;
  }

  .search {
    max-width: none;
  }

  .tab {
    flex: 1;
    justify-content: center;
    padding: 8px 10px;
  }

  .inv__foot {
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
  }
}

