    { id: "p5",  name: "Developer 20 Vol 1L",           brand: "Maison Toné",   sku: "MTN-DEV-20", onHand: 9,  par: 4,  price: 26,  supplier: "Toné Pro Supply",   color: "#b5bcc2" },
    { id: "p6",  name: "Argan Finishing Oil 100ml",     brand: "Fleur d'Or",    sku: "FDO-OIL-100",onHand: 3,  par: 6,  price: 48,  supplier: "Fleur d'Or Beauté", color: "#b08d57" },
    { id: "p7",  name: "Sea-Salt Texture Spray 200ml",  brand: "Fleur d'Or",    sku: "FDO-TXT-200",onHand: 11, par: 6,  price: 32,  supplier: "Fleur d'Or Beauté", color: "#a7b3a0" },
    { id: "p8",  name: "Thermal Shield Mist 150ml",     brand: "Fleur d'Or",    sku: "FDO-THM-150",onHand: 6,  par: 6,  price: 34,  supplier: "Fleur d'Or Beauté", color: "#c08a3e" },
    { id: "p9",  name: "Aria Ionic Blow Dryer",         brand: "Vance Tools",   sku: "VNC-DRY-001",onHand: 4,  par: 2,  price: 189, supplier: "Vance Pro Tools",   color: "#3d362f" },
    { id: "p10", name: "Tourmaline Flat Iron 1in",      brand: "Vance Tools",   sku: "VNC-IRN-100",onHand: 0,  par: 3,  price: 142, supplier: "Vance Pro Tools",   color: "#5a514a" },
    { id: "p11", name: "Boar-Bristle Round Brush 45mm", brand: "Vance Tools",   sku: "VNC-BRS-045",onHand: 7,  par: 5,  price: 44,  supplier: "Vance Pro Tools",   color: "#8c6d3f" },
    { id: "p12", name: "Rose Scalp Serum 60ml",         brand: "Sève Atelier",  sku: "SEV-SCP-060", onHand: 2, par: 5,  price: 62,  supplier: "Sève Distribution", color: "#c9a78f" }
  ];

  var state = { filter: "all", query: "" };

  /* ============ HELPERS ============ */
  function statusOf(p) {
    if (p.onHand <= 0) return "out";
    if (p.onHand <= p.par) return "low";
    return "ok";
  }

  function money(n) {
    return "$" + n.toLocaleString("en-US");
  }

  function initials(name) {
    var parts = name.replace(/[0-9].*$/, "").trim().split(/\s+/);
    return ((parts[0] || "")[0] || "") + ((parts[1] || "")[0] || "");
  }

  var STATUS_LABEL = { ok: "In stock", low: "Low", out: "Out" };

  /* ============ DOM REFS ============ */
  var tbody = document.getElementById("tbody");
  var emptyState = document.getElementById("emptyState");
  var searchInput = document.getElementById("searchInput");
  var rowSummary = document.getElementById("rowSummary");
  var toastEl = document.getElementById("toast");
  var toastTimer = null;

  /* ============ TOAST ============ */
  function toast(msg, accent) {
    toastEl.innerHTML = accent
      ? msg + ' <span class="toast__accent">' + accent + "</span>"
      : msg;
    toastEl.classList.add("is-show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("is-show");
    }, 2600);
  }

  /* ============ RENDER ============ */
  function matchesFilter(p) {
    if (state.filter === "all") return true;
    return statusOf(p) === state.filter;
  }

  function matchesQuery(p) {
    if (!state.query) return true;
    var q = state.query.toLowerCase();
    return (
      p.name.toLowerCase().indexOf(q) !== -1 ||
      p.brand.toLowerCase().indexOf(q) !== -1 ||
      p.sku.toLowerCase().indexOf(q) !== -1 ||
      p.supplier.toLowerCase().indexOf(q) !== -1
    );
  }

  function rowHTML(p) {
    var st = statusOf(p);
    var rowClass = st === "low" ? "row--low" : st === "out" ? "row--out" : "";
    var needsReorder = st === "low" || st === "out";

    var action = needsReorder
      ? '<button class="reorder" data-action="reorder" data-id="' + p.id +
        '" type="button">Reorder</button>'
      : '<span class="dash" aria-hidden="true">—</span>';

    return (
      '<tr class="' + rowClass + '" data-id="' + p.id + '">' +
        '<td class="tbl__product">' +
          '<div class="prod">' +
            '<span class="prod__sw" style="background:' + p.color + '" aria-hidden="true">' +
              initials(p.name) +
            "</span>" +
            "<span>" +
              '<span class="prod__name">' + p.name + "</span>" +
              '<span class="prod__brand">' + p.brand + "</span>" +
            "</span>" +
          "</div>" +
        "</td>" +
        '<td><span class="sku">' + p.sku + "</span></td>" +
        '<td class="tbl__num">' +
          '<span class="stepper">' +
            '<button class="step" data-action="dec" data-id="' + p.id +
              '" type="button" aria-label="Decrease on-hand for ' + p.name + '"' +
              (p.onHand <= 0 ? " disabled" : "") + ">&minus;</button>" +
            '<span class="stepper__val" data-val="' + p.id + '" aria-live="polite">' +
              p.onHand +
            "</span>" +
            '<button class="step" data-action="inc" data-id="' + p.id +
              '" type="button" aria-label="Increase on-hand for ' + p.name + '">+</button>' +
          "</span>" +
        "</td>" +
        '<td class="tbl__num num">' + p.par + "</td>" +
        "<td>" +
          '<span class="pill pill--' + st + '" data-pill="' + p.id + '">' +
            STATUS_LABEL[st] +
          "</span>" +
        "</td>" +
        '<td class="tbl__num retail">' + money(p.price) + "</td>" +
        '<td><span class="supplier">' + p.supplier + "</span></td>" +
        '<td class="tbl__act act-cell">' + action + "</td>" +
      "</tr>"
    );
  }

  function render() {
    var visible = PRODUCTS.filter(function (p) {
      return matchesFilter(p) && matchesQuery(p);
    });

    tbody.innerHTML = visible.map(rowHTML).join("");
    emptyState.hidden = visible.length !== 0;
    rowSummary.textContent =
      "Showing " + visible.length + " of " + PRODUCTS.length + " products";
  }

  function updateStats() {
    var low = 0, out = 0, retail = 0;
    PRODUCTS.forEach(function (p) {
      var st = statusOf(p);
      if (st === "low") low++;
      if (st === "out") out++;
      retail += p.onHand * p.price;
    });

    document.getElementById("statSkus").textContent = PRODUCTS.length;
    document.getElementById("statLow").textContent = low;
    document.getElementById("statOut").textContent = out;
    document.getElementById("statValue").textContent = money(retail);

    document.querySelector('[data-count="all"]').textContent = PRODUCTS.length;
    document.querySelector('[data-count="low"]').textContent = low;
    document.querySelector('[data-count="out"]').textContent = out;
  }

  function refresh() {
    updateStats();
    render();
  }

  /* ============ INTERACTIONS ============ */
  function adjust(id, delta) {
    var p = PRODUCTS.find(function (x) { return x.id === id; });
    if (!p) return;
    var next = p.onHand + delta;
    if (next < 0) return;
    p.onHand = next;

    // If the row is still visible under the current filter, update it in place
    // with a flash; otherwise the filter no longer matches, so re-render.
    var row = tbody.querySelector('tr[data-id="' + id + '"]');
    var stillVisible = matchesFilter(p) && matchesQuery(p);

    if (row && stillVisible) {
      var st = statusOf(p);
      row.className = st === "low" ? "row--low" : st === "out" ? "row--out" : "";
      row.querySelector('[data-val="' + id + '"]').textContent = p.onHand;

      var pill = row.querySelector('[data-pill="' + id + '"]');
      pill.className = "pill pill--" + st;
      pill.textContent = STATUS_LABEL[st];

      var dec = row.querySelector('[data-action="dec"]');
      dec.disabled = p.onHand <= 0;

      // refresh the action cell (reorder appears/disappears)
      var actCell = row.querySelector(".act-cell");
      if (st === "low" || st === "out") {
        if (!actCell.querySelector(".reorder")) {
          actCell.innerHTML =
            '<button class="reorder" data-action="reorder" data-id="' + id +
            '" type="button">Reorder</button>';
        }
      } else {
        actCell.innerHTML = '<span class="dash" aria-hidden="true">—</span>';
      }

      row.classList.remove("flash");
      void row.offsetWidth; // restart animation
      row.classList.add("flash");
      updateStats();
    } else {
      refresh();
    }
  }

  function reorder(id, btn) {
    var p = PRODUCTS.find(function (x) { return x.id === id; });
    if (!p || btn.classList.contains("is-done")) return;
    var qty = Math.max(p.par * 2 - p.onHand, p.par);
    btn.classList.add("is-done");
    btn.textContent = "Ordered";
    toast("Reorder placed · " + qty + " × " + p.name + " from", p.supplier);
  }

  /* delegated clicks on the table */
  tbody.addEventListener("click", function (e) {
    var t = e.target.closest("[data-action]");
    if (!t) return;
    var action = t.getAttribute("data-action");
    var id = t.getAttribute("data-id");
    if (action === "inc") adjust(id, 1);
    else if (action === "dec") adjust(id, -1);
    else if (action === "reorder") reorder(id, t);
  });

  /* filter tabs */
  var tabs = Array.prototype.slice.call(document.querySelectorAll(".tab"));
  tabs.forEach(function (tab) {
    tab.addEventListener("click", function () {
      tabs.forEach(function (t) {
        t.classList.remove("is-active");
        t.setAttribute("aria-selected", "false");
      });
      tab.classList.add("is-active");
      tab.setAttribute("aria-selected", "true");
      state.filter = tab.getAttribute("data-filter");
      render();
    });
  });

  /* search */
  searchInput.addEventListener("input", function () {
    state.query = searchInput.value.trim();
    render();
  });

  /* clear filters from empty state */
  document.getElementById("clearBtn").addEventListener("click", function () {
    state.filter = "all";
    state.query = "";
    searchInput.value = "";
    tabs.forEach(function (t) {
      var on = t.getAttribute("data-filter") === "all";
      t.classList.toggle("is-active", on);
      t.setAttribute("aria-selected", on ? "true" : "false");
    });
    render();
  });

  /* export (toast only — no backend) */
  document.getElementById("exportBtn").addEventListener("click", function () {
    toast("Exported " + PRODUCTS.length + " SKUs to", "inventory.csv");
  });

  /* ============ INIT ============ */
  refresh();
})();

snippets.css:
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Topbar ── */
.topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  background: var(--navy-d);
  color: var(--bone);
  padding: 0 32px;
  height: 64px;
  display: flex;
  align-items: center;
  gap: 32px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--bone);
  flex-shrink: 0;
}
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: var(--r-sm);
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.2rem;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
}
.brand-name em {
  font-style: normal;
  color: var(--gold-light);
}
.top-nav {
  display: flex;
  gap: 6px;
  margin-left: 24px;
}
.top-nav a {
  text-decoration: none;
  color: rgba(251, 248, 242, 0.65);
  font-size: 0.86rem;
  font-weight: 500;
  padding: 6px 13px;
  border-radius: var(--r-sm);
  transition: color 0.15s, background 0.15s;
}
.top-nav a:hover,
.top-nav a.active {
  color: var(--bone);
  background: rgba(255, 255, 255, 0.08);
}
.top-nav a.active {
  color: var(--gold-light);
}
.nav-cta {
  margin-left: auto;
  background: var(--gold);
  color: var(--navy-d);
  font-weight: 700;
  font-size: 0.84rem;
  padding: 9px 20px;
  border-radius: 999px;
  text-decoration: none;
  transition: background 0.15s;
}
.nav-cta:hover {
  background: var(--gold-light);
}

/* ── Page hero ── */
.page-hero {
  background: linear-gradient(160deg, var(--navy-2) 0%, var(--navy-d) 55%, #070f1e 100%);
  color: var(--bone);
  padding: 64px 32px 52px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 80% 60% at 50% 0%, rgba(201, 166, 73, 0.18), transparent 70%);
}
.breadcrumb {
  position: relative;
  font-size: 0.75rem;
  color: var(--gold-light);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 600;
  margin-bottom: 16px;
}
.page-hero h1 {
  position: relative;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(2.4rem, 5vw, 3.8rem);
  line-height: 1.05;
  color: var(--bone);
}
.hero-sub {
  position: relative;
  margin-top: 14px;
  font-size: 0.95rem;
  color: rgba(251, 248, 242, 0.7);
}

/* ── Controls bar ── */
.controls-bar {
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.filter-pills {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.pill {
  font-family: var(--font-body);
  font-size: 0.86rem;
  font-weight: 600;
  padding: 8px 20px;
  border: 1.5px solid var(--line-strong);
  border-radius: 999px;
  background: var(--bone);
  color: var(--ink-2);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}
.pill:hover {
  border-color: var(--navy);
  color: var(--navy);
}
.pill.active {
  background: var(--navy);
  border-color: var(--navy);
  color: var(--bone);
}
.view-toggle {
  display: flex;
  gap: 4px;
}
.toggle-btn {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border: 1.5px solid var(--line-strong);
  border-radius: var(--r-sm);
  background: var(--bone);
  color: var(--warm-gray);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.toggle-btn:hover {
  border-color: var(--navy);
  color: var(--navy);
}
.toggle-btn.active {
  background: var(--navy);
  border-color: var(--navy);
  color: var(--bone);
}

/* ── Rooms wrap ── */
.rooms-wrap {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 32px 72px;
}

/* ── Grid view ── */
.room-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
}
.room-grid.list-view {
  grid-template-columns: 1fr;
}

/* ── Room card ── */
.room-card {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--shadow-1);
  display: flex;
  flex-direction: column;
  transition: box-shadow 0.18s, transform 0.18s;
}
.room-card:hover {
  box-shadow: var(--shadow-2);
  transform: translateY(-3px);
}
.list-view .room-card {
  flex-direction: row;
}

/* ── Card image ── */
.card-img {
  position: relative;
  height: 200px;
  flex-shrink: 0;
}
.list-view .card-img {
  width: 260px;
  height: auto;
  min-height: 180px;
}
.card-img.img-classic {
  background: linear-gradient(135deg, #4a5568, #2e3a52);
}
.card-img.img-deluxe {
  background: linear-gradient(135deg, #3a5180, #1a2b4a);
}
.card-img.img-junior {
  background: linear-gradient(135deg, #5a6e4a, #2e3a2e);
}
.card-img.img-signature {
  background: linear-gradient(135deg, var(--gold-d), #4a3010);
}
.card-img.img-family {
  background: linear-gradient(135deg, #5a4a80, #2a1e48);
}
.card-img::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(60% 70% at 70% 25%, rgba(255, 255, 255, 0.13), transparent 65%);
}
.card-badge {
  position: absolute;
  top: 14px;
  left: 14px;
  z-index: 1;
  background: rgba(15, 29, 54, 0.82);
  color: var(--gold-light);
  font-size: 0.64rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 5px 11px;
  border-radius: 999px;
}
.card-price-overlay {
  position: absolute;
  bottom: 14px;
  right: 14px;
  z-index: 1;
  background: var(--gold);
  color: var(--navy-d);
  border-radius: var(--r-sm);
  padding: 6px 12px;
  text-align: right;
  line-height: 1.2;
}
.card-price-overlay .from {
  font-size: 0.58rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.card-price-overlay .amount {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

/* ── Card body ── */
.card-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: 8px;
}
.card-body h3 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.5rem;
  color: var(--navy-d);
  line-height: 1.1;
}
.card-meta {
  font-size: 0.82rem;
  color: var(--warm-gray);
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.card-meta span::before {
  margin-right: 4px;
}
.amenity-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 2px;
}
.ab {
  font-size: 0.68rem;
  font-weight: 600;
  padding: 3px 9px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--cream);
  color: var(--ink-2);
}
.ab.green {
  background: rgba(74, 119, 82, 0.1);
  border-color: rgba(74, 119, 82, 0.28);
  color: var(--success);
}
.card-footer {
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid var(--line);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.card-footer .price-detail {
  font-size: 0.78rem;
  color: var(--warm-gray);
  line-height: 1.4;
}
.card-footer .price-detail strong {
  font-family: var(--font-mono);
  color: var(--navy-d);
  font-size: 1.0rem;
  font-variant-numeric: tabular-nums;
}
.book-btn {
  flex-shrink: 0;
  font-family: var(--font-body);
  font-size: 0.84rem;
  font-weight: 700;
  padding: 10px 20px;
  border: none;
  border-radius: var(--r-sm);
  background: var(--navy);
  color: var(--bone);
  cursor: pointer;
  transition: background 0.15s;
}
.book-btn:hover {
  background: var(--navy-d);
}
.book-btn.secondary {
  background: transparent;
  border: 1.5px solid var(--navy);
  color: var(--navy);
}
.book-btn.secondary:hover {
  background: var(--navy);
  color: var(--bone);
}

/* ── Empty state ── */
.empty {
  text-align: center;
  padding: 72px 24px;
  color: var(--warm-gray);
  font-style: italic;
  background: var(--bone);
  border: 1px dashed var(--line-strong);
  border-radius: var(--r-md);
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 12px 24px;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 50;
  white-space: nowrap;
}

/* ── Responsive ── */
@media (max-width: 960px) {
  .top-nav {
    display: none;
  }
  .controls-bar {
    padding: 16px 20px;
  }
  .rooms-wrap {
    padding: 0 20px 56px;
  }
  .list-view .card-img {
    width: 200px;
  }
}
@media (max-width: 560px) {
  .topbar {
    padding: 0 18px;
    gap: 16px;
  }
  .page-hero {
    padding: 44px 20px 36px;
  }
  .controls-bar {
    padding: 14px 18px;
    flex-wrap: wrap;
  }
  .rooms-wrap {
    padding: 0 18px 48px;
  }
  .room-grid {
    grid-template-columns: 1fr;
  }
  .list-view .room-card {
    flex-direction: column;
  }
  .list-view .card-img {
    width: 100%;
    min-height: 160px;
  }
}

