/* ── Design tokens ── */
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Layout util ── */
.container {
  max-width: 1100px;
  margin-inline: auto;
  padding-inline: 32px;
}

/* ── Sticky nav ── */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 50;
  padding: 18px 0;
  transition: background 0.25s, padding 0.25s, box-shadow 0.25s;
}
.nav.is-scrolled {
  background: rgba(15, 29, 54, 0.97);
  padding: 12px 0;
  box-shadow: 0 2px 20px rgba(15, 29, 54, 0.3);
  backdrop-filter: blur(8px);
}
.nav-inner {
  display: flex;
  align-items: center;
  gap: 32px;
}
.nav-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  flex-shrink: 0;
}
.brand-mark {
  width: 34px;
  height: 34px;
  background: var(--gold);
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--navy-d);
}
.brand-mark--lg {
  width: 44px;
  height: 44px;
  font-size: 1.4rem;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--bone);
  letter-spacing: 0.01em;
}
.nav-links {
  display: flex;
  gap: 28px;
  list-style: none;
  margin-left: auto;
}
.nav-links a {
  text-decoration: none;
  color: rgba(251, 248, 242, 0.75);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color 0.15s;
}
.nav-links a:hover {
  color: var(--gold-light);
}
.nav-cta {
  text-decoration: none;
  font-size: 0.86rem;
  font-weight: 700;
  padding: 9px 20px;
  background: var(--gold);
  color: var(--navy-d);
  border-radius: 999px;
  transition: background 0.15s;
  white-space: nowrap;
}
.nav-cta:hover {
  background: var(--gold-light);
}

/* ── Hero ── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 60%, rgba(201, 166, 73, 0.18), transparent 55%),
    radial-gradient(ellipse at 80% 20%, rgba(45, 69, 112, 0.4), transparent 50%),
    linear-gradient(160deg, #152440 0%, #0a1628 100%);
}
.hero-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23c9a649' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}
.hero-content {
  position: relative;
  z-index: 2;
  padding-top: 100px;
  padding-bottom: 40px;
}
.hero-kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: var(--gold-light);
  font-weight: 700;
  margin-bottom: 20px;
}
.hero-heading {
  font-family: var(--font-display);
  font-size: clamp(3rem, 6vw, 5.5rem);
  font-weight: 700;
  color: var(--bone);
  line-height: 1.05;
  letter-spacing: -0.01em;
  margin-bottom: 24px;
}
.hero-sub {
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  color: rgba(251, 248, 242, 0.72);
  max-width: 480px;
  line-height: 1.65;
  margin-bottom: 32px;
}
.hero-btn {
  display: inline-block;
  text-decoration: none;
  background: transparent;
  border: 1.5px solid var(--gold);
  color: var(--gold-light);
  font-weight: 600;
  font-size: 0.9rem;
  padding: 13px 28px;
  border-radius: 999px;
  letter-spacing: 0.04em;
