  .rooms-grid .room-card:last-child {
    grid-column: span 2;
    max-width: 380px;
    justify-self: center;
  }
  .amenities-grid {
    grid-template-columns: 1fr 1fr;
  }
  .about-inner {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .about-stats {
    flex-direction: row;
    border-left: none;
    border-top: 2px solid var(--gold);
    padding-left: 0;
    padding-top: 28px;
    gap: 36px;
  }
  .footer-inner {
    grid-template-columns: 1fr 1fr;
  }
  .footer-brand {
    grid-column: span 2;
    flex-direction: row;
    align-items: center;
    gap: 16px;
  }
}
@media (max-width: 560px) {
  .container {
    padding-inline: 18px;
  }
  .nav-links {
    display: none;
  }
  .rooms-grid {
    grid-template-columns: 1fr;
  }
  .rooms-grid .room-card:last-child {
    grid-column: span 1;
    max-width: none;
  }
  .amenities-grid {
    grid-template-columns: 1fr;
  }
  .search-inner {
    flex-direction: column;
    gap: 12px;
  }
  .sf {
    min-width: 100%;
  }
  .search-btn {
    width: 100%;
  }
  .footer-inner {
    grid-template-columns: 1fr;
  }
  .footer-brand {
    grid-column: span 1;
  }
  .newsletter-form {
    flex-direction: column;
  }
  .about-stats {
    flex-direction: column;
  }
}

