    guest: "Olivier Banks",
    request: "Wake-up call at 05:45 on 10 Jun",
    time: "09:02",
    priority: "normal",
    status: "new",
    assignee: null,
  },
  {
    id: 5,
    room: "302",
    guest: "Fátima Cervantes",
    request: "Luggage storage after checkout until 18:00",
    time: "09:15",
    priority: "low",
    status: "new",
    assignee: null,
  },
  {
    id: 6,
    room: "405",
    guest: "Carlos Mendes",
    request: "Restaurant booking — Solar dos Presuntos, 9 Jun",
    time: "07:58",
    priority: "high",
    status: "inprogress",
    assignee: "Paulo",
  },
  {
    id: 7,
    room: "219",
    guest: "Elena Vasquez",
    request: "Taxi to Belém Cultural Centre — 9 Jun, 14:00",
    time: "08:05",
    priority: "normal",
    status: "inprogress",
    assignee: "Sofia",
  },
  {
    id: 8,
    room: "103",
    guest: "Hassan Najjar",
    request: "Extra towels and pillow to room",
    time: "08:33",
    priority: "low",
    status: "inprogress",
    assignee: null,
  },
  {
    id: 9,
    room: "315",
    guest: "Pilar Romero",
    request: "Wake-up call at 07:00 on 9 Jun — confirmed",
    time: "07:44",
    priority: "normal",
    status: "done",
    assignee: "Paulo",
  },
  {
    id: 10,
    room: "108",
    guest: "Ruiqi Chen",
    request: "Theatre tickets — Teatro Nacional, 8 Jun — booked",
    time: "07:22",
    priority: "high",
    status: "done",
    assignee: "Sofia",
  },
  {
    id: 11,
    room: "221",
    guest: "Marc Dupuis",
    request: "Luggage delivered to room on arrival",
    time: "07:10",
    priority: "low",
    status: "done",
    assignee: "Paulo",
  },
];

let nextId = 12;
let activePriority = "all";

const LANE_LABELS = { new: "New", inprogress: "In Progress", done: "Done" };
const STATUS_ORDER = ["new", "inprogress", "done"];

// ── Toast helper ──────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2200);
}

// ── Render board ──────────────────────────────────────────────────────────────
function renderBoard() {
  const board = document.getElementById("board");
  const filtered =
    activePriority === "all" ? requests : requests.filter((r) => r.priority === activePriority);

  board.innerHTML = STATUS_ORDER.map((lane) => {
    const cards = filtered.filter((r) => r.status === lane);
    const allInLane = requests.filter((r) => r.status === lane);
    return `
      <div class="lane" data-lane="${lane}">
        <div class="lane-head">
          <span class="lane-title">
            <span class="lane-dot"></span>
            ${LANE_LABELS[lane]}
          </span>
          <span class="lane-count">${allInLane.length}</span>
        </div>
        <div class="lane-body">
          ${
            cards.length === 0
              ? `<p class="lane-empty">No requests${activePriority !== "all" ? " for this filter" : ""}</p>`
              : cards.map((card) => renderCard(card, lane)).join("")
          }
        </div>
      </div>`;
  }).join("");

  // ── Wire card buttons ──────────────────────────────────────────────────────
  board.addEventListener("click", handleCardAction);
}

function renderCard(r, lane) {
  const canAdvance = lane !== "done";
  const advanceLabel = lane === "new" ? "→ In Progress" : "→ Done";
  const assignLabel = r.assignee ? `Assigned: ${r.assignee}` : "Assign to me";

  return `
    <div class="card" data-id="${r.id}">
      <div class="card-top">
        <div class="card-request">${r.request}</div>
        <span class="pri ${r.priority}">${r.priority}</span>
      </div>
      <div class="card-meta">
        <span class="card-room">${r.room}</span>
        <span class="card-sep">·</span>
        <span class="card-guest">${r.guest}</span>
        <span class="card-sep">·</span>
        <span class="card-time">${r.time}</span>
      </div>
      ${
        r.assignee
          ? `<div class="card-assignee">Assigned to <span>${r.assignee}</span></div>`
          : `<div class="card-assignee">Unassigned</div>`
      }
      <div class="card-actions">
        <button class="card-btn assign" data-action="assign" data-id="${r.id}">
          ${r.assignee ? "✓ " + r.assignee : "Assign to me"}
        </button>
        ${
          canAdvance
            ? `<button class="card-btn advance" data-action="advance" data-id="${r.id}">${advanceLabel}</button>`
            : `<span class="card-btn" style="margin-left:auto;opacity:0.45;cursor:default">✓ Done</span>`
        }
      </div>
    </div>`;
}

// ── Card action handler (event delegation) ────────────────────────────────────
function handleCardAction(e) {
  // Guard: don't double-fire from re-renders adding new listeners
  if (e._handled) return;
  e._handled = true;

  const btn = e.target.closest("button[data-action]");
  if (!btn) return;

  const id = parseInt(btn.dataset.id, 10);
  const req = requests.find((r) => r.id === id);
  if (!req) return;

  if (btn.dataset.action === "advance") {
    const idx = STATUS_ORDER.indexOf(req.status);
    if (idx < STATUS_ORDER.length - 1) {
      req.status = STATUS_ORDER[idx + 1];
      showToast(`Request #${id} moved to "${LANE_LABELS[req.status]}"`);
      renderBoard();
    }
  }

  if (btn.dataset.action === "assign") {
    if (!req.assignee) {
      req.assignee = "Paulo";
      showToast(`Assigned to Paulo — room ${req.room}`);
    } else {
      req.assignee = null;
      showToast(`Assignment removed — room ${req.room}`);
    }
    renderBoard();
  }
}

// ── Priority filter ───────────────────────────────────────────────────────────
document.querySelectorAll(".chip[data-pri]").forEach((btn) => {
  btn.addEventListener("click", () => {
    document.querySelectorAll(".chip[data-pri]").forEach((b) => b.classList.remove("is-active"));
    btn.classList.add("is-active");
    activePriority = btn.dataset.pri;
    renderBoard();
  });
});

// ── New request button (adds demo card) ───────────────────────────────────────
const REQUEST_TYPES = [
  "Restaurant booking — Bica do Sapato, tonight 21:00",
  "Taxi to Parque das Nações — 11 Jun, 09:00",
  "Extra pillows and blanket for room",
  "Wake-up call at 06:30 on 12 Jun",
  "Luggage storage — 2 bags until 17:00",
];
const ROOMS = ["101", "112", "223", "317", "408", "205", "316"];
const GUESTS = ["Sofia Bellini", "Karl Henriksen", "Yuki Mori", "Ana Costa", "Luca Ferrari"];
const PRIS = ["high", "normal", "normal", "low"];

document.getElementById("btnNewRequest").addEventListener("click", () => {
  const r = {
    id: nextId++,
    room: ROOMS[Math.floor(Math.random() * ROOMS.length)],
    guest: GUESTS[Math.floor(Math.random() * GUESTS.length)],
    request: REQUEST_TYPES[Math.floor(Math.random() * REQUEST_TYPES.length)],
    time: new Date().toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" }),
    priority: PRIS[Math.floor(Math.random() * PRIS.length)],
    status: "new",
    assignee: null,
  };
  requests.unshift(r);
  showToast(`New request added — room ${r.room}`);
  renderBoard();
});

// ── Clock + date ──────────────────────────────────────────────────────────────
const clockEl = document.getElementById("clock");
const todayEl = document.getElementById("todayLabel");
function tick() {
  const now = new Date();
  clockEl.textContent = now.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
  todayEl.textContent = now.toLocaleDateString("en-GB", {
    weekday: "long",
    day: "numeric",
    month: "long",
  });
}
tick();
setInterval(tick, 1000);

// ── Initial render ────────────────────────────────────────────────────────────
renderBoard();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --sh-1: 0 1px 2px rgba(28, 42, 37, 0.06), 0 8px 24px rgba(28, 42, 37, 0.06);
  --sh-2: 0 2px 6px rgba(28, 42, 37, 0.08), 0 18px 48px rgba(28, 42, 37, 0.12);
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: "Inter", system-ui, sans-serif;
  line-height: 1.55;
  color: var(--ink);
  background: var(--ivory);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1,
h2 {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
  line-height: 1.1;
  margin: 0;
  letter-spacing: 0.2px;
}

.shell {
  max-width: 940px;
  margin: 0 auto;
  padding: clamp(20px, 4vw, 48px) clamp(16px, 4vw, 40px) 72px;
  display: grid;
  gap: 26px;
}

.eyebrow {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--brass-d);
  margin: 0 0 6px;
}

.muted {
  color: var(--muted);
}

/* ---------- Listing header ---------- */
.listing {
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--sh-2);
}

.listing__photo {
  position: relative;
  min-height: 280px;
  background:
    radial-gradient(120% 80% at 78% 12%, rgba(255, 244, 214, 0.5), transparent 55%),
    radial-gradient(90% 70% at 14% 92%, rgba(22, 48, 42, 0.55), transparent 60%),
    linear-gradient(155deg, #2c5145 0%, #1f3d34 42%, #16302a 70%, #244036 100%);
}

.listing__photo::before {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 58%;
  background:
    linear-gradient(180deg, transparent, rgba(11, 24, 20, 0.42)),
    repeating-linear-gradient(105deg, rgba(176, 141, 87, 0.16) 0 2px, transparent 2px 26px);
  -webkit-mask-image: linear-gradient(180deg, transparent, #000 40%);
  mask-image: linear-gradient(180deg, transparent, #000 40%);
}

.listing__photo::after {
  content: "";
  position: absolute;
  right: 16%;
  bottom: 0;
  width: 30%;
  height: 64%;
  background: linear-gradient(180deg, rgba(243, 234, 217, 0.22), rgba(176, 141, 87, 0.32));
  border-radius: 4px 4px 0 0;
  box-shadow: -54px 0 0 -8px rgba(243, 234, 217, 0.16), 60px 8px 0 -12px rgba(243, 234, 217, 0.12);
}

.listing__chip {
  position: absolute;
  z-index: 2;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  padding: 6px 11px;
  border-radius: 999px;
  backdrop-filter: blur(4px);
}

.listing__chip--status {
  top: 14px;
  left: 14px;
  background: rgba(47, 158, 111, 0.92);
  color: #fff;
}

.listing__chip--days {
  bottom: 14px;
  left: 14px;
  background: rgba(255, 253, 248, 0.9);
  color: var(--green-d);
}

.listing__body {
  padding: clamp(20px, 3vw, 32px);
  display: flex;
  flex-direction: column;
}

.listing__title {
  font-size: clamp(30px, 4.5vw, 42px);
  color: var(--green-d);
}

.listing__addr {
  margin: 4px 0 0;
  color: var(--ink-2);
  font-size: 15px;
}

.facts {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  margin: 16px 0 18px;
  padding: 14px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.fact {
  font-size: 14px;
  color: var(--muted);
}

.fact strong {
  color: var(--ink);
  font-weight: 600;
}

.listing__price {
  margin-top: auto;
  display: flex;
  flex-wrap: wrap;
  gap: 20px 40px;
  align-items: flex-end;
}

.price__label {
  display: block;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 2px;
}

.price__value {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: clamp(26px, 3.4vw, 34px);
  font-weight: 700;
  color: var(--green-d);
  line-height: 1;
}

.price__value--lead {
  color: var(--brass-d);
}

.lead__by {
  display: block;
  margin-top: 4px;
  font-size: 12px;
  color: var(--muted);
}

/* ---------- Summary band ---------- */
.band {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.stat {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 18px;
  box-shadow: var(--sh-1);
}

.stat__num {
  display: block;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 28px;
  font-weight: 700;
  color: var(--green);
  line-height: 1;
}

.stat__lbl {
  display: block;
  margin-top: 6px;
  font-size: 12px;
  color: var(--muted);
}

/* ---------- Offers ---------- */
.offers__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.offers__head h2 {
  font-size: 26px;
  color: var(--green-d);
}

.offer-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 12px;
}

.offer {
  position: relative;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 18px 20px 18px 24px;
  box-shadow: var(--sh-1);
  transition: box-shadow 0.18s ease, transform 0.18s ease, border-color 0.18s ease;
}

.offer::before {
  content: "";
  position: absolute;
  left: 0;
  top: 12px;
  bottom: 12px;
  width: 4px;
  border-radius: 0 4px 4px 0;
  background: var(--line-2);
  transition: background 0.18s ease;
}

.offer:hover {
  box-shadow: var(--sh-2);
  transform: translateY(-1px);
}

.offer--lead {
  border-color: var(--brass);
  background: linear-gradient(180deg, var(--brass-50), var(--paper) 60%);
}

.offer--lead::before {
  background: var(--brass);
}

.offer__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.offer__buyer {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.avatar {
  width: 40px;
  height: 40px;
  flex: none;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 600;
  font-size: 14px;
  color: var(--white);
  background: linear-gradient(150deg, var(--green-700), var(--green-d));
  box-shadow: inset 0 0 0 2px rgba(255, 253, 248, 0.25);
}

.offer--lead .avatar {
  background: linear-gradient(150deg, var(--brass), var(--brass-d));
}

.offer__name {
  font-weight: 600;
  font-size: 15px;
  color: var(--ink);
}

.offer__agent {
  font-size: 12px;
  color: var(--muted);
}

.offer__amount {
  text-align: right;
  white-space: nowrap;
}

.offer__amount b {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 26px;
  font-weight: 700;
  color: var(--green-d);
}

.offer__delta {
  display: block;
  font-size: 12px;
  font-weight: 600;
  margin-top: 2px;
}

.offer__delta--up {
  color: var(--ok);
}

.offer__delta--down {
  color: var(--danger);
}

.offer__meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}

.badge {
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.02em;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid transparent;
  white-space: nowrap;
}

.badge--cash {
  background: var(--green-50);
  color: var(--green-700);
  border-color: rgba(38, 73, 62, 0.18);
}

.badge--financed {
  background: var(--brass-50);
  color: var(--brass-d);
  border-color: rgba(176, 141, 87, 0.3);
}

.badge--term {
  background: var(--white);
  color: var(--ink-2);
  border-color: var(--line-2);
}

.badge--lead {
  background: var(--brass);
  color: #fff;
}

.status {
  margin-left: auto;
  font-size: 12px;
  font-weight: 600;
  padding: 5px 12px 5px 22px;
  border-radius: 999px;
  position: relative;
}

.status::before {
  content: "";
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.status--submitted {
  background: rgba(107, 122, 114, 0.12);
  color: var(--ink-2);
}

.status--countered {
  background: rgba(201, 138, 43, 0.14);
  color: var(--warn);
}

.status--accepted {
  background: rgba(47, 158, 111, 0.16);
  color: var(--ok);
}

.status--rejected {
  background: rgba(196, 80, 62, 0.14);
  color: var(--danger);
}

.offer__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 14px;
  padding-top: 13px;
  border-top: 1px solid var(--line);
}

.offer__time {
  font-size: 12px;
  color: var(--muted);
}

.offer__actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

/* ---------- Buttons ---------- */
.btn {
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border-radius: var(--r-sm);
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink-2);
  padding: 7px 14px;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.08s ease;
}

.btn:hover {
  border-color: var(--green-700);
  color: var(--green-d);
}

.btn:active {
  transform: translateY(1px);
}

.btn:focus-visible {
  outline: 2px solid var(--brass);
  outline-offset: 2px;
}

.btn--accept:hover {
  background: var(--green-50);
  border-color: var(--ok);
  color: var(--green-700);
}

.btn--reject:hover {
  background: rgba(196, 80, 62, 0.08);
  border-color: var(--danger);
  color: var(--danger);
}

.btn--primary {
  background: var(--green);
  border-color: var(--green-d);
  color: var(--white);
  padding: 11px 22px;
  font-size: 14px;
}

.btn--primary:hover {
  background: var(--green-d);
  color: var(--white);
}

/* ---------- Composer ---------- */
.composer {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: clamp(20px, 3vw, 32px);
  box-shadow: var(--sh-1);
  position: relative;
}

.composer::before {
  content: "";
  position: absolute;
  top: 0;
  left: clamp(20px, 3vw, 32px);
  right: clamp(20px, 3vw, 32px);
  height: 2px;
  background: linear-gradient(90deg, var(--brass), transparent 70%);
  border-radius: 2px;
}

.composer h2 {
  font-size: 24px;
  color: var(--green-d);
  margin-bottom: 4px;
}

.composer__form {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin-top: 20px;
  align-items: end;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.field--terms {
  grid-column: 1 / -1;
}

.field label,
.field__legend {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
}

.field input,
.field select {
  font: inherit;
  font-size: 15px;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 11px 13px;
}

.field input:focus,
.field select:focus {
  outline: none;
  border-color: var(--brass);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.18);
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip-toggle {
  position: relative;
  cursor: pointer;
}

.chip-toggle input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.chip-toggle span {
  display: inline-block;
  font-size: 13px;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: 999px;
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink-2);
  transition: all 0.15s ease;
}

.chip-toggle:hover span {
  border-color: var(--green-700);
}

.chip-toggle input:checked + span {
  background: var(--green-50);
  border-color: var(--green-700);
  color: var(--green-700);
}

.chip-toggle input:focus-visible + span {
  outline: 2px solid var(--brass);
  outline-offset: 2px;
}

.composer .btn--primary {
  justify-self: start;
  grid-column: 1 / -1;
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 18px);
  background: var(--green-d);
  color: var(--white);
  font-size: 14px;
  font-weight: 500;
  padding: 12px 20px;
  border-radius: var(--r-sm);
  box-shadow: var(--sh-2);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  z-index: 50;
  max-width: calc(100vw - 32px);
}

.toast--show {
  opacity: 1;
  transform: translate(-50%, 0);
}

.toast__accent {
  color: var(--brass-50);
}

/* ---------- Responsive ---------- */
@media (max-width: 760px) {
  .listing {
    grid-template-columns: 1fr;
  }
  .listing__photo {
    min-height: 200px;
  }
  .band {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 520px) {
  .shell {
    padding: 18px 14px 56px;
    gap: 20px;
  }
  .composer__form {
    grid-template-columns: 1fr;
  }
  .offer__amount {
    text-align: left;
  }
  .offer__amount b {
    font-size: 23px;
  }
  .status {
    margin-left: 0;
  }
  .offer__meta {
    gap: 6px;
  }
}

