:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --pending: #6b7280;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

/* ── App bar ── */
.appbar {
  background: var(--white);
  border-bottom: 1px solid var(--line);
  padding: 14px 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 20;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--ink);
}
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: linear-gradient(150deg, var(--teal), var(--teal-d));
  color: #fff;
  font-size: 1.1rem;
  font-weight: 700;
}
.brand-name {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.brand-name em {
  font-style: normal;
  color: var(--teal-d);
}
.avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: none;
  background: var(--teal-d);
  color: #fff;
  font-weight: 700;
  font-size: 0.82rem;
  cursor: pointer;
}

/* ── Layout ── */
.booking {
  max-width: 1020px;
  margin: 0 auto;
  padding: 28px 28px 56px;
}
.head {
  margin-bottom: 18px;
}
.eyebrow {
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--teal-d);
}
.head h1 {
  font-size: 1.75rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-top: 2px;
}

/* ── Stepper ── */
.stepper {
  list-style: none;
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 10px 16px;
  margin-bottom: 22px;
}
.step {
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 1;
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 600;
}
.step:not(:last-child)::after {
  content: "";
  flex: 1;
  height: 2px;
  border-radius: 2px;
  background: var(--line);
  margin-left: 8px;
}
.step-num {
  width: 28px;
  height: 28px;
  flex: none;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--bg);
  border: 1px solid var(--line-2);
  color: var(--muted);
  font-size: 0.84rem;
  font-weight: 700;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.step.is-current {
  color: var(--ink);
}
.step.is-current .step-num {
  background: var(--teal-d);
  border-color: var(--teal-d);
  color: #fff;
}
.step.is-done {
  color: var(--teal-d);
}
.step.is-done .step-num {
  background: var(--teal-50);
  border-color: var(--teal);
  color: transparent;
  font-size: 0;
}
.step.is-done .step-num::after {
  content: "✓";
  color: var(--teal-d);
  font-size: 0.9rem;
}
.step.is-done:not(:last-child)::after {
  background: var(--teal);
}

/* ── Two-column layout ── */
.layout {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 22px;
  align-items: start;
}
.flow {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 22px 24px;
  min-height: 320px;
}
.step-title {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-bottom: 16px;
}

/* ── Step 1: specialties ── */
.spec-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.spec-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
  text-align: center;
  font: inherit;
  cursor: pointer;
  transition: transform 0.14s, box-shadow 0.14s, border-color 0.14s;
}
.spec-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-1);
  border-color: var(--teal);
}
.spec-card.is-selected {
  border-color: var(--teal);
  background: var(--teal-50);
  box-shadow: 0 0 0 2px rgba(18, 156, 147, 0.3);
}
.spec-ic {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: var(--teal-50);
  color: var(--teal-d);
  font-size: 1.4rem;
}
.spec-card.is-selected .spec-ic {
  background: var(--teal-d);
  color: #fff;
}
.spec-name {
  font-weight: 700;
  font-size: 0.92rem;
  color: var(--ink);
}
.spec-blurb {
  font-size: 0.78rem;
  color: var(--muted);
  line-height: 1.35;
}

/* ── Step 2: doctors ── */
.doc-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.doc-card {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 16px;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.14s, box-shadow 0.14s, background 0.14s;
}
.doc-card:hover {
  border-color: var(--teal);
  box-shadow: var(--shadow-1);
}
.doc-card.is-selected {
  border-color: var(--teal);
  background: var(--teal-50);
  box-shadow: 0 0 0 2px rgba(18, 156, 147, 0.3);
}
.doc-avatar {
  width: 48px;
  height: 48px;
  flex: none;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--teal-d);
  color: #fff;
  font-weight: 700;
  font-size: 0.92rem;
}
.doc-card:nth-child(2n) .doc-avatar {
  background: #4f7cac;
}
.doc-card:nth-child(3n) .doc-avatar {
  background: var(--coral);
}
.doc-body {
  flex: 1;
  min-width: 0;
}
.doc-name {
  font-weight: 700;
  font-size: 0.96rem;
}
.doc-sub {
  font-size: 0.82rem;
  color: var(--muted);
  margin-top: 1px;
}
.doc-avail {
  font-size: 0.8rem;
  color: var(--teal-d);
  font-weight: 600;
  margin-top: 4px;
}
.doc-rating {
  flex: none;
  text-align: right;
  font-size: 0.82rem;
  color: var(--ink-2);
  font-weight: 600;
}
.doc-rating .stars {
  color: var(--warn);
  letter-spacing: 1px;
}

/* ── Step 3: date strip + slots ── */
.date-strip {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 4px;
  margin-bottom: 18px;
}
.date-chip {
  flex: none;
  min-width: 64px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--white);
  padding: 10px 6px;
  text-align: center;
  font: inherit;
  cursor: pointer;
  transition: border-color 0.14s, background 0.14s;
}
.date-chip:hover {
  border-color: var(--teal);
}
.date-chip.is-selected {
  border-color: var(--teal);
  background: var(--teal-d);
  color: #fff;
}
.dc-dow {
  display: block;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
  font-weight: 600;
}
.date-chip.is-selected .dc-dow {
  color: rgba(255, 255, 255, 0.85);
}
.dc-day {
  display: block;
  font-size: 1.15rem;
  font-weight: 800;
  margin-top: 2px;
}
.slot-head {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ink-2);
  margin: 14px 0 8px;
}
.slot-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}
.slot {
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  background: var(--white);
  padding: 10px 6px;
  font: inherit;
  font-weight: 600;
  font-size: 0.86rem;
  color: var(--ink);
  cursor: pointer;
  transition: border-color 0.14s, background 0.14s;
}
.slot:hover:not(:disabled) {
  border-color: var(--teal);
  background: var(--teal-50);
}
.slot.is-selected {
  border-color: var(--teal);
  background: var(--teal-d);
  color: #fff;
}
.slot:disabled {
  color: var(--muted);
  background: var(--bg);
  cursor: not-allowed;
  text-decoration: line-through;
  opacity: 0.6;
}

/* ── Success panel ── */
.panel-step.success {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 28px 16px;
  gap: 10px;
}
.ok-mark {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--teal-50);
  color: var(--ok);
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 6px;
}
.panel-step.success h2 {
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.ok-sub {
  color: var(--muted);
  font-size: 0.92rem;
  max-width: 360px;
}
.ok-ref {
  margin-top: 6px;
  background: var(--teal-50);
  color: var(--teal-d);
  border-radius: 999px;
  padding: 8px 16px;
  font-size: 0.88rem;
  font-weight: 600;
}
.ok-actions {
  display: flex;
  gap: 10px;
  margin-top: 12px;
}

/* ── Buttons ── */
.btn {
  border: none;
  border-radius: 11px;
  padding: 11px 18px;
  font: inherit;
  font-weight: 600;
  font-size: 0.9rem;
  cursor: pointer;
  transition: transform 0.12s, background 0.15s, opacity 0.15s;
}
.btn:active {
  transform: translateY(1px);
}
.btn.primary {
  background: var(--coral);
  color: #fff;
}
.btn.primary:hover {
  background: #ff8e7c;
}
.btn.primary:disabled {
  background: var(--coral-soft);
  color: #fff;
  cursor: not-allowed;
}
.btn.ghost {
  background: var(--white);
  border: 1px solid var(--line-2);
  color: var(--ink-2);
}
.btn.ghost:hover {
  background: var(--teal-50);
  border-color: var(--teal);
}

/* ── Summary sidebar ── */
.summary {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 20px;
  position: sticky;
  top: 86px;
  box-shadow: var(--shadow-1);
}
.sum-title {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 14px;
}
.sum-list {
  display: flex;
  flex-direction: column;
}
.sum-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid var(--line);
}
.sum-row dt {
  font-size: 0.82rem;
  color: var(--muted);
}
.sum-row dd {
  font-size: 0.88rem;
  font-weight: 600;
  text-align: right;
}
.nav {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}
.nav .btn {
  flex: 1;
}
.sum-fine {
  margin-top: 12px;
  font-size: 0.78rem;
  color: var(--muted);
  text-align: center;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}

@media (max-width: 820px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .summary {
    position: static;
  }
  .spec-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .slot-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

