/* ── Design tokens ───────────────────────────────────────────────────────────── */
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Nav ── */
.nav {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 20px 40px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  color: var(--bone);
}
.brand-mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.4rem;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 700;
  letter-spacing: 0.01em;
}
.brand-name em {
  font-style: normal;
  color: var(--gold-light);
}
.nav-links {
  display: flex;
  gap: 26px;
  margin-left: auto;
}
.nav-links a {
  color: rgba(251, 248, 242, 0.8);
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 500;
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--gold-light);
}
.nav-actions {
  display: flex;
  align-items: center;
  gap: 18px;
}
.nav-link {
  color: rgba(251, 248, 242, 0.8);
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 500;
}
.nav-link:hover {
  color: var(--bone);
}
.nav-cta {
  background: rgba(251, 248, 242, 0.12);
  border: 1px solid rgba(251, 248, 242, 0.3);
  color: var(--bone);
  font-family: inherit;
  font-size: 0.86rem;
  font-weight: 600;
  padding: 9px 16px;
  border-radius: 999px;
  cursor: pointer;
}
.nav-cta:hover {
  background: rgba(251, 248, 242, 0.2);
}

/* ── Page header ── */
.page-head {
  position: relative;
  min-height: 320px;
  padding: 130px 40px 60px;
  display: flex;
  align-items: flex-end;
  background: linear-gradient(135deg, var(--navy-d) 0%, var(--navy) 55%, var(--navy-2) 100%);
  overflow: hidden;
}
.page-head::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(100% 80% at 90% 5%, rgba(201, 166, 73, 0.2), transparent 50%),
    radial-gradient(60% 60% at 0% 100%, rgba(45, 69, 112, 0.5), transparent 60%);
  pointer-events: none;
}
.page-head-inner {
  position: relative;
  max-width: 1100px;
  width: 100%;
  margin: 0 auto;
  color: var(--bone);
}
.eyebrow {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--gold-light);
  font-weight: 600;
}
.page-head h1 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(2.2rem, 5vw, 3.6rem);
  line-height: 1.06;
  letter-spacing: -0.01em;
  margin: 8px 0 12px;
}
.lede {
  font-size: 0.98rem;
  line-height: 1.65;
  color: rgba(251, 248, 242, 0.78);
  max-width: 560px;
}

/* ── Main two-column grid ── */
.main-grid {
  max-width: 1100px;
  margin: 0 auto;
  padding: 56px 40px 80px;
  display: grid;
  grid-template-columns: 1fr 1.3fr;
  gap: 40px;
  align-items: start;
}

/* ── Location column ── */
.location-col {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

/* CSS map */
.map-box {
  border-radius: var(--r-lg);
  overflow: hidden;
  height: 260px;
  position: relative;
  border: 1px solid var(--line);
  box-shadow: var(--shadow-1);
}
.map-bg {
  width: 100%;
  height: 100%;
  background: #e8e0d0;
  position: relative;
  overflow: hidden;
}
.map-grid {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(180, 170, 150, 0.4) 1px, transparent 1px),
    linear-gradient(90deg, rgba(180, 170, 150, 0.4) 1px, transparent 1px);
  background-size: 40px 40px;
}
.map-road {
  position: absolute;
  background: #fff;
}
.map-road-h {
  left: 0;
  right: 0;
  height: 10px;
  transform: translateY(-50%);
}
.map-road-v {
  top: 0;
  bottom: 0;
  width: 10px;
  transform: translateX(-50%);
}
.map-block {
  position: absolute;
  background: rgba(160, 148, 120, 0.35);
  border-radius: 3px;
}
.map-park {
  background: rgba(100, 150, 90, 0.3);
}
.map-pin {
  position: absolute;
  transform: translate(-50%, -100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  z-index: 2;
}
.pin-dot {
  width: 20px;
  height: 20px;
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  background: var(--gold);
  border: 2px solid var(--navy-d);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
}
.pin-label {
  background: var(--navy-d);
  color: var(--gold-light);
  font-size: 0.68rem;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: var(--r-sm);
  white-space: nowrap;
  letter-spacing: 0.04em;
}

/* Info panel */
.info-panel {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 24px 24px 20px;
  box-shadow: var(--shadow-1);
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.info-block {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}
.info-ic {
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: var(--r-md);
  background: rgba(201, 166, 73, 0.14);
  color: var(--gold-d);
  display: grid;
  place-items: center;
  font-size: 1rem;
}
.info-block strong {
  display: block;
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 700;
  color: var(--warm-gray);
  margin-bottom: 3px;
}
.info-block p,
.info-block a {
  font-size: 0.9rem;
  color: var(--ink-2);
  text-decoration: none;
  line-height: 1.5;
}
.info-block a:hover {
  color: var(--gold-d);
  text-decoration: underline;
}
.copy-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--cream-2);
  border: 1px solid var(--line-strong);
  color: var(--ink-2);
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  padding: 9px 16px;
  border-radius: var(--r-md);
  cursor: pointer;
  align-self: flex-start;
  transition: all 0.15s;
}
.copy-btn:hover {
  background: var(--cream);
  border-color: var(--gold);
  color: var(--gold-d);
}

/* Hours table */
.hours-panel {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px 24px;
  box-shadow: var(--shadow-1);
}
.hours-panel h3 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.3rem;
  color: var(--navy-d);
  margin-bottom: 14px;
}
.hours-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.86rem;
}
.hours-table td {
  padding: 8px 0;
  border-bottom: 1px solid var(--line);
  color: var(--ink-2);
}
.hours-table tr:last-child td {
  border-bottom: none;
}
.hours-val {
  text-align: right;
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.8rem;
  color: var(--navy-d);
  font-variant-numeric: tabular-nums;
}

/* ── Form column ── */
.form-col {
  display: flex;
  flex-direction: column;
  gap: 30px;
}

/* Form card */
.form-card {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 32px 34px;
  box-shadow: var(--shadow-1);
  position: relative;
}
.form-header {
  margin-bottom: 26px;
}
.form-header h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.9rem;
  color: var(--navy-d);
}
.form-header p {
  font-size: 0.86rem;
  color: var(--warm-gray);
  margin-top: 5px;
}

/* Form rows and field groups */
.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.field-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 20px;
}
.field-group label {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--ink-2);
}
.req {
  color: var(--gold-d);
}
.field-group input,
.field-group select,
.field-group textarea {
  font-family: inherit;
  font-size: 0.92rem;
  color: var(--ink);
  background: var(--cream);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-md);
  padding: 11px 14px;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
  width: 100%;
}
.field-group textarea {
  resize: vertical;
  min-height: 120px;
}
.field-group input:focus,
.field-group select:focus,
.field-group textarea:focus {
  border-color: var(--navy-2);
  box-shadow: 0 0 0 3px rgba(45, 69, 112, 0.1);
}
.field-group.has-error input,
.field-group.has-error select,
.field-group.has-error textarea {
  border-color: var(--danger);
}
.field-err {
  font-size: 0.76rem;
  color: var(--danger);
  font-weight: 600;
  min-height: 1em;
}
.char-count {
  text-align: right;
  font-size: 0.74rem;
  font-family: var(--font-mono);
  color: var(--warm-gray);
  font-variant-numeric: tabular-nums;
}
.char-count.over {
  color: var(--danger);
  font-weight: 700;
}

/* Form footer */
.form-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 4px;
}
.form-note {
  font-size: 0.76rem;
  color: var(--warm-gray);
}
.btn-submit {
  background: var(--navy);
  color: var(--bone);
  border: none;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 700;
  padding: 12px 28px;
  border-radius: var(--r-md);
  cursor: pointer;
  transition: background 0.15s;
}
.btn-submit:hover {
  background: var(--navy-2);
}
.btn-submit:disabled {
  opacity: 0.5;
  cursor: default;
}

/* Success state */
.success-state {
  text-align: center;
  padding: 40px 20px;
}
.success-ic {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: rgba(74, 119, 82, 0.14);
  color: var(--success);
  font-size: 1.8rem;
  display: grid;
  place-items: center;
  margin: 0 auto 20px;
  border: 2px solid rgba(74, 119, 82, 0.3);
}
.success-state h3 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 2rem;
  color: var(--navy-d);
  margin-bottom: 10px;
}
.success-state p {
  font-size: 0.9rem;
  color: var(--ink-2);
  line-height: 1.6;
  max-width: 380px;
  margin: 0 auto 24px;
}
.btn-reset {
  background: var(--cream-2);
  border: 1px solid var(--line-strong);
  color: var(--ink-2);
  font-family: inherit;
  font-size: 0.86rem;
  font-weight: 600;
  padding: 10px 22px;
  border-radius: var(--r-md);
  cursor: pointer;
  transition: all 0.15s;
}
.btn-reset:hover {
  background: var(--cream);
  border-color: var(--navy);
  color: var(--navy-d);
}

/* ── FAQ accordion ── */
.faq-section {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 28px 30px;
  box-shadow: var(--shadow-1);
}
.faq-title {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.7rem;
  color: var(--navy-d);
  margin-bottom: 20px;
}
.acc-item {
  border-bottom: 1px solid var(--line);
}
.acc-item:last-child {
  border-bottom: none;
}
.acc-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: transparent;
  border: none;
  padding: 16px 0;
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ink);
  transition: color 0.15s;
}
.acc-trigger:hover {
  color: var(--navy-2);
}
.acc-trigger[aria-expanded="true"] {
  color: var(--navy-d);
}
.acc-ic {
  font-size: 1.3rem;
  color: var(--gold-d);
  flex-shrink: 0;
  line-height: 1;
  transition: transform 0.2s;
  font-weight: 400;
}
.acc-trigger[aria-expanded="true"] .acc-ic {
  transform: rotate(45deg);
}
.acc-body {
  overflow: hidden;
  max-height: 0;
  transition: max-height 0.28s ease;
}
.acc-body p {
  padding: 0 0 16px;
  font-size: 0.88rem;
  color: var(--ink-2);
  line-height: 1.7;
}

/* ── Footer ── */
.foot {
  background: var(--navy-d);
  color: rgba(251, 248, 242, 0.5);
  text-align: center;
  padding: 22px 40px;
  font-size: 0.8rem;
}
.foot a {
  color: rgba(251, 248, 242, 0.6);
  text-decoration: none;
}
.foot a:hover {
  color: var(--gold-light);
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 12px 24px;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 50;
  white-space: nowrap;
}

/* ── Responsive ── */
@media (max-width: 960px) {
  .main-grid {
    grid-template-columns: 1fr;
    gap: 30px;
  }
}
@media (max-width: 720px) {
  .nav-links {
    display: none;
  }
  .nav {
    padding: 16px 20px;
  }
  .page-head {
    padding: 120px 20px 50px;
    min-height: 260px;
  }
  .main-grid {
    padding: 36px 20px 60px;
  }
  .form-card {
    padding: 24px 20px;
  }
  .faq-section {
    padding: 22px 20px;
  }
}
@media (max-width: 560px) {
  .form-row {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .form-actions {
    flex-direction: column;
    align-items: stretch;
  }
  .btn-submit {
    text-align: center;
  }
}

