:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --sh-1: 0 1px 2px rgba(0, 0, 0, 0.4);
  --sh-2: 0 8px 24px rgba(0, 0, 0, 0.45);
  --sh-3: 0 18px 48px rgba(0, 0, 0, 0.55);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
}

body {
  background:
    radial-gradient(1200px 600px at 85% -10%, rgba(198, 255, 58, 0.06), transparent 60%),
    radial-gradient(900px 500px at -5% 0%, rgba(255, 106, 43, 0.06), transparent 55%),
    var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

.eyebrow {
  display: block;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--neon);
}

.muted { color: var(--muted); }

:focus-visible {
  outline: 2px solid var(--neon);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------- Topbar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding: 16px 24px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent), var(--surface);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 20;
  backdrop-filter: blur(8px);
}

.brand { display: flex; align-items: center; gap: 14px; }

.logo {
  width: 46px;
  height: 46px;
  border-radius: var(--r-md);
  display: grid;
  place-items: center;
  font-weight: 900;
  font-size: 18px;
  letter-spacing: 0.04em;
  color: #0d0f12;
  background: linear-gradient(135deg, var(--neon), var(--neon-d));
  box-shadow: 0 6px 18px rgba(198, 255, 58, 0.3);
}

.brand-text h1 {
  margin: 2px 0 0;
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -0.01em;
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.plan-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 6px 14px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  min-width: 64px;
}

.plan-stat-num {
  font-size: 20px;
  font-weight: 900;
  line-height: 1.1;
  color: var(--neon);
}

.plan-stat-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- Buttons ---------- */
.btn {
  font-family: inherit;
  font-weight: 700;
  font-size: 14px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-md);
  padding: 11px 18px;
  cursor: pointer;
  color: var(--ink);
  background: var(--surface-2);
  transition: transform 0.08s ease, background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
}

.btn:hover { background: var(--elevated); border-color: var(--line-2); }
.btn:active { transform: translateY(1px); }

.btn-primary {
  background: linear-gradient(135deg, var(--neon), var(--neon-d));
  color: #0d0f12;
  border-color: transparent;
  box-shadow: 0 6px 18px rgba(198, 255, 58, 0.25);
}
.btn-primary:hover { background: var(--neon); box-shadow: 0 8px 24px rgba(198, 255, 58, 0.35); }

.btn-ghost { background: transparent; }

.btn-add-day {
  background: var(--orange-soft);
  border-color: rgba(255, 106, 43, 0.4);
  color: #ffd6c2;
}
.btn-add-day:hover { background: rgba(255, 106, 43, 0.22); color: #fff; }

/* ---------- Workspace ---------- */
.workspace {
  display: grid;
  grid-template-columns: 340px 1fr;
  gap: 20px;
  padding: 20px 24px 48px;
  align-items: start;
}

/* ---------- Library ---------- */
.library {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  position: sticky;
  top: 92px;
  max-height: calc(100vh - 116px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: var(--sh-2);
}

.library-head { padding: 18px 18px 14px; border-bottom: 1px solid var(--line); }
.library-head h2 { margin: 0; font-size: 16px; font-weight: 800; }
.library-head .muted { font-size: 12.5px; margin: 2px 0 12px; }

.search-wrap input {
  width: 100%;
  font-family: inherit;
  font-size: 14px;
  color: var(--ink);
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 10px 14px;
}
.search-wrap input::placeholder { color: var(--muted); }
.search-wrap input:focus { border-color: var(--neon); outline: none; }

.filter-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 12px;
}

.chip {
  font-family: inherit;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.03em;
  color: var(--ink-2);
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 6px 12px;
  cursor: pointer;
  transition: all 0.14s ease;
}
.chip:hover { border-color: var(--line-2); color: var(--ink); }
.chip[aria-selected="true"] {
  background: var(--neon-50);
  border-color: var(--neon);
  color: var(--neon);
}

.library-list {
  overflow-y: auto;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.lib-group-label {
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 4px 2px 2px;
}

.lib-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 13px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  cursor: grab;
  transition: transform 0.1s ease, border-color 0.14s ease, background 0.14s ease;
}
.lib-card:hover { border-color: var(--line-2); background: var(--elevated); transform: translateX(2px); }
.lib-card:active { cursor: grabbing; }
.lib-card.dragging { opacity: 0.45; }

.lib-icon {
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: var(--r-sm);
  display: grid;
  place-items: center;
  font-size: 18px;
  background: var(--neon-50);
}

.lib-info { min-width: 0; }
.lib-name { font-size: 14px; font-weight: 700; }
.lib-meta { font-size: 11.5px; color: var(--muted); }

.badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 999px;
  border: 1px solid var(--line);
  color: var(--ink-2);
}
.badge.compound { background: var(--orange-soft); border-color: rgba(255, 106, 43, 0.35); color: #ffb596; }
.badge.isolation { background: rgba(52, 211, 153, 0.12); border-color: rgba(52, 211, 153, 0.3); color: #8df0cf; }

.lib-empty { padding: 24px 8px; text-align: center; color: var(--muted); font-size: 13px; }

/* ---------- Board ---------- */
.board { min-width: 0; }

.board-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
  flex-wrap: wrap;
}

.program-title {
  font-family: inherit;
  font-size: 24px;
  font-weight: 900;
  letter-spacing: -0.02em;
  color: var(--ink);
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  padding: 2px 0;
  margin-top: 2px;
  width: 100%;
  max-width: 560px;
}
.program-title:hover { border-bottom-color: var(--line); }
.program-title:focus { outline: none; border-bottom-color: var(--neon); }

.days {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(330px, 1fr));
  gap: 18px;
  align-items: start;
}

/* ---------- Day block ---------- */
.day {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--sh-2);
  transition: border-color 0.14s ease, box-shadow 0.14s ease;
}
.day.drop-active {
  border-color: var(--neon);
  box-shadow: 0 0 0 1px var(--neon), 0 18px 48px rgba(0, 0, 0, 0.55);
}

.day-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent);
  border-bottom: 1px solid var(--line);
}

.day-index {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--neon);
}

.day-name {
  font-family: inherit;
  font-size: 16px;
  font-weight: 800;
  color: var(--ink);
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--r-sm);
  padding: 3px 6px;
  flex: 1;
  min-width: 0;
}
.day-name:hover { background: var(--surface-2); }
.day-name:focus { outline: none; border-color: var(--neon); background: var(--surface-2); }

.day-remove {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border-radius: var(--r-sm);
  border: 1px solid var(--line);
  background: var(--surface-2);
  color: var(--muted);
  cursor: pointer;
  font-size: 16px;
  line-height: 1;
  transition: all 0.14s ease;
}
.day-remove:hover { color: var(--danger); border-color: rgba(248, 113, 113, 0.5); background: rgba(248, 113, 113, 0.1); }

.day-body { padding: 12px; min-height: 90px; display: flex; flex-direction: column; gap: 10px; }

.day-empty {
  border: 1.5px dashed var(--line-2);
  border-radius: var(--r-md);
  padding: 22px 12px;
  text-align: center;
  color: var(--muted);
  font-size: 13px;
  font-weight: 600;
}

/* ---------- Exercise row ---------- */
.ex-row {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 10px 12px;
  cursor: grab;
  transition: border-color 0.14s ease, box-shadow 0.14s ease, opacity 0.1s ease;
}
.ex-row:hover { border-color: var(--line-2); }
.ex-row:active { cursor: grabbing; }
.ex-row.dragging { opacity: 0.4; }
.ex-row.drag-over-top { box-shadow: 0 -2px 0 var(--neon); }
.ex-row.drag-over-bottom { box-shadow: 0 2px 0 var(--neon); }

.ex-top {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 9px;
}

.ex-handle { color: var(--muted); font-size: 14px; cursor: grab; user-select: none; }
.ex-name { font-size: 14px; font-weight: 700; flex: 1; min-width: 0; }
.ex-muscle { font-size: 10.5px; font-weight: 700; color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; }

.ex-remove {
  margin-left: auto;
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border-radius: 6px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
  transition: all 0.14s ease;
}
.ex-remove:hover { color: var(--danger); background: rgba(248, 113, 113, 0.12); }

.ex-fields { display: flex; gap: 8px; }

.field {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.field label {
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}
.field input {
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  padding: 6px 8px;
  width: 100%;
}
.field input:focus { border-color: var(--neon); outline: none; }

/* ---------- Day footer ---------- */
.day-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 16px;
  border-top: 1px solid var(--line);
  background: var(--surface);
}
.day-summary { font-size: 12px; color: var(--ink-2); }
.day-summary strong { color: var(--neon); font-weight: 800; }
.day-duration {
  font-size: 12px;
  font-weight: 700;
  color: var(--ink-2);
  display: flex;
  align-items: center;
  gap: 5px;
}

/* ---------- Toast ---------- */
.toast-stack {
  position: fixed;
  bottom: 22px;
  right: 22px;
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 10px;
  pointer-events: none;
}
.toast {
  background: var(--elevated);
  border: 1px solid var(--line-2);
  border-left: 3px solid var(--neon);
  border-radius: var(--r-md);
  padding: 12px 16px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--ink);
  box-shadow: var(--sh-3);
  min-width: 200px;
  transform: translateX(120%);
  opacity: 0;
  transition: transform 0.32s cubic-bezier(0.2, 0.9, 0.3, 1), opacity 0.3s ease;
}
.toast.show { transform: translateX(0); opacity: 1; }

/* ---------- Responsive ---------- */
@media (max-width: 920px) {
  .workspace { grid-template-columns: 1fr; }
  .library {
    position: static;
    max-height: 420px;
  }
}

@media (max-width: 520px) {
  .topbar { padding: 14px 16px; }
  .brand-text h1 { font-size: 18px; }
  .topbar-actions { gap: 8px; width: 100%; }
  .plan-stat { min-width: 0; flex: 1; padding: 6px 8px; }
  .btn { padding: 10px 14px; font-size: 13px; }
  .workspace { padding: 16px 14px 40px; gap: 16px; }
  .program-title { font-size: 20px; }
  .days { grid-template-columns: 1fr; }
  .ex-fields { flex-wrap: wrap; }
  .field { flex: 1 1 28%; }
  .toast-stack { left: 14px; right: 14px; bottom: 14px; }
  .toast { min-width: 0; }
}

