(function () {
  "use strict";

  /* ---------- Exercise library data ---------- */
  var LIBRARY = [
    { id: "ex-bench", name: "Barbell Bench Press", group: "Chest", type: "compound", icon: "🏋️", est: 9 },
    { id: "ex-incdb", name: "Incline Dumbbell Press", group: "Chest", type: "compound", icon: "💪", est: 7 },
    { id: "ex-fly", name: "Cable Fly", group: "Chest", type: "isolation", icon: "🔗", est: 5 },
    { id: "ex-pull", name: "Weighted Pull-Up", group: "Back", type: "compound", icon: "🧗", est: 8 },
    { id: "ex-row", name: "Barbell Row", group: "Back", type: "compound", icon: "🚣", est: 8 },
    { id: "ex-pulldown", name: "Lat Pulldown", group: "Back", type: "compound", icon: "⬇️", est: 6 },
    { id: "ex-ohp", name: "Overhead Press", group: "Shoulders", type: "compound", icon: "🆙", est: 8 },
    { id: "ex-lat", name: "Lateral Raise", group: "Shoulders", type: "isolation", icon: "↔️", est: 5 },
    { id: "ex-rear", name: "Rear Delt Fly", group: "Shoulders", type: "isolation", icon: "🦅", est: 5 },
    { id: "ex-squat", name: "Back Squat", group: "Legs", type: "compound", icon: "🦵", est: 10 },
    { id: "ex-rdl", name: "Romanian Deadlift", group: "Legs", type: "compound", icon: "⚙️", est: 9 },
    { id: "ex-legpress", name: "Leg Press", group: "Legs", type: "compound", icon: "🛗", est: 7 },
    { id: "ex-curl", name: "Leg Curl", group: "Legs", type: "isolation", icon: "🌀", est: 5 },
    { id: "ex-bicep", name: "EZ-Bar Curl", group: "Arms", type: "isolation", icon: "💥", est: 5 },
    { id: "ex-tricep", name: "Triceps Pushdown", group: "Arms", type: "isolation", icon: "🔻", est: 5 },
    { id: "ex-hammer", name: "Hammer Curl", group: "Arms", type: "isolation", icon: "🔨", est: 5 },
    { id: "ex-plank", name: "Weighted Plank", group: "Core", type: "isolation", icon: "🧱", est: 4 },
    { id: "ex-crunch", name: "Cable Crunch", group: "Core", type: "isolation", icon: "🌊", est: 4 }
  ];

  var GROUPS = ["Chest", "Back", "Shoulders", "Legs", "Arms", "Core"];

  /* ---------- State ---------- */
  var uid = 0;
  function nextId(prefix) { uid += 1; return prefix + "-" + Date.now().toString(36) + "-" + uid; }

  // Each day: { id, name, exercises: [{ rowId, libId, name, group, type, est, sets, reps, rest }] }
  var state = { days: [] };

  function makeRow(libId, opts) {
    var lib = LIBRARY.filter(function (x) { return x.id === libId; })[0];
    if (!lib) return null;
    opts = opts || {};
    return {
      rowId: nextId("row"),
      libId: lib.id,
      name: lib.name,
      group: lib.group,
      type: lib.type,
      est: lib.est,
      sets: opts.sets != null ? opts.sets : (lib.type === "compound" ? 4 : 3),
      reps: opts.reps != null ? opts.reps : (lib.type === "compound" ? 8 : 12),
      rest: opts.rest != null ? opts.rest : (lib.type === "compound" ? 120 : 60)
    };
  }

  function seed() {
    var day1 = { id: nextId("day"), name: "Day 1 — Push", exercises: [] };
    ["ex-bench", "ex-ohp", "ex-incdb", "ex-lat", "ex-tricep"].forEach(function (id) {
      var r = makeRow(id); if (r) day1.exercises.push(r);
    });
    var day2 = { id: nextId("day"), name: "Day 2 — Pull", exercises: [] };
    ["ex-pull", "ex-row", "ex-pulldown", "ex-bicep", "ex-rear"].forEach(function (id) {
      var r = makeRow(id); if (r) day2.exercises.push(r);
    });
    var day3 = { id: nextId("day"), name: "Day 3 — Legs", exercises: [] };
    ["ex-squat", "ex-rdl", "ex-legpress", "ex-curl", "ex-plank"].forEach(function (id) {
      var r = makeRow(id); if (r) day3.exercises.push(r);
    });
    state.days = [day1, day2, day3];
  }

  /* ---------- DOM refs ---------- */
  var libraryList = document.getElementById("libraryList");
  var filterRow = document.getElementById("filterRow");
  var searchInput = document.getElementById("searchInput");
  var daysContainer = document.getElementById("daysContainer");
  var addDayBtn = document.getElementById("addDayBtn");
  var resetBtn = document.getElementById("resetBtn");
  var saveBtn = document.getElementById("saveBtn");
  var toastStack = document.getElementById("toastStack");
  var statDays = document.getElementById("statDays");
  var statExercises = document.getElementById("statExercises");
  var statVolume = document.getElementById("statVolume");

  var activeFilter = "All";
  var searchTerm = "";

  /* ---------- Toast ---------- */
  function toast(msg) {
    var el = document.createElement("div");
    el.className = "toast";
    el.textContent = msg;
    toastStack.appendChild(el);
    requestAnimationFrame(function () { el.classList.add("show"); });
    setTimeout(function () {
      el.classList.remove("show");
      setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, 360);
    }, 2400);
  }

  /* ---------- Library render ---------- */
  function renderFilters() {
    filterRow.innerHTML = "";
    var all = ["All"].concat(GROUPS);
    all.forEach(function (g) {
      var chip = document.createElement("button");
      chip.type = "button";
      chip.className = "chip";
      chip.textContent = g;
      chip.setAttribute("role", "tab");
      chip.setAttribute("aria-selected", g === activeFilter ? "true" : "false");
      chip.addEventListener("click", function () {
        activeFilter = g;
        renderFilters();
        renderLibrary();
      });
      filterRow.appendChild(chip);
    });
  }

  function renderLibrary() {
    libraryList.innerHTML = "";
    var matches = LIBRARY.filter(function (ex) {
      var byGroup = activeFilter === "All" || ex.group === activeFilter;
      var bySearch = !searchTerm || ex.name.toLowerCase().indexOf(searchTerm) !== -1 || ex.group.toLowerCase().indexOf(searchTerm) !== -1;
      return byGroup && bySearch;
    });

    if (!matches.length) {
      var empty = document.createElement("div");
      empty.className = "lib-empty";
      empty.textContent = "No exercises match your search.";
      libraryList.appendChild(empty);
      return;
    }

    var groupsToShow = activeFilter === "All" ? GROUPS : [activeFilter];
    groupsToShow.forEach(function (group) {
      var inGroup = matches.filter(function (ex) { return ex.group === group; });
      if (!inGroup.length) return;
      var label = document.createElement("div");
      label.className = "lib-group-label";
      label.textContent = group;
      libraryList.appendChild(label);
      inGroup.forEach(function (ex) {
        libraryList.appendChild(buildLibCard(ex));
      });
    });
  }

  function buildLibCard(ex) {
    var card = document.createElement("div");
    card.className = "lib-card";
    card.setAttribute("draggable", "true");
    card.dataset.libId = ex.id;

    var icon = document.createElement("div");
    icon.className = "lib-icon";
    icon.textContent = ex.icon;

    var info = document.createElement("div");
    info.className = "lib-info";
    var name = document.createElement("div");
    name.className = "lib-name";
    name.textContent = ex.name;
    var meta = document.createElement("div");
    meta.className = "lib-meta";
    meta.innerHTML = '<span class="badge ' + ex.type + '">' + ex.type + "</span>";
    info.appendChild(name);
    info.appendChild(meta);

    card.appendChild(icon);
    card.appendChild(info);

    card.addEventListener("dragstart", function (e) {
      card.classList.add("dragging");
      e.dataTransfer.effectAllowed = "copy";
      e.dataTransfer.setData("application/x-lib-id", ex.id);
      e.dataTransfer.setData("text/plain", ex.id);
    });
    card.addEventListener("dragend", function () { card.classList.remove("dragging"); });
    return card;
  }

  /* ---------- Days render ---------- */
  function estDayMinutes(day) {
    // base exercise est + ~ per-set time from rest
    var mins = 0;
    day.exercises.forEach(function (r) {
      var sets = clampInt(r.sets, 1, 12);
      var rest = clampInt(r.rest, 0, 600);
      // working time ~ 45s/set + rest between sets
      mins += (sets * 45 + (sets - 1) * rest) / 60;
    });
    return Math.round(mins);
  }

  function renderDays() {
    daysContainer.innerHTML = "";
    state.days.forEach(function (day, i) {
      daysContainer.appendChild(buildDay(day, i));
    });
    updateStats();
  }

  function buildDay(day, index) {
    var el = document.createElement("article");
    el.className = "day";
    el.dataset.dayId = day.id;

    /* head */
    var head = document.createElement("div");
    head.className = "day-head";
    var idx = document.createElement("span");
    idx.className = "day-index";
    idx.textContent = "Day " + (index + 1);
    var nameInput = document.createElement("input");
    nameInput.className = "day-name";
    nameInput.value = day.name;
    nameInput.setAttribute("aria-label", "Day name");
    nameInput.addEventListener("input", function () { day.name = nameInput.value; });
    var del = document.createElement("button");
    del.className = "day-remove";
    del.type = "button";
    del.setAttribute("aria-label", "Remove " + day.name);
    del.textContent = "×";
    del.addEventListener("click", function () {
      state.days = state.days.filter(function (d) { return d.id !== day.id; });
      renderDays();
      toast("Removed " + day.name);
    });
    head.appendChild(idx);
    head.appendChild(nameInput);
    head.appendChild(del);

    /* body */
    var body = document.createElement("div");
    body.className = "day-body";
    body.dataset.dayId = day.id;

    if (!day.exercises.length) {
      var empty = document.createElement("div");
      empty.className = "day-empty";
      empty.textContent = "Drag exercises here";
      body.appendChild(empty);
    } else {
      day.exercises.forEach(function (row) {
        body.appendChild(buildRow(day, row));
      });
    }

    /* drop handling for adding from library */
    body.addEventListener("dragover", function (e) {
      e.preventDefault();
      el.classList.add("drop-active");
      e.dataTransfer.dropEffect = isRowDrag(e) ? "move" : "copy";
    });
    body.addEventListener("dragleave", function (e) {
      if (!body.contains(e.relatedTarget)) el.classList.remove("drop-active");
    });
    body.addEventListener("drop", function (e) {
      e.preventDefault();
      el.classList.remove("drop-active");
      var libId = e.dataTransfer.getData("application/x-lib-id");
      if (libId && !isRowDrag(e)) {
        var row = makeRow(libId);
        if (row) {
          day.exercises.push(row);
          renderDays();
          toast(row.name + " added to " + day.name);
        }
      }
    });

    /* footer */
    var footer = document.createElement("div");
    footer.className = "day-footer";
    var summary = document.createElement("div");
    summary.className = "day-summary";
    summary.innerHTML = "<strong>" + day.exercises.length + "</strong> exercises · <strong>" +
      totalSets(day) + "</strong> sets";
    var dur = document.createElement("div");
    dur.className = "day-duration";
    dur.innerHTML = "⏱ ~" + estDayMinutes(day) + " min";
    footer.appendChild(summary);
    footer.appendChild(dur);

    el.appendChild(head);
    el.appendChild(body);
    el.appendChild(footer);
    return el;
  }

  function totalSets(day) {
    return day.exercises.reduce(function (sum, r) { return sum + clampInt(r.sets, 0, 99); }, 0);
  }

  function buildRow(day, row) {
    var el = document.createElement("div");
    el.className = "ex-row";
    el.setAttribute("draggable", "true");
    el.dataset.rowId = row.rowId;

    var top = document.createElement("div");
    top.className = "ex-top";
    var handle = document.createElement("span");
    handle.className = "ex-handle";
    handle.textContent = "⋮⋮";
    handle.setAttribute("aria-hidden", "true");
    var name = document.createElement("span");
    name.className = "ex-name";
    name.textContent = row.name;
    var muscle = document.createElement("span");
    muscle.className = "ex-muscle";
    muscle.textContent = row.group;
    var rm = document.createElement("button");
    rm.className = "ex-remove";
    rm.type = "button";
    rm.setAttribute("aria-label", "Remove " + row.name);
    rm.textContent = "×";
    rm.addEventListener("click", function () {
      day.exercises = day.exercises.filter(function (r) { return r.rowId !== row.rowId; });
      renderDays();
      toast("Removed " + row.name);
    });
    top.appendChild(handle);
    top.appendChild(name);
    top.appendChild(muscle);
    top.appendChild(rm);

    var fields = document.createElement("div");
    fields.className = "ex-fields";
    fields.appendChild(buildField("Sets", row.sets, 1, 12, function (v) { row.sets = v; }, day));
    fields.appendChild(buildField("Reps", row.reps, 1, 50, function (v) { row.reps = v; }, day));
    fields.appendChild(buildField("Rest s", row.rest, 0, 600, function (v) { row.rest = v; }, day));

    el.appendChild(top);
    el.appendChild(fields);

    /* reorder drag */
    el.addEventListener("dragstart", function (e) {
      el.classList.add("dragging");
      e.dataTransfer.effectAllowed = "move";
      e.dataTransfer.setData("application/x-row-id", row.rowId);
      e.dataTransfer.setData("application/x-row-day", day.id);
      e.dataTransfer.setData("text/plain", row.rowId);
    });
    el.addEventListener("dragend", function () {
      el.classList.remove("dragging");
      el.classList.remove("drag-over-top");
      el.classList.remove("drag-over-bottom");
    });
    el.addEventListener("dragover", function (e) {
      if (!isRowDrag(e)) return;
      e.preventDefault();
      e.stopPropagation();
      var rect = el.getBoundingClientRect();
      var before = (e.clientY - rect.top) < rect.height / 2;
      el.classList.toggle("drag-over-top", before);
      el.classList.toggle("drag-over-bottom", !before);
    });
    el.addEventListener("dragleave", function () {
      el.classList.remove("drag-over-top");
      el.classList.remove("drag-over-bottom");
    });
    el.addEventListener("drop", function (e) {
      if (!isRowDrag(e)) return;
      e.preventDefault();
      e.stopPropagation();
      var rect = el.getBoundingClientRect();
      var before = (e.clientY - rect.top) < rect.height / 2;
      el.classList.remove("drag-over-top");
      el.classList.remove("drag-over-bottom");
      handleRowDrop(e, day, row.rowId, before);
    });

    return el;
  }

  function buildField(label, value, min, max, onChange, day) {
    var wrap = document.createElement("div");
    wrap.className = "field";
    var lab = document.createElement("label");
    lab.textContent = label;
    var inp = document.createElement("input");
    inp.type = "number";
    inp.min = String(min);
    inp.max = String(max);
    inp.value = String(value);
    inp.setAttribute("aria-label", label);
    inp.addEventListener("input", function () {
      var v = clampInt(parseInt(inp.value, 10), min, max);
      onChange(v);
      // live-update footer without full re-render
      refreshDayFooter(day);
    });
    inp.addEventListener("blur", function () {
      var v = clampInt(parseInt(inp.value, 10), min, max);
      inp.value = String(v);
    });
    wrap.appendChild(lab);
    wrap.appendChild(inp);
    return wrap;
  }

  function refreshDayFooter(day) {
    var dayEl = daysContainer.querySelector('[data-day-id="' + cssEscape(day.id) + '"]');
    if (!dayEl) return;
    var summary = dayEl.querySelector(".day-summary");
    var dur = dayEl.querySelector(".day-duration");
    if (summary) {
      summary.innerHTML = "<strong>" + day.exercises.length + "</strong> exercises · <strong>" +
        totalSets(day) + "</strong> sets";
    }
    if (dur) dur.innerHTML = "⏱ ~" + estDayMinutes(day) + " min";
    updateStats();
  }

  /* ---------- Row drop / reorder logic ---------- */
  function isRowDrag(e) {
    var types = e.dataTransfer.types || [];
    return Array.prototype.indexOf.call(types, "application/x-row-id") !== -1;
  }

  function handleRowDrop(e, targetDay, targetRowId, before) {
    var rowId = e.dataTransfer.getData("application/x-row-id");
    var fromDayId = e.dataTransfer.getData("application/x-row-day");
    if (!rowId || rowId === targetRowId) return;

    var fromDay = state.days.filter(function (d) { return d.id === fromDayId; })[0];
    if (!fromDay) return;
    var movingIdx = indexOfRow(fromDay, rowId);
    if (movingIdx === -1) return;
    var moving = fromDay.exercises.splice(movingIdx, 1)[0];

    var targetIdx = indexOfRow(targetDay, targetRowId);
    if (targetIdx === -1) {
      targetDay.exercises.push(moving);
    } else {
      targetDay.exercises.splice(before ? targetIdx : targetIdx + 1, 0, moving);
    }
    renderDays();
  }

  function indexOfRow(day, rowId) {
    for (var i = 0; i < day.exercises.length; i++) {
      if (day.exercises[i].rowId === rowId) return i;
    }
    return -1;
  }

  /* ---------- Stats ---------- */
  function updateStats() {
    var exCount = 0, setCount = 0;
    state.days.forEach(function (d) {
      exCount += d.exercises.length;
      setCount += totalSets(d);
    });
    statDays.textContent = String(state.days.length);
    statExercises.textContent = String(exCount);
    statVolume.textContent = String(setCount);
  }

  /* ---------- Helpers ---------- */
  function clampInt(n, min, max) {
    if (isNaN(n)) n = min;
    n = Math.round(n);
    if (n < min) n = min;
    if (n > max) n = max;
    return n;
  }

  function cssEscape(s) {
    if (window.CSS && CSS.escape) return CSS.escape(s);
    return String(s).replace(/["\\]/g, "\\$&");
  }

  /* ---------- Top-level actions ---------- */
  addDayBtn.addEventListener("click", function () {
    var n = state.days.length + 1;
    state.days.push({ id: nextId("day"), name: "Day " + n + " — New", exercises: [] });
    renderDays();
    var last = daysContainer.lastElementChild;
    if (last) last.scrollIntoView({ behavior: "smooth", block: "nearest" });
    toast("Day " + n + " added");
  });

  resetBtn.addEventListener("click", function () {
    seed();
    renderDays();
    toast("Plan reset to default split");
  });

  saveBtn.addEventListener("click", function () {
    var title = document.getElementById("programTitle").value || "Untitled Program";
    var exCount = state.days.reduce(function (s, d) { return s + d.exercises.length; }, 0);
    toast("Saved “" + title + "” · " + state.days.length + " days, " + exCount + " exercises");
  });

  searchInput.addEventListener("input", function () {
    searchTerm = searchInput.value.trim().toLowerCase();
    renderLibrary();
  });

  /* ---------- Init ---------- */
  seed();
  renderFilters();
  renderLibrary();
  renderDays();
})();

snippets.css:
:root {
  --cream: #f4efe4;
  --paper: #faf7f0;
  --white: #ffffff;
  --newsprint: #efe9da;
  --ink: #16130f;
  --ink-2: #2b2620;
  --ink-3: #4a443b;
  --muted: #7a7164;
  --red: #b4291f;
  --red-d: #8f1f17;
  --red-50: #f3dcd9;
  --rule: rgba(22, 19, 15, 0.16);
  --rule-2: rgba(22, 19, 15, 0.30);
  --rule-hair: rgba(22, 19, 15, 0.10);
  --ok: #2f7d4f;
  --warn: #b67a18;
  --danger: #b4291f;
  --r-sm: 4px;
  --r-md: 8px;
  --r-lg: 12px;
  --serif: "Playfair Display", "Times New Roman", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--cream);
  color: var(--ink);
  font-family: var(--sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-size: 16px;
}

.skip-link {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--ink);
  color: var(--paper);
  padding: 10px 16px;
  z-index: 50;
  font-size: 13px;
  font-weight: 600;
}
.skip-link:focus { left: 8px; top: 8px; }

:focus-visible {
  outline: 2px solid var(--red);
  outline-offset: 2px;
}

/* ---------- Masthead ---------- */
.masthead {
  background: var(--paper);
  border-bottom: 3px double var(--rule-2);
}
.masthead__bar {
  max-width: 1180px;
  margin: 0 auto;
  padding: 7px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--rule-hair);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 500;
}
.masthead__name {
  text-align: center;
  padding: 14px 24px 8px;
}
.masthead__title {
  font-family: var(--serif);
  font-weight: 900;
  font-size: clamp(2.4rem, 7vw, 4.2rem);
  letter-spacing: -0.01em;
  margin: 0;
  line-height: 1;
  color: var(--ink);
}
.masthead__nav {
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  gap: 26px;
  justify-content: center;
  flex-wrap: wrap;
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
}
.masthead__nav a {
  display: inline-block;
  padding: 9px 0;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-2);
  text-decoration: none;
}
.masthead__nav a:hover { color: var(--red); }
.masthead__nav a[aria-current="page"] {
  color: var(--red);
  border-bottom: 2px solid var(--red);
  margin-bottom: -1px;
}

/* ---------- Layout shell ---------- */
.wrap {
  max-width: 1180px;
  margin: 0 auto;
  padding: 30px 24px 60px;
}

/* ---------- Live blog head ---------- */
.kicker {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 0 0 12px;
  flex-wrap: wrap;
}
.kicker__topic {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-3);
}

.live-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: var(--red);
  color: var(--white);
  padding: 4px 10px 4px 9px;
  border-radius: var(--r-sm);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.live-badge__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: 0 0 0 0 rgba(255, 255, 255, 0.7);
  animation: pulse 1.6s ease-out infinite;
}
@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(255, 255, 255, 0.55); }
  70% { box-shadow: 0 0 0 7px rgba(255, 255, 255, 0); }
  100% { box-shadow: 0 0 0 0 rgba(255, 255, 255, 0); }
}

.liveblog__headline {
  font-family: var(--serif);
  font-weight: 800;
  font-size: clamp(1.9rem, 4.6vw, 3.15rem);
  line-height: 1.04;
  letter-spacing: -0.01em;
  margin: 0 0 16px;
  color: var(--ink);
  max-width: 17ch;
}
.liveblog__summary {
  font-size: 1.12rem;
  line-height: 1.55;
  color: var(--ink-2);
  margin: 0 0 18px;
  max-width: 62ch;
}
.liveblog__summary::first-letter {
  initial-letter: 3;
  -webkit-initial-letter: 3;
  font-family: var(--serif);
  font-weight: 800;
  color: var(--red);
  margin-right: 8px;
}

.liveblog__byline {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px 18px;
  padding: 14px 0;
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
  font-size: 13px;
  color: var(--ink-3);
}
.byline__authors strong { color: var(--ink); font-weight: 600; }
.byline__meta {
  color: var(--muted);
  letter-spacing: 0.02em;
}
.byline__sep { margin: 0 4px; }

/* ---------- Two-column layout ---------- */
.liveblog__layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 48px;
  margin-top: 28px;
}
.liveblog__main { min-width: 0; }

/* ---------- Stream toolbar ---------- */
.stream-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 14px;
  margin-bottom: 4px;
  border-bottom: 2px solid var(--ink);
  flex-wrap: wrap;
}
.stream-toolbar__left {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--ink-3);
}
.stream-count { color: var(--ink); }
.stream-toolbar__hint { color: var(--muted); font-weight: 500; }
.stream-toolbar__sep { color: var(--rule-2); }

.btn {
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.04em;
  border: 1px solid var(--ink);
  background: var(--paper);
  color: var(--ink);
  padding: 9px 15px;
  border-radius: var(--r-sm);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background 0.15s ease, color 0.15s ease, transform 0.05s ease;
}
.btn:hover { background: var(--newsprint); }
.btn:active { transform: translateY(1px); }
.btn--accent {
  background: var(--red);
  border-color: var(--red);
  color: var(--white);
}
.btn--accent:hover { background: var(--red-d); border-color: var(--red-d); }
.btn__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--white);
  animation: pulse 1.6s ease-out infinite;
}

/* ---------- Stream / entries ---------- */
.stream {
  list-style: none;
  margin: 0;
  padding: 0;
}
.entry {
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr);
  gap: 20px;
  padding: 24px 0;
  border-bottom: 1px solid var(--rule);
  position: relative;
}
.entry::before {
  content: "";
  position: absolute;
  left: 96px;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--rule-hair);
  transform: translateX(-10px);
}
.entry__rail {
  display: flex;
  flex-direction: column;
  gap: 3px;
  position: relative;
  z-index: 1;
}
.entry__rail::after {
  content: "";
  position: absolute;
  right: -10px;
  top: 7px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--paper);
  border: 2px solid var(--ink-3);
  transform: translateX(50%);
}
.entry--key-row .entry__rail::after,
.entry:first-child .entry__rail::after {
  border-color: var(--red);
  background: var(--red);
}
.entry__time {
  font-family: var(--sans);
  font-weight: 700;
  font-size: 14px;
  color: var(--ink);
  letter-spacing: 0.01em;
}
.entry__rel {
  font-size: 11px;
  color: var(--muted);
  letter-spacing: 0.04em;
}

.entry__body { min-width: 0; }
.entry__kicker {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--red);
  margin: 0 0 6px;
}
.entry--key {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  color: var(--ink-3);
}
.key-flag {
  background: var(--ink);
  color: var(--paper);
  padding: 2px 7px;
  border-radius: var(--r-sm);
  font-size: 10px;
  letter-spacing: 0.12em;
}
.entry__headline {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.32rem;
  line-height: 1.18;
  margin: 0 0 10px;
  color: var(--ink);
}
.entry__body p {
  margin: 0 0 11px;
  font-size: 1rem;
  line-height: 1.62;
  color: var(--ink-2);
  text-align: justify;
  hyphens: auto;
}
.entry__body p:last-child { margin-bottom: 0; }
.entry__lede::first-letter {
  initial-letter: 2;
  -webkit-initial-letter: 2;
  font-family: var(--serif);
  font-weight: 700;
  color: var(--ink);
  margin-right: 6px;
}
.entry__author {
  font-style: italic;
  font-size: 0.9rem !important;
  color: var(--muted) !important;
  text-align: left !important;
}

/* New entry flash */
.entry--flash {
  animation: flashIn 1.6s ease-out;
}
@keyframes flashIn {
  0% { background: var(--red-50); }
  100% { background: transparent; }
}
.entry--new .entry__time {
  color: var(--red);
}

/* ---------- Press photos (CSS-only) ---------- */
.entry__fig { margin: 4px 0 14px; }
.press-photo {
  width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: var(--r-sm);
  border: 1px solid var(--rule);
  position: relative;
  overflow: hidden;
}
.press-photo::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(115deg,
      rgba(255, 255, 255, 0.04) 0 2px,
      rgba(0, 0, 0, 0.04) 2px 4px);
  mix-blend-mode: overlay;
  pointer-events: none;
}
.press-photo--surge {
  background:
    radial-gradient(120% 80% at 20% 0%, rgba(200, 214, 214, 0.55), transparent 60%),
    linear-gradient(180deg, #5d6a6b 0%, #44514f 32%, #2f3b39 60%, #1d2625 100%),
    linear-gradient(90deg, #3a4746, #4c5957);
}
.press-photo--crew {
  background:
    radial-gradient(90% 120% at 78% 20%, rgba(214, 168, 60, 0.45), transparent 55%),
    linear-gradient(180deg, #2c2620 0%, #3a3024 40%, #241e18 100%),
    linear-gradient(120deg, #4a3c26, #2a221a);
}
.press-photo--live {
  background:
    radial-gradient(110% 90% at 30% 10%, rgba(180, 41, 31, 0.4), transparent 55%),
    linear-gradient(180deg, #3a2622 0%, #2a1c1a 45%, #161311 100%);
}
figcaption {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 4px 12px;
  margin-top: 7px;
  font-size: 12.5px;
  line-height: 1.4;
}
.figcap__text { font-style: italic; color: var(--ink-3); }
.figcap__credit {
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 10.5px;
  color: var(--muted);
  font-weight: 600;
  white-space: nowrap;
}

/* ---------- Pull quote ---------- */
.pull {
  margin: 16px 0;
  padding: 4px 0 4px 20px;
  border-left: 3px solid var(--red);
}
.pull p {
  font-family: var(--serif) !important;
  font-weight: 600;
  font-size: 1.34rem !important;
  line-height: 1.32 !important;
  color: var(--ink) !important;
  font-style: italic;
  margin: 0 0 8px !important;
  text-align: left !important;
  hyphens: none !important;
}
.pull cite {
  display: block;
  font-family: var(--sans);
  font-style: normal;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- Aside ---------- */
.liveblog__aside {
  position: sticky;
  top: 20px;
  align-self: start;
  display: flex;
  flex-direction: column;
  gap: 22px;
}
.keybox {
  border: 1px solid var(--ink);
  background: var(--white);
  padding: 18px 20px 16px;
  border-radius: var(--r-md);
}
.keybox__title {
  font-family: var(--sans);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  margin: 0 0 12px;
  padding-bottom: 10px;
  border-bottom: 2px solid var(--ink);
  color: var(--ink);
}
.keybox__list {
  margin: 0;
  padding: 0;
  list-style: none;
}
.keybox__list li {
  position: relative;
  padding: 8px 0 8px 18px;
  font-size: 14px;
  line-height: 1.45;
  color: var(--ink-2);
  border-bottom: 1px solid var(--rule-hair);
}
.keybox__list li:last-child { border-bottom: 0; }
.keybox__list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 14px;
  width: 6px;
  height: 6px;
  background: var(--red);
  border-radius: 1px;
}
.keybox__list strong { color: var(--ink); font-weight: 600; }
.keybox__foot {
  margin: 12px 0 0;
  padding-top: 10px;
  border-top: 1px solid var(--rule-hair);
  font-size: 11px;
  color: var(--muted);
  letter-spacing: 0.03em;
}

.aside-card {
  border: 1px solid var(--rule);
  background: var(--newsprint);
  padding: 16px 20px;
  border-radius: var(--r-md);
}
.aside-card__kicker {
  margin: 0 0 2px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--red);
}
.aside-card__big {
  font-family: var(--serif);
  font-weight: 800;
  font-size: 2.6rem;
  line-height: 1;
  margin: 0 0 6px;
  color: var(--ink);
}
.aside-card__sub {
  margin: 0 0 6px;
  font-size: 13px;
  line-height: 1.45;
  color: var(--ink-3);
}
.aside-card__sub--alt { margin-bottom: 0; color: var(--red-d); }
.aside-card__sub strong { color: var(--red-d); }

/* ---------- Footer ---------- */
.foot {
  border-top: 3px double var(--rule-2);
  background: var(--paper);
  padding: 24px;
  text-align: center;
}
.foot__name {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.3rem;
  margin: 0 0 4px;
  color: var(--ink);
}
.foot__note {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
  letter-spacing: 0.02em;
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translate(-50%, 20px);
  background: var(--ink);
  color: var(--paper);
  padding: 11px 18px;
  border-radius: var(--r-sm);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.02em;
  box-shadow: 0 6px 20px rgba(22, 19, 15, 0.22);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s ease, transform 0.22s ease;
  z-index: 60;
  max-width: calc(100vw - 32px);
}
.toast--show {
  opacity: 1;
  transform: translate(-50%, 0);
}
.toast__dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--red);
  margin-right: 8px;
  vertical-align: middle;
}

/* ---------- Responsive ---------- */
@media (max-width: 880px) {
  .liveblog__layout {
    grid-template-columns: 1fr;
    gap: 36px;
  }
  .liveblog__aside {
    position: static;
    flex-direction: column;
  }
}

@media (max-width: 720px) {
  .wrap { padding: 22px 18px 48px; }
  .liveblog__summary { font-size: 1.05rem; }
  .entry {
    grid-template-columns: 1fr;
    gap: 8px;
    padding: 20px 0;
  }
  .entry::before { display: none; }
  .entry__rail {
    flex-direction: row;
    align-items: baseline;
    gap: 10px;
  }
  .entry__rail::after { display: none; }
  .entry__body p { text-align: left; hyphens: none; }
}

@media (max-width: 400px) {
  body { font-size: 15px; }
  .masthead__bar { font-size: 10px; padding: 6px 16px; }
  .masthead__name { padding: 12px 16px 6px; }
  .masthead__nav { gap: 16px; padding: 0 16px; }
  .stream-toolbar { flex-direction: column; align-items: flex-start; }
  .btn--accent { width: 100%; justify-content: center; }
}

@media (prefers-reduced-motion: reduce) {
  .live-badge__dot, .btn__dot { animation: none; }
  .entry--flash { animation: none; }
  .toast { transition: opacity 0.01s; }
}

