(function () {
  "use strict";

  var stream = document.getElementById("stream");
  var newBtn = document.getElementById("newUpdateBtn");
  var countEl = document.getElementById("streamCount");
  var toastEl = document.getElementById("toast");
  var keyboxTime = document.getElementById("keyboxTime");

  /* ---------- Toast helper ---------- */
  var toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.innerHTML = '<span class="toast__dot" aria-hidden="true"></span>' + msg;
    toastEl.classList.add("toast--show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("toast--show");
    }, 2600);
  }

  /* ---------- Relative time ---------- */
  function relTime(date) {
    var diff = Math.round((Date.now() - date.getTime()) / 1000);
    if (diff < 5) return "just now";
    if (diff < 60) return diff + " sec ago";
    var mins = Math.round(diff / 60);
    if (mins < 60) return mins + " min ago";
    var hours = Math.round(mins / 60);
    if (hours < 24) return hours + " hr ago";
    var days = Math.round(hours / 24);
    return days + (days === 1 ? " day ago" : " days ago");
  }

  function fmtClock(date) {
    var h = date.getHours();
    var m = date.getMinutes();
    var ampm = h >= 12 ? "PM" : "AM";
    h = h % 12;
    if (h === 0) h = 12;
    return h + ":" + (m < 10 ? "0" + m : m) + " " + ampm;
  }

  /* ---------- Refresh all relative timestamps ---------- */
  function refreshRel() {
    var entries = stream.querySelectorAll(".entry");
    for (var i = 0; i < entries.length; i++) {
      var iso = entries[i].getAttribute("data-time");
      var relEl = entries[i].querySelector("[data-rel]");
      if (!iso || !relEl) continue;
      var d = new Date(iso);
      if (isNaN(d.getTime())) continue;
      relEl.textContent = relTime(d);
    }
    if (keyboxTime) {
      keyboxTime.textContent = "moments ago";
    }
  }

  /* ---------- Update count label ---------- */
  function updateCount() {
    var n = stream.querySelectorAll(".entry").length;
    countEl.textContent = n + (n === 1 ? " update" : " updates");
  }

  /* ---------- Pool of fictional new updates ---------- */
  var pool = [
    {
      kicker: "Bay County",
      headline: "Water reaches the first floor of the Wharf Row market",
      key: false,
      body: "Reporters at the scene say the historic market has taken on roughly a foot of water, with vendors moving stock to upper shelves. Police have closed the surrounding blocks to all but emergency vehicles.",
      author: "— Marcus Vellán, at the Old Wharf"
    },
    {
      kicker: "Schools",
      headline: "All coastal schools to remain closed Tuesday",
      key: false,
      body: "The Meridian district announced that every school east of the Pinewright ridge will stay closed tomorrow, with remote instruction suspended in areas expecting prolonged power outages."
    },
    {
      kicker: "Surge",
      headline: "Tide gauge at Cole Point hits a new daily record",
      key: true,
      body: "The Cole Point gauge has recorded its highest reading since the station opened, surpassing the mark set during last autumn's nor'easter. Forecasters warn the peak is still two hours away.",
      author: "— Dispatch Weather Desk"
    },
    {
      kicker: "Rescues",
      headline: "Swift-water teams pull six from stranded vehicles",
      key: false,
      body: "Fire officials confirm that swift-water rescue crews have helped six people from cars caught in flooded underpasses along Calder Street. No injuries have been reported.",
      author: "— Dana Okwu"
    },
    {
      kicker: "Power",
      headline: "Outage total climbs past 18,000 customers",
      key: false,
      body: "Meridian Power & Light now reports more than 18,000 homes and businesses without electricity, with the heaviest losses on the Cole County peninsula. Restoration crews remain grounded until winds ease."
    },
    {
      kicker: "Shelters",
      headline: "Fairgrounds shelter nears capacity; new site opening",
      key: false,
      body: "Officials say the Meridian Fairgrounds shelter is approaching its limit and that a fourth site will open within the hour at the Tasker County armory to absorb arriving families.",
      author: "— Dana Okwu"
    }
  ];
  var poolIdx = 0;

  /* ---------- Build a new entry element ---------- */
  function buildEntry(item, date) {
    var li = document.createElement("li");
    li.className = "entry entry--flash entry--new";
    li.setAttribute("data-time", date.toISOString());

    var rail = document.createElement("div");
    rail.className = "entry__rail";

    var time = document.createElement("time");
    time.className = "entry__time";
    time.setAttribute("datetime", date.toISOString());
    time.textContent = fmtClock(date);

    var rel = document.createElement("span");
    rel.className = "entry__rel";
    rel.setAttribute("data-rel", "");
    rel.textContent = "just now";

    rail.appendChild(time);
    rail.appendChild(rel);

    var body = document.createElement("div");
    body.className = "entry__body";

    var kick = document.createElement("p");
    if (item.key) {
      kick.className = "entry__kicker entry--key";
      kick.innerHTML =
        '<span class="key-flag">Key update</span> ' + escapeHtml(item.kicker);
    } else {
      kick.className = "entry__kicker";
      kick.textContent = item.kicker;
    }

    var h = document.createElement("h3");
    h.className = "entry__headline";
    h.textContent = item.headline;

    var p = document.createElement("p");
    p.textContent = item.body;

    body.appendChild(kick);
    body.appendChild(h);
    body.appendChild(p);

    if (item.author) {
      var au = document.createElement("p");
      au.className = "entry__author";
      au.textContent = item.author;
      body.appendChild(au);
    }

    li.appendChild(rail);
    li.appendChild(body);
    return li;
  }

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }

  /* ---------- Prepend a fresh update ---------- */
  function postUpdate() {
    var item = pool[poolIdx % pool.length];
    poolIdx++;
    var now = new Date();
    var el = buildEntry(item, now);

    // Clear the "new" red accent from the previously-newest entry
    var prevNew = stream.querySelector(".entry--new");
    if (prevNew) prevNew.classList.remove("entry--new");

    stream.insertBefore(el, stream.firstElementChild);
    updateCount();
    refreshRel();

    // Remove the one-shot flash class after the animation settles
    setTimeout(function () {
      el.classList.remove("entry--flash");
    }, 1700);

    toast(item.key ? "Key update posted" : "New update posted");

    // Move focus to the new headline for keyboard/AT users
    var headline = el.querySelector(".entry__headline");
    if (headline) {
      headline.setAttribute("tabindex", "-1");
      headline.focus({ preventScroll: false });
    }
  }

  if (newBtn) newBtn.addEventListener("click", postUpdate);

  /* ---------- Init ---------- */
  refreshRel();
  updateCount();
  setInterval(refreshRel, 30000);
})();

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --pending: #6b7280;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

/* ── Layout ── */
.appts {
  max-width: 640px;
  margin: 0 auto;
  padding: 32px 20px 56px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.appts-head {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.appts-head h1 {
  font-size: 1.6rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

/* ── Tabs ── */
.tabs {
  display: inline-flex;
  align-self: flex-start;
  gap: 4px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 4px;
  box-shadow: var(--shadow-1);
}
.tab {
  border: none;
  background: transparent;
  border-radius: 999px;
  padding: 8px 18px;
  font: inherit;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--muted);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background 0.15s, color 0.15s;
}
.tab:hover {
  color: var(--ink-2);
}
.tab.is-active {
  background: var(--teal-d);
  color: #fff;
}
.count {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--teal-50);
  color: var(--teal-d);
  font-size: 0.74rem;
  font-weight: 700;
}
.tab.is-active .count {
  background: rgba(255, 255, 255, 0.22);
  color: #fff;
}

/* ── Panels ── */
.panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.panel[hidden] {
  display: none;
}

/* ── Appointment card ── */
.card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 18px;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 16px;
  box-shadow: var(--shadow-1);
  transition: opacity 0.2s, border-color 0.15s;
}
.card.is-past {
  box-shadow: none;
  background: #fafdfc;
}
.card.is-cancelled {
  opacity: 0.7;
}

.date {
  width: 58px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-radius: var(--r-sm);
  background: linear-gradient(150deg, var(--teal-50), #d9efec);
  color: var(--teal-700);
  padding: 10px 0;
}
.card.is-past .date {
  background: #eef3f2;
  color: var(--muted);
}
.day {
  font-size: 1.5rem;
  font-weight: 800;
  line-height: 1;
}
.mon {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-top: 3px;
}

.info {
  min-width: 0;
}
.info-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.info h2 {
  font-size: 1.02rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.spec {
  color: var(--muted);
  font-size: 0.85rem;
  margin-top: 1px;
}
.meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 10px;
}
.time {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ink-2);
}
.mod {
  font-size: 0.74rem;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 999px;
}
.mod.video {
  background: var(--coral-soft);
  color: #c4503a;
}
.mod.person {
  background: var(--teal-50);
  color: var(--teal-d);
}
.loc {
  font-size: 0.82rem;
  color: var(--muted);
  margin-top: 8px;
}

/* ── Badges ── */
.badge {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  white-space: nowrap;
  flex-shrink: 0;
}
.badge.ok {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}
.badge.warn {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.badge.cancelled {
  background: rgba(212, 80, 62, 0.14);
  color: var(--danger);
}

/* ── Actions ── */
.actions {
  grid-column: 2;
  display: flex;
  gap: 8px;
  margin-top: 14px;
  flex-wrap: wrap;
}
.btn {
  border: none;
  border-radius: 10px;
  padding: 9px 16px;
  font: inherit;
  font-weight: 600;
  font-size: 0.84rem;
  cursor: pointer;
  transition: transform 0.12s, background 0.15s, border-color 0.15s;
}
.btn:active {
  transform: translateY(1px);
}
.btn.ghost {
  background: var(--white);
  border: 1px solid var(--line-2);
  color: var(--ink-2);
}
.btn.ghost:hover {
  background: var(--teal-50);
  border-color: var(--teal);
  color: var(--teal-d);
}
.btn.danger {
  background: var(--white);
  border: 1px solid rgba(212, 80, 62, 0.4);
  color: var(--danger);
}
.btn.danger:hover {
  background: rgba(212, 80, 62, 0.08);
  border-color: var(--danger);
}
.btn.link {
  background: transparent;
  color: var(--teal-d);
  padding: 9px 4px;
  text-decoration: underline;
}
.btn.link:hover {
  color: var(--teal-700);
}

/* ── Inline cancel confirm ── */
.confirm {
  grid-column: 2;
  margin-top: 14px;
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  background: rgba(212, 80, 62, 0.07);
  border: 1px solid rgba(212, 80, 62, 0.25);
  border-radius: var(--r-sm);
  padding: 12px 14px;
}
.confirm p {
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--ink-2);
  flex: 1;
  min-width: 160px;
}
.confirm-actions {
  display: flex;
  gap: 8px;
}
.btn.solid-danger {
  background: var(--danger);
  color: #fff;
}
.btn.solid-danger:hover {
  background: #c2452f;
}

/* ── Toast ── */
.toast {
