// ── Toast ──────────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2600);
}

// ── Tab switching ────────────────────────────────────────────────────────────
const tabs = document.querySelectorAll(".tab");
tabs.forEach((tab) => {
  tab.addEventListener("click", () => {
    tabs.forEach((t) => {
      const active = t === tab;
      t.classList.toggle("is-active", active);
      t.setAttribute("aria-selected", String(active));
      document.getElementById(t.getAttribute("aria-controls")).hidden = !active;
    });
  });
});

// ── Update upcoming count from live DOM state ────────────────────────────────
function refreshUpcomingCount() {
  const open = document.querySelectorAll('#panel-upcoming .card[data-state="upcoming"]').length;
  document.getElementById("count-upcoming").textContent = open;
}

// ── Card actions ─────────────────────────────────────────────────────────────
function cancelCard(card) {
  card.dataset.state = "cancelled";
  card.classList.add("is-cancelled");
  card.querySelector(".badge").className = "badge cancelled";
  card.querySelector(".badge").textContent = "Cancelled";
  card.querySelector(".confirm").remove();
  refreshUpcomingCount();
  showToast("Appointment cancelled — a confirmation has been sent.");
}

function askConfirm(card) {
  if (card.querySelector(".confirm")) return;
  const actions = card.querySelector(".actions");
  actions.remove();
  const box = document.createElement("div");
  box.className = "confirm";
  box.innerHTML =
    "<p>Cancel this appointment?</p>" +
    '<div class="confirm-actions">' +
    '<button class="btn ghost" data-action="keep">Keep it</button>' +
    '<button class="btn solid-danger" data-action="confirm">Yes, cancel</button>' +
    "</div>";
  card.appendChild(box);
}

function keepCard(card) {
  card.querySelector(".confirm").remove();
  const actions = document.createElement("div");
  actions.className = "actions";
  actions.innerHTML =
    '<button class="btn ghost" data-action="reschedule">Reschedule</button>' +
    '<button class="btn danger" data-action="cancel">Cancel</button>';
  card.appendChild(actions);
}

document.querySelector(".appts").addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action]");
  if (!btn || btn.classList.contains("tab")) return;
  const card = btn.closest(".card");
  const action = btn.dataset.action;
  if (action === "cancel") askConfirm(card);
  else if (action === "confirm") cancelCard(card);
  else if (action === "keep") keepCard(card);
  else if (action === "reschedule") showToast("Reschedule: pick a new slot from the calendar.");
  else if (action === "summary") showToast("Opening your visit summary…");
});

snippets.css:
:root {
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --sh-1: 0 1px 2px rgba(28, 24, 20, 0.05), 0 1px 0 rgba(255, 255, 255, 0.6) inset;
  --sh-2: 0 18px 44px -28px rgba(28, 24, 20, 0.4), 0 2px 8px rgba(28, 24, 20, 0.04);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background:
    radial-gradient(1200px 600px at 90% -10%, rgba(176, 141, 87, 0.08), transparent 60%),
    var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1,
h2,
h3 {
  font-family: var(--serif);
  font-weight: 600;
  margin: 0;
  letter-spacing: 0.01em;
}

.shell {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 28px 64px;
}

/* ===== Topbar ===== */
.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
  padding: 18px 0 16px;
  margin-bottom: 8px;
  background: linear-gradient(var(--bg) 70%, rgba(250, 246, 239, 0));
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 13px;
}

.brand__mark {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--white);
  background:
    radial-gradient(120% 120% at 30% 20%, #c9a667, var(--gold-d));
  box-shadow: 0 6px 18px -8px rgba(140, 109, 63, 0.7), 0 0 0 1px rgba(255, 255, 255, 0.4) inset;
  letter-spacing: 0.04em;
}

.brand__text {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.brand__name {
  font-family: var(--serif);
  font-size: 1.32rem;
  font-weight: 600;
}

.brand__sub {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--muted);
}

.topbar__actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

/* Segmented control */
.seg {
  display: inline-flex;
  padding: 4px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  box-shadow: var(--sh-1);
}

.seg__btn {
  appearance: none;
  border: 0;
  background: transparent;
  font: inherit;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--muted);
  padding: 7px 18px;
  border-radius: 999px;
  cursor: pointer;
  transition: color 0.2s, background 0.2s, box-shadow 0.2s;
}

.seg__btn:hover {
  color: var(--ink-2);
}

.seg__btn.is-active {
  color: var(--ink);
  background: linear-gradient(180deg, var(--gold-soft), var(--rose-soft));
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.7) inset, 0 2px 6px -3px rgba(140, 109, 63, 0.5);
}

.seg__btn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.btn {
  appearance: none;
  font: inherit;
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  border-radius: 999px;
  padding: 8px 16px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  transition: transform 0.15s, box-shadow 0.2s, background 0.2s, border-color 0.2s;
}

.btn:active {
  transform: translateY(1px);
}

.btn--ghost {
  background: var(--white);
  border: 1px solid var(--line);
  color: var(--ink-2);
  box-shadow: var(--sh-1);
}

.btn--ghost:hover {
  border-color: var(--gold);
  color: var(--ink);
}

.btn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

/* ===== Page head ===== */
.page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
  flex-wrap: wrap;
  margin: 22px 0 24px;
}

.eyebrow {
  margin: 0 0 4px;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--gold-d);
  font-weight: 600;
}

.page-title {
  font-size: clamp(1.9rem, 4vw, 2.6rem);
  line-height: 1.05;
}

.page-meta {
  margin: 0;
  font-size: 0.88rem;
  color: var(--muted);
}

.page-meta strong {
  color: var(--ink-2);
  text-transform: capitalize;
}

/* ===== Cards ===== */
.card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-2);
  padding: 22px;
}

.card__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 18px;
}

.card__title {
  font-size: 1.4rem;
}

.card__sub {
  margin: 2px 0 0;
  font-size: 0.8rem;
  color: var(--muted);
}

.hint {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--gold-d);
  white-space: nowrap;
}

/* ===== KPI ===== */
.kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 16px;
}

.kpi {
  padding: 20px 22px;
  position: relative;
  overflow: hidden;
}

.kpi::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: linear-gradient(var(--gold), var(--rose));
  opacity: 0.85;
}

.kpi__label {
  margin: 0 0 8px;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--muted);
  font-weight: 600;
}

.kpi__value {
  margin: 0;
  font-family: var(--serif);
  font-size: 2.1rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  line-height: 1;
}

.kpi__delta {
  margin: 12px 0 0;
  font-size: 0.78rem;
  color: var(--muted);
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 2px 8px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.72rem;
  margin-right: 4px;
}

.chip--up {
  color: var(--ok);
  background: rgba(95, 138, 107, 0.12);
}

.chip--down {
  color: var(--danger);
  background: rgba(179, 80, 62, 0.12);
}

/* ===== Grid ===== */
.grid-2 {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: 16px;
  margin-bottom: 16px;
}

.grid-2--lower {
  grid-template-columns: 1fr 1.25fr;
}

/* ===== Bar chart ===== */
.bars {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.bar-row {
  display: grid;
  grid-template-columns: 96px 1fr auto;
  align-items: center;
  gap: 12px;
}

.bar-row__name {
  font-size: 0.83rem;
  font-weight: 500;
  color: var(--ink-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bar-track {
  height: 12px;
  border-radius: 999px;
  background: var(--cream);
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 0;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--rose), var(--gold));
  transition: width 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

.bar-row:nth-child(1) .bar-fill {
  background: linear-gradient(90deg, var(--gold), var(--gold-d));
}

.bar-row__val {
  font-size: 0.82rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
  min-width: 56px;
  text-align: right;
}

/* ===== Donut / mix ===== */
.mix {
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
}

.donut {
  --c1: var(--gold);
  position: relative;
  width: 168px;
  height: 168px;
  border-radius: 50%;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  background: conic-gradient(var(--cream) 0 100%);
  transition: background 0.8s ease;
}

.donut__hole {
  width: 104px;
  height: 104px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: inset 0 0 0 1px var(--line);
  display: grid;
  place-content: center;
  text-align: center;
  gap: 2px;
}

.donut__num {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1;
}

.donut__cap {
  font-size: 0.64rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--muted);
}

.legend {
  list-style: none;
  margin: 0;
  padding: 0;
  flex: 1 1 160px;
  min-width: 160px;
  display: flex;
  flex-direction: column;
  gap: 11px;
}

.legend li {
  display: grid;
  grid-template-columns: 12px 1fr auto;
  align-items: center;
  gap: 10px;
  font-size: 0.85rem;
}

.legend .dot {
  width: 11px;
  height: 11px;
  border-radius: 3px;
}

.legend .lg-name {
  color: var(--ink-2);
}

.legend .lg-val {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}

/* ===== Performers ===== */
.performers {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
}

.performer {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 13px;
  padding: 13px 0;
  border-top: 1px solid var(--line);
}

.performer:first-child {
  border-top: 0;
}

.performer__rank {
  width: 26px;
  height: 26px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--gold-d);
  background: var(--gold-soft);
  font-variant-numeric: tabular-nums;
}

.performer:first-child .performer__rank {
  color: var(--white);
  background: linear-gradient(140deg, #c9a667, var(--gold-d));
}

.performer__name {
  font-weight: 600;
  font-size: 0.92rem;
}

.performer__role {
  display: block;
  font-size: 0.74rem;
  font-weight: 400;
  color: var(--muted);
}

.performer__amt {
  text-align: right;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.performer__amt small {
  display: block;
  font-weight: 500;
  font-size: 0.72rem;
  color: var(--ok);
}

/* ===== Table ===== */
.table-wrap {
  overflow-x: auto;
}

.txn {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.86rem;
}

.txn th {
  text-align: left;
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  font-weight: 600;
  padding: 0 0 10px;
  border-bottom: 1px solid var(--line-2);
}

.txn td {
  padding: 12px 0;
  border-bottom: 1px solid var(--line);
  vertical-align: middle;
}

.txn tr:last-child td {
  border-bottom: 0;
}

.txn .ta-r {
  text-align: right;
}

.txn .client {
  font-weight: 600;
}

.txn .svc {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.svc-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.txn .amt {
  text-align: right;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* ===== Toast ===== */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 24px);
  background: var(--ink);
  color: var(--cream);
  padding: 12px 20px;
  border-radius: 999px;
  font-size: 0.85rem;
  font-weight: 500;
  box-shadow: var(--sh-2);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s, transform 0.3s;
  z-index: 60;
}

.toast.is-on {
  opacity: 1;
  transform: translate(-50%, 0);
}

.toast::before {
  content: "✦";
  color: var(--gold);
  margin-right: 8px;
}

/* ===== Responsive ===== */
@media (max-width: 900px) {
  .kpis {
    grid-template-columns: repeat(2, 1fr);
  }
  .grid-2,
  .grid-2--lower {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .shell {
    padding: 0 16px 48px;
  }
  .topbar {
    padding-top: 14px;
  }
  .topbar__actions {
    width: 100%;
    justify-content: space-between;
  }
  .seg__btn {
    padding: 7px 13px;
    font-size: 0.8rem;
  }
  .kpis {
    grid-template-columns: 1fr;
  }
  .kpi__value {
    font-size: 1.85rem;
  }
  .bar-row {
    grid-template-columns: 80px 1fr auto;
    gap: 9px;
  }
  .mix {
    justify-content: center;
  }
  .card {
    padding: 18px;
  }
}

