:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
  --shadow-lift: 0 18px 38px rgba(12, 122, 115, 0.18);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

button {
  font: inherit;
}

:focus-visible {
  outline: 3px solid rgba(18, 156, 147, 0.45);
  outline-offset: 2px;
  border-radius: 6px;
}

/* ── Layout ── */
.page {
  max-width: 1080px;
  margin: 0 auto;
  padding: 40px 20px 48px;
  display: flex;
  flex-direction: column;
  gap: 28px;
}

/* ── Hero ── */
.hero {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.eyebrow {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--teal-d);
}
.hero h1 {
  font-size: clamp(1.9rem, 4vw, 2.6rem);
  font-weight: 800;
  letter-spacing: -0.025em;
  line-height: 1.1;
  max-width: 18ch;
}
.lede {
  font-size: 1.02rem;
  color: var(--ink-2);
  max-width: 62ch;
}

/* ── Filter chips ── */
.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 6px;
}
.chip {
  border: 1px solid var(--line-2);
  background: var(--white);
  border-radius: 999px;
  padding: 9px 16px;
  font-weight: 600;
  font-size: 0.88rem;
  color: var(--ink-2);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  box-shadow: var(--shadow-1);
  transition: background 0.16s, color 0.16s, border-color 0.16s, transform 0.12s;
}
.chip:hover {
  border-color: var(--teal);
  color: var(--teal-d);
}
.chip:active {
  transform: translateY(1px);
}
.chip.is-active {
  background: var(--teal-d);
  border-color: var(--teal-d);
  color: #fff;
}
.chip-count {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--teal-50);
  color: var(--teal-d);
  font-size: 0.72rem;
  font-weight: 700;
}
.chip.is-active .chip-count {
  background: rgba(255, 255, 255, 0.22);
  color: #fff;
}
.result-line {
  font-size: 0.85rem;
  color: var(--muted);
  font-weight: 500;
  min-height: 1.2em;
}

/* ── Grid ── */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 18px;
}

/* ── Service card ── */
.svc {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: var(--shadow-1);
  position: relative;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.svc:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lift);
  border-color: rgba(18, 156, 147, 0.35);
}
.svc.is-hidden {
  display: none;
}

.svc-tag {
  align-self: flex-start;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
}
.svc-tag.primary {
  background: var(--teal-50);
  color: var(--teal-d);
}
.svc-tag.specialist {
  background: var(--coral-soft);
  color: #c4503a;
}
.svc-tag.diagnostic {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}

.svc-icon {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: linear-gradient(150deg, var(--teal-50), #d9efec);
  font-size: 1.5rem;
  margin-top: 4px;
}

.svc h2 {
  font-size: 1.12rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-top: 2px;
}
.svc-blurb {
  font-size: 0.9rem;
  color: var(--muted);
  flex: 1;
}

.svc-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 8px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.link-more {
  border: none;
  background: transparent;
  color: var(--teal-d);
  font-weight: 600;
  font-size: 0.86rem;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 0;
  transition: gap 0.16s, color 0.16s;
}
.link-more:hover {
  color: var(--teal-700);
  gap: 10px;
}

/* ── Buttons ── */
.btn {
  border: none;
  border-radius: 10px;
  padding: 9px 18px;
  font-weight: 600;
  font-size: 0.86rem;
  cursor: pointer;
  transition: transform 0.12s, background 0.16s, box-shadow 0.16s;
}
.btn:active {
  transform: translateY(1px);
}
.btn.book {
  background: var(--teal);
  color: #fff;
  box-shadow: 0 6px 14px rgba(18, 156, 147, 0.25);
}
.btn.book:hover {
  background: var(--teal-d);
}

/* ── Empty state ── */
.empty {
  text-align: center;
  color: var(--muted);
  font-weight: 500;
  padding: 40px 0;
  font-size: 0.95rem;
}
.empty[hidden] {
  display: none;
}

/* ── CTA band ── */
.cta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 22px;
  background: linear-gradient(135deg, var(--teal-d), var(--teal-700));
  color: #fff;
  border-radius: var(--r-lg);
  padding: 32px 34px;
  box-shadow: var(--shadow-2);
}
.cta-text h2 {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.cta-text p {
  margin-top: 6px;
  color: rgba(255, 255, 255, 0.86);
  font-size: 0.95rem;
  max-width: 46ch;
}
.cta-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.btn.cta-primary {
  background: var(--white);
  color: var(--teal-d);
  padding: 12px 22px;
}
.btn.cta-primary:hover {
  background: #f0fbf9;
}
.btn.cta-secondary {
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.4);
  padding: 12px 22px;
}
.btn.cta-secondary:hover {
  background: rgba(255, 255, 255, 0.2);
}

/* ── Footer ── */
.page-foot {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px;
  color: var(--muted);
  font-size: 0.84rem;
  padding-top: 8px;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}

/* ── Responsive ── */
@media (max-width: 520px) {
  .page {
    padding: 28px 16px 40px;
    gap: 22px;
  }
  .grid {
    grid-template-columns: 1fr;
  }
  .cta {
    padding: 26px 22px;
    flex-direction: column;
    align-items: flex-start;
  }
  .cta-actions {
    width: 100%;
  }
  .cta-actions .btn {
    flex: 1;
  }
  .filters {
    overflow-x: auto;
    flex-wrap: nowrap;
    padding-bottom: 4px;
    -webkit-overflow-scrolling: touch;
  }
  .chip {
    flex: 0 0 auto;
  }
}

