  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --sh-1: 0 1px 0 rgba(255, 255, 255, 0.04) inset, 0 8px 24px rgba(0, 0, 0, 0.4);
  --sh-2: 0 1px 0 rgba(255, 255, 255, 0.06) inset, 0 20px 50px rgba(0, 0, 0, 0.55);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.page {
  max-width: 1140px;
  margin: 0 auto;
  padding: 22px 22px 64px;
}

a {
  color: inherit;
  text-decoration: none;
}

:focus-visible {
  outline: 3px solid var(--neon);
  outline-offset: 2px;
  border-radius: var(--r-sm);
}

/* ---------- Buttons ---------- */
.btn {
  font-family: inherit;
  font-weight: 800;
  font-size: 0.95rem;
  letter-spacing: 0.01em;
  border: none;
  cursor: pointer;
  border-radius: var(--r-md);
  padding: 14px 20px;
  transition: transform 0.12s ease, background 0.15s ease, box-shadow 0.15s ease,
    border-color 0.15s ease;
}
.btn:active {
  transform: translateY(1px) scale(0.99);
}
.btn-neon {
  background: var(--neon);
  color: #0d0f12;
  box-shadow: 0 8px 22px var(--neon-50);
}
.btn-neon:hover {
  background: var(--neon-d);
}
.btn-outline {
  background: transparent;
  color: var(--ink);
  border: 1.5px solid var(--line-2);
}
.btn-outline:hover {
  border-color: var(--neon);
  color: var(--neon);
}
.btn-ghost {
  background: var(--surface-2);
  color: var(--ink);
  border: 1px solid var(--line);
  padding: 10px 16px;
  font-size: 0.85rem;
}
.btn-ghost:hover {
  border-color: var(--line-2);
}
.btn-mini {
  background: var(--neon);
  color: #0d0f12;
  padding: 9px 18px;
  font-size: 0.82rem;
  border-radius: var(--r-sm);
}
.btn-mini:hover {
  background: var(--neon-d);
}

/* ---------- Masthead ---------- */
.masthead {
  display: flex;
  align-items: center;
  gap: 22px;
  padding: 6px 4px 26px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 9px;
  font-weight: 900;
}
.brand-mark {
  color: var(--neon);
  font-size: 1.1rem;
}
.brand-name {
  letter-spacing: 0.18em;
  font-size: 1.05rem;
}
.masthead-nav {
  display: flex;
  gap: 24px;
  margin-left: 18px;
  font-size: 0.9rem;
  color: var(--ink-2);
  font-weight: 600;
}
.masthead-nav a:hover {
  color: var(--neon);
}
.masthead .btn-ghost {
  margin-left: auto;
}

/* ---------- Hero ---------- */
.hero {
  text-align: center;
  padding: 30px 0 14px;
}
.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.28em;
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--neon);
  margin: 0 0 14px;
}
.hero-title {
  font-size: clamp(2.6rem, 7vw, 4.6rem);
  line-height: 0.98;
  font-weight: 900;
  letter-spacing: -0.02em;
  margin: 0 0 18px;
}
.hero-title .accent {
  color: var(--neon);
}
.hero-sub {
  max-width: 560px;
  margin: 0 auto 30px;
  color: var(--ink-2);
  font-size: 1.05rem;
}

/* ---------- Billing toggle ---------- */
.billing {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 14px;
  box-shadow: var(--sh-1);
  flex-wrap: wrap;
  justify-content: center;
}
.billing-label {
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--muted);
  transition: color 0.15s ease;
}
.billing-label.is-on {
  color: var(--ink);
}
.switch {
  position: relative;
  width: 56px;
  height: 30px;
  border-radius: 999px;
  border: none;
  cursor: pointer;
  background: var(--elevated);
  padding: 0;
  transition: background 0.18s ease;
}
.switch[aria-checked="true"] {
  background: var(--neon);
}
.switch-thumb {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--ink);
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.switch[aria-checked="true"] .switch-thumb {
  transform: translateX(26px);
  background: #0d0f12;
}
.billing-save {
  font-weight: 800;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--neon);
  background: var(--neon-50);
  padding: 5px 11px;
  border-radius: 999px;
}

/* ---------- Tiers ---------- */
.tiers {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 46px;
}
.tier {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 26px 22px 24px;
  display: flex;
  flex-direction: column;
  box-shadow: var(--sh-1);
  transition: transform 0.16s ease, border-color 0.16s ease, box-shadow 0.16s ease;
}
.tier:hover {
  transform: translateY(-4px);
  border-color: var(--line-2);
  box-shadow: var(--sh-2);
}
.tier.is-popular {
  border-color: var(--neon);
  background: linear-gradient(180deg, var(--neon-50), var(--surface) 42%);
  box-shadow: 0 0 0 1px var(--neon-d), var(--sh-2);
}
.tier-black {
  background: linear-gradient(180deg, #0a0b0d, var(--surface-2));
  border-color: var(--line-2);
}
.ribbon {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--neon);
  color: #0d0f12;
  font-size: 0.68rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 5px 14px;
  border-radius: 999px;
  white-space: nowrap;
}
.ribbon-dark {
  background: var(--orange);
  color: #0d0f12;
}
.tier-head {
  margin-bottom: 16px;
}
.tier-name {
  margin: 0;
  font-size: 1.4rem;
  font-weight: 900;
  letter-spacing: -0.01em;
}
.tier-tag {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 0.82rem;
  font-weight: 500;
}
.price {
  display: flex;
  align-items: baseline;
  gap: 2px;
  margin-bottom: 4px;
}
.price-cur {
  font-size: 1.3rem;
  font-weight: 800;
  color: var(--ink-2);
  align-self: flex-start;
  margin-top: 6px;
}
.price-amt {
  font-size: 3rem;
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1;
}
.price-per {
  color: var(--muted);
  font-weight: 700;
  font-size: 0.95rem;
}
.price-note {
  font-size: 0.78rem;
  color: var(--muted);
  margin: 0 0 18px;
  min-height: 1.1em;
}
.features {
  list-style: none;
  margin: 0 0 22px;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 11px;
  flex: 1;
}
.features li {
  position: relative;
  padding-left: 26px;
  font-size: 0.88rem;
  color: var(--ink-2);
}
.features li::before {
  position: absolute;
  left: 0;
  top: -1px;
  font-weight: 900;
  font-size: 0.9rem;
}
.features li.ok::before {
  content: "✓";
  color: var(--neon);
}
.features li.no {
  color: var(--muted);
  opacity: 0.7;
}
.features li.no::before {
  content: "✕";
  color: var(--muted);
}
.tier .btn {
  width: 100%;
}

/* ---------- Add-ons ---------- */
.addons {
  margin-top: 56px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 30px 26px;
  box-shadow: var(--sh-1);
}
.addons-head {
  margin-bottom: 22px;
}
.addons-title {
  margin: 0;
  font-size: 1.5rem;
  font-weight: 900;
  letter-spacing: -0.01em;
}
.addons-sub {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 0.9rem;
}
.addon-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}
.addon {
  display: flex;
  align-items: center;
  gap: 14px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px;
  transition: border-color 0.15s ease, transform 0.15s ease;
}
.addon:hover {
  border-color: var(--line-2);
  transform: translateY(-2px);
}
.addon-icon {
  font-size: 1.6rem;
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  background: var(--elevated);
  border-radius: var(--r-sm);
  flex-shrink: 0;
}
.addon-body {
  flex: 1;
  min-width: 0;
}
.addon-body h3 {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 800;
}
.addon-body p {
  margin: 3px 0 0;
  font-size: 0.78rem;
  color: var(--muted);
}
.addon-price {
  font-weight: 900;
  font-size: 1.15rem;
  white-space: nowrap;
}
.addon-price span {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--muted);
}

/* ---------- Section titles ---------- */
.section-title {
  font-size: clamp(1.6rem, 4vw, 2.2rem);
  font-weight: 900;
  letter-spacing: -0.02em;
  margin: 0 0 22px;
  text-align: center;
}

/* ---------- Comparison table ---------- */
.compare {
  margin-top: 64px;
}
.table-wrap {
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  background: var(--surface);
  box-shadow: var(--sh-1);
}
.cmp {
  width: 100%;
  border-collapse: collapse;
  min-width: 620px;
}
.cmp th,
.cmp td {
  padding: 15px 16px;
  text-align: center;
  font-size: 0.88rem;
  border-bottom: 1px solid var(--line);
}
.cmp thead th {
  font-size: 0.95rem;
  font-weight: 900;
  color: var(--ink);
  background: var(--surface-2);
  position: sticky;
  top: 0;
}
.cmp tbody th[scope="row"],
.cmp .feat-col {
  text-align: left;
  font-weight: 700;
  color: var(--ink-2);
}
.cmp td {
  color: var(--ink-2);
  font-weight: 600;
}
.cmp .col-pop {
  background: var(--neon-50);
}
.cmp thead .col-pop {
  color: var(--neon);
}
.cmp .check {
  color: var(--neon);
  font-weight: 900;
}
.cmp .x {
  color: var(--muted);
}
.cmp tbody tr:last-child th,
.cmp tbody tr:last-child td {
  border-bottom: none;
}

/* ---------- FAQ accordion ---------- */
.faq {
  margin-top: 64px;
  max-width: 760px;
  margin-left: auto;
  margin-right: auto;
}
.accordion {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.acc-item {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
  transition: border-color 0.15s ease;
}
.acc-item.is-open {
  border-color: var(--line-2);
}
.acc-trigger {
  width: 100%;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--ink);
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  text-align: left;
  padding: 18px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}
.acc-trigger:hover {
  color: var(--neon);
}
.acc-icon {
  font-size: 1.4rem;
  font-weight: 400;
  color: var(--neon);
  transition: transform 0.2s ease;
  flex-shrink: 0;
}
.acc-item.is-open .acc-icon {
  transform: rotate(45deg);
}
.acc-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.28s ease;
}
.acc-panel p {
  margin: 0;
  padding: 0 20px 20px;
  color: var(--ink-2);
  font-size: 0.92rem;
}

/* ---------- Footer ---------- */
.foot {
  margin-top: 64px;
  text-align: center;
  color: var(--muted);
  font-size: 0.8rem;
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%) translateY(24px);
  background: var(--neon);
  color: #0d0f12;
  font-weight: 800;
  font-size: 0.9rem;
  padding: 13px 22px;
  border-radius: 999px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.55);
  opacity: 0;
  pointer-events: none;
  transition: transform 0.28s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.22s ease;
  z-index: 50;
  max-width: calc(100vw - 32px);
  text-align: center;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ---------- Responsive ---------- */
@media (max-width: 940px) {
  .tiers {
    grid-template-columns: repeat(2, 1fr);
  }
  .addon-row {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .page {
    padding: 16px 14px 48px;
  }
  .masthead {
    flex-wrap: wrap;
    gap: 12px;
  }
  .masthead-nav {
    order: 3;
    margin-left: 0;
    width: 100%;
    justify-content: space-between;
    gap: 10px;
  }
  .masthead .btn-ghost {
    margin-left: 0;
  }
  .tiers {
    grid-template-columns: 1fr;
  }
  .billing {
    gap: 10px;
  }
  .billing-save {
    width: 100%;
    text-align: center;
    order: 4;
  }
  .addon {
    flex-wrap: wrap;
  }
  .addon-body {
    flex-basis: calc(100% - 62px);
  }
  .addon-price {
    margin-left: 62px;
  }
  .addon .btn-mini {
    margin-left: auto;
  }
}

