// ── Toast ────────────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2200);
}

// ── Sticky nav + CTA band ────────────────────────────────────────────────────
const siteNav = document.getElementById("siteNav");
const stickyCta = document.getElementById("stickyCta");
const heroEl = document.getElementById("home");

function onScroll() {
  const heroBottom = heroEl.getBoundingClientRect().bottom;
  siteNav.classList.toggle("scrolled", window.scrollY > 60);
  // Show the sticky CTA band once the hero is fully scrolled past
  const show = heroBottom < 0;
  stickyCta.classList.toggle("visible", show);
  stickyCta.setAttribute("aria-hidden", String(!show));
}
window.addEventListener("scroll", onScroll, { passive: true });
onScroll(); // run once on load

// ── Nights calculator helper ─────────────────────────────────────────────────
function calcNights(inVal, outVal) {
  if (!inVal || !outVal) return 0;
  const nights = Math.round((new Date(outVal) - new Date(inVal)) / 864e5);
  return nights > 0 ? nights : 0;
}
function fmtNights(n) {
  return n === 1 ? "1 night" : `${n} nights`;
}

// ── Hero widget ──────────────────────────────────────────────────────────────
const wCheckIn = document.getElementById("wCheckIn");
const wCheckOut = document.getElementById("wCheckOut");
const widgetNights = document.getElementById("widgetNights");

// Seed with defaults (9–12 Jun 2026)
wCheckIn.value = "2026-06-09";
wCheckOut.value = "2026-06-12";

function updateWidgetLabel() {
  const n = calcNights(wCheckIn.value, wCheckOut.value);
  widgetNights.textContent = n > 0 ? `${fmtNights(n)} · ` : "";
}
updateWidgetLabel();

wCheckIn.addEventListener("change", () => {
  if (wCheckOut.value && wCheckOut.value <= wCheckIn.value) {
    const d = new Date(wCheckIn.value);
    d.setDate(d.getDate() + 1);
    wCheckOut.value = d.toISOString().slice(0, 10);
  }
  updateWidgetLabel();
});
wCheckOut.addEventListener("change", updateWidgetLabel);

document.getElementById("widgetSearch").addEventListener("click", () => {
  const n = calcNights(wCheckIn.value, wCheckOut.value);
  if (n <= 0) {
    showToast("Please select valid check-in and check-out dates.");
    return;
  }
  showToast(`Checking availability · ${fmtNights(n)} from ${wCheckIn.value}`);
});

// ── Room cards ───────────────────────────────────────────────────────────────
document.querySelectorAll(".room-btn").forEach((btn) => {
  btn.addEventListener("click", () => {
    const room = btn.dataset.room;
    showToast(`Opening reservation for "${room}" →`);
  });
});

// ── Reserve form ─────────────────────────────────────────────────────────────
const rIn = document.getElementById("rIn");
const rOut = document.getElementById("rOut");
const rName = document.getElementById("rName");
const rEmail = document.getElementById("rEmail");
const nightsCalc = document.getElementById("nightsCalc");

// Seed defaults
rIn.value = "2026-06-09";
rOut.value = "2026-06-12";

// Rate map per room type
const RATES = { "": 180, garden: 180, ocean: 340, cliff: 680 };

function updateNightsCalc() {
  const n = calcNights(rIn.value, rOut.value);
  const roomType = document.getElementById("rRoom").value;
  const rate = RATES[roomType] || 180;
  if (n > 0) {
    const total = n * rate;
    nightsCalc.innerHTML = `<strong>${fmtNights(n)}</strong> · from €${total.toLocaleString()} (direct −10%)`;
  } else {
    nightsCalc.textContent = "";
  }
}
updateNightsCalc();

rIn.addEventListener("change", () => {
  if (rOut.value && rOut.value <= rIn.value) {
    const d = new Date(rIn.value);
    d.setDate(d.getDate() + 1);
    rOut.value = d.toISOString().slice(0, 10);
  }
  updateNightsCalc();
});
rOut.addEventListener("change", updateNightsCalc);
document.getElementById("rRoom").addEventListener("change", updateNightsCalc);

document.getElementById("reserveForm").addEventListener("submit", (e) => {
  e.preventDefault();
  let valid = true;

  // Clear errors
  [rName, rEmail, rIn, rOut].forEach((el) => el.classList.remove("error"));

  if (!rName.value.trim()) {
    rName.classList.add("error");
    valid = false;
  }
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRe.test(rEmail.value.trim())) {
    rEmail.classList.add("error");
    valid = false;
  }
  if (calcNights(rIn.value, rOut.value) <= 0) {
    rIn.classList.add("error");
    rOut.classList.add("error");
    valid = false;
  }

  if (!valid) {
    showToast("Please complete all required fields.");
    return;
  }

  const firstName = rName.value.trim().split(" ")[0];
  const n = calcNights(rIn.value, rOut.value);
  showToast(`Booking request sent! See you soon, ${firstName} · ${fmtNights(n)}`);
  document.getElementById("reserveForm").reset();
  nightsCalc.textContent = "";
});

// ── Smooth scroll ────────────────────────────────────────────────────────────
document.querySelectorAll('a[href^="#"]').forEach((a) => {
  a.addEventListener("click", (e) => {
    const target = document.querySelector(a.getAttribute("href"));
    if (target) {
      e.preventDefault();
      target.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  });
});

snippets.css:
:root {
  --cream: #f4efe4;
  --paper: #faf7f0;
  --white: #ffffff;
  --newsprint: #efe9da;
  --ink: #16130f;
  --ink-2: #2b2620;
  --ink-3: #4a443b;
  --muted: #7a7164;
  --red: #b4291f;
  --red-d: #8f1f17;
  --red-50: #f3dcd9;
  --rule: rgba(22, 19, 15, 0.16);
  --rule-2: rgba(22, 19, 15, 0.30);
  --rule-hair: rgba(22, 19, 15, 0.10);
  --ok: #2f7d4f;
  --warn: #b67a18;
  --danger: #b4291f;
  --r-sm: 4px;
  --r-md: 8px;
  --r-lg: 12px;

  --serif: "Playfair Display", "Times New Roman", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --measure: 38rem;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--cream);
  color: var(--ink);
  font-family: var(--sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1, h2, h3 { margin: 0; }
p { margin: 0; }
a { color: inherit; }

/* ---------- Reading progress ---------- */
.progress {
  position: fixed;
  inset: 0 0 auto 0;
  height: 3px;
  background: transparent;
  z-index: 60;
}
.progress__bar {
  display: block;
  height: 100%;
  width: 0%;
  background: var(--red);
  transition: width 0.08s linear;
}

/* ---------- Slim top bar ---------- */
.topbar {
  position: fixed;
  top: 3px;
  left: 0;
  right: 0;
  z-index: 50;
  background: rgba(244, 239, 228, 0.86);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid transparent;
  transform: translateY(-110%);
  transition: transform 0.35s cubic-bezier(0.2, 0.7, 0.2, 1), border-color 0.35s;
}
.topbar.is-visible {
  transform: translateY(0);
  border-bottom-color: var(--rule);
}
.topbar__inner {
  max-width: 1180px;
  margin: 0 auto;
  padding: 0.6rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 0.6rem;
}
.topbar__brand {
  font-family: var(--serif);
  font-weight: 800;
  font-size: 1.05rem;
  letter-spacing: 0.01em;
  text-decoration: none;
  color: var(--ink);
}
.topbar__sep { color: var(--rule-2); }
.topbar__kicker {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-weight: 600;
  color: var(--muted);
}
.topbar__share {
  margin-left: auto;
  font-family: var(--sans);
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-weight: 600;
  color: var(--red);
  background: none;
  border: 1px solid var(--rule);
  border-radius: var(--r-sm);
  padding: 0.4rem 0.8rem;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s;
}
.topbar__share:hover { background: var(--red-50); border-color: var(--red); }
.topbar__share:focus-visible { outline: 2px solid var(--red); outline-offset: 2px; }

/* ---------- Cover ---------- */
.cover {
  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  color: var(--paper);
}
.cover__art {
  position: absolute;
  inset: -12% 0 -12% 0;
  background:
    radial-gradient(120% 90% at 78% 18%, rgba(217, 142, 74, 0.55), transparent 55%),
    radial-gradient(90% 70% at 18% 8%, rgba(180, 41, 31, 0.30), transparent 60%),
    radial-gradient(140% 120% at 50% 120%, rgba(8, 9, 14, 0.92), transparent 60%),
    linear-gradient(180deg, #1a1d2a 0%, #20202b 30%, #15110d 78%, #0c0a08 100%);
  will-change: transform;
}
.cover__grain {
  position: absolute;
  inset: 0;
  background-image:
    repeating-linear-gradient(115deg, rgba(255, 220, 170, 0.05) 0 2px, transparent 2px 5px),
    radial-gradient(2px 2px at 60% 30%, rgba(255, 200, 130, 0.5), transparent 60%),
    radial-gradient(1.5px 1.5px at 72% 24%, rgba(255, 220, 160, 0.45), transparent 60%),
    radial-gradient(2px 2px at 66% 40%, rgba(255, 190, 120, 0.35), transparent 60%);
  opacity: 0.6;
  mix-blend-mode: screen;
}
.cover__scrim {
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgba(8, 7, 6, 0.78) 0%, rgba(8, 7, 6, 0.25) 45%, transparent 70%);
}
.cover__inner {
  position: relative;
  max-width: 1180px;
  width: 100%;
  margin: 0 auto;
  padding: 0 1.5rem 5rem;
}
.cover__kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.24em;
  font-weight: 600;
  color: #f0c9a0;
  margin-bottom: 1.1rem;
  display: inline-block;
  border-bottom: 2px solid var(--red);
  padding-bottom: 0.35rem;
}
.cover__title {
  font-family: var(--serif);
  font-weight: 900;
  font-size: clamp(2.6rem, 8vw, 6rem);
  line-height: 0.98;
  letter-spacing: -0.015em;
  max-width: 16ch;
  margin-bottom: 1.4rem;
  text-shadow: 0 2px 30px rgba(0, 0, 0, 0.4);
}
.cover__dek {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: clamp(1.05rem, 2.4vw, 1.5rem);
  line-height: 1.45;
  max-width: 46ch;
  color: #ece3d4;
  margin-bottom: 1.8rem;
}
.cover__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.55rem;
  font-size: 0.82rem;
  letter-spacing: 0.02em;
  color: #d8cdba;
}
.cover__byline strong { color: var(--paper); font-weight: 600; }
.cover__dot { color: rgba(255, 255, 255, 0.4); }
.cover__scroll {
  margin-top: 2.6rem;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: #c9bda9;
  animation: bob 2.4s ease-in-out infinite;
}
@keyframes bob {
  0%, 100% { transform: translateY(0); opacity: 0.7; }
  50% { transform: translateY(5px); opacity: 1; }
}

/* ---------- Shell layout ---------- */
.shell {
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 1.5rem;
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 3.5rem;
  align-items: start;
}

/* ---------- Chapter rail ---------- */
.rail {
  position: sticky;
  top: 5.5rem;
  padding-top: 4rem;
}
.rail__label {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-weight: 700;
  color: var(--muted);
  padding-bottom: 0.7rem;
  border-bottom: 1px solid var(--rule);
  margin-bottom: 0.4rem;
}
.rail__nav { display: flex; flex-direction: column; }
.rail__link {
  display: flex;
  align-items: baseline;
  gap: 0.55rem;
  padding: 0.6rem 0;
  font-size: 0.86rem;
  font-weight: 500;
  color: var(--ink-3);
  text-decoration: none;
  border-bottom: 1px solid var(--rule-hair);
  transition: color 0.2s, padding-left 0.2s;
}
.rail__num {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 0.78rem;
  color: var(--muted);
  transition: color 0.2s;
}
.rail__link:hover { color: var(--ink); padding-left: 0.25rem; }
.rail__link.is-active {
  color: var(--red);
  font-weight: 600;
  padding-left: 0.25rem;
}
.rail__link.is-active .rail__num { color: var(--red); }
.rail__link:focus-visible { outline: 2px solid var(--red); outline-offset: 2px; }

/* ---------- Article ---------- */
.article {
  padding: 4rem 0 5rem;
  max-width: 44rem;
}
.dateline {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 0.82rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--ink-2);
  margin-bottom: 2rem;
}

.chapter { padding-top: 1rem; }
.chapter + .chapter { padding-top: 2rem; }
.chapter__head {
  margin-bottom: 1.6rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--rule);
}
.chapter:first-of-type .chapter__head { border-top: none; padding-top: 0; }
.chapter__kicker {
  display: block;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-weight: 600;
  color: var(--red);
  margin-bottom: 0.6rem;
}
.chapter__title {
  font-family: var(--serif);
  font-weight: 800;
  font-size: clamp(1.7rem, 4vw, 2.5rem);
  line-height: 1.05;
  letter-spacing: -0.01em;
}

.article p {
  font-size: 1.12rem;
  line-height: 1.74;
  color: var(--ink-2);
  margin-bottom: 1.5rem;
  text-align: justify;
  hyphens: auto;
}
.article .lead {
  font-size: 1.18rem;
}
.lead::first-letter {
  font-family: var(--serif);
  font-weight: 800;
  font-size: 4.4rem;
  line-height: 0.8;
  float: left;
  margin: 0.42rem 0.7rem 0 0;
  color: var(--ink);
}

.endmark {
  font-family: var(--serif);
  font-style: italic;
  color: var(--ink-3);
}
.endmark__sq {
  display: inline-block;
  width: 0.6rem;
  height: 0.6rem;
  background: var(--red);
  margin-left: 0.5rem;
  vertical-align: baseline;
  transform: translateY(1px);
}

/* ---------- Figures ---------- */
.fig { margin: 2.5rem 0; }
.fig__img {
  aspect-ratio: 16 / 10;
  border-radius: var(--r-sm);
  background-size: cover;
  background-position: center;
  position: relative;
  overflow: hidden;
}
.fig__img::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.04) 0 1px, transparent 1px 3px);
  mix-blend-mode: multiply;
  opacity: 0.5;
}
.fig--wide { margin: 3rem -2rem; }
.fig--wide .fig__img { aspect-ratio: 16 / 9; }

.fig__img--lamp {
  background:
    radial-gradient(40% 55% at 64% 34%, rgba(255, 196, 110, 0.85), rgba(255, 150, 60, 0.2) 40%, transparent 62%),
    radial-gradient(90% 80% at 50% 110%, rgba(10, 12, 18, 0.95), transparent 65%),
    linear-gradient(180deg, #232634 0%, #2a2620 55%, #120f0c 100%);
}
.fig__img--harbour {
  background:
    radial-gradient(80% 60% at 30% 25%, rgba(140, 165, 185, 0.55), transparent 60%),
    linear-gradient(180deg, #5b6b78 0%, #45525d 38%, #2e3940 70%, #1d2429 100%);
}
.fig__img--pole {
  background:
    linear-gradient(105deg, rgba(214, 168, 92, 0.65) 0%, transparent 55%),
    radial-gradient(70% 90% at 50% 50%, rgba(70, 58, 40, 0.4), transparent 70%),
    linear-gradient(180deg, #3a3327 0%, #241f17 60%, #14110c 100%);
}
.fig__img--meeting {
  background:
    radial-gradient(50% 60% at 38% 42%, rgba(232, 156, 80, 0.7), rgba(176, 70, 30, 0.25) 45%, transparent 68%),
    radial-gradient(90% 90% at 70% 100%, rgba(12, 9, 7, 0.9), transparent 60%),
    linear-gradient(180deg, #3a2a1d 0%, #2a1d13 55%, #15100b 100%);
}
.fig__cap {
  margin-top: 0.7rem;
  padding-left: 0.9rem;
  border-left: 2px solid var(--red);
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}
.fig--wide .fig__cap { margin-left: 2rem; }
.fig__cap-text {
  font-family: var(--serif);
  font-style: italic;
  font-size: 0.95rem;
  line-height: 1.4;
  color: var(--ink-3);
}
.fig__credit {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  font-weight: 500;
}

.grid2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
  margin: 2.5rem 0;
}
.grid2 .fig { margin: 0; }
.grid2 .fig__img { aspect-ratio: 4 / 5; }

/* ---------- Pull quote break (full bleed) ---------- */
.pullbreak {
  position: relative;
  margin: 4rem calc(50% - 50vw);
  width: 100vw;
  padding: 5rem 1.5rem;
  text-align: center;
  color: var(--paper);
  overflow: hidden;
  background:
    radial-gradient(80% 120% at 80% 20%, rgba(180, 41, 31, 0.35), transparent 55%),
    linear-gradient(135deg, #1c1814 0%, #241d16 50%, #14100c 100%);
}
.pullbreak__quote {
  position: relative;
  font-family: var(--serif);
  font-weight: 600;
  font-style: italic;
  font-size: clamp(1.5rem, 4.2vw, 2.8rem);
  line-height: 1.28;
  max-width: 22ch;
  margin: 0 auto;
  letter-spacing: -0.01em;
}
.pullbreak__attr {
  position: relative;
  margin-top: 1.6rem;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-weight: 600;
  color: #e0a784;
}

/* ---------- Parallax scene ---------- */
.scene {
  position: relative;
  margin: 4rem calc(50% - 50vw);
  width: 100vw;
  min-height: 78vh;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  background:
    radial-gradient(28% 40% at 22% 30%, rgba(255, 196, 110, 0.9), transparent 55%),
    radial-gradient(24% 36% at 50% 22%, rgba(255, 184, 96, 0.7), transparent 55%),
    radial-gradient(26% 40% at 78% 34%, rgba(255, 200, 120, 0.8), transparent 55%),
    radial-gradient(120% 100% at 50% 120%, rgba(6, 8, 12, 0.95), transparent 60%),
    linear-gradient(180deg, #1a1d2b 0%, #241d15 55%, #0c0a08 100%);
  background-size: cover;
  background-attachment: fixed;
}
.scene__overlay {
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 1.5rem 4rem;
  width: 100%;
}
.scene__caption {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: clamp(1.1rem, 2.6vw, 1.7rem);
  line-height: 1.4;
  color: #f1e7d6;
  max-width: 40ch;
  text-shadow: 0 2px 24px rgba(0, 0, 0, 0.5);
}

/* ---------- Colophon ---------- */
.colophon { margin-top: 4rem; }
.colophon__rule {
  height: 0;
  border-top: 3px double var(--rule-2);
  margin-bottom: 1.6rem;
}
.colophon__line {
  font-size: 0.95rem !important;
  line-height: 1.6 !important;
  color: var(--ink-3) !important;
  text-align: left !important;
  margin-bottom: 0.8rem !important;
}
.colophon__line strong { color: var(--ink); }
.colophon__meta {
  font-size: 0.74rem !important;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted) !important;
  text-align: left !important;
  margin-bottom: 1.6rem !important;
}
.colophon__actions { display: flex; gap: 0.8rem; flex-wrap: wrap; }

.btn {
  font-family: var(--sans);
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-weight: 600;
  padding: 0.7rem 1.3rem;
  border-radius: var(--r-sm);
  border: 1px solid var(--ink);
  background: var(--ink);
  color: var(--paper);
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
}
.btn:hover { background: var(--red); border-color: var(--red); }
.btn:focus-visible { outline: 2px solid var(--red); outline-offset: 2px; }
.btn--ghost { background: none; color: var(--ink); }
.btn--ghost:hover { background: var(--ink); color: var(--paper); border-color: var(--ink); }

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 2rem;
  transform: translate(-50%, 1.5rem);
  background: var(--ink);
  color: var(--paper);
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.01em;
  padding: 0.8rem 1.3rem;
  border-radius: var(--r-md);
  border-left: 3px solid var(--red);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.25);
  opacity: 0;
  pointer-events: none;
  z-index: 70;
  transition: opacity 0.3s, transform 0.3s;
}
.toast.is-show { opacity: 1; transform: translate(-50%, 0); }

/* ---------- Reveal ---------- */
[data-reveal] {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 0.7s ease, transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
}
[data-reveal].is-in { opacity: 1; transform: none; }

/* ---------- Responsive ---------- */
@media (max-width: 980px) {
  .shell { grid-template-columns: 1fr; gap: 0; }
  .rail {
    position: static;
    padding-top: 2.5rem;
    margin-bottom: 1rem;
  }
  .rail__nav { flex-flow: row wrap; gap: 0.4rem; }
  .rail__link { border: 1px solid var(--rule); border-radius: 999px; padding: 0.4rem 0.85rem; }
  .rail__link.is-active { background: var(--red-50); border-color: var(--red); padding-left: 0.85rem; }
  .article { padding-top: 1.5rem; max-width: none; }
  .fig--wide { margin: 2.5rem 0; }
  .fig--wide .fig__cap { margin-left: 0; }
}

@media (max-width: 720px) {
  .cover__inner { padding-bottom: 3rem; }
  .grid2 { grid-template-columns: 1fr; }
  .scene { background-attachment: scroll; min-height: 60vh; }
  .article p { text-align: left; }
}

@media (max-width: 380px) {
  .shell { padding: 0 1.1rem; }
  .cover__inner { padding-left: 1.1rem; padding-right: 1.1rem; }
  .lead::first-letter { font-size: 3.4rem; }
  .article p { font-size: 1.05rem; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .cover__scroll { animation: none; }
  [data-reveal] { transition: none; opacity: 1; transform: none; }
  .scene { background-attachment: scroll; }
}

