/* ── Boutique palette — charcoal · brass · ivory ─────────────────────────── */
:root {
  --charcoal: #1c1c1e;
  --charcoal-2: #2e2e30;
  --charcoal-3: #424244;
  --brass: #b08d57;
  --brass-light: #cba878;
  --brass-d: #8a6d3b;
  --ivory: #f8f5ef;
  --ivory-2: #ede9e0;
  --ivory-3: #e2ddd3;
  --stone: #9a958e;
  --ink: #1c1c1e;
  --line: rgba(28, 28, 30, 0.1);
  --line-strong: rgba(28, 28, 30, 0.2);
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --r-sm: 4px;
  --r-md: 8px;
  --shadow-soft: 0 4px 24px rgba(28, 28, 30, 0.08);
  --shadow-deep: 0 16px 48px rgba(28, 28, 30, 0.18);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html {
  scroll-behavior: smooth;
}
body {
  font-family: var(--font-body);
  background: var(--ivory);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  font-weight: 400;
  line-height: 1.65;
}
img {
  display: block;
  max-width: 100%;
}
a {
  color: inherit;
  text-decoration: none;
}

/* ── Typography helpers ── */
.eyebrow {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--brass);
  font-weight: 600;
  margin-bottom: 10px;
}
h1,
h2,
h3 {
  font-family: var(--font-display);
  font-weight: 600;
  line-height: 1.18;
  letter-spacing: -0.01em;
}
em {
  font-style: italic;
}
p + p {
  margin-top: 1em;
}

/* ── Section base ── */
.section {
  padding: 96px 7vw;
}
.section-header {
  max-width: 560px;
  margin-bottom: 56px;
}
.section-header h2 {
  font-size: clamp(2.2rem, 4vw, 3.2rem);
  margin-top: 8px;
}
.section-header.centered {
  max-width: 100%;
  text-align: center;
  margin-left: auto;
  margin-right: auto;
}

/* ── Nav ── */
.site-nav {
  position: fixed;
  top: 0;
  inset-inline: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px 7vw;
  transition: background 0.3s, padding 0.3s, box-shadow 0.3s;
}
.site-nav.scrolled {
  background: var(--charcoal);
  padding: 14px 7vw;
  box-shadow: var(--shadow-deep);
}
.nav-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--ivory);
}
.nav-mark {
  width: 36px;
  height: 36px;
  border-radius: var(--r-sm);
  background: var(--brass);
  color: var(--charcoal);
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.9rem;
  letter-spacing: 0.04em;
}
.nav-name {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}
.nav-links {
  list-style: none;
  display: flex;
  gap: 32px;
}
.nav-links a {
  color: rgba(248, 245, 239, 0.82);
  font-size: 0.84rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  transition: color 0.2s;
}
.nav-links a:hover {
  color: var(--ivory);
}
.nav-cta {
  background: var(--brass);
  color: var(--charcoal);
  font-size: 0.82rem;
  font-weight: 600;
  padding: 10px 20px;
  border-radius: var(--r-sm);
  letter-spacing: 0.04em;
  transition: background 0.2s;
}
.nav-cta:hover {
  background: var(--brass-light);
}

/* ── Hero ── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: 0 7vw;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    var(--charcoal) 0%,
    var(--charcoal-2) 40%,
    #3b3328 70%,
    #2a2118 100%
  );
  z-index: 0;
}
.hero-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    ellipse 80% 60% at 70% 40%,
    rgba(176, 141, 87, 0.18) 0%,
    transparent 70%
  );
}
.hero-inner {
  position: relative;
  z-index: 1;
  max-width: 640px;
  padding-top: 80px;
}
.hero .eyebrow {
  color: var(--brass-light);
}
.hero-title {
  font-size: clamp(3rem, 7vw, 5.5rem);
  color: var(--ivory);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.08;
  margin: 12px 0 22px;
}
.hero-title em {
  color: var(--brass-light);
}
.hero-sub {
  color: rgba(248, 245, 239, 0.7);
  font-size: 1.05rem;
  font-weight: 300;
  max-width: 400px;
  margin-bottom: 40px;
  line-height: 1.7;
}

/* ── Reservation widget ── */
.widget {
  display: flex;
  align-items: stretch;
  background: var(--ivory);
  border-radius: var(--r-md);
  overflow: hidden;
  box-shadow: var(--shadow-deep);
  max-width: 680px;
}
.widget-field {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 16px 18px;
  min-width: 0;
}
.widget-field label {
  font-size: 0.64rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--stone);
  font-weight: 600;
  margin-bottom: 5px;
}
.widget-field input,
.widget-field select {
  border: none;
  outline: none;
  background: transparent;
  font-family: var(--font-body);
  font-size: 0.9rem;
  color: var(--ink);
  width: 100%;
  cursor: pointer;
}
.widget-divider {
  width: 1px;
  background: var(--line);
  align-self: stretch;
  margin: 10px 0;
}
.widget-btn {
  background: var(--charcoal);
  color: var(--ivory);
  border: none;
  font-family: var(--font-body);
  font-size: 0.84rem;
  font-weight: 600;
  padding: 0 24px;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.2s;
  letter-spacing: 0.02em;
}
.widget-btn:hover {
  background: var(--brass-d);
}

/* ── Rooms ── */
.rooms {
  background: var(--ivory);
}
.room-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
.room-card {
  background: var(--ivory-2);
  border-radius: var(--r-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow 0.25s, transform 0.25s;
}
.room-card:hover {
  box-shadow: var(--shadow-deep);
  transform: translateY(-4px);
}
.room-card.featured {
  border: 2px solid var(--brass);
}
.room-img {
  height: 220px;
  flex-shrink: 0;
}
.room-img-1 {
  background: linear-gradient(145deg, #2e2b27 0%, #3f3829 50%, #524a38 100%);
}
.room-img-2 {
  background: linear-gradient(145deg, #1c1a16 0%, #342f24 40%, #4a4232 80%, #5c5340 100%);
}
.room-img-3 {
  background: linear-gradient(145deg, #2a2820 0%, #393629 50%, #504a38 85%, #c8b98a 100%);
}
.room-body {
  padding: 22px 20px 24px;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.room-cat {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--brass);
  font-weight: 600;
}
.room-card h3 {
  font-size: 1.45rem;
  font-weight: 600;
  margin-top: 2px;
}
.room-desc {
  font-size: 0.86rem;
  color: var(--stone);
  line-height: 1.6;
  flex: 1;
}
.room-meta {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-top: 8px;
  font-size: 0.8rem;
  color: var(--stone);
}
.room-rate {
  font-weight: 600;
  color: var(--charcoal-3);
  font-family: var(--font-display);
  font-size: 0.96rem;
}
.room-btn {
  background: var(--charcoal);
  color: var(--ivory);
  border: none;
  font-family: var(--font-body);
  font-size: 0.82rem;
  font-weight: 600;
  padding: 11px 16px;
  border-radius: var(--r-sm);
  cursor: pointer;
  margin-top: 12px;
  transition: background 0.2s;
  letter-spacing: 0.02em;
}
.room-btn:hover {
  background: var(--brass-d);
}

/* ── Story ── */
.story {
  background: var(--charcoal);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  align-items: center;
}
.story-img {
  height: 560px;
  border-radius: var(--r-md);
  background: linear-gradient(160deg, #3a3420 0%, #2b2618 40%, #1c1a14 70%, #4a4230 100%);
  position: relative;
  overflow: hidden;
}
.story-img::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    ellipse 60% 80% at 30% 60%,
    rgba(176, 141, 87, 0.25) 0%,
    transparent 70%
  );
}
.story-text {
  color: var(--ivory);
}
.story-text .eyebrow {
  color: var(--brass-light);
}
.story-text h2 {
  font-size: clamp(2rem, 3.5vw, 2.8rem);
  margin-bottom: 24px;
  line-height: 1.2;
}
.story-text h2 em {
  color: var(--brass-light);
}
.story-text p {
  font-size: 0.95rem;
  color: rgba(248, 245, 239, 0.72);
  line-height: 1.75;
}
.link-underline {
  display: inline-block;
  margin-top: 24px;
  color: var(--brass-light);
  font-size: 0.86rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  border-bottom: 1px solid var(--brass);
  padding-bottom: 2px;
  transition: color 0.2s, border-color 0.2s;
}
.link-underline:hover {
  color: var(--ivory);
  border-color: var(--ivory);
}

/* ── Visit ── */
.visit {
  background: var(--ivory-2);
}
.visit-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 56px;
  align-items: start;
}
.visit-info {
  display: flex;
  flex-direction: column;
  gap: 40px;
}
.info-block h3 {
  font-size: 1.15rem;
  font-weight: 600;
  font-family: var(--font-display);
  margin-bottom: 14px;
  color: var(--charcoal);
}
.info-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.info-list li {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 0.88rem;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
  gap: 16px;
}
.info-list li span {
  color: var(--stone);
  flex-shrink: 0;
}
.info-list li strong {
  color: var(--charcoal);
  font-weight: 600;
  text-align: right;
}
.visit-map {
  height: 380px;
}
.map-placeholder {
  height: 100%;
  background: linear-gradient(145deg, #d9d4c8 0%, #e5e0d5 40%, #ccc8be 100%);
  border-radius: var(--r-md);
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  overflow: hidden;
}
.map-placeholder::before {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
      0deg,
      rgba(0, 0, 0, 0.04) 0px,
      transparent 1px,
      transparent 40px,
      rgba(0, 0, 0, 0.04) 40px
    ),
    repeating-linear-gradient(
      90deg,
      rgba(0, 0, 0, 0.04) 0px,
      transparent 1px,
      transparent 40px,
      rgba(0, 0, 0, 0.04) 40px
    );
}
.map-pin {
  width: 20px;
  height: 20px;
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  background: var(--brass);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
  z-index: 1;
}
.map-placeholder p {
  font-size: 0.82rem;
  color: var(--charcoal);
  font-weight: 500;
  text-align: center;
  line-height: 1.5;
  z-index: 1;
}

/* ── Reserve ── */
.reserve {
  background: var(--ivory);
}
.reserve-inner {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 80px;
  align-items: start;
}
.reserve-text {
  position: sticky;
  top: 100px;
}
.reserve-text h2 {
  font-size: clamp(2rem, 3.5vw, 2.8rem);
  margin: 8px 0 16px;
}
.reserve-text p {
  font-size: 0.9rem;
  color: var(--stone);
  line-height: 1.7;
}
.reserve-form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.form-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.form-field.narrow {
  max-width: 120px;
}
.form-field.full {
  grid-column: 1 / -1;
}
.form-field label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--stone);
  font-weight: 600;
}
.form-field input,
.form-field select,
.form-field textarea {
  border: 1px solid var(--line-strong);
  border-radius: var(--r-sm);
  padding: 11px 14px;
  font-family: var(--font-body);
  font-size: 0.9rem;
  color: var(--ink);
  background: var(--ivory);
  outline: none;
  transition: border-color 0.2s;
  resize: vertical;
}
.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--brass);
}
.form-field input.error,
.form-field select.error {
  border-color: #b34232;
}
.form-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}
.nights-calc {
  font-size: 0.82rem;
  color: var(--stone);
  font-weight: 500;
}
.nights-calc strong {
  color: var(--charcoal);
}
.submit-btn {
  background: var(--charcoal);
  color: var(--ivory);
  border: none;
  font-family: var(--font-body);
  font-size: 0.88rem;
  font-weight: 600;
  padding: 13px 28px;
  border-radius: var(--r-sm);
  cursor: pointer;
  letter-spacing: 0.03em;
  transition: background 0.2s;
}
.submit-btn:hover {
  background: var(--brass-d);
}

/* ── Footer ── */
.site-footer {
  background: var(--charcoal);
  color: rgba(248, 245, 239, 0.55);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 22px 7vw;
  font-size: 0.78rem;
  letter-spacing: 0.04em;
}
.footer-brand {
  font-family: var(--font-display);
  font-size: 0.95rem;
  color: var(--ivory);
  font-weight: 600;
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--charcoal);
  color: var(--ivory);
  padding: 12px 24px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: var(--shadow-deep);
  white-space: nowrap;
  z-index: 999;
  border-top: 2px solid var(--brass);
}

/* ── Responsive ── */
@media (max-width: 1100px) {
  .reserve-inner {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .reserve-text {
    position: static;
  }
  .story {
    grid-template-columns: 1fr;
    gap: 48px;
    padding: 64px 7vw;
  }
  .story-img {
    height: 320px;
  }
}
@media (max-width: 960px) {
  .room-grid {
    grid-template-columns: 1fr 1fr;
  }
  .visit-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .visit-map {
    height: 280px;
  }
  .nav-links {
    display: none;
  }
}
@media (max-width: 640px) {
  .section {
    padding: 64px 5vw;
  }
  .room-grid {
    grid-template-columns: 1fr;
  }
  .widget {
    flex-direction: column;
  }
  .widget-divider {
    width: auto;
    height: 1px;
    margin: 0 12px;
  }
  .form-row {
    grid-template-columns: 1fr;
  }
  .form-field.narrow {
    max-width: 100%;
  }
  .site-footer {
    flex-direction: column;
    gap: 8px;
    text-align: center;
  }
}

