/* ── Design tokens ─────────────────────────────────────────────────────────── */
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
  overflow: hidden;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Layout ── */
.rpt {
  height: 100vh;
  display: grid;
  grid-template-columns: 230px 1fr;
  overflow: hidden;
}

/* ── Rail ── */
.rail {
  background: var(--navy);
  color: var(--bone);
  display: flex;
  flex-direction: column;
  padding: 22px 16px 14px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 4px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.brand-mark {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.35rem;
  flex-shrink: 0;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.01em;
}
.brand-prop {
  font-size: 0.7rem;
  color: var(--gold-light);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-top: 2px;
}
.nav {
  margin-top: 18px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}
.nav-item {
  font-size: 0.86rem;
  font-weight: 500;
  color: rgba(251, 248, 242, 0.78);
  text-decoration: none;
  padding: 10px 12px;
  border-radius: var(--r-md);
  display: flex;
  align-items: center;
  gap: 10px;
}
.nav-item:hover {
  background: rgba(255, 255, 255, 0.06);
  color: var(--bone);
}
.nav-item.is-active {
  background: rgba(201, 166, 73, 0.16);
  color: var(--gold-light);
  font-weight: 600;
}
.nav-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--gold);
  flex-shrink: 0;
}
.nav-item:not(.is-active) .nav-dot {
  display: none;
}
.rail-foot {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.clock {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 0.88rem;
  color: var(--gold-light);
}
.agent {
  font-size: 0.72rem;
  color: rgba(251, 248, 242, 0.6);
  letter-spacing: 0.04em;
}

/* ── Main ── */
.main {
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  padding: 22px 28px 28px;
  gap: 18px;
}

/* ── Topbar ── */
.topbar {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  flex-wrap: wrap;
}
.kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold-d);
  font-weight: 600;
}
.topbar h1 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.9rem;
  letter-spacing: -0.005em;
  margin-top: 2px;
}
.topbar h1 span {
  color: var(--navy-2);
  font-weight: 500;
}
.topbar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding-top: 4px;
}

/* ── Report type tabs ── */
.report-tabs {
  display: flex;
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 3px;
  gap: 2px;
}
.rtab {
  background: transparent;
  border: none;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--warm-gray);
  padding: 8px 13px;
  border-radius: var(--r-sm);
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s, color 0.15s;
}
.rtab:hover {
  color: var(--ink);
}
.rtab.is-active {
  background: var(--navy);
  color: var(--bone);
}

/* ── Horizon selector ── */
.horizon-group {
  display: flex;
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 3px;
  gap: 2px;
}
.hz {
  background: transparent;
  border: none;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--warm-gray);
  padding: 7px 11px;
  border-radius: var(--r-sm);
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.hz:hover {
  color: var(--ink);
}
.hz.is-active {
  background: var(--gold);
  color: var(--navy-d);
}

/* ── Export buttons ── */
.export-btn {
  background: var(--navy);
  color: var(--bone);
  border: none;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  padding: 9px 14px;
  border-radius: var(--r-md);
  cursor: pointer;
  transition: background 0.15s;
}
.export-btn:hover {
  background: var(--navy-d);
}
.export-btn.ghost {
  background: transparent;
  border: 1px solid var(--line-strong);
  color: var(--ink-2);
}
.export-btn.ghost:hover {
  background: var(--cream-2);
  border-color: var(--navy-2);
  color: var(--navy-d);
}

/* ── KPI band ── */
.kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}
.kpi {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 16px;
  position: relative;
  overflow: hidden;
}
.kpi::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: var(--gold);
}
.kpi-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  font-weight: 600;
}
.kpi-value {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.85rem;
  color: var(--navy-d);
  margin-top: 4px;
  letter-spacing: -0.01em;
  font-variant-numeric: tabular-nums;
}
.kpi-value small {
  font-size: 1rem;
  font-weight: 600;
  color: var(--warm-gray);
  margin-left: 1px;
}
.kpi-trend {
  font-size: 0.74rem;
  font-weight: 600;
  margin-top: 2px;
  letter-spacing: 0.02em;
}
.kpi-trend.up {
  color: var(--success);
}
.kpi-trend.down {
  color: var(--danger);
}
.kpi-trend.neutral {
  color: var(--warm-gray);
}

/* ── Chart panel ── */
.chart-panel {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 18px 20px 12px;
}
.chart-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}
.chart-head h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.15rem;
  letter-spacing: -0.005em;
}
.legend {
  display: flex;
  gap: 14px;
  align-items: center;
}
.leg {
  font-size: 0.76rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--ink-2);
}
.leg::before {
  content: "";
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 3px;
}
.leg-actual::before {
  background: var(--navy-2);
}
.leg-forecast::before {
  background: var(--gold);
}

/* ── Chart inner ── */
.chart-wrap {
  display: flex;
  gap: 8px;
  align-items: flex-end;
  height: 180px;
}
.chart-y {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 100%;
  padding-bottom: 2px;
}
.chart-y span {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  color: var(--warm-gray);
  text-align: right;
  white-space: nowrap;
}
.chart-bars {
  flex: 1;
  display: flex;
  align-items: flex-end;
  gap: 6px;
  height: 100%;
  position: relative;
  border-left: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 6px 4px 0;
  overflow: hidden;
}
/* Horizontal grid lines */
.chart-bars::before {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    to top,
    transparent,
    transparent calc(25% - 1px),
    var(--line) calc(25% - 1px),
    var(--line) 25%
  );
  pointer-events: none;
}
.bar-group {
  flex: 1;
  display: flex;
  gap: 2px;
  align-items: flex-end;
  height: 100%;
  min-width: 0;
}
.bar {
  flex: 1;
  border-radius: 3px 3px 0 0;
  min-height: 2px;
  transform-origin: bottom;
  animation: barGrow 0.45s cubic-bezier(0.22, 1, 0.36, 1) both;
  position: relative;
}
.bar-actual {
  background: var(--navy-2);
}
.bar-forecast {
  background: var(--gold);
  opacity: 0.82;
}
@keyframes barGrow {
  from {
    transform: scaleY(0);
  }
  to {
    transform: scaleY(1);
  }
}
.chart-x {
  display: flex;
  gap: 6px;
  padding: 6px 0 0 44px;
}
.chart-x span {
  flex: 1;
  text-align: center;
  font-size: 0.68rem;
  color: var(--warm-gray);
  font-family: var(--font-mono);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Table panel ── */
.table-panel {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
}
.table-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 18px;
  border-bottom: 1px solid var(--line);
}
.table-head h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.05rem;
}
.table-meta {
  font-size: 0.76rem;
  color: var(--warm-gray);
  font-variant-numeric: tabular-nums;
}
.table-wrap {
  overflow-x: auto;
}
table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.86rem;
}
thead th {
  background: var(--cream);
  text-align: left;
  padding: 10px 14px;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--warm-gray);
  border-bottom: 1px solid var(--line);
  white-space: nowrap;
}
tbody tr {
  border-bottom: 1px solid var(--line);
  transition: background 0.12s;
}
tbody tr:last-child {
  border-bottom: none;
}
tbody tr:hover {
  background: var(--cream);
}
tbody td {
  padding: 11px 14px;
  color: var(--ink);
  vertical-align: middle;
}
tbody td.mono {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}
tbody td.up {
  color: var(--success);
  font-weight: 600;
}
tbody td.down {
  color: var(--danger);
  font-weight: 600;
}
tbody td.muted {
  color: var(--warm-gray);
  font-style: italic;
}
.bar-inline {
  height: 6px;
  border-radius: 3px;
  background: var(--navy-2);
  display: inline-block;
  vertical-align: middle;
}
.bar-inline.fc {
  background: var(--gold);
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 22px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  white-space: nowrap;
  z-index: 999;
}

/* ── Responsive ── */
@media (max-width: 1200px) {
  .report-tabs {
    flex-wrap: wrap;
  }
  .kpis {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (max-width: 960px) {
  .rpt {
    grid-template-columns: 1fr;
    height: auto;
  }
  html,
  body {
    overflow: auto;
  }
  .rail {
    flex-direction: row;
    flex-wrap: wrap;
    padding: 14px 16px;
    gap: 12px;
    align-items: center;
  }
  .nav {
    flex-direction: row;
    margin-top: 0;
    flex: none;
    flex-wrap: wrap;
  }
  .rail-foot {
    border-top: none;
    padding-top: 0;
    flex-direction: row;
    gap: 10px;
    margin-left: auto;
  }
  .brand {
    padding-bottom: 0;
    border-bottom: none;
  }
  .topbar {
    flex-direction: column;
    align-items: flex-start;
  }
  .topbar-actions {
    padding-top: 0;
  }
}
@media (max-width: 560px) {
  .main {
    padding: 16px;
    gap: 14px;
  }
  .kpis {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }
  .topbar-actions {
    flex-wrap: wrap;
  }
  .report-tabs {
    width: 100%;
  }
}

