// ── State ────────────────────────────────────────────────────────────────────
let activeReport = "occupancy";
let activeDays = 7;

// ── Helpers ──────────────────────────────────────────────────────────────────
const $ = (id) => document.getElementById(id);
const toast = $("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2200);
}

function getRows() {
  const ds = DATASETS[activeReport];
  if (activeReport === "source") return ds.channels;
  const key = activeDays === 7 ? "weeks7" : activeDays === 30 ? "weeks30" : "weeks90";
  return ds[key];
}

// ── KPI band ─────────────────────────────────────────────────────────────────
function renderKPIs() {
  const ds = DATASETS[activeReport];
  $("kpiBand").innerHTML = ds.kpis
    .map(
      (k) => `
    <article class="kpi">
      <p class="kpi-label">${k.label}</p>
      <p class="kpi-value">${k.value}<small>${k.unit}</small></p>
      <p class="kpi-trend ${k.trend}">${k.delta}</p>
    </article>`
    )
    .join("");
}

// ── Chart ────────────────────────────────────────────────────────────────────
function renderChart() {
  const ds = DATASETS[activeReport];
  const rows = getRows();
  $("chartTitle").textContent = ds.chartTitle;

  // Y-axis labels (5 steps)
  const yMax = ds.yMax;
  $("chartY").innerHTML = [yMax, yMax * 0.75, yMax * 0.5, yMax * 0.25, 0]
    .map((v) => `<span>${Math.round(v)}${ds.yUnit}</span>`)
    .join("");

  // Determine what the two bars represent per report
  const barsEl = $("chartBars");
  const xEl = $("chartX");
  barsEl.innerHTML = "";
  xEl.innerHTML = "";

  rows.forEach((r) => {
    let valA, valB;
    if (activeReport === "occupancy") {
      valA = r.actual;
      valB = r.forecast;
    } else if (activeReport === "pickup") {
      valA = r.a;
      valB = r.b + r.c;
    } else if (activeReport === "pace") {
      valA = r.otb;
      valB = r.ly;
    } else {
      // source — single bar (pct)
      valA = r.pct;
      valB = null;
    }

    const aHeight = valA != null ? (valA / yMax) * 100 : 0;
    const bHeight = valB != null ? (valB / yMax) * 100 : 0;
    const aStyle = `height:${aHeight}%`;
    const bStyle = valB != null ? `height:${bHeight}%` : "";

    const group = document.createElement("div");
    group.className = "bar-group";
    group.innerHTML = `
      <div class="bar bar-actual" style="${aStyle}" title="${r.label} · actual: ${valA}${ds.yUnit}"></div>
      ${valB != null ? `<div class="bar bar-forecast" style="${bStyle}" title="${r.label} · forecast: ${valB}${ds.yUnit}"></div>` : ""}`;
    barsEl.appendChild(group);

    const xLabel = document.createElement("span");
    xLabel.textContent = r.label;
    xEl.appendChild(xLabel);
  });
}

// ── Table ────────────────────────────────────────────────────────────────────
function renderTable() {
  const ds = DATASETS[activeReport];
  const rows = getRows();
  $("tableTitle").textContent = ds.tableTitle;
  $("tableMeta").textContent = `${rows.length} rows`;

  $("tableHead").innerHTML = `<tr>${ds.cols.map((c) => `<th>${c}</th>`).join("")}</tr>`;

  let tbody = "";
  if (activeReport === "occupancy") {
    rows.forEach((r) => {
      const variance = r.actual != null ? r.actual - r.forecast : null;
      const varClass = variance == null ? "muted" : variance >= 0 ? "up" : "down";
      const varText = variance == null ? "—" : (variance >= 0 ? "+" : "") + variance + "%";
      const barActW = r.actual != null ? r.actual : 0;
      const barFcW = r.forecast;
      tbody += `<tr>
        <td>${r.label}</td>
        <td class="mono">${r.actual != null ? r.actual + "%" : "<span class='muted'>—</span>"}</td>
        <td class="mono">${r.forecast}% <span class="bar-inline fc" style="width:${barFcW * 0.5}px"></span></td>
        <td class="${varClass}">${varText}</td>
        <td class="mono">${r.rooms != null ? r.rooms : "<span class='muted'>est. " + Math.round((r.forecast * r.avail) / 100) + "</span>"}</td>
        <td class="mono">${r.avail}</td>
      </tr>`;
    });
  } else if (activeReport === "pickup") {
    rows.forEach((r) => {
      const ly_est = Math.round(r.total * 0.88);
      const varV = r.total - ly_est;
      tbody += `<tr>
        <td>${r.label}</td>
        <td class="mono">${r.a}</td>
        <td class="mono">${r.b}</td>
        <td class="mono">${r.c}</td>
        <td class="mono">${r.total}</td>
        <td class="${varV >= 0 ? "up" : "down"}">${varV >= 0 ? "+" : ""}${varV}</td>
      </tr>`;
    });
  } else if (activeReport === "pace") {
    rows.forEach((r) => {
      const diff = r.otb - r.ly;
      tbody += `<tr>
        <td>${r.label}</td>
        <td class="mono">${r.otb}</td>
        <td class="mono">${r.ly}</td>
        <td class="${diff >= 0 ? "up" : "down"}">${diff >= 0 ? "+" : ""}${diff}</td>
        <td class="mono">€${r.adr}</td>
        <td class="mono">${r.idx.toFixed(2)}</td>
      </tr>`;
    });
  } else {
    rows.forEach((r) => {
      const ly_rev = Math.round(r.rev * 0.89);
      const diff = r.rev - ly_rev;
      tbody += `<tr>
        <td>${r.label}</td>
        <td class="mono">${r.rns > 0 ? r.rns : "—"}</td>
        <td class="mono">€${r.rev.toLocaleString()}</td>
        <td class="mono">${r.adr > 0 ? "€" + r.adr : "—"}</td>
        <td class="mono">${r.pct}% <span class="bar-inline" style="width:${r.pct}px"></span></td>
        <td class="${diff >= 0 ? "up" : "down"}">${diff >= 0 ? "+" : ""}€${Math.abs(diff).toLocaleString()}</td>
      </tr>`;
    });
  }
  $("tableBody").innerHTML = tbody;
}

// ── Full render ──────────────────────────────────────────────────────────────
function render() {
  renderKPIs();
  renderChart();
  renderTable();
}

// ── Clock ────────────────────────────────────────────────────────────────────
function tick() {
  const now = new Date();
  const hhmm = now.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
  const wk = now.toLocaleDateString("en-GB", { weekday: "short" });
  $("clock").textContent = `${hhmm} · ${wk}`;
}
tick();
setInterval(tick, 1000);

// ── Event wiring ─────────────────────────────────────────────────────────────
document.querySelectorAll(".rtab").forEach((btn) => {
  btn.addEventListener("click", () => {
    document.querySelectorAll(".rtab").forEach((b) => b.classList.remove("is-active"));
    btn.classList.add("is-active");
    activeReport = btn.dataset.report;
    render();
  });
});

document.querySelectorAll(".hz").forEach((btn) => {
  btn.addEventListener("click", () => {
    document.querySelectorAll(".hz").forEach((b) => b.classList.remove("is-active"));
    btn.classList.add("is-active");
    activeDays = Number(btn.dataset.days);
    render();
  });
});

$("btnCSV").addEventListener("click", () => {
  const reportName = document.querySelector(".rtab.is-active").textContent.trim();
  showToast(`Exporting "${reportName}" as CSV…`);
});

$("btnPDF").addEventListener("click", () => {
  const reportName = document.querySelector(".rtab.is-active").textContent.trim();
  showToast(`Generating PDF report for "${reportName}"…`);
});

// ── Init ─────────────────────────────────────────────────────────────────────
render();

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

button {
  font: inherit;
}

input,
button {
  font-family: inherit;
}

:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}

/* ── Layout ── */
.dispense {
  max-width: 920px;
  margin: 0 auto;
  padding: 32px 20px 64px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}
.eyebrow {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--teal-d);
}
.head h1 {
  font-size: 1.7rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-top: 4px;
}
.head-meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.pill {
  font-size: 0.76rem;
  font-weight: 600;
  color: var(--ink-2);
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 6px 12px;
}

/* ── Rx detail ── */
.rx {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px;
  box-shadow: var(--shadow-1);
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.rx-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.rx-id {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.rx-tag {
  font-size: 0.74rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
}
.rx-num {
  font-size: 1.2rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.rx-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.rx-block .label {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
}
.rx-block .value {
  font-size: 1.02rem;
  font-weight: 700;
  margin-top: 3px;
}
.rx-block .sub {
  font-size: 0.82rem;
  color: var(--muted);
  margin-top: 2px;
}

.drug {
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: linear-gradient(160deg, var(--teal-50), #f4faf9);
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.drug-name {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
}
.drug-strength {
  font-size: 1.12rem;
  font-weight: 800;
  color: var(--teal-700);
  letter-spacing: -0.01em;
}
.drug-form {
  font-size: 0.85rem;
  color: var(--ink-2);
}
.drug-facts {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.drug-facts div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.drug-facts dt {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
}
.drug-facts dd {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ink);
}
.sig {
  font-size: 0.9rem;
  color: var(--ink-2);
  line-height: 1.55;
  background: var(--white);
  border: 1px dashed var(--line-2);
  border-radius: var(--r-sm);
  padding: 10px 12px;
}
.sig-tag {
  display: inline-block;
  font-size: 0.68rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--teal-d);
  background: var(--teal-50);
  border-radius: 6px;
  padding: 2px 7px;
  margin-right: 6px;
  vertical-align: 1px;
}

/* ── Two columns ── */
.cols {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 20px;
  align-items: start;
}
.card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px;
  box-shadow: var(--shadow-1);
}
.card-title {
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

/* ── Form ── */
.form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.field-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.field label,
.checklist legend {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--ink-2);
}
.field input[type="text"],
.field input[type="number"],
.field input[type="date"] {
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 11px 13px;
  font-size: 0.95rem;
  color: var(--ink);
  background: var(--white);
  width: 100%;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.field input:focus {
  outline: none;
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(18, 156, 147, 0.16);
}
.field input.invalid {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(212, 80, 62, 0.14);
}
.hint {
  font-size: 0.8rem;
  color: var(--muted);
}
.hint.warn {
  color: var(--warn);
  font-weight: 600;
}

/* ── Quantity stepper ── */
.qty {
  display: grid;
  grid-template-columns: 44px 1fr 44px;
  gap: 0;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  overflow: hidden;
}
.qty input {
  border: none !important;
  border-radius: 0 !important;
  text-align: center;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  box-shadow: none !important;
}
.qty input:focus {
  background: var(--teal-50);
}
.step {
  border: none;
  background: var(--teal-50);
  color: var(--teal-d);
  font-size: 1.25rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s;
  line-height: 1;
}
.step:hover {
  background: #d6ede9;
}
.step:active {
  background: #c8e6e1;
}

/* ── Scan field ── */
.scan {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 4px 12px 4px 14px;
  background: var(--white);
  transition: border-color 0.15s, box-shadow 0.15s, background 0.2s;
}
.scan:focus-within {
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(18, 156, 147, 0.16);
}
.scan[data-state="ok"] {
  border-color: var(--ok);
  background: rgba(47, 158, 111, 0.06);
}
.scan[data-state="bad"] {
  border-color: var(--danger);
  background: rgba(212, 80, 62, 0.05);
}
.scan-icon {
  font-size: 1.1rem;
  color: var(--muted);
  letter-spacing: -2px;
}
.scan input {
  border: none !important;
  box-shadow: none !important;
  padding: 9px 0 !important;
  background: transparent;
  font-size: 0.95rem;
  width: 100%;
}
.scan input:focus {
  outline: none;
}
.scan-status {
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
}
.scan[data-state="ok"] .scan-status {
  color: var(--ok);
}
.scan[data-state="bad"] .scan-status {
  color: var(--danger);
}
.chip {
  border: 1px solid var(--line-2);
  background: var(--white);
  border-radius: 999px;
  padding: 2px 9px;
  font-size: 0.76rem;
  font-weight: 600;
  color: var(--teal-d);
  cursor: pointer;
  font-variant-numeric: tabular-nums;
  transition: background 0.15s, border-color 0.15s;
}
.chip:hover {
  background: var(--teal-50);
  border-color: var(--teal);
}

/* ── Checklist ── */
.checklist {
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 16px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.checklist legend {
  padding: 0 6px;
}
.check {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 11px;
  align-items: start;
  cursor: pointer;
  padding: 8px 8px;
  border-radius: var(--r-sm);
  transition: background 0.15s;
}
.check:hover {
  background: var(--teal-50);
}
.check input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
}
.box {
  width: 20px;
  height: 20px;
  border: 2px solid var(--line-2);
  border-radius: 6px;
  margin-top: 1px;
  display: grid;
  place-items: center;
  transition: background 0.15s, border-color 0.15s;
}
.box::after {
  content: "✓";
  color: #fff;
  font-size: 0.78rem;
  font-weight: 800;
  opacity: 0;
  transform: scale(0.6);
  transition: opacity 0.12s, transform 0.12s;
}
.check input:checked ~ .box {
  background: var(--ok);
  border-color: var(--ok);
}
.check input:checked ~ .box::after {
  opacity: 1;
  transform: scale(1);
}
.check input:focus-visible ~ .box {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}
.check-text {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.check-text strong {
  font-size: 0.9rem;
  font-weight: 600;
}
.check-text small {
  font-size: 0.78rem;
  color: var(--muted);
}
.checklist-meter {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--ink-2);
  padding: 2px 8px 0;
}
.checklist-meter span {
  color: var(--teal-d);
}

/* ── Buttons ── */
.btn {
  border: none;
  border-radius: 11px;
  padding: 12px 18px;
  font-weight: 700;
  font-size: 0.92rem;
  cursor: pointer;
  transition: transform 0.12s, background 0.15s, border-color 0.15s, opacity 0.15s;
}
.btn:active {
  transform: translateY(1px);
}
.btn.primary {
  background: var(--teal-d);
  color: #fff;
  box-shadow: 0 6px 16px rgba(12, 122, 115, 0.22);
}
.btn.primary:hover {
  background: var(--teal-700);
}
.btn.ghost {
  background: var(--white);
  border: 1px solid var(--line-2);
  color: var(--ink-2);
}
.btn.ghost:hover {
  background: var(--teal-50);
  border-color: var(--teal);
  color: var(--teal-d);
}

/* ── Badge ── */
.badge {
  font-size: 0.74rem;
  font-weight: 700;
  padding: 5px 11px;
  border-radius: 999px;
  white-space: nowrap;
}
.badge.ok {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}
.badge.done {
  background: var(--teal-50);
  color: var(--teal-d);
}

/* ── Label preview ── */
.preview {
  position: sticky;
  top: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.preview-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.live-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 0 rgba(47, 158, 111, 0.5);
  animation: pulse 2s infinite;
}
@keyframes pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(47, 158, 111, 0.5);
  }
  70% {
    box-shadow: 0 0 0 7px rgba(47, 158, 111, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(47, 158, 111, 0);
  }
}
.label {
  border: 1px solid var(--line-2);
  border-radius: var(--r-md);
  background: #fffef9;
  padding: 16px 18px;
  font-family: "Inter", monospace;
  box-shadow: inset 0 0 0 4px #fff, 0 2px 8px rgba(16, 50, 47, 0.06);
}
.label hr {
  border: none;
  border-top: 1px dashed var(--line-2);
  margin: 10px 0;
}
.label-pharm {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.label-pharm strong {
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--ink);
}
.label-pharm span {
  font-size: 0.74rem;
  color: var(--muted);
}
.label-rx {
  font-size: 0.78rem;
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
}
.label-patient {
  font-size: 1.05rem;
  font-weight: 800;
  margin-top: 2px;
}
.label-drug {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--teal-700);
  margin-top: 2px;
}
.label-qty {
  font-size: 0.82rem;
  color: var(--ink-2);
  margin-top: 4px;
  font-variant-numeric: tabular-nums;
}
.label-sig {
  font-size: 0.86rem;
  color: var(--ink);
  margin-top: 6px;
  line-height: 1.5;
}
.label-foot {
  font-size: 0.72rem;
  color: var(--muted);
  line-height: 1.5;
}
.preview-note {
  font-size: 0.78rem;
  color: var(--muted);
  text-align: center;
}

/* ── Done state ── */
.done {
  display: flex;
  align-items: center;
  gap: 16px;
  background: linear-gradient(150deg, var(--teal-50), #eafaf6);
  border: 1px solid rgba(47, 158, 111, 0.3);
  border-radius: var(--r-lg);
  padding: 20px 22px;
  box-shadow: var(--shadow-1);
  animation: rise 0.3s ease;
}
@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.done-icon {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: var(--ok);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 1.4rem;
  font-weight: 800;
  flex-shrink: 0;
}
.done-text {
  flex: 1;
}
.done-text h2 {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--teal-700);
}
.done-text p {
  font-size: 0.88rem;
  color: var(--ink-2);
  margin-top: 1px;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}

@media (max-width: 820px) {
  .cols {
    grid-template-columns: 1fr;
  }
  .preview {
    position: static;
  }
}

@media (max-width: 520px) {
  .dispense {
    padding: 24px 14px 48px;
  }
  .head h1 {
    font-size: 1.45rem;
  }
  .rx,
  .card {
    padding: 18px;
  }
  .rx-grid {
    grid-template-columns: 1fr;
  }
  .drug-facts {
    grid-template-columns: 1fr 1fr;
  }
  .field-row {
    grid-template-columns: 1fr;
  }
  .done {
    flex-direction: column;
    align-items: flex-start;
  }
}

