// ── In-clinic Dispense Counter ──────────────────────────────────────────────
// Vanilla JS only. Live label preview, simulated barcode scan + lot validation,
// counseling checklist gate, and a dispensed done-state with toast feedback.

(function () {
  "use strict";

  // ── Elements ──
  const form = document.getElementById("dispense-form");
  const qty = document.getElementById("qty");
  const qtyUp = document.getElementById("qty-up");
  const qtyDown = document.getElementById("qty-down");

  const scanWrap = document.querySelector(".scan");
  const scan = document.getElementById("scan");
  const scanStatus = document.getElementById("scan-status");

  const lot = document.getElementById("lot");
  const expiry = document.getElementById("expiry");
  const expiryWarn = document.getElementById("expiry-warn");

  const counselBoxes = Array.from(
    document.querySelectorAll('input[name="counsel"]')
  );
  const counselCount = document.getElementById("counsel-count");

  const dispenseBtn = document.getElementById("dispense-btn");
  const done = document.getElementById("done");
  const doneDetail = document.getElementById("done-detail");
  const nextBtn = document.getElementById("next-btn");

  // Label fields
  const lbl = {
    date: document.getElementById("label-date"),
    qty: document.getElementById("label-qty"),
    lot: document.getElementById("label-lot"),
    exp: document.getElementById("label-exp"),
  };

  // ── Known stock barcodes → lot data (simulated formulary) ──
  const STOCK = {
    "NDC-0093-4155-78": { lot: "A23F091", exp: "2027-04-30" },
    "NDC-0093-4155-79": { lot: "A23F114", exp: "2027-06-30" },
  };

  const QTY_MIN = 1;
  const QTY_MAX = 120;

  // Lot is considered "verified" only when set by a valid scan.
  let lotVerified = false;

  // ── Toast helper ──
  let toastTimer = null;
  const toastEl = document.getElementById("toast");
  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => {
      toastEl.hidden = true;
    }, 2600);
  }

  // ── Date formatting ──
  const MONTHS = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun",
    "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
  ];
  function fmtDate(iso) {
    if (!iso) return "—";
    const [y, m, d] = iso.split("-").map(Number);
    if (!y || !m || !d) return "—";
    return `${String(d).padStart(2, "0")} ${MONTHS[m - 1]} ${y}`;
  }
  function todayISO() {
    const t = new Date();
    return [
      t.getFullYear(),
      String(t.getMonth() + 1).padStart(2, "0"),
      String(t.getDate()).padStart(2, "0"),
    ].join("-");
  }

  // ── Live label sync ──
  function renderLabel() {
    lbl.qty.textContent = qty.value || "0";
    lbl.lot.textContent = lot.value.trim() || "——";
    lbl.exp.textContent = fmtDate(expiry.value);
    lbl.date.textContent = fmtDate(todayISO());
  }

  // ── Quantity stepper ──
  function clampQty() {
    let v = parseInt(qty.value, 10);
    if (isNaN(v)) v = QTY_MIN;
    v = Math.min(QTY_MAX, Math.max(QTY_MIN, v));
    qty.value = v;
    return v;
  }
  function bumpQty(delta) {
    qty.value = clampQty() + delta;
    clampQty();
    renderLabel();
  }
  qtyUp.addEventListener("click", () => bumpQty(1));
  qtyDown.addEventListener("click", () => bumpQty(-1));
  qty.addEventListener("input", renderLabel);
  qty.addEventListener("blur", () => {
    clampQty();
    renderLabel();
  });

  // ── Expiry validation (warn if expired or near) ──
  function checkExpiry() {
    expiry.classList.remove("invalid");
    if (!expiry.value) {
      expiryWarn.hidden = true;
      return;
    }
    const exp = new Date(expiry.value + "T00:00:00");
    const now = new Date(todayISO() + "T00:00:00");
    const days = Math.round((exp - now) / 86400000);
    if (days < 0) {
      expiryWarn.hidden = false;
      expiryWarn.textContent = "Lot expired — do not dispense.";
      expiryWarn.classList.add("warn");
      expiry.classList.add("invalid");
    } else if (days <= 90) {
      expiryWarn.hidden = false;
      expiryWarn.textContent = `Short-dated: expires in ${days} day${days === 1 ? "" : "s"}.`;
      expiryWarn.classList.add("warn");
    } else {
      expiryWarn.hidden = true;
    }
    renderLabel();
  }
  expiry.addEventListener("input", checkExpiry);

  // ── Lot field (manual edits invalidate scan verification) ──
  lot.addEventListener("input", () => {
    lotVerified = false;
    setScanState("idle", "");
    renderLabel();
  });

  // ── Barcode scan simulation ──
  function setScanState(state, msg) {
    scanWrap.dataset.state = state;
    scanStatus.textContent = msg;
  }

  function processScan(raw) {
    const code = (raw || "").trim().toUpperCase();
    if (!code) {
      setScanState("idle", "");
      return;
    }
    const match = STOCK[code];
    if (match) {
      lot.value = match.lot;
      expiry.value = match.exp;
      lotVerified = true;
      setScanState("ok", "Lot verified");
      checkExpiry();
      renderLabel();
      toast(`Scan matched · lot ${match.lot}`);
    } else {
      lotVerified = false;
      setScanState("bad", "Not in stock");
      toast("Barcode not recognized — check the bottle.");
    }
  }

  // Enter simulates the scanner's terminating keystroke.
  scan.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      processScan(scan.value);
    }
  });
  // Hardware scanners type fast then stop; debounce as a fallback.
  let scanTimer = null;
  scan.addEventListener("input", () => {
    setScanState("idle", "Scanning…");
    clearTimeout(scanTimer);
    scanTimer = setTimeout(() => {
      if (scan.value.trim()) processScan(scan.value);
      else setScanState("idle", "");
    }, 550);
  });

  // Sample-code chip(s)
  document.querySelectorAll(".chip[data-fill]").forEach((chip) => {
    chip.addEventListener("click", () => {
      scan.value = chip.dataset.fill;
      processScan(scan.value);
      scan.focus();
    });
  });

  // ── Counseling checklist ──
  function counselDone() {
    return counselBoxes.filter((b) => b.checked).length;
  }
  function syncCounsel() {
    counselCount.textContent = String(counselDone());
  }
  counselBoxes.forEach((b) => b.addEventListener("change", syncCounsel));

  // ── Submit / validate ──
  function flash(el) {
    el.classList.add("invalid");
    el.focus();
    setTimeout(() => el.classList.remove("invalid"), 1600);
  }

  form.addEventListener("submit", (e) => {
    e.preventDefault();

    const q = clampQty();
    if (!q) {
      flash(qty);
      toast("Enter a quantity to dispense.");
      return;
    }
    if (!lot.value.trim()) {
      flash(lot);
      toast("Scan or enter a lot number first.");
      scan.focus();
      return;
    }
    if (!lotVerified) {
      toast("Lot not verified — scan the stock bottle to confirm.");
      flash(lot);
      scan.focus();
      return;
    }
    if (expiry.classList.contains("invalid")) {
      toast("Expiry issue — resolve before dispensing.");
      expiry.focus();
      return;
    }
    if (counselDone() < counselBoxes.length) {
      const firstUnchecked = counselBoxes.find((b) => !b.checked);
      if (firstUnchecked) firstUnchecked.focus();
      toast("Complete all counseling points before dispensing.");
      return;
    }

    // Success → lock the form, reveal done-state.
    renderLabel();
    form
      .querySelectorAll("input, button")
      .forEach((el) => (el.disabled = true));
    setScanState("ok", "Lot verified");

    const rxStatus = document.getElementById("rx-status");
    if (rxStatus) {
      rxStatus.textContent = "Dispensed";
      rxStatus.classList.remove("ok");
      rxStatus.classList.add("done");
    }

    doneDetail.textContent = `Label printed · ${q} dispensed · lot ${lot.value.trim()}.`;
    done.hidden = false;
    done.scrollIntoView({ behavior: "smooth", block: "nearest" });
    toast("Dispensed — label sent to printer.");
  });

  // ── Reset for next prescription ──
  nextBtn.addEventListener("click", () => {
    form
      .querySelectorAll("input, button")
      .forEach((el) => (el.disabled = false));
    form.reset();
    lotVerified = false;
    setScanState("idle", "");
    expiryWarn.hidden = true;
    qty.value = 30;
    expiry.value = "2027-04-30";

    const rxStatus = document.getElementById("rx-status");
    if (rxStatus) {
      rxStatus.textContent = "Ready to dispense";
      rxStatus.classList.remove("done");
      rxStatus.classList.add("ok");
    }

    done.hidden = true;
    syncCounsel();
    renderLabel();
    scan.focus();
    toast("Counter cleared — next prescription ready.");
  });

  // ── Init ──
  syncCounsel();
  checkExpiry();
  renderLabel();
})();

snippets.css:
:root {
  /* Mental-health palette — sage + cream + lavender */
  --sage: #9bb6a3;
  --sage-d: #5f8270;
  --sage-700: #4a6a59;
  --sage-50: #eef4f0;
  --lav: #c9bce0;
  --lav-soft: #efeaf7;
  --cream: #f7f3ea;
  --coral: #e8917c;
  --coral-soft: #f7e3dc;
  --ink: #34303a;
  --ink-2: #524d5b;
  --muted: #837e8c;
  --bg: #faf7f1;
  --white: #ffffff;
  --line: rgba(52, 48, 58, 0.08);
  --line-2: rgba(52, 48, 58, 0.16);
  --serif: "Fraunces", Georgia, "Times New Roman", serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --r-xl: 28px;
  --shadow-1: 0 1px 2px rgba(52, 48, 58, 0.04), 0 8px 24px rgba(52, 48, 58, 0.05);
  --shadow-2: 0 18px 46px rgba(95, 130, 112, 0.18);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--sans);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.6;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}

.skip {
  position: absolute;
  left: 16px;
  top: -60px;
  background: var(--sage-d);
  color: #fff;
  padding: 10px 16px;
  border-radius: var(--r-sm);
  z-index: 100;
  font-weight: 600;
  font-size: 0.9rem;
  transition: top 0.2s;
}
.skip:focus {
  top: 16px;
}

:focus-visible {
  outline: 2.5px solid var(--sage-d);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: none;
  border-radius: 999px;
  padding: 13px 26px;
  font: inherit;
  font-weight: 600;
  font-size: 0.95rem;
  text-decoration: none;
  cursor: pointer;
  transition: transform 0.14s ease, background 0.18s, box-shadow 0.18s, border-color 0.18s, color 0.18s;
}
.btn:active {
  transform: translateY(1px);
}
.btn.primary {
  background: var(--sage-d);
  color: #fff;
  box-shadow: 0 8px 20px rgba(95, 130, 112, 0.28);
}
.btn.primary:hover {
  background: var(--sage-700);
  box-shadow: 0 12px 26px rgba(95, 130, 112, 0.34);
}
.btn.quiet {
  background: transparent;
  color: var(--ink-2);
  border: 1px solid var(--line-2);
}
.btn.quiet:hover {
  background: var(--white);
  border-color: var(--sage);
  color: var(--sage-700);
}
.btn.ghost-light {
  background: rgba(255, 255, 255, 0.16);
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.4);
}
.btn.ghost-light:hover {
  background: rgba(255, 255, 255, 0.26);
}
.btn.solid-coral {
  background: var(--coral);
  color: #fff;
  white-space: nowrap;
}
.btn.solid-coral:hover {
  background: #db7a63;
}

/* ── Top bar ── */
.bar {
  position: sticky;
  top: 0;
  z-index: 60;
  background: rgba(250, 247, 241, 0.78);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid transparent;
  transition: border-color 0.25s, box-shadow 0.25s, background 0.25s;
}
.bar.is-stuck {
  border-bottom-color: var(--line);
  box-shadow: 0 4px 18px rgba(52, 48, 58, 0.04);
}
.bar-inner {
  max-width: 1120px;
  margin: 0 auto;
  padding: 16px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--ink);
}
.mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: var(--sage-50);
  color: var(--sage-d);
  border: 1px solid var(--line);
}
.brand-name {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.25rem;
  letter-spacing: -0.01em;
}

.nav {
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav > a {
  text-decoration: none;
  color: var(--ink-2);
  font-weight: 500;
  font-size: 0.94rem;
  padding: 9px 14px;
  border-radius: 999px;
  transition: background 0.16s, color 0.16s;
}
.nav > a:hover {
  background: var(--sage-50);
  color: var(--sage-700);
}
.nav .nav-cta {
  background: var(--sage-d);
  color: #fff;
  margin-left: 8px;
  font-weight: 600;
}
.nav .nav-cta:hover {
  background: var(--sage-700);
  color: #fff;
}

.burger {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 42px;
  height: 42px;
  align-items: center;
  justify-content: center;
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: 12px;
  cursor: pointer;
}
.burger span {
  width: 18px;
  height: 2px;
  background: var(--ink);
  border-radius: 2px;
  transition: transform 0.22s, opacity 0.18s;
}
.burger[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.burger[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}
.burger[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ── Reveal on scroll ── */
.reveal {
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}
.reveal.in {
  opacity: 1;
  transform: none;
}
@media (prefers-reduced-motion: reduce) {
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

/* ── Section scaffolding ── */
section {
  max-width: 1120px;
  margin: 0 auto;
  padding: 84px 24px;
}
.section-head {
  max-width: 580px;
  margin: 0 auto 48px;
  text-align: center;
}
.kicker {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--sage-d);
  margin-bottom: 14px;
}
.kicker.light {
  color: var(--lav);
}
.section-head h2 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(1.8rem, 4vw, 2.5rem);
  letter-spacing: -0.02em;
  line-height: 1.12;
}
.section-head p {
  margin-top: 16px;
  color: var(--muted);
  font-size: 1.04rem;
}

/* ── Hero ── */
.hero {
  padding-top: 56px;
  padding-bottom: 64px;
}
.hero-inner {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 56px;
  align-items: center;
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--sage-700);
  background: var(--sage-50);
  border: 1px solid var(--line);
  padding: 7px 14px;
  border-radius: 999px;
  margin-bottom: 22px;
}
.hero-copy h1 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(2.6rem, 6.2vw, 4.4rem);
  line-height: 1.04;
  letter-spacing: -0.03em;
  color: var(--ink);
}
.lede {
  margin-top: 22px;
  font-size: 1.14rem;
  color: var(--ink-2);
  max-width: 38ch;
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 30px;
}
.hero-note {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 24px;
  font-size: 0.9rem;
  color: var(--muted);
  font-weight: 500;
}
.hero-note .dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--sage);
  box-shadow: 0 0 0 4px var(--sage-50);
}

/* Hero floating card */
.hero-card {
  position: relative;
}
.card-soft {
  position: relative;
  z-index: 2;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-xl);
  padding: 28px;
  box-shadow: var(--shadow-1);
}
.stat-row {
  display: flex;
  gap: 14px;
}
.stat {
  flex: 1;
  background: var(--cream);
  border-radius: var(--r-md);
  padding: 16px;
}
.stat strong {
  display: block;
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--sage-700);
}
.stat span {
  font-size: 0.82rem;
  color: var(--muted);
  margin-top: 2px;
  display: block;
}
.quote {
  margin: 22px 0;
  padding-left: 16px;
  border-left: 3px solid var(--lav);
}
.quote p {
  font-family: var(--serif);
  font-style: italic;
  font-size: 1.06rem;
  color: var(--ink);
  line-height: 1.45;
}
.quote-by {
  display: block;
  margin-top: 10px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--muted);
}
.assure {
  list-style: none;
  display: grid;
  gap: 10px;
}
.assure li {
  position: relative;
  padding-left: 26px;
  font-size: 0.9rem;
  color: var(--ink-2);
  font-weight: 500;
}
.assure li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 4px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--sage-50);
  border: 1.5px solid var(--sage);
}
.assure li::after {
  content: "";
  position: absolute;
  left: 5px;
  top: 8px;
  width: 6px;
  height: 3.5px;
  border-left: 1.8px solid var(--sage-d);
  border-bottom: 1.8px solid var(--sage-d);
  transform: rotate(-45deg);
}
.leaf {
  position: absolute;
  border-radius: 60% 40% 55% 45% / 55% 45% 60% 40%;
  z-index: 1;
  filter: blur(2px);
}
.leaf-a {
  width: 180px;
  height: 180px;
  background: var(--lav-soft);
  top: -42px;
  right: -34px;
}
.leaf-b {
  width: 130px;
  height: 130px;
  background: var(--sage-50);
  bottom: -36px;
  left: -30px;
}

/* ── Services ── */
.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.svc {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 26px 22px;
  box-shadow: var(--shadow-1);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s;
}
.svc:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-2);
  border-color: rgba(95, 130, 112, 0.3);
}
.svc-ic {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 14px;
  background: var(--sage-50);
  color: var(--sage-d);
  margin-bottom: 18px;
}
.svc:nth-child(2) .svc-ic {
  background: var(--lav-soft);
  color: #7a6a98;
}
.svc:nth-child(3) .svc-ic {
  background: var(--coral-soft);
  color: #c06a52;
}
.svc:nth-child(4) .svc-ic {
  background: var(--cream);
  color: var(--sage-700);
}
.svc h3 {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.22rem;
  letter-spacing: -0.01em;
  margin-bottom: 8px;
}
.svc p {
  font-size: 0.93rem;
  color: var(--muted);
  line-height: 1.55;
}
.svc-tag {
  display: inline-block;
  margin-top: 16px;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--sage-700);
  background: var(--sage-50);
  padding: 5px 11px;
  border-radius: 999px;
}

/* ── How it works ── */
.how {
  background: linear-gradient(180deg, var(--cream), #f4eee2);
  max-width: none;
  border-radius: 0;
}
.how .section-head,
.how .steps {
  max-width: 1120px;
  margin-left: auto;
  margin-right: auto;
}
.how .section-head {
  max-width: 580px;
}
.steps {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
  counter-reset: none;
}
.step {
  position: relative;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 30px 26px;
}
.step-no {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.1rem;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--lav-soft);
  color: #6e5e92;
  margin-bottom: 18px;
}
.step h3 {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.24rem;
  margin-bottom: 8px;
}
.step p {
  color: var(--muted);
  font-size: 0.96rem;
}
.step:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 52px;
  right: -16px;
  width: 22px;
  height: 2px;
  background: var(--line-2);
}

/* ── Approach band ── */
.approach {
  max-width: none;
  background: var(--sage-d);
  background: linear-gradient(140deg, var(--sage-d), var(--sage-700));
  color: #fff;
  border-radius: 0;
}
.approach-inner {
  max-width: 1120px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 56px;
  align-items: center;
}
.approach-copy h2 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(1.8rem, 4vw, 2.5rem);
  line-height: 1.14;
  letter-spacing: -0.02em;
  margin-bottom: 18px;
}
.approach-copy p {
  color: rgba(255, 255, 255, 0.86);
  font-size: 1.06rem;
  max-width: 46ch;
  margin-bottom: 26px;
}
.values {
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.values li {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: var(--r-md);
  padding: 20px;
}
.values strong {
  display: block;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.1rem;
  margin-bottom: 6px;
}
.values span {
  font-size: 0.9rem;
  color: rgba(255, 255, 255, 0.82);
  line-height: 1.5;
}

/* ── Testimonial ── */
.voices {
  text-align: center;
}
.testimonial {
  position: relative;
  max-width: 720px;
  margin: 0 auto;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-xl);
  padding: 52px 48px 40px;
  box-shadow: var(--shadow-1);
}
.mark-quote {
  position: absolute;
  top: 14px;
  left: 34px;
  font-family: var(--serif);
  font-size: 5rem;
  line-height: 1;
  color: var(--lav);
  opacity: 0.55;
}
.testimonial blockquote {
  font-family: var(--serif);
  font-weight: 500;
  font-style: italic;
  font-size: clamp(1.2rem, 3vw, 1.6rem);
  line-height: 1.4;
  color: var(--ink);
  letter-spacing: -0.01em;
}
.testimonial figcaption {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  margin-top: 28px;
}
.avatar {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: var(--sage-50);
  color: var(--sage-d);
  font-weight: 700;
  font-size: 0.86rem;
  border: 1px solid var(--line);
}
.who {
  text-align: left;
