.who strong {
  display: block;
  font-size: 0.95rem;
  color: var(--ink);
}
.who span {
  font-size: 0.84rem;
  color: var(--muted);
}

/* ── Crisis note ── */
.crisis {
  display: flex;
  align-items: center;
  gap: 22px;
  background: var(--coral-soft);
  border: 1px solid rgba(232, 145, 124, 0.4);
  border-radius: var(--r-lg);
  padding: 28px 32px;
  margin-top: 0;
  margin-bottom: 0;
  max-width: 1072px;
}
.crisis-ic {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  flex-shrink: 0;
  border-radius: 14px;
  background: #fff;
  color: #c06a52;
}
.crisis-copy {
  flex: 1;
}
.crisis-copy h3 {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.18rem;
  margin-bottom: 6px;
  color: var(--ink);
}
.crisis-copy p {
  font-size: 0.94rem;
  color: var(--ink-2);
  line-height: 1.55;
}

/* ── Footer ── */
.foot {
  background: var(--ink);
  color: #fff;
  margin-top: 84px;
}
.foot-inner {
  max-width: 1120px;
  margin: 0 auto;
  padding: 72px 24px 40px;
}
.foot-cta {
  text-align: center;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  margin-bottom: 40px;
}
.foot-cta h2 {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(2rem, 5vw, 3rem);
  letter-spacing: -0.02em;
}
.foot-cta p {
  color: rgba(255, 255, 255, 0.7);
  margin: 12px 0 26px;
  font-size: 1.05rem;
}
.foot-cols {
  display: flex;
  justify-content: space-between;
  gap: 32px;
  flex-wrap: wrap;
  margin-bottom: 36px;
}
.foot-brand {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.3rem;
  display: block;
  margin-bottom: 12px;
}
.foot-col p {
  color: rgba(255, 255, 255, 0.62);
  font-size: 0.92rem;
  margin-top: 4px;
}
.foot-col[aria-label] {
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: flex-start;
}
.foot-col a {
  color: rgba(255, 255, 255, 0.78);
  text-decoration: none;
  font-size: 0.94rem;
  transition: color 0.16s;
}
.foot-col a:hover {
  color: #fff;
}
.foot-fine {
  font-size: 0.82rem;
  color: rgba(255, 255, 255, 0.45);
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%) translateY(8px);
  background: var(--ink);
  color: #fff;
  padding: 14px 22px;
  border-radius: 999px;
  font-size: 0.92rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 90;
  max-width: 90vw;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s, transform 0.25s;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}
.toast[hidden] {
  display: block;
}

/* ── Responsive ── */
@media (max-width: 900px) {
  .hero-inner,
  .approach-inner {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .steps {
    grid-template-columns: 1fr;
  }
  .step:not(:last-child)::after {
    display: none;
  }
}

@media (max-width: 760px) {
  .nav {
    position: fixed;
    inset: 70px 16px auto 16px;
    flex-direction: column;
    align-items: stretch;
    gap: 6px;
    background: var(--white);
    border: 1px solid var(--line);
    border-radius: var(--r-lg);
    padding: 14px;
    box-shadow: var(--shadow-2);
    transform: translateY(-12px);
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.2s, transform 0.2s;
  }
  .nav.open {
    transform: none;
    opacity: 1;
    pointer-events: auto;
  }
  .nav > a {
    padding: 12px 14px;
  }
  .nav .nav-cta {
    margin-left: 0;
    text-align: center;
    justify-content: center;
  }
  .burger {
    display: flex;
  }
}

@media (max-width: 520px) {
  section {
    padding: 60px 18px;
  }
  .bar-inner {
    padding: 14px 18px;
  }
  .hero {
    padding-top: 40px;
  }
  .grid {
    grid-template-columns: 1fr;
  }
  .values {
    grid-template-columns: 1fr;
  }
  .card-soft {
    padding: 22px;
  }
  .stat-row {
    flex-direction: column;
  }
  .testimonial {
    padding: 44px 26px 32px;
  }
  .crisis {
    flex-direction: column;
    align-items: flex-start;
    text-align: left;
    padding: 24px;
  }
  .crisis .btn.solid-coral {
    width: 100%;
  }
  .foot-cols {
    flex-direction: column;
    gap: 24px;
  }
  .leaf {
    display: none;
  }
}

