:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(0, 0, 0, 0.4);
  --shadow-2: 0 10px 30px rgba(0, 0, 0, 0.45);
  --shadow-3: 0 24px 60px rgba(0, 0, 0, 0.6);
}

*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3 { margin: 0; line-height: 1.05; letter-spacing: -0.02em; }
p { margin: 0; }
img { max-width: 100%; display: block; }

.wrap { width: min(1140px, 92vw); margin-inline: auto; }

a { color: inherit; text-decoration: none; }

.skip-link {
  position: absolute;
  left: -999px;
  top: 0;
  z-index: 100;
  background: var(--neon);
  color: #0a0c0e;
  padding: 10px 16px;
  border-radius: var(--r-sm);
  font-weight: 700;
}
.skip-link:focus { left: 12px; top: 12px; }

:focus-visible {
  outline: 3px solid var(--neon);
  outline-offset: 2px;
  border-radius: 6px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.22em;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--neon);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid var(--line-2);
  background: var(--elevated);
  color: var(--ink);
  font-family: inherit;
  font-weight: 700;
  font-size: 0.95rem;
  padding: 13px 20px;
  border-radius: var(--r-md);
  cursor: pointer;
  transition: transform 0.12s ease, background 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}
.btn:hover { transform: translateY(-2px); }
.btn:active { transform: translateY(0); }
.btn--sm { padding: 9px 16px; font-size: 0.85rem; }
.btn--neon {
  background: var(--neon);
  color: #0a0c0e;
  border-color: var(--neon);
}
.btn--neon:hover { background: var(--neon-d); box-shadow: 0 8px 24px var(--neon-50); }
.btn--orange {
  background: var(--orange);
  color: #160a04;
  border-color: var(--orange);
}
.btn--orange:hover { box-shadow: 0 8px 24px var(--orange-soft); }
.btn--ghost { background: transparent; }
.btn--block { width: 100%; }

/* Topbar */
.topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  background: rgba(13, 15, 18, 0.82);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--line);
}
.topbar__inner {
  display: flex;
  align-items: center;
  gap: 24px;
  height: 66px;
}
.brand { display: inline-flex; align-items: center; gap: 9px; }
.brand__mark {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  background: var(--neon);
  color: #0a0c0e;
  border-radius: 9px;
  font-size: 0.85rem;
  transform: rotate(0deg);
}
.brand__name { font-weight: 900; letter-spacing: 0.14em; font-size: 1rem; }
.nav { margin-left: auto; display: flex; gap: 26px; }
.nav a {
  color: var(--ink-2);
  font-weight: 600;
  font-size: 0.9rem;
  transition: color 0.15s ease;
}
.nav a:hover { color: var(--ink); }

/* Hero */
.hero {
  position: relative;
  padding: 84px 0 64px;
  overflow: hidden;
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(60% 70% at 82% -10%, var(--neon-50), transparent 60%),
    radial-gradient(50% 60% at 8% 110%, var(--orange-soft), transparent 60%);
  pointer-events: none;
}
.hero__inner { position: relative; }
.hero h1 {
  font-weight: 900;
  font-size: clamp(2.6rem, 6.5vw, 4.6rem);
  margin: 16px 0 18px;
}
.hl { color: var(--neon); }
.hero__lead {
  color: var(--ink-2);
  max-width: 54ch;
  font-size: 1.05rem;
}
.hero__stats { display: flex; gap: 14px; margin-top: 30px; flex-wrap: wrap; }
.stat {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 20px;
  min-width: 120px;
}
.stat strong {
  display: block;
  font-size: 1.7rem;
  font-weight: 900;
  color: var(--ink);
}
.stat span {
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 0.68rem;
  color: var(--muted);
  font-weight: 600;
}

/* Roster */
.roster { padding: 24px 0 80px; }
.roster__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}
.roster__head h2 { font-size: clamp(1.5rem, 3vw, 2.1rem); font-weight: 800; }
.roster__sub { color: var(--muted); font-size: 0.9rem; font-weight: 600; }

.filters {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 26px;
}
.chip {
  font-family: inherit;
  font-weight: 700;
  font-size: 0.85rem;
  color: var(--ink-2);
  background: var(--surface);
  border: 1px solid var(--line-2);
  padding: 9px 17px;
  border-radius: 999px;
  cursor: pointer;
  transition: all 0.16s ease;
}
.chip:hover { color: var(--ink); border-color: var(--neon); }
.chip.is-active {
  background: var(--neon);
  color: #0a0c0e;
  border-color: var(--neon);
}

/* Grid + cards */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 18px;
}
.card {
  position: relative;
  display: flex;
  flex-direction: column;
  text-align: left;
  background: linear-gradient(180deg, var(--surface-2), var(--surface));
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 18px;
  cursor: pointer;
  font-family: inherit;
  color: inherit;
  box-shadow: var(--shadow-1);
  transition: transform 0.35s cubic-bezier(0.2, 0.7, 0.2, 1),
    opacity 0.35s ease, border-color 0.2s ease, box-shadow 0.25s ease;
}
.card:hover {
  transform: translateY(-5px);
  border-color: var(--line-2);
  box-shadow: var(--shadow-2);
}
.card.is-hidden {
  display: none;
  opacity: 0;
  transform: scale(0.94);
  pointer-events: none;
}
.card__top { display: flex; align-items: center; gap: 14px; }
.avatar {
  flex: none;
  width: 60px;
  height: 60px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  font-weight: 900;
  font-size: 1.25rem;
  color: #0a0c0e;
}
.card__name { font-size: 1.12rem; font-weight: 800; }
.card__role {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  font-weight: 700;
}
.rating {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 4px;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--warn);
}
.rating span { color: var(--muted); font-weight: 600; }
.tags { display: flex; flex-wrap: wrap; gap: 6px; margin: 14px 0; }
.tag {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--neon-50);
  color: var(--neon);
  border: 1px solid rgba(198, 255, 58, 0.25);
}
.card__bio {
  color: var(--ink-2);
  font-size: 0.9rem;
  margin-bottom: 14px;
}
.card__cert {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 0.78rem;
  color: var(--muted);
  font-weight: 600;
  margin-bottom: 16px;
}
.card__cert::before { content: "✓"; color: var(--ok); font-weight: 900; }
.card__foot { margin-top: auto; }

.empty {
  text-align: center;
  color: var(--muted);
  padding: 48px 0;
  font-weight: 600;
}

/* Footer */
.footer { border-top: 1px solid var(--line); padding: 30px 0; }
.footer__inner { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.footer p { color: var(--muted); font-size: 0.85rem; }

/* Modal */
.modal {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: 18px;
}
.modal[hidden] { display: none; }
.modal__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(5, 6, 8, 0.74);
  backdrop-filter: blur(4px);
  animation: fade 0.2s ease;
}
.modal__panel {
  position: relative;
  width: min(620px, 100%);
  max-height: 90vh;
  overflow-y: auto;
  background: var(--surface);
  border: 1px solid var(--line-2);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-3);
  animation: pop 0.26s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.modal__close {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid var(--line-2);
  background: var(--elevated);
  color: var(--ink);
  font-size: 0.9rem;
  cursor: pointer;
  z-index: 2;
  transition: background 0.15s ease;
}
.modal__close:hover { background: var(--danger); color: #1a0808; }

.m-hero {
  padding: 28px 28px 22px;
  border-bottom: 1px solid var(--line);
  display: flex;
  gap: 18px;
  align-items: center;
}
.m-hero .avatar { width: 76px; height: 76px; font-size: 1.6rem; }
.m-hero h3 { font-size: 1.5rem; font-weight: 900; }
.m-section { padding: 22px 28px; }
.m-section + .m-section { border-top: 1px solid var(--line); }
.m-section h4 {
  margin: 0 0 12px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.72rem;
  color: var(--neon);
  font-weight: 800;
}
.m-section p { color: var(--ink-2); }
.ach-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 9px; }
.ach-list li {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  color: var(--ink-2);
  font-size: 0.92rem;
}
.ach-list li::before { content: "🏆"; flex: none; }
.slots { display: flex; flex-wrap: wrap; gap: 9px; }
.slot {
  font-family: inherit;
  font-weight: 700;
  font-size: 0.85rem;
  padding: 9px 14px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line-2);
  background: var(--surface-2);
  color: var(--ink);
  cursor: pointer;
  transition: all 0.15s ease;
}
.slot:hover:not(.is-taken) { border-color: var(--neon); color: var(--neon); }
.slot.is-selected { background: var(--neon); color: #0a0c0e; border-color: var(--neon); }
.slot.is-taken {
  color: var(--muted);
  cursor: not-allowed;
  text-decoration: line-through;
  opacity: 0.55;
}
.m-foot { padding: 0 28px 28px; }

/* Toast */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%) translateY(140%);
  background: var(--elevated);
  color: var(--ink);
  border: 1px solid var(--line-2);
  border-left: 4px solid var(--neon);
  padding: 13px 20px;
  border-radius: var(--r-md);
  font-weight: 600;
  font-size: 0.92rem;
  box-shadow: var(--shadow-2);
  z-index: 80;
  opacity: 0;
  transition: transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1), opacity 0.3s ease;
  max-width: min(90vw, 420px);
}
.toast.is-show { transform: translateX(-50%) translateY(0); opacity: 1; }

@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes pop {
  from { opacity: 0; transform: translateY(14px) scale(0.97); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; scroll-behavior: auto; }
}

@media (max-width: 520px) {
  .nav { display: none; }
  .topbar__inner { gap: 12px; }
  .hero { padding: 56px 0 44px; }
  .hero__stats { gap: 10px; }
  .stat { min-width: calc(50% - 5px); flex: 1; padding: 12px 14px; }
  .roster__head { flex-direction: column; gap: 4px; }
  .grid { grid-template-columns: 1fr; }
  .m-hero { flex-direction: column; text-align: center; }
}

