    return (
      '<button class="card" type="button" data-id="' + t.id +
        '" data-specialties="' + esc(t.specialties.join(",")) + '" aria-label="View profile for ' + esc(t.name) + '">' +
        '<div class="card__top">' +
          '<span class="avatar" style="background:' + t.color + '" aria-hidden="true">' + esc(t.initials) + "</span>" +
          "<div>" +
            '<div class="card__name">' + esc(t.name) + "</div>" +
            '<div class="card__role">' + esc(t.role) + "</div>" +
            '<div class="rating">★ ' + t.rating.toFixed(1) + " <span>(" + t.reviews + ")</span></div>" +
          "</div>" +
        "</div>" +
        '<div class="tags">' + tags + "</div>" +
        '<p class="card__bio">' + esc(t.bio) + "</p>" +
        '<div class="card__cert">' + esc(t.certs) + "</div>" +
        '<div class="card__foot"><span class="btn btn--neon btn--sm btn--block">Book session</span></div>' +
      "</button>"
    );
  }

  grid.innerHTML = TRAINERS.map(cardHTML).join("");

  /* ---------- Filtering ---------- */
  var countEl = $("#result-count");
  var emptyEl = $("#empty-state");
  var activeFilter = "all";

  function applyFilter(filter) {
    activeFilter = filter;
    var visible = 0;
    $$(".card", grid).forEach(function (card) {
      var specs = card.getAttribute("data-specialties").split(",");
      var match = filter === "all" || specs.indexOf(filter) !== -1;
      card.classList.toggle("is-hidden", !match);
      if (match) visible++;
    });
    emptyEl.hidden = visible !== 0;
    countEl.textContent = visible + (visible === 1 ? " coach" : " coaches") +
      (filter === "all" ? "" : " in " + filter);
  }

  $$(".chip").forEach(function (chip) {
    chip.addEventListener("click", function () {
      $$(".chip").forEach(function (c) {
        c.classList.remove("is-active");
        c.setAttribute("aria-pressed", "false");
      });
      chip.classList.add("is-active");
      chip.setAttribute("aria-pressed", "true");
      applyFilter(chip.getAttribute("data-filter"));
    });
  });

  applyFilter("all");

  /* ---------- Modal ---------- */
  var modal = $("#modal");
  var modalBody = $("#modal-body");
  var lastFocused = null;

  function modalHTML(t) {
    var tags = t.specialties.map(function (s) { return '<span class="tag">' + esc(s) + "</span>"; }).join("");
    var ach = t.achievements.map(function (a) { return "<li>" + esc(a) + "</li>"; }).join("");
    var slots = t.slots.map(function (s) {
      return '<button class="slot' + (s.taken ? " is-taken" : "") + '" type="button"' +
        (s.taken ? " disabled aria-disabled=\"true\"" : "") +
        ' data-slot="' + esc(s.label) + '">' + esc(s.label) + "</button>";
    }).join("");

    return (
      '<div class="m-hero">' +
        '<span class="avatar" style="background:' + t.color + '" aria-hidden="true">' + esc(t.initials) + "</span>" +
        "<div>" +
          '<h3 id="modal-name">' + esc(t.name) + "</h3>" +
          '<div class="card__role">' + esc(t.role) + "</div>" +
          '<div class="rating">★ ' + t.rating.toFixed(1) + " <span>(" + t.reviews + " reviews)</span></div>" +
          '<div class="tags">' + tags + "</div>" +
        "</div>" +
      "</div>" +
      '<div class="m-section"><h4>About</h4><p>' + esc(t.full) + "</p>" +
        '<div class="card__cert">' + esc(t.certs) + "</div></div>" +
      '<div class="m-section"><h4>Achievements</h4><ul class="ach-list">' + ach + "</ul></div>" +
      '<div class="m-section"><h4>Available slots</h4><div class="slots" id="slot-group">' + slots + "</div></div>" +
      '<div class="m-foot"><button class="btn btn--neon btn--block" type="button" id="confirm-book" disabled>' +
        "Select a slot to book</button></div>"
    );
  }

  function openModal(id) {
    var t = TRAINERS.filter(function (x) { return x.id === id; })[0];
    if (!t) return;
    lastFocused = document.activeElement;
    modalBody.innerHTML = modalHTML(t);
    modal.hidden = false;
    document.body.style.overflow = "hidden";

    var selected = null;
    var confirmBtn = $("#confirm-book");

    $$(".slot:not(.is-taken)", modalBody).forEach(function (slot) {
      slot.addEventListener("click", function () {
        $$(".slot", modalBody).forEach(function (s) { s.classList.remove("is-selected"); });
        slot.classList.add("is-selected");
        selected = slot.getAttribute("data-slot");
        confirmBtn.disabled = false;
        confirmBtn.textContent = "Book " + t.name.split(" ")[0] + " · " + selected;
      });
    });

    confirmBtn.addEventListener("click", function () {
      if (!selected) return;
      closeModal();
      toast("Session booked with " + t.name + " — " + selected + ". Check your email.");
    });

    var closeBtn = $(".modal__close", modal);
    if (closeBtn) closeBtn.focus();
  }

  function closeModal() {
    modal.hidden = true;
    document.body.style.overflow = "";
    if (lastFocused && lastFocused.focus) lastFocused.focus();
  }

  grid.addEventListener("click", function (e) {
    var card = e.target.closest(".card");
    if (card) openModal(card.getAttribute("data-id"));
  });

  modal.addEventListener("click", function (e) {
    if (e.target.hasAttribute("data-close")) closeModal();
  });

  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && !modal.hidden) closeModal();
  });

  /* ---------- Generic toast buttons ---------- */
  $$("[data-toast]").forEach(function (btn) {
    btn.addEventListener("click", function () { toast(btn.getAttribute("data-toast")); });
  });
})();

snippets.css:
:root {
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --shadow-sm: 0 1px 2px rgba(28, 24, 20, 0.05), 0 4px 14px rgba(28, 24, 20, 0.06);
  --shadow-md: 0 10px 30px rgba(28, 24, 20, 0.12), 0 2px 8px rgba(28, 24, 20, 0.06);
  --shadow-lg: 0 30px 80px rgba(28, 24, 20, 0.32);
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

h1,
h2,
h3 {
  font-family: var(--serif);
  font-weight: 600;
  margin: 0;
  color: var(--ink);
}

button {
  font-family: inherit;
}

.page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 28px clamp(18px, 5vw, 48px) 64px;
}

/* ---------- Masthead ---------- */
.masthead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-mark {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid var(--gold);
  color: var(--gold-d);
  font-family: var(--serif);
  font-weight: 700;
  font-size: 18px;
  letter-spacing: 0.04em;
  background: radial-gradient(circle at 30% 25%, var(--white), var(--gold-soft));
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.brand-eyebrow {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: var(--muted);
}

.brand-name {
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 600;
  color: var(--ink);
}

.masthead-nav {
  display: flex;
  align-items: center;
  gap: 22px;
}

.masthead-link {
  font-size: 13px;
  letter-spacing: 0.02em;
  color: var(--ink-2);
  text-decoration: none;
  padding-bottom: 3px;
  border-bottom: 1px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}

.masthead-link:hover {
  color: var(--ink);
}

.masthead-link.is-active {
  color: var(--gold-d);
  border-color: var(--gold);
}

/* ---------- Buttons ---------- */
.btn {
  border: none;
  cursor: pointer;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.02em;
  padding: 10px 20px;
  transition: transform 0.16s, box-shadow 0.2s, background 0.2s, color 0.2s;
}

.btn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(1px);
}

.btn-ghost {
  background: transparent;
  border: 1px solid var(--line-2);
  color: var(--ink);
}

.btn-ghost:hover {
  border-color: var(--gold);
  color: var(--gold-d);
}

.btn-gold {
  background: linear-gradient(135deg, var(--gold), var(--gold-d));
  color: var(--white);
  box-shadow: var(--shadow-sm);
}

.btn-gold:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

/* ---------- Hero ---------- */
.hero {
  text-align: center;
  padding: 54px 0 36px;
  max-width: 640px;
  margin: 0 auto;
}

.eyebrow {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.3em;
  color: var(--gold-d);
  margin: 0 0 12px;
}

.hero-title {
  font-size: clamp(40px, 7vw, 66px);
  line-height: 1.02;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.hero-sub {
  margin: 18px auto 0;
  max-width: 480px;
  color: var(--ink-2);
  font-size: 15.5px;
}

/* ---------- Toolbar ---------- */
.toolbar {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  margin: 8px 0 30px;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
}

.chip {
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink-2);
  border-radius: 999px;
  padding: 9px 18px;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.02em;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background 0.2s, color 0.2s, border-color 0.2s, transform 0.16s;
}

.chip:hover {
  border-color: var(--gold);
  color: var(--ink);
}

.chip:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.chip.is-active {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--white);
}

.chip-count {
  font-size: 11px;
  font-weight: 600;
  min-width: 18px;
  text-align: center;
  padding: 1px 6px;
  border-radius: 999px;
  background: var(--gold-soft);
  color: var(--gold-d);
}

.chip.is-active .chip-count {
  background: rgba(255, 255, 255, 0.18);
  color: var(--white);
}

.result-line {
  margin: 0;
  font-size: 12px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- Gallery (masonry-ish) ---------- */
.gallery {
  columns: 3 280px;
  column-gap: 18px;
}

.tile {
  position: relative;
  break-inside: avoid;
  margin-bottom: 18px;
  border-radius: var(--r-md);
  overflow: hidden;
  cursor: pointer;
  border: none;
  padding: 0;
  width: 100%;
  display: block;
  box-shadow: var(--shadow-sm);
  background: var(--cream);
  transition: transform 0.28s cubic-bezier(0.2, 0.7, 0.2, 1), box-shadow 0.28s;
  animation: tile-in 0.4s ease both;
}

@keyframes tile-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.tile:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.tile:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

.tile-art {
  width: 100%;
  display: block;
  position: relative;
}

.tile-art::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(28, 24, 20, 0.72));
  opacity: 0;
  transition: opacity 0.28s;
}

.tile:hover .tile-art::after,
.tile:focus-visible .tile-art::after {
  opacity: 1;
}

.tile-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--white);
  background: rgba(28, 24, 20, 0.4);
  backdrop-filter: blur(6px);
  padding: 5px 11px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.25);
  z-index: 2;
}

.tile-cap {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 16px;
  z-index: 2;
  text-align: left;
  transform: translateY(8px);
  opacity: 0;
  transition: transform 0.28s, opacity 0.28s;
}

.tile:hover .tile-cap,
.tile:focus-visible .tile-cap {
  transform: translateY(0);
  opacity: 1;
}

.tile-service {
  font-family: var(--serif);
  font-size: 21px;
  font-weight: 600;
  color: var(--white);
  line-height: 1.1;
}

.tile-stylist {
  margin-top: 3px;
  font-size: 12px;
  letter-spacing: 0.04em;
  color: var(--gold-soft);
}

/* ---------- Empty ---------- */
.empty {
  text-align: center;
  color: var(--muted);
  font-size: 14px;
  padding: 48px 0;
}

.link-btn {
  background: none;
  border: none;
  color: var(--gold-d);
  cursor: pointer;
  font: inherit;
  text-decoration: underline;
  text-underline-offset: 3px;
  padding: 0;
}

.link-btn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

/* ---------- Footer ---------- */
.foot {
  margin-top: 56px;
  padding-top: 22px;
  border-top: 1px solid var(--line);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
  font-size: 12px;
  letter-spacing: 0.06em;
  color: var(--muted);
}

.foot-dot {
  color: var(--gold);
}

/* ---------- Lightbox ---------- */
.lightbox {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: clamp(16px, 4vw, 48px);
}

.lightbox[hidden] {
  display: none;
}

.lightbox-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(20, 16, 12, 0.74);
  backdrop-filter: blur(4px);
  animation: fade-in 0.25s ease;
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.lightbox-panel {
  position: relative;
  z-index: 2;
  width: min(760px, 100%);
  background: var(--white);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  animation: pop-in 0.32s cubic-bezier(0.2, 0.7, 0.2, 1);
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.lb-figure {
  margin: 0;
}

.lb-stage {
  width: 100%;
  aspect-ratio: 16 / 11;
}

.lb-caption {
  padding: 24px 28px 26px;
  border-top: 1px solid var(--line);
}

.lb-cat {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.24em;
  color: var(--gold-d);
}

.lb-service {
  font-size: 32px;
  font-weight: 600;
  line-height: 1.05;
  margin: 6px 0 2px;
}

.lb-stylist {
  margin: 0;
  color: var(--ink-2);
  font-size: 14px;
}

.lb-stylist strong {
  font-weight: 600;
}

.lb-actions {
  margin-top: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.lb-index {
  font-size: 12px;
  letter-spacing: 0.14em;
  color: var(--muted);
}

.lb-close,
.lb-nav {
  position: absolute;
  z-index: 3;
  border: none;
  cursor: pointer;
  background: rgba(255, 255, 255, 0.92);
  color: var(--ink);
  border-radius: 50%;
  display: grid;
  place-items: center;
  box-shadow: var(--shadow-sm);
  transition: background 0.2s, transform 0.16s, color 0.2s;
}

.lb-close:focus-visible,
.lb-nav:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.lb-close {
  top: 14px;
  right: 14px;
  width: 38px;
  height: 38px;
  font-size: 24px;
  line-height: 1;
}

.lb-close:hover {
  background: var(--ink);
  color: var(--white);
}

.lb-nav {
  top: calc(50% - 60px);
  width: 46px;
  height: 46px;
  font-size: 28px;
  line-height: 1;
}

.lb-nav:hover {
  background: var(--gold);
  color: var(--white);
  transform: scale(1.06);
}

.lb-prev {
  left: 16px;
}

.lb-next {
  right: 16px;
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 30px;
  transform: translateX(-50%) translateY(20px);
  z-index: 80;
  background: var(--ink);
  color: var(--white);
  padding: 13px 22px;
  border-radius: 999px;
  font-size: 13.5px;
  letter-spacing: 0.01em;
  box-shadow: var(--shadow-md);
  border: 1px solid rgba(176, 141, 87, 0.5);
  display: flex;
  align-items: center;
  gap: 10px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s, transform 0.3s;
}

.toast[hidden] {
  display: none;
}

.toast.is-visible {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

.toast::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.3);
}

/* ---------- Responsive ---------- */
@media (max-width: 820px) {
  .gallery {
    columns: 2 220px;
  }
}

@media (max-width: 520px) {
  .masthead {
    justify-content: center;
    text-align: center;
  }

  .masthead-nav {
    gap: 16px;
  }

  .masthead-link:not(.is-active) {
    display: none;
  }

  .hero {
    padding: 36px 0 26px;
  }

  .gallery {
    columns: 1;
  }

  .lb-service {
    font-size: 26px;
  }

  .lb-nav {
    top: auto;
    bottom: 16px;
    width: 42px;
    height: 42px;
  }

  .lb-actions {
    justify-content: flex-start;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

