}

:focus-visible {
  outline: 3px solid var(--teal);
  outline-offset: 2px;
  border-radius: 4px;
}

.skip-link {
  position: fixed;
  top: -60px;
  left: 16px;
  z-index: 200;
  background: var(--ink);
  color: #fff;
  padding: 10px 16px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 0.88rem;
  transition: top 0.2s;
}
.skip-link:focus {
  top: 14px;
}

/* ── Buttons ─────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: none;
  border-radius: 999px;
  padding: 13px 24px;
  font: inherit;
  font-weight: 600;
  font-size: 0.94rem;
  cursor: pointer;
  white-space: nowrap;
  transition: transform 0.12s ease, background 0.15s, border-color 0.15s, box-shadow 0.15s, color
    0.15s;
}
.btn:active {
  transform: translateY(1px);
}
.btn-sm {
  padding: 9px 16px;
  font-size: 0.86rem;
}
.btn-block {
  width: 100%;
}
.btn-primary {
  background: var(--teal-d);
  color: #fff;
  box-shadow: 0 6px 16px rgba(12, 122, 115, 0.28);
}
.btn-primary:hover {
  background: var(--teal-700);
  box-shadow: 0 10px 22px rgba(12, 122, 115, 0.34);
  transform: translateY(-1px);
}
.btn-primary:active {
  transform: translateY(0);
}
.btn-ghost {
  background: var(--white);
  border: 1px solid var(--line-2);
  color: var(--ink-2);
}
.btn-ghost:hover {
  border-color: var(--teal);
  color: var(--teal-d);
  background: var(--teal-50);
}

/* ── Brand ───────────────────────────────────────────────── */
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.brand-mark {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: linear-gradient(145deg, var(--teal), var(--teal-700));
  color: #fff;
  box-shadow: 0 6px 14px rgba(12, 122, 115, 0.3);
}
.brand-name {
  font-weight: 800;
  font-size: 1.12rem;
  letter-spacing: -0.02em;
  color: var(--ink);
}
.brand-name.big {
  font-size: 1.5rem;
}
.brand-dot {
  color: var(--teal);
}

/* ── Nav ─────────────────────────────────────────────────── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(241, 247, 246, 0.72);
  backdrop-filter: saturate(160%) blur(14px);
  -webkit-backdrop-filter: saturate(160%) blur(14px);
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s, background 0.2s, box-shadow 0.2s;
}
.nav.is-scrolled {
  border-bottom-color: var(--line);
  background: rgba(241, 247, 246, 0.88);
  box-shadow: 0 6px 24px rgba(16, 50, 47, 0.05);
}
.nav-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 14px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}
.nav-links a[data-link] {
  padding: 8px 14px;
  border-radius: 999px;
  font-weight: 500;
  font-size: 0.92rem;
  color: var(--ink-2);
  transition: background 0.15s, color 0.15s;
}
.nav-links a[data-link]:hover {
  background: var(--teal-50);
  color: var(--teal-d);
}
.nav-links a[data-link].is-active {
  background: var(--teal-50);
  color: var(--teal-d);
  font-weight: 600;
}
.nav-cta {
  display: flex;
  align-items: center;
  gap: 10px;
}
.nav-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 42px;
  height: 42px;
  border: 1px solid var(--line-2);
  border-radius: 12px;
  background: var(--white);
  cursor: pointer;
  padding: 0 10px;
}
.nav-toggle span {
  display: block;
  height: 2px;
  border-radius: 2px;
  background: var(--ink);
  transition: transform 0.22s, opacity 0.22s;
}
.nav-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.nav-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}
.nav-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ── Hero ────────────────────────────────────────────────── */
.hero {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 64px 20px 40px;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 48px;
  align-items: center;
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--white);
  border: 1px solid var(--line);
  color: var(--teal-d);
  font-weight: 600;
  font-size: 0.82rem;
  padding: 7px 14px;
  border-radius: 999px;
  box-shadow: var(--shadow-1);
}
.eyebrow .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 4px rgba(47, 158, 111, 0.18);
  animation: pulse 2.2s ease-in-out infinite;
}
@keyframes pulse {
  0%,
  100% {
    box-shadow: 0 0 0 3px rgba(47, 158, 111, 0.18);
  }
  50% {
    box-shadow: 0 0 0 6px rgba(47, 158, 111, 0.08);
  }
}
.hero-copy h1 {
  margin-top: 18px;
  font-size: clamp(2.1rem, 5vw, 3.2rem);
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.03em;
}
.hero-copy h1 .hl {
  color: var(--teal-d);
  position: relative;
  white-space: nowrap;
}
.hero-copy h1 .hl::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0.06em;
  height: 0.32em;
  background: var(--coral-soft);
  border-radius: 4px;
  z-index: -1;
}
.lede {
  margin-top: 18px;
  max-width: 46ch;
  font-size: 1.08rem;
  color: var(--ink-2);
}
.hero-actions {
  margin-top: 26px;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.stats {
  margin-top: 36px;
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}
.stat {
  flex: 1;
  min-width: 120px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 18px;
  box-shadow: var(--shadow-1);
}
.stat-num {
  font-size: 1.7rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--teal-d);
  line-height: 1;
}
.stat-label {
  margin-top: 6px;
  font-size: 0.82rem;
  color: var(--muted);
}

/* ── Hero card ───────────────────────────────────────────── */
.hero-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px;
  box-shadow: var(--shadow-2);
  position: relative;
}
.hero-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(160deg, rgba(18, 156, 147, 0.4), transparent 60%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}
.hc-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.hc-tag {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
}
.hc-time {
  margin-top: 8px;
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--ink);
}
.hc-doc {
  margin-top: 2px;
  color: var(--ink-2);
  font-size: 0.92rem;
  font-weight: 500;
}
.hc-list {
  list-style: none;
  margin: 18px 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.hc-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.9rem;
  color: var(--ink-2);
}
.tick {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--teal-50);
  color: var(--teal-d);
  font-size: 0.7rem;
  font-weight: 800;
  flex-shrink: 0;
}
.hc-foot {
  margin-top: 14px;
  font-size: 0.78rem;
  color: var(--muted);
  text-align: center;
}

/* ── Badges ──────────────────────────────────────────────── */
.badge {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  white-space: nowrap;
}
.badge.ok {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}
.badge.warn {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}

/* ── Sections ────────────────────────────────────────────── */
.section {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 64px 20px;
}
.section-tint {
  max-width: none;
  background: linear-gradient(180deg, #fff, #f6fbfa);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.section-tint > * {
  max-width: var(--maxw);
  margin-left: auto;
  margin-right: auto;
}
.section-head {
  text-align: center;
  max-width: 620px;
  margin: 0 auto 40px;
}
.kicker {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--teal);
  margin-bottom: 10px;
}
.section-head h2 {
  font-size: clamp(1.6rem, 3.4vw, 2.2rem);
  font-weight: 800;
  letter-spacing: -0.025em;
}
.section-sub {
  margin-top: 12px;
  color: var(--ink-2);
  font-size: 1.02rem;
}

.grid {
  display: grid;
  gap: 18px;
}
.services-grid {
  grid-template-columns: repeat(3, 1fr);
}
.features-grid {
  grid-template-columns: repeat(4, 1fr);
}
.doctors-grid {
  grid-template-columns: repeat(3, 1fr);
}

/* ── Service cards ───────────────────────────────────────── */
.svc {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 24px;
  box-shadow: var(--shadow-1);
  transition: transform 0.18s, box-shadow 0.18s, border-color 0.18s;
}
.svc:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-2);
  border-color: rgba(18, 156, 147, 0.35);
}
.svc-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: var(--teal-50);
  font-size: 1.4rem;
}
.svc h3 {
  margin-top: 16px;
  font-size: 1.08rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.svc p {
  margin-top: 8px;
  font-size: 0.92rem;
  color: var(--ink-2);
}

/* ── Features ────────────────────────────────────────────── */
.feature {
  text-align: left;
  padding: 8px 4px;
}
.feat-icon {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: var(--white);
  border: 1px solid var(--line);
  box-shadow: var(--shadow-1);
  font-size: 1.3rem;
}
.feature h3 {
  margin-top: 14px;
  font-size: 1.02rem;
  font-weight: 700;
}
.feature p {
  margin-top: 6px;
  font-size: 0.9rem;
  color: var(--ink-2);
}

/* ── Doctors ─────────────────────────────────────────────── */
.doc {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 26px 24px;
  text-align: center;
  box-shadow: var(--shadow-1);
  transition: transform 0.18s, box-shadow 0.18s;
}
.doc:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-2);
}
.doc-avatar {
  display: grid;
  place-items: center;
  width: 72px;
  height: 72px;
  margin: 0 auto;
  border-radius: 50%;
  font-weight: 800;
  font-size: 1.3rem;
  color: #fff;
  background: linear-gradient(145deg, var(--teal), var(--teal-700));
  box-shadow: 0 8px 18px rgba(12, 122, 115, 0.28);
}
.doc-avatar.alt {
  background: linear-gradient(145deg, var(--coral), #e85f48);
  box-shadow: 0 8px 18px rgba(255, 122, 102, 0.35);
}
.doc-avatar.warm {
  background: linear-gradient(145deg, #4f6f6a, var(--ink));
  box-shadow: 0 8px 18px rgba(16, 50, 47, 0.3);
}
.doc h3 {
  margin-top: 16px;
  font-size: 1.1rem;
  font-weight: 700;
}
.doc-spec {
  margin-top: 3px;
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--teal-d);
}
.doc-bio {
  margin: 12px 0 16px;
  font-size: 0.9rem;
  color: var(--ink-2);
}

/* ── Testimonial ─────────────────────────────────────────── */
.quote {
  max-width: 760px;
  margin: 0 auto;
  background: linear-gradient(160deg, var(--teal-d), var(--teal-700));
  color: #fff;
  border-radius: var(--r-lg);
  padding: 48px 44px 36px;
  position: relative;
  box-shadow: var(--shadow-3);
  overflow: hidden;
}
.quote-mark {
  position: absolute;
  top: 8px;
  left: 28px;
  font-size: 7rem;
  line-height: 1;
  font-weight: 800;
  color: rgba(255, 255, 255, 0.16);
}
.quote blockquote {
  position: relative;
  font-size: clamp(1.15rem, 2.4vw, 1.45rem);
  font-weight: 500;
  letter-spacing: -0.01em;
  line-height: 1.5;
}
.quote figcaption {
  margin-top: 26px;
  display: flex;
  align-items: center;
  gap: 14px;
}
.q-avatar {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.18);
  font-weight: 700;
  font-size: 0.9rem;
  flex-shrink: 0;
}
.q-meta {
  display: flex;
  flex-direction: column;
  line-height: 1.3;
}
.q-meta strong {
  font-weight: 700;
}
.q-meta span {
  font-size: 0.84rem;
  color: rgba(255, 255, 255, 0.78);
}
.q-stars {
  margin-left: auto;
  color: #ffd66e;
  letter-spacing: 2px;
  font-size: 1rem;
}

/* ── Book CTA ────────────────────────────────────────────── */
.book {
  scroll-margin-top: 84px;
}
.book-card {
  display: grid;
  grid-template-columns: 1fr 360px;
  gap: 40px;
  align-items: center;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 40px;
  box-shadow: var(--shadow-2);
}
.book-copy h2 {
  font-size: clamp(1.6rem, 3.4vw, 2.1rem);
  font-weight: 800;
  letter-spacing: -0.025em;
}
.book-copy p {
  margin-top: 12px;
  color: var(--ink-2);
  font-size: 1.02rem;
  max-width: 42ch;
}
.book-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.field span {
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--ink-2);
}
.field input,
.field select {
  font: inherit;
  font-size: 0.94rem;
  color: var(--ink);
  background: var(--bg);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 12px 14px;
  transition: border-color 0.15s, background 0.15s, box-shadow 0.15s;
}
.field input::placeholder {
  color: var(--muted);
}
.field input:focus,
.field select:focus {
  outline: none;
  border-color: var(--teal);
  background: var(--white);
  box-shadow: 0 0 0 3px rgba(18, 156, 147, 0.15);
}
.field input.invalid {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(212, 80, 62, 0.14);
}
.book-fine {
  font-size: 0.78rem;
  color: var(--muted);
  text-align: center;
}

/* ── Footer ──────────────────────────────────────────────── */
.footer {
  background: var(--ink);
  color: rgba(255, 255, 255, 0.82);
  margin-top: 40px;
  scroll-margin-top: 84px;
}
.footer-grid {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 52px 20px 36px;
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 40px;
}
.footer .brand-name {
  color: #fff;
}
.footer .brand-dot {
  color: var(--coral);
}
.foot-brand p {
  margin-top: 14px;
  font-size: 0.92rem;
  max-width: 32ch;
  color: rgba(255, 255, 255, 0.66);
}
.foot-col h4 {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: rgba(255, 255, 255, 0.55);
  margin-bottom: 14px;
}
.foot-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.foot-col li {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  font-size: 0.9rem;
}
.foot-col a {
  transition: color 0.15s;
}
.foot-col a:hover {
  color: #fff;
}
.closed {
  color: var(--coral);
}
.footer-bar {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}
.footer-bar > * {
  display: block;
}
.footer-bar {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 20px 20px 36px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-size: 0.84rem;
  color: rgba(255, 255, 255, 0.55);
}
.footer-bar a:hover {
  color: #fff;
}

/* ── Toast ───────────────────────────────────────────────── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%) translateY(10px);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 150;
  max-width: 90vw;
  opacity: 0;
  transition: opacity 0.2s, transform 0.2s;
}
.toast:not([hidden]) {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ── Reveal on scroll ────────────────────────────────────── */
.reveal {
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.reveal.is-in {
  opacity: 1;
  transform: none;
}
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
  .eyebrow .dot {
    animation: none;
  }
}

/* ── Responsive ──────────────────────────────────────────── */
@media (max-width: 920px) {
  .hero-grid {
    grid-template-columns: 1fr;
    gap: 36px;
  }
  .hero-card {
    max-width: 420px;
  }
  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .book-card {
    grid-template-columns: 1fr;
    gap: 28px;
  }
}

@media (max-width: 760px) {
  .services-grid,
  .doctors-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .nav-links {
    position: absolute;
    top: calc(100% + 8px);
    right: 20px;
    left: 20px;
    flex-direction: column;
    align-items: stretch;
    gap: 4px;
    background: var(--white);
    border: 1px solid var(--line);
    border-radius: var(--r-md);
    padding: 10px;
    box-shadow: var(--shadow-2);
    transform-origin: top;
    transform: scaleY(0.96);
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.18s, transform 0.18s, visibility 0.18s;
  }
  .nav-links.is-open {
    opacity: 1;
    visibility: visible;
    transform: scaleY(1);
  }
  .nav-links a[data-link] {
    padding: 12px 14px;
  }
  .nav-toggle {
    display: flex;
  }
  .nav-cta .btn-sm {
    display: none;
  }
}

@media (max-width: 520px) {
  .hero {
    padding: 40px 18px 28px;
  }
  .section {
    padding: 48px 18px;
  }
  .services-grid,
  .doctors-grid,
  .features-grid {
    grid-template-columns: 1fr;
  }
  .stats {
    gap: 10px;
  }
  .stat {
    min-width: 0;
    padding: 14px;
  }
