// ── Toast ────────────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2800);
}

// ── Sticky nav shadow on scroll ──────────────────────────────────────────────
const nav = document.getElementById("nav");
const onScroll = () => nav.classList.toggle("is-scrolled", window.scrollY > 8);
onScroll();
window.addEventListener("scroll", onScroll, { passive: true });

// ── Mobile nav toggle ────────────────────────────────────────────────────────
const navToggle = document.getElementById("navToggle");
const navLinks = document.getElementById("navLinks");

function setMenu(open) {
  navLinks.classList.toggle("is-open", open);
  navToggle.setAttribute("aria-expanded", String(open));
  navToggle.setAttribute("aria-label", open ? "Close menu" : "Open menu");
}
navToggle.addEventListener("click", () =>
  setMenu(navToggle.getAttribute("aria-expanded") !== "true")
);

// Smooth-scroll for in-page links + close mobile menu after a tap.
document.querySelectorAll('a[href^="#"]').forEach((link) => {
  link.addEventListener("click", (e) => {
    const id = link.getAttribute("href");
    if (id.length < 2) return;
    const target = document.querySelector(id);
    if (!target) return;
    e.preventDefault();
    target.scrollIntoView({ behavior: "smooth", block: "start" });
    history.replaceState(null, "", id);
    setMenu(false);
  });
});

// Close menu on Escape or when clicking outside.
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") setMenu(false);
});
document.addEventListener("click", (e) => {
  if (!navLinks.classList.contains("is-open")) return;
  if (e.target.closest("#navLinks") || e.target.closest("#navToggle")) return;
  setMenu(false);
});

// ── Reveal on scroll ─────────────────────────────────────────────────────────
const reveals = document.querySelectorAll(".reveal");
if ("IntersectionObserver" in window) {
  const io = new IntersectionObserver(
    (entries, obs) => {
      entries.forEach((entry, i) => {
        if (!entry.isIntersecting) return;
        // Stagger siblings revealing together for a gentle cascade.
        setTimeout(() => entry.target.classList.add("is-in"), (i % 4) * 70);
        obs.unobserve(entry.target);
      });
    },
    { threshold: 0.12, rootMargin: "0px 0px -8% 0px" }
  );
  reveals.forEach((el) => io.observe(el));
} else {
  reveals.forEach((el) => el.classList.add("is-in"));
}

// ── Animated count-up for hero stats ─────────────────────────────────────────
function animateCount(el) {
  const target = Number.parseFloat(el.dataset.count);
  const decimals = Number.parseInt(el.dataset.decimals || "0", 10);
  const suffix = el.dataset.suffix || "";
  const duration = 1400;
  const start = performance.now();
  function frame(now) {
    const p = Math.min((now - start) / duration, 1);
    const eased = 1 - (1 - p) ** 3; // easeOutCubic
    const value = target * eased;
    el.textContent =
      (decimals ? value.toFixed(decimals) : Math.round(value).toLocaleString("en-US")) + suffix;
    if (p < 1) requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

const statEls = document.querySelectorAll(".stat-num[data-count]");
if ("IntersectionObserver" in window) {
  const statIo = new IntersectionObserver(
    (entries, obs) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        animateCount(entry.target);
        obs.unobserve(entry.target);
      });
    },
    { threshold: 0.6 }
  );
  statEls.forEach((el) => statIo.observe(el));
} else {
  statEls.forEach(animateCount);
}

// ── Scroll-spy: highlight the active nav link ────────────────────────────────
const sections = ["services", "why", "doctors", "voices", "book"]
  .map((id) => document.getElementById(id))
  .filter(Boolean);
const linkFor = (id) => document.querySelector(`.nav-links a[href="#${id}"]`);

if ("IntersectionObserver" in window && sections.length) {
  const spy = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        const link = linkFor(entry.target.id);
        if (!link) return;
        if (entry.isIntersecting) {
          document
            .querySelectorAll(".nav-links a.is-active")
            .forEach((a) => a.classList.remove("is-active"));
          link.classList.add("is-active");
        }
      });
    },
    { rootMargin: "-45% 0px -50% 0px" }
  );
  sections.forEach((s) => spy.observe(s));
}

// ── Call button feedback ─────────────────────────────────────────────────────
const callBtn = document.getElementById("callBtn");
if (callBtn) {
  callBtn.addEventListener("click", () => showToast("Calling Northpoint Clinic — (555) 014-8821"));
}

// ── Booking form (illustrative — nothing is sent) ────────────────────────────
const bookForm = document.getElementById("bookForm");
if (bookForm) {
  const nameInput = bookForm.elements.name;
  nameInput.addEventListener("input", () => nameInput.classList.remove("invalid"));

  bookForm.addEventListener("submit", (e) => {
    e.preventDefault();
    if (!nameInput.value.trim()) {
      nameInput.classList.add("invalid");
      nameInput.focus();
      showToast("Please add your name so we know who to expect.");
      return;
    }
    const reason = bookForm.elements.reason.value;
    const first = nameInput.value.trim().split(/\s+/)[0];
    showToast(
      `Thanks, ${first} — your ${reason.toLowerCase()} request is in. We'll text to confirm.`
    );
    bookForm.reset();
  });
}

snippets.css:
:root {
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --sh-sm: 0 1px 2px rgba(28, 24, 20, 0.05);
  --sh-md: 0 10px 30px -16px rgba(28, 24, 20, 0.35);
  --sh-lg: 0 30px 70px -40px rgba(28, 24, 20, 0.45);
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(1200px 600px at 80% -10%, var(--rose-soft), transparent 60%),
    radial-gradient(900px 500px at -10% 110%, var(--gold-soft), transparent 55%),
    var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2 {
  font-family: var(--serif);
  font-weight: 600;
  margin: 0;
}

button, input, select, output {
  font: inherit;
  color: inherit;
}

.wrap {
  max-width: 1060px;
  margin: 0 auto;
  padding: clamp(20px, 5vw, 56px) clamp(14px, 4vw, 32px);
}

.caps {
  font-size: 10.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
}

/* ---- Sheet ---- */
.sheet {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-lg);
  overflow: hidden;
}

.sheet__head {
  padding: clamp(20px, 4vw, 34px) clamp(20px, 4vw, 40px);
  background: linear-gradient(180deg, var(--cream), var(--white));
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
}

.brand__mark {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--ink);
  color: var(--gold-soft);
  font-family: var(--serif);
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.04em;
}

.eyebrow {
  margin: 0;
  font-size: 11px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold-d);
  font-weight: 600;
}

.client {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 16px;
}

.client__avatar {
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(145deg, var(--rose), var(--gold));
  color: var(--white);
  font-family: var(--serif);
  font-weight: 700;
  font-size: 20px;
  box-shadow: inset 0 0 0 3px rgba(255, 255, 255, 0.4);
}

.client__name {
  font-size: clamp(26px, 5vw, 34px);
  line-height: 1.05;
  letter-spacing: 0.01em;
}

.client__sub {
  margin: 4px 0 0;
  color: var(--ink-2);
  font-size: 13.5px;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.client__sub .dot {
  color: var(--line-2);
}

.tag {
  display: inline-block;
  padding: 2px 9px;
  border-radius: 100px;
  background: var(--gold-soft);
  color: var(--gold-d);
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.client__stylist {
  text-align: right;
  display: grid;
  gap: 2px;
  padding-left: 16px;
  border-left: 1px solid var(--line);
}

.client__stylist strong {
  font-family: var(--serif);
  font-size: 18px;
  font-weight: 600;
}

/* ---- Grid ---- */
.grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 0;
}

.panel {
  padding: clamp(20px, 4vw, 32px) clamp(20px, 4vw, 36px);
}

.panel--builder {
  border-right: 1px solid var(--line);
}

.panel--history {
  background: linear-gradient(180deg, var(--white), var(--cream));
}

.panel__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 18px;
}

.panel__title {
  font-size: 22px;
}

.badge {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  padding: 4px 10px;
  border-radius: 100px;
  background: var(--ink);
  color: var(--gold-soft);
}

.badge--ghost {
  background: transparent;
  color: var(--gold-d);
  border: 1px solid var(--line-2);
}

/* ---- Rows ---- */
.rowhead,
.row {
  display: grid;
  grid-template-columns: 1fr 84px 96px 30px;
  align-items: center;
  gap: 10px;
}

.rowhead {
  padding: 0 4px 8px;
}

.rowhead span {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
}

.rows {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.row {
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--white);
  box-shadow: var(--sh-sm);
  transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
  animation: rowin 0.28s ease;
}

@keyframes rowin {
  from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: translateY(0); }
}

.row:hover {
  border-color: var(--line-2);
  box-shadow: var(--sh-md);
}

.row__shade {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}

.swatch {
  flex: none;
  width: 22px;
  height: 22px;
  border-radius: 6px;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.12), var(--sh-sm);
}

.row select,
.row input {
  width: 100%;
  border: 1px solid transparent;
  background: var(--cream);
  border-radius: var(--r-sm);
  padding: 8px 9px;
  font-size: 13.5px;
  transition: border-color 0.16s ease, background 0.16s ease;
  min-width: 0;
}

.row__shade select {
  font-weight: 600;
}

.row input {
  text-align: center;
}

.row select:focus,
.row input:focus {
  outline: none;
  border-color: var(--gold);
  background: var(--white);
}

.row__rm {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: var(--white);
  color: var(--muted);
  cursor: pointer;
  font-size: 16px;
  line-height: 1;
  display: grid;
  place-items: center;
  transition: all 0.16s ease;
}

.row__rm:hover {
  border-color: var(--danger);
  color: var(--danger);
  background: #fdf3f1;
}

.addrow {
  margin-top: 12px;
  width: 100%;
  padding: 11px;
  border: 1px dashed var(--line-2);
  background: transparent;
  border-radius: var(--r-md);
  color: var(--gold-d);
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.16s ease;
}

.addrow:hover {
  border-color: var(--gold);
  background: var(--gold-soft);
}

.addrow__plus {
  font-weight: 700;
}

/* ---- Readout ---- */
.readout {
  margin-top: 22px;
  padding: 16px 18px;
  border-radius: var(--r-md);
  background: var(--ink);
  color: var(--cream);
}

.readout__bar {
  height: 12px;
  border-radius: 100px;
  background: rgba(255, 255, 255, 0.12);
  overflow: hidden;
  display: flex;
  margin-bottom: 14px;
}

.readout__bar span {
  height: 100%;
  transition: width 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.readout__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.stat {
  display: grid;
  gap: 3px;
}

.stat .caps {
  color: rgba(239, 226, 207, 0.6);
}

.stat strong {
  font-family: var(--serif);
  font-size: 21px;
  font-weight: 600;
  letter-spacing: 0.01em;
}

/* ---- Process ---- */
.process {
  margin-top: 22px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.field {
  display: grid;
  gap: 7px;
}

.field--wide {
  grid-column: 1 / -1;
}

.field select,
.field input {
  border: 1px solid var(--line);
  background: var(--white);
  border-radius: var(--r-sm);
  padding: 10px 12px;
  font-size: 14px;
  transition: border-color 0.16s ease, box-shadow 0.16s ease;
}

.field select:focus,
.field input:focus {
  outline: none;
  border-color: var(--gold);
  box-shadow: 0 0 0 3px var(--gold-soft);
}

.stepper {
  display: flex;
  align-items: center;
  gap: 4px;
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  background: var(--white);
  padding: 5px 8px;
}

.stepper output {
  font-family: var(--serif);
  font-size: 20px;
  font-weight: 600;
  min-width: 34px;
  text-align: center;
}

.stepper__unit {
  font-size: 12px;
  color: var(--muted);
  margin-right: auto;
}

.stepper__btn {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: var(--cream);
  cursor: pointer;
  font-size: 16px;
  line-height: 1;
  color: var(--ink-2);
  transition: all 0.14s ease;
}

.stepper__btn:hover {
  border-color: var(--gold);
  color: var(--gold-d);
}

/* ---- Save ---- */
.save {
  margin-top: 22px;
  width: 100%;
  padding: 14px;
  border: none;
  border-radius: var(--r-md);
  background: linear-gradient(135deg, var(--ink), var(--ink-2));
  color: var(--gold-soft);
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0.02em;
  cursor: pointer;
  box-shadow: var(--sh-md);
  transition: transform 0.14s ease, box-shadow 0.14s ease;
}

.save:hover {
  transform: translateY(-1px);
  box-shadow: var(--sh-lg);
}

.save:active {
  transform: translateY(0);
}

/* ---- History ---- */
.history {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 12px;
}

.hist {
  padding: 14px 16px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--white);
  box-shadow: var(--sh-sm);
  transition: border-color 0.16s ease, box-shadow 0.16s ease;
}

.hist:hover {
  border-color: var(--line-2);
  box-shadow: var(--sh-md);
}

.hist__top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}

.hist__date {
  font-family: var(--serif);
  font-size: 16px;
  font-weight: 600;
}

.hist__tech {
  font-size: 11px;
  color: var(--gold-d);
  font-weight: 600;
  letter-spacing: 0.04em;
}

.hist__swatches {
  display: flex;
  gap: 5px;
  margin: 10px 0;
}

.hist__swatches .swatch {
  width: 18px;
  height: 18px;
  border-radius: 5px;
}

.hist__note {
  margin: 0 0 12px;
  font-size: 13px;
  color: var(--ink-2);
  line-height: 1.45;
}

.hist__load {
  border: 1px solid var(--line-2);
  background: transparent;
  color: var(--ink);
  border-radius: 100px;
  padding: 6px 16px;
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.16s ease;
}

.hist__load:hover {
  border-color: var(--gold);
  background: var(--gold-soft);
  color: var(--gold-d);
}

/* ---- Toast ---- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 24px);
  background: var(--ink);
  color: var(--cream);
  padding: 12px 22px;
  border-radius: 100px;
  font-size: 13.5px;
  font-weight: 500;
  box-shadow: var(--sh-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.26s ease, transform 0.26s ease;
  z-index: 50;
  border: 1px solid rgba(239, 226, 207, 0.18);
}

.toast--show {
  opacity: 1;
  transform: translate(-50%, 0);
}

.toast__mark {
  color: var(--gold);
  font-weight: 700;
  margin-right: 6px;
}

/* ---- Responsive ---- */
@media (max-width: 820px) {
  .grid {
    grid-template-columns: 1fr;
  }
  .panel--builder {
    border-right: none;
    border-bottom: 1px solid var(--line);
  }
}

@media (max-width: 520px) {
  .client {
    grid-template-columns: auto 1fr;
    row-gap: 14px;
  }
  .client__stylist {
    grid-column: 1 / -1;
    text-align: left;
    padding-left: 0;
    border-left: none;
    border-top: 1px solid var(--line);
    padding-top: 12px;
    display: flex;
    align-items: baseline;
    gap: 8px;
  }
  .rowhead {
    display: none;
  }
  .row {
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }
  .row__shade {
    grid-column: 1 / -1;
  }
  .row__rm {
    justify-self: end;
  }
  .process {
    grid-template-columns: 1fr;
  }
  .readout__stats {
    grid-template-columns: 1fr;
    gap: 8px;
    text-align: left;
  }
  .stat {
    grid-template-columns: auto 1fr;
    align-items: baseline;
    gap: 8px;
  }
}

