      tech: "Global gloss",
      time: 20,
      note: "Pearl glaze to kill brass between sessions. Cool but not flat.",
      rows: [
        { shade: "Clear", parts: 2, dev: "10 vol" },
        { shade: "10.21", parts: 1, dev: "10 vol" }
      ]
    },
    {
      date: "02 Feb 2026",
      tech: "Root retouch",
      time: 40,
      note: "Regrowth blend, warm natural base. Slightly warmer than target.",
      rows: [
        { shade: "7N", parts: 1, dev: "20 vol" },
        { shade: "6.1", parts: 1, dev: "20 vol" }
      ]
    }
  ];

  // ---- Elements ----
  var $ = function (id) { return document.getElementById(id); };
  var rowsEl = $("rows");
  var historyEl = $("history");
  var toastEl = $("toast");
  var processTimeEl = $("processTime");

  function shadeByCode(code) {
    for (var i = 0; i < SHADES.length; i++) {
      if (SHADES[i].code === code) return SHADES[i];
    }
    return SHADES[0];
  }

  function fmtParts(n) {
    return (Math.round(n * 100) / 100).toString();
  }

  // ---- Render builder rows ----
  function renderRows() {
    rowsEl.innerHTML = "";
    rowsData.forEach(function (r, i) {
      var li = document.createElement("li");
      li.className = "row";

      // Shade cell
      var shadeCell = document.createElement("div");
      shadeCell.className = "row__shade";

      var sw = document.createElement("span");
      sw.className = "swatch";
      sw.style.background = shadeByCode(r.shade).hex;

      var sel = document.createElement("select");
      sel.setAttribute("aria-label", "Shade for row " + (i + 1));
      SHADES.forEach(function (s) {
        var opt = document.createElement("option");
        opt.value = s.code;
        opt.textContent = s.code + " · " + s.name;
        if (s.code === r.shade) opt.selected = true;
        sel.appendChild(opt);
      });
      sel.addEventListener("change", function () {
        r.shade = sel.value;
        sw.style.background = shadeByCode(r.shade).hex;
        update();
      });
      shadeCell.appendChild(sw);
      shadeCell.appendChild(sel);

      // Parts cell
      var partsInput = document.createElement("input");
      partsInput.type = "number";
      partsInput.min = "0";
      partsInput.step = "0.5";
      partsInput.value = r.parts;
      partsInput.setAttribute("aria-label", "Parts for row " + (i + 1));
      partsInput.addEventListener("input", function () {
        var v = parseFloat(partsInput.value);
        r.parts = isNaN(v) || v < 0 ? 0 : v;
        update();
      });

      // Developer cell
      var devSel = document.createElement("select");
      devSel.setAttribute("aria-label", "Developer for row " + (i + 1));
      DEVELOPERS.forEach(function (d) {
        var opt = document.createElement("option");
        opt.value = d;
        opt.textContent = d;
        if (d === r.dev) opt.selected = true;
        devSel.appendChild(opt);
      });
      devSel.addEventListener("change", function () {
        r.dev = devSel.value;
      });

      // Remove cell
      var rm = document.createElement("button");
      rm.type = "button";
      rm.className = "row__rm";
      rm.textContent = "×";
      rm.setAttribute("aria-label", "Remove row " + (i + 1));
      rm.addEventListener("click", function () {
        if (rowsData.length <= 1) {
          toast("At least one shade is required");
          return;
        }
        rowsData.splice(i, 1);
        renderRows();
        update();
      });

      li.appendChild(shadeCell);
      li.appendChild(partsInput);
      li.appendChild(devSel);
      li.appendChild(rm);
      rowsEl.appendChild(li);
    });
  }

  // ---- Update live readout ----
  function update() {
    var total = rowsData.reduce(function (sum, r) { return sum + (r.parts || 0); }, 0);

    $("rowCount").textContent = rowsData.length + (rowsData.length === 1 ? " shade" : " shades");
    $("totalParts").textContent = fmtParts(total) + (total === 1 ? " part" : " parts");
    $("totalGrams").textContent = Math.round(total * GRAMS_PER_PART) + " g";

    // Ratio readout (parts joined by colon, simplified to whole-ish numbers)
    var ratioStr;
    if (total === 0) {
      ratioStr = "—";
    } else {
      ratioStr = rowsData.map(function (r) { return fmtParts(r.parts || 0); }).join(" : ");
    }
    $("ratio").textContent = ratioStr;

    // Ratio bar
    var bar = $("ratioBar");
    bar.innerHTML = "";
    rowsData.forEach(function (r) {
      var seg = document.createElement("span");
      var pct = total > 0 ? ((r.parts || 0) / total) * 100 : 0;
      seg.style.width = pct + "%";
      seg.style.background = shadeByCode(r.shade).hex;
      bar.appendChild(seg);
    });
  }

  // ---- Render history ----
  function renderHistory() {
    historyEl.innerHTML = "";
    history.forEach(function (h, i) {
      var li = document.createElement("li");
      li.className = "hist";

      var top = document.createElement("div");
      top.className = "hist__top";
      var date = document.createElement("span");
      date.className = "hist__date";
      date.textContent = h.date;
      var tech = document.createElement("span");
      tech.className = "hist__tech";
      tech.textContent = h.tech + " · " + h.time + " min";
      top.appendChild(date);
      top.appendChild(tech);

      var sws = document.createElement("div");
      sws.className = "hist__swatches";
      h.rows.forEach(function (r) {
        var s = document.createElement("span");
        s.className = "swatch";
        s.style.background = shadeByCode(r.shade).hex;
        s.title = r.shade;
        sws.appendChild(s);
      });

      var note = document.createElement("p");
      note.className = "hist__note";
      note.textContent = h.note;

      var load = document.createElement("button");
      load.type = "button";
      load.className = "hist__load";
      load.textContent = "Load into builder";
      load.addEventListener("click", function () {
        loadFormula(i);
      });

      li.appendChild(top);
      li.appendChild(sws);
      li.appendChild(note);
      li.appendChild(load);
      historyEl.appendChild(li);
    });
    $("histCount").textContent = history.length + " saved";
  }

  // ---- Load a past formula ----
  function loadFormula(i) {
    var h = history[i];
    rowsData = h.rows.map(function (r) {
      return { shade: r.shade, parts: r.parts, dev: r.dev };
    });
    processTimeEl.textContent = h.time;
    $("resultNote").value = h.note;
    // Set technique select if it matches an option
    var techSel = $("technique");
    for (var k = 0; k < techSel.options.length; k++) {
      if (techSel.options[k].value === h.tech) { techSel.selectedIndex = k; break; }
    }
    renderRows();
    update();
    toast("Loaded formula from " + h.date);
  }

  // ---- Save current formula ----
  function saveFormula() {
    var total = rowsData.reduce(function (sum, r) { return sum + (r.parts || 0); }, 0);
    if (total <= 0) {
      toast("Add some parts before saving");
      return;
    }
    var now = new Date();
    var months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    var dateStr = ("0" + now.getDate()).slice(-2) + " " + months[now.getMonth()] + " " + now.getFullYear();
    var note = $("resultNote").value.trim() || "Saved formula — no note added.";

    history.unshift({
      date: dateStr,
      tech: $("technique").value,
      time: parseInt(processTimeEl.textContent, 10),
      note: note,
      rows: rowsData.map(function (r) { return { shade: r.shade, parts: r.parts, dev: r.dev }; })
    });
    renderHistory();
    toast("Formula saved to Aria's record");
  }

  // ---- Process time stepper ----
  function stepTime(delta) {
    var v = parseInt(processTimeEl.textContent, 10) || 0;
    v = Math.max(5, Math.min(90, v + delta));
    processTimeEl.textContent = v;
  }

  // ---- Toast ----
  var toastTimer;
  function toast(msg) {
    toastEl.innerHTML = '<span class="toast__mark" aria-hidden="true">✓</span>' + msg;
    toastEl.classList.add("toast--show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("toast--show");
    }, 2600);
  }

  // ---- Wire up ----
  $("addRow").addEventListener("click", function () {
    rowsData.push({ shade: "Clear", parts: 1, dev: "20 vol" });
    renderRows();
    update();
  });
  $("timeUp").addEventListener("click", function () { stepTime(5); });
  $("timeDown").addEventListener("click", function () { stepTime(-5); });
  $("saveBtn").addEventListener("click", saveFormula);

  // ---- Init ----
  renderRows();
  update();
  renderHistory();
})();

snippets.css:
:root {
  /* Urban Condo Tower palette */
  --charcoal: #1a1d21;
  --charcoal-2: #21262c;
  --charcoal-3: #2b3138;
  --glass: #5a8fb0;
  --glass-d: #46758f;
  --glass-50: rgba(90, 143, 176, 0.12);
  --chrome: #cfd6dd;
  --chrome-2: #aab3bc;
  --ink: #11141a;
  --paper: #f4f6f8;
  --white: #ffffff;
  --muted: #8b96a1;
  --muted-d: #5d6770;
  --line: rgba(207, 214, 221, 0.16);
  --line-strong: rgba(207, 214, 221, 0.3);
  --ok: #4cae8b;
  --warn: #d6a44b;
  --danger: #d05a4a;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --shadow-sm: 0 2px 8px rgba(8, 11, 15, 0.18);
  --shadow-md: 0 12px 30px rgba(8, 11, 15, 0.35);
  --shadow-lg: 0 30px 70px rgba(8, 11, 15, 0.45);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  background: var(--charcoal);
  color: var(--chrome);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1,
h2,
h3 {
  margin: 0;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--white);
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
}

.section {
  max-width: 1180px;
  margin: 0 auto;
  padding: 96px 28px;
}

.kicker {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--glass);
  margin: 0 0 14px;
}
.kicker-light {
  color: var(--chrome-2);
}

.section-head {
  max-width: 640px;
  margin-bottom: 48px;
}
.section-head h2 {
  font-size: clamp(2rem, 4vw, 2.9rem);
  letter-spacing: -0.03em;
}
.section-lead {
  margin: 16px 0 0;
  color: var(--muted);
  font-size: 1.05rem;
}
.section-lead-light {
  color: var(--chrome-2);
}

/* ---------- TOPBAR ---------- */
.topbar {
  position: sticky;
  top: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 28px;
  background: rgba(26, 29, 33, 0.72);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--line);
}
.brand {
  display: flex;
  align-items: center;
  gap: 11px;
}
.brand-mark {
  width: 26px;
  height: 26px;
  border-radius: 6px;
  background: linear-gradient(145deg, var(--glass), var(--chrome));
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.25), var(--shadow-sm);
}
.brand-name {
  font-weight: 700;
  letter-spacing: 0.18em;
  font-size: 0.85rem;
  color: var(--white);
}
.brand-name em {
  font-style: normal;
  color: var(--glass);
  margin-left: 2px;
}
.nav {
  display: flex;
  align-items: center;
  gap: 28px;
}
.nav a {
  font-size: 0.82rem;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--chrome-2);
  transition: color 0.18s ease;
}
.nav a:hover {
  color: var(--white);
}
.nav-cta {
  padding: 9px 18px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  color: var(--white) !important;
  background: var(--glass-50);
  transition: background 0.18s ease, border-color 0.18s ease;
}
.nav-cta:hover {
  background: rgba(90, 143, 176, 0.24);
  border-color: var(--glass);
}

/* ---------- HERO ---------- */
.hero {
  position: relative;
  overflow: hidden;
  min-height: 88vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 80px 28px 64px;
  background:
    radial-gradient(120% 90% at 80% -10%, rgba(90, 143, 176, 0.28), transparent 55%),
    radial-gradient(80% 60% at 10% 110%, rgba(43, 49, 56, 0.9), transparent 60%),
    linear-gradient(180deg, #12151a 0%, #1a1d21 60%, #15181d 100%);
}
.hero-content {
  position: relative;
  z-index: 3;
  max-width: 1180px;
  margin: 0 auto;
  width: 100%;
}
.eyebrow {
  display: inline-block;
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--glass);
  padding: 7px 14px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  margin: 0 0 24px;
  background: rgba(90, 143, 176, 0.08);
}
.hero h1 {
  font-size: clamp(2.6rem, 7vw, 5rem);
  line-height: 1.02;
  letter-spacing: -0.04em;
}
.hero-sub {
  max-width: 520px;
  margin: 22px 0 0;
  color: var(--chrome-2);
  font-size: 1.12rem;
}
.hero-actions {
  display: flex;
  gap: 14px;
  margin: 34px 0 0;
  flex-wrap: wrap;
}
.hero-stats {
  display: flex;
  gap: 44px;
  margin: 52px 0 0;
  padding-top: 30px;
  border-top: 1px solid var(--line);
  flex-wrap: wrap;
}
.hero-stats dt {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.hero-stats dd {
  margin: 4px 0 0;
  font-size: 1.7rem;
  font-weight: 700;
  color: var(--white);
  letter-spacing: -0.02em;
}

/* tower silhouette */
.hero-tower {
  position: absolute;
  top: -4%;
  right: 4%;
  width: 38%;
  max-width: 460px;
  height: 108%;
  z-index: 1;
  filter: drop-shadow(0 30px 60px rgba(0, 0, 0, 0.5));
}
.tower-core {
  position: absolute;
  inset: 0;
  clip-path: polygon(28% 0, 72% 0, 86% 100%, 14% 100%);
  background: linear-gradient(95deg, #20262d 0%, #2c343c 40%, #161a1f 100%);
}
.tower-glass {
  position: absolute;
  inset: 0;
  clip-path: polygon(28% 0, 72% 0, 86% 100%, 14% 100%);
  background:
    linear-gradient(100deg, rgba(90, 143, 176, 0.55) 0%, rgba(90, 143, 176, 0.05) 30%, rgba(207, 214, 221, 0.18) 60%, rgba(90, 143, 176, 0.4) 100%);
  mix-blend-mode: screen;
  opacity: 0.85;
}
.tower-floors {
  position: absolute;
  inset: 0;
  clip-path: polygon(28% 0, 72% 0, 86% 100%, 14% 100%);
  background-image: repeating-linear-gradient(
    180deg,
    rgba(0, 0, 0, 0.32) 0 2px,
    transparent 2px 22px
  ),
  repeating-linear-gradient(
    90deg,
    rgba(207, 214, 221, 0.1) 0 1px,
    transparent 1px 16px
  );
}
.tower-glow {
  position: absolute;
  top: 30%;
  left: 50%;
  transform: translateX(-50%);
  width: 60%;
  height: 40%;
  background: radial-gradient(closest-side, rgba(90, 143, 176, 0.5), transparent);
  filter: blur(30px);
}

/* ticker */
.ticker {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: rgba(17, 20, 26, 0.5);
  overflow: hidden;
}
.ticker-label {
  position: relative;
  z-index: 2;
  flex: 0 0 auto;
  padding: 14px 20px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--charcoal);
  background: var(--glass);
  white-space: nowrap;
}
.ticker-track {
  display: flex;
  gap: 0;
  white-space: nowrap;
  animation: ticker-scroll 32s linear infinite;
}
.ticker:hover .ticker-track {
  animation-play-state: paused;
}
.ticker-item {
  padding: 14px 26px;
  font-size: 0.82rem;
  letter-spacing: 0.02em;
  color: var(--chrome-2);
  border-right: 1px solid var(--line);
}
.ticker-item b {
  color: var(--white);
  font-weight: 600;
}
.ticker-item .dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  margin-right: 8px;
  vertical-align: middle;
}
.dot-ok { background: var(--ok); box-shadow: 0 0 8px rgba(76, 174, 139, 0.8); }
.dot-low { background: var(--warn); box-shadow: 0 0 8px rgba(214, 164, 75, 0.8); }
.dot-sold { background: var(--muted-d); }
@keyframes ticker-scroll {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

/* ---------- BUTTONS ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-size: 0.86rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  padding: 13px 24px;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.16s ease, background 0.18s ease, box-shadow 0.18s ease;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: linear-gradient(135deg, var(--glass), var(--glass-d));
  color: var(--white);
  box-shadow: 0 8px 24px rgba(90, 143, 176, 0.35);
}
.btn-primary:hover {
  box-shadow: 0 12px 32px rgba(90, 143, 176, 0.5);
  transform: translateY(-1px);
}
.btn-ghost {
  background: transparent;
  border-color: var(--line-strong);
  color: var(--chrome);
}
.btn-ghost:hover {
  border-color: var(--chrome);
  background: rgba(207, 214, 221, 0.06);
}
.btn-block { width: 100%; }

/* ---------- RESIDENCES ---------- */
.res-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 22px;
}
.res-card {
  display: flex;
  flex-direction: column;
  background: var(--charcoal-2);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}
.res-card:hover {
  transform: translateY(-4px);
  border-color: var(--line-strong);
  box-shadow: var(--shadow-md);
}
.res-photo {
  position: relative;
  aspect-ratio: 4 / 3;
  background-size: cover;
  display: flex;
  align-items: flex-end;
  padding: 14px;
}
.res-photo::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(13, 16, 20, 0.65));
}
.res-badges {
  position: relative;
  z-index: 2;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.badge {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  padding: 5px 11px;
  border-radius: 999px;
  background: rgba(17, 20, 26, 0.72);
  border: 1px solid var(--line-strong);
  color: var(--chrome);
  backdrop-filter: blur(6px);
}
.badge-price {
  background: var(--chrome);
  color: var(--ink);
  border-color: transparent;
}
.badge-status-ok { color: var(--ok); }
.badge-status-low { color: var(--warn); }
.res-floorplan {
  position: absolute;
  top: 14px;
  right: 14px;
  z-index: 2;
  width: 56px;
  height: 56px;
  border-radius: 10px;
  background: rgba(17, 20, 26, 0.7);
  border: 1px solid var(--line-strong);
  backdrop-filter: blur(6px);
  padding: 8px;
}
.res-floorplan svg { width: 100%; height: 100%; display: block; }
.res-floorplan svg path,
.res-floorplan svg rect,
.res-floorplan svg line {
  stroke: var(--chrome-2);
  fill: none;
  stroke-width: 2;
}
.res-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
}
.res-name {
  font-size: 1.3rem;
  letter-spacing: -0.02em;
}
.res-spec {
  display: flex;
  gap: 16px;
  font-size: 0.82rem;
  color: var(--muted);
  flex-wrap: wrap;
}
.res-spec span b {
  color: var(--chrome);
  font-weight: 600;
}
.res-desc {
  font-size: 0.9rem;
  color: var(--muted);
  margin: 0;
}
.res-foot {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.res-price {
  font-size: 0.78rem;
  color: var(--muted);
}
.res-price b {
  display: block;
  font-size: 1.35rem;
  color: var(--white);
  letter-spacing: -0.02em;
}
.res-cta {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--glass);
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px 4px;
  font-family: inherit;
  transition: color 0.16s ease;
}
.res-cta:hover { color: var(--chrome); }
.res-cta::after { content: " →"; }

/* ---------- AMENITIES ---------- */
.section-dark {
  max-width: none;
  background:
    radial-gradient(80% 100% at 100% 0, rgba(90, 143, 176, 0.14), transparent 60%),
    var(--charcoal-2);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.section-dark .section-head,
.section-dark .amen-grid {
  max-width: 1180px;
  margin-left: auto;
  margin-right: auto;
}
.amen-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
}
.amen-tile {
  padding: 26px 22px;
  border-radius: var(--r-md);
  background: linear-gradient(160deg, var(--charcoal-3), var(--charcoal));
  border: 1px solid var(--line);
  transition: transform 0.18s ease, border-color 0.18s ease;
}
.amen-tile:hover {
  transform: translateY(-3px);
  border-color: var(--glass);
}
.amen-icon {
  width: 44px;
  height: 44px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  background: var(--glass-50);
  border: 1px solid var(--line-strong);
  margin-bottom: 16px;
}
.amen-icon svg { width: 22px; height: 22px; stroke: var(--glass); fill: none; stroke-width: 1.7; }
.amen-tile h3 {
  font-size: 1.05rem;
  letter-spacing: -0.01em;
}
.amen-tile p {
  margin: 8px 0 0;
  font-size: 0.86rem;
  color: var(--muted);
}

/* ---------- FLOOR SELECTOR ---------- */
.floor-tool {
  display: grid;
  grid-template-columns: 168px 1fr;
  gap: 26px;
  align-items: start;
}
.floor-rail {
  display: flex;
  flex-direction: column;
  gap: 8px;
  position: sticky;
  top: 86px;
}
.floor-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-family: inherit;
  text-align: left;
  padding: 13px 15px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line);
  background: var(--charcoal-2);
  color: var(--chrome-2);
  cursor: pointer;
  transition: all 0.16s ease;
}
.floor-btn:hover {
  border-color: var(--line-strong);
  color: var(--white);
}
.floor-btn[aria-selected="true"] {
  background: linear-gradient(135deg, var(--glass), var(--glass-d));
  border-color: transparent;
  color: var(--white);
  box-shadow: 0 8px 22px rgba(90, 143, 176, 0.3);
}
.floor-btn .fb-name {
  font-weight: 600;
  font-size: 0.86rem;
}
.floor-btn .fb-floors {
  display: block;
  font-size: 0.7rem;
  opacity: 0.7;
  margin-top: 2px;
}
.floor-btn .fb-count {
  flex: 0 0 auto;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.25);
}

.floor-panel {
  min-height: 320px;
}
.fp-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 18px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}
.fp-head h3 {
  font-size: 1.5rem;
  letter-spacing: -0.02em;
}
.fp-head .fp-sub {
  color: var(--muted);
  font-size: 0.86rem;
}
.fp-premium {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--glass);
}
.unit-list {
  display: grid;
  gap: 10px;
}
.unit-row {
  display: grid;
  grid-template-columns: 64px 1fr auto auto;
  align-items: center;
  gap: 16px;
  padding: 15px 18px;
  border-radius: var(--r-md);
  border: 1px solid var(--line);
  background: var(--charcoal-2);
  transition: border-color 0.16s ease, transform 0.16s ease;
}
.unit-row:hover { border-color: var(--line-strong); transform: translateX(2px); }
.unit-row.is-sold { opacity: 0.5; }
.unit-no {
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--white);
}
.unit-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.unit-type { font-size: 0.9rem; color: var(--chrome); font-weight: 500; }
.unit-detail { font-size: 0.78rem; color: var(--muted); }
.unit-price { font-weight: 700; color: var(--white); font-size: 0.98rem; }
.unit-status {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  padding: 5px 11px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  white-space: nowrap;
}
.us-available { color: var(--ok); border-color: rgba(76, 174, 139, 0.4); }
.us-reserved { color: var(--warn); border-color: rgba(214, 164, 75, 0.4); }
.us-sold { color: var(--muted); }
.unit-row .unit-cta {
  grid-column: 1 / -1;
  display: none;
}

/* ---------- REGISTER ---------- */
.register {
  max-width: 1180px;
}
.register-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-radius: var(--r-lg);
  overflow: hidden;
  border: 1px solid var(--line);
  background: var(--charcoal-2);
  box-shadow: var(--shadow-lg);
}
.register-copy {
  padding: 48px;
  background:
    radial-gradient(90% 90% at 0 0, rgba(90, 143, 176, 0.18), transparent 60%),
    linear-gradient(160deg, var(--charcoal-3), var(--charcoal));
}
.register-copy h2 {
  font-size: clamp(1.8rem, 3vw, 2.4rem);
  letter-spacing: -0.03em;
}
.register-perks {
  list-style: none;
  padding: 0;
  margin: 28px 0 0;
  display: grid;
  gap: 12px;
}
.register-perks li {
  position: relative;
  padding-left: 28px;
  color: var(--chrome-2);
  font-size: 0.92rem;
}
.register-perks li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 6px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--glass-50);
  border: 1px solid var(--glass);
  box-shadow: inset 0 0 0 3px var(--charcoal-2);
}
.register-form {
  padding: 48px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  background: var(--charcoal-2);
}
.field {
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.field span {
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--chrome-2);
}
.field input,
.field select {
  font-family: inherit;
  font-size: 0.92rem;
  padding: 12px 14px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line-strong);
  background: var(--charcoal);
  color: var(--white);
  transition: border-color 0.16s ease, box-shadow 0.16s ease;
}
.field input::placeholder { color: var(--muted-d); }
.field input:focus,
.field select:focus {
  outline: none;
  border-color: var(--glass);
  box-shadow: 0 0 0 3px var(--glass-50);
}
.field.invalid input {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(208, 90, 74, 0.2);
}
.form-fine {
  margin: 4px 0 0;
  font-size: 0.74rem;
  color: var(--muted-d);
  text-align: center;
}

/* ---------- FOOTER ---------- */
.footer {
  border-top: 1px solid var(--line);
  padding: 40px 28px;
  background: var(--charcoal-2);
}
.footer-inner {
  max-width: 1180px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: center;
  text-align: center;
}
.footer-brand { letter-spacing: 0.2em; }
.footer p { margin: 0; font-size: 0.84rem; color: var(--muted); }
.footer-fine { color: var(--muted-d) !important; font-size: 0.76rem !important; }

/* ---------- TOAST ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 24px);
  z-index: 80;
  padding: 13px 22px;
  border-radius: 999px;
  background: var(--chrome);
  color: var(--ink);
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: var(--shadow-md);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  max-width: calc(100vw - 40px);
}
.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- RESPONSIVE ---------- */
@media (max-width: 900px) {
  .register-card { grid-template-columns: 1fr; }
  .register-copy, .register-form { padding: 34px; }
  .hero-tower { opacity: 0.45; width: 60%; }
}

@media (max-width: 760px) {
  .nav a:not(.nav-cta) { display: none; }
  .floor-tool { grid-template-columns: 1fr; }
  .floor-rail {
    position: static;
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: 6px;
    -webkit-overflow-scrolling: touch;
  }
  .floor-btn { flex: 0 0 auto; min-width: 150px; }
}

@media (max-width: 520px) {
  .section { padding: 64px 18px; }
  .hero { padding: 64px 18px 0; min-height: auto; }
  .hero h1 { font-size: 2.4rem; }
  .hero-stats { gap: 24px; }
  .hero-stats dd { font-size: 1.35rem; }
  .topbar { padding: 13px 18px; }
  .ticker-label { padding: 11px 14px; font-size: 0.64rem; }
  .res-grid { grid-template-columns: 1fr; }
  .amen-grid { grid-template-columns: 1fr; }
  .unit-row {
    grid-template-columns: 50px 1fr;
    grid-auto-rows: auto;
    row-gap: 8px;
  }
  .unit-price { grid-column: 2; justify-self: start; }
  .unit-status { grid-column: 2; justify-self: start; }
  .register-copy, .register-form { padding: 26px 20px; }
  .hero-tower { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation-duration: 0.001ms !important; scroll-behavior: auto; }
  .ticker-track { animation: none; }
}

