/* Meridian Heights — Urban Condo Tower landing
   Vanilla JS: floor-availability ticker, residences grid, amenities,
   floor selector, register-interest form. No external libraries. */
(function () {
  "use strict";

  /* ---------- toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2600);
  }

  function money(n) {
    return "$" + n.toLocaleString("en-US");
  }

  /* ---------- listing imagery via CSS gradients ---------- */
  var PHOTOS = [
    "linear-gradient(135deg,#2c3a45 0%,#41616f 45%,#8aa9b6 100%)",
    "linear-gradient(150deg,#3a3f46 0%,#5a8fb0 60%,#cfd6dd 100%)",
    "linear-gradient(120deg,#23303a 0%,#365163 50%,#9fb6c2 100%)",
    "linear-gradient(160deg,#2a2e34 0%,#46758f 55%,#b9c6cf 100%)",
    "linear-gradient(135deg,#1f262c 0%,#3d6b86 50%,#cfd6dd 100%)"
  ];

  /* tiny floorplan svg generators */
  function plan(kind) {
    var inner = {
      studio: '<rect x="3" y="3" width="34" height="34"/><line x1="3" y1="24" x2="20" y2="24"/><line x1="20" y1="24" x2="20" y2="37"/>',
      one: '<rect x="3" y="3" width="34" height="34"/><line x1="20" y1="3" x2="20" y2="37"/><line x1="20" y1="20" x2="37" y2="20"/>',
      two: '<rect x="3" y="3" width="34" height="34"/><line x1="3" y1="20" x2="37" y2="20"/><line x1="20" y1="3" x2="20" y2="20"/><line x1="20" y1="20" x2="20" y2="37"/>',
      three: '<rect x="3" y="3" width="34" height="34"/><line x1="3" y1="16" x2="37" y2="16"/><line x1="3" y1="28" x2="37" y2="28"/><line x1="20" y1="16" x2="20" y2="37"/>',
      penthouse: '<rect x="3" y="3" width="34" height="34"/><line x1="3" y1="14" x2="37" y2="14"/><line x1="14" y1="14" x2="14" y2="37"/><line x1="26" y1="14" x2="26" y2="37"/>'
    };
    return '<svg viewBox="0 0 40 40" aria-hidden="true">' + (inner[kind] || inner.one) + "</svg>";
  }

  /* ---------- residences data ---------- */
  var RESIDENCES = [
    {
      name: "The Atrium Studio",
      plan: "studio",
      beds: "Studio",
      bath: "1 Bath",
      sqft: 512,
      from: 489000,
      status: "available",
      statusLabel: "12 left",
      desc: "Floor-to-ceiling glass, integrated kitchen, and a Juliet balcony facing the river."
    },
    {
      name: "The Riverline One",
      plan: "one",
      beds: "1 Bed",
      bath: "1 Bath",
      sqft: 740,
      from: 638000,
      status: "available",
      statusLabel: "21 left",
      desc: "Open-plan living with a dedicated home-office nook and a private corner terrace."
    },
    {
      name: "The Chrome Two",
      plan: "two",
      beds: "2 Bed",
      bath: "2 Bath",
      sqft: 1080,
      from: 945000,
      status: "low",
      statusLabel: "6 left",
      desc: "Split-bedroom layout, chef's island kitchen, and double-aspect skyline views."
    },
    {
      name: "The Cantilever Three",
      plan: "three",
      beds: "3 Bed",
      bath: "2.5 Bath",
      sqft: 1465,
      from: 1390000,
      status: "low",
      statusLabel: "3 left",
      desc: "Wraparound terrace, family room, and a wine wall framed in brushed chrome."
    },
    {
      name: "The Skyline Penthouse",
      plan: "penthouse",
      beds: "4 Bed",
      bath: "4 Bath",
      sqft: 3240,
      from: 4200000,
      status: "low",
      statusLabel: "2 left",
      desc: "Two-story crown residence with a private elevator, plunge pool, and 360° terrace."
    }
  ];

  function statusClass(s) {
    return s === "low" ? "badge-status-low" : "badge-status-ok";
  }

  function renderResidences() {
    var grid = document.getElementById("res-grid");
    if (!grid) return;
    grid.innerHTML = RESIDENCES.map(function (r, i) {
      return (
        '<article class="res-card">' +
          '<div class="res-photo" style="background-image:' + PHOTOS[i % PHOTOS.length] + '">' +
            '<div class="res-floorplan">' + plan(r.plan) + "</div>" +
            '<div class="res-badges">' +
              '<span class="badge badge-price">From ' + money(r.from) + "</span>" +
              '<span class="badge ' + statusClass(r.status) + '">' + r.statusLabel + "</span>" +
            "</div>" +
          "</div>" +
          '<div class="res-body">' +
            '<h3 class="res-name">' + r.name + "</h3>" +
            '<div class="res-spec">' +
              "<span><b>" + r.beds + "</b></span>" +
              "<span><b>" + r.bath + "</b></span>" +
              "<span><b>" + r.sqft.toLocaleString() + "</b> sq ft</span>" +
            "</div>" +
            '<p class="res-desc">' + r.desc + "</p>" +
            '<div class="res-foot">' +
              '<span class="res-price">Starting at<b>' + money(r.from) + "</b></span>" +
              '<button class="res-cta" type="button" data-res="' + r.name + '">View floorplan</button>' +
            "</div>" +
          "</div>" +
        "</article>"
      );
    }).join("");

    grid.querySelectorAll(".res-cta").forEach(function (btn) {
      btn.addEventListener("click", function () {
        toast("Floorplan for " + btn.getAttribute("data-res") + " sent to your sales advisor");
      });
    });
  }

  /* ---------- amenities ---------- */
  var ICONS = {
    rooftop: '<path d="M3 20h18"/><path d="M5 20V9l7-5 7 5v11"/><path d="M9 20v-5h6v5"/>',
    gym: '<path d="M4 8v8M20 8v8M7 6v12M17 6v12M7 12h10"/>',
    concierge: '<circle cx="12" cy="8" r="3"/><path d="M5 21a7 7 0 0 1 14 0"/>',
    pool: '<path d="M3 18c2 0 2-1.5 4-1.5S9 18 11 18s2-1.5 4-1.5S17 18 19 18"/><path d="M3 13c2 0 2-1.5 4-1.5S9 13 11 13"/><path d="M8 16V6a2 2 0 0 1 4 0M16 16V6"/>',
    lounge: '<rect x="3" y="11" width="18" height="7" rx="2"/><path d="M5 11V8a3 3 0 0 1 6 0M19 11V8a3 3 0 0 0-6 0"/>',
    parking: '<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M9 16V8h3a2.5 2.5 0 0 1 0 5H9"/>'
  };
  var AMENITIES = [
    { icon: "rooftop", title: "Sky Terrace", desc: "Rooftop garden, fire lounges, and an outdoor cinema on level 42." },
    { icon: "gym", title: "Performance Gym", desc: "2,400 sq ft of equipment with a glass-walled studio and trainers on call." },
    { icon: "concierge", title: "24/7 Concierge", desc: "Dedicated lobby team for packages, bookings, and resident requests." },
    { icon: "pool", title: "Lap Pool & Spa", desc: "Heated 20-meter infinity lane with sauna, steam, and cold plunge." },
    { icon: "lounge", title: "Residents' Lounge", desc: "Co-working bar, private dining room, and a curated library." },
    { icon: "parking", title: "Smart Parking", desc: "EV-ready spaces with app-controlled valet and secure bike storage." }
  ];

  function renderAmenities() {
    var grid = document.getElementById("amen-grid");
    if (!grid) return;
    grid.innerHTML = AMENITIES.map(function (a) {
      return (
        '<div class="amen-tile">' +
          '<div class="amen-icon"><svg viewBox="0 0 24 24" aria-hidden="true">' + ICONS[a.icon] + "</svg></div>" +
          "<h3>" + a.title + "</h3>" +
          "<p>" + a.desc + "</p>" +
        "</div>"
      );
    }).join("");
  }

  /* ---------- floor selector ---------- */
  var TYPES = ["Studio", "1 Bed", "2 Bed", "3 Bed", "Penthouse"];
  function buildUnits(band) {
    // deterministic pseudo-random so the demo is stable per band
    var seed = band.id.charCodeAt(0) + band.id.charCodeAt(band.id.length - 1);
    var units = [];
    for (var i = 0; i < band.units; i++) {
      var n = band.lowFloor + Math.floor(i / 4);
      var letter = "ABCDEF"[i % 4];
      var t = TYPES[(seed + i) % TYPES.length];
      var roll = (seed * 7 + i * 13) % 10;
      var status = roll < 5 ? "available" : roll < 8 ? "reserved" : "sold";
      var basePrice = 480000 + (TYPES.indexOf(t) * 280000) + ((n - band.lowFloor) * 14000) + band.premium;
      units.push({
        no: n + letter,
        type: t,
        sqft: 500 + TYPES.indexOf(t) * 360,
        price: Math.round(basePrice / 1000) * 1000,
        status: status
      });
    }
    return units;
  }

  var BANDS = [
    { id: "podium", name: "Podium", lowFloor: 3, highFloor: 9, units: 14, premium: 0 },
    { id: "midrise", name: "Mid-Rise", lowFloor: 10, highFloor: 24, units: 16, premium: 90000 },
    { id: "highrise", name: "High-Rise", lowFloor: 25, highFloor: 38, units: 12, premium: 240000 },
    { id: "crown", name: "The Crown", lowFloor: 39, highFloor: 42, units: 6, premium: 620000 }
  ];
  BANDS.forEach(function (b) { b.unitData = buildUnits(b); });

  function availCount(b) {
    return b.unitData.filter(function (u) { return u.status === "available"; }).length;
  }

  function renderFloorRail() {
    var rail = document.getElementById("floor-rail");
    if (!rail) return;
    rail.innerHTML = BANDS.map(function (b, i) {
      return (
        '<button class="floor-btn" role="tab" type="button" id="tab-' + b.id + '"' +
          ' aria-controls="floor-panel" aria-selected="' + (i === 0 ? "true" : "false") + '"' +
          ' data-band="' + b.id + '">' +
          "<span>" +
            '<span class="fb-name">' + b.name + "</span>" +
            '<span class="fb-floors">Floors ' + b.lowFloor + "–" + b.highFloor + "</span>" +
          "</span>" +
          '<span class="fb-count">' + availCount(b) + "</span>" +
        "</button>"
      );
    }).join("");

    rail.querySelectorAll(".floor-btn").forEach(function (btn) {
      btn.addEventListener("click", function () { selectBand(btn.getAttribute("data-band")); });
      btn.addEventListener("keydown", function (e) {
        var btns = Array.prototype.slice.call(rail.querySelectorAll(".floor-btn"));
        var idx = btns.indexOf(btn);
        if (e.key === "ArrowDown" || e.key === "ArrowRight") {
          e.preventDefault();
          btns[(idx + 1) % btns.length].focus();
        } else if (e.key === "ArrowUp" || e.key === "ArrowLeft") {
          e.preventDefault();
          btns[(idx - 1 + btns.length) % btns.length].focus();
        }
      });
    });
  }

  var STATUS_LABEL = { available: "Available", reserved: "Reserved", sold: "Sold" };
  var STATUS_CLASS = { available: "us-available", reserved: "us-reserved", sold: "us-sold" };

  function selectBand(id) {
    var band = BANDS.filter(function (b) { return b.id === id; })[0];
    if (!band) return;

    document.querySelectorAll(".floor-btn").forEach(function (b) {
      b.setAttribute("aria-selected", b.getAttribute("data-band") === id ? "true" : "false");
    });

    var panel = document.getElementById("floor-panel");
    if (!panel) return;
    var avail = availCount(band);
    var rows = band.unitData.map(function (u) {
      var sold = u.status === "sold";
      return (
        '<div class="unit-row' + (sold ? " is-sold" : "") + '">' +
          '<span class="unit-no">' + u.no + "</span>" +
          '<span class="unit-meta">' +
            '<span class="unit-type">' + u.type + "</span>" +
            '<span class="unit-detail">' + u.sqft.toLocaleString() + " sq ft · Floor " + u.no.replace(/[A-F]$/, "") + "</span>" +
          "</span>" +
          '<span class="unit-price">' + money(u.price) + "</span>" +
          '<span class="unit-status ' + STATUS_CLASS[u.status] + '">' + STATUS_LABEL[u.status] + "</span>" +
        "</div>"
      );
    }).join("");

    panel.innerHTML =
      '<div class="fp-head">' +
        "<div>" +
          "<h3>" + band.name + "</h3>" +
          '<span class="fp-sub">Floors ' + band.lowFloor + "–" + band.highFloor + " · " + avail + " of " + band.unitData.length + " available</span>" +
        "</div>" +
        '<span class="fp-premium">' + (band.premium ? "+" + money(band.premium) + " view premium" : "No view premium") + "</span>" +
      "</div>" +
      '<div class="unit-list">' + rows + "</div>";
  }

  /* ---------- availability ticker ---------- */
  function renderTicker() {
    var track = document.getElementById("ticker-track");
    if (!track) return;
    var items = BANDS.map(function (b) {
      var avail = availCount(b);
      var cls = avail === 0 ? "dot-sold" : avail <= 3 ? "dot-low" : "dot-ok";
      var label = avail === 0 ? "Sold out" : avail + " available";
      return '<span class="ticker-item"><span class="dot ' + cls + '"></span><b>' + b.name + "</b> · " + label + " · Floors " + b.lowFloor + "–" + b.highFloor + "</span>";
    });
    items.push('<span class="ticker-item"><span class="dot dot-ok"></span><b>Move-in</b> · Q3 2027</span>');
    items.push('<span class="ticker-item"><span class="dot dot-low"></span><b>Penthouse</b> · 2 remaining</span>');
    // duplicate for a seamless loop
    track.innerHTML = items.join("") + items.join("");
  }

  /* ---------- register form ---------- */
  function bindForm() {
    var form = document.getElementById("register-form");
    if (!form) return;
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var name = document.getElementById("f-name");
      var email = document.getElementById("f-email");
      var ok = true;

      function mark(input, valid) {
        var field = input.closest(".field");
        if (field) field.classList.toggle("invalid", !valid);
        if (!valid) ok = false;
      }

      mark(name, name.value.trim().length >= 2);
      mark(email, /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim()));

      if (!ok) {
        toast("Please check the highlighted fields");
        return;
      }
      var interest = document.getElementById("f-interest").value;
      toast("Thanks " + name.value.trim().split(" ")[0] + " — you're on the " + interest + " priority list");
      form.reset();
      form.querySelectorAll(".field.invalid").forEach(function (f) { f.classList.remove("invalid"); });
    });

    form.querySelectorAll("input").forEach(function (input) {
      input.addEventListener("input", function () {
        var field = input.closest(".field");
        if (field) field.classList.remove("invalid");
      });
    });
  }

  /* ---------- init ---------- */
  document.addEventListener("DOMContentLoaded", function () {
    renderResidences();
    renderAmenities();
    renderTicker();
    renderFloorRail();
    selectBand(BANDS[0].id);
    bindForm();
  });
})();

snippets.css:
:root {
  --navy: #11284a;
  --navy-d: #0a1a33;
  --navy-700: #0e2240;
  --steel: #5b7299;
  --steel-soft: #eaeff7;
  --silver: #dfe5ee;
  --silver-2: #c7d1e1;
  --gold: #c7a86a;
  --gold-d: #a8884a;
  --gold-soft: #f3ebd9;
  --ink: #0d1b30;
  --ink-2: #33425c;
  --muted: #6c7993;
  --bg: #f6f8fc;
  --white: #ffffff;
  --line: rgba(13, 27, 48, 0.1);
  --line-2: rgba(13, 27, 48, 0.18);
  --ok: #2f7a6b;
  --warn: #b5852c;
  --danger: #c2503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --serif: "Fraunces", Georgia, "Times New Roman", serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(13, 27, 48, 0.05), 0 6px 18px rgba(13, 27, 48, 0.07);
  --shadow-2: 0 22px 52px rgba(10, 26, 51, 0.26);
  --shadow-gold: 0 10px 26px rgba(199, 168, 106, 0.34);
  --maxw: 1140px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

.serif {
  font-family: var(--serif);
  font-weight: 500;
  letter-spacing: -0.01em;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  z-index: 100;
  background: var(--navy);
  color: #fff;
  padding: 10px 16px;
  border-radius: 0 0 var(--r-sm) 0;
  font-weight: 600;
  font-size: 0.9rem;
}
.skip-link:focus {
  left: 0;
}

a {
  color: inherit;
}

:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ── Buttons ── */
.btn {
  --btn-pad: 11px 20px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: none;
  border-radius: 999px;
  padding: var(--btn-pad);
  font: inherit;
  font-weight: 600;
  font-size: 0.9rem;
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
  transition: transform 0.12s ease, background 0.18s, border-color 0.18s, box-shadow 0.18s,
    color 0.18s;
}
.btn:active {
  transform: translateY(1px);
}
.btn-sm {
  --btn-pad: 9px 16px;
  font-size: 0.84rem;
}
.btn-lg {
  --btn-pad: 14px 26px;
  font-size: 0.96rem;
}
.btn-block {
  width: 100%;
}

.btn-primary {
  background: var(--navy);
  color: #fff;
  box-shadow: 0 8px 20px rgba(17, 40, 74, 0.22);
}
.btn-primary:hover {
  background: var(--navy-d);
  box-shadow: 0 12px 26px rgba(17, 40, 74, 0.3);
}

.btn-gold {
  background: linear-gradient(135deg, var(--gold), var(--gold-d));
  color: var(--navy-d);
  box-shadow: var(--shadow-gold);
}
.btn-gold:hover {
  filter: brightness(1.04);
  box-shadow: 0 14px 30px rgba(199, 168, 106, 0.42);
}

.btn-ghost {
  background: transparent;
  border: 1px solid var(--line-2);
  color: var(--ink-2);
}
.btn-ghost:hover {
  border-color: var(--navy);
  background: var(--steel-soft);
  color: var(--navy);
}

/* ── Nav ── */
.nav {
  position: sticky;
  top: 0;
  z-index: 40;
  background: rgba(246, 248, 252, 0.82);
  backdrop-filter: saturate(140%) blur(12px);
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s, box-shadow 0.2s, background 0.2s;
}
.nav.is-stuck {
  border-bottom-color: var(--line);
  box-shadow: 0 6px 22px rgba(13, 27, 48, 0.07);
  background: rgba(246, 248, 252, 0.94);
}
.nav-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 14px 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  text-decoration: none;
  color: var(--navy);
}
.brand-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 11px;
  background: linear-gradient(150deg, var(--navy), var(--navy-d));
  color: var(--gold);
  box-shadow: inset 0 0 0 1px rgba(199, 168, 106, 0.4);
}
.brand-name {
  display: flex;
  flex-direction: column;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.16rem;
  line-height: 1.04;
  letter-spacing: -0.01em;
  color: var(--navy);
}
.brand-sub {
  font-family: var(--font);
  font-size: 0.64rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--steel);
  margin-top: 3px;
}
.brand-name.big {
  font-size: 1.42rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  margin-left: auto;
  margin-right: 6px;
}
.nav-links a {
  text-decoration: none;
  font-weight: 600;
  font-size: 0.92rem;
  color: var(--ink-2);
  position: relative;
  padding: 4px 0;
  transition: color 0.15s;
}
.nav-links a::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -2px;
  width: 0;
  height: 2px;
  border-radius: 2px;
  background: var(--gold);
  transition: width 0.2s ease;
}
.nav-links a:hover,
.nav-links a.is-active {
  color: var(--navy);
}
.nav-links a:hover::after,
.nav-links a.is-active::after {
  width: 100%;
}

.nav-cta {
  display: flex;
  align-items: center;
  gap: 12px;
}
.nav-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 42px;
  height: 42px;
  padding: 0 10px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 11px;
  cursor: pointer;
}
.nav-toggle span {
  height: 2px;
  border-radius: 2px;
  background: var(--navy);
  transition: transform 0.22s ease, opacity 0.18s ease;
}
.nav-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.nav-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}
.nav-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ── Hero ── */
.hero {
  position: relative;
  overflow: hidden;
  background: radial-gradient(120% 130% at 15% 0%, #1b3a66 0%, var(--navy) 42%, var(--navy-d) 100%);
  color: #eaf0fb;
  isolation: isolate;
}
.hero-glow {
  position: absolute;
  top: -30%;
  right: -10%;
  width: 60%;
  height: 130%;
  background: radial-gradient(circle, rgba(199, 168, 106, 0.22), transparent 62%);
  filter: blur(4px);
  z-index: -1;
}
.hero-grid-lines {
  position: absolute;
  inset: 0;
  z-index: -1;
  background-image: linear-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: radial-gradient(120% 90% at 70% 10%, #000 0%, transparent 70%);
  -webkit-mask-image: radial-gradient(120% 90% at 70% 10%, #000 0%, transparent 70%);
}
.hero-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 84px 22px 92px;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 52px;
  align-items: center;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #d6c79a;
  background: rgba(199, 168, 106, 0.12);
  border: 1px solid rgba(199, 168, 106, 0.3);
  padding: 7px 14px;
  border-radius: 999px;
}
.eyebrow .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 0 4px rgba(199, 168, 106, 0.2);
}

.display {
  margin-top: 22px;
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(2.3rem, 5vw, 3.5rem);
  line-height: 1.06;
  letter-spacing: -0.02em;
  color: #fff;
}
.display .hl {
  color: var(--gold);
  font-style: italic;
}
.lede {
  margin-top: 20px;
  max-width: 38ch;
  font-size: 1.06rem;
  color: #c4d0e6;
  line-height: 1.62;
}
.hero-actions {
  margin-top: 28px;
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}
.hero .btn-ghost {
  border-color: rgba(255, 255, 255, 0.26);
  color: #eaf0fb;
}
.hero .btn-ghost:hover {
  border-color: var(--gold);
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}

.hero-trust {
  margin-top: 38px;
  display: flex;
  gap: 34px;
  list-style: none;
  flex-wrap: wrap;
}
.hero-trust li {
  display: flex;
  flex-direction: column;
}
.hero-trust strong {
  font-family: var(--serif);
  font-size: 1.7rem;
  font-weight: 600;
  color: #fff;
}
.hero-trust span {
  font-size: 0.82rem;
  color: #9fb0cd;
  margin-top: 2px;
}

/* Hero card */
.hero-card {
  background: rgba(255, 255, 255, 0.97);
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: var(--r-lg);
  padding: 24px;
  color: var(--ink);
  box-shadow: var(--shadow-2);
}
.hc-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.hc-tag {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--steel);
}
.hc-headline {
  margin: 16px 0 4px;
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.hc-num {
  font-family: var(--serif);
  font-size: 2.6rem;
  font-weight: 600;
  line-height: 1;
  color: var(--navy);
}
.hc-unit {
  font-size: 0.88rem;
  color: var(--muted);
  max-width: 14ch;
  line-height: 1.35;
}
.hc-list {
  list-style: none;
  margin: 18px 0;
  border-top: 1px solid var(--line);
}
.hc-list li {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 11px 0;
  border-bottom: 1px solid var(--line);
  font-size: 0.9rem;
  color: var(--ink-2);
}
.hc-list li span:nth-child(2) {
  flex: 1;
}
.hc-list strong {
  font-weight: 600;
  color: var(--navy);
  font-size: 0.86rem;
}
.hc-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--gold);
  flex-shrink: 0;
}
.hc-foot {
  margin-top: 16px;
  font-size: 0.78rem;
  color: var(--muted);
  text-align: center;
}

/* ── Badges ── */
.badge {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 4px 11px;
  border-radius: 999px;
  white-space: nowrap;
}
.badge.ok {
  background: rgba(47, 122, 107, 0.14);
  color: var(--ok);
}
.badge.warn {
  background: rgba(181, 133, 44, 0.16);
  color: var(--warn);
}

/* ── Section scaffolding ── */
.section {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 84px 22px;
}
.section-head {
  max-width: 640px;
  margin: 0 auto 44px;
  text-align: center;
}
.kicker {
  display: inline-block;
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--gold-d);
}
.kicker.light {
  color: var(--gold);
}
.section-head h2 {
  margin-top: 12px;
  font-size: clamp(1.6rem, 3.4vw, 2.3rem);
  color: var(--navy);
}
.section-sub {
  margin-top: 14px;
  font-size: 1.02rem;
  color: var(--ink-2);
  line-height: 1.6;
}

.grid {
  display: grid;
  gap: 18px;
}

/* ── Specialties grid ── */
.specialties-grid {
  grid-template-columns: repeat(3, 1fr);
}
.spec {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 28px 24px;
  box-shadow: var(--shadow-1);
  position: relative;
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.spec::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 3px;
  background: linear-gradient(90deg, var(--navy), var(--gold));
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.28s ease;
}
.spec:hover,
.spec:focus-visible {
  transform: translateY(-4px);
  box-shadow: var(--shadow-2);
  border-color: transparent;
}
.spec:hover::before,
.spec:focus-visible::before {
  transform: scaleX(1);
}
.spec-icon {
  display: grid;
  place-items: center;
  width: 50px;
  height: 50px;
  border-radius: 14px;
  background: var(--steel-soft);
  color: var(--navy);
  margin-bottom: 18px;
  transition: background 0.2s, color 0.2s;
}
.spec:hover .spec-icon {
  background: var(--navy);
  color: var(--gold);
}
.spec h3 {
  font-size: 1.08rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--navy);
}
.spec p {
  margin-top: 9px;
  font-size: 0.92rem;
  color: var(--ink-2);
  line-height: 1.56;
}
.spec-tag {
  display: inline-block;
  margin-top: 16px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--gold-d);
  background: var(--gold-soft);
  padding: 4px 11px;
  border-radius: 999px;
}

/* ── Outcomes band ── */
.band {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, var(--navy-d), var(--navy) 55%, #173356);
  color: #eaf0fb;
  isolation: isolate;
}
.band-glow {
  position: absolute;
  bottom: -40%;
  left: -10%;
  width: 50%;
  height: 140%;
  background: radial-gradient(circle, rgba(199, 168, 106, 0.18), transparent 60%);
  z-index: -1;
}
.band-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 76px 22px;
  display: grid;
  grid-template-columns: 0.95fr 1.05fr;
  gap: 52px;
  align-items: center;
}
.band-copy h2 {
  margin-top: 12px;
  font-size: clamp(1.7rem, 3.4vw, 2.4rem);
}
.serif.light,
.band-copy h2 {
  color: #fff;
}
.band-copy p {
  margin-top: 16px;
  font-size: 1rem;
  color: #c4d0e6;
  line-height: 1.64;
  max-width: 42ch;
}
.band-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.band-stat {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--r-md);
  padding: 24px 22px;
  transition: border-color 0.2s, background 0.2s;
}
.band-stat:hover {
  border-color: rgba(199, 168, 106, 0.5);
  background: rgba(255, 255, 255, 0.08);
}
.stat-num {
  font-family: var(--serif);
  font-size: clamp(2rem, 4vw, 2.7rem);
  font-weight: 600;
  line-height: 1;
  color: var(--gold);
}
.band-stat dd {
  margin-top: 8px;
  font-size: 0.86rem;
  color: #b3c1da;
}

/* ── Accreditation seals ── */
.seals {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.seal {
  display: flex;
  align-items: center;
  gap: 14px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 18px;
  box-shadow: var(--shadow-1);
  transition: transform 0.18s ease, border-color 0.18s;
}
.seal:hover {
  transform: translateY(-3px);
  border-color: var(--gold);
}
.seal-mark {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  flex-shrink: 0;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 0.92rem;
  color: var(--navy);
  background: radial-gradient(circle at 30% 25%, #fff, var(--silver));
  border: 2px solid var(--silver-2);
  box-shadow: inset 0 0 0 3px rgba(199, 168, 106, 0.35);
}
.seal div {
  display: flex;
  flex-direction: column;
}
.seal strong {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1.25;
}
.seal span {
  font-size: 0.78rem;
  color: var(--muted);
  margin-top: 4px;
}

/* ── Surgeon spotlight ── */
.spotlight {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 48px;
  align-items: center;
  background: linear-gradient(135deg, var(--white), var(--steel-soft));
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 44px;
  box-shadow: var(--shadow-1);
}
.spot-portrait {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 280px;
}
.spot-avatar {
  width: 168px;
  height: 168px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 3.4rem;
  color: var(--gold);
  background: linear-gradient(150deg, var(--navy), var(--navy-d));
  box-shadow: inset 0 0 0 2px rgba(199, 168, 106, 0.45), var(--shadow-2);
  z-index: 2;
}
.spot-ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid var(--silver-2);
  z-index: 1;
}
.spot-ring.r1 {
  width: 210px;
  height: 210px;
}
.spot-ring.r2 {
  width: 250px;
  height: 250px;
  border-style: dashed;
  border-color: rgba(199, 168, 106, 0.4);
}
.spot-badge {
  position: absolute;
  bottom: 18px;
  z-index: 3;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--navy-d);
  background: linear-gradient(135deg, var(--gold), var(--gold-d));
  padding: 6px 14px;
  border-radius: 999px;
  box-shadow: var(--shadow-gold);
}
.spot-copy h2 {
  margin-top: 12px;
  font-size: clamp(1.5rem, 3vw, 2.05rem);
  color: var(--navy);
}
.spot-role {
  margin-top: 6px;
  font-weight: 600;
  color: var(--steel);
  font-size: 0.95rem;
}
.spot-bio {
  margin-top: 16px;
  font-size: 1rem;
  color: var(--ink-2);
  line-height: 1.64;
  max-width: 52ch;
}
.spot-stats {
  list-style: none;
  display: flex;
  gap: 30px;
  margin: 22px 0;
  flex-wrap: wrap;
}
.spot-stats li {
  display: flex;
  flex-direction: column;
}
.spot-stats strong {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--navy);
}
.spot-stats span {
  font-size: 0.8rem;
  color: var(--muted);
  margin-top: 2px;
}
.spot-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

/* ── Consult CTA ── */
.consult-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--shadow-2);
  border: 1px solid var(--line);
}
.consult-copy {
  background: linear-gradient(150deg, var(--navy), var(--navy-d));
  color: #eaf0fb;
  padding: 48px 40px;
}
.consult-copy h2 {
  margin-top: 12px;
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  color: #fff;
}
.consult-copy p {
  margin-top: 14px;
  font-size: 1rem;
  color: #c4d0e6;
  line-height: 1.62;
}
.consult-points {
  list-style: none;
  margin: 22px 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.consult-points li {
  display: flex;
  align-items: center;
  gap: 11px;
  font-size: 0.94rem;
  color: #dbe4f4;
}
.consult-points li span {
  color: var(--gold);
  font-size: 0.8rem;
}
.consult-meta {
  margin-top: 20px;
  font-size: 0.84rem;
  color: #9fb0cd;
  border-top: 1px solid rgba(255, 255, 255, 0.14);
  padding-top: 16px;
}
.consult-form {
  background: var(--white);
  padding: 40px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.field > span {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ink-2);
}
.field input,
.field select,
.field textarea {
  font: inherit;
  font-size: 0.94rem;
  color: var(--ink);
  background: var(--bg);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 11px 13px;
  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;
}
.field textarea {
  resize: vertical;
  min-height: 76px;
}
.field input:focus,
.field select:focus,
.field textarea:focus {
  outline: none;
  border-color: var(--navy);
  background: var(--white);
  box-shadow: 0 0 0 3px rgba(17, 40, 74, 0.12);
}
.field input.invalid,
.field select.invalid {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(194, 80, 62, 0.12);
}
.field-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.consult-fine {
  font-size: 0.78rem;
  color: var(--muted);
  text-align: center;
}

/* ── Footer ── */
.footer {
  background: var(--navy-d);
  color: #c4d0e6;
  margin-top: 40px;
}
.footer-grid {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 56px 22px 36px;
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: 40px;
}
.footer .brand-name,
.footer .brand-name .brand-sub {
  color: #fff;
}
.footer .brand-sub {
  color: var(--steel);
}
.foot-brand p {
  margin-top: 14px;
  font-size: 0.92rem;
  line-height: 1.6;
  max-width: 38ch;
  color: #9fb0cd;
}
.foot-col h4 {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 16px;
}
.foot-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  font-size: 0.9rem;
}
.foot-col a {
  text-decoration: none;
  transition: color 0.15s;
}
.foot-col a:hover {
  color: #fff;
}
.foot-col span {
  color: var(--steel);
  display: inline-block;
  min-width: 86px;
}
.footer-bar {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 20px 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
  font-size: 0.82rem;
  color: #8294b3;
}
.footer-bar a {
  text-decoration: none;
  color: var(--gold);
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%) translateY(12px);
  background: var(--navy-d);
  color: #fff;
  padding: 13px 22px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  border: 1px solid rgba(199, 168, 106, 0.4);
  z-index: 60;
  max-width: 90vw;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ── Reveal on scroll ── */
.reveal {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.reveal.in {
  opacity: 1;
  transform: none;
}

/* ── Responsive ── */
@media (max-width: 900px) {
  .hero-inner,
  .band-inner,
  .spotlight,
  .consult-card {
    grid-template-columns: 1fr;
  }
  .hero-inner {
    gap: 38px;
    padding: 64px 22px 72px;
  }
  .spotlight {
    text-align: center;
    gap: 30px;
  }
  .spot-stats,
  .spot-actions {
    justify-content: center;
  }
  .specialties-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .seals {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 520px) {
  .nav-links {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    background: var(--white);
    border-bottom: 1px solid var(--line);
    box-shadow: var(--shadow-1);
    padding: 8px 16px 16px;
    margin: 0;
    transform: translateY(-8px);
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.2s ease, transform 0.2s ease;
  }
  .nav-links.open {
    transform: none;
    opacity: 1;
    pointer-events: auto;
  }
  .nav-links a {
    padding: 12px 4px;
    border-bottom: 1px solid var(--line);
  }
  .nav-links a::after {
    display: none;
  }
  .nav-toggle {
    display: flex;
  }
  .nav-cta .btn-primary {
    display: none;
  }
  .section,
  .band-inner {
    padding-top: 56px;
    padding-bottom: 56px;
  }
  .hero-trust {
    gap: 24px;
  }
  .band-stats,
  .specialties-grid,
  .seals,
  .field-row {
    grid-template-columns: 1fr;
  }
  .spotlight,
  .consult-copy,
  .consult-form {
    padding: 28px 22px;
  }
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 30px;
  }
  .footer-bar {
    justify-content: center;
    text-align: center;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    scroll-behavior: auto !important;
  }
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

