(function () {
  "use strict";

  /* ── Toast helper ── */
  const toastEl = document.getElementById("toast");
  let toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.hidden = false;
    // force reflow so the transition runs every time
    void toastEl.offsetWidth;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => {
      toastEl.classList.remove("show");
      setTimeout(() => {
        toastEl.hidden = true;
      }, 280);
    }, 2600);
  }

  /* ── Sticky nav shadow ── */
  const nav = document.getElementById("nav");
  const onScrollNav = () => {
    if (!nav) return;
    nav.classList.toggle("is-stuck", window.scrollY > 8);
  };
  onScrollNav();
  window.addEventListener("scroll", onScrollNav, { passive: true });

  /* ── Mobile nav toggle ── */
  const navToggle = document.getElementById("navToggle");
  const navLinks = document.getElementById("navLinks");
  function closeMenu() {
    if (!navToggle || !navLinks) return;
    navToggle.setAttribute("aria-expanded", "false");
    navToggle.setAttribute("aria-label", "Open menu");
    navLinks.classList.remove("open");
  }
  if (navToggle && navLinks) {
    navToggle.addEventListener("click", () => {
      const open = navToggle.getAttribute("aria-expanded") === "true";
      navToggle.setAttribute("aria-expanded", String(!open));
      navToggle.setAttribute("aria-label", open ? "Open menu" : "Close menu");
      navLinks.classList.toggle("open", !open);
    });
  }

  /* ── Smooth in-page nav + close mobile menu ── */
  document.querySelectorAll("[data-link]").forEach((link) => {
    link.addEventListener("click", (e) => {
      const href = link.getAttribute("href") || "";
      if (href.startsWith("#")) {
        const target = document.querySelector(href);
        if (target) {
          e.preventDefault();
          target.scrollIntoView({ behavior: "smooth", block: "start" });
          closeMenu();
        }
      }
    });
  });

  /* ── Reveal on scroll ── */
  const revealEls = document.querySelectorAll(".reveal");
  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.14, rootMargin: "0px 0px -40px 0px" }
    );
    revealEls.forEach((el) => io.observe(el));
  } else {
    revealEls.forEach((el) => el.classList.add("in"));
  }

  /* ── Active nav link via section observer ── */
  const links = Array.from(document.querySelectorAll(".nav-links a[href^='#']"));
  const sections = links
    .map((l) => document.querySelector(l.getAttribute("href")))
    .filter(Boolean);
  if ("IntersectionObserver" in window && sections.length) {
    const spy = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const id = entry.target.id;
            links.forEach((l) =>
              l.classList.toggle("is-active", l.getAttribute("href") === "#" + id)
            );
          }
        });
      },
      { rootMargin: "-45% 0px -50% 0px" }
    );
    sections.forEach((s) => spy.observe(s));
  }

  /* ── Animated stat counters ── */
  function animateCount(el) {
    const target = parseFloat(el.dataset.count || "0");
    const suffix = el.dataset.suffix || "";
    const decimals = parseInt(el.dataset.decimals || "0", 10);
    const duration = 1400;
    const start = performance.now();
    function frame(now) {
      const p = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - p, 3); // easeOutCubic
      const value = target * eased;
      const shown =
        decimals > 0
          ? value.toFixed(decimals)
          : Math.round(value).toLocaleString("en-US");
      el.textContent = shown + suffix;
      if (p < 1) requestAnimationFrame(frame);
      else
        el.textContent =
          (decimals > 0 ? target.toFixed(decimals) : target.toLocaleString("en-US")) +
          suffix;
    }
    requestAnimationFrame(frame);
  }
  const statEls = document.querySelectorAll(".stat-num[data-count]");
  if ("IntersectionObserver" in window) {
    const statObs = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            animateCount(entry.target);
            statObs.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.5 }
    );
    statEls.forEach((el) => statObs.observe(el));
  } else {
    statEls.forEach(animateCount);
  }

  /* ── Hero consult desk: reserve a slot (live count) ── */
  const slotCountEl = document.getElementById("slotCount");
  const reserveBtn = document.getElementById("reserveBtn");
  const deskBadge = document.getElementById("deskBadge");
  if (reserveBtn && slotCountEl) {
    reserveBtn.addEventListener("click", () => {
      let count = parseInt(slotCountEl.textContent, 10) || 0;
      if (count <= 0) {
        toast("This week is fully booked — we'll add you to the waitlist.");
        return;
      }
      count -= 1;
      slotCountEl.textContent = String(count);
      if (count === 0) {
        reserveBtn.textContent = "Join the waitlist";
        if (deskBadge) {
          deskBadge.textContent = "Waitlist only";
          deskBadge.classList.remove("ok");
          deskBadge.classList.add("warn");
        }
        toast("Last slot reserved — desk is now waitlist only.");
      } else {
        toast("Consult slot reserved · " + count + " remaining this week.");
      }
    });
  }

  /* ── Surgeon profile button ── */
  const bioBtn = document.getElementById("bioBtn");
  if (bioBtn) {
    bioBtn.addEventListener("click", () => {
      toast("Dr. Vasquez's full profile would open here.");
    });
  }

  /* ── Consultation form ── */
  const form = document.getElementById("consultForm");
  if (form) {
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const name = form.querySelector("[name='name']");
      const email = form.querySelector("[name='email']");
      let ok = true;

      [name, email].forEach((f) => f && f.classList.remove("invalid"));

      if (!name || !name.value.trim()) {
        ok = false;
        if (name) name.classList.add("invalid");
      }
      const emailVal = email ? email.value.trim() : "";
      if (!emailVal || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailVal)) {
        ok = false;
        if (email) email.classList.add("invalid");
      }

      if (!ok) {
        toast("Please add your name and a valid email so we can reply.");
        const firstInvalid = form.querySelector(".invalid");
        if (firstInvalid) firstInvalid.focus();
        return;
      }

      const firstName = name.value.trim().split(/\s+/)[0];
      const specialty = form.querySelector("[name='specialty']");
      const spec = specialty ? specialty.value : "a specialist";
      toast("Thank you, " + firstName + " — your " + spec + " request is in.");
      form.reset();
    });

    form.querySelectorAll("input, select, textarea").forEach((el) => {
      el.addEventListener("input", () => el.classList.remove("invalid"));
    });
  }
})();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --sh-sm: 0 1px 2px rgba(22, 48, 42, 0.06), 0 1px 1px rgba(22, 48, 42, 0.04);
  --sh-md: 0 8px 24px -12px rgba(22, 48, 42, 0.22), 0 2px 6px rgba(22, 48, 42, 0.06);
  --sh-lg: 0 24px 60px -28px rgba(22, 48, 42, 0.4), 0 6px 18px rgba(22, 48, 42, 0.08);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--ivory);
  color: var(--ink);
  font-family: "Inter", system-ui, sans-serif;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3 {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
  color: var(--green-d);
  margin: 0;
  line-height: 1.1;
  letter-spacing: 0.2px;
}

p { margin: 0; }

a { color: inherit; text-decoration: none; }

/* ---------- Shell ---------- */
.shell {
  display: grid;
  grid-template-columns: 256px 1fr;
  min-height: 100vh;
}

/* ---------- Sidebar ---------- */
.sidebar {
  background: linear-gradient(180deg, var(--green) 0%, var(--green-d) 100%);
  color: var(--ivory);
  padding: 26px 20px;
  display: flex;
  flex-direction: column;
  gap: 26px;
  position: sticky;
  top: 0;
  height: 100vh;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: var(--brass);
  color: var(--green-d);
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 700;
  font-size: 16px;
  letter-spacing: 0.5px;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.25);
}

.brand-name {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 22px;
  font-weight: 600;
  color: var(--paper);
}

.nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 14px;
  border-radius: var(--r-sm);
  font-size: 14px;
  font-weight: 500;
  color: rgba(247, 244, 236, 0.74);
  transition: background 0.18s ease, color 0.18s ease;
}

.nav-item .dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: rgba(247, 244, 236, 0.35);
  transition: background 0.18s ease, box-shadow 0.18s ease;
}

.nav-item:hover { background: rgba(255, 255, 255, 0.07); color: var(--paper); }

.nav-item.is-active {
  background: rgba(176, 141, 87, 0.18);
  color: var(--paper);
  box-shadow: inset 0 0 0 1px rgba(176, 141, 87, 0.4);
}

.nav-item.is-active .dot { background: var(--brass); box-shadow: 0 0 0 4px rgba(176, 141, 87, 0.22); }

.side-card {
  margin-top: auto;
  padding: 16px;
  border-radius: var(--r-md);
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.side-card__eyebrow {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1.4px;
  color: var(--brass);
  font-weight: 600;
}

.side-card__big {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 34px;
  font-weight: 700;
  color: var(--paper);
  margin: 2px 0 10px;
}

.side-bar {
  height: 6px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.14);
  overflow: hidden;
}

.side-bar span {
  display: block;
  height: 100%;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--brass-d), var(--brass));
  transition: width 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

.side-card__note {
  margin-top: 10px;
  font-size: 12px;
  color: rgba(247, 244, 236, 0.6);
}

/* ---------- Main ---------- */
.main {
  padding: 30px 38px 40px;
  max-width: 1280px;
  width: 100%;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  flex-wrap: wrap;
  margin-bottom: 26px;
}

.eyebrow {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1.6px;
  color: var(--brass-d);
  font-weight: 600;
  margin-bottom: 4px;
}

.topbar h1 { font-size: 38px; }

.sub { color: var(--muted); font-size: 14px; margin-top: 4px; }

.topbar__right { display: flex; align-items: center; gap: 16px; }

.range {
  display: inline-flex;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 99px;
  padding: 4px;
  box-shadow: var(--sh-sm);
}

.range__btn {
  border: 0;
  background: transparent;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  color: var(--muted);
  padding: 7px 16px;
  border-radius: 99px;
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease;
}

.range__btn:hover { color: var(--green); }

.range__btn.is-active {
  background: var(--green);
  color: var(--paper);
  box-shadow: var(--sh-sm);
}

.range__btn:focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }

.avatar {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--brass-50);
  color: var(--brass-d);
  font-weight: 700;
  font-size: 14px;
  border: 1px solid var(--brass);
}

/* ---------- KPI ---------- */
.kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
  margin-bottom: 22px;
}

.kpi {
  position: relative;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 18px 18px 14px;
  box-shadow: var(--sh-sm);
  overflow: hidden;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.kpi::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: linear-gradient(180deg, var(--brass), var(--brass-d));
}

.kpi:hover { transform: translateY(-3px); box-shadow: var(--sh-md); }

.kpi__label {
  font-size: 12px;
  color: var(--muted);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.6px;
}

.kpi__value {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 36px;
  font-weight: 700;
  color: var(--green-d);
  margin: 6px 0 6px;
  line-height: 1;
  display: flex;
  align-items: baseline;
}

.kpi__value .cur { font-size: 22px; color: var(--brass-d); margin-right: 1px; }
.kpi__value .suf { font-size: 18px; color: var(--ink-2); margin-left: 2px; font-family: "Inter", sans-serif; font-weight: 600; }

.kpi__delta {
  display: inline-block;
  font-size: 12px;
  font-weight: 600;
  padding: 2px 0;
}
.kpi__delta.up { color: var(--ok); }
.kpi__delta.down { color: var(--danger); }
.kpi__delta.good { color: var(--ok); }

.spark {
  position: absolute;
  right: 14px;
  bottom: 12px;
  width: 86px;
  height: 30px;
  opacity: 0.85;
}
.spark svg { width: 100%; height: 100%; display: block; overflow: visible; }
.spark path { stroke: var(--brass); stroke-width: 2; fill: none; }

/* ---------- Grid layout ---------- */
.grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  grid-auto-rows: min-content;
  gap: 18px;
}

.card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px;
  box-shadow: var(--sh-sm);
}

.card--chart { grid-column: 1; grid-row: 1; }
.card--donut { grid-column: 2; grid-row: 1 / span 1; }
.card--table { grid-column: 1; grid-row: 2; }
.card--feed { grid-column: 2; grid-row: 2; }

.card__head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 18px;
}

.card h2 { font-size: 25px; }
.card__sub { font-size: 13px; color: var(--muted); margin-top: 3px; }

.chart-total, .chart-total .cur, .chart-total .suf {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 700;
  color: var(--green-d);
}
.chart-total { font-size: 28px; line-height: 1; white-space: nowrap; }
.chart-total .cur { font-size: 18px; color: var(--brass-d); }
.chart-total .suf { font-size: 16px; }

/* ---------- Trend chart ---------- */
.chart {
  position: relative;
  width: 100%;
}

.chart svg { width: 100%; height: 280px; display: block; overflow: visible; }

.grid-lines line { stroke: var(--line); stroke-width: 1; }

.area {
  opacity: 0;
  transition: opacity 0.6s ease 0.3s;
}
.area.in { opacity: 1; }

.line {
  stroke: var(--brass-d);
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 4px 8px rgba(148, 115, 63, 0.25));
}

.dot {
  fill: var(--paper);
  stroke: var(--brass-d);
  stroke-width: 2;
  cursor: pointer;
  transition: r 0.15s ease;
}
.dot:hover { r: 6; }

.chart-axis {
  display: flex;
  justify-content: space-between;
  margin-top: 8px;
  font-size: 11px;
  color: var(--muted);
  letter-spacing: 0.4px;
}

.chart-tip {
  position: absolute;
  transform: translate(-50%, -118%);
  background: var(--green-d);
  color: var(--paper);
  padding: 6px 10px;
  border-radius: var(--r-sm);
  font-size: 12px;
  font-weight: 600;
  pointer-events: none;
  white-space: nowrap;
  box-shadow: var(--sh-md);
  z-index: 4;
}
.chart-tip::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -5px;
  transform: translateX(-50%);
  border: 5px solid transparent;
  border-top-color: var(--green-d);
  border-bottom: 0;
}
.chart-tip span { color: var(--brass); }

/* ---------- Donut ---------- */
.donut-wrap {
  position: relative;
  width: 200px;
  max-width: 100%;
  margin: 4px auto 16px;
}

.donut { width: 100%; height: auto; transform: rotate(-90deg); }

.donut-track { fill: none; stroke: var(--line); stroke-width: 22; }

.donut-seg {
  fill: none;
  stroke-width: 22;
  stroke-linecap: butt;
  stroke-dasharray: 0 999;
  transition: stroke-dasharray 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}

#seg-active { stroke: var(--green); }
#seg-pending { stroke: var(--brass); }
#seg-closed { stroke: var(--ok); }
#seg-withdrawn { stroke: var(--danger); }

.donut-center {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  text-align: center;
}
.donut-center__num {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 40px;
  font-weight: 700;
  color: var(--green-d);
  line-height: 1;
}
.donut-center__label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1.4px;
  color: var(--muted);
}

.legend { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.legend li {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 13px;
  color: var(--ink-2);
}
.legend .sw { width: 11px; height: 11px; border-radius: 3px; flex: none; }
.legend .lg-val { margin-left: auto; font-weight: 600; color: var(--green-d); }

/* ---------- Leaderboard ---------- */
.table-scroll { overflow-x: auto; }

.lb { width: 100%; border-collapse: collapse; font-size: 14px; }

.lb thead th {
  text-align: left;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--muted);
  font-weight: 600;
  padding: 0 12px 10px;
  border-bottom: 1px solid var(--line);
}
.lb th.num-col, .lb td.num-col { text-align: right; }

.lb tbody td { padding: 12px; border-bottom: 1px solid var(--line); vertical-align: middle; }
.lb tbody tr { transition: background 0.15s ease; }
.lb tbody tr:hover { background: var(--green-50); }
.lb tbody tr:last-child td { border-bottom: 0; }

.rank {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  font-size: 12px;
  font-weight: 700;
  background: var(--ivory);
  color: var(--ink-2);
  border: 1px solid var(--line);
}
.rank.top { background: var(--brass-50); color: var(--brass-d); border-color: var(--brass); }

.agent-cell { display: flex; align-items: center; gap: 11px; }
.agent-av {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  font-size: 12px;
  font-weight: 700;
  color: var(--paper);
  flex: none;
}
.agent-name { font-weight: 600; color: var(--green-d); }
.agent-team { font-size: 12px; color: var(--muted); }

.lb .num-col { font-variant-numeric: tabular-nums; font-weight: 600; color: var(--ink); }

.share { display: flex; align-items: center; gap: 8px; min-width: 110px; }
.share-bar { flex: 1; height: 6px; border-radius: 99px; background: var(--line); overflow: hidden; }
.share-bar span {
  display: block;
  height: 100%;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--green-700), var(--green));
  transition: width 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}
.share-pct { font-size: 12px; color: var(--muted); width: 34px; text-align: right; font-variant-numeric: tabular-nums; }

/* ---------- Feed ---------- */
.feed { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }

.feed li {
  display: grid;
  grid-template-columns: 56px 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--white);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.feed li:hover { transform: translateY(-2px); box-shadow: var(--sh-md); }

.thumb {
  width: 56px;
  height: 48px;
  border-radius: var(--r-sm);
  position: relative;
  overflow: hidden;
  box-shadow: inset 0 0 0 1px rgba(31, 61, 52, 0.08);
}
.thumb::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(255,255,255,0.18), rgba(0,0,0,0.12));
}

.feed-addr { font-weight: 600; color: var(--green-d); font-size: 13.5px; line-height: 1.3; }
.feed-meta { font-size: 12px; color: var(--muted); display: flex; gap: 8px; flex-wrap: wrap; }
.feed-meta .badge {
  font-size: 10.5px;
  font-weight: 600;
  padding: 1px 7px;
  border-radius: 99px;
  background: var(--green-50);
  color: var(--green-700);
}
.feed-price {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 700;
  font-size: 19px;
  color: var(--brass-d);
  text-align: right;
  white-space: nowrap;
}
.feed-when { font-size: 11px; color: var(--muted); text-align: right; }

/* ---------- Foot ---------- */
.foot {
  margin-top: 26px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
  font-size: 12px;
  color: var(--muted);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 20px);
  background: var(--green-d);
  color: var(--paper);
  padding: 11px 18px;
  border-radius: 99px;
  font-size: 13px;
  font-weight: 500;
  box-shadow: var(--sh-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  z-index: 50;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast .tk { color: var(--brass); font-weight: 700; }

@media (prefers-reduced-motion: reduce) {
  * { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
}

/* ---------- Responsive ---------- */
@media (max-width: 1080px) {
  .shell { grid-template-columns: 1fr; }
  .sidebar {
    position: static;
    height: auto;
    flex-direction: row;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;
  }
  .nav { flex-direction: row; flex-wrap: wrap; margin-left: auto; }
  .side-card { display: none; }
  .grid { grid-template-columns: 1fr; }
  .card--chart, .card--donut, .card--table, .card--feed { grid-column: 1; grid-row: auto; }
}

@media (max-width: 760px) {
  .kpis { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 520px) {
  .main { padding: 22px 16px 30px; }
  .topbar h1 { font-size: 30px; }
  .kpis { grid-template-columns: 1fr 1fr; gap: 12px; }
  .kpi__value { font-size: 30px; }
  .spark { display: none; }
  .nav { display: none; }
  .sidebar { padding: 16px; }
  .card { padding: 18px; border-radius: var(--r-md); }
  .card h2 { font-size: 22px; }
  .hide-sm { display: none; }
  .topbar__right { width: 100%; justify-content: space-between; }
  .range__btn { padding: 7px 13px; }
  .feed li { grid-template-columns: 48px 1fr; }
  .feed-price, .feed-when { grid-column: 2; text-align: left; }
}

@media (max-width: 360px) {
  .kpis { grid-template-columns: 1fr; }
}

