    var rect = host.getBoundingClientRect();
    tipEl.hidden = false;
    tipEl.innerHTML = "<span>$" + p.v.toFixed(1) + "M</span> closed";
    tipEl.style.left = (p.x / chartW * rect.width) + "px";
    tipEl.style.top = (p.y / chartH * 280) + "px";
  }
  if (dotsG) {
    dotsG.addEventListener("mouseover", function (e) {
      var d = e.target.getAttribute && e.target.getAttribute("data-i");
      if (d !== null && d !== undefined) chartTipShow(parseInt(d, 10));
    });
    dotsG.addEventListener("mouseout", function () { tipEl.hidden = true; });
  }

  /* ---------------- Donut ---------------- */
  var R = 76, CIRC = 2 * Math.PI * R;
  function buildDonut(status) {
    var keys = ["active", "pending", "closed", "withdrawn"];
    var total = keys.reduce(function (s, k) { return s + status[k]; }, 0);
    var offset = 0;
    keys.forEach(function (k) {
      var seg = document.getElementById("seg-" + k);
      var frac = total ? status[k] / total : 0;
      var len = frac * CIRC;
      // small reset then animate
      seg.setAttribute("stroke-dasharray", "0 " + CIRC);
      seg.setAttribute("stroke-dashoffset", -offset);
      (function (s, l) {
        requestAnimationFrame(function () {
          requestAnimationFrame(function () {
            s.setAttribute("stroke-dasharray", l.toFixed(2) + " " + (CIRC - l).toFixed(2));
          });
        });
      })(seg, len);
      offset += len;
    });

    $("#donutTotal").textContent = total;

    var legend = $("#legend");
    legend.innerHTML = keys.map(function (k) {
      return '<li><span class="sw" style="background:' + STATUS_COLORS[k] + '"></span>' +
        STATUS_LABELS[k] + '<span class="lg-val">' + status[k] + "</span></li>";
    }).join("");
  }

  /* ---------------- Leaderboard ---------------- */
  function buildLeaderboard(agents) {
    var maxVol = Math.max.apply(null, agents.map(function (a) { return a[2]; }));
    var totalVol = agents.reduce(function (s, a) { return s + a[2]; }, 0);
    var body = $("#lbBody");
    body.innerHTML = agents.map(function (a, i) {
      var name = a[0], team = a[1], vol = a[2], units = a[3], gci = a[4], color = a[5];
      var share = totalVol ? Math.round((vol / totalVol) * 100) : 0;
      return "<tr>" +
        '<td><span class="rank ' + (i === 0 ? "top" : "") + '">' + (i + 1) + "</span></td>" +
        '<td><div class="agent-cell">' +
          '<span class="agent-av" style="background:' + color + '">' + initials(name) + "</span>" +
          "<div><div class=\"agent-name\">" + name + "</div><div class=\"agent-team\">" + team + "</div></div>" +
        "</div></td>" +
        '<td class="num-col">$' + vol.toFixed(1) + "M</td>" +
        '<td class="num-col">' + units + "</td>" +
        '<td class="num-col hide-sm">$' + gci + "K</td>" +
        '<td><div class="share"><div class="share-bar"><span style="width:' +
          Math.round((vol / maxVol) * 100) + '%"></span></div><span class="share-pct">' + share + "%</span></div></td>" +
        "</tr>";
    }).join("");
  }

  /* ---------------- Closings feed ---------------- */
  function buildFeed() {
    var feed = $("#feed");
    feed.innerHTML = CLOSINGS.map(function (c) {
      var addr = c[0], hood = c[1], facts = c[2], price = c[3], agent = c[4], grad = c[5], when = c[6];
      return "<li>" +
        '<span class="thumb" style="background:' + grad + '"></span>' +
        "<div>" +
          '<div class="feed-addr">' + addr + "</div>" +
          '<div class="feed-meta"><span class="badge">' + hood + "</span><span>" + facts + "</span><span>· " + agent + "</span></div>" +
        "</div>" +
        "<div><div class=\"feed-price\">" + fmtMoney(price) + "</div><div class=\"feed-when\">" + when + "</div></div>" +
        "</li>";
    }).join("");
  }

  /* ---------------- Render a range ---------------- */
  function render(key, announce) {
    var data = RANGES[key];
    if (!data) return;

    // KPIs
    $all("[data-kpi]").forEach(function (el) {
      var kpi = el.getAttribute("data-kpi");
      var kind = el.getAttribute("data-fmt");
      animateNum(el, data.kpis[kpi], kind);
    });
    // deltas
    $all("[data-delta]").forEach(function (el) {
      var key2 = el.getAttribute("data-delta");
      var d = data.deltas[key2];
      var card = el.closest(".kpi");
      var positiveGood = key2 !== "dom"; // lower DOM is good
      var arrow = d >= 0 ? "▲" : "▼";
      el.textContent = arrow + " " + Math.abs(d) + "%";
      var good = (d >= 0) === positiveGood;
      el.className = "kpi__delta " + (good ? "up" : "down");
    });

    // sparks
    $all("[data-spark]").forEach(function (el) {
      buildSpark(el, data.series);
    });

    // chart total
    var chartTotalEl = $("#chartTotal");
    var totalSeries = data.series.reduce(function (s, v) { return s + v; }, 0);
    if (prefersReduced) {
      chartTotalEl.textContent = totalSeries.toFixed(1);
    } else {
      var ct0 = parseFloat(chartTotalEl.getAttribute("data-cur")) || 0;
      chartTotalEl.setAttribute("data-cur", totalSeries);
      var s0 = performance.now();
      (function () {
        function step(now) {
          var p = Math.min(1, (now - s0) / 700);
          var e = 1 - Math.pow(1 - p, 3);
          chartTotalEl.textContent = (ct0 + (totalSeries - ct0) * e).toFixed(1);
          if (p < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      })();
    }

    buildChart(data);
    buildDonut(data.status);
    buildLeaderboard(data.agents);

    if (announce) toast('Range set to <span class="tk">' + data.label + "</span>");
  }

  /* ---------------- Range toggle ---------------- */
  $all(".range__btn").forEach(function (btn) {
    btn.addEventListener("click", function () {
      $all(".range__btn").forEach(function (b) {
        b.classList.remove("is-active");
        b.removeAttribute("aria-pressed");
      });
      btn.classList.add("is-active");
      btn.setAttribute("aria-pressed", "true");
      render(btn.getAttribute("data-range"), true);
    });
  });

  /* ---------------- Init ---------------- */
  buildFeed();
  render("90", false);
})();

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background:
    radial-gradient(1200px 480px at 50% -8%, rgba(18, 156, 147, 0.1), transparent 60%),
    var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

:focus-visible {
  outline: 3px solid rgba(18, 156, 147, 0.45);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ── Shell ── */
.intake {
  max-width: 680px;
  margin: 0 auto;
  padding: 40px 20px 64px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

/* ── Header ── */
.intake-head {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}
.brand-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: linear-gradient(150deg, var(--teal), var(--teal-700));
  color: #fff;
  font-weight: 800;
  font-size: 1.2rem;
  box-shadow: var(--shadow-1);
}
.brand-name {
  font-weight: 700;
  font-size: 0.96rem;
  letter-spacing: -0.01em;
}
.brand-sub {
  font-size: 0.78rem;
  color: var(--muted);
}
.intake-head h1 {
  font-size: 1.7rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-top: 4px;
}
.lede {
  color: var(--ink-2);
  font-size: 0.94rem;
  max-width: 56ch;
}

/* ── Progress ── */
.progress {
  position: sticky;
  top: 0;
  z-index: 20;
  margin-top: 6px;
  padding: 12px 14px 14px;
  background: rgba(241, 247, 246, 0.86);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  box-shadow: var(--shadow-1);
}
.steps {
  list-style: none;
  display: flex;
  justify-content: space-between;
  gap: 6px;
}
.step {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--muted);
  transition: color 0.2s;
  min-width: 0;
}
.step .dot {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--white);
  border: 1.5px solid var(--line-2);
  font-size: 0.78rem;
  font-weight: 700;
  transition: background 0.2s, border-color 0.2s, color 0.2s;
}
.step.is-active {
  color: var(--teal-700);
}
.step.is-active .dot {
  background: var(--teal-d);
  border-color: var(--teal-d);
  color: #fff;
}
.step.is-done .dot {
  background: var(--teal-50);
  border-color: var(--teal);
  color: var(--teal-d);
}
.step.is-done .dot::after {
  content: "✓";
}
.step.is-done .dot {
  font-size: 0;
}
.step.is-done .dot::after {
  font-size: 0.8rem;
}
.bar {
  margin-top: 12px;
  height: 6px;
  border-radius: 999px;
  background: var(--line);
  overflow: hidden;
}
.bar > span {
  display: block;
  height: 100%;
  width: 25%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--teal), var(--teal-d));
  transition: width 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ── Form & cards ── */
.form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px;
  box-shadow: var(--shadow-1);
  scroll-margin-top: 96px;
}
.card-head {
  margin-bottom: 18px;
}
.card-head h2 {
  font-size: 1.12rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.card-sub {
  font-size: 0.86rem;
  color: var(--muted);
  margin-top: 2px;
}

/* ── Fields ── */
.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.field-wide {
  grid-column: 1 / -1;
}
.field + .field {
  margin-top: 16px;
}
label {
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--ink-2);
}
label em {
  color: var(--danger);
  font-style: normal;
  font-weight: 700;
}
label .opt,
label .quick-label {
  font-weight: 500;
  color: var(--muted);
}

input[type="text"],
input[type="tel"],
input[type="email"],
input[type="date"],
textarea {
  width: 100%;
  font: inherit;
  font-size: 0.92rem;
  color: var(--ink);
  background: #fbfdfc;
  border: 1.5px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 11px 13px;
  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;
}
input::placeholder,
textarea::placeholder {
  color: #9bafab;
}
input:hover,
textarea:hover {
  border-color: rgba(18, 156, 147, 0.5);
}
input:focus,
textarea:focus {
  outline: none;
  background: var(--white);
  border-color: var(--teal);
  box-shadow: 0 0 0 4px rgba(18, 156, 147, 0.14);
}
textarea {
  resize: vertical;
  min-height: 96px;
}

/* invalid glow */
.field.invalid input,
.field.invalid textarea,
.field.invalid .chip-input {
  border-color: var(--danger);
  background: rgba(212, 80, 62, 0.04);
  box-shadow: 0 0 0 4px rgba(212, 80, 62, 0.12);
  animation: nudge 0.3s ease;
}
@keyframes nudge {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  75% { transform: translateX(4px); }
}

.hint {
  font-size: 0.78rem;
  color: var(--muted);
}
.hint.err {
  display: none;
  color: var(--danger);
  font-weight: 600;
}
.field.invalid .hint.err {
  display: block;
}

.textarea-foot {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 10px;
}
.counter {
  font-size: 0.74rem;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* ── Severity slider ── */
.sev-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.sev-pill {
  font-size: 0.78rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 999px;
  background: var(--sev-bg, var(--teal-50));
  color: var(--sev-fg, var(--teal-d));
  transition: background 0.2s, color 0.2s;
  white-space: nowrap;
}
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 8px;
  margin: 14px 0 8px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    var(--sev-track, var(--teal)) var(--sev-pct, 50%),
    var(--line) var(--sev-pct, 50%)
  );
  cursor: pointer;
}
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--sev-track, var(--teal));
  box-shadow: var(--shadow-1);
  transition: transform 0.12s, border-color 0.2s;
}
input[type="range"]::-webkit-slider-thumb:active {
  transform: scale(1.14);
}
input[type="range"]::-moz-range-thumb {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--sev-track, var(--teal));
  box-shadow: var(--shadow-1);
}
input[type="range"]:focus-visible {
  outline: none;
}
input[type="range"]:focus-visible::-webkit-slider-thumb {
  box-shadow: 0 0 0 5px rgba(18, 156, 147, 0.22);
}
.sev-scale {
  display: flex;
  justify-content: space-between;
  font-size: 0.72rem;
  color: var(--muted);
  font-weight: 500;
}

/* ── Chip inputs ── */
.chip-input {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 9px 10px;
  background: #fbfdfc;
  border: 1.5px solid var(--line-2);
  border-radius: var(--r-sm);
  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;
}
.chip-input:focus-within {
  background: var(--white);
  border-color: var(--teal);
  box-shadow: 0 0 0 4px rgba(18, 156, 147, 0.14);
}
.chip-input.danger-input:focus-within {
  border-color: var(--coral);
  box-shadow: 0 0 0 4px rgba(255, 122, 102, 0.18);
}
.chips {
  display: contents;
  list-style: none;
}
.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 6px 5px 12px;
  border-radius: 999px;
  font-size: 0.82rem;
  font-weight: 600;
  background: var(--teal-50);
  color: var(--teal-700);
  animation: pop 0.18s ease;
}
.danger-input .chip {
  background: var(--coral-soft);
  color: #b8412e;
}
@keyframes pop {
  from { transform: scale(0.8); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}
.chip button {
  border: none;
  cursor: pointer;
  width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(16, 50, 47, 0.1);
  color: inherit;
  font-size: 0.9rem;
  line-height: 1;
  transition: background 0.15s;
}
.chip button:hover {
  background: rgba(16, 50, 47, 0.22);
}
.chip-entry {
  flex: 1;
  min-width: 130px;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  padding: 5px 4px !important;
  font-size: 0.88rem;
}
.chip-entry:focus {
  outline: none;
}

.quick-add {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
}
.quick-label {
  font-size: 0.76rem;
  color: var(--muted);
  font-weight: 600;
}
.quick {
  border: 1px solid var(--line-2);
  background: var(--white);
  border-radius: 999px;
  padding: 4px 11px;
  font: inherit;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--ink-2);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s, opacity 0.15s;
}
.quick:hover {
  background: var(--coral-soft);
  border-color: var(--coral);
  color: #b8412e;
}
.quick[hidden] {
  display: none;
}

/* ── Consent ── */
.consent {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 16px;
  border: 1.5px solid var(--line-2);
  border-radius: var(--r-md);
  background: #fbfdfc;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}
.consent:hover {
  border-color: var(--teal);
  background: var(--teal-50);
}
.consent input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}
.consent-box {
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  margin-top: 1px;
  border: 2px solid var(--line-2);
  border-radius: 6px;
  background: #fff;
  display: grid;
  place-items: center;
  transition: background 0.15s, border-color 0.15s;
}
.consent-box::after {
  content: "";
  width: 11px;
  height: 6px;
  border-left: 2.4px solid #fff;
  border-bottom: 2.4px solid #fff;
  transform: rotate(-45deg) scale(0);
  transform-origin: center;
  margin-top: -2px;
  transition: transform 0.15s ease;
}
.consent input:checked + .consent-box {
  background: var(--teal-d);
  border-color: var(--teal-d);
}
.consent input:checked + .consent-box::after {
  transform: rotate(-45deg) scale(1);
}
.consent input:focus-visible + .consent-box {
  box-shadow: 0 0 0 4px rgba(18, 156, 147, 0.22);
}
.consent-text {
  font-size: 0.88rem;
  color: var(--ink-2);
  line-height: 1.45;
}
.consent-text em {
  color: var(--danger);
  font-style: normal;
  font-weight: 700;
}
#sec-consent .hint.err {
  margin-top: 8px;
}
#sec-consent.invalid .consent {
  border-color: var(--danger);
  box-shadow: 0 0 0 4px rgba(212, 80, 62, 0.1);
}
#sec-consent.invalid .hint.err {
  display: block;
}

/* ── Footer / submit ── */
.form-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding-top: 4px;
}
.reassure {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 0.8rem;
  color: var(--muted);
  font-weight: 500;
}
.reassure svg {
  color: var(--teal);
  flex-shrink: 0;
}

.btn {
  border: none;
  border-radius: 12px;
  padding: 12px 22px;
  font: inherit;
  font-weight: 700;
  font-size: 0.9rem;
  cursor: pointer;
  transition: transform 0.12s, background 0.15s, border-color 0.15s, box-shadow 0.15s;
}
.btn:active {
  transform: translateY(1px);
}
.btn.primary {
  background: var(--teal-d);
  color: #fff;
  box-shadow: 0 6px 18px rgba(12, 122, 115, 0.28);
}
.btn.primary:hover {
  background: var(--teal-700);
  box-shadow: 0 8px 22px rgba(12, 122, 115, 0.34);
}
.btn.ghost {
  background: var(--white);
  border: 1px solid var(--line-2);
  color: var(--ink-2);
}
.btn.ghost:hover {
  background: var(--teal-50);
  border-color: var(--teal);
  color: var(--teal-d);
}

/* ── Review summary ── */
.review {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 24px;
  box-shadow: var(--shadow-2);
  animation: rise 0.3s ease;
}
.review[hidden] {
  display: none;
}
@keyframes rise {
  from { transform: translateY(10px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}
.review-head {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 20px;
}
.review-tick {
  flex-shrink: 0;
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}
.review-head h2 {
  font-size: 1.2rem;
  font-weight: 800;
  letter-spacing: -0.01em;
}
.review-sub {
  font-size: 0.86rem;
  color: var(--muted);
}
.review-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
}
.review-grid .row {
  background: var(--white);
  padding: 14px 16px;
}
.review-grid .row.full {
  grid-column: 1 / -1;
}
.review-grid dt {
  font-size: 0.74rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
  margin-bottom: 4px;
}
.review-grid dd {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ink);
  word-break: break-word;
}
.review-grid dd.empty {
  color: var(--muted);
  font-weight: 500;
  font-style: italic;
}
.tag-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 2px;
}
.tag {
  font-size: 0.78rem;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--teal-50);
  color: var(--teal-700);
}
.tag.danger {
  background: var(--coral-soft);
  color: #b8412e;
}
.sev-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 0.84rem;
  font-weight: 700;
}
.sev-chip .swatch {
  width: 12px;
  height: 12px;
  border-radius: 50%;
}
.review-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 20px;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
  display: flex;
  align-items: center;
  gap: 9px;
}
.toast::before {
  content: "✓";
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--ok);
  color: #fff;
  font-size: 0.74rem;
  font-weight: 800;
  flex-shrink: 0;
}

/* ── Responsive ── */
@media (max-width: 520px) {
  .intake {
    padding: 24px 14px 48px;
  }
  .intake-head h1 {
    font-size: 1.42rem;
  }
  .grid-2 {
    grid-template-columns: 1fr;
  }
  .field.field-wide {
    grid-column: auto;
  }
  .step .label {
    display: none;
  }
  .steps {
    justify-content: space-around;
  }
  .review-grid {
    grid-template-columns: 1fr;
  }
  .review-grid .row.full {
    grid-column: auto;
  }
  .form-foot {
    flex-direction: column-reverse;
    align-items: stretch;
  }
  .form-foot .btn.primary {
    width: 100%;
  }
  .review-actions .btn {
    flex: 1;
  }
}

