// ── Toast ──────────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2800);
}

const form = document.getElementById("intake-form");

// ── Reason character counter ──────────────────────────────────────────────
const reason = document.getElementById("reason");
const reasonCount = document.getElementById("reason-count");
reason.addEventListener("input", () => {
  reasonCount.textContent = reason.value.length;
});

// ── Severity slider (live label + colour) ─────────────────────────────────
const severity = document.getElementById("severity");
const sevPill = document.getElementById("sev-pill");

const SEV_BANDS = [
  { max: 3, label: "Mild", track: "#2f9e6f", bg: "rgba(47,158,111,0.14)", fg: "#2f9e6f" },
  { max: 6, label: "Moderate", track: "#d98a2b", bg: "rgba(217,138,43,0.16)", fg: "#b9741f" },
  { max: 8, label: "High", track: "#ff7a66", bg: "#ffe6df", fg: "#b8412e" },
  { max: 10, label: "Severe", track: "#d4503e", bg: "rgba(212,80,62,0.14)", fg: "#d4503e" },
];
function bandFor(v) {
  return SEV_BANDS.find((b) => v <= b.max);
}
function paintSeverity() {
  const v = Number(severity.value);
  const band = bandFor(v);
  const pct = ((v - 1) / 9) * 100;
  severity.style.setProperty("--sev-pct", pct + "%");
  severity.style.setProperty("--sev-track", band.track);
  sevPill.style.setProperty("--sev-bg", band.bg);
  sevPill.style.setProperty("--sev-fg", band.fg);
  sevPill.textContent = v + " · " + band.label;
}
severity.addEventListener("input", paintSeverity);
paintSeverity();

// ── Chip inputs (meds + allergies) ────────────────────────────────────────
function makeChipGroup(inputId, listId, opts) {
  opts = opts || {};
  const input = document.getElementById(inputId);
  const list = document.getElementById(listId);
  const items = [];

  function render() {
    list.innerHTML = "";
    items.forEach((text, i) => {
      const li = document.createElement("li");
      li.className = "chip";
      const span = document.createElement("span");
      span.textContent = text;
      const x = document.createElement("button");
      x.type = "button";
      x.setAttribute("aria-label", "Remove " + text);
      x.textContent = "×";
      x.addEventListener("click", () => {
        items.splice(i, 1);
        render();
        if (opts.onChange) opts.onChange(items);
      });
      li.append(span, x);
      list.appendChild(li);
    });
    if (opts.onChange) opts.onChange(items);
  }

  function add(raw) {
    const text = raw.trim().replace(/\s+/g, " ");
    if (!text) return false;
    const dup = items.some((t) => t.toLowerCase() === text.toLowerCase());
    if (dup) {
      showToast('"' + text + '" is already on the list.');
      return false;
    }
    items.push(text);
    render();
    return true;
  }

  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === ",") {
      e.preventDefault();
      if (add(input.value)) input.value = "";
    } else if (e.key === "Backspace" && input.value === "" && items.length) {
      items.pop();
      render();
    }
  });
  input.addEventListener("blur", () => {
    if (add(input.value)) input.value = "";
  });

  return { items, add: (t) => { if (add(t)) return true; return false; }, focus: () => input.focus() };
}

const meds = makeChipGroup("med-input", "meds-chips");
const allergies = makeChipGroup("allergy-input", "allergies-chips", {
  onChange(items) {
    // Hide quick-add buttons that are already present.
    document.querySelectorAll("#allergy-quick .quick").forEach((b) => {
      const taken = items.some((t) => t.toLowerCase() === b.dataset.add.toLowerCase());
      b.hidden = taken;
    });
  },
});

document.getElementById("allergy-quick").addEventListener("click", (e) => {
  const b = e.target.closest(".quick");
  if (!b) return;
  allergies.add(b.dataset.add);
  allergies.focus();
});

// ── Progress / active-section tracking ────────────────────────────────────
const sections = [
  { id: "sec-about", step: "about" },
  { id: "sec-visit", step: "visit" },
  { id: "sec-history", step: "history" },
  { id: "sec-consent", step: "consent" },
];
const stepEls = {};
document.querySelectorAll(".step").forEach((el) => (stepEls[el.dataset.step] = el));
const barFill = document.getElementById("bar-fill");

function setActiveStep(idx) {
  sections.forEach((s, i) => {
    const el = stepEls[s.step];
    el.classList.toggle("is-active", i === idx);
    el.classList.toggle("is-done", i < idx);
  });
  barFill.style.width = ((idx + 1) / sections.length) * 100 + "%";
}

const observer = new IntersectionObserver(
  (entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        const idx = sections.findIndex((s) => s.id === entry.target.id);
        if (idx > -1) setActiveStep(idx);
      }
    });
  },
  { rootMargin: "-45% 0px -45% 0px", threshold: 0 }
);
sections.forEach((s) => observer.observe(document.getElementById(s.id)));

// ── Inline validation ─────────────────────────────────────────────────────
function fieldOf(input) {
  return input.closest(".field");
}
function clearError(input) {
  const f = fieldOf(input);
  if (f) f.classList.remove("invalid");
}
form.querySelectorAll("input, textarea").forEach((el) => {
  el.addEventListener("input", () => clearError(el));
});
document.getElementById("consent").addEventListener("change", () => {
  document.getElementById("sec-consent").classList.remove("invalid");
});

function validate() {
  let firstBad = null;
  const fail = (el, container) => {
    (container || fieldOf(el)).classList.add("invalid");
    if (!firstBad) firstBad = container || el;
  };

  ["firstName", "lastName", "dob", "phone", "reason"].forEach((id) => {
    const el = document.getElementById(id);
    if (!el.value.trim()) fail(el);
  });

  const email = document.getElementById("email");
  if (email.value.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim())) {
    fail(email);
  }

  const consentSec = document.getElementById("sec-consent");
  if (!document.getElementById("consent").checked) fail(null, consentSec);

  return firstBad;
}

// ── Submit → review summary ───────────────────────────────────────────────
function val(id) {
  return document.getElementById(id).value.trim();
}
function fmtDate(iso) {
  if (!iso) return "";
  const d = new Date(iso + "T00:00:00");
  if (isNaN(d)) return iso;
  return d.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
}

function buildReview() {
  const grid = document.getElementById("review-grid");
  const sevVal = Number(severity.value);
  const band = bandFor(sevVal);

  const tags = (items, danger) =>
    items.length
      ? '<div class="tag-row">' +
        items
          .map((t) => '<span class="tag' + (danger ? " danger" : "") + '">' + esc(t) + "</span>")
          .join("") +
        "</div>"
      : '<dd class="empty">None listed</dd>';

  const rows = [
    { dt: "Name", dd: esc(val("firstName") + " " + val("lastName")) },
    { dt: "Date of birth", dd: esc(fmtDate(val("dob"))) },
    { dt: "Mobile phone", dd: esc(val("phone")) },
    { dt: "Email", dd: val("email") ? esc(val("email")) : '<span class="empty">Not provided</span>' },
    {
      dt: "Reason for visit",
      dd: esc(val("reason")),
      full: true,
    },
    {
      dt: "Symptom severity",
      dd:
        '<span class="sev-chip"><span class="swatch" style="background:' +
        band.track +
        '"></span>' +
        sevVal +
        " / 10 · " +
        band.label +
        "</span>",
    },
    { dt: "Consent", dd: "Confirmed" },
    { dt: "Current medications", ddHtml: tags(meds.items, false), full: true },
    { dt: "Known allergies", ddHtml: tags(allergies.items, true), full: true },
  ];

  grid.innerHTML = rows
    .map((r) => {
      const body = r.ddHtml
        ? (r.ddHtml.startsWith("<dd") ? r.ddHtml : "<dd>" + r.ddHtml + "</dd>")
        : "<dd>" + r.dd + "</dd>";
      return '<div class="row' + (r.full ? " full" : "") + '"><dt>' + r.dt + "</dt>" + body + "</div>";
    })
    .join("");
}

function esc(s) {
  return String(s).replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])
  );
}

const review = document.getElementById("review");

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const bad = validate();
  if (bad) {
    showToast("Please complete the highlighted fields.");
    bad.scrollIntoView({ behavior: "smooth", block: "center" });
    const focusable = bad.querySelector("input, textarea") || bad;
    if (focusable.focus) setTimeout(() => focusable.focus(), 300);
    return;
  }

  buildReview();
  form.hidden = true;
  review.hidden = false;
  setActiveStep(sections.length - 1);
  review.scrollIntoView({ behavior: "smooth", block: "start" });
  showToast("Intake submitted — your care team has it.");
});

document.getElementById("edit-btn").addEventListener("click", () => {
  review.hidden = true;
  form.hidden = false;
  document.getElementById("sec-about").scrollIntoView({ behavior: "smooth", block: "start" });
});

document.getElementById("done-btn").addEventListener("click", () => {
  showToast("All set — see you at your appointment.");
});

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --pending: #6b7280;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

/* ── App bar ── */
.appbar {
  background: var(--white);
  border-bottom: 1px solid var(--line);
  padding: 14px 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 20;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--ink);
}
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: linear-gradient(150deg, var(--teal), var(--teal-d));
  color: #fff;
  font-size: 1.1rem;
  font-weight: 700;
}
.brand-name {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.brand-name em {
  font-style: normal;
  color: var(--teal-d);
}
.appbar-tag {
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--teal-d);
  background: var(--teal-50);
  border-radius: 999px;
  padding: 6px 12px;
}

/* ── Layout ── */
.wizard {
  max-width: 680px;
  margin: 0 auto;
  padding: 28px 24px 56px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ── Progress ── */
.progress {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.progress-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}
.progress-label {
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--teal-d);
}
.progress-name {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ink-2);
}
.progress-track {
  height: 8px;
  border-radius: 999px;
  background: var(--white);
  border: 1px solid var(--line);
  overflow: hidden;
}
.progress-fill {
  display: block;
  height: 100%;
  width: 25%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--teal), var(--teal-d));
  transition: width 0.35s ease;
}

/* ── Card ── */
.card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 26px 26px 20px;
  box-shadow: var(--shadow-1);
}

/* ── Steps ── */
.step {
  border: none;
  display: none;
}
.step.is-active {
  display: block;
  animation: rise 0.3s ease;
}
@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.step-h {
  font-size: 1.3rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.step-sub {
  color: var(--muted);
  font-size: 0.92rem;
  margin: 4px 0 18px;
}

/* ── Step 1 — Body area ── */
.area-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}
.area-card {
  background: var(--white);
  border: 1.5px solid var(--line);
  border-radius: var(--r-md);
  padding: 18px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  font: inherit;
  font-weight: 600;
  font-size: 0.88rem;
  color: var(--ink);
  cursor: pointer;
  transition: transform 0.14s, box-shadow 0.14s, border-color 0.14s, background 0.14s;
}
.area-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-1);
  border-color: var(--teal);
}
.area-card[aria-checked="true"] {
  border-color: var(--teal);
  background: var(--teal-50);
  color: var(--teal-700);
}
.area-ic {
  font-size: 1.6rem;
  line-height: 1;
}

/* ── Step 2 — Symptom chips ── */
.chip-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1.5px solid var(--line);
  border-radius: 999px;
  padding: 10px 16px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--ink-2);
  cursor: pointer;
  transition: border-color 0.14s, background 0.14s, color 0.14s;
}
.chip:hover {
  border-color: var(--teal);
}
.chip input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}
.chip:has(input:checked) {
  border-color: var(--teal);
  background: var(--teal-50);
  color: var(--teal-700);
  font-weight: 600;
}
.chip:has(input:focus-visible) {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}

/* ── Step 3 — Duration & severity ── */
.field {
  margin-bottom: 22px;
}
.field:last-child {
  margin-bottom: 0;
}
.field-label {
  font-size: 0.84rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ink-2);
  margin-bottom: 12px;
}
.radio-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}
.radio {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1.5px solid var(--line);
  border-radius: var(--r-md);
  padding: 12px 14px;
  font-size: 0.9rem;
  font-weight: 500;
  cursor: pointer;
  transition: border-color 0.14s, background 0.14s;
}
.radio:hover {
  border-color: var(--teal);
}
.radio input {
  accent-color: var(--teal-d);
  width: 16px;
  height: 16px;
}
.radio:has(input:checked) {
  border-color: var(--teal);
  background: var(--teal-50);
  color: var(--teal-700);
  font-weight: 600;
}
.sev-value {
  display: inline-grid;
  place-items: center;
  min-width: 30px;
  height: 26px;
  padding: 0 8px;
  border-radius: 999px;
  background: var(--teal-d);
  color: #fff;
  font-size: 0.9rem;
  font-weight: 700;
  margin-left: 6px;
  vertical-align: middle;
}
.sev-of {
  color: var(--muted);
  font-weight: 600;
  margin-left: 4px;
}
.slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 8px;
  border-radius: 999px;
  background: var(--teal-50);
  outline: none;
  margin: 6px 0 8px;
}
.slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--teal-d);
  border: 3px solid var(--white);
  box-shadow: var(--shadow-1);
  cursor: pointer;
}
.slider::-moz-range-thumb {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--teal-d);
  border: 3px solid var(--white);
  box-shadow: var(--shadow-1);
  cursor: pointer;
}
.slider-scale {
  display: flex;
  justify-content: space-between;
  font-size: 0.76rem;
  color: var(--muted);
  font-weight: 500;
}

/* ── Step 4 — Result ── */
.result {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.result-banner {
  border-radius: var(--r-md);
  padding: 20px 22px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  border-left: 5px solid var(--pending);
  background: rgba(107, 114, 128, 0.1);
}
.result-banner.level-danger {
  border-left-color: var(--danger);
  background: rgba(212, 80, 62, 0.1);
}
.result-banner.level-warn {
  border-left-color: var(--warn);
  background: rgba(217, 138, 43, 0.12);
}
.result-banner.level-ok {
  border-left-color: var(--ok);
  background: rgba(47, 158, 111, 0.12);
}
.rb-level {
  font-size: 1.2rem;
  font-weight: 800;
  letter-spacing: -0.01em;
}
.level-danger .rb-level {
  color: var(--danger);
}
.level-warn .rb-level {
  color: var(--warn);
}
.level-ok .rb-level {
  color: var(--ok);
}
.rb-rec {
  font-size: 0.94rem;
  color: var(--ink-2);
}
.next-steps {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.next-steps li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.92rem;
  color: var(--ink-2);
}
.next-steps li::before {
  content: "✓";
  flex: none;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--teal-50);
  color: var(--teal-d);
  font-size: 0.78rem;
  font-weight: 800;
  margin-top: 1px;
}
.disclaimer {
  background: var(--coral-soft);
  border: 1px solid rgba(255, 122, 102, 0.4);
  border-radius: var(--r-md);
  padding: 14px 16px;
  font-size: 0.86rem;
  color: var(--ink-2);
  line-height: 1.55;
}
.disclaimer strong {
  color: var(--danger);
}

/* ── Buttons ── */
.btn {
  border: none;
  border-radius: 11px;
  padding: 11px 22px;
  font: inherit;
  font-weight: 600;
  font-size: 0.92rem;
  cursor: pointer;
  transition: transform 0.12s, background 0.15s, opacity 0.15s;
}
.btn:active {
  transform: translateY(1px);
}
.btn.primary {
  background: var(--coral);
  color: #fff;
}
.btn.primary:hover {
  background: #ff8e7c;
}
.btn.primary:disabled {
  background: var(--line-2);
  color: var(--muted);
  cursor: default;
}
.btn.ghost {
  background: var(--white);
  border: 1px solid var(--line-2);
  color: var(--ink-2);
}
.btn.ghost:hover {
  background: var(--teal-50);
  border-color: var(--teal);
}
.btn.block {
  width: 100%;
}

/* ── Nav ── */
.nav {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}
.nav-hint {
  flex: 1;
  font-size: 0.82rem;
  color: var(--danger);
  font-weight: 500;
  text-align: center;
  min-height: 1em;
}
#nextBtn {
  margin-left: auto;
}

@media (max-width: 560px) {
  .area-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .radio-grid {
    grid-template-columns: 1fr;
  }
  .card {
    padding: 20px 18px 16px;
  }
}

