// ── State ────────────────────────────────────────────────────────────────────
const TOTAL_STEPS = 4;
const STEP_NAMES = ["Body area", "Symptoms", "Duration & severity", "Result"];
const state = {
  step: 1,
  area: null,
  symptoms: [],
  duration: "<24h",
  severity: 5,
};

const form = document.getElementById("wizardForm");
const steps = [...form.querySelectorAll(".step")];
const stepLabel = document.getElementById("stepLabel");
const stepName = document.getElementById("stepName");
const progressBar = document.getElementById("progressBar");
const progressFill = document.getElementById("progressFill");
const backBtn = document.getElementById("backBtn");
const nextBtn = document.getElementById("nextBtn");
const restartBtn = document.getElementById("restartBtn");
const navHint = document.getElementById("navHint");

// ── Render the current step ──────────────────────────────────────────────────
function render() {
  steps.forEach((s) => s.classList.toggle("is-active", Number(s.dataset.step) === state.step));
  stepLabel.textContent = `Step ${state.step} of ${TOTAL_STEPS}`;
  stepName.textContent = STEP_NAMES[state.step - 1];
  progressFill.style.width = `${(state.step / TOTAL_STEPS) * 100}%`;
  progressBar.setAttribute("aria-valuenow", String(state.step));
  navHint.textContent = "";

  const onResult = state.step === TOTAL_STEPS;
  backBtn.hidden = state.step === 1 || onResult;
  nextBtn.hidden = onResult;
  restartBtn.hidden = !onResult;
  nextBtn.textContent = state.step === TOTAL_STEPS - 1 ? "See result" : "Next";
}

// ── Validation gating ────────────────────────────────────────────────────────
function validateStep() {
  if (state.step === 1 && !state.area) {
    return "Please choose a body area to continue.";
  }
  if (state.step === 2 && state.symptoms.length === 0) {
    return "Please select at least one symptom.";
  }
  return "";
}

// ── Deterministic illustrative triage ────────────────────────────────────────
function computeTriage() {
  const hasUrgentSymptom = state.symptoms.includes("Shortness of breath");
  const chestPain = state.area === "Chest" && state.symptoms.includes("Pain");
  const longDuration = state.duration === "4-7 days" || state.duration === ">1 week";

  if (hasUrgentSymptom || chestPain || state.severity >= 8) {
    return {
      key: "danger",
      level: "Seek urgent care",
      rec: "Your answers suggest symptoms that should be assessed promptly by a clinician.",
      steps: [
        "Contact urgent care or your clinic today.",
        "If breathing is difficult or pain is severe, call your local emergency number.",
        "Have someone stay with you if you feel unwell.",
      ],
    };
  }

  if (state.severity >= 5 || longDuration || state.symptoms.length >= 3) {
    return {
      key: "warn",
      level: "Book a GP appointment soon",
      rec: "Your symptoms are worth a professional review within the next day or two.",
      steps: [
        "Book a routine appointment with your GP.",
        "Note when symptoms started and what makes them better or worse.",
        "Rest, stay hydrated, and monitor for any new symptoms.",
      ],
    };
  }

  return {
    key: "ok",
    level: "Self-care & monitor",
    rec: "Your symptoms appear mild. Home care and observation are reasonable for now.",
    steps: [
      "Rest and keep up your fluids.",
      "Use over-the-counter relief as appropriate.",
      "Check back in if symptoms worsen or last beyond a few days.",
    ],
  };
}

function renderResult() {
  const t = computeTriage();
  const banner = document.getElementById("resultBanner");
  banner.className = `result-banner level-${t.key}`;
  document.getElementById("rbLevel").textContent = t.level;
  document.getElementById("rbRec").textContent = t.rec;

  const list = document.getElementById("nextSteps");
  list.innerHTML = "";
  for (const step of t.steps) {
    const li = document.createElement("li");
    li.textContent = step;
    list.appendChild(li);
  }
}

// ── Step 1 — body area (single select) ───────────────────────────────────────
document.getElementById("areaGrid").addEventListener("click", (e) => {
  const card = e.target.closest(".area-card");
  if (!card) return;
  state.area = card.dataset.area;
  for (const c of card.parentElement.children) {
    c.setAttribute("aria-checked", String(c === card));
  }
  navHint.textContent = "";
});

// ── Step 2 — symptoms (multi select) ─────────────────────────────────────────
document.getElementById("symptomGrid").addEventListener("change", () => {
  state.symptoms = [...form.querySelectorAll('input[name="symptom"]:checked')].map((i) => i.value);
  if (state.symptoms.length > 0) navHint.textContent = "";
});

// ── Step 3 — duration & severity ─────────────────────────────────────────────
document.getElementById("durationGrid").addEventListener("change", (e) => {
  state.duration = e.target.value;
});
const severity = document.getElementById("severity");
const sevValue = document.getElementById("sevValue");
severity.addEventListener("input", () => {
  state.severity = Number(severity.value);
  sevValue.textContent = severity.value;
});

// ── Navigation ───────────────────────────────────────────────────────────────
nextBtn.addEventListener("click", () => {
  const error = validateStep();
  if (error) {
    navHint.textContent = error;
    return;
  }
  if (state.step === TOTAL_STEPS - 1) renderResult();
  state.step = Math.min(state.step + 1, TOTAL_STEPS);
  render();
});

backBtn.addEventListener("click", () => {
  state.step = Math.max(state.step - 1, 1);
  render();
});

document.getElementById("bookBtn").addEventListener("click", () => {
  document.getElementById("bookBtn").textContent = "Appointment requested ✓";
  document.getElementById("bookBtn").disabled = true;
});

restartBtn.addEventListener("click", () => {
  form.reset();
  state.step = 1;
  state.area = null;
  state.symptoms = [];
  state.duration = "<24h";
  state.severity = 5;
  sevValue.textContent = "5";
  for (const c of document.getElementById("areaGrid").children) {
    c.setAttribute("aria-checked", "false");
  }
  const bookBtn = document.getElementById("bookBtn");
  bookBtn.textContent = "Book an appointment";
  bookBtn.disabled = false;
  render();
});

render();

snippets.css:
:root {
  /* Pediatric pastel palette */
  --sun: #ffd862;
  --sun-soft: #fff2c8;
  --sky: #7ec8f2;
  --sky-soft: #dff0fb;
  --bubble: #ff9ec4;
  --bubble-soft: #ffe1ee;
  --mint: #8fe3c4;
  --coral: #ff9a7a;
  --grape: #b9a6f1;

  --ink: #2a2350;
  --ink-2: #4a4374;
  --muted: #7d77a3;

  --bg: #fffdf4;
  --white: #ffffff;

  --line: rgba(42, 35, 80, 0.1);
  --line-2: rgba(42, 35, 80, 0.16);

  --ok: #2f9e6f;
  --warn: #d98a2b;
  --danger: #d4503e;

  --r-sm: 12px;
  --r-md: 20px;
  --r-lg: 32px;
  --r-pill: 999px;

  --shadow-sm: 0 4px 14px rgba(42, 35, 80, 0.08);
  --shadow-md: 0 14px 34px rgba(42, 35, 80, 0.12);
  --shadow-lg: 0 26px 60px rgba(42, 35, 80, 0.16);

  --maxw: 1140px;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  font-weight: 400;
  line-height: 1.5;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

h1, h2, h3, h4 {
  margin: 0;
  line-height: 1.12;
  letter-spacing: -0.02em;
  font-weight: 800;
}

p {
  margin: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
}

:focus-visible {
  outline: 3px solid var(--sky);
  outline-offset: 3px;
  border-radius: 6px;
}

/* ============ Decorative blobs ============ */
.sky-deco {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(2px);
  opacity: 0.5;
}

.blob--sun {
  width: 420px;
  height: 420px;
  top: -160px;
  right: -120px;
  background: radial-gradient(circle at 30% 30%, var(--sun), var(--sun-soft));
  animation: float 9s ease-in-out infinite;
}

.blob--sky {
  width: 360px;
  height: 360px;
  bottom: 8%;
  left: -140px;
  background: radial-gradient(circle at 40% 30%, var(--sky), var(--sky-soft));
  animation: float 11s ease-in-out infinite reverse;
}

.blob--bubble {
  width: 280px;
  height: 280px;
  top: 44%;
  right: -100px;
  background: radial-gradient(circle at 40% 30%, var(--bubble), var(--bubble-soft));
  animation: float 10s ease-in-out infinite;
}

.cloud {
  position: absolute;
  background: var(--white);
  border-radius: var(--r-pill);
  opacity: 0.6;
  box-shadow:
    -28px 8px 0 -4px var(--white),
    30px 6px 0 -6px var(--white);
}
.cloud--1 { width: 70px; height: 26px; top: 16%; left: 12%; animation: drift 22s linear infinite; }
.cloud--2 { width: 54px; height: 20px; top: 30%; left: 60%; animation: drift 30s linear infinite; }

@keyframes float {
  0%, 100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-26px) scale(1.04); }
}
@keyframes drift {
  from { transform: translateX(-10vw); }
  to { transform: translateX(110vw); }
}

/* ============ Layout helpers ============ */
main {
  position: relative;
  z-index: 1;
}

.section {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 84px 24px;
}
.section--tight {
  padding-top: 36px;
  padding-bottom: 36px;
}

.section__head {
  max-width: 640px;
  margin: 0 auto 44px;
  text-align: center;
}
.section__head h2 {
  font-size: clamp(1.7rem, 3.6vw, 2.5rem);
  margin: 14px 0 12px;
}
.section__head p {
  color: var(--ink-2);
  font-size: 1.05rem;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: var(--r-pill);
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.01em;
}
.pill--sun { background: var(--sun-soft); color: #8a6500; }
.pill--sky { background: var(--sky-soft); color: #1f6ea0; }
.pill--bubble { background: var(--bubble-soft); color: #b53774; }

/* ============ Buttons ============ */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 24px;
  border-radius: var(--r-pill);
  font-weight: 700;
  font-size: 1rem;
  border: 2px solid transparent;
  cursor: pointer;
  transition: transform 0.16s ease, box-shadow 0.2s ease, background 0.2s ease;
}
.btn--sm {
  padding: 10px 18px;
  font-size: 0.9rem;
}
.btn--primary {
  background: var(--ink);
  color: var(--white);
  box-shadow: var(--shadow-sm);
}
.btn--primary:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  background: #342b66;
}
.btn--primary:active {
  transform: translateY(0);
}
.btn--ghost {
  background: var(--white);
  color: var(--ink);
  border-color: var(--line-2);
}
.btn--ghost:hover {
  transform: translateY(-2px);
  border-color: var(--ink);
  box-shadow: var(--shadow-sm);
}

/* ============ Nav ============ */
.nav {
  position: sticky;
  top: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 16px 24px;
  transition: background 0.25s ease, box-shadow 0.25s ease, padding 0.25s ease;
}
.nav.is-scrolled {
  background: rgba(255, 253, 244, 0.86);
  backdrop-filter: blur(10px);
  box-shadow: var(--shadow-sm);
  border-radius: 0 0 var(--r-md) var(--r-md);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
}
.brand__mark {
  font-size: 1.7rem;
  filter: drop-shadow(0 2px 4px rgba(42, 35, 80, 0.18));
  animation: float 6s ease-in-out infinite;
}
.brand__name {
  display: flex;
  flex-direction: column;
  font-size: 1.1rem;
  line-height: 1;
  color: var(--ink);
}
.brand__name small {
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
  margin-top: 3px;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: 6px;
}
.nav__links > a {
  padding: 9px 14px;
  border-radius: var(--r-pill);
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--ink-2);
  transition: background 0.18s ease, color 0.18s ease;
}
.nav__links > a:hover {
  background: var(--white);
  color: var(--ink);
}
.nav__links > a.is-active {
  color: var(--ink);
  background: var(--sun-soft);
}
.nav__cta {
  background: var(--ink) !important;
  color: var(--white) !important;
  padding: 10px 18px !important;
  box-shadow: var(--shadow-sm);
}
.nav__cta:hover {
  transform: translateY(-1px);
}

.nav__toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 46px;
  height: 46px;
  align-items: center;
  justify-content: center;
  background: var(--white);
  border: 2px solid var(--line-2);
  border-radius: var(--r-sm);
  cursor: pointer;
}
.nav__toggle span {
  width: 22px;
  height: 2.5px;
  background: var(--ink);
  border-radius: 2px;
  transition: transform 0.25s ease, opacity 0.2s ease;
}
.nav__toggle[aria-expanded="true"] span:nth-child(1) { transform: translateY(7.5px) rotate(45deg); }
.nav__toggle[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
.nav__toggle[aria-expanded="true"] span:nth-child(3) { transform: translateY(-7.5px) rotate(-45deg); }

/* ============ Hero ============ */
.hero {
  position: relative;
  z-index: 1;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 40px 24px 72px;
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  align-items: center;
  gap: 32px;
}

.hero__text .pill {
  margin-bottom: 18px;
}
.hero h1 {
  font-size: clamp(2.4rem, 6vw, 4rem);
}
.hero__pop {
  position: relative;
  display: inline-block;
  color: var(--bubble);
  background: var(--bubble-soft);
  padding: 0 0.12em;
  border-radius: 14px;
  transform: rotate(-2deg);
}
.hero__sparkle {
  position: absolute;
  top: -0.5em;
  right: -0.5em;
  font-size: 0.5em;
  animation: float 4s ease-in-out infinite;
}
.hero__lead {
  margin: 22px 0 28px;
  font-size: 1.15rem;
  color: var(--ink-2);
  max-width: 30em;
}
.hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}
.hero__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  list-style: none;
  margin: 30px 0 0;
  padding: 0;
}
.hero__chips li {
  background: var(--white);
  border: 1.5px solid var(--line);
  padding: 9px 15px;
  border-radius: var(--r-pill);
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--ink-2);
  box-shadow: var(--shadow-sm);
}

/* Hero mascot art */
.hero__art {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 360px;
}
.mascot {
  position: relative;
  width: 240px;
  height: 240px;
  border-radius: 46% 54% 52% 48% / 52% 46% 54% 48%;
  background:
    radial-gradient(circle at 35% 28%, var(--sun), var(--coral));
  box-shadow: var(--shadow-lg), inset 0 -18px 32px rgba(42, 35, 80, 0.12);
  animation: bob 5s ease-in-out infinite;
}
@keyframes bob {
  0%, 100% { transform: translateY(0) rotate(-2deg); }
  50% { transform: translateY(-18px) rotate(2deg); }
}
.mascot__face {
  position: absolute;
  inset: 0;
}
.mascot__eye {
  position: absolute;
  top: 42%;
  width: 22px;
  height: 30px;
  background: var(--ink);
  border-radius: 50%;
}
.mascot__eye--l { left: 32%; }
.mascot__eye--r { right: 32%; }
.mascot__eye::after {
  content: "";
  position: absolute;
  top: 4px;
  left: 5px;
  width: 7px;
  height: 7px;
  background: var(--white);
  border-radius: 50%;
}
.mascot__cheek {
  position: absolute;
  top: 56%;
  width: 30px;
  height: 18px;
  background: var(--bubble);
  border-radius: 50%;
  opacity: 0.75;
  filter: blur(1px);
}
.mascot__cheek--l { left: 20%; }
.mascot__cheek--r { right: 20%; }
.mascot__smile {
  position: absolute;
  top: 58%;
  left: 50%;
  transform: translateX(-50%);
  width: 70px;
  height: 36px;
  border: 6px solid var(--ink);
  border-top: none;
  border-radius: 0 0 70px 70px;
}
.mascot__sticker {
  position: absolute;
  font-size: 1.8rem;
  filter: drop-shadow(0 4px 6px rgba(42, 35, 80, 0.2));
}
.mascot__sticker--star { top: -14px; left: -10px; animation: float 5s ease-in-out infinite; }
.mascot__sticker--heart { bottom: 8px; right: -16px; animation: float 6s ease-in-out infinite reverse; }
.mascot__sticker--plus { top: 40%; right: -28px; font-size: 1.3rem; animation: float 7s ease-in-out infinite; }

.orbit {
  position: absolute;
  font-size: 2rem;
  filter: drop-shadow(0 4px 8px rgba(42, 35, 80, 0.18));
}
.orbit--1 { top: 6%; left: 4%; animation: float 6s ease-in-out infinite; }
.orbit--2 { bottom: 4%; left: 16%; animation: float 7.5s ease-in-out infinite reverse; }
.orbit--3 { top: 10%; right: 2%; animation: float 8s ease-in-out infinite; }

/* ============ Services ============ */
.services {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.svc {
  position: relative;
  text-align: left;
  font-family: inherit;
  background: var(--white);
  border: 2px solid var(--line);
  border-radius: var(--r-lg);
  padding: 26px 24px 24px;
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.svc:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
  border-color: var(--line-2);
}
.svc__icon {
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  border-radius: 20px;
  font-size: 1.7rem;
  background: color-mix(in srgb, var(--c) 32%, white);
  margin-bottom: 16px;
  transition: transform 0.2s ease;
}
.svc:hover .svc__icon {
  transform: rotate(-8deg) scale(1.08);
}
.svc h3 {
  font-size: 1.2rem;
  margin-bottom: 8px;
}
.svc p {
  color: var(--ink-2);
  font-size: 0.95rem;
}
.svc__add {
  display: inline-block;
  margin-top: 16px;
  font-weight: 700;
  font-size: 0.85rem;
  color: var(--muted);
  transition: color 0.18s ease;
}
.svc:hover .svc__add { color: var(--ink); }
.svc.is-added {
  border-color: var(--mint);
  background: color-mix(in srgb, var(--mint) 14%, white);
}
.svc.is-added .svc__add {
  color: var(--ok);
}
.svc.is-added .svc__add::before {
  content: "✓ Added";
}
.svc.is-added .svc__add { font-size: 0; }
.svc.is-added .svc__add::before { font-size: 0.85rem; }

/* Checklist basket */
.basket {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 28px;
  padding: 16px 22px;
  background: var(--ink);
  color: var(--white);
  border-radius: var(--r-md);
  box-shadow: var(--shadow-md);
  animation: pop 0.25s ease;
}
@keyframes pop {
  from { transform: scale(0.96); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}
.basket__text {
  flex: 1;
  font-size: 0.98rem;
}
.basket__text strong {
  display: inline-grid;
  place-items: center;
  min-width: 28px;
  height: 28px;
  padding: 0 6px;
  margin-right: 6px;
  background: var(--sun);
  color: var(--ink);
  border-radius: var(--r-pill);
  font-size: 0.95rem;
}
.basket__clear {
  background: none;
  border: none;
  color: rgba(255, 255, 255, 0.7);
  font-family: inherit;
  font-weight: 600;
  font-size: 0.9rem;
  cursor: pointer;
  text-decoration: underline;
}
.basket__clear:hover { color: var(--white); }

/* ============ For parents band ============ */
.parents {
  position: relative;
  z-index: 1;
  background: linear-gradient(135deg, var(--sky-soft), var(--bubble-soft));
  margin: 20px 0;
}
.parents__inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 72px 24px;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 40px;
  align-items: center;
}
.parents__copy h2 {
  font-size: clamp(1.6rem, 3.4vw, 2.3rem);
  margin: 14px 0 14px;
}
.parents__copy > p {
  color: var(--ink-2);
  font-size: 1.05rem;
  margin-bottom: 20px;
}
.parents__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 12px;
}
.parents__list li {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 600;
  color: var(--ink);
}
.parents__list li span {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  background: var(--white);
  border-radius: 12px;
  font-size: 1.1rem;
  box-shadow: var(--shadow-sm);
}

.quote {
  margin: 0;
  background: var(--white);
  border-radius: var(--r-lg);
  padding: 30px 28px;
  box-shadow: var(--shadow-md);
  border: 2px solid var(--line);
}
.quote blockquote {
  margin: 0 0 18px;
  font-size: 1.2rem;
  font-weight: 600;
  line-height: 1.45;
  color: var(--ink);
}
.quote figcaption {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--ink-2);
  font-size: 0.92rem;
}
.quote__avatar {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: var(--sun-soft);
  font-size: 1.4rem;
}

/* ============ Stats ============ */
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}
.stat {
  text-align: center;
  background: var(--white);
  border: 2px solid var(--line);
  border-radius: var(--r-lg);
  padding: 28px 16px;
  box-shadow: var(--shadow-sm);
}
.stat__num {
  display: block;
  font-size: clamp(1.9rem, 4vw, 2.6rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  background: linear-gradient(120deg, var(--sky), var(--bubble));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.stat__label {
  display: block;
  margin-top: 6px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ink-2);
}

.badges {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
  list-style: none;
  margin: 34px 0 0;
  padding: 0;
}
.badges li {
  background: var(--white);
  border: 1.5px solid var(--line);
  padding: 10px 18px;
  border-radius: var(--r-pill);
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--ink);
  box-shadow: var(--shadow-sm);
}

/* ============ Team ============ */
.team {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.doc {
  background: var(--white);
  border: 2px solid var(--line);
  border-radius: var(--r-lg);
  padding: 26px 22px;
  text-align: center;
  transition: transform 0.18s ease, box-shadow 0.2s ease;
}
.doc:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
}
.doc__avatar {
  display: grid;
  place-items: center;
  width: 84px;
  height: 84px;
  margin: 0 auto 14px;
  border-radius: 50%;
  font-size: 2.4rem;
  background: color-mix(in srgb, var(--accent) 30%, white);
  border: 3px solid color-mix(in srgb, var(--accent) 55%, white);
}
.doc h3 {
  font-size: 1.1rem;
}
.doc__role {
  margin-top: 4px;
  font-weight: 700;
  font-size: 0.85rem;
  color: var(--muted);
}
.doc__bio {
  margin: 10px 0 14px;
  font-size: 0.9rem;
  color: var(--ink-2);
}
.doc__tag {
  display: inline-block;
  padding: 5px 12px;
  border-radius: var(--r-pill);
  font-size: 0.78rem;
  font-weight: 700;
  background: color-mix(in srgb, var(--accent) 22%, white);
  color: var(--ink);
}

/* ============ Book CTA ============ */
.cta {
  position: relative;
  z-index: 1;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 24px 24px 84px;
}
.cta__card {
  position: relative;
  overflow: hidden;
  text-align: center;
  background: linear-gradient(135deg, var(--sun), var(--coral));
  border-radius: var(--r-lg);
  padding: 56px 28px;
  box-shadow: var(--shadow-lg);
}
.cta__card h2 {
  font-size: clamp(1.7rem, 4vw, 2.5rem);
  color: var(--ink);
}
.cta__card p {
  margin: 14px auto 26px;
  max-width: 34em;
  color: var(--ink-2);
  font-size: 1.05rem;
  font-weight: 500;
}
.cta__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  justify-content: center;
}
.cta__sticker {
  position: absolute;
  font-size: 3rem;
  opacity: 0.85;
}
.cta__sticker--1 { top: 18px; left: 24px; animation: float 6s ease-in-out infinite; }
.cta__sticker--2 { bottom: 16px; right: 26px; animation: float 7s ease-in-out infinite reverse; }

/* ============ Footer ============ */
.footer {
  position: relative;
  z-index: 1;
  background: var(--ink);
  color: rgba(255, 255, 255, 0.82);
  border-radius: var(--r-lg) var(--r-lg) 0 0;
}
.footer__top {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 56px 24px 32px;
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1.2fr;
  gap: 28px;
}
.footer__brand strong {
  display: block;
  margin: 8px 0 8px;
  font-size: 1.1rem;
  color: var(--white);
}
.footer__brand .brand__mark { animation: none; }
.footer__brand p {
  font-size: 0.9rem;
  max-width: 24em;
}
.footer__col h4 {
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--sun);
  margin-bottom: 14px;
}
.footer__col a,
.footer__col p {
  display: block;
  font-size: 0.92rem;
  margin-bottom: 9px;
  color: rgba(255, 255, 255, 0.78);
}
.footer__col a {
  transition: color 0.16s ease;
}
.footer__col a:hover { color: var(--white); }
.footer__bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 18px 24px;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  font-size: 0.85rem;
  color: rgba(255, 255, 255, 0.6);
}

/* ============ Toast ============ */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink);
  color: var(--white);
  padding: 14px 22px;
  border-radius: var(--r-pill);
  font-weight: 600;
  font-size: 0.95rem;
  box-shadow: var(--shadow-lg);
  z-index: 100;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
}
.toast.is-show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ============ Reveal on scroll ============ */
.reveal {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 0.55s ease, transform 0.55s ease;
}
.reveal.is-in {
  opacity: 1;
  transform: none;
}

/* ============ Responsive ============ */
@media (max-width: 900px) {
  .services { grid-template-columns: repeat(2, 1fr); }
  .stats { grid-template-columns: repeat(2, 1fr); }
  .team { grid-template-columns: repeat(2, 1fr); }
  .parents__inner { grid-template-columns: 1fr; gap: 28px; }
  .footer__top { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 760px) {
  .hero {
    grid-template-columns: 1fr;
    text-align: center;
    padding-top: 24px;
  }
  .hero__actions, .hero__chips { justify-content: center; }
  .hero__lead { margin-left: auto; margin-right: auto; }
  .hero__art { order: -1; min-height: 300px; }

  .nav__toggle { display: flex; }
  .nav__links {
    position: absolute;
    top: calc(100% + 8px);
    right: 16px;
    left: 16px;
    flex-direction: column;
    align-items: stretch;
    gap: 6px;
    background: var(--white);
    border: 2px solid var(--line);
    border-radius: var(--r-md);
    padding: 12px;
    box-shadow: var(--shadow-md);
    opacity: 0;
    visibility: hidden;
    transform: translateY(-10px);
    transition: opacity 0.2s ease, transform 0.2s ease, visibility 0.2s;
  }
  .nav__links.is-open {
    opacity: 1;
    visibility: visible;
    transform: none;
  }
  .nav__links > a { text-align: center; }
}

@media (max-width: 520px) {
  .section { padding: 56px 18px; }
  .services { grid-template-columns: 1fr; }
  .stats { grid-template-columns: repeat(2, 1fr); }
  .team { grid-template-columns: 1fr; }
  .footer__top { grid-template-columns: 1fr; }
  .footer__bottom { justify-content: center; text-align: center; }
  .basket { flex-wrap: wrap; }
  .basket__text { flex-basis: 100%; }
  .cta__sticker { font-size: 2rem; }
  .hero__chips { gap: 8px; }
  .quote blockquote { font-size: 1.05rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
  .reveal { opacity: 1; transform: none; }
}

