/* ── Design tokens ── */
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  background: radial-gradient(circle at 75% 80%, rgba(201, 166, 73, 0.15), transparent 50%),
    linear-gradient(160deg, #14213b 0%, #0f1d36 100%);
  display: grid;
  place-items: center;
  min-height: 100vh;
  padding: 32px;
}

/* ── Card ── */
.bg {
  width: 100%;
  display: grid;
  place-items: center;
}
.card {
  width: min(580px, 100%);
  background: var(--bone);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: 0 40px 100px rgba(15, 29, 54, 0.55);
}

/* ── Header ── */
.card-head {
  padding: 22px 26px 18px;
  border-bottom: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
}
.kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold-d);
  font-weight: 700;
}
.card-head h2 {
  font-family: var(--font-display);
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.005em;
  color: var(--navy-d);
  margin-top: 2px;
}
.clock-wrap {
  display: flex;
  align-items: flex-end;
}
.clock {
  font-family: var(--font-mono);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--navy);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.03em;
}

/* ── Direction bar ── */
.dir-bar {
  padding: 12px 26px;
  border-bottom: 1px solid var(--line);
  background: var(--cream);
}
.seg {
  display: flex;
  background: var(--cream-2);
  border-radius: var(--r-md);
  padding: 3px;
  gap: 3px;
}
.seg-btn {
  flex: 1;
  background: transparent;
  border: none;
  font-family: var(--font-body);
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--warm-gray);
  padding: 9px 12px;
  border-radius: 7px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.seg-btn:hover {
  color: var(--ink);
}
.seg-btn.is-active {
  background: var(--bone);
  color: var(--navy-d);
  box-shadow: var(--shadow-1);
}
.route-icon {
  margin-right: 5px;
}

/* ── Next departure banner ── */
.next-banner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 18px 26px 16px;
  background: linear-gradient(135deg, var(--navy-2), var(--navy-d));
  gap: 16px;
  flex-wrap: wrap;
}
.next-label {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(251, 248, 242, 0.6);
  font-weight: 700;
}
.next-time {
  font-family: var(--font-mono);
  font-size: 2rem;
  font-weight: 700;
  color: var(--gold-light);
  line-height: 1;
  font-variant-numeric: tabular-nums;
  margin-top: 3px;
}
.next-stops {
  font-size: 0.78rem;
  color: rgba(251, 248, 242, 0.7);
  margin-top: 5px;
}
.next-right {
  text-align: right;
}
.countdown-label {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: rgba(251, 248, 242, 0.55);
  font-weight: 700;
}
.countdown {
  font-family: var(--font-mono);
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--bone);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
  line-height: 1;
  margin-top: 3px;
}
.reserve-btn {
  margin-top: 10px;
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.82rem;
  padding: 8px 18px;
  border-radius: 999px;
  cursor: pointer;
  background: var(--gold);
  color: var(--navy-d);
  border: none;
  white-space: nowrap;
}
.reserve-btn:hover {
  background: var(--gold-light);
}
.reserve-btn:disabled {
  background: rgba(251, 248, 242, 0.15);
  color: rgba(251, 248, 242, 0.4);
  cursor: not-allowed;
}

/* ── Departure list ── */
.dep-list {
  padding: 8px 0 8px;
  max-height: 340px;
  overflow-y: auto;
}
.dep-row {
  display: grid;
  grid-template-columns: 72px 1fr auto auto;
  align-items: center;
  gap: 10px;
  padding: 11px 26px;
  border-bottom: 1px solid var(--line);
  transition: background 0.12s;
}
.dep-row:last-child {
  border-bottom: none;
}
.dep-row:hover:not(.is-departed) {
  background: var(--cream);
}
.dep-row.is-next {
  background: rgba(201, 166, 73, 0.07);
}
.dep-row.is-departed {
  opacity: 0.45;
}

.dep-time {
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 700;
  color: var(--navy);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.dep-row.is-departed .dep-time {
  text-decoration: line-through;
}

.dep-info {
}
.dep-route {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--ink-2);
}
.dep-stops {
  font-size: 0.75rem;
  color: var(--warm-gray);
  margin-top: 2px;
}

.dep-seats {
  text-align: center;
  min-width: 54px;
}
.seats-n {
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 700;
  color: var(--navy);
  display: block;
  font-variant-numeric: tabular-nums;
}
.seats-n.low {
  color: var(--danger);
}
.seats-label {
  font-size: 0.66rem;
  color: var(--warm-gray);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 700;
}

.dep-action {
  min-width: 86px;
  text-align: right;
}
.status-badge {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 4px 10px;
  border-radius: 999px;
}
.status-ontime {
  background: rgba(74, 119, 82, 0.12);
  color: var(--success);
}
.status-boarding {
  background: rgba(201, 166, 73, 0.14);
  color: var(--gold-d);
}
.status-departed {
  background: rgba(22, 30, 44, 0.06);
  color: var(--warm-gray);
}
.btn-reserve {
  font-family: var(--font-body);
  font-size: 0.78rem;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  background: var(--bone);
  color: var(--navy-d);
  cursor: pointer;
  white-space: nowrap;
}
.btn-reserve:hover {
  border-color: var(--gold);
  background: var(--cream);
}
.btn-reserve:disabled {
  color: var(--warm-gray);
  background: transparent;
  border-style: dashed;
  cursor: not-allowed;
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 22px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: 0 10px 30px rgba(22, 30, 44, 0.18);
  z-index: 100;
  white-space: nowrap;
}

/* ── Responsive ── */
@media (max-width: 560px) {
  body {
    padding: 0;
  }
  .card {
    border-radius: 0;
  }
  .dep-row {
    grid-template-columns: 62px 1fr auto;
    gap: 8px;
  }
  .dep-action {
    display: none;
  }
  .next-right {
    text-align: left;
  }
}

