      stops: "T1 Arrivals · Concourse A · Lobby",
      seats: 2,
      maxSeats: 8,
    },
    {
      id: "i4",
      hhmm: "11:30",
      route: "Airport T2 → Hotel",
      stops: "T2 Arrivals · Lobby",
      seats: 8,
