    },
    {
      id: "i5",
      hhmm: "13:45",
      route: "Airport T1 → Hotel",
      stops: "T1 Arrivals · Concourse A · Lobby",
      seats: 6,
      maxSeats: 8,
    },
    {
      id: "i6",
