      seats: 8,
      maxSeats: 8,
    },
    {
      id: "i8",
      hhmm: "19:45",
      route: "Airport T2 → Hotel",
      stops: "T2 Arrivals · Lobby",
      seats: 3,
      maxSeats: 8,
    },
  ],
};

// ── State ─────────────────────────────────────────────────────────────────────
let dir = "out"; // "out" | "in"

// ── Helpers ───────────────────────────────────────────────────────────────────
const $ = (id) => document.getElementById(id);

const toast = $("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2200);
}

function nowMinutes() {
  const d = new Date();
  return d.getHours() * 60 + d.getMinutes();
}

function hhmmToMinutes(hhmm) {
  const [h, m] = hhmm.split(":").map(Number);
  return h * 60 + m;
}

function padTwo(n) {
  return String(n).padStart(2, "0");
}

function formatCountdown(diffMin) {
  if (diffMin < 0) return "–";
  const h = Math.floor(diffMin / 60);
  const m = diffMin % 60;
  return h > 0 ? `${h}h ${padTwo(m)}m` : `${m}m`;
}

function getStatus(hhmm) {
  const depMin = hhmmToMinutes(hhmm);
  const now = nowMinutes();
  const diff = depMin - now;
  if (diff < -3) return "departed";
  if (diff <= 10) return "boarding";
  return "ontime";
}

// ── Find next departure ───────────────────────────────────────────────────────
function findNext() {
  const now = nowMinutes();
  const rows = SCHEDULE[dir];
  return rows.find((r) => hhmmToMinutes(r.hhmm) - now > -3) || null;
}

// ── Render clock ──────────────────────────────────────────────────────────────
function renderClock() {
  const d = new Date();
  $("clock").textContent = `${padTwo(d.getHours())}:${padTwo(d.getMinutes())}`;
}

// ── Render next banner ────────────────────────────────────────────────────────
function renderNext() {
  const next = findNext();
  if (!next) {
    $("nextTime").textContent = "—";
    $("nextStops").textContent = "No more departures today";
    $("countdown").textContent = "—";
    $("nextReserveBtn").disabled = true;
    return;
  }
  const diff = hhmmToMinutes(next.hhmm) - nowMinutes();
  $("nextTime").textContent = next.hhmm;
  $("nextStops").textContent = next.stops;
  $("countdown").textContent = formatCountdown(diff);
  $("nextReserveBtn").disabled = next.seats === 0 || diff < -3;
  $("nextReserveBtn").dataset.id = next.id;
}

// ── Render departure list ─────────────────────────────────────────────────────
function renderList() {
  const rows = SCHEDULE[dir];
  const next = findNext();

  $("depList").innerHTML = rows
    .map((r) => {
      const status = getStatus(r.hhmm);
      const isNext = next && r.id === next.id;
      const isDep = status === "departed";
      const isBoard = status === "boarding";
      const canRes = !isDep && r.seats > 0;

      const seatsLow = r.seats <= 2 && r.seats > 0;
      const statusHtml = isDep
        ? `<span class="status-badge status-departed">Departed</span>`
        : isBoard
          ? `<span class="status-badge status-boarding">Boarding</span>`
          : `<span class="status-badge status-ontime">On time</span>`;

      const actionHtml = isDep
        ? statusHtml
        : `<button type="button" class="btn-reserve" data-id="${r.id}" ${r.seats === 0 ? "disabled" : ""}>${r.seats === 0 ? "Full" : "Reserve"}</button>`;

      return `
      <div class="dep-row ${isNext ? "is-next" : ""} ${isDep ? "is-departed" : ""}" role="listitem">
        <span class="dep-time">${r.hhmm}</span>
        <div class="dep-info">
          <div class="dep-route">${r.route}</div>
          <div class="dep-stops">${r.stops}</div>
        </div>
        <div class="dep-seats">
          <span class="seats-n ${seatsLow ? "low" : ""}">${r.seats}</span>
          <span class="seats-label">seats</span>
        </div>
        <div class="dep-action">${actionHtml}</div>
      </div>`;
    })
    .join("");
}

// ── Reserve seat (list) ───────────────────────────────────────────────────────
$("depList").addEventListener("click", (e) => {
  const btn = e.target.closest(".btn-reserve");
  if (!btn || btn.disabled) return;
  reserveSeat(btn.dataset.id);
});

// ── Reserve seat (banner) ─────────────────────────────────────────────────────
$("nextReserveBtn").addEventListener("click", () => {
  const next = findNext();
  if (!next) return;
  reserveSeat(next.id);
});

function reserveSeat(id) {
  const row = [...SCHEDULE.out, ...SCHEDULE.in].find((r) => r.id === id);
  if (!row || row.seats === 0) return;
  row.seats -= 1;
  const suffix = row.seats === 1 ? "1 seat left" : `${row.seats} seats left`;
  showToast(`Reserved · ${row.hhmm} ${row.route} — ${suffix}`);
  renderNext();
  renderList();
}

// ── Direction toggle ──────────────────────────────────────────────────────────
$("dirSeg").addEventListener("click", (e) => {
  const btn = e.target.closest(".seg-btn");
  if (!btn) return;
  dir = btn.dataset.dir;
  document.querySelectorAll(".seg-btn").forEach((b) => b.classList.remove("is-active"));
  btn.classList.add("is-active");
  renderNext();
  renderList();
});

// ── Tick ──────────────────────────────────────────────────────────────────────
function tick() {
  renderClock();
  renderNext();
  renderList();
}

// ── Init ──────────────────────────────────────────────────────────────────────
tick();
setInterval(tick, 30_000); // refresh every 30 s

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ── Layout ── */
.page {
  max-width: 760px;
  margin: 0 auto;
  padding: 40px 20px 72px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ── Hero ── */
.hero {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.eyebrow {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--teal-d);
}
.hero h1 {
  font-size: 2.1rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.1;
}
.lede {
  font-size: 1.02rem;
  color: var(--ink-2);
  max-width: 56ch;
}
.hero-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 6px;
}
.pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 7px 14px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ink-2);
  box-shadow: var(--shadow-1);
}
.pill .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ok);
  flex-shrink: 0;
}

/* ── Block (card section) ── */
.block {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 26px;
  box-shadow: var(--shadow-1);
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.block-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}
.block-head h2 {
  font-size: 1.22rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.sub {
  font-size: 0.88rem;
  color: var(--muted);
  margin-top: 3px;
  max-width: 44ch;
}

/* ── Payer search ── */
.search {
  position: relative;
  flex-shrink: 0;
}
.search-ico {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  color: var(--muted);
  pointer-events: none;
}
.search input {
  font: inherit;
  font-size: 0.88rem;
  width: 220px;
  max-width: 100%;
  padding: 10px 14px 10px 38px;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  background: var(--bg);
  color: var(--ink);
  transition: border-color 0.15s, background 0.15s, box-shadow 0.15s;
}
.search input::placeholder {
  color: var(--muted);
}
.search input:focus {
  outline: none;
  background: var(--white);
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(18, 156, 147, 0.14);
}

/* ── Payer grid ── */
.payers {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 12px;
}
.payer {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: #fafdfc;
  transition: border-color 0.15s, transform 0.12s, box-shadow 0.15s;
}
.payer:hover {
  border-color: var(--teal);
  box-shadow: var(--shadow-1);
  transform: translateY(-1px);
}
.payer[hidden] {
  display: none;
}
.logo {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  border-radius: 10px;
  display: grid;
  place-items: center;
  font-size: 0.84rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: #fff;
  background: var(--c, var(--teal-d));
  box-shadow: inset 0 -2px 6px rgba(0, 0, 0, 0.14);
}
.payer-name {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ink);
  min-width: 0;
}
.no-match {
  font-size: 0.9rem;
  color: var(--ink-2);
  background: var(--teal-50);
  border: 1px solid rgba(18, 156, 147, 0.22);
  border-radius: var(--r-sm);
  padding: 12px 14px;
}
.no-match[hidden] {
  display: none;
}
.fine {
  font-size: 0.82rem;
  color: var(--muted);
}

/* ── Pricing segmented toggle ── */
.seg {
  display: inline-flex;
  gap: 4px;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 4px;
  flex-shrink: 0;
}
.seg-btn {
  border: none;
  background: transparent;
  border-radius: 999px;
  padding: 8px 14px;
  font: inherit;
  font-weight: 600;
  font-size: 0.84rem;
  color: var(--muted);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  transition: background 0.15s, color 0.15s;
}
.seg-btn:hover {
  color: var(--ink-2);
}
.seg-btn.is-active {
  background: var(--teal-d);
  color: #fff;
}
.seg-save {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 999px;
  background: var(--coral-soft);
  color: #c4503a;
}
.seg-btn.is-active .seg-save {
  background: rgba(255, 255, 255, 0.22);
  color: #fff;
}

/* ── Pricing table ── */
.table {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
}
.trow {
  display: grid;
  grid-template-columns: 1fr 130px 130px;
  gap: 14px;
  align-items: center;
  padding: 16px 18px;
  border-bottom: 1px solid var(--line);
}
.trow:last-child {
  border-bottom: none;
}
.trow:not(.thead):hover {
  background: #fafdfc;
}
.thead {
  background: var(--teal-50);
  font-size: 0.74rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--teal-700);
}
.svc strong {
  display: block;
  font-size: 0.96rem;
  font-weight: 700;
  color: var(--ink);
}
.svc em {
  display: block;
  font-style: normal;
  font-size: 0.82rem;
  color: var(--muted);
  margin-top: 2px;
}
.dur {
  font-size: 0.86rem;
  color: var(--ink-2);
  font-weight: 500;
}
.ta-right {
  text-align: right;
}
.price {
  font-size: 1.06rem;
  font-weight: 800;
  color: var(--teal-d);
  font-variant-numeric: tabular-nums;
  transition: color 0.2s;
}
.price.is-member {
  color: var(--coral);
}

/* ── Coverage CTA ── */
.cta {
  background: linear-gradient(150deg, var(--teal-d), var(--teal-700));
  color: #fff;
  border-radius: var(--r-lg);
  padding: 30px;
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 28px;
  align-items: center;
  box-shadow: var(--shadow-2);
}
.cta-text h2 {
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.cta-text p {
  margin-top: 8px;
  font-size: 0.94rem;
  color: rgba(255, 255, 255, 0.86);
  max-width: 40ch;
}
.cta-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.field span {
  font-size: 0.78rem;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.88);
}
.field input {
  font: inherit;
  font-size: 0.9rem;
  padding: 11px 14px;
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: var(--r-sm);
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  transition: border-color 0.15s, background 0.15s, box-shadow 0.15s;
}
.field input::placeholder {
  color: rgba(255, 255, 255, 0.6);
}
.field input:focus {
  outline: none;
  background: rgba(255, 255, 255, 0.18);
  border-color: #fff;
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.18);
}
.field.invalid input {
  border-color: var(--coral);
  box-shadow: 0 0 0 3px rgba(255, 122, 102, 0.28);
}

/* ── Buttons ── */
.btn {
  border: none;
  border-radius: var(--r-sm);
  padding: 12px 18px;
  font: inherit;
  font-weight: 700;
  font-size: 0.9rem;
  cursor: pointer;
  transition: transform 0.12s, background 0.15s, color 0.15s, box-shadow 0.15s;
}
.btn:active {
  transform: translateY(1px);
}
.btn.solid {
  background: var(--white);
  color: var(--teal-d);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.16);
}
.btn.solid:hover {
  background: var(--teal-50);
}
.btn.solid:disabled {
  opacity: 0.7;
  cursor: progress;
}

/* ── FAQ accordion ── */
.faq {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
}
.faq-item {
  border-bottom: 1px solid var(--line);
}
.faq-item:last-child {
  border-bottom: none;
}
.faq-q {
  width: 100%;
  border: none;
  background: var(--white);
  font: inherit;
  font-weight: 600;
  font-size: 0.96rem;
  color: var(--ink);
  text-align: left;
  padding: 18px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.faq-q:hover {
  background: #fafdfc;
  color: var(--teal-d);
}
.faq-q[aria-expanded="true"] {
  color: var(--teal-d);
}
.chev {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  color: var(--muted);
  transition: transform 0.22s ease, color 0.15s;
}
.faq-q[aria-expanded="true"] .chev {
  transform: rotate(180deg);
  color: var(--teal-d);
}
.faq-a {
  overflow: hidden;
  max-height: 0;
  transition: max-height 0.26s ease;
}
.faq-a p {
  padding: 0 20px 18px;
  font-size: 0.9rem;
  color: var(--ink-2);
  max-width: 62ch;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}
.toast[hidden] {
  display: none;
}

/* ── Responsive ── */
@media (max-width: 520px) {
  .page {
    padding: 28px 16px 56px;
    gap: 18px;
  }
  .hero h1 {
    font-size: 1.7rem;
  }
  .block {
    padding: 20px 18px;
  }
  .block-head {
    flex-direction: column;
  }
  .search input {
    width: 100%;
  }
  .payers {
    grid-template-columns: 1fr 1fr;
  }
  .trow {
    grid-template-columns: 1fr auto;
    gap: 4px 12px;
  }
  .dur {
    grid-row: 2;
    grid-column: 1;
  }
  .price {
    grid-row: 1 / span 2;
    grid-column: 2;
    align-self: center;
  }
  .thead {
    display: none;
  }
  .cta {
    grid-template-columns: 1fr;
    padding: 24px 20px;
  }
}

@media (max-width: 360px) {
  .payers {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition: none !important;
  }
}

