// ── Toast ──────────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2800);
}

// ── Payer search filter ──────────────────────────────────────────────────────
const search = document.getElementById("payer-search");
const payers = Array.from(document.querySelectorAll("#payer-grid .payer"));
const payerEmpty = document.getElementById("payer-empty");

search.addEventListener("input", () => {
  const q = search.value.trim().toLowerCase();
  let shown = 0;
  payers.forEach((p) => {
    const match = p.dataset.name.toLowerCase().includes(q);
    p.hidden = !match;
    if (match) shown++;
  });
  payerEmpty.hidden = shown !== 0;
});

// ── Self-pay pricing toggle (Standard vs Care Member −15%) ────────────────────
const segBtns = Array.from(document.querySelectorAll(".seg-btn"));
const priceCells = Array.from(document.querySelectorAll(".trow[data-base]"));
const MEMBER_RATE = 0.85; // −15%

function renderPrices(cycle) {
  const member = cycle === "member";
  priceCells.forEach((row) => {
    const base = Number(row.dataset.base);
    const cell = row.querySelector("[data-price]");
    const value = member ? Math.round(base * MEMBER_RATE) : base;
    cell.textContent = "$" + value;
    cell.classList.toggle("is-member", member);
  });
}

segBtns.forEach((btn) => {
  btn.addEventListener("click", () => {
    segBtns.forEach((b) => {
      const active = b === btn;
      b.classList.toggle("is-active", active);
      b.setAttribute("aria-pressed", String(active));
    });
    renderPrices(btn.dataset.cycle);
    if (btn.dataset.cycle === "member") {
      showToast("Care Member rates applied — save 15% on self-pay services.");
    }
  });
});

// ── FAQ accordion (single-open) ──────────────────────────────────────────────
const faqButtons = Array.from(document.querySelectorAll(".faq-q"));

function closePanel(btn) {
  const panel = document.getElementById(btn.getAttribute("aria-controls"));
  btn.setAttribute("aria-expanded", "false");
  panel.style.maxHeight = "0px";
}

function openPanel(btn) {
  const panel = document.getElementById(btn.getAttribute("aria-controls"));
  btn.setAttribute("aria-expanded", "true");
  panel.style.maxHeight = panel.scrollHeight + "px";
}

faqButtons.forEach((btn) => {
  btn.addEventListener("click", () => {
    const isOpen = btn.getAttribute("aria-expanded") === "true";
    faqButtons.forEach((other) => {
      if (other !== btn) closePanel(other);
    });
    if (isOpen) closePanel(btn);
    else openPanel(btn);
  });
});

// Keep an open panel sized correctly when the viewport changes.
window.addEventListener("resize", () => {
  faqButtons.forEach((btn) => {
    if (btn.getAttribute("aria-expanded") === "true") {
      const panel = document.getElementById(btn.getAttribute("aria-controls"));
      panel.style.maxHeight = panel.scrollHeight + "px";
    }
  });
});

// ── Coverage check form ──────────────────────────────────────────────────────
const form = document.getElementById("coverage-form");
const planInput = document.getElementById("cv-plan");
const idInput = document.getElementById("cv-id");

[planInput, idInput].forEach((input) => {
  input.addEventListener("input", () => {
    input.closest(".field").classList.remove("invalid");
  });
});

form.addEventListener("submit", (e) => {
  e.preventDefault();
  let valid = true;
  [planInput, idInput].forEach((input) => {
    const ok = input.value.trim().length > 0;
    input.closest(".field").classList.toggle("invalid", !ok);
    if (!ok) valid = false;
  });

  if (!valid) {
    showToast("Add your plan and member ID so we can verify coverage.");
    (planInput.value.trim() ? idInput : planInput).focus();
    return;
  }

  const submitBtn = form.querySelector('button[type="submit"]');
  const planName = planInput.value.trim();
  submitBtn.disabled = true;
  submitBtn.textContent = "Checking…";
  showToast("Submitting your details to our billing team…");

  setTimeout(() => {
    submitBtn.disabled = false;
    submitBtn.textContent = "Check coverage";
    form.reset();
    showToast(`Thanks — we'll confirm your ${planName} coverage within one business day.`);
  }, 1400);
});

snippets.css:
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Topbar ── */
.topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  background: var(--navy-d);
  color: var(--bone);
  padding: 0 32px;
  height: 64px;
  display: flex;
  align-items: center;
  gap: 32px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--bone);
  flex-shrink: 0;
}
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: var(--r-sm);
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.2rem;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
}
.brand-name em {
  font-style: normal;
  color: var(--gold-light);
}
.top-nav {
  display: flex;
  gap: 6px;
  margin-left: 24px;
}
.top-nav a {
  text-decoration: none;
  color: rgba(251, 248, 242, 0.65);
  font-size: 0.86rem;
  font-weight: 500;
  padding: 6px 13px;
  border-radius: var(--r-sm);
  transition: color 0.15s, background 0.15s;
}
.top-nav a:hover,
.top-nav a.active {
  color: var(--bone);
  background: rgba(255, 255, 255, 0.08);
}
.top-nav a.active {
  color: var(--gold-light);
}
.nav-cta {
  margin-left: auto;
  background: var(--gold);
  color: var(--navy-d);
  font-weight: 700;
  font-size: 0.84rem;
  padding: 9px 20px;
  border-radius: 999px;
  text-decoration: none;
  transition: background 0.15s;
}
.nav-cta:hover {
  background: var(--gold-light);
}

/* ── Hero strip ── */
.hero-strip {
  background: linear-gradient(160deg, var(--navy-2) 0%, var(--navy-d) 55%, #070f1e 100%);
  color: var(--bone);
  padding: 60px 32px 48px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.hero-strip::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 50% at 50% 0%, rgba(201, 166, 73, 0.16), transparent 70%);
}
.breadcrumb {
  position: relative;
  font-size: 0.75rem;
  color: var(--gold-light);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 600;
  margin-bottom: 14px;
}
.hero-strip h1 {
  position: relative;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(2.2rem, 5vw, 3.6rem);
  line-height: 1.05;
}
.hero-sub {
  position: relative;
  margin-top: 12px;
  font-size: 0.95rem;
  color: rgba(251, 248, 242, 0.68);
}

/* ── Tabs bar ── */
.tabs-bar {
  background: var(--bone);
  border-bottom: 1px solid var(--line);
  padding: 0 32px;
  position: sticky;
  top: 64px;
  z-index: 20;
}
.tabs {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  gap: 4px;
  overflow-x: auto;
  scrollbar-width: none;
  padding: 10px 0;
}
.tabs::-webkit-scrollbar {
  display: none;
}
.tab {
  font-family: var(--font-body);
  font-size: 0.86rem;
  font-weight: 600;
  padding: 7px 18px;
  border: 1.5px solid transparent;
  border-radius: 999px;
  background: transparent;
  color: var(--ink-2);
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}
.tab:hover {
  border-color: var(--navy);
  color: var(--navy);
}
.tab.active {
  background: var(--navy);
  color: var(--bone);
  border-color: var(--navy);
}

/* ── Content wrap ── */
.content-wrap {
  max-width: 1200px;
  margin: 0 auto;
  padding: 36px 32px 72px;
  display: flex;
  flex-direction: column;
  gap: 60px;
}

/* ── Amenity grid ── */
.amenity-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 20px;
}
.amenity-card {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 28px 24px 22px;
  box-shadow: var(--shadow-1);
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: box-shadow 0.18s, transform 0.18s;
}
.amenity-card:hover {
  box-shadow: var(--shadow-2);
  transform: translateY(-2px);
}
.amenity-icon {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  font-size: 1.6rem;
  background: linear-gradient(135deg, var(--navy-2), var(--navy-d));
  border-radius: var(--r-md);
  color: var(--gold-light);
  flex-shrink: 0;
}
.amenity-card h3 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.3rem;
  color: var(--navy-d);
  line-height: 1.15;
}
.amenity-card p {
  font-size: 0.84rem;
  color: var(--warm-gray);
  line-height: 1.55;
}
.amenity-hours {
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  font-size: 0.76rem;
  font-weight: 600;
  color: var(--gold-d);
  display: flex;
  align-items: center;
  gap: 6px;
}

/* ── Empty state ── */
.empty {
  text-align: center;
  padding: 60px 24px;
  color: var(--warm-gray);
  font-style: italic;
  background: var(--bone);
  border: 1px dashed var(--line-strong);
  border-radius: var(--r-md);
}

/* ── Section title ── */
.section-title {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 2rem;
  color: var(--navy-d);
  margin-bottom: 20px;
}

/* ── Accordion ── */
.accordion-section {
}
.accordion {
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  background: var(--bone);
}
.acc-item {
  border-bottom: 1px solid var(--line);
}
.acc-item:last-child {
  border-bottom: none;
}
.acc-trigger {
  width: 100%;
  background: none;
  border: none;
  padding: 18px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  cursor: pointer;
  text-align: left;
  transition: background 0.15s;
}
.acc-trigger:hover {
  background: var(--cream);
}
.acc-trigger-left {
  display: flex;
  align-items: center;
  gap: 14px;
}
.acc-ico {
  font-size: 1.4rem;
  width: 36px;
  text-align: center;
  flex-shrink: 0;
}
.acc-name {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--navy-d);
}
.acc-chevron {
  font-size: 1rem;
  color: var(--warm-gray);
  transition: transform 0.22s;
  flex-shrink: 0;
}
.acc-item.open .acc-chevron {
  transform: rotate(180deg);
}
.acc-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.28s ease;
}
.acc-body-inner {
  padding: 0 24px 20px 74px;
}
.hours-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.86rem;
}
.hours-table td {
  padding: 5px 0;
  color: var(--ink-2);
}
.hours-table td:first-child {
  width: 160px;
  color: var(--warm-gray);
  font-weight: 500;
}
.hours-table td:last-child {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.82rem;
}
.highlight-row td {
  color: var(--gold-d) !important;
  font-weight: 600;
}

/* ── Form section ── */
.form-section {
}
.form-card {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 36px 40px;
  max-width: 640px;
  box-shadow: var(--shadow-1);
}
.form-card h2 {
  font-family: var(--font-display);
  font-size: 1.9rem;
  font-weight: 700;
  color: var(--navy-d);
  margin-bottom: 6px;
}
.form-desc {
  font-size: 0.86rem;
  color: var(--warm-gray);
  margin-bottom: 24px;
}
.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 16px;
}
.field label {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--ink-2);
  text-transform: uppercase;
  letter-spacing: 0.07em;
}
.field input,
.field select,
.field textarea {
  font-family: var(--font-body);
  font-size: 0.9rem;
  color: var(--ink);
  background: var(--cream);
  border: 1.5px solid var(--line-strong);
  border-radius: var(--r-sm);
  padding: 10px 14px;
  transition: border-color 0.15s, box-shadow 0.15s;
  resize: vertical;
}
.field input:focus,
.field select:focus,
.field textarea:focus {
  outline: none;
  border-color: var(--navy);
  box-shadow: 0 0 0 3px rgba(26, 43, 74, 0.1);
}
.field input.invalid,
.field select.invalid {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(179, 66, 50, 0.1);
}
.field-error {
  font-size: 0.74rem;
  color: var(--danger);
  min-height: 16px;
}
.optional {
  color: var(--warm-gray);
  font-weight: 400;
  text-transform: none;
  letter-spacing: 0;
}
.submit-btn {
  font-family: var(--font-body);
  font-size: 0.9rem;
  font-weight: 700;
  background: var(--navy);
  color: var(--bone);
  border: none;
  border-radius: var(--r-sm);
  padding: 13px 28px;
  cursor: pointer;
  transition: background 0.15s;
  width: 100%;
  margin-top: 4px;
}
.submit-btn:hover {
  background: var(--navy-d);
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 12px 24px;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 50;
  white-space: nowrap;
}

/* ── Responsive ── */
@media (max-width: 960px) {
  .top-nav {
    display: none;
  }
  .content-wrap {
    padding: 28px 20px 56px;
  }
  .amenity-grid {
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  }
  .form-card {
    padding: 28px 24px;
  }
}
@media (max-width: 560px) {
  .topbar {
    padding: 0 18px;
    gap: 16px;
  }
  .hero-strip {
    padding: 44px 20px 36px;
  }
  .tabs-bar {
    padding: 0 18px;
  }
  .content-wrap {
    padding: 24px 18px 48px;
  }
  .amenity-grid {
    grid-template-columns: 1fr 1fr;
  }
  .form-row {
    grid-template-columns: 1fr;
  }
  .acc-body-inner {
    padding-left: 24px;
  }
}
@media (max-width: 400px) {
  .amenity-grid {
    grid-template-columns: 1fr;
  }
}

