// ── Toast ──────────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2600);
}

// ── Card flip ────────────────────────────────────────────────────────────────
const flip = document.getElementById("flip");
const flipInner = document.getElementById("flipInner");
const flipBtn = document.getElementById("flipBtn");

function setFace(face) {
  flip.dataset.face = face;
  const onBack = face === "back";
  flipInner.setAttribute("aria-pressed", String(onBack));
  flipInner.setAttribute(
    "aria-label",
    `Insurance card, showing ${onBack ? "back" : "front"}. Activate to flip.`,
  );
  flipInner.querySelector(".face-front").setAttribute("aria-hidden", String(onBack));
  flipInner.querySelector(".face-back").setAttribute("aria-hidden", String(!onBack));
}

function toggleFace() {
  setFace(flip.dataset.face === "back" ? "front" : "back");
}

// Flip on card activation (click / Enter / Space all fire click on a <button>)
flipInner.addEventListener("click", toggleFace);
flipBtn.addEventListener("click", (e) => {
  e.stopPropagation();
  toggleFace();
});

// ── Copy member ID ───────────────────────────────────────────────────────────
const copyBtn = document.getElementById("copyBtn");
const memberIdText = document.getElementById("memberId").textContent.trim();

async function copyMemberId() {
  let ok = false;
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(memberIdText);
      ok = true;
    } else {
      const ta = document.createElement("textarea");
      ta.value = memberIdText;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      ok = document.execCommand("copy");
      ta.remove();
    }
  } catch (_) {
    ok = false;
  }

  if (ok) {
    showToast(`Member ID ${memberIdText} copied to clipboard.`);
    copyBtn.classList.add("is-done");
    const label = copyBtn.innerHTML;
    copyBtn.innerHTML = '<span class="ico" aria-hidden="true">✓</span> Copied';
    clearTimeout(copyMemberId._t);
    copyMemberId._t = setTimeout(() => {
      copyBtn.classList.remove("is-done");
      copyBtn.innerHTML = label;
    }, 1800);
  } else {
    showToast(`Couldn't copy automatically — your Member ID is ${memberIdText}.`);
  }
}
copyBtn.addEventListener("click", copyMemberId);

// ── Animate coverage bars on load ────────────────────────────────────────────
function animateBars() {
  document.querySelectorAll(".bar-fill").forEach((fill) => {
    const target = getComputedStyle(fill).getPropertyValue("--pct").trim() || "0%";
    fill.style.width = "0%";
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        fill.style.width = target;
      });
    });
  });
}

if (document.readyState === "complete") animateBars();
else window.addEventListener("load", animateBars);

snippets.css:
:root {
  --cream: #f4efe4;
  --paper: #faf7f0;
  --white: #ffffff;
  --newsprint: #efe9da;
  --ink: #16130f;
  --ink-2: #2b2620;
  --ink-3: #4a443b;
  --muted: #7a7164;
  --red: #b4291f;
  --red-d: #8f1f17;
  --red-50: #f3dcd9;
  --rule: rgba(22, 19, 15, 0.16);
  --rule-2: rgba(22, 19, 15, 0.3);
  --rule-hair: rgba(22, 19, 15, 0.1);
  --ok: #2f7d4f;
  --warn: #b67a18;
  --danger: #b4291f;
  --r-sm: 4px;
  --r-md: 8px;
  --r-lg: 12px;
  --serif: "Playfair Display", "Times New Roman", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;
  --read: 17px;
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--cream);
  color: var(--ink);
  font-family: var(--sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

a {
  color: inherit;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* Reading progress -------------------------------------------------------- */
.progress {
  position: fixed;
  inset: 0 0 auto 0;
  height: 3px;
  background: transparent;
  z-index: 50;
}
.progress span {
  display: block;
  height: 100%;
  width: 0%;
  background: var(--red);
  transition: width 0.08s linear;
}

/* Masthead ---------------------------------------------------------------- */
.masthead {
  border-bottom: 2px solid var(--ink);
  background: var(--paper);
}
.masthead__inner {
  max-width: 1180px;
  margin: 0 auto;
  padding: 14px 24px 10px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 12px;
}
.masthead__date {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-3);
  font-weight: 600;
}
.masthead__name {
  font-family: var(--serif);
  font-weight: 800;
  font-size: clamp(28px, 5vw, 46px);
  letter-spacing: 0.01em;
  text-align: center;
  text-decoration: none;
  white-space: nowrap;
  line-height: 1;
}
.masthead__tools {
  text-align: right;
}
.masthead__price {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-3);
  font-weight: 600;
}
.subnav {
  border-top: 1px solid var(--rule-hair);
  background: var(--paper);
}
.subnav ul {
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 24px;
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 22px;
  justify-content: center;
}
.subnav a {
  display: inline-block;
  padding: 9px 0;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-2);
  text-decoration: none;
  border-bottom: 2px solid transparent;
}
.subnav a:hover {
  color: var(--red);
}
.subnav a[aria-current="page"] {
  border-bottom-color: var(--red);
  color: var(--ink);
}

/* Layout ------------------------------------------------------------------ */
.wrap {
  max-width: 820px;
  margin: 0 auto;
  padding: 0 24px 64px;
}

/* Article head ------------------------------------------------------------ */
.article__head {
  padding: 38px 0 22px;
  text-align: center;
}
.kicker {
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--ink-3);
  margin: 0 0 16px;
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.kicker__tag {
  background: var(--red);
  color: var(--paper);
  padding: 3px 8px;
  border-radius: var(--r-sm);
  letter-spacing: 0.14em;
}
.headline {
  font-family: var(--serif);
  font-weight: 800;
  font-size: clamp(32px, 6vw, 56px);
  line-height: 1.04;
  letter-spacing: -0.01em;
  margin: 0 auto;
  max-width: 16ch;
  color: var(--ink);
}
.deck {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(17px, 2.6vw, 22px);
  line-height: 1.42;
  color: var(--ink-3);
  max-width: 44ch;
  margin: 18px auto 0;
}

/* Byline ------------------------------------------------------------------ */
.byline {
  margin-top: 26px;
  padding: 16px 0;
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  text-align: left;
  flex-wrap: wrap;
}
.byline__author {
  display: flex;
  align-items: center;
  gap: 12px;
}
.byline__avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 700;
  font-size: 14px;
  color: var(--paper);
  background: linear-gradient(135deg, var(--ink-2), var(--ink));
  letter-spacing: 0.02em;
  flex: none;
}
.byline__who {
  display: flex;
  flex-direction: column;
}
.byline__name {
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.02em;
}
.byline__dateline {
  font-size: 12px;
  color: var(--muted);
  letter-spacing: 0.04em;
}
.share {
  display: flex;
  gap: 8px;
}
.share__btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-family: var(--sans);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: var(--ink-2);
  background: var(--white);
  border: 1px solid var(--rule);
  border-radius: var(--r-sm);
  padding: 7px 11px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}
.share__btn svg {
  width: 15px;
  height: 15px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.share__btn:hover {
  border-color: var(--ink);
  color: var(--ink);
}
.share__btn[data-share="x"],
.share__btn[data-share="mail"] {
  padding: 7px 9px;
}
.share__btn:focus-visible,
.controls__btn:focus-visible,
.subnav a:focus-visible {
  outline: 2px solid var(--red);
  outline-offset: 2px;
}

/* Hero figure ------------------------------------------------------------- */
figure {
  margin: 0;
}
.hero {
  margin: 28px 0 8px;
}
.hero__img {
  aspect-ratio: 16 / 9;
  border-radius: var(--r-sm);
  background: var(--newsprint);
}
.hero__img--dune {
  background:
    radial-gradient(120% 90% at 18% 8%, rgba(255, 238, 200, 0.85), transparent 46%),
    radial-gradient(140% 120% at 88% 96%, rgba(22, 19, 15, 0.62), transparent 50%),
    linear-gradient(176deg, #c9b58a 0%, #b39a6c 34%, #6f7c70 60%, #2f3a3a 100%);
}
figcaption {
  margin-top: 9px;
  font-size: 12.5px;
  line-height: 1.4;
  color: var(--muted);
  padding-bottom: 4px;
}
.cap {
  font-style: italic;
  color: var(--ink-3);
}
.credit {
  display: block;
  margin-top: 3px;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

/* Controls ---------------------------------------------------------------- */
.controls {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 22px 0 4px;
  padding: 10px 0;
  border-top: 1px solid var(--rule-hair);
  border-bottom: 1px solid var(--rule-hair);
}
.controls__label {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--muted);
  margin-right: auto;
}
.controls__btn {
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-2);
  background: var(--white);
  border: 1px solid var(--rule);
  border-radius: var(--r-sm);
  padding: 6px 12px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.controls__btn:hover {
  border-color: var(--ink);
}
.controls__btn:active {
  background: var(--newsprint);
}

/* Body -------------------------------------------------------------------- */
.body {
  margin-top: 26px;
  font-size: var(--read);
  line-height: 1.72;
  color: var(--ink-2);
}
.body p {
  margin: 0 0 1.25em;
  text-align: justify;
  hyphens: auto;
}
.body p:last-child {
  margin-bottom: 0;
}
.lead {
  font-size: 1.06em;
}
.lead::first-letter {
  font-family: var(--serif);
  font-weight: 800;
  float: left;
  font-size: 4.4em;
  line-height: 0.78;
  padding: 0.04em 0.1em 0 0;
  margin: 0.02em 0 0;
  color: var(--red);
}
.body em {
  font-style: italic;
}

/* Inline related box ------------------------------------------------------ */
.relatedbox {
  float: right;
  width: 268px;
  max-width: 50%;
  margin: 4px 0 18px 26px;
  padding: 16px 18px;
  background: var(--paper);
  border-top: 3px solid var(--red);
  border-bottom: 1px solid var(--rule);
}
.relatedbox__label {
  margin: 0 0 10px;
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--red);
}
.relatedbox ul {
  margin: 0;
  padding: 0;
  list-style: none;
}
.relatedbox li {
  border-top: 1px solid var(--rule-hair);
  padding: 9px 0;
}
.relatedbox li:first-child {
  border-top: 0;
  padding-top: 0;
}
.relatedbox a {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 16px;
  line-height: 1.3;
  color: var(--ink);
  text-decoration: none;
  text-align: left;
  display: block;
}
.relatedbox a:hover {
  color: var(--red);
}

/* Pull quote -------------------------------------------------------------- */
.pull {
  margin: 30px 0;
  padding: 6px 0 6px 24px;
  border-left: 3px solid var(--red);
  clear: both;
}
.pull p {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 600;
  font-size: clamp(22px, 4vw, 30px);
  line-height: 1.22;
  color: var(--ink);
  margin: 0;
  text-align: left;
  hyphens: manual;
}
.pull cite {
  display: block;
  margin-top: 12px;
  font-family: var(--sans);
  font-style: normal;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

/* Inset figure ------------------------------------------------------------ */
.inset {
  margin: 26px 0;
  clear: both;
}
.inset__img {
  aspect-ratio: 5 / 3;
  border-radius: var(--r-sm);
  background:
    repeating-linear-gradient(90deg, rgba(22, 19, 15, 0.05) 0 1px, transparent 1px 38px),
    radial-gradient(120% 140% at 0% 100%, rgba(180, 41, 31, 0.4), transparent 55%),
    linear-gradient(180deg, #e6dcc4 0%, #cdbf9c 55%, #5d6a66 100%);
}

/* Article footer ---------------------------------------------------------- */
.article__foot {
  margin-top: 32px;
  padding-top: 18px;
  border-top: 1px solid var(--rule);
}
.article__tags {
  margin: 0;
  font-size: 12px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.article__tags span {
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}
.article__tags a {
  text-decoration: none;
  color: var(--ink-2);
  background: var(--white);
  border: 1px solid var(--rule);
  border-radius: 999px;
  padding: 4px 11px;
  font-weight: 600;
}
.article__tags a:hover {
  border-color: var(--red);
  color: var(--red);
}

/* Related cards ----------------------------------------------------------- */
.related {
  margin-top: 56px;
  padding-top: 18px;
  border-top: 2px solid var(--ink);
}
.related__heading {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 22px;
  margin: 0 0 22px;
  letter-spacing: -0.01em;
}
.related__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 26px;
}
.card {
  text-decoration: none;
  color: inherit;
  display: block;
}
.card__img {
  aspect-ratio: 4 / 3;
  border-radius: var(--r-sm);
  margin-bottom: 12px;
  background: var(--newsprint);
}
.card:hover .card__img {
  filter: brightness(0.94);
}
.card__img--forest {
  background:
    radial-gradient(120% 90% at 80% 6%, rgba(255, 210, 120, 0.7), transparent 50%),
    linear-gradient(170deg, #8a6a3a 0%, #4f5a36 55%, #1d251a 100%);
}
.card__img--grid {
  background:
    repeating-linear-gradient(45deg, rgba(250, 247, 240, 0.18) 0 1px, transparent 1px 16px),
    linear-gradient(160deg, #46566a 0%, #2a3340 60%, #b4291f 160%);
}
.card__img--river {
  background:
    radial-gradient(140% 100% at 20% 90%, rgba(180, 41, 31, 0.35), transparent 55%),
    linear-gradient(165deg, #cdd6cf 0%, #7e9189 45%, #2c4742 100%);
}
.card__kicker {
  margin: 0 0 6px;
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--red);
}
.card__title {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 19px;
  line-height: 1.22;
  margin: 0 0 8px;
  letter-spacing: -0.005em;
}
.card:hover .card__title {
  text-decoration: underline;
  text-decoration-color: var(--rule-2);
  text-underline-offset: 2px;
}
.card__meta {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
  letter-spacing: 0.02em;
}

/* Site footer ------------------------------------------------------------- */
.sitefoot {
  border-top: 1px solid var(--rule);
  background: var(--paper);
  text-align: center;
  padding: 26px 24px;
}
.sitefoot p {
  margin: 0;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 15px;
  color: var(--ink-2);
}
.sitefoot__fine {
  margin-top: 6px !important;
  font-family: var(--sans) !important;
  font-weight: 400 !important;
  font-size: 12px !important;
  color: var(--muted) !important;
}

/* Toast ------------------------------------------------------------------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 16px);
  background: var(--ink);
  color: var(--paper);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.02em;
  padding: 11px 18px;
  border-radius: var(--r-md);
  box-shadow: 0 6px 22px rgba(22, 19, 15, 0.28);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s, transform 0.22s;
  z-index: 60;
  max-width: 90vw;
}
.toast.is-on {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* Responsive -------------------------------------------------------------- */
@media (max-width: 720px) {
  .masthead__inner {
    grid-template-columns: 1fr;
    text-align: center;
    gap: 6px;
  }
  .masthead__tools {
    text-align: center;
  }
  .subnav ul {
    justify-content: flex-start;
    gap: 16px;
    overflow-x: auto;
    flex-wrap: nowrap;
    -webkit-overflow-scrolling: touch;
  }
  .relatedbox {
    float: none;
    width: auto;
    max-width: none;
    margin: 22px 0;
  }
  .related__grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }
  .byline {
    align-items: flex-start;
  }
}

@media (max-width: 420px) {
  .wrap {
    padding: 0 18px 48px;
  }
  .controls__label {
    display: none;
  }
  .share__btn[data-share="link"] span {
    display: none;
  }
  .lead::first-letter {
    font-size: 3.8em;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}

