(function () {
  "use strict";

  /* ---------- Data: fictional Maple Grove, OR listings ---------- */
  var LISTINGS = [
    { id: "L1", price: 689000, beds: 3, baths: 2, sqft: 1840, type: "House", status: "New",
      addr: "412 Larkspur Lane", agent: "Nora Avery", img: 0, featured: 9, days: 2, x: 22, y: 55 },
    { id: "L2", price: 1245000, beds: 4, baths: 3, sqft: 2960, type: "House", status: "For sale",
      addr: "8 Wren Hollow Court", agent: "Desmond Hale", img: 1, featured: 7, days: 11, x: 64, y: 28 },
    { id: "L3", price: 472500, beds: 2, baths: 2, sqft: 1180, type: "Condo", status: "Open house",
      addr: "210 Cedar Mill Rd, #4B", agent: "Priya Mehta", img: 3, featured: 6, days: 5, x: 41, y: 70 },
    { id: "L4", price: 815000, beds: 3, baths: 2, sqft: 2110, type: "Townhouse", status: "For sale",
      addr: "57 Aspen Ridge Way", agent: "Marcus Boone", img: 2, featured: 5, days: 18, x: 78, y: 60 },
    { id: "L5", price: 1590000, beds: 5, baths: 3, sqft: 3680, type: "House", status: "New",
      addr: "1 Heron Bluff Estate", agent: "Eleanor Frost", img: 5, featured: 10, days: 1, x: 30, y: 22 },
    { id: "L6", price: 539000, beds: 2, baths: 1, sqft: 980, type: "Loft", status: "For sale",
      addr: "94 Foundry St, Loft 3", agent: "Theo Salas", img: 4, featured: 4, days: 24, x: 53, y: 44 },
    { id: "L7", price: 725000, beds: 3, baths: 2, sqft: 1720, type: "House", status: "Pending",
      addr: "330 Willowmere Drive", agent: "Nora Avery", img: 1, featured: 3, days: 32, x: 15, y: 38 },
    { id: "L8", price: 968000, beds: 4, baths: 3, sqft: 2540, type: "House", status: "Open house",
      addr: "6 Briarwood Crescent", agent: "Desmond Hale", img: 0, featured: 8, days: 4, x: 70, y: 80 },
    { id: "L9", price: 419000, beds: 1, baths: 1, sqft: 760, type: "Condo", status: "For sale",
      addr: "188 Maple Square, #12", agent: "Priya Mehta", img: 3, featured: 2, days: 40, x: 47, y: 18 }
  ];

  var STATUS_CLASS = { "New": "badge--new", "Open house": "badge--open", "Pending": "badge--pending", "For sale": "" };

  /* ---------- DOM ---------- */
  var grid = document.getElementById("grid");
  var pinsWrap = document.getElementById("pins");
  var emptyEl = document.getElementById("empty");
  var countNum = document.getElementById("countNum");
  var toastEl = document.getElementById("toast");

  var fPrice = document.getElementById("fPrice");
  var fBeds = document.getElementById("fBeds");
  var fBaths = document.getElementById("fBaths");
  var fType = document.getElementById("fType");
  var fSqft = document.getElementById("fSqft");
  var sortSel = document.getElementById("sortSel");
  var statusBoxes = Array.prototype.slice.call(document.querySelectorAll('input[name="status"]'));

  var activeId = null;
  var favs = {};

  /* ---------- Helpers ---------- */
  var toastTimer;
  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add("is-on");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { toastEl.classList.remove("is-on"); }, 2600);
  }

  function money(n) {
    if (n >= 1000000) return "$" + (n / 1000000).toFixed(n % 1000000 === 0 ? 0 : 2).replace(/\.?0+$/, "") + "M";
    return "$" + n.toLocaleString("en-US");
  }
  function fullMoney(n) { return "$" + n.toLocaleString("en-US"); }

  /* ---------- Filtering + sorting ---------- */
  function getFiltered() {
    var priceRange = fPrice.value;
    var minBeds = parseInt(fBeds.value, 10);
    var minBaths = parseInt(fBaths.value, 10);
    var type = fType.value;
    var minSqft = parseInt(fSqft.value, 10);
    var allowedStatus = statusBoxes.filter(function (b) { return b.checked; }).map(function (b) { return b.value; });

    var lo = 0, hi = Infinity;
    if (priceRange !== "any") { var p = priceRange.split("-"); lo = +p[0]; hi = +p[1]; }

    var out = LISTINGS.filter(function (l) {
      if (l.price < lo || l.price > hi) return false;
      if (l.beds < minBeds) return false;
      if (l.baths < minBaths) return false;
      if (type !== "any" && l.type !== type) return false;
      if (l.sqft < minSqft) return false;
      if (allowedStatus.indexOf(l.status) === -1) return false;
      return true;
    });

    var s = sortSel.value;
    out.sort(function (a, b) {
      switch (s) {
        case "price-asc": return a.price - b.price;
        case "price-desc": return b.price - a.price;
        case "beds-desc": return b.beds - a.beds || b.price - a.price;
        case "sqft-desc": return b.sqft - a.sqft;
        case "newest": return a.days - b.days;
        default: return b.featured - a.featured;
      }
    });
    return out;
  }

  /* ---------- Rendering ---------- */
  function render() {
    var items = getFiltered();
    countNum.textContent = items.length;
    grid.innerHTML = "";
    pinsWrap.innerHTML = "";

    if (!items.length) {
      emptyEl.hidden = false;
      grid.hidden = true;
      return;
    }
    emptyEl.hidden = true;
    grid.hidden = false;

    items.forEach(function (l) {
      grid.appendChild(buildCard(l));
      pinsWrap.appendChild(buildPin(l));
    });

    if (activeId && !items.some(function (l) { return l.id === activeId; })) activeId = null;
    syncActive();
  }

  function buildCard(l) {
    var card = document.createElement("article");
    card.className = "card";
    card.tabIndex = 0;
    card.dataset.id = l.id;
    card.setAttribute("role", "button");
    card.setAttribute("aria-label", money(l.price) + ", " + l.beds + " bed " + l.type + " at " + l.addr);

    var badgeClass = STATUS_CLASS[l.status] || "";
    var isFav = !!favs[l.id];

    card.innerHTML =
      '<div class="card__photo" data-img="' + l.img + '">' +
        '<span class="badge ' + badgeClass + '">' + l.status + '</span>' +
        '<button class="fav' + (isFav ? ' is-fav' : '') + '" type="button" aria-pressed="' + isFav + '" aria-label="Save listing">' +
          '<svg viewBox="0 0 24 24" width="17" height="17" aria-hidden="true"><path fill="currentColor" d="M12 21l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.18L12 21z"/></svg>' +
        '</button>' +
      '</div>' +
      '<div class="card__body">' +
        '<div class="card__price">' + fullMoney(l.price) + '</div>' +
        '<div class="card__specs">' +
          '<span><b>' + l.beds + '</b>&nbsp;bd</span>' +
          '<span><b>' + l.baths + '</b>&nbsp;ba</span>' +
          '<span><b>' + l.sqft.toLocaleString("en-US") + '</b>&nbsp;sqft</span>' +
        '</div>' +
        '<div class="card__addr">' + l.addr + ', Maple Grove, OR</div>' +
        '<div class="card__meta">' +
          '<span class="card__type">' + l.type + '</span>' +
          '<span class="card__agent">Listed by ' + l.agent + '</span>' +
        '</div>' +
      '</div>';

    var fav = card.querySelector(".fav");
    fav.addEventListener("click", function (e) {
      e.stopPropagation();
      toggleFav(l, fav);
    });

    card.addEventListener("click", function () { setActive(l.id, true); });
    card.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setActive(l.id, true); }
    });
    card.addEventListener("mouseenter", function () { highlightPin(l.id, true); });
    card.addEventListener("mouseleave", function () { if (activeId !== l.id) highlightPin(l.id, false); });
    return card;
  }

  function buildPin(l) {
    var pin = document.createElement("button");
    pin.type = "button";
    pin.className = "pin";
    pin.dataset.id = l.id;
    pin.style.left = l.x + "%";
    pin.style.top = l.y + "%";
    pin.textContent = money(l.price);
    pin.setAttribute("aria-label", money(l.price) + " at " + l.addr);
    pin.addEventListener("click", function () { setActive(l.id, false); });
    pin.addEventListener("mouseenter", function () { highlightCard(l.id, true); });
    pin.addEventListener("mouseleave", function () { if (activeId !== l.id) highlightCard(l.id, false); });
    return pin;
  }

  /* ---------- Favorites ---------- */
  function toggleFav(l, btn) {
    favs[l.id] = !favs[l.id];
    btn.classList.toggle("is-fav", favs[l.id]);
    btn.setAttribute("aria-pressed", String(favs[l.id]));
    toast(favs[l.id] ? "Saved " + l.addr + " to favorites" : "Removed from favorites");
  }

  /* ---------- Active sync (cards <-> pins) ---------- */
  function setActive(id, fromCard) {
    activeId = (activeId === id) ? null : id;
    syncActive();
    if (activeId) {
      var sel = activeId;
      if (fromCard) {
        var pin = pinsWrap.querySelector('.pin[data-id="' + sel + '"]');
        if (pin) pin.focus({ preventScroll: true });
      } else {
        var card = grid.querySelector('.card[data-id="' + sel + '"]');
        if (card) card.scrollIntoView({ behavior: "smooth", block: "center" });
      }
    }
  }

  function syncActive() {
    Array.prototype.forEach.call(grid.querySelectorAll(".card"), function (c) {
      c.classList.toggle("is-active", c.dataset.id === activeId);
    });
    Array.prototype.forEach.call(pinsWrap.querySelectorAll(".pin"), function (p) {
      p.classList.toggle("is-active", p.dataset.id === activeId);
    });
  }

  function highlightCard(id, on) {
    var c = grid.querySelector('.card[data-id="' + id + '"]');
    if (c) c.classList.toggle("is-active", on || activeId === id);
  }
  function highlightPin(id, on) {
    var p = pinsWrap.querySelector('.pin[data-id="' + id + '"]');
    if (p) p.classList.toggle("is-active", on || activeId === id);
  }

  /* ---------- More filters toggle ---------- */
  var moreBtn = document.getElementById("moreFiltersBtn");
  var morePanel = document.getElementById("moreFilters");
  moreBtn.addEventListener("click", function () {
    var open = morePanel.hasAttribute("hidden");
    if (open) morePanel.removeAttribute("hidden"); else morePanel.setAttribute("hidden", "");
    moreBtn.setAttribute("aria-expanded", String(open));
  });

  /* ---------- Save search ---------- */
  var saveBtn = document.getElementById("saveSearchBtn");
  var searchSaved = false;
  saveBtn.addEventListener("click", function () {
    searchSaved = !searchSaved;
    saveBtn.classList.toggle("is-saved", searchSaved);
    saveBtn.lastChild.textContent = searchSaved ? " Search saved" : " Save search";
    var n = getFiltered().length;
    toast(searchSaved ? "Search saved — we'll alert you when new homes match (" + n + " now)" : "Saved search removed");
  });

  /* ---------- Reset ---------- */
  document.getElementById("resetBtn").addEventListener("click", function () {
    fPrice.value = "any"; fBeds.value = "0"; fBaths.value = "0";
    fType.value = "any"; fSqft.value = "0"; sortSel.value = "featured";
    statusBoxes.forEach(function (b) { b.checked = true; });
    activeId = null;
    render();
    toast("Filters reset");
  });

  /* ---------- Wire up live filtering ---------- */
  [fPrice, fBeds, fBaths, fType, fSqft, sortSel].forEach(function (el) {
    el.addEventListener("change", render);
  });
  statusBoxes.forEach(function (b) { b.addEventListener("change", render); });

  /* ---------- Init ---------- */
  render();
})();

snippets.css:
:root {
  --bg: #101113;
  --surface: #191b1e;
  --surface-2: #202327;
  --elevated: #282b30;
  --ink: #f2f3f4;
  --ink-2: #b7bbc0;
  --muted: #7d8288;
  --yellow: #ffd21f;
  --yellow-d: #e6bd00;
  --yellow-50: rgba(255, 210, 31, 0.12);
  --concrete: #3a3d42;
  --line: rgba(255, 255, 255, 0.1);
  --line-2: rgba(255, 255, 255, 0.18);
  --ok: #5fd38a;
  --warn: #ffb84d;
  --danger: #ff6b6b;
  --r-sm: 4px;
  --r-md: 6px;
  --r-lg: 10px;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.55);
  --tape: repeating-linear-gradient(
    -45deg,
    var(--yellow) 0 22px,
    #101113 22px 44px
  );
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

.wrap {
  width: min(1180px, 92vw);
  margin-inline: auto;
}

.skip {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--yellow);
  color: #101113;
  padding: 10px 16px;
  font-weight: 800;
  z-index: 200;
}
.skip:focus {
  left: 12px;
  top: 12px;
}

/* ---- Typography helpers ---- */
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: "Oswald", "Inter", sans-serif;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 0.74rem;
  color: var(--ink-2);
  margin: 0 0 14px;
}
.eyebrow .dot {
  width: 8px;
  height: 8px;
  background: var(--yellow);
  display: inline-block;
}
.eyebrow--y {
  color: var(--yellow);
}
.up {
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.72rem;
  font-weight: 700;
}
.muted {
  color: var(--muted);
}
.ok {
  color: var(--ok);
}
.warn {
  color: var(--warn);
}
.danger {
  color: var(--danger);
}

.sec-head {
  max-width: 640px;
  margin-bottom: 40px;
}
.sec-title {
  font-family: "Oswald", "Inter", sans-serif;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.01em;
  font-size: clamp(2rem, 5vw, 3.2rem);
  line-height: 0.98;
  margin: 0 0 12px;
}
.sec-sub {
  color: var(--ink-2);
  margin: 0;
  font-size: 1.02rem;
}

/* ---- Buttons ---- */
.btn {
  --pad-y: 12px;
  --pad-x: 22px;
  font-family: "Oswald", "Inter", sans-serif;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  font-size: 0.92rem;
  border: 1px solid transparent;
  border-radius: var(--r-sm);
  padding: var(--pad-y) var(--pad-x);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: transform 0.12s ease, background 0.15s ease, box-shadow 0.15s ease,
    border-color 0.15s ease;
  background: var(--surface-2);
  color: var(--ink);
}
.btn:hover {
  transform: translateY(-2px);
}
.btn:active {
  transform: translateY(0);
}
.btn:focus-visible {
  outline: 3px solid var(--yellow);
  outline-offset: 2px;
}
.btn--yellow {
  background: var(--yellow);
  color: #101113;
  box-shadow: 0 0 0 1px var(--yellow-d) inset;
}
.btn--yellow:hover {
  background: var(--yellow-d);
}
.btn--dark {
  background: #101113;
  color: var(--ink);
  border-color: var(--line-2);
}
.btn--dark:hover {
  border-color: var(--yellow);
}
.btn--ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--line-2);
}
.btn--ghost:hover {
  border-color: var(--yellow);
  color: var(--yellow);
}
.btn--block {
  width: 100%;
}
.btn--lg {
  --pad-y: 16px;
  --pad-x: 30px;
  font-size: 1rem;
}
.btn--sm {
  --pad-y: 9px;
  --pad-x: 16px;
  font-size: 0.82rem;
}
.btn--xs {
  --pad-y: 6px;
  --pad-x: 12px;
  font-size: 0.74rem;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.72rem;
  font-weight: 600;
  padding: 5px 10px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line-2);
  color: var(--ink-2);
}
.badge--live {
  color: var(--ok);
  border-color: rgba(95, 211, 138, 0.4);
}
.pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 0 rgba(95, 211, 138, 0.5);
  animation: pulse 1.8s infinite;
}
@keyframes pulse {
  70% {
    box-shadow: 0 0 0 8px rgba(95, 211, 138, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(95, 211, 138, 0);
  }
}

.tag {
  display: inline-block;
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.7rem;
  color: var(--ink-2);
  border: 1px solid var(--line);
  padding: 4px 9px;
  border-radius: var(--r-sm);
}

/* ---- Nav ---- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(16, 17, 19, 0.82);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
  transition: box-shadow 0.2s ease, background 0.2s ease;
}
.nav.is-scrolled {
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.5);
  background: rgba(16, 17, 19, 0.95);
}
.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 68px;
  gap: 20px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.brand__mark {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  background: var(--yellow);
  color: #101113;
  font-family: "Oswald", sans-serif;
  font-weight: 700;
  font-size: 0.95rem;
  border-radius: var(--r-sm);
  transform: skewX(-6deg);
}
.brand__txt {
  font-family: "Oswald", sans-serif;
  font-weight: 700;
  letter-spacing: 0.06em;
  font-size: 1.18rem;
}
.brand__txt em {
  font-style: normal;
  color: var(--yellow);
}
.nav__links {
  display: flex;
  gap: 26px;
  margin-left: auto;
}
.nav__links a {
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.86rem;
  color: var(--ink-2);
  position: relative;
  padding: 6px 0;
  transition: color 0.15s ease;
}
.nav__links a::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2px;
  width: 0;
  background: var(--yellow);
  transition: width 0.2s ease;
}
.nav__links a:hover {
  color: var(--ink);
}
.nav__links a:hover::after {
  width: 100%;
}
.nav__actions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.nav__burger {
  display: none;
  flex-direction: column;
  gap: 4px;
  background: none;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 9px 8px;
  cursor: pointer;
}
.nav__burger span {
  width: 20px;
  height: 2px;
  background: var(--ink);
  transition: transform 0.2s ease, opacity 0.2s ease;
}
.nav__burger[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(6px) rotate(45deg);
}
.nav__burger[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}
.nav__burger[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-6px) rotate(-45deg);
}
.nav__mobile {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 14px 4vw 22px;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}
.nav__mobile a {
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 12px 8px;
  border-bottom: 1px solid var(--line);
  color: var(--ink-2);
}
.nav__mobile .btn {
  margin-top: 12px;
}

/* ---- Hero ---- */
.hero {
  position: relative;
  padding: clamp(48px, 8vw, 96px) 0 clamp(56px, 9vw, 110px);
  overflow: hidden;
  background: radial-gradient(
      900px 500px at 78% -10%,
      rgba(255, 210, 31, 0.1),
      transparent 60%
    ),
    linear-gradient(180deg, var(--bg), #0c0d0f);
}
.hero__tape {
  position: absolute;
  inset: 0 auto 0 0;
  width: 10px;
  background: var(--tape);
}
.hero__inner {
  display: grid;
  grid-template-columns: 1.25fr 0.85fr;
  gap: 48px;
  align-items: center;
}
.hero__title {
  font-family: "Oswald", sans-serif;
  font-weight: 700;
  text-transform: uppercase;
  font-size: clamp(2.6rem, 7vw, 5rem);
  line-height: 0.92;
  margin: 0 0 20px;
  letter-spacing: -0.01em;
}
.hero__title .hl {
  color: var(--yellow);
  position: relative;
}
.hero__lede {
  color: var(--ink-2);
  font-size: 1.12rem;
  max-width: 46ch;
  margin: 0 0 28px;
}
.hero__cta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 26px;
}
.hero__chips {
  list-style: none;
  display: flex;
  gap: 26px;
  padding: 0;
  margin: 0;
  flex-wrap: wrap;
}
.hero__chips li {
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 0.84rem;
  color: var(--ink-2);
  padding-left: 14px;
  position: relative;
}
.hero__chips li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 6px;
  height: 6px;
  background: var(--yellow);
}

.hero__card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px;
  box-shadow: var(--shadow);
  position: relative;
}
.hero__card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 6px;
  background: var(--tape);
  border-radius: var(--r-lg) var(--r-lg) 0 0;
}
.hero__card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 18px;
  flex-wrap: wrap;
}
.hero__temp {
  font-size: 0.78rem;
  color: var(--muted);
}
.hero__next {
  margin-bottom: 14px;
}
.hero__next-name {
  font-family: "Oswald", sans-serif;
  font-weight: 700;
  text-transform: uppercase;
  font-size: 1.7rem;
  margin: 6px 0 4px;
}
.hero__next-meta {
  color: var(--ink-2);
  margin: 0;
  font-size: 0.92rem;
}
.hero__bars {
  display: flex;
  align-items: flex-end;
  gap: 7px;
  height: 64px;
  margin: 18px 0;
}
.hero__bars span {
  flex: 1;
  height: var(--h);
  background: linear-gradient(180deg, var(--yellow), var(--yellow-d));
  border-radius: 2px 2px 0 0;
  opacity: 0.85;
}
.hero__bars span:nth-child(even) {
  background: var(--concrete);
}

/* ---- WOD board ---- */
.wod {
  padding: clamp(56px, 9vw, 96px) 0;
  background: var(--surface);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.board {
  display: grid;
  grid-template-columns: 1.4fr 0.9fr;
  gap: 0;
  border: 1px solid var(--line-2);
  border-radius: var(--r-lg);
  overflow: hidden;
  background: #0b0c0d;
}
.board__main {
  position: relative;
  padding: 38px;
  background: #0b0c0d
    radial-gradient(
      circle at 20% 0%,
      rgba(255, 255, 255, 0.04),
      transparent 60%
    );
}
.board__chalk {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent 0 30px,
    rgba(255, 255, 255, 0.015) 30px 31px
  );
  pointer-events: none;
}
.board__type {
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.82rem;
  color: var(--yellow);
  margin: 0 0 8px;
}
.board__name {
  font-family: "Oswald", sans-serif;
  font-weight: 700;
  text-transform: uppercase;
  font-size: clamp(2rem, 5vw, 3rem);
  margin: 0 0 24px;
  letter-spacing: 0.02em;
}
.board__moves {
  list-style: none;
  margin: 0 0 26px;
  padding: 0;
  counter-reset: m;
}
.board__moves li {
  display: flex;
  align-items: baseline;
  gap: 14px;
  padding: 12px 0;
  border-bottom: 1px dashed var(--line);
  font-size: 1.15rem;
}
.board__moves span {
  font-family: "Oswald", sans-serif;
  font-weight: 700;
  color: var(--yellow);
  min-width: 84px;
}
.board__moves em {
  font-style: normal;
  color: var(--muted);
  font-size: 0.92rem;
}
.board__scale ul {
  list-style: none;
  padding: 0;
  margin: 8px 0 0;
  display: grid;
  gap: 8px;
}
.board__scale li {
  font-size: 0.95rem;
  color: var(--ink-2);
}
.board__scale b {
  display: inline-block;
  min-width: 78px;
  color: var(--ink);
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 0.82rem;
}

.board__timer {
  padding: 38px 30px;
  background: var(--surface-2);
  border-left: 1px solid var(--line-2);
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.timer__face {
  font-family: "Oswald", sans-serif;
  font-weight: 700;
  font-size: clamp(3rem, 9vw, 4.6rem);
  line-height: 1;
  letter-spacing: 0.02em;
  text-align: center;
  font-variant-numeric: tabular-nums;
  background: #0b0c0d;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 18px 0;
  color: var(--yellow);
}
.timer__face.is-running {
  animation: glow 1s ease-in-out infinite alternate;
}
@keyframes glow {
  to {
    box-shadow: 0 0 0 1px var(--yellow-d) inset;
  }
}
.timer__mode {
  display: flex;
  gap: 8px;
}
.chip {
  flex: 1;
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: 0.78rem;
  padding: 9px;
  background: transparent;
  color: var(--ink-2);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  cursor: pointer;
  transition: all 0.15s ease;
}
.chip:hover {
  border-color: var(--yellow);
}
.chip.is-active {
  background: var(--yellow);
  color: #101113;
  border-color: var(--yellow);
}
.chip:focus-visible {
  outline: 3px solid var(--yellow);
  outline-offset: 2px;
}
.timer__btns {
  display: flex;
  gap: 8px;
}
.timer__hint {
  font-size: 0.74rem;
  text-align: center;
}

/* ---- Programs ---- */
.programs {
  padding: clamp(56px, 9vw, 96px) 0;
}
.grid {
  display: grid;
  gap: 18px;
}
.grid--4 {
  grid-template-columns: repeat(4, 1fr);
}
.prog {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 26px 22px 22px;
  overflow: hidden;
  transition: transform 0.18s ease, border-color 0.18s ease,
    background 0.18s ease;
  cursor: default;
}
.prog::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: var(--concrete);
  transition: background 0.18s ease;
}
.prog:hover,
.prog:focus-visible {
  transform: translateY(-4px);
  border-color: var(--line-2);
  background: var(--surface-2);
  outline: none;
}
.prog:hover::before,
.prog:focus-visible::before {
  background: var(--yellow);
}
.prog__num {
  font-family: "Oswald", sans-serif;
  font-weight: 700;
  font-size: 1.6rem;
  color: var(--concrete);
  transition: color 0.18s ease;
}
.prog:hover .prog__num {
  color: var(--yellow);
}
.prog h3 {
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  font-size: 1.3rem;
  margin: 10px 0 8px;
}
.prog p {
  color: var(--ink-2);
  font-size: 0.92rem;
  margin: 0 0 16px;
}

/* ---- Coaches ---- */
.coaches {
  padding: clamp(56px, 9vw, 96px) 0;
  background: var(--surface);
  border-top: 1px solid var(--line);
}
.coach {
  text-align: center;
}
.coach__photo {
  aspect-ratio: 4 / 5;
  border-radius: var(--r-md);
  background: linear-gradient(160deg, var(--concrete), #16181b);
  border: 1px solid var(--line);
  margin-bottom: 14px;
  display: grid;
  place-items: center;
  position: relative;
  overflow: hidden;
  transition: border-color 0.18s ease;
}
.coach__photo::after {
  content: attr(data-init);
  font-family: "Oswald", sans-serif;
  font-weight: 700;
  font-size: 3rem;
  color: rgba(255, 255, 255, 0.14);
}
.coach__photo::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 5px;
  background: var(--tape);
  opacity: 0;
  transition: opacity 0.18s ease;
}
.coach:hover .coach__photo {
  border-color: var(--yellow);
}
.coach:hover .coach__photo::before {
  opacity: 1;
}
.coach h3 {
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  font-size: 1.1rem;
  margin: 0 0 4px;
}
.coach__role {
  color: var(--yellow);
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: 0.76rem;
  margin: 0 0 2px;
}
.coach__spec {
  color: var(--muted);
  font-size: 0.86rem;
  margin: 0;
}

/* ---- Results ---- */
.results {
  padding: clamp(56px, 9vw, 96px) 0;
}
.results__inner {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 48px;
  align-items: center;
}
.quote {
  margin: 24px 0 0;
  padding: 20px 24px;
  border-left: 4px solid var(--yellow);
  background: var(--surface);
  border-radius: 0 var(--r-md) var(--r-md) 0;
  font-size: 1.05rem;
  color: var(--ink);
}
.quote cite {
  display: block;
  margin-top: 12px;
  font-style: normal;
  color: var(--muted);
  font-size: 0.86rem;
}
.stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.stat {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 26px 20px;
  position: relative;
  overflow: hidden;
}
.stat::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 36px;
  height: 4px;
  background: var(--yellow);
}
.stat__num {
  display: block;
  font-family: "Oswald", sans-serif;
  font-weight: 700;
  font-size: clamp(2.2rem, 5vw, 3rem);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.stat__label {
  display: block;
  margin-top: 6px;
  color: var(--ink-2);
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 0.78rem;
}

/* ---- Schedule ---- */
.schedule {
  padding: clamp(56px, 9vw, 96px) 0;
  background: var(--surface);
  border-top: 1px solid var(--line);
}
.sched {
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
}
.sched__row {
  display: grid;
  grid-template-columns: 0.8fr 1.6fr 0.8fr 0.7fr 0.7fr;
  align-items: center;
  gap: 14px;
  padding: 16px 22px;
  border-bottom: 1px solid var(--line);
  transition: background 0.15s ease;
}
.sched__row:last-child {
  border-bottom: 0;
}
.sched__row:not(.sched__row--head):hover {
  background: var(--surface-2);
}
.sched__row--head {
  background: #0b0c0d;
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.74rem;
  color: var(--muted);
}
.sched__time {
  font-family: "Oswald", sans-serif;
  font-weight: 600;
  font-size: 1.02rem;
}

/* ---- CTA band ---- */
.cta {
  position: relative;
  padding: clamp(64px, 10vw, 110px) 0;
  background: var(--yellow);
  color: #101113;
  overflow: hidden;
}
.cta__tape {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 8px;
  background: repeating-linear-gradient(
    -45deg,
    #101113 0 22px,
    var(--yellow) 22px 44px
  );
}
.cta__inner {
  text-align: center;
}
.cta h2 {
  font-family: "Oswald", sans-serif;
  font-weight: 700;
  text-transform: uppercase;
  font-size: clamp(2rem, 6vw, 4rem);
  line-height: 0.95;
  margin: 0 0 14px;
}
.cta p {
  font-size: 1.1rem;
  font-weight: 600;
  margin: 0 0 28px;
}

/* ---- Footer ---- */
.foot {
  background: var(--bg);
  border-top: 1px solid var(--line);
  padding: 36px 0;
}
.foot__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}
.foot .brand {
  display: inline-flex;
}
.foot p {
  margin: 0;
  font-size: 0.84rem;
}

/* ---- Modal ---- */
.modal {
  position: fixed;
  inset: 0;
  z-index: 300;
  display: grid;
  place-items: center;
  padding: 20px;
}
.modal__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(8, 9, 10, 0.78);
  backdrop-filter: blur(3px);
}
.modal__panel {
  position: relative;
  width: min(460px, 100%);
  background: var(--surface);
  border: 1px solid var(--line-2);
  border-radius: var(--r-lg);
  padding: 32px 30px;
  box-shadow: var(--shadow);
  animation: pop 0.18s ease;
}
.modal__panel::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 6px;
  background: var(--tape);
  border-radius: var(--r-lg) var(--r-lg) 0 0;
}
@keyframes pop {
  from {
    transform: translateY(12px) scale(0.98);
    opacity: 0;
  }
}
.modal__x {
  position: absolute;
  top: 14px;
  right: 16px;
  background: none;
  border: 0;
  color: var(--muted);
  font-size: 1.8rem;
  line-height: 1;
  cursor: pointer;
}
.modal__x:hover {
  color: var(--ink);
}
.modal__title {
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  font-size: 1.6rem;
  margin: 0 0 8px;
}
.form {
  display: grid;
  gap: 14px;
  margin-top: 20px;
}
.form label {
  display: grid;
  gap: 6px;
}
.form label span {
  font-family: "Oswald", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 0.74rem;
  color: var(--ink-2);
}
.form input,
.form select {
  background: #0b0c0d;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  color: var(--ink);
  padding: 12px 14px;
  font: inherit;
  font-size: 0.95rem;
}
.form input:focus,
.form select:focus {
  outline: none;
  border-color: var(--yellow);
  box-shadow: 0 0 0 3px var(--yellow-50);
}
.form input.is-invalid {
  border-color: var(--danger);
}

/* ---- Toast ---- */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--elevated);
  color: var(--ink);
  border: 1px solid var(--line-2);
  border-left: 4px solid var(--yellow);
  border-radius: var(--r-sm);
  padding: 14px 20px;
  font-weight: 600;
  font-size: 0.92rem;
  box-shadow: var(--shadow);
  z-index: 400;
  opacity: 0;
  transition: opacity 0.25s ease, transform 0.25s ease;
}
.toast.is-show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ---- Reveal ---- */
.reveal {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 0.55s ease, transform 0.55s ease;
}
.reveal.is-in {
  opacity: 1;
  transform: none;
}

/* ---- Responsive ---- */
@media (max-width: 920px) {
  .hero__inner,
  .results__inner {
    grid-template-columns: 1fr;
  }
  .board {
    grid-template-columns: 1fr;
  }
  .board__timer {
    border-left: 0;
    border-top: 1px solid var(--line-2);
  }
  .grid--4 {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 760px) {
  .nav__links {
    display: none;
  }
  .nav__actions .btn--ghost {
    display: none;
  }
  .nav__burger {
    display: flex;
  }
  .sched__row {
    grid-template-columns: 0.7fr 1.4fr 0.6fr;
  }
  .sched__row span:nth-child(3),
  .sched__row span:nth-child(4) {
    display: none;
  }
}

@media (max-width: 520px) {
  .grid--4 {
    grid-template-columns: 1fr;
  }
  .stats {
    grid-template-columns: 1fr;
  }
  .hero__chips {
    gap: 14px;
  }
  .board__main,
  .board__timer {
    padding: 26px 20px;
  }
  .board__moves li {
    flex-direction: column;
    gap: 2px;
  }
  .nav__actions .btn[data-book] {
    display: none;
  }
  .foot__inner {
    flex-direction: column;
    align-items: flex-start;
    text-align: left;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    scroll-behavior: auto;
  }
  .reveal {
    opacity: 1;
    transform: none;
  }
}

