(function () {
  "use strict";

  /* ---------- Toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.hidden = false;
    // force reflow so the transition runs
    void toastEl.offsetWidth;
    toastEl.classList.add("is-show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("is-show");
      setTimeout(function () {
        toastEl.hidden = true;
      }, 280);
    }, 2800);
  }

  /* ---------- Today's date on the whiteboard ---------- */
  var wodDate = document.getElementById("wodDate");
  if (wodDate) {
    try {
      wodDate.textContent = new Date().toLocaleDateString(undefined, {
        weekday: "long",
        month: "long",
        day: "numeric",
      });
    } catch (e) {
      /* keep fallback text */
    }
  }

  /* ---------- Sticky nav shadow ---------- */
  var nav = document.getElementById("nav");
  function onScroll() {
    if (!nav) return;
    nav.classList.toggle("is-scrolled", window.scrollY > 8);
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  /* ---------- Mobile menu ---------- */
  var burger = document.getElementById("burger");
  var mobileMenu = document.getElementById("mobileMenu");
  function setMenu(open) {
    if (!burger || !mobileMenu) return;
    burger.setAttribute("aria-expanded", String(open));
    mobileMenu.hidden = !open;
    burger.setAttribute("aria-label", open ? "Close menu" : "Open menu");
  }
  if (burger) {
    burger.addEventListener("click", function () {
      setMenu(burger.getAttribute("aria-expanded") !== "true");
    });
  }
  if (mobileMenu) {
    mobileMenu.addEventListener("click", function (e) {
      if (e.target.closest("a")) setMenu(false);
    });
  }

  /* ---------- Reveal on scroll ---------- */
  var reveals = document.querySelectorAll(".reveal");
  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-in");
            io.unobserve(entry.target);
            if (entry.target.querySelector("[data-count]")) runCounters(entry.target);
          }
        });
      },
      { threshold: 0.16 }
    );
    reveals.forEach(function (el) {
      io.observe(el);
    });
  } else {
    reveals.forEach(function (el) {
      el.classList.add("is-in");
    });
    runCounters(document);
  }

  /* ---------- Count-up stats ---------- */
  function runCounters(scope) {
    var nums = scope.querySelectorAll("[data-count]");
    nums.forEach(function (el) {
      if (el.dataset.done) return;
      el.dataset.done = "1";
      var target = parseInt(el.getAttribute("data-count"), 10) || 0;
      var suffix = el.getAttribute("data-suffix") || "";
      var dur = 1300;
      var start = performance.now();
      function tick(now) {
        var p = Math.min((now - start) / dur, 1);
        var eased = 1 - Math.pow(1 - p, 3);
        el.textContent = Math.round(target * eased).toLocaleString() + suffix;
        if (p < 1) requestAnimationFrame(tick);
      }
      requestAnimationFrame(tick);
    });
  }

  /* ---------- WOD timer demo ---------- */
  var face = document.getElementById("timerFace");
  var startBtn = document.getElementById("timerStart");
  var resetBtn = document.getElementById("timerReset");
  var modeBtns = document.querySelectorAll("[data-mode]");
  var AMRAP_SECS = 12 * 60;
  var mode = "stopwatch";
  var running = false;
  var rafId = null;
  var startTs = 0;
  var elapsedAtPause = 0;

  function fmt(totalSecs) {
    totalSecs = Math.max(0, Math.floor(totalSecs));
    var m = Math.floor(totalSecs / 60);
    var s = totalSecs % 60;
    return String(m).padStart(2, "0") + ":" + String(s).padStart(2, "0");
  }
  function render(elapsed) {
    if (!face) return;
    if (mode === "amrap") {
      var remaining = AMRAP_SECS - elapsed;
      if (remaining <= 0) {
        face.textContent = "00:00";
        stopTimer(true);
        toast("Time! AMRAP complete.");
        return;
      }
      face.textContent = fmt(remaining);
    } else {
      face.textContent = fmt(elapsed);
    }
  }
  function loop(now) {
    var elapsed = elapsedAtPause + (now - startTs) / 1000;
    render(elapsed);
    if (running) rafId = requestAnimationFrame(loop);
  }
  function startTimer() {
    if (running) return;
    running = true;
    startTs = performance.now();
    if (face) face.classList.add("is-running");
    if (startBtn) startBtn.textContent = "Pause";
    rafId = requestAnimationFrame(loop);
  }
  function pauseTimer() {
    if (!running) return;
    running = false;
    elapsedAtPause += (performance.now() - startTs) / 1000;
    if (rafId) cancelAnimationFrame(rafId);
    if (face) face.classList.remove("is-running");
    if (startBtn) startBtn.textContent = "Resume";
  }
  function stopTimer(finished) {
    running = false;
    if (rafId) cancelAnimationFrame(rafId);
    if (face) face.classList.remove("is-running");
    if (startBtn) startBtn.textContent = finished ? "Start" : "Resume";
    if (finished) elapsedAtPause = 0;
  }
  function resetTimer() {
    running = false;
    if (rafId) cancelAnimationFrame(rafId);
    elapsedAtPause = 0;
    if (face) face.classList.remove("is-running");
    if (startBtn) startBtn.textContent = "Start";
    render(0);
  }
  if (startBtn) {
    startBtn.addEventListener("click", function () {
      if (running) pauseTimer();
      else startTimer();
    });
  }
  if (resetBtn) resetBtn.addEventListener("click", resetTimer);
  modeBtns.forEach(function (b) {
    b.addEventListener("click", function () {
      modeBtns.forEach(function (x) {
        x.classList.remove("is-active");
      });
      b.classList.add("is-active");
      mode = b.getAttribute("data-mode");
      resetTimer();
    });
  });
  render(0);

  /* ---------- Booking modal (focus trap) ---------- */
  var modal = document.getElementById("modal");
  var form = document.getElementById("bookForm");
  var lastFocused = null;

  function getFocusable() {
    return modal
      ? Array.prototype.slice.call(
          modal.querySelectorAll(
            'button, input, select, textarea, a[href], [tabindex]:not([tabindex="-1"])'
          )
        ).filter(function (el) {
          return !el.disabled && el.offsetParent !== null;
        })
      : [];
  }
  function openModal() {
    if (!modal) return;
    lastFocused = document.activeElement;
    modal.hidden = false;
    setMenu(false);
    document.body.style.overflow = "hidden";
    var f = getFocusable();
    if (f[0]) f[0].focus();
    document.addEventListener("keydown", onModalKey);
  }
  function closeModal() {
    if (!modal) return;
    modal.hidden = true;
    document.body.style.overflow = "";
    document.removeEventListener("keydown", onModalKey);
    if (lastFocused && lastFocused.focus) lastFocused.focus();
  }
  function onModalKey(e) {
    if (e.key === "Escape") {
      closeModal();
      return;
    }
    if (e.key === "Tab") {
      var f = getFocusable();
      if (!f.length) return;
      var first = f[0];
      var last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  }

  document.addEventListener("click", function (e) {
    if (e.target.closest("[data-book]")) {
      e.preventDefault();
      openModal();
    } else if (e.target.closest("[data-close]")) {
      closeModal();
    } else if (e.target.closest("[data-waitlist]")) {
      toast("Added to the waitlist — we'll text you if a spot opens.");
    }
  });

  if (form) {
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var name = form.elements.name;
      var email = form.elements.email;
      var valid = true;
      [name, email].forEach(function (input) {
        input.classList.remove("is-invalid");
      });
      if (!name.value.trim()) {
        name.classList.add("is-invalid");
        valid = false;
      }
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim())) {
        email.classList.add("is-invalid");
        valid = false;
      }
      if (!valid) {
        toast("Check the highlighted fields.");
        return;
      }
      var who = name.value.trim().split(" ")[0];
      closeModal();
      form.reset();
      toast("Booked! See you on the floor, " + who + ".");
    });
  }
})();

snippets.css:
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Topbar ── */
.topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  background: var(--navy-d);
  color: var(--bone);
  padding: 0 32px;
  height: 64px;
  display: flex;
  align-items: center;
  gap: 32px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--bone);
  flex-shrink: 0;
}
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: var(--r-sm);
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.2rem;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
}
.brand-name em {
  font-style: normal;
  color: var(--gold-light);
}
.top-nav {
  display: flex;
  gap: 6px;
  margin-left: 24px;
}
.top-nav a {
  text-decoration: none;
  color: rgba(251, 248, 242, 0.65);
  font-size: 0.86rem;
  font-weight: 500;
  padding: 6px 13px;
  border-radius: var(--r-sm);
  transition: color 0.15s, background 0.15s;
}
.top-nav a:hover,
.top-nav a.active {
  color: var(--bone);
  background: rgba(255, 255, 255, 0.08);
}
.top-nav a.active {
  color: var(--gold-light);
}
.nav-cta {
  margin-left: auto;
  background: var(--gold);
  color: var(--navy-d);
  font-weight: 700;
  font-size: 0.84rem;
  padding: 9px 20px;
  border-radius: 999px;
  text-decoration: none;
  transition: background 0.15s;
}
.nav-cta:hover {
  background: var(--gold-light);
}

/* ── Page hero ── */
.page-hero {
  background: linear-gradient(160deg, var(--navy-2) 0%, var(--navy-d) 55%, #070f1e 100%);
  color: var(--bone);
  padding: 60px 32px 48px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 50% at 50% 0%, rgba(201, 166, 73, 0.16), transparent 70%);
}
.breadcrumb {
  position: relative;
  font-size: 0.75rem;
  color: var(--gold-light);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 600;
  margin-bottom: 14px;
}
.page-hero h1 {
  position: relative;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(2.2rem, 5vw, 3.6rem);
  line-height: 1.05;
}
.hero-sub {
  position: relative;
  margin-top: 12px;
  font-size: 0.95rem;
  color: rgba(251, 248, 242, 0.68);
}

/* ── Filter bar ── */
.filter-bar {
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.filter-pills {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.pill {
  font-family: var(--font-body);
  font-size: 0.86rem;
  font-weight: 600;
  padding: 7px 18px;
  border: 1.5px solid var(--line-strong);
  border-radius: 999px;
  background: var(--bone);
  color: var(--ink-2);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}
.pill:hover {
  border-color: var(--navy);
  color: var(--navy);
}
.pill.active {
  background: var(--navy);
  border-color: var(--navy);
  color: var(--bone);
}
.gallery-count {
  font-size: 0.82rem;
  color: var(--warm-gray);
  font-weight: 600;
  white-space: nowrap;
}
.gallery-count span {
  font-family: var(--font-mono);
  color: var(--navy-d);
  font-variant-numeric: tabular-nums;
}

/* ── Gallery wrap ── */
.gallery-wrap {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 32px 72px;
}

/* ── Gallery grid (CSS columns masonry) ── */
.gallery-grid {
  column-count: 3;
  column-gap: 16px;
}
.gallery-tile {
  break-inside: avoid;
  margin-bottom: 16px;
  border-radius: var(--r-md);
  overflow: hidden;
  position: relative;
  cursor: pointer;
  box-shadow: var(--shadow-1);
  transition: box-shadow 0.18s, transform 0.18s;
}
.gallery-tile:hover {
  box-shadow: var(--shadow-2);
  transform: scale(1.02);
}
.tile-img {
  width: 100%;
  display: block;
  position: relative;
}
/* Tile gradient fill — heights vary for masonry effect */
.tile-img.h-sm {
  height: 180px;
}
.tile-img.h-md {
  height: 240px;
}
.tile-img.h-lg {
  height: 300px;
}
.tile-img.h-xl {
  height: 360px;
}

/* Per-category gradients */
.tile-img.g-rooms {
  background: linear-gradient(135deg, #3a5180, #1a2b4a);
}
.tile-img.g-rooms-2 {
  background: linear-gradient(155deg, #5a6e88, #2d4570);
}
.tile-img.g-dining {
  background: linear-gradient(135deg, #5a3a28, #2e1a10);
}
.tile-img.g-dining-2 {
  background: linear-gradient(155deg, #7a5040, #3e2018);
}
.tile-img.g-spa {
  background: linear-gradient(135deg, #3a5a4a, #1a3028);
}
.tile-img.g-spa-2 {
  background: linear-gradient(155deg, #4a6858, #2a3e34);
}
.tile-img.g-views {
  background: linear-gradient(135deg, #2a4a6a, #0e2038);
}
.tile-img.g-views-2 {
  background: linear-gradient(155deg, #4a6880, #1e3856);
}
.tile-img.g-events {
  background: linear-gradient(135deg, var(--gold-d), #4a2e08);
}
.tile-img.g-events-2 {
  background: linear-gradient(155deg, #d0a050, #6a4018);
}

.tile-img::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(70% 60% at 65% 20%, rgba(255, 255, 255, 0.14), transparent 70%);
}

/* ── Tile hover overlay ── */
.tile-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(10, 18, 34, 0.82) 0%, transparent 55%);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 16px;
  opacity: 0;
  transition: opacity 0.2s;
}
.gallery-tile:hover .tile-overlay {
  opacity: 1;
}
.tile-overlay-title {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--bone);
  line-height: 1.2;
}
.tile-overlay-cat {
  font-size: 0.66rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gold-light);
  margin-top: 4px;
}

/* ── Empty state ── */
.empty {
  text-align: center;
  padding: 72px 24px;
  color: var(--warm-gray);
  font-style: italic;
  background: var(--bone);
  border: 1px dashed var(--line-strong);
  border-radius: var(--r-md);
}

/* ── Lightbox ── */
.lightbox {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
}
.lightbox[hidden] {
  display: none;
}
.lb-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(7, 14, 28, 0.88);
  cursor: pointer;
}
.lb-panel {
  position: relative;
  z-index: 1;
  width: min(860px, 94vw);
  background: var(--navy-d);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: 0 32px 80px rgba(0, 0, 0, 0.6);
  display: flex;
  flex-direction: column;
}
.lb-close {
  position: absolute;
  top: 14px;
  right: 14px;
  z-index: 10;
  background: rgba(255, 255, 255, 0.12);
  border: none;
  color: var(--bone);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  font-size: 1rem;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background 0.15s;
}
.lb-close:hover {
  background: rgba(255, 255, 255, 0.22);
}
.lb-image {
  width: 100%;
  height: 420px;
  position: relative;
  flex-shrink: 0;
}
.lb-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  background: rgba(255, 255, 255, 0.14);
  border: none;
  color: var(--bone);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  font-size: 1.6rem;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background 0.15s;
  line-height: 1;
}
.lb-nav:hover {
  background: rgba(255, 255, 255, 0.26);
}
.lb-prev {
  left: 16px;
}
.lb-next {
  right: 16px;
}
.lb-caption {
  padding: 20px 24px 22px;
  background: var(--navy-d);
  color: var(--bone);
}
.lb-caption-top {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 6px;
}
.lb-caption h2 {
  font-family: var(--font-display);
  font-size: 1.6rem;
  font-weight: 700;
  line-height: 1.1;
}
.lb-cat-badge {
  font-size: 0.66rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--navy-d);
  background: var(--gold);
  padding: 4px 10px;
  border-radius: 999px;
  white-space: nowrap;
}
.lb-caption p {
  font-size: 0.86rem;
  color: rgba(251, 248, 242, 0.65);
  line-height: 1.55;
}
.lb-counter {
  font-family: var(--font-mono);
  font-size: 0.76rem;
  font-variant-numeric: tabular-nums;
  color: var(--gold-light);
  margin-top: 8px;
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 12px 24px;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 50;
  white-space: nowrap;
}

/* ── Responsive ── */
@media (max-width: 960px) {
  .top-nav {
    display: none;
  }
  .gallery-grid {
    column-count: 2;
  }
  .lb-image {
    height: 320px;
  }
}
@media (max-width: 560px) {
  .topbar {
    padding: 0 18px;
    gap: 16px;
  }
  .page-hero {
    padding: 44px 20px 36px;
  }
  .filter-bar {
    padding: 14px 18px;
    flex-wrap: wrap;
  }
  .gallery-wrap {
    padding: 0 18px 48px;
  }
  .gallery-grid {
    column-count: 2;
    column-gap: 10px;
  }
  .gallery-tile {
    margin-bottom: 10px;
  }
  .lb-image {
    height: 240px;
  }
  .lb-caption h2 {
    font-size: 1.2rem;
  }
}
@media (max-width: 380px) {
  .gallery-grid {
    column-count: 1;
  }
}

