    grad: "g-events-2",
    height: "h-xl",
    desc: "Round tables dressed in ivory and gold for a 90-person gala dinner in the Salón Dorado. Custom centrepieces by Flores Aurelia.",
  },
];

// ── State ─────────────────────────────────────────────────────────────────────
let activeCat = "all";
let lightboxIndex = 0;
let visibleTiles = [];

// ── DOM refs ──────────────────────────────────────────────────────────────────
const galleryGrid = document.getElementById("galleryGrid");
const emptyEl = document.getElementById("emptyMsg");
const tileCountEl = document.getElementById("tileCount");
const lightbox = document.getElementById("lightbox");
const lbImage = document.getElementById("lbImage");
const lbTitle = document.getElementById("lbTitle");
const lbDesc = document.getElementById("lbDesc");
const lbCatBadge = document.getElementById("lbCatBadge");
const lbCurrent = document.getElementById("lbCurrent");
const lbTotal = document.getElementById("lbTotal");
const toast = document.getElementById("toast");

// ── Helpers ───────────────────────────────────────────────────────────────────
const CAT_LABEL = {
  rooms: "Rooms",
  dining: "Dining",
  spa: "Spa",
  views: "Views",
  events: "Events",
};

function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2200);
}

// ── Render grid ───────────────────────────────────────────────────────────────
function renderGrid() {
  visibleTiles = TILES.filter((t) => activeCat === "all" || t.cat === activeCat);
  emptyEl.hidden = visibleTiles.length > 0;
  tileCountEl.textContent = visibleTiles.length;

  galleryGrid.innerHTML = visibleTiles
    .map(
      (t, i) => `
      <div class="gallery-tile" data-index="${i}" role="button" tabindex="0" aria-label="Open photo: ${t.title}">
        <div class="tile-img ${t.grad} ${t.height}"></div>
        <div class="tile-overlay">
          <p class="tile-overlay-title">${t.title}</p>
          <p class="tile-overlay-cat">${CAT_LABEL[t.cat] || t.cat}</p>
        </div>
      </div>`
    )
    .join("");
}

// ── Open lightbox ─────────────────────────────────────────────────────────────
function openLightbox(index) {
  lightboxIndex = index;
  updateLightbox();
  lightbox.hidden = false;
  document.body.style.overflow = "hidden";
  document.getElementById("lbClose").focus();
}

function updateLightbox() {
  const t = visibleTiles[lightboxIndex];
  if (!t) return;

  // Rebuild gradient in lightbox image area
  lbImage.className = `lb-image tile-img ${t.grad}`;
  lbImage.style.height = "420px";

  lbTitle.textContent = t.title;
  lbDesc.textContent = t.desc;
  lbCatBadge.textContent = CAT_LABEL[t.cat] || t.cat;
  lbCurrent.textContent = lightboxIndex + 1;
  lbTotal.textContent = visibleTiles.length;

  // Show/hide nav when only one tile
  document.getElementById("lbPrev").style.visibility =
    visibleTiles.length > 1 ? "visible" : "hidden";
  document.getElementById("lbNext").style.visibility =
    visibleTiles.length > 1 ? "visible" : "hidden";
}

function closeLightbox() {
  lightbox.hidden = true;
  document.body.style.overflow = "";
}

function prevPhoto() {
  lightboxIndex = (lightboxIndex - 1 + visibleTiles.length) % visibleTiles.length;
  updateLightbox();
}

function nextPhoto() {
  lightboxIndex = (lightboxIndex + 1) % visibleTiles.length;
  updateLightbox();
}

// ── Category filter ───────────────────────────────────────────────────────────
document.getElementById("filterPills").addEventListener("click", (e) => {
  const pill = e.target.closest(".pill");
  if (!pill) return;
  activeCat = pill.dataset.cat;
  document.querySelectorAll(".pill").forEach((p) => {
    p.classList.toggle("active", p === pill);
    p.setAttribute("aria-selected", p === pill ? "true" : "false");
  });
  renderGrid();
});

// ── Grid click / keyboard ─────────────────────────────────────────────────────
galleryGrid.addEventListener("click", (e) => {
  const tile = e.target.closest(".gallery-tile");
  if (!tile) return;
  openLightbox(Number(tile.dataset.index));
});
galleryGrid.addEventListener("keydown", (e) => {
  if (e.key !== "Enter" && e.key !== " ") return;
  const tile = e.target.closest(".gallery-tile");
  if (!tile) return;
  e.preventDefault();
  openLightbox(Number(tile.dataset.index));
});

// ── Lightbox controls ─────────────────────────────────────────────────────────
document.getElementById("lbClose").addEventListener("click", closeLightbox);
document.getElementById("lbBackdrop").addEventListener("click", closeLightbox);
document.getElementById("lbPrev").addEventListener("click", prevPhoto);
document.getElementById("lbNext").addEventListener("click", nextPhoto);

document.addEventListener("keydown", (e) => {
  if (lightbox.hidden) return;
  if (e.key === "Escape") closeLightbox();
  if (e.key === "ArrowLeft") prevPhoto();
  if (e.key === "ArrowRight") nextPhoto();
});

// ── Init ──────────────────────────────────────────────────────────────────────
renderGrid();

snippets.css:
:root {
  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;
  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;
  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;
  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);
  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;
  --shadow-sm: 0 1px 2px rgba(28, 24, 20, 0.05), 0 4px 14px rgba(28, 24, 20, 0.05);
  --shadow-md: 0 18px 48px -18px rgba(28, 24, 20, 0.32);
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--sans);
  line-height: 1.5;
  color: var(--ink);
  background: var(--bg);
  background-image: radial-gradient(900px 480px at 92% -8%, rgba(176, 141, 87, 0.1), transparent 70%),
    radial-gradient(720px 420px at -6% 4%, rgba(201, 167, 143, 0.12), transparent 65%);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1,
h2,
h3 {
  font-family: var(--serif);
  font-weight: 600;
  line-height: 1.08;
  margin: 0;
  color: var(--ink);
}

button {
  font-family: inherit;
  cursor: pointer;
  color: inherit;
}

input {
  font-family: inherit;
}

input[type="number"]::-webkit-outer-spin-button,
input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
input[type="number"] {
  -moz-appearance: textfield;
}

.shell {
  max-width: 1060px;
  margin: 0 auto;
  padding: clamp(20px, 4vw, 52px) clamp(16px, 4vw, 40px) 72px;
}

/* ───────── Masthead ───────── */
.masthead {
  margin-bottom: 30px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 16px;
}
.brand__mark {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  flex: none;
  border-radius: 50%;
  font-family: var(--serif);
  font-weight: 700;
  font-size: 19px;
  letter-spacing: 0.5px;
  color: var(--white);
  background: linear-gradient(150deg, var(--gold) 0%, var(--gold-d) 100%);
  box-shadow: 0 10px 22px -10px rgba(140, 109, 63, 0.7);
}
.eyebrow {
  margin: 0 0 2px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold-d);
}
.masthead h1 {
  font-size: clamp(28px, 5vw, 40px);
  font-weight: 600;
}
.masthead__note {
  margin: 16px 0 0;
  max-width: 46ch;
  color: var(--ink-2);
  font-size: 15px;
}

/* ───────── Layout ───────── */
.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
  align-items: start;
}

.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 26px;
  box-shadow: var(--shadow-md);
}
.panel--split {
  margin-top: 22px;
}
.panel__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 22px;
}
.panel__head h2 {
  font-size: 24px;
}
.panel__sub {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--muted);
}

.chip {
  flex: none;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  padding: 6px 12px;
  border-radius: 999px;
  color: var(--gold-d);
  background: var(--gold-soft);
}
.chip--ghost {
  background: transparent;
  border: 1px solid var(--line-2);
  color: var(--ink-2);
}

/* ───────── Fields ───────── */
.field {
  margin-bottom: 22px;
}
.field:last-child {
  margin-bottom: 0;
}
.field__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}
.field label {
  display: block;
  margin-bottom: 10px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}
.field__row label {
  margin-bottom: 0;
}

.money {
  display: flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-md);
  padding: 0 14px;
  background: var(--cream);
  transition: border-color 0.18s, box-shadow 0.18s, background 0.18s;
}
.money:focus-within {
  border-color: var(--gold);
  background: var(--white);
  box-shadow: 0 0 0 4px rgba(176, 141, 87, 0.16);
}
.money__sym {
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 600;
  color: var(--gold-d);
}
.money input {
  flex: 1;
  width: 100%;
  border: 0;
  background: transparent;
  outline: none;
  padding: 14px 0;
  font-size: 22px;
  font-weight: 600;
  color: var(--ink);
}

.hint {
  margin: 9px 0 0;
  font-size: 12.5px;
  color: var(--muted);
}

/* ───────── Segmented control ───────── */
.seg {
  display: inline-flex;
  padding: 3px;
  gap: 2px;
  border-radius: 999px;
  background: var(--cream);
  border: 1px solid var(--line);
}
.seg__btn {
  border: 0;
  background: transparent;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--muted);
  padding: 7px 14px;
  border-radius: 999px;
  transition: color 0.18s, background 0.18s, box-shadow 0.18s;
}
.seg__btn.is-active {
  color: var(--ink);
  background: var(--white);
  box-shadow: var(--shadow-sm);
}

/* ───────── Tip presets ───────── */
.tip-presets {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-bottom: 12px;
}
.preset {
  border: 1px solid var(--line-2);
  background: var(--white);
  border-radius: var(--r-sm);
  padding: 11px 0;
  font-weight: 600;
  font-size: 14px;
  color: var(--ink-2);
  transition: all 0.16s;
}
.preset:hover {
  border-color: var(--gold);
  color: var(--gold-d);
}
.preset.is-active {
  border-color: var(--gold);
  background: var(--gold-soft);
  color: var(--gold-d);
}

/* ───────── Slider ───────── */
.rate-out {
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 700;
  color: var(--gold-d);
}
.slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--gold) var(--fill, 45%), var(--gold-soft) var(--fill, 45%));
  outline: none;
  margin: 4px 0 2px;
}
.slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--white);
  border: 2px solid var(--gold);
  box-shadow: 0 4px 12px -3px rgba(140, 109, 63, 0.6);
  cursor: pointer;
}
.slider::-moz-range-thumb {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--white);
  border: 2px solid var(--gold);
  box-shadow: 0 4px 12px -3px rgba(140, 109, 63, 0.6);
  cursor: pointer;
}
.slider:focus-visible {
  box-shadow: 0 0 0 4px rgba(176, 141, 87, 0.2);
}

/* ───────── Ledger panel ───────── */
.panel--ledger {
  background: linear-gradient(180deg, #fffdf9 0%, var(--white) 38%);
}
.bigfig {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-bottom: 20px;
  margin-bottom: 20px;
  border-bottom: 1px solid var(--line);
}
.bigfig__label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}
.bigfig__value {
  font-family: var(--serif);
  font-size: clamp(40px, 8vw, 52px);
  font-weight: 700;
  letter-spacing: -0.5px;
  color: var(--ink);
}

.bar {
  display: flex;
  height: 14px;
  border-radius: 999px;
  overflow: hidden;
  background: var(--cream);
  box-shadow: inset 0 0 0 1px var(--line);
}
.bar__seg {
  height: 100%;
  transition: width 0.45s cubic-bezier(0.22, 0.61, 0.36, 1);
}
.bar__seg--comm {
  background: linear-gradient(90deg, var(--gold), var(--gold-d));
}
.bar__seg--tip {
  background: var(--rose);
}
.bar__seg--salon {
  background: #c8bca9;
}
.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin: 12px 0 22px;
}
.legend__item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 12.5px;
  color: var(--ink-2);
}
.dot {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  flex: none;
}
.dot--comm {
  background: var(--gold);
}
.dot--tip {
  background: var(--rose);
}
.dot--salon {
  background: #c8bca9;
}

.ledger {
  margin: 0 0 22px;
}
.ledger__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid var(--line);
}
.ledger__row dt {
  color: var(--ink-2);
  font-size: 14.5px;
}
.ledger__row dd {
  margin: 0;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  font-size: 15px;
}
.ledger__row--muted dt,
.ledger__row--muted dd {
  color: var(--muted);
}
.ledger__row--total {
  border-bottom: 0;
  margin-top: 4px;
  padding-top: 16px;
}
.ledger__row--total dt {
  font-family: var(--serif);
  font-size: 19px;
  color: var(--ink);
}
.ledger__row--total dd {
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 700;
  color: var(--gold-d);
}

/* ───────── Buttons ───────── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 14px 20px;
  border: 1px solid transparent;
  border-radius: var(--r-md);
  font-size: 14.5px;
  font-weight: 600;
  letter-spacing: 0.01em;
  transition: transform 0.12s, box-shadow 0.18s, background 0.18s;
}
.btn:active {
  transform: translateY(1px);
}
.btn--primary {
  color: var(--white);
  background: linear-gradient(150deg, var(--gold) 0%, var(--gold-d) 100%);
  box-shadow: 0 14px 26px -12px rgba(140, 109, 63, 0.75);
}
.btn--primary:hover {
  box-shadow: 0 18px 30px -12px rgba(140, 109, 63, 0.85);
}
.btn--ghost {
  background: var(--cream);
  border-color: var(--line-2);
  color: var(--ink-2);
}
.btn--ghost:hover {
  border-color: var(--gold);
  color: var(--gold-d);
}

/* ───────── Split / stylists ───────── */
.field--pool {
  max-width: 280px;
  margin-bottom: 22px;
}
.stylists {
  list-style: none;
  margin: 0 0 16px;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.stylist {
  display: grid;
  grid-template-columns: 38px 1fr 118px 96px 34px;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--cream);
  animation: rowIn 0.28s ease;
}
@keyframes rowIn {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
}
.stylist__avatar {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: linear-gradient(150deg, var(--rose-soft), var(--rose));
  display: grid;
  place-items: center;
  font-family: var(--serif);
  font-weight: 700;
  font-size: 15px;
  color: var(--white);
}
.stylist__name {
  border: 1px solid transparent;
  background: transparent;
  border-radius: var(--r-sm);
  padding: 8px 10px;
  font-size: 15px;
  font-weight: 500;
  color: var(--ink);
  outline: none;
  min-width: 0;
  transition: border-color 0.18s, background 0.18s;
}
.stylist__name:focus {
  border-color: var(--gold);
  background: var(--white);
}
.stylist__hours {
  display: flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 0 10px;
  background: var(--white);
  transition: border-color 0.18s, box-shadow 0.18s;
}
.stylist__hours:focus-within {
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.14);
}
.stylist__hourval {
  width: 100%;
  border: 0;
  background: transparent;
  outline: none;
  padding: 8px 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--ink);
}
.stylist__unit {
  font-size: 12px;
  color: var(--muted);
}
.stylist.is-even .stylist__hours {
  opacity: 0.4;
  pointer-events: none;
}
.stylist__amt {
  text-align: right;
  font-weight: 700;
  font-size: 16px;
  font-variant-numeric: tabular-nums;
  color: var(--gold-d);
}
.stylist__rm {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--muted);
  font-size: 13px;
  line-height: 1;
  display: grid;
  place-items: center;
  transition: all 0.16s;
}
.stylist__rm:hover {
  border-color: var(--danger);
  color: var(--danger);
  background: #fbeeeb;
}

/* ───────── Toast ───────── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 20px);
  background: var(--ink);
  color: var(--cream);
  padding: 12px 20px;
  border-radius: 999px;
  font-size: 13.5px;
  font-weight: 500;
  box-shadow: 0 18px 40px -14px rgba(28, 24, 20, 0.6);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s, transform 0.25s;
  z-index: 50;
}
.toast.is-show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ───────── Responsive ───────── */
@media (max-width: 820px) {
  .grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .panel {
    padding: 20px;
  }
  .panel__head {
    flex-direction: column;
  }
  .tip-presets {
    grid-template-columns: repeat(2, 1fr);
  }
  .stylist {
    grid-template-columns: 36px 1fr 30px;
    grid-template-areas:
      "av name rm"
      "av hours amt";
    row-gap: 8px;
  }
  .stylist__avatar {
    grid-area: av;
  }
  .stylist__name {
    grid-area: name;
  }
  .stylist__hours {
    grid-area: hours;
  }
  .stylist__amt {
    grid-area: amt;
    align-self: center;
  }
  .stylist__rm {
    grid-area: rm;
    justify-self: end;
  }
  .field--pool {
    max-width: 100%;
  }
}

