(function () {
  "use strict";

  var fmt = function (n) {
    if (!isFinite(n)) n = 0;
    return "$" + n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  };
  var num = function (el) {
    var v = parseFloat(el.value);
    return isFinite(v) && v >= 0 ? v : 0;
  };
  var initials = function (name) {
    var p = (name || "").trim().split(/\s+/).filter(Boolean);
    if (!p.length) return "•";
    return (p[0][0] + (p[1] ? p[1][0] : "")).toUpperCase();
  };

  /* ───────── Toast ───────── */
  var toastEl = document.getElementById("toast");
  var toastTimer;
  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add("is-show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("is-show");
    }, 2600);
  }

  /* ════════════ Calculator ════════════ */
  var serviceTotal = document.getElementById("serviceTotal");
  var tipValue = document.getElementById("tipValue");
  var tipSym = document.getElementById("tipSym");
  var commissionRate = document.getElementById("commissionRate");
  var rateOut = document.getElementById("rateOut");
  var presets = document.getElementById("tipPresets");

  var tipMode = "pct"; // "pct" | "amt"

  function activeTip() {
    // returns absolute tip dollars based on mode
    var service = num(serviceTotal);
    if (tipMode === "pct") {
      return service * (num(tipValue) / 100);
    }
    return num(tipValue);
  }

  function recalc() {
    var service = num(serviceTotal);
    var rate = num(commissionRate) / 100;
    var tip = activeTip();

    var commission = service * rate;
    var salon = service - commission;
    var take = commission + tip;

    document.getElementById("rowService").textContent = fmt(service);
    document.getElementById("rowComm").textContent = fmt(commission);
    document.getElementById("rowTip").textContent = fmt(tip);
    document.getElementById("rowSalon").textContent = fmt(salon);
    document.getElementById("rowTake").textContent = fmt(take);
    document.getElementById("takeHome").textContent = fmt(take);

    // stacked bar — proportion of grand total (service + tip)
    var grand = service + tip;
    var pc = grand > 0 ? (commission / grand) * 100 : 0;
    var pt = grand > 0 ? (tip / grand) * 100 : 0;
    var ps = grand > 0 ? (salon / grand) * 100 : 0;
    document.getElementById("barComm").style.width = pc + "%";
    document.getElementById("barTip").style.width = pt + "%";
    document.getElementById("barSalon").style.width = ps + "%";
  }

  function syncRate() {
    var v = num(commissionRate);
    rateOut.textContent = v + "%";
    commissionRate.style.setProperty("--fill", v + "%");
  }

  // tip mode toggle
  document.querySelectorAll("[data-tipmode]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      tipMode = btn.getAttribute("data-tipmode");
      document.querySelectorAll("[data-tipmode]").forEach(function (b) {
        var on = b === btn;
        b.classList.toggle("is-active", on);
        b.setAttribute("aria-pressed", on ? "true" : "false");
      });
      if (tipMode === "pct") {
        tipSym.textContent = "%";
        presets.style.display = "";
        if (num(tipValue) > 100) tipValue.value = "20";
      } else {
        tipSym.textContent = "$";
        presets.style.display = "none";
        // convert current % into a dollar value for convenience
        tipValue.value = activeTipFromPctSnapshot().toFixed(0);
        clearPresets();
      }
      recalc();
    });
  });

  var lastPct = 20;
  function activeTipFromPctSnapshot() {
    return num(serviceTotal) * (lastPct / 100);
  }

  function clearPresets() {
    presets.querySelectorAll(".preset").forEach(function (p) {
      p.classList.remove("is-active");
    });
  }

  // tip presets
  presets.querySelectorAll(".preset").forEach(function (p) {
    p.addEventListener("click", function () {
      clearPresets();
      p.classList.add("is-active");
      var pct = Math.round(parseFloat(p.getAttribute("data-tip")) * 100);
      lastPct = pct;
      tipMode = "pct";
      document.querySelectorAll("[data-tipmode]").forEach(function (b) {
        var on = b.getAttribute("data-tipmode") === "pct";
        b.classList.toggle("is-active", on);
        b.setAttribute("aria-pressed", on ? "true" : "false");
      });
      tipSym.textContent = "%";
      presets.style.display = "";
      tipValue.value = String(pct);
      recalc();
    });
  });

  serviceTotal.addEventListener("input", recalc);
  tipValue.addEventListener("input", function () {
    if (tipMode === "pct") lastPct = num(tipValue);
    clearPresets();
    recalc();
  });
  commissionRate.addEventListener("input", function () {
    syncRate();
    recalc();
  });

  document.getElementById("settleBtn").addEventListener("click", function () {
    toast("Ticket settled — " + document.getElementById("takeHome").textContent + " to Aria Vance.");
  });

  syncRate();
  recalc();

  /* ════════════ Split mode ════════════ */
  var list = document.getElementById("stylistList");
  var tpl = document.getElementById("stylistTpl");
  var poolTip = document.getElementById("poolTip");
  var splitMode = "hours"; // "hours" | "even"

  var seed = [
    { name: "Aria Vance", hours: 6 },
    { name: "Léa Moreau", hours: 4.5 },
    { name: "Noor Haddad", hours: 3 }
  ];

  function rows() {
    return Array.prototype.slice.call(list.querySelectorAll(".stylist"));
  }

  function recalcSplit() {
    var pool = num(poolTip);
    var r = rows();
    var n = r.length;
    if (!n) return;

    var totalHours = 0;
    r.forEach(function (row) {
      totalHours += num(row.querySelector(".stylist__hourval"));
    });

    r.forEach(function (row) {
      var amtEl = row.querySelector(".stylist__amt");
      var share;
      if (splitMode === "even") {
        share = pool / n;
      } else {
        var h = num(row.querySelector(".stylist__hourval"));
        share = totalHours > 0 ? pool * (h / totalHours) : 0;
      }
      amtEl.textContent = fmt(share);
    });
  }

  function makeRow(data) {
    var node = tpl.content.firstElementChild.cloneNode(true);
    var nameI = node.querySelector(".stylist__name");
    var hourI = node.querySelector(".stylist__hourval");
    var avatar = node.querySelector(".stylist__avatar");

    nameI.value = data.name || "";
    hourI.value = data.hours != null ? String(data.hours) : "";
    avatar.textContent = initials(data.name);

    nameI.addEventListener("input", function () {
      avatar.textContent = initials(nameI.value);
    });
    hourI.addEventListener("input", recalcSplit);

    node.querySelector(".stylist__rm").addEventListener("click", function () {
      if (rows().length <= 1) {
        toast("Keep at least one stylist on the split.");
        return;
      }
      node.remove();
      recalcSplit();
    });

    node.classList.toggle("is-even", splitMode === "even");
    list.appendChild(node);
    return node;
  }

  seed.forEach(makeRow);
  recalcSplit();

  poolTip.addEventListener("input", recalcSplit);

  document.querySelectorAll("[data-splitmode]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      splitMode = btn.getAttribute("data-splitmode");
      document.querySelectorAll("[data-splitmode]").forEach(function (b) {
        var on = b === btn;
        b.classList.toggle("is-active", on);
        b.setAttribute("aria-pressed", on ? "true" : "false");
      });
      rows().forEach(function (row) {
        row.classList.toggle("is-even", splitMode === "even");
      });
      recalcSplit();
    });
  });

  document.getElementById("addStylist").addEventListener("click", function () {
    var n = rows().length + 1;
    var row = makeRow({ name: "", hours: 3 });
    row.querySelector(".stylist__name").placeholder = "Stylist " + n;
    row.querySelector(".stylist__name").focus();
    recalcSplit();
  });
})();

snippets.css:
:root {
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --sh-sm: 0 1px 2px rgba(28, 24, 20, 0.06);
  --sh-md: 0 10px 30px -12px rgba(28, 24, 20, 0.22);
  --sh-lg: 0 30px 70px -28px rgba(28, 24, 20, 0.34);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  margin: 0;
  font-family: var(--sans);
  line-height: 1.5;
  color: var(--ink);
  background:
    radial-gradient(120% 80% at 50% -10%, var(--cream) 0%, var(--bg) 55%) fixed;
  min-height: 100vh;
}

.stage {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: clamp(18px, 4vw, 56px);
}

/* ── Card ─────────────────────────────── */
.appt {
  width: 100%;
  max-width: 520px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-lg);
  padding: clamp(22px, 4vw, 34px);
  position: relative;
  overflow: hidden;
}

.appt::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: linear-gradient(90deg, transparent, var(--gold), var(--rose), transparent);
  opacity: 0.9;
}

/* ── Header ───────────────────────────── */
.appt__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand__mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid var(--gold);
  color: var(--gold-d);
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1rem;
  letter-spacing: 0.04em;
  background: var(--gold-soft);
}

.brand__txt {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}

.brand__name {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.15rem;
  color: var(--ink);
}

.brand__sub {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--muted);
}

/* ── Status pill ──────────────────────── */
.pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 13px 6px 11px;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  border: 1px solid var(--line-2);
  background: var(--cream);
  color: var(--ink-2);
  transition: background 0.3s ease, color 0.3s ease, border-color 0.3s ease;
  white-space: nowrap;
}

.pill__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 22%, transparent);
}

.pill[data-status="confirmed"] {
  color: var(--gold-d);
  border-color: color-mix(in srgb, var(--gold) 45%, transparent);
  background: var(--gold-soft);
}
.pill[data-status="checkedin"] {
  color: #4d6fa3;
  border-color: rgba(77, 111, 163, 0.4);
  background: rgba(77, 111, 163, 0.1);
}
.pill[data-status="service"] {
  color: var(--warn);
  border-color: rgba(192, 138, 62, 0.4);
  background: rgba(192, 138, 62, 0.12);
}
.pill[data-status="service"] .pill__dot {
  animation: pulse 1.4s ease-in-out infinite;
}
.pill[data-status="done"] {
  color: var(--ok);
  border-color: rgba(95, 138, 107, 0.42);
  background: rgba(95, 138, 107, 0.12);
}

@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.45; transform: scale(0.8); }
}

/* ── Client ───────────────────────────── */
.client {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 22px;
}

.avatar {
  flex: none;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.25rem;
  color: var(--white);
  background: linear-gradient(140deg, var(--rose), var(--gold-d));
  box-shadow: var(--sh-sm), inset 0 0 0 2px var(--white);
}

.client__info {
  flex: 1;
  min-width: 0;
}

.client__name {
  margin: 0;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.55rem;
  line-height: 1.1;
  color: var(--ink);
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
}

.vip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--sans);
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-d);
  background: var(--gold-soft);
  border: 1px solid color-mix(in srgb, var(--gold) 45%, transparent);
  padding: 3px 8px;
  border-radius: 999px;
}

.client__phone {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
  font-size: 0.85rem;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s ease;
}
.client__phone:hover {
  color: var(--gold-d);
}

.client__meta {
  flex: none;
  text-align: right;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

/* ── Meta primitives ──────────────────── */
.metalabel {
  font-size: 0.62rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--muted);
  font-weight: 600;
}
.metaval {
  font-size: 0.9rem;
  color: var(--ink-2);
  font-weight: 600;
}
.metaval--lead {
  font-family: var(--serif);
  font-size: 1.18rem;
  font-weight: 600;
  color: var(--ink);
}
.metasub {
  font-size: 0.76rem;
  color: var(--muted);
}

.rule {
  height: 1px;
  margin: 22px 0;
  background: linear-gradient(90deg, transparent, var(--line-2) 18%, var(--line-2) 82%, transparent);
}

/* ── Schedule grid ────────────────────── */
.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.field + .field {
  padding-left: 16px;
  border-left: 1px solid var(--line);
}

/* ── Services ─────────────────────────── */
.section-cap {
  display: block;
  font-size: 0.62rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--muted);
  font-weight: 600;
  margin-bottom: 12px;
}

.lines {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
}
.line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 11px 0;
  border-bottom: 1px dashed var(--line);
}
.line:last-child {
  border-bottom: none;
}
.line__name {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.94rem;
  color: var(--ink-2);
  font-weight: 500;
}
.line__price {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--ink);
}
.line__tag {
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gold-d);
  background: var(--gold-soft);
  padding: 2px 7px;
  border-radius: 999px;
}
.line__addon {
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
  border: 1px solid var(--line-2);
  padding: 2px 7px;
  border-radius: 999px;
}

/* ── Notes ────────────────────────────── */
.notes {
  display: flex;
  gap: 10px;
  margin-top: 18px;
  padding: 13px 15px;
  background: var(--rose-soft);
  border: 1px solid color-mix(in srgb, var(--rose) 30%, transparent);
  border-radius: var(--r-md);
}
.notes__icon {
  flex: none;
  color: var(--gold-d);
  margin-top: 2px;
}
.notes__txt {
  margin: 0;
  font-size: 0.83rem;
  line-height: 1.45;
  color: var(--ink-2);
}

/* ── Footer / totals ──────────────────── */
.appt__foot {
  margin-top: 22px;
}
.totals {
  margin: 0 0 20px;
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.totals__row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 0.9rem;
}
.totals__row dt {
  color: var(--muted);
}
.totals__row dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--ink-2);
}
.totals__row--muted dd {
  color: var(--ok);
}
.totals__row--grand {
  padding-top: 11px;
  border-top: 1px solid var(--line-2);
  align-items: baseline;
}
.totals__row--grand dt {
  font-family: var(--serif);
  font-size: 1.05rem;
  color: var(--ink);
}
.totals__row--grand dd {
  font-family: var(--serif);
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--gold-d);
}

/* ── Actions ──────────────────────────── */
.actions {
  display: flex;
  gap: 10px;
}
.btn {
  flex: 1;
  font-family: var(--sans);
  font-size: 0.86rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  padding: 12px 14px;
  border-radius: var(--r-md);
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink-2);
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.2s ease, background 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}
.btn:hover {
  border-color: var(--gold);
  color: var(--gold-d);
  box-shadow: var(--sh-sm);
}
.btn:active {
  transform: translateY(1px);
}
.btn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}
.btn--primary {
  flex: 1.4;
  background: linear-gradient(140deg, var(--ink), var(--ink-2));
  color: var(--cream);
  border-color: var(--ink);
}
.btn--primary:hover {
  background: linear-gradient(140deg, var(--gold-d), var(--gold));
  color: var(--white);
  border-color: var(--gold-d);
  box-shadow: var(--sh-md);
}
.btn--primary:disabled {
  background: var(--cream);
  color: var(--muted);
  border-color: var(--line-2);
  cursor: default;
  box-shadow: none;
  transform: none;
}

/* ── Toasts ───────────────────────────── */
.toast-wrap {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 10px;
  z-index: 50;
  pointer-events: none;
  width: min(92vw, 380px);
}
.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  background: var(--ink);
  color: var(--cream);
  border-radius: var(--r-md);
  box-shadow: var(--sh-md);
  font-size: 0.85rem;
  font-weight: 500;
  border: 1px solid rgba(255, 255, 255, 0.08);
  opacity: 0;
  transform: translateY(14px) scale(0.98);
  transition: opacity 0.3s ease, transform 0.3s ease;
}
.toast.show {
  opacity: 1;
  transform: translateY(0) scale(1);
}
.toast__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--gold);
  flex: none;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

/* ── Responsive ───────────────────────── */
@media (max-width: 520px) {
  .appt {
    padding: 20px 18px;
    border-radius: var(--r-md);
  }
  .grid {
    grid-template-columns: 1fr 1fr;
  }
  .field:nth-child(3) {
    grid-column: 1 / -1;
    padding-left: 0;
    padding-top: 14px;
    border-left: none;
    border-top: 1px solid var(--line);
  }
  .client__meta {
    display: none;
  }
  .actions {
    flex-wrap: wrap;
  }
  .btn--primary {
    flex-basis: 100%;
  }
  .client__name {
    font-size: 1.35rem;
  }
}

