(function () {
  "use strict";

  /* ── Toast helper ─────────────────────── */
  var toastWrap = document.getElementById("toasts");

  function toast(msg) {
    var el = document.createElement("div");
    el.className = "toast";
    el.setAttribute("role", "status");
    el.innerHTML = '<span class="toast__dot" aria-hidden="true"></span><span></span>';
    el.querySelector("span:last-child").textContent = msg;
    toastWrap.appendChild(el);
    // force reflow so the transition runs
    void el.offsetWidth;
    el.classList.add("show");

    window.setTimeout(function () {
      el.classList.remove("show");
      window.setTimeout(function () {
        if (el.parentNode) el.parentNode.removeChild(el);
      }, 320);
    }, 2600);
  }

  /* ── Status machine ───────────────────── */
  // Each step: machine-readable key, the pill label, and the label for the
  // button that advances *to the next* step.
  var FLOW = [
    { key: "confirmed", label: "Confirmed", next: "Check in" },
    { key: "checkedin", label: "Checked-in", next: "Begin service" },
    { key: "service", label: "In service", next: "Complete" },
    { key: "done", label: "Done", next: null }
  ];

  var stepIndex = 0;

  var pill = document.getElementById("status");
  var pillLabel = document.getElementById("status-label");
  var advanceBtn = document.getElementById("advance");

  var ARRIVAL_MSG = {
    checkedin: "Aria Vance checked in — Léa has been notified.",
    service: "Service started at chair 3. Timer running.",
    done: "Appointment complete. Receipt ready to send."
  };

  function render() {
    var step = FLOW[stepIndex];
    pill.setAttribute("data-status", step.key);
    pillLabel.textContent = step.label;

    if (step.next) {
      advanceBtn.textContent = step.next;
      advanceBtn.disabled = false;
    } else {
      advanceBtn.textContent = "Completed";
      advanceBtn.disabled = true;
    }
  }

  advanceBtn.addEventListener("click", function () {
    if (stepIndex >= FLOW.length - 1) return;
    stepIndex += 1;
    render();
    var step = FLOW[stepIndex];
    if (ARRIVAL_MSG[step.key]) toast(ARRIVAL_MSG[step.key]);
  });

  /* ── Totals (derived from the line items) ─ */
  var DISCOUNT_RATE = 0.1; // Atelier member

  function money(n) {
    var sign = n < 0 ? "−" : "";
    var v = Math.abs(n).toFixed(2);
    // trim a trailing ".00" to a clean dollar figure
    v = v.replace(/\.00$/, "");
    return sign + "$" + v;
  }

  function parsePrice(txt) {
    var m = txt.replace(/[^0-9.]/g, "");
    return m ? parseFloat(m) : 0;
  }

  function recalc() {
    var subtotal = 0;
    document.querySelectorAll("#lines .line__price").forEach(function (el) {
      subtotal += parsePrice(el.textContent);
    });
    var discount = subtotal * DISCOUNT_RATE;
    var total = subtotal - discount;

    document.getElementById("subtotal").textContent = money(subtotal);
    document.getElementById("discount").textContent = money(-discount);
    document.getElementById("total").textContent = money(total);
  }

  /* ── Secondary actions ────────────────── */
  document.getElementById("reschedule").addEventListener("click", function () {
    toast("Reschedule link sent to Aria — choose a new slot.");
  });

  document.getElementById("message").addEventListener("click", function () {
    toast("Message thread opened with Aria Vance.");
  });

  /* ── Init ─────────────────────────────── */
  recalc();
  render();
})();

snippets.css:
:root {
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --shadow-sm: 0 1px 2px rgba(28, 24, 20, 0.05), 0 1px 1px rgba(28, 24, 20, 0.04);
  --shadow-md: 0 14px 34px -18px rgba(28, 24, 20, 0.32), 0 2px 8px rgba(28, 24, 20, 0.05);
  --shadow-lg: 0 40px 80px -38px rgba(28, 24, 20, 0.42);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: var(--sans);
  line-height: 1.5;
  color: var(--ink);
  background:
    radial-gradient(120% 80% at 100% 0%, var(--rose-soft) 0%, transparent 45%),
    radial-gradient(120% 90% at 0% 100%, var(--gold-soft) 0%, transparent 40%),
    var(--bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  display: flex;
  justify-content: center;
  padding: 40px 20px;
}

h1,
h2 {
  font-family: var(--serif);
  font-weight: 600;
  margin: 0;
  letter-spacing: 0.2px;
}

.wrap {
  width: 100%;
  max-width: 540px;
}

/* ---------- card shell ---------- */
.card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
}

.card__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 26px 28px 22px;
  background: linear-gradient(180deg, var(--cream), var(--white));
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.brand__mark {
  flex: none;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: var(--serif);
  font-weight: 700;
  font-size: 18px;
  letter-spacing: 0.5px;
  color: var(--white);
  background: linear-gradient(140deg, var(--gold), var(--gold-d));
  box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.4), var(--shadow-sm);
}

.eyebrow {
  margin: 0 0 2px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 1.6px;
  text-transform: uppercase;
  color: var(--gold-d);
}

#loyalty-title {
  font-size: 26px;
  line-height: 1.1;
  color: var(--ink);
}

.member {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: none;
}

.member__meta {
  text-align: right;
}

.member__name {
  display: block;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--ink-2);
}

.tier-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.4px;
  color: var(--gold-d);
  background: var(--gold-soft);
  border: 1px solid rgba(176, 141, 87, 0.3);
}

.tier-pill__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.18);
}

.member__avatar {
  flex: none;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 13px;
  font-weight: 600;
  color: var(--gold-d);
  background: var(--rose-soft);
  border: 1px solid rgba(201, 167, 143, 0.5);
}

/* ---------- panels ---------- */
.panel {
  padding: 24px 28px;
  border-bottom: 1px solid var(--line);
}

.panel:last-child {
  border-bottom: 0;
}

.panel__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}

.panel__title {
  font-size: 20px;
  color: var(--ink);
}

.panel__hint {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
}

.label {
  margin: 0 0 4px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- progress ---------- */
.progress__top {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

.points {
  margin: 0;
  font-family: var(--serif);
  font-weight: 700;
  font-size: 42px;
  line-height: 1;
  color: var(--ink);
}

.points__unit {
  font-family: var(--sans);
  font-size: 14px;
  font-weight: 600;
  color: var(--muted);
  margin-left: 6px;
}

.progress__goal {
  text-align: right;
}

.goal-name {
  margin: 0;
  font-family: var(--serif);
  font-size: 19px;
  font-weight: 600;
  color: var(--gold-d);
}

.bar {
  height: 12px;
  border-radius: 999px;
  background: var(--gold-soft);
  border: 1px solid rgba(176, 141, 87, 0.22);
  overflow: hidden;
  box-shadow: inset 0 1px 2px rgba(28, 24, 20, 0.08);
}

.bar__fill {
  height: 100%;
  width: 0%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--rose), var(--gold) 60%, var(--gold-d));
  box-shadow: 0 0 12px rgba(176, 141, 87, 0.45);
  transition: width 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}

.bar__caption {
  margin: 10px 0 0;
  font-size: 12.5px;
  color: var(--ink-2);
}

.bar__caption span {
  font-weight: 600;
  color: var(--gold-d);
}

.tiers {
  list-style: none;
  margin: 20px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
}

.tier {
  position: relative;
  text-align: center;
  padding: 12px 4px 10px;
  border-radius: var(--r-md);
  border: 1px solid var(--line);
  background: var(--cream);
}

.tier__badge {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  margin: 0 auto 7px;
  border-radius: 50%;
  font-size: 13px;
  color: var(--muted);
  background: var(--white);
  border: 1px solid var(--line-2);
  transition: all 0.25s ease;
}

.tier__name {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--ink-2);
}

.tier__at {
  display: block;
  font-size: 10.5px;
  color: var(--muted);
  margin-top: 2px;
}

.tier.is-done .tier__badge {
  color: var(--white);
  background: linear-gradient(140deg, var(--gold), var(--gold-d));
  border-color: var(--gold-d);
}

.tier.is-current {
  border-color: var(--gold);
  background: var(--gold-soft);
  box-shadow: 0 0 0 1px rgba(176, 141, 87, 0.35), var(--shadow-sm);
}

.tier.is-current .tier__badge {
  color: var(--gold-d);
  background: var(--white);
  border-color: var(--gold);
  box-shadow: 0 0 0 4px rgba(176, 141, 87, 0.16);
}

/* ---------- stamps ---------- */
.stamp-row {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 10px;
}

.stamp {
  aspect-ratio: 1;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 15px;
  color: var(--muted);
  background: var(--cream);
  border: 1px dashed var(--line-2);
}

.stamp.is-punched {
  color: var(--white);
  background: linear-gradient(140deg, var(--rose), var(--gold));
  border: 1px solid var(--gold-d);
  box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.4), var(--shadow-sm);
}

.stamp.is-free {
  color: var(--gold-d);
  background: var(--white);
  border: 1px solid var(--gold);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.14);
}

.stamp.is-free::after {
  content: "FREE";
  font-family: var(--sans);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.6px;
}

/* ---------- rewards ---------- */
.reward-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 12px;
}

.reward {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border-radius: var(--r-md);
  border: 1px solid var(--line);
  background: var(--white);
  box-shadow: var(--shadow-sm);
  transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
}

.reward:hover {
  border-color: rgba(176, 141, 87, 0.4);
  box-shadow: var(--shadow-md);
}

.reward__icon {
  flex: none;
  width: 44px;
  height: 44px;
  border-radius: var(--r-sm);
  display: grid;
  place-items: center;
  font-size: 20px;
  background: var(--gold-soft);
  border: 1px solid rgba(176, 141, 87, 0.28);
}

.reward__body {
  flex: 1;
  min-width: 0;
}

.reward__name {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--ink);
}

.reward__desc {
  margin: 2px 0 0;
  font-size: 12px;
  color: var(--muted);
}

.reward__cost {
  flex: none;
  text-align: center;
  font-size: 13px;
  font-weight: 600;
  color: var(--gold-d);
  white-space: nowrap;
}

.reward__cost small {
  display: block;
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- buttons ---------- */
.btn {
  font-family: var(--sans);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.2px;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.2s ease, background 0.2s ease, color 0.2s ease, border-color 0.2s ease;
  white-space: nowrap;
}

.btn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(1px);
}

.btn--solid {
  padding: 11px 20px;
  color: var(--white);
  background: linear-gradient(140deg, var(--gold), var(--gold-d));
  box-shadow: var(--shadow-sm);
}

.btn--solid:hover {
  box-shadow: 0 8px 20px -8px rgba(140, 109, 63, 0.6);
}

.btn--ghost {
  padding: 8px 14px;
  color: var(--gold-d);
  background: var(--white);
  border-color: var(--line-2);
}

.btn--ghost:hover {
  background: var(--cream);
  border-color: var(--gold);
}

.reward__redeem {
  flex: none;
  padding: 9px 16px;
  color: var(--gold-d);
  background: var(--gold-soft);
  border: 1px solid rgba(176, 141, 87, 0.4);
  border-radius: 999px;
  font-family: var(--sans);
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.18s ease;
}

.reward__redeem:hover:not(:disabled) {
  color: var(--white);
  background: linear-gradient(140deg, var(--gold), var(--gold-d));
  border-color: var(--gold-d);
}

.reward__redeem:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.reward__redeem:disabled {
  cursor: not-allowed;
  color: var(--muted);
  background: var(--cream);
  border-color: var(--line);
  opacity: 0.85;
}

.reward.is-locked {
  opacity: 0.72;
}

/* ---------- referral ---------- */
.referral {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  align-items: center;
  background: linear-gradient(160deg, var(--cream), var(--rose-soft));
}

.referral__copy .panel__title {
  font-size: 22px;
  margin-top: 2px;
}

.referral__sub {
  margin: 8px 0 0;
  font-size: 12.5px;
  color: var(--ink-2);
}

.referral__code {
  display: grid;
  gap: 10px;
}

.code-field {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 9px 9px 14px;
  background: var(--white);
  border: 1px dashed var(--gold);
  border-radius: var(--r-md);
}

.code-field code {
  font-family: var(--sans);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--ink);
}

.copy {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.copy.is-copied {
  color: var(--ok);
  border-color: var(--ok);
  background: rgba(95, 138, 107, 0.1);
}

.referral__stats {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  color: var(--muted);
}

.referral__stats strong {
  color: var(--ink);
}

.referral__stats .dot {
  color: var(--line-2);
}

/* ---------- toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 24px);
  max-width: 90vw;
  padding: 12px 20px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 500;
  color: var(--cream);
  background: var(--ink);
  border: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: var(--shadow-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease, transform 0.3s cubic-bezier(0.22, 1, 0.36, 1);
  z-index: 50;
}

.toast.is-on {
  opacity: 1;
  transform: translate(-50%, 0);
}

.toast::before {
  content: "✦";
  color: var(--gold);
  margin-right: 8px;
}

@keyframes pop {
  0% { transform: scale(0.6); opacity: 0; }
  60% { transform: scale(1.12); }
  100% { transform: scale(1); opacity: 1; }
}

.stamp.just-punched {
  animation: pop 0.4s ease;
}

/* ---------- responsive ---------- */
@media (max-width: 520px) {
  body {
    padding: 18px 12px;
  }

  .card__head {
    flex-direction: column;
    align-items: flex-start;
    gap: 16px;
    padding: 22px 20px 20px;
  }

  .member {
    width: 100%;
    justify-content: flex-start;
    flex-direction: row-reverse;
  }

  .member__meta {
    text-align: left;
  }

  #loyalty-title {
    font-size: 24px;
  }

  .panel {
    padding: 20px;
  }

  .progress__top {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
  }

  .progress__goal {
    text-align: left;
  }

  .tiers {
    grid-template-columns: repeat(2, 1fr);
  }

  .stamp-row {
    grid-template-columns: repeat(4, 1fr);
  }

  .reward {
    flex-wrap: wrap;
  }

  .reward__cost {
    order: 2;
    text-align: left;
  }

  .reward__redeem {
    order: 3;
    margin-left: auto;
  }

  .referral {
    grid-template-columns: 1fr;
    gap: 18px;
  }
}

