(function () {
  "use strict";

  /* ---------- toast ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("is-show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("is-show");
    }, 2800);
  }

  /* ---------- sticky nav shadow ---------- */
  var nav = document.getElementById("nav");
  function onScroll() {
    if (window.scrollY > 8) nav.classList.add("is-stuck");
    else nav.classList.remove("is-stuck");
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  /* ---------- mobile nav ---------- */
  var toggle = document.getElementById("navToggle");
  var navLinks = document.getElementById("navLinks");
  function closeNav() {
    navLinks.classList.remove("is-open");
    toggle.setAttribute("aria-expanded", "false");
    toggle.setAttribute("aria-label", "Open menu");
  }
  toggle.addEventListener("click", function () {
    var open = navLinks.classList.toggle("is-open");
    toggle.setAttribute("aria-expanded", String(open));
    toggle.setAttribute("aria-label", open ? "Close menu" : "Open menu");
  });
  navLinks.querySelectorAll("a").forEach(function (a) {
    a.addEventListener("click", closeNav);
  });

  /* ---------- reveal on scroll ---------- */
  var reveals = document.querySelectorAll(".reveal");
  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (e) {
          if (e.isIntersecting) {
            e.target.classList.add("is-in");
            io.unobserve(e.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -40px 0px" }
    );
    reveals.forEach(function (el) { io.observe(el); });
  } else {
    reveals.forEach(function (el) { el.classList.add("is-in"); });
  }

  /* ---------- active nav link ---------- */
  var sections = ["services", "barbers", "heritage", "book"]
    .map(function (id) { return document.getElementById(id); })
    .filter(Boolean);
  var linkFor = {};
  navLinks.querySelectorAll('a[href^="#"]:not(.btn)').forEach(function (a) {
    linkFor[a.getAttribute("href").slice(1)] = a;
  });
  if ("IntersectionObserver" in window && sections.length) {
    var spy = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (e) {
          var link = linkFor[e.target.id];
          if (!link) return;
          if (e.isIntersecting) {
            Object.keys(linkFor).forEach(function (k) { linkFor[k].classList.remove("is-active"); });
            link.classList.add("is-active");
          }
        });
      },
      { threshold: 0.4 }
    );
    sections.forEach(function (s) { spy.observe(s); });
  }

  /* ---------- count-up stats ---------- */
  function animateCount(el) {
    var target = parseInt(el.getAttribute("data-count"), 10) || 0;
    var suffix = el.getAttribute("data-suffix") || "";
    var dur = 1300, start = null;
    function fmt(n) { return n.toLocaleString("en-US"); }
    function step(ts) {
      if (start === null) start = ts;
      var p = Math.min((ts - start) / dur, 1);
      var eased = 1 - Math.pow(1 - p, 3);
      el.textContent = fmt(Math.round(target * eased)) + suffix;
      if (p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }
  var counters = document.querySelectorAll("[data-count]");
  if ("IntersectionObserver" in window) {
    var cio = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (e) {
          if (e.isIntersecting) { animateCount(e.target); cio.unobserve(e.target); }
        });
      },
      { threshold: 0.6 }
    );
    counters.forEach(function (c) { cio.observe(c); });
  } else {
    counters.forEach(animateCount);
  }

  /* ---------- service filters ---------- */
  var chips = document.querySelectorAll(".chip");
  var cards = document.querySelectorAll(".svc");
  chips.forEach(function (chip) {
    chip.addEventListener("click", function () {
      var f = chip.getAttribute("data-filter");
      chips.forEach(function (c) {
        var on = c === chip;
        c.classList.toggle("is-active", on);
        c.setAttribute("aria-selected", String(on));
      });
      cards.forEach(function (card) {
        var match = f === "all" || card.getAttribute("data-cat") === f;
        card.classList.toggle("is-hidden", !match);
      });
    });
  });

  /* ---------- ticket builder ---------- */
  var ticket = [];
  var ticketEl = document.getElementById("ticket");
  var ticketList = document.getElementById("ticketList");
  var ticketTotal = document.getElementById("ticketTotal");

  function renderTicket() {
    if (!ticket.length) {
      ticketEl.hidden = true;
      return;
    }
    ticketEl.hidden = false;
    ticketList.innerHTML = "";
    var total = 0;
    ticket.forEach(function (item, i) {
      total += item.cost;
      var li = document.createElement("li");
      var label = document.createElement("span");
      label.textContent = item.name + " · $" + item.cost;
      var rm = document.createElement("button");
      rm.type = "button";
      rm.setAttribute("aria-label", "Remove " + item.name);
      rm.textContent = "×";
      rm.addEventListener("click", function () {
        ticket.splice(i, 1);
        renderTicket();
      });
      li.appendChild(label);
      li.appendChild(rm);
      ticketList.appendChild(li);
    });
    ticketTotal.textContent = "$" + total;
  }

  document.querySelectorAll("[data-add]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      var name = btn.getAttribute("data-add");
      var cost = parseInt(btn.getAttribute("data-cost"), 10) || 0;
      if (ticket.some(function (t) { return t.name === name; })) {
        toast(name + " is already on your ticket.");
        return;
      }
      ticket.push({ name: name, cost: cost });
      renderTicket();
      toast("Added " + name + " to your ticket.");
    });
  });

  /* ---------- barber picker ---------- */
  var barberSelect = document.getElementById("fBarber");
  function pickBarber(name, node) {
    document.querySelectorAll(".barber").forEach(function (b) { b.classList.remove("is-picked"); });
    if (node) node.classList.add("is-picked");
    if (barberSelect) {
      var found = Array.prototype.some.call(barberSelect.options, function (o) {
        if (o.value === name || o.text === name) { barberSelect.value = o.value || o.text; return true; }
        return false;
      });
      if (!found) barberSelect.value = name;
    }
    toast(name + " is your barber. Finish booking below.");
  }
  document.querySelectorAll(".barber").forEach(function (b) {
    function act() { pickBarber(b.getAttribute("data-barber"), b); }
    b.addEventListener("click", act);
    b.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); act(); }
    });
  });

  /* ---------- open / closed indicator ---------- */
  var openDot = document.getElementById("openDot");
  var openLabel = document.getElementById("openLabel");
  function updateOpen() {
    var now = new Date();
    var day = now.getDay(); // 0 Sun .. 6 Sat
    var hour = now.getHours() + now.getMinutes() / 60;
    var open = false;
    if (day >= 1 && day <= 5) open = hour >= 9 && hour < 19;
    else if (day === 6) open = hour >= 8 && hour < 17;
    openDot.classList.remove("is-open", "is-closed");
    if (open) {
      openDot.classList.add("is-open");
      openLabel.textContent = "Open now — the pole is spinning";
    } else {
      openDot.classList.add("is-closed");
      openLabel.textContent = day === 0 ? "Closed Sundays — see you Monday" : "Closed now — back during shop hours";
    }
  }
  if (openDot && openLabel) { updateOpen(); setInterval(updateOpen, 60000); }

  /* ---------- date min = today ---------- */
  var dateInput = document.getElementById("fDate");
  if (dateInput) {
    var t = new Date();
    var iso = t.getFullYear() + "-" + String(t.getMonth() + 1).padStart(2, "0") + "-" + String(t.getDate()).padStart(2, "0");
    dateInput.min = iso;
  }

  /* ---------- form validation ---------- */
  var form = document.getElementById("bookForm");
  function setError(id, msg) {
    var field = document.getElementById(id).closest(".field");
    var err = form.querySelector('.err[data-for="' + id + '"]');
    field.classList.toggle("has-error", !!msg);
    if (err) err.textContent = msg || "";
  }
  function validPhone(v) {
    var digits = v.replace(/\D/g, "");
    return digits.length >= 10;
  }
  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var ok = true;
    var name = document.getElementById("fName").value.trim();
    var phone = document.getElementById("fPhone").value.trim();
    var date = document.getElementById("fDate").value;

    if (!name) { setError("fName", "Tell us your name."); ok = false; } else setError("fName", "");
    if (!phone) { setError("fPhone", "We need a number to confirm."); ok = false; }
    else if (!validPhone(phone)) { setError("fPhone", "Enter a valid phone number."); ok = false; }
    else setError("fPhone", "");
    if (!date) { setError("fDate", "Pick a date."); ok = false; }
    else if (date < dateInput.min) { setError("fDate", "Choose today or later."); ok = false; }
    else setError("fDate", "");
    setError("fBarber", "");

    if (!ok) {
      toast("Please fix the highlighted fields.");
      var firstErr = form.querySelector(".has-error input, .has-error select");
      if (firstErr) firstErr.focus();
      return;
    }

    var barber = barberSelect.value || "the next available barber";
    var extra = ticket.length ? " (" + ticket.length + " item" + (ticket.length > 1 ? "s" : "") + " on ticket)" : "";
    toast("Booked, " + name + "! " + barber + " on " + date + extra + ". We'll text to confirm.");

    form.reset();
    ticket = [];
    renderTicket();
    document.querySelectorAll(".barber").forEach(function (b) { b.classList.remove("is-picked"); });
    if (dateInput) dateInput.min = iso;
  });

  /* clear field error as user types */
  ["fName", "fPhone", "fDate", "fBarber"].forEach(function (id) {
    var el = document.getElementById(id);
    if (el) el.addEventListener("input", function () { setError(id, ""); });
  });
})();

snippets.css:
:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --sh-1: 0 1px 2px rgba(0, 0, 0, 0.4);
  --sh-2: 0 8px 24px rgba(0, 0, 0, 0.45);
  --sh-3: 0 18px 48px rgba(0, 0, 0, 0.55);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button,
input {
  font-family: inherit;
}

:focus-visible {
  outline: 2px solid var(--neon);
  outline-offset: 2px;
  border-radius: var(--r-sm);
}

.app {
  max-width: 1280px;
  margin: 0 auto;
  padding: 18px 22px 48px;
}

/* ---------- Topbar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 0 20px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 24px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-mark {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: linear-gradient(135deg, var(--neon), var(--neon-d));
  color: #0b0d10;
  font-weight: 900;
  letter-spacing: -0.5px;
  font-size: 17px;
  box-shadow: 0 6px 18px var(--neon-50);
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.brand-name {
  font-weight: 800;
  font-size: 18px;
  letter-spacing: -0.3px;
}

.brand-sub {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--muted);
  font-weight: 600;
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: 14px;
}

.date-chip {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 6px 14px;
  line-height: 1.1;
}

.date-day {
  font-size: 10px;
  letter-spacing: 1.5px;
  color: var(--neon);
  font-weight: 800;
}

.date-num {
  font-size: 14px;
  font-weight: 700;
}

.coach {
  display: flex;
  align-items: center;
  gap: 10px;
}

.coach-av {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--orange-soft);
  color: var(--orange);
  font-weight: 800;
  font-size: 14px;
  border: 1px solid rgba(255, 106, 43, 0.3);
}

.coach-meta {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.coach-name {
  font-weight: 700;
  font-size: 14px;
}

.coach-role {
  font-size: 11px;
  color: var(--muted);
}

/* ---------- KPIs ---------- */
.kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 22px;
}

.kpi {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  box-shadow: var(--sh-1);
  position: relative;
  overflow: hidden;
}

.kpi.accent {
  background: linear-gradient(160deg, rgba(198, 255, 58, 0.08), var(--surface) 60%);
  border-color: rgba(198, 255, 58, 0.25);
}

.kpi-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  color: var(--muted);
  font-weight: 700;
}

.kpi-value {
  font-size: 30px;
  font-weight: 900;
  letter-spacing: -1px;
}

.kpi-value small {
  font-size: 16px;
  font-weight: 700;
  color: var(--ink-2);
}

.kpi-delta {
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
}

.kpi-delta.up {
  color: var(--ok);
}

/* ---------- Layout grid ---------- */
.grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 18px;
  align-items: start;
}

.side {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 18px;
  box-shadow: var(--sh-1);
}

.panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}

.eyebrow {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--neon);
  font-weight: 800;
}

.panel-title {
  margin: 2px 0 0;
  font-size: 19px;
  font-weight: 800;
  letter-spacing: -0.4px;
}

.pill {
  font-size: 11px;
  font-weight: 700;
  padding: 5px 10px;
  border-radius: 999px;
  background: var(--neon-50);
  color: var(--neon);
  white-space: nowrap;
}

.pill.warn {
  background: rgba(251, 191, 36, 0.14);
  color: var(--warn);
}

/* ---------- Segmented control ---------- */
.seg {
  display: inline-flex;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 3px;
  gap: 2px;
}

.seg-btn {
  border: 0;
  background: transparent;
  color: var(--ink-2);
  font-size: 12px;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.16s, color 0.16s;
}

.seg-btn:hover {
  color: var(--ink);
}

.seg-btn.is-active {
  background: var(--neon);
  color: #0b0d10;
}

/* ---------- Timeline ---------- */
.timeline {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
}

.t-item {
  display: grid;
  grid-template-columns: 64px 1fr;
  gap: 14px;
  padding: 14px 0;
  border-top: 1px solid var(--line);
}

.t-item:first-child {
  border-top: 0;
}

.t-item.is-hidden {
  display: none;
}

.t-time {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  padding-top: 2px;
}

.t-start {
  font-weight: 800;
  font-size: 14px;
}

.t-end {
  font-size: 11px;
  color: var(--muted);
}

.t-card {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-left: 3px solid var(--type-color, var(--line-2));
  border-radius: var(--r-md);
  overflow: hidden;
  transition: border-color 0.16s, transform 0.12s;
}

.t-card.type-pt {
  --type-color: var(--neon);
}
.t-card.type-group {
  --type-color: var(--orange);
}
.t-card.type-assessment {
  --type-color: #60a5fa;
}

.t-card.is-done {
  opacity: 0.62;
}

.t-trigger {
  width: 100%;
  text-align: left;
  background: transparent;
  border: 0;
  color: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
}

.t-trigger:hover {
  background: rgba(255, 255, 255, 0.025);
}

.t-main {
  flex: 1;
  min-width: 0;
}

.t-row1 {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.t-title {
  font-weight: 700;
  font-size: 14.5px;
}

.t-badge {
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--type-soft, rgba(255, 255, 255, 0.06));
  color: var(--type-color);
  border: 1px solid currentColor;
}

.t-sub {
  font-size: 12.5px;
  color: var(--muted);
  margin-top: 2px;
}

.t-chev {
  color: var(--muted);
  transition: transform 0.18s;
  flex-shrink: 0;
}

.t-card.is-open .t-chev {
  transform: rotate(180deg);
}

.t-detail {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.22s ease;
}

.t-card.is-open .t-detail {
  grid-template-rows: 1fr;
}

.t-detail-inner {
  overflow: hidden;
  padding: 0 14px;
}

.t-card.is-open .t-detail-inner {
  padding: 0 14px 14px;
}

.t-meta-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  border-top: 1px solid var(--line);
  padding-top: 12px;
}

.t-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.t-meta dt {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
  font-weight: 700;
  margin: 0;
}

.t-meta dd {
  margin: 0;
  font-size: 13px;
  font-weight: 600;
}

.t-notes {
  font-size: 13px;
  color: var(--ink-2);
  margin: 12px 0 0;
}

.t-actions {
  display: flex;
  gap: 8px;
  margin-top: 14px;
  flex-wrap: wrap;
}

/* ---------- Buttons ---------- */
.btn {
  border: 1px solid var(--line-2);
  background: var(--elevated);
  color: var(--ink);
  font-size: 13px;
  font-weight: 700;
  padding: 9px 14px;
  border-radius: var(--r-sm);
  cursor: pointer;
  transition: background 0.14s, transform 0.08s, border-color 0.14s;
}

.btn:hover {
  border-color: var(--line-2);
  background: #2a3038;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--neon);
  border-color: var(--neon);
  color: #0b0d10;
}

.btn-primary:hover {
  background: var(--neon-d);
  border-color: var(--neon-d);
}

.btn-done {
  background: var(--ok);
  border-color: var(--ok);
  color: #062318;
}

/* ---------- Clients ---------- */
.search {
  margin-bottom: 12px;
}

.search input {
  width: 100%;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  padding: 9px 12px;
  color: var(--ink);
  font-size: 13px;
}

.search input::placeholder {
  color: var(--muted);
}

.clients {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  max-height: 360px;
  overflow-y: auto;
}

.c-item {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 11px 8px;
  border-top: 1px solid var(--line);
  border-radius: var(--r-sm);
  cursor: pointer;
  transition: background 0.14s;
}

.c-item:first-child {
  border-top: 0;
}

.c-item:hover {
  background: var(--surface-2);
}

.c-item.is-hidden {
  display: none;
}

.c-av {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 800;
  font-size: 13px;
  flex-shrink: 0;
  color: #0b0d10;
}

.c-main {
  flex: 1;
  min-width: 0;
}

.c-name {
  font-weight: 700;
  font-size: 13.5px;
}

.c-next {
  font-size: 11.5px;
  color: var(--muted);
}

.c-adh {
  text-align: right;
  flex-shrink: 0;
}

.c-adh-val {
  font-weight: 800;
  font-size: 14px;
}

.c-adh-bar {
  width: 54px;
  height: 5px;
  border-radius: 999px;
  background: var(--surface-2);
  overflow: hidden;
  margin-top: 4px;
}

.c-adh-fill {
  height: 100%;
  border-radius: 999px;
}

.adh-hi .c-adh-fill {
  background: var(--ok);
}
.adh-hi .c-adh-val {
  color: var(--ok);
}
.adh-mid .c-adh-fill {
  background: var(--warn);
}
.adh-mid .c-adh-val {
  color: var(--warn);
}
.adh-lo .c-adh-fill {
  background: var(--danger);
}
.adh-lo .c-adh-val {
  color: var(--danger);
}

.empty {
  text-align: center;
  color: var(--muted);
  font-size: 13px;
  padding: 22px 0;
}

/* ---------- Tasks ---------- */
.tasks {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.task {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 11px 12px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  transition: opacity 0.16s, background 0.16s;
}

.task.is-done {
  opacity: 0.5;
}

.task-check {
  width: 22px;
  height: 22px;
  border-radius: 7px;
  border: 2px solid var(--line-2);
  background: transparent;
  cursor: pointer;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  transition: background 0.14s, border-color 0.14s;
  color: #062318;
}

.task-check:hover {
  border-color: var(--neon);
}

.task.is-done .task-check {
  background: var(--ok);
  border-color: var(--ok);
}

.task-check svg {
  opacity: 0;
  transition: opacity 0.12s;
}

.task.is-done .task-check svg {
  opacity: 1;
}

.task-main {
  flex: 1;
  min-width: 0;
}

.task-title {
  font-weight: 700;
  font-size: 13.5px;
}

.task.is-done .task-title {
  text-decoration: line-through;
}

.task-sub {
  font-size: 11.5px;
  color: var(--muted);
}

.task-tag {
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  padding: 3px 8px;
  border-radius: 999px;
  flex-shrink: 0;
}

.tag-program {
  background: var(--neon-50);
  color: var(--neon);
}

.tag-checkin {
  background: var(--orange-soft);
  color: var(--orange);
}

/* ---------- Toast ---------- */
.toast-wrap {
  position: fixed;
  bottom: 22px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 50;
  width: max-content;
  max-width: 92vw;
}

.toast {
  background: var(--elevated);
  border: 1px solid var(--line-2);
  border-left: 3px solid var(--neon);
  color: var(--ink);
  padding: 12px 16px;
  border-radius: var(--r-md);
  font-size: 13px;
  font-weight: 600;
  box-shadow: var(--sh-3);
  animation: toast-in 0.25s ease both;
}

.toast.out {
  animation: toast-out 0.25s ease forwards;
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
}

@keyframes toast-out {
  to {
    opacity: 0;
    transform: translateY(12px);
  }
}

/* ---------- Responsive ---------- */
@media (max-width: 920px) {
  .grid {
    grid-template-columns: 1fr;
  }
  .kpis {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 520px) {
  .app {
    padding: 14px 14px 40px;
  }
  .topbar {
    flex-wrap: wrap;
    gap: 12px;
  }
  .coach-meta {
    display: none;
  }
  .kpis {
    gap: 10px;
  }
  .kpi {
    padding: 13px 14px;
  }
  .kpi-value {
    font-size: 24px;
  }
  .panel {
    padding: 14px;
  }
  .panel-head {
    flex-direction: column;
    gap: 10px;
  }
  .seg {
    width: 100%;
    justify-content: space-between;
  }
  .seg-btn {
    flex: 1;
    text-align: center;
  }
  .t-item {
    grid-template-columns: 52px 1fr;
    gap: 10px;
  }
  .t-meta-grid {
    grid-template-columns: 1fr 1fr;
  }
  .clients {
    max-height: none;
  }
}

