// ── Toast ──────────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2800);
}

const list = document.getElementById("list");
const cards = () => Array.from(list.querySelectorAll(".card"));
const checkIcon =
  '<svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true">' +
  '<path d="M20 6 9 17l-5-5" fill="none" stroke="currentColor" ' +
  'stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>';

// ── Per-state metadata ───────────────────────────────────────────────────────
const BADGE = {
  active: { cls: "badge ok", text: "Active" },
  "needs-refill": { cls: "badge warn", text: "Needs refill" },
  requested: { cls: "badge requested", text: "Refill requested" },
  completed: { cls: "badge done", text: "Course complete" },
};

// ── Live counts + filter visibility ──────────────────────────────────────────
function matchesFilter(state, filter) {
  if (filter === "all") return true;
  if (filter === "active") return state === "active" || state === "requested";
  if (filter === "needs-refill") return state === "needs-refill";
  return true;
}

function currentFilter() {
  return document.querySelector(".filter.is-active").dataset.filter;
}

function isEligible(card) {
  return (
    card.dataset.state === "needs-refill" &&
    Number(card.querySelector("[data-refills]").textContent) > 0
  );
}

function refreshCounts() {
  const all = cards();
  const set = (id, n) => (document.getElementById(id).textContent = n);

  set("count-all", all.length);
  set(
    "count-active",
    all.filter((c) => matchesFilter(c.dataset.state, "active")).length
  );
  set(
    "count-needs-refill",
    all.filter((c) => c.dataset.state === "needs-refill").length
  );

  const eligible = all.filter(isEligible).length;
  set("eligible-count", eligible);
  const refillAll = document.getElementById("refill-all");
  refillAll.disabled = eligible === 0;
}

function applyFilter() {
  const filter = currentFilter();
  let visible = 0;
  cards().forEach((card) => {
    const show = matchesFilter(card.dataset.state, filter);
    card.hidden = !show;
    if (show) visible++;
  });
  document.getElementById("empty").hidden = visible !== 0;
}

// ── Filter tabs ──────────────────────────────────────────────────────────────
document.querySelectorAll(".filter").forEach((btn) => {
  btn.addEventListener("click", () => {
    document.querySelectorAll(".filter").forEach((f) => {
      const active = f === btn;
      f.classList.toggle("is-active", active);
      f.setAttribute("aria-selected", String(active));
    });
    applyFilter();
  });
});

// ── Request a single refill (pending → requested) ────────────────────────────
function requestRefill(card, { silent } = {}) {
  if (!isEligible(card)) return false;

  const refillsEl = card.querySelector("[data-refills]");
  const left = Number(refillsEl.textContent) - 1;
  refillsEl.textContent = left;
  refillsEl.classList.toggle("low", left <= 2);

  card.dataset.state = "requested";
  card.classList.remove("needs-refill");

  const badge = card.querySelector("[data-badge]");
  badge.className = BADGE.requested.cls;
  badge.textContent = BADGE.requested.text;

  // Reset the warn-styled due date now that it's handled.
  const due = card.querySelector(".warn-text");
  if (due) due.classList.remove("warn-text");

  const btn = card.querySelector("[data-action='request']");
  btn.classList.add("is-requested");
  btn.disabled = true;
  btn.innerHTML = checkIcon + "Requested";

  const name = card.querySelector("h2").firstChild.textContent.trim();
  if (!silent) {
    showToast(`Refill requested for ${name} — your care team will review it.`);
  }
  return name;
}

// ── Refill all eligible at once ──────────────────────────────────────────────
function refillAll() {
  const eligible = cards().filter(isEligible);
  if (eligible.length === 0) return;
  eligible.forEach((card) => requestRefill(card, { silent: true }));
  refreshCounts();
  applyFilter();
  showToast(
    `${eligible.length} refill request${eligible.length > 1 ? "s" : ""} sent ` +
      `to your care team.`
  );
}

// ── Event delegation ─────────────────────────────────────────────────────────
list.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action='request']");
  if (!btn || btn.disabled) return;
  const card = btn.closest(".card");
  const requested = requestRefill(card);
  if (requested) {
    refreshCounts();
    applyFilter();
    card.classList.remove("just-requested");
    void card.offsetWidth; // restart animation
    card.classList.add("just-requested");
  }
});

document.getElementById("refill-all").addEventListener("click", refillAll);

// ── Init ─────────────────────────────────────────────────────────────────────
refreshCounts();
applyFilter();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --sh-1: 0 1px 2px rgba(28, 42, 37, 0.05), 0 1px 1px rgba(28, 42, 37, 0.04);
  --sh-2: 0 6px 18px rgba(28, 42, 37, 0.08), 0 2px 6px rgba(28, 42, 37, 0.05);
  --sh-3: 0 18px 40px rgba(28, 42, 37, 0.14), 0 6px 14px rgba(28, 42, 37, 0.08);
}

* {
  box-sizing: border-box;
}

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  font-family: "Inter", system-ui, sans-serif;
  line-height: 1.55;
  color: var(--ink);
  background: var(--ivory);
}

h1, h2, h3 {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
  letter-spacing: 0.01em;
  margin: 0;
}

a {
  color: inherit;
}

.skip-link {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--green);
  color: var(--paper);
  padding: 10px 16px;
  border-radius: 0 0 var(--r-sm) 0;
  z-index: 50;
}
.skip-link:focus {
  left: 0;
}

/* ---------- Topbar ---------- */
.topbar {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 16px clamp(18px, 4vw, 48px);
  background: var(--green);
  color: var(--ivory);
  border-bottom: 1px solid rgba(176, 141, 87, 0.35);
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}
.brand-mark {
  color: var(--brass);
  font-size: 18px;
  line-height: 1;
}
.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}
.brand-text strong {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.02em;
}
.brand-text span {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: rgba(243, 234, 217, 0.7);
}

.topnav {
  display: flex;
  gap: 6px;
  margin-left: 12px;
}
.topnav a {
  text-decoration: none;
  font-size: 13.5px;
  font-weight: 500;
  color: rgba(243, 234, 217, 0.78);
  padding: 8px 14px;
  border-radius: 999px;
  transition: background 0.18s, color 0.18s;
}
.topnav a:hover {
  color: var(--ivory);
  background: rgba(255, 255, 255, 0.07);
}
.topnav a.active {
  color: var(--green-d);
  background: var(--brass-50);
}

.topbar-right {
  margin-left: auto;
}
.agent-pill {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 13.5px;
  font-weight: 500;
  padding: 6px 14px 6px 6px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(176, 141, 87, 0.35);
}
.agent-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--green-d);
  background: linear-gradient(140deg, var(--brass-50), var(--brass));
}

/* ---------- Layout ---------- */
.wrap {
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(28px, 5vw, 56px) clamp(18px, 4vw, 48px) 80px;
}

.page-head {
  display: flex;
  flex-wrap: wrap;
  gap: 28px;
  align-items: flex-end;
  justify-content: space-between;
  padding-bottom: 26px;
  border-bottom: 1px solid var(--line);
}
.eyebrow {
  margin: 0 0 6px;
  font-size: 11.5px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--brass-d);
}
.page-head h1 {
  font-size: clamp(34px, 5vw, 46px);
  line-height: 1.05;
  color: var(--green-d);
}
.lede {
  margin: 12px 0 0;
  max-width: 52ch;
  color: var(--ink-2);
  font-size: 15px;
}

.summary {
  display: flex;
  gap: 10px;
}
.summary-stat {
  min-width: 92px;
  padding: 14px 16px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  box-shadow: var(--sh-1);
  text-align: center;
}
.summary-stat .num {
  display: block;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 30px;
  font-weight: 700;
  line-height: 1;
  color: var(--green);
}
.summary-stat .lbl {
  display: block;
  margin-top: 4px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
}
.summary-stat.warn .num {
  color: var(--warn);
}

/* ---------- Toolbar ---------- */
.toolbar {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  margin: 26px 0 22px;
}
.filters {
  display: inline-flex;
  gap: 6px;
  padding: 4px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  box-shadow: var(--sh-1);
}
.chip {
  appearance: none;
  border: 0;
  cursor: pointer;
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-2);
  background: transparent;
  padding: 8px 16px;
  border-radius: 999px;
  transition: background 0.18s, color 0.18s, box-shadow 0.18s;
}
.chip:hover {
  color: var(--green-d);
}
.chip.is-active {
  color: var(--paper);
  background: var(--green);
  box-shadow: var(--sh-1);
}
.chip:focus-visible {
  outline: 2px solid var(--brass);
  outline-offset: 2px;
}
.toolbar-note {
  margin: 0;
  font-size: 13px;
  color: var(--muted);
}

/* ---------- Board ---------- */
.board {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 22px;
}

.txn {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-2);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow 0.22s, transform 0.22s;
}
.txn:hover {
  box-shadow: var(--sh-3);
  transform: translateY(-2px);
}

.txn-photo {
  position: relative;
  aspect-ratio: 16 / 7;
  background: linear-gradient(115deg, #2a4a3e 0%, #38604f 45%, #6f8a72 100%);
}
.txn-photo::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(120% 90% at 18% 12%, rgba(255, 245, 222, 0.42), transparent 55%),
    radial-gradient(90% 130% at 92% 100%, rgba(22, 48, 42, 0.6), transparent 60%);
}
.txn:nth-child(3n + 2) .txn-photo {
  background: linear-gradient(120deg, #5a4326 0%, #8a6a3c 48%, #c4a36a 100%);
}
.txn:nth-child(3n) .txn-photo {
  background: linear-gradient(125deg, #34433f 0%, #4d6a5c 40%, #9bb0a0 100%);
}
.txn-photo .ph-label {
  position: absolute;
  left: 14px;
  bottom: 12px;
  z-index: 1;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ivory);
  background: rgba(22, 48, 42, 0.5);
  border: 1px solid rgba(243, 234, 217, 0.3);
  padding: 4px 10px;
  border-radius: 999px;
  backdrop-filter: blur(2px);
}
.txn-photo .price-badge {
  position: absolute;
  right: 14px;
  top: 14px;
  z-index: 1;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 18px;
  font-weight: 700;
  color: var(--green-d);
  background: var(--brass-50);
  padding: 5px 12px;
  border-radius: 999px;
  box-shadow: var(--sh-1);
}

.txn-head {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  padding: 18px 20px 14px;
  border-bottom: 1px solid var(--line);
}
.txn-meta {
  min-width: 0;
}
.txn-meta h2 {
  font-size: 22px;
  line-height: 1.1;
  color: var(--green-d);
}
.txn-sub {
  margin: 3px 0 8px;
  font-size: 12.5px;
  color: var(--muted);
}
.tags {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.tag {
  font-size: 11px;
  font-weight: 600;
  color: var(--ink-2);
  background: var(--green-50);
  border: 1px solid var(--line);
  padding: 2px 9px;
  border-radius: 999px;
}

/* ---------- Progress ring ---------- */
.ring {
  flex: none;
  position: relative;
  width: 62px;
  height: 62px;
}
.ring svg {
  width: 62px;
  height: 62px;
  transform: rotate(-90deg);
}
.ring .track {
  fill: none;
  stroke: var(--green-50);
  stroke-width: 7;
}
.ring .bar {
  fill: none;
  stroke: var(--brass);
  stroke-width: 7;
  stroke-linecap: round;
  transition: stroke-dashoffset 0.6s cubic-bezier(0.4, 0, 0.2, 1), stroke 0.4s;
}
.ring.is-complete .bar {
  stroke: var(--ok);
}
.ring .ring-pct {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: 13px;
  font-weight: 700;
  color: var(--green-d);
}

/* ---------- Doc list ---------- */
.docs {
  list-style: none;
  margin: 0;
  padding: 6px 12px 12px;
}
.doc {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 6px 12px;
  align-items: center;
  padding: 12px 8px;
  border-bottom: 1px solid var(--line);
}
.doc:last-child {
  border-bottom: 0;
}
.doc-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--ink);
}
.doc-due {
  grid-column: 1;
  font-size: 12px;
  color: var(--muted);
}
.doc-due.is-overdue {
  color: var(--danger);
  font-weight: 600;
}

.status {
  grid-column: 2;
  grid-row: 1 / span 2;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  justify-self: end;
  font-size: 11.5px;
  font-weight: 600;
  padding: 5px 11px;
  border-radius: 999px;
  border: 1px solid transparent;
  white-space: nowrap;
}
.status .dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}
.status.s-missing {
  color: var(--danger);
  background: rgba(196, 80, 62, 0.1);
  border-color: rgba(196, 80, 62, 0.25);
}
.status.s-pending {
  color: var(--brass-d);
  background: var(--brass-50);
  border-color: rgba(176, 141, 87, 0.4);
}
.status.s-approved {
  color: var(--ok);
  background: rgba(47, 158, 111, 0.12);
  border-color: rgba(47, 158, 111, 0.3);
}
.status.s-expired {
  color: var(--ink-2);
  background: rgba(31, 61, 52, 0.08);
  border-color: var(--line-2);
}

.doc-actions {
  grid-column: 1 / -1;
  display: flex;
  gap: 8px;
  margin-top: 4px;
}
.btn {
  appearance: none;
  cursor: pointer;
  font-family: inherit;
  font-size: 12.5px;
  font-weight: 600;
  padding: 7px 13px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--green-d);
  transition: background 0.16s, border-color 0.16s, transform 0.08s;
}
.btn:hover {
  background: var(--green-50);
  border-color: var(--brass);
}
.btn:active {
  transform: translateY(1px);
}
.btn.primary {
  background: var(--green);
  color: var(--paper);
  border-color: var(--green);
}
.btn.primary:hover {
  background: var(--green-700);
}
.btn:focus-visible {
  outline: 2px solid var(--brass);
  outline-offset: 2px;
}

.txn-foot {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  background: rgba(232, 239, 234, 0.5);
  border-top: 1px solid var(--line);
  font-size: 12.5px;
  color: var(--ink-2);
}
.txn-foot .done-flag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 600;
  color: var(--ok);
}

.empty {
  margin: 48px auto 0;
  max-width: 40ch;
  text-align: center;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 22px;
  color: var(--green-700);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 16px);
  background: var(--green-d);
  color: var(--ivory);
  font-size: 13.5px;
  font-weight: 500;
  padding: 11px 20px;
  border-radius: 999px;
  box-shadow: var(--sh-3);
  border: 1px solid rgba(176, 141, 87, 0.5);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s, transform 0.25s;
  z-index: 60;
}
.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Responsive ---------- */
@media (max-width: 760px) {
  .topnav {
    display: none;
  }
}

@media (max-width: 520px) {
  .topbar {
    gap: 12px;
    padding: 12px 16px;
  }
  .agent-pill .agent-avatar {
    margin: 0;
  }
  .agent-pill {
    font-size: 0;
    padding: 4px;
    gap: 0;
  }
  .page-head {
    align-items: flex-start;
  }
  .summary {
    width: 100%;
  }
  .summary-stat {
    flex: 1;
    min-width: 0;
    padding: 12px 8px;
  }
  .board {
    grid-template-columns: 1fr;
  }
  .doc-actions {
    flex-wrap: wrap;
  }
  .toolbar {
    margin-top: 20px;
  }
}

