(function () {
  "use strict";

  // ---- Data: fictional transactions, each with a required-document checklist ----
  var STATUSES = {
    missing: { label: "Missing", cls: "s-missing" },
    pending: { label: "Pending Review", cls: "s-pending" },
    approved: { label: "Approved", cls: "s-approved" },
    expired: { label: "Expired", cls: "s-expired" }
  };

  var DOC_TEMPLATE = [
    { key: "listing", name: "Listing Agreement" },
    { key: "disclosures", name: "Seller Disclosures" },
    { key: "inspection", name: "Inspection Report" },
    { key: "appraisal", name: "Appraisal" },
    { key: "closing", name: "Closing Statement" }
  ];

  var transactions = [
    {
      id: "tx-1",
      address: "412 Juniper Hollow Rd",
      city: "Asheton Heights, CT",
      price: "$1.24M",
      tags: ["4 bd", "3 ba", "3,180 sqft"],
      label: "Under Contract",
      docs: [
        { key: "listing", status: "approved", due: "Closed 04/02" },
        { key: "disclosures", status: "approved", due: "Closed 04/05" },
        { key: "inspection", status: "pending", due: "Due Jun 11" },
        { key: "appraisal", status: "missing", due: "Due Jun 14" },
        { key: "closing", status: "missing", due: "Due Jun 27" }
      ]
    },
    {
      id: "tx-2",
      address: "88 Wren Court",
      city: "Lake Marlowe, CT",
      price: "$685K",
      tags: ["3 bd", "2 ba", "1,940 sqft"],
      label: "Active",
      docs: [
        { key: "listing", status: "approved", due: "Closed 05/19" },
        { key: "disclosures", status: "pending", due: "Due Jun 09" },
        { key: "inspection", status: "missing", due: "Due Jun 16" },
        { key: "appraisal", status: "missing", due: "Due Jun 21" },
        { key: "closing", status: "missing", due: "Due Jul 02" }
      ]
    },
    {
      id: "tx-3",
      address: "1207 Cedar Bluff Ave",
      city: "Harlow Park, CT",
      price: "$2.05M",
      tags: ["5 bd", "4 ba", "4,610 sqft"],
      label: "Closing Soon",
      docs: [
        { key: "listing", status: "approved", due: "Closed 03/28" },
        { key: "disclosures", status: "approved", due: "Closed 04/02" },
        { key: "inspection", status: "approved", due: "Closed 05/30" },
        { key: "appraisal", status: "expired", due: "Expired Jun 04" },
        { key: "closing", status: "pending", due: "Due Jun 10" }
      ]
    },
    {
      id: "tx-4",
      address: "26 Saffron Lane",
      city: "Edenfield, CT",
      price: "$540K",
      tags: ["2 bd", "2 ba", "1,310 sqft"],
      label: "Active",
      docs: [
        { key: "listing", status: "approved", due: "Closed 05/26" },
        { key: "disclosures", status: "approved", due: "Closed 05/29" },
        { key: "inspection", status: "approved", due: "Closed 06/03" },
        { key: "appraisal", status: "approved", due: "Closed 06/05" },
        { key: "closing", status: "approved", due: "Closed 06/06" }
      ]
    }
  ];

  var RING_C = 2 * Math.PI * 26; // r = 26
  var currentFilter = "all";

  var board = document.getElementById("board");
  var emptyState = document.getElementById("emptyState");
  var toolbarNote = document.getElementById("toolbarNote");
  var toastEl = document.getElementById("toast");
  var toastTimer;

  // ---- Helpers ----
  function docName(key) {
    for (var i = 0; i < DOC_TEMPLATE.length; i++) {
      if (DOC_TEMPLATE[i].key === key) return DOC_TEMPLATE[i].name;
    }
    return key;
  }

  function findTxn(id) {
    return transactions.filter(function (t) { return t.id === id; })[0];
  }

  function approvedCount(txn) {
    return txn.docs.filter(function (d) { return d.status === "approved"; }).length;
  }

  function isComplete(txn) {
    return approvedCount(txn) === txn.docs.length;
  }

  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2200);
  }

  // ---- Rendering ----
  function render() {
    board.innerHTML = "";
    var shown = 0;

    transactions.forEach(function (txn) {
      if (currentFilter === "incomplete" && isComplete(txn)) return;
      shown++;
      board.appendChild(buildCard(txn));
    });

    emptyState.hidden = shown > 0;
    updateSummary();
  }

  function buildCard(txn) {
    var done = approvedCount(txn);
    var total = txn.docs.length;
    var pct = Math.round((done / total) * 100);
    var complete = done === total;

    var card = document.createElement("article");
    card.className = "txn";
    card.setAttribute("aria-label", txn.address);

    var photo =
      '<div class="txn-photo">' +
        '<span class="price-badge">' + txn.price + "</span>" +
        '<span class="ph-label">' + txn.label + "</span>" +
      "</div>";

    var head =
      '<div class="txn-head">' +
        '<div class="txn-meta">' +
          "<h2>" + txn.address + "</h2>" +
          '<p class="txn-sub">' + txn.city + "</p>" +
          '<div class="tags">' +
            txn.tags.map(function (t) { return '<span class="tag">' + t + "</span>"; }).join("") +
          "</div>" +
        "</div>" +
        buildRing(txn.id, pct, complete) +
      "</div>";

    var list = document.createElement("ul");
    list.className = "docs";
    txn.docs.forEach(function (doc) {
      list.appendChild(buildDocRow(txn.id, doc));
    });

    var foot =
      '<div class="txn-foot">' +
        "<span>" + done + " of " + total + " documents approved</span>" +
        (complete
          ? '<span class="done-flag">✓ Compliant</span>'
          : '<span>' + (total - done) + ' outstanding</span>') +
      "</div>";

    card.innerHTML = photo + head;
    card.appendChild(list);
    card.insertAdjacentHTML("beforeend", foot);
    return card;
  }

  function buildRing(id, pct, complete) {
    var offset = RING_C * (1 - pct / 100);
    return (
      '<div class="ring' + (complete ? " is-complete" : "") + '" data-ring="' + id + '" ' +
        'role="img" aria-label="' + pct + ' percent compliant">' +
        '<svg viewBox="0 0 62 62" aria-hidden="true">' +
          '<circle class="track" cx="31" cy="31" r="26"></circle>' +
          '<circle class="bar" cx="31" cy="31" r="26" ' +
            'stroke-dasharray="' + RING_C.toFixed(1) + '" ' +
            'stroke-dashoffset="' + offset.toFixed(1) + '"></circle>' +
        "</svg>" +
        '<span class="ring-pct">' + pct + "%</span>" +
      "</div>"
    );
  }

  function buildDocRow(txnId, doc) {
    var meta = STATUSES[doc.status];
    var overdue = /Expired/.test(doc.due);

    var li = document.createElement("li");
    li.className = "doc";
    li.dataset.txn = txnId;
    li.dataset.doc = doc.key;

    li.innerHTML =
      '<span class="doc-name">' + docName(doc.key) + "</span>" +
      '<span class="status ' + meta.cls + '"><span class="dot" aria-hidden="true"></span>' + meta.label + "</span>" +
      '<span class="doc-due' + (overdue ? " is-overdue" : "") + '">' + doc.due + "</span>";

    var actions = document.createElement("div");
    actions.className = "doc-actions";

    if (doc.status === "missing" || doc.status === "expired") {
      actions.appendChild(makeBtn("Upload", "primary", function () {
        setStatus(txnId, doc.key, "pending", "Due Jun 30");
        toast(docName(doc.key) + " uploaded — sent for review.");
      }));
    } else if (doc.status === "pending") {
      actions.appendChild(makeBtn("Approve", "primary", function () {
        setStatus(txnId, doc.key, "approved", "Closed " + today());
        toast(docName(doc.key) + " approved.");
      }));
      actions.appendChild(makeBtn("Request changes", "", function () {
        setStatus(txnId, doc.key, "missing", "Re-upload required");
        toast("Changes requested on " + docName(doc.key) + ".");
      }));
    } else if (doc.status === "approved") {
      actions.appendChild(makeBtn("Mark expired", "", function () {
        setStatus(txnId, doc.key, "expired", "Expired " + today());
        toast(docName(doc.key) + " marked expired.");
      }));
    }

    li.appendChild(actions);
    return li;
  }

  function makeBtn(text, variant, onClick) {
    var b = document.createElement("button");
    b.className = "btn" + (variant ? " " + variant : "");
    b.type = "button";
    b.textContent = text;
    b.addEventListener("click", onClick);
    return b;
  }

  function today() {
    var d = new Date();
    var mm = String(d.getMonth() + 1).padStart(2, "0");
    var dd = String(d.getDate()).padStart(2, "0");
    return mm + "/" + dd;
  }

  // ---- State mutation ----
  function setStatus(txnId, docKey, status, due) {
    var txn = findTxn(txnId);
    if (!txn) return;
    txn.docs.forEach(function (d) {
      if (d.key === docKey) {
        d.status = status;
        if (due) d.due = due;
      }
    });
    render();
  }

  function updateSummary() {
    var approved = 0, pending = 0, open = 0;
    transactions.forEach(function (txn) {
      txn.docs.forEach(function (d) {
        if (d.status === "approved") approved++;
        else if (d.status === "pending") pending++;
        else open++; // missing or expired
      });
    });
    document.getElementById("statApproved").textContent = approved;
    document.getElementById("statPending").textContent = pending;
    document.getElementById("statOpen").textContent = open;
  }

  // ---- Filters ----
  var chips = document.querySelectorAll(".chip");
  chips.forEach(function (chip) {
    chip.addEventListener("click", function () {
      chips.forEach(function (c) {
        c.classList.remove("is-active");
        c.setAttribute("aria-pressed", "false");
      });
      chip.classList.add("is-active");
      chip.setAttribute("aria-pressed", "true");
      currentFilter = chip.dataset.filter;
      toolbarNote.textContent =
        currentFilter === "incomplete"
          ? "Showing transactions with outstanding documents."
          : "Showing all open transactions.";
      render();
    });
  });

  render();
})();

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

/* ── Layout ── */
.queue {
  max-width: 960px;
  margin: 0 auto;
  padding: 32px 20px 64px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ── Header ── */
.queue-head {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.head-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}
.eyebrow {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--teal-d);
}
.queue-head h1 {
  font-size: 1.6rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-top: 4px;
}
.pill-clock {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 7px 13px;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--ink-2);
  box-shadow: var(--shadow-1);
  white-space: nowrap;
}
.pill-clock .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 4px rgba(47, 158, 111, 0.16);
  animation: pulse 2s ease-in-out infinite;
}
@keyframes pulse {
  50% {
    box-shadow: 0 0 0 7px rgba(47, 158, 111, 0.04);
  }
}

/* ── Controls ── */
.controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
}
.search {
  position: relative;
  flex: 1;
  min-width: 240px;
}
.search-ico {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  fill: none;
  stroke: var(--muted);
  stroke-width: 2;
  stroke-linecap: round;
  pointer-events: none;
}
.search input {
  width: 100%;
  font: inherit;
  font-size: 0.92rem;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 11px 16px 11px 42px;
  box-shadow: var(--shadow-1);
  transition: border-color 0.15s, box-shadow 0.15s;
}
.search input::placeholder {
  color: var(--muted);
}
.search input:focus-visible {
  outline: none;
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(18, 156, 147, 0.18);
}

/* ── Tabs ── */
.tabs {
  display: inline-flex;
  gap: 4px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 4px;
  box-shadow: var(--shadow-1);
  flex-wrap: wrap;
}
.tab {
  border: none;
  background: transparent;
  border-radius: 999px;
  padding: 8px 15px;
  font: inherit;
  font-weight: 600;
  font-size: 0.86rem;
  color: var(--muted);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  transition: background 0.15s, color 0.15s;
}
.tab:hover {
  color: var(--ink-2);
}
.tab:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}
.tab.is-active {
  background: var(--teal-d);
  color: #fff;
}
.count {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--teal-50);
  color: var(--teal-d);
  font-size: 0.74rem;
  font-weight: 700;
}
.tab.is-active .count {
  background: rgba(255, 255, 255, 0.22);
  color: #fff;
}

/* ── Rows ── */
.rows {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.row {
  display: grid;
  grid-template-columns: 40px minmax(104px, 1.1fr) minmax(132px, 1.6fr) 56px minmax(104px, 1fr) auto auto;
  align-items: center;
  gap: 16px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 18px;
  box-shadow: var(--shadow-1);
  transition: border-color 0.15s, box-shadow 0.15s, opacity 0.25s, transform 0.12s;
}
.row > * { min-width: 0; }
.row .status, .row .row-action { min-width: max-content; }
.row:hover {
  border-color: var(--line-2);
  box-shadow: 0 2px 4px rgba(16, 50, 47, 0.05), 0 8px 22px rgba(16, 50, 47, 0.08);
}
.row[hidden] {
  display: none;
}
.row.is-dispensed {
  background: #fafdfc;
  box-shadow: none;
}
.row.just-advanced {
  animation: flash 0.6s ease;
}
@keyframes flash {
  0% {
    background: var(--teal-50);
  }
  100% {
    background: var(--white);
  }
}

.avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(150deg, var(--teal-50), #d9efec);
  color: var(--teal-700);
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.who .name,
.pres-name {
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--ink);
}
.sub {
  font-size: 0.78rem;
  color: var(--muted);
  margin-top: 2px;
}
.drug {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--ink);
}
.strength {
  font-weight: 700;
  color: var(--teal-d);
}
.qty {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}
.qty-num {
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--ink);
  line-height: 1;
}
.qty-unit {
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--muted);
  margin-top: 3px;
}
.prescriber .sub {
  margin-top: 0;
}
.prescriber .pres-name {
  font-size: 0.88rem;
  margin-top: 1px;
}

/* ── Status pill ── */
.status {
  justify-self: start;
  font-size: 0.74rem;
  font-weight: 700;
  padding: 5px 11px;
  border-radius: 999px;
  white-space: nowrap;
}
.status-verify {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.status-ready {
  background: rgba(18, 156, 147, 0.14);
  color: var(--teal-d);
}
.status-dispensed {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}

/* ── Action ── */
.row-action {
  justify-self: end;
}
.btn {
  border: none;
  border-radius: 10px;
  padding: 9px 16px;
  font: inherit;
  font-weight: 600;
  font-size: 0.84rem;
  cursor: pointer;
  white-space: nowrap;
  transition: transform 0.12s, background 0.15s, box-shadow 0.15s;
}
.btn:active {
  transform: translateY(1px);
}
.btn:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}
.btn-verify {
  background: var(--white);
  border: 1px solid var(--line-2);
  color: var(--warn);
}
.btn-verify:hover {
  background: rgba(217, 138, 43, 0.1);
  border-color: var(--warn);
}
.btn-dispense {
  background: var(--teal-d);
  color: #fff;
  box-shadow: 0 2px 8px rgba(12, 122, 115, 0.24);
}
.btn-dispense:hover {
  background: var(--teal-700);
}
.done-mark {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--ok);
  white-space: nowrap;
}
.done-mark svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: var(--ok);
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ── Empty ── */
.empty {
  text-align: center;
  color: var(--muted);
  font-size: 0.92rem;
  padding: 36px 0;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}

/* ── Responsive ── */
@media (max-width: 760px) {
  .row {
    grid-template-columns: 40px 1fr auto;
    grid-template-areas:
      "avatar who status"
      "avatar rx rx"
      "avatar meta action";
    row-gap: 10px;
    column-gap: 14px;
  }
  .avatar {
    grid-area: avatar;
    align-self: start;
  }
  .who {
    grid-area: who;
  }
  .rx {
    grid-area: rx;
  }
  .qty {
    grid-area: meta;
    flex-direction: row;
    align-items: baseline;
    gap: 6px;
  }
  .qty-unit {
    margin-top: 0;
  }
  .prescriber {
    display: none;
  }
  .status {
    grid-area: status;
    justify-self: end;
  }
  .row-action {
    grid-area: action;
    justify-self: end;
  }
}

@media (max-width: 520px) {
  .queue {
    padding: 24px 14px 56px;
  }
  .head-top {
    flex-direction: column;
  }
  .controls {
    flex-direction: column;
    align-items: stretch;
  }
  .tabs {
    justify-content: flex-start;
  }
  .tab {
    padding: 8px 12px;
    font-size: 0.82rem;
  }
}

