:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --pending: #6b7280;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

/* ── App bar ── */
.appbar {
  background: var(--white);
  border-bottom: 1px solid var(--line);
  padding: 14px 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 20;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--ink);
}
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: linear-gradient(150deg, var(--teal), var(--teal-d));
  color: #fff;
  font-size: 1.1rem;
  font-weight: 700;
}
.brand-name {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.brand-name em {
  font-style: normal;
  color: var(--teal-d);
}
.patient-chip {
  display: flex;
  align-items: center;
  gap: 11px;
  background: var(--teal-50);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 6px 14px 6px 6px;
}
.pc-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--teal-d);
  color: #fff;
  font-weight: 700;
  font-size: 0.78rem;
}
.pc-info {
  display: flex;
  flex-direction: column;
}
.pc-info strong {
  font-size: 0.88rem;
}
.pc-info small {
  color: var(--muted);
  font-size: 0.74rem;
}

/* ── Layout ── */
.pad {
  max-width: 1020px;
  margin: 0 auto;
  padding: 28px 28px 56px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  align-items: start;
}
.pane {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 22px 24px;
}
.pane-head {
  margin-bottom: 18px;
}
.preview-pane {
  display: flex;
  flex-direction: column;
}
.pane-head h1 {
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.sub {
  color: var(--muted);
  font-size: 0.9rem;
  margin-top: 3px;
}
.section-h {
  font-size: 1.02rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

/* ── Form ── */
.rx-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.field label {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--ink-2);
  letter-spacing: 0.01em;
}
.field input,
.field select,
.field textarea {
  font: inherit;
  font-size: 0.9rem;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 10px 12px;
  width: 100%;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.field textarea {
  resize: vertical;
  min-height: 56px;
}
.field input:focus,
.field select:focus,
.field textarea:focus {
  outline: none;
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(18, 156, 147, 0.16);
}
.field input.is-invalid,
.field select.is-invalid {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(212, 80, 62, 0.14);
}

/* ── Autocomplete ── */
.combo {
  position: relative;
}
.ac-list {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  list-style: none;
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  box-shadow: var(--shadow-2);
  max-height: 232px;
  overflow-y: auto;
  z-index: 30;
  padding: 4px;
}
.ac-item {
  padding: 9px 11px;
  border-radius: 6px;
  font-size: 0.88rem;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  gap: 10px;
}
.ac-item .ac-cat {
  color: var(--muted);
  font-size: 0.76rem;
}
.ac-item:hover,
.ac-item.is-active {
  background: var(--teal-50);
  color: var(--teal-700);
}
.ac-item mark {
  background: var(--coral-soft);
  color: var(--ink);
  border-radius: 3px;
  padding: 0 1px;
}
.ac-empty {
  padding: 11px;
  font-size: 0.84rem;
  color: var(--muted);
  text-align: center;
}

/* ── Checkbox ── */
.check {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--ink-2);
  cursor: pointer;
}
.check input {
  width: 17px;
  height: 17px;
  accent-color: var(--teal);
  cursor: pointer;
}

/* ── Buttons ── */
.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 2px;
}
.btn {
  border: none;
  border-radius: 11px;
  padding: 11px 18px;
  font: inherit;
  font-weight: 600;
  font-size: 0.9rem;
  cursor: pointer;
  transition: transform 0.12s, background 0.15s, opacity 0.15s;
}
.btn:active {
  transform: translateY(1px);
}
.btn.primary {
  background: var(--coral);
  color: #fff;
}
.btn.primary:hover {
  background: #ff8e7c;
}
.btn.ghost {
  background: var(--teal-50);
  color: var(--teal-700);
}
.btn.ghost:hover {
  background: #d7ece9;
}
.btn.send {
  width: 100%;
  margin-top: 14px;
  background: var(--teal-d);
  color: #fff;
}
.btn.send:hover:not(:disabled) {
  background: var(--teal-700);
}
.btn.send:disabled {
  background: var(--line-2);
  color: var(--white);
  cursor: not-allowed;
}

/* ── Rx preview card ── */
.rx-card {
  border: 1px solid var(--line-2);
  border-radius: var(--r-md);
  padding: 20px 22px;
  background: linear-gradient(180deg, #fbfefd, var(--white));
  box-shadow: var(--shadow-1);
}
.rx-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  border-bottom: 1px solid var(--line);
  padding-bottom: 12px;
}
.rx-clinic {
  font-weight: 700;
  font-size: 0.98rem;
  color: var(--teal-700);
}
.rx-clinic-meta {
  font-size: 0.76rem;
  color: var(--muted);
  margin-top: 2px;
}
.rx-sym {
  font-size: 2rem;
  font-weight: 700;
  line-height: 1;
  color: var(--teal-d);
}
.rx-patient {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 0.82rem;
  color: var(--ink-2);
  font-weight: 600;
  padding: 12px 0;
  border-bottom: 1px dashed var(--line);
}
.rx-body {
  padding: 14px 0;
  min-height: 110px;
}
.rx-drug {
  font-size: 1.18rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: var(--ink);
}
.rx-sig {
  margin-top: 8px;
  font-size: 0.92rem;
  color: var(--ink-2);
  line-height: 1.55;
}
.rx-notes {
  margin-top: 8px;
  font-size: 0.84rem;
  color: var(--muted);
  font-style: italic;
}
.rx-meta {
  display: flex;
  gap: 22px;
  margin-top: 14px;
  font-size: 0.84rem;
  color: var(--ink-2);
}
.rx-meta strong {
  color: var(--ink);
}
.rx-foot {
  border-top: 1px solid var(--line);
  padding-top: 12px;
}
.rx-signline {
  display: block;
  font-family: "Inter", cursive;
  font-weight: 700;
  font-size: 0.98rem;
  color: var(--teal-700);
  border-bottom: 1.5px solid var(--line-2);
  padding-bottom: 4px;
  margin-bottom: 5px;
  width: 60%;
}
.rx-sign small {
  font-size: 0.74rem;
  color: var(--muted);
}

/* ── Prescription list ── */
.list-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 22px 0 12px;
}
.count-pill {
  font-size: 0.74rem;
  font-weight: 700;
  color: var(--teal-700);
  background: var(--teal-50);
  border-radius: 999px;
  padding: 4px 11px;
}
.rx-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.rx-list .empty {
  text-align: center;
  color: var(--muted);
  font-size: 0.86rem;
  padding: 18px 0;
  border: 1px dashed var(--line-2);
  border-radius: var(--r-sm);
}
.rx-item {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  padding: 11px 13px;
  background: var(--white);
}
.li-name {
  font-weight: 700;
  font-size: 0.9rem;
}
.li-sig {
  font-size: 0.79rem;
  color: var(--muted);
  margin-top: 2px;
}
.remove-btn {
  border: none;
  background: transparent;
  color: var(--muted);
  font-size: 1rem;
  line-height: 1;
  cursor: pointer;
  border-radius: 6px;
  padding: 4px 7px;
  transition: background 0.15s, color 0.15s;
}
.remove-btn:hover {
  background: var(--coral-soft);
  color: var(--danger);
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}
.toast.is-error {
  background: var(--danger);
}

@media (max-width: 820px) {
  .pad {
    grid-template-columns: 1fr;
  }
  .patient-chip .pc-info {
    display: none;
  }
}

