// ── Medication formulary (illustrative) ──────────────────────────────────────
const DRUGS = [
  { name: "Amoxicillin 500mg", cat: "Antibiotic" },
  { name: "Atorvastatin 20mg", cat: "Statin" },
  { name: "Lisinopril 10mg", cat: "ACE inhibitor" },
  { name: "Metformin 500mg", cat: "Antidiabetic" },
  { name: "Omeprazole 20mg", cat: "PPI" },
  { name: "Ibuprofen 400mg", cat: "NSAID" },
  { name: "Amlodipine 5mg", cat: "Calcium blocker" },
  { name: "Sertraline 50mg", cat: "SSRI" },
  { name: "Levothyroxine 50mcg", cat: "Thyroid" },
  { name: "Salbutamol inhaler", cat: "Bronchodilator" },
];

// ── Element refs ──────────────────────────────────────────────────────────────
const $ = (id) => document.getElementById(id);
const form = $("rxForm");
const drugInput = $("drug");
const acList = $("acList");
const fields = {
  dose: $("dose"),
  route: $("route"),
  frequency: $("frequency"),
  duration: $("duration"),
  quantity: $("quantity"),
  refills: $("refills"),
  prn: $("prn"),
  notes: $("notes"),
};
const pv = {
  drug: $("pvDrug"),
  sig: $("pvSig"),
  notes: $("pvNotes"),
  qty: $("pvQty"),
  refills: $("pvRefills"),
};
const rxList = $("rxList");
const emptyState = $("emptyState");
const countPill = $("countPill");
const sendBtn = $("sendBtn");
const toast = $("toast");

let prescriptions = [];
let activeIndex = -1;

// ── Toast ─────────────────────────────────────────────────────────────────────
function showToast(msg, isError) {
  toast.textContent = msg;
  toast.classList.toggle("is-error", Boolean(isError));
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2800);
}

// ── Sig assembly ──────────────────────────────────────────────────────────────
function buildSig() {
  const parts = [];
  if (fields.dose.value.trim()) parts.push(fields.dose.value.trim());
  if (fields.route.value) parts.push(fields.route.value.toLowerCase());
  if (fields.frequency.value) parts.push(fields.frequency.value.toLowerCase());
  if (fields.prn.checked) parts.push("as needed (PRN)");
  if (fields.duration.value.trim()) parts.push(`for ${fields.duration.value.trim()}`);
  return parts.length
    ? `Sig: ${parts.join(" · ")}`
    : "Sig: complete the fields to assemble instructions.";
}

function renderPreview() {
  pv.drug.textContent = drugInput.value.trim() || "—";
  pv.sig.textContent = buildSig();
  pv.qty.textContent = fields.quantity.value || "0";
  pv.refills.textContent = fields.refills.value || "0";
  const note = fields.notes.value.trim();
  pv.notes.textContent = note;
  pv.notes.hidden = !note;
}

// ── Autocomplete ──────────────────────────────────────────────────────────────
function highlight(name, q) {
  const i = name.toLowerCase().indexOf(q.toLowerCase());
  if (i < 0) return name;
  return `${name.slice(0, i)}<mark>${name.slice(i, i + q.length)}</mark>${name.slice(i + q.length)}`;
}

function closeList() {
  acList.hidden = true;
  acList.innerHTML = "";
  activeIndex = -1;
  drugInput.setAttribute("aria-expanded", "false");
}

function openList() {
  const q = drugInput.value.trim();
  if (!q) return closeList();
  const matches = DRUGS.filter((d) => d.name.toLowerCase().includes(q.toLowerCase()));
  activeIndex = -1;
  acList.innerHTML = matches.length
    ? matches
        .map(
          (d) =>
            `<li class="ac-item" role="option" data-name="${d.name}"><span>${highlight(d.name, q)}</span><span class="ac-cat">${d.cat}</span></li>`
        )
        .join("")
    : `<li class="ac-empty">No matching medication</li>`;
  acList.hidden = false;
  drugInput.setAttribute("aria-expanded", "true");
}

function selectDrug(name) {
  drugInput.value = name;
  closeList();
  renderPreview();
  fields.dose.focus();
}

drugInput.addEventListener("input", () => {
  openList();
  renderPreview();
});
drugInput.addEventListener("focus", openList);

drugInput.addEventListener("keydown", (e) => {
  const items = [...acList.querySelectorAll(".ac-item")];
  if (!items.length) return;
  if (e.key === "ArrowDown" || e.key === "ArrowUp") {
    e.preventDefault();
    activeIndex += e.key === "ArrowDown" ? 1 : -1;
    if (activeIndex < 0) activeIndex = items.length - 1;
    if (activeIndex >= items.length) activeIndex = 0;
    items.forEach((it, i) => it.classList.toggle("is-active", i === activeIndex));
    items[activeIndex].scrollIntoView({ block: "nearest" });
  } else if (e.key === "Enter" && activeIndex > -1) {
    e.preventDefault();
    selectDrug(items[activeIndex].dataset.name);
  } else if (e.key === "Escape") {
    closeList();
  }
});

acList.addEventListener("mousedown", (e) => {
  const item = e.target.closest(".ac-item");
  if (item) {
    e.preventDefault();
    selectDrug(item.dataset.name);
  }
});

document.addEventListener("click", (e) => {
  if (!e.target.closest(".combo")) closeList();
});

// ── Live preview on any field change ──────────────────────────────────────────
form.addEventListener("input", renderPreview);
form.addEventListener("change", renderPreview);

// ── List rendering ────────────────────────────────────────────────────────────
function refreshList() {
  countPill.textContent = `${prescriptions.length} item${prescriptions.length === 1 ? "" : "s"}`;
  sendBtn.disabled = prescriptions.length === 0;
  emptyState.hidden = prescriptions.length > 0;
  rxList.querySelectorAll(".rx-item").forEach((n) => n.remove());
  prescriptions.forEach((rx, i) => {
    const li = document.createElement("li");
    li.className = "rx-item";
    const sig = rx.sig.replace(/^Sig:\s*/, "");
    li.innerHTML =
      `<div><p class="li-name">${rx.drug}</p><p class="li-sig">${sig}</p></div>` +
      `<button class="remove-btn" data-i="${i}" aria-label="Remove ${rx.drug}">✕</button>`;
    rxList.appendChild(li);
  });
}

rxList.addEventListener("click", (e) => {
  const btn = e.target.closest(".remove-btn");
  if (!btn) return;
  const removed = prescriptions.splice(Number(btn.dataset.i), 1)[0];
  refreshList();
  showToast(`Removed ${removed.drug} from the list.`);
});

// ── Add / submit ──────────────────────────────────────────────────────────────
form.addEventListener("submit", (e) => {
  e.preventDefault();
  drugInput.classList.remove("is-invalid");
  fields.frequency.classList.remove("is-invalid");
  if (!drugInput.value.trim()) {
    drugInput.classList.add("is-invalid");
    drugInput.focus();
    return showToast("Select or enter a medication first.", true);
  }
  if (!fields.frequency.value) {
    fields.frequency.classList.add("is-invalid");
    fields.frequency.focus();
    return showToast("Choose a frequency before adding.", true);
  }
  prescriptions.push({ drug: drugInput.value.trim(), sig: buildSig() });
  refreshList();
  showToast(`Added ${drugInput.value.trim()} to the prescription.`);
  form.reset();
  renderPreview();
});

form.addEventListener("reset", () => {
  drugInput.classList.remove("is-invalid");
  fields.frequency.classList.remove("is-invalid");
  setTimeout(renderPreview, 0);
});

// ── Send all ──────────────────────────────────────────────────────────────────
sendBtn.addEventListener("click", () => {
  if (!prescriptions.length) return;
  const n = prescriptions.length;
  prescriptions = [];
  refreshList();
  showToast(`Sent ${n} prescription${n === 1 ? "" : "s"} to the pharmacy.`);
});

renderPreview();
refreshList();

snippets.css:
:root {
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --sh-sm: 0 1px 2px rgba(28, 24, 20, 0.05), 0 1px 3px rgba(28, 24, 20, 0.04);
  --sh-md: 0 6px 22px rgba(28, 24, 20, 0.07), 0 2px 6px rgba(28, 24, 20, 0.05);
  --sh-lg: 0 18px 50px rgba(28, 24, 20, 0.12);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-size: 15px;
}

h1, h2, h3 { font-family: var(--serif); font-weight: 600; margin: 0; line-height: 1.12; letter-spacing: 0.01em; }

.eyebrow {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--gold-d);
}

.portal {
  max-width: 1120px;
  margin: 0 auto;
  padding: 36px 24px 80px;
}

/* ===== Hero ===== */
.hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 32px;
  flex-wrap: wrap;
  padding-bottom: 30px;
  border-bottom: 1px solid var(--line);
}

.hero__brand { display: flex; gap: 18px; align-items: center; }

.hero__mark {
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  flex: none;
  border-radius: 50%;
  background: linear-gradient(150deg, var(--gold) 0%, var(--gold-d) 100%);
  color: var(--white);
  font-family: var(--serif);
  font-weight: 700;
  font-size: 20px;
  letter-spacing: 0.04em;
  box-shadow: var(--sh-md);
}

.hero__greet { font-size: 34px; margin-top: 6px; color: var(--ink); }
.hero__greet span { font-style: italic; color: var(--gold-d); }
.hero__sub { margin: 6px 0 0; color: var(--muted); font-size: 14px; }
.hero__sub strong { color: var(--ink-2); }

.hero__loyalty { flex: none; }

.loyalty {
  display: grid;
  gap: 5px;
  min-width: 250px;
  padding: 18px 22px;
  background: var(--white);
  border: 1px solid var(--gold-soft);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-md);
}

.loyalty__label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gold-d);
}

.loyalty__pts { font-family: var(--serif); font-size: 28px; color: var(--ink); line-height: 1; }
.loyalty__pts strong { font-weight: 700; }
.loyalty__tier { font-size: 12px; color: var(--muted); }

.loyalty__bar {
  margin-top: 7px;
  height: 6px;
  border-radius: 99px;
  background: var(--rose-soft);
  overflow: hidden;
}
.loyalty__bar i {
  display: block;
  height: 100%;
  width: var(--w, 0%);
  border-radius: 99px;
  background: linear-gradient(90deg, var(--rose), var(--gold));
}

/* ===== Stats ===== */
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin: 26px 0 8px;
}
.stat {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 18px;
  box-shadow: var(--sh-sm);
}
.stat b { display: block; font-family: var(--serif); font-size: 26px; color: var(--ink); line-height: 1; }
.stat span { font-size: 12px; color: var(--muted); letter-spacing: 0.02em; }

/* ===== Tabs ===== */
.tabs {
  display: flex;
  gap: 6px;
  margin: 28px 0 22px;
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}
.tab {
  appearance: none;
  border: 0;
  background: none;
  font-family: var(--sans);
  font-size: 14px;
  font-weight: 600;
  color: var(--muted);
  padding: 11px 16px;
  cursor: pointer;
  position: relative;
  border-radius: var(--r-sm) var(--r-sm) 0 0;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: color 0.18s ease;
}
.tab:hover { color: var(--ink-2); }
.tab.is-active { color: var(--ink); }
.tab.is-active::after {
  content: "";
  position: absolute;
  left: 12px; right: 12px; bottom: -1px;
  height: 2px;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--gold), var(--gold-d));
}
.tab:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.tab__count {
  font-size: 11px;
  font-weight: 700;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  display: inline-grid;
  place-items: center;
  border-radius: 99px;
  background: var(--gold-soft);
  color: var(--gold-d);
}

/* ===== Layout ===== */
.layout {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 30px;
  align-items: start;
}

.panel { animation: rise 0.32s ease; }
.panel[hidden] { display: none; }
@keyframes rise {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: none; }
}

/* ===== Upcoming cards ===== */
.cards { display: grid; gap: 16px; }

.appt {
  position: relative;
  display: grid;
  grid-template-columns: 78px 1fr auto;
  gap: 18px;
  align-items: center;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 18px 20px;
  box-shadow: var(--sh-sm);
  transition: box-shadow 0.2s ease, transform 0.2s ease, border-color 0.2s ease;
}
.appt:hover { box-shadow: var(--sh-md); transform: translateY(-2px); border-color: var(--gold-soft); }
.appt::before {
  content: "";
  position: absolute;
  left: 0; top: 16px; bottom: 16px;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: linear-gradient(var(--rose), var(--gold));
}

.datechip {
  text-align: center;
  border-radius: var(--r-md);
  background: var(--cream);
  border: 1px solid var(--gold-soft);
  padding: 10px 8px;
}
.datechip .m { font-size: 11px; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: var(--gold-d); }
.datechip .d { font-family: var(--serif); font-size: 26px; font-weight: 600; color: var(--ink); line-height: 1; }
.datechip .t { font-size: 11px; color: var(--muted); margin-top: 2px; }

.appt__svc { font-family: var(--serif); font-size: 21px; color: var(--ink); }
.appt__meta { font-size: 13px; color: var(--muted); margin-top: 3px; }
.appt__meta b { color: var(--ink-2); font-weight: 600; }
.appt__tags { display: flex; gap: 7px; margin-top: 9px; flex-wrap: wrap; }
.pill {
  font-size: 11px;
  font-weight: 600;
  padding: 3px 9px;
  border-radius: 99px;
  background: var(--rose-soft);
  color: var(--gold-d);
  letter-spacing: 0.02em;
}
.pill--soft { background: var(--cream); color: var(--ink-2); }

.appt__actions { display: flex; flex-direction: column; gap: 8px; }

/* Buttons */
.btn {
  appearance: none;
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 600;
  border-radius: 99px;
  padding: 8px 16px;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.16s ease, color 0.16s ease, border-color 0.16s ease, transform 0.08s ease;
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink);
}
.btn:hover { border-color: var(--gold); color: var(--gold-d); }
.btn:active { transform: translateY(1px); }
.btn:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.btn--gold { background: linear-gradient(150deg, var(--gold), var(--gold-d)); color: var(--white); border-color: transparent; }
.btn--gold:hover { color: var(--white); filter: brightness(1.06); }
.btn--ghost { border-color: transparent; background: transparent; color: var(--muted); padding-inline: 12px; }
.btn--ghost:hover { color: var(--danger); background: rgba(179, 80, 62, 0.07); }
.btn--sm { padding: 6px 13px; font-size: 12px; }

/* Inline confirm */
.confirm {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
  margin-top: 4px;
  padding: 13px 16px;
  border-radius: var(--r-md);
  background: rgba(179, 80, 62, 0.06);
  border: 1px solid rgba(179, 80, 62, 0.22);
  animation: rise 0.2s ease;
}
.confirm p { margin: 0; font-size: 13px; color: var(--ink-2); }
.confirm__btns { display: flex; gap: 8px; }
.btn--danger { background: var(--danger); color: var(--white); border-color: transparent; }
.btn--danger:hover { color: var(--white); filter: brightness(1.05); }

.appt.is-cancelled { opacity: 0.55; }
.appt.is-cancelled .appt__svc { text-decoration: line-through; text-decoration-color: var(--line-2); }

/* ===== Past visits rows ===== */
.filterbar { margin-bottom: 16px; }
.srch {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 99px;
  padding: 9px 16px;
  box-shadow: var(--sh-sm);
}
.srch:focus-within { border-color: var(--gold); }
.srch svg { width: 16px; height: 16px; flex: none; fill: none; stroke: var(--muted); stroke-width: 2; stroke-linecap: round; }
.srch input { border: 0; background: none; outline: none; font: inherit; font-size: 14px; width: 100%; color: var(--ink); }
.srch input::placeholder { color: var(--muted); }

.rows { display: grid; gap: 10px; }
.row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 16px;
  align-items: center;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 18px;
  box-shadow: var(--sh-sm);
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}
.row:hover { border-color: var(--gold-soft); box-shadow: var(--sh-md); }
.row__date {
  font-size: 12px;
  font-weight: 600;
  color: var(--gold-d);
  letter-spacing: 0.04em;
  min-width: 64px;
}
.row__svc { font-family: var(--serif); font-size: 18px; color: var(--ink); }
.row__meta { font-size: 12.5px; color: var(--muted); margin-top: 1px; }
.row__right { display: flex; align-items: center; gap: 14px; }
.row__price { font-family: var(--serif); font-size: 18px; color: var(--ink-2); }

/* ===== Favorites ===== */
.grp {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-d);
  font-family: var(--sans);
  margin: 4px 0 14px;
}
.grp:not(:first-child) { margin-top: 30px; }

.fav-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 14px; }
.fav-grid--people { grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); }

.fav {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 18px;
  box-shadow: var(--sh-sm);
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}
.fav:hover { border-color: var(--gold-soft); box-shadow: var(--sh-md); }
.fav__head { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }
.fav__name { font-family: var(--serif); font-size: 19px; color: var(--ink); }
.fav__sub { font-size: 12.5px; color: var(--muted); margin-top: 2px; }
.fav__price { font-family: var(--serif); font-size: 17px; color: var(--gold-d); }

.fav .person { display: flex; align-items: center; gap: 12px; }
.avatar {
  width: 44px; height: 44px; flex: none;
  border-radius: 50%;
  display: grid; place-items: center;
  font-family: var(--serif); font-weight: 600; font-size: 17px;
  color: var(--white);
  background: linear-gradient(150deg, var(--rose), var(--gold-d));
}

.heart {
  appearance: none;
  border: 0;
  background: none;
  cursor: pointer;
  width: 30px; height: 30px;
  display: grid; place-items: center;
  border-radius: 50%;
  color: var(--gold);
  transition: background 0.16s ease, transform 0.12s ease;
}
.heart:hover { background: var(--rose-soft); }
.heart:active { transform: scale(0.88); }
.heart:focus-visible { outline: 2px solid var(--gold); outline-offset: 1px; }
.heart svg { width: 18px; height: 18px; }
.heart[aria-pressed="true"] svg { fill: var(--gold); stroke: var(--gold); }
.heart[aria-pressed="false"] svg { fill: none; stroke: var(--muted); }

/* ===== Rail ===== */
.rail { display: grid; gap: 18px; position: sticky; top: 24px; }
.rec, .note {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px;
  box-shadow: var(--sh-sm);
}
.rec { background: linear-gradient(180deg, var(--cream), var(--white)); border-color: var(--gold-soft); }
.rec__title { font-size: 22px; margin: 6px 0 14px; color: var(--ink); }
.rec__list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }
.rec__item { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding-bottom: 12px; border-bottom: 1px solid var(--line); }
.rec__item:last-child { border-bottom: 0; padding-bottom: 0; }
.rec__svc { font-weight: 600; font-size: 14px; color: var(--ink); }
.rec__why { font-size: 12px; color: var(--muted); margin-top: 1px; }
.rec__add { flex: none; }

.note__body { font-size: 14px; color: var(--ink-2); margin: 8px 0 0; line-height: 1.6; }
.note__body em { color: var(--gold-d); font-style: italic; }

.empty {
  text-align: center;
  color: var(--muted);
  font-size: 14px;
  padding: 40px 20px;
  border: 1px dashed var(--line-2);
  border-radius: var(--r-md);
}

/* ===== Toast ===== */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 24px);
  background: var(--ink);
  color: var(--cream);
  font-size: 13.5px;
  font-weight: 500;
  padding: 12px 20px;
  border-radius: 99px;
  box-shadow: var(--sh-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  z-index: 50;
  max-width: calc(100vw - 32px);
}
.toast.is-show { opacity: 1; transform: translate(-50%, 0); }
.toast::before { content: "✦"; color: var(--gold); margin-right: 8px; }

/* ===== Responsive ===== */
@media (max-width: 860px) {
  .layout { grid-template-columns: 1fr; }
  .rail { position: static; grid-template-columns: 1fr 1fr; }
}
@media (max-width: 640px) {
  .rail { grid-template-columns: 1fr; }
}
@media (max-width: 520px) {
  .portal { padding: 24px 16px 64px; }
  .hero { gap: 22px; }
  .hero__greet { font-size: 28px; }
  .hero__loyalty, .loyalty { width: 100%; min-width: 0; }
  .stats { grid-template-columns: 1fr 1fr; }
  .appt { grid-template-columns: 60px 1fr; }
  .appt__actions { grid-column: 1 / -1; flex-direction: row; flex-wrap: wrap; }
  .row { grid-template-columns: 1fr; gap: 8px; }
  .row__right { justify-content: space-between; }
  .tab { padding: 10px 12px; font-size: 13px; }
}

