(function () {
  "use strict";

  /* ----- Data ----- */
  var upcoming = [
    {
      id: "u1", month: "Jun", day: "11", time: "4:30 PM", weekday: "Thursday",
      service: "Balayage + Gloss", stylist: "Aria Vance",
      duration: "2h 15m", price: 245, tags: ["Colour", "Confirmed"],
    },
    {
      id: "u2", month: "Jun", day: "27", time: "11:00 AM", weekday: "Saturday",
      service: "Silk Press & Trim", stylist: "Noor Halabi",
      duration: "1h 30m", price: 120, tags: ["Styling", "Confirmed"],
    },
  ];

  var past = [
    { id: "p1", date: "May 22", service: "Root Touch-Up", stylist: "Aria Vance", price: 95, dur: "1h" },
    { id: "p2", date: "Apr 30", service: "Hydrating Mask Treatment", stylist: "Noor Halabi", price: 65, dur: "45m" },
    { id: "p3", date: "Apr 09", service: "Balayage + Gloss", stylist: "Aria Vance", price: 245, dur: "2h 15m" },
    { id: "p4", date: "Mar 18", service: "Cut & Blow-Dry", stylist: "Léa Moreau", price: 85, dur: "1h" },
    { id: "p5", date: "Feb 27", service: "Keratin Smoothing", stylist: "Noor Halabi", price: 210, dur: "2h 30m" },
    { id: "p6", date: "Feb 06", service: "Silk Press & Trim", stylist: "Noor Halabi", price: 120, dur: "1h 30m" },
    { id: "p7", date: "Jan 15", service: "Brow Shape & Tint", stylist: "Léa Moreau", price: 48, dur: "30m" },
  ];

  var favServices = [
    { id: "fs1", name: "Balayage + Gloss", sub: "Signature colour · 2h 15m", price: 245, saved: true },
    { id: "fs2", name: "Hydrating Mask", sub: "Treatment · 45m", price: 65, saved: true },
    { id: "fs3", name: "Cut & Blow-Dry", sub: "Styling · 1h", price: 85, saved: true },
  ];

  var favStylists = [
    { id: "ft1", name: "Aria Vance", sub: "Colour Director", initials: "AV", saved: true },
    { id: "ft2", name: "Noor Halabi", sub: "Senior Stylist", initials: "NH", saved: true },
  ];

  var recommends = [
    { svc: "Bond-Repair Add-On", why: "Pairs with your balayage", price: 35 },
    { svc: "Scalp Detox Ritual", why: "You're due — last one in March", price: 55 },
    { svc: "Glaze Refresh", why: "Keeps tone bright between visits", price: 45 },
  ];

  /* ----- Helpers ----- */
  var $ = function (s, r) { return (r || document).querySelector(s); };
  var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };
  var esc = function (v) {
    return String(v).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  };

  var toastEl = $("#toast");
  var toastTimer;
  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add("is-show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { toastEl.classList.remove("is-show"); }, 2600);
  }

  /* ----- Live counts ----- */
  function refreshCounts() {
    var up = upcoming.filter(function (a) { return !a.cancelled; }).length;
    var fv = favServices.filter(function (f) { return f.saved; }).length +
             favStylists.filter(function (f) { return f.saved; }).length;
    $("#countUpcoming").textContent = up;
    $("#countPast").textContent = past.length;
    $("#countFavs").textContent = fv;
    $("#statUpcoming").textContent = up;
    $("#statPast").textContent = past.length;
    $("#statFavs").textContent = fv;
  }

  /* ----- Tabs ----- */
  $$(".tab").forEach(function (tab) {
    tab.addEventListener("click", function () {
      $$(".tab").forEach(function (t) {
        var on = t === tab;
        t.classList.toggle("is-active", on);
        t.setAttribute("aria-selected", on ? "true" : "false");
      });
      $$(".panel").forEach(function (p) {
        var on = p.id === "panel-" + tab.dataset.tab;
        p.classList.toggle("is-active", on);
        p.hidden = !on;
      });
    });
  });

  /* ----- Render upcoming ----- */
  function renderUpcoming() {
    var list = $("#upcomingList");
    var active = upcoming.filter(function (a) { return !a.cancelled; });
    $("#upcomingEmpty").hidden = active.length !== 0;

    list.innerHTML = upcoming.map(function (a) {
      var tags = a.tags.map(function (t, i) {
        return '<span class="pill' + (i ? " pill--soft" : "") + '">' + esc(t) + "</span>";
      }).join("");
      return '' +
        '<article class="appt' + (a.cancelled ? " is-cancelled" : "") + '" data-id="' + a.id + '">' +
          '<div class="datechip">' +
            '<div class="m">' + esc(a.month) + '</div>' +
            '<div class="d">' + esc(a.day) + '</div>' +
            '<div class="t">' + esc(a.time) + '</div>' +
          '</div>' +
          '<div class="appt__body">' +
            '<div class="appt__svc">' + esc(a.service) + '</div>' +
            '<div class="appt__meta">' + esc(a.weekday) + ' · with <b>' + esc(a.stylist) + '</b> · ' + esc(a.duration) + '</div>' +
            '<div class="appt__tags">' + tags + '</div>' +
          '</div>' +
          (a.cancelled
            ? '<div class="appt__actions"><span class="pill pill--soft">Cancelled</span></div>'
            : '<div class="appt__actions">' +
                '<button class="btn btn--sm" data-act="reschedule">Reschedule</button>' +
                '<button class="btn btn--ghost btn--sm" data-act="cancel">Cancel</button>' +
              '</div>') +
        '</article>';
    }).join("");
  }

  // delegated actions for upcoming
  $("#upcomingList").addEventListener("click", function (e) {
    var btn = e.target.closest("button[data-act]");
    if (!btn) return;
    var card = btn.closest(".appt");
    var id = card.dataset.id;
    var appt = upcoming.find(function (a) { return a.id === id; });
    if (!appt) return;

    if (btn.dataset.act === "reschedule") {
      toast("Reschedule link sent for " + appt.service + ".");
      return;
    }

    if (btn.dataset.act === "cancel") {
      if ($(".confirm", card)) return;
      var c = document.createElement("div");
      c.className = "confirm";
      c.innerHTML =
        '<p>Cancel <strong>' + esc(appt.service) + '</strong> on ' + esc(appt.month) + " " + esc(appt.day) + '?</p>' +
        '<div class="confirm__btns">' +
          '<button class="btn btn--sm" data-confirm="no">Keep it</button>' +
          '<button class="btn btn--danger btn--sm" data-confirm="yes">Yes, cancel</button>' +
        '</div>';
      card.appendChild(c);
      $('[data-confirm="yes"]', c).focus();

      c.addEventListener("click", function (ev) {
        var cb = ev.target.closest("button[data-confirm]");
        if (!cb) return;
        if (cb.dataset.confirm === "yes") {
          appt.cancelled = true;
          renderUpcoming();
          refreshCounts();
          toast(appt.service + " cancelled. We hope to see you soon.");
        } else {
          c.remove();
        }
      });
    }
  });

  /* ----- Render past ----- */
  function renderPast(filter) {
    var q = (filter || "").trim().toLowerCase();
    var rows = past.filter(function (p) {
      return !q || p.service.toLowerCase().indexOf(q) > -1 || p.stylist.toLowerCase().indexOf(q) > -1;
    });
    $("#pastEmpty").hidden = rows.length !== 0;
    $("#pastList").innerHTML = rows.map(function (p) {
      return '' +
        '<div class="row" data-id="' + p.id + '">' +
          '<div class="row__date">' + esc(p.date) + '</div>' +
          '<div>' +
            '<div class="row__svc">' + esc(p.service) + '</div>' +
            '<div class="row__meta">with ' + esc(p.stylist) + ' · ' + esc(p.dur) + '</div>' +
          '</div>' +
          '<div class="row__right">' +
            '<span class="row__price">$' + p.price + '</span>' +
            '<button class="btn btn--gold btn--sm" data-rebook="' + p.id + '">Rebook</button>' +
          '</div>' +
        '</div>';
    }).join("");
  }

  $("#pastList").addEventListener("click", function (e) {
    var btn = e.target.closest("button[data-rebook]");
    if (!btn) return;
    var p = past.find(function (x) { return x.id === btn.dataset.rebook; });
    if (!p) return;
    toast("Rebooking " + p.service + " with " + p.stylist + " — details pre-filled.");
  });

  $("#pastSearch").addEventListener("input", function (e) {
    renderPast(e.target.value);
  });

  /* ----- Render favorites ----- */
  function heartSvg() {
    return '<svg viewBox="0 0 24 24" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
      '<path d="M12 20.5 4.4 13a4.6 4.6 0 1 1 6.5-6.5l1.1 1.1 1.1-1.1A4.6 4.6 0 1 1 19.6 13z"/></svg>';
  }

  function renderFavServices() {
    $("#favServices").innerHTML = favServices.map(function (f) {
      return '' +
        '<div class="fav" data-id="' + f.id + '">' +
          '<div class="fav__head">' +
            '<div><div class="fav__name">' + esc(f.name) + '</div><div class="fav__sub">' + esc(f.sub) + '</div></div>' +
            '<button class="heart" data-fav="service" aria-pressed="' + (f.saved ? "true" : "false") +
              '" aria-label="' + (f.saved ? "Remove" : "Save") + " " + esc(f.name) + '">' + heartSvg() + '</button>' +
          '</div>' +
          '<div class="fav__head" style="align-items:center">' +
            '<span class="fav__price">$' + f.price + '</span>' +
            '<button class="btn btn--gold btn--sm" data-book="' + f.id + '">Book</button>' +
          '</div>' +
        '</div>';
    }).join("");
  }

  function renderFavStylists() {
    $("#favStylists").innerHTML = favStylists.map(function (f) {
      return '' +
        '<div class="fav" data-id="' + f.id + '">' +
          '<div class="fav__head">' +
            '<div class="person">' +
              '<span class="avatar">' + esc(f.initials) + '</span>' +
              '<div><div class="fav__name">' + esc(f.name) + '</div><div class="fav__sub">' + esc(f.sub) + '</div></div>' +
            '</div>' +
            '<button class="heart" data-fav="stylist" aria-pressed="' + (f.saved ? "true" : "false") +
              '" aria-label="' + (f.saved ? "Remove" : "Save") + " " + esc(f.name) + '">' + heartSvg() + '</button>' +
          '</div>' +
        '</div>';
    }).join("");
  }

  function bindFavToggle(container, store, kind) {
    container.addEventListener("click", function (e) {
      var heart = e.target.closest('.heart[data-fav]');
      var book = e.target.closest("button[data-book]");
      if (book) {
        var bi = store.find(function (x) { return x.id === book.dataset.book; });
        if (bi) toast("Booking " + bi.name + " — choose a time to confirm.");
        return;
      }
      if (!heart) return;
      var card = heart.closest(".fav");
      var item = store.find(function (x) { return x.id === card.dataset.id; });
      if (!item) return;
      item.saved = !item.saved;
      heart.setAttribute("aria-pressed", item.saved ? "true" : "false");
      heart.setAttribute("aria-label", (item.saved ? "Remove " : "Save ") + item.name);
      refreshCounts();
      toast(item.saved ? item.name + " saved to favorites." : item.name + " removed from favorites.");
    });
  }

  /* ----- Recommendations ----- */
  function renderRecs() {
    $("#recList").innerHTML = recommends.map(function (r) {
      return '' +
        '<li class="rec__item">' +
          '<div><div class="rec__svc">' + esc(r.svc) + '</div><div class="rec__why">' + esc(r.why) + '</div></div>' +
          '<button class="btn btn--sm rec__add" data-rec="' + esc(r.svc) + '">+ $' + r.price + '</button>' +
        '</li>';
    }).join("");
  }
  $("#recList").addEventListener("click", function (e) {
    var btn = e.target.closest("button[data-rec]");
    if (!btn) return;
    toast("Added " + btn.dataset.rec + " to your next visit.");
  });

  /* ----- Init ----- */
  renderUpcoming();
  renderPast("");
  renderFavServices();
  renderFavStylists();
  renderRecs();
  bindFavToggle($("#favServices"), favServices, "service");
  bindFavToggle($("#favStylists"), favStylists, "stylist");
  refreshCounts();
})();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --sh-1: 0 1px 2px rgba(28, 42, 37, 0.05), 0 1px 3px rgba(28, 42, 37, 0.06);
  --sh-2: 0 6px 18px rgba(28, 42, 37, 0.08), 0 2px 6px rgba(28, 42, 37, 0.05);
  --sh-3: 0 24px 60px rgba(22, 48, 42, 0.22), 0 6px 18px rgba(22, 48, 42, 0.14);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: "Inter", system-ui, sans-serif;
  line-height: 1.55;
  color: var(--ink);
  background:
    radial-gradient(1200px 480px at 78% -10%, rgba(176, 141, 87, 0.08), transparent 60%),
    var(--ivory);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3 {
  font-family: "Cormorant Garamond", Georgia, serif;
  margin: 0;
}

.shell { max-width: 1180px; margin: 0 auto; padding: 0 22px 64px; }

/* ---------- Topbar ---------- */
.topbar {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 18px 0;
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 20;
  background:
    linear-gradient(var(--ivory), var(--ivory)) padding-box;
  backdrop-filter: saturate(1.1);
}
.brand { display: flex; align-items: center; gap: 12px; }
.brand__mark {
  width: 44px; height: 44px;
  display: grid; place-items: center;
  border-radius: 12px;
  background: linear-gradient(150deg, var(--green-700), var(--green-d));
  color: var(--brass-50);
  font-family: "Cormorant Garamond", serif;
  font-weight: 700;
  font-size: 16px;
  letter-spacing: 0.5px;
  box-shadow: inset 0 0 0 1px rgba(176, 141, 87, 0.35), var(--sh-1);
}
.brand__txt { display: flex; flex-direction: column; line-height: 1.15; }
.brand__name { font-family: "Cormorant Garamond", serif; font-weight: 600; font-size: 19px; color: var(--green); }
.brand__sub { font-size: 11px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--brass-d); }

.topnav { display: flex; gap: 6px; margin-left: 14px; }
.topnav__link {
  text-decoration: none;
  color: var(--ink-2);
  font-size: 14px; font-weight: 500;
  padding: 8px 12px;
  border-radius: var(--r-sm);
  transition: background 0.18s, color 0.18s;
}
.topnav__link:hover { background: var(--green-50); color: var(--green); }
.topnav__link.is-active {
  color: var(--green);
  background: var(--green-50);
  box-shadow: inset 0 -2px 0 var(--brass);
}

/* ---------- Buttons ---------- */
.btn {
  font-family: inherit;
  font-size: 14px; font-weight: 600;
  border: 1px solid transparent;
  border-radius: var(--r-sm);
  padding: 10px 16px;
  cursor: pointer;
  display: inline-flex; align-items: center; gap: 8px;
  transition: transform 0.12s, box-shadow 0.18s, background 0.18s, border-color 0.18s;
}
.btn:active { transform: translateY(1px); }
.btn:focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }
.btn--primary {
  margin-left: auto;
  color: var(--paper);
  background: linear-gradient(150deg, var(--green-700), var(--green-d));
  box-shadow: var(--sh-2), inset 0 0 0 1px rgba(176, 141, 87, 0.28);
}
.btn--primary:hover { box-shadow: var(--sh-3), inset 0 0 0 1px rgba(176, 141, 87, 0.45); }
.btn__plus { font-size: 17px; line-height: 1; color: var(--brass-50); }
.btn--ghost {
  background: var(--white);
  color: var(--ink-2);
  border-color: var(--line-2);
}
.btn--ghost:hover { background: var(--green-50); border-color: var(--green-700); color: var(--green); }

/* ---------- Head ---------- */
.page { padding-top: 30px; }
.head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 28px;
  flex-wrap: wrap;
}
.eyebrow {
  margin: 0 0 6px;
  font-size: 11px; letter-spacing: 0.18em; text-transform: uppercase;
  color: var(--brass-d); font-weight: 600;
}
.display { font-size: clamp(38px, 6vw, 56px); font-weight: 600; line-height: 1.02; color: var(--green); letter-spacing: -0.01em; }
.lede { margin: 10px 0 0; max-width: 46ch; color: var(--muted); font-size: 15px; }

.stats { display: flex; gap: 14px; margin: 0; }
.stat {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 18px;
  min-width: 116px;
  box-shadow: var(--sh-1);
}
.stat dt { font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); }
.stat dd { margin: 4px 0 0; font-family: "Cormorant Garamond", serif; font-weight: 700; font-size: 26px; color: var(--green); }

/* ---------- Toolbar ---------- */
.toolbar {
  margin: 30px 0 22px;
  display: flex;
  gap: 14px;
  align-items: center;
  flex-wrap: wrap;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--line);
}
.search {
  position: relative;
  flex: 1 1 260px;
  min-width: 220px;
}
.search__icon {
  position: absolute; left: 13px; top: 50%; transform: translateY(-50%);
  width: 18px; height: 18px; color: var(--muted); pointer-events: none;
}
.search input {
  width: 100%;
  font-family: inherit; font-size: 14px;
  padding: 11px 14px 11px 40px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-md);
  background: var(--white);
  color: var(--ink);
  transition: border-color 0.18s, box-shadow 0.18s;
}
.search input::placeholder { color: var(--muted); }
.search input:focus { outline: none; border-color: var(--green-700); box-shadow: 0 0 0 3px rgba(38, 73, 62, 0.12); }

.chips { display: flex; gap: 8px; flex-wrap: wrap; }
.chip {
  font-family: inherit; font-size: 13px; font-weight: 500;
  padding: 8px 14px;
  border-radius: 999px;
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink-2);
  cursor: pointer;
  transition: all 0.16s;
}
.chip:hover { border-color: var(--brass); color: var(--brass-d); }
.chip.is-active {
  background: var(--green);
  color: var(--brass-50);
  border-color: var(--green);
  box-shadow: var(--sh-1);
}
.chip:focus-visible, .seg:focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }

.status-toggle {
  display: inline-flex;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  padding: 3px;
  background: var(--white);
}
.seg {
  font-family: inherit; font-size: 13px; font-weight: 500;
  border: none; background: transparent; cursor: pointer;
  padding: 6px 14px; border-radius: 999px; color: var(--ink-2);
  transition: all 0.16s;
}
.seg.is-active { background: var(--brass-50); color: var(--brass-d); box-shadow: inset 0 0 0 1px rgba(176, 141, 87, 0.4); }

/* ---------- Grid ---------- */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(310px, 1fr));
  gap: 20px;
}

.card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--sh-1);
  display: flex;
  flex-direction: column;
  transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
  animation: rise 0.4s ease both;
}
.card:hover { transform: translateY(-4px); box-shadow: var(--sh-3); border-color: var(--line-2); }
@keyframes rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

.card__cover {
  position: relative;
  aspect-ratio: 16 / 7;
  background-size: cover;
}
.card__cover::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(22, 48, 42, 0.05), rgba(22, 48, 42, 0.35));
}
.cover-label {
  position: absolute; top: 12px; left: 12px; z-index: 2;
  font-size: 10px; letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--paper); font-weight: 600;
  background: rgba(22, 48, 42, 0.42);
  border: 1px solid rgba(243, 234, 217, 0.4);
  padding: 4px 9px; border-radius: 999px;
  backdrop-filter: blur(2px);
}

.card__avatar {
  position: absolute;
  bottom: -28px; left: 22px; z-index: 3;
  width: 64px; height: 64px;
  border-radius: 16px;
  display: grid; place-items: center;
  font-family: "Cormorant Garamond", serif;
  font-weight: 700; font-size: 24px;
  color: var(--paper);
  border: 3px solid var(--paper);
  box-shadow: var(--sh-2);
}

.card__body { padding: 38px 22px 18px; }
.card__name { font-size: 23px; font-weight: 600; color: var(--green); line-height: 1.05; }
.card__role { margin: 2px 0 0; font-size: 13px; color: var(--muted); }
.card__role .dot { color: var(--brass); margin: 0 6px; }

.card__badges { display: flex; gap: 7px; flex-wrap: wrap; margin: 14px 0 16px; }
.badge {
  font-size: 11px; font-weight: 600; letter-spacing: 0.04em;
  padding: 4px 9px; border-radius: 999px;
  display: inline-flex; align-items: center; gap: 5px;
}
.badge--team { background: var(--green-50); color: var(--green-700); }
.badge--status { gap: 6px; }
.badge--status::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
.badge--active { background: rgba(47, 158, 111, 0.12); color: var(--ok); }
.badge--inactive { background: rgba(107, 122, 114, 0.14); color: var(--muted); }
.badge--pending { background: rgba(201, 138, 43, 0.14); color: var(--warn); }

.metrics {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
}
.metric { background: var(--paper); padding: 11px 14px; }
.metric__k { font-size: 11px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); }
.metric__v { font-family: "Cormorant Garamond", serif; font-weight: 700; font-size: 21px; color: var(--ink); }

.card__foot {
  margin-top: auto;
  display: flex; gap: 8px;
  padding: 14px 22px;
  border-top: 1px solid var(--line);
  background: linear-gradient(var(--white), var(--paper));
}
.act {
  flex: 1;
  font-family: inherit; font-size: 13px; font-weight: 500;
  padding: 8px 10px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink-2);
  cursor: pointer;
  transition: all 0.15s;
}
.act:hover { background: var(--green-50); border-color: var(--green-700); color: var(--green); }
.act--icon { flex: 0 0 auto; min-width: 40px; font-size: 15px; }
.act:focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }

/* ---------- Empty ---------- */
.empty { text-align: center; color: var(--muted); padding: 48px 0; font-size: 15px; }
.linkbtn { background: none; border: none; color: var(--green-700); font-weight: 600; cursor: pointer; text-decoration: underline; font: inherit; }

/* ---------- Modal ---------- */
.modal { position: fixed; inset: 0; z-index: 60; display: grid; place-items: center; padding: 20px; }
.modal[hidden] { display: none; }
.modal__backdrop { position: absolute; inset: 0; background: rgba(22, 34, 30, 0.5); backdrop-filter: blur(3px); animation: fade 0.2s ease; }
.modal__card {
  position: relative;
  width: min(520px, 100%);
  background: var(--paper);
  border-radius: var(--r-lg);
  border: 1px solid var(--line-2);
  box-shadow: var(--sh-3);
  padding: 26px 26px 24px;
  animation: pop 0.24s cubic-bezier(0.2, 0.9, 0.3, 1.2) both;
}
@keyframes fade { from { opacity: 0; } }
@keyframes pop { from { opacity: 0; transform: translateY(14px) scale(0.97); } }
.modal__bar { display: flex; justify-content: space-between; align-items: flex-start; }
.modal__title { font-size: 30px; font-weight: 600; color: var(--green); }
.modal__x { border: none; background: none; font-size: 26px; line-height: 1; color: var(--muted); cursor: pointer; padding: 0 4px; border-radius: 6px; }
.modal__x:hover { color: var(--danger); }
.modal__lede { margin: 4px 0 18px; color: var(--muted); font-size: 14px; }

.form { display: flex; flex-direction: column; gap: 14px; }
.field { display: flex; flex-direction: column; gap: 6px; }
.field label { font-size: 12px; font-weight: 600; letter-spacing: 0.04em; color: var(--ink-2); text-transform: uppercase; }
.field input, .field select {
  font-family: inherit; font-size: 14px;
  padding: 10px 12px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  background: var(--white);
  color: var(--ink);
}
.field input:focus, .field select:focus { outline: none; border-color: var(--green-700); box-shadow: 0 0 0 3px rgba(38, 73, 62, 0.12); }
.field input.invalid { border-color: var(--danger); box-shadow: 0 0 0 3px rgba(196, 80, 62, 0.12); }
.row2 { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.modal__actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 8px; }

/* ---------- Toast ---------- */
.toast {
  position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%) translateY(12px);
  background: var(--green-d);
  color: var(--brass-50);
  padding: 12px 18px;
  border-radius: var(--r-md);
  font-size: 14px; font-weight: 500;
  box-shadow: var(--sh-3), inset 0 0 0 1px rgba(176, 141, 87, 0.35);
  z-index: 80;
  opacity: 0;
  transition: opacity 0.25s, transform 0.25s;
  pointer-events: none;
  max-width: calc(100% - 40px);
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

/* ---------- Responsive ---------- */
@media (max-width: 820px) {
  .topnav { display: none; }
  .btn--primary { margin-left: auto; }
}
@media (max-width: 520px) {
  .shell { padding: 0 14px 48px; }
  .topbar { gap: 12px; }
  .brand__sub { display: none; }
  .head { align-items: stretch; }
  .stats { width: 100%; }
  .stat { flex: 1; min-width: 0; padding: 12px; }
  .stat dd { font-size: 22px; }
  .toolbar { gap: 12px; }
  .grid { grid-template-columns: 1fr; }
  .row2 { grid-template-columns: 1fr; }
  .status-toggle, .chips { width: 100%; }
  .chips { justify-content: flex-start; }
  .modal__card { padding: 22px 18px; }
}

