(function () {
  "use strict";

  /* ---------- Data (fictional) ---------- */
  var TEAM_LABELS = {
    luxury: "Luxury",
    residential: "Residential",
    commercial: "Commercial",
    rentals: "Rentals"
  };

  // Warm, architectural "photography" simulated with gradients.
  var COVERS = [
    "linear-gradient(135deg, #2c4a3e 0%, #4a6b58 45%, #b08d57 110%)",
    "linear-gradient(135deg, #7a5a36 0%, #b08d57 50%, #e8d3a8 105%)",
    "linear-gradient(120deg, #1f3d34 0%, #2f5a4a 55%, #8fae9a 110%)",
    "linear-gradient(140deg, #5b4327 0%, #94733f 50%, #d8b483 110%)",
    "linear-gradient(130deg, #26493e 0%, #6b8f7c 60%, #c8a36a 115%)",
    "linear-gradient(135deg, #3a3a2e 0%, #6b6a4a 50%, #b08d57 110%)",
    "linear-gradient(125deg, #1c3a31 0%, #486b5c 55%, #a8c0ad 110%)",
    "linear-gradient(140deg, #6a4a2c 0%, #a3814d 50%, #ead2a8 110%)"
  ];

  var AGENTS = [
    { name: "Eleanor Whitfield", role: "Senior Broker", team: "luxury", listings: 14, volume: 48.2, status: "active", region: "Marin Heights" },
    { name: "Diego Salazar", role: "Listing Agent", team: "residential", listings: 11, volume: 22.9, status: "active", region: "Cedar Park" },
    { name: "Priya Ramanathan", role: "Team Lead", team: "commercial", listings: 9, volume: 61.4, status: "active", region: "Harbor District" },
    { name: "Marcus Bélanger", role: "Sales Associate", team: "rentals", listings: 18, volume: 7.3, status: "active", region: "Old Mill Quarter" },
    { name: "Sofia Castellano", role: "Listing Agent", team: "luxury", listings: 8, volume: 39.6, status: "active", region: "Vale Ridge" },
    { name: "Theo Nakamura", role: "Sales Associate", team: "residential", listings: 13, volume: 18.1, status: "inactive", region: "Birchwood" },
    { name: "Amara Okafor", role: "Senior Broker", team: "commercial", listings: 6, volume: 14.7, status: "active", region: "Foundry Row" },
    { name: "Lucas Hartmann", role: "Listing Agent", team: "rentals", listings: 7, volume: 2.4, status: "inactive", region: "Greenfield" }
  ];

  var BRASS_TONES = ["#b08d57", "#26493e", "#94733f", "#2f5a4a", "#6b8f7c", "#5b4327", "#1f3d34", "#a3814d"];

  /* ---------- State ---------- */
  var state = { search: "", team: "all", status: "all" };

  /* ---------- Helpers ---------- */
  var $ = function (sel, ctx) { return (ctx || document).querySelector(sel); };
  var $$ = function (sel, ctx) { return Array.prototype.slice.call((ctx || document).querySelectorAll(sel)); };

  function initials(name) {
    return name.split(/\s+/).map(function (p) { return p[0]; }).join("").slice(0, 2).toUpperCase();
  }
  function money(m) {
    return "$" + (m >= 1 ? m.toFixed(1) + "M" : (m * 1000).toFixed(0) + "K");
  }
  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  var toastEl = $("#toast");
  var toastTimer;
  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.hidden = false;
    requestAnimationFrame(function () { toastEl.classList.add("show"); });
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
      setTimeout(function () { toastEl.hidden = true; }, 280);
    }, 2600);
  }

  /* ---------- Render ---------- */
  var roster = $("#roster");
  var emptyEl = $("#empty");

  function filtered() {
    var q = state.search.trim().toLowerCase();
    return AGENTS.filter(function (a) {
      if (state.team !== "all" && a.team !== state.team) return false;
      if (state.status !== "all" && a.status !== state.status) return false;
      if (q) {
        var hay = (a.name + " " + a.role + " " + TEAM_LABELS[a.team] + " " + a.region + " " + a.status).toLowerCase();
        if (hay.indexOf(q) === -1) return false;
      }
      return true;
    });
  }

  function statusBadge(s) {
    var label = s === "active" ? "Active" : s === "pending" ? "Pending" : "Inactive";
    return '<span class="badge badge--status badge--' + s + '">' + label + "</span>";
  }

  function cardHTML(a, i) {
    var tone = BRASS_TONES[i % BRASS_TONES.length];
    var cover = COVERS[i % COVERS.length];
    return (
      '<article class="card" data-name="' + esc(a.name) + '">' +
        '<div class="card__cover" style="background-image:' + cover + '">' +
          '<span class="cover-label">' + esc(a.region) + "</span>" +
          '<div class="card__avatar" style="background:linear-gradient(150deg,' + tone + ',rgba(0,0,0,.35))">' + initials(a.name) + "</div>" +
        "</div>" +
        '<div class="card__body">' +
          '<h3 class="card__name">' + esc(a.name) + "</h3>" +
          '<p class="card__role">' + esc(a.role) + '<span class="dot">&bull;</span>' + TEAM_LABELS[a.team] + "</p>" +
          '<div class="card__badges">' +
            '<span class="badge badge--team">' + TEAM_LABELS[a.team] + "</span>" +
            statusBadge(a.status) +
          "</div>" +
          '<div class="metrics">' +
            '<div class="metric"><div class="metric__k">Active listings</div><div class="metric__v">' + a.listings + "</div></div>" +
            '<div class="metric"><div class="metric__k">YTD volume</div><div class="metric__v">' + money(a.volume) + "</div></div>" +
          "</div>" +
        "</div>" +
        '<div class="card__foot">' +
          '<button class="act" data-act="profile">View profile</button>' +
          '<button class="act" data-act="message">Message</button>' +
          '<button class="act act--icon" data-act="more" aria-label="More actions">&#8943;</button>' +
        "</div>" +
      "</article>"
    );
  }

  function render() {
    var list = filtered();
    if (!list.length) {
      roster.innerHTML = "";
      emptyEl.hidden = false;
    } else {
      emptyEl.hidden = true;
      roster.innerHTML = list.map(cardHTML).join("");
    }
    updateStats();
  }

  function updateStats() {
    var live = AGENTS.filter(function (a) { return a.status === "active"; });
    var listings = AGENTS.reduce(function (s, a) { return s + a.listings; }, 0);
    var vol = AGENTS.reduce(function (s, a) { return s + a.volume; }, 0);
    $("#statAgents").textContent = AGENTS.length;
    $("#statListings").textContent = listings;
    $("#statVolume").textContent = "$" + vol.toFixed(1) + "M";
    void live;
  }

  /* ---------- Filter wiring ---------- */
  $("#search").addEventListener("input", function (e) {
    state.search = e.target.value;
    render();
  });

  $$(".chip").forEach(function (chip) {
    chip.addEventListener("click", function () {
      $$(".chip").forEach(function (c) {
        c.classList.remove("is-active");
        c.setAttribute("aria-pressed", "false");
      });
      chip.classList.add("is-active");
      chip.setAttribute("aria-pressed", "true");
      state.team = chip.dataset.team;
      render();
    });
  });

  $$(".seg").forEach(function (seg) {
    seg.addEventListener("click", function () {
      $$(".seg").forEach(function (s) {
        s.classList.remove("is-active");
        s.setAttribute("aria-pressed", "false");
      });
      seg.classList.add("is-active");
      seg.setAttribute("aria-pressed", "true");
      state.status = seg.dataset.status;
      render();
    });
  });

  $("#clearAll").addEventListener("click", function () {
    state.search = "";
    state.team = "all";
    state.status = "all";
    $("#search").value = "";
    $$(".chip").forEach(function (c) {
      var on = c.dataset.team === "all";
      c.classList.toggle("is-active", on);
      c.setAttribute("aria-pressed", String(on));
    });
    $$(".seg").forEach(function (s) {
      var on = s.dataset.status === "all";
      s.classList.toggle("is-active", on);
      s.setAttribute("aria-pressed", String(on));
    });
    render();
  });

  /* ---------- Per-row actions (delegated) ---------- */
  roster.addEventListener("click", function (e) {
    var btn = e.target.closest(".act");
    if (!btn) return;
    var card = e.target.closest(".card");
    var name = card ? card.dataset.name : "Agent";
    var act = btn.dataset.act;
    if (act === "profile") toast("Opening profile — " + name);
    else if (act === "message") toast("Message draft started for " + name);
    else if (act === "more") toast("Reassign · Deactivate · Export — " + name);
  });

  /* ---------- Modal ---------- */
  var modal = $("#inviteModal");
  var lastFocus = null;

  function openModal() {
    lastFocus = document.activeElement;
    modal.hidden = false;
    document.body.style.overflow = "hidden";
    setTimeout(function () { $("#fName").focus(); }, 30);
  }
  function closeModal() {
    modal.hidden = true;
    document.body.style.overflow = "";
    $("#inviteForm").reset();
    $$(".invalid", modal).forEach(function (el) { el.classList.remove("invalid"); });
    if (lastFocus) lastFocus.focus();
  }

  $("#inviteOpen").addEventListener("click", openModal);
  $$("[data-close]", modal).forEach(function (el) { el.addEventListener("click", closeModal); });

  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && !modal.hidden) closeModal();
  });

  $("#inviteForm").addEventListener("submit", function (e) {
    e.preventDefault();
    var nameEl = $("#fName");
    var emailEl = $("#fEmail");
    var ok = true;
    [nameEl, emailEl].forEach(function (el) {
      var bad = !el.value.trim() || (el.type === "email" && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(el.value));
      el.classList.toggle("invalid", bad);
      if (bad) ok = false;
    });
    if (!ok) { toast("Please complete the highlighted fields."); return; }

    var name = nameEl.value.trim();
    var team = $("#fTeam").value;
    AGENTS.unshift({
      name: name,
      role: $("#fRole").value,
      team: team,
      listings: 0,
      volume: 0,
      status: "pending",
      region: "Awaiting desk"
    });
    closeModal();
    state.search = ""; state.team = "all"; state.status = "all";
    $("#search").value = "";
    $$(".chip").forEach(function (c) {
      var on = c.dataset.team === "all";
      c.classList.toggle("is-active", on);
      c.setAttribute("aria-pressed", String(on));
    });
    $$(".seg").forEach(function (s) {
      var on = s.dataset.status === "all";
      s.classList.toggle("is-active", on);
      s.setAttribute("aria-pressed", String(on));
    });
    render();
    toast("Invitation sent to " + name + " · " + TEAM_LABELS[team]);
  });

  /* ---------- Boot ---------- */
  render();
})();

snippets.css:
:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow: 0 1px 0 rgba(255,255,255,0.04) inset, 0 12px 30px -12px rgba(0,0,0,0.7);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background-image:
    radial-gradient(900px 500px at 110% -10%, rgba(198,255,58,0.06), transparent 60%),
    radial-gradient(700px 500px at -10% 0%, rgba(255,106,43,0.05), transparent 55%);
  background-attachment: fixed;
  min-height: 100vh;
}

.app {
  max-width: 1080px;
  margin: 0 auto;
  padding: 28px 20px 64px;
}

/* ---------- Top bar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 26px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.logo {
  width: 48px;
  height: 48px;
  border-radius: var(--r-md);
  display: grid;
  place-items: center;
  font-weight: 900;
  font-size: 18px;
  letter-spacing: -0.5px;
  color: #0d0f12;
  background: linear-gradient(135deg, var(--neon), var(--neon-d));
  box-shadow: 0 8px 22px -8px rgba(198,255,58,0.6);
}

.eyebrow {
  display: block;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
}

.brand-text h1 {
  margin: 2px 0 0;
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.live {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-2);
  background: var(--surface);
  border: 1px solid var(--line);
  padding: 9px 14px;
  border-radius: 999px;
}

.live .dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 0 rgba(52,211,153,0.6);
  animation: pulse 1.8s infinite;
}

.live .clock {
  color: var(--neon);
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(52,211,153,0.5); }
  70% { box-shadow: 0 0 0 7px rgba(52,211,153,0); }
  100% { box-shadow: 0 0 0 0 rgba(52,211,153,0); }
}

/* ---------- Summary stats ---------- */
.summary {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 22px;
}

.stat {
  appearance: none;
  text-align: left;
  cursor: pointer;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 16px 14px;
  color: var(--ink);
  font-family: inherit;
  transition: transform 0.12s ease, border-color 0.15s ease, background 0.15s ease;
  position: relative;
  overflow: hidden;
}

.stat::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: var(--line-2);
  transition: background 0.15s ease;
}

.stat.free::before { background: var(--ok); }
.stat.inuse::before { background: var(--orange); }
.stat.oos::before { background: var(--danger); }

.stat:hover { transform: translateY(-2px); border-color: var(--line-2); }
.stat:focus-visible {
  outline: 2px solid var(--neon);
  outline-offset: 2px;
}
.stat[aria-pressed="true"] {
  background: var(--surface-2);
  border-color: var(--line-2);
}

.stat-num {
  display: block;
  font-size: 30px;
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.stat.free .stat-num { color: var(--ok); }
.stat.inuse .stat-num { color: var(--orange); }
.stat.oos .stat-num { color: var(--danger); }

.stat-label {
  display: block;
  margin-top: 8px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}

/* ---------- Toolbar ---------- */
.toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  flex-wrap: wrap;
}

.search {
  position: relative;
  flex: 1 1 240px;
  min-width: 200px;
}

.search-ico {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  color: var(--muted);
  pointer-events: none;
}

.search input {
  width: 100%;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  color: var(--ink);
  font-family: inherit;
  font-size: 14px;
  padding: 12px 14px 12px 42px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.search input::placeholder { color: var(--muted); }
.search input:focus {
  outline: none;
  border-color: var(--neon);
  box-shadow: 0 0 0 3px var(--neon-50);
}

.filters {
  display: inline-flex;
  gap: 6px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 4px;
}

.chip {
  appearance: none;
  cursor: pointer;
  border: none;
  background: transparent;
  color: var(--ink-2);
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  padding: 8px 14px;
  border-radius: 999px;
  transition: background 0.15s ease, color 0.15s ease;
  white-space: nowrap;
}

.chip:hover { color: var(--ink); }
.chip:focus-visible {
  outline: 2px solid var(--neon);
  outline-offset: 2px;
}
.chip.is-active {
  background: var(--neon);
  color: #0d0f12;
}

/* ---------- Board ---------- */
.board {
  display: flex;
  flex-direction: column;
  gap: 26px;
}

.group-title {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin: 0 0 12px;
  font-size: 13px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--ink);
}

.group-title .group-count {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--muted);
}

.group-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 12px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 15px 15px 14px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: transform 0.12s ease, border-color 0.15s ease;
}

.card:hover { transform: translateY(-2px); border-color: var(--line-2); }

.card.free { border-left: 3px solid var(--ok); }
.card.inuse { border-left: 3px solid var(--orange); }
.card.oos { border-left: 3px solid var(--danger); }

.card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.card-name {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.card-sub {
  font-size: 12px;
  color: var(--muted);
  margin-top: 2px;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 5px 10px;
  border-radius: 999px;
  white-space: nowrap;
  flex-shrink: 0;
}

.pill::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.pill.free { color: var(--ok); background: rgba(52,211,153,0.13); }
.pill.inuse { color: var(--orange); background: var(--orange-soft); }
.pill.oos { color: var(--danger); background: rgba(248,113,113,0.13); }

.card-meta {
  font-size: 12.5px;
  color: var(--ink-2);
  min-height: 18px;
}

.card-meta strong { color: var(--ink); font-weight: 700; }
.card-meta .oos-reason { color: var(--danger); font-weight: 600; }

/* ETA bar */
.eta {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.eta-track {
  height: 6px;
  border-radius: 999px;
  background: var(--surface-2);
  overflow: hidden;
}

.eta-fill {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--orange), #ffb066);
  transition: width 0.6s ease;
}

.eta-label {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: var(--muted);
  font-weight: 600;
}

.card-foot {
  display: flex;
  gap: 8px;
  margin-top: 2px;
}

.btn {
  appearance: none;
  cursor: pointer;
  font-family: inherit;
  font-weight: 700;
  font-size: 13px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line);
  padding: 9px 13px;
  background: var(--surface-2);
  color: var(--ink);
  transition: transform 0.1s ease, background 0.15s ease, border-color 0.15s ease;
}

.btn:hover { transform: translateY(-1px); border-color: var(--line-2); }
.btn:active { transform: translateY(0); }
.btn:focus-visible {
  outline: 2px solid var(--neon);
  outline-offset: 2px;
}

.btn.report { flex: 1; }
.btn.fix {
  flex: 1;
  background: var(--neon);
  color: #0d0f12;
  border-color: transparent;
}
.btn.fix:hover { background: var(--neon-d); }

.btn.danger {
  background: var(--danger);
  color: #1a0a0a;
  border-color: transparent;
}
.btn.danger:hover { filter: brightness(1.08); }

.btn.ghost {
  background: transparent;
}

.empty {
  text-align: center;
  color: var(--muted);
  font-size: 14px;
  padding: 48px 0;
  font-weight: 600;
}

/* ---------- Modal ---------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(5,6,8,0.7);
  backdrop-filter: blur(4px);
  display: grid;
  place-items: center;
  padding: 20px;
  z-index: 50;
  animation: fade 0.15s ease;
}

@keyframes fade { from { opacity: 0; } to { opacity: 1; } }

.modal {
  width: 100%;
  max-width: 420px;
  background: var(--elevated);
  border: 1px solid var(--line-2);
  border-radius: var(--r-lg);
  padding: 24px;
  box-shadow: 0 30px 60px -20px rgba(0,0,0,0.8);
  animation: rise 0.18s ease;
}

@keyframes rise { from { transform: translateY(10px); opacity: 0; } to { transform: none; opacity: 1; } }

.modal h2 {
  margin: 0 0 4px;
  font-size: 19px;
  font-weight: 800;
}

.modal-sub {
  margin: 0 0 18px;
  font-size: 13px;
  color: var(--muted);
}

.field {
  display: block;
  margin-bottom: 14px;
}

.field span {
  display: block;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ink-2);
  margin-bottom: 6px;
}

.field select,
.field textarea {
  width: 100%;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  color: var(--ink);
  font-family: inherit;
  font-size: 14px;
  padding: 10px 12px;
  resize: vertical;
}

.field select:focus,
.field textarea:focus {
  outline: none;
  border-color: var(--neon);
  box-shadow: 0 0 0 3px var(--neon-50);
}

.modal-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
  margin-top: 18px;
}

/* ---------- Toasts ---------- */
.toast-wrap {
  position: fixed;
  bottom: 22px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 60;
  width: min(360px, calc(100% - 40px));
}

.toast {
  background: var(--elevated);
  border: 1px solid var(--line-2);
  border-left: 3px solid var(--neon);
  border-radius: var(--r-md);
  padding: 12px 14px;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  box-shadow: 0 16px 36px -14px rgba(0,0,0,0.8);
  animation: toastIn 0.22s ease;
}

.toast.warn { border-left-color: var(--danger); }
.toast.ok { border-left-color: var(--ok); }

@keyframes toastIn {
  from { transform: translateY(12px); opacity: 0; }
  to { transform: none; opacity: 1; }
}

/* ---------- Responsive ---------- */
@media (max-width: 520px) {
  .app { padding: 20px 14px 56px; }
  .topbar { flex-direction: column; align-items: flex-start; gap: 12px; }
  .brand-text h1 { font-size: 22px; }
  .summary { grid-template-columns: repeat(2, 1fr); }
  .toolbar { flex-direction: column; align-items: stretch; }
  .filters { overflow-x: auto; justify-content: flex-start; }
  .group-grid { grid-template-columns: 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

