/* Ironworks Performance — Equipment Status board (vanilla JS) */
(function () {
  "use strict";

  var STATUS = { FREE: "free", INUSE: "inuse", OOS: "oos" };
  var LABEL = { free: "Free", inuse: "In use", oos: "Out of order" };

  // Equipment grouped by category. inUse holds elapsed minutes; eta holds total session minutes.
  var equipment = [
    { id: "tm-1", group: "Treadmills", name: "Treadmill 01", sub: "Woodway Curve", status: STATUS.INUSE, by: "M. Okafor", elapsed: 14, total: 30 },
    { id: "tm-2", group: "Treadmills", name: "Treadmill 02", sub: "Technogym Skillrun", status: STATUS.FREE },
    { id: "tm-3", group: "Treadmills", name: "Treadmill 03", sub: "Technogym Skillrun", status: STATUS.INUSE, by: "Priya N.", elapsed: 22, total: 25 },
    { id: "tm-4", group: "Treadmills", name: "Treadmill 04", sub: "Woodway 4Front", status: STATUS.OOS, reason: "Belt slipping" },

    { id: "sq-1", group: "Squat Racks", name: "Rack A", sub: "Power rack — platform", status: STATUS.INUSE, by: "Diego R.", elapsed: 9, total: 35 },
    { id: "sq-2", group: "Squat Racks", name: "Rack B", sub: "Power rack — platform", status: STATUS.FREE },
    { id: "sq-3", group: "Squat Racks", name: "Rack C", sub: "Half rack", status: STATUS.FREE },
    { id: "sq-4", group: "Squat Racks", name: "Rack D", sub: "Combo rack", status: STATUS.INUSE, by: "Coach Lena", elapsed: 41, total: 45 },

    { id: "bn-1", group: "Benches", name: "Flat Bench 1", sub: "Olympic flat", status: STATUS.FREE },
    { id: "bn-2", group: "Benches", name: "Incline Bench 1", sub: "Adjustable", status: STATUS.INUSE, by: "T. Alvarez", elapsed: 6, total: 20 },
    { id: "bn-3", group: "Benches", name: "Decline Bench 1", sub: "Olympic decline", status: STATUS.FREE },
    { id: "bn-4", group: "Benches", name: "Flat Bench 2", sub: "Olympic flat", status: STATUS.OOS, reason: "Loose / unsafe" },

    { id: "rw-1", group: "Rowers", name: "Rower 01", sub: "Concept2 RowErg", status: STATUS.INUSE, by: "Sam W.", elapsed: 3, total: 15 },
    { id: "rw-2", group: "Rowers", name: "Rower 02", sub: "Concept2 RowErg", status: STATUS.FREE },
    { id: "rw-3", group: "Rowers", name: "Rower 03", sub: "Concept2 RowErg", status: STATUS.INUSE, by: "Hana K.", elapsed: 18, total: 20 },

    { id: "cb-1", group: "Cable Machines", name: "Dual Cable 1", sub: "Functional trainer", status: STATUS.FREE },
    { id: "cb-2", group: "Cable Machines", name: "Lat Pulldown", sub: "Selectorized", status: STATUS.INUSE, by: "Marco V.", elapsed: 11, total: 18 },
    { id: "cb-3", group: "Cable Machines", name: "Cable Crossover", sub: "Functional trainer", status: STATUS.FREE },
    { id: "cb-4", group: "Cable Machines", name: "Seated Row", sub: "Selectorized", status: STATUS.OOS, reason: "Display not working" }
  ];

  var GROUP_ORDER = ["Treadmills", "Squat Racks", "Benches", "Rowers", "Cable Machines"];
  var FIRST_NAMES = ["Aria", "Noah", "Zoe", "Liam", "Mei", "Carlos", "Ines", "Jay", "Tara", "Omar", "Nia", "Ben"];

  var state = { filter: "all", query: "" };

  var board = document.getElementById("board");
  var emptyEl = document.getElementById("empty");
  var searchEl = document.getElementById("search");
  var toastWrap = document.getElementById("toasts");

  // ---------- helpers ----------
  function byId(id) { return equipment.filter(function (e) { return e.id === id; })[0]; }

  function randomName() {
    var f = FIRST_NAMES[Math.floor(Math.random() * FIRST_NAMES.length)];
    return f + " " + String.fromCharCode(65 + Math.floor(Math.random() * 26)) + ".";
  }

  function toast(msg, kind) {
    var el = document.createElement("div");
    el.className = "toast" + (kind ? " " + kind : "");
    el.textContent = msg;
    toastWrap.appendChild(el);
    setTimeout(function () {
      el.style.transition = "opacity .25s ease, transform .25s ease";
      el.style.opacity = "0";
      el.style.transform = "translateY(8px)";
      setTimeout(function () { el.remove(); }, 260);
    }, 3200);
  }

  function matches(item) {
    if (state.filter !== "all" && item.status !== state.filter) return false;
    if (state.query) {
      var q = state.query.toLowerCase();
      var hay = (item.name + " " + item.sub + " " + item.group + " " + (item.by || "") + " " + (item.reason || "")).toLowerCase();
      if (hay.indexOf(q) === -1) return false;
    }
    return true;
  }

  // ---------- rendering ----------
  function updateSummary() {
    var c = { all: equipment.length, free: 0, inuse: 0, oos: 0 };
    equipment.forEach(function (e) { c[e.status]++; });
    document.getElementById("count-all").textContent = c.all;
    document.getElementById("count-free").textContent = c.free;
    document.getElementById("count-inuse").textContent = c.inuse;
    document.getElementById("count-oos").textContent = c.oos;
  }

  function cardHTML(item) {
    var meta = "";
    if (item.status === STATUS.FREE) {
      meta = '<div class="card-meta">Available now — last cleaned <strong>recently</strong></div>';
    } else if (item.status === STATUS.INUSE) {
      var remaining = Math.max(0, item.total - item.elapsed);
      var pct = Math.min(100, Math.round((item.elapsed / item.total) * 100));
      meta =
        '<div class="card-meta">In use by <strong>' + item.by + "</strong> · " + item.elapsed + " min</div>" +
        '<div class="eta">' +
          '<div class="eta-track"><div class="eta-fill" style="width:' + pct + '%"></div></div>' +
          '<div class="eta-label"><span>Session</span><span>~' + remaining + " min left</span></div>" +
        "</div>";
    } else {
      meta = '<div class="card-meta"><span class="oos-reason">' + item.reason + "</span> · reported</div>";
    }

    var foot;
    if (item.status === STATUS.OOS) {
      foot = '<button class="btn fix" data-act="fix" data-id="' + item.id + '">Mark fixed</button>';
    } else {
      foot = '<button class="btn report" data-act="report" data-id="' + item.id + '">Report issue</button>';
    }

    return (
      '<article class="card ' + item.status + '">' +
        '<div class="card-head">' +
          "<div><div class=\"card-name\">" + item.name + "</div><div class=\"card-sub\">" + item.sub + "</div></div>" +
          '<span class="pill ' + item.status + '">' + LABEL[item.status] + "</span>" +
        "</div>" +
        meta +
        '<div class="card-foot">' + foot + "</div>" +
      "</article>"
    );
  }

  function render() {
    var visible = equipment.filter(matches);
    board.innerHTML = "";

    if (!visible.length) {
      emptyEl.hidden = false;
      return;
    }
    emptyEl.hidden = true;

    GROUP_ORDER.forEach(function (group) {
      var items = visible.filter(function (e) { return e.group === group; });
      if (!items.length) return;

      var section = document.createElement("section");
      var total = equipment.filter(function (e) { return e.group === group; }).length;

      var head = document.createElement("h2");
      head.className = "group-title";
      head.innerHTML = group + ' <span class="group-count">' + items.length + " / " + total + " shown</span>";
      section.appendChild(head);

      var grid = document.createElement("div");
      grid.className = "group-grid";
      grid.innerHTML = items.map(cardHTML).join("");
      section.appendChild(grid);

      board.appendChild(section);
    });
  }

  // ---------- modal (report issue) ----------
  var modal = document.getElementById("modal");
  var modalSub = document.getElementById("modal-sub");
  var reasonEl = document.getElementById("reason");
  var notesEl = document.getElementById("notes");
  var pendingId = null;
  var lastFocused = null;

  function openModal(id) {
    pendingId = id;
    var item = byId(id);
    modalSub.textContent = "Mark " + item.name + " (" + item.sub + ") out of order so members and staff are warned.";
    notesEl.value = "";
    reasonEl.selectedIndex = 0;
    lastFocused = document.activeElement;
    modal.hidden = false;
    reasonEl.focus();
    document.addEventListener("keydown", onKey);
  }

  function closeModal() {
    modal.hidden = true;
    pendingId = null;
    document.removeEventListener("keydown", onKey);
    if (lastFocused && lastFocused.focus) lastFocused.focus();
  }

  function onKey(e) { if (e.key === "Escape") closeModal(); }

  document.getElementById("cancel").addEventListener("click", closeModal);
  modal.addEventListener("click", function (e) { if (e.target === modal) closeModal(); });

  document.getElementById("confirm").addEventListener("click", function () {
    if (!pendingId) return;
    var item = byId(pendingId);
    var reason = reasonEl.value;
    if (notesEl.value.trim()) reason += " — " + notesEl.value.trim();
    item.status = STATUS.OOS;
    item.reason = reason;
    delete item.by; delete item.elapsed; delete item.total;
    closeModal();
    updateSummary();
    render();
    toast(item.name + " marked out of order", "warn");
  });

  // ---------- board interactions ----------
  board.addEventListener("click", function (e) {
    var btn = e.target.closest("button[data-act]");
    if (!btn) return;
    var id = btn.getAttribute("data-id");
    var act = btn.getAttribute("data-act");
    if (act === "report") {
      openModal(id);
    } else if (act === "fix") {
      var item = byId(id);
      item.status = STATUS.FREE;
      delete item.reason;
      updateSummary();
      render();
      toast(item.name + " is back in service", "ok");
    }
  });

  // ---------- filters & search ----------
  function setFilter(f) {
    state.filter = f;
    document.querySelectorAll(".chip").forEach(function (c) {
      c.classList.toggle("is-active", c.getAttribute("data-filter") === f);
    });
    document.querySelectorAll(".stat").forEach(function (s) {
      s.setAttribute("aria-pressed", String(s.getAttribute("data-filter") === f));
    });
    render();
  }

  document.querySelectorAll(".chip").forEach(function (c) {
    c.addEventListener("click", function () { setFilter(c.getAttribute("data-filter")); });
  });
  document.querySelectorAll(".stat").forEach(function (s) {
    s.addEventListener("click", function () { setFilter(s.getAttribute("data-filter")); });
  });

  searchEl.addEventListener("input", function () {
    state.query = searchEl.value.trim();
    render();
  });

  // ---------- clock ----------
  function tickClock() {
    var d = new Date();
    var h = String(d.getHours()).padStart(2, "0");
    var m = String(d.getMinutes()).padStart(2, "0");
    document.getElementById("clock").textContent = h + ":" + m;
  }
  tickClock();
  setInterval(tickClock, 30000);

  // ---------- live-ish updates ----------
  // Advance in-use sessions; occasionally free up finished units or start new sessions.
  setInterval(function () {
    var changed = false;

    equipment.forEach(function (e) {
      if (e.status === STATUS.INUSE) {
        e.elapsed += 1;
        if (e.elapsed >= e.total) {
          e.status = STATUS.FREE;
          delete e.by; delete e.elapsed; delete e.total;
          changed = true;
        }
      }
    });

    // Randomly start a session on one free unit.
    if (Math.random() < 0.6) {
      var freeUnits = equipment.filter(function (e) { return e.status === STATUS.FREE; });
      if (freeUnits.length) {
        var u = freeUnits[Math.floor(Math.random() * freeUnits.length)];
        u.status = STATUS.INUSE;
        u.by = randomName();
        u.elapsed = 1;
        u.total = 15 + Math.floor(Math.random() * 30);
        changed = true;
      }
    }

    updateSummary();
    if (changed || modal.hidden) render();
  }, 5000);

  // ---------- init ----------
  updateSummary();
  render();
})();

snippets.css:
:root {
  --cream: #f4efe4;
  --paper: #faf7f0;
  --white: #ffffff;
  --newsprint: #efe9da;
  --ink: #16130f;
  --ink-2: #2b2620;
  --ink-3: #4a443b;
  --muted: #7a7164;
  --red: #b4291f;
  --red-d: #8f1f17;
  --red-50: #f3dcd9;
  --rule: rgba(22, 19, 15, 0.16);
  --rule-2: rgba(22, 19, 15, 0.3);
  --rule-hair: rgba(22, 19, 15, 0.1);
  --ok: #2f7d4f;
  --warn: #b67a18;
  --danger: #b4291f;
  --r-sm: 4px;
  --r-md: 8px;
  --r-lg: 12px;

  --serif: "Playfair Display", "Times New Roman", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  margin: 0;
  background: var(--cream);
  color: var(--ink);
  font-family: var(--sans);
  line-height: 1.5;
  padding: clamp(16px, 4vw, 48px);
}

.sheet {
  max-width: 1080px;
  margin: 0 auto;
  background: var(--paper);
  border: 1px solid var(--rule-2);
  padding: clamp(20px, 4vw, 56px);
  box-shadow: 0 1px 0 rgba(22, 19, 15, 0.04);
}

/* ---------- Rules ---------- */
.masthead__rule {
  height: 1px;
  background: var(--ink);
  margin: 14px 0;
}
.masthead__rule--double {
  position: relative;
  height: 3px;
  background: var(--ink);
  margin-top: 10px;
}
.masthead__rule--double::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -5px;
  height: 1px;
  background: var(--ink);
}

/* ---------- Masthead ---------- */
.masthead {
  text-align: center;
}
.masthead__kicker {
  margin: 0;
  font-family: var(--sans);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--muted);
}
.masthead__title {
  margin: 6px 0 6px;
  font-family: var(--serif);
  font-weight: 900;
  font-size: clamp(2.6rem, 8vw, 4.4rem);
  letter-spacing: -0.01em;
  line-height: 0.95;
  color: var(--ink);
}
.masthead__sub {
  margin: 0;
  font-size: 0.78rem;
  letter-spacing: 0.04em;
  color: var(--ink-3);
}
.masthead__sub span,
.masthead__sub time {
  white-space: nowrap;
}

/* ---------- Layout ---------- */
.layout {
  display: grid;
  grid-template-columns: minmax(0, 1.9fr) minmax(0, 1fr);
  gap: clamp(24px, 4vw, 48px);
  margin-top: 28px;
}

/* ---------- Kickers ---------- */
.kicker {
  margin: 0;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.kicker--red {
  color: var(--red);
}

/* ---------- Primary obituary ---------- */
.obit {
  border: 1px solid var(--rule-2);
  padding: clamp(18px, 3vw, 34px);
  background: linear-gradient(180deg, var(--white), var(--paper));
}
.obit__head {
  display: grid;
  grid-template-columns: 132px 1fr;
  gap: 20px;
  align-items: end;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--ink);
}
.obit__head .kicker--red {
  grid-column: 1 / -1;
  margin-bottom: 4px;
}

.portrait {
  grid-column: 1;
  margin: 0;
}
.portrait__img {
  aspect-ratio: 3 / 4;
  border: 1px solid var(--rule-2);
  filter: contrast(1.04) saturate(0.9);
}
.portrait__img--primary {
  background:
    radial-gradient(120% 80% at 50% 18%, rgba(244, 239, 228, 0.55), transparent 60%),
    radial-gradient(70% 55% at 38% 34%, rgba(43, 38, 32, 0.18), transparent 70%),
    linear-gradient(180deg, #6d6357 0%, #4a443b 42%, #2b2620 100%);
  position: relative;
}
.portrait__img--primary::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(38% 30% at 50% 40%, rgba(244, 239, 228, 0.42), transparent 70%),
    linear-gradient(120deg, transparent 40%, rgba(180, 41, 31, 0.14) 100%);
  mix-blend-mode: screen;
}
.portrait__cap {
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  text-align: left;
}
.portrait__name {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.02rem;
  line-height: 1.15;
  color: var(--ink);
}
.portrait__years {
  font-size: 0.8rem;
  letter-spacing: 0.04em;
  color: var(--muted);
  font-style: italic;
}

.obit__headline {
  grid-column: 2;
  align-self: end;
  margin: 0;
  font-family: var(--serif);
  font-weight: 700;
  font-size: clamp(1.5rem, 3.4vw, 2.25rem);
  line-height: 1.08;
  letter-spacing: -0.01em;
  color: var(--ink);
}

.dateline {
  margin: 18px 0 4px;
  font-size: 0.98rem;
  color: var(--ink-2);
}
.dateline__place {
  font-weight: 700;
  letter-spacing: 0.08em;
  font-size: 0.82rem;
  color: var(--ink);
}

/* ---------- Body columns ---------- */
.obit__body {
  margin-top: 12px;
  columns: 2;
  column-gap: 30px;
  column-rule: 1px solid var(--rule-hair);
}
.obit__body p {
  margin: 0 0 1em;
  font-size: 0.96rem;
  line-height: 1.62;
  text-align: justify;
  hyphens: auto;
  color: var(--ink-2);
}
.obit__body .lead {
  column-span: all;
  font-size: 1.04rem;
  text-align: left;
}
.lead::first-letter {
  font-family: var(--serif);
  font-weight: 800;
  float: left;
  font-size: 3.4em;
  line-height: 0.78;
  padding: 6px 10px 0 0;
  color: var(--red);
}

/* ---------- Pull quote ---------- */
.pull {
  break-inside: avoid;
  margin: 4px 0 1.2em;
  padding: 16px 0;
  border-top: 3px solid var(--ink);
  border-bottom: 1px solid var(--rule);
}
.pull__quote {
  margin: 0;
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: 1.28rem;
  line-height: 1.28;
  color: var(--ink);
  text-align: left;
}
.pull__cite {
  margin-top: 10px;
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--red);
}

/* ---------- Meta block ---------- */
.metablock {
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid var(--ink);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 26px;
}
.metablock__label {
  margin: 0 0 6px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--red);
}
.metablock__text {
  margin: 0;
  font-size: 0.88rem;
  line-height: 1.55;
  color: var(--ink-2);
}
.metablock__text strong {
  color: var(--ink);
}

/* ---------- Condolence ---------- */
.condolence {
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid var(--rule);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px 18px;
}
.candle {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--sans);
  font-weight: 600;
  font-size: 0.86rem;
  letter-spacing: 0.02em;
  color: var(--white);
  background: var(--red);
  border: 1px solid var(--red-d);
  border-radius: var(--r-sm);
  padding: 9px 16px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.08s ease;
}
.candle:hover {
  background: var(--red-d);
}
.candle:active {
  transform: translateY(1px);
}
.candle:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}
.candle__flame {
  width: 9px;
  height: 13px;
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
  background: linear-gradient(180deg, #ffe7a3, #ffb347 55%, #ff7a18);
  box-shadow: 0 0 8px rgba(255, 179, 71, 0.85);
  display: inline-block;
  transform-origin: bottom center;
  animation: flicker 1.6s ease-in-out infinite;
}
.candle.is-lit {
  background: var(--ink);
  border-color: var(--ink);
}
.candle.is-lit:hover {
  background: var(--ink-2);
}
@keyframes flicker {
  0%, 100% { transform: scale(1) rotate(-1deg); opacity: 1; }
  50% { transform: scale(0.92, 1.06) rotate(1.5deg); opacity: 0.88; }
}
@media (prefers-reduced-motion: reduce) {
  .candle__flame { animation: none; }
}
.condolence__count {
  margin: 0;
  font-size: 0.84rem;
  color: var(--ink-3);
}
.condolence__count strong {
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.share {
  margin-left: auto;
  font-family: var(--sans);
  font-weight: 600;
  font-size: 0.8rem;
  color: var(--ink);
  background: transparent;
  border: 1px solid var(--rule-2);
  border-radius: var(--r-sm);
  padding: 8px 14px;
  cursor: pointer;
  transition: border-color 0.15s ease, color 0.15s ease;
}
.share:hover {
  border-color: var(--ink);
  color: var(--red);
}
.share:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}

/* ---------- Rail ---------- */
.rail__title {
  margin: 0 0 4px;
  font-family: var(--serif);
  font-weight: 800;
  font-size: 1.2rem;
  padding-bottom: 8px;
  border-bottom: 3px solid var(--ink);
  position: relative;
}
.rail__title::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -5px;
  height: 1px;
  background: var(--ink);
}
.obitlist {
  list-style: none;
  margin: 18px 0 0;
  padding: 0;
}
.obititem {
  display: grid;
  grid-template-columns: 56px 1fr;
  gap: 14px;
  padding: 16px 0;
  border-bottom: 1px solid var(--rule-hair);
}
.obititem:first-child {
  padding-top: 0;
}
.obititem__img {
  width: 56px;
  height: 70px;
  border: 1px solid var(--rule-2);
  filter: contrast(1.03) saturate(0.85);
}
.obititem:nth-child(1) .obititem__img {
  background: linear-gradient(160deg, #5b6b6e, #2f3b3d 70%, #1c2425);
}
.obititem:nth-child(2) .obititem__img {
  background: linear-gradient(160deg, #7a6a55, #4a3d2e 70%, #2b2218);
}
.obititem:nth-child(3) .obititem__img {
  background: linear-gradient(160deg, #6f5560, #4a3540 70%, #2a1d24);
}
.obititem:nth-child(4) .obititem__img {
  background: linear-gradient(160deg, #5a5f6e, #3a3e4a 70%, #22252e);
}
.obititem__name {
  margin: 0;
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.02rem;
  line-height: 1.1;
  color: var(--ink);
}
.obititem__years {
  margin: 3px 0 6px;
  font-size: 0.74rem;
  font-style: italic;
  color: var(--muted);
}
.obititem__line {
  margin: 0 0 8px;
  font-size: 0.84rem;
  line-height: 1.45;
  color: var(--ink-2);
}
.ministem {
  font-family: var(--sans);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--red);
  background: transparent;
  border: 0;
  padding: 0;
  cursor: pointer;
  border-bottom: 1px solid var(--red-50);
}
.ministem:hover {
  border-bottom-color: var(--red);
}
.ministem:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 2px;
}
.ministem.is-lit {
  color: var(--muted);
  cursor: default;
  border-bottom-color: transparent;
}
.rail__note {
  margin: 18px 0 0;
  padding-top: 14px;
  border-top: 1px solid var(--rule);
  font-size: 0.76rem;
  font-style: italic;
  line-height: 1.5;
  color: var(--muted);
}

/* ---------- Colophon ---------- */
.colophon {
  margin-top: 36px;
  text-align: center;
}
.colophon p {
  margin: 0;
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 20px);
  background: var(--ink);
  color: var(--paper);
  font-size: 0.82rem;
  font-weight: 500;
  letter-spacing: 0.01em;
  padding: 11px 18px;
  border-radius: var(--r-sm);
  border: 1px solid var(--ink-2);
  box-shadow: 0 6px 22px rgba(22, 19, 15, 0.28);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s ease, transform 0.22s ease;
  z-index: 50;
  max-width: min(90vw, 360px);
  text-align: center;
}
.toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Responsive ---------- */
@media (max-width: 860px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .rail {
    border-top: 3px solid var(--ink);
    padding-top: 22px;
  }
}

@media (max-width: 720px) {
  .obit__body {
    columns: 1;
  }
  .metablock {
    grid-template-columns: 1fr;
    gap: 16px;
  }
}

@media (max-width: 480px) {
  .obit__head {
    grid-template-columns: 100px 1fr;
    gap: 14px;
  }
  .obit__headline {
    font-size: 1.4rem;
  }
  .share {
    margin-left: 0;
  }
}

