(function () {
  "use strict";

  /* ---------- Toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer = null;

  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("is-visible");
    window.clearTimeout(toastTimer);
    toastTimer = window.setTimeout(function () {
      toastEl.classList.remove("is-visible");
    }, 2600);
  }

  function formatCount(n) {
    return n.toLocaleString("en-US");
  }

  /* ---------- Primary "light a candle" counter ---------- */
  var candleBtn = document.getElementById("candleBtn");
  var candleCount = document.getElementById("candleCount");
  var count = 1284;
  var lit = false;

  if (candleBtn && candleCount) {
    candleBtn.addEventListener("click", function () {
      if (!lit) {
        count += 1;
        lit = true;
        candleBtn.classList.add("is-lit");
        candleBtn.querySelector(".candle__label").textContent = "Candle lit";
        candleBtn.setAttribute("aria-pressed", "true");
        candleCount.textContent = formatCount(count);
        toast("Your candle now burns for Eleanor. Thank you.");
      } else {
        count -= 1;
        lit = false;
        candleBtn.classList.remove("is-lit");
        candleBtn.querySelector(".candle__label").textContent = "Light a candle";
        candleBtn.setAttribute("aria-pressed", "false");
        candleCount.textContent = formatCount(count);
        toast("Candle dimmed.");
      }
    });
  }

  /* ---------- Compact list mini candle buttons ---------- */
  var miniBtns = document.querySelectorAll(".ministem");
  Array.prototype.forEach.call(miniBtns, function (btn) {
    btn.addEventListener("click", function () {
      if (btn.classList.contains("is-lit")) return;
      btn.classList.add("is-lit");
      btn.textContent = "Candle lit ✓";
      btn.setAttribute("aria-pressed", "true");
      var name = btn.getAttribute("data-name") || "this neighbour";
      toast("A candle was lit for " + name + ".");
    });
  });

  /* ---------- Share ---------- */
  var shareBtn = document.getElementById("shareBtn");
  if (shareBtn) {
    shareBtn.addEventListener("click", function () {
      var shareData = {
        title: "In Memoriam — Eleanor M. Whitcombe",
        text: "Remembering Eleanor M. Whitcombe (1940–2026), beloved teacher of Meridian Falls.",
        url: window.location.href
      };

      if (navigator.share) {
        navigator
          .share(shareData)
          .then(function () {
            toast("Thank you for sharing this remembrance.");
          })
          .catch(function () {
            /* user cancelled — stay quiet */
          });
        return;
      }

      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard
          .writeText(shareData.text + " " + shareData.url)
          .then(function () {
            toast("Remembrance link copied to clipboard.");
          })
          .catch(function () {
            toast("Could not copy — please copy the page link manually.");
          });
        return;
      }

      toast("Sharing is not available in this preview.");
    });
  }
})();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --sh-sm: 0 1px 2px rgba(28, 42, 37, 0.06), 0 2px 6px rgba(28, 42, 37, 0.05);
  --sh-md: 0 4px 14px rgba(28, 42, 37, 0.09), 0 12px 30px rgba(28, 42, 37, 0.07);
  --sh-lg: 0 18px 50px rgba(28, 42, 37, 0.16);
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--ivory);
  color: var(--ink);
  font-family: "Inter", system-ui, sans-serif;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1,
h2,
h3 {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
  margin: 0;
  letter-spacing: 0.01em;
}

.page {
  max-width: 1240px;
  margin: 0 auto;
  padding: clamp(22px, 4vw, 52px) clamp(16px, 3vw, 40px) 64px;
}

/* ---------- Masthead ---------- */
.masthead {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 28px;
  padding-bottom: 26px;
  margin-bottom: 30px;
  border-bottom: 1px solid var(--line);
  position: relative;
}

.masthead::after {
  content: "";
  position: absolute;
  bottom: -1px;
  left: 0;
  width: 86px;
  height: 2px;
  background: var(--brass);
}

.masthead-text {
  max-width: 620px;
}

.eyebrow {
  margin: 0 0 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--brass-d);
}

.masthead h1 {
  font-size: clamp(34px, 5vw, 52px);
  line-height: 1.04;
  color: var(--green-d);
}

.lede {
  margin: 12px 0 0;
  color: var(--ink-2);
  font-size: 15.5px;
  max-width: 56ch;
}

.masthead-stats {
  display: flex;
  gap: 14px;
}

.stat {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 20px;
  min-width: 132px;
  box-shadow: var(--sh-sm);
}

.stat.brass {
  border-color: rgba(176, 141, 87, 0.4);
  background: linear-gradient(180deg, var(--brass-50), var(--paper));
}

.stat-num {
  display: block;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 700;
  font-size: 30px;
  line-height: 1;
  color: var(--green-d);
}

.stat.brass .stat-num {
  color: var(--brass-d);
}

.stat-label {
  display: block;
  margin-top: 6px;
  font-size: 11.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- Board ---------- */
.board {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(278px, 1fr);
  gap: 18px;
  overflow-x: auto;
  padding: 4px 4px 18px;
  scroll-snap-type: x proximity;
  -webkit-overflow-scrolling: touch;
}

.column {
  background: linear-gradient(180deg, var(--paper), var(--ivory));
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  display: flex;
  flex-direction: column;
  min-height: 280px;
  scroll-snap-align: start;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}

.column.drag-over {
  border-color: var(--brass);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.16), var(--sh-md);
  background: linear-gradient(180deg, var(--brass-50), var(--paper));
}

.col-head {
  padding: 16px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.col-title-row {
  display: flex;
  align-items: center;
  gap: 9px;
}

.col-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex: none;
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.6);
}

.col-title {
  font-family: "Inter", system-ui, sans-serif;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--green-d);
  margin: 0;
}

.col-count {
  margin-left: auto;
  font-size: 12px;
  font-weight: 700;
  color: var(--green-700);
  background: var(--green-50);
  border-radius: 999px;
  padding: 2px 9px;
  min-width: 24px;
  text-align: center;
}

.col-volume {
  margin: 9px 0 0;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 20px;
  font-weight: 700;
  color: var(--brass-d);
  line-height: 1;
}

.col-volume span {
  font-family: "Inter", system-ui, sans-serif;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-left: 6px;
}

.col-body {
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
  min-height: 60px;
}

.col-empty {
  border: 1px dashed var(--line-2);
  border-radius: var(--r-md);
  padding: 22px 12px;
  text-align: center;
  font-size: 12.5px;
  color: var(--muted);
}

/* ---------- Deal card ---------- */
.deal {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  box-shadow: var(--sh-sm);
  overflow: hidden;
  cursor: grab;
  transition: transform 0.16s ease, box-shadow 0.16s ease, border-color 0.16s ease, opacity 0.16s ease;
}

.deal:hover {
  transform: translateY(-3px);
  box-shadow: var(--sh-md);
  border-color: var(--line-2);
}

.deal:active {
  cursor: grabbing;
}

.deal:focus-visible {
  outline: 2px solid var(--brass);
  outline-offset: 2px;
}

.deal.dragging {
  opacity: 0.45;
  box-shadow: var(--sh-lg);
}

.deal.selected {
  border-color: var(--brass);
  box-shadow: 0 0 0 2px rgba(176, 141, 87, 0.4), var(--sh-md);
}

.deal-thumb {
  position: relative;
  aspect-ratio: 16 / 9;
  width: 100%;
}

.deal-thumb .price-pill {
  position: absolute;
  left: 10px;
  bottom: 10px;
  background: rgba(22, 48, 42, 0.86);
  color: var(--paper);
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.01em;
  padding: 4px 11px;
  border-radius: 999px;
  backdrop-filter: blur(3px);
}

.deal-thumb .beds-pill {
  position: absolute;
  right: 10px;
  top: 10px;
  background: rgba(255, 253, 248, 0.92);
  color: var(--green-d);
  font-weight: 600;
  font-size: 11px;
  letter-spacing: 0.02em;
  padding: 3px 9px;
  border-radius: 999px;
  box-shadow: var(--sh-sm);
}

.deal-body {
  padding: 12px 13px 13px;
}

.deal-address {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 19px;
  font-weight: 600;
  line-height: 1.12;
  color: var(--green-d);
  margin: 0;
}

.deal-city {
  margin: 3px 0 0;
  font-size: 12px;
  color: var(--muted);
}

.deal-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 11px;
}

.deal-client {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  flex: none;
  display: grid;
  place-items: center;
  font-size: 10.5px;
  font-weight: 700;
  color: var(--paper);
  letter-spacing: 0.02em;
}

.client-name {
  font-size: 12.5px;
  font-weight: 500;
  color: var(--ink-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.days-badge {
  margin-left: auto;
  flex: none;
  font-size: 11px;
  font-weight: 600;
  color: var(--green-700);
  background: var(--green-50);
  border-radius: 999px;
  padding: 2px 8px;
}

.days-badge.stale {
  color: var(--danger);
  background: rgba(196, 80, 62, 0.1);
}

.checklist {
  margin-top: 12px;
}

.checklist-head {
  display: flex;
  justify-content: space-between;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 6px;
}

.checklist-head .done {
  color: var(--green-700);
}

.progress {
  height: 6px;
  border-radius: 999px;
  background: var(--green-50);
  overflow: hidden;
}

.progress > i {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--brass), var(--brass-d));
  transition: width 0.3s ease;
}

.progress.complete > i {
  background: linear-gradient(90deg, var(--ok), #1f7d56);
}

/* ---------- Simulated property photos ---------- */
.ph {
  background-color: #cdb89a;
}
.ph-1 {
  background:
    radial-gradient(120% 80% at 78% 18%, rgba(255, 244, 220, 0.9), rgba(255, 244, 220, 0) 55%),
    linear-gradient(160deg, #e8c79a 0%, #c79a64 42%, #6f5436 100%);
}
.ph-2 {
  background:
    radial-gradient(100% 70% at 22% 22%, rgba(214, 232, 240, 0.85), rgba(214, 232, 240, 0) 60%),
    linear-gradient(155deg, #9fb9bd 0%, #5f7f86 48%, #2f4b4a 100%);
}
.ph-3 {
  background:
    radial-gradient(110% 80% at 70% 80%, rgba(255, 214, 170, 0.8), rgba(255, 214, 170, 0) 58%),
    linear-gradient(150deg, #c98f6a 0%, #9a5b48 45%, #4f2f33 100%);
}
.ph-4 {
  background:
    radial-gradient(120% 80% at 30% 16%, rgba(236, 248, 224, 0.85), rgba(236, 248, 224, 0) 56%),
    linear-gradient(160deg, #aeca84 0%, #7b9159 46%, #3c5034 100%);
}
.ph-5 {
  background:
    radial-gradient(110% 80% at 80% 20%, rgba(255, 235, 235, 0.85), rgba(255, 235, 235, 0) 55%),
    linear-gradient(155deg, #d7a9ad 0%, #9a6f86 46%, #4a3a54 100%);
}
.ph-6 {
  background:
    radial-gradient(120% 80% at 20% 80%, rgba(255, 246, 214, 0.85), rgba(255, 246, 214, 0) 58%),
    linear-gradient(150deg, #e0c486 0%, #b58a45 45%, #6b4d26 100%);
}
.ph-7 {
  background:
    radial-gradient(100% 70% at 75% 25%, rgba(220, 233, 246, 0.85), rgba(220, 233, 246, 0) 60%),
    linear-gradient(160deg, #aebfd2 0%, #6f7f9b 46%, #344056 100%);
}
.ph-8 {
  background:
    radial-gradient(120% 80% at 28% 22%, rgba(255, 240, 224, 0.86), rgba(255, 240, 224, 0) 56%),
    linear-gradient(155deg, #d9b48c 0%, #a87a4f 44%, #5c3d28 100%);
}

/* ---------- Hint ---------- */
.hint {
  margin: 18px 4px 0;
  font-size: 12.5px;
  color: var(--muted);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 16px);
  background: var(--green-d);
  color: var(--paper);
  font-size: 13.5px;
  font-weight: 500;
  padding: 11px 18px;
  border-radius: 999px;
  box-shadow: var(--sh-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.24s ease, transform 0.24s ease;
  z-index: 60;
  max-width: calc(100vw - 32px);
}

.toast::before {
  content: "";
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--brass);
  margin-right: 9px;
  vertical-align: middle;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
  pointer-events: auto;
}

/* ---------- Responsive ---------- */
@media (max-width: 820px) {
  .masthead-stats {
    width: 100%;
  }
  .stat {
    flex: 1;
  }
}

@media (max-width: 520px) {
  .page {
    padding: 22px 14px 56px;
  }
  .masthead {
    gap: 18px;
  }
  .board {
    grid-auto-columns: 86%;
    gap: 14px;
  }
  .masthead-stats {
    gap: 10px;
  }
  .stat {
    min-width: 0;
    padding: 12px 14px;
  }
  .stat-num {
    font-size: 26px;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}

