(function () {
  "use strict";

  /* ---------- Toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer;
  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2400);
  }

  /* ---------- Adherence ring ---------- */
  (function ring() {
    var fill = document.getElementById("ringFill");
    var pct = 87;
    var C = 2 * Math.PI * 52; // ~326.7
    requestAnimationFrame(function () {
      fill.style.strokeDashoffset = String(C * (1 - pct / 100));
    });
    document.getElementById("ringPct").textContent = pct + "%";
  })();

  /* ---------- Chart data (12 weekly points) ---------- */
  var SERIES = {
    weight: {
      title: "Body weight",
      unit: "kg",
      color: "#c6ff3a",
      data: [86.8, 86.1, 85.4, 85.0, 84.3, 83.9, 83.4, 83.0, 82.7, 82.5, 82.3, 82.1],
      foot: function (d) {
        return [
          ["Start", d[0] + " kg"],
          ["Now", d[d.length - 1] + " kg"],
          ["Change", (d[d.length - 1] - d[0]).toFixed(1) + " kg"]
        ];
      }
    },
    bench: {
      title: "Bench press 1RM",
      unit: "kg",
      color: "#ff6a2b",
      data: [93, 94, 95, 95, 96, 98, 99, 99, 100, 101, 101, 102],
      foot: function (d) {
        return [
          ["Start", d[0] + " kg"],
          ["Now", d[d.length - 1] + " kg"],
          ["Gain", "+" + (d[d.length - 1] - d[0]) + " kg"]
        ];
      }
    },
    squat: {
      title: "Back squat 1RM",
      unit: "kg",
      color: "#34d399",
      data: [125, 127, 128, 130, 132, 133, 135, 138, 140, 141, 143, 145],
      foot: function (d) {
        return [
          ["Start", d[0] + " kg"],
          ["Now", d[d.length - 1] + " kg"],
          ["Gain", "+" + (d[d.length - 1] - d[0]) + " kg"]
        ];
      }
    }
  };

  var W = 640, H = 260, PAD_L = 44, PAD_R = 14, PAD_T = 16, PAD_B = 28;
  var svg = document.getElementById("chart");
  var titleEl = document.getElementById("chartTitle");
  var footEl = document.getElementById("chartFoot");
  var SVGNS = "http://www.w3.org/2000/svg";

  function el(name, attrs) {
    var n = document.createElementNS(SVGNS, name);
    for (var k in attrs) n.setAttribute(k, attrs[k]);
    return n;
  }

  function renderChart(key) {
    var s = SERIES[key];
    var d = s.data;
    var min = Math.min.apply(null, d);
    var max = Math.max.apply(null, d);
    var span = max - min || 1;
    // pad domain a touch
    var lo = min - span * 0.15;
    var hi = max + span * 0.15;
    var range = hi - lo;

    var innerW = W - PAD_L - PAD_R;
    var innerH = H - PAD_T - PAD_B;

    function x(i) { return PAD_L + (i / (d.length - 1)) * innerW; }
    function y(v) { return PAD_T + (1 - (v - lo) / range) * innerH; }

    svg.textContent = "";

    // horizontal gridlines + y labels
    var rows = 4;
    for (var r = 0; r <= rows; r++) {
      var gv = lo + (range * r) / rows;
      var gy = y(gv);
      svg.appendChild(el("line", { class: "chart-grid", x1: PAD_L, y1: gy, x2: W - PAD_R, y2: gy }));
      var lbl = el("text", { class: "chart-lbl", x: PAD_L - 8, y: gy + 4, "text-anchor": "end" });
      lbl.textContent = Math.round(gv);
      svg.appendChild(lbl);
    }

    // x labels (weeks)
    for (var i = 0; i < d.length; i++) {
      if (i % 2 !== 0 && i !== d.length - 1) continue;
      var t = el("text", { class: "chart-lbl", x: x(i), y: H - 8, "text-anchor": "middle" });
      t.textContent = "W" + (i + 1);
      svg.appendChild(t);
    }

    // build path
    var line = "";
    for (var j = 0; j < d.length; j++) {
      line += (j === 0 ? "M" : "L") + x(j).toFixed(1) + " " + y(d[j]).toFixed(1) + " ";
    }
    var area = line + "L" + x(d.length - 1).toFixed(1) + " " + (H - PAD_B) + " L" + PAD_L + " " + (H - PAD_B) + " Z";

    // gradient fill
    var defs = el("defs", {});
    var grad = el("linearGradient", { id: "g_" + key, x1: 0, y1: 0, x2: 0, y2: 1 });
    grad.appendChild(el("stop", { offset: "0%", "stop-color": s.color, "stop-opacity": "0.28" }));
    grad.appendChild(el("stop", { offset: "100%", "stop-color": s.color, "stop-opacity": "0" }));
    defs.appendChild(grad);
    svg.appendChild(defs);

    svg.appendChild(el("path", { class: "chart-area", d: area, fill: "url(#g_" + key + ")" }));
    svg.appendChild(el("path", { class: "chart-line", d: line, stroke: s.color }));

    // dots
    for (var p = 0; p < d.length; p++) {
      var dot = el("circle", { class: "chart-dot", cx: x(p), cy: y(d[p]), r: 3.5, fill: s.color });
      var tt = el("title", {});
      tt.textContent = "Week " + (p + 1) + ": " + d[p] + " " + s.unit;
      dot.appendChild(tt);
      svg.appendChild(dot);
    }

    titleEl.textContent = s.title;
    svg.setAttribute("aria-label", s.title + " over 12 weeks");

    // footer stats
    footEl.textContent = "";
    s.foot(d).forEach(function (pair) {
      var span2 = document.createElement("span");
      span2.innerHTML = pair[0] + " <b>" + pair[1] + "</b>";
      footEl.appendChild(span2);
    });
  }

  var tabs = Array.prototype.slice.call(document.querySelectorAll(".tab"));
  tabs.forEach(function (tab) {
    tab.addEventListener("click", function () {
      tabs.forEach(function (t) {
        t.classList.remove("is-active");
        t.setAttribute("aria-selected", "false");
      });
      tab.classList.add("is-active");
      tab.setAttribute("aria-selected", "true");
      renderChart(tab.dataset.metric);
    });
  });
  renderChart("weight");

  /* ---------- Attendance heat strip (12 weeks × 3 sessions) ---------- */
  (function heat() {
    var grid = document.getElementById("heat");
    // value 0-3 sessions attended that week
    var weeks = [3, 3, 2, 3, 3, 3, 1, 3, 3, 2, 3, 3];
    var labels = ["No sessions", "1 of 3 sessions", "2 of 3 sessions", "Full week — 3/3"];
    weeks.forEach(function (v, idx) {
      var c = document.createElement("div");
      c.className = "cell l" + v;
      c.setAttribute("role", "img");
      c.setAttribute("title", "Week " + (idx + 1) + ": " + labels[v]);
      c.setAttribute("aria-label", "Week " + (idx + 1) + ", " + labels[v]);
      grid.appendChild(c);
    });
  })();

  /* ---------- Notes timeline ---------- */
  var timeline = document.getElementById("timeline");
  var seed = [
    { tag: "training", time: "2 days ago", body: "Bumped bench to 3×6 @ 92.5 kg — bar speed strong, added a back-off set." },
    { tag: "nutrition", time: "5 days ago", body: "Protein dialed to 180g/day. Reports better gym energy on training days." },
    { tag: "recovery", time: "1 week ago", body: "Right shoulder a little cranky — swapped flat for slight incline, cued scap retraction." },
    { tag: "flag", time: "2 weeks ago", body: "Missed Wed session (travel). Adjusted week to 2 sessions, kept volume." }
  ];

  function tagLabel(t) {
    return { training: "Training", nutrition: "Nutrition", recovery: "Recovery", flag: "Flag" }[t] || t;
  }

  function makeNote(n, isNew) {
    var li = document.createElement("li");
    li.className = "note" + (isNew ? " is-new" : "");
    var top = document.createElement("div");
    top.className = "note__top";
    var tag = document.createElement("span");
    tag.className = "note__tag t-" + n.tag;
    tag.textContent = tagLabel(n.tag);
    var time = document.createElement("span");
    time.className = "note__time";
    time.textContent = n.time;
    top.appendChild(tag);
    top.appendChild(time);
    var body = document.createElement("p");
    body.className = "note__body";
    body.textContent = n.body;
    li.appendChild(top);
    li.appendChild(body);
    return li;
  }

  seed.forEach(function (n) { timeline.appendChild(makeNote(n, false)); });

  /* ---------- Composer ---------- */
  var composer = document.getElementById("composer");
  var noteInput = document.getElementById("noteInput");
  var noteTag = document.getElementById("noteTag");

  function showComposer() {
    composer.hidden = false;
    noteInput.focus();
  }
  function hideComposer() {
    composer.hidden = true;
    noteInput.value = "";
    noteTag.value = "training";
  }

  document.getElementById("openNote").addEventListener("click", showComposer);
  document.getElementById("openNote2").addEventListener("click", showComposer);
  document.getElementById("cancelNote").addEventListener("click", hideComposer);

  composer.addEventListener("submit", function (e) {
    e.preventDefault();
    var text = noteInput.value.trim();
    if (!text) {
      noteInput.focus();
      toast("Write something first");
      return;
    }
    var li = makeNote({ tag: noteTag.value, time: "Just now", body: text }, true);
    timeline.insertBefore(li, timeline.firstChild);
    hideComposer();
    toast("Note added to timeline");
  });

  /* ---------- Send program ---------- */
  document.getElementById("sendProgram").addEventListener("click", function () {
    var btn = this;
    var orig = btn.textContent;
    btn.disabled = true;
    btn.textContent = "Sending…";
    setTimeout(function () {
      btn.textContent = "Sent ✓";
      toast("Week 13 program sent to Marcus");
      setTimeout(function () {
        btn.textContent = orig;
        btn.disabled = false;
      }, 1600);
    }, 700);
  });
})();

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --pending: #6b7280;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

/* ── Layout ── */
.tracker {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 32px 20px;
}
.card {
  width: 100%;
  max-width: 460px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-1);
  padding: 24px 24px 22px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ── Header ── */
.card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}
.eyebrow {
  font-size: 0.74rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--teal-d);
}
.card-head h1 {
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin: 3px 0 2px;
}
.sub {
  color: var(--muted);
  font-size: 0.86rem;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border-radius: 999px;
  padding: 6px 12px;
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
  background: var(--teal-50);
  color: var(--teal-d);
}
.sp-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: currentColor;
}
.status-pill.is-prep {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.status-pill.is-out {
  background: var(--coral-soft);
  color: var(--danger);
}
.status-pill.is-done {
  background: rgba(47, 158, 111, 0.16);
  color: var(--ok);
}

/* ── Stepper ── */
.stepper {
  list-style: none;
  display: flex;
  flex-direction: column;
}
.step {
  position: relative;
  display: grid;
  grid-template-columns: 26px 1fr;
  column-gap: 14px;
  padding-bottom: 22px;
}
.step:last-child {
  padding-bottom: 0;
}
.step-rail {
  position: absolute;
  left: 12px;
  top: 24px;
  bottom: 0;
  width: 2px;
  background: var(--line-2);
}
.step:last-child .step-rail {
  display: none;
}
.step-marker {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: 2px solid var(--line-2);
  background: var(--white);
  display: grid;
  place-items: center;
  position: relative;
  z-index: 1;
  transition: background 0.2s, border-color 0.2s;
}
.step-title {
  font-weight: 600;
  font-size: 0.94rem;
  color: var(--muted);
  transition: color 0.2s;
}
.step-desc {
  font-size: 0.82rem;
  color: var(--muted);
  margin-top: 2px;
}
.step-time {
  font-size: 0.76rem;
  font-weight: 600;
  color: var(--ok);
  margin-top: 5px;
}

/* completed */
.step.is-complete .step-rail {
  background: var(--teal);
}
.step.is-complete .step-marker {
  background: var(--teal);
  border-color: var(--teal);
}
.step.is-complete .step-marker::after {
  content: "✓";
  color: #fff;
  font-size: 0.78rem;
  font-weight: 700;
}
.step.is-complete .step-title {
  color: var(--ink);
}

/* current */
.step.is-current .step-marker {
  border-color: var(--coral);
  background: var(--coral-soft);
}
.step.is-current .step-marker::after {
  content: "";
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--coral);
  animation: pulse 1.4s ease-in-out infinite;
}
.step.is-current .step-title {
  color: var(--ink);
  font-weight: 700;
}

@keyframes pulse {
  0%,
  100% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(255, 122, 102, 0.5);
  }
  50% {
    transform: scale(1.15);
    box-shadow: 0 0 0 6px rgba(255, 122, 102, 0);
  }
}

/* ── ETA ── */
.eta {
  display: flex;
  align-items: center;
  gap: 14px;
  background: linear-gradient(135deg, var(--teal-d), var(--teal-700));
  color: #fff;
  border-radius: var(--r-md);
  padding: 16px 18px;
}
.eta.is-done {
  background: linear-gradient(135deg, #0f7a5a, #0b6149);
}
.eta-ic {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.18);
  font-size: 1.2rem;
}
.eta-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  opacity: 0.82;
  font-weight: 600;
}
.eta-value {
  font-size: 1.02rem;
  font-weight: 700;
  margin-top: 2px;
}

/* ── Courier ── */
.courier {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 13px 14px;
}
.courier-avatar {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--coral);
  color: #fff;
  font-weight: 700;
  font-size: 0.82rem;
}
.courier-info {
  flex: 1;
  min-width: 0;
}
.courier-name {
  font-weight: 600;
  font-size: 0.92rem;
}
.courier-meta {
  font-size: 0.8rem;
  color: var(--muted);
  margin-top: 1px;
}

/* ── Items ── */
.section-h {
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.item-list {
  list-style: none;
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 0;
  border-bottom: 1px solid var(--line);
}
.item:last-child {
  border-bottom: none;
}
.i-name {
  font-weight: 600;
  font-size: 0.88rem;
}
.i-qty {
  font-size: 0.82rem;
  color: var(--muted);
  white-space: nowrap;
}
.address {
  margin-top: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--teal-50);
  border-radius: var(--r-sm);
  padding: 10px 12px;
  font-size: 0.84rem;
  font-weight: 500;
  color: var(--ink-2);
}
.addr-ic {
  color: var(--teal-d);
  font-size: 1rem;
}

/* ── Buttons ── */
.btn {
  border: none;
  border-radius: 11px;
  padding: 12px 16px;
  font: inherit;
  font-weight: 600;
  font-size: 0.9rem;
  cursor: pointer;
  transition: transform 0.12s, background 0.15s, opacity 0.15s;
}
.btn:active {
  transform: translateY(1px);
}
.btn.primary {
  background: var(--coral);
  color: #fff;
}
.btn.primary:hover {
  background: #ff8e7c;
}
.btn.primary:disabled {
  background: rgba(47, 158, 111, 0.16);
  color: var(--ok);
  cursor: default;
}
.btn.ghost {
  flex-shrink: 0;
  padding: 8px 13px;
  font-size: 0.82rem;
  background: var(--teal-50);
  color: var(--teal-d);
}
.btn.ghost:hover {
  background: #d6ece9;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}

@media (max-width: 480px) {
  .card {
    padding: 20px 18px;
  }
  .card-head {
    flex-direction: column;
  }
}

