:root {
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --sh-sm: 0 1px 2px rgba(28, 24, 20, 0.05), 0 1px 0 rgba(255, 255, 255, 0.6) inset;
  --sh-md: 0 6px 22px -10px rgba(28, 24, 20, 0.28);
  --sh-lg: 0 24px 60px -28px rgba(28, 24, 20, 0.4);

  /* service colours */
  --svc-color: #b07ca0;
  --svc-color-soft: #f3e2ec;
  --svc-cut: #6f93a8;
  --svc-cut-soft: #e1ecf1;
  --svc-treatment: #8aa57b;
  --svc-treatment-soft: #e6efdf;
  --svc-break: var(--muted);
  --svc-break-soft: rgba(138, 125, 112, 0.12);
}

* {
  box-sizing: border-box;
}

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  margin: 0;
  font-family: var(--sans);
  line-height: 1.5;
  color: var(--ink);
  background: var(--bg);
  background-image:
    radial-gradient(900px 500px at 88% -6%, rgba(176, 141, 87, 0.08), transparent 60%),
    radial-gradient(700px 460px at -4% 4%, rgba(201, 167, 143, 0.1), transparent 62%);
}

h1, h2, h3 {
  font-family: var(--serif);
  margin: 0;
  letter-spacing: 0.01em;
}

.app {
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(16px, 3vw, 34px);
}

/* ---------- Top bar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand__mark {
  display: grid;
  place-items: center;
  width: 50px;
  height: 50px;
  border-radius: 50%;
  font-family: var(--serif);
  font-weight: 700;
  font-size: 18px;
  letter-spacing: 0.04em;
  color: var(--white);
  background: linear-gradient(150deg, var(--gold), var(--gold-d));
  box-shadow: var(--sh-md), 0 0 0 4px var(--gold-soft);
}

.brand__eyebrow {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold-d);
}

.brand__title {
  font-size: clamp(24px, 3.4vw, 32px);
  font-weight: 600;
  line-height: 1.1;
  color: var(--ink);
}

.stylist {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 14px 8px 8px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  box-shadow: var(--sh-sm);
}

.stylist__avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid var(--gold-soft);
}

.stylist__name {
  margin: 0;
  font-weight: 600;
  font-size: 14px;
}

.stylist__role {
  margin: 0;
  font-size: 11.5px;
  color: var(--muted);
}

.stylist__status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: 4px;
  padding: 5px 11px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--ok);
  background: rgba(95, 138, 107, 0.1);
  border-radius: 999px;
}

.stylist__status .dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 3px rgba(95, 138, 107, 0.2);
}

/* ---------- Date strip ---------- */
.datestrip {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 22px 0 24px;
}

.datestrip__nav {
  flex: none;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink-2);
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  transition: background 0.18s, border-color 0.18s, transform 0.1s;
}

.datestrip__nav:hover {
  background: var(--cream);
  border-color: var(--gold);
  color: var(--gold-d);
}

.datestrip__nav:active {
  transform: scale(0.94);
}

.datestrip__list {
  display: flex;
  gap: 8px;
  list-style: none;
  margin: 0;
  padding: 4px;
  overflow-x: auto;
  flex: 1;
  scrollbar-width: thin;
}

.day {
  flex: 1 0 auto;
  min-width: 68px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 10px 6px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--white);
  cursor: pointer;
  color: var(--ink-2);
  font-family: var(--sans);
  transition: border-color 0.18s, background 0.18s, transform 0.12s, box-shadow 0.18s;
}

.day:hover {
  border-color: var(--rose);
  transform: translateY(-2px);
  box-shadow: var(--sh-sm);
}

.day__dow {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

.day__num {
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 600;
  line-height: 1;
}

.day__count {
  font-size: 10.5px;
  color: var(--gold-d);
  font-weight: 600;
}

.day[aria-selected="true"] {
  background: linear-gradient(160deg, var(--ink), var(--ink-2));
  border-color: var(--ink);
  color: var(--white);
  box-shadow: var(--sh-md);
}

.day[aria-selected="true"] .day__dow,
.day[aria-selected="true"] .day__count {
  color: var(--gold-soft);
}

.day--today .day__num::after {
  content: "";
  display: block;
  width: 5px;
  height: 5px;
  margin: 3px auto 0;
  border-radius: 50%;
  background: var(--gold);
}

/* ---------- Layout ---------- */
.layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 22px;
  align-items: start;
}

/* ---------- Timeline ---------- */
.timeline-wrap {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-md);
  overflow: hidden;
}

.timeline-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding: 18px 22px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(var(--white), var(--cream));
}

.timeline-head__date {
  font-size: 21px;
  font-weight: 600;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  list-style: none;
  margin: 0;
  padding: 0;
  font-size: 12px;
  color: var(--ink-2);
}

.legend li {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.swatch {
  width: 12px;
  height: 12px;
  border-radius: 4px;
}

.swatch[data-svc="color"] { background: var(--svc-color); }
.swatch[data-svc="cut"] { background: var(--svc-cut); }
.swatch[data-svc="treatment"] { background: var(--svc-treatment); }
.swatch[data-svc="break"] {
  background: repeating-linear-gradient(45deg, var(--svc-break), var(--svc-break) 3px, transparent 3px, transparent 6px);
  background-color: var(--svc-break-soft);
}

.timeline {
  position: relative;
  --axis-w: 64px;
  --hour-h: 84px;
  height: 560px;
  overflow-y: auto;
  padding: 8px 0;
  scrollbar-width: thin;
}

.timeline__axis,
.timeline__grid,
.timeline__blocks {
  position: relative;
}

.timeline__axis {
  position: absolute;
  inset: 8px auto 8px 0;
  width: var(--axis-w);
}

.axis-hour {
  position: absolute;
  left: 0;
  right: 0;
  height: var(--hour-h);
  padding-top: 2px;
  text-align: right;
  padding-right: 12px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: var(--muted);
  transform: translateY(-7px);
}

.timeline__grid {
  position: absolute;
  inset: 8px 16px 8px var(--axis-w);
}

.grid-line {
  position: absolute;
  left: 0;
  right: 0;
  border-top: 1px solid var(--line);
}

.grid-line--half {
  border-top: 1px dashed rgba(28, 24, 20, 0.06);
}

.timeline__blocks {
  position: absolute;
  inset: 8px 16px 8px var(--axis-w);
}

.block {
  position: absolute;
  left: 0;
  right: 0;
  border-radius: var(--r-md);
  border: 1px solid var(--line);
  padding: 9px 13px;
  overflow: hidden;
  cursor: pointer;
  text-align: left;
  font-family: var(--sans);
  background: var(--white);
  box-shadow: var(--sh-sm);
  transition: transform 0.14s, box-shadow 0.18s, filter 0.18s;
}

.block::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
}

.block:hover {
  transform: translateX(2px);
  box-shadow: var(--sh-md);
  filter: saturate(1.05);
  z-index: 3;
}

.block:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.block.is-active {
  box-shadow: 0 0 0 2px var(--gold), var(--sh-md);
  z-index: 4;
}

.block__time {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--ink-2);
}

.block__client {
  margin: 1px 0 0;
  font-family: var(--serif);
  font-size: 17px;
  font-weight: 600;
  line-height: 1.15;
  color: var(--ink);
}

.block__svc {
  margin: 1px 0 0;
  font-size: 12px;
  color: var(--ink-2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.block[data-svc="color"] { background: var(--svc-color-soft); }
.block[data-svc="color"]::before { background: var(--svc-color); }
.block[data-svc="cut"] { background: var(--svc-cut-soft); }
.block[data-svc="cut"]::before { background: var(--svc-cut); }
.block[data-svc="treatment"] { background: var(--svc-treatment-soft); }
.block[data-svc="treatment"]::before { background: var(--svc-treatment); }

/* break / blocked */
.block--break {
  background:
    repeating-linear-gradient(45deg, rgba(138, 125, 112, 0.1), rgba(138, 125, 112, 0.1) 6px, transparent 6px, transparent 13px),
    var(--svc-break-soft);
  cursor: default;
}

.block--break::before { background: var(--muted); }

.block--break .block__client {
  font-style: italic;
  color: var(--ink-2);
  font-size: 15px;
}

.block--compact {
  padding: 6px 13px;
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.block--compact .block__client {
  font-size: 14px;
  margin: 0;
}

.block--compact .block__svc { display: none; }

/* open gap */
.gap {
  position: absolute;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px dashed var(--line-2);
  border-radius: var(--r-md);
  background: transparent;
  color: var(--muted);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  font-family: var(--sans);
  transition: background 0.18s, border-color 0.18s, color 0.18s;
}

.gap:hover {
  background: var(--gold-soft);
  border-color: var(--gold);
  color: var(--gold-d);
}

.gap:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.gap__plus {
  margin-right: 6px;
  font-weight: 700;
  font-size: 14px;
}

/* now line */
.nowline {
  position: absolute;
  left: var(--axis-w);
  right: 16px;
  height: 0;
  border-top: 2px solid var(--danger);
  z-index: 5;
  pointer-events: none;
}

.nowline span {
  position: absolute;
  left: 0;
  top: -9px;
  transform: translateX(-100%);
  margin-left: -6px;
  padding: 1px 7px;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--white);
  background: var(--danger);
  border-radius: 999px;
}

/* ---------- Side ---------- */
.side {
  display: flex;
  flex-direction: column;
  gap: 18px;
  position: sticky;
  top: 18px;
}

.side__title {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--gold-d);
  margin-bottom: 14px;
  font-family: var(--sans);
}

.summary,
.detail {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-md);
  padding: 20px;
}

.summary__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.stat {
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--cream);
}

.stat--wide {
  grid-column: 1 / -1;
  background: var(--white);
}

.stat__label {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.stat__value {
  margin: 4px 0 0;
  font-family: var(--serif);
  font-size: 28px;
  font-weight: 700;
  line-height: 1;
  color: var(--ink);
}

.stat__value span {
  font-size: 16px;
  color: var(--muted);
  margin-left: 1px;
}

.stat__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.stat__pct {
  margin: 0;
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 700;
  color: var(--gold-d);
}

.meter {
  margin: 10px 0 8px;
  height: 9px;
  border-radius: 999px;
  background: var(--gold-soft);
  overflow: hidden;
}

.meter__fill {
  display: block;
  height: 100%;
  width: 0;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--rose), var(--gold));
  transition: width 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.stat__sub {
  margin: 0;
  font-size: 11.5px;
  color: var(--muted);
}

/* detail card */
.detail__empty {
  text-align: center;
  color: var(--muted);
  font-size: 13.5px;
  padding: 18px 8px;
}

.detail__icon {
  display: block;
  font-size: 26px;
  color: var(--gold);
  margin-bottom: 10px;
}

.detail__card .dc-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 11px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: capitalize;
}

.dc-tag[data-svc="color"] { background: var(--svc-color-soft); color: #7c4f6c; }
.dc-tag[data-svc="cut"] { background: var(--svc-cut-soft); color: #3f5f73; }
.dc-tag[data-svc="treatment"] { background: var(--svc-treatment-soft); color: #4c6640; }

.dc-client {
  margin: 12px 0 2px;
  font-family: var(--serif);
  font-size: 26px;
  font-weight: 600;
  line-height: 1.1;
}

.dc-time {
  margin: 0 0 16px;
  font-size: 13px;
  color: var(--muted);
}

.dc-meta {
  list-style: none;
  margin: 0 0 16px;
  padding: 16px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  display: grid;
  gap: 11px;
}

.dc-meta li {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  font-size: 13.5px;
}

.dc-meta .k {
  color: var(--muted);
  font-size: 12px;
  letter-spacing: 0.03em;
}

.dc-meta .v {
  font-weight: 600;
  color: var(--ink);
  text-align: right;
}

.dc-meta .v--price {
  font-family: var(--serif);
  font-size: 18px;
  color: var(--gold-d);
}

.dc-notes {
  font-size: 13px;
  color: var(--ink-2);
  line-height: 1.55;
}

.dc-notes strong {
  display: block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 4px;
}

.dc-actions {
  display: flex;
  gap: 10px;
  margin-top: 18px;
}

.btn {
  flex: 1;
  padding: 10px 14px;
  border-radius: var(--r-sm);
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink-2);
  transition: background 0.16s, border-color 0.16s, transform 0.1s, color 0.16s;
}

.btn:hover {
  background: var(--cream);
  border-color: var(--gold);
}

.btn:active { transform: scale(0.97); }

.btn--primary {
  background: linear-gradient(155deg, var(--gold), var(--gold-d));
  border-color: var(--gold-d);
  color: var(--white);
  box-shadow: var(--sh-sm);
}

.btn--primary:hover {
  filter: brightness(1.06);
  background: linear-gradient(155deg, var(--gold), var(--gold-d));
}

.btn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 26px);
  background: var(--ink);
  color: var(--cream);
  padding: 12px 20px;
  border-radius: 999px;
  font-size: 13.5px;
  font-weight: 500;
  box-shadow: var(--sh-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.28s, transform 0.28s;
  z-index: 50;
  max-width: 90vw;
}

.toast::before {
  content: "✦";
  color: var(--gold);
  margin-right: 8px;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Responsive ---------- */
@media (max-width: 900px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .side {
    position: static;
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: start;
  }
}

@media (max-width: 520px) {
  .topbar {
    flex-direction: column;
    align-items: flex-start;
  }
  .stylist {
    width: 100%;
  }
  .side {
    grid-template-columns: 1fr;
  }
  .summary__grid {
    grid-template-columns: 1fr 1fr;
  }
  .timeline {
    --axis-w: 52px;
    --hour-h: 78px;
    height: 480px;
  }
  .block__client {
    font-size: 15px;
  }
  .legend {
    gap: 10px;
    font-size: 11px;
  }
  .timeline-head {
    padding: 14px 16px;
  }
  .day {
    min-width: 58px;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

