let activities = [
  { name: "Grand Via stay · 3 nights", date: "09 Jun 2026", pts: +1850, id: "a1" },
  { name: "Spa treatment", date: "07 Jun 2026", pts: +220, id: "a2" },
  { name: "Room service", date: "06 Jun 2026", pts: +75, id: "a3" },
  { name: "Palermo stay · 2 nights", date: "28 May 2026", pts: +1230, id: "a4" },
  { name: "Points redemption", date: "20 May 2026", pts: -500, id: "a5" },
];

// ── Render card ──
function renderCard() {
  const tier = TIERS[currentTier];
  const card = $("loyaltyCard");
  card.dataset.tier = currentTier;
  $("tierBadge").textContent = tier.label;
  $("pointsBal").textContent = fmtPts(points);
}

// ── Render progress ──
function renderProgress() {
  const tier = TIERS[currentTier];

  if (!tier.nextTier) {
    // Max tier reached
    $("progLabel").textContent = "Maximum tier reached";
    $("progPct").textContent = "100%";
    $("progressFill").style.width = "100%";
    $("nightsLeft").textContent = "All benefits unlocked";
    $("pointsLeft").textContent = "";
    return;
  }

  const rangeBottom = tier.threshold;
  const rangeTop = tier.nextThreshold;
  const progress = Math.min(1, Math.max(0, (points - rangeBottom) / (rangeTop - rangeBottom)));
  const pct = Math.round(progress * 100);
  const ptsLeft = Math.max(0, rangeTop - points);
  const nightsLeft = Math.max(
    0,
    tier.stays_for_next - Math.floor((points - rangeBottom) / (POINTS_PER_STAY / 3))
  );

  $("progLabel").textContent = `Progress to ${tier.nextLabel}`;
  $("progPct").textContent = `${pct}%`;
  $("progressFill").style.width = `${pct}%`;
  const prog = document.querySelector(".progress-track");
  if (prog) {
    prog.setAttribute("aria-valuenow", pct);
  }
  $("nightsLeft").textContent =
    nightsLeft > 0
      ? `${nightsLeft} night${nightsLeft !== 1 ? "s" : ""} to go`
      : "Promotion imminent!";
  $("pointsLeft").textContent = ptsLeft > 0 ? `${fmtPts(ptsLeft)} pts needed` : "Threshold reached";
}

// ── Render benefits ──
function renderBenefits() {
  const tier = TIERS[currentTier];
  $("benefitsList").innerHTML = tier.benefits.map((b) => `<li>${b}</li>`).join("");
}

// ── Render activity ──
function renderActivity() {
  $("activityList").innerHTML = activities
    .slice(0, 5)
    .map(
      (a) => `
      <li class="activity-item">
        <div class="ai-info">
          <span class="ai-name">${a.name}</span>
          <span class="ai-date">${a.date}</span>
        </div>
        <span class="ai-pts ${a.pts > 0 ? "positive" : "negative"}">${a.pts > 0 ? "+" : ""}${fmtPts(a.pts)} pts</span>
      </li>`
    )
    .join("");
}

// ── Full render ──
function render() {
  renderCard();
  renderProgress();
  renderBenefits();
  renderActivity();
}

// ── Tier switcher ──
document.querySelectorAll(".ts-btn").forEach((btn) => {
  btn.addEventListener("click", () => {
    const targetTier = btn.dataset.tier;
    // Update button state
    document.querySelectorAll(".ts-btn").forEach((b) => b.classList.remove("is-active"));
    btn.classList.add("is-active");
    // Set points to midpoint of tier range for demonstration
    currentTier = targetTier;
    const tier = TIERS[targetTier];
    if (targetTier === "silver") {
      points = 14500;
    } else if (targetTier === "gold") {
      points = 18450;
    } else {
      points = 52000;
    }
    render();
    showToast(`Viewing ${tier.label} tier — ${fmtPts(points)} pts`);
  });
});

// ── Simulate a stay ──
$("simulateBtn").addEventListener("click", () => {
  const btn = $("simulateBtn");
  btn.disabled = true;

  const added = POINTS_PER_STAY;
  points += added;

  // Add new activity
  const today = "09 Jun 2026";
  activities.unshift({
    name: "Simulated stay · 3 nights",
    date: today,
    pts: added,
    id: `sim${Date.now()}`,
  });

  // Check for promotion
  const tier = TIERS[currentTier];
  if (tier.nextTier && points >= tier.nextThreshold) {
    const oldLabel = tier.label;
    currentTier = tier.nextTier;
    // Update switcher button
    document.querySelectorAll(".ts-btn").forEach((b) => {
      b.classList.toggle("is-active", b.dataset.tier === currentTier);
    });
    render();
    showToast(`🎉 Congratulations! Promoted from ${oldLabel} to ${TIERS[currentTier].label}!`);
  } else {
    render();
    showToast(`+${fmtPts(added)} pts added — ${fmtPts(points)} total`);
  }

  setTimeout(() => (btn.disabled = false), 800);
});

// ── Init ──
render();

snippets.css:
:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --sh-1: 0 1px 2px rgba(0, 0, 0, 0.4);
  --sh-2: 0 8px 24px rgba(0, 0, 0, 0.45);
  --sh-3: 0 18px 48px rgba(0, 0, 0, 0.55);
}

* { box-sizing: border-box; }

html, body { margin: 0; padding: 0; }

body {
  background:
    radial-gradient(1200px 600px at 85% -10%, rgba(198, 255, 58, 0.07), transparent 60%),
    radial-gradient(900px 500px at -5% 110%, rgba(255, 106, 43, 0.06), transparent 55%),
    var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
}

.app {
  max-width: 1180px;
  margin: 0 auto;
  padding: 22px 22px 48px;
}

.eyebrow {
  margin: 0;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- Topbar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding: 14px 18px;
  background: linear-gradient(180deg, var(--surface), var(--surface-2));
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-2);
}

.brand { display: flex; align-items: center; gap: 14px; }

.logo {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: var(--neon);
  color: #0a0c0e;
  font-weight: 900;
  font-size: 18px;
  letter-spacing: -0.02em;
  box-shadow: 0 0 0 1px var(--neon-d), 0 8px 20px rgba(198, 255, 58, 0.25);
}

.brand h1 {
  margin: 2px 0 0;
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.topbar-actions { display: flex; align-items: center; gap: 12px; }

.clock {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  font-size: 15px;
  color: var(--ink-2);
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  background: var(--surface-2);
}

.btn {
  font-family: inherit;
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.02em;
  cursor: pointer;
  border-radius: var(--r-md);
  padding: 11px 16px;
  border: 1px solid var(--line-2);
  transition: transform 0.08s ease, background 0.18s ease, border-color 0.18s ease;
}

.btn:focus-visible {
  outline: 3px solid var(--neon);
  outline-offset: 2px;
}

.btn:active { transform: translateY(1px); }

.btn-ghost {
  background: var(--surface-2);
  color: var(--ink);
  display: inline-flex;
  align-items: center;
  gap: 9px;
}

.btn-ghost:hover { border-color: var(--neon); color: var(--ink); }

.btn-ghost[aria-pressed="true"] {
  background: var(--orange-soft);
  border-color: var(--orange);
  color: #ffd7c4;
}

.dot-live {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--muted);
  box-shadow: 0 0 0 0 rgba(255, 106, 43, 0.5);
}

.btn-ghost[aria-pressed="true"] .dot-live {
  background: var(--orange);
  animation: pulse 1.4s infinite;
}

@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(255, 106, 43, 0.5); }
  70% { box-shadow: 0 0 0 8px rgba(255, 106, 43, 0); }
  100% { box-shadow: 0 0 0 0 rgba(255, 106, 43, 0); }
}

/* ---------- Layout ---------- */
.layout {
  display: grid;
  grid-template-columns: 1.55fr 1fr;
  gap: 18px;
  margin-top: 18px;
}

.map-wrap {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 18px;
  box-shadow: var(--sh-2);
}

.map-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 14px;
}

.map-head h2 { margin: 0; font-size: 17px; font-weight: 800; letter-spacing: -0.01em; }
.hint { font-size: 12px; color: var(--muted); }

/* ---------- Floor grid ---------- */
.floor {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(4, minmax(72px, 1fr));
  grid-template-areas:
    "fw fw mc mc"
    "fw fw mc mc"
    "rg cd cd st"
    "lk en cd st";
}

.zone, .zone-static {
  position: relative;
  border-radius: var(--r-md);
  border: 1px solid var(--line-2);
  background: var(--surface-2);
  color: var(--ink);
  padding: 12px 14px;
  text-align: left;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 6px;
  overflow: hidden;
  min-height: 0;
}

.zone {
  font-family: inherit;
  cursor: pointer;
  transition: transform 0.1s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.zone::before {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0.16;
  background: var(--occ, var(--muted));
  transition: opacity 0.25s ease;
}

.zone > * { position: relative; z-index: 1; }

.zone:hover { transform: translateY(-2px); box-shadow: var(--sh-2); }
.zone:hover::before { opacity: 0.26; }

.zone:focus-visible {
  outline: 3px solid var(--neon);
  outline-offset: 2px;
}

.zone[aria-pressed="true"] {
  border-color: var(--neon);
  box-shadow: 0 0 0 1px var(--neon), var(--sh-2);
}

.zone[data-occ="quiet"] { --occ: var(--ok); }
.zone[data-occ="moderate"] { --occ: var(--warn); }
.zone[data-occ="busy"] { --occ: var(--danger); }

.zone-tag {
  font-weight: 800;
  font-size: 13px;
  letter-spacing: -0.01em;
}

.zone-meta {
  font-size: 11px;
  font-weight: 600;
  color: var(--ink-2);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.zone-pulse {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--occ, var(--muted));
  box-shadow: 0 0 10px var(--occ, var(--muted));
  z-index: 2;
}

.zone-static.entrance {
  background: repeating-linear-gradient(
    45deg,
    rgba(255, 255, 255, 0.03),
    rgba(255, 255, 255, 0.03) 8px,
    transparent 8px,
    transparent 16px
  );
  border-style: dashed;
  align-items: center;
  justify-content: center;
}

.entrance .zone-tag {
  color: var(--muted);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

/* ---------- Legend ---------- */
.legend {
  display: flex;
  gap: 18px;
  flex-wrap: wrap;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}

.leg {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 600;
  color: var(--ink-2);
}

.leg i { width: 12px; height: 12px; border-radius: 4px; display: inline-block; }
.leg-quiet i { background: var(--ok); }
.leg-moderate i { background: var(--warn); }
.leg-busy i { background: var(--danger); }

/* ---------- Side ---------- */
.side { display: flex; flex-direction: column; gap: 18px; }

.gauge-card, .panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 18px;
  box-shadow: var(--sh-2);
}

.gauge {
  position: relative;
  width: 168px;
  height: 168px;
  margin: 12px auto 6px;
}

.gauge-svg { width: 100%; height: 100%; transform: rotate(-90deg); }

.g-track {
  fill: none;
  stroke: var(--elevated);
  stroke-width: 11;
}

.g-fill {
  fill: none;
  stroke: var(--neon);
  stroke-width: 11;
  stroke-linecap: round;
  stroke-dasharray: 326.7;
  stroke-dashoffset: 326.7;
  transition: stroke-dashoffset 0.7s cubic-bezier(0.4, 0, 0.2, 1), stroke 0.4s ease;
}

.gauge-center {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  text-align: center;
}

.gauge-center strong {
  display: block;
  font-size: 34px;
  font-weight: 900;
  letter-spacing: -0.03em;
}

.gauge-center span {
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.gauge-label {
  margin: 4px 0 0;
  text-align: center;
  font-size: 13px;
  font-weight: 700;
  color: var(--ink-2);
}

/* ---------- Panel ---------- */
.panel { flex: 1; min-height: 280px; }

.panel-empty {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  text-align: center;
  color: var(--muted);
  padding: 24px 8px;
}

.ghost {
  font-size: 38px;
  color: var(--elevated);
}

.panel-empty p { margin: 0; font-size: 13px; max-width: 220px; }

.panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.panel-head h3 { margin: 3px 0 0; font-size: 19px; font-weight: 800; letter-spacing: -0.02em; }

.badge {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 6px 11px;
  border-radius: 999px;
  border: 1px solid var(--line-2);
  white-space: nowrap;
}

.badge[data-occ="quiet"] { background: rgba(52, 211, 153, 0.14); color: #6ee7b7; border-color: rgba(52, 211, 153, 0.4); }
.badge[data-occ="moderate"] { background: rgba(251, 191, 36, 0.14); color: #fcd34d; border-color: rgba(251, 191, 36, 0.4); }
.badge[data-occ="busy"] { background: rgba(248, 113, 113, 0.14); color: #fca5a5; border-color: rgba(248, 113, 113, 0.4); }

.panel-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 16px 0;
}

.panel-stats > div {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  padding: 10px 8px;
  text-align: center;
}

.panel-stats strong {
  display: block;
  font-size: 22px;
  font-weight: 900;
  letter-spacing: -0.02em;
}

.panel-stats span {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--muted);
}

.equip {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.equip li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 11px 13px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  animation: rise 0.32s ease both;
}

.equip .e-name { font-weight: 600; font-size: 14px; }
.equip .e-sub { display: block; font-size: 11px; color: var(--muted); font-weight: 500; }

.pill {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 999px;
  white-space: nowrap;
}

.pill.free { background: rgba(52, 211, 153, 0.14); color: #6ee7b7; }
.pill.in-use { background: rgba(248, 113, 113, 0.14); color: #fca5a5; }
.pill.maint { background: var(--surface); color: var(--muted); border: 1px solid var(--line-2); }

@keyframes rise {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 20px);
  background: var(--elevated);
  color: var(--ink);
  border: 1px solid var(--line-2);
  padding: 12px 18px;
  border-radius: var(--r-md);
  font-size: 13px;
  font-weight: 600;
  box-shadow: var(--sh-3);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  z-index: 50;
}

.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* ---------- Responsive ---------- */
@media (max-width: 860px) {
  .layout { grid-template-columns: 1fr; }
}

@media (max-width: 520px) {
  .app { padding: 14px 14px 40px; }
  .topbar { padding: 12px 14px; }
  .brand h1 { font-size: 18px; }
  .logo { width: 40px; height: 40px; font-size: 16px; }
  .floor {
    grid-template-rows: repeat(7, minmax(64px, 1fr));
    grid-template-areas:
      "fw fw mc mc"
      "fw fw mc mc"
      "cd cd cd cd"
      "rg rg st st"
      "rg rg st st"
      "lk lk en en";
  }
  .topbar-actions { width: 100%; justify-content: space-between; }
  .gauge { width: 150px; height: 150px; }
  .gauge-center strong { font-size: 30px; }
}

