    { day: 2, time: "17:30", name: "Tabata Torch", type: "Cardio", trainer: "Dana Reyes", room: "The Box", intensity: "high", capacity: 18 },
    { day: 2, time: "18:45", name: "Deadlift Club", type: "Strength", trainer: "Sam Cho", room: "Studio A", intensity: "high", capacity: 12 },

    { day: 3, time: "07:30", name: "Boxing Cardio", type: "Cardio", trainer: "Marcus Hale", room: "The Box", intensity: "high", capacity: 18 },
    { day: 3, time: "12:00", name: "Lunch Flow", type: "Yoga", trainer: "Mira Okafor", room: "Mind Room", intensity: "low", capacity: 20 },
    { day: 3, time: "18:45", name: "Spin45", type: "Cycle", trainer: "Priya Nair", room: "Spin Loft", intensity: "mid", capacity: 26 },
    { day: 3, time: "20:00", name: "Functional Strength", type: "Strength", trainer: "Sam Cho", room: "Studio B", intensity: "mid", capacity: 16 },

    { day: 4, time: "06:00", name: "HIIT Burn", type: "Cardio", trainer: "Dana Reyes", room: "The Box", intensity: "high", capacity: 18 },
    { day: 4, time: "09:00", name: "Power Vinyasa", type: "Yoga", trainer: "Mira Okafor", room: "Mind Room", intensity: "mid", capacity: 22 },
    { day: 4, time: "17:30", name: "Friday Ride", type: "Cycle", trainer: "Leo Banks", room: "Spin Loft", intensity: "high", capacity: 26 },
    { day: 4, time: "18:45", name: "Total Body Lift", type: "Strength", trainer: "Sam Cho", room: "Studio A", intensity: "high", capacity: 14 },

    { day: 5, time: "09:00", name: "Weekend Warrior", type: "Strength", trainer: "Marcus Hale", room: "Studio A", intensity: "high", capacity: 16 },
    { day: 5, time: "12:00", name: "Spin & Sweat", type: "Cycle", trainer: "Priya Nair", room: "Spin Loft", intensity: "mid", capacity: 26 },
    { day: 5, time: "17:30", name: "Sunset Flow", type: "Yoga", trainer: "Mira Okafor", room: "Mind Room", intensity: "low", capacity: 24 },

    { day: 6, time: "09:00", name: "Recovery Stretch", type: "Yoga", trainer: "Mira Okafor", room: "Mind Room", intensity: "low", capacity: 24 },
    { day: 6, time: "12:00", name: "Steady Spin", type: "Cycle", trainer: "Leo Banks", room: "Spin Loft", intensity: "low", capacity: 26 },
  ];

  // Deterministic-ish booked count per class so spots feel real
  const classes = RAW.map((c, i) => {
    const taken = Math.min(c.capacity, Math.round(((i * 7 + 11) % c.capacity) * 0.82) + 2);
    return {
      id: "c" + i,
      ...c,
      booked: Math.min(taken, c.capacity),
      mine: false,
    };
  });

  const INTENSITY_LABEL = { low: "Low", mid: "Moderate", high: "High" };
  const TYPE_COLORVAR = { Strength: "--c-strength", Cardio: "--c-cardio", Yoga: "--c-yoga", Cycle: "--c-cycle" };

  /* ---------- State ---------- */
  let activeFilter = "all";
  let weekOffset = 0;          // 0 = current week
  let selectedId = null;

  /* ---------- DOM ---------- */
  const grid = document.getElementById("grid");
  const weekRange = document.getElementById("weekRange");
  const overlay = document.getElementById("overlay");
  const panel = document.getElementById("panel");
  const panelBody = document.getElementById("panelBody");
  const toastHost = document.getElementById("toastHost");
  let lastFocused = null;

  /* ---------- Date helpers ---------- */
  function mondayOf(offset) {
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    const dow = (d.getDay() + 6) % 7; // 0 = Mon
    d.setDate(d.getDate() - dow + offset * 7);
    return d;
  }
  function todayDayIndex() {
    return (new Date().getDay() + 6) % 7;
  }
  const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

  /* ---------- Render headers ---------- */
  function renderHeaders() {
    const mon = mondayOf(weekOffset);
    const heads = grid.querySelectorAll(".dayhead");
    const isCurrentWeek = weekOffset === 0;
    const todayIdx = todayDayIndex();

    heads.forEach((h, i) => {
      const d = new Date(mon);
      d.setDate(d.getDate() + i);
      h.querySelector(".d-date").textContent = `${MONTHS[d.getMonth()]} ${d.getDate()}`;
      h.classList.toggle("is-today", isCurrentWeek && i === todayIdx);
    });

    const last = new Date(mon); last.setDate(last.getDate() + 6);
    if (isCurrentWeek) {
      weekRange.textContent = "This Week";
    } else if (weekOffset === 1) {
      weekRange.textContent = "Next Week";
    } else if (weekOffset === -1) {
      weekRange.textContent = "Last Week";
    } else {
      weekRange.textContent = `${MONTHS[mon.getMonth()]} ${mon.getDate()} – ${MONTHS[last.getMonth()]} ${last.getDate()}`;
    }
  }

  /* ---------- Render grid body ---------- */
  function spotsLeft(c) { return c.capacity - c.booked; }

  function blockHTML(c) {
    const left = spotsLeft(c);
    const spotCls = left === 0 ? "is-full" : left <= 3 ? "is-low" : "";
    const spotTxt = left === 0 ? "Full" : `${left} spot${left === 1 ? "" : "s"} left`;
    const dimCls = activeFilter !== "all" && c.type !== activeFilter ? "dim" : "";
    const selCls = c.id === selectedId ? "is-selected" : "";
    const bookedCls = c.mine ? "is-booked" : "";
    return `<button class="block ${dimCls} ${selCls} ${bookedCls}" data-type="${c.type}" data-id="${c.id}" type="button"
        aria-label="${c.name} with ${c.trainer} at ${c.time}, ${spotTxt}">
        <p class="b-name">${c.name}</p>
        <p class="b-meta">${c.time} · ${c.trainer.split(" ")[0]}</p>
        <div class="b-foot">
          <span class="b-int int-${c.intensity}">${INTENSITY_LABEL[c.intensity]}</span>
          <span class="b-spots ${spotCls}">${spotTxt}</span>
        </div>
      </button>`;
  }

  function renderGrid() {
    // remove existing rows (everything after the 8 header cells)
    const headerCount = 8;
    while (grid.children.length > headerCount) grid.removeChild(grid.lastChild);

    const todayIdx = todayDayIndex();
    const highlightCol = weekOffset === 0;

    TIMES.forEach((time) => {
      const tc = document.createElement("div");
      tc.className = "timecell";
      tc.textContent = time;
      grid.appendChild(tc);

      for (let day = 0; day < 7; day++) {
        const slot = document.createElement("div");
        slot.className = "slot" + (highlightCol && day === todayIdx ? " is-today-col" : "");
        slot.setAttribute("role", "gridcell");
        const match = classes.find((c) => c.day === day && c.time === time);
        if (match) slot.innerHTML = blockHTML(match);
        grid.appendChild(slot);
      }
    });
  }

  /* ---------- Detail panel ---------- */
  function openPanel(c) {
    selectedId = c.id;
    const colorVar = TYPE_COLORVAR[c.type];
    const left = spotsLeft(c);
    const pct = Math.round((c.booked / c.capacity) * 100);
    const fillCls = left === 0 ? "is-full" : left <= 3 ? "is-low" : "";

    const bookLabel = c.mine ? "✓ Booked — Tap to cancel" : left === 0 ? "Class Full" : "Book This Class";
    const bookCls = c.mine ? "is-booked" : "";
    const bookDisabled = left === 0 && !c.mine ? "disabled" : "";

    panelBody.innerHTML = `
      <span class="pn-type" style="color:var(${colorVar});background:color-mix(in srgb, var(${colorVar}) 14%, transparent)">
        <span class="dot" style="background:var(${colorVar})"></span>${c.type}
      </span>
      <h2 class="pn-title">${c.name}</h2>
      <p class="pn-sub">with ${c.trainer}</p>

      <div class="pn-rows">
        <div class="pn-row"><span class="pn-k">Time</span><span class="pn-v">${c.time} – ${addMins(c.time, c.intensity === "low" ? 60 : 45)}</span></div>
        <div class="pn-row"><span class="pn-k">Room</span><span class="pn-v">${c.room}</span></div>
        <div class="pn-row"><span class="pn-k">Intensity</span><span class="pn-v"><span class="b-int int-${c.intensity}">${INTENSITY_LABEL[c.intensity]}</span></span></div>
        <div class="pn-row"><span class="pn-k">Capacity</span><span class="pn-v">${c.booked}/${c.capacity}</span></div>
      </div>

      <div class="pn-spots-bar" aria-hidden="true">
        <div class="pn-spots-fill ${fillCls}" style="width:${pct}%"></div>
      </div>

      <p class="pn-desc">${describe(c)}</p>

      <button class="pn-book ${bookCls}" id="bookBtn" type="button" ${bookDisabled}>${bookLabel}</button>
    `;

    const bookBtn = document.getElementById("bookBtn");
    if (bookBtn) bookBtn.addEventListener("click", () => toggleBooking(c));

    lastFocused = document.activeElement;
    overlay.hidden = false;
    panel.classList.add("is-open");
    panel.setAttribute("aria-hidden", "false");
    panel.focus();
    renderGrid(); // refresh selection highlight
  }

  function closePanel() {
    panel.classList.remove("is-open");
    panel.setAttribute("aria-hidden", "true");
    overlay.hidden = true;
    selectedId = null;
    renderGrid();
    if (lastFocused && lastFocused.focus) lastFocused.focus();
  }

  function toggleBooking(c) {
    if (!c.mine && spotsLeft(c) === 0) return;
    if (c.mine) {
      c.mine = false;
      c.booked = Math.max(0, c.booked - 1);
      toast(`Cancelled · ${c.name}`);
    } else {
      c.mine = true;
      c.booked = Math.min(c.capacity, c.booked + 1);
      toast(`Booked · ${c.name} @ ${c.time}`);
    }
    openPanel(c); // re-render panel + grid
  }

  function addMins(hhmm, mins) {
    const [h, m] = hhmm.split(":").map(Number);
    const total = h * 60 + m + mins;
    const nh = Math.floor(total / 60) % 24;
    const nm = total % 60;
    return `${String(nh).padStart(2, "0")}:${String(nm).padStart(2, "0")}`;
  }

  function describe(c) {
    const map = {
      Strength: `A coach-led ${c.intensity === "high" ? "heavy" : "progressive"} strength session focused on compound lifts and controlled tempo. Bring a towel and water.`,
      Cardio: `High-output conditioning built around intervals to spike your heart rate and torch calories. Scalable for all levels.`,
      Yoga: `A breath-guided ${c.intensity === "low" ? "grounding" : "dynamic"} practice to build mobility, balance and recovery. Mats provided.`,
      Cycle: `Beat-driven indoor ride with climbs, sprints and recovery flats. Cycling shoes available to borrow at the desk.`,
    };
    return map[c.type];
  }

  /* ---------- Toast ---------- */
  function toast(msg) {
    const el = document.createElement("div");
    el.className = "toast";
    el.textContent = msg;
    toastHost.appendChild(el);
    setTimeout(() => {
      el.classList.add("toast-out");
      el.addEventListener("animationend", () => el.remove());
    }, 2400);
  }

  /* ---------- Filters ---------- */
  function setFilter(type) {
    activeFilter = type;
    document.querySelectorAll(".chip").forEach((chip) => {
      const active = chip.dataset.type === type;
      chip.classList.toggle("is-active", active);
      chip.setAttribute("aria-pressed", String(active));
    });
    renderGrid();
  }

  /* ---------- Events ---------- */
  document.getElementById("chips").addEventListener("click", (e) => {
    const chip = e.target.closest(".chip");
    if (chip) setFilter(chip.dataset.type);
  });

  grid.addEventListener("click", (e) => {
    const block = e.target.closest(".block");
    if (!block) return;
    const c = classes.find((x) => x.id === block.dataset.id);
    if (c) openPanel(c);
  });

  document.getElementById("prevWeek").addEventListener("click", () => { weekOffset--; renderHeaders(); renderGrid(); });
  document.getElementById("nextWeek").addEventListener("click", () => { weekOffset++; renderHeaders(); renderGrid(); });
  document.getElementById("todayBtn").addEventListener("click", () => {
    weekOffset = 0; renderHeaders(); renderGrid(); toast("Jumped to this week");
  });

  document.getElementById("panelClose").addEventListener("click", closePanel);
  overlay.addEventListener("click", closePanel);
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && panel.classList.contains("is-open")) closePanel();
  });

  /* ---------- Init ---------- */
  renderHeaders();
  renderGrid();
})();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --sh-1: 0 1px 2px rgba(28, 42, 37, 0.06), 0 2px 8px rgba(28, 42, 37, 0.05);
  --sh-2: 0 6px 18px rgba(28, 42, 37, 0.08), 0 18px 40px rgba(28, 42, 37, 0.08);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: "Inter", system-ui, sans-serif;
  line-height: 1.55;
  color: var(--ink);
  background: var(--ivory);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1,
h2,
h3 {
  font-family: "Cormorant Garamond", Georgia, serif;
  margin: 0;
  line-height: 1.08;
  letter-spacing: 0.01em;
}

p {
  margin: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

.wrap {
  width: min(1140px, 92vw);
  margin-inline: auto;
}

.skip-link {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--green);
  color: var(--paper);
  padding: 10px 16px;
  border-radius: 0 0 var(--r-sm) 0;
  z-index: 100;
}
.skip-link:focus {
  left: 0;
}

:focus-visible {
  outline: 2px solid var(--brass);
  outline-offset: 2px;
  border-radius: 4px;
}

.eyebrow {
  font-size: 0.74rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--brass-d);
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-size: 0.92rem;
  font-weight: 600;
  padding: 11px 20px;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.15s ease, background 0.2s ease, box-shadow 0.2s ease,
    color 0.2s ease;
}
.btn:active {
  transform: translateY(1px);
}
.btn--solid {
  background: var(--green);
  color: var(--paper);
  box-shadow: var(--sh-1);
}
.btn--solid:hover {
  background: var(--green-d);
  box-shadow: var(--sh-2);
}
.btn--outline {
  background: transparent;
  color: var(--green);
  border-color: var(--line-2);
}
.btn--outline:hover {
  border-color: var(--green);
  background: var(--green-50);
}
.btn--ghost {
  background: var(--brass-50);
  color: var(--brass-d);
  padding: 9px 16px;
  font-size: 0.86rem;
}
.btn--ghost:hover {
  background: var(--brass);
  color: var(--paper);
}

/* ===== Topbar ===== */
.topbar {
  position: sticky;
  top: 0;
  z-index: 40;
  background: rgba(247, 244, 236, 0.86);
  backdrop-filter: saturate(1.4) blur(10px);
  border-bottom: 1px solid var(--line);
}
.topbar__inner {
  display: flex;
  align-items: center;
  gap: 22px;
  height: 66px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 700;
  font-size: 1.32rem;
  color: var(--green);
}
.brand__mark {
  color: var(--brass);
  font-size: 0.9em;
}
.topnav {
  display: flex;
  gap: 26px;
  margin-left: auto;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--ink-2);
}
.topnav a {
  position: relative;
  padding: 4px 0;
}
.topnav a::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -2px;
  width: 0;
  height: 1.5px;
  background: var(--brass);
  transition: width 0.22s ease;
}
.topnav a:hover {
  color: var(--green);
}
.topnav a:hover::after {
  width: 100%;
}

/* ===== Hero ===== */
.hero {
  width: min(1140px, 92vw);
  margin: 28px auto 0;
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: 0;
  border-radius: var(--r-lg);
  overflow: hidden;
  background: var(--paper);
  box-shadow: var(--sh-2);
  border: 1px solid var(--line);
}
.hero__photo {
  position: relative;
  min-height: 440px;
  background: linear-gradient(180deg, rgba(28, 42, 37, 0) 35%, rgba(22, 48, 42, 0.55) 100%),
    radial-gradient(120% 80% at 75% 12%, #f3d9a8 0%, rgba(243, 217, 168, 0) 45%),
    linear-gradient(135deg, #3c6354 0%, #244a3e 42%, #6b8a5a 78%, #a9b884 100%);
}
.hero__chip {
  position: absolute;
  left: 18px;
  top: 18px;
  background: rgba(255, 253, 248, 0.92);
  color: var(--green);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 7px 12px;
  border-radius: 999px;
  box-shadow: var(--sh-1);
}
.hero__body {
  padding: 44px 42px 40px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.hero__body h1 {
  font-size: clamp(2.6rem, 5vw, 3.7rem);
  font-weight: 700;
  color: var(--green-d);
  margin: 10px 0 14px;
}
.hero__vibe {
  color: var(--ink-2);
  font-size: 1.02rem;
  max-width: 46ch;
}
.hero__tags {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 0;
  margin: 22px 0 26px;
}
.hero__tags li {
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--green-700);
  background: var(--green-50);
  border: 1px solid var(--line);
  padding: 6px 12px;
  border-radius: 999px;
}
.hero__cta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

/* ===== Sections ===== */
.section {
  padding: 64px 0;
}
.section--alt {
  background: linear-gradient(180deg, var(--paper), var(--ivory));
  border-block: 1px solid var(--line);
}
.section__head {
  max-width: 60ch;
  margin-bottom: 34px;
}
.section__head h2 {
  font-size: clamp(1.9rem, 3.6vw, 2.6rem);
  font-weight: 600;
  color: var(--green-d);
  margin: 8px 0 8px;
}
.section__sub {
  color: var(--muted);
  font-size: 0.98rem;
}

/* ===== Stats ===== */
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}
.stat {
  position: relative;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 22px 20px 20px;
  box-shadow: var(--sh-1);
  transition: transform 0.18s ease, box-shadow 0.2s ease;
}
.stat::before {
  content: "";
  position: absolute;
  left: 20px;
  top: 0;
  width: 34px;
  height: 3px;
  border-radius: 0 0 3px 3px;
  background: var(--brass);
}
.stat:hover {
  transform: translateY(-3px);
  box-shadow: var(--sh-2);
}
.stat__label {
  font-size: 0.8rem;
  color: var(--muted);
  font-weight: 500;
}
.stat__value {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 2.2rem;
  font-weight: 700;
  color: var(--green-d);
  margin: 4px 0 6px;
  line-height: 1;
}
.stat__delta {
  font-size: 0.82rem;
  font-weight: 600;
  display: flex;
  align-items: baseline;
  gap: 6px;
}
.stat__delta span {
  font-weight: 400;
  color: var(--muted);
  font-size: 0.74rem;
}
.stat__delta--up {
  color: var(--ok);
}
.stat__delta--down {
  color: var(--green-700);
}
.spark {
  margin-top: 12px;
}
.spark svg {
  width: 100%;
  height: 30px;
  display: block;
}
.spark polyline {
  fill: none;
  stroke: var(--brass);
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ===== Lifestyle dials ===== */
.dials {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}
.dial {
  margin: 0;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 28px 22px 26px;
  text-align: center;
  box-shadow: var(--sh-1);
  display: flex;
  flex-direction: column;
  align-items: center;
  transition: transform 0.18s ease, box-shadow 0.2s ease;
}
.dial:hover {
  transform: translateY(-3px);
  box-shadow: var(--sh-2);
}
.dial__ring {
  position: relative;
  width: 142px;
  height: 142px;
}
.dial__ring svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}
.dial__track {
  fill: none;
  stroke: var(--green-50);
  stroke-width: 12;
}
.dial__fill {
  fill: none;
  stroke: var(--brass);
  stroke-width: 12;
  stroke-linecap: round;
  stroke-dasharray: 326.7;
  stroke-dashoffset: 326.7;
  transition: stroke-dashoffset 1.1s cubic-bezier(0.22, 1, 0.36, 1);
}
.dial__num {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--green-d);
}
.dial figcaption {
  margin-top: 16px;
}
.dial figcaption strong {
  display: block;
  color: var(--green-d);
  font-size: 1.02rem;
  margin-bottom: 4px;
}
.dial figcaption span {
  color: var(--muted);
  font-size: 0.84rem;
}

/* ===== Amenities ===== */
.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 26px;
}
.chip {
  font-family: inherit;
  font-size: 0.86rem;
  font-weight: 500;
  color: var(--ink-2);
  background: var(--paper);
  border: 1px solid var(--line-2);
  padding: 8px 16px;
  border-radius: 999px;
  cursor: pointer;
  transition: all 0.18s ease;
}
.chip:hover {
  border-color: var(--green);
  color: var(--green);
}
.chip.is-active {
  background: var(--green);
  border-color: var(--green);
  color: var(--paper);
}
.amen-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 14px;
}
.amen {
  display: flex;
  align-items: center;
  gap: 14px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 16px;
  box-shadow: var(--sh-1);
  transition: transform 0.18s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.amen.is-hidden {
  display: none;
}
.amen:hover {
  transform: translateY(-2px);
  box-shadow: var(--sh-2);
  border-color: var(--line-2);
}
.amen__icon {
  flex: 0 0 auto;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: var(--r-sm);
  font-size: 1.25rem;
  background: var(--green-50);
}
.amen__icon--dining {
  background: var(--brass-50);
}
.amen__icon--parks {
  background: #e3efe1;
}
.amen__main {
  flex: 1;
  min-width: 0;
}
.amen__name {
  font-weight: 600;
  color: var(--ink);
}
.amen__meta {
  font-size: 0.82rem;
  color: var(--muted);
}
.amen__badge {
  flex: 0 0 auto;
  font-size: 0.76rem;
  font-weight: 600;
  padding: 5px 10px;
  border-radius: 999px;
  white-space: nowrap;
}
.badge--green {
  background: var(--green-50);
  color: var(--green-700);
}
.badge--brass {
  background: var(--brass-50);
  color: var(--brass-d);
}
.amen-empty {
  color: var(--muted);
  font-style: italic;
  margin-top: 8px;
}

/* ===== Listing cards ===== */
.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}
.card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--sh-1);
  transition: transform 0.2s ease, box-shadow 0.22s ease;
}
.card:hover {
  transform: translateY(-5px);
  box-shadow: var(--sh-2);
}
.card__photo {
  position: relative;
  aspect-ratio: 4 / 3;
}
.card__photo--1 {
  background: linear-gradient(160deg, #d9c39a 0%, #b89a64 50%, #7d6a47 100%),
    radial-gradient(80% 60% at 70% 20%, rgba(255, 248, 230, 0.7), transparent 60%);
  background-blend-mode: overlay, normal;
}
.card__photo--2 {
  background: linear-gradient(160deg, #5d7e6c 0%, #2f4f42 55%, #20382f 100%),
    radial-gradient(70% 50% at 30% 18%, rgba(214, 230, 210, 0.55), transparent 60%);
  background-blend-mode: screen, normal;
}
.card__photo--3 {
  background: linear-gradient(160deg, #c7b3c4 0%, #8b6d80 48%, #5a4a64 100%),
    radial-gradient(75% 55% at 65% 22%, rgba(255, 240, 230, 0.6), transparent 60%);
  background-blend-mode: overlay, normal;
}
.card__status {
  position: absolute;
  left: 14px;
  top: 14px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 5px 11px;
  border-radius: 999px;
  box-shadow: var(--sh-1);
}
.badge--ok {
  background: var(--ok);
  color: #fff;
}
.badge--warn {
  background: var(--warn);
  color: #fff;
}
.card__fav {
  position: absolute;
  right: 12px;
  top: 12px;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: none;
  background: rgba(255, 253, 248, 0.92);
  color: var(--danger);
  font-size: 1.1rem;
  cursor: pointer;
  display: grid;
  place-items: center;
  box-shadow: var(--sh-1);
  transition: transform 0.15s ease, background 0.2s ease;
}
.card__fav:hover {
  transform: scale(1.08);
}
.card__fav[aria-pressed="true"] {
  background: var(--danger);
  color: #fff;
}
.card__body {
  padding: 18px 20px 20px;
}
.card__price {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 1.7rem;
  font-weight: 700;
  color: var(--green-d);
  line-height: 1;
}
.card__addr {
  font-weight: 600;
  margin: 6px 0 2px;
}
.card__specs {
  font-size: 0.86rem;
  color: var(--muted);
}
.card__agent {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
  font-size: 0.83rem;
  color: var(--ink-2);
}
.avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--green);
  color: var(--paper);
  display: grid;
  place-items: center;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}

/* ===== Footer ===== */
.footer {
  background: var(--green-d);
  color: var(--green-50);
  padding: 34px 0;
}
.footer__inner {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  justify-content: space-between;
  align-items: center;
}
.brand--footer {
  color: var(--paper);
  font-size: 1.2rem;
}
.brand--footer .brand__mark {
  color: var(--brass);
}
.footer__fine {
  font-size: 0.82rem;
  color: rgba(232, 239, 234, 0.72);
}

/* ===== Toast ===== */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 24px);
  background: var(--green-d);
  color: var(--paper);
  padding: 12px 20px;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 500;
  box-shadow: var(--sh-2);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  z-index: 80;
}
.toast.is-show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ===== Responsive ===== */
@media (max-width: 880px) {
  .hero {
    grid-template-columns: 1fr;
  }
  .hero__photo {
    min-height: 280px;
  }
  .stats {
    grid-template-columns: repeat(2, 1fr);
  }
  .dials,
  .cards {
    grid-template-columns: 1fr;
  }
  .topnav {
    display: none;
  }
}

@media (max-width: 520px) {
  .section {
    padding: 46px 0;
  }
  .hero__body {
    padding: 30px 24px 28px;
  }
  .stats {
    grid-template-columns: 1fr;
  }
  .amen-list {
    grid-template-columns: 1fr;
  }
  .dials {
    grid-template-columns: 1fr;
  }
  .topbar__inner {
    gap: 12px;
  }
  .brand__name {
    font-size: 0.95em;
  }
  .footer__inner {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    scroll-behavior: auto !important;
    transition-duration: 0.001ms !important;
  }
}

