(function () {
  "use strict";

  /* ---------- Toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("is-show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("is-show");
    }, 2400);
  }

  /* ---------- Animated lifestyle dials ---------- */
  var CIRCUMFERENCE = 2 * Math.PI * 52; // r = 52
  var dials = Array.prototype.slice.call(document.querySelectorAll(".dial"));

  function fillDial(dial) {
    if (dial.dataset.done === "1") return;
    dial.dataset.done = "1";

    var score = Math.max(0, Math.min(100, parseInt(dial.dataset.score, 10) || 0));
    var fill = dial.querySelector(".dial__fill");
    var num = dial.querySelector(".dial__num");
    var offset = CIRCUMFERENCE * (1 - score / 100);

    // Trigger the stroke animation on next frame.
    requestAnimationFrame(function () {
      fill.style.strokeDashoffset = String(offset);
    });

    // Count the number up in step with the ring.
    var DURATION = 1100;
    var start = null;
    function tick(ts) {
      if (start === null) start = ts;
      var t = Math.min(1, (ts - start) / DURATION);
      // easeOutCubic
      var eased = 1 - Math.pow(1 - t, 3);
      num.textContent = String(Math.round(eased * score));
      if (t < 1) requestAnimationFrame(tick);
      else num.textContent = String(score);
    }
    requestAnimationFrame(tick);
  }

  if ("IntersectionObserver" in window && dials.length) {
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            fillDial(entry.target);
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.4 }
    );
    dials.forEach(function (d) {
      io.observe(d);
    });
  } else {
    // Fallback: just fill them.
    dials.forEach(fillDial);
  }

  /* ---------- Amenity category filter ---------- */
  var filterBar = document.getElementById("filters");
  var amenities = Array.prototype.slice.call(
    document.querySelectorAll(".amen")
  );
  var emptyMsg = document.getElementById("amenEmpty");

  function applyFilter(cat) {
    var visible = 0;
    amenities.forEach(function (item) {
      var show = cat === "all" || item.dataset.cat === cat;
      item.classList.toggle("is-hidden", !show);
      if (show) visible++;
    });
    if (emptyMsg) emptyMsg.hidden = visible !== 0;
  }

  if (filterBar) {
    filterBar.addEventListener("click", function (e) {
      var btn = e.target.closest(".chip");
      if (!btn) return;
      filterBar.querySelectorAll(".chip").forEach(function (c) {
        c.classList.remove("is-active");
        c.setAttribute("aria-selected", "false");
      });
      btn.classList.add("is-active");
      btn.setAttribute("aria-selected", "true");
      applyFilter(btn.dataset.filter);
    });
  }

  /* ---------- Favorite (save) listings ---------- */
  document.querySelectorAll(".card__fav").forEach(function (btn) {
    btn.addEventListener("click", function () {
      var saved = btn.getAttribute("aria-pressed") === "true";
      btn.setAttribute("aria-pressed", String(!saved));
      btn.textContent = saved ? "♡" : "♥";
      var card = btn.closest(".card");
      var addr = card
        ? card.querySelector(".card__addr").textContent.trim()
        : "listing";
      toast(saved ? "Removed " + addr : "Saved " + addr + " to favorites");
    });
  });

  /* ---------- Save guide ---------- */
  var saveGuide = document.getElementById("saveGuide");
  if (saveGuide) {
    saveGuide.addEventListener("click", function () {
      toast("Maplewood Heights guide saved to your account");
    });
  }
})();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;

  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;

  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;

  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;

  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);

  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --shadow-sm: 0 1px 2px rgba(28, 42, 37, 0.06), 0 2px 8px rgba(28, 42, 37, 0.05);
  --shadow-md: 0 6px 18px rgba(28, 42, 37, 0.08), 0 2px 6px rgba(28, 42, 37, 0.06);
  --shadow-lg: 0 20px 44px rgba(28, 42, 37, 0.16), 0 6px 14px rgba(28, 42, 37, 0.08);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  margin: 0;
  font-family: "Inter", system-ui, sans-serif;
  line-height: 1.55;
  color: var(--ink);
  background:
    radial-gradient(1200px 600px at 85% -10%, var(--brass-50), transparent 60%),
    var(--ivory);
  min-height: 100vh;
}

.page {
  max-width: 1160px;
  margin: 0 auto;
  padding: clamp(2rem, 5vw, 4.5rem) clamp(1.1rem, 4vw, 2.5rem) 4rem;
}

/* ---------- Masthead ---------- */
.masthead {
  max-width: 640px;
  margin-bottom: clamp(1.8rem, 4vw, 3rem);
}

.eyebrow {
  margin: 0 0 0.7rem;
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--brass-d);
}

.masthead h1 {
  margin: 0 0 0.6rem;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
  font-size: clamp(2.4rem, 6vw, 3.6rem);
  line-height: 1.04;
  letter-spacing: -0.01em;
  color: var(--green-d);
}

.lede {
  margin: 0;
  color: var(--ink-2);
  font-size: 1.04rem;
  max-width: 52ch;
}

/* ---------- Grid ---------- */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: clamp(1.1rem, 2.4vw, 1.8rem);
}

/* ---------- Card ---------- */
.card {
  display: flex;
  flex-direction: column;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.32s ease, border-color 0.32s ease;
}

.card:hover,
.card:focus-within {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
  border-color: var(--line-2);
}

/* ---------- Media / Photo ---------- */
.card__media {
  position: relative;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background: var(--green-50);
}

.card__photo {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: flex-end;
  padding: 0.9rem 1rem;
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1),
    background 0.6s ease;
}

.card:hover .card__photo {
  transform: scale(1.045);
}

/* Simulated photography — warm architectural gradients */
.card__photo[data-current="warm"] {
  background:
    radial-gradient(120% 90% at 78% 8%, rgba(255, 244, 222, 0.95), transparent 52%),
    radial-gradient(90% 80% at 18% 110%, rgba(31, 61, 52, 0.55), transparent 60%),
    linear-gradient(155deg, #d9a566 0%, #b9824a 36%, #6f5a45 70%, #2f3a33 100%);
}
.card__photo[data-current="sky"] {
  background:
    radial-gradient(110% 80% at 80% 0%, rgba(255, 255, 255, 0.55), transparent 55%),
    radial-gradient(80% 70% at 12% 100%, rgba(176, 141, 87, 0.5), transparent 60%),
    linear-gradient(160deg, #aecfda 0%, #7fb0c0 34%, #4f8a82 68%, #244a45 100%);
}
.card__photo[data-current="dusk"] {
  background:
    radial-gradient(120% 90% at 70% 12%, rgba(255, 214, 170, 0.75), transparent 50%),
    radial-gradient(90% 80% at 20% 105%, rgba(22, 48, 42, 0.7), transparent 60%),
    linear-gradient(165deg, #e3a86b 0%, #c2724a 30%, #6c3f3a 66%, #221f2e 100%);
}
.card__photo[data-current="garden"] {
  background:
    radial-gradient(110% 80% at 75% 6%, rgba(255, 248, 224, 0.8), transparent 52%),
    radial-gradient(95% 85% at 25% 110%, rgba(22, 48, 42, 0.6), transparent 62%),
    linear-gradient(160deg, #cdd6a0 0%, #8faa67 34%, #4f7a4e 66%, #244a3a 100%);
}

.card__photolabel {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--white);
  background: rgba(22, 48, 42, 0.42);
  backdrop-filter: blur(3px);
  padding: 0.28rem 0.6rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.22);
}

/* ---------- Ribbon (status) ---------- */
.ribbon {
  position: absolute;
  top: 0.85rem;
  left: 0.85rem;
  z-index: 2;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  padding: 0.34rem 0.7rem;
  border-radius: 999px;
  color: var(--white);
  box-shadow: var(--shadow-sm);
}
.ribbon--new {
  background: linear-gradient(135deg, var(--green-700), var(--green-d));
}
.ribbon--sale {
  background: linear-gradient(135deg, var(--brass), var(--brass-d));
}
.ribbon--pending {
  background: linear-gradient(135deg, #c98a2b, #9c6a1d);
}

/* ---------- Heart toggle ---------- */
.heart {
  position: absolute;
  top: 0.7rem;
  right: 0.7rem;
  z-index: 2;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.55);
  border-radius: 50%;
  background: rgba(255, 253, 248, 0.78);
  backdrop-filter: blur(6px);
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s ease, background 0.2s ease;
}
.heart svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: var(--green-d);
  stroke-width: 1.7;
  transition: fill 0.22s ease, stroke 0.22s ease, transform 0.22s ease;
}
.heart:hover {
  background: var(--white);
  transform: scale(1.08);
}
.heart:focus-visible {
  outline: 2px solid var(--brass);
  outline-offset: 2px;
}
.heart[aria-pressed="true"] svg {
  fill: var(--danger);
  stroke: var(--danger);
}
.heart.is-bump svg {
  animation: pop 0.34s ease;
}
@keyframes pop {
  0% { transform: scale(1); }
  40% { transform: scale(1.32); }
  100% { transform: scale(1); }
}

/* ---------- Carousel dots ---------- */
.dots {
  position: absolute;
  bottom: 0.85rem;
  right: 0.9rem;
  z-index: 2;
  display: flex;
  gap: 0.4rem;
}
.dots button {
  width: 8px;
  height: 8px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 253, 248, 0.55);
  box-shadow: 0 0 0 1px rgba(22, 48, 42, 0.18);
  cursor: pointer;
  transition: transform 0.2s ease, background 0.2s ease, width 0.2s ease;
}
.dots button[aria-selected="true"] {
  width: 18px;
  border-radius: 999px;
  background: var(--white);
}
.dots button:focus-visible {
  outline: 2px solid var(--brass);
  outline-offset: 2px;
}

/* ---------- Body ---------- */
.card__body {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  padding: 1.15rem 1.25rem 1.3rem;
}

.card__pricerow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
}

.price {
  margin: 0;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 700;
  font-size: 1.78rem;
  line-height: 1;
  color: var(--green-d);
  letter-spacing: -0.01em;
}

.pill {
  flex: none;
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 0.26rem 0.6rem;
  border-radius: 999px;
}
.pill--sale {
  color: var(--brass-d);
  background: var(--brass-50);
  border: 1px solid rgba(176, 141, 87, 0.3);
}
.pill--pending {
  color: #9c6a1d;
  background: #fbf0dc;
  border: 1px solid rgba(201, 138, 43, 0.32);
}

/* ---------- Stats ---------- */
.stats {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  margin: 0;
  padding: 0.55rem 0;
  list-style: none;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.stats li {
  display: flex;
  align-items: baseline;
  gap: 0.28rem;
  font-size: 0.86rem;
  color: var(--muted);
}
.stats li + li::before {
  content: "·";
  margin-right: 0.55rem;
  color: var(--line-2);
}
.stats strong {
  font-weight: 600;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

/* ---------- Address ---------- */
.address {
  margin: 0;
  font-size: 0.9rem;
  color: var(--ink-2);
}

/* ---------- Agent footer ---------- */
.agent {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  margin-top: 0.15rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--line);
}
.agent__avatar {
  flex: none;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--green-700), var(--green-d));
  color: var(--white);
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}
.agent__meta {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
}
.agent__name {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--ink);
}
.agent__brand {
  font-size: 0.76rem;
  color: var(--muted);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 1.6rem;
  transform: translate(-50%, 1.4rem);
  z-index: 50;
  max-width: min(90vw, 340px);
  padding: 0.7rem 1.1rem;
  border-radius: var(--r-md);
  background: var(--green-d);
  color: var(--paper);
  font-size: 0.86rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.28s ease, transform 0.28s ease;
}
.toast.is-show {
  opacity: 1;
  transform: translate(-50%, 0);
}
.toast b {
  color: var(--brass-50);
  font-weight: 600;
}

/* ---------- Responsive ---------- */
@media (max-width: 520px) {
  .page {
    padding: 2rem 1.1rem 3rem;
  }
  .grid {
    grid-template-columns: 1fr;
    gap: 1.1rem;
  }
  .price {
    font-size: 1.55rem;
  }
  .masthead h1 {
    font-size: 2.3rem;
  }
  .lede {
    font-size: 0.96rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.001ms !important;
    animation-duration: 0.001ms !important;
  }
}

