(function () {
  "use strict";

  /* ---------- Toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.innerHTML = msg;
    toastEl.classList.add("is-show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("is-show");
    }, 2400);
  }

  /* ---------- Persistence ---------- */
  var STORE_KEY = "stealthis.realestate.favorites";
  function loadFavs() {
    try {
      return JSON.parse(localStorage.getItem(STORE_KEY) || "[]");
    } catch (e) {
      return [];
    }
  }
  function saveFavs(list) {
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify(list));
    } catch (e) {
      /* storage may be unavailable (private mode) — state stays in-session */
    }
  }
  var favorites = loadFavs();

  /* ---------- Per-card wiring ---------- */
  var cards = document.querySelectorAll(".card");

  cards.forEach(function (card) {
    var id = card.getAttribute("data-id");
    var media = card.querySelector(".card__media");
    var photo = card.querySelector(".card__photo");
    var dotsWrap = card.querySelector(".dots");
    var heart = card.querySelector(".heart");

    /* --- Carousel: build dots from data-slides --- */
    var slides = (photo.getAttribute("data-slides") || "warm")
      .split(",")
      .map(function (s) { return s.trim(); })
      .filter(Boolean);

    var current = 0;
    photo.setAttribute("data-current", slides[0]);

    function go(index) {
      current = (index + slides.length) % slides.length;
      photo.setAttribute("data-current", slides[current]);
      var btns = dotsWrap.querySelectorAll("button");
      btns.forEach(function (b, i) {
        b.setAttribute("aria-selected", i === current ? "true" : "false");
      });
    }

    slides.forEach(function (slide, i) {
      var dot = document.createElement("button");
      dot.type = "button";
      dot.setAttribute("role", "tab");
      dot.setAttribute("aria-selected", i === 0 ? "true" : "false");
      dot.setAttribute("aria-label", "View photo " + (i + 1) + " of " + slides.length);
      dot.addEventListener("click", function () { go(i); });
      dotsWrap.appendChild(dot);
    });

    /* Click anywhere on the photo (not a control) advances to next slide */
    photo.addEventListener("click", function () {
      go(current + 1);
    });

    /* Keyboard arrows when media region is focused via heart/dots area */
    media.addEventListener("keydown", function (e) {
      if (e.key === "ArrowRight") { go(current + 1); }
      else if (e.key === "ArrowLeft") { go(current - 1); }
    });

    /* --- Favorite heart --- */
    var label = card.querySelector(".card__photolabel");
    var name = label ? label.textContent.trim() : "Listing";

    function reflect(isFav) {
      heart.setAttribute("aria-pressed", isFav ? "true" : "false");
    }

    reflect(favorites.indexOf(id) !== -1);

    heart.addEventListener("click", function () {
      var idx = favorites.indexOf(id);
      var nowFav;
      if (idx === -1) {
        favorites.push(id);
        nowFav = true;
      } else {
        favorites.splice(idx, 1);
        nowFav = false;
      }
      saveFavs(favorites);
      reflect(nowFav);

      heart.classList.remove("is-bump");
      /* force reflow so the animation can restart */
      void heart.offsetWidth;
      if (nowFav) heart.classList.add("is-bump");

      toast(
        nowFav
          ? "Saved <b>" + name + "</b> to favorites"
          : "Removed <b>" + name + "</b> from favorites"
      );
    });
  });

  /* ---------- Startup nudge ---------- */
  if (favorites.length) {
    toast(
      favorites.length +
        " saved " +
        (favorites.length === 1 ? "listing" : "listings") +
        " restored"
    );
  }
})();

snippets.css:
:root {
  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;
  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;
  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;
  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);
  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;
  --shadow-sm: 0 1px 2px rgba(28, 24, 20, 0.05), 0 1px 1px rgba(28, 24, 20, 0.04);
  --shadow-md: 0 14px 40px -20px rgba(28, 24, 20, 0.35);
  --shadow-lg: 0 30px 70px -34px rgba(28, 24, 20, 0.42);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1,
h2,
h3 {
  font-family: var(--serif);
  font-weight: 600;
  margin: 0;
  letter-spacing: 0.01em;
}

.page {
  max-width: 1080px;
  margin: 0 auto;
  padding: 0 24px 80px;
}

/* ---------- Masthead ---------- */
.masthead {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 26px 0 22px;
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand__mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 1px solid var(--gold);
  color: var(--gold-d);
  font-family: var(--serif);
  font-weight: 700;
  font-size: 16px;
  letter-spacing: 0.04em;
}

.brand__name {
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--ink);
}

.masthead__nav {
  display: flex;
  gap: 26px;
  margin-left: auto;
}

.masthead__nav a {
  font-size: 13px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  text-decoration: none;
  padding-bottom: 3px;
  border-bottom: 1px solid transparent;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.masthead__nav a:hover,
.masthead__nav a:focus-visible {
  color: var(--ink);
}

.masthead__nav a.is-active {
  color: var(--gold-d);
  border-bottom-color: var(--gold);
}

.masthead__cta {
  flex-shrink: 0;
}

/* ---------- Hero ---------- */
.hero {
  text-align: center;
  padding: 56px 0 38px;
}

.eyebrow {
  margin: 0 0 14px;
  font-size: 12px;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--gold-d);
}

.hero__title {
  font-size: clamp(44px, 8vw, 76px);
  line-height: 1.02;
  margin: 0 0 18px;
}

.hero__lede {
  max-width: 540px;
  margin: 0 auto;
  color: var(--ink-2);
  font-size: 17px;
}

/* ---------- Toolbar / search ---------- */
.toolbar {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 8px 0 18px;
  flex-wrap: wrap;
}

.search {
  position: relative;
  flex: 1 1 320px;
  min-width: 240px;
}

.search__icon {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  fill: none;
  stroke: var(--muted);
  stroke-width: 1.7;
  stroke-linecap: round;
  pointer-events: none;
}

.search__input {
  width: 100%;
  padding: 14px 18px 14px 46px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-lg);
  background: var(--white);
  font-family: inherit;
  font-size: 15px;
  color: var(--ink);
  box-shadow: var(--shadow-sm);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.search__input::placeholder {
  color: var(--muted);
}

.search__input:focus-visible {
  outline: none;
  border-color: var(--gold);
  box-shadow: 0 0 0 3px var(--gold-soft);
}

.result-count {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

.result-count #count {
  color: var(--gold-d);
  font-weight: 600;
}

/* ---------- Filter chips ---------- */
.filters {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  padding-bottom: 30px;
  border-bottom: 1px solid var(--line);
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 18px;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  background: var(--white);
  color: var(--ink-2);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease, border-color 0.2s ease,
    box-shadow 0.2s ease, transform 0.12s ease;
}

.chip:hover {
  border-color: var(--gold);
  color: var(--ink);
}

.chip:active {
  transform: translateY(1px);
}

.chip:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--gold-soft);
}

.chip.is-active {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--cream);
  box-shadow: var(--shadow-md);
}

.chip__n {
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  color: var(--muted);
}

.chip.is-active .chip__n {
  color: var(--gold-soft);
}

/* ---------- Catalog ---------- */
.catalog {
  list-style: none;
  margin: 30px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 26px 40px;
}

.service {
  display: flex;
  flex-direction: column;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--line);
  animation: rise 0.4s ease both;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
}

.service__head {
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.service__name {
  font-size: 25px;
  line-height: 1.15;
  color: var(--ink);
}

.service__leader {
  flex: 1;
  height: 1px;
  margin-bottom: 6px;
  background-image: linear-gradient(
    to right,
    transparent,
    var(--line-2) 40%,
    var(--line-2)
  );
  background-size: 6px 1px;
}

.service__price {
  font-family: var(--serif);
  font-size: 24px;
  font-weight: 600;
  color: var(--gold-d);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.service__from {
  font-size: 11px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
  margin-right: 4px;
}

.service__desc {
  margin: 10px 0 16px;
  color: var(--ink-2);
  font-size: 14.5px;
  max-width: 46ch;
}

.service__meta {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: auto;
}

.tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.tag__cat {
  color: var(--gold-d);
  border: 1px solid var(--gold-soft);
  background: var(--rose-soft);
  padding: 4px 10px;
  border-radius: 999px;
}

.tag__dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--rose);
}

.service__book {
  margin-left: auto;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 11px 22px;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease, border-color 0.2s ease,
    box-shadow 0.2s ease, transform 0.12s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--gold-soft);
}

.btn--book {
  background: var(--ink);
  color: var(--cream);
}

.btn--book:hover {
  background: var(--gold-d);
}

.btn--ghost {
  background: transparent;
  color: var(--gold-d);
  border-color: var(--gold);
}

.btn--ghost:hover {
  background: var(--gold);
  color: var(--white);
  border-color: var(--gold);
}

/* ---------- Empty state ---------- */
.empty {
  text-align: center;
  padding: 64px 20px;
}

.empty__title {
  font-family: var(--serif);
  font-size: 30px;
  margin: 0 0 6px;
  color: var(--ink);
}

.empty__sub {
  margin: 0 0 22px;
  color: var(--muted);
}

/* ---------- Footer ---------- */
.footer {
  margin-top: 60px;
  padding-top: 30px;
  border-top: 1px solid var(--line);
  text-align: center;
}

.footer__name {
  font-family: var(--serif);
  font-size: 22px;
  margin: 0 0 6px;
  color: var(--ink);
}

.footer__line {
  margin: 0;
  font-size: 12px;
  letter-spacing: 0.06em;
  color: var(--muted);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 32px;
  transform: translate(-50%, 24px);
  background: var(--ink);
  color: var(--cream);
  padding: 14px 22px;
  border-radius: var(--r-md);
  font-size: 14px;
  letter-spacing: 0.02em;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.28s ease, transform 0.28s ease;
  z-index: 50;
  max-width: calc(100vw - 40px);
  text-align: center;
}

.toast::before {
  content: "✦";
  color: var(--gold);
  margin-right: 8px;
}

.toast.is-show {
  opacity: 1;
  transform: translate(-50%, 0);
  pointer-events: auto;
}

/* ---------- Responsive ---------- */
@media (max-width: 760px) {
  .catalog {
    grid-template-columns: 1fr;
    gap: 22px;
  }
}

@media (max-width: 520px) {
  .page {
    padding: 0 18px 60px;
  }

  .masthead {
    flex-wrap: wrap;
    gap: 14px;
  }

  .masthead__nav {
    order: 3;
    width: 100%;
    margin-left: 0;
    justify-content: space-between;
    gap: 12px;
  }

  .masthead__cta {
    margin-left: auto;
  }

  .hero {
    padding: 38px 0 28px;
  }

  .toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .result-count {
    text-align: right;
  }

  .service__head {
    flex-wrap: wrap;
  }

  .service__leader {
    display: none;
  }

  .service__price {
    margin-left: auto;
  }

  .service__meta {
    flex-wrap: wrap;
    gap: 12px;
  }

  .service__book {
    margin-left: 0;
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

