      '<span class="tag tag__cat">' +
      escapeHtml(CATEGORY_LABELS[svc.category]) +
      "</span>" +
      '<span class="tag"><span class="tag__dot" aria-hidden="true"></span>' +
      fmtDuration(svc.duration) +
      "</span>" +
      '<button class="btn btn--book service__book" type="button" data-book="' +
      escapeHtml(svc.name) +
      '">Book</button>' +
      "</div>" +
      "</li>"
    );
  }

  function matches(svc) {
    if (state.filter !== "all" && svc.category !== state.filter) return false;
    if (state.query) {
      var q = state.query;
      var hay = (svc.name + " " + svc.desc + " " + CATEGORY_LABELS[svc.category]).toLowerCase();
      if (hay.indexOf(q) === -1) return false;
    }
    return true;
  }

  function render() {
    var visible = SERVICES.filter(matches);
    catalog.innerHTML = visible.map(cardHtml).join("");
    countEl.textContent = String(visible.length);

    var hasNone = visible.length === 0;
    emptyEl.hidden = !hasNone;
    catalog.hidden = hasNone;
  }

  function updateChipCounts() {
    chips.forEach(function (chip) {
      var key = chip.getAttribute("data-filter");
      var n =
        key === "all"
          ? SERVICES.length
          : SERVICES.filter(function (s) {
              return s.category === key;
            }).length;
      var span = chip.querySelector(".chip__n");
      if (span) span.textContent = n;
    });
  }

  function setFilter(key) {
    state.filter = key;
    chips.forEach(function (chip) {
      var active = chip.getAttribute("data-filter") === key;
      chip.classList.toggle("is-active", active);
      chip.setAttribute("aria-selected", active ? "true" : "false");
    });
    render();
  }

  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add("is-show");
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("is-show");
    }, 2600);
  }

  /* ---- events ---- */
  chips.forEach(function (chip) {
    chip.addEventListener("click", function () {
      setFilter(chip.getAttribute("data-filter"));
    });
  });

  searchInput.addEventListener("input", function () {
    state.query = searchInput.value.trim().toLowerCase();
    render();
  });

  document.addEventListener("click", function (e) {
    var btn = e.target.closest("[data-book]");
    if (!btn) return;
    var name = btn.getAttribute("data-book");
    if (name === "__appointment__") {
      toast("Booking request started — we'll confirm your visit shortly.");
    } else {
      toast("Reserved · " + name + " — a stylist will confirm your time.");
    }
  });

  resetBtn.addEventListener("click", function () {
    searchInput.value = "";
    state.query = "";
    setFilter("all");
    searchInput.focus();
  });

  /* ---- init ---- */
  updateChipCounts();
  render();
})();

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ── Layout ── */
.ref {
  max-width: 1040px;
  margin: 0 auto;
  padding: 36px 20px 64px;
  display: grid;
  grid-template-columns: 1fr 360px;
  gap: 28px;
  align-items: start;
}

/* ── Form card ── */
.ref-form {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-1);
  padding: 26px;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.ref-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--line);
}
.eyebrow {
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--teal-d);
}
.ref-head h1 {
  font-size: 1.42rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-top: 4px;
}
.sub {
  font-size: 0.88rem;
  color: var(--muted);
  margin-top: 6px;
  max-width: 46ch;
}
.draft-pill {
  flex-shrink: 0;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  padding: 5px 12px;
  border-radius: 999px;
  background: var(--teal-50);
  color: var(--teal-d);
  transition: background 0.2s, color 0.2s;
}
.draft-pill.is-ready {
  background: rgba(47, 158, 111, 0.16);
  color: var(--ok);
}

/* ── Fields ── */
.field {
  display: flex;
  flex-direction: column;
  gap: 9px;
}
.lbl {
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--ink);
}
.lbl-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}
.req {
  color: var(--danger);
  font-weight: 800;
}
.counter {
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.counter.near {
  color: var(--warn);
}
.hint {
  font-size: 0.78rem;
  color: var(--muted);
}

/* ── Patient chip ── */
.patient-chip {
  display: flex;
  align-items: center;
  gap: 13px;
  background: linear-gradient(140deg, var(--teal-50), #d9efec);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 12px 14px;
}
.avatar {
  flex-shrink: 0;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--teal-d);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 0.86rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}
.avatar.sm {
  width: 34px;
  height: 34px;
  font-size: 0.72rem;
}
.patient-meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
}
.patient-meta strong {
  font-size: 0.96rem;
  font-weight: 700;
}
.patient-meta span {
  font-size: 0.78rem;
  color: var(--ink-2);
}
.chip-tag {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--teal-700);
  background: rgba(255, 255, 255, 0.7);
  border-radius: 999px;
  padding: 4px 9px;
}

/* ── Select ── */
.select-wrap {
  position: relative;
}
select {
  width: 100%;
  appearance: none;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 12px 40px 12px 13px;
  cursor: pointer;
  transition: border-color 0.15s, box-shadow 0.15s;
}
select:hover {
  border-color: var(--teal);
}
select:focus {
  outline: none;
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(18, 156, 147, 0.16);
}
select:invalid {
  color: var(--muted);
}
.caret {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  color: var(--muted);
  pointer-events: none;
}

/* ── Segmented urgency ── */
.seg {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 4px;
}
.seg-btn {
  border: none;
  background: transparent;
  border-radius: 999px;
  padding: 9px 10px;
  font: inherit;
  font-weight: 700;
  font-size: 0.84rem;
  color: var(--muted);
  cursor: pointer;
  transition: background 0.16s, color 0.16s, box-shadow 0.16s;
}
.seg-btn:hover {
  color: var(--ink-2);
}
.seg-btn.is-active {
  background: var(--white);
  box-shadow: var(--shadow-1);
}
.seg-btn.is-active[data-tone="ok"] {
  color: var(--ok);
}
.seg-btn.is-active[data-tone="warn"] {
  color: var(--warn);
}
.seg-btn.is-active[data-tone="danger"] {
  color: var(--danger);
}

/* ── Textareas ── */
textarea {
  width: 100%;
  font: inherit;
  font-size: 0.9rem;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 12px 13px;
  resize: vertical;
  min-height: 80px;
  transition: border-color 0.15s, box-shadow 0.15s;
}
textarea::placeholder {
  color: var(--muted);
}
textarea:hover {
  border-color: var(--teal);
}
textarea:focus {
  outline: none;
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(18, 156, 147, 0.16);
}

/* ── Validation ── */
.err {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--danger);
}
.field.invalid select,
.field.invalid textarea {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(212, 80, 62, 0.12);
}

/* ── Attach checklist ── */
.check-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.check {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 12px 14px;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}
.check:hover {
  border-color: var(--teal);
  background: var(--teal-50);
}
.check input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}
.box {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  margin-top: 1px;
  border: 2px solid var(--line-2);
  border-radius: 6px;
  background: var(--white);
  display: grid;
  place-items: center;
  transition: background 0.15s, border-color 0.15s;
}
.box::after {
  content: "";
  width: 10px;
  height: 6px;
  border-left: 2.4px solid #fff;
  border-bottom: 2.4px solid #fff;
  transform: rotate(-45deg) scale(0);
  transform-origin: center;
  transition: transform 0.15s ease;
  margin-top: -2px;
}
.check input:checked ~ .box {
  background: var(--teal-d);
  border-color: var(--teal-d);
}
.check input:checked ~ .box::after {
  transform: rotate(-45deg) scale(1);
}
.check:has(input:checked) {
  border-color: var(--teal);
  background: var(--teal-50);
}
.check input:focus-visible ~ .box {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}
.check-body {
  display: flex;
  flex-direction: column;
}
.check-body strong {
  font-size: 0.88rem;
  font-weight: 700;
}
.check-body small {
  font-size: 0.76rem;
  color: var(--muted);
}

/* ── Form actions ── */
.ref-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding-top: 8px;
  border-top: 1px solid var(--line);
  margin-top: 2px;
  padding-top: 20px;
}
.btn {
  border: none;
  border-radius: 10px;
  padding: 11px 20px;
  font: inherit;
  font-weight: 700;
  font-size: 0.88rem;
  cursor: pointer;
  transition: transform 0.12s, background 0.15s, border-color 0.15s,
    box-shadow 0.15s;
}
.btn:active {
  transform: translateY(1px);
}
.btn.full {
  width: 100%;
}
.btn.ghost {
  background: var(--white);
  border: 1px solid var(--line-2);
  color: var(--ink-2);
}
.btn.ghost:hover {
  background: var(--teal-50);
  border-color: var(--teal);
  color: var(--teal-d);
}
.btn.solid {
  background: var(--teal-d);
  color: #fff;
  box-shadow: 0 6px 16px rgba(12, 122, 115, 0.22);
}
.btn.solid:hover {
  background: var(--teal-700);
}

/* ── Preview column ── */
.preview {
  position: sticky;
  top: 24px;
}
.preview-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-1);
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.preview-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.84rem;
  font-weight: 800;
  color: var(--ink);
  letter-spacing: -0.01em;
}
.brand-dot {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--teal);
  box-shadow: 0 0 0 4px var(--teal-50);
}
.badge.urg {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 11px;
  border-radius: 999px;
  white-space: nowrap;
}
.badge.urg.ok {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}
.badge.urg.warn {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.badge.urg.danger {
  background: rgba(212, 80, 62, 0.14);
  color: var(--danger);
}

.pv-kicker {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  margin-top: -6px;
}

.pv-patient {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px;
  background: var(--bg);
  border-radius: var(--r-md);
}
.pv-patient strong {
  display: block;
  font-size: 0.9rem;
  font-weight: 700;
}
.pv-patient span {
  font-size: 0.76rem;
  color: var(--muted);
}

.pv-grid {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.pv-row dt,
.pv-block dt {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 3px;
}
.pv-row dd {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--ink);
}
.pv-block {
  border-top: 1px dashed var(--line);
  padding-top: 13px;
}
.pv-block dd {
  font-size: 0.84rem;
  color: var(--ink-2);
  white-space: pre-wrap;
  word-break: break-word;
}
.empty {
  color: var(--muted) !important;
  font-weight: 500 !important;
  font-style: italic;
}

.pv-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.pv-tag {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--teal-d);
  background: var(--teal-50);
  border-radius: 999px;
  padding: 4px 10px;
}

.pv-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border-top: 1px solid var(--line);
  padding-top: 13px;
  font-size: 0.74rem;
  color: var(--muted);
  font-weight: 600;
}
.pv-ref {
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}

/* ── Confirmation ── */
.confirm-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-2);
  padding: 26px 22px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  animation: pop 0.35s cubic-bezier(0.2, 0.9, 0.3, 1.2);
}
@keyframes pop {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.confirm-mark {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
  display: grid;
  place-items: center;
}
.confirm-card h2 {
  font-size: 1.2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.confirm-sub {
  font-size: 0.84rem;
  color: var(--muted);
  max-width: 32ch;
}
.ref-number {
  width: 100%;
  background: var(--teal-50);
  border: 1px dashed var(--teal);
  border-radius: var(--r-md);
  padding: 13px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.ref-label {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--teal-d);
}
.ref-number strong {
  font-size: 1.24rem;
  font-weight: 800;
  color: var(--teal-700);
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
}
.confirm-list {
  width: 100%;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0;
}
.confirm-list li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 2px;
  font-size: 0.84rem;
  font-weight: 600;
  border-top: 1px solid var(--line);
  text-align: left;
}
.confirm-list .k {
  color: var(--muted);
  font-weight: 600;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%) translateY(8px);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
  opacity: 0;
  transition: opacity 0.22s, transform 0.22s;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}
.toast::before {
  content: "✓";
  margin-right: 8px;
  color: #6fe0b4;
  font-weight: 800;
}

/* ── Responsive ── */
@media (max-width: 860px) {
  .ref {
    grid-template-columns: 1fr;
  }
  .preview {
    position: static;
    order: -1;
  }
}

@media (max-width: 520px) {
  .ref {
    padding: 22px 14px 48px;
  }
  .ref-form {
    padding: 20px 16px;
  }
  .ref-head {
    flex-direction: column;
    gap: 12px;
  }
  .seg-btn {
    padding: 9px 4px;
    font-size: 0.8rem;
  }
  .ref-actions {
    flex-direction: column-reverse;
  }
  .ref-actions .btn {
    width: 100%;
  }
  .patient-chip {
    flex-wrap: wrap;
  }
}

