// ── Toast ──────────────────────────────────────────────────────────────────
const toastEl = document.getElementById("toast");
function toast(msg) {
  toastEl.textContent = msg;
  toastEl.hidden = false;
  clearTimeout(toast._t);
  toast._t = setTimeout(() => (toastEl.hidden = true), 2600);
}

// ── Time model ───────────────────────────────────────────────────────────────
// 8:00 AM → 5:00 PM in 30-min blocks. Slot index 0 = 8:00.
const START_MIN = 8 * 60;
const SLOT_MIN = 30;
const SLOTS = 18; // 8:00 .. 4:30 start blocks (last visible block 4:30–5:00)

function slotToLabel(i) {
  const total = START_MIN + i * SLOT_MIN;
  let h = Math.floor(total / 60);
  const m = total % 60;
  const mer = h >= 12 ? "PM" : "AM";
  if (h > 12) h -= 12;
  if (h === 0) h = 12;
  return `${h}:${String(m).padStart(2, "0")} ${mer}`;
}

// ── Data: doctors, rooms, appointments ───────────────────────────────────────
const doctors = [
  { id: "okafor", name: "Dr. Lena Okafor", spec: "Cardiology", initials: "LO" },
  { id: "patel", name: "Dr. Ravi Patel", spec: "Primary care", initials: "RP" },
  { id: "bloom", name: "Dr. Maya Bloom", spec: "Dermatology", initials: "MB" },
  { id: "reyes", name: "Dr. Tomas Reyes", spec: "Orthopedics", initials: "TR" },
  { id: "novak", name: "Dr. Anja Novak", spec: "Pediatrics", initials: "AN" },
];

const rooms = [
  { id: "r201", name: "Room 201", spec: "Exam · Floor 2", initials: "201" },
  { id: "r202", name: "Room 202", spec: "Exam · Floor 2", initials: "202" },
  { id: "r210", name: "Procedure A", spec: "Surgical · Floor 2", initials: "PA" },
  { id: "r305", name: "Room 305", spec: "Exam · Floor 3", initials: "305" },
  { id: "tele", name: "Telehealth", spec: "Remote bay", initials: "TH" },
];

const TYPES = {
  new: { label: "New patient", cls: "t-new" },
  follow: { label: "Follow-up", cls: "t-follow" },
  proc: { label: "Procedure", cls: "t-proc" },
  tele: { label: "Telehealth", cls: "t-tele" },
};

// start = slot index, len = number of 30-min blocks
const appts = [
  // Okafor
  { doctor: "okafor", room: "r201", start: 0, len: 1, type: "follow", patient: "George Hale", reason: "Hypertension review" },
  { doctor: "okafor", room: "r201", start: 2, len: 2, type: "new", patient: "Priya Anand", reason: "Initial cardiac consult" },
  { doctor: "okafor", room: "tele", start: 6, len: 1, type: "tele", patient: "Marcus Webb", reason: "ECG results call" },
  { doctor: "okafor", room: "r210", start: 10, len: 3, type: "proc", patient: "Dolores Kim", reason: "Stress echocardiogram" },
  { doctor: "okafor", room: "r201", start: 15, len: 1, type: "follow", patient: "Ian Frost", reason: "Medication titration" },
  // Patel
  { doctor: "patel", room: "r202", start: 0, len: 2, type: "new", patient: "Sofia Marlow", reason: "New patient intake" },
  { doctor: "patel", room: "r202", start: 3, len: 1, type: "follow", patient: "Henry Dawes", reason: "Lab follow-up" },
  { doctor: "patel", room: "tele", start: 5, len: 1, type: "tele", patient: "Aisha Bello", reason: "Refill check-in" },
  { doctor: "patel", room: "r202", start: 8, len: 2, type: "follow", patient: "Owen Pritchard", reason: "Diabetes management" },
  { doctor: "patel", room: "r202", start: 12, len: 1, type: "new", patient: "Lucia Mendez", reason: "Annual physical" },
  { doctor: "patel", room: "r202", start: 16, len: 2, type: "follow", patient: "Nadia Hart", reason: "Thyroid recheck" },
  // Bloom
  { doctor: "bloom", room: "r305", start: 1, len: 1, type: "follow", patient: "Theo Vance", reason: "Eczema follow-up" },
  { doctor: "bloom", room: "r210", start: 3, len: 2, type: "proc", patient: "Renata Cole", reason: "Lesion excision" },
  { doctor: "bloom", room: "r305", start: 7, len: 1, type: "new", patient: "Jonah Reed", reason: "Skin screening" },
  { doctor: "bloom", room: "tele", start: 11, len: 1, type: "tele", patient: "Mira Solis", reason: "Rash photo review" },
  { doctor: "bloom", room: "r305", start: 14, len: 2, type: "follow", patient: "Caleb Nguyen", reason: "Acne treatment review" },
  // Reyes
  { doctor: "reyes", room: "r210", start: 0, len: 3, type: "proc", patient: "Della Ortiz", reason: "Knee arthroscopy" },
  { doctor: "reyes", room: "r305", start: 5, len: 1, type: "new", patient: "Sam Whitlock", reason: "Shoulder eval" },
  { doctor: "reyes", room: "r305", start: 8, len: 1, type: "follow", patient: "Bea Lindqvist", reason: "Post-op check" },
  { doctor: "reyes", room: "tele", start: 12, len: 1, type: "tele", patient: "Omar Said", reason: "Imaging review" },
  { doctor: "reyes", room: "r305", start: 15, len: 2, type: "follow", patient: "Grace Yoon", reason: "Physio progress" },
  // Novak
  { doctor: "novak", room: "r201", start: 4, len: 1, type: "new", patient: "Eli Brandt (age 6)", reason: "Well-child visit" },
  { doctor: "novak", room: "r201", start: 6, len: 1, type: "follow", patient: "Maya Tran (age 4)", reason: "Asthma follow-up" },
  { doctor: "novak", room: "tele", start: 9, len: 1, type: "tele", patient: "Liam Hayes (age 9)", reason: "Cold symptoms call" },
  { doctor: "novak", room: "r201", start: 11, len: 2, type: "new", patient: "Zoe Park (age 2)", reason: "Vaccination + intake" },
  { doctor: "novak", room: "r201", start: 16, len: 1, type: "follow", patient: "Noah Fields (age 7)", reason: "Growth check" },
];

// ── State ────────────────────────────────────────────────────────────────────
let viewMode = "doctor"; // "doctor" | "room"
let range = "day"; // "day" | "week"
let filter = "all";

const grid = document.getElementById("grid");

// ── Populate doctor filter ───────────────────────────────────────────────────
const docFilter = document.getElementById("doctor-filter");
doctors.forEach((d) => {
  const opt = document.createElement("option");
  opt.value = d.id;
  opt.textContent = d.name;
  docFilter.appendChild(opt);
});

// ── Render the grid ──────────────────────────────────────────────────────────
function render() {
  const rows = viewMode === "doctor" ? doctors : rooms;
  const rowKey = viewMode === "doctor" ? "doctor" : "room";

  grid.style.gridTemplateColumns = `var(--label-w) repeat(${SLOTS}, var(--col-w))`;
  grid.innerHTML = "";

  // header row: corner + time labels
  const corner = document.createElement("div");
  corner.className = "g-corner";
  corner.textContent = viewMode === "doctor" ? "Provider" : "Room";
  grid.appendChild(corner);

  for (let i = 0; i < SLOTS; i++) {
    const t = document.createElement("div");
    t.className = "g-time";
    // label only on the hour to reduce clutter
    t.textContent = i % 2 === 0 ? slotToLabel(i) : "";
    grid.appendChild(t);
  }

  // body rows
  rows.forEach((row) => {
    const label = document.createElement("div");
    label.className = "g-rowlabel";
    label.innerHTML =
      `<span class="row-avatar">${row.initials}</span>` +
      `<span class="row-meta">` +
      `<span class="row-name">${escape(row.name)}</span>` +
      `<span class="row-spec">${escape(row.spec)}</span>` +
      `</span>`;
    grid.appendChild(label);

    // track spanning all slot columns
    const track = document.createElement("div");
    track.className = "g-track";
    track.style.gridColumn = `2 / span ${SLOTS}`;
    for (let i = 0; i < SLOTS; i++) {
      const cell = document.createElement("div");
      cell.className = "g-cell" + (i % 2 === 1 ? " is-half" : "");
      track.appendChild(cell);
    }

    // appointments for this row
    appts
      .filter((a) => a[rowKey] === row.id)
      .forEach((a) => {
        const block = document.createElement("button");
        const t = TYPES[a.type];
        const dimmed =
          filter !== "all" && a.doctor !== filter ? " is-dim" : "";
        block.className = `appt ${t.cls}${dimmed}`;
        block.style.left = `calc(${a.start} * var(--col-w) + 3px)`;
        block.style.width = `calc(${a.len} * var(--col-w) - 6px)`;
        block.dataset.id = `${a.doctor}-${a.start}-${a.room}`;
        const dctr = doctors.find((d) => d.id === a.doctor);
        block.innerHTML =
          `<span class="appt-name">${escape(a.patient)}</span>` +
          `<span class="appt-sub">${slotToLabel(a.start)} · ${t.label}</span>`;
        block.addEventListener("click", () => openDetail(a, dctr, block));
        block.setAttribute(
          "aria-label",
          `${a.patient}, ${t.label}, ${slotToLabel(a.start)}, ${
            dctr ? dctr.name : ""
          }`
        );
        track.appendChild(block);
      });

    grid.appendChild(track);
  });

  updateStats();
}

function escape(s) {
  const d = document.createElement("div");
  d.textContent = s;
  return d.innerHTML;
}

// ── Utilization summary (live) ───────────────────────────────────────────────
function updateStats() {
  // Count against currently visible rows, honoring the doctor filter.
  let visible = appts;
  if (filter !== "all") visible = appts.filter((a) => a.doctor === filter);

  const rows = viewMode === "doctor" ? doctors : rooms;
  const rowKey = viewMode === "doctor" ? "doctor" : "room";
  const activeRows =
    filter === "all"
      ? rows
      : rows.filter((r) =>
          visible.some((a) => a[rowKey] === r.id)
        );

  const capacity = (filter === "all" ? rows.length : activeRows.length || 1) *
    SLOTS *
    (range === "week" ? 5 : 1);

  let booked = visible.reduce((sum, a) => sum + a.len, 0);
  if (range === "week") booked = Math.round(booked * 4.6); // illustrative week fill

  const open = Math.max(capacity - booked, 0);
  const util = capacity ? Math.round((booked / capacity) * 100) : 0;

  document.getElementById("stat-booked").textContent = booked;
  document.getElementById("stat-open").textContent = open;
  document.getElementById("stat-util").textContent = `${util}%`;
  document.getElementById("util-fill").style.width = `${Math.min(util, 100)}%`;

  const unit = range === "week" ? "this week" : "today";
  document.getElementById("stat-booked-foot").textContent = `slots ${unit}`;
  document.getElementById("stat-open-foot").textContent = `slots ${unit}`;
}

// ── Detail side panel ────────────────────────────────────────────────────────
const panel = document.getElementById("detail");
const scrim = document.getElementById("scrim");
let activeBlock = null;

function openDetail(a, dctr, block) {
  if (activeBlock) activeBlock.classList.remove("is-active");
  activeBlock = block;
  block.classList.add("is-active");

  const t = TYPES[a.type];
  const room = rooms.find((r) => r.id === a.room);
  const tag = document.getElementById("detail-tag");
  tag.textContent = t.label;
  tag.className = `panel-tag ${t.cls}`;

  document.getElementById("detail-title").textContent = a.patient;
  const endLabel = slotToLabel(a.start + a.len);
  document.getElementById("detail-time").textContent = `${slotToLabel(
    a.start
  )} – ${endLabel}`;
  document.getElementById("detail-doctor").textContent = dctr
    ? `${dctr.name} · ${dctr.spec}`
    : "—";
  document.getElementById("detail-room").textContent = room ? room.name : "—";
  document.getElementById("detail-type").textContent = t.label;
  document.getElementById("detail-reason").textContent = a.reason;

  panel.hidden = false;
  panel.setAttribute("aria-hidden", "false");
  scrim.hidden = false;
  requestAnimationFrame(() => {
    panel.classList.add("is-open");
    scrim.classList.add("is-open");
  });
  document.getElementById("detail-close").focus();
}

function closeDetail() {
  panel.classList.remove("is-open");
  scrim.classList.remove("is-open");
  panel.setAttribute("aria-hidden", "true");
  if (activeBlock) activeBlock.classList.remove("is-active");
  setTimeout(() => {
    panel.hidden = true;
    scrim.hidden = true;
  }, 280);
}

document.getElementById("detail-close").addEventListener("click", closeDetail);
scrim.addEventListener("click", closeDetail);
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && !panel.hidden) closeDetail();
});

panel.querySelectorAll("[data-panel-action]").forEach((btn) => {
  btn.addEventListener("click", () => {
    const name = document.getElementById("detail-title").textContent;
    if (btn.dataset.panelAction === "checkin") {
      toast(`${name} checked in — provider notified.`);
    } else {
      toast(`Reschedule ${name}: drag to a new open slot.`);
    }
    closeDetail();
  });
});

// ── Toggles + filter ─────────────────────────────────────────────────────────
document.getElementById("view-toggle").addEventListener("click", (e) => {
  const btn = e.target.closest(".seg-btn");
  if (!btn || btn.dataset.view === viewMode) return;
  viewMode = btn.dataset.view;
  syncSeg("view-toggle", btn);
  // filter only applies to doctor rows; reset it when viewing rooms
  if (viewMode === "room") {
    filter = "all";
    docFilter.value = "all";
  }
  docFilter.disabled = viewMode === "room";
  render();
});

document.getElementById("range-toggle").addEventListener("click", (e) => {
  const btn = e.target.closest(".seg-btn");
  if (!btn || btn.dataset.range === range) return;
  range = btn.dataset.range;
  syncSeg("range-toggle", btn);
  document.querySelector(".sub").textContent =
    range === "week"
      ? "Northpoint Clinic · Week of June 8–12"
      : "Northpoint Clinic · Tuesday, June 9";
  updateStats();
  toast(range === "week" ? "Showing week utilization." : "Showing day view.");
});

docFilter.addEventListener("change", () => {
  filter = docFilter.value;
  render();
});

function syncSeg(groupId, active) {
  document.querySelectorAll(`#${groupId} .seg-btn`).forEach((b) => {
    const on = b === active;
    b.classList.toggle("is-active", on);
    b.setAttribute("aria-pressed", String(on));
  });
}

// ── Init ─────────────────────────────────────────────────────────────────────
render();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --sh-1: 0 1px 2px rgba(28, 42, 37, 0.06), 0 2px 8px rgba(28, 42, 37, 0.05);
  --sh-2: 0 10px 30px rgba(28, 42, 37, 0.10), 0 2px 6px rgba(28, 42, 37, 0.06);
  --sh-3: 0 24px 60px rgba(22, 48, 42, 0.18);
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, sans-serif;
}

*,
*::before,
*::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--sans);
  background: var(--ivory);
  color: var(--ink);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3 { margin: 0; font-family: var(--serif); font-weight: 600; line-height: 1.08; }
p { margin: 0; }
ul { margin: 0; padding: 0; list-style: none; }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }

.wrap { width: min(1140px, 92vw); margin-inline: auto; }

/* ---------- shared bits ---------- */
.eyebrow,
.kicker {
  font-size: 0.74rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--brass-d);
}
.kicker { display: inline-flex; align-items: center; gap: 0.55rem; }
.kicker--center { justify-content: center; }
.hair { width: 28px; height: 1px; background: var(--brass); display: inline-block; }

.h2 {
  font-size: clamp(1.9rem, 1.2rem + 2vw, 2.9rem);
  color: var(--green-d);
  letter-spacing: 0.005em;
  margin-top: 0.4rem;
}
.lede { font-size: 1.12rem; color: var(--ink-2); margin-top: 1rem; }
.body { color: var(--ink-2); margin-top: 0.9rem; }

.ic { width: 18px; height: 18px; fill: currentColor; flex: none; }

.btn {
  --bg: var(--green);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: var(--sans);
  font-weight: 600;
  font-size: 0.95rem;
  padding: 0.72rem 1.15rem;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease, color 0.2s ease;
}
.btn:active { transform: translateY(1px); }
.btn--green { background: var(--green); color: var(--paper); box-shadow: var(--sh-1); }
.btn--green:hover { background: var(--green-d); box-shadow: var(--sh-2); }
.btn--brass { background: var(--brass); color: #2a1f0f; }
.btn--brass:hover { background: var(--brass-d); color: #fff; }
.btn--outline { background: var(--white); color: var(--green-d); border-color: var(--line-2); }
.btn--outline:hover { border-color: var(--green); box-shadow: var(--sh-1); }
.btn--ghost { background: transparent; color: var(--green-700); border-color: transparent; }
.btn--ghost:hover { background: var(--green-50); }
.btn--block { width: 100%; }
.btn:focus-visible { outline: 2px solid var(--brass); outline-offset: 3px; }

/* ---------- top bar ---------- */
.topbar {
  position: sticky;
  top: 0;
  z-index: 40;
  background: color-mix(in srgb, var(--ivory) 88%, transparent);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
}
.topbar__in { display: flex; align-items: center; gap: 1.5rem; padding: 0.85rem 0; }
.brand { display: inline-flex; align-items: center; gap: 0.6rem; }
.brand__mark {
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border-radius: 9px;
  background: var(--green);
  color: var(--brass-50);
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.25rem;
  box-shadow: inset 0 0 0 1px rgba(176, 141, 87, 0.5);
}
.brand__name { font-family: var(--serif); font-weight: 600; font-size: 1.2rem; color: var(--green-d); letter-spacing: 0.01em; }
.topnav { display: flex; gap: 1.4rem; margin-left: auto; font-size: 0.92rem; font-weight: 500; color: var(--ink-2); }
.topnav a { padding: 0.2rem 0; border-bottom: 1.5px solid transparent; transition: color 0.15s, border-color 0.15s; }
.topnav a:hover { color: var(--green-d); border-color: var(--brass); }
.topbar__cta { padding: 0.55rem 1.05rem; }

/* ---------- hero ---------- */
.hero { padding: clamp(2.5rem, 1rem + 6vw, 5rem) 0 clamp(2rem, 4vw, 3.5rem); }
.hero__in {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  gap: clamp(1.8rem, 4vw, 3.5rem);
  align-items: center;
}
.hero__portrait { margin: 0; position: relative; }
.portrait {
  aspect-ratio: 4 / 5;
  border-radius: var(--r-lg);
  box-shadow: var(--sh-3);
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(120% 80% at 70% 12%, rgba(247, 244, 236, 0.55), transparent 55%),
    radial-gradient(90% 70% at 30% 95%, rgba(22, 48, 42, 0.55), transparent 60%),
    linear-gradient(165deg, #5d7166 0%, #3b554b 38%, #243f37 70%, #16302a 100%);
}
.portrait::before {
  content: "";
  position: absolute;
  left: 50%; top: 30%;
  width: 46%; aspect-ratio: 1;
  transform: translateX(-50%);
  border-radius: 50% 50% 48% 48%;
  background: radial-gradient(60% 60% at 50% 40%, #e9d8bf, #d9bd97 60%, #b89a72 100%);
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.25);
}
.portrait::after {
  content: "";
  position: absolute;
  left: 50%; bottom: 0;
  width: 74%; height: 38%;
  transform: translateX(-50%);
  border-radius: 50% 50% 0 0;
  background: linear-gradient(180deg, #f3ead9, #d9c19a 70%, #c2a878);
  box-shadow: 0 -8px 24px rgba(0, 0, 0, 0.15);
}
.portrait__badge {
  position: absolute;
  left: 14px; bottom: 14px;
  display: inline-flex; align-items: center; gap: 0.45rem;
  background: rgba(255, 253, 248, 0.94);
  color: var(--green-d);
  font-size: 0.78rem; font-weight: 600;
  padding: 0.4rem 0.7rem;
  border-radius: 999px;
  box-shadow: var(--sh-1);
}
.dot { width: 8px; height: 8px; border-radius: 50%; background: var(--ok); box-shadow: 0 0 0 3px rgba(47, 158, 111, 0.22); }

.hero__name {
  font-size: clamp(2.6rem, 1.4rem + 4.5vw, 4.4rem);
  font-weight: 700;
  color: var(--green-d);
  margin-top: 0.6rem;
  letter-spacing: -0.005em;
}
.hero__role { font-family: var(--serif); font-size: 1.5rem; color: var(--brass-d); margin-top: 0.2rem; }
.hero__brand { color: var(--muted); font-size: 0.95rem; margin-top: 0.35rem; }
.hero__chips { display: flex; flex-wrap: wrap; gap: 0.5rem; margin-top: 1.2rem; }
.hero__chips li {
  font-size: 0.82rem; font-weight: 500;
  color: var(--green-700);
  background: var(--green-50);
  border: 1px solid var(--line);
  padding: 0.35rem 0.75rem;
  border-radius: 999px;
}
.hero__actions { display: flex; flex-wrap: wrap; gap: 0.7rem; margin-top: 1.7rem; }

/* ---------- stats ---------- */
.stats { padding: 1rem 0 0.5rem; }
.stats__grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
  box-shadow: var(--sh-1);
}
.stat { background: var(--paper); padding: 1.4rem 1rem; text-align: center; }
.stat__num { display: block; font-family: var(--serif); font-weight: 700; font-size: clamp(1.6rem, 1rem + 1.6vw, 2.25rem); color: var(--green-d); }
.stat__small { font-size: 0.55em; color: var(--brass-d); }
.stat__label { display: block; font-size: 0.76rem; color: var(--muted); margin-top: 0.25rem; letter-spacing: 0.02em; }

/* ---------- about ---------- */
.about { padding: clamp(3rem, 5vw, 5rem) 0; }
.about__in { display: grid; grid-template-columns: 1.55fr 0.9fr; gap: clamp(1.8rem, 4vw, 3.5rem); align-items: start; }
.areas {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 1.6rem 1.5rem;
  box-shadow: var(--sh-1);
}
.areas__title { font-size: 1.5rem; color: var(--green-d); }
.areas__list { margin-top: 1rem; }
.areas__list li { display: flex; justify-content: space-between; align-items: baseline; padding: 0.6rem 0; border-bottom: 1px solid var(--line); }
.areas__list li:last-child { border-bottom: 0; }
.areas__list span { color: var(--ink-2); font-weight: 500; }
.areas__list b { color: var(--green-700); font-variant-numeric: tabular-nums; font-size: 0.9rem; }
.areas__note { margin-top: 1rem; font-size: 0.85rem; color: var(--muted); padding-top: 0.9rem; border-top: 1px dashed var(--line-2); }

/* ---------- section heads ---------- */
.sec-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 1.5rem; flex-wrap: wrap; margin-bottom: 1.8rem; }
.sec-head--center { justify-content: center; text-align: center; }

/* ---------- tabs ---------- */
.tabs { display: inline-flex; background: var(--paper); border: 1px solid var(--line); border-radius: 999px; padding: 0.3rem; box-shadow: var(--sh-1); }
.tab {
  font-family: var(--sans);
  font-weight: 600; font-size: 0.92rem;
  color: var(--ink-2);
  background: transparent;
  border: 0; cursor: pointer;
  padding: 0.5rem 1.1rem;
  border-radius: 999px;
  display: inline-flex; align-items: center; gap: 0.45rem;
  transition: background 0.18s, color 0.18s;
}
.tab__count { font-size: 0.72rem; background: var(--green-50); color: var(--green-700); padding: 0.05rem 0.45rem; border-radius: 999px; }
.tab.is-active { background: var(--green); color: var(--paper); }
.tab.is-active .tab__count { background: rgba(255, 253, 248, 0.2); color: var(--brass-50); }
.tab:focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }

/* ---------- listings grid ---------- */
.listings { padding: clamp(1rem, 3vw, 2rem) 0 clamp(3rem, 5vw, 5rem); }
.grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.3rem; }
.grid.is-hidden { display: none; }

.card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--sh-1);
  transition: transform 0.2s ease, box-shadow 0.25s ease, border-color 0.2s ease;
  animation: rise 0.4s ease both;
}
.card:hover { transform: translateY(-4px); box-shadow: var(--sh-2); border-color: var(--line-2); }
.card__photo { aspect-ratio: 4 / 3; position: relative; }
.card__body { padding: 1rem 1.1rem 1.2rem; }
.card__title { font-size: 1.35rem; color: var(--green-d); }
.card__addr { color: var(--muted); font-size: 0.86rem; margin-top: 0.15rem; }
.specs { display: flex; flex-wrap: wrap; gap: 0.4rem 0.6rem; margin-top: 0.8rem; }
.specs li {
  font-size: 0.78rem; font-weight: 500; color: var(--ink-2);
  background: var(--ivory);
  border: 1px solid var(--line);
  padding: 0.25rem 0.55rem;
  border-radius: var(--r-sm);
  font-variant-numeric: tabular-nums;
}
.card__cta {
  margin-top: 1rem;
  width: 100%;
  font-family: var(--sans); font-weight: 600; font-size: 0.9rem;
  color: var(--green-d);
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: 999px;
  padding: 0.6rem;
  cursor: pointer;
  transition: background 0.18s, color 0.18s, border-color 0.18s;
}
.card__cta:hover { background: var(--green); color: var(--paper); border-color: var(--green); }
.card__cta:focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }
.sold-note { margin-top: 0.9rem; font-size: 0.83rem; font-weight: 600; color: var(--green-700); }
.card--sold .card__photo { filter: saturate(0.85); }

.badge {
  position: absolute;
  font-size: 0.75rem; font-weight: 600;
  padding: 0.32rem 0.6rem;
  border-radius: 999px;
  backdrop-filter: blur(2px);
}
.badge--status { top: 12px; left: 12px; background: rgba(255, 253, 248, 0.92); color: var(--green-d); }
.badge--new { background: var(--brass); color: #2a1f0f; }
.badge--sold { top: 12px; left: 12px; background: var(--green-d); color: var(--brass-50); }
.badge--price { bottom: 12px; right: 12px; background: rgba(22, 48, 42, 0.9); color: #fff; letter-spacing: 0.01em; }

/* simulated listing photography */
.ph-1 { background: radial-gradient(120% 100% at 20% 10%, #cfe0e6, transparent 55%), linear-gradient(150deg, #93b2bd 0%, #5e8492 45%, #355661 100%); }
.ph-2 { background: radial-gradient(110% 90% at 80% 15%, #f3e7cf, transparent 55%), linear-gradient(155deg, #c9a878 0%, #9c7d54 50%, #6e5436 100%); }
.ph-3 { background: radial-gradient(120% 100% at 30% 90%, #d7e3cf, transparent 55%), linear-gradient(150deg, #9fb98a 0%, #6f8e5d 48%, #3f5b32 100%); }
.ph-4 { background: radial-gradient(110% 90% at 75% 20%, #e9dcc9, transparent 55%), linear-gradient(160deg, #d8c4a4 0%, #b49a73 45%, #7e6644 100%); }
.ph-5 { background: radial-gradient(120% 100% at 25% 12%, #d9d2e6, transparent 55%), linear-gradient(150deg, #9d93b6 0%, #6c618c 50%, #443a63 100%); }
.ph-6 { background: radial-gradient(110% 90% at 80% 18%, #f1d9cd, transparent 55%), linear-gradient(155deg, #d8a98e 0%, #b07b5d 48%, #774a32 100%); }
.ph-7 { background: radial-gradient(120% 100% at 30% 90%, #cfe2df, transparent 55%), linear-gradient(150deg, #8fc0b6 0%, #5a958a 48%, #336158 100%); }
.ph-8 { background: radial-gradient(110% 90% at 70% 15%, #e6e2d0, transparent 55%), linear-gradient(160deg, #c4bf99 0%, #9a946b 48%, #65613f 100%); }

@keyframes rise { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: translateY(0); } }

/* ---------- reviews ---------- */
.reviews { padding: clamp(3rem, 5vw, 5rem) 0; background: linear-gradient(180deg, var(--green) 0%, var(--green-d) 100%); color: var(--paper); }
.reviews .h2 { color: var(--paper); }
.reviews .kicker { color: var(--brass); }
.reviews .hair { background: var(--brass); }
.carousel { display: flex; align-items: center; gap: 1rem; max-width: 820px; margin: 0 auto; }
.car-viewport { overflow: hidden; flex: 1; border-radius: var(--r-lg); }
.car-track { display: flex; transition: transform 0.45s cubic-bezier(0.4, 0, 0.2, 1); }
.review { flex: 0 0 100%; padding: 0.4rem 0.6rem 0.2rem; text-align: center; }
.review__stars { color: var(--brass); letter-spacing: 0.18em; font-size: 1rem; }
.review blockquote { margin: 0.9rem 0 0; font-family: var(--serif); font-size: clamp(1.3rem, 0.9rem + 1.4vw, 1.85rem); line-height: 1.32; color: var(--ivory); }
.review figcaption { margin-top: 1.1rem; font-size: 0.9rem; color: rgba(247, 244, 236, 0.72); }
.review figcaption b { color: var(--brass-50); }
.car-btn {
  flex: none;
  width: 44px; height: 44px;
  border-radius: 50%;
  display: grid; place-items: center;
  background: rgba(255, 253, 248, 0.08);
  border: 1px solid rgba(247, 244, 236, 0.22);
  color: var(--ivory);
  cursor: pointer;
  transition: background 0.18s, border-color 0.18s;
}
.car-btn:hover { background: rgba(255, 253, 248, 0.18); border-color: var(--brass); }
.car-btn svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.car-btn:focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }
.dots { display: flex; gap: 0.5rem; justify-content: center; margin-top: 1.8rem; }
.dots button {
  width: 9px; height: 9px; padding: 0;
  border-radius: 50%;
  border: 0;
  background: rgba(247, 244, 236, 0.3);
  cursor: pointer;
  transition: background 0.2s, transform 0.2s;
}
.dots button.is-active { background: var(--brass); transform: scale(1.25); }
.dots button:focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }

/* ---------- contact ---------- */
.contact { padding: clamp(3rem, 5vw, 5.5rem) 0; }
.contact__in { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(2rem, 4vw, 4rem); align-items: start; }
.contact__meta { margin-top: 1.6rem; display: grid; gap: 0.7rem; }
.contact__meta li { font-size: 0.95rem; color: var(--ink-2); }
.contact__meta b { display: block; font-size: 0.72rem; letter-spacing: 0.14em; text-transform: uppercase; color: var(--brass-d); margin-bottom: 0.1rem; }

.form { background: var(--paper); border: 1px solid var(--line); border-radius: var(--r-lg); padding: clamp(1.4rem, 3vw, 2.2rem); box-shadow: var(--sh-2); }
.field { display: flex; flex-direction: column; gap: 0.35rem; margin-bottom: 1rem; }
.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
.field label { font-size: 0.82rem; font-weight: 600; color: var(--ink-2); }
.field .opt { font-weight: 400; color: var(--muted); }
.field input,
.field select,
.field textarea {
  font-family: var(--sans);
  font-size: 0.95rem;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 0.65rem 0.8rem;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.field textarea { resize: vertical; min-height: 90px; }
.field input:focus,
.field select:focus,
.field textarea:focus { outline: none; border-color: var(--green); box-shadow: 0 0 0 3px rgba(31, 61, 52, 0.12); }
.field input:user-invalid,
.field textarea:user-invalid { border-color: var(--danger); }
.form .btn { margin-top: 0.4rem; }
.form__fine { margin-top: 0.8rem; font-size: 0.78rem; color: var(--muted); text-align: center; }

/* ---------- footer ---------- */
.foot { border-top: 1px solid var(--line); padding: 2rem 0; }
.foot__in { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 0.4rem; }
.foot p { font-size: 0.9rem; color: var(--ink-2); }
.foot__fine { color: var(--muted); font-size: 0.82rem; }

/* ---------- toast ---------- */
.toast {
  position: fixed;
  left: 50%; bottom: 26px;
  transform: translate(-50%, 140%);
  background: var(--green-d);
  color: var(--paper);
  font-weight: 500; font-size: 0.92rem;
  padding: 0.8rem 1.2rem;
  border-radius: 999px;
  box-shadow: var(--sh-3);
  z-index: 80;
  opacity: 0;
  transition: transform 0.4s cubic-bezier(0.2, 0.9, 0.3, 1.2), opacity 0.3s;
  max-width: 90vw;
}
.toast.show { transform: translate(-50%, 0); opacity: 1; }
.toast::before { content: "✓"; color: var(--brass); font-weight: 700; margin-right: 0.5rem; }

/* ---------- responsive ---------- */
@media (max-width: 960px) {
  .hero__in { grid-template-columns: 1fr; }
  .hero__portrait { max-width: 360px; }
  .stats__grid { grid-template-columns: repeat(3, 1fr); }
  .stat:nth-child(4) { border-top: 1px solid var(--line); }
  .stat:nth-child(5) { border-top: 1px solid var(--line); }
  .about__in { grid-template-columns: 1fr; }
  .contact__in { grid-template-columns: 1fr; }
  .grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 520px) {
  .topnav { display: none; }
  .topbar__cta { margin-left: auto; }
  .stats__grid { grid-template-columns: repeat(2, 1fr); }
  .stat:nth-child(3) { border-top: 1px solid var(--line); }
  .stat:nth-child(5) { grid-column: 1 / -1; border-top: 1px solid var(--line); }
  .hero__actions .btn { flex: 1 1 auto; }
  .grid { grid-template-columns: 1fr; }
  .field-row { grid-template-columns: 1fr; }
  .carousel { gap: 0.4rem; }
  .car-btn { width: 38px; height: 38px; }
  .foot__in { justify-content: center; text-align: center; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; scroll-behavior: auto !important; }
}

