(function () {
  "use strict";

  /* ---------- toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 3200);
  }

  /* ---------- listing tab switch (active / sold) ---------- */
  var tabs = Array.prototype.slice.call(document.querySelectorAll(".tab"));
  var panels = {
    active: document.querySelector('[data-panel="active"]'),
    sold: document.querySelector('[data-panel="sold"]'),
  };

  function selectTab(name) {
    tabs.forEach(function (tab) {
      var on = tab.dataset.tab === name;
      tab.classList.toggle("is-active", on);
      tab.setAttribute("aria-selected", on ? "true" : "false");
      tab.tabIndex = on ? 0 : -1;
    });
    Object.keys(panels).forEach(function (key) {
      var panel = panels[key];
      if (!panel) return;
      var on = key === name;
      panel.classList.toggle("is-hidden", !on);
      if (on) {
        panel.removeAttribute("hidden");
        // re-trigger the rise animation on the newly shown cards
        panel.querySelectorAll(".card").forEach(function (card, i) {
          card.style.animation = "none";
          // force reflow
          void card.offsetWidth;
          card.style.animation = "";
          card.style.animationDelay = i * 0.05 + "s";
        });
      } else {
        panel.setAttribute("hidden", "");
      }
    });
  }

  tabs.forEach(function (tab, idx) {
    tab.addEventListener("click", function () {
      selectTab(tab.dataset.tab);
    });
    tab.addEventListener("keydown", function (e) {
      if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
      e.preventDefault();
      var next = e.key === "ArrowRight" ? (idx + 1) % tabs.length : (idx - 1 + tabs.length) % tabs.length;
      tabs[next].focus();
      selectTab(tabs[next].dataset.tab);
    });
  });

  /* ---------- tour request buttons ---------- */
  document.querySelectorAll("[data-tour]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      toast("Tour requested for " + btn.dataset.tour + " — Marguerite will be in touch.");
    });
  });

  /* ---------- share ---------- */
  var shareBtn = document.getElementById("shareBtn");
  if (shareBtn) {
    shareBtn.addEventListener("click", function () {
      var data = {
        title: "Marguerite Alcott — Halford & Vane",
        text: "Marguerite Alcott, Principal Broker on the Marisol coast.",
        url: location.href,
      };
      if (navigator.share) {
        navigator.share(data).catch(function () {});
      } else if (navigator.clipboard) {
        navigator.clipboard.writeText(location.href).then(
          function () { toast("Profile link copied to clipboard."); },
          function () { toast("Couldn't copy — please copy the URL manually."); }
        );
      } else {
        toast("Sharing isn't supported in this browser.");
      }
    });
  }

  /* ---------- reviews carousel ---------- */
  var track = document.getElementById("revTrack");
  var prevBtn = document.getElementById("revPrev");
  var nextBtn = document.getElementById("revNext");
  var dotsWrap = document.getElementById("revDots");

  if (track) {
    var slides = Array.prototype.slice.call(track.querySelectorAll("[data-rev]"));
    var index = 0;
    var auto = null;

    // build dots
    slides.forEach(function (_, i) {
      var b = document.createElement("button");
      b.type = "button";
      b.setAttribute("role", "tab");
      b.setAttribute("aria-label", "Review " + (i + 1));
      b.addEventListener("click", function () { go(i, true); });
      dotsWrap.appendChild(b);
    });
    var dots = Array.prototype.slice.call(dotsWrap.children);

    function render() {
      track.style.transform = "translateX(" + -index * 100 + "%)";
      dots.forEach(function (d, i) {
        d.classList.toggle("is-active", i === index);
        d.setAttribute("aria-selected", i === index ? "true" : "false");
      });
    }
    function go(i, userInitiated) {
      index = (i + slides.length) % slides.length;
      render();
      if (userInitiated) restartAuto();
    }
    function startAuto() {
      auto = setInterval(function () { go(index + 1, false); }, 6000);
    }
    function restartAuto() {
      clearInterval(auto);
      startAuto();
    }

    if (nextBtn) nextBtn.addEventListener("click", function () { go(index + 1, true); });
    if (prevBtn) prevBtn.addEventListener("click", function () { go(index - 1, true); });

    // pause on hover / focus
    var carousel = track.closest(".reviews");
    if (carousel) {
      carousel.addEventListener("mouseenter", function () { clearInterval(auto); });
      carousel.addEventListener("mouseleave", startAuto);
      carousel.addEventListener("focusin", function () { clearInterval(auto); });
      carousel.addEventListener("focusout", startAuto);
    }

    // keyboard
    track.parentElement.addEventListener("keydown", function (e) {
      if (e.key === "ArrowRight") { e.preventDefault(); go(index + 1, true); }
      if (e.key === "ArrowLeft") { e.preventDefault(); go(index - 1, true); }
    });

    render();
    startAuto();
  }

  /* ---------- count-up stats ---------- */
  var counters = Array.prototype.slice.call(document.querySelectorAll("[data-count]"));
  if (counters.length && "IntersectionObserver" in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        animateCount(entry.target);
        io.unobserve(entry.target);
      });
    }, { threshold: 0.6 });
    counters.forEach(function (el) { io.observe(el); });
  }
  function animateCount(el) {
    var target = parseInt(el.dataset.count, 10) || 0;
    var dur = 1100;
    var start = performance.now();
    function tick(now) {
      var p = Math.min((now - start) / dur, 1);
      var eased = 1 - Math.pow(1 - p, 3);
      el.textContent = Math.round(target * eased).toString();
      if (p < 1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }

  /* ---------- contact form ---------- */
  var form = document.getElementById("contactForm");
  if (form) {
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      if (!form.checkValidity()) {
        var firstInvalid = form.querySelector(":invalid");
        if (firstInvalid) firstInvalid.focus();
        toast("Please complete the highlighted fields.");
        return;
      }
      var name = (form.elements.name.value || "").trim().split(" ")[0] || "there";
      form.reset();
      toast("Thanks, " + name + " — your message is on its way to Marguerite.");
    });
  }
})();

snippets.css:
:root {
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --sh-sm: 0 1px 2px rgba(28, 24, 20, 0.06), 0 1px 1px rgba(28, 24, 20, 0.04);
  --sh-md: 0 14px 34px -18px rgba(28, 24, 20, 0.32);
  --sh-lg: 0 38px 80px -42px rgba(28, 24, 20, 0.45);

  --nav-h: 72px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--nav-h) + 12px);
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  color: var(--ink-2);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

h1,
h2,
h3 {
  font-family: var(--serif);
  color: var(--ink);
  font-weight: 600;
  margin: 0;
  line-height: 1.06;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

.skip-link {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--ink);
  color: var(--cream);
  padding: 10px 16px;
  border-radius: var(--r-sm);
  z-index: 200;
}
.skip-link:focus {
  left: 12px;
  top: 12px;
}

:focus-visible {
  outline: 2px solid var(--gold-d);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------- shared bits ---------- */
.eyebrow {
  font-family: var(--sans);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold-d);
  margin: 0 0 14px;
}
.eyebrow--light {
  color: var(--gold-soft);
}

.btn {
  --btn-bg: var(--ink);
  --btn-fg: var(--cream);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--sans);
  font-size: 0.92rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  padding: 13px 24px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: var(--btn-bg);
  color: var(--btn-fg);
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease,
    color 0.18s ease, border-color 0.18s ease;
  white-space: nowrap;
}
.btn:hover {
  transform: translateY(-2px);
  box-shadow: var(--sh-md);
}
.btn:active {
  transform: translateY(0);
}
.btn--gold {
  --btn-bg: linear-gradient(135deg, var(--gold) 0%, var(--gold-d) 100%);
  --btn-fg: #fff;
}
.btn--outline {
  --btn-bg: transparent;
  --btn-fg: var(--ink);
  border-color: var(--line-2);
}
.btn--outline:hover {
  border-color: var(--gold);
  color: var(--gold-d);
}
.btn--ghost {
  --btn-bg: transparent;
  --btn-fg: var(--ink-2);
}
.btn--ghost:hover {
  --btn-fg: var(--gold-d);
  box-shadow: none;
}
.btn--sm {
  padding: 9px 16px;
  font-size: 0.85rem;
}
.btn--block {
  width: 100%;
}

/* ---------- nav ---------- */
.nav {
  position: fixed;
  inset: 0 0 auto 0;
  height: var(--nav-h);
  z-index: 100;
  display: flex;
  align-items: center;
  background: rgba(250, 246, 239, 0.55);
  backdrop-filter: saturate(140%) blur(14px);
  -webkit-backdrop-filter: saturate(140%) blur(14px);
  border-bottom: 1px solid transparent;
  transition: background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease,
    height 0.3s ease;
}
.nav.is-scrolled {
  background: rgba(250, 246, 239, 0.86);
  border-bottom-color: var(--line);
  box-shadow: var(--sh-sm);
}
.nav__inner {
  width: min(1180px, 92vw);
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 18px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-right: auto;
}
.brand__mark {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: linear-gradient(140deg, var(--gold) 0%, var(--gold-d) 100%);
  color: #fff;
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.05rem;
  letter-spacing: 0.02em;
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.25);
}
.brand__name {
  font-family: var(--serif);
  font-size: 1.32rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1;
}
.brand__name small {
  display: block;
  font-family: var(--sans);
  font-size: 0.6rem;
  font-weight: 600;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--muted);
  margin-top: 4px;
}
.nav__links {
  display: flex;
  gap: 6px;
}
.nav__link {
  position: relative;
  padding: 8px 14px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--ink-2);
  border-radius: var(--r-sm);
  transition: color 0.18s ease;
}
.nav__link::after {
  content: "";
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 4px;
  height: 1px;
  background: var(--gold);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.22s ease;
}
.nav__link:hover,
.nav__link.is-active {
  color: var(--gold-d);
}
.nav__link:hover::after,
.nav__link.is-active::after {
  transform: scaleX(1);
}
.nav__actions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.nav__toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 42px;
  height: 42px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  background: transparent;
  cursor: pointer;
}
.nav__toggle span {
  display: block;
  height: 1.6px;
  width: 20px;
  margin: 0 auto;
  background: var(--ink);
  transition: transform 0.25s ease, opacity 0.2s ease;
}
.nav__toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(6.6px) rotate(45deg);
}
.nav__toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}
.nav__toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-6.6px) rotate(-45deg);
}

/* ---------- hero ---------- */
.hero {
  position: relative;
  padding: calc(var(--nav-h) + 86px) 0 96px;
  overflow: hidden;
}
.hero__media {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.hero__glow {
  position: absolute;
  top: -18%;
  right: -8%;
  width: 60vw;
  height: 60vw;
  max-width: 760px;
  max-height: 760px;
  background: radial-gradient(
    circle at 50% 50%,
    rgba(201, 167, 143, 0.5),
    rgba(201, 167, 143, 0) 62%
  );
  filter: blur(8px);
}
.hero__photo {
  position: absolute;
  inset: 0;
  background: radial-gradient(
      120% 120% at 78% 8%,
      rgba(239, 226, 207, 0.9) 0%,
      rgba(239, 226, 207, 0) 48%
    ),
    linear-gradient(180deg, var(--bg) 0%, var(--cream) 100%);
}
.hero__inner {
  position: relative;
  z-index: 1;
  width: min(1180px, 92vw);
  margin: 0 auto;
}
.hero__title {
  font-size: clamp(2.9rem, 7.6vw, 5.6rem);
  letter-spacing: -0.01em;
  max-width: 16ch;
}
.hero__title em {
  font-style: italic;
  color: var(--gold-d);
}
.hero__lede {
  margin: 26px 0 0;
  max-width: 52ch;
  font-size: 1.08rem;
  color: var(--ink-2);
}
.hero__cta {
  margin-top: 32px;
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}
.hero__stats {
  list-style: none;
  margin: 56px 0 0;
  padding: 26px 0 0;
  border-top: 1px solid var(--line);
  display: flex;
  flex-wrap: wrap;
  gap: 48px;
}
.hero__stats strong {
  display: block;
  font-family: var(--serif);
  font-size: 2.6rem;
  font-weight: 700;
  color: var(--ink);
  line-height: 1;
}
.hero__stats span {
  display: block;
  margin-top: 6px;
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- section scaffolding ---------- */
.section {
  width: min(1180px, 92vw);
  margin: 0 auto;
  padding: 104px 0;
}
.section--tight {
  padding: 84px 0;
}
.section__head {
  max-width: 56ch;
  margin-bottom: 48px;
}
.section__title {
  font-size: clamp(2.2rem, 4.6vw, 3.4rem);
  letter-spacing: -0.01em;
}
.section__sub {
  margin: 16px 0 0;
  color: var(--muted);
  font-size: 1.02rem;
}

/* ---------- services ---------- */
.services {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}
.svc {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 30px 28px;
  box-shadow: var(--sh-sm);
  transition: transform 0.22s ease, box-shadow 0.22s ease,
    border-color 0.22s ease;
  position: relative;
}
.svc::after {
  content: "";
  position: absolute;
  left: 28px;
  right: 28px;
  top: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--gold), var(--rose));
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
  border-radius: 2px;
}
.svc:hover {
  transform: translateY(-6px);
  box-shadow: var(--sh-md);
  border-color: rgba(176, 141, 87, 0.45);
}
.svc:hover::after {
  transform: scaleX(1);
}
.svc__icon {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--gold-soft);
  color: var(--gold-d);
  font-size: 1.25rem;
  margin-bottom: 18px;
}
.svc h3 {
  font-size: 1.5rem;
}
.svc p {
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 0.95rem;
}
.svc__price {
  margin-top: 18px !important;
  color: var(--ink-2) !important;
  font-size: 0.82rem !important;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.svc__price strong {
  font-family: var(--serif);
  font-size: 1.5rem;
  color: var(--gold-d);
  letter-spacing: 0;
}

/* ---------- why band ---------- */
.why {
  background:
    radial-gradient(120% 140% at 0% 0%, rgba(176, 141, 87, 0.16), transparent 55%),
    var(--ink);
  color: var(--cream);
  padding: 104px 0;
}
.why__inner {
  width: min(1180px, 92vw);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: 60px;
  align-items: start;
}
.why__title {
  color: var(--cream);
  font-size: clamp(2.2rem, 4.4vw, 3.2rem);
}
.why__sub {
  margin: 18px 0 0;
  color: rgba(247, 241, 232, 0.66);
  font-size: 1.04rem;
}
.why__grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 30px 40px;
}
.why__item {
  border-top: 1px solid rgba(239, 226, 207, 0.22);
  padding-top: 20px;
}
.why__num {
  font-family: var(--serif);
  font-size: 1.3rem;
  color: var(--gold);
}
.why__item h3 {
  color: var(--cream);
  font-size: 1.4rem;
  margin: 8px 0 8px;
}
.why__item p {
  margin: 0;
  color: rgba(247, 241, 232, 0.6);
  font-size: 0.92rem;
}

/* ---------- stylists ---------- */
.stylists {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}
.stylist {
  font: inherit;
  text-align: center;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 30px 18px;
  cursor: pointer;
  box-shadow: var(--sh-sm);
  transition: transform 0.22s ease, box-shadow 0.22s ease,
    border-color 0.22s ease;
}
.stylist:hover {
  transform: translateY(-6px);
  box-shadow: var(--sh-md);
  border-color: rgba(176, 141, 87, 0.45);
}
.stylist__avatar {
  width: 92px;
  height: 92px;
  margin: 0 auto 16px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(150deg, var(--a, var(--rose)), var(--b, var(--gold-soft)));
  box-shadow: inset 0 0 0 4px rgba(255, 255, 255, 0.6);
  position: relative;
}
.stylist__avatar::after {
  content: attr(data-initials);
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.8rem;
  color: var(--ink);
  opacity: 0.78;
}
.stylist__name {
  display: block;
  font-family: var(--serif);
  font-size: 1.32rem;
  font-weight: 600;
  color: var(--ink);
}
.stylist__role {
  display: block;
  margin-top: 4px;
  font-size: 0.78rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- testimonial ---------- */
.quote {
  background: var(--cream);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 96px 0;
}
.quote__inner {
  width: min(840px, 92vw);
  margin: 0 auto;
  text-align: center;
  position: relative;
}
.quote__mark {
  font-family: var(--serif);
  font-size: 6rem;
  line-height: 0.5;
  color: var(--gold);
  opacity: 0.55;
  margin: 0 0 8px;
}
.quote blockquote {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3.6vw, 2.3rem);
  font-weight: 500;
  font-style: italic;
  color: var(--ink);
  line-height: 1.3;
}
.quote__by {
  margin: 26px 0 0;
}
.quote__by strong {
  font-family: var(--serif);
  font-size: 1.2rem;
  color: var(--ink);
}
.quote__by span {
  display: block;
  margin-top: 2px;
  font-size: 0.78rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.quote__stars {
  margin: 14px 0 0;
  color: var(--gold);
  letter-spacing: 0.32em;
  font-size: 0.95rem;
}

/* ---------- gallery ---------- */
.gallery {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 14px;
}
.tile {
  aspect-ratio: 1;
  border-radius: var(--r-md);
  box-shadow: var(--sh-sm);
  transition: transform 0.3s ease, box-shadow 0.3s ease, filter 0.3s ease;
  filter: saturate(0.96);
}
.tile:hover {
  transform: translateY(-4px) scale(1.02);
  box-shadow: var(--sh-md);
  filter: saturate(1.06);
}
.tile--1 { background: linear-gradient(145deg, #d9bda3, #b08d57); }
.tile--2 { background: linear-gradient(145deg, #efe2cf, #c9a78f); }
.tile--3 { background: linear-gradient(145deg, #3d362f, #8a7d70); }
.tile--4 { background: linear-gradient(145deg, #f3e6dc, #b08d57); }
.tile--5 { background: linear-gradient(145deg, #c9a78f, #8c6d3f); }
.tile--6 { background: linear-gradient(145deg, #f7f1e8, #c9a78f); }

/* ---------- visit / book ---------- */
.visit {
  background: var(--white);
  border-top: 1px solid var(--line);
}
.visit__inner {
  width: min(1180px, 92vw);
  margin: 0 auto;
  padding: 104px 0;
  display: grid;
  grid-template-columns: 1fr 0.9fr;
  gap: 64px;
  align-items: start;
}
.visit__title {
  font-size: clamp(2.2rem, 4.4vw, 3.2rem);
}
.visit__addr {
  margin: 18px 0 28px;
  font-size: 1.05rem;
  color: var(--ink-2);
}
.hours {
  margin: 0;
  border-top: 1px solid var(--line);
}
.hours > div {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
}
.hours dt {
  font-weight: 600;
  color: var(--ink);
  font-size: 0.92rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.hours dd {
  margin: 0;
  font-family: var(--serif);
  font-size: 1.3rem;
  color: var(--ink-2);
}
.hours--closed dd {
  color: var(--danger);
  font-size: 1rem;
  font-style: italic;
}
.visit__note {
  margin: 22px 0 0;
  font-size: 0.92rem;
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.visit__note::before {
  content: "";
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--muted);
}
.visit__note.is-open {
  color: var(--ok);
}
.visit__note.is-open::before {
  background: var(--ok);
  box-shadow: 0 0 0 4px rgba(95, 138, 107, 0.18);
}
.visit__note.is-closed {
  color: var(--danger);
}
.visit__note.is-closed::before {
  background: var(--danger);
}

.book {
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 34px 32px;
  box-shadow: var(--sh-md);
}
.book__title {
  font-size: 1.9rem;
}
.book__sub {
  margin: 6px 0 24px;
  color: var(--muted);
  font-size: 0.92rem;
}
.field {
  margin-bottom: 16px;
}
.field label {
  display: block;
  margin-bottom: 7px;
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-2);
}
.field input,
.field select {
  width: 100%;
  font: inherit;
  font-size: 0.95rem;
  padding: 12px 14px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  background: var(--white);
  color: var(--ink);
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}
.field input::placeholder {
  color: #b6aa9c;
}
.field input:focus,
.field select:focus {
  outline: none;
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.18);
}
.field input[aria-invalid="true"],
.field select[aria-invalid="true"] {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(179, 80, 62, 0.16);
}
.book__fine {
  margin: 14px 0 0;
  font-size: 0.74rem;
  color: var(--muted);
  text-align: center;
}

/* ---------- footer ---------- */
.foot {
  background: var(--ink);
  color: rgba(247, 241, 232, 0.7);
}
.foot__inner {
  width: min(1180px, 92vw);
  margin: 0 auto;
  padding: 56px 0;
  display: flex;
  flex-wrap: wrap;
  gap: 28px 48px;
  align-items: center;
}
.foot__brand {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-right: auto;
}
.foot__brand p {
  margin: 0;
  font-family: var(--serif);
  font-size: 1.15rem;
  color: var(--cream);
  line-height: 1.3;
}
.foot__brand span {
  font-family: var(--sans);
  font-size: 0.78rem;
  color: rgba(247, 241, 232, 0.5);
}
.foot__links {
  display: flex;
  gap: 22px;
}
.foot__links a {
  font-size: 0.9rem;
  transition: color 0.18s ease;
}
.foot__links a:hover {
  color: var(--gold);
}
.foot__copy {
  width: 100%;
  margin: 0;
  padding-top: 24px;
  border-top: 1px solid rgba(247, 241, 232, 0.12);
  font-size: 0.8rem;
  color: rgba(247, 241, 232, 0.45);
}

/* ---------- toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 24px);
  z-index: 300;
  max-width: min(420px, 90vw);
  padding: 14px 20px;
  background: var(--ink);
  color: var(--cream);
  border-radius: 999px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--sh-lg);
  border: 1px solid rgba(176, 141, 87, 0.4);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease, transform 0.3s ease;
}
.toast.is-show {
  opacity: 1;
  transform: translate(-50%, 0);
}
.toast::before {
  content: "✦ ";
  color: var(--gold);
}

/* ---------- reveal ---------- */
.reveal {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 0.6s ease, transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}
.reveal.is-in {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
  .btn:hover,
  .svc:hover,
  .stylist:hover,
  .tile:hover {
    transform: none;
  }
}

/* ---------- responsive ---------- */
@media (max-width: 940px) {
  .why__inner {
    grid-template-columns: 1fr;
    gap: 44px;
  }
  .services {
    grid-template-columns: repeat(2, 1fr);
  }
  .stylists {
    grid-template-columns: repeat(2, 1fr);
  }
  .visit__inner {
    grid-template-columns: 1fr;
    gap: 44px;
  }
}

@media (max-width: 760px) {
  .nav__links {
    position: fixed;
    inset: var(--nav-h) 0 auto 0;
    flex-direction: column;
    gap: 0;
    background: rgba(250, 246, 239, 0.97);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border-bottom: 1px solid var(--line);
    box-shadow: var(--sh-md);
    padding: 10px 6vw 18px;
    transform: translateY(-12px);
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.22s ease, transform 0.22s ease;
  }
  .nav__links.is-open {
    transform: none;
    opacity: 1;
    pointer-events: auto;
  }
  .nav__link {
    padding: 14px 6px;
    border-bottom: 1px solid var(--line);
    font-size: 1rem;
  }
  .nav__link::after {
    display: none;
  }
  .nav__toggle {
    display: flex;
  }
  .nav__call {
    display: none;
  }
}

@media (max-width: 520px) {
  body {
    font-size: 15px;
  }
  .hero {
    padding: calc(var(--nav-h) + 54px) 0 70px;
  }
  .hero__stats {
    gap: 28px 40px;
    margin-top: 40px;
  }
  .hero__stats strong {
    font-size: 2.1rem;
  }
  .section,
  .why,
  .quote {
    padding-top: 70px;
    padding-bottom: 70px;
  }
  .why,
  .visit__inner {
    padding-top: 70px;
    padding-bottom: 70px;
  }
  .services,
  .stylists {
    grid-template-columns: 1fr;
  }
  .why__grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .gallery {
    grid-template-columns: repeat(3, 1fr);
  }
  .hero__cta .btn,
  .hero__cta {
    width: 100%;
  }
  .book {
    padding: 26px 22px;
  }
  .brand__name {
    font-size: 1.16rem;
  }
}

