(function () {
  "use strict";

  /* ---------- Toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2600);
  }
  document.querySelectorAll("[data-toast]").forEach(function (el) {
    el.addEventListener("click", function (e) {
      if (el.getAttribute("href") === "#") e.preventDefault();
      toast(el.getAttribute("data-toast"));
    });
  });

  /* ---------- Sticky header shadow ---------- */
  var header = document.getElementById("siteHeader");
  function onScroll() {
    if (window.scrollY > 12) header.classList.add("scrolled");
    else header.classList.remove("scrolled");
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  /* ---------- Listing data ---------- */
  var stays = [
    { cat: "beach", loc: "Tulum, Mexico", title: "Casa Marea — beachfront palapa", rate: "4.97", reviews: 184, guests: 6, beds: 3, baths: 2, price: 268, art: "linear-gradient(135deg,#ffd28a 0%,#f0a36b 38%,#2a9d9b 130%)" },
    { cat: "mountain", loc: "Lake Tahoe, USA", title: "Pinecrest A-frame with hot tub", rate: "4.92", reviews: 211, guests: 8, beds: 4, baths: 3, price: 342, art: "linear-gradient(150deg,#9fd6c9 0%,#5b9aa0 45%,#2e4f4b 130%)" },
    { cat: "city", loc: "Lisbon, Portugal", title: "Alfama tiled loft with terrace", rate: "4.89", reviews: 156, guests: 4, beds: 2, baths: 1, price: 174, art: "linear-gradient(135deg,#f7d9b0 0%,#e79b7c 50%,#9c5e6a 130%)" },
    { cat: "beach", loc: "Amalfi Coast, Italy", title: "Limone cliff villa, sea view", rate: "4.99", reviews: 98, guests: 5, beds: 3, baths: 2, price: 410, art: "linear-gradient(135deg,#bfe9ff 0%,#5ec0d8 45%,#1f7c7b 130%)" },
    { cat: "countryside", loc: "Provence, France", title: "Lavender farmhouse & pool", rate: "4.94", reviews: 142, guests: 7, beds: 4, baths: 3, price: 298, art: "linear-gradient(135deg,#e3d4f0 0%,#b39ad1 40%,#6f7f9c 130%)" },
    { cat: "mountain", loc: "Banff, Canada", title: "Glasswall cabin under the peaks", rate: "4.96", reviews: 173, guests: 6, beds: 3, baths: 2, price: 315, art: "linear-gradient(160deg,#cfe6e1 0%,#7aa6a2 45%,#2f4a4f 130%)" },
    { cat: "city", loc: "Mexico City, MX", title: "Roma Norte mid-century flat", rate: "4.91", reviews: 207, guests: 3, beds: 1, baths: 1, price: 132, art: "linear-gradient(135deg,#ffe1a8 0%,#f0926e 50%,#b85c5c 130%)" },
    { cat: "beach", loc: "Bali, Indonesia", title: "Uluwatu jungle bungalow", rate: "4.95", reviews: 264, guests: 4, beds: 2, baths: 2, price: 156, art: "linear-gradient(135deg,#d5f0c0 0%,#5cb39b 45%,#1f6a64 130%)" },
    { cat: "countryside", loc: "Tuscany, Italy", title: "Vineyard stone villa & olive grove", rate: "4.98", reviews: 121, guests: 9, beds: 5, baths: 4, price: 388, art: "linear-gradient(150deg,#f3e2a8 0%,#cda154 45%,#6a5a32 130%)" }
  ];

  var grid = document.getElementById("getawaysGrid");
  var emptyEl = document.getElementById("getawaysEmpty");

  function fmt(n) { return "$" + n.toLocaleString("en-US"); }

  function cardHTML(s) {
    return (
      '<article class="card" data-cat="' + s.cat + '">' +
        '<div class="card-photo" style="background:' + s.art + '">' +
          '<span class="badge">★ Guest favourite</span>' +
          '<button class="like" type="button" aria-label="Save ' + s.title + '" aria-pressed="false">♥</button>' +
        '</div>' +
        '<div class="card-body">' +
          '<div class="card-top">' +
            '<span class="card-loc">' + s.loc + '</span>' +
            '<span class="card-rate"><span class="star">★</span> ' + s.rate + ' <span style="color:var(--muted);font-weight:500">(' + s.reviews + ')</span></span>' +
          '</div>' +
          '<h3 class="card-title">' + s.title + '</h3>' +
          '<div class="card-meta">' +
            '<span class="sleeps">Sleeps ' + s.guests + '</span>' +
            '<span>' + s.beds + ' beds · ' + s.baths + ' baths</span>' +
          '</div>' +
          '<div class="card-foot">' +
            '<span class="card-price">' + fmt(s.price) + '</span>' +
            '<span class="card-per">/ night</span>' +
          '</div>' +
        '</div>' +
      '</article>'
    );
  }

  function render(filter) {
    var list = filter === "all" ? stays : stays.filter(function (s) { return s.cat === filter; });
    grid.innerHTML = list.map(cardHTML).join("");
    emptyEl.hidden = list.length !== 0;

    grid.querySelectorAll(".like").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var on = btn.classList.toggle("on");
        btn.setAttribute("aria-pressed", on ? "true" : "false");
        toast(on ? "Saved to your wishlist" : "Removed from wishlist");
      });
    });
  }

  render("all");

  /* ---------- Filter chips ---------- */
  var chips = document.querySelectorAll(".chip");
  chips.forEach(function (chip) {
    chip.addEventListener("click", function () {
      chips.forEach(function (c) {
        c.classList.remove("is-active");
        c.setAttribute("aria-selected", "false");
      });
      chip.classList.add("is-active");
      chip.setAttribute("aria-selected", "true");
      render(chip.getAttribute("data-filter"));
    });
  });

  /* ---------- Guests stepper ---------- */
  var guestsToggle = document.getElementById("guestsToggle");
  var guestsPop = document.getElementById("guestsPop");
  var guestsValue = document.getElementById("guestsValue");
  var counts = { adults: 2, children: 0, pets: 0 };
  var limits = { adults: [1, 16], children: [0, 10], pets: [0, 5] };

  function updateGuestsLabel() {
    var people = counts.adults + counts.children;
    var parts = [people + (people === 1 ? " guest" : " guests")];
    if (counts.pets) parts.push(counts.pets + (counts.pets === 1 ? " pet" : " pets"));
    guestsValue.textContent = parts.join(", ");
  }
  function syncSteppers() {
    document.querySelectorAll(".step-count").forEach(function (el) {
      el.textContent = counts[el.getAttribute("data-count")];
    });
    document.querySelectorAll(".step").forEach(function (btn) {
      var key = btn.getAttribute("data-step");
      var dir = parseInt(btn.getAttribute("data-dir"), 10);
      var v = counts[key];
      btn.disabled = dir < 0 ? v <= limits[key][0] : v >= limits[key][1];
    });
    updateGuestsLabel();
  }
  document.querySelectorAll(".step").forEach(function (btn) {
    btn.addEventListener("click", function () {
      var key = btn.getAttribute("data-step");
      var dir = parseInt(btn.getAttribute("data-dir"), 10);
      var next = counts[key] + dir;
      if (next < limits[key][0] || next > limits[key][1]) return;
      counts[key] = next;
      syncSteppers();
    });
  });
  function openGuests(open) {
    guestsPop.hidden = !open;
    guestsToggle.setAttribute("aria-expanded", open ? "true" : "false");
  }
  guestsToggle.addEventListener("click", function (e) {
    e.stopPropagation();
    openGuests(guestsPop.hidden);
  });
  document.addEventListener("click", function (e) {
    if (!guestsPop.hidden && !guestsPop.contains(e.target) && e.target !== guestsToggle) openGuests(false);
  });
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && !guestsPop.hidden) { openGuests(false); guestsToggle.focus(); }
  });
  syncSteppers();

  /* ---------- Search submit ---------- */
  var searchForm = document.getElementById("searchForm");
  searchForm.addEventListener("submit", function (e) {
    e.preventDefault();
    var where = document.getElementById("where").value.trim() || "Anywhere";
    var people = counts.adults + counts.children;
    toast("Searching " + where + " for " + people + (people === 1 ? " guest" : " guests") + "…");
    openGuests(false);
  });

  /* ---------- Destinations carousel ---------- */
  var destinations = [
    { name: "Tulum", meta: "1,240 stays", art: "linear-gradient(180deg,#ffd28a 0%,#2a9d9b 130%)" },
    { name: "Amalfi", meta: "612 stays", art: "linear-gradient(180deg,#bfe9ff 0%,#1f7c7b 130%)" },
    { name: "Lake Tahoe", meta: "884 stays", art: "linear-gradient(180deg,#9fd6c9 0%,#2e4f4b 130%)" },
    { name: "Lisbon", meta: "1,506 stays", art: "linear-gradient(180deg,#f7d9b0 0%,#9c5e6a 130%)" },
    { name: "Bali", meta: "2,031 stays", art: "linear-gradient(180deg,#d5f0c0 0%,#1f6a64 130%)" },
    { name: "Provence", meta: "498 stays", art: "linear-gradient(180deg,#e3d4f0 0%,#6f7f9c 130%)" },
    { name: "Banff", meta: "327 stays", art: "linear-gradient(180deg,#cfe6e1 0%,#2f4a4f 130%)" },
    { name: "Tuscany", meta: "742 stays", art: "linear-gradient(180deg,#f3e2a8 0%,#6a5a32 130%)" }
  ];
  var carousel = document.getElementById("carousel");
  carousel.innerHTML = destinations.map(function (d) {
    return (
      '<button class="slide" type="button" style="background:' + d.art + '" aria-label="Explore ' + d.name + '">' +
        '<span class="slide-text"><h3>' + d.name + '</h3><span>' + d.meta + '</span></span>' +
      '</button>'
    );
  }).join("");
  carousel.querySelectorAll(".slide").forEach(function (slide, i) {
    slide.addEventListener("click", function () { toast("Exploring " + destinations[i].name + " — demo only"); });
  });

  var prevBtn = document.getElementById("carPrev");
  var nextBtn = document.getElementById("carNext");
  function scrollAmount() {
    var first = carousel.querySelector(".slide");
    var step = first ? first.getBoundingClientRect().width + 18 : 300;
    return step * Math.max(1, Math.floor(carousel.clientWidth / step));
  }
  function updateCarBtns() {
    prevBtn.disabled = carousel.scrollLeft <= 4;
    nextBtn.disabled = carousel.scrollLeft + carousel.clientWidth >= carousel.scrollWidth - 4;
  }
  prevBtn.addEventListener("click", function () { carousel.scrollBy({ left: -scrollAmount(), behavior: "smooth" }); });
  nextBtn.addEventListener("click", function () { carousel.scrollBy({ left: scrollAmount(), behavior: "smooth" }); });
  carousel.addEventListener("scroll", updateCarBtns, { passive: true });
  window.addEventListener("resize", updateCarBtns);
  updateCarBtns();

  /* ---------- Host earnings slider ---------- */
  var nights = document.getElementById("nights");
  var nightsOut = document.getElementById("nightsOut");
  var estValue = document.getElementById("estValue");
  var NIGHTLY = 142; // assumed avg nightly net for the demo estimate
  function updateEst() {
    var n = parseInt(nights.value, 10);
    nightsOut.textContent = n;
    estValue.textContent = "$" + (n * NIGHTLY).toLocaleString("en-US");
  }
  nights.addEventListener("input", updateEst);
  updateEst();

  /* ---------- Host email form ---------- */
  var hostForm = document.getElementById("hostForm");
  hostForm.addEventListener("submit", function (e) {
    e.preventDefault();
    var email = document.getElementById("hostEmail");
    if (!email.checkValidity()) { email.reportValidity(); return; }
    toast("Estimate sent to " + email.value + " — happy hosting!");
    email.value = "";
  });
})();

snippets.css:
/* ============================================================
   Verdé Day Spa — Landing
   Palette override: sage + sand + bronze (serene, wellness)
   ============================================================ */
:root {
  --sage: #9bb39b;
  --sage-d: #6f8a6f;
  --sand: #e7ddca;
  --bronze: #a9824f;
  --bronze-d: #8a6839;

  --ink: #2f352c;
  --ink-2: #50584a;
  --muted: #847d6e;

  --bg: #f6f2e9;
  --cream: #efe9da;
  --white: #ffffff;

  --line: rgba(47, 53, 44, 0.1);
  --line-2: rgba(47, 53, 44, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --shadow-sm: 0 1px 2px rgba(47, 53, 44, 0.05), 0 2px 8px rgba(47, 53, 44, 0.04);
  --shadow-md: 0 6px 24px rgba(47, 53, 44, 0.08), 0 2px 6px rgba(47, 53, 44, 0.05);
  --shadow-lg: 0 24px 60px rgba(47, 53, 44, 0.12);

  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --wrap: 1140px;
  --pad: clamp(20px, 5vw, 64px);
}

*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3 { font-family: var(--serif); font-weight: 600; line-height: 1.08; margin: 0; }

a { color: inherit; text-decoration: none; }

img, figure { display: block; }

.skip {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--ink);
  color: var(--bg);
  padding: 10px 16px;
  border-radius: var(--r-sm);
  z-index: 200;
}
.skip:focus { left: 16px; top: 16px; }

:focus-visible { outline: 2px solid var(--bronze); outline-offset: 3px; border-radius: 4px; }

.eyebrow {
  font-family: var(--sans);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--bronze);
  margin: 0 0 14px;
}
.eyebrow--light { color: var(--sand); }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--sans);
  font-size: 0.92rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  padding: 11px 22px;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.18s ease, background 0.2s ease, color 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }
.btn--solid { background: var(--ink); color: var(--bg); }
.btn--solid:hover { background: var(--bronze); box-shadow: var(--shadow-md); }
.btn--ghost { background: transparent; color: var(--ink); border-color: var(--line-2); }
.btn--ghost:hover { border-color: var(--bronze); color: var(--bronze); }
.btn--lg { padding: 14px 30px; font-size: 1rem; }
.btn--block { width: 100%; }

/* ===== NAV ===== */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(246, 242, 233, 0.78);
  backdrop-filter: saturate(140%) blur(14px);
  -webkit-backdrop-filter: saturate(140%) blur(14px);
  border-bottom: 1px solid transparent;
  transition: border-color 0.25s ease, box-shadow 0.25s ease, background 0.25s ease;
}
.nav.is-scrolled {
  border-bottom-color: var(--line);
  box-shadow: 0 6px 24px rgba(47, 53, 44, 0.05);
}
.nav__inner {
  max-width: var(--wrap);
  margin: 0 auto;
  padding: 14px var(--pad);
  display: flex;
  align-items: center;
  gap: 28px;
}
.brand { display: inline-flex; align-items: center; gap: 12px; }
.brand__mark {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(145deg, var(--sage), var(--sage-d));
  color: var(--white);
  font-family: var(--serif);
  font-size: 1.3rem;
  font-weight: 700;
  box-shadow: inset 0 0 0 3px rgba(255, 255, 255, 0.18);
}
.brand__name {
  font-family: var(--serif);
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  line-height: 1;
  display: flex;
  flex-direction: column;
}
.brand__sub {
  font-family: var(--sans);
  font-size: 0.56rem;
  font-weight: 600;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--muted);
  margin-top: 3px;
}
.nav__links { display: flex; gap: 26px; margin-left: auto; }
.nav__links a {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--ink-2);
  position: relative;
  padding: 4px 0;
  transition: color 0.2s ease;
}
.nav__links a::after {
  content: "";
  position: absolute;
  left: 0; bottom: -2px;
  width: 0; height: 1.5px;
  background: var(--bronze);
  transition: width 0.25s ease;
}
.nav__links a:hover, .nav__links a.is-active { color: var(--ink); }
.nav__links a:hover::after, .nav__links a.is-active::after { width: 100%; }
.nav__cta { display: flex; gap: 10px; }
.nav__toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  width: 42px;
  height: 42px;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  cursor: pointer;
}
.nav__toggle span {
  display: block;
  width: 18px;
  height: 1.5px;
  background: var(--ink);
  transition: transform 0.25s ease, opacity 0.2s ease;
}
.nav__toggle[aria-expanded="true"] span:nth-child(1) { transform: translateY(6.5px) rotate(45deg); }
.nav__toggle[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
.nav__toggle[aria-expanded="true"] span:nth-child(3) { transform: translateY(-6.5px) rotate(-45deg); }
.nav__mobile {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px var(--pad) 22px;
  border-top: 1px solid var(--line);
}
.nav__mobile a { padding: 12px 4px; font-weight: 500; color: var(--ink-2); border-bottom: 1px solid var(--line); }
.nav__mobile a.btn { margin-top: 12px; border-bottom: none; color: var(--bg); justify-content: center; }

/* ===== SECTION SHELL ===== */
.section { padding: clamp(64px, 9vw, 120px) var(--pad); }
.section__head { max-width: 640px; margin: 0 auto clamp(36px, 5vw, 60px); text-align: center; }
.section__head--light { color: var(--cream); }
.section__title { font-size: clamp(2rem, 4.4vw, 3.1rem); letter-spacing: -0.01em; }
.section__title em { font-style: italic; color: var(--bronze); }
.section__lede { color: var(--muted); font-size: 1.05rem; margin: 16px 0 0; line-height: 1.65; }
.section__head--light .section__lede { color: rgba(255, 255, 255, 0.7); }

/* ===== HERO ===== */
.hero {
  position: relative;
  overflow: hidden;
  padding: clamp(80px, 12vw, 150px) var(--pad) clamp(70px, 9vw, 120px);
}
.hero__glow {
  position: absolute;
  inset: -20% -10% auto -10%;
  height: 720px;
  background:
    radial-gradient(620px 420px at 22% 18%, rgba(155, 179, 155, 0.42), transparent 70%),
    radial-gradient(520px 380px at 82% 8%, rgba(231, 221, 202, 0.6), transparent 72%),
    radial-gradient(480px 360px at 60% 70%, rgba(169, 130, 79, 0.12), transparent 70%);
  filter: blur(6px);
  z-index: 0;
}
.hero__inner { position: relative; z-index: 1; max-width: var(--wrap); margin: 0 auto; }
.hero__title {
  font-size: clamp(3.2rem, 10vw, 6.6rem);
  font-weight: 500;
  letter-spacing: -0.02em;
  margin: 0 0 22px;
}
.hero__title em { font-style: italic; color: var(--bronze); }
.hero__lede {
  max-width: 480px;
  font-size: 1.15rem;
  color: var(--ink-2);
  line-height: 1.7;
  margin: 0 0 32px;
}
.hero__cta { display: flex; flex-wrap: wrap; gap: 14px; }
.hero__stats {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: clamp(28px, 5vw, 60px);
  margin: clamp(48px, 7vw, 76px) 0 0;
  padding: 30px 0 0;
  border-top: 1px solid var(--line);
}
.hero__stats li { display: flex; flex-direction: column; gap: 4px; }
.stat { font-family: var(--serif); font-size: clamp(2rem, 4vw, 2.7rem); font-weight: 600; color: var(--ink); line-height: 1; }
.stat__label {
  font-size: 0.74rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ===== SERVICES ===== */
.svc-grid {
  max-width: var(--wrap);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}
.svc {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 32px 30px;
  position: relative;
  overflow: hidden;
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}
.svc::before {
  content: "";
  position: absolute;
  left: 0; top: 0;
  width: 100%; height: 3px;
  background: linear-gradient(90deg, var(--sage), var(--bronze));
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
}
.svc:hover, .svc:focus-visible {
  transform: translateY(-5px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}
.svc:hover::before, .svc:focus-visible::before { transform: scaleX(1); }
.svc__icon {
  display: inline-grid;
  place-items: center;
  width: 50px; height: 50px;
  border-radius: 50%;
  background: var(--cream);
  color: var(--sage-d);
  font-size: 1.4rem;
  margin-bottom: 20px;
}
.svc__name { font-size: 1.55rem; margin-bottom: 10px; }
.svc__copy { color: var(--muted); font-size: 0.96rem; line-height: 1.6; margin: 0 0 22px; }
.svc__meta {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding-top: 16px;
  border-top: 1px solid var(--line);
  font-size: 0.84rem;
  color: var(--muted);
  letter-spacing: 0.02em;
}
.svc__price { font-family: var(--serif); font-size: 1.25rem; font-weight: 600; color: var(--ink); }

/* ===== FLOW BAND ===== */
.flow {
  background:
    radial-gradient(900px 500px at 80% -10%, rgba(169, 130, 79, 0.18), transparent 70%),
    linear-gradient(160deg, #3a4338, #2c332a);
  color: var(--cream);
}
.flow__inner { max-width: var(--wrap); margin: 0 auto; }
.flow__steps {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
.flow__step {
  position: relative;
  padding: 6px 6px 6px 0;
}
.flow__step + .flow__step { padding-left: 28px; border-left: 1px solid rgba(255, 255, 255, 0.12); }
.flow__num {
  font-family: var(--serif);
  font-size: 2.6rem;
  font-weight: 500;
  color: var(--sage);
  display: block;
  margin-bottom: 12px;
}
.flow__name { font-size: 1.7rem; color: var(--white); margin-bottom: 10px; }
.flow__step p { color: rgba(255, 255, 255, 0.72); line-height: 1.7; margin: 0; font-size: 0.98rem; }

/* ===== GALLERY ===== */
.gallery { background: var(--cream); }
.gal-grid {
  max-width: var(--wrap);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  grid-auto-rows: 150px;
  gap: 16px;
}
.gal {
  position: relative;
  border-radius: var(--r-md);
  overflow: hidden;
  margin: 0;
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.gal:hover { transform: scale(1.012); box-shadow: var(--shadow-md); }
.gal figcaption {
  position: absolute;
  left: 16px; bottom: 14px;
  z-index: 2;
  color: var(--white);
  font-family: var(--serif);
  font-size: 1.2rem;
  font-weight: 600;
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.4);
}
.gal::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(34, 40, 31, 0.5));
  z-index: 1;
}
.gal--a { grid-column: span 3; grid-row: span 2; background: linear-gradient(150deg, #8ba98b, #5f7a5f); }
.gal--b { grid-column: span 3; background: linear-gradient(150deg, #c9b48a, #a9824f); }
.gal--c { grid-column: span 2; background: linear-gradient(150deg, #aebfa6, #738a72); }
.gal--d { grid-column: span 1; background: linear-gradient(150deg, #e0d4b8, #b8a173); }
.gal--e { grid-column: span 3; background: linear-gradient(150deg, #9fb9b3, #5e8079); }

/* ===== GIFT ===== */
.gift__card {
  max-width: var(--wrap);
  margin: 0 auto;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 1fr;
}
.gift__copy {
  padding: clamp(36px, 5vw, 56px);
  background:
    radial-gradient(420px 320px at 0% 100%, rgba(155, 179, 155, 0.22), transparent 70%),
    var(--cream);
}
.gift__copy .section__title { text-align: left; }
.gift__copy .section__lede { margin-top: 12px; }
.gift__perks {
  list-style: none;
  margin: 26px 0 0;
  padding: 0;
  display: grid;
  gap: 12px;
}
.gift__perks li {
  position: relative;
  padding-left: 26px;
  color: var(--ink-2);
  font-size: 0.95rem;
}
.gift__perks li::before {
  content: "✓";
  position: absolute;
  left: 0; top: 0;
  color: var(--sage-d);
  font-weight: 700;
}
.gift__form { padding: clamp(32px, 4vw, 48px); display: grid; gap: 18px; }
.gift__amounts { border: none; margin: 0; padding: 0; }
.amount-row { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 10px; }
.chip {
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink);
  font-family: var(--sans);
  font-weight: 600;
  font-size: 0.95rem;
  padding: 10px 18px;
  border-radius: 999px;
  cursor: pointer;
  transition: all 0.18s ease;
}
.chip:hover { border-color: var(--bronze); }
.chip.is-active { background: var(--ink); color: var(--bg); border-color: var(--ink); }
.chip--custom { display: inline-flex; align-items: center; gap: 4px; padding: 6px 14px; }
.chip--custom span { color: var(--muted); }
.chip--custom input {
  width: 64px;
  border: none;
  background: transparent;
  font: inherit;
  color: var(--ink);
  outline: none;
}
.chip--custom:focus-within { border-color: var(--bronze); }

.field { display: grid; gap: 7px; }
.field__label {
  font-size: 0.76rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-2);
}
.field__opt { color: var(--muted); font-weight: 500; text-transform: none; letter-spacing: 0; }
.field input, .field textarea {
  font-family: var(--sans);
  font-size: 0.98rem;
  color: var(--ink);
  background: var(--bg);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 12px 14px;
  width: 100%;
  resize: vertical;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}
.field input:focus, .field textarea:focus {
  outline: none;
  border-color: var(--bronze);
  background: var(--white);
  box-shadow: 0 0 0 3px rgba(169, 130, 79, 0.12);
}
.field input.is-invalid, .field textarea.is-invalid { border-color: var(--danger); }
.field__hint { font-size: 0.76rem; color: var(--muted); justify-self: end; }
.gift__total {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 14px 0 4px;
  border-top: 1px solid var(--line);
  font-size: 0.82rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}
.gift__total strong { font-family: var(--serif); font-size: 1.7rem; font-weight: 600; color: var(--ink); }

/* ===== HOURS ===== */
.hours { background: var(--cream); }
.hours__inner {
  max-width: var(--wrap);
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 0.9fr;
  gap: clamp(32px, 6vw, 80px);
  align-items: center;
}
.hours__intro .section__title { text-align: left; }
.hours__intro .section__lede { margin-top: 12px; }
.hours__status {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin: 22px 0 24px;
  font-weight: 600;
  font-size: 0.92rem;
}
.hours__status .dot {
  width: 9px; height: 9px;
  border-radius: 50%;
  background: var(--muted);
  box-shadow: 0 0 0 4px rgba(132, 125, 110, 0.15);
}
.hours__status.is-open .dot { background: var(--ok); box-shadow: 0 0 0 4px rgba(95, 138, 107, 0.2); }
.hours__status.is-closed .dot { background: var(--danger); box-shadow: 0 0 0 4px rgba(179, 80, 62, 0.18); }
.hours__list { list-style: none; margin: 0; padding: 0; background: var(--white); border: 1px solid var(--line); border-radius: var(--r-md); overflow: hidden; }
.hours__list li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px 22px;
  border-bottom: 1px solid var(--line);
  font-size: 0.96rem;
}
.hours__list li:last-child { border-bottom: none; }
.hours__list li.is-today { background: var(--bg); font-weight: 600; }
.hours__list .day { color: var(--ink); }
.hours__list .time { color: var(--muted); font-variant-numeric: tabular-nums; }
.hours__list li.is-today .time { color: var(--bronze); }
.hours__badge {
  margin-left: 10px;
  font-size: 0.64rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--bronze);
  border: 1px solid var(--line-2);
  border-radius: 999px;
  padding: 2px 8px;
}

/* ===== FOOTER ===== */
.footer { background: var(--ink); color: rgba(255, 255, 255, 0.78); padding: 56px var(--pad) 40px; }
.footer__inner {
  max-width: var(--wrap);
  margin: 0 auto;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 24px 40px;
}
.footer__brand { display: flex; align-items: center; gap: 14px; }
.footer__name { font-family: var(--serif); font-size: 1.4rem; color: var(--white); margin: 0; }
.footer__tag { font-size: 0.82rem; color: rgba(255, 255, 255, 0.55); margin: 2px 0 0; }
.footer__links { display: flex; gap: 24px; margin-left: auto; }
.footer__links a { font-size: 0.9rem; color: rgba(255, 255, 255, 0.7); transition: color 0.2s ease; }
.footer__links a:hover { color: var(--white); }
.footer__legal { width: 100%; font-size: 0.8rem; color: rgba(255, 255, 255, 0.45); margin: 8px 0 0; padding-top: 22px; border-top: 1px solid rgba(255, 255, 255, 0.1); }

/* ===== TOAST ===== */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink);
  color: var(--bg);
  padding: 14px 22px;
  border-radius: var(--r-md);
  box-shadow: var(--shadow-lg);
  font-size: 0.92rem;
  font-weight: 500;
  z-index: 300;
  max-width: calc(100vw - 40px);
  opacity: 0;
  transition: opacity 0.3s ease, transform 0.3s ease;
}
.toast.is-visible { opacity: 1; transform: translateX(-50%) translateY(0); }
.toast::before { content: "✦ "; color: var(--sage); }

/* ===== REVEAL ===== */
.reveal { opacity: 0; transform: translateY(22px); transition: opacity 0.7s ease, transform 0.7s ease; }
.reveal.is-in { opacity: 1; transform: none; }

/* ===== RESPONSIVE ===== */
@media (max-width: 900px) {
  .svc-grid { grid-template-columns: repeat(2, 1fr); }
  .flow__steps { grid-template-columns: 1fr; gap: 0; }
  .flow__step + .flow__step { padding-left: 0; border-left: none; border-top: 1px solid rgba(255, 255, 255, 0.12); padding-top: 28px; margin-top: 28px; }
  .gift__card { grid-template-columns: 1fr; }
  .hours__inner { grid-template-columns: 1fr; }
  .hours__intro .section__title, .gift__copy .section__title { text-align: left; }
}

@media (max-width: 760px) {
  .nav__links, .nav__cta { display: none; }
  .nav__toggle { display: flex; }
}

@media (max-width: 520px) {
  body { font-size: 15px; }
  .svc-grid { grid-template-columns: 1fr; }
  .gal-grid { grid-template-columns: repeat(2, 1fr); grid-auto-rows: 130px; }
  .gal--a { grid-column: span 2; grid-row: span 1; }
  .gal--b, .gal--c, .gal--e { grid-column: span 2; }
  .gal--d { grid-column: span 2; }
  .hero__stats { gap: 24px 36px; }
  .hero__cta .btn { flex: 1; }
  .amount-row { gap: 8px; }
  .chip { padding: 9px 15px; font-size: 0.9rem; }
  .footer__links { margin-left: 0; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .reveal { opacity: 1; transform: none; transition: none; }
  * { animation-duration: 0.001ms !important; transition-duration: 0.05ms !important; }
}

