}

.msg {
  display: flex;
  flex-direction: column;
  max-width: 78%;
}
.msg.in {
  align-self: flex-start;
  align-items: flex-start;
}
.msg.out {
  align-self: flex-end;
  align-items: flex-end;
}
.bubble {
  padding: 10px 14px;
  font-size: 0.9rem;
  line-height: 1.45;
  border-radius: var(--r-md);
  box-shadow: var(--shadow-1);
  word-wrap: break-word;
}
.msg.in .bubble {
