  padding: 0 4px;
}
.tick {
  color: var(--teal);
  font-size: 0.68rem;
  letter-spacing: -1px;
}

/* ── Typing indicator ── */
.typing {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  align-self: flex-start;
}
.typing[hidden] {
  display: none;
}
.typing-bubble {
  display: flex;
  align-items: center;
  gap: 4px;
  background: var(--white);
  border-bottom-left-radius: 4px;
  padding: 12px 14px;
}
.typing-bubble .dot {
