}
@keyframes blink {
  0%,
  60%,
  100% {
    opacity: 0.3;
    transform: translateY(0);
  }
  30% {
    opacity: 1;
    transform: translateY(-3px);
  }
}

/* ── Quick replies ── */
.quick-replies {
  display: flex;
  gap: 8px;
  padding: 10px 16px;
  overflow-x: auto;
  border-top: 1px solid var(--line);
  background: var(--white);
}
.chip {
  border: 1px solid var(--teal);
  background: var(--teal-50);
  color: var(--teal-d);
  border-radius: 999px;
  padding: 7px 13px;
  font: inherit;
  font-weight: 600;
  font-size: 0.8rem;
  white-space: nowrap;
  cursor: pointer;
  transition: background 0.15s, transform 0.12s;
}
.chip:hover {
  background: #d6ece9;
}
.chip:active {
  transform: translateY(1px);
}

/* ── Composer ── */
.composer {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  padding: 12px 16px;
  border-top: 1px solid var(--line);
  background: var(--white);
}
.input {
  flex: 1;
  resize: none;
  border: 1px solid var(--line-2);
  border-radius: var(--r-md);
  padding: 10px 14px;
  font: inherit;
  font-size: 0.9rem;
  color: var(--ink);
  background: var(--bg);
  max-height: 120px;
  line-height: 1.45;
  transition: border-color 0.15s, background 0.15s;
}
.input:focus {
  outline: none;
  border-color: var(--teal);
  background: var(--white);
}
.input::placeholder {
