}
.send-btn {
  border: none;
  background: linear-gradient(135deg, var(--teal), var(--teal-d));
  color: #fff;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  font-size: 1.05rem;
  cursor: pointer;
