  --ink-2: #3d362f;
  --muted: #8a7d70;
  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;
  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);
  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;
  --shadow-sm: 0 1px 2px rgba(28, 24, 20, 0.05),
    0 4px 14px rgba(28, 24, 20, 0.05);
  --shadow-md: 0 10px 30px rgba(28, 24, 20, 0.08),
    0 2px 8px rgba(28, 24, 20, 0.05);
  --shadow-lg: 0 24px 60px rgba(28, 24, 20, 0.12);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--sans);
  line-height: 1.5;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1,
h2,
h3 {
  font-family: var(--serif);
  font-weight: 600;
  margin: 0;
  letter-spacing: 0.01em;
  line-height: 1.1;
}

button {
  font-family: inherit;
  cursor: pointer;
}

:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  border-radius: var(--r-sm);
}

.kicker,
.eyebrow {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  font-weight: 600;
  color: var(--gold-d);
  margin: 0;
}

.muted {
