}

/* ---------- Layout shell ---------- */
.booking {
  max-width: 1120px;
  margin: 0 auto;
  padding: clamp(1.5rem, 4vw, 3.5rem) clamp(1rem, 4vw, 2.5rem) 4rem;
}

.hero {
  display: grid;
  gap: 1rem;
  padding-bottom: 1.75rem;
  border-bottom: 1px solid var(--line);
}

.hero__brand {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.hero__monogram {
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  flex: none;
  border-radius: 50%;
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--white);
  letter-spacing: 0.04em;
  background: radial-gradient(circle at 30% 25%, var(--rose), var(--gold-d));
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.25), var(--shadow-sm);
}

.hero h1 {
  font-size: clamp(2rem, 5vw, 3rem);
  margin-top: 0.15rem;
}

.hero__lede {
  max-width: 46ch;
  color: var(--ink-2);
  font-size: 1rem;
  margin: 0;
}

/* ---------- Stepper ---------- */
