/* ---------- Two-column layout ---------- */
.layout {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 1.75rem;
  align-items: start;
}

.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-md);
  padding: clamp(1.25rem, 3vw, 2rem);
  display: flex;
  flex-direction: column;
}

.screen {
  display: none;
  animation: fade 0.35s ease;
}

.screen.is-active {
  display: block;
}

@keyframes fade {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.screen__head {
  margin-bottom: 1.5rem;
}

.screen__head h2 {
  font-size: 1.85rem;
  margin: 0.35rem 0 0.4rem;
}

.screen__hint {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
  max-width: 52ch;
}

/* ---------- Category chips ---------- */
.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1.4rem;
}

.chip {
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink-2);
  font-size: 0.82rem;
  font-weight: 500;
  padding: 0.45rem 0.95rem;
  border-radius: 999px;
  transition: all 0.2s ease;
}

.chip:hover {
  border-color: var(--gold);
  color: var(--gold-d);
}

.chip.is-active {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--gold-soft);
}

/* ---------- Service list ---------- */
.service-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.75rem;
}

.service {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1rem;
  width: 100%;
  text-align: left;
  background: var(--cream);
  border: 1px solid transparent;
  border-radius: var(--r-md);
  padding: 1rem 1.1rem;
  transition: all 0.2s ease;
}

.service:hover {
  border-color: var(--gold-soft);
  background: var(--white);
  box-shadow: var(--shadow-sm);
  transform: translateY(-1px);
}

.service.is-selected {
  border-color: var(--gold);
  background: var(--white);
  box-shadow: 0 0 0 1px var(--gold), var(--shadow-sm);
}

.service__cat {
  font-size: 0.62rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-weight: 600;
  color: var(--gold-d);
  background: var(--gold-soft);
  padding: 0.3rem 0.55rem;
  border-radius: var(--r-sm);
  align-self: start;
}

.service__body h3 {
  font-size: 1.3rem;
  font-weight: 600;
}

.service__desc {
  margin: 0.15rem 0 0;
  font-size: 0.84rem;
  color: var(--muted);
}

.service__meta {
  text-align: right;
  display: grid;
  gap: 0.15rem;
}

.service__price {
  font-family: var(--serif);
  font-size: 1.4rem;
  font-weight: 600;
  color: var(--ink);
}

.service__dur {
  font-size: 0.78rem;
  color: var(--muted);
}

/* ---------- Stylist grid ---------- */
.stylist-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  gap: 0.85rem;
}

.stylist {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0.5rem;
  background: var(--cream);
  border: 1px solid transparent;
  border-radius: var(--r-md);
  padding: 1.4rem 1rem 1.25rem;
  transition: all 0.2s ease;
}

.stylist:hover {
  border-color: var(--gold-soft);
  background: var(--white);
  box-shadow: var(--shadow-sm);
  transform: translateY(-2px);
}

.stylist.is-selected {
  border-color: var(--gold);
  background: var(--white);
  box-shadow: 0 0 0 1px var(--gold), var(--shadow-sm);
}

.stylist__avatar {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.35rem;
  color: var(--white);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.3);
}

.stylist__name {
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 600;
}

.stylist__spec {
  font-size: 0.76rem;
  color: var(--muted);
  letter-spacing: 0.02em;
}

.stylist__rating {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--ink-2);
}

.stylist__rating .star {
  color: var(--gold);
}

.stylist--any .stylist__avatar {
  background: linear-gradient(135deg, var(--gold-soft), var(--rose-soft));
  color: var(--gold-d);
  font-size: 1.6rem;
}

/* ---------- Day strip ---------- */
.daystrip {
  display: flex;
  gap: 0.55rem;
  overflow-x: auto;
  padding-bottom: 0.5rem;
  margin-bottom: 1.5rem;
  scrollbar-width: thin;
}

.day {
  flex: none;
  width: 72px;
  border: 1px solid var(--line-2);
  background: var(--white);
  border-radius: var(--r-md);
  padding: 0.7rem 0.5rem;
  text-align: center;
  transition: all 0.2s ease;
}

.day:hover:not(:disabled) {
  border-color: var(--gold);
}

.day.is-selected {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--gold-soft);
}

.day:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.day__dow {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 600;
}

.day__num {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 600;
  line-height: 1.1;
}

.day__mon {
  font-size: 0.66rem;
  color: inherit;
  opacity: 0.7;
}

/* ---------- Slots ---------- */
.slots-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-weight: 600;
  color: var(--muted);
  margin: 0 0 0.85rem;
}

.slots {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(92px, 1fr));
  gap: 0.55rem;
}

.slot {
  border: 1px solid var(--line-2);
  background: var(--white);
  border-radius: var(--r-sm);
  padding: 0.6rem 0.5rem;
  font-size: 0.88rem;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  color: var(--ink-2);
  transition: all 0.18s ease;
}

.slot:hover:not(:disabled) {
  border-color: var(--gold);
  color: var(--gold-d);
}

.slot.is-selected {
  background: var(--gold);
  border-color: var(--gold);
  color: var(--white);
}

.slot:disabled {
  opacity: 0.35;
  text-decoration: line-through;
  cursor: not-allowed;
}

.slots__empty {
  grid-column: 1 / -1;
  color: var(--muted);
  font-size: 0.9rem;
  padding: 1rem 0;
}

/* ---------- Panel actions ---------- */
.panel__actions {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  margin-top: 1.75rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--line);
}

.panel__actions .btn--primary {
  margin-left: auto;
}

/* ---------- Buttons ---------- */
.btn {
  font-family: var(--sans);
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 0.72rem 1.5rem;
  transition: all 0.2s ease;
}

.btn--primary {
  background: var(--ink);
  color: var(--gold-soft);
}

.btn--primary:hover:not(:disabled) {
  background: var(--ink-2);
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.btn--ghost {
  background: transparent;
  border-color: var(--line-2);
  color: var(--ink-2);
}

.btn--ghost:hover {
  border-color: var(--gold);
  color: var(--gold-d);
}

.btn--block {
  width: 100%;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

/* ---------- Summary rail ---------- */
.summary {
  position: sticky;
  top: 1.5rem;
}

.summary__inner {
  background: linear-gradient(170deg, var(--ink) 0%, #2a241e 100%);
  color: var(--cream);
  border-radius: var(--r-lg);
  padding: 1.6rem 1.5rem;
  box-shadow: var(--shadow-lg);
}

.summary .eyebrow {
  color: var(--gold);
}

.summary__list {
  list-style: none;
  margin: 1.1rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.85rem;
}

.summary__row {
  display: grid;
  gap: 0.15rem;
  padding-bottom: 0.85rem;
  border-bottom: 1px solid rgba(239, 226, 207, 0.14);
}

.summary__key {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--rose);
}

.summary__val {
  font-size: 0.98rem;
  font-weight: 500;
}

.summary__val.muted {
  color: rgba(247, 241, 232, 0.45);
  font-weight: 400;
  font-style: italic;
}

.summary__val small {
  display: block;
  font-size: 0.76rem;
  color: var(--rose);
  font-weight: 400;
  margin-top: 0.1rem;
}

.summary__totals {
  margin: 1.1rem 0 1.25rem;
  display: grid;
  gap: 0.5rem;
}

.summary__line {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 0.9rem;
  color: rgba(247, 241, 232, 0.78);
}

.summary__line span:last-child {
  font-variant-numeric: tabular-nums;
}

.summary__line--price {
  font-family: var(--serif);
  font-size: 1.05rem;
  color: var(--cream);
}

.summary__line--price span:last-child {
  font-size: 1.7rem;
  font-weight: 600;
  color: var(--gold-soft);
}

.summary__note {
  margin: 0.9rem 0 0;
  font-size: 0.72rem;
  color: rgba(247, 241, 232, 0.5);
  text-align: center;
  line-height: 1.4;
}

/* ---------- Confirmation ---------- */
.confirm {
  text-align: center;
  padding: 1.5rem 0;
}

.confirm__mark {
  width: 72px;
  height: 72px;
  margin: 0 auto 1.2rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--white);
  background: radial-gradient(circle at 30% 25%, var(--rose), var(--gold-d));
  box-shadow: var(--shadow-md);
  animation: pop 0.45s cubic-bezier(0.2, 0.9, 0.3, 1.4);
}

@keyframes pop {
  from {
    transform: scale(0.6);
    opacity: 0;
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}

.confirm h2 {
  font-size: 2.2rem;
  margin: 0.3rem 0 0.6rem;
}

.confirm__copy {
  max-width: 42ch;
  margin: 0 auto 1.5rem;
  color: var(--ink-2);
}

.confirm__ref {
  display: inline-grid;
  grid-auto-flow: column;
  gap: 2.5rem;
  margin: 0 auto 1.75rem;
  padding: 1.1rem 1.75rem;
  background: var(--cream);
  border: 1px solid var(--gold-soft);
  border-radius: var(--r-md);
  text-align: left;
}

.confirm__ref dt {
  font-size: 0.64rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--gold-d);
  font-weight: 600;
}

.confirm__ref dd {
  margin: 0.25rem 0 0;
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--ink);
  letter-spacing: 0.03em;
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 1.5rem;
  transform: translate(-50%, 1.5rem);
  background: var(--ink);
  color: var(--gold-soft);
  padding: 0.85rem 1.4rem;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease, transform 0.3s ease;
  z-index: 50;
  max-width: calc(100vw - 2rem);
}

.toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Responsive ---------- */
@media (max-width: 880px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .summary {
    position: static;
    order: -1;
  }
}

@media (max-width: 520px) {
  .booking {
    padding: 1.25rem 1rem 3rem;
  }
  .hero h1 {
    font-size: 2rem;
  }
  .step__label {
    display: none;
  }
  .step:not(:last-child)::after {
    margin-left: 0;
  }
  .service {
    grid-template-columns: 1fr auto;
    gap: 0.5rem 0.75rem;
  }
  .service__cat {
    grid-column: 1 / -1;
    justify-self: start;
  }
  .service__body {
    grid-column: 1;
  }
  .service__meta {
    grid-column: 2;
    align-self: center;
  }
  .screen__head h2 {
    font-size: 1.55rem;
  }
  .confirm__ref {
    grid-auto-flow: row;
    gap: 1rem;
    text-align: center;
  }
  .panel__actions {
    flex-direction: column-reverse;
  }
  .panel__actions .btn {
    width: 100%;
  }
}

