(() => {
  "use strict";

  /* ---------------- Data ---------------- */
  const SERVICES = [
    { id: "svc-cut", cat: "Hair", name: "Signature Cut & Style", desc: "Consultation, precision cut, blow-dry finish.", dur: 60, price: 85 },
