    { id: "svc-gel", cat: "Nails", name: "Gel Extensions", desc: "Custom-built tips with two-week wear.", dur: 90, price: 78 },
    { id: "svc-pedi", cat: "Spa", name: "Ritual Pedicure", desc: "Warm soak, exfoliation and pressure massage.", dur: 60, price: 65 },
    { id: "svc-facial", cat: "Spa", name: "Glow Facial", desc: "Double cleanse, mask and lymphatic massage.", dur: 75, price: 130 },
    { id: "svc-scalp", cat: "Spa", name: "Scalp Renewal", desc: "Detoxifying scrub and aromatic head massage.", dur: 40, price: 60 },
  ];

  const STYLISTS = [
    { id: "any", name: "Any available", spec: "We pair you with the soonest opening", rating: null, init: "✶", tint: null, cats: ["Hair", "Color", "Nails", "Spa"] },
    { id: "aria", name: "Aria Vance", spec: "Cutting & Editorial Color", rating: 4.9, init: "AV", tint: "linear-gradient(135deg,#c9a78f,#8c6d3f)", cats: ["Hair", "Color"] },
    { id: "noor", name: "Noor Halabi", spec: "Balayage & Blonding", rating: 4.8, init: "NH", tint: "linear-gradient(135deg,#b08d57,#5f4a2e)", cats: ["Color", "Hair"] },
    { id: "lena", name: "Lena Okafor", spec: "Nail Artistry", rating: 5.0, init: "LO", tint: "linear-gradient(135deg,#caa089,#9a6b50)", cats: ["Nails"] },
    { id: "mara", name: "Mara Sølv", spec: "Skin & Spa Rituals", rating: 4.9, init: "MS", tint: "linear-gradient(135deg,#a89178,#6e5a40)", cats: ["Spa"] },
    { id: "theo", name: "Theo Marchetti", spec: "Precision Barbering", rating: 4.7, init: "TM", tint: "linear-gradient(135deg,#9c8463,#5a4730)", cats: ["Hair"] },
  ];

  const SLOT_TIMES = ["9:30", "10:15", "11:00", "11:45", "13:00", "13:45", "14:30", "15:15", "16:00", "16:45", "17:30", "18:15"];
  const DOW = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

  /* ---------------- State ---------------- */
  const state = {
    step: 1,
    service: null,
    stylist: null,
    cat: "all",
    day: null, // ISO date string
    slot: null,
  };

  /* ---------------- Helpers ---------------- */
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => Array.from(r.querySelectorAll(s));
  const money = (n) => "$" + n;
  const fmtDur = (m) => {
    const h = Math.floor(m / 60), mm = m % 60;
    if (h && mm) return `${h}h ${mm}m`;
    if (h) return `${h}h`;
    return `${mm}m`;
  };

  let toastTimer;
  function toast(msg) {
    const el = $("#toast");
    el.textContent = msg;
    el.classList.add("is-visible");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => el.classList.remove("is-visible"), 3200);
  }

  /* ---------------- Render: services ---------------- */
  const serviceList = $("#serviceList");
  function renderServices() {
    const items = SERVICES.filter((s) => state.cat === "all" || s.cat === state.cat);
    serviceList.innerHTML = items
      .map(
        (s) => `
      <li>
        <button class="service ${state.service === s.id ? "is-selected" : ""}"
                data-svc="${s.id}" aria-pressed="${state.service === s.id}">
          <span class="service__cat">${s.cat}</span>
          <span class="service__body">
            <h3>${s.name}</h3>
            <p class="service__desc">${s.desc}</p>
          </span>
          <span class="service__meta">
            <span class="service__price">${money(s.price)}</span>
            <span class="service__dur">${fmtDur(s.dur)}</span>
          </span>
        </button>
      </li>`
      )
      .join("");
  }

  $("#serviceFilters").addEventListener("click", (e) => {
    const btn = e.target.closest("[data-cat]");
    if (!btn) return;
    state.cat = btn.dataset.cat;
    $$("#serviceFilters .chip").forEach((c) => {
      const on = c === btn;
      c.classList.toggle("is-active", on);
      c.setAttribute("aria-selected", on);
    });
    renderServices();
  });

  serviceList.addEventListener("click", (e) => {
    const btn = e.target.closest("[data-svc]");
    if (!btn) return;
    state.service = btn.dataset.svc;
    // If chosen stylist can't do this category, reset stylist.
    const svc = SERVICES.find((s) => s.id === state.service);
    if (state.stylist) {
      const st = STYLISTS.find((s) => s.id === state.stylist);
      if (st && !st.cats.includes(svc.cat)) state.stylist = null;
    }
    renderServices();
    sync();
  });

  /* ---------------- Render: stylists ---------------- */
  const stylistGrid = $("#stylistGrid");
  function renderStylists() {
    const svc = SERVICES.find((s) => s.id === state.service);
    const list = STYLISTS.filter((s) => !svc || s.cats.includes(svc.cat));
    stylistGrid.innerHTML = list
      .map((s) => {
        const sel = state.stylist === s.id;
        const avatar = s.tint
          ? `style="background:${s.tint}"`
          : "";
        const rating =
          s.rating === null
            ? `<span class="stylist__rating muted">Flexible timing</span>`
            : `<span class="stylist__rating"><span class="star">★</span>${s.rating.toFixed(1)}</span>`;
        return `
        <li>
          <button class="stylist ${s.id === "any" ? "stylist--any" : ""} ${sel ? "is-selected" : ""}"
                  data-stylist="${s.id}" aria-pressed="${sel}">
            <span class="stylist__avatar" ${avatar}>${s.init}</span>
            <span class="stylist__name">${s.name}</span>
            <span class="stylist__spec">${s.spec}</span>
            ${rating}
          </button>
        </li>`;
      })
      .join("");
  }

  stylistGrid.addEventListener("click", (e) => {
    const btn = e.target.closest("[data-stylist]");
    if (!btn) return;
    state.stylist = btn.dataset.stylist;
    renderStylists();
    sync();
  });

  /* ---------------- Render: days & slots ---------------- */
  const dayStrip = $("#dayStrip");
  const slotGrid = $("#slotGrid");

  // Build the next 10 days starting tomorrow.
  const DAYS = (() => {
    const out = [];
    const base = new Date();
    base.setHours(0, 0, 0, 0);
    for (let i = 1; i <= 10; i++) {
      const d = new Date(base);
      d.setDate(base.getDate() + i);
      out.push(d);
    }
    return out;
  })();

  function isoOf(d) {
    return d.toISOString().slice(0, 10);
  }

  // Deterministic pseudo-availability per day+time so it stays stable.
  function slotOpen(iso, time) {
    let h = 0;
    const str = iso + time;
    for (let i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) >>> 0;
    return h % 10 > 2; // ~70% open
  }

  function renderDays() {
    dayStrip.innerHTML = DAYS.map((d) => {
      const iso = isoOf(d);
      const sun = d.getDay() === 0; // closed Sundays
      const sel = state.day === iso;
      return `
        <button class="day ${sel ? "is-selected" : ""}" data-day="${iso}"
                role="option" aria-selected="${sel}" ${sun ? "disabled" : ""}>
          <span class="day__dow">${DOW[d.getDay()]}</span>
          <span class="day__num">${d.getDate()}</span>
          <span class="day__mon">${MON[d.getMonth()]}</span>
        </button>`;
    }).join("");
  }

  function renderSlots() {
    if (!state.day) {
      slotGrid.innerHTML = `<p class="slots__empty">Select a day above to see open times.</p>`;
      return;
    }
    slotGrid.innerHTML = SLOT_TIMES.map((t) => {
      const open = slotOpen(state.day, t);
      const sel = state.slot === t;
      return `
        <button class="slot ${sel ? "is-selected" : ""}" data-slot="${t}"
                role="option" aria-selected="${sel}" ${open ? "" : "disabled aria-disabled=\"true\""}>
          ${t}
        </button>`;
    }).join("");
  }

  dayStrip.addEventListener("click", (e) => {
    const btn = e.target.closest("[data-day]");
    if (!btn || btn.disabled) return;
    state.day = btn.dataset.day;
    state.slot = null; // reset slot when day changes
    renderDays();
    renderSlots();
    sync();
  });

  slotGrid.addEventListener("click", (e) => {
    const btn = e.target.closest("[data-slot]");
    if (!btn || btn.disabled) return;
    state.slot = btn.dataset.slot;
    renderSlots();
    sync();
  });

  /* ---------------- Summary + totals ---------------- */
  function prettyDay(iso) {
    const d = new Date(iso + "T00:00:00");
    return `${DOW[d.getDay()]}, ${MON[d.getMonth()]} ${d.getDate()}`;
  }

  function setRow(row, valHtml, filled) {
    const valEl = $(`.summary__row[data-row="${row}"] .summary__val`);
    valEl.innerHTML = valHtml;
    valEl.classList.toggle("muted", !filled);
  }

  function sync() {
    const svc = SERVICES.find((s) => s.id === state.service);
    const st = STYLISTS.find((s) => s.id === state.stylist);

    setRow(
      "service",
      svc ? `${svc.name}<small>${svc.cat} · ${fmtDur(svc.dur)}</small>` : "Not selected",
      !!svc
    );
    setRow("stylist", st ? st.name : "Not selected", !!st);
    setRow(
      "when",
      state.day && state.slot
        ? `${prettyDay(state.day)}<small>${state.slot}</small>`
        : "Not selected",
      !!(state.day && state.slot)
    );

    $("#totalDuration").textContent = svc ? fmtDur(svc.dur) : "—";
    $("#totalPrice").textContent = svc ? money(svc.price) : "$0";

    // Footer continue button gating
    const nextBtn = $("#nextBtn");
    nextBtn.disabled = !stepValid(state.step);

    // Confirm button: needs everything
    $("#confirmBtn").disabled = !(state.service && state.stylist && state.day && state.slot);
  }

  function stepValid(step) {
    if (step === 1) return !!state.service;
    if (step === 2) return !!state.stylist;
    if (step === 3) return !!(state.day && state.slot);
    return false;
  }

  /* ---------------- Step navigation ---------------- */
  function showStep(step) {
    state.step = step;
    $$(".screen").forEach((s) => s.classList.remove("is-active"));
    $(`.screen[data-screen="${step}"]`).classList.add("is-active");

    $$("#steps .step").forEach((el) => {
      const n = Number(el.dataset.step);
      el.classList.toggle("is-active", n === step);
      el.classList.toggle("is-done", n < step);
    });

    $("#backBtn").hidden = step === 1;
    const nextBtn = $("#nextBtn");
    nextBtn.textContent = step === 3 ? "Review & confirm" : "Continue";
    $("#panelActions").hidden = false;

    if (step === 2) renderStylists();
    if (step === 3) {
      renderDays();
      renderSlots();
    }
    sync();
  }

  $("#nextBtn").addEventListener("click", () => {
    if (!stepValid(state.step)) {
      const msg =
        state.step === 1
          ? "Please choose a service first."
          : state.step === 2
            ? "Please choose a stylist."
            : "Please pick a date and time.";
      toast(msg);
      return;
    }
    if (state.step < 3) {
      showStep(state.step + 1);
    } else {
      $("#confirmBtn").focus();
      toast("Looking good — confirm to lock it in.");
    }
  });

  $("#backBtn").addEventListener("click", () => {
    if (state.step > 1) showStep(state.step - 1);
  });

  /* ---------------- Confirm ---------------- */
  function makeRef() {
    const a = "ML";
    const n = Math.floor(1000 + Math.random() * 9000);
    const c = String.fromCharCode(65 + Math.floor(Math.random() * 26));
    return `${a}-${n}-${c}`;
  }

  $("#confirmBtn").addEventListener("click", () => {
    if (!(state.service && state.stylist && state.day && state.slot)) {
      toast("Complete every step before confirming.");
      return;
    }
    const svc = SERVICES.find((s) => s.id === state.service);
    const st = STYLISTS.find((s) => s.id === state.stylist);
    const ref = makeRef();

    $("#confirmRef").textContent = ref;
    $("#confirmCopy").innerHTML =
      `Your <strong>${svc.name}</strong> with <strong>${st.name}</strong> is reserved for ` +
      `<strong>${prettyDay(state.day)} at ${state.slot}</strong>. We can't wait to see you.`;

    // Hide stepper + actions, show confirmation.
    $("#steps").classList.add("is-hidden");
    $$(".screen").forEach((s) => s.classList.remove("is-active"));
    $(`.screen[data-screen="done"]`).classList.add("is-active");
    $("#panelActions").hidden = true;
    $$("#steps .step").forEach((el) => el.classList.add("is-done"));

    toast(`Booked! Reference ${ref}`);
  });

  $("#restartBtn").addEventListener("click", () => {
    state.service = null;
    state.stylist = null;
    state.cat = "all";
    state.day = null;
    state.slot = null;
    $("#steps").classList.remove("is-hidden");
    $$("#steps .step").forEach((el) => el.classList.remove("is-done"));
    $$("#serviceFilters .chip").forEach((c, i) => {
      c.classList.toggle("is-active", i === 0);
      c.setAttribute("aria-selected", i === 0);
    });
    renderServices();
    showStep(1);
    toast("Let's start a fresh booking.");
  });

  /* ---------------- Init ---------------- */
  renderServices();
  showStep(1);
})();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --shadow-sm: 0 1px 2px rgba(28, 42, 37, 0.05), 0 2px 8px rgba(28, 42, 37, 0.05);
  --shadow-md: 0 8px 24px rgba(28, 42, 37, 0.09), 0 2px 6px rgba(28, 42, 37, 0.06);
  --shadow-lg: 0 24px 60px rgba(22, 48, 42, 0.18), 0 8px 22px rgba(22, 48, 42, 0.1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--ivory);
  color: var(--ink);
  font-family: "Inter", system-ui, sans-serif;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1,
h2,
h3 {
  font-family: "Cormorant Garamond", Georgia, serif;
  margin: 0;
  line-height: 1.05;
  letter-spacing: 0.2px;
}

p {
  margin: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

.wrap {
  width: 100%;
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 28px;
}

.display {
  font-weight: 600;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: -999px;
  top: 8px;
  background: var(--green);
  color: var(--paper);
  padding: 10px 16px;
  border-radius: var(--r-sm);
  z-index: 100;
}
.skip-link:focus {
  left: 12px;
}

:focus-visible {
  outline: 2px solid var(--brass);
  outline-offset: 2px;
}

/* ===================== BUTTONS / CHIPS ===================== */
.btn {
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 12px 22px;
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease,
    border-color 0.18s ease, color 0.18s ease;
  white-space: nowrap;
}
.btn:active {
  transform: translateY(1px);
}
.btn-sm {
  padding: 9px 18px;
  font-size: 0.88rem;
}
.btn-brass {
  background: var(--brass);
  color: #1a1305;
  box-shadow: 0 6px 16px rgba(176, 141, 87, 0.32);
}
.btn-brass:hover {
  background: var(--brass-d);
  color: #fff;
  box-shadow: 0 10px 22px rgba(148, 115, 63, 0.4);
  transform: translateY(-1px);
}
.btn-ghost {
  background: transparent;
  border-color: var(--line-2);
  color: var(--green);
}
.btn-ghost:hover {
  background: var(--green);
  color: var(--paper);
  border-color: var(--green);
}

.chip {
  font: inherit;
  font-size: 0.82rem;
  font-weight: 500;
  background: var(--white);
  border: 1px solid var(--line);
  color: var(--ink-2);
  border-radius: 999px;
  padding: 6px 13px;
  cursor: pointer;
  transition: border-color 0.16s, color 0.16s, background 0.16s;
}
.chip:hover {
  border-color: var(--brass);
  color: var(--brass-d);
  background: var(--brass-50);
}

/* ===================== HEADER ===================== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 40;
  background: rgba(247, 244, 236, 0.82);
  backdrop-filter: saturate(160%) blur(12px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 24px;
  height: 70px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  font-weight: 700;
}
.brand-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: var(--green);
  color: var(--brass-50);
  font-family: "Cormorant Garamond", serif;
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: 0.5px;
  box-shadow: inset 0 0 0 1px rgba(176, 141, 87, 0.4);
}
.brand-name {
  font-family: "Cormorant Garamond", serif;
  font-size: 1.32rem;
  font-weight: 600;
  color: var(--green-d);
}
.site-nav {
  display: flex;
  gap: 26px;
  margin-left: auto;
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--ink-2);
}
.site-nav a {
  position: relative;
  padding: 4px 0;
  transition: color 0.16s;
}
.site-nav a::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -2px;
  height: 1.5px;
  width: 0;
  background: var(--brass);
  transition: width 0.22s ease;
}
.site-nav a:hover {
  color: var(--green);
}
.site-nav a:hover::after {
  width: 100%;
}
.header-inner .btn-ghost {
  margin-left: 4px;
}

/* ===================== PHOTO BASE ===================== */
.photo {
  position: relative;
  border-radius: var(--r-md);
  overflow: hidden;
  background: var(--green-700);
  isolation: isolate;
}
.photo::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0, 0, 0, 0) 45%, rgba(20, 30, 26, 0.42) 100%);
  z-index: 1;
}
.photo-tag {
  position: absolute;
  left: 12px;
  bottom: 12px;
  z-index: 2;
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.3px;
  color: #fff;
  background: rgba(22, 35, 30, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.18);
  padding: 4px 10px;
  border-radius: 999px;
  backdrop-filter: blur(4px);
}

/* simulated property photography */
.photo--hero {
  aspect-ratio: 4 / 5;
  background:
    radial-gradient(120% 80% at 78% 8%, rgba(255, 233, 196, 0.85), transparent 55%),
    radial-gradient(90% 60% at 10% 92%, rgba(35, 70, 60, 0.7), transparent 60%),
    linear-gradient(160deg, #d8a86b 0%, #b07a47 28%, #6f5237 52%, #2e4a3f 78%, #1c3a31 100%);
}
.photo--hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(105deg, transparent 38%, rgba(255, 246, 222, 0.16) 40%, transparent 43%),
    repeating-linear-gradient(92deg, rgba(20, 30, 25, 0.12) 0 2px, transparent 2px 64px),
    repeating-linear-gradient(0deg, rgba(255, 245, 220, 0.05) 0 1px, transparent 1px 40px);
  z-index: 1;
}

.photo--l1 {
  background:
    radial-gradient(100% 70% at 80% 10%, rgba(190, 224, 240, 0.7), transparent 60%),
    linear-gradient(155deg, #9fc4d6 0%, #6f99ad 40%, #3f6a72 70%, #274f51 100%);
}
.photo--l2 {
  background:
    radial-gradient(110% 75% at 75% 6%, rgba(255, 236, 198, 0.8), transparent 55%),
    linear-gradient(155deg, #e0b878 0%, #b98e54 38%, #7a6342 68%, #2f4a3f 100%);
}
.photo--l3 {
  background:
    radial-gradient(100% 70% at 20% 12%, rgba(247, 224, 210, 0.7), transparent 60%),
    linear-gradient(150deg, #cf9f86 0%, #a87a63 42%, #6f5747 72%, #3a4239 100%);
}
.photo--l4 {
  background:
    radial-gradient(100% 65% at 82% 14%, rgba(214, 233, 205, 0.7), transparent 58%),
    linear-gradient(155deg, #a8c486 0%, #7fa066 42%, #4f7253 72%, #284b3c 100%);
}
.photo--l5 {
  background:
    radial-gradient(120% 80% at 70% 4%, rgba(206, 228, 240, 0.75), transparent 55%),
    linear-gradient(160deg, #b9d2dd 0%, #7e9aa6 36%, #4b6c70 66%, #233f3a 100%);
}
.photo--l6 {
  background:
    radial-gradient(100% 70% at 16% 10%, rgba(255, 228, 196, 0.72), transparent 58%),
    linear-gradient(150deg, #d8b27e 0%, #a9814f 44%, #6f5a3c 74%, #2c4239 100%);
}
.listing .photo {
  aspect-ratio: 4 / 3;
}
.listing .photo::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(100deg, transparent 46%, rgba(255, 250, 235, 0.14) 49%, transparent 52%),
    repeating-linear-gradient(90deg, rgba(15, 25, 22, 0.07) 0 1px, transparent 1px 54px);
  z-index: 1;
}

/* agent portraits */
.agent .photo {
  aspect-ratio: 1 / 1;
}
.photo--a1 {
  background:
    radial-gradient(60% 50% at 50% 36%, rgba(255, 236, 210, 0.9), transparent 60%),
    linear-gradient(160deg, #c9a37a 0%, #7c6347 50%, #2c463c 100%);
}
.photo--a2 {
  background:
    radial-gradient(60% 50% at 50% 36%, rgba(228, 210, 240, 0.85), transparent 60%),
    linear-gradient(160deg, #8d7fa0 0%, #5a5170 50%, #233f3a 100%);
}
.photo--a3 {
  background:
    radial-gradient(60% 50% at 50% 36%, rgba(255, 224, 222, 0.85), transparent 60%),
    linear-gradient(160deg, #cf8f87 0%, #7d5a55 50%, #2c463c 100%);
}
.photo--a4 {
  background:
    radial-gradient(60% 50% at 50% 36%, rgba(214, 233, 205, 0.85), transparent 60%),
    linear-gradient(160deg, #8aa478 0%, #4f6c50 50%, #233f3a 100%);
}
.agent .photo::before {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -8%;
  transform: translateX(-50%);
  width: 56%;
  height: 60%;
  border-radius: 50% 50% 12% 12% / 60% 60% 12% 12%;
  background: rgba(22, 35, 30, 0.28);
  z-index: 1;
}

/* ===================== HERO ===================== */
.hero {
  padding: 56px 0 64px;
  background:
    radial-gradient(80% 60% at 90% -10%, var(--brass-50), transparent 60%),
    linear-gradient(180deg, var(--ivory), var(--paper));
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 56px;
  align-items: center;
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--brass-d);
  margin-bottom: 18px;
}
.eyebrow .dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--brass);
  box-shadow: 0 0 0 4px rgba(176, 141, 87, 0.18);
}
.eyebrow--ink {
  color: var(--muted);
}
.eyebrow--brass {
  color: var(--brass);
}
h1.display {
  font-size: clamp(2.7rem, 5.4vw, 4.4rem);
  color: var(--green-d);
  margin-bottom: 18px;
}
.lede {
  font-size: 1.08rem;
  color: var(--ink-2);
  max-width: 46ch;
  margin-bottom: 28px;
}

.search {
  display: flex;
  align-items: flex-end;
  gap: 6px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 10px;
  box-shadow: var(--shadow-md);
  max-width: 560px;
}
.search-field {
  display: flex;
  flex-direction: column;
  padding: 6px 12px;
  flex: 1 1 auto;
  min-width: 0;
  border-right: 1px solid var(--line);
}
.search-field--select {
  flex: 0 0 auto;
}
.search-field label {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 2px;
}
.search-field input,
.search-field select {
  border: 0;
  background: transparent;
  font: inherit;
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--ink);
  padding: 2px 0;
  width: 100%;
  outline: none;
}
.search-field select {
  cursor: pointer;
}
.search .btn {
  flex: 0 0 auto;
  margin-left: 4px;
}
.search-hint {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 18px;
  font-size: 0.85rem;
  color: var(--muted);
}

.hero-photo {
  box-shadow: var(--shadow-lg);
}
.hero-float {
  position: absolute;
  left: 16px;
  bottom: 16px;
  right: 16px;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 2px;
  background: rgba(255, 253, 248, 0.93);
  border: 1px solid rgba(176, 141, 87, 0.3);
  border-radius: var(--r-md);
  padding: 14px 16px;
  box-shadow: var(--shadow-md);
  backdrop-filter: blur(6px);
}
.hf-label {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--brass-d);
}
.hf-title {
  font-family: "Cormorant Garamond", serif;
  font-size: 1.28rem;
  font-weight: 600;
  color: var(--green-d);
}
.hf-meta {
  font-size: 0.82rem;
  color: var(--muted);
}

/* ===================== STATS ===================== */
.stats {
  background: var(--green);
  color: var(--paper);
  padding: 0;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  padding: 34px 28px;
}
.stat {
  text-align: center;
  padding: 4px 16px;
  border-left: 1px solid rgba(255, 255, 255, 0.1);
}
.stat:first-child {
  border-left: 0;
}
.stat-num {
  display: block;
  font-family: "Cormorant Garamond", serif;
  font-size: clamp(2rem, 3.6vw, 2.9rem);
  font-weight: 600;
  color: #fff;
  line-height: 1;
}
.stat-label {
  font-size: 0.82rem;
  letter-spacing: 0.04em;
  color: rgba(232, 239, 234, 0.74);
  margin-top: 8px;
  display: block;
}

/* ===================== SECTIONS ===================== */
.section {
  padding: 72px 0;
}
.section--paper {
  background: var(--paper);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 36px;
}
.section-head--center {
  justify-content: center;
  text-align: center;
  margin-bottom: 44px;
}
.section-title {
  font-size: clamp(2rem, 3.6vw, 2.8rem);
  color: var(--green-d);
}
.section-title--light {
  color: var(--paper);
}

/* carousel */
.carousel-ctrl {
  display: flex;
  gap: 10px;
}
.round-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--green);
  font-size: 1.1rem;
  cursor: pointer;
  transition: background 0.16s, color 0.16s, border-color 0.16s, transform 0.16s;
}
.round-btn:hover {
  background: var(--green);
  color: var(--paper);
  border-color: var(--green);
}
.round-btn:active {
  transform: scale(0.94);
}
.round-btn[disabled] {
  opacity: 0.4;
  cursor: not-allowed;
}

.carousel {
  overflow: hidden;
  padding: 6px 0;
}
.track {
  display: flex;
  gap: 24px;
  list-style: none;
  margin: 0;
  padding: 0 28px;
  max-width: 1180px;
  margin-inline: auto;
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: transform;
}

.card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}
.listing {
  flex: 0 0 calc((100% - 48px) / 3);
  min-width: 0;
}
.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: var(--line-2);
}

.badge {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 2;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 999px;
  color: #fff;
}
.badge-status {
  background: rgba(31, 61, 52, 0.92);
}
.badge-new {
  background: var(--brass);
  color: #1a1305;
}
.badge-pending {
  background: var(--warn);
  color: #2a1c05;
}

.fav {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 2;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.25);
  background: rgba(22, 35, 30, 0.45);
  color: #fff;
  font-size: 1.05rem;
  line-height: 1;
  cursor: pointer;
  backdrop-filter: blur(4px);
  transition: background 0.16s, transform 0.16s, color 0.16s;
}
.fav:hover {
  background: rgba(22, 35, 30, 0.7);
  transform: scale(1.08);
}
.fav.is-saved {
  background: var(--brass);
  color: #1a1305;
  border-color: var(--brass);
}

.listing-body {
  padding: 18px 20px 22px;
}
.listing-price {
  font-family: "Cormorant Garamond", serif;
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--green-d);
  line-height: 1;
}
.listing-title {
  font-size: 1.32rem;
  font-weight: 600;
  color: var(--ink);
  margin-top: 8px;
}
.listing-addr {
  font-size: 0.88rem;
  color: var(--muted);
  margin-top: 4px;
}
.specs {
  display: flex;
  gap: 16px;
  list-style: none;
  margin: 14px 0 0;
  padding: 14px 0 0;
  border-top: 1px solid var(--line);
  font-size: 0.86rem;
  font-weight: 500;
  color: var(--ink-2);
}
.specs li {
  position: relative;
}
.specs li + li::before {
  content: "";
  position: absolute;
  left: -8px;
  top: 50%;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--brass);
  transform: translateY(-50%);
}

.dots {
  display: flex;
  justify-content: center;
  gap: 9px;
  margin-top: 30px;
}
.dot-btn {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: 0;
  background: var(--line-2);
  cursor: pointer;
  padding: 0;
  transition: width 0.22s, background 0.22s;
}
.dot-btn.is-active {
  width: 26px;
  border-radius: 999px;
  background: var(--brass);
}

/* feature trio */
.feature-trio {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.feature {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 30px 28px;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s, box-shadow 0.2s;
}
.feature:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}
.feature-ic {
  display: grid;
  place-items: center;
  width: 50px;
  height: 50px;
  border-radius: 14px;
  background: var(--green-50);
  color: var(--green);
  font-size: 1.4rem;
  margin-bottom: 18px;
  border: 1px solid var(--line);
}
.feature h3 {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--green-d);
  margin-bottom: 8px;
}
.feature p {
  font-size: 0.96rem;
  color: var(--ink-2);
}

/* agents */
.agent-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.agent {
  text-align: left;
}
.agent-body {
  padding: 18px 20px 22px;
}
.agent-body h3 {
  font-size: 1.4rem;
  font-weight: 600;
  color: var(--green-d);
}
.agent-role {
  font-size: 0.86rem;
  color: var(--brass-d);
  font-weight: 600;
  margin-top: 2px;
}
.agent-stat {
  font-size: 0.84rem;
  color: var(--muted);
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--line);
}

/* testimonials */
.section--green {
  background:
    radial-gradient(70% 50% at 85% 0%, rgba(176, 141, 87, 0.16), transparent 60%),
    var(--green);
}
.quotes {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.quote {
  margin: 0;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--r-lg);
  padding: 28px 26px;
}
.quote blockquote {
  margin: 0 0 18px;
  font-family: "Cormorant Garamond", serif;
  font-size: 1.32rem;
  font-weight: 500;
  line-height: 1.34;
  color: var(--paper);
}
.quote figcaption {
  display: flex;
  flex-direction: column;
  gap: 2px;
  border-top: 1px solid rgba(176, 141, 87, 0.35);
  padding-top: 14px;
}
.q-name {
  font-weight: 600;
  color: #fff;
  font-size: 0.95rem;
}
.q-meta {
  font-size: 0.82rem;
  color: rgba(232, 239, 234, 0.7);
}

/* CTA */
.cta {
  padding: 64px 0;
  background:
    radial-gradient(70% 90% at 10% 10%, var(--brass-50), transparent 60%),
    var(--paper);
}
.cta-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 44px 48px;
  box-shadow: var(--shadow-md);
  position: relative;
  overflow: hidden;
}
.cta-inner::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: linear-gradient(180deg, var(--brass), var(--green));
}
.cta-title {
  font-size: clamp(1.9rem, 3.4vw, 2.6rem);
  color: var(--green-d);
  margin-bottom: 8px;
}
.cta-copy p {
  color: var(--ink-2);
  max-width: 42ch;
}
.cta-form {
  display: flex;
  gap: 8px;
  flex: 0 0 auto;
}
.cta-form input {
  font: inherit;
  font-size: 0.95rem;
  padding: 12px 16px;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  background: var(--paper);
  min-width: 240px;
  outline: none;
  transition: border-color 0.16s, box-shadow 0.16s;
}
.cta-form input:focus {
  border-color: var(--brass);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.18);
}

/* footer */
.site-footer {
  background: var(--green-d);
  color: rgba(232, 239, 234, 0.8);
  padding: 48px 0 36px;
}
.footer-inner {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 24px 40px;
  align-items: start;
}
.footer-brand {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  font-size: 0.88rem;
  line-height: 1.5;
}
.footer-brand .brand-mark {
  flex: 0 0 auto;
}
.footer-nav {
  display: flex;
  gap: 24px;
  justify-content: flex-end;
  flex-wrap: wrap;
  font-size: 0.92rem;
  font-weight: 500;
}
.footer-nav a:hover {
  color: var(--brass);
}
.footer-fine {
  grid-column: 1 / -1;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 20px;
  margin-top: 10px;
  font-size: 0.8rem;
  color: rgba(232, 239, 234, 0.55);
}

/* toasts */
.toast-host {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 80;
  display: flex;
  flex-direction: column;
  gap: 10px;
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--green-d);
  color: var(--paper);
  border: 1px solid rgba(176, 141, 87, 0.45);
  border-radius: var(--r-md);
  padding: 13px 18px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  transform: translateY(16px);
  opacity: 0;
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.3s;
  max-width: 320px;
}
.toast.is-in {
  transform: translateY(0);
  opacity: 1;
}
.toast .t-ic {
  color: var(--brass);
  font-size: 1.05rem;
}

/* ===================== RESPONSIVE ===================== */
@media (max-width: 920px) {
  .hero-grid {
    grid-template-columns: 1fr;
    gap: 36px;
  }
  .photo--hero {
    aspect-ratio: 16 / 10;
  }
  .agent-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .listing {
    flex-basis: calc((100% - 24px) / 2);
  }
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 24px 0;
  }
  .stat:nth-child(3) {
    border-left: 0;
  }
}

@media (max-width: 760px) {
  .feature-trio,
  .quotes {
    grid-template-columns: 1fr;
  }
  .cta-inner {
    flex-direction: column;
    align-items: flex-start;
    padding: 32px 28px;
  }
  .cta-form {
    width: 100%;
  }
  .cta-form input {
    flex: 1;
    min-width: 0;
  }
}

@media (max-width: 520px) {
  .wrap {
    padding: 0 18px;
  }
  .site-nav {
    display: none;
  }
  .header-inner {
    height: 62px;
  }
  .hero {
    padding: 36px 0 44px;
  }
  h1.display {
    font-size: clamp(2.3rem, 10vw, 2.9rem);
  }
  .search {
    flex-wrap: wrap;
    border-radius: var(--r-lg);
  }
  .search-field {
    border-right: 0;
    border-bottom: 1px solid var(--line);
    flex: 1 1 100%;
  }
  .search-field--select {
    flex: 1 1 calc(50% - 3px);
    border-bottom: 0;
  }
  .search .btn {
    flex: 1 1 100%;
    margin-left: 0;
    margin-top: 4px;
  }
  .listing {
    flex-basis: calc(100% - 0px);
  }
  .agent-grid {
    grid-template-columns: 1fr;
  }
  .stats-grid {
    grid-template-columns: 1fr 1fr;
  }
  .section {
    padding: 52px 0;
  }
  .section-head {
    flex-wrap: wrap;
  }
  .track {
    padding: 0 18px;
  }
  .footer-inner {
    grid-template-columns: 1fr;
  }
  .footer-nav {
    justify-content: flex-start;
  }
  .toast-host {
    left: 16px;
    right: 16px;
  }
  .toast {
    max-width: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    scroll-behavior: auto !important;
  }
  .track,
  .toast,
  .btn,
  .card {
    transition-duration: 0.01ms !important;
  }
}

