/* Harbor & Vale — Brokerage Landing
 * Vanilla JS: toast helper, animated stats, listings carousel, favourites,
 * search + CTA handlers. No external libraries.
 */
(function () {
  "use strict";

  /* ---------- toast helper ---------- */
  var toastHost = document.getElementById("toast-host");
  function toast(msg, opts) {
    opts = opts || {};
    var el = document.createElement("div");
    el.className = "toast";
    el.setAttribute("role", "status");
    var ic = document.createElement("span");
    ic.className = "t-ic";
    ic.setAttribute("aria-hidden", "true");
    ic.textContent = opts.icon || "✓";
    var txt = document.createElement("span");
    txt.textContent = msg;
    el.appendChild(ic);
    el.appendChild(txt);
    toastHost.appendChild(el);
    // force reflow then animate in
    void el.offsetWidth;
    el.classList.add("is-in");
    var life = opts.duration || 3200;
    setTimeout(function () {
      el.classList.remove("is-in");
      setTimeout(function () {
        if (el.parentNode) el.parentNode.removeChild(el);
      }, 320);
    }, life);
  }

  /* ---------- animated stat counters ---------- */
  function formatCount(value, decimals) {
    if (decimals > 0) return value.toFixed(decimals);
    return Math.round(value).toLocaleString("en-US");
  }

  function animateStat(el) {
    var target = parseFloat(el.getAttribute("data-count"));
    var prefix = el.getAttribute("data-prefix") || "";
    var suffix = el.getAttribute("data-suffix") || "";
    var decimals = target % 1 !== 0 ? 1 : 0;
    var start = null;
    var duration = 1400;
    function step(ts) {
      if (start === null) start = ts;
      var p = Math.min((ts - start) / duration, 1);
      // easeOutCubic
      var eased = 1 - Math.pow(1 - p, 3);
      el.textContent = prefix + formatCount(target * eased, decimals) + suffix;
      if (p < 1) requestAnimationFrame(step);
      else el.textContent = prefix + formatCount(target, decimals) + suffix;
    }
    requestAnimationFrame(step);
  }

  var statEls = Array.prototype.slice.call(document.querySelectorAll(".stat-num"));
  if (statEls.length) {
    if ("IntersectionObserver" in window) {
      var seen = new WeakSet();
      var io = new IntersectionObserver(
        function (entries) {
          entries.forEach(function (e) {
            if (e.isIntersecting && !seen.has(e.target)) {
              seen.add(e.target);
              animateStat(e.target);
            }
          });
        },
        { threshold: 0.5 }
      );
      statEls.forEach(function (el) {
        io.observe(el);
      });
    } else {
      statEls.forEach(animateStat);
    }
  }

  /* ---------- listings carousel ---------- */
  var track = document.querySelector(".js-track");
  var prevBtn = document.querySelector(".js-prev");
  var nextBtn = document.querySelector(".js-next");
  var dotsHost = document.querySelector(".js-dots");

  if (track && prevBtn && nextBtn) {
    var slides = Array.prototype.slice.call(track.children);
    var page = 0;

    function perView() {
      var w = window.innerWidth;
      if (w <= 520) return 1;
      if (w <= 920) return 2;
      return 3;
    }
    function pageCount() {
      return Math.max(1, Math.ceil(slides.length / perView()));
    }

    function buildDots() {
      if (!dotsHost) return;
      dotsHost.innerHTML = "";
      var count = pageCount();
      for (var i = 0; i < count; i++) {
        var b = document.createElement("button");
        b.className = "dot-btn";
        b.type = "button";
        b.setAttribute("role", "tab");
        b.setAttribute("aria-label", "Go to listing page " + (i + 1));
        (function (idx) {
          b.addEventListener("click", function () {
            goTo(idx);
          });
        })(i);
        dotsHost.appendChild(b);
      }
    }

    function update() {
      var pv = perView();
      var slide = slides[0];
      var gap = parseFloat(getComputedStyle(track).columnGap || getComputedStyle(track).gap) || 24;
      var slideW = slide.getBoundingClientRect().width;
      var step = (slideW + gap) * pv;
      var maxPage = pageCount() - 1;
      if (page > maxPage) page = maxPage;
      track.style.transform = "translateX(" + -(step * page) + "px)";

      prevBtn.disabled = page === 0;
      nextBtn.disabled = page === maxPage;

      if (dotsHost) {
        var dots = dotsHost.querySelectorAll(".dot-btn");
        dots.forEach(function (d, i) {
          d.classList.toggle("is-active", i === page);
          d.setAttribute("aria-selected", i === page ? "true" : "false");
        });
      }
    }

    function goTo(p) {
      var maxPage = pageCount() - 1;
      page = Math.max(0, Math.min(p, maxPage));
      update();
    }

    nextBtn.addEventListener("click", function () {
      goTo(page + 1);
    });
    prevBtn.addEventListener("click", function () {
      goTo(page - 1);
    });

    // keyboard arrows when carousel region focused/hovered
    document.querySelector(".carousel").setAttribute("tabindex", "0");
    document.querySelector(".carousel").addEventListener("keydown", function (e) {
      if (e.key === "ArrowRight") {
        e.preventDefault();
        goTo(page + 1);
      } else if (e.key === "ArrowLeft") {
        e.preventDefault();
        goTo(page - 1);
      }
    });

    var resizeTimer;
    window.addEventListener("resize", function () {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(function () {
        buildDots();
        update();
      }, 120);
    });

    buildDots();
    update();
  }

  /* ---------- favourite (save) toggles ---------- */
  Array.prototype.slice.call(document.querySelectorAll(".js-fav")).forEach(function (btn) {
    btn.addEventListener("click", function () {
      var saved = btn.classList.toggle("is-saved");
      btn.setAttribute("aria-pressed", saved ? "true" : "false");
      btn.textContent = saved ? "♥" : "♡";
      var card = btn.closest(".listing");
      var title = card ? card.querySelector(".listing-title").textContent : "Listing";
      toast(saved ? "Saved " + title + " to your shortlist" : "Removed from shortlist", {
        icon: saved ? "♥" : "✕"
      });
    });
  });

  /* ---------- hero search ---------- */
  var searchForm = document.querySelector(".search");
  if (searchForm) {
    searchForm.addEventListener("submit", function (e) {
      e.preventDefault();
      var where = document.getElementById("q").value.trim();
      var place = where || "Aldermoor";
      toast("Searching " + place + " — 47 homes match your filters", { icon: "⌕" });
    });
    Array.prototype.slice.call(document.querySelectorAll(".search-hint .chip")).forEach(function (chip) {
      chip.addEventListener("click", function () {
        toast("Filter applied: " + chip.textContent, { icon: "✧" });
      });
    });
  }

  /* ---------- contact + CTA ---------- */
  Array.prototype.slice.call(document.querySelectorAll(".js-contact")).forEach(function (b) {
    b.addEventListener("click", function () {
      toast("An advisor will reach out within one business day.", { icon: "☎" });
    });
  });

  var ctaForm = document.querySelector(".js-cta-form");
  if (ctaForm) {
    ctaForm.addEventListener("submit", function (e) {
      e.preventDefault();
      var email = ctaForm.querySelector("input[type=email]").value.trim();
      if (!email) return;
      toast("Valuation request received for " + email, { icon: "✓" });
      ctaForm.reset();
    });
  }
})();

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

button:focus-visible,
input:focus-visible,
.tab:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
}

/* ── Layout ── */
.inv {
  max-width: 1000px;
  margin: 0 auto;
  padding: 32px 22px 64px;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

/* ── Header ── */
.inv-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.eyebrow {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--teal-d);
}
.inv-title h1 {
  font-size: 1.7rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-top: 4px;
}
.sub {
  color: var(--muted);
  font-size: 0.9rem;
  max-width: 46ch;
  margin-top: 6px;
}

/* ── Summary cards ── */
.summary {
  display: flex;
  gap: 12px;
}
.stat {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 12px 18px;
  min-width: 96px;
  box-shadow: var(--shadow-1);
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.stat-label {
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--muted);
  white-space: nowrap;
}
.stat-val {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--ink);
  line-height: 1.1;
}
.stat.is-low {
  border-color: rgba(217, 138, 43, 0.35);
  background: linear-gradient(180deg, #fff, #fff7ec);
}
.stat.is-low .stat-val {
  color: var(--warn);
}
.stat.is-out {
  border-color: rgba(212, 80, 62, 0.35);
  background: linear-gradient(180deg, #fff, #fff1ee);
}
.stat.is-out .stat-val {
  color: var(--danger);
}

/* ── Toolbar ── */
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
}
.tabs {
  display: inline-flex;
  gap: 4px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 4px;
  box-shadow: var(--shadow-1);
}
.tab {
  border: none;
  background: transparent;
  border-radius: 999px;
  padding: 8px 18px;
  font: inherit;
  font-weight: 600;
  font-size: 0.88rem;
  color: var(--muted);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background 0.15s, color 0.15s;
}
.tab:hover {
  color: var(--ink-2);
}
.tab.is-active {
  background: var(--teal-d);
  color: #fff;
}
.count {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--teal-50);
  color: var(--teal-d);
  font-size: 0.74rem;
  font-weight: 700;
}
.tab.is-active .count {
  background: rgba(255, 255, 255, 0.22);
  color: #fff;
}

.search {
  position: relative;
  flex: 1;
  min-width: 200px;
  max-width: 320px;
}
.search-ico {
  position: absolute;
  left: 13px;
  top: 50%;
  transform: translateY(-50%);
  width: 17px;
  height: 17px;
  fill: none;
  stroke: var(--muted);
  stroke-width: 2;
  stroke-linecap: round;
  pointer-events: none;
}
.search input {
  width: 100%;
  font: inherit;
  font-size: 0.9rem;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: 999px;
  padding: 10px 16px 10px 38px;
  transition: border-color 0.15s, box-shadow 0.15s;
}
.search input::placeholder {
  color: var(--muted);
}
.search input:focus {
  outline: none;
  border-color: var(--teal);
  box-shadow: 0 0 0 3px var(--teal-50);
}

/* ── Table ── */
.table-wrap {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-1);
  overflow: hidden;
}
.inv-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}
.inv-table thead th {
  text-align: left;
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
  padding: 14px 16px;
  background: #f7fbfa;
  border-bottom: 1px solid var(--line);
  white-space: nowrap;
}
.col-onhand,
.col-par {
  text-align: center;
}
.inv-table tbody tr {
  border-bottom: 1px solid var(--line);
  transition: background 0.15s;
}
.inv-table tbody tr:last-child {
  border-bottom: none;
}
.inv-table tbody tr:hover {
  background: #f6fbfa;
}
.inv-table td {
  padding: 14px 16px;
  vertical-align: middle;
}

/* Row status accents */
tr[data-status="low"] {
  background: #fffaf1;
}
tr[data-status="low"]:hover {
  background: #fff5e3;
}
tr[data-status="low"] td.col-item {
  box-shadow: inset 3px 0 0 var(--warn);
}
tr[data-status="out"] {
  background: #fff4f1;
}
tr[data-status="out"]:hover {
  background: #ffece7;
}
tr[data-status="out"] td.col-item {
  box-shadow: inset 3px 0 0 var(--danger);
}

/* Item cell */
.item-name {
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.01em;
}
.item-sku {
  font-size: 0.76rem;
  color: var(--muted);
  margin-top: 2px;
  font-variant-numeric: tabular-nums;
}

.par-val,
.restock,
.supplier {
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
}
.col-par {
  font-weight: 600;
}
.restock-rel {
  display: block;
  font-size: 0.74rem;
  color: var(--muted);
  margin-top: 1px;
}
.supplier {
  font-size: 0.86rem;
}

/* Stepper */
.stepper {
  display: inline-flex;
  align-items: center;
  gap: 0;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  background: var(--white);
  overflow: hidden;
}
.step {
  border: none;
  background: transparent;
  width: 28px;
  height: 30px;
  font-size: 1.1rem;
  font-weight: 700;
  line-height: 1;
  color: var(--teal-d);
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background 0.12s, color 0.12s;
}
.step:hover {
  background: var(--teal-50);
}
.step:active {
  background: #d4ece9;
}
.step:disabled {
  color: var(--line-2);
  cursor: not-allowed;
  background: transparent;
}
.onhand-val {
  min-width: 30px;
  text-align: center;
  font-weight: 700;
  font-size: 0.95rem;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
  padding: 0 4px;
}
tr[data-status="out"] .onhand-val {
  color: var(--danger);
}

/* Status pill */
.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.74rem;
  font-weight: 700;
  padding: 4px 11px;
  border-radius: 999px;
  white-space: nowrap;
}
.pill::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}
.pill.ok {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}
.pill.low {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.pill.out {
  background: rgba(212, 80, 62, 0.14);
  color: var(--danger);
}

/* Reorder action */
.col-action {
  text-align: right;
  white-space: nowrap;
}
.reorder {
  border: 1px solid rgba(212, 80, 62, 0.4);
  background: var(--white);
  color: var(--danger);
  border-radius: 10px;
  padding: 7px 14px;
  font: inherit;
  font-weight: 600;
  font-size: 0.82rem;
  cursor: pointer;
  transition: transform 0.12s, background 0.15s, border-color 0.15s;
}
.reorder:hover {
  background: rgba(212, 80, 62, 0.08);
  border-color: var(--danger);
}
.reorder:active {
  transform: translateY(1px);
}
.reorder.is-low {
  border-color: rgba(217, 138, 43, 0.45);
  color: var(--warn);
}
.reorder.is-low:hover {
  background: rgba(217, 138, 43, 0.1);
  border-color: var(--warn);
}

/* Empty state */
.empty {
  padding: 40px 20px;
  text-align: center;
  color: var(--muted);
  font-size: 0.92rem;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}

/* ── Responsive ── */
@media (max-width: 760px) {
  .col-supplier,
  .col-restock {
    display: none;
  }
}

@media (max-width: 520px) {
  .inv {
    padding: 22px 14px 48px;
  }
  .inv-head {
    align-items: flex-start;
  }
  .summary {
    width: 100%;
  }
  .stat {
    flex: 1;
    min-width: 0;
    padding: 10px 12px;
  }
  .toolbar {
    flex-direction: column;
    align-items: stretch;
  }
  .tabs {
    justify-content: space-between;
  }
  .search {
    max-width: none;
  }
  .table-wrap {
    border-radius: var(--r-md);
  }
  .inv-table thead {
    display: none;
  }
  .inv-table,
  .inv-table tbody,
  .inv-table tr,
  .inv-table td {
    display: block;
    width: 100%;
  }
  .inv-table tbody tr {
    padding: 14px 16px;
    position: relative;
  }
  .inv-table td {
    padding: 4px 0;
  }
  .inv-table td.col-item {
    box-shadow: none !important;
    padding-right: 90px;
  }
  tr[data-status="low"],
  tr[data-status="out"] {
    border-left: 3px solid transparent;
  }
  tr[data-status="low"] {
    border-left-color: var(--warn);
  }
  tr[data-status="out"] {
    border-left-color: var(--danger);
  }
  .col-onhand {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-top: 8px;
  }
  .col-onhand::before {
    content: "On hand";
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--muted);
  }
  .col-par {
    text-align: left;
  }
  .col-par::before {
    content: "Par: ";
    font-weight: 600;
    color: var(--muted);
  }
  .col-status {
    margin-top: 6px;
  }
  .col-action {
    position: absolute;
    top: 14px;
    right: 16px;
    text-align: right;
  }
}

