// ── Inventory data ───────────────────────────────────────────────────────────
// Status is derived, never stored: out = 0, low = onHand <= par, else ok.
const ITEMS = [
  { name: "Nitrile exam gloves (M)", sku: "GLV-NTR-M", onHand: 42, par: 30, restock: "2026-05-28", supplier: "MedSupply Co." },
  { name: "Adhesive bandages, assorted", sku: "BND-ASRT", onHand: 8, par: 20, restock: "2026-04-19", supplier: "CareLine Health" },
  { name: "Isopropyl alcohol prep pads", sku: "PRP-ALC-70", onHand: 0, par: 25, restock: "2026-03-30", supplier: "MedSupply Co." },
  { name: "Sterile gauze 4×4 in", sku: "GZE-4X4-S", onHand: 60, par: 40, restock: "2026-06-02", supplier: "CareLine Health" },
  { name: "Disposable face masks", sku: "MSK-3PLY", onHand: 18, par: 50, restock: "2026-05-11", supplier: "Vireo Medical" },
  { name: "Tongue depressors, wood", sku: "TDP-WD-100", onHand: 120, par: 60, restock: "2026-05-22", supplier: "MedSupply Co." },
  { name: "Vinyl exam gloves (L)", sku: "GLV-VNL-L", onHand: 0, par: 30, restock: "2026-02-14", supplier: "Vireo Medical" },
  { name: "Syringes 3 mL, Luer-lock", sku: "SYR-3ML-LL", onHand: 22, par: 35, restock: "2026-05-30", supplier: "Northgate Pharma" },
  { name: "Examination table paper", sku: "PPR-EXM-RL", onHand: 14, par: 12, restock: "2026-06-04", supplier: "CareLine Health" },
  { name: "Surface disinfectant wipes", sku: "DIS-WIPE-XL", onHand: 9, par: 24, restock: "2026-04-27", supplier: "Vireo Medical" },
  { name: "Cotton-tipped applicators", sku: "APP-CTN-200", onHand: 75, par: 40, restock: "2026-05-18", supplier: "MedSupply Co." },
  { name: "Lancets, 28G safety", sku: "LNC-28G-SF", onHand: 33, par: 30, restock: "2026-06-01", supplier: "Northgate Pharma" },
];

let activeFilter = "all";
let query = "";

const rowsEl = document.getElementById("rows");
const emptyEl = document.getElementById("empty");
const searchEl = document.getElementById("search");
const toastEl = document.getElementById("toast");

// ── Helpers ──────────────────────────────────────────────────────────────────
function statusOf(item) {
  if (item.onHand <= 0) return "out";
  if (item.onHand <= item.par) return "low";
  return "ok";
}

const STATUS_LABEL = { ok: "OK", low: "Low", out: "Out" };

function showToast(msg) {
  toastEl.textContent = msg;
  toastEl.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toastEl.hidden = true), 2600);
}

function formatDate(iso) {
  const d = new Date(iso + "T00:00:00");
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

function relativeDays(iso) {
  const then = new Date(iso + "T00:00:00");
  const now = new Date("2026-06-08T00:00:00");
  const days = Math.round((now - then) / 86400000);
  if (days <= 0) return "today";
  if (days === 1) return "1 day ago";
  if (days < 30) return days + " days ago";
  const months = Math.round(days / 30);
  return months + (months === 1 ? " month ago" : " months ago");
}

// ── Render ───────────────────────────────────────────────────────────────────
function rowMarkup(item, idx) {
  const status = statusOf(item);
  const needsReorder = status !== "ok";
  const reorder = needsReorder
    ? `<button class="reorder${status === "low" ? " is-low" : ""}" data-reorder="${idx}">Reorder</button>`
    : "";
  return `
    <tr data-idx="${idx}" data-status="${status}">
      <td class="col-item">
        <div class="item-name">${item.name}</div>
        <div class="item-sku">${item.sku}</div>
      </td>
      <td class="col-onhand">
        <div class="stepper" role="group" aria-label="Adjust on-hand for ${item.name}">
          <button class="step" data-dec="${idx}" aria-label="Decrease on-hand"${item.onHand <= 0 ? " disabled" : ""}>−</button>
          <span class="onhand-val" aria-live="polite">${item.onHand}</span>
          <button class="step" data-inc="${idx}" aria-label="Increase on-hand">+</button>
        </div>
      </td>
      <td class="col-par"><span class="par-val">${item.par}</span></td>
      <td class="col-status">
        <span class="pill ${status}">${STATUS_LABEL[status]}</span>
      </td>
      <td class="col-restock">
        <span class="restock">${formatDate(item.restock)}</span>
        <span class="restock-rel">${relativeDays(item.restock)}</span>
      </td>
      <td class="col-supplier"><span class="supplier">${item.supplier}</span></td>
      <td class="col-action">${reorder}</td>
    </tr>`;
}

function matchesFilter(item) {
  if (activeFilter !== "all" && statusOf(item) !== activeFilter) return false;
  if (query) {
    const hay = (item.name + " " + item.sku).toLowerCase();
    if (!hay.includes(query)) return false;
  }
  return true;
}

function render() {
  const visible = ITEMS.map((item, idx) => ({ item, idx })).filter(({ item }) => matchesFilter(item));
  rowsEl.innerHTML = visible.map(({ item, idx }) => rowMarkup(item, idx)).join("");
  emptyEl.hidden = visible.length > 0;
}

// ── Counts & summary ─────────────────────────────────────────────────────────
function refreshCounts() {
  let low = 0;
  let out = 0;
  ITEMS.forEach((item) => {
    const s = statusOf(item);
    if (s === "low") low++;
    else if (s === "out") out++;
  });
  document.getElementById("stat-total").textContent = ITEMS.length;
  document.getElementById("stat-low").textContent = low;
  document.getElementById("stat-out").textContent = out;
  document.getElementById("count-all").textContent = ITEMS.length;
  document.getElementById("count-low").textContent = low;
  document.getElementById("count-out").textContent = out;
}

// ── Stepper: update a single row in place when possible ──────────────────────
function adjust(idx, delta) {
  const item = ITEMS[idx];
  const next = Math.max(0, item.onHand + delta);
  if (next === item.onHand) return;
  item.onHand = next;
  refreshCounts();

  // If the row would leave the current filter, re-render the whole list.
  if (!matchesFilter(item)) {
    render();
    return;
  }
  const row = rowsEl.querySelector(`tr[data-idx="${idx}"]`);
  if (!row) {
    render();
    return;
  }
  const status = statusOf(item);
  row.dataset.status = status;
  row.querySelector(".onhand-val").textContent = item.onHand;
  const pill = row.querySelector(".pill");
  pill.className = "pill " + status;
  pill.textContent = STATUS_LABEL[status];
  row.querySelector(".step[data-dec]").disabled = item.onHand <= 0;

  const actionCell = row.querySelector(".col-action");
  if (status === "ok") {
    actionCell.innerHTML = "";
  } else {
    actionCell.innerHTML = `<button class="reorder${status === "low" ? " is-low" : ""}" data-reorder="${idx}">Reorder</button>`;
  }
}

// ── Events ───────────────────────────────────────────────────────────────────
rowsEl.addEventListener("click", (e) => {
  const dec = e.target.closest("[data-dec]");
  const inc = e.target.closest("[data-inc]");
  const reorder = e.target.closest("[data-reorder]");
  if (dec) adjust(Number(dec.dataset.dec), -1);
  else if (inc) adjust(Number(inc.dataset.inc), +1);
  else if (reorder) {
    const item = ITEMS[Number(reorder.dataset.reorder)];
    const status = statusOf(item);
    const shortfall = Math.max(item.par - item.onHand, item.par);
    showToast(
      status === "out"
        ? `Reorder raised for ${item.name} — purchase order sent to ${item.supplier}.`
        : `Reorder raised for ${item.name} (suggested ${shortfall} units) — sent to ${item.supplier}.`
    );
  }
});

document.querySelectorAll(".tab").forEach((tab) => {
  tab.addEventListener("click", () => {
    activeFilter = tab.dataset.filter;
    document.querySelectorAll(".tab").forEach((t) => {
      const on = t === tab;
      t.classList.toggle("is-active", on);
      t.setAttribute("aria-selected", String(on));
    });
    render();
  });
});

searchEl.addEventListener("input", () => {
  query = searchEl.value.trim().toLowerCase();
  render();
});

// ── Init ─────────────────────────────────────────────────────────────────────
refreshCounts();
render();

snippets.css:
:root {
  --cream: #f4efe4;
  --paper: #faf7f0;
  --white: #ffffff;
  --newsprint: #efe9da;
  --ink: #16130f;
  --ink-2: #2b2620;
  --ink-3: #4a443b;
  --muted: #7a7164;
  --red: #b4291f;
  --red-d: #8f1f17;
  --red-50: #f3dcd9;
  --rule: rgba(22, 19, 15, 0.16);
  --rule-2: rgba(22, 19, 15, 0.30);
  --rule-hair: rgba(22, 19, 15, 0.10);
  --ok: #2f7d4f;
  --warn: #b67a18;
  --danger: #b4291f;
  --r-sm: 4px;
  --r-md: 8px;
  --r-lg: 12px;
  --serif: "Playfair Display", "Times New Roman", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  background: var(--cream);
  color: var(--ink);
  font-family: var(--sans);
  line-height: 1.5;
  font-size: 17px;
}

a {
  color: inherit;
}

.skip-link {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--ink);
  color: var(--cream);
  padding: 10px 16px;
  z-index: 50;
  font: 600 13px/1 var(--sans);
}
.skip-link:focus {
  left: 12px;
  top: 12px;
}

.sr-only,
.sr-only:not(:focus):not(:active) {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

:focus-visible {
  outline: 2px solid var(--red);
  outline-offset: 2px;
}

/* ---------- Masthead ---------- */
.masthead {
  background: var(--paper);
  border-bottom: 3px double var(--rule-2);
}
.masthead__inner {
  max-width: 1180px;
  margin: 0 auto;
  padding: 22px 24px 14px;
  text-align: center;
}
.masthead__dateline {
  margin: 0 0 8px;
  font: 600 11px/1.4 var(--sans);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.masthead__title {
  margin: 0;
  font-family: var(--serif);
  font-weight: 900;
  font-size: clamp(34px, 7vw, 64px);
  line-height: 1;
  letter-spacing: 0.01em;
  color: var(--ink);
}
.masthead__tag {
  margin: 10px 0 0;
  font: italic 500 14px/1.4 var(--serif);
  color: var(--ink-3);
}

.subnav {
  border-top: 1px solid var(--rule);
  background: var(--paper);
}
.subnav ul {
  max-width: 1180px;
  margin: 0 auto;
  padding: 0 24px;
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 4px 26px;
  justify-content: center;
  align-items: center;
}
.subnav li {
  padding: 9px 0;
}
.subnav a {
  text-decoration: none;
  font: 600 12px/1 var(--sans);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-2);
  padding-bottom: 3px;
  border-bottom: 2px solid transparent;
  transition: color 0.15s, border-color 0.15s;
}
.subnav a:hover {
  color: var(--red);
  border-color: var(--red);
}
.subnav__cta a {
  color: var(--red);
}

/* ---------- Layout ---------- */
.wrap {
  max-width: 1180px;
  margin: 0 auto;
  padding: 40px 24px 56px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 56px;
  align-items: start;
}

/* ---------- Column head ---------- */
.column {
  max-width: 680px;
  margin: 0 auto;
}
.kicker {
  margin: 0 0 14px;
  font: 700 12px/1 var(--sans);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--red);
}
.headline {
  margin: 0;
  font-family: var(--serif);
  font-weight: 800;
  font-size: clamp(32px, 5.4vw, 52px);
  line-height: 1.06;
  letter-spacing: -0.005em;
  color: var(--ink);
}
.deck {
  margin: 18px 0 0;
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: clamp(18px, 2.4vw, 22px);
  line-height: 1.45;
  color: var(--ink-3);
}

/* ---------- Byline card ---------- */
.byline {
  margin: 26px 0 20px;
  display: flex;
  gap: 16px;
  align-items: flex-start;
  padding: 16px;
  background: var(--paper);
  border: 1px solid var(--rule);
  border-radius: var(--r-md);
}
.byline__portrait {
  flex: 0 0 64px;
  width: 64px;
  height: 64px;
  margin: 0;
  border-radius: var(--r-sm);
  display: grid;
  place-items: center;
  overflow: hidden;
  background:
    radial-gradient(120% 100% at 30% 18%, rgba(244, 239, 228, 0.55), transparent 55%),
    radial-gradient(140% 120% at 78% 86%, var(--red-d), transparent 60%),
    linear-gradient(150deg, #3a322a 0%, #1d1813 60%, #120f0b 100%);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.3);
}
.byline__initials {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 24px;
  color: var(--cream);
  letter-spacing: 0.02em;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
}
.byline__meta {
  min-width: 0;
}
.byline__name {
  margin: 0;
  font: 700 16px/1.2 var(--sans);
  color: var(--ink);
}
.byline__title {
  margin: 3px 0 0;
  font: 600 12px/1.3 var(--sans);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--red-d);
}
.byline__bio {
  margin: 8px 0 0;
  font: 400 13.5px/1.5 var(--sans);
  color: var(--ink-3);
}

.column__meta {
  margin: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  font: 500 13px/1.4 var(--sans);
  color: var(--muted);
}
.column__meta-updated {
  color: var(--red-d);
  font-weight: 600;
}

.rule {
  border: 0;
  border-top: 1px solid var(--rule);
  margin: 24px 0;
}

/* ---------- Body ---------- */
.column__body {
  font-size: 18px;
  line-height: 1.72;
  color: var(--ink-2);
  text-align: justify;
  hyphens: auto;
}
.column__body p {
  margin: 0 0 1.25em;
}
.column__body strong {
  color: var(--ink);
}
.column__body em {
  font-style: italic;
}
.lead::first-letter {
  float: left;
  font-family: var(--serif);
  font-weight: 800;
  font-size: 4.4em;
  line-height: 0.74;
  padding: 6px 12px 0 0;
  color: var(--red);
}
.lead {
  text-align: left;
}

/* ---------- Figures / press photos ---------- */
.figure {
  margin: 28px 0;
}
.figure--inset {
  float: right;
  width: 46%;
  margin: 8px 0 18px 28px;
}
.figure figcaption {
  margin-top: 8px;
  font: italic 500 13px/1.45 var(--serif);
  color: var(--ink-3);
  text-align: left;
}
.figure .credit {
  display: block;
  margin-top: 3px;
  font: 600 10.5px/1.3 var(--sans);
  font-style: normal;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}
.press-photo {
  width: 100%;
  border-radius: var(--r-sm);
  box-shadow: inset 0 0 0 1px var(--rule-2), inset 0 -40px 60px -30px rgba(0, 0, 0, 0.4);
  position: relative;
}
.press-photo::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background-image: radial-gradient(rgba(22, 19, 15, 0.16) 1px, transparent 1.4px);
  background-size: 4px 4px;
  mix-blend-mode: multiply;
  opacity: 0.5;
  pointer-events: none;
}
.press-photo--street {
  aspect-ratio: 16 / 9;
  background:
    radial-gradient(80% 60% at 50% 12%, rgba(244, 220, 200, 0.5), transparent 60%),
    linear-gradient(180deg, #5a4634 0%, #6b5340 22%, #2c2620 60%, #14110d 100%),
    linear-gradient(95deg, rgba(180, 41, 31, 0.18), transparent 40%);
}
.press-photo--portrait {
  aspect-ratio: 4 / 5;
  background:
    radial-gradient(70% 55% at 42% 28%, rgba(243, 220, 217, 0.55), transparent 55%),
    radial-gradient(120% 120% at 80% 100%, var(--red-d), transparent 58%),
    linear-gradient(160deg, #463a2e 0%, #241d17 55%, #110e0a 100%);
}

/* ---------- Pull quotes ---------- */
.pullquote {
  margin: 30px 0;
  padding: 0 0 0 22px;
  border-left: 3px solid var(--red);
  font-family: var(--serif);
  font-weight: 600;
  font-style: italic;
  font-size: clamp(22px, 3.4vw, 30px);
  line-height: 1.28;
  color: var(--ink);
  text-align: left;
}
.pullquote--right {
  border-left: 0;
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
  padding: 22px 0;
  text-align: center;
  color: var(--red-d);
}

/* ---------- Reactions ---------- */
.reactions {
  margin: 30px 0 4px;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
}
.clap,
.share {
  font: 600 14px/1 var(--sans);
  cursor: pointer;
  border-radius: var(--r-sm);
  transition: transform 0.12s, background 0.15s, color 0.15s, border-color 0.15s;
}
.clap {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 11px 18px;
  background: var(--ink);
  color: var(--cream);
  border: 1px solid var(--ink);
}
.clap:hover {
  background: var(--red-d);
  border-color: var(--red-d);
}
.clap:active {
  transform: scale(0.96);
}
.clap.is-clapped {
  background: var(--red);
  border-color: var(--red);
}
.clap__icon {
  font-size: 17px;
}
.clap__count {
  padding-left: 10px;
  margin-left: 2px;
  border-left: 1px solid rgba(244, 239, 228, 0.3);
  font-variant-numeric: tabular-nums;
}
.clap.is-bumped {
  animation: bump 0.3s ease;
}
@keyframes bump {
  40% { transform: scale(1.06); }
}
.share {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 11px 16px;
  background: var(--paper);
  color: var(--ink-2);
  border: 1px solid var(--rule-2);
}
.share:hover {
  border-color: var(--ink);
  color: var(--ink);
}
.share:active {
  transform: scale(0.96);
}
.share--ghost {
  background: transparent;
}

/* ---------- Editor's note ---------- */
.editors-note {
  background: var(--newsprint);
  border: 1px solid var(--rule);
  border-radius: var(--r-md);
  padding: 18px 20px;
}
.editors-note__label {
  margin: 0 0 8px;
  font: 700 11px/1 var(--sans);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--red);
}
.editors-note__body {
  margin: 0;
  font: italic 500 14.5px/1.6 var(--serif);
  color: var(--ink-3);
}

/* ---------- Sidebar: more ---------- */
.more {
  position: sticky;
  top: 24px;
}
.more__title {
  margin: 0 0 4px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--ink);
  font-family: var(--serif);
  font-weight: 700;
  font-size: 21px;
  line-height: 1.15;
  color: var(--ink);
}
.more__list {
  margin: 0;
  padding: 0;
  list-style: none;
  counter-reset: more;
}
.more__list li {
  border-bottom: 1px solid var(--rule-hair);
}
.more__list a {
  display: grid;
  gap: 4px;
  padding: 14px 0;
  text-decoration: none;
  position: relative;
}
.more__list a:hover .more__hl {
  color: var(--red-d);
}
.more__kicker {
  font: 700 10.5px/1 var(--sans);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--red);
}
.more__hl {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 17px;
  line-height: 1.22;
  color: var(--ink);
  transition: color 0.15s;
}
.more__date {
  font: 500 12px/1 var(--sans);
  color: var(--muted);
}

/* ---------- Newsletter ---------- */
.newsletter {
  margin-top: 26px;
  padding: 20px;
  background: var(--ink);
  color: var(--cream);
  border-radius: var(--r-md);
}
.newsletter__title {
  margin: 0;
  font-family: var(--serif);
  font-weight: 700;
  font-size: 19px;
  line-height: 1.2;
}
.newsletter__sub {
  margin: 6px 0 14px;
  font: 400 13px/1.45 var(--sans);
  color: rgba(244, 239, 228, 0.7);
}
.newsletter__form {
  display: flex;
  gap: 8px;
}
.newsletter__form input {
  flex: 1;
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid rgba(244, 239, 228, 0.25);
  border-radius: var(--r-sm);
  background: rgba(244, 239, 228, 0.06);
  color: var(--cream);
  font: 500 14px/1 var(--sans);
}
.newsletter__form input::placeholder {
  color: rgba(244, 239, 228, 0.45);
}
.newsletter__form input:focus-visible {
  outline-color: var(--red);
  border-color: var(--red);
}
.newsletter__form button {
  padding: 10px 16px;
  border: 0;
  border-radius: var(--r-sm);
  background: var(--red);
  color: var(--white);
  font: 600 14px/1 var(--sans);
  cursor: pointer;
  transition: background 0.15s;
}
.newsletter__form button:hover {
  background: var(--red-d);
}

/* ---------- Page foot ---------- */
.page-foot {
  border-top: 1px solid var(--rule);
  background: var(--paper);
  text-align: center;
}
.page-foot p {
  max-width: 1180px;
  margin: 0 auto;
  padding: 20px 24px;
  font: 500 12px/1.5 var(--sans);
  letter-spacing: 0.03em;
  color: var(--muted);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 24px);
  background: var(--ink);
  color: var(--cream);
  padding: 12px 20px;
  border-radius: var(--r-sm);
  font: 600 14px/1 var(--sans);
  box-shadow: 0 8px 24px -8px rgba(0, 0, 0, 0.5);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
  z-index: 60;
  max-width: calc(100vw - 32px);
}
.toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Responsive ---------- */
@media (max-width: 960px) {
  .wrap {
    grid-template-columns: minmax(0, 1fr);
    gap: 44px;
  }
  .column {
    max-width: 720px;
  }
  .more {
    position: static;
    max-width: 720px;
    margin: 0 auto;
    width: 100%;
  }
}

@media (max-width: 720px) {
  body {
    font-size: 16px;
  }
  .column__body {
    font-size: 17px;
    text-align: left;
    hyphens: manual;
  }
  .figure--inset {
    float: none;
    width: 100%;
    margin: 24px 0;
  }
  .byline {
    flex-direction: column;
  }
}

@media (max-width: 400px) {
  .masthead__inner {
    padding: 16px 16px 12px;
  }
  .wrap {
    padding: 28px 16px 40px;
  }
  .newsletter__form {
    flex-direction: column;
  }
  .lead::first-letter {
    font-size: 3.8em;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

