:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --sh-1: 0 1px 0 rgba(255, 255, 255, 0.04) inset, 0 6px 18px rgba(0, 0, 0, 0.4);
  --sh-2: 0 12px 40px rgba(0, 0, 0, 0.55);
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(1100px 520px at 88% -8%, rgba(198, 255, 58, 0.07), transparent 60%),
    radial-gradient(800px 460px at -6% 4%, rgba(255, 106, 43, 0.06), transparent 58%),
    var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.wrap {
  max-width: 1080px;
  margin: 0 auto;
  padding: 40px 24px 64px;
}

/* ── Hero ── */
.hero-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.eyebrow {
  margin: 0;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--neon);
}

.eyebrow.sm {
  font-size: 10px;
  color: var(--muted);
}

.streak {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 13px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
  font-size: 13px;
  color: var(--ink-2);
}

.streak strong {
  color: var(--ink);
}

.flame {
  font-size: 14px;
}

.hero h1 {
  margin: 12px 0 6px;
  font-size: clamp(30px, 6vw, 46px);
  font-weight: 900;
  letter-spacing: -0.025em;
  line-height: 1.02;
}

.sub {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  font-weight: 500;
}

.tier {
  color: var(--neon);
  font-weight: 700;
}

/* ── Tabs ── */
.tabs {
  display: inline-flex;
  gap: 4px;
  margin: 26px 0 22px;
  padding: 5px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
}

.tab {
  appearance: none;
  border: 0;
  cursor: pointer;
  padding: 9px 20px;
  border-radius: 999px;
  background: transparent;
  color: var(--ink-2);
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.01em;
  transition: color 0.18s, background 0.18s, transform 0.1s;
}

.tab:hover {
  color: var(--ink);
}

.tab.is-active {
  background: var(--neon);
  color: #0d0f12;
}

.tab:active {
  transform: translateY(1px);
}

/* ── Stat cards ── */
.stat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  margin-bottom: 18px;
}

.stat-card {
  padding: 18px 18px 16px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: linear-gradient(180deg, var(--surface-2), var(--surface));
  box-shadow: var(--sh-1);
}

.stat-label {
  margin: 0 0 8px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.stat-value {
  margin: 0 0 8px;
  font-size: 27px;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.stat-value .unit {
  font-size: 14px;
  font-weight: 600;
  color: var(--muted);
}

.delta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  font-size: 12.5px;
  font-weight: 700;
}

.delta .arrow {
  font-size: 10px;
}

.delta.up {
  color: var(--ok);
}

.delta.down {
  color: var(--orange);
}

.delta.flat {
  color: var(--muted);
}

/* ── Panels ── */
.panels {
  display: grid;
  grid-template-columns: 1.55fr 1fr;
  gap: 16px;
}

.panel {
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  background: var(--surface);
  box-shadow: var(--sh-2);
  padding: 20px;
}

.panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 16px;
}

.panel-head h2 {
  margin: 4px 0 0;
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.01em;
}

/* ── Range toggle ── */
.range {
  display: inline-flex;
  gap: 3px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-2);
}

.range-btn {
  appearance: none;
  border: 0;
  cursor: pointer;
  padding: 6px 12px;
  border-radius: 999px;
  background: transparent;
  color: var(--ink-2);
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  transition: background 0.16s, color 0.16s;
}

.range-btn:hover {
  color: var(--ink);
}

.range-btn.is-active {
  background: var(--elevated);
  color: var(--neon);
}

/* ── Chart ── */
.chart-stage {
  position: relative;
}

.chart {
  width: 100%;
  height: auto;
  display: block;
  overflow: visible;
}

.chart .grid-line {
  stroke: var(--line);
  stroke-width: 1;
}

.chart .axis-label {
  fill: var(--muted);
  font-size: 11px;
  font-weight: 600;
  font-family: inherit;
}

.chart .area {
  fill: url(#areaGrad);
  opacity: 0;
  animation: rise 0.5s ease forwards;
}

.chart .line {
  fill: none;
  stroke: var(--neon);
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.chart .target-line {
  fill: none;
  stroke: var(--orange);
  stroke-width: 1.5;
  stroke-dasharray: 5 5;
  opacity: 0.8;
}

.chart .pt {
  fill: var(--bg);
  stroke: var(--neon);
  stroke-width: 2.5;
  cursor: pointer;
  transition: r 0.12s ease;
}

.chart .pt:hover,
.chart .pt.is-hot {
  fill: var(--neon);
  r: 6;
}

.chart .hit {
  fill: transparent;
  cursor: pointer;
}

.chart .bar {
  fill: var(--neon-50);
  stroke: var(--neon);
  stroke-width: 1.5;
  cursor: pointer;
  transition: fill 0.14s ease;
  transform-box: fill-box;
  transform-origin: bottom;
  animation: grow 0.45s cubic-bezier(0.2, 0.7, 0.2, 1) forwards;
}

.chart .bar:hover,
.chart .bar.is-hot {
  fill: var(--neon);
}

@keyframes rise {
  to {
    opacity: 1;
  }
}

@keyframes grow {
  from {
    transform: scaleY(0);
  }
  to {
    transform: scaleY(1);
  }
}

.tooltip {
  position: absolute;
  pointer-events: none;
  z-index: 4;
  min-width: 96px;
  padding: 8px 11px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  background: var(--elevated);
  box-shadow: var(--sh-2);
  font-size: 12px;
  color: var(--ink);
  opacity: 0;
  transform: translate(-50%, -8px);
  transition: opacity 0.12s ease;
}

.tooltip.show {
  opacity: 1;
}

.tooltip .tt-label {
  display: block;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 2px;
}

.tooltip .tt-val {
  font-weight: 800;
  font-size: 14px;
}

.tooltip .tt-val b {
  color: var(--neon);
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  margin-top: 14px;
  font-size: 12px;
  color: var(--ink-2);
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.dot.neon {
  background: var(--neon);
}

.dot.orange {
  background: var(--orange);
}

/* ── PR list ── */
.pr-count {
  font-size: 12px;
  font-weight: 700;
  color: var(--muted);
  padding: 5px 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  white-space: nowrap;
}

.pr-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}

.pr-item {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 13px 14px;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--surface-2);
  transition: border-color 0.16s, transform 0.12s, background 0.16s;
}

.pr-item:hover {
  border-color: var(--line-2);
  background: var(--elevated);
  transform: translateY(-1px);
}

.pr-main {
  min-width: 0;
}

.pr-name {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
}

.pr-name .ico {
  font-size: 15px;
}

.pr-date {
  margin-top: 3px;
  font-size: 11.5px;
  color: var(--muted);
  font-weight: 500;
}

.pr-right {
  text-align: right;
}

.pr-val {
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.01em;
}

.pr-val .u {
  font-size: 11px;
  font-weight: 600;
  color: var(--muted);
}

.pr-trend {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 3px;
  font-size: 11.5px;
  font-weight: 700;
}

.pr-trend.up {
  color: var(--ok);
}

.pr-trend.down {
  color: var(--danger);
}

.pr-trend.flat {
  color: var(--muted);
}

/* ── Toast ── */
.toast-host {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  display: grid;
  gap: 8px;
  z-index: 50;
  pointer-events: none;
}

.toast {
  padding: 11px 16px;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  background: var(--elevated);
  color: var(--ink);
  font-size: 13px;
  font-weight: 600;
  box-shadow: var(--sh-2);
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 0.2s, transform 0.2s;
}

.toast.in {
  opacity: 1;
  transform: translateY(0);
}

.toast .tk {
  color: var(--neon);
  font-weight: 800;
}

/* ── Focus ── */
:focus-visible {
  outline: 2px solid var(--neon);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ── Responsive ── */
@media (max-width: 860px) {
  .panels {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .wrap {
    padding: 28px 16px 48px;
  }

  .hero-top {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
  }

  .stat-grid {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .stat-value {
    font-size: 24px;
  }

  .tabs {
    display: flex;
    width: 100%;
  }

  .tab {
    flex: 1;
    padding: 9px 10px;
    text-align: center;
  }

  .panel {
    padding: 16px;
  }

  .panel-head {
    flex-direction: column;
  }

  .legend {
    gap: 14px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .chart .area,
  .chart .bar,
  .toast,
  .pr-item,
  .tab {
    animation: none !important;
    transition: none !important;
  }
}

