/* Gym — Progress Stats. Vanilla JS, no libraries. Self-drawn SVG charts. */
(function () {
  "use strict";

  var NS = "http://www.w3.org/2000/svg";

  /* ── Toast helper ── */
  var toastHost = document.querySelector(".toast-host");
  function toast(msg) {
    var el = document.createElement("div");
    el.className = "toast";
    el.innerHTML = msg;
    toastHost.appendChild(el);
    requestAnimationFrame(function () {
      el.classList.add("in");
    });
    setTimeout(function () {
      el.classList.remove("in");
      setTimeout(function () {
        el.remove();
      }, 250);
    }, 2200);
  }

  /* ── Data: per-metric series + PRs ──
     Each metric carries series for 4w / 12w / 52w plus a chart "kind". */
  function seed(rangeKey, base, drift, jitter, count) {
    var pts = [];
    var rng = mulberry(rangeKey * 9301 + count * 49297);
    var v = base;
    for (var i = 0; i < count; i++) {
      v += drift + (rng() - 0.5) * jitter;
      pts.push(Math.round(v * 10) / 10);
    }
    return pts;
  }
  function mulberry(a) {
    return function () {
      a |= 0;
      a = (a + 0x6d2b79f5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function labelsFor(range) {
    if (range === 4) return ["W1", "W2", "W3", "W4"];
    if (range === 12) return ["W1", "W3", "W5", "W7", "W9", "W11", "W12"];
    return ["Jan", "Mar", "May", "Jul", "Sep", "Nov", "Now"];
  }
  function countFor(range) {
    return range === 4 ? 4 : range === 12 ? 7 : 7;
  }

  var METRICS = {
    strength: {
      eyebrow: "Total volume",
      title: "Weekly training volume",
      legend: "Volume (kg)",
      kind: "bar",
      unit: "kg",
      series: {
        4: seed(11, 13800, 220, 1400, 4),
        12: seed(12, 12200, 520, 2200, 7),
        52: seed(15, 9800, 1100, 3200, 7),
      },
      target: { 4: 14500, 12: 14500, 52: 14500 },
    },
    cardio: {
      eyebrow: "5k pace",
      title: "Average running pace",
      legend: "Pace (sec/km)",
      kind: "line",
      unit: "s/km",
      series: {
        4: seed(21, 312, -2.2, 6, 4),
        12: seed(22, 326, -2.6, 8, 7),
        52: seed(25, 358, -4.4, 12, 7),
      },
      target: { 4: 300, 12: 300, 52: 300 },
    },
    body: {
      eyebrow: "Bodyweight trend",
      title: "Where you're heading",
      legend: "Bodyweight (kg)",
      kind: "line",
      unit: "kg",
      series: {
        4: seed(31, 82.4, -0.32, 0.5, 4),
        12: seed(32, 83.6, -0.36, 0.7, 7),
        52: seed(35, 88.5, -0.7, 1.1, 7),
      },
      target: { 4: 79.5, 12: 79.5, 52: 79.5 },
    },
  };

  var PRS = {
    strength: [
      { ico: "🏋️", name: "Back Squat", val: 182.5, u: "kg", date: "May 28", trend: "up", d: "+5.0 kg" },
      { ico: "💪", name: "Bench Press", val: 122.5, u: "kg", date: "Jun 02", trend: "up", d: "+2.5 kg" },
      { ico: "🪨", name: "Deadlift", val: 215.0, u: "kg", date: "May 14", trend: "flat", d: "matched" },
      { ico: "🤸", name: "Overhead Press", val: 72.5, u: "kg", date: "Apr 30", trend: "up", d: "+2.5 kg" },
    ],
    cardio: [
      { ico: "🏃", name: "5k Run", val: "22:48", u: "", date: "Jun 01", trend: "up", d: "-41 s" },
      { ico: "🚴", name: "10k Bike", val: "16:12", u: "", date: "May 22", trend: "up", d: "-22 s" },
      { ico: "🛶", name: "2k Row", val: "7:38", u: "", date: "May 09", trend: "down", d: "+6 s" },
      { ico: "🧗", name: "Plank Hold", val: "4:05", u: "", date: "Apr 27", trend: "up", d: "+18 s" },
    ],
    body: [
      { ico: "⚖️", name: "Bodyweight", val: 81.2, u: "kg", date: "Jun 08", trend: "down", d: "-2.1 kg" },
      { ico: "📏", name: "Body fat", val: "14.6", u: "%", date: "Jun 06", trend: "down", d: "-1.4 %" },
      { ico: "💪", name: "Arm girth", val: 39.4, u: "cm", date: "May 31", trend: "up", d: "+0.6 cm" },
      { ico: "🫀", name: "Resting HR", val: 54, u: "bpm", date: "Jun 04", trend: "down", d: "-3 bpm" },
    ],
  };

  /* ── State ── */
  var state = { metric: "strength", range: 12 };

  /* ── Chart geometry ── */
  var W = 720;
  var H = 320;
  var PAD = { l: 44, r: 16, t: 18, b: 30 };
  var IW = W - PAD.l - PAD.r;
  var IH = H - PAD.t - PAD.b;

  var svg = document.querySelector(".chart");
  var tooltip = document.querySelector(".tooltip");

  function el(tag, attrs) {
    var e = document.createElementNS(NS, tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    return e;
  }

  function niceBounds(vals, target) {
    var all = vals.concat([target]);
    var min = Math.min.apply(null, all);
    var max = Math.max.apply(null, all);
    var span = max - min || 1;
    return { min: min - span * 0.15, max: max + span * 0.15 };
  }

  function fmt(v, metric) {
    if (metric === "cardio") {
      var m = Math.floor(v / 60);
      var s = Math.round(v % 60);
      return m + ":" + (s < 10 ? "0" + s : s);
    }
    return Number.isInteger(v) ? String(v) : v.toFixed(1);
  }

  function drawChart() {
    var m = METRICS[state.metric];
    var data = m.series[state.range];
    var labels = labelsFor(state.range);
    var target = m.target[state.range];
    var b = niceBounds(data, target);

    while (svg.firstChild) svg.removeChild(svg.firstChild);

    // defs gradient
    var defs = el("defs", {});
    var grad = el("linearGradient", { id: "areaGrad", x1: "0", y1: "0", x2: "0", y2: "1" });
    grad.appendChild(el("stop", { offset: "0%", "stop-color": "#c6ff3a", "stop-opacity": "0.28" }));
    grad.appendChild(el("stop", { offset: "100%", "stop-color": "#c6ff3a", "stop-opacity": "0" }));
    defs.appendChild(grad);
    svg.appendChild(defs);

    var x = function (i) {
      return PAD.l + (data.length === 1 ? IW / 2 : (i / (data.length - 1)) * IW);
    };
    var y = function (v) {
      return PAD.t + IH - ((v - b.min) / (b.max - b.min)) * IH;
    };

    // grid + y labels (4 rows)
    for (var g = 0; g <= 4; g++) {
      var gv = b.min + ((b.max - b.min) * g) / 4;
      var gy = y(gv);
      svg.appendChild(el("line", { class: "grid-line", x1: PAD.l, y1: gy, x2: W - PAD.r, y2: gy }));
      var yl = el("text", { class: "axis-label", x: PAD.l - 8, y: gy + 4, "text-anchor": "end" });
      yl.textContent = fmt(gv, state.metric);
      svg.appendChild(yl);
    }

    // x labels
    var step = data.length / labels.length;
    for (var li = 0; li < labels.length; li++) {
      var xi = Math.min(data.length - 1, Math.round(li * step));
      var xt = el("text", { class: "axis-label", x: x(xi), y: H - 8, "text-anchor": "middle" });
      xt.textContent = labels[li];
      svg.appendChild(xt);
    }

    // target line
    var ty = y(target);
    svg.appendChild(el("line", { class: "target-line", x1: PAD.l, y1: ty, x2: W - PAD.r, y2: ty }));

    if (m.kind === "line") {
      drawLine(data, x, y, m);
    } else {
      drawBars(data, x, y, m, b);
    }
  }

  function drawLine(data, x, y, m) {
    var d = "";
    var area = "M" + x(0) + " " + (PAD.t + IH);
    data.forEach(function (v, i) {
      d += (i === 0 ? "M" : "L") + x(i) + " " + y(v) + " ";
      area += "L" + x(i) + " " + y(v) + " ";
    });
    area += "L" + x(data.length - 1) + " " + (PAD.t + IH) + " Z";

    svg.appendChild(el("path", { class: "area", d: area }));
    svg.appendChild(el("path", { class: "line", d: d.trim() }));

    data.forEach(function (v, i) {
      var cx = x(i);
      var cy = y(v);
      var pt = el("circle", { class: "pt", cx: cx, cy: cy, r: 4, "data-i": i });
      var hit = el("circle", { class: "hit", cx: cx, cy: cy, r: 18, "data-i": i, tabindex: "0" });
      svg.appendChild(pt);
      svg.appendChild(hit);
      bindPoint(hit, pt, v, m, cx, cy);
    });
  }

  function drawBars(data, x, y, m, b) {
    var bw = (IW / data.length) * 0.6;
    data.forEach(function (v, i) {
      var cx = x(i);
      var top = y(v);
      var bottom = PAD.t + IH;
      var bar = el("rect", {
        class: "bar",
        x: cx - bw / 2,
        y: top,
        width: bw,
        height: Math.max(2, bottom - top),
        rx: 4,
        "data-i": i,
        tabindex: "0",
      });
      bar.style.animationDelay = i * 45 + "ms";
      svg.appendChild(bar);
      bindPoint(bar, bar, v, m, cx, top);
    });
  }

  function bindPoint(hit, visual, v, m, cx, cy) {
    function show() {
      visual.classList.add("is-hot");
      var rect = svg.getBoundingClientRect();
      var stage = svg.parentElement.getBoundingClientRect();
      var px = ((cx / W) * rect.width) + (rect.left - stage.left);
      var py = ((cy / H) * rect.height) + (rect.top - stage.top);
      tooltip.style.left = px + "px";
      tooltip.style.top = py + "px";
      tooltip.innerHTML =
        '<span class="tt-label">' + m.legend + "</span>" +
        '<span class="tt-val"><b>' + fmt(v, state.metric) + "</b> " + m.unit + "</span>";
      tooltip.classList.add("show");
    }
    function hide() {
      visual.classList.remove("is-hot");
      tooltip.classList.remove("show");
    }
    hit.addEventListener("mouseenter", show);
    hit.addEventListener("mouseleave", hide);
    hit.addEventListener("focus", show);
    hit.addEventListener("blur", hide);
  }

  /* ── PR list ── */
  var prList = document.querySelector("[data-pr-list]");
  var prCount = document.querySelector("[data-pr-count]");
  var prTitle = document.querySelector("[data-pr-title]");
  var arrows = { up: "▲", down: "▼", flat: "■" };

  function renderPRs() {
    var rows = PRS[state.metric];
    prList.innerHTML = "";
    rows.forEach(function (r) {
      var li = document.createElement("li");
      li.className = "pr-item";
      li.tabIndex = 0;
      li.innerHTML =
        '<div class="pr-main">' +
          '<div class="pr-name"><span class="ico">' + r.ico + "</span>" + r.name + "</div>" +
          '<div class="pr-date">' + r.date + "</div>" +
        "</div>" +
        '<div class="pr-right">' +
          '<div class="pr-val">' + r.val + (r.u ? ' <span class="u">' + r.u + "</span>" : "") + "</div>" +
          '<div class="pr-trend ' + r.trend + '">' + arrows[r.trend] + " " + r.d + "</div>" +
        "</div>";
      li.addEventListener("click", function () {
        toast('<span class="tk">' + r.name + "</span> · " + r.val + (r.u ? " " + r.u : "") + " on " + r.date);
      });
      li.addEventListener("keydown", function (e) {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          li.click();
        }
      });
      prList.appendChild(li);
    });
    prCount.textContent = rows.length + " " + (state.metric === "body" ? "metrics" : "lifts");
    prTitle.textContent = state.metric === "body" ? "Body measurements" : state.metric === "cardio" ? "Cardio bests" : "Current PRs";
  }

  /* ── Summary stat cards (refresh per metric) ── */
  function refreshSummary() {
    var m = METRICS[state.metric];
    var data = m.series[12];
    var first = data[0];
    var last = data[data.length - 1];
    var diff = last - first;
    var pct = ((diff / first) * 100).toFixed(1);

    setVal("[data-stat=volume]", fmt(last, state.metric) + ' <span class="unit">' + m.unit + "</span>");
    var betterUp = state.metric === "strength";
    var cls = diff === 0 ? "flat" : (diff > 0) === betterUp ? "up" : "down";
    setDelta("[data-stat=volumeDelta]", cls, Math.abs(pct) + "% vs start");

    document.querySelector(".stat-card:nth-child(1) .stat-label").textContent =
      m.eyebrow + " · 12w";
  }

  function setVal(sel, html) {
    var e = document.querySelector(sel);
    if (e) e.innerHTML = html;
  }
  function setDelta(sel, cls, text) {
    var e = document.querySelector(sel);
    if (!e) return;
    e.className = "delta " + cls;
    e.innerHTML = '<span class="arrow">' + (cls === "up" ? "▲" : cls === "down" ? "▼" : "■") + "</span> " + text;
  }

  /* ── Chart header text ── */
  function refreshChartHead() {
    var m = METRICS[state.metric];
    document.querySelector("[data-chart-eyebrow]").textContent = m.eyebrow;
    document.querySelector("[data-chart-title]").textContent = m.title;
    document.querySelector("[data-legend]").textContent = m.legend;
  }

  /* ── Wire tabs ── */
  document.querySelectorAll(".tab").forEach(function (tab) {
    tab.addEventListener("click", function () {
      if (tab.classList.contains("is-active")) return;
      document.querySelectorAll(".tab").forEach(function (t) {
        t.classList.remove("is-active");
        t.setAttribute("aria-selected", "false");
      });
      tab.classList.add("is-active");
      tab.setAttribute("aria-selected", "true");
      state.metric = tab.dataset.metric;
      renderAll();
      toast("Showing <span class=\"tk\">" + tab.textContent.trim() + "</span> progress");
    });
  });

  /* ── Wire range ── */
  document.querySelectorAll(".range-btn").forEach(function (btn) {
    btn.addEventListener("click", function () {
      if (btn.classList.contains("is-active")) return;
      document.querySelectorAll(".range-btn").forEach(function (b) {
        b.classList.remove("is-active");
      });
      btn.classList.add("is-active");
      state.range = parseInt(btn.dataset.range, 10);
      drawChart();
      var label = btn.textContent.trim();
      toast("Range set to <span class=\"tk\">" + label + "</span>");
    });
  });

  function renderAll() {
    refreshChartHead();
    drawChart();
    renderPRs();
    refreshSummary();
  }

  renderAll();
})();

snippets.css:
:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --sh-1: 0 1px 2px rgba(0, 0, 0, 0.4);
  --sh-2: 0 10px 30px rgba(0, 0, 0, 0.45);
  --sh-3: 0 24px 60px rgba(0, 0, 0, 0.55);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  background:
    radial-gradient(900px 500px at 88% -8%, rgba(198, 255, 58, 0.07), transparent 60%),
    radial-gradient(700px 460px at -6% 0%, rgba(255, 106, 43, 0.06), transparent 55%),
    var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button { font-family: inherit; }

:focus-visible {
  outline: 2px solid var(--neon);
  outline-offset: 2px;
  border-radius: var(--r-sm);
}

.shell {
  max-width: 1180px;
  margin: 0 auto;
  padding: 28px 24px 64px;
}

/* ---------- Topbar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 26px;
}
.brand { display: flex; align-items: center; gap: 14px; }
.brand-mark {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: linear-gradient(135deg, var(--neon), var(--neon-d));
  color: #0d0f12;
  font-weight: 900;
  font-size: 17px;
  letter-spacing: 0.5px;
  box-shadow: 0 6px 18px rgba(198, 255, 58, 0.28);
}
.brand-eyebrow {
  display: block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}
.brand-title {
  margin: 0;
  font-size: 24px;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.topbar-actions { display: flex; gap: 10px; }

/* ---------- Buttons ---------- */
.btn {
  border: 1px solid var(--line-2);
  background: var(--surface-2);
  color: var(--ink);
  font-weight: 600;
  font-size: 14px;
  padding: 10px 16px;
  border-radius: var(--r-md);
  cursor: pointer;
  transition: transform 0.06s ease, background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
}
.btn:hover { background: var(--elevated); border-color: var(--line-2); }
.btn:active { transform: translateY(1px); }
.btn-sm { padding: 7px 12px; font-size: 13px; border-radius: var(--r-sm); }
.btn-ghost { background: transparent; border-color: var(--line); color: var(--ink-2); }
.btn-ghost:hover { color: var(--ink); border-color: var(--line-2); }
.btn-neon {
  background: linear-gradient(135deg, var(--neon), var(--neon-d));
  color: #0d0f12;
  border-color: transparent;
  font-weight: 800;
  box-shadow: 0 8px 20px rgba(198, 255, 58, 0.22);
}
.btn-neon:hover { box-shadow: 0 10px 26px rgba(198, 255, 58, 0.34); }
.btn-danger { color: var(--danger); border-color: rgba(248, 113, 113, 0.4); }
.btn-danger:hover { background: rgba(248, 113, 113, 0.12); }

/* ---------- KPIs ---------- */
.kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 22px;
}
.kpi {
  background: linear-gradient(180deg, var(--surface), var(--surface-2));
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 18px 18px 8px;
  box-shadow: var(--sh-1);
  position: relative;
  overflow: hidden;
}
.kpi-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.kpi-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}
.kpi-trend {
  font-size: 12px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
}
.kpi-trend.up { color: var(--ok); background: rgba(52, 211, 153, 0.14); }
.kpi-trend.down { color: var(--ok); background: rgba(52, 211, 153, 0.14); }
.kpi-value {
  font-size: 30px;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin: 8px 0 4px;
}
.spark {
  width: 100%;
  height: 36px;
  display: block;
}
.spark polyline {
  fill: none;
  stroke: var(--neon);
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 2px 6px rgba(198, 255, 58, 0.35));
}
.spark.warn polyline { stroke: var(--orange); filter: drop-shadow(0 2px 6px rgba(255, 106, 43, 0.35)); }

/* ---------- Panel ---------- */
.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-2);
  overflow: hidden;
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
  padding: 16px 18px;
  border-bottom: 1px solid var(--line);
}
.search {
  position: relative;
  flex: 1 1 240px;
  max-width: 360px;
}
.search svg {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 17px;
  height: 17px;
  stroke: var(--muted);
  stroke-width: 2;
  fill: none;
  stroke-linecap: round;
  pointer-events: none;
}
.search input {
  width: 100%;
  padding: 10px 12px 10px 38px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  color: var(--ink);
  font-size: 14px;
}
.search input::placeholder { color: var(--muted); }
.search input:focus { border-color: var(--line-2); outline: none; box-shadow: 0 0 0 3px var(--neon-50); }

.filters { display: flex; gap: 8px; flex-wrap: wrap; }
.chip {
  border: 1px solid var(--line);
  background: var(--surface-2);
  color: var(--ink-2);
  font-size: 13px;
  font-weight: 600;
  padding: 8px 14px;
  border-radius: 999px;
  cursor: pointer;
  transition: all 0.15s ease;
}
.chip:hover { color: var(--ink); border-color: var(--line-2); }
.chip.is-active {
  background: var(--neon-50);
  border-color: rgba(198, 255, 58, 0.4);
  color: var(--neon);
}

/* ---------- Bulk bar ---------- */
.bulkbar {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 18px;
  background: var(--neon-50);
  border-bottom: 1px solid rgba(198, 255, 58, 0.25);
  animation: slideDown 0.18s ease;
}
@keyframes slideDown { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: none; } }
.bulk-count { font-size: 14px; color: var(--ink-2); }
.bulk-count strong { color: var(--neon); }
.bulk-actions { display: flex; gap: 8px; }
.bulk-clear {
  margin-left: auto;
  background: transparent;
  border: none;
  color: var(--muted);
  font-size: 22px;
  line-height: 1;
  cursor: pointer;
  padding: 0 4px;
}
.bulk-clear:hover { color: var(--ink); }

/* ---------- Table ---------- */
.table-wrap { overflow-x: auto; }
.members {
  width: 100%;
  border-collapse: collapse;
  min-width: 760px;
}
.members thead th {
  text-align: left;
  padding: 12px 14px;
  background: var(--surface-2);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
}
.members th.num, .members td.num { text-align: right; }
.col-check { width: 44px; }
.col-actions { width: 120px; text-align: right; }
.sort {
  background: none;
  border: none;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0;
}
.sort:hover { color: var(--ink); }
.caret {
  width: 0; height: 0;
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  opacity: 0;
  transition: opacity 0.15s;
}
.sort.asc .caret { opacity: 1; border-bottom: 5px solid var(--neon); }
.sort.desc .caret { opacity: 1; border-top: 5px solid var(--neon); }
.sort.asc, .sort.desc { color: var(--ink); }

.members tbody td {
  padding: 13px 14px;
  border-bottom: 1px solid var(--line);
  font-size: 14px;
  color: var(--ink-2);
  vertical-align: middle;
}
.members tbody tr { transition: background 0.12s ease; cursor: pointer; }
.members tbody tr:hover { background: var(--surface-2); }
.members tbody tr.is-selected { background: var(--neon-50); }
.members tbody tr:last-child td { border-bottom: none; }

.member-cell { display: flex; align-items: center; gap: 11px; }
.avatar {
  width: 34px; height: 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 13px;
  font-weight: 700;
  color: #0d0f12;
  flex: none;
}
.member-name { color: var(--ink); font-weight: 600; }
.member-email { font-size: 12px; color: var(--muted); }

.tier {
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.tier-elite { color: var(--neon); }
.tier-pro { color: var(--orange); }
.tier-basic { color: var(--ink-2); }

.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  text-transform: capitalize;
}
.pill::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.pill.active { color: var(--ok); background: rgba(52, 211, 153, 0.13); }
.pill.frozen { color: #7dd3fc; background: rgba(125, 211, 252, 0.13); }
.pill.trial { color: var(--warn); background: rgba(251, 191, 36, 0.13); }
.pill.lapsed { color: var(--danger); background: rgba(248, 113, 113, 0.13); }

.ltv { color: var(--ink); font-weight: 700; font-variant-numeric: tabular-nums; }

.row-actions { display: flex; gap: 6px; justify-content: flex-end; }
.icon-btn {
  width: 30px; height: 30px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line);
  background: var(--surface-2);
  color: var(--ink-2);
  display: grid;
  place-items: center;
  cursor: pointer;
  font-size: 14px;
  transition: all 0.13s ease;
}
.icon-btn:hover { color: var(--ink); border-color: var(--line-2); background: var(--elevated); }
.icon-btn svg { width: 15px; height: 15px; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

.col-check input, .members thead input {
  width: 16px; height: 16px;
  accent-color: var(--neon);
  cursor: pointer;
}

.empty {
  padding: 48px 20px;
  text-align: center;
  color: var(--muted);
  font-size: 14px;
}

/* ---------- Pager ---------- */
.pager {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 18px;
  border-top: 1px solid var(--line);
  flex-wrap: wrap;
}
.pager-info { font-size: 13px; color: var(--muted); }
.pager-btns { display: flex; align-items: center; gap: 8px; }
.pager-pages { display: flex; gap: 6px; }
.page-num {
  min-width: 32px;
  height: 32px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line);
  background: var(--surface-2);
  color: var(--ink-2);
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
}
.page-num.is-active { background: var(--neon); color: #0d0f12; border-color: transparent; }
.btn:disabled { opacity: 0.4; cursor: not-allowed; }

/* ---------- Drawer ---------- */
.drawer-scrim {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(2px);
  z-index: 40;
  animation: fade 0.18s ease;
}
@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
.drawer {
  position: fixed;
  top: 0; right: 0;
  height: 100%;
  width: 400px;
  max-width: 92vw;
  background: var(--surface);
  border-left: 1px solid var(--line-2);
  box-shadow: var(--sh-3);
  z-index: 50;
  transform: translateX(100%);
  transition: transform 0.26s cubic-bezier(0.22, 1, 0.36, 1);
  overflow-y: auto;
  padding: 22px 22px 32px;
}
.drawer.is-open { transform: translateX(0); }
.drawer-close {
  position: absolute;
  top: 14px; right: 16px;
  background: transparent;
  border: none;
  color: var(--muted);
  font-size: 26px;
  line-height: 1;
  cursor: pointer;
}
.drawer-close:hover { color: var(--ink); }

.d-head { display: flex; align-items: center; gap: 14px; margin: 6px 0 18px; }
.d-avatar {
  width: 58px; height: 58px;
  border-radius: 50%;
  display: grid; place-items: center;
  font-size: 21px; font-weight: 800; color: #0d0f12;
  flex: none;
}
.d-name { font-size: 20px; font-weight: 800; margin: 0; letter-spacing: -0.01em; }
.d-email { color: var(--muted); font-size: 13px; }

.d-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin: 18px 0;
}
.d-stat {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 12px;
  text-align: center;
}
.d-stat-v { font-size: 18px; font-weight: 800; color: var(--ink); }
.d-stat-l { font-size: 10px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); margin-top: 2px; }

.d-section-title {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
  margin: 22px 0 10px;
}
.d-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 0;
  border-bottom: 1px solid var(--line);
  font-size: 14px;
}
.d-row span:first-child { color: var(--muted); }
.d-row span:last-child { color: var(--ink); font-weight: 600; }
.d-actions { display: flex; gap: 10px; margin-top: 22px; }
.d-actions .btn { flex: 1; }

/* ---------- Toasts ---------- */
.toast-stack {
  position: fixed;
  bottom: 22px; left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 10px;
  z-index: 80;
  width: max-content;
  max-width: 92vw;
}
.toast {
  background: var(--elevated);
  border: 1px solid var(--line-2);
  border-left: 3px solid var(--neon);
  color: var(--ink);
  padding: 12px 16px;
  border-radius: var(--r-md);
  font-size: 14px;
  font-weight: 500;
  box-shadow: var(--sh-2);
  animation: toastIn 0.22s ease;
}
.toast.danger { border-left-color: var(--danger); }
@keyframes toastIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }

/* ---------- Responsive ---------- */
@media (max-width: 880px) {
  .kpis { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 520px) {
  .shell { padding: 18px 14px 48px; }
  .brand-title { font-size: 20px; }
  .topbar-actions { width: 100%; }
  .topbar-actions .btn { flex: 1; }
  .kpis { grid-template-columns: 1fr 1fr; gap: 10px; }
  .kpi { padding: 14px 14px 6px; }
  .kpi-value { font-size: 24px; }
  .toolbar { padding: 14px; }
  .search { max-width: none; }
  .filters { width: 100%; }
  .pager { justify-content: center; }
  .drawer { width: 100%; max-width: 100%; }
}

