// ---------------------------------------------------------------------------
// Ironpulse — Classes Overview
// Vanilla JS: render class grid, category filtering with fade reveal, toasts.
// ---------------------------------------------------------------------------

(function () {
  "use strict";

  /** Class catalog — fictional but realistic data. */
  const CLASSES = [
    {
      cat: "strength",
