    },
    {
      cat: "cardio",
      label: "Cardio",
      name: "Row Republic",
      blurb: "Low-impact, high-output rowing intervals. Big aerobic gains, easy on the joints.",
      duration: "40 min",
      intensity: 3,
      trainer: "Leo Marsh",
      role: "Endurance Coach",
    },
    {
      cat: "cycle",
      label: "Cycle",
      name: "Night Ride",
      blurb: "Beat-matched indoor cycling in the dark with neon visuals and relentless climbs.",
      duration: "45 min",
      intensity: 4,
      trainer: "Sofia Reyes",
      role: "Ride Captain",
    },
    {
      cat: "cycle",
      label: "Cycle",
      name: "Power Sprint",
      blurb: "Short, savage cycle sprints built around wattage targets and recovery blocks.",
      duration: "30 min",
      intensity: 5,
      trainer: "Sofia Reyes",
      role: "Ride Captain",
    },
    {
      cat: "yoga",
      label: "Yoga",
      name: "Flow & Restore",
      blurb: "A slow vinyasa flow into deep restorative holds. Reset your nervous system.",
      duration: "60 min",
      intensity: 2,
      trainer: "Hannah Lim",
      role: "Yoga Instructor",
    },
    {
      cat: "yoga",
      label: "Yoga",
      name: "Power Vinyasa",
      blurb: "Heated, breath-led flow that builds heat, balance, and serious core control.",
      duration: "55 min",
      intensity: 3,
      trainer: "Hannah Lim",
      role: "Yoga Instructor",
    },
    {
      cat: "hiit",
      label: "HIIT",
      name: "Engine Room",
      blurb: "Rowers, bikes, and barbell complexes in timed intervals. Featured 6-week series.",
      duration: "45 min",
      intensity: 5,
      trainer: "Marcus Vega",
      role: "Head S&C Coach",
    },
    {
      cat: "hiit",
      label: "HIIT",
      name: "Tabata 20",
      blurb: "Twenty minutes, eight rounds, zero excuses. Bodyweight intervals at max effort.",
      duration: "30 min",
      intensity: 5,
      trainer: "Priya Anand",
      role: "Conditioning Coach",
    },
    {
      cat: "mobility",
      label: "Mobility",
      name: "Joints & Jelly",
      blurb: "Controlled articular rotations and loaded stretching to bulletproof your joints.",
      duration: "40 min",
      intensity: 1,
      trainer: "Leo Marsh",
      role: "Endurance Coach",
    },
    {
      cat: "mobility",
      label: "Mobility",
      name: "Deep Reset",
      blurb: "Foam rolling, breathwork, and mobility drills to unwind after a heavy training week.",
      duration: "35 min",
      intensity: 2,
      trainer: "Dana Okafor",
      role: "Strength Coach",
    },
  ];

  const grid = document.getElementById("grid");
  const empty = document.getElementById("empty");
  const countEl = document.querySelector("[data-count]");
  const filterBtns = Array.from(document.querySelectorAll(".filter"));
  const toastEl = document.getElementById("toast");

  let activeFilter = "all";
  let toastTimer = null;

  /** Initials for the trainer avatar. */
  function initials(name) {
    return name
      .split(" ")
      .map((p) => p[0])
      .join("")
      .slice(0, 2)
      .toUpperCase();
  }

  /** Build the intensity meter (5 bars). */
  function intensityBars(level) {
    let bars = "";
    for (let i = 1; i <= 5; i++) {
      bars += `<span class="intensity__bar${i <= level ? " on" : ""}"></span>`;
    }
    return bars;
  }

  /** Render one card element from a class record. */
  function makeCard(c) {
    const el = document.createElement("article");
    el.className = "card";
    el.dataset.cat = c.cat;
    el.innerHTML = `
      <div class="card__header h-${c.cat}">
        <span class="card__cat">${c.label}</span>
        <span class="card__time">${c.duration}</span>
      </div>
      <div class="card__body">
        <h3 class="card__name">${c.name}</h3>
        <p class="card__blurb">${c.blurb}</p>
        <div class="intensity">
          <div class="intensity__label">
            <span>Intensity</span><span>${c.intensity}/5</span>
          </div>
          <div class="intensity__bars" role="img" aria-label="Intensity ${c.intensity} out of 5">
            ${intensityBars(c.intensity)}
          </div>
        </div>
        <div class="card__foot">
          <div class="trainer">
            <span class="trainer__avatar" aria-hidden="true">${initials(c.trainer)}</span>
            <span>
              <span class="trainer__name">${c.trainer}</span><br />
              <span class="trainer__role">${c.role}</span>
            </span>
          </div>
          <button class="card__link" data-schedule="${c.name}">
            See schedule <span aria-hidden="true">→</span>
          </button>
        </div>
      </div>`;
    return el;
  }

  /** Initial render of all cards. */
  function render() {
    const frag = document.createDocumentFragment();
    CLASSES.forEach((c) => frag.appendChild(makeCard(c)));
    grid.appendChild(frag);
  }

  /** Apply the active filter with a staggered fade-in reveal. */
  function applyFilter(filter) {
    activeFilter = filter;
    const cards = Array.from(grid.children);
    let shown = 0;
    let stagger = 0;

    cards.forEach((card) => {
      const match = filter === "all" || card.dataset.cat === filter;
      if (match) {
        shown++;
        card.classList.remove("is-hidden");
        card.classList.add("is-enter");
        // stagger the reveal for a smooth cascade
        const delay = stagger;
        stagger += 45;
        requestAnimationFrame(() => {
          card.style.transitionDelay = delay + "ms";
          requestAnimationFrame(() => {
            card.classList.remove("is-enter");
            card.classList.add("is-in");
          });
        });
        // clear the delay after the reveal so hover stays snappy
        window.setTimeout(() => {
          card.style.transitionDelay = "";
        }, delay + 400);
      } else {
        card.classList.add("is-hidden");
        card.classList.remove("is-enter", "is-in");
      }
    });

    empty.hidden = shown > 0;
    updateCount(shown);
  }

  function updateCount(n) {
    const word = n === 1 ? "class" : "classes";
    const scope = activeFilter === "all" ? "all" : activeFilter;
    countEl.textContent = `${n} ${word} · ${scope}`;
  }

  function setActiveButton(btn) {
    filterBtns.forEach((b) => {
      const on = b === btn;
      b.classList.toggle("is-active", on);
      b.setAttribute("aria-selected", on ? "true" : "false");
    });
  }

  /** Lightweight toast helper. */
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = window.setTimeout(() => {
      toastEl.classList.remove("show");
    }, 2600);
  }

  // ----- Wire up events -----
  filterBtns.forEach((btn) => {
    btn.addEventListener("click", () => {
      setActiveButton(btn);
      applyFilter(btn.dataset.filter);
    });
  });

  // Delegated clicks for "See schedule" + booking CTAs.
  document.addEventListener("click", (e) => {
    const schedule = e.target.closest("[data-schedule]");
    if (schedule) {
      toast(`Opening the schedule for “${schedule.dataset.schedule}”…`);
      return;
    }
    const book = e.target.closest("[data-book]");
    if (book) {
      toast(`Nice — we saved you a ${book.dataset.book}. Check your email!`);
    }
  });

  // ----- Boot -----
  render();
  applyFilter("all");
})();

snippets.css:
/* ── Design tokens ─────────────────────────────────────────────────────────── */
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream-2);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  display: grid;
  place-items: start center;
  min-height: 100vh;
  padding: 32px 16px;
}

/* ── Widget wrapper ─────────────────────────────────────────────────────────── */
.widget-wrap {
  width: 100%;
  max-width: 780px;
}
.widget {
  background: var(--bone);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-2);
  overflow: hidden;
}

/* ── Widget header ───────────────────────────────────────────────────────────── */
.widget-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 22px 14px;
  background: var(--navy);
  color: var(--bone);
}
.wh-left {
  display: flex;
  align-items: center;
  gap: 14px;
}
.brand-mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.35rem;
  flex-shrink: 0;
}
.wh-title {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.25rem;
  letter-spacing: 0.01em;
}
.wh-sub {
  font-size: 0.7rem;
  color: var(--gold-light);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-top: 2px;
}
.open-badge {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 700;
  background: var(--danger);
  color: #fff;
  padding: 5px 14px;
  border-radius: 999px;
  font-variant-numeric: tabular-nums;
  transition: background 0.2s;
}
.open-badge[data-zero="true"] {
  background: rgba(74, 119, 82, 0.8);
}

/* ── New ticket form ─────────────────────────────────────────────────────────── */
.new-form {
  padding: 14px 22px;
  background: rgba(22, 30, 44, 0.03);
  border-bottom: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.form-row {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}
.form-input,
.form-select {
  background: var(--bone);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-sm);
  font-family: var(--font-body);
  font-size: 0.84rem;
  color: var(--ink);
  padding: 9px 12px;
  outline: none;
  transition: border-color 0.1s;
}
.form-input:focus,
.form-select:focus {
  border-color: var(--navy-2);
}
.form-input[id="fRoom"] {
  width: 90px;
}
.form-input[id="fAssignee"] {
  flex: 1;
  min-width: 100px;
}
.form-input.desc {
  flex: 1;
  min-width: 200px;
}
.form-select {
  flex: 1;
  min-width: 110px;
  cursor: pointer;
}
.form-submit {
  background: var(--navy);
  color: var(--bone);
  border: none;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 700;
  padding: 9px 18px;
  border-radius: var(--r-sm);
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.1s;
}
.form-submit:hover {
  background: var(--navy-d);
}

/* ── Filter bar ──────────────────────────────────────────────────────────────── */
.filter-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 22px;
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}
.filter-label {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  margin-right: 2px;
}
.chip {
  background: transparent;
  border: 1px solid var(--line-strong);
  font-family: inherit;
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--ink-2);
  padding: 5px 12px;
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.1s, border-color 0.1s, color 0.1s;
}
.chip:hover {
  background: var(--cream-2);
}
.chip.is-active {
  background: var(--gold);
  color: var(--navy-d);
  border-color: var(--gold);
}

/* ── Ticket list ─────────────────────────────────────────────────────────────── */
.ticket-list {
  list-style: none;
  max-height: 520px;
  overflow-y: auto;
}

/* ── Ticket item ─────────────────────────────────────────────────────────────── */
.ticket {
  display: grid;
  grid-template-columns: 60px 1fr auto;
  align-items: start;
  gap: 12px;
  padding: 14px 22px;
  border-bottom: 1px solid var(--line);
  transition: background 0.1s;
}
.ticket:last-child {
  border-bottom: none;
}
.ticket:hover {
  background: rgba(22, 30, 44, 0.02);
}
.ticket.resolved {
  opacity: 0.55;
}

/* room + id block */
.t-room-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
  align-items: center;
  text-align: center;
}
.t-room {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--navy-d);
}
.t-id {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  color: var(--warm-gray);
  font-variant-numeric: tabular-nums;
}

/* body */
.t-body {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.t-top {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.t-issue {
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--ink);
}
.pri-badge {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 999px;
}
.pri-badge.urgent {
  background: rgba(179, 66, 50, 0.18);
  color: var(--danger);
}
.pri-badge.high {
  background: rgba(217, 144, 32, 0.16);
  color: var(--warning);
}
.pri-badge.normal {
  background: rgba(74, 109, 160, 0.14);
  color: var(--info);
}
.pri-badge.low {
  background: rgba(74, 119, 82, 0.12);
  color: var(--success);
}

.t-desc {
  font-size: 0.82rem;
  color: var(--ink-2);
  line-height: 1.4;
}
.t-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.74rem;
  color: var(--warm-gray);
  margin-top: 2px;
  flex-wrap: wrap;
}
.t-assignee strong {
  font-weight: 600;
  color: var(--navy-2);
}
.t-age {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-variant-numeric: tabular-nums;
}

/* right side: status pill (clickable) */
.t-status-wrap {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  padding-top: 2px;
}
.status-btn {
  border: none;
  font-family: inherit;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 11px;
  border-radius: 999px;
  cursor: pointer;
  white-space: nowrap;
  transition: filter 0.1s;
}
.status-btn:hover {
  filter: brightness(0.9);
}
.status-btn.open {
  background: rgba(179, 66, 50, 0.14);
  color: var(--danger);
}
.status-btn.inprogress {
  background: rgba(217, 144, 32, 0.16);
  color: var(--warning);
}
.status-btn.resolved {
  background: rgba(74, 119, 82, 0.14);
  color: var(--success);
}
.status-hint {
  font-size: 0.62rem;
  color: var(--warm-gray);
  white-space: nowrap;
}

/* ── Empty state ─────────────────────────────────────────────────────────────── */
.empty-state {
  text-align: center;
  padding: 40px 24px;
  font-size: 0.86rem;
  color: var(--warm-gray);
  font-style: italic;
}

/* ── Toast ───────────────────────────────────────────────────────────────────── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 22px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 100;
  white-space: nowrap;
}

/* ── Responsive ─────────────────────────────────────────────────────────────── */
@media (max-width: 640px) {
  body {
    padding: 16px 8px;
  }
  .ticket {
    grid-template-columns: 50px 1fr;
  }
  .t-status-wrap {
    grid-column: 2;
    flex-direction: row;
    align-items: center;
  }
  .form-row {
    gap: 6px;
  }
  .form-input[id="fRoom"] {
    width: 70px;
  }
}

