// ── Mock data ─────────────────────────────────────────────────────────────────
let tickets = [
  {
    id: 1001,
    room: "311",
    issue: "AC",
    priority: "urgent",
    desc: "AC not cooling — guest reports 28 °C in room",
    ageH: 1.5,
    assignee: "Marco B.",
    status: "open",
  },
  {
    id: 1002,
    room: "204",
    issue: "Plumbing",
    priority: "high",
    desc: "Shower drain blocked, standing water",
    ageH: 2.2,
    assignee: "Davide R.",
    status: "inprogress",
  },
  {
    id: 1003,
    room: "118",
    issue: "TV",
    priority: "normal",
    desc: "TV remote unresponsive, batteries replaced — no change",
    ageH: 3.0,
    assignee: "Marco B.",
    status: "open",
  },
  {
    id: 1004,
    room: "405",
    issue: "Lock",
    priority: "urgent",
    desc: "Electronic lock fails on 3rd attempt — keycard issue",
    ageH: 0.5,
    assignee: "Davide R.",
    status: "inprogress",
  },
  {
    id: 1005,
    room: "207",
    issue: "Lighting",
    priority: "normal",
    desc: "Bedside lamp flickers — likely loose bulb",
    ageH: 5.0,
    assignee: "Tiago F.",
    status: "open",
  },
  {
    id: 1006,
    room: "302",
    issue: "Heating",
    priority: "high",
    desc: "Radiator making loud banging noise at night",
    ageH: 8.0,
    assignee: "Marco B.",
    status: "open",
  },
  {
    id: 1007,
    room: "106",
    issue: "Plumbing",
    priority: "low",
    desc: "Tap drips slowly when fully closed",
    ageH: 14.0,
    assignee: "Tiago F.",
    status: "resolved",
  },
  {
    id: 1008,
    room: "219",
    issue: "AC",
    priority: "normal",
    desc: "AC thermostat unresponsive after power outage",
    ageH: 6.5,
    assignee: "Davide R.",
    status: "inprogress",
  },
  {
    id: 1009,
    room: "401",
    issue: "Elevator",
    priority: "high",
    desc: "Floor 4 elevator door judders on close — safety concern",
    ageH: 4.0,
    assignee: "Chief Eng.",
    status: "open",
  },
  {
    id: 1010,
    room: "112",
    issue: "TV",
    priority: "low",
    desc: "HDMI input 2 not recognised by TV",
    ageH: 11.0,
    assignee: "Tiago F.",
    status: "resolved",
  },
];
let nextId = 1011;
let activeFilter = "all";

// ── Status cycle ──────────────────────────────────────────────────────────────
const STATUS_CYCLE = { open: "inprogress", inprogress: "resolved", resolved: "open" };
const STATUS_NEXT_LABEL = { open: "→ In Progress", inprogress: "→ Resolved", resolved: "→ Reopen" };
const STATUS_LABEL = { open: "Open", inprogress: "In Progress", resolved: "Resolved" };

// ── Toast helper ──────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2200);
}

// ── Age formatter ─────────────────────────────────────────────────────────────
function fmtAge(h) {
  if (h < 1) return `${Math.round(h * 60)} min ago`;
  if (h < 24) return `${h % 1 === 0 ? h : h.toFixed(1)} hr ago`;
  return `${Math.floor(h / 24)} d ago`;
}

// ── Open count ────────────────────────────────────────────────────────────────
function updateBadge() {
  const count = tickets.filter((t) => t.status !== "resolved").length;
  const badge = document.getElementById("openBadge");
  badge.textContent = `${count} open`;
  badge.dataset.zero = count === 0 ? "true" : "false";
}

// ── Render list ───────────────────────────────────────────────────────────────
function renderList() {
  const list = document.getElementById("ticketList");
  const empty = document.getElementById("emptyState");

  const filtered =
    activeFilter === "all" ? tickets : tickets.filter((t) => t.priority === activeFilter);

  if (filtered.length === 0) {
    list.innerHTML = "";
    empty.hidden = false;
    return;
  }
  empty.hidden = true;

  list.innerHTML = filtered
    .map(
      (t) => `
    <li class="ticket ${t.status}" data-id="${t.id}">
      <div class="t-room-block">
        <span class="t-room">${t.room}</span>
        <span class="t-id">#${t.id}</span>
      </div>
      <div class="t-body">
        <div class="t-top">
          <span class="t-issue">${t.issue}</span>
          <span class="pri-badge ${t.priority}">${t.priority}</span>
        </div>
        <p class="t-desc">${t.desc}</p>
        <div class="t-meta">
          <span class="t-assignee">Assignee: <strong>${t.assignee}</strong></span>
          <span class="t-age">${fmtAge(t.ageH)}</span>
        </div>
      </div>
      <div class="t-status-wrap">
        <button class="status-btn ${t.status}" data-action="cycle" data-id="${t.id}">
          ${STATUS_LABEL[t.status]}
        </button>
        <span class="status-hint">${STATUS_NEXT_LABEL[t.status]}</span>
      </div>
    </li>
  `
    )
    .join("");
}

// ── Status cycle click (event delegation) ─────────────────────────────────────
document.getElementById("ticketList").addEventListener("click", (e) => {
  const btn = e.target.closest("button[data-action='cycle']");
  if (!btn) return;
  const id = parseInt(btn.dataset.id, 10);
  const t = tickets.find((x) => x.id === id);
  if (!t) return;
  const prev = t.status;
  t.status = STATUS_CYCLE[prev];
  showToast(`Ticket #${id} · ${STATUS_LABEL[t.status]}`);
  updateBadge();
  renderList();
});

// ── Priority filter chips ─────────────────────────────────────────────────────
document.querySelectorAll(".chip[data-pri]").forEach((btn) => {
  btn.addEventListener("click", () => {
    document.querySelectorAll(".chip[data-pri]").forEach((b) => b.classList.remove("is-active"));
    btn.classList.add("is-active");
    activeFilter = btn.dataset.pri;
    renderList();
  });
});

// ── New ticket form ───────────────────────────────────────────────────────────
document.getElementById("newForm").addEventListener("submit", (e) => {
  e.preventDefault();

  const room = document.getElementById("fRoom").value.trim();
  const issue = document.getElementById("fIssue").value;
  const priority = document.getElementById("fPri").value;
  const assignee = document.getElementById("fAssignee").value.trim() || "Unassigned";
  const desc = document.getElementById("fDesc").value.trim();

  if (!room || !issue || !priority) {
    showToast("Please fill in room, issue type, and priority.");
    return;
  }

  const t = {
    id: nextId++,
    room,
    issue,
    priority,
    desc: desc || `${issue} issue reported in room ${room}.`,
    ageH: 0,
    assignee,
    status: "open",
  };

  tickets.unshift(t);

  // ── Reset form ──
  document.getElementById("fRoom").value = "";
  document.getElementById("fIssue").value = "";
  document.getElementById("fPri").value = "";
  document.getElementById("fAssignee").value = "";
  document.getElementById("fDesc").value = "";

  showToast(`Ticket #${t.id} created — room ${room}`);
  updateBadge();
  renderList();
});

// ── Initial render ────────────────────────────────────────────────────────────
updateBadge();
renderList();

snippets.css:
:root {
  --cream: #f4efe4;
  --paper: #faf7f0;
  --white: #ffffff;
  --newsprint: #efe9da;
  --ink: #16130f;
  --ink-2: #2b2620;
  --ink-3: #4a443b;
  --muted: #7a7164;
  --red: #b4291f;
  --red-d: #8f1f17;
  --red-50: #f3dcd9;
  --rule: rgba(22, 19, 15, 0.16);
  --rule-2: rgba(22, 19, 15, 0.30);
  --rule-hair: rgba(22, 19, 15, 0.10);
  --ok: #2f7d4f;
  --warn: #b67a18;
  --danger: #b4291f;
  --r-sm: 4px;
  --r-md: 8px;
  --r-lg: 12px;
  --serif: "Playfair Display", "Times New Roman", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;
  --hud-h: 56px;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--sans);
  background: var(--cream);
  color: var(--ink);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

.skip-link {
  position: fixed;
  left: 12px;
  top: -60px;
  z-index: 200;
  background: var(--ink);
  color: var(--paper);
  padding: 8px 14px;
  font-size: 13px;
  font-weight: 600;
  border-radius: var(--r-sm);
  transition: top .18s ease;
}
.skip-link:focus { top: 12px; }

kbd {
  font-family: var(--sans);
  font-size: 11px;
  font-weight: 600;
  background: var(--white);
  border: 1px solid var(--rule);
  border-bottom-width: 2px;
  border-radius: var(--r-sm);
  padding: 1px 6px;
  color: var(--ink-2);
}

/* ============ FRAME HUD ============ */
.frame-hud {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--hud-h);
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 18px;
  background: color-mix(in srgb, var(--paper) 86%, transparent);
  backdrop-filter: blur(10px) saturate(1.1);
  -webkit-backdrop-filter: blur(10px) saturate(1.1);
  border-bottom: 1px solid var(--rule);
}

.frame-hud__brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.frame-hud__mark {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 1.5px solid var(--ink);
  border-radius: var(--r-sm);
  font-family: var(--serif);
  font-weight: 800;
  font-size: 14px;
  letter-spacing: .02em;
  color: var(--ink);
}
.frame-hud__paper {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 15px;
  letter-spacing: .01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.frame-hud__counter {
  font-family: var(--serif);
  font-weight: 700;
  display: flex;
  align-items: baseline;
  gap: 4px;
  letter-spacing: .04em;
}
.frame-hud__cur { font-size: 20px; color: var(--red); }
.frame-hud__sep { font-size: 16px; color: var(--rule-2); }
.frame-hud__total { font-size: 15px; color: var(--muted); }

.frame-hud__controls { display: flex; gap: 8px; }
.hud-btn {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  font-size: 15px;
  background: var(--white);
  color: var(--ink-2);
  border: 1px solid var(--rule);
  border-radius: var(--r-sm);
  cursor: pointer;
  transition: background .15s ease, color .15s ease, border-color .15s ease, transform .08s ease;
}
.hud-btn:hover { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.hud-btn:active { transform: translateY(1px); }
.hud-btn:focus-visible { outline: 2px solid var(--red); outline-offset: 2px; }

.frame-progress {
  position: fixed;
  top: var(--hud-h);
  left: 0;
  right: 0;
  height: 3px;
  z-index: 99;
  background: var(--rule-hair);
}
.frame-progress__bar {
  display: block;
  height: 100%;
  width: 0%;
  background: var(--red);
  transition: width .3s cubic-bezier(.4,0,.2,1);
}

/* ============ DECK / PLATES ============ */
.deck {
  scroll-snap-type: y proximity;
  overflow-y: auto;
  height: 100vh;
}

.plate {
  min-height: 100vh;
  scroll-snap-align: start;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(var(--hud-h) + 28px) 24px 40px;
  position: relative;
}

/* ============ DUOTONE "PHOTOS" ============ */
.duo {
  position: relative;
  overflow: hidden;
  background-color: var(--ink-2);
  isolation: isolate;
}
.duo .grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  opacity: .5;
  mix-blend-mode: overlay;
  background-image:
    radial-gradient(rgba(255,255,255,.10) 1px, transparent 1.4px),
    radial-gradient(rgba(0,0,0,.16) 1px, transparent 1.4px);
  background-size: 3px 3px, 4px 4px;
  background-position: 0 0, 1px 2px;
}

/* dawn — title plate: cool indigo to ember red */
.duo--dawn {
  background:
    radial-gradient(120% 90% at 75% 12%, rgba(244,200,150,.42), transparent 55%),
    radial-gradient(140% 120% at 20% 110%, rgba(180,41,31,.55), transparent 60%),
    linear-gradient(165deg, #1b2233 0%, #2c2436 38%, #5a2a28 70%, #8f1f17 100%);
}
/* harbor — silvered blue dawn water */
.duo--harbor {
  background:
    radial-gradient(90% 70% at 50% 20%, rgba(238,231,210,.55), transparent 60%),
    linear-gradient(180deg, #c8c9c2 0%, #8f9aa0 30%, #4f5e69 60%, #232b33 100%),
    repeating-linear-gradient(180deg, rgba(255,255,255,.05) 0 2px, transparent 2px 9px);
  background-blend-mode: screen, normal, overlay;
}
/* hull — weathered green hull + dark waterline */
.duo--hull {
  background:
    linear-gradient(180deg, transparent 0 52%, rgba(15,18,14,.66) 52% 56%, transparent 56%),
    radial-gradient(80% 60% at 30% 35%, rgba(120,150,120,.4), transparent 60%),
    linear-gradient(160deg, #46503f 0%, #2f3a30 45%, #1a2018 100%);
}
/* hands — warm sepia close-up */
.duo--hands {
  background:
    radial-gradient(70% 60% at 40% 45%, rgba(245,222,182,.6), transparent 65%),
    linear-gradient(150deg, #6e4a30 0%, #4a3220 50%, #241712 100%);
}
/* marsh — bleached mud and grey-green cordgrass */
.duo--marsh {
  background:
    radial-gradient(120% 80% at 60% 30%, rgba(232,226,205,.5), transparent 60%),
    linear-gradient(175deg, #9aa089 0%, #6f7860 38%, #494f3c 70%, #2a2e22 100%),
    repeating-linear-gradient(92deg, rgba(20,30,18,.10) 0 3px, transparent 3px 14px);
}
/* lantern — deep night with a single warm glow */
.duo--lantern {
  background:
    radial-gradient(28% 32% at 64% 42%, rgba(255,206,120,.85), rgba(200,120,40,.3) 40%, transparent 70%),
    linear-gradient(180deg, #0d1422 0%, #111a26 55%, #060a12 100%);
}
/* reef — dark wet shell ridge under steel sky */
.duo--reef {
  background:
    linear-gradient(180deg, #aeb4ad 0%, #7c857f 34%, transparent 50%),
    linear-gradient(180deg, transparent 48%, #2b2a26 56%, #14130f 100%),
    radial-gradient(60% 30% at 50% 60%, rgba(70,60,50,.6), transparent 70%);
}
/* portrait — soft window-light duotone in ink + red */
.duo--portrait {
  background:
    radial-gradient(55% 70% at 32% 38%, rgba(244,231,205,.62), transparent 62%),
    linear-gradient(155deg, #4a443b 0%, #2b2620 45%, #161310 100%),
    radial-gradient(40% 50% at 80% 80%, rgba(180,41,31,.22), transparent 70%);
}
/* dusk — coda: ember sky over dark water */
.duo--dusk {
  background:
    linear-gradient(180deg, #e8a25a 0%, #c0512c 22%, #6e2a28 44%, #2a2530 64%, #14131a 100%),
    radial-gradient(60% 22% at 50% 46%, rgba(255,210,150,.4), transparent 70%);
}

/* ============ TITLE SPREAD ============ */
.plate--title { align-items: stretch; }
.title-spread {
  width: min(1180px, 100%);
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  grid-template-rows: auto 1fr;
  gap: 0 48px;
  align-self: center;
}
.masthead { grid-column: 1 / -1; }
.masthead__rule {
  height: 0;
  margin: 14px 0 0;
  border-top: 3px double var(--rule-2);
}
.kicker {
  margin: 0;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--red);
}
.title-spread__body {
  padding: 34px 0 0;
  align-self: center;
  max-width: 36ch;
}
.title-spread__overline {
  margin: 0 0 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--muted);
}
.title-spread__head {
  margin: 0;
  font-family: var(--serif);
  font-weight: 900;
  font-size: clamp(3.4rem, 9vw, 6.6rem);
  line-height: .92;
  letter-spacing: -.02em;
  color: var(--ink);
}
.title-spread__dek {
  margin: 22px 0 0;
  font-size: 1.06rem;
  line-height: 1.55;
  color: var(--ink-3);
  max-width: 34ch;
}
.byline {
  margin: 24px 0 0;
  padding-top: 16px;
  border-top: 1px solid var(--rule);
  font-size: 13px;
  color: var(--ink-2);
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 8px;
}
.byline__name { font-weight: 600; }
.byline__dot { color: var(--rule-2); }
.byline__date, .byline__read { color: var(--muted); }
.byline__read { font-variant: small-caps; letter-spacing: .03em; }
.title-spread__hint {
  margin: 28px 0 0;
  font-size: 12.5px;
  color: var(--muted);
  line-height: 1.7;
}
.title-spread__hint kbd { margin: 0 1px; }
.title-spread__hint em { color: var(--red); font-style: italic; }
.title-spread__hint-key { font-weight: 600; color: var(--ink-3); }

.title-spread__plate {
  margin: 34px 0 0;
  border-radius: var(--r-sm);
  min-height: 60vh;
  border: 1px solid var(--rule);
  box-shadow: 0 1px 0 var(--rule-hair);
}

/* ============ FRAME (full-bleed-ish plate photo) ============ */
.frame {
  margin: 0;
  width: min(1100px, 100%);
  display: flex;
  flex-direction: column;
}
.frame__img {
  display: block;
  width: 100%;
  aspect-ratio: 16 / 9;
  border: 0;
  padding: 0;
  cursor: zoom-in;
  border-radius: var(--r-sm);
  box-shadow: 0 1px 0 var(--rule-hair), 0 18px 40px -28px rgba(22,19,15,.5);
  transition: transform .35s cubic-bezier(.2,.7,.3,1), box-shadow .35s ease;
}
.frame--split .frame__img { aspect-ratio: 4 / 5; max-width: 680px; margin: 0 auto; }
.frame--coda .frame__img { aspect-ratio: 21 / 9; }
.frame__img:hover { box-shadow: 0 1px 0 var(--rule-hair), 0 26px 54px -26px rgba(22,19,15,.6); }
.frame__img:focus-visible { outline: 3px solid var(--red); outline-offset: 4px; }

.frame__num {
  position: absolute;
  left: 14px;
  bottom: 12px;
  z-index: 4;
  font-family: var(--serif);
  font-weight: 800;
  font-size: 13px;
  letter-spacing: .08em;
  color: var(--paper);
  background: rgba(22,19,15,.5);
  padding: 3px 9px;
  border-radius: var(--r-sm);
  backdrop-filter: blur(2px);
}

/* ============ CAPTIONS ============ */
.caption {
  margin: 14px 2px 0;
  padding-left: 14px;
  border-left: 2px solid var(--red);
  max-width: 62ch;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .6s ease, transform .6s ease;
}
.plate.is-active .caption { opacity: 1; transform: none; }
.caption__text {
  display: block;
  font-family: var(--serif);
  font-style: italic;
  font-size: 1.02rem;
  line-height: 1.5;
  color: var(--ink-2);
}
.caption__text em { font-style: normal; }
.caption__credit {
  display: block;
  margin-top: 7px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--muted);
}
.caption--coda { max-width: 70ch; }

/* ============ TEXT PASSAGES ============ */
.plate--text { padding-left: 24px; padding-right: 24px; }
.passage {
  width: min(680px, 100%);
  columns: 2;
  column-gap: 40px;
  column-rule: 1px solid var(--rule-hair);
}
.passage__lead, .passage__body {
  margin: 0 0 1.1em;
  font-size: 1.04rem;
  line-height: 1.62;
  color: var(--ink-2);
  text-align: justify;
  hyphens: auto;
  break-inside: avoid-column;
}
.passage__lead { break-after: column; }
.passage__lead::first-letter {
  float: left;
  font-family: var(--serif);
  font-weight: 800;
  font-size: 3.6em;
  line-height: .76;
  padding: 6px 10px 0 0;
  color: var(--red);
}

/* ============ PULL QUOTE ============ */
.plate--quote { background: var(--paper); }
.pullquote {
  margin: 0;
  width: min(820px, 100%);
  text-align: center;
  padding: 0 12px;
}
.pullquote__q {
  margin: 0;
  font-family: var(--serif);
  font-weight: 600;
  font-style: italic;
  font-size: clamp(1.9rem, 5.5vw, 3.4rem);
  line-height: 1.12;
  letter-spacing: -.01em;
  color: var(--ink);
  position: relative;
}
.pullquote__q::before,
.pullquote__q::after {
  content: "";
  display: block;
  width: 64px;
  height: 0;
  margin: 0 auto;
  border-top: 2px solid var(--red);
}
.pullquote__q::before { margin-bottom: 28px; }
.pullquote__q::after { margin-top: 28px; }
.pullquote__by {
  margin: 18px 0 0;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ============ CODA ============ */
.frame--coda { width: min(1180px, 100%); }
.coda__end {
  margin-top: 30px;
  padding-top: 22px;
  border-top: 3px double var(--rule-2);
  text-align: center;
}
.coda__paper {
  margin: 0;
  font-family: var(--serif);
  font-weight: 800;
  font-size: 1.5rem;
  letter-spacing: .01em;
}
.coda__note {
  margin: 6px 0 18px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--muted);
}
.coda__top {
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-2);
  background: var(--white);
  border: 1px solid var(--rule);
  padding: 9px 18px;
  border-radius: var(--r-sm);
  cursor: pointer;
  transition: background .15s ease, color .15s ease, border-color .15s ease;
}
.coda__top:hover { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.coda__top:focus-visible { outline: 2px solid var(--red); outline-offset: 2px; }

/* ============ LIGHTBOX ============ */
.lightbox {
  position: fixed;
  inset: 0;
  z-index: 300;
  display: grid;
  place-items: center;
  padding: 28px;
  background: rgba(12,10,8,.86);
  backdrop-filter: blur(6px);
  animation: lbIn .22s ease;
}
.lightbox[hidden] { display: none; }
@keyframes lbIn { from { opacity: 0; } to { opacity: 1; } }
.lightbox__close {
  position: absolute;
  top: 18px;
  right: 22px;
  width: 44px;
  height: 44px;
  font-size: 26px;
  line-height: 1;
  color: var(--paper);
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.22);
  border-radius: 50%;
  cursor: pointer;
  transition: background .15s ease, transform .08s ease;
}
.lightbox__close:hover { background: rgba(255,255,255,.18); }
.lightbox__close:active { transform: scale(.94); }
.lightbox__close:focus-visible { outline: 2px solid var(--red); outline-offset: 2px; }
.lightbox__fig {
  margin: 0;
  width: min(1080px, 100%);
  max-height: 100%;
  display: flex;
  flex-direction: column;
}
.lightbox__img {
  width: 100%;
  aspect-ratio: 16 / 9;
  max-height: 74vh;
  border-radius: var(--r-sm);
  box-shadow: 0 30px 80px -30px rgba(0,0,0,.8);
}
.lightbox__cap {
  margin: 14px 2px 0;
  padding-left: 14px;
  border-left: 2px solid var(--red);
  font-family: var(--serif);
  font-style: italic;
  font-size: 1rem;
  color: var(--newsprint);
  max-width: 62ch;
}
.lightbox__cap b {
  display: block;
  margin-top: 7px;
  font-family: var(--sans);
  font-style: normal;
  font-weight: 600;
  font-size: 11px;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: rgba(244,239,228,.65);
}

/* ============ TOAST ============ */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 20px);
  z-index: 400;
  background: var(--ink);
  color: var(--paper);
  font-size: 13px;
  font-weight: 500;
  padding: 10px 18px;
  border-radius: var(--r-md);
  box-shadow: 0 12px 30px -12px rgba(0,0,0,.5);
  opacity: 0;
  pointer-events: none;
  transition: opacity .25s ease, transform .25s ease;
}
.toast.is-on { opacity: 1; transform: translate(-50%, 0); }

/* ============ RESPONSIVE ============ */
@media (max-width: 920px) {
  .title-spread {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .title-spread__plate { min-height: 42vh; order: 3; }
  .title-spread__body { order: 2; max-width: none; }
}

@media (max-width: 720px) {
  .plate {
    padding: calc(var(--hud-h) + 22px) 18px 34px;
    min-height: 92vh;
  }
  .passage { columns: 1; column-rule: none; }
  .passage__lead::first-letter { font-size: 3.1em; }
  .frame--split .frame__img { aspect-ratio: 4 / 5; }
  .frame--coda .frame__img { aspect-ratio: 16 / 10; }
  .frame-hud__paper { font-size: 13px; }
}

@media (max-width: 480px) {
  .frame-hud { padding: 0 12px; gap: 10px; }
  .frame-hud__paper { display: none; }
  .frame__img { aspect-ratio: 4 / 3; }
  .frame--coda .frame__img { aspect-ratio: 4 / 3; }
  .caption__text { font-size: .96rem; }
  .title-spread__dek { font-size: 1rem; }
  .lightbox { padding: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  * { scroll-behavior: auto !important; }
  .caption { transition: none; opacity: 1; transform: none; }
  .frame__img { transition: none; }
}

snippets.js:
(function () {
  "use strict";

  var deck = document.getElementById("plates");
  var plates = Array.prototype.slice.call(document.querySelectorAll(".plate"));
  var curEl = document.getElementById("frameCur");
  var totalEl = document.getElementById("frameTotal");
  var progressBar = document.getElementById("progressBar");
  var prevBtn = document.getElementById("prevBtn");
  var nextBtn = document.getElementById("nextBtn");
  var toTop = document.getElementById("toTop");
  var toastEl = document.getElementById("toast");

  var total = plates.length;
  var current = 0; // index into plates
  var toastTimer = null;

  totalEl.textContent = pad(total);

  /* ---------- helpers ---------- */
  function pad(n) { return String(n).length < 2 ? "0" + n : String(n); }

  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("is-on");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("is-on");
    }, 1900);
  }

  function setCurrent(idx) {
    if (idx < 0) idx = 0;
    if (idx > total - 1) idx = total - 1;
    current = idx;
    var frame = parseInt(plates[idx].getAttribute("data-frame"), 10) || idx + 1;
    curEl.textContent = pad(frame);
    var pct = total > 1 ? (frame - 1) / (total - 1) * 100 : 0;
    progressBar.style.width = pct.toFixed(2) + "%";

    plates.forEach(function (p, i) {
      p.classList.toggle("is-active", i === idx);
    });
  }

  function goTo(idx, announce) {
    if (idx < 0) idx = 0;
    if (idx > total - 1) idx = total - 1;
    plates[idx].scrollIntoView({ behavior: "smooth", block: "start" });
    if (announce) {
      var frame = parseInt(plates[idx].getAttribute("data-frame"), 10) || idx + 1;
      toast("Plate " + frame + " of " + total);
    }
  }

  function next() { goTo(current + 1, true); }
  function prev() { goTo(current - 1, true); }

  /* ---------- active-plate tracking via IntersectionObserver ---------- */
  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(function (entries) {
      var best = null;
      entries.forEach(function (e) {
        if (e.isIntersecting && (!best || e.intersectionRatio > best.intersectionRatio)) {
          best = e;
        }
      });
      if (best) {
        var idx = plates.indexOf(best.target);
        if (idx !== -1 && idx !== current) setCurrent(idx);
      }
    }, { root: deck, threshold: [0.35, 0.55, 0.75] });
    plates.forEach(function (p) { io.observe(p); });
  } else {
    // fallback: scroll math
    deck.addEventListener("scroll", function () {
      var mid = deck.scrollTop + deck.clientHeight / 2;
      var idx = 0;
      for (var i = 0; i < plates.length; i++) {
        if (plates[i].offsetTop <= mid) idx = i;
      }
      if (idx !== current) setCurrent(idx);
    }, { passive: true });
  }

  /* ---------- controls ---------- */
  prevBtn.addEventListener("click", prev);
  nextBtn.addEventListener("click", next);
  if (toTop) {
    toTop.addEventListener("click", function () {
      goTo(0, false);
      toast("Back to the title spread");
    });
  }

  /* ---------- keyboard navigation ---------- */
  document.addEventListener("keydown", function (e) {
    if (lightboxOpen) {
      if (e.key === "Escape") { closeLightbox(); }
      return;
    }
    var tag = (e.target && e.target.tagName) || "";
    if (tag === "INPUT" || tag === "TEXTAREA") return;

    switch (e.key) {
      case "ArrowRight":
      case "ArrowDown":
      case "PageDown":
        e.preventDefault(); next(); break;
      case "ArrowLeft":
      case "ArrowUp":
      case "PageUp":
        e.preventDefault(); prev(); break;
      case "Home":
        e.preventDefault(); goTo(0, true); break;
      case "End":
        e.preventDefault(); goTo(total - 1, true); break;
      case " ":
        e.preventDefault(); e.shiftKey ? prev() : next(); break;
      default: break;
    }
  });

  /* ---------- lightbox / zoom ---------- */
  var lightbox = document.getElementById("lightbox");
  var lbImg = document.getElementById("lbImg");
  var lbCap = document.getElementById("lbCap");
  var lbClose = document.getElementById("lbClose");
  var lightboxOpen = false;
  var lastFocused = null;

  // duotone class carried over to the lightbox image
  var DUO_RE = /\bduo--[a-z]+\b/;

  function openLightbox(btn) {
    var duoCls = (btn.className.match(DUO_RE) || [""])[0];
    lbImg.className = "lightbox__img duo " + duoCls;

    var fig = btn.closest("figure");
    var cap = fig ? fig.querySelector(".caption") : null;
    if (cap) {
      var text = cap.querySelector(".caption__text");
      var credit = cap.querySelector(".caption__credit");
      lbCap.innerHTML =
        (text ? text.innerHTML : "") +
        (credit ? "<b>" + credit.textContent + "</b>" : "");
    } else {
      lbCap.innerHTML = "";
    }

    lastFocused = btn;
    lightbox.hidden = false;
    lightboxOpen = true;
    document.body.style.overflow = "hidden";
    lbClose.focus();
    toast("Zoomed — press Esc to close");
  }

  function closeLightbox() {
    lightbox.hidden = true;
    lightboxOpen = false;
    document.body.style.overflow = "";
    if (lastFocused && typeof lastFocused.focus === "function") lastFocused.focus();
  }

  document.querySelectorAll("[data-zoom]").forEach(function (btn) {
    btn.addEventListener("click", function () { openLightbox(btn); });
  });

  lbClose.addEventListener("click", closeLightbox);
  lightbox.addEventListener("click", function (e) {
    if (e.target === lightbox) closeLightbox();
  });

  /* ---------- init ---------- */
  setCurrent(0);

  // de-emphasise the scroll hint once the reader has moved on
  var hint = document.getElementById("scrollHint");
  if (hint) {
    var hintObserver = function () {
      if (current > 0) {
        hint.style.transition = "opacity .4s ease";
        hint.style.opacity = "0";
        deck.removeEventListener("scroll", hintObserver);
      }
    };
    deck.addEventListener("scroll", hintObserver, { passive: true });
  }
})();

snippets.css:
:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --sh-1: 0 1px 0 rgba(255, 255, 255, 0.03), 0 1px 2px rgba(0, 0, 0, 0.4);
  --sh-2: 0 8px 24px rgba(0, 0, 0, 0.45), 0 2px 6px rgba(0, 0, 0, 0.4);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  background: radial-gradient(1200px 600px at 80% -10%, rgba(198, 255, 58, 0.05), transparent 60%),
    radial-gradient(900px 500px at -10% 10%, rgba(255, 106, 43, 0.05), transparent 55%), var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  min-height: 100vh;
}

button {
  font-family: inherit;
  cursor: pointer;
}

:focus-visible {
  outline: 2px solid var(--neon);
  outline-offset: 2px;
  border-radius: 6px;
}

.shell {
  max-width: 1180px;
  margin: 0 auto;
  padding: 22px clamp(14px, 3vw, 28px) 48px;
}

/* ---------- Topbar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 22px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand__mark {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  font-weight: 900;
  font-size: 17px;
  letter-spacing: -0.02em;
  color: #0d0f12;
  background: linear-gradient(135deg, var(--neon), var(--neon-d));
  box-shadow: 0 6px 18px rgba(198, 255, 58, 0.25);
}

.brand__txt {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.brand__name {
  font-weight: 800;
  font-size: 18px;
  letter-spacing: -0.01em;
}

.brand__sub {
  font-size: 12px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 600;
}

.topbar__right {
  display: flex;
  align-items: center;
  gap: 10px;
}

.range {
  display: inline-flex;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 4px;
  gap: 2px;
}

.range__btn {
  border: 0;
  background: transparent;
  color: var(--ink-2);
  font-weight: 700;
  font-size: 13px;
  padding: 8px 14px;
  border-radius: 9px;
  transition: background 0.16s, color 0.16s, transform 0.1s;
}

.range__btn:hover {
  color: var(--ink);
}

.range__btn:active {
  transform: scale(0.96);
}

.range__btn.is-active {
  background: var(--neon);
  color: #0d0f12;
  box-shadow: 0 2px 8px rgba(198, 255, 58, 0.3);
}

.export {
  border: 1px solid var(--line-2);
  background: var(--surface-2);
  color: var(--ink);
  font-weight: 700;
  font-size: 13px;
  padding: 9px 16px;
  border-radius: 11px;
  transition: border-color 0.16s, background 0.16s, transform 0.1s;
}

.export:hover {
  border-color: var(--neon);
  background: var(--elevated);
}

.export:active {
  transform: scale(0.97);
}

/* ---------- KPI cards ---------- */
.kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 16px;
}

.kpi {
  background: linear-gradient(180deg, var(--surface), var(--surface-2));
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 16px 12px;
  box-shadow: var(--sh-1);
  position: relative;
  overflow: hidden;
  transition: border-color 0.18s, transform 0.18s;
}

.kpi:hover {
  border-color: var(--line-2);
  transform: translateY(-2px);
}

.kpi__eyebrow {
  display: block;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  font-weight: 700;
  color: var(--muted);
}

.kpi__row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-top: 8px;
}

.kpi__value {
  font-size: clamp(22px, 3vw, 28px);
  font-weight: 900;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.kpi__delta {
  font-size: 12px;
  font-weight: 800;
  padding: 3px 8px;
  border-radius: 999px;
  white-space: nowrap;
}

.kpi__delta.is-up {
  color: var(--ok);
  background: rgba(52, 211, 153, 0.14);
}

.kpi__delta.is-down {
  color: var(--danger);
  background: rgba(248, 113, 113, 0.14);
}

.kpi__spark {
  margin-top: 10px;
  height: 36px;
}

.kpi__spark svg {
  width: 100%;
  height: 36px;
  display: block;
}

/* ---------- Grid + panels ---------- */
.grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 16px;
}

.panel {
  background: linear-gradient(180deg, var(--surface), var(--surface-2));
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 18px;
  box-shadow: var(--sh-2);
}

.panel--wide {
  grid-column: 1 / -1;
}

.panel__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.panel__title {
  margin: 0;
  font-size: 16px;
  font-weight: 800;
  letter-spacing: -0.01em;
}

.panel__hint {
  margin: 3px 0 0;
  font-size: 12.5px;
  color: var(--muted);
}

.legend {
  display: flex;
  gap: 14px;
  flex-shrink: 0;
}

.legend__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 600;
  color: var(--ink-2);
}

.dot {
  width: 9px;
  height: 9px;
  border-radius: 3px;
  display: inline-block;
}

.dot--neon {
  background: var(--neon);
}

.dot--orange {
  background: var(--orange);
}

/* ---------- Revenue chart ---------- */
.chart {
  position: relative;
}

.chart svg {
  width: 100%;
  height: auto;
  display: block;
  overflow: visible;
}

.chart .axis-line {
  stroke: var(--line);
  stroke-width: 1;
}

.chart .axis-label {
  fill: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

.chart .hover-line {
  stroke: var(--line-2);
  stroke-width: 1;
  stroke-dasharray: 3 3;
}

.chart .hover-dot {
  stroke: var(--bg);
  stroke-width: 2;
}

.chart__tip {
  position: absolute;
  pointer-events: none;
  background: var(--elevated);
  border: 1px solid var(--line-2);
  border-radius: 10px;
  padding: 9px 11px;
  font-size: 12px;
  box-shadow: var(--sh-2);
  transform: translate(-50%, -118%);
  white-space: nowrap;
  z-index: 5;
}

.chart__tip b {
  display: block;
  font-size: 11px;
  color: var(--muted);
  font-weight: 700;
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.chart__tip .tip-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.chart__tip .tip-row + .tip-row {
  margin-top: 3px;
}

/* ---------- Donut ---------- */
.donut {
  position: relative;
  width: 180px;
  max-width: 100%;
  margin: 4px auto 6px;
}

.donut svg {
  width: 100%;
  height: auto;
  display: block;
}

.donut .arc {
  cursor: pointer;
  transition: opacity 0.16s, transform 0.16s;
  transform-origin: 90px 90px;
}

.donut .arc:hover {
  opacity: 0.85;
}

.donut .arc.is-dim {
  opacity: 0.3;
}

.donut__center {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  text-align: center;
  pointer-events: none;
}

.donut__total {
  font-size: 30px;
  font-weight: 900;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.donut__label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
  font-weight: 700;
}

.mix {
  list-style: none;
  margin: 6px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.mix__row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 8px;
  border-radius: 9px;
  transition: background 0.14s;
}

.mix__row:hover {
  background: var(--surface);
}

.mix__swatch {
  width: 11px;
  height: 11px;
  border-radius: 3px;
  flex-shrink: 0;
}

.mix__name {
  font-size: 13px;
  font-weight: 600;
  flex: 1;
}

.mix__count {
  font-size: 13px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.mix__pct {
  font-size: 12px;
  color: var(--muted);
  font-weight: 700;
  min-width: 38px;
  text-align: right;
}

/* ---------- Cohort heat grid ---------- */
.scale {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  color: var(--muted);
  font-weight: 600;
  flex-shrink: 0;
}

.scale__bar {
  width: 90px;
  height: 10px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(198, 255, 58, 0.12), var(--neon));
}

.cohort {
  display: grid;
  gap: 4px;
  overflow-x: auto;
}

.cohort__head,
.cohort__row {
  display: grid;
  grid-template-columns: 92px repeat(var(--cols, 6), 1fr);
  gap: 4px;
  align-items: center;
  min-width: 460px;
}

.cohort__corner,
.cohort__colhead {
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  text-align: center;
  padding-bottom: 2px;
}

.cohort__corner {
  text-align: left;
}

.cohort__label {
  font-size: 12px;
  font-weight: 700;
  color: var(--ink-2);
}

.cell {
  height: 38px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  font-size: 12px;
  font-weight: 800;
  color: #0d0f12;
  cursor: default;
  transition: transform 0.12s, box-shadow 0.12s;
  font-variant-numeric: tabular-nums;
}

.cell:hover {
  transform: scale(1.06);
  box-shadow: 0 0 0 2px var(--line-2);
  z-index: 2;
}

.cell--empty {
  background: var(--surface) !important;
  color: transparent;
  cursor: default;
}

.cell--empty:hover {
  transform: none;
  box-shadow: none;
}

/* ---------- Top classes bars ---------- */
.bars {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.bar__top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}

.bar__name {
  font-size: 13.5px;
  font-weight: 700;
}

.bar__sub {
  font-size: 11px;
  color: var(--muted);
  font-weight: 600;
  margin-left: 8px;
}

.bar__val {
  font-size: 13.5px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
}

.bar__track {
  height: 10px;
  background: var(--surface);
  border-radius: 999px;
  overflow: hidden;
  border: 1px solid var(--line);
}

.bar__fill {
  height: 100%;
  border-radius: 999px;
  width: 0;
  background: linear-gradient(90deg, var(--neon-d), var(--neon));
  transition: width 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}

.bars li:nth-child(2) .bar__fill {
  background: linear-gradient(90deg, #c98f2a, var(--orange));
}

.bars li:nth-child(3) .bar__fill {
  background: linear-gradient(90deg, #6aa3ff, #9ec2ff);
}

/* ---------- Footer + toast ---------- */
.foot {
  margin-top: 26px;
  text-align: center;
  font-size: 12px;
  color: var(--muted);
}

.toast {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translate(-50%, 20px);
  background: var(--elevated);
  border: 1px solid var(--line-2);
  color: var(--ink);
  font-weight: 600;
  font-size: 13.5px;
  padding: 11px 18px;
  border-radius: 12px;
  box-shadow: var(--sh-2);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
  z-index: 50;
}

.toast.is-show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Responsive ---------- */
@media (max-width: 900px) {
  .kpis {
    grid-template-columns: repeat(2, 1fr);
  }
  .grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .shell {
    padding: 16px 12px 40px;
  }
  .topbar {
    gap: 12px;
  }
  .topbar__right {
    width: 100%;
    justify-content: space-between;
  }
  .kpis {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }
  .kpi__value {
    font-size: 22px;
  }
  .panel {
    padding: 14px;
  }
  .panel__head {
    flex-direction: column;
  }
  .legend {
    margin-top: 2px;
  }
}

