/* ── Design tokens ── */
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Outer background ── */
.bg {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 32px 16px;
  background: radial-gradient(circle at 18% 14%, rgba(201, 166, 73, 0.18), transparent 52%),
    linear-gradient(160deg, #14213b 0%, #0f1d36 100%);
}

/* ── Sheet card ── */
.sheet {
  width: min(680px, 100%);
  background: var(--bone);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: 0 40px 100px rgba(15, 29, 54, 0.55);
  display: flex;
  flex-direction: column;
}

/* ── Header ── */
.sheet-head {
  padding: 22px 26px 18px;
  border-bottom: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--navy-d);
}
.kicker {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold-light);
  font-weight: 700;
}
.sheet-head h2 {
  font-family: var(--font-display);
  font-size: 1.7rem;
  font-weight: 700;
  letter-spacing: -0.005em;
  color: var(--bone);
  margin-top: 2px;
}
.brand-mark {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 700;
  display: grid;
  place-items: center;
  flex-shrink: 0;
}

/* ── Guest bar ── */
.guest-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  border-bottom: 1px solid var(--line);
  background: var(--cream);
}
.guest-info {
  display: flex;
  flex-direction: column;
  padding: 10px 20px;
  border-right: 1px solid var(--line);
  gap: 2px;
  min-width: 0;
}
.guest-info:last-child {
  border-right: none;
}
.g-label {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  font-weight: 700;
}
.g-val {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--navy-d);
  white-space: nowrap;
}
.g-val.mono {
  font-family: var(--font-mono);
  font-size: 0.84rem;
  font-variant-numeric: tabular-nums;
}

/* ── Table ── */
.table-wrap {
  overflow-x: auto;
  flex: 1;
}
.folio-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.86rem;
}
.folio-table thead {
  background: var(--cream);
  border-bottom: 1px solid var(--line-strong);
}
.folio-table th {
  padding: 9px 14px;
  text-align: left;
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  font-weight: 700;
}
.col-date {
  width: 96px;
}
.col-ref {
  width: 80px;
}
.col-amt {
  width: 88px;
  text-align: right;
}
.col-act {
  width: 44px;
}
.folio-table td {
  padding: 9px 14px;
  border-bottom: 1px solid var(--line);
  vertical-align: middle;
}
.folio-table tbody tr:last-child td {
  border-bottom: none;
}
.folio-table tbody tr:hover {
  background: rgba(201, 166, 73, 0.04);
}
.folio-table tbody tr.is-voided {
  opacity: 0.42;
}
.folio-table tbody tr.is-voided td {
  text-decoration: line-through;
  color: var(--warm-gray);
}

.td-date {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  color: var(--warm-gray);
  font-variant-numeric: tabular-nums;
}
.td-desc {
  font-weight: 500;
  color: var(--ink);
}
.td-cat {
  display: inline-block;
  margin-left: 6px;
  font-size: 0.68rem;
  padding: 2px 7px;
  border-radius: 999px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  vertical-align: middle;
}
.cat-room {
  background: rgba(26, 43, 74, 0.1);
  color: var(--navy-2);
}
.cat-tax {
  background: rgba(108, 114, 128, 0.1);
  color: var(--warm-gray);
}
.cat-fb {
  background: rgba(74, 119, 82, 0.12);
  color: var(--success);
}
.cat-spa {
  background: rgba(74, 109, 160, 0.12);
  color: var(--info);
}
.cat-minibar {
  background: rgba(201, 166, 73, 0.15);
  color: var(--gold-d);
}
.cat-other {
  background: rgba(179, 66, 50, 0.1);
  color: var(--danger);
}

.td-ref {
  font-family: var(--font-mono);
  font-size: 0.76rem;
  color: var(--warm-gray);
}
.td-amt {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  text-align: right;
  color: var(--ink);
}
.td-act {
  text-align: center;
}
.btn-void {
  background: none;
  border: 1px solid var(--line-strong);
  border-radius: var(--r-sm);
  padding: 4px 8px;
  font-size: 0.72rem;
  color: var(--warm-gray);
  cursor: pointer;
  font-family: inherit;
  white-space: nowrap;
}
.btn-void:hover {
  background: rgba(179, 66, 50, 0.08);
  color: var(--danger);
  border-color: var(--danger);
}
.btn-void.is-voided {
  color: var(--warm-gray);
  cursor: not-allowed;
}

/* ── Totals ── */
.totals-block {
  border-top: 2px solid var(--line-strong);
  background: var(--cream);
  padding: 14px 26px;
}
.totals-inner {
  max-width: 320px;
  margin-left: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.total-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 0.88rem;
  color: var(--ink-2);
}
.total-row .mono {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}
.total-row--bold {
  font-weight: 700;
  color: var(--ink);
  padding-top: 6px;
  border-top: 1px solid var(--line-strong);
  margin-top: 4px;
}
.total-row.separator {
  padding-top: 8px;
  border-top: 1px solid var(--line);
  margin-top: 4px;
}
.negative {
  color: var(--success) !important;
}
.total-row--balance {
  font-size: 1rem;
  font-weight: 700;
  color: var(--navy-d);
  padding-top: 6px;
  border-top: 2px solid var(--line-strong);
  margin-top: 4px;
}

/* ── Add charge bar ── */
.add-charge-bar {
  display: flex;
  gap: 8px;
  padding: 14px 26px;
  border-top: 1px solid var(--line);
  align-items: center;
  flex-wrap: wrap;
}
.charge-select {
  flex: 1;
  min-width: 200px;
  font-family: inherit;
  font-size: 0.88rem;
  background: var(--cream);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-sm);
  padding: 9px 12px;
  color: var(--ink);
  outline: none;
  cursor: pointer;
}
.charge-select:focus {
  border-color: var(--gold);
}
.btn-add {
  font-family: inherit;
  font-size: 0.86rem;
  font-weight: 600;
  padding: 9px 20px;
  background: var(--navy);
  color: var(--bone);
  border: none;
  border-radius: 999px;
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
}
.btn-add:hover {
  background: var(--navy-2);
}

/* ── Footer ── */
.sheet-foot {
  padding: 16px 26px 22px;
  background: var(--bone);
  border-top: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.foot-acts {
  display: flex;
  gap: 8px;
  margin-left: auto;
}
.ghost,
.primary {
  font-family: inherit;
  font-weight: 600;
  font-size: 0.86rem;
  padding: 11px 18px;
  border-radius: 999px;
  cursor: pointer;
}
.ghost {
  background: transparent;
  border: 1px solid var(--line-strong);
  color: var(--ink-2);
}
.ghost:hover {
  background: var(--cream);
  border-color: var(--navy-2);
  color: var(--navy-d);
}
.primary {
  background: var(--navy);
  color: var(--bone);
  border: none;
}
.primary:hover {
  background: var(--navy-d);
}
.primary:disabled {
  background: var(--warm-gray);
  cursor: not-allowed;
  opacity: 0.6;
}

/* ── Paid stamp ── */
.paid-stamp {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--success);
  border: 3px solid var(--success);
  border-radius: var(--r-sm);
  padding: 6px 18px;
  text-transform: uppercase;
  transform: rotate(-2deg);
  opacity: 0.9;
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 22px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: 0 10px 30px rgba(22, 30, 44, 0.25);
  z-index: 100;
  white-space: nowrap;
}

/* ── Responsive ── */
@media (max-width: 560px) {
  .guest-bar {
    flex-direction: column;
  }
  .guest-info {
    border-right: none;
    border-bottom: 1px solid var(--line);
  }
  .guest-info:last-child {
    border-bottom: none;
  }
  .add-charge-bar {
    flex-direction: column;
  }
  .charge-select {
    min-width: 0;
    width: 100%;
  }
  .foot-acts {
    width: 100%;
    justify-content: flex-end;
  }
  .folio-table .col-ref {
    display: none;
  }
}

