.btn.ghost {
  background: var(--white);
  border: 1px solid var(--line-2);
  color: var(--ink-2);
}
.btn.ghost:hover {
  background: var(--teal-50);
  border-color: var(--teal);
  color: var(--teal-d);
}
.btn.solid {
  background: var(--teal-d);
  color: #fff;
  box-shadow: var(--shadow-1);
}
.btn.solid:hover {
  background: var(--teal-700);
}

/* ── Filter bar ── */
.filterbar {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 12px 16px;
  box-shadow: var(--shadow-1);
}
.switch {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  user-select: none;
}
.switch input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}
.track {
  position: relative;
  width: 40px;
  height: 23px;
  border-radius: 999px;
  background: #cbdbd8;
  transition: background 0.2s;
  flex-shrink: 0;
}
.thumb {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 3px rgba(16, 50, 47, 0.3);
  transition: transform 0.2s;
}
.switch input:checked + .track {
  background: var(--teal);
}
.switch input:checked + .track .thumb {
  transform: translateX(17px);
}
.switch input:focus-visible + .track {
