  gap: 12px;
  margin-left: auto;
}
.lg {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--muted);
}
.dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  display: inline-block;
}
.dot-ok {
  background: var(--ok);
}
.dot-high {
  background: var(--danger);
}
.dot-low {
  background: var(--warn);
