}

/* ── Panel ── */
.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  box-shadow: var(--shadow-1);
  overflow: hidden;
}
.panel.is-hidden {
  display: none;
}

.panel-head {
  width: 100%;
  border: none;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  cursor: pointer;
  text-align: left;
  transition: background 0.15s;
}
.panel-head:hover {
  background: #f6fbfa;
}
.panel-title {
  display: flex;
  flex-direction: column;
  gap: 1px;
}
.panel-name {
