.pill {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  white-space: nowrap;
}
.pill-flag {
  background: rgba(212, 80, 62, 0.12);
  color: var(--danger);
}
.pill-flag.is-clear {
