  grid-template-columns: 1fr auto;
  grid-template-areas:
    "main value"
    "bar  bar"
    "ref  ref";
  column-gap: 16px;
  row-gap: 8px;
  padding: 14px 18px;
  border-top: 1px solid var(--line);
  transition: background 0.15s;
