}
.r-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--ink);
}
.r-flag {
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  padding: 2px 8px;
  border-radius: 999px;
  text-transform: uppercase;
  white-space: nowrap;
}
.flag-ok {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}
.flag-high {
  background: rgba(212, 80, 62, 0.14);
  color: var(--danger);
}
.flag-low {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}

.r-value {
  grid-area: value;
  text-align: right;
  white-space: nowrap;
}
.r-value strong {
  font-size: 1.15rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: var(--ink);
}
.r-value .unit {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
  margin-left: 4px;
}
.row[data-status="high"] .r-value strong {
  color: var(--danger);
}
.row[data-status="low"] .r-value strong {
  color: var(--warn);
}

/* ── Range bar ── */
.r-bar {
  grid-area: bar;
  position: relative;
  height: 6px;
  border-radius: 999px;
  background: #e7eeec;
  margin-top: 2px;
}
/* the in-range band */
.r-bar::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 18%;
  right: 18%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--teal-50), #cdeae6);
}
/* the value marker */
.r-marker {
  position: absolute;
  top: 50%;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: var(--ok);
  border: 2.5px solid var(--white);
  box-shadow: 0 1px 4px rgba(16, 50, 47, 0.28);
  transform: translate(-50%, -50%);
  transition: left 0.45s cubic-bezier(0.22, 1, 0.36, 1);
  z-index: 2;
}
.row[data-status="high"] .r-marker {
  background: var(--danger);
}
.row[data-status="low"] .r-marker {
  background: var(--warn);
}

.r-ref {
  grid-area: ref;
  font-size: 0.76rem;
  font-weight: 500;
  color: var(--muted);
}

/* ── Footer ── */
.labs-foot {
  margin-top: 6px;
  padding: 4px 4px 0;
}
.labs-foot p {
  font-size: 0.82rem;
  color: var(--muted);
  line-height: 1.55;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}
.toast[hidden] {
  display: none;
}

@media (max-width: 520px) {
  .labs {
    padding: 24px 14px 48px;
  }
  .head-top {
    flex-direction: column;
  }
  .head-actions {
    width: 100%;
  }
  .head-actions .btn {
    flex: 1;
    justify-content: center;
  }
  .legend {
    margin-left: 0;
    width: 100%;
  }
  .row {
    grid-template-columns: 1fr;
    grid-template-areas:
      "main"
      "value"
      "bar"
      "ref";
    row-gap: 7px;
  }
  .r-value {
    text-align: left;
  }
}

