  justify-content: space-between;
  gap: 18px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: var(--ink);
}
.brand-mark {
  display: inline-grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 11px;
  background: linear-gradient(150deg, var(--teal), var(--teal-700));
  color: #fff;
  box-shadow: 0 6px 14px rgba(12, 122, 115, 0.32);
}
.brand-name {
  display: inline-flex;
  flex-direction: column;
  line-height: 1.05;
  font-size: 1.02rem;
}
.brand-dot {
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--teal-d);
}
.brand-name.big {
  font-size: 1.4rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}
.nav-links a {
  padding: 8px 14px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.92rem;
  color: var(--ink-2);
  transition: color 0.15s, background 0.15s;
}
.nav-links a:hover {
  color: var(--teal-d);
  background: var(--teal-50);
}
.nav-cta {
  display: flex;
  align-items: center;
  gap: 10px;
}
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: 10px;
  padding: 10px 9px;
  cursor: pointer;
}
.nav-toggle span {
  width: 20px;
  height: 2px;
  border-radius: 2px;
  background: var(--ink);
  transition: transform 0.2s, opacity 0.2s;
}
.nav-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.nav-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}
.nav-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ── Sections ── */
.section {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 88px 24px;
}
.section-head {
  max-width: 640px;
  margin: 0 auto 44px;
  text-align: center;
}
.kicker {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--coral-d);
  margin-bottom: 12px;
}
.kicker.light {
  color: #ffd9cf;
}
h1,
h2,
h3 {
  letter-spacing: -0.02em;
}
.section-head h2 {
  font-size: clamp(1.7rem, 3.6vw, 2.3rem);
  font-weight: 800;
}
.section-sub {
  margin-top: 12px;
  color: var(--muted);
  font-size: 1.04rem;
}
.grid {
  display: grid;
  gap: 18px;
}

/* ── Hero ── */
.hero {
  position: relative;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 56px 24px 72px;
  overflow: hidden;
}
.blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(8px);
  z-index: 0;
  pointer-events: none;
}
.blob-a {
  width: 460px;
  height: 460px;
  top: -140px;
  right: -120px;
  background: radial-gradient(circle at 30% 30%, rgba(255, 122, 102, 0.22), transparent 62%);
}
.blob-b {
  width: 420px;
  height: 420px;
  bottom: -180px;
  left: -120px;
  background: radial-gradient(circle at 60% 40%, rgba(18, 156, 147, 0.18), transparent 64%);
}
.hero-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 48px;
  align-items: center;
}
.hero-copy {
  max-width: 560px;
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  background: var(--coral-soft);
  color: var(--coral-d);
  font-size: 0.82rem;
  font-weight: 700;
  padding: 7px 14px;
  border-radius: 999px;
  margin-bottom: 20px;
}
.eyebrow .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--coral-d);
  box-shadow: 0 0 0 0 rgba(240, 94, 72, 0.5);
  animation: pulse 2.2s ease-out infinite;
}
@keyframes pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(240, 94, 72, 0.5);
  }
  70% {
    box-shadow: 0 0 0 8px rgba(240, 94, 72, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(240, 94, 72, 0);
  }
}
.hero h1 {
  font-size: clamp(2.2rem, 5.2vw, 3.4rem);
  font-weight: 800;
  line-height: 1.06;
}
.hl {
  position: relative;
  color: var(--teal-d);
  white-space: nowrap;
}
.hl::after {
  content: "";
  position: absolute;
  left: -2px;
  right: -2px;
  bottom: 0.06em;
  height: 0.34em;
  background: var(--coral-soft);
  border-radius: 4px;
  z-index: -1;
}
.lede {
  margin-top: 20px;
  font-size: 1.1rem;
  color: var(--ink-2);
  max-width: 50ch;
}
.hero-actions {
  margin-top: 28px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.hero-pills {
  margin-top: 26px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px 20px;
  list-style: none;
}
.hero-pills li {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ink-2);
}
.hero-pills li span {
  display: inline-grid;
  place-items: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--teal-50);
  color: var(--teal-d);
  font-size: 0.72rem;
  font-weight: 800;
}

/* Hero card */
.hero-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-xl);
  padding: 24px;
  box-shadow: var(--shadow-soft);
  position: relative;
}
.hero-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(150deg, rgba(255, 122, 102, 0.4), rgba(18, 156, 147, 0.32));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}
.hc-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.hc-tag {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--muted);
}
.hc-time {
  margin: 14px 0 16px;
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.hc-num {
  font-size: 2.6rem;
  font-weight: 800;
  color: var(--teal-d);
  line-height: 1;
  letter-spacing: -0.03em;
}
.hc-unit {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ink-2);
}
.hc-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 18px;
}
.hc-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 12px;
  border-radius: var(--r-sm);
  font-size: 0.92rem;
  transition: background 0.15s;
}
.hc-list li:hover {
  background: var(--teal-50);
}
.hc-list li span:nth-of-type(1) {
  flex: 1;
  color: var(--ink-2);
  font-weight: 500;
}
.hc-list li strong {
  font-weight: 700;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.hc-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
}
.hc-dot.teal {
  background: var(--teal);
}
.hc-dot.coral {
  background: var(--coral);
}
.hc-foot {
  margin-top: 14px;
  font-size: 0.82rem;
  color: var(--muted);
  text-align: center;
}

/* ── Badges ── */
.badge {
  display: inline-flex;
  align-items: center;
  font-size: 0.74rem;
  font-weight: 700;
  padding: 4px 11px;
  border-radius: 999px;
  white-space: nowrap;
}
.badge.ok {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}
.badge.warn {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.badge.closed {
  background: rgba(212, 80, 62, 0.14);
  color: var(--danger);
}

/* ── Services grid ── */
.services-grid {
  grid-template-columns: repeat(3, 1fr);
}
.svc {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 26px 24px;
  box-shadow: var(--shadow-1);
  transition: transform 0.18s ease, box-shadow 0.18s, border-color 0.18s;
  outline-offset: 4px;
}
.svc:hover,
.svc:focus-visible {
  transform: translateY(-4px);
  box-shadow: var(--shadow-2);
  border-color: rgba(18, 156, 147, 0.4);
}
.svc-icon {
  display: inline-grid;
  place-items: center;
  width: 50px;
  height: 50px;
  border-radius: 15px;
  margin-bottom: 16px;
}
.svc-icon.teal {
  background: var(--teal-50);
  color: var(--teal-d);
}
.svc-icon.coral {
  background: var(--coral-soft);
  color: var(--coral-d);
}
.svc h3 {
  font-size: 1.16rem;
  font-weight: 700;
}
.svc p {
  margin-top: 8px;
  color: var(--ink-2);
  font-size: 0.95rem;
}
.svc-link {
  display: inline-block;
  margin-top: 14px;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--teal-d);
  letter-spacing: 0.01em;
}

/* ── Same-day band ── */
.band {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, var(--teal-d), var(--teal-700) 70%, #084f4a);
  color: #fff;
}
.band-blob {
  position: absolute;
  width: 520px;
  height: 520px;
  border-radius: 50%;
  top: -200px;
  right: -120px;
  background: radial-gradient(circle, rgba(255, 122, 102, 0.32), transparent 60%);
  pointer-events: none;
}
.band-inner {
  position: relative;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 72px 24px;
  display: grid;
  grid-template-columns: 1.25fr 0.75fr;
  gap: 48px;
  align-items: center;
}
.band-copy h2 {
  font-size: clamp(1.7rem, 3.6vw, 2.4rem);
  font-weight: 800;
  margin-top: 6px;
}
.band-copy p {
  margin-top: 14px;
  color: rgba(255, 255, 255, 0.82);
  font-size: 1.06rem;
  max-width: 50ch;
}
.band-actions {
  margin-top: 28px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}
.band-stats {
  display: grid;
  gap: 14px;
}
.band-stat {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: var(--r-md);
  padding: 16px 20px;
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.band-stat .stat-num {
  font-size: 1.8rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #fff;
  font-variant-numeric: tabular-nums;
  min-width: 78px;
}
.band-stat dd {
  font-size: 0.92rem;
  color: rgba(255, 255, 255, 0.78);
}

/* ── Doctors ── */
.doctors-grid {
  grid-template-columns: repeat(4, 1fr);
}
.doc {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 24px 22px;
  box-shadow: var(--shadow-1);
  transition: transform 0.18s, box-shadow 0.18s;
}
.doc:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-2);
}
.doc-avatar {
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  font-weight: 800;
  font-size: 1.1rem;
  color: #fff;
  margin-bottom: 14px;
  background: linear-gradient(150deg, var(--teal), var(--teal-700));
}
.doc-avatar.coral-av {
  background: linear-gradient(150deg, var(--coral), var(--coral-d));
  color: #5a2419;
}
.doc-avatar.warm-av {
  background: linear-gradient(150deg, #f6b352, #e0892c);
}
.doc-avatar.teal-av {
  background: linear-gradient(150deg, #2bbcae, var(--teal-d));
}
.doc h3 {
  font-size: 1.06rem;
  font-weight: 700;
}
.doc-spec {
  margin-top: 3px;
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--teal-d);
}
.doc-bio {
  margin: 10px 0 14px;
  font-size: 0.9rem;
  color: var(--ink-2);
}

/* ── Hours + location ── */
.visit-grid {
  display: grid;
  grid-template-columns: 1fr 1.1fr;
  gap: 22px;
}
.visit-card,
.map-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-1);
}
.visit-card {
  padding: 32px;
}
.visit-card h2 {
  font-size: 1.5rem;
  font-weight: 800;
  margin-top: 6px;
}
.hours {
  list-style: none;
  margin: 20px 0 0;
  border-top: 1px solid var(--line);
}
.hours li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 4px;
  border-bottom: 1px solid var(--line);
  font-size: 0.95rem;
}
.hours li span:first-child {
  font-weight: 600;
  color: var(--ink-2);
}
.hours li span:last-child {
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.hours li.is-today {
  background: var(--teal-50);
  border-radius: var(--r-sm);
  padding-left: 12px;
  padding-right: 12px;
  margin: 0 -8px;
  border-bottom-color: transparent;
}
.hours li.is-today span:first-child {
  color: var(--teal-700);
}
.hours .closed {
  color: var(--danger);
  font-weight: 600;
}
.visit-note {
  margin-top: 18px;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ink-2);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--teal-50);
  border-radius: 999px;
  padding: 9px 16px;
}
.visit-note.is-closed {
  background: var(--coral-soft);
  color: var(--coral-d);
}

.map-card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.map-art {
  position: relative;
  height: 220px;
  background: linear-gradient(160deg, #d6ece8, #c7e3df 60%, #e3f3f0);
  overflow: hidden;
}
.map-road {
  position: absolute;
  background: rgba(255, 255, 255, 0.85);
}
.map-road.r1 {
  height: 14px;
  left: 0;
  right: 0;
  top: 58%;
  transform: rotate(-4deg);
}
.map-road.r2 {
  width: 14px;
  top: 0;
  bottom: 0;
  left: 38%;
}
.map-block {
  position: absolute;
  border-radius: 6px;
  background: rgba(18, 156, 147, 0.16);
}
.map-block.b1 {
  width: 64px;
  height: 48px;
  left: 12%;
  top: 18%;
}
.map-block.b2 {
  width: 80px;
  height: 60px;
  right: 14%;
  top: 14%;
  background: rgba(255, 122, 102, 0.18);
}
.map-block.b3 {
  width: 70px;
  height: 50px;
  right: 22%;
  bottom: 12%;
}
.map-pin {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -100%);
  color: var(--coral-d);
  filter: drop-shadow(0 6px 8px rgba(16, 50, 47, 0.25));
  animation: bob 2.4s ease-in-out infinite;
}
@keyframes bob {
  0%,
  100% {
    transform: translate(-50%, -100%);
  }
  50% {
    transform: translate(-50%, -116%);
  }
}
.map-info {
  padding: 22px 24px 24px;
}
.map-info h3 {
  font-size: 1.12rem;
  font-weight: 700;
}
.map-info p {
  margin-top: 6px;
  color: var(--ink-2);
  font-size: 0.95rem;
}
.map-actions {
  margin-top: 16px;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.map-fine {
  margin-top: 16px;
  font-size: 0.82rem;
  color: var(--muted);
}

/* ── Book CTA ── */
.book {
  padding-top: 24px;
}
.book-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-xl);
  overflow: hidden;
  box-shadow: var(--shadow-soft);
}
.book-copy {
  padding: 44px;
  background: linear-gradient(155deg, var(--teal-50), #dff1ee);
}
.book-copy h2 {
  font-size: 1.7rem;
  font-weight: 800;
  margin-top: 6px;
}
.book-copy p {
  margin-top: 12px;
  color: var(--ink-2);
}
.book-points {
  margin-top: 22px;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.book-points li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.94rem;
  font-weight: 600;
  color: var(--ink-2);
}
.book-points li span {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--teal-d);
  color: #fff;
  font-size: 0.74rem;
  font-weight: 800;
}
.book-form {
  padding: 44px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.field > span {
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--ink-2);
}
.field-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.field input,
.field select {
  font: inherit;
  font-size: 0.95rem;
  padding: 12px 14px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  background: var(--white);
  color: var(--ink);
  transition: border-color 0.15s, box-shadow 0.15s;
}
.field input:focus,
.field select:focus {
  outline: none;
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(18, 156, 147, 0.16);
}
.field input.invalid {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(212, 80, 62, 0.14);
}
.book-fine {
  font-size: 0.8rem;
  color: var(--muted);
  text-align: center;
}

/* ── Footer ── */
.footer {
  background: var(--ink);
  color: rgba(255, 255, 255, 0.78);
  margin-top: 40px;
}
.footer-grid {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 56px 24px 36px;
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  gap: 36px;
}
.foot-brand .brand-name {
  color: #fff;
  margin-bottom: 12px;
}
.foot-brand .brand-dot {
  color: var(--coral);
}
.foot-brand p {
  font-size: 0.95rem;
  max-width: 36ch;
}
.foot-col h4 {
  color: #fff;
  font-size: 0.86rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 14px;
}
.foot-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  font-size: 0.94rem;
}
.foot-col li span {
  display: inline-block;
  min-width: 78px;
  color: rgba(255, 255, 255, 0.6);
}
.foot-col a:hover {
  color: var(--coral);
}
.footer-bar {
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 20px 24px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 0.85rem;
}
.footer-bar a:hover {
  color: var(--coral);
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%) translateY(12px);
  background: var(--ink);
  color: #fff;
  padding: 13px 22px;
  border-radius: 999px;
  font-size: 0.92rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 60;
  max-width: 90vw;
  opacity: 0;
  transition: opacity 0.22s ease, transform 0.22s ease;
}
.toast:not([hidden]) {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}
.toast .toast-mark {
  color: var(--coral);
  margin-right: 6px;
}

/* ── Reveal on scroll ── */
.reveal {
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 0.55s ease, transform 0.55s ease;
}
.reveal.is-in {
  opacity: 1;
  transform: none;
}

/* ── Responsive ── */
@media (max-width: 940px) {
  .hero-grid,
  .band-inner,
  .visit-grid,
  .book-card {
    grid-template-columns: 1fr;
  }
  .hero-card {
    max-width: 460px;
  }
  .services-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .doctors-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .book-copy {
    padding: 36px;
  }
}

@media (max-width: 520px) {
  .nav-links {
    position: absolute;
    top: calc(100% + 8px);
    right: 16px;
    left: 16px;
    flex-direction: column;
    align-items: stretch;
    gap: 2px;
    background: var(--white);
    border: 1px solid var(--line);
    border-radius: var(--r-md);
    padding: 8px;
    box-shadow: var(--shadow-soft);
    opacity: 0;
    transform: translateY(-8px);
    pointer-events: none;
    transition: opacity 0.2s, transform 0.2s;
  }
  .nav-links.is-open {
    opacity: 1;
    transform: none;
    pointer-events: auto;
  }
  .nav-links a {
    padding: 12px 14px;
  }
  .nav-toggle {
    display: flex;
  }
  .nav-cta .btn-primary {
    display: none;
  }
  .section {
    padding: 60px 18px;
  }
  .hero {
    padding: 36px 18px 56px;
  }
  .hero-actions {
    flex-direction: column;
    align-items: stretch;
  }
  .hero-actions .btn {
    width: 100%;
  }
  .services-grid,
  .doctors-grid {
    grid-template-columns: 1fr;
  }
  .band-inner {
    padding: 56px 18px;
  }
  .band-actions {
    flex-direction: column;
    align-items: stretch;
  }
  .visit-card,
  .book-copy,
  .book-form {
    padding: 28px 22px;
  }
  .field-row {
    grid-template-columns: 1fr;
  }
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
  .reveal {
    opacity: 1;
    transform: none;
  }
}

