(function () {
  "use strict";

  /* ── Toast helper ── */
  var toastEl = document.getElementById("toast");
  var toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.innerHTML = '<span class="toast-mark" aria-hidden="true">✓</span>' + msg;
    toastEl.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.hidden = true;
    }, 3000);
  }

  /* ── Sticky nav shadow ── */
  var nav = document.getElementById("nav");
  function onScroll() {
    if (!nav) return;
    nav.classList.toggle("is-stuck", window.scrollY > 8);
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  /* ── Mobile nav toggle ── */
  var navToggle = document.getElementById("navToggle");
  var navLinks = document.getElementById("navLinks");
  function closeNav() {
    if (!navToggle || !navLinks) return;
    navLinks.classList.remove("is-open");
    navToggle.setAttribute("aria-expanded", "false");
    navToggle.setAttribute("aria-label", "Open menu");
  }
  if (navToggle && navLinks) {
    navToggle.addEventListener("click", function () {
      var open = navLinks.classList.toggle("is-open");
      navToggle.setAttribute("aria-expanded", open ? "true" : "false");
      navToggle.setAttribute("aria-label", open ? "Close menu" : "Open menu");
    });
    navLinks.addEventListener("click", function (e) {
      if (e.target.closest("a")) closeNav();
    });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape") closeNav();
    });
  }

  /* ── Smooth-scroll for in-page links + close mobile nav ── */
  document.querySelectorAll('a[data-link][href^="#"]').forEach(function (a) {
    a.addEventListener("click", function (e) {
      var id = a.getAttribute("href");
      if (id.length < 2) return;
      var target = document.querySelector(id);
      if (!target) return;
      e.preventDefault();
      closeNav();
      target.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });

  /* ── Reveal on scroll ── */
  var reveals = document.querySelectorAll(".reveal");
  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-in");
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -40px 0px" }
    );
    reveals.forEach(function (el) {
      io.observe(el);
    });
  } else {
    reveals.forEach(function (el) {
      el.classList.add("is-in");
    });
  }

  /* ── Animated count-up stats ── */
  function animateCount(el) {
    var target = parseFloat(el.getAttribute("data-count")) || 0;
    var decimals = parseInt(el.getAttribute("data-decimals") || "0", 10);
    var suffix = el.getAttribute("data-suffix") || "";
    var start = performance.now();
    var dur = 1200;
    function step(now) {
      var p = Math.min((now - start) / dur, 1);
      var eased = 1 - Math.pow(1 - p, 3);
      var val = target * eased;
      el.textContent = val.toFixed(decimals) + suffix;
      if (p < 1) requestAnimationFrame(step);
      else el.textContent = target.toFixed(decimals) + suffix;
    }
    requestAnimationFrame(step);
  }
  var counters = document.querySelectorAll(".stat-num[data-count]");
  if ("IntersectionObserver" in window) {
    var cio = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            animateCount(entry.target);
            cio.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.6 }
    );
    counters.forEach(function (el) {
      cio.observe(el);
    });
  } else {
    counters.forEach(animateCount);
  }

  /* ── Live same-day slot counter ── */
  var slotCount = document.getElementById("slotCount");
  var slotsLeft = slotCount ? parseInt(slotCount.textContent, 10) || 6 : 6;
  var grabBtn = document.getElementById("grabSlot");
  if (grabBtn && slotCount) {
    grabBtn.addEventListener("click", function () {
      if (slotsLeft <= 0) {
        toast("Today is fully booked — try a next-day slot.");
        return;
      }
      slotsLeft -= 1;
      slotCount.textContent = String(slotsLeft);
      // mark the matching band stat as live so it mirrors the count
      var bandStat = document.querySelector('.band-stat .stat-num[data-count="6"]');
      if (bandStat) {
        bandStat.dataset.live = "1";
        bandStat.textContent = String(slotsLeft);
      }
      var openBadge = document.getElementById("openBadge");
      if (slotsLeft === 0 && openBadge) {
        openBadge.textContent = "Fully booked";
        openBadge.classList.remove("ok");
        openBadge.classList.add("warn");
        grabBtn.disabled = true;
        grabBtn.style.opacity = "0.6";
        grabBtn.style.cursor = "default";
      }
      toast("Slot reserved — " + slotsLeft + " left today. We'll text to confirm.");
    });
  }

  /* ── Check availability button ── */
  var checkBtn = document.getElementById("checkAvail");
  if (checkBtn) {
    checkBtn.addEventListener("click", function () {
      if (slotsLeft > 0) {
        toast(slotsLeft + " same-day slots open right now — earliest 9:20 AM.");
      } else {
        toast("Same-day is full today, but next-day looks wide open.");
      }
      // gently nudge attention to the hero card's count
      if (slotCount && slotCount.animate) {
        slotCount.animate(
          [
            { transform: "scale(1)" },
            { transform: "scale(1.18)" },
            { transform: "scale(1)" }
          ],
          { duration: 420, easing: "ease-out" }
        );
      }
    });
  }

  /* ── Today's hours highlight ── */
  var hoursList = document.getElementById("hoursList");
  var todayNote = document.getElementById("todayNote");
  if (hoursList && todayNote) {
    var now = new Date();
    var day = now.getDay(); // 0 = Sun
    var li = hoursList.querySelector('li[data-day="' + day + '"]');
    if (li) li.classList.add("is-today");

    // open ranges per weekday: [openHour, closeHour] or null when closed
    var ranges = {
      0: null,
      1: [8, 19],
      2: [8, 19],
      3: [8, 19],
      4: [8, 19],
      5: [8, 18],
      6: [9, 14]
    };
    var r = ranges[day];
    var hour = now.getHours() + now.getMinutes() / 60;
    if (!r) {
      todayNote.textContent = "Closed today — open again Monday at 8:00 AM.";
      todayNote.classList.add("is-closed");
    } else if (hour < r[0]) {
      todayNote.textContent = "Opening soon — front desk at " + fmtHour(r[0]) + " today.";
    } else if (hour >= r[1]) {
      todayNote.textContent = "Closed for the day — back tomorrow morning.";
      todayNote.classList.add("is-closed");
    } else {
      todayNote.textContent = "Open now until " + fmtHour(r[1]) + " — walk-ins welcome.";
    }
  }
  function fmtHour(h) {
    var ampm = h >= 12 ? "PM" : "AM";
    var hr = h % 12 || 12;
    return hr + ":00 " + ampm;
  }

  /* ── Directions button (illustrative) ── */
  var directionsBtn = document.getElementById("directionsBtn");
  if (directionsBtn) {
    directionsBtn.addEventListener("click", function (e) {
      // it's a #book anchor; let the smooth-scroll run but also confirm
      toast("412 Maple Grove Rd — about 6 min from Cedar Hollow center.");
    });
  }

  /* ── Booking form ── */
  var form = document.getElementById("bookForm");
  if (form) {
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var nameInput = form.querySelector('input[name="name"]');
      var name = (nameInput.value || "").trim();
      if (name.length < 2) {
        nameInput.classList.add("invalid");
        nameInput.focus();
        toast("Please add a name so we know who's coming in.");
        return;
      }
      nameInput.classList.remove("invalid");
      var reason = form.querySelector('select[name="reason"]').value;
      var first = name.split(" ")[0];
      toast("Thanks, " + first + " — we'll text to confirm your " + reason + " visit.");
      form.reset();
    });
    form.querySelector('input[name="name"]').addEventListener("input", function (e) {
      if (e.target.value.trim().length >= 2) e.target.classList.remove("invalid");
    });
  }

  /* ── Phone call button feedback ── */
  var callBtn = document.getElementById("callBtn");
  if (callBtn) {
    callBtn.addEventListener("click", function () {
      toast("Calling the front desk — Mon–Fri 8 AM to 7 PM.");
    });
  }
})();

snippets.css:
/* ── Design tokens ───────────────────────────────────────────────────────── */
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
  overflow: hidden;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Layout ─────────────────────────────────────────────────────────────── */
.inv {
  height: 100vh;
  display: grid;
  grid-template-columns: 220px 1fr;
}

/* ── Rail ───────────────────────────────────────────────────────────────── */
.rail {
  background: var(--navy);
  color: var(--bone);
  display: flex;
  flex-direction: column;
  padding: 22px 16px 14px;
  overflow-y: auto;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 4px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.brand-mark {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.35rem;
  flex-shrink: 0;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 700;
}
.brand-prop {
  font-size: 0.68rem;
  color: var(--gold-light);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-top: 2px;
}

.nav {
  margin-top: 18px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}
.nav-item {
  font-size: 0.84rem;
  font-weight: 500;
  color: rgba(251, 248, 242, 0.72);
  text-decoration: none;
  padding: 9px 12px;
  border-radius: var(--r-md);
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-item:hover {
  background: rgba(255, 255, 255, 0.06);
  color: var(--bone);
}
.nav-item.is-active {
  background: rgba(201, 166, 73, 0.16);
  color: var(--gold-light);
  font-weight: 600;
}
.nav-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--gold);
  flex-shrink: 0;
}

/* ── Legend ─────────────────────────────────────────────────────────────── */
.rail-legend {
  margin-top: 20px;
  padding: 14px 12px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: var(--r-md);
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.legend-title {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-light);
  margin-bottom: 8px;
}
.legend-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.76rem;
  color: rgba(251, 248, 242, 0.72);
  margin-bottom: 5px;
}
.swatch {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  flex-shrink: 0;
}
.av-ok {
  background: rgba(74, 119, 82, 0.5);
  border: 1px solid rgba(74, 119, 82, 0.7);
}
.av-low {
  background: rgba(217, 144, 32, 0.5);
  border: 1px solid rgba(217, 144, 32, 0.7);
}
.av-none {
  background: rgba(179, 66, 50, 0.5);
  border: 1px solid rgba(179, 66, 50, 0.7);
}
.av-stop {
  background: rgba(22, 30, 44, 0.4);
  border: 1px solid rgba(22, 30, 44, 0.5);
}

.rail-foot {
  margin-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.clock {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 0.84rem;
  color: var(--gold-light);
}
.agent {
  font-size: 0.7rem;
  color: rgba(251, 248, 242, 0.55);
  letter-spacing: 0.04em;
}

/* ── Main ───────────────────────────────────────────────────────────────── */
.main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--cream);
}

/* ── Topbar ─────────────────────────────────────────────────────────────── */
.topbar {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  padding: 22px 28px 14px;
  border-bottom: 1px solid var(--line);
  background: var(--bone);
  flex-shrink: 0;
}
.kicker {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold-d);
  font-weight: 600;
}
.topbar h1 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.8rem;
  letter-spacing: -0.005em;
  margin-top: 2px;
}
.topbar h1 span {
  color: var(--navy-2);
  font-weight: 500;
  font-size: 1.4rem;
}
.topbar-controls {
  display: flex;
  align-items: center;
  gap: 10px;
}
.ctrl-label {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--warm-gray);
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.ctrl-select {
  font-family: var(--font-body);
  font-size: 0.84rem;
  font-weight: 500;
  color: var(--ink);
  background: var(--bone);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-sm);
  padding: 7px 10px;
  cursor: pointer;
  outline: none;
}
.ctrl-select:focus {
  border-color: var(--navy-2);
}
.icon-btn {
  background: var(--bone);
  border: 1px solid var(--line);
  width: 38px;
  height: 38px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  cursor: pointer;
  color: var(--ink-2);
  align-self: flex-end;
}
.icon-btn:hover {
  background: var(--cream-2);
}

/* ── Grid wrap ──────────────────────────────────────────────────────────── */
.grid-wrap {
  flex: 1;
  overflow: auto;
  padding-bottom: 4px;
}

/* ── Inventory grid ─────────────────────────────────────────────────────── */
.inv-grid {
  border-collapse: collapse;
  width: max-content;
  min-width: 100%;
  font-size: 0.82rem;
}

.inv-grid thead th {
  position: sticky;
  top: 0;
  z-index: 10;
  background: var(--bone);
  border-bottom: 2px solid var(--line-strong);
  padding: 0;
}
.inv-grid thead th:first-child {
  position: sticky;
  left: 0;
  z-index: 20;
  min-width: 170px;
}
.th-inner {
  padding: 10px 12px;
  text-align: center;
  min-width: 100px;
}
.th-date {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.78rem;
  color: var(--navy-d);
  display: block;
}
.th-dow {
  font-size: 0.68rem;
  font-weight: 600;
  color: var(--warm-gray);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  display: block;
  margin-top: 2px;
}
.th-dow.weekend {
  color: var(--gold-d);
}
.th-room-label {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  text-align: left;
  padding: 10px 16px;
}

/* ── Row header (sticky left) ───────────────────────────────────────────── */
.inv-grid tbody td.row-head {
  position: sticky;
  left: 0;
  z-index: 5;
  background: var(--bone);
  border-right: 2px solid var(--line-strong);
  padding: 0;
}
.row-head-inner {
  padding: 0 14px;
  min-height: 72px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.row-type-name {
  font-weight: 700;
  font-size: 0.88rem;
  color: var(--navy-d);
  letter-spacing: -0.005em;
}
.row-type-sub {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  color: var(--warm-gray);
  letter-spacing: 0.08em;
  margin-top: 2px;
}

/* ── Inventory cell ─────────────────────────────────────────────────────── */
.inv-grid tbody td.inv-cell {
  padding: 0;
  border: 1px solid var(--line);
  vertical-align: top;
  min-width: 100px;
  height: 72px;
  position: relative;
}
.cell-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 6px 8px;
  gap: 1px;
  position: relative;
  transition: background 0.12s;
}

/* availability colouring via data-av */
.inv-cell[data-av="ok"] .cell-inner {
  background: rgba(74, 119, 82, 0.1);
}
.inv-cell[data-av="low"] .cell-inner {
  background: rgba(217, 144, 32, 0.16);
}
.inv-cell[data-av="none"] .cell-inner {
  background: rgba(179, 66, 50, 0.14);
}
.inv-cell[data-av="stop"] .cell-inner {
  background: rgba(22, 30, 44, 0.07);
  opacity: 0.7;
}

.cell-avail {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--navy-d);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.cell-avail.zero {
  color: var(--danger);
}

.cell-sub {
  font-size: 0.64rem;
  color: var(--warm-gray);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.03em;
}

.cell-stop-badge {
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 1px 5px;
  border-radius: 3px;
  background: rgba(22, 30, 44, 0.12);
  color: var(--warm-gray);
  margin-top: 1px;
}

/* stepper + stop-sell controls — visible on hover */
.cell-controls {
  display: none;
  position: absolute;
  bottom: 3px;
  left: 50%;
  transform: translateX(-50%);
  gap: 2px;
  align-items: center;
}
.inv-cell:hover .cell-controls {
  display: flex;
}
.step-btn {
  width: 20px;
  height: 20px;
  border-radius: 4px;
  border: 1px solid var(--line-strong);
  background: var(--bone);
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--navy-d);
  cursor: pointer;
  display: grid;
  place-items: center;
  line-height: 1;
}
.step-btn:hover {
  background: var(--cream-2);
}
.step-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.stop-btn {
  width: 20px;
  height: 20px;
  border-radius: 4px;
  border: 1px solid var(--line-strong);
  background: var(--bone);
  font-size: 0.6rem;
  font-weight: 700;
  color: var(--warm-gray);
  cursor: pointer;
  display: grid;
  place-items: center;
  margin-left: 2px;
}
.stop-btn:hover {
  background: var(--cream-2);
}
.stop-btn.active {
  background: var(--danger);
  color: white;
  border-color: var(--danger);
}

/* dirty cell indicator */
.inv-cell.is-dirty::after {
  content: "";
  position: absolute;
  top: 4px;
  right: 4px;
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: var(--gold);
}

/* ── Summary bar ────────────────────────────────────────────────────────── */
.summary-bar {
  display: flex;
  align-items: center;
  gap: 0;
  background: var(--navy-d);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  flex-shrink: 0;
  flex-wrap: wrap;
}
.sum-kpi {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 10px 20px;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
}
.sum-label {
  font-size: 0.64rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: rgba(251, 248, 242, 0.55);
}
.sum-val {
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 700;
  color: var(--bone);
  font-variant-numeric: tabular-nums;
}
.sum-val.warn {
  color: var(--gold-light);
}
.sum-val.danger {
  color: #e07060;
}

.save-btn {
  margin-left: auto;
  margin-right: 16px;
  background: var(--gold);
  color: var(--navy-d);
  border: none;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 700;
  padding: 10px 20px;
  border-radius: var(--r-md);
  cursor: pointer;
  white-space: nowrap;
}
.save-btn:hover {
  background: var(--gold-light);
}

/* ── Toast ──────────────────────────────────────────────────────────────── */
.toast {
  position: fixed;
  bottom: 60px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 20px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  white-space: nowrap;
  pointer-events: none;
}

/* ── Responsive ─────────────────────────────────────────────────────────── */
@media (max-width: 960px) {
  .inv {
    grid-template-columns: 1fr;
  }
  .rail {
    display: none;
  }
  .topbar {
    flex-direction: column;
    align-items: flex-start;
    padding: 14px 16px 10px;
  }
  .topbar-controls {
    flex-wrap: wrap;
  }
  .summary-bar {
    justify-content: flex-start;
  }
  .save-btn {
    margin: 8px 16px;
  }
}
@media (max-width: 560px) {
  .topbar h1 {
    font-size: 1.3rem;
  }
  .sum-kpi {
    padding: 8px 12px;
  }
  .sum-val {
    font-size: 0.9rem;
  }
}

