:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Topbar ── */
.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  background: var(--navy-d);
  color: var(--bone);
  padding: 14px 32px;
  display: flex;
  align-items: center;
  gap: 28px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--bone);
  flex-shrink: 0;
}
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: var(--r-sm);
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.2rem;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
}
.brand-name em {
  font-style: normal;
  color: var(--gold-light);
}
.stay-bar {
  display: flex;
  align-items: center;
  gap: 26px;
  margin-left: auto;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 999px;
  padding: 8px 8px 8px 22px;
}
.stay-seg {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
}
.seg-label {
  font-size: 0.64rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gold-light);
  font-weight: 600;
}
.stay-seg strong {
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--bone);
}
.edit-btn {
  background: var(--gold);
  color: var(--navy-d);
  border: none;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 700;
  padding: 9px 16px;
  border-radius: 999px;
  cursor: pointer;
}
.edit-btn:hover {
  background: var(--gold-light);
}

/* ── Layout ── */
.results {
  max-width: 1200px;
  margin: 0 auto;
  padding: 28px 32px 64px;
  display: grid;
  grid-template-columns: 264px 1fr;
  gap: 28px;
  align-items: start;
}

/* ── Filters ── */
.filters {
  position: sticky;
  top: 92px;
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 4px 20px 20px;
}
.filters-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0 14px;
  border-bottom: 1px solid var(--line);
}
.filters-head h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.4rem;
  color: var(--navy-d);
}
.clear-btn {
  background: transparent;
  border: none;
  font-family: inherit;
  font-size: 0.76rem;
  font-weight: 600;
  color: var(--navy-2);
  cursor: pointer;
}
.clear-btn:hover {
  color: var(--gold-d);
}
.fgroup {
  padding: 16px 0;
  border-bottom: 1px solid var(--line);
}
.fgroup:last-child {
  border-bottom: none;
}
.fgroup h3 {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gold-d);
  font-weight: 700;
  margin-bottom: 12px;
}
input[type="range"] {
  width: 100%;
  accent-color: var(--gold-d);
}
.range-out {
  font-size: 0.82rem;
  color: var(--warm-gray);
  margin-top: 8px;
}
.range-out strong {
  font-family: var(--font-mono);
  color: var(--navy-d);
}
.check {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.88rem;
  color: var(--ink-2);
  padding: 7px 0;
  cursor: pointer;
}
.check input {
  width: 17px;
  height: 17px;
  accent-color: var(--navy);
  cursor: pointer;
}

/* ── Listing ── */
.listing-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
  gap: 16px;
}
.count {
  font-size: 0.96rem;
  color: var(--ink-2);
}
.count strong {
  font-family: var(--font-display);
  font-size: 1.4rem;
  color: var(--navy-d);
}
.muted {
  color: var(--warm-gray);
  font-size: 0.86rem;
}
.sort {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--warm-gray);
}
.sort select {
  font-family: inherit;
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--navy-d);
  background: var(--bone);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-sm);
  padding: 8px 12px;
  cursor: pointer;
}

.room-list {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.room {
  display: grid;
  grid-template-columns: 240px 1fr 200px;
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--shadow-1);
  transition: box-shadow 0.18s, transform 0.18s;
}
.room:hover {
  box-shadow: var(--shadow-2);
  transform: translateY(-2px);
}
.room-img {
  position: relative;
  background: linear-gradient(135deg, var(--navy-2), var(--navy-d));
}
.room-img.t-standard {
  background: linear-gradient(135deg, #6c7280, #2e3a52);
}
.room-img.t-deluxe {
  background: linear-gradient(135deg, #3a5180, #1a2b4a);
}
.room-img.t-suite {
  background: linear-gradient(135deg, var(--gold-d), #5a4a1e);
}
.room-img::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(60% 80% at 70% 20%, rgba(255, 255, 255, 0.12), transparent 60%);
}
.room-tag {
  position: absolute;
  top: 12px;
  left: 12px;
  background: rgba(15, 29, 54, 0.8);
  color: var(--gold-light);
  font-size: 0.66rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 5px 10px;
  border-radius: 999px;
}
.room-body {
  padding: 18px 20px;
  border-right: 1px solid var(--line);
}
.room-body h3 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.55rem;
  color: var(--navy-d);
}
.room-specs {
  font-size: 0.82rem;
  color: var(--warm-gray);
  margin: 4px 0 12px;
}
.badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.badge {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--ink-2);
  background: var(--cream);
  border: 1px solid var(--line);
  padding: 4px 10px;
  border-radius: 999px;
}
.badge.green {
  color: var(--success);
  background: rgba(74, 119, 82, 0.1);
  border-color: rgba(74, 119, 82, 0.24);
}
.room-buy {
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-end;
  text-align: right;
  gap: 2px;
}
.price-night {
  font-size: 0.78rem;
  color: var(--warm-gray);
}
.price-total {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 2rem;
  color: var(--navy-d);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.price-sub {
  font-size: 0.74rem;
  color: var(--warm-gray);
  margin-bottom: 12px;
}
.select-btn {
  background: var(--navy);
  color: var(--bone);
  border: none;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.88rem;
  padding: 11px 20px;
  border-radius: var(--r-sm);
  cursor: pointer;
  width: 100%;
}
.select-btn:hover {
  background: var(--navy-d);
}

.empty {
  text-align: center;
  padding: 70px 24px;
  color: var(--warm-gray);
  font-style: italic;
  background: var(--bone);
  border: 1px dashed var(--line-strong);
  border-radius: var(--r-md);
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 12px 22px;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 50;
}

/* ── Responsive ── */
@media (max-width: 980px) {
  .stay-bar {
    display: none;
  }
  .edit-btn {
    margin-left: auto;
  }
  .results {
    grid-template-columns: 1fr;
  }
  .filters {
    position: static;
  }
  .room {
    grid-template-columns: 180px 1fr;
  }
  .room-buy {
    grid-column: 1 / -1;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    border-top: 1px solid var(--line);
  }
  .room-buy .select-btn {
    width: auto;
  }
  .price-sub {
    margin-bottom: 0;
  }
}
@media (max-width: 560px) {
  .topbar {
    padding: 12px 18px;
  }
  .results {
    padding: 20px 18px 48px;
  }
  .room {
    grid-template-columns: 1fr;
  }
  .room-img {
    height: 150px;
  }
  .room-body {
    border-right: none;
  }
}

