// ── Room inventory (price is per night; stay = 3 nights) ──────────────────────
const NIGHTS = 3;
const ROOMS = [
  {
    id: "single-std",
    name: "Classic Single",
    type: "Standard",
    bed: "Twin",
    size: 18,
    price: 132,
    tag: "Smart value",
    amenities: ["Refundable"],
    specs: "City view · 18m² · 1 single bed",
  },
  {
    id: "double-std",
    name: "Classic Double",
    type: "Standard",
    bed: "Queen",
    size: 24,
    price: 168,
    tag: null,
    amenities: ["Breakfast", "Refundable"],
    specs: "Courtyard view · 24m² · Queen bed",
  },
  {
    id: "deluxe-double",
    name: "Deluxe Double",
    type: "Deluxe",
    bed: "King",
    size: 28,
    price: 184,
    tag: "Most booked",
    amenities: ["Breakfast", "Balcony", "Refundable"],
    specs: "City view · 28m² · King bed",
  },
  {
    id: "twin-deluxe",
    name: "Deluxe Twin",
    type: "Deluxe",
    bed: "Twin",
    size: 30,
    price: 196,
    tag: null,
    amenities: ["Breakfast", "Balcony"],
    specs: "Garden view · 30m² · 2 twin beds",
  },
  {
    id: "junior-suite",
    name: "Junior Suite",
    type: "Suite",
    bed: "King",
    size: 42,
    price: 268,
    tag: "Suite",
    amenities: ["Breakfast", "Balcony", "Refundable"],
    specs: "Balcony · 42m² · King + lounge area",
  },
  {
    id: "signature-suite",
    name: "Signature Suite",
    type: "Suite",
    bed: "King",
    size: 64,
    price: 412,
    tag: "Top suite",
    amenities: ["Breakfast", "Balcony", "Refundable"],
    specs: "Terrace · 64m² · Separate living room",
  },
];

// ── State ─────────────────────────────────────────────────────────────────────
const state = {
  maxPrice: 520,
  type: new Set(),
  bed: new Set(),
  amenity: new Set(),
  sort: "rec",
};

const list = document.getElementById("roomList");
const empty = document.getElementById("empty");
const countEl = document.getElementById("count");
const toast = document.getElementById("toast");

const eur = (n) => "€" + n.toLocaleString("en-GB");

function passes(r) {
  if (r.price > state.maxPrice) return false;
  if (state.type.size && !state.type.has(r.type)) return false;
  if (state.bed.size && !state.bed.has(r.bed)) return false;
  for (const a of state.amenity) if (!r.amenities.includes(a)) return false;
  return true;
}

function sortRooms(rooms) {
  const s = [...rooms];
  if (state.sort === "price-asc") s.sort((a, b) => a.price - b.price);
  else if (state.sort === "price-desc") s.sort((a, b) => b.price - a.price);
  else if (state.sort === "size-desc") s.sort((a, b) => b.size - a.size);
  return s;
}

function render() {
  const visible = sortRooms(ROOMS.filter(passes));
  countEl.textContent = visible.length;
  empty.hidden = visible.length > 0;

  list.innerHTML = visible
    .map((r) => {
      const total = r.price * NIGHTS;
      const badges = r.amenities
        .map(
          (a) =>
            `<span class="badge ${a === "Refundable" ? "green" : ""}">${a === "Refundable" ? "Free cancellation" : a}</span>`
        )
        .join("");
      return `
      <article class="room">
        <div class="room-img t-${r.type.toLowerCase()}">
          ${r.tag ? `<span class="room-tag">${r.tag}</span>` : ""}
        </div>
        <div class="room-body">
          <h3>${r.name}</h3>
          <p class="room-specs">${r.specs}</p>
          <div class="badges">${badges}</div>
        </div>
        <div class="room-buy">
          <p class="price-night">${eur(r.price)} / night</p>
          <p class="price-total">${eur(total)}</p>
          <p class="price-sub">total · ${NIGHTS} nights · incl. taxes</p>
          <button class="select-btn" data-name="${r.name}">Select room</button>
        </div>
      </article>`;
    })
    .join("");
}

// ── Wiring ────────────────────────────────────────────────────────────────────
const priceRange = document.getElementById("priceRange");
const priceOut = document.getElementById("priceOut");
priceRange.addEventListener("input", () => {
  state.maxPrice = Number(priceRange.value);
  priceOut.textContent = eur(state.maxPrice);
  render();
});

document.querySelectorAll('input[type="checkbox"][data-filter]').forEach((cb) => {
  cb.addEventListener("change", () => {
    const bucket = state[cb.dataset.filter];
    if (cb.checked) bucket.add(cb.value);
    else bucket.delete(cb.value);
    render();
  });
});

document.getElementById("sort").addEventListener("change", (e) => {
  state.sort = e.target.value;
  render();
});

document.getElementById("clearFilters").addEventListener("click", () => {
  state.type.clear();
  state.bed.clear();
  state.amenity.clear();
  state.maxPrice = 520;
  state.sort = "rec";
  priceRange.value = 520;
  priceOut.textContent = eur(520);
  document.getElementById("sort").value = "rec";
  document
    .querySelectorAll('input[type="checkbox"][data-filter]')
    .forEach((cb) => (cb.checked = false));
  render();
});

list.addEventListener("click", (e) => {
  const btn = e.target.closest(".select-btn");
  if (!btn) return;
  showToast(`${btn.dataset.name} selected · continuing to room details…`);
});

document.querySelector(".edit-btn").addEventListener("click", () => showToast("Edit search"));

function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2400);
}

render();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --shadow-sm: 0 1px 2px rgba(28, 42, 37, 0.06), 0 2px 8px rgba(28, 42, 37, 0.05);
  --shadow-md: 0 10px 30px -12px rgba(22, 48, 42, 0.28), 0 2px 6px rgba(22, 48, 42, 0.08);
  --shadow-lg: 0 30px 60px -24px rgba(22, 48, 42, 0.4);
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: "Inter", system-ui, sans-serif;
  line-height: 1.55;
  color: var(--ink);
  background-color: var(--ivory);
  background-image:
    radial-gradient(1200px 600px at 110% -10%, rgba(176, 141, 87, 0.08), transparent 60%),
    radial-gradient(900px 500px at -10% 0%, rgba(31, 61, 52, 0.06), transparent 55%);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3 {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
  letter-spacing: 0.2px;
  margin: 0;
}

.page {
  max-width: 1180px;
  margin: 0 auto;
  padding: 28px 24px 48px;
}

/* ============ MASTHEAD ============ */
.masthead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--line);
}

.brandmark {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-glyph {
  display: grid;
  place-items: center;
  width: 50px;
  height: 50px;
  border-radius: var(--r-md);
  background: linear-gradient(155deg, var(--green-700), var(--green-d));
  color: var(--brass-50);
  font-family: "Cormorant Garamond", serif;
  font-weight: 700;
  font-size: 17px;
  letter-spacing: 0.5px;
  box-shadow: var(--shadow-sm), inset 0 0 0 1px rgba(176, 141, 87, 0.35);
}

.brand-name {
  margin: 0;
  font-family: "Cormorant Garamond", serif;
  font-weight: 700;
  font-size: 22px;
  color: var(--green-d);
  line-height: 1.1;
}

.brand-tag {
  margin: 2px 0 0;
  font-size: 11px;
  letter-spacing: 1.6px;
  text-transform: uppercase;
  color: var(--muted);
}

.masthead-nav {
  display: flex;
  align-items: center;
  gap: 20px;
}

.nav-link {
  font-size: 14px;
  font-weight: 500;
  color: var(--ink-2);
  text-decoration: none;
  padding: 4px 2px;
  border-bottom: 1.5px solid transparent;
  transition: color 0.18s ease, border-color 0.18s ease;
}

.nav-link:hover {
  color: var(--green);
}

.nav-link.is-active {
  color: var(--green-d);
  border-color: var(--brass);
}

.nav-pill {
  font-size: 12px;
  font-weight: 500;
  color: var(--brass-d);
  background: var(--brass-50);
  border: 1px solid rgba(176, 141, 87, 0.3);
  padding: 6px 12px;
  border-radius: 999px;
}

/* ============ INTRO ============ */
.intro {
  margin: 40px 0 28px;
  max-width: 760px;
}

.eyebrow {
  margin: 0 0 10px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--brass-d);
}

.display {
  font-size: clamp(32px, 5vw, 50px);
  line-height: 1.05;
  font-weight: 600;
  color: var(--green-d);
  max-width: 14ch;
}

.lede {
  margin: 16px 0 0;
  font-size: 16px;
  color: var(--ink-2);
  max-width: 58ch;
}

/* ============ GRID ============ */
.grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 24px;
  align-items: start;
}

.panel {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 26px;
  box-shadow: var(--shadow-md);
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 20px;
}

.panel-title {
  font-size: 26px;
  color: var(--green-d);
}

.ghost-btn {
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  color: var(--muted);
  background: transparent;
  border: 1px solid var(--line-2);
  padding: 6px 14px;
  border-radius: 999px;
  cursor: pointer;
  transition: all 0.18s ease;
}

.ghost-btn:hover {
  color: var(--green-d);
  border-color: var(--brass);
  background: var(--brass-50);
}

/* ============ FIELDS ============ */
.field {
  margin-bottom: 22px;
}

.field-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 8px;
}

.field label,
.term-field legend {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-2);
  padding: 0;
}

.field-val {
  font-family: "Cormorant Garamond", serif;
  font-size: 20px;
  font-weight: 600;
  color: var(--green-700);
}

.money-input {
  display: flex;
  align-items: center;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  background: var(--white);
  overflow: hidden;
  margin-bottom: 12px;
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}

.money-input:focus-within {
  border-color: var(--brass);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.18);
}

.money-input .prefix,
.money-input .suffix {
  font-size: 13px;
  font-weight: 600;
  color: var(--muted);
  padding: 0 12px;
  background: var(--ivory);
  align-self: stretch;
  display: flex;
  align-items: center;
}

.money-input .suffix {
  border-left: 1px solid var(--line);
}

.money-input .prefix {
  border-right: 1px solid var(--line);
}

.money-input input {
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background: transparent;
  font-family: inherit;
  font-size: 16px;
  font-weight: 600;
  color: var(--ink);
  padding: 11px 12px;
}

.field-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}

.hint {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
}

/* ============ RANGE ============ */
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--brass) 0%, var(--brass) var(--fill, 50%), var(--green-50) var(--fill, 50%), var(--green-50) 100%);
  outline: none;
  margin: 4px 0 0;
  cursor: pointer;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--white);
  border: 2px solid var(--brass-d);
  box-shadow: var(--shadow-sm);
  cursor: grab;
  transition: transform 0.12s ease;
}

input[type="range"]::-webkit-slider-thumb:active {
  cursor: grabbing;
  transform: scale(1.12);
}

input[type="range"]::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--white);
  border: 2px solid var(--brass-d);
  box-shadow: var(--shadow-sm);
  cursor: grab;
}

input[type="range"]:focus-visible {
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.28);
}

/* ============ SEGMENTED ============ */
.term-field {
  border: none;
  margin: 0 0 18px;
  padding: 0;
}

.term-field legend {
  margin-bottom: 8px;
}

.seg {
  display: inline-flex;
  background: var(--ivory);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 3px;
}

.seg-opt {
  position: relative;
  cursor: pointer;
}

.seg-opt input {
  position: absolute;
  opacity: 0;
  inset: 0;
  cursor: pointer;
}

.seg-opt span {
  display: block;
  padding: 7px 20px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
  color: var(--muted);
  transition: all 0.18s ease;
}

.seg-opt input:checked + span {
  background: var(--green-d);
  color: var(--brass-50);
  box-shadow: var(--shadow-sm);
}

.seg-opt input:focus-visible + span {
  outline: 2px solid var(--brass);
  outline-offset: 2px;
}

.assump {
  margin: 4px 0 0;
  font-size: 12.5px;
  color: var(--muted);
  padding: 12px 14px;
  background: var(--green-50);
  border-radius: var(--r-sm);
  border-left: 3px solid var(--green-700);
}

.assump strong {
  color: var(--green-d);
}

/* ============ RESULTS ============ */
.results {
  background: linear-gradient(170deg, var(--paper), #fbf8f0);
}

.status-chip {
  font-size: 12px;
  font-weight: 600;
  padding: 5px 13px;
  border-radius: 999px;
  letter-spacing: 0.3px;
}

.status-chip[data-tone="ok"] {
  color: #1c6647;
  background: rgba(47, 158, 111, 0.13);
  border: 1px solid rgba(47, 158, 111, 0.3);
}

.status-chip[data-tone="warn"] {
  color: var(--brass-d);
  background: rgba(201, 138, 43, 0.13);
  border: 1px solid rgba(201, 138, 43, 0.32);
}

.status-chip[data-tone="danger"] {
  color: #9c3a2c;
  background: rgba(196, 80, 62, 0.12);
  border: 1px solid rgba(196, 80, 62, 0.3);
}

/* ============ GAUGE ============ */
.gauge-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 0 18px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 20px;
}

.gauge {
  width: 230px;
  max-width: 100%;
  height: auto;
}

.gauge-track {
  fill: none;
  stroke: var(--green-50);
  stroke-width: 14;
  stroke-linecap: round;
}

.gauge-fill {
  fill: none;
  stroke: url(#gaugeGrad);
  stroke-width: 14;
  stroke-linecap: round;
  stroke-dasharray: 283;
  stroke-dashoffset: 283;
  transition: stroke-dashoffset 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}

.gauge-needle {
  stroke: var(--ink);
  stroke-width: 3;
  stroke-linecap: round;
  transform-origin: 110px 120px;
  transform: rotate(-90deg);
  transition: transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}

.gauge-hub {
  fill: var(--green-d);
  stroke: var(--brass);
  stroke-width: 2;
}

.gauge-readout {
  text-align: center;
  margin-top: -6px;
}

.readout-label {
  margin: 0;
  font-size: 11px;
  letter-spacing: 1.6px;
  text-transform: uppercase;
  color: var(--muted);
}

.readout-price {
  margin: 4px 0 2px;
  font-family: "Cormorant Garamond", serif;
  font-size: 44px;
  font-weight: 700;
  line-height: 1;
  color: var(--green-d);
}

.readout-range {
  margin: 0;
  font-size: 13px;
  font-weight: 500;
  color: var(--brass-d);
}

/* ============ METRICS ============ */
.metric-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
  margin-bottom: 22px;
}

.metric {
  background: var(--paper);
  padding: 14px 16px;
}

.metric-k {
  margin: 0;
  font-size: 11px;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: var(--muted);
}

.metric-v {
  margin: 5px 0 1px;
  font-family: "Cormorant Garamond", serif;
  font-size: 26px;
  font-weight: 600;
  color: var(--ink);
}

.metric-sub {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
}

/* ============ BREAKDOWN ============ */
.breakdown {
  margin-bottom: 22px;
}

.breakdown-title {
  margin: 0 0 12px;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-2);
}

.bars {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.bars li {
  display: grid;
  grid-template-columns: 130px 1fr 64px;
  align-items: center;
  gap: 12px;
}

.bar-k {
  font-size: 12.5px;
  color: var(--ink-2);
}

.bar-track {
  height: 9px;
  border-radius: 999px;
  background: var(--green-50);
  overflow: hidden;
}

.bar-fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--green-700);
  transition: width 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

.bar-fill.alt {
  background: var(--brass);
}

.bar-fill.alt2 {
  background: var(--brass-d);
}

.bar-v {
  text-align: right;
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

/* ============ CTA ============ */
.cta {
  width: 100%;
  font-family: inherit;
  font-size: 15px;
  font-weight: 600;
  color: var(--brass-50);
  background: linear-gradient(150deg, var(--green-700), var(--green-d));
  border: 1px solid var(--green-d);
  padding: 14px;
  border-radius: var(--r-md);
  cursor: pointer;
  box-shadow: var(--shadow-md);
  transition: transform 0.16s ease, box-shadow 0.16s ease;
}

.cta:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.cta:active {
  transform: translateY(0);
}

.cta:focus-visible {
  outline: 2px solid var(--brass);
  outline-offset: 3px;
}

/* ============ LISTINGS ============ */
.listings {
  margin-top: 48px;
}

.listings-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 16px;
  margin-bottom: 22px;
  border-bottom: 1px solid var(--line);
}

.section-h {
  font-size: 30px;
  color: var(--green-d);
}

.section-sub {
  margin: 0;
  font-size: 14px;
  color: var(--muted);
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 22px;
}

.card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  display: flex;
  flex-direction: column;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--line-2);
}

.card.out-of-range {
  opacity: 0.62;
}

.card.out-of-range:hover {
  opacity: 0.82;
}

.photo {
  position: relative;
  aspect-ratio: 4 / 3;
  width: 100%;
}

.photo-badges {
  position: absolute;
  top: 12px;
  left: 12px;
  right: 12px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 8px;
}

.badge {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.3px;
  padding: 5px 11px;
  border-radius: 999px;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.18);
}

.badge.fit {
  color: #fff;
  background: rgba(31, 61, 52, 0.82);
  border: 1px solid rgba(176, 141, 87, 0.5);
}

.badge.over {
  color: #fff;
  background: rgba(196, 80, 62, 0.85);
}

.badge.price {
  color: var(--green-d);
  background: rgba(255, 253, 248, 0.92);
  font-family: "Cormorant Garamond", serif;
  font-size: 15px;
  font-weight: 700;
}

.card-body {
  padding: 16px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}

.card-title {
  font-size: 21px;
  color: var(--green-d);
  line-height: 1.1;
}

.card-addr {
  margin: 0;
  font-size: 13px;
  color: var(--muted);
}

.card-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 2px;
}

.chip {
  font-size: 11.5px;
  font-weight: 500;
  color: var(--ink-2);
  background: var(--ivory);
  border: 1px solid var(--line);
  padding: 4px 10px;
  border-radius: 999px;
}

.card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.agent {
  font-size: 12px;
  color: var(--muted);
}

.agent strong {
  color: var(--ink-2);
  font-weight: 600;
}

.pay-note {
  font-size: 12px;
  font-weight: 600;
  color: var(--brass-d);
  font-variant-numeric: tabular-nums;
}

/* ============ FOOTER ============ */
.footer {
  margin-top: 44px;
  padding-top: 22px;
  border-top: 1px solid var(--line);
  text-align: center;
}

.footer p {
  margin: 0;
  font-size: 12.5px;
  color: var(--muted);
}

/* ============ TOAST ============ */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 20px);
  background: var(--green-d);
  color: var(--brass-50);
  font-size: 14px;
  font-weight: 500;
  padding: 12px 22px;
  border-radius: 999px;
  box-shadow: var(--shadow-lg);
  border: 1px solid rgba(176, 141, 87, 0.4);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.28s ease, transform 0.28s ease;
  z-index: 50;
  max-width: 90vw;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ============ RESPONSIVE ============ */
@media (max-width: 920px) {
  .grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .page {
    padding: 20px 16px 36px;
  }

  .masthead {
    flex-direction: column;
    align-items: flex-start;
    gap: 14px;
  }

  .masthead-nav {
    flex-wrap: wrap;
    gap: 12px;
  }

  .nav-pill {
    order: 3;
  }

  .intro {
    margin: 28px 0 22px;
  }

  .panel {
    padding: 20px 18px;
  }

  .field-split {
    grid-template-columns: 1fr;
    gap: 18px;
  }

  .metric-grid {
    grid-template-columns: 1fr 1fr;
  }

  .readout-price {
    font-size: 38px;
  }

  .bars li {
    grid-template-columns: 1fr;
    gap: 5px;
  }

  .bar-v {
    text-align: left;
  }

  .listings-head {
    flex-direction: column;
    gap: 6px;
  }

  .cards {
    grid-template-columns: 1fr;
  }
}

