(function () {
  "use strict";

  /* ---------- helpers ---------- */
  var fmt0 = new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  });

  function money(n) {
    if (!isFinite(n) || n < 0) n = 0;
    return fmt0.format(Math.round(n));
  }

  function compact(n) {
    if (n >= 1000000) return "$" + (n / 1000000).toFixed(n % 1000000 === 0 ? 0 : 1) + "M";
    if (n >= 1000) return "$" + Math.round(n / 1000) + "k";
    return money(n);
  }

  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function num(id) {
    var el = document.getElementById(id);
    var v = parseFloat(el.value);
    return isNaN(v) ? 0 : v;
  }

  var toastEl = document.getElementById("toast");
  var toastTimer = null;
  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2600);
  }

  /* ---------- range fill paint ---------- */
  function paintRange(el) {
    var min = parseFloat(el.min),
      max = parseFloat(el.max),
      val = parseFloat(el.value);
    var pct = ((val - min) / (max - min)) * 100;
    el.style.setProperty("--fill", pct + "%");
  }

  /* ---------- sample listings ---------- */
  var LISTINGS = [
    {
      title: "The Aldergrove",
      addr: "42 Harlowe Terrace · Westhaven",
      price: 489000,
      beds: 3,
      baths: 2,
      sqft: 1980,
      agent: "Priya Ackerman",
      grad: "linear-gradient(135deg,#c9b79a 0%,#a8895f 45%,#6d5436 100%)",
      overlay: "radial-gradient(120% 90% at 20% 0%,rgba(255,245,225,.55),transparent 55%)",
    },
    {
      title: "Linnea Row House",
      addr: "7 Cobble Mews · Briarpoint",
      price: 575000,
      beds: 4,
      baths: 3,
      sqft: 2340,
      agent: "Marcus Vela",
      grad: "linear-gradient(135deg,#2f4a40 0%,#3c6053 50%,#243a32 100%)",
      overlay: "radial-gradient(130% 100% at 80% 10%,rgba(176,141,87,.4),transparent 60%)",
    },
    {
      title: "Calder Courtyard Flat",
      addr: "300 Vinewood Ave · Westhaven",
      price: 612000,
      beds: 2,
      baths: 2,
      sqft: 1640,
      agent: "Dora Whitfield",
      grad: "linear-gradient(135deg,#b7704f 0%,#8a4f37 50%,#5c3322 100%)",
      overlay: "radial-gradient(120% 90% at 30% 100%,rgba(255,230,200,.5),transparent 55%)",
    },
    {
      title: "Marlowe Hill Estate",
      addr: "18 Crestline Loop · Highmoor",
      price: 845000,
      beds: 5,
      baths: 4,
      sqft: 3420,
      agent: "Theo Brandt",
      grad: "linear-gradient(135deg,#3a3f52 0%,#566079 50%,#2a2f3e 100%)",
      overlay: "radial-gradient(130% 100% at 70% 0%,rgba(200,210,235,.4),transparent 60%)",
    },
  ];

  /* ---------- core affordability math ---------- */
  function monthlyPI(principal, annualRate, years) {
    var r = annualRate / 100 / 12;
    var n = years * 12;
    if (r === 0) return principal / n;
    return (principal * r) / (1 - Math.pow(1 + r, -n));
  }

  // Given a target monthly P&I, invert to find affordable loan principal.
  function loanFromPI(pi, annualRate, years) {
    var r = annualRate / 100 / 12;
    var n = years * 12;
    if (r === 0) return pi * n;
    return (pi * (1 - Math.pow(1 + r, -n))) / r;
  }

  var TAX_RATE = 0.0115; // annual property tax as % of price
  var INS_HOA_MONTHLY_PER_1000 = 0.55; // insurance + HOA per $1000 of price / month

  function compute() {
    var income = num("income");
    var debts = num("debts");
    var down = num("down");
    var rate = num("rate");
    var dti = num("dti");
    var term = parseInt(
      document.querySelector('input[name="term"]:checked').value,
      10
    );

    // Max monthly housing the lender allows under DTI.
    var maxTotalDebt = (income / 12) * (dti / 100);
    var maxHousing = Math.max(0, maxTotalDebt - debts);

    // Solve price iteratively: housing = P&I(price-down) + tax + ins/hoa.
    // tax & ins scale with price, so we converge.
    var price = (down + loanFromPI(maxHousing, rate, term)); // first guess ignoring escrow
    for (var i = 0; i < 24; i++) {
      var taxM = (price * TAX_RATE) / 12;
      var insM = (price / 1000) * INS_HOA_MONTHLY_PER_1000;
      var availPI = Math.max(0, maxHousing - taxM - insM);
      var loan = loanFromPI(availPI, rate, term);
      var newPrice = loan + down;
      if (Math.abs(newPrice - price) < 50) {
        price = newPrice;
        break;
      }
      price = newPrice;
    }
    price = Math.max(down, price);

    var loan = Math.max(0, price - down);
    var pi = monthlyPI(loan, rate, term);
    var taxM = (price * TAX_RATE) / 12;
    var insM = (price / 1000) * INS_HOA_MONTHLY_PER_1000;
    var housing = pi + taxM + insM;
    var downPct = price > 0 ? (down / price) * 100 : 0;

    // "Comfort" assessment vs. how aggressive the DTI target is.
    var tone, label;
    if (dti <= 33 && downPct >= 18) {
      tone = "ok";
      label = "Comfortable";
    } else if (dti <= 40) {
      tone = "warn";
      label = "Stretch";
    } else {
      tone = "danger";
      label = "Aggressive";
    }
    if (housing <= 0) {
      tone = "danger";
      label = "Debts too high";
    }

    return {
      income: income,
      down: down,
      dti: dti,
      price: price,
      loan: loan,
      pi: pi,
      taxM: taxM,
      insM: insM,
      housing: housing,
      downPct: downPct,
      tone: tone,
      label: label,
    };
  }

  /* ---------- gauge ---------- */
  var GAUGE_LEN = 283; // length of the semicircle arc path
  var GAUGE_MIN = 150000;
  var GAUGE_MAX = 1500000;

  function setGauge(price) {
    var t = clamp((price - GAUGE_MIN) / (GAUGE_MAX - GAUGE_MIN), 0, 1);
    var fill = document.getElementById("gauge-fill");
    fill.style.strokeDashoffset = String(GAUGE_LEN - GAUGE_LEN * t);
    var needle = document.getElementById("gauge-needle");
    var deg = -90 + t * 180;
    needle.style.transform = "rotate(" + deg + "deg)";
  }

  /* ---------- render results ---------- */
  function set(id, txt) {
    document.getElementById(id).textContent = txt;
  }

  var lastMaxPrice = 0;

  function render() {
    var r = compute();
    lastMaxPrice = r.price;

    // headline
    set("max-price", money(r.price));
    var low = r.price * 0.85;
    set("price-range", "Sweet spot " + compact(low) + " – " + compact(r.price));

    // gauge
    setGauge(r.price);

    // status chip
    var chip = document.getElementById("status-chip");
    chip.textContent = r.label;
    chip.setAttribute("data-tone", r.tone);

    // metrics
    set("m-payment", money(r.housing));
    set("m-payment-sub", "at " + r.dti + "% DTI");
    set("m-loan", money(r.loan));
    set("m-income", money(r.income));
    set("m-down", Math.round(r.downPct) + "%");
    set("m-down-sub", money(r.down) + " cash");

    // breakdown
    var total = r.housing > 0 ? r.housing : 1;
    document.getElementById("bar-pi").style.width =
      (r.pi / total) * 100 + "%";
    document.getElementById("bar-tax").style.width =
      (r.taxM / total) * 100 + "%";
    document.getElementById("bar-ins").style.width =
      (r.insM / total) * 100 + "%";
    set("val-pi", money(r.pi));
    set("val-tax", money(r.taxM));
    set("val-ins", money(r.insM));

    renderCards(r.price);
  }

  /* ---------- listing cards ---------- */
  var cardsEl = document.getElementById("cards");

  function payForPrice(price) {
    // quick payment preview using current rate/term and current down (capped).
    var rate = num("rate");
    var term = parseInt(
      document.querySelector('input[name="term"]:checked').value,
      10
    );
    var down = Math.min(num("down"), price * 0.4);
    var loan = Math.max(0, price - down);
    var pi = monthlyPI(loan, rate, term);
    var taxM = (price * TAX_RATE) / 12;
    var insM = (price / 1000) * INS_HOA_MONTHLY_PER_1000;
    return pi + taxM + insM;
  }

  function renderCards(maxPrice) {
    cardsEl.innerHTML = "";
    var fits = 0;
    LISTINGS.forEach(function (l) {
      var inRange = l.price <= maxPrice + 1;
      if (inRange) fits++;
      var card = document.createElement("article");
      card.className = "card" + (inRange ? "" : " out-of-range");

      var pay = payForPrice(l.price);
      var badgeHtml = inRange
        ? '<span class="badge fit">In your range</span>'
        : '<span class="badge over">Over by ' +
          compact(l.price - maxPrice) +
          "</span>";

      card.innerHTML =
        '<div class="photo" style="background:' +
        l.grad +
        ";background-image:" +
        l.overlay +
        "," +
        l.grad +
        '">' +
        '<div class="photo-badges">' +
        badgeHtml +
        '<span class="badge price">' +
        compact(l.price) +
        "</span>" +
        "</div></div>" +
        '<div class="card-body">' +
        '<h3 class="card-title">' +
        l.title +
        "</h3>" +
        '<p class="card-addr">' +
        l.addr +
        "</p>" +
        '<div class="card-meta">' +
        '<span class="chip">' +
        l.beds +
        " bd</span>" +
        '<span class="chip">' +
        l.baths +
        " ba</span>" +
        '<span class="chip">' +
        l.sqft.toLocaleString() +
        " sqft</span>" +
        "</div>" +
        '<div class="card-foot">' +
        '<span class="agent">Listed by <strong>' +
        l.agent +
        "</strong></span>" +
        '<span class="pay-note">~' +
        money(pay) +
        "/mo</span>" +
        "</div>" +
        "</div>";

      cardsEl.appendChild(card);
    });

    var summary = document.getElementById("match-summary");
    summary.textContent =
      fits +
      " of " +
      LISTINGS.length +
      " listings fit your recommended price.";
  }

  /* ---------- bind number <-> range pairs + outputs ---------- */
  function bindPair(numId, rangeId, outId, formatter) {
    var n = document.getElementById(numId);
    var rng = document.getElementById(rangeId);

    function syncFromNum() {
      var v = clamp(parseFloat(n.value) || 0, parseFloat(rng.min), parseFloat(rng.max));
      rng.value = String(v);
      paintRange(rng);
      document.getElementById(outId).textContent = formatter(parseFloat(n.value) || 0);
      render();
    }
    function syncFromRange() {
      n.value = rng.value;
      paintRange(rng);
      document.getElementById(outId).textContent = formatter(parseFloat(rng.value));
      render();
    }

    n.addEventListener("input", syncFromNum);
    rng.addEventListener("input", syncFromRange);
    paintRange(rng);
  }

  bindPair("income", "income-range", "income-out", money);
  bindPair("debts", "debts-range", "debts-out", money);
  bindPair("down", "down-range", "down-out", money);

  // standalone sliders (rate, dti)
  var rateEl = document.getElementById("rate");
  rateEl.addEventListener("input", function () {
    paintRange(rateEl);
    set("rate-out", parseFloat(rateEl.value).toFixed(2) + "%");
    render();
  });
  paintRange(rateEl);

  var dtiEl = document.getElementById("dti");
  dtiEl.addEventListener("input", function () {
    paintRange(dtiEl);
    set("dti-out", Math.round(parseFloat(dtiEl.value)) + "%");
    render();
  });
  paintRange(dtiEl);

  // term radios
  Array.prototype.forEach.call(
    document.querySelectorAll('input[name="term"]'),
    function (el) {
      el.addEventListener("change", render);
    }
  );

  /* ---------- reset ---------- */
  var DEFAULTS = {
    income: 140000,
    debts: 650,
    down: 90000,
    rate: 6.5,
    dti: 36,
    term: "30",
  };

  document.getElementById("reset-btn").addEventListener("click", function () {
    document.getElementById("income").value = DEFAULTS.income;
    document.getElementById("income-range").value = DEFAULTS.income;
    document.getElementById("debts").value = DEFAULTS.debts;
    document.getElementById("debts-range").value = DEFAULTS.debts;
    document.getElementById("down").value = DEFAULTS.down;
    document.getElementById("down-range").value = DEFAULTS.down;
    document.getElementById("rate").value = DEFAULTS.rate;
    document.getElementById("dti").value = DEFAULTS.dti;
    document.querySelector(
      'input[name="term"][value="' + DEFAULTS.term + '"]'
    ).checked = true;

    set("income-out", money(DEFAULTS.income));
    set("debts-out", money(DEFAULTS.debts));
    set("down-out", money(DEFAULTS.down));
    set("rate-out", DEFAULTS.rate.toFixed(2) + "%");
    set("dti-out", DEFAULTS.dti + "%");

    ["income-range", "debts-range", "down-range", "rate", "dti"].forEach(
      function (id) {
        paintRange(document.getElementById(id));
      }
    );
    render();
    toast("Reset to sample buyer profile");
  });

  /* ---------- save ---------- */
  document.getElementById("save-btn").addEventListener("click", function () {
    toast("Estimate saved — " + money(lastMaxPrice) + " max. Scroll to your matches.");
    document.getElementById("listings").scrollIntoView({ behavior: "smooth", block: "start" });
  });

  /* ---------- init ---------- */
  render();
})();

snippets.css:
:root {
  --cream: #f4efe4;
  --paper: #faf7f0;
  --white: #ffffff;
  --newsprint: #efe9da;
  --ink: #16130f;
  --ink-2: #2b2620;
  --ink-3: #4a443b;
  --muted: #7a7164;
  --red: #b4291f;
  --red-d: #8f1f17;
  --red-50: #f3dcd9;
  --rule: rgba(22, 19, 15, 0.16);
  --rule-2: rgba(22, 19, 15, 0.3);
  --rule-hair: rgba(22, 19, 15, 0.1);
  --ok: #2f7d4f;
  --warn: #b67a18;
  --danger: #b4291f;
  --r-sm: 4px;
  --r-md: 8px;
  --r-lg: 12px;

  --serif: "Playfair Display", "Times New Roman", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  /* JS-controlled body type scale */
  --type-scale: 1;
  --body-size: calc(1rem * var(--type-scale));
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background:
    radial-gradient(120% 80% at 50% -10%, rgba(255, 255, 255, 0.5), transparent 60%),
    var(--cream);
  color: var(--ink);
  font-family: var(--sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.skip-link {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--ink);
  color: var(--paper);
  padding: 10px 16px;
  z-index: 50;
  font: 600 13px/1 var(--sans);
}
.skip-link:focus {
  left: 12px;
  top: 12px;
}

.sheet {
  max-width: 1180px;
  margin: 0 auto;
  padding: 28px clamp(14px, 3.5vw, 40px) 48px;
  background:
    linear-gradient(180deg, var(--paper), var(--paper)) padding-box;
}

/* ========================= MASTHEAD ========================= */
.masthead {
  text-align: center;
}

.masthead__strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 6px 22px;
  font: 600 11px/1.3 var(--sans);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-3);
  padding: 9px 0;
}
.masthead__strip--top {
  border-bottom: 1px solid var(--rule-2);
  justify-content: space-between;
}
.masthead__strip--bottom {
  border-top: 2px solid var(--ink);
  border-bottom: 1px solid var(--rule-2);
  justify-content: space-between;
  gap: 6px 16px;
}
.strip__item--motto {
  font-style: italic;
  font-family: var(--serif);
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: none;
  color: var(--muted);
}
.strip__label {
  color: var(--muted);
  margin-right: 5px;
}
.strip__item--clock time {
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.08em;
}
.strip__item--price,
.strip__item--edition {
  color: var(--red-d);
}
.strip__day {
  font-weight: 700;
}

.nameplate {
  padding: clamp(8px, 2vw, 18px) 0 4px;
}
.nameplate__title {
  margin: 0;
  font-family: var(--serif);
  font-weight: 900;
  font-size: clamp(2.6rem, 9vw, 6.2rem);
  line-height: 0.95;
  letter-spacing: -0.01em;
  color: var(--ink);
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.4);
}

/* ========================= SECTION NAV ========================= */
.sectnav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 14px;
  padding: 8px 0;
  border-top: 1px solid var(--rule);
  border-bottom: 3px double var(--rule-2);
  position: sticky;
  top: 0;
  background: var(--paper);
  z-index: 20;
}
.sectnav__list {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 4px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.sectnav__list a {
  display: inline-block;
  padding: 5px 11px;
  font: 700 11.5px/1 var(--sans);
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--ink-2);
  text-decoration: none;
  border-radius: var(--r-sm);
  transition: background 0.15s ease, color 0.15s ease;
}
.sectnav__list a:hover,
.sectnav__list a:focus-visible {
  background: var(--ink);
  color: var(--paper);
  outline: none;
}
.sectnav__list a.is-active {
  color: var(--red-d);
  background: var(--red-50);
}

.textsize {
  display: flex;
  align-items: center;
  gap: 5px;
}
.textsize__label {
  font: 600 10px/1 var(--sans);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
  margin-right: 2px;
}
.textsize__btn {
  font: 700 13px/1 var(--serif);
  min-width: 30px;
  height: 28px;
  padding: 0 8px;
  border: 1px solid var(--rule-2);
  background: var(--white);
  color: var(--ink);
  border-radius: var(--r-sm);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.05s ease;
}
.textsize__btn:hover {
  background: var(--newsprint);
}
.textsize__btn:active {
  transform: translateY(1px);
}
.textsize__btn:focus-visible {
  outline: 2px solid var(--red);
  outline-offset: 1px;
}

/* ========================= KICKERS / SHARED ========================= */
.kicker {
  margin: 0 0 6px;
  font: 700 10.5px/1.2 var(--sans);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.kicker--red {
  color: var(--red);
}
.kicker--red::before {
  content: "";
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 7px;
  background: var(--red);
  border-radius: 50%;
  vertical-align: 1px;
}

.byline {
  margin: 0 0 10px;
  font: 600 12px/1.4 var(--sans);
  color: var(--ink-2);
}
.byline .dateline {
  color: var(--muted);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 11px;
}

/* ========================= MAIN GRID ========================= */
.grid {
  display: grid;
  grid-template-columns: minmax(0, 2.1fr) minmax(0, 1.35fr) minmax(0, 1fr);
  gap: 0;
  margin-top: 20px;
}
.grid > .lead {
  padding-right: clamp(16px, 2.5vw, 30px);
  border-right: 1px solid var(--rule);
}
.grid > .secondary {
  padding: 0 clamp(16px, 2.5vw, 30px);
  border-right: 1px solid var(--rule);
}
.grid > .sidebar {
  padding-left: clamp(16px, 2.5vw, 28px);
}

/* ========================= LEAD STORY ========================= */
.lead__headline {
  margin: 4px 0 10px;
  font-family: var(--serif);
  font-weight: 800;
  font-size: clamp(1.9rem, 4.2vw, 3.2rem);
  line-height: 1.02;
  letter-spacing: -0.01em;
  color: var(--ink);
}
.lead__deck {
  margin: 0 0 16px;
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: clamp(1.05rem, 1.7vw, 1.3rem);
  line-height: 1.35;
  color: var(--ink-3);
  padding-bottom: 14px;
  border-bottom: 1px solid var(--rule);
}

.lead__body {
  font-size: var(--body-size);
  color: var(--ink-2);
  text-align: justify;
  hyphens: auto;
}
.lead__body p {
  margin: 0 0 0.85em;
}
.lead__lede {
  margin-top: 14px;
}
.lead__lede::first-letter {
  float: left;
  font-family: var(--serif);
  font-weight: 800;
  font-size: 3.6em;
  line-height: 0.74;
  padding: 6px 10px 0 0;
  color: var(--red-d);
}

@media (min-width: 880px) {
  .lead__body {
    column-count: 2;
    column-gap: 28px;
    column-rule: 1px solid var(--rule-hair);
  }
  .lead__body .pullquote {
    column-span: all;
  }
}

.jump-cont {
  font-style: italic;
  font-family: var(--serif);
  color: var(--red-d);
  white-space: nowrap;
}

/* ========================= PULL QUOTE ========================= */
.pullquote {
  margin: 18px 0;
  padding: 14px 0;
  border-top: 2px solid var(--ink);
  border-bottom: 2px solid var(--ink);
  font-family: var(--serif);
  font-weight: 600;
  font-size: clamp(1.3rem, 2.4vw, 1.85rem);
  line-height: 1.18;
  color: var(--ink);
  text-align: left;
  hyphens: none;
}
.pullquote cite {
  display: block;
  margin-top: 10px;
  font-family: var(--sans);
  font-style: normal;
  font-weight: 600;
  font-size: 0.66em;
  letter-spacing: 0.04em;
  color: var(--red-d);
}

/* ========================= FIGURES / PRESS PHOTOS ========================= */
.figure {
  margin: 0 0 16px;
}
.press-photo {
  width: 100%;
  border: 1px solid var(--rule-2);
  border-radius: var(--r-sm);
  filter: contrast(1.04) saturate(0.9);
}
.figure--hero .press-photo {
  aspect-ratio: 16 / 9;
}
.figure--inline .press-photo {
  aspect-ratio: 4 / 3;
}
.figure--side .press-photo {
  aspect-ratio: 3 / 4;
}

/* Duotone-ink / red "press" imagery via layered gradients */
.press-photo--harbor {
  background:
    linear-gradient(180deg, rgba(244, 239, 228, 0.35), rgba(22, 19, 15, 0.55)),
    radial-gradient(80% 60% at 22% 22%, rgba(180, 41, 31, 0.42), transparent 55%),
    radial-gradient(120% 90% at 78% 90%, rgba(43, 38, 32, 0.9), transparent 60%),
    repeating-linear-gradient(96deg, rgba(22, 19, 15, 0.16) 0 2px, transparent 2px 7px),
    linear-gradient(120deg, #6f5a4a, #2b2620 70%);
}
.press-photo--river {
  background:
    linear-gradient(180deg, rgba(244, 239, 228, 0.4), rgba(74, 68, 59, 0.5)),
    radial-gradient(90% 70% at 30% 10%, rgba(212, 196, 160, 0.6), transparent 60%),
    linear-gradient(160deg, #b8ab87 0%, #7a7164 45%, #3b352d 100%),
    repeating-linear-gradient(-12deg, rgba(255, 255, 255, 0.06) 0 1px, transparent 1px 9px);
}
.press-photo--portrait {
  background:
    linear-gradient(180deg, rgba(244, 239, 228, 0.25), rgba(22, 19, 15, 0.6)),
    radial-gradient(60% 45% at 50% 32%, rgba(216, 198, 178, 0.85), transparent 60%),
    radial-gradient(120% 80% at 50% 120%, rgba(143, 31, 23, 0.5), transparent 55%),
    linear-gradient(135deg, #5a4a3e, #211d18);
}

.figure__caption {
  margin-top: 7px;
  font: italic 500 12.5px/1.4 var(--serif);
  color: var(--ink-3);
  border-left: 2px solid var(--red);
  padding-left: 9px;
}
.figure__credit {
  display: inline;
  font: 600 10.5px/1.4 var(--sans);
  font-style: normal;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ========================= SECONDARY COLUMN ========================= */
.secondary {
  font-size: calc(0.95rem * var(--type-scale));
}
.story {
  padding-bottom: 16px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--rule);
}
.story:last-child {
  border-bottom: 0;
  margin-bottom: 0;
}
.story__headline {
  margin: 0 0 8px;
  font-family: var(--serif);
  font-weight: 700;
  font-size: clamp(1.15rem, 1.9vw, 1.45rem);
  line-height: 1.12;
  color: var(--ink);
}
.story__headline:hover {
  color: var(--ink-2);
}
.story p {
  margin: 0 0 0.7em;
  color: var(--ink-2);
  text-align: justify;
  hyphens: auto;
}
.story p:first-of-type::first-letter {
  font-weight: 600;
}

/* ========================= SIDEBAR ========================= */
.sidebar__title,
.briefs__title {
  margin: 0 0 12px;
  padding-bottom: 7px;
  font: 700 12px/1 var(--sans);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--ink);
  border-bottom: 2px solid var(--ink);
}

.morelist {
  list-style: none;
  margin: 0 0 18px;
  padding: 0;
}
.morelist__item {
  padding: 11px 0;
  border-bottom: 1px solid var(--rule-hair);
}
.morelist__item:first-child {
  padding-top: 0;
}
.morelist__link {
  display: block;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.05rem;
  line-height: 1.16;
  color: var(--ink);
  text-decoration: none;
  transition: color 0.15s ease;
}
.morelist__link:hover,
.morelist__link:focus-visible {
  color: var(--red-d);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
  outline: none;
}
.morelist__meta {
  margin: 5px 0 0;
  font: 600 10.5px/1 var(--sans);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

.weatherbox {
  margin-top: 16px;
  padding: 12px 14px;
  background: var(--newsprint);
  border: 1px solid var(--rule);
  border-radius: var(--r-sm);
}
.weatherbox__title {
  margin: 0 0 8px;
  font: 700 10.5px/1 var(--sans);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-2);
}
.weatherbox__list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.weatherbox__list li {
  display: grid;
  grid-template-columns: 1fr 1.4fr auto;
  align-items: center;
  gap: 8px;
  padding: 5px 0;
  font: 600 12px/1 var(--sans);
  color: var(--ink-2);
  border-top: 1px solid var(--rule-hair);
}
.weatherbox__list li:first-child {
  border-top: 0;
}
.wx {
  font-weight: 500;
  font-size: 11px;
  letter-spacing: 0.04em;
}
.wx--sun {
  color: var(--warn);
}
.wx--cloud {
  color: var(--muted);
}
.wx--rain {
  color: #3a6ea5;
}

/* ========================= BRIEFS ========================= */
.briefs {
  margin-top: 26px;
  padding-top: 18px;
  border-top: 3px double var(--rule-2);
}
.briefs__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
}
.brief {
  padding: 0 18px;
  border-left: 1px solid var(--rule);
  font-size: calc(0.9rem * var(--type-scale));
}
.brief:first-child {
  padding-left: 0;
  border-left: 0;
}
.brief:last-child {
  padding-right: 0;
}
.brief__text {
  margin: 0;
  color: var(--ink-2);
  text-align: justify;
  hyphens: auto;
}

/* ========================= COLOPHON ========================= */
.colophon {
  margin-top: 28px;
  padding-top: 14px;
  border-top: 1px solid var(--rule);
  text-align: center;
  font: italic 500 12px/1.5 var(--serif);
  color: var(--muted);
}

/* ========================= TOAST ========================= */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 18px);
  background: var(--ink);
  color: var(--paper);
  padding: 11px 18px;
  border-radius: var(--r-md);
  font: 600 13px/1.2 var(--sans);
  letter-spacing: 0.01em;
  box-shadow: 0 6px 22px rgba(22, 19, 15, 0.28);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s ease, transform 0.22s ease;
  z-index: 60;
  max-width: 88vw;
}
.toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}
.toast__accent {
  color: var(--red-50);
  font-weight: 700;
}

/* ========================= RESPONSIVE ========================= */
@media (max-width: 980px) {
  .grid {
    grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr);
  }
  .grid > .sidebar {
    grid-column: 1 / -1;
    margin-top: 22px;
    padding-left: 0;
    padding-top: 18px;
    border-top: 3px double var(--rule-2);
  }
  .grid > .secondary {
    border-right: 0;
    padding-right: 0;
  }
  .sidebar {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px 28px;
    align-items: start;
  }
  .sidebar__title {
    grid-column: 1 / -1;
  }
}

@media (max-width: 720px) {
  .grid {
    grid-template-columns: 1fr;
  }
  .grid > .lead,
  .grid > .secondary {
    border-right: 0;
    padding: 0;
  }
  .grid > .secondary {
    margin-top: 22px;
    padding-top: 18px;
    border-top: 3px double var(--rule-2);
  }
  .lead__body {
    column-count: 1 !important;
  }
  .briefs__grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .brief {
    padding: 12px 0;
    border-left: 0;
    border-top: 1px solid var(--rule-hair);
  }
  .brief:nth-child(odd) {
    padding-right: 14px;
  }
  .brief:nth-child(even) {
    padding-left: 14px;
    border-left: 1px solid var(--rule);
  }
  .sidebar {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 460px) {
  .masthead__strip {
    letter-spacing: 0.08em;
    gap: 4px 12px;
  }
  .strip__item--motto {
    display: none;
  }
  .sectnav {
    position: static;
  }
  .briefs__grid {
    grid-template-columns: 1fr;
  }
  .brief {
    padding: 12px 0 !important;
    border-left: 0 !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition-duration: 0.01ms !important;
  }
}

