  text-decoration: none;
}
.crumbs a:hover {
  color: var(--bone);
}
.crumbs strong {
  color: var(--gold-light);
  font-weight: 600;
}

/* ── Layout ── */
.detail {
  max-width: 1180px;
  margin: 0 auto;
  padding: 28px 32px 72px;
  display: grid;
  grid-template-columns: 1fr 360px;
  gap: 36px;
  align-items: start;
}

/* ── Gallery ── */
.gallery {
  margin-bottom: 30px;
}
.gallery-main {
  height: 420px;
  border-radius: var(--r-lg);
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #3a5180, #1a2b4a);
  transition: background 0.3s;
}
.gallery-main::after {
  content: attr(data-caption);
  position: absolute;
  left: 18px;
  bottom: 16px;
