}
.thumb[data-shot="1"] {
  background: linear-gradient(135deg, #6c7280, #2e3a52);
}
.thumb[data-shot="2"] {
  background: linear-gradient(135deg, var(--gold-d), #5a4a1e);
}
.thumb[data-shot="3"] {
  background: linear-gradient(135deg, #4a6da0, #243a5e);
}
.thumb::after {
  content: attr(data-label);
  position: absolute;
  inset: auto 0 0 0;
  font-size: 0.62rem;
  font-weight: 600;
  color: var(--bone);
  background: rgba(15, 29, 54, 0.55);
