}
.specs {
  font-size: 0.92rem;
  color: var(--warm-gray);
}
.rating {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
  font-size: 0.88rem;
}
.stars {
  color: var(--gold);
