  border-top: 1px solid var(--line);
}
.block h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.7rem;
  color: var(--navy-d);
  margin-bottom: 14px;
}
.block p {
  font-size: 0.96rem;
  line-height: 1.7;
  color: var(--ink-2);
