}
.rate-name {
  display: block;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--navy-d);
}
.rate-policy {
  display: block;
  font-size: 0.82rem;
  font-weight: 600;
  margin-top: 3px;
}
.rate-policy.green {
  color: var(--success);
}
.rate-policy.red {
  color: var(--danger);
}
.rate-extras {
  display: block;
  font-size: 0.78rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.rate-price {
  text-align: right;
  white-space: nowrap;
}
.rate-price strong {
  font-family: var(--font-display);
  font-size: 1.7rem;
  color: var(--navy-d);
}
.rate-price small {
  display: block;
  font-size: 0.74rem;
  color: var(--warm-gray);
}

/* ── Booking sidebar ── */
.booking {
  position: sticky;
  top: 24px;
}
.booking-card {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-2);
  padding: 22px 22px 24px;
}
.bc-eyebrow {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--gold-d);
  font-weight: 700;
  margin-bottom: 12px;
}
.bc-dates {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 12px 14px;
}
.bc-dates small {
  display: block;
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--warm-gray);
  font-weight: 600;
}
.bc-dates strong {
  font-size: 0.92rem;
  color: var(--navy-d);
  font-weight: 600;
}
.bc-arrow {
  color: var(--gold-d);
  font-weight: 700;
}
.bc-meta {
  font-size: 0.82rem;
  color: var(--warm-gray);
  margin: 12px 0 16px;
}
.bc-lines {
  list-style: none;
  border-top: 1px solid var(--line);
  padding-top: 14px;
}
.bc-lines li {
  display: flex;
  justify-content: space-between;
  font-size: 0.88rem;
  color: var(--ink-2);
  padding: 6px 0;
}
.num {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--navy-d);
  font-variant-numeric: tabular-nums;
}
.num.green {
  color: var(--success);
}
.bc-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-top: 12px;
  padding-top: 14px;
  border-top: 1px solid var(--line-strong);
}
.bc-total span {
  font-size: 0.96rem;
  font-weight: 600;
  color: var(--ink);
}
.bc-total strong {
  font-family: var(--font-display);
  font-size: 2.1rem;
  color: var(--navy-d);
  font-variant-numeric: tabular-nums;
}
.bc-plan {
  font-size: 0.78rem;
  color: var(--success);
  font-weight: 600;
  margin: 8px 0 14px;
}
.reserve-btn {
  width: 100%;
  background: var(--gold);
  color: var(--navy-d);
  border: none;
  font-family: inherit;
  font-weight: 700;
  font-size: 1rem;
  padding: 14px;
  border-radius: var(--r-md);
  cursor: pointer;
}
.reserve-btn:hover {
  background: var(--gold-light);
}
.bc-fine {
  font-size: 0.74rem;
  color: var(--warm-gray);
  text-align: center;
  margin-top: 10px;
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 12px 22px;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 50;
}

/* ── Responsive ── */
@media (max-width: 940px) {
  .detail {
    grid-template-columns: 1fr;
  }
  .booking {
    position: static;
  }
  .gallery-main {
    height: 320px;
  }
}
@media (max-width: 560px) {
  .topbar {
    padding: 12px 18px;
    flex-wrap: wrap;
    gap: 12px;
  }
  .detail {
    padding: 22px 18px 56px;
  }
  .head h1 {
    font-size: 2.2rem;
  }
  .amenities {
    grid-template-columns: 1fr;
  }
  .rate {
    grid-template-columns: 20px 1fr;
  }
  .rate-price {
    grid-column: 2;
    text-align: left;
  }
}

