  position: relative;
}
.sb-link:hover {
  background: rgba(255, 255, 255, 0.06);
  color: var(--bone);
}
.sb-link.is-active {
  background: rgba(201, 166, 73, 0.15);
  color: var(--gold-light);
  font-weight: 600;
}
.sb-icon {
  width: 18px;
  text-align: center;
  font-size: 0.9rem;
  flex-shrink: 0;
}
.sb-badge {
  margin-left: auto;
  background: var(--gold);
  color: var(--navy-d);
  font-size: 0.66rem;
  font-weight: 700;
  border-radius: 999px;
  padding: 2px 7px;
  min-width: 20px;
  text-align: center;
}
.sb-footer {
  padding: 16px 18px 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.sb-foot-label {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: rgba(251, 248, 242, 0.45);
