  margin-bottom: 4px;
}
.sb-countdown {
  font-family: var(--font-mono);
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--gold-light);
  font-variant-numeric: tabular-nums;
}

/* ── Main area ── */
.main-area {
  background: var(--cream);
  overflow-y: auto;
  min-height: 0;
}

/* ── Tab panels ── */
.tab-panel {
  padding: 28px 28px 40px;
  max-width: 800px;
}
.panel-head {
  margin-bottom: 24px;
}
.panel-head h1 {
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 700;
