  letter-spacing: -0.01em;
}
.panel-sub {
  font-size: 0.88rem;
  color: var(--warm-gray);
  margin-top: 4px;
}

/* ── Room hero ── */
.room-hero {
  border-radius: var(--r-lg);
  overflow: hidden;
  background: var(--bone);
  border: 1px solid var(--line-strong);
  margin-bottom: 20px;
  box-shadow: var(--shadow-1);
}
.room-hero-img {
  height: 160px;
  background: linear-gradient(135deg, var(--navy-2) 0%, var(--navy-d) 100%);
