}
.room-hero-img::after {
  content: "Room 302 · Deluxe Double";
  position: absolute;
  bottom: 12px;
  left: 16px;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: rgba(251, 248, 242, 0.55);
