}
.rh-name {
  font-family: var(--font-display);
  font-size: 1.45rem;
  font-weight: 700;
  color: var(--navy-d);
}
.rh-specs {
  font-size: 0.82rem;
  color: var(--warm-gray);
  margin-top: 4px;
