/* ── Facts grid ── */
.facts-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}
.fact-card {
  background: var(--bone);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-md);
