  border-radius: var(--r-md);
  overflow: hidden;
  box-shadow: var(--shadow-1);
}
.info-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 11px 18px;
  border-bottom: 1px solid var(--line);
  gap: 12px;
  font-size: 0.88rem;
}
.info-row:last-child {
  border-bottom: none;
}
.ir-label {
  color: var(--warm-gray);
  font-weight: 500;
}
.ir-val {
  font-weight: 500;
  color: var(--ink);
  text-align: right;
}
.ir-val.mono {
  font-family: var(--font-mono);
  font-size: 0.84rem;
  font-variant-numeric: tabular-nums;
}
.ir-val.strong {
  font-weight: 700;
  font-size: 1rem;
  color: var(--navy-d);
}

/* ── Folio table ── */
.folio-wrap {
  background: var(--bone);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-md);
  overflow: hidden;
  box-shadow: var(--shadow-1);
  margin-bottom: 16px;
  overflow-x: auto;
}
.folio-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.86rem;
}
.folio-table thead {
  background: var(--cream);
  border-bottom: 1px solid var(--line-strong);
}
.folio-table th {
  padding: 9px 14px;
  text-align: left;
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  font-weight: 700;
}
.col-date {
  width: 88px;
}
.col-amt {
  width: 90px;
  text-align: right;
}
.folio-table td {
  padding: 9px 14px;
  border-bottom: 1px solid var(--line);
