}
.td-date {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  color: var(--warm-gray);
}
.td-amt {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  text-align: right;
}

.folio-totals {
  background: var(--bone);
  border: 1px solid var(--line-strong);
