  border-radius: var(--r-lg);
  padding: 20px;
  margin-bottom: 24px;
  box-shadow: var(--shadow-1);
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.req-form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.field span {
  font-size: 0.74rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--warm-gray);
}
.field select,
.field textarea {
  font-family: inherit;
  font-size: 0.9rem;
  background: var(--cream);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-sm);
  padding: 9px 12px;
  color: var(--ink);
  outline: none;
  resize: vertical;
}
.field select:focus,
.field textarea:focus {
  border-color: var(--gold);
}
.req-form-foot {
  display: flex;
  justify-content: flex-end;
}
.btn-submit {
  font-family: inherit;
  font-size: 0.88rem;
  font-weight: 700;
  padding: 11px 24px;
  background: var(--navy);
  color: var(--bone);
  border: none;
  border-radius: 999px;
  cursor: pointer;
}
.btn-submit:hover {
  background: var(--navy-2);
}

/* ── Request list ── */
.req-list-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--warm-gray);
}
.req-count {
  font-weight: 600;
}
.req-empty {
  font-size: 0.88rem;
  color: var(--warm-gray);
  padding: 20px 0;
  text-align: center;
}
.req-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.req-item {
  background: var(--bone);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-md);
  padding: 14px 16px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  box-shadow: var(--shadow-1);
}
.ri-body {
  flex: 1;
  min-width: 0;
}
.ri-title {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ink);
  margin-bottom: 3px;
}
.ri-meta {
  font-size: 0.76rem;
  color: var(--warm-gray);
}
.ri-notes {
  font-size: 0.8rem;
  color: var(--ink-2);
  margin-top: 4px;
  font-style: italic;
}
.status-pill {
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 4px 10px;
  border-radius: 999px;
  cursor: pointer;
  border: none;
  font-family: inherit;
  white-space: nowrap;
  flex-shrink: 0;
  margin-top: 1px;
}
.pill--pending {
  background: rgba(217, 144, 32, 0.14);
  color: var(--warning);
}
.pill--progress {
  background: rgba(74, 109, 160, 0.14);
  color: var(--info);
}
.pill--done {
  background: rgba(74, 119, 82, 0.14);
  color: var(--success);
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 22px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: 0 10px 30px rgba(22, 30, 44, 0.25);
  z-index: 200;
  white-space: nowrap;
}

/* ── Responsive ── */
@media (max-width: 960px) {
  .shell {
    grid-template-columns: 1fr;
  }
  .sidebar {
    min-height: auto;
    flex-direction: row;
    align-items: center;
    overflow-x: auto;
    padding: 0 12px;
    gap: 8px;
    border-right: none;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  }
  .sb-prop {
    display: none;
  }
  .sb-nav {
    flex-direction: row;
    padding: 0;
    flex: none;
  }
  .sb-footer {
    display: none;
  }
  .facts-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (max-width: 560px) {
  .topbar {
    padding: 0 12px;
  }
  .gc-name {
    display: none;
  }
  .tab-panel {
    padding: 18px 14px 32px;
  }
  .facts-grid {
    grid-template-columns: 1fr 1fr;
  }
  .req-form-row {
    grid-template-columns: 1fr;
  }
  .folio-totals {
    max-width: 100%;
  }
}

