      { d: 6, t: 660, dur: 45, name: "Boxing Burn", trainer: "Marcus Bell", room: "Dock Ring", type: "boxing", intensity: "high", cap: 14, booked: 7 },
    ],
  };

  var LOCATION_LABEL = {
    downtown: { short: "Downtown", full: "Downtown — 12 Forge St" },
    riverside: { short: "Riverside", full: "Riverside — 88 Harbor Ave" },
  };

  var DAY_NAMES = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

  /* ---------- State ---------- */
  var state = {
    location: "downtown",
    type: "all",
    trainer: "all",
    day: 0,
  };

  /* ---------- Helpers ---------- */
  function $(sel, ctx) { return (ctx || document).querySelector(sel); }
  function fmtTime(mins) {
    var h = Math.floor(mins / 60);
    var m = mins % 60;
    var ampm = h >= 12 ? "PM" : "AM";
    var hr = h % 12; if (hr === 0) hr = 12;
    return hr + ":" + (m < 10 ? "0" + m : m) + " " + ampm;
  }
  function jsDayToIndex(js) { return js === 0 ? 6 : js - 1; } // JS Sun=0 -> our Sun=6

  var toastTimer;
  function toast(msg) {
    var el = $("#toast");
    el.textContent = msg;
    el.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { el.classList.remove("show"); }, 2600);
  }

  var TODAY_IDX = jsDayToIndex(new Date().getDay());

  /* ---------- Build day tabs ---------- */
  function buildDayTabs() {
    var tabs = $("#dayTabs");
    tabs.innerHTML = "";
    var base = new Date();
    var todayJs = base.getDay();
    // Find Monday of current week.
    var monday = new Date(base);
    monday.setDate(base.getDate() - ((todayJs + 6) % 7));

    DAY_NAMES.forEach(function (name, i) {
      var dayDate = new Date(monday);
      dayDate.setDate(monday.getDate() + i);
      var btn = document.createElement("button");
      btn.className = "day-tab";
      btn.type = "button";
      btn.setAttribute("role", "tab");
      btn.dataset.day = i;
      if (i === state.day) btn.classList.add("is-active");
      if (i === TODAY_IDX) btn.classList.add("is-today");
      btn.setAttribute("aria-selected", i === state.day ? "true" : "false");
      btn.innerHTML =
        '<span class="dt-day">' + name + "</span>" +
        '<span class="dt-date">' + dayDate.getDate() + "</span>";
      btn.addEventListener("click", function () {
        state.day = i;
        syncTabs();
        renderSchedule();
      });
      tabs.appendChild(btn);
    });
  }

  function syncTabs() {
    var tabs = $("#dayTabs").children;
    for (var i = 0; i < tabs.length; i++) {
      var active = Number(tabs[i].dataset.day) === state.day;
      tabs[i].classList.toggle("is-active", active);
      tabs[i].setAttribute("aria-selected", active ? "true" : "false");
    }
  }

  /* ---------- Trainer dropdown ---------- */
  function buildTrainerOptions() {
    var sel = $("#trainerSelect");
    var trainers = [];
    CLASSES[state.location].forEach(function (c) {
      if (trainers.indexOf(c.trainer) === -1) trainers.push(c.trainer);
    });
    trainers.sort();
    sel.innerHTML = '<option value="all">All trainers</option>';
    trainers.forEach(function (t) {
      var o = document.createElement("option");
      o.value = t;
      o.textContent = t;
      sel.appendChild(o);
    });
    // Reset trainer filter if no longer present.
    if (state.trainer !== "all" && trainers.indexOf(state.trainer) === -1) {
      state.trainer = "all";
    }
    sel.value = state.trainer;
  }

  /* ---------- Render schedule ---------- */
  function intensityLabel(i) {
    return i === "low" ? "Low" : i === "mid" ? "Moderate" : "High";
  }

  function renderSchedule() {
    var container = $("#schedule");
    container.innerHTML = "";
    var list = CLASSES[state.location]
      .filter(function (c) { return c.d === state.day; })
      .filter(function (c) { return state.type === "all" || c.type === state.type; })
      .filter(function (c) { return state.trainer === "all" || c.trainer === state.trainer; })
      .sort(function (a, b) { return a.t - b.t; });

    var nowMins = new Date().getHours() * 60 + new Date().getMinutes();

    if (!list.length) {
      $("#emptyState").hidden = false;
      return;
    }
    $("#emptyState").hidden = true;

    list.forEach(function (c, idx) {
      var spotsLeft = c.cap - c.booked;
      var full = spotsLeft <= 0;
      var isNow = state.day === TODAY_IDX && nowMins >= c.t && nowMins < c.t + c.dur;

      var row = document.createElement("article");
      row.className = "class-row" + (isNow ? " is-now" : "");
      row.style.animationDelay = (idx * 0.04) + "s";

      var spotsClass = full ? "" : spotsLeft <= 3 ? "spots few" : "spots";
      var spotsText = full ? "Class full" : spotsLeft + " spots left";

      row.innerHTML =
        '<div class="cr-time">' +
          "<b>" + fmtTime(c.t) + "</b>" +
          "<span>" + c.dur + " min</span>" +
        "</div>" +
        '<div class="cr-main">' +
          '<h3 class="cr-name">' + c.name + (isNow ? ' <span class="badge high">In session</span>' : "") + "</h3>" +
          '<div class="cr-meta">' +
            '<span class="m-item cr-trainer">' + icon("user") + c.trainer + "</span>" +
            '<span class="m-item">' + icon("pin") + c.room + "</span>" +
            '<span class="m-item">' + icon("tag") + TYPE_LABEL[c.type] + "</span>" +
          "</div>" +
        "</div>" +
        '<div class="cr-side">' +
          '<span class="badge ' + c.intensity + '">' + intensityLabel(c.intensity) + " intensity</span>" +
          (full
            ? '<button class="reserve-btn full" type="button" disabled>Waitlist</button>'
            : '<button class="reserve-btn" type="button">Reserve</button>') +
          '<span class="' + spotsClass + '">' + spotsText + "</span>" +
        "</div>";

      if (!full) {
        row.querySelector(".reserve-btn").addEventListener("click", function () {
          openModal(c);
        });
      } else {
        row.querySelector(".reserve-btn").addEventListener("click", function () {
          toast("Waitlist requested for " + c.name);
        });
        row.querySelector(".reserve-btn").disabled = false;
        row.querySelector(".reserve-btn").style.cursor = "pointer";
      }

      container.appendChild(row);
    });
  }

  function icon(kind) {
    var paths = {
      user: '<path d="M8 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z"/><path d="M2.5 14a5.5 5.5 0 0 1 11 0"/>',
      pin: '<path d="M8 1.5c-2.5 0-4.5 2-4.5 4.5C3.5 9.5 8 14.5 8 14.5s4.5-5 4.5-8.5C12.5 3.5 10.5 1.5 8 1.5Z"/><circle cx="8" cy="6" r="1.6"/>',
      tag: '<path d="M2 2h5l7 7-5 5-7-7V2Z"/><circle cx="5" cy="5" r="1"/>',
    };
    return '<svg width="13" height="13" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round">' + paths[kind] + "</svg>";
  }

  /* ---------- Modal ---------- */
  var activeClass = null;
  function openModal(c) {
    activeClass = c;
    $("#modalClassInfo").innerHTML =
      "<strong>" + c.name + "</strong> · " + fmtTime(c.t) + " with " + c.trainer +
      "<br>" + c.room + " · " + TYPE_LABEL[c.type];
    $("#modal").hidden = false;
    setTimeout(function () { $("#rName").focus(); }, 30);
    document.addEventListener("keydown", onEsc);
  }
  function closeModal() {
    $("#modal").hidden = true;
    $("#reserveForm").reset();
    document.removeEventListener("keydown", onEsc);
  }
  function onEsc(e) { if (e.key === "Escape") closeModal(); }

  /* ---------- Location change ---------- */
  function setLocation(loc) {
    state.location = loc;
    state.trainer = "all";
    var lbl = LOCATION_LABEL[loc];
    $("#heroLocation").textContent = lbl.short;
    $("#footLocation").textContent = lbl.full;
    buildTrainerOptions();
    renderSchedule();
    toast("Showing " + lbl.short + " schedule");
  }

  /* ---------- Wire up ---------- */
  function init() {
    buildDayTabs();
    buildTrainerOptions();
    renderSchedule();

    $("#locationSelect").addEventListener("change", function (e) {
      setLocation(e.target.value);
    });

    $("#typeChips").addEventListener("click", function (e) {
      var chip = e.target.closest(".chip");
      if (!chip) return;
      state.type = chip.dataset.type;
      var chips = $("#typeChips").children;
      for (var i = 0; i < chips.length; i++) chips[i].classList.toggle("is-active", chips[i] === chip);
      renderSchedule();
    });

    $("#trainerSelect").addEventListener("change", function (e) {
      state.trainer = e.target.value;
      renderSchedule();
    });

    $("#trialBtn").addEventListener("click", function () {
      toast("Pick any class below and hit Reserve to start your free trial");
    });
    $("#printBtn").addEventListener("click", function () { window.print(); });

    $("#modalClose").addEventListener("click", closeModal);
    $("#modal").addEventListener("click", function (e) {
      if (e.target === $("#modal")) closeModal();
    });

    $("#reserveForm").addEventListener("submit", function (e) {
      e.preventDefault();
      var name = $("#rName").value.trim();
      var email = $("#rEmail").value.trim();
      if (!name) { toast("Please enter your name"); $("#rName").focus(); return; }
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { toast("Enter a valid email"); $("#rEmail").focus(); return; }
      closeModal();
      toast("Reserved! " + (activeClass ? activeClass.name : "") + " — trial pass sent to " + email);
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

snippets.css:
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Topbar ── */
.topbar {
  background: var(--navy-d);
  color: var(--bone);
  padding: 14px 32px;
  display: flex;
  align-items: center;
  gap: 28px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--bone);
}
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: var(--r-sm);
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.2rem;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
}
.brand-name em {
  font-style: normal;
  color: var(--gold-light);
}
.steps {
  display: flex;
  gap: 8px;
  margin-left: auto;
  list-style: none;
  counter-reset: step;
}
.steps li {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.82rem;
  font-weight: 600;
  color: rgba(251, 248, 242, 0.5);
}
.steps li::before {
  counter-increment: step;
  content: counter(step);
  width: 22px;
  height: 22px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-size: 0.72rem;
  border: 1px solid rgba(251, 248, 242, 0.3);
}
.steps li:not(:last-child)::after {
  content: "";
  width: 22px;
  height: 1px;
  background: rgba(251, 248, 242, 0.2);
}
.steps li.done {
  color: var(--gold-light);
}
.steps li.done::before {
  content: "✓";
  background: var(--gold);
  color: var(--navy-d);
  border-color: var(--gold);
}
.steps li.current {
  color: var(--bone);
}
.steps li.current::before {
  border-color: var(--bone);
  color: var(--bone);
}
.secure {
  font-size: 0.8rem;
  color: rgba(251, 248, 242, 0.66);
}

/* ── Layout ── */
.checkout {
  max-width: 1140px;
  margin: 0 auto;
  padding: 28px 32px 72px;
  display: grid;
  grid-template-columns: 1fr 360px;
  gap: 30px;
  align-items: start;
  position: relative;
}
.form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

/* ── Cards ── */
.card {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px 24px 24px;
}
.card h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.5rem;
  color: var(--navy-d);
  margin-bottom: 16px;
}
.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px 16px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}
.grid-2 .field {
  margin-bottom: 0;
}
.field label {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--ink-2);
}
.field .opt {
  color: var(--warm-gray);
  font-weight: 400;
}
.field input,
.field select,
.field textarea {
  font-family: inherit;
  font-size: 0.92rem;
  color: var(--navy-d);
  background: var(--cream);
  border: 1.5px solid var(--line);
  border-radius: var(--r-sm);
  padding: 11px 13px;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
  width: 100%;
}
.field textarea {
  resize: vertical;
}
.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(201, 166, 73, 0.16);
}
.field input::placeholder,
.field textarea::placeholder {
  color: var(--warm-gray);
}
.err {
  font-size: 0.74rem;
  color: var(--danger);
  font-weight: 600;
  display: none;
}
.field.invalid input,
.field.invalid select {
  border-color: var(--danger);
}
.field.invalid .err {
  display: block;
}

.paybrands {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}
.pb {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--navy-2);
  background: var(--cream);
  border: 1px solid var(--line);
  padding: 5px 10px;
  border-radius: var(--r-sm);
}

.agree {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.84rem;
  color: var(--ink-2);
  margin-top: 4px;
  cursor: pointer;
}
.agree input {
  width: 18px;
  height: 18px;
  margin-top: 1px;
  accent-color: var(--navy);
  flex-shrink: 0;
}
.agree a {
  color: var(--gold-d);
  font-weight: 600;
}
.err-terms {
  margin-top: 6px;
}
.err-terms.show {
  display: block;
}

/* ── Summary ── */
.summary {
  position: sticky;
  top: 24px;
}
.summary-card {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-2);
  padding: 20px 22px 24px;
}
.sum-room {
  display: flex;
  gap: 14px;
  align-items: center;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line);
}
.sum-img {
  width: 64px;
  height: 64px;
  border-radius: var(--r-md);
  flex-shrink: 0;
  background: linear-gradient(135deg, #3a5180, #1a2b4a);
}
.sum-room h3 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.35rem;
  color: var(--navy-d);
}
.sum-room p {
  font-size: 0.82rem;
  color: var(--warm-gray);
}
.sum-meta {
  list-style: none;
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
}
.sum-meta li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 5px 0;
  font-size: 0.84rem;
}
.sum-meta span {
  color: var(--warm-gray);
}
.sum-meta strong {
  color: var(--navy-d);
  font-weight: 600;
  text-align: right;
}
.sum-lines {
  list-style: none;
  padding: 14px 0;
}
.sum-lines li {
  display: flex;
  justify-content: space-between;
  font-size: 0.86rem;
  color: var(--ink-2);
  padding: 5px 0;
}
.num {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--navy-d);
  font-variant-numeric: tabular-nums;
}
.num.green {
  color: var(--success);
  font-family: inherit;
  font-weight: 600;
}
.sum-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-top: 14px;
  border-top: 1px solid var(--line-strong);
}
.sum-total span {
  font-size: 0.96rem;
  font-weight: 600;
}
.sum-total strong {
  font-family: var(--font-display);
  font-size: 2.1rem;
  color: var(--navy-d);
}
.pay-btn {
  width: 100%;
  margin-top: 18px;
  background: var(--gold);
  color: var(--navy-d);
  border: none;
  font-family: inherit;
  font-weight: 700;
  font-size: 0.98rem;
  padding: 14px;
  border-radius: var(--r-md);
  cursor: pointer;
}
.pay-btn:hover:not(:disabled) {
  background: var(--gold-light);
}
.pay-btn:disabled {
  opacity: 0.7;
  cursor: default;
}
.sum-fine {
  font-size: 0.74rem;
  color: var(--warm-gray);
  text-align: center;
  margin-top: 10px;
}

/* ── Confirmed overlay ── */
.confirmed {
  position: fixed;
  inset: 0;
  background: rgba(15, 29, 54, 0.55);
  backdrop-filter: blur(4px);
  display: grid;
  place-items: center;
  z-index: 60;
  padding: 24px;
}
.confirmed-card {
  background: var(--bone);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-2);
  padding: 40px 38px;
  text-align: center;
  max-width: 440px;
  width: 100%;
  animation: pop 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}
@keyframes pop {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.97);
  }
}
.check-ic {
  width: 64px;
  height: 64px;
  border-radius: 999px;
  background: var(--success);
  color: var(--bone);
  font-size: 2rem;
  display: grid;
  place-items: center;
  margin: 0 auto 18px;
}
.confirmed-card h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 2rem;
  color: var(--navy-d);
}
.confirmed-card p {
  font-size: 0.92rem;
  color: var(--ink-2);
  margin-top: 8px;
}
.conf-ref {
  background: var(--cream);
  border: 1px dashed var(--line-strong);
  border-radius: var(--r-md);
  padding: 14px;
  margin: 20px 0;
}
.conf-ref span {
  display: block;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  font-weight: 600;
}
.conf-ref strong {
  font-family: var(--font-mono);
  font-size: 1.4rem;
  color: var(--navy-d);
  letter-spacing: 0.04em;
}
.conf-detail {
  font-size: 0.86rem !important;
}
.conf-btn {
  margin-top: 8px;
  background: var(--navy);
  color: var(--bone);
  border: none;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.92rem;
  padding: 12px 26px;
  border-radius: var(--r-md);
  cursor: pointer;
}
.conf-btn:hover {
  background: var(--navy-d);
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 12px 22px;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 70;
}

/* ── Responsive ── */
@media (max-width: 940px) {
  .checkout {
    grid-template-columns: 1fr;
  }
  .summary {
    position: static;
    order: -1;
  }
}
@media (max-width: 560px) {
  .topbar {
    padding: 12px 18px;
    flex-wrap: wrap;
    gap: 14px;
  }
  .steps {
    order: 3;
    width: 100%;
    margin-left: 0;
    justify-content: center;
  }
  .checkout {
    padding: 22px 18px 56px;
  }
  .grid-2 {
    grid-template-columns: 1fr;
  }
}

/* ── Honor [hidden] over display (overlay/panel toggle fix) ── */
.confirmed[hidden] {
  display: none;
}

