(function () {
  "use strict";

  var CAPACITY = 20;

  // Member states: "expected" | "present" | "noshow" | "promoted"
  var members = [
    { id: 1, name: "Diego Salcedo", tier: "Elite", state: "present" },
    { id: 2, name: "Priya Raman", tier: "Plus", state: "expected" },
    { id: 3, name: "Tomás Bianchi", tier: "Core", state: "present" },
    { id: 4, name: "Hannah Okafor", tier: "Elite", state: "expected" },
    { id: 5, name: "Wei Lin", tier: "Core", state: "noshow" },
    { id: 6, name: "Sofía Marín", tier: "Plus", state: "expected" },
    { id: 7, name: "Marcus Hale", tier: "Core", state: "present" },
    { id: 8, name: "Yuki Tanaka", tier: "Elite", state: "expected" },
    { id: 9, name: "Olivia Brandt", tier: "Day Pass", state: "expected" },
    { id: 10, name: "Kwame Asante", tier: "Plus", state: "promoted" },
    { id: 11, name: "Renata Cardoso", tier: "Core", state: "expected" },
    { id: 12, name: "Felix Norberg", tier: "Core", state: "present" },
  ];

  var TIER_COLORS = {
    Elite: ["#c6ff3a", "#a6e016"],
    Plus: ["#ff6a2b", "#ff8a5a"],
    Core: ["#5e9bff", "#7fb2ff"],
    "Day Pass": ["#8b929c", "#aeb4bd"],
  };

  var STATE_LABEL = {
    expected: "Expected",
    present: "Present",
    noshow: "No-show",
    promoted: "Waitlist · promoted",
  };

  var $ = function (sel) {
    return document.querySelector(sel);
  };

  var rosterEl = $("#roster");
  var searchEl = $("#search");
  var filterBtn = $("#filterToggle");
  var checkAllBtn = $("#checkAll");
  var toastEl = $("#toast");
  var nextId = 100;
  var pendingOnly = false;

  /* ---------- toast ---------- */
  var toastTimer;
  function toast(msg) {
    toastEl.innerHTML = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2400);
  }

  function initials(name) {
    return name
      .trim()
      .split(/\s+/)
      .slice(0, 2)
      .map(function (p) {
        return p.charAt(0).toUpperCase();
      })
      .join("");
  }

  /* ---------- render ---------- */
  function render() {
    rosterEl.innerHTML = "";
    var q = searchEl.value.trim().toLowerCase();
    var shown = 0;

    members.forEach(function (m) {
      var li = document.createElement("li");
      li.className = "row";
      li.dataset.id = String(m.id);
      applyStateClass(li, m.state);

      var matchesQ =
        !q || m.name.toLowerCase().indexOf(q) > -1 || m.tier.toLowerCase().indexOf(q) > -1;
      var matchesFilter = !pendingOnly || m.state === "expected";
      if (!matchesQ || !matchesFilter) {
        li.hidden = true;
      } else {
        shown++;
      }

      var colors = TIER_COLORS[m.tier] || TIER_COLORS["Day Pass"];

      var avatar = document.createElement("div");
      avatar.className = "avatar";
      avatar.style.background = "linear-gradient(135deg," + colors[0] + "," + colors[1] + ")";
      avatar.textContent = initials(m.name);
      avatar.setAttribute("aria-hidden", "true");

      var who = document.createElement("div");
      who.className = "who";
      var nm = document.createElement("div");
      nm.className = "who__name";
      nm.textContent = m.name;
      var sub = document.createElement("div");
      sub.className = "who__sub";
      var tier = document.createElement("span");
      tier.className = "tier tier--" + m.tier.replace(/\s+/g, "");
      tier.textContent = m.tier;
      var tag = document.createElement("span");
      tag.className = "state-tag";
      tag.textContent = STATE_LABEL[m.state];
      sub.appendChild(tier);
      sub.appendChild(tag);
      who.appendChild(nm);
      who.appendChild(sub);

      var actions = document.createElement("div");
      actions.className = "actions";

      var present = m.state === "present" || m.state === "promoted";
      var presentBtn = document.createElement("button");
      presentBtn.type = "button";
      presentBtn.className = "tog" + (present ? " tog--present" : "");
      presentBtn.textContent = present ? "Checked in" : "Check in";
      presentBtn.setAttribute("aria-pressed", present ? "true" : "false");
      presentBtn.addEventListener("click", function () {
        togglePresent(m.id);
      });

      var missBtn = document.createElement("button");
      missBtn.type = "button";
      missBtn.className = "tog tog--miss";
      missBtn.textContent = "No-show";
      missBtn.dataset.active = m.state === "noshow" ? "true" : "false";
      missBtn.setAttribute("aria-pressed", m.state === "noshow" ? "true" : "false");
      missBtn.addEventListener("click", function () {
        toggleNoShow(m.id);
      });

      actions.appendChild(presentBtn);
      actions.appendChild(missBtn);

      li.appendChild(avatar);
      li.appendChild(who);
      li.appendChild(actions);
      rosterEl.appendChild(li);
    });

    if (shown === 0) {
      var empty = document.createElement("li");
      empty.className = "empty";
      empty.textContent = pendingOnly
        ? "No pending members — everyone's accounted for."
        : "No members match your search.";
      rosterEl.appendChild(empty);
    }

    updateStats();
  }

  function applyStateClass(li, state) {
    li.classList.toggle("is-present", state === "present");
    li.classList.toggle("is-noshow", state === "noshow");
    li.classList.toggle("is-promoted", state === "promoted");
  }

  function find(id) {
    for (var i = 0; i < members.length; i++) {
      if (members[i].id === id) return members[i];
    }
    return null;
  }

  function flash(id) {
    var row = rosterEl.querySelector('.row[data-id="' + id + '"]');
    if (!row) return;
    row.classList.remove("flash");
    void row.offsetWidth; // reflow to restart animation
    row.classList.add("flash");
  }

  /* ---------- actions ---------- */
  function togglePresent(id) {
    var m = find(id);
    if (!m) return;
    if (m.state === "present" || m.state === "promoted") {
      m.state = "expected";
      toast(m.name + " set back to expected");
    } else {
      m.state = "present";
      toast('<span class="toast__accent">✓</span> ' + m.name + " checked in");
    }
    render();
    flash(id);
  }

  function toggleNoShow(id) {
    var m = find(id);
    if (!m) return;
    if (m.state === "noshow") {
      m.state = "expected";
      toast(m.name + " cleared");
    } else {
      m.state = "noshow";
      toast(m.name + " marked no-show");
    }
    render();
    flash(id);
  }

  /* ---------- stats ---------- */
  function updateStats() {
    var present = 0,
      expected = 0,
      noshow = 0,
      wait = 0;
    members.forEach(function (m) {
      if (m.state === "present") present++;
      else if (m.state === "promoted") {
        present++;
        wait++;
      } else if (m.state === "noshow") noshow++;
      else expected++;
    });

    $("#statPresent").textContent = present;
    $("#statExpected").textContent = expected;
    $("#statNoShow").textContent = noshow;
    $("#statWait").textContent = wait;

    var enrolled = members.length;
    $("#capCurrent").textContent = enrolled;
    var pct = Math.min(100, Math.round((enrolled / CAPACITY) * 100));
    $("#capFill").style.width = pct + "%";
    var bar = $("#capBar");
    bar.setAttribute("aria-valuenow", String(enrolled));
    bar.setAttribute("aria-valuemax", String(CAPACITY));
  }

  /* ---------- toolbar ---------- */
  searchEl.addEventListener("input", render);

  filterBtn.addEventListener("click", function () {
    pendingOnly = !pendingOnly;
    filterBtn.setAttribute("aria-pressed", pendingOnly ? "true" : "false");
    render();
  });

  checkAllBtn.addEventListener("click", function () {
    var changed = 0;
    members.forEach(function (m) {
      if (m.state === "expected" || m.state === "noshow") {
        m.state = "present";
        changed++;
      }
    });
    render();
    if (changed === 0) {
      toast("Everyone's already checked in");
    } else {
      toast('<span class="toast__accent">✓</span> Checked in ' + changed + " member" + (changed === 1 ? "" : "s"));
    }
  });

  /* ---------- walk-in ---------- */
  $("#walkinForm").addEventListener("submit", function (e) {
    e.preventDefault();
    var nameEl = $("#walkinName");
    var name = nameEl.value.trim();
    if (!name) {
      nameEl.focus();
      toast("Enter a name for the walk-in");
      return;
    }
    if (members.length >= CAPACITY) {
      toast("Class is at capacity (" + CAPACITY + ")");
      return;
    }
    var tier = $("#walkinTier").value;
    var id = nextId++;
    members.push({ id: id, name: name, tier: tier, state: "present" });
    nameEl.value = "";
    pendingOnly = false;
    filterBtn.setAttribute("aria-pressed", "false");
    searchEl.value = "";
    render();
    flash(id);
    toast('<span class="toast__accent">+</span> ' + name + " added and checked in");
  });

  render();
})();

snippets.css:
:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.45), 0 2px 8px rgba(0, 0, 0, 0.35);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background-image:
    radial-gradient(900px 500px at 100% -10%, rgba(198, 255, 58, 0.06), transparent 60%),
    radial-gradient(700px 400px at -10% 110%, rgba(255, 106, 43, 0.07), transparent 55%);
  min-height: 100vh;
}

.app {
  max-width: 720px;
  margin: 0 auto;
  padding: 24px 20px 120px;
}

.eyebrow {
  margin: 0;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
}

/* Header */
.top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}
.brand { display: flex; align-items: center; gap: 14px; }
.logo {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: var(--r-md);
  background: var(--neon-50);
  border: 1px solid var(--line-2);
  font-size: 24px;
}
.top h1 {
  margin: 2px 0 0;
  font-size: 24px;
  font-weight: 900;
  letter-spacing: -0.02em;
}
.clock {
  text-align: right;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 8px 14px;
  box-shadow: var(--shadow);
}
.clock-label {
  display: block;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  font-weight: 700;
}
.clock-time {
  font-variant-numeric: tabular-nums;
  font-size: 22px;
  font-weight: 800;
  color: var(--neon);
}

/* Stats */
.stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 18px;
}
.stat {
  background: linear-gradient(180deg, var(--surface-2), var(--surface));
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px;
  box-shadow: var(--shadow);
}
.stat-label {
  display: block;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  font-weight: 700;
  margin-bottom: 6px;
}
.stat-value {
  font-size: 14px;
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
}
.stat-value b {
  font-size: 22px;
  font-weight: 900;
  color: var(--ink);
}

/* Timer */
.timer-card {
  background: radial-gradient(120% 140% at 50% -20%, rgba(198, 255, 58, 0.1), transparent 60%), var(--surface);
  border: 1px solid var(--line-2);
  border-radius: var(--r-lg);
  padding: 18px;
  margin-bottom: 22px;
  box-shadow: var(--shadow);
  text-align: center;
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}
.timer-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}
.timer-presets { display: flex; gap: 6px; }
.chip {
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  color: var(--ink-2);
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 5px 11px;
  cursor: pointer;
  transition: all 0.15s ease;
}
.chip:hover { border-color: var(--line-2); color: var(--ink); }
.chip.active {
  background: var(--neon-50);
  border-color: var(--neon-d);
  color: var(--neon);
}
.timer-display {
  font-variant-numeric: tabular-nums;
  font-size: clamp(56px, 18vw, 86px);
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1;
  margin: 14px 0 12px;
  color: var(--ink);
}
.timer-display.running { color: var(--neon); }
.timer-display.flash {
  animation: flash 0.4s ease 3;
  color: var(--orange);
}
@keyframes flash {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.25; }
}
.timer-card.alarm {
  border-color: var(--orange);
  box-shadow: 0 0 0 3px var(--orange-soft), var(--shadow);
}
.timer-bar {
  height: 6px;
  border-radius: 999px;
  background: var(--surface-2);
  overflow: hidden;
  margin-bottom: 16px;
}
.timer-bar span {
  display: block;
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, var(--neon-d), var(--neon));
  transform-origin: left;
  transition: width 0.25s linear;
}
.timer-controls { display: flex; gap: 10px; justify-content: center; }

/* Buttons */
.btn {
  font: inherit;
  font-weight: 800;
  border: 1px solid transparent;
  border-radius: var(--r-md);
  padding: 13px 22px;
  cursor: pointer;
  transition: transform 0.08s ease, background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
  letter-spacing: 0.01em;
}
.btn:active { transform: translateY(1px) scale(0.99); }
.btn:focus-visible {
  outline: 3px solid var(--neon);
  outline-offset: 2px;
}
.btn-neon { background: var(--neon); color: #0d0f12; }
.btn-neon:hover { background: var(--neon-d); }
.btn-orange { background: var(--orange); color: #1a0d05; }
.btn-orange:hover { filter: brightness(1.06); }
.btn-ghost {
  background: var(--surface-2);
  color: var(--ink-2);
  border-color: var(--line);
}
.btn-ghost:hover { color: var(--ink); border-color: var(--line-2); }
.btn-sm { padding: 9px 14px; font-size: 13px; border-radius: var(--r-sm); }
.btn-block { width: 100%; padding: 16px; font-size: 16px; }
.btn-paused { background: var(--warn); color: #1a1305; }

/* Exercise cards */
.exercises { display: flex; flex-direction: column; gap: 16px; }
.ex-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 18px;
  box-shadow: var(--shadow);
}
.ex-card.complete {
  border-color: var(--neon-d);
  box-shadow: 0 0 0 1px var(--neon-50), var(--shadow);
}
.ex-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}
.ex-title { display: flex; align-items: center; gap: 12px; }
.ex-index {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: var(--r-sm);
  background: var(--surface-2);
  border: 1px solid var(--line);
  font-weight: 900;
  font-size: 15px;
  color: var(--neon);
  flex: none;
}
.ex-name { margin: 0; font-size: 17px; font-weight: 800; letter-spacing: -0.01em; }
.ex-meta { margin: 1px 0 0; font-size: 12px; color: var(--muted); }
.ex-badge {
  font-size: 12px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--ink-2);
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 5px 12px;
}
.ex-card.complete .ex-badge {
  background: var(--neon-50);
  border-color: var(--neon-d);
  color: var(--neon);
}

.set-head, .set-row {
  display: grid;
  grid-template-columns: 42px 1fr 1fr 48px;
  align-items: center;
  gap: 10px;
}
.set-head {
  padding: 0 4px 8px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
  color: var(--muted);
}
.set-rows { display: flex; flex-direction: column; gap: 8px; }
.set-row {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  padding: 8px 10px;
  transition: background 0.15s ease, border-color 0.15s ease, opacity 0.15s ease;
}
.set-row.done {
  background: var(--neon-50);
  border-color: var(--neon-d);
}
.set-num {
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--ink-2);
  text-align: center;
}
.set-row.done .set-num { color: var(--neon); }
.set-row input {
  font: inherit;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  width: 100%;
  text-align: center;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  color: var(--ink);
  padding: 8px 6px;
  -moz-appearance: textfield;
  appearance: textfield;
}
.set-row input::-webkit-outer-spin-button,
.set-row input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
.set-row input:focus-visible {
  outline: none;
  border-color: var(--neon);
  box-shadow: 0 0 0 2px var(--neon-50);
}
.set-row.done input { opacity: 0.7; }
.check {
  width: 32px;
  height: 32px;
  margin: 0 auto;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 2px solid var(--line-2);
  background: transparent;
  color: transparent;
  cursor: pointer;
  font-size: 16px;
  font-weight: 900;
  transition: all 0.15s ease;
}
.check:hover { border-color: var(--neon); }
.check:focus-visible { outline: 3px solid var(--neon); outline-offset: 2px; }
.set-row.done .check {
  background: var(--neon);
  border-color: var(--neon);
  color: #0d0f12;
}
.set-del {
  background: none;
  border: none;
  color: var(--muted);
  cursor: pointer;
  font-size: 18px;
  line-height: 1;
  padding: 4px;
  display: none;
}

.ex-actions {
  display: flex;
  gap: 10px;
  margin-top: 14px;
  flex-wrap: wrap;
}
.rest-set { color: var(--ink-2); }

/* Finish bar */
.finish-bar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 14px 20px calc(14px + env(safe-area-inset-bottom));
  background: linear-gradient(180deg, transparent, var(--bg) 35%);
}
.finish-bar .btn { max-width: 720px; margin: 0 auto; display: block; }

/* Toast */
.toast-host {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 90px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  pointer-events: none;
  z-index: 50;
  padding: 0 16px;
}
.toast {
  pointer-events: auto;
  max-width: 480px;
  width: 100%;
  background: var(--elevated);
  border: 1px solid var(--line-2);
  border-left: 4px solid var(--neon);
  border-radius: var(--r-md);
  padding: 14px 16px;
  box-shadow: var(--shadow);
  color: var(--ink);
  font-size: 14px;
  font-weight: 600;
  transform: translateY(16px);
  opacity: 0;
  transition: transform 0.25s ease, opacity 0.25s ease;
}
.toast.show { transform: translateY(0); opacity: 1; }
.toast.summary { border-left-color: var(--orange); }
.toast b { font-weight: 800; }
.toast .toast-line { display: block; font-size: 13px; font-weight: 500; color: var(--ink-2); margin-top: 4px; }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap; border: 0;
}

/* Responsive */
@media (max-width: 520px) {
  .app { padding: 18px 14px 110px; }
  .top h1 { font-size: 20px; }
  .stats { gap: 8px; }
  .stat { padding: 11px; }
  .stat-value b { font-size: 18px; }
  .clock { padding: 6px 10px; }
  .clock-time { font-size: 18px; }
  .timer-presets .chip { padding: 5px 9px; }
  .set-head, .set-row { grid-template-columns: 34px 1fr 1fr 44px; gap: 7px; }
  .ex-actions .btn { flex: 1; }
}

