(function () {
  "use strict";

  /* ---------- Seed data (fictional Push Day A) ---------- */
  const workout = [
    {
      name: "Back Squat",
      meta: "Barbell · Legs · 3 min rest",
      rest: 180,
      sets: [
        { weight: 100, reps: 5, done: false },
        { weight: 100, reps: 5, done: false },
        { weight: 100, reps: 5, done: false },
      ],
    },
    {
      name: "Bench Press",
      meta: "Barbell · Chest · 2 min rest",
      rest: 120,
      sets: [
        { weight: 80, reps: 8, done: false },
        { weight: 80, reps: 8, done: false },
        { weight: 75, reps: 10, done: false },
      ],
    },
    {
      name: "Deadlift",
      meta: "Barbell · Posterior · 3 min rest",
      rest: 180,
      sets: [
        { weight: 140, reps: 3, done: false },
        { weight: 140, reps: 3, done: false },
      ],
    },
    {
      name: "Overhead Press",
      meta: "Barbell · Shoulders · 90s rest",
      rest: 90,
      sets: [
        { weight: 45, reps: 8, done: false },
        { weight: 45, reps: 8, done: false },
      ],
    },
  ];

  /* ---------- Toast helper ---------- */
  const toastHost = document.getElementById("toastHost");
  function toast(msg, opts) {
    opts = opts || {};
    const el = document.createElement("div");
    el.className = "toast" + (opts.summary ? " summary" : "");
    el.innerHTML = msg;
    toastHost.appendChild(el);
    requestAnimationFrame(() => el.classList.add("show"));
    const life = opts.life || 3200;
    setTimeout(() => {
      el.classList.remove("show");
      setTimeout(() => el.remove(), 300);
    }, life);
  }

  /* ---------- Render exercises ---------- */
  const root = document.getElementById("exercises");
  const tpl = document.getElementById("exTpl");

  function render() {
    root.innerHTML = "";
    workout.forEach((ex, ei) => {
      const node = tpl.content.cloneNode(true);
      const card = node.querySelector(".ex-card");
      card.dataset.ex = ei;
      node.querySelector(".ex-index").textContent = ei + 1;
      node.querySelector(".ex-name").textContent = ex.name;
      node.querySelector(".ex-meta").textContent = ex.meta;
      node.querySelector(".rest-secs").textContent = ex.rest;
      node.querySelector(".rest-set").dataset.secs = ex.rest;

      const rows = node.querySelector(".set-rows");
      ex.sets.forEach((set, si) => rows.appendChild(buildRow(ei, si, set)));

      updateCard(card, ex);
      root.appendChild(node);

      // re-grab the live card (appendChild moves the fragment children)
      const live = root.querySelector('.ex-card[data-ex="' + ei + '"]');
      updateCard(live, ex);
    });
    recalc();
  }

  function buildRow(ei, si, set) {
    const row = document.createElement("div");
    row.className = "set-row" + (set.done ? " done" : "");
    row.dataset.ex = ei;
    row.dataset.set = si;
    row.innerHTML =
      '<span class="set-num">' + (si + 1) + "</span>" +
      '<input type="number" inputmode="decimal" min="0" step="2.5" class="in-weight" value="' + set.weight + '" aria-label="Weight in kilograms" />' +
      '<input type="number" inputmode="numeric" min="0" step="1" class="in-reps" value="' + set.reps + '" aria-label="Repetitions" />' +
      '<button class="check" aria-label="Mark set ' + (si + 1) + ' done" aria-pressed="' + set.done + '">✓</button>';
    return row;
  }

  function updateCard(card, ex) {
    const done = ex.sets.filter((s) => s.done).length;
    card.querySelector(".ex-badge").textContent = done + "/" + ex.sets.length;
    card.classList.toggle("complete", done === ex.sets.length && ex.sets.length > 0);
  }

  /* ---------- Event delegation ---------- */
  root.addEventListener("click", (e) => {
    const card = e.target.closest(".ex-card");
    if (!card) return;
    const ei = +card.dataset.ex;
    const ex = workout[ei];

    if (e.target.classList.contains("check")) {
      const row = e.target.closest(".set-row");
      const si = +row.dataset.set;
      ex.sets[si].done = !ex.sets[si].done;
      row.classList.toggle("done", ex.sets[si].done);
      e.target.setAttribute("aria-pressed", String(ex.sets[si].done));
      updateCard(card, ex);
      recalc();
      if (ex.sets[si].done) startTimer(ex.rest, true);
      return;
    }

    if (e.target.classList.contains("add-set")) {
      const last = ex.sets[ex.sets.length - 1] || { weight: 20, reps: 8 };
      ex.sets.push({ weight: last.weight, reps: last.reps, done: false });
      const rows = card.querySelector(".set-rows");
      rows.appendChild(buildRow(ei, ex.sets.length - 1, ex.sets[ex.sets.length - 1]));
      updateCard(card, ex);
      recalc();
      toast("Added set to <b>" + ex.name + "</b>");
      return;
    }

    if (e.target.classList.contains("rest-set")) {
      startTimer(+e.target.dataset.secs, true);
      return;
    }
  });

  root.addEventListener("input", (e) => {
    const row = e.target.closest(".set-row");
    if (!row) return;
    const ei = +row.dataset.ex;
    const si = +row.dataset.set;
    const set = workout[ei].sets[si];
    if (e.target.classList.contains("in-weight")) set.weight = parseFloat(e.target.value) || 0;
    if (e.target.classList.contains("in-reps")) set.reps = parseInt(e.target.value, 10) || 0;
    recalc();
  });

  /* ---------- Running totals ---------- */
  const elTotalVolume = document.getElementById("totalVolume");
  const elSetsDone = document.getElementById("setsDone");
  const elSetsTotal = document.getElementById("setsTotal");
  const elExDone = document.getElementById("exDone");
  const elExTotal = document.getElementById("exTotal");

  function totals() {
    let volume = 0, setsDone = 0, setsTotal = 0, exDone = 0;
    workout.forEach((ex) => {
      let allDone = ex.sets.length > 0;
      ex.sets.forEach((s) => {
        setsTotal++;
        if (s.done) {
          setsDone++;
          volume += s.weight * s.reps;
        } else {
          allDone = false;
        }
      });
      if (allDone) exDone++;
    });
    return { volume, setsDone, setsTotal, exDone, exTotal: workout.length };
  }

  function recalc() {
    const t = totals();
    elTotalVolume.textContent = t.volume.toLocaleString();
    elSetsDone.textContent = t.setsDone;
    elSetsTotal.textContent = t.setsTotal;
    elExDone.textContent = t.exDone;
    elExTotal.textContent = t.exTotal;
  }

  /* ---------- Rest timer ---------- */
  const display = document.getElementById("timerDisplay");
  const bar = document.getElementById("timerBar");
  const card = document.getElementById("timerCard");
  const startBtn = document.getElementById("timerStart");
  const resetBtn = document.getElementById("timerReset");
  const chips = Array.from(document.querySelectorAll(".chip"));

  let total = 120;        // selected preset
  let remaining = 120;    // seconds left
  let running = false;
  let endAt = 0;
  let raf = null;

  function fmt(s) {
    s = Math.max(0, Math.ceil(s));
    const m = Math.floor(s / 60);
    const r = s % 60;
    return String(m).padStart(2, "0") + ":" + String(r).padStart(2, "0");
  }

  function paintTimer() {
    display.textContent = fmt(remaining);
    bar.style.width = total > 0 ? (Math.max(0, remaining) / total) * 100 + "%" : "0%";
  }

  function tick() {
    remaining = (endAt - Date.now()) / 1000;
    if (remaining <= 0) {
      remaining = 0;
      paintTimer();
      finishTimer();
      return;
    }
    paintTimer();
    raf = requestAnimationFrame(tick);
  }

  function setStartLabel() {
    if (running) {
      startBtn.textContent = "Pause";
      startBtn.classList.add("btn-paused");
      startBtn.classList.remove("btn-neon");
    } else {
      startBtn.textContent = remaining < total && remaining > 0 ? "Resume" : "Start";
      startBtn.classList.add("btn-neon");
      startBtn.classList.remove("btn-paused");
    }
  }

  function startTimer(secs, fresh) {
    card.classList.remove("alarm");
    display.classList.remove("flash");
    if (typeof secs === "number" && fresh) {
      total = secs;
      remaining = secs;
      selectChip(secs);
    }
    if (remaining <= 0) remaining = total;
    endAt = Date.now() + remaining * 1000;
    running = true;
    display.classList.add("running");
    setStartLabel();
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(tick);
  }

  function pauseTimer() {
    running = false;
    cancelAnimationFrame(raf);
    display.classList.remove("running");
    setStartLabel();
  }

  function resetTimer() {
    pauseTimer();
    remaining = total;
    card.classList.remove("alarm");
    display.classList.remove("flash");
    paintTimer();
    setStartLabel();
  }

  function finishTimer() {
    running = false;
    cancelAnimationFrame(raf);
    display.classList.remove("running");
    // beep-free visual flash
    card.classList.add("alarm");
    display.classList.remove("flash");
    void display.offsetWidth; // restart animation
    display.classList.add("flash");
    setStartLabel();
    toast("Rest done — back to work! 💪");
  }

  function selectChip(secs) {
    chips.forEach((c) => c.classList.toggle("active", +c.dataset.secs === secs));
  }

  startBtn.addEventListener("click", () => {
    if (running) pauseTimer();
    else startTimer();
  });
  resetBtn.addEventListener("click", resetTimer);
  chips.forEach((c) =>
    c.addEventListener("click", () => startTimer(+c.dataset.secs, true))
  );

  selectChip(120);
  paintTimer();
  setStartLabel();

  /* ---------- Elapsed workout clock ---------- */
  const elElapsed = document.getElementById("elapsed");
  const workoutStart = Date.now();
  function tickElapsed() {
    const s = Math.floor((Date.now() - workoutStart) / 1000);
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const r = s % 60;
    elElapsed.textContent =
      (h > 0 ? String(h) + ":" + String(m).padStart(2, "0") : String(m).padStart(2, "0")) +
      ":" + String(r).padStart(2, "0");
  }
  tickElapsed();
  setInterval(tickElapsed, 1000);

  /* ---------- Finish workout ---------- */
  document.getElementById("finishBtn").addEventListener("click", () => {
    const t = totals();
    const elapsed = elElapsed.textContent;
    if (t.setsDone === 0) {
      toast("Log at least one set before finishing.", { life: 2600 });
      return;
    }
    toast(
      "🏁 <b>Workout complete!</b>" +
        '<span class="toast-line">' +
        t.setsDone + " sets · " + t.volume.toLocaleString() + " kg volume · " +
        t.exDone + "/" + t.exTotal + " exercises · " + elapsed + " elapsed" +
        "</span>",
      { summary: true, life: 6000 }
    );
  });

  /* ---------- Boot ---------- */
  render();
})();

snippets.css:
/* ── Design tokens ─────────────────────────────────────────────────────────── */
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);

  /* ── Status colours ── */
  --c-clean: #4a7752;
  --c-clean-bg: rgba(74, 119, 82, 0.12);
  --c-dirty: #b34232;
  --c-dirty-bg: rgba(179, 66, 50, 0.12);
  --c-inprogress: #d99020;
  --c-inprogress-bg: rgba(217, 144, 32, 0.14);
  --c-inspected: #4a6da0;
  --c-inspected-bg: rgba(74, 109, 160, 0.14);
  --c-outoforder: #6c7280;
  --c-outoforder-bg: rgba(108, 114, 128, 0.14);
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
  overflow: hidden;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Layout ─────────────────────────────────────────────────────────────────── */
.app {
  height: 100vh;
  display: grid;
  grid-template-columns: 220px 1fr;
}

/* ── Rail ───────────────────────────────────────────────────────────────────── */
.rail {
  background: var(--navy);
  color: var(--bone);
  display: flex;
  flex-direction: column;
  padding: 22px 16px 14px;
  overflow-y: auto;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 4px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.brand-mark {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.35rem;
  flex-shrink: 0;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.01em;
}
.brand-prop {
  font-size: 0.7rem;
  color: var(--gold-light);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-top: 2px;
}
.nav {
  margin-top: 18px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}
.nav-item {
  font-size: 0.86rem;
  font-weight: 500;
  color: rgba(251, 248, 242, 0.78);
  text-decoration: none;
  padding: 10px 12px;
  border-radius: var(--r-md);
  display: flex;
  align-items: center;
  gap: 10px;
}
.nav-item:hover {
  background: rgba(255, 255, 255, 0.06);
  color: var(--bone);
}
.nav-item.is-active {
  background: rgba(201, 166, 73, 0.16);
  color: var(--gold-light);
  font-weight: 600;
}
.nav-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--gold);
}
.nav-item:not(.is-active) .nav-dot {
  display: none;
}

/* ── Legend ─────────────────────────────────────────────────────────────────── */
.legend {
  padding: 16px 0 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  margin-top: 8px;
}
.legend-title {
  font-size: 0.66rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--gold-light);
  margin-bottom: 10px;
  padding: 0 4px;
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.8rem;
  color: rgba(251, 248, 242, 0.82);
  padding: 5px 4px;
}
.lswatch {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  flex-shrink: 0;
}
.lswatch.clean {
  background: var(--c-clean);
}
.lswatch.dirty {
  background: var(--c-dirty);
}
.lswatch.inprogress {
  background: var(--c-inprogress);
}
.lswatch.inspected {
  background: var(--c-inspected);
}
.lswatch.outoforder {
  background: var(--c-outoforder);
}

.rail-foot {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  margin-top: 12px;
}
.clock {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 0.88rem;
  color: var(--gold-light);
}
.agent {
  font-size: 0.72rem;
  color: rgba(251, 248, 242, 0.6);
  letter-spacing: 0.04em;
}

/* ── Main ───────────────────────────────────────────────────────────────────── */
.main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--cream);
}
.topbar {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  padding: 22px 24px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--cream);
  flex-shrink: 0;
}
.kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold-d);
  font-weight: 600;
}
.topbar h1 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.9rem;
  letter-spacing: -0.005em;
  margin-top: 2px;
}
.topbar h1 span {
  color: var(--navy-2);
  font-weight: 500;
}
.topbar-right {
  display: flex;
  align-items: center;
}
.filter-group {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}
.filter-label {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--warm-gray);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-right: 2px;
}
.chip {
  background: transparent;
  border: 1px solid var(--line-strong);
  font-family: inherit;
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--ink-2);
  padding: 5px 10px;
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.1s, color 0.1s, border-color 0.1s;
}
.chip:hover {
  background: var(--cream-2);
}
.chip.is-active {
  background: var(--gold);
  color: var(--navy-d);
  border-color: var(--gold);
}

/* ── Tally bar ──────────────────────────────────────────────────────────────── */
.tally-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 24px;
  background: var(--bone);
  border-bottom: 1px solid var(--line);
  flex-shrink: 0;
  flex-wrap: wrap;
}
.tally {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  padding: 5px 12px;
  border-radius: 999px;
  font-variant-numeric: tabular-nums;
}
.tally.clean {
  background: var(--c-clean-bg);
  color: var(--c-clean);
}
.tally.dirty {
  background: var(--c-dirty-bg);
  color: var(--c-dirty);
}
.tally.inprogress {
  background: var(--c-inprogress-bg);
  color: var(--c-inprogress);
}
.tally.inspected {
  background: var(--c-inspected-bg);
  color: var(--c-inspected);
}
.tally.outoforder {
  background: var(--c-outoforder-bg);
  color: var(--c-outoforder);
}
.tally-total {
  font-size: 0.74rem;
  color: var(--warm-gray);
  font-weight: 600;
  margin-left: auto;
}

/* ── Grid area ──────────────────────────────────────────────────────────────── */
.grid-area {
  flex: 1;
  overflow-y: auto;
  padding: 18px 24px 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.floor-block {
}
.floor-label {
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--warm-gray);
  margin-bottom: 8px;
}
.floor-rooms {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(88px, 1fr));
  gap: 8px;
}

/* ── Room tile ──────────────────────────────────────────────────────────────── */
.tile {
  background: var(--bone);
  border: 1.5px solid transparent;
  border-radius: var(--r-md);
  padding: 10px 8px 8px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 4px;
  transition: transform 0.1s, box-shadow 0.1s, border-color 0.12s;
  position: relative;
  min-height: 82px;
}
.tile:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-1);
}
.tile.clean {
  background: var(--c-clean-bg);
  border-color: rgba(74, 119, 82, 0.3);
}
.tile.dirty {
  background: var(--c-dirty-bg);
  border-color: rgba(179, 66, 50, 0.3);
}
.tile.inprogress {
  background: var(--c-inprogress-bg);
  border-color: rgba(217, 144, 32, 0.35);
}
.tile.inspected {
  background: var(--c-inspected-bg);
  border-color: rgba(74, 109, 160, 0.3);
}
.tile.outoforder {
  background: var(--c-outoforder-bg);
  border-color: rgba(108, 114, 128, 0.3);
}

.tile-number {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 1rem;
  color: var(--navy-d);
  line-height: 1;
}
.tile-status {
  font-size: 0.62rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  line-height: 1.1;
}
.tile.clean .tile-status {
  color: var(--c-clean);
}
.tile.dirty .tile-status {
  color: var(--c-dirty);
}
.tile.inprogress .tile-status {
  color: var(--c-inprogress);
}
.tile.inspected .tile-status {
  color: var(--c-inspected);
}
.tile.outoforder .tile-status {
  color: var(--c-outoforder);
}

.tile-occ {
  font-size: 0.62rem;
  color: var(--warm-gray);
  font-weight: 500;
  text-transform: capitalize;
}
.tile-note-dot {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--gold);
}
/* dim tiles not matching filter */
.tile.dimmed {
  opacity: 0.28;
  pointer-events: none;
}

/* ── Modal ───────────────────────────────────────────────────────────────────── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 29, 54, 0.5);
  display: grid;
  place-items: center;
  z-index: 50;
  padding: 20px;
}
.modal-overlay[hidden] {
  display: none;
}
.modal {
  background: var(--bone);
  border-radius: var(--r-lg);
  width: 100%;
  max-width: 400px;
  box-shadow: var(--shadow-2);
  display: flex;
  flex-direction: column;
}
.modal-head {
  padding: 18px 20px 14px;
  border-bottom: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.modal-head h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.4rem;
}
.modal-close {
  background: transparent;
  border: none;
  font-size: 1rem;
  color: var(--warm-gray);
  cursor: pointer;
  padding: 4px 6px;
  border-radius: var(--r-sm);
}
.modal-close:hover {
  background: var(--cream-2);
  color: var(--ink);
}
.modal-body {
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.modal-row {
  display: flex;
  align-items: center;
  gap: 12px;
}
.modal-label {
  font-size: 0.74rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--warm-gray);
  min-width: 90px;
}
.status-pill {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
}
.status-pill.clean {
  background: var(--c-clean-bg);
  color: var(--c-clean);
}
.status-pill.dirty {
  background: var(--c-dirty-bg);
  color: var(--c-dirty);
}
.status-pill.inprogress {
  background: var(--c-inprogress-bg);
  color: var(--c-inprogress);
}
.status-pill.inspected {
  background: var(--c-inspected-bg);
  color: var(--c-inspected);
}
.status-pill.outoforder {
  background: var(--c-outoforder-bg);
  color: var(--c-outoforder);
}

.modal-note {
  width: 100%;
  font-family: var(--font-body);
  font-size: 0.84rem;
  color: var(--ink);
  background: var(--cream);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-sm);
  padding: 10px 12px;
  resize: vertical;
  outline: none;
}
.modal-note:focus {
  border-color: var(--navy-2);
}
.modal-foot {
  padding: 12px 20px 18px;
  border-top: 1px solid var(--line);
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}
.modal-btn {
  border: none;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 600;
  padding: 9px 16px;
  border-radius: var(--r-md);
  cursor: pointer;
}
.modal-btn.advance {
  background: var(--navy);
  color: var(--bone);
}
.modal-btn.advance:hover {
  background: var(--navy-d);
}
.modal-btn.save {
  background: var(--gold);
  color: var(--navy-d);
}
.modal-btn.save:hover {
  background: var(--gold-light);
}

/* ── Toast ───────────────────────────────────────────────────────────────────── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 22px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 100;
  white-space: nowrap;
}

/* ── Responsive ─────────────────────────────────────────────────────────────── */
@media (max-width: 960px) {
  html,
  body {
    overflow: auto;
  }
  .app {
    grid-template-columns: 1fr;
    height: auto;
  }
  .rail {
    flex-direction: row;
    align-items: center;
    flex-wrap: wrap;
    gap: 10px;
    padding: 14px 16px;
  }
  .nav {
    display: none;
  }
  .legend {
    display: none;
  }
  .rail-foot {
    display: none;
  }
  .main {
    overflow: visible;
  }
  .grid-area {
    overflow: visible;
  }
  .topbar {
    flex-direction: column;
    align-items: flex-start;
  }
}
@media (max-width: 560px) {
  .filter-group {
    gap: 4px;
  }
  .chip {
    font-size: 0.7rem;
    padding: 4px 8px;
  }
  .floor-rooms {
    grid-template-columns: repeat(auto-fill, minmax(70px, 1fr));
  }
}

