:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --sh-1: 0 1px 2px rgba(28, 42, 37, 0.06), 0 1px 3px rgba(28, 42, 37, 0.05);
  --sh-2: 0 6px 18px rgba(28, 42, 37, 0.08), 0 2px 6px rgba(28, 42, 37, 0.05);
  --sh-3: 0 22px 48px rgba(22, 48, 42, 0.16), 0 8px 18px rgba(22, 48, 42, 0.08);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: "Inter", system-ui, sans-serif;
  line-height: 1.55;
  color: var(--ink);
  background:
    radial-gradient(1200px 600px at 80% -10%, rgba(176, 141, 87, 0.08), transparent 60%),
    var(--ivory);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3 {
  font-family: "Cormorant Garamond", Georgia, serif;
  margin: 0;
  letter-spacing: 0.2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.page {
  max-width: 1240px;
  margin: 0 auto;
  padding: 28px 24px 72px;
}

/* ---------- Masthead ---------- */
.masthead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  flex-wrap: wrap;
  padding-bottom: 20px;
  margin-bottom: 26px;
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand__mark {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: var(--r-md);
  background: linear-gradient(150deg, var(--green-700), var(--green-d));
  color: var(--brass);
  font-size: 22px;
  box-shadow: var(--sh-2);
}

.brand__kicker {
  margin: 0;
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
}

.brand__title {
  font-size: clamp(28px, 4vw, 38px);
  font-weight: 600;
  color: var(--green);
  line-height: 1.05;
}

.masthead__actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 12px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  border: 1px solid var(--line-2);
  background: var(--paper);
  color: var(--ink-2);
}

.status-pill__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--muted);
}

.status-pill[data-state="draft"] .status-pill__dot { background: var(--warn); }
.status-pill[data-state="published"] {
  border-color: rgba(47, 158, 111, 0.4);
  background: rgba(47, 158, 111, 0.1);
  color: var(--green);
}
.status-pill[data-state="published"] .status-pill__dot { background: var(--ok); }

/* ---------- Buttons ---------- */
.btn {
  font: inherit;
  font-weight: 600;
  font-size: 14px;
  border-radius: var(--r-sm);
  padding: 10px 16px;
  cursor: pointer;
  border: 1px solid transparent;
  transition: transform 0.12s ease, box-shadow 0.18s ease, background 0.18s ease, color 0.18s ease;
}

.btn:active { transform: translateY(1px); }

.btn:focus-visible {
  outline: 2px solid var(--brass);
  outline-offset: 2px;
}

.btn--ghost {
  background: var(--paper);
  border-color: var(--line-2);
  color: var(--green);
}
.btn--ghost:hover { border-color: var(--green); box-shadow: var(--sh-1); }

.btn--solid {
  background: linear-gradient(150deg, var(--green-700), var(--green-d));
  color: var(--paper);
  box-shadow: var(--sh-2);
}
.btn--solid:hover { box-shadow: var(--sh-3); }

/* ---------- Layout ---------- */
.editor {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr);
  gap: 28px;
  align-items: start;
}

.panel {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px 22px 24px;
  box-shadow: var(--sh-1);
  margin-bottom: 22px;
}

.panel__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.panel__title {
  font-size: 23px;
  font-weight: 600;
  color: var(--green);
}

.panel__hint {
  margin: 0;
  font-size: 12.5px;
  color: var(--muted);
}

/* ---------- Uploader ---------- */
.dropzone {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  text-align: center;
  padding: 22px;
  border: 1.5px dashed var(--line-2);
  border-radius: var(--r-md);
  background: linear-gradient(var(--white), var(--ivory));
  cursor: pointer;
  transition: border-color 0.18s ease, background 0.18s ease;
  margin-bottom: 16px;
}
.dropzone:hover,
.dropzone:focus-visible,
.dropzone.is-over {
  border-color: var(--brass);
  background: var(--brass-50);
  outline: none;
}

.dropzone__icon {
  font-size: 26px;
  color: var(--brass-d);
  line-height: 1;
}
.dropzone__title { font-weight: 600; color: var(--ink); }
.dropzone__sub { font-size: 12px; color: var(--muted); }

.photo-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 12px;
}

.photo {
  position: relative;
  aspect-ratio: 4 / 3;
  border-radius: var(--r-md);
  overflow: hidden;
  border: 1px solid var(--line);
  box-shadow: var(--sh-1);
  cursor: grab;
  transition: transform 0.16s ease, box-shadow 0.16s ease, opacity 0.16s ease;
}
.photo:hover { box-shadow: var(--sh-2); transform: translateY(-2px); }
.photo.dragging { opacity: 0.45; cursor: grabbing; }
.photo.drop-target { outline: 2px solid var(--brass); outline-offset: 2px; }

.photo__img { position: absolute; inset: 0; }

.photo__cover {
  position: absolute;
  top: 8px;
  left: 8px;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 4px 8px;
  border-radius: 999px;
  background: var(--green-d);
  color: var(--brass);
  box-shadow: var(--sh-1);
}

.photo__remove {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 26px;
  height: 26px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: none;
  cursor: pointer;
  background: rgba(28, 42, 37, 0.62);
  color: #fff;
  font-size: 15px;
  line-height: 1;
  opacity: 0;
  transition: opacity 0.16s ease, background 0.16s ease;
}
.photo:hover .photo__remove,
.photo__remove:focus-visible { opacity: 1; }
.photo__remove:hover { background: var(--danger); }

.photo__order {
  position: absolute;
  bottom: 8px;
  left: 8px;
  font-size: 11px;
  font-weight: 600;
  color: #fff;
  background: rgba(28, 42, 37, 0.55);
  padding: 2px 7px;
  border-radius: 999px;
}

/* ---------- Fields ---------- */
.grid { display: grid; gap: 16px; }
.grid--2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }

.field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.field--full { grid-column: 1 / -1; }

.field__label {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--muted);
}

.input {
  font: inherit;
  font-size: 15px;
  width: 100%;
  padding: 11px 13px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line-2);
  background: var(--white);
  color: var(--ink);
  transition: border-color 0.16s ease, box-shadow 0.16s ease;
}
.input::placeholder { color: #9aa8a0; }
.input:hover { border-color: var(--green-700); }
.input:focus {
  outline: none;
  border-color: var(--green);
  box-shadow: 0 0 0 3px rgba(31, 61, 52, 0.12);
}

.input.is-invalid {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(196, 80, 62, 0.14);
}

.textarea { resize: vertical; min-height: 120px; line-height: 1.6; }

.input-money { position: relative; }
.input-money__sign {
  position: absolute;
  left: 13px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--muted);
  font-weight: 600;
  pointer-events: none;
}
.input--money { padding-left: 26px; }

.select-wrap { position: relative; }
.select-wrap::after {
  content: "▾";
  position: absolute;
  right: 13px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--brass-d);
  pointer-events: none;
  font-size: 12px;
}
.select-wrap .input { appearance: none; -webkit-appearance: none; padding-right: 32px; }

.field__error {
  margin: 0;
  font-size: 12px;
  font-weight: 500;
  color: var(--danger);
}

.char-count {
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}
.char-count.is-near { color: var(--warn); }
.char-count.is-max { color: var(--danger); }

/* ---------- Features ---------- */
.features {
  border: 0;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.feature {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 13px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line);
  background: var(--white);
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  transition: border-color 0.16s ease, background 0.16s ease;
}
.feature:hover { border-color: var(--brass); }
.feature:has(input:checked) {
  border-color: var(--green);
  background: var(--green-50);
  color: var(--green-d);
}
.feature:has(input:focus-visible) {
  outline: 2px solid var(--brass);
  outline-offset: 2px;
}

.feature input {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 5px;
  border: 1.5px solid var(--line-2);
  background: var(--white);
  display: grid;
  place-items: center;
  flex: none;
  cursor: pointer;
  transition: background 0.16s ease, border-color 0.16s ease;
}
.feature input::after {
  content: "✓";
  font-size: 12px;
  color: #fff;
  transform: scale(0);
  transition: transform 0.14s ease;
}
.feature input:checked {
  background: var(--green);
  border-color: var(--green);
}
.feature input:checked::after { transform: scale(1); }

/* ---------- Preview ---------- */
.preview__sticky { position: sticky; top: 24px; }

.preview__eyebrow {
  margin: 0 0 12px;
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--brass-d);
}

.listing-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--sh-3);
}

.listing-card__media {
  position: relative;
  aspect-ratio: 4 / 3;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.12), rgba(0, 0, 0, 0.22)),
    linear-gradient(150deg, #c9b48f 0%, #a98c63 42%, #6f6450 100%);
}

/* simulated property "photos" — warm architectural tones */
.listing-card__media[data-tone="0"] {
  background:
    radial-gradient(120% 90% at 18% 12%, rgba(255, 246, 224, 0.55), transparent 55%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.1), rgba(22, 36, 30, 0.35)),
    linear-gradient(155deg, #d7c6a1 0%, #b79a6d 45%, #6c5e44 100%);
}
.listing-card__media[data-tone="1"] {
  background:
    radial-gradient(120% 90% at 80% 18%, rgba(255, 236, 200, 0.5), transparent 55%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.1), rgba(22, 36, 30, 0.4)),
    linear-gradient(150deg, #8fb6a3 0%, #4f7a68 48%, #26493e 100%);
}
.listing-card__media[data-tone="2"] {
  background:
    radial-gradient(110% 80% at 30% 80%, rgba(255, 222, 188, 0.5), transparent 55%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(22, 36, 30, 0.42)),
    linear-gradient(160deg, #caa97f 0%, #9a7a52 45%, #3f3a30 100%);
}
.listing-card__media[data-tone="3"] {
  background:
    radial-gradient(120% 90% at 70% 30%, rgba(214, 230, 222, 0.5), transparent 55%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.1), rgba(22, 36, 30, 0.4)),
    linear-gradient(150deg, #aeb9ad 0%, #6e7d6f 50%, #2e3b33 100%);
}

/* faux skyline / structure */
.listing-card__media::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to top, rgba(22, 36, 30, 0.4), transparent 40%),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.05) 0 2px, transparent 2px 22px);
  opacity: 0.7;
}

.listing-card__cover-tag,
.listing-card__status,
.listing-card__price {
  position: absolute;
  z-index: 1;
  font-weight: 600;
}

.listing-card__cover-tag {
  top: 12px;
  left: 12px;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  padding: 4px 9px;
  border-radius: 999px;
  background: rgba(22, 36, 30, 0.55);
  color: #fff;
  backdrop-filter: blur(2px);
}

.listing-card__status {
  top: 12px;
  right: 12px;
  font-size: 10.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 999px;
  background: var(--brass);
  color: var(--green-d);
  box-shadow: var(--sh-1);
}
.listing-card__status[data-state="published"] {
  background: var(--ok);
  color: #fff;
}

.listing-card__price {
  bottom: 12px;
  left: 12px;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 27px;
  font-weight: 700;
  color: #fff;
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.45);
}

.listing-card__body { padding: 18px 18px 20px; }

.listing-card__title {
  font-size: 25px;
  font-weight: 600;
  color: var(--green);
  line-height: 1.1;
}
.listing-card__loc {
  margin: 2px 0 14px;
  font-size: 13.5px;
  color: var(--muted);
}

.spec-row {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0 0 12px;
  padding: 12px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.spec-row li {
  font-size: 13px;
  color: var(--ink-2);
  flex: 1 1 0;
  min-width: 0;
  text-align: center;
}
.spec-row li + li { border-left: 1px solid var(--line); }
.spec-row strong {
  display: block;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 21px;
  font-weight: 600;
  color: var(--ink);
}

.listing-card__type {
  margin: 0 0 8px;
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--brass-d);
}

.listing-card__desc {
  margin: 0 0 14px;
  font-size: 13.5px;
  color: var(--ink-2);
  line-height: 1.6;
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.chip-row {
  list-style: none;
  margin: 0 0 16px;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.chip-row li {
  font-size: 11.5px;
  font-weight: 500;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--brass-50);
  color: var(--brass-d);
  border: 1px solid rgba(176, 141, 87, 0.25);
}
.chip-row__empty { color: var(--muted); background: transparent; border: 0; padding-left: 0; }

.listing-card__agent {
  display: flex;
  align-items: center;
  gap: 11px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.avatar {
  width: 40px;
  height: 40px;
  flex: none;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--brass);
  background: linear-gradient(150deg, var(--green-700), var(--green-d));
}
.agent__name { margin: 0; font-weight: 600; font-size: 14px; color: var(--ink); }
.agent__role { margin: 0; font-size: 12px; color: var(--muted); }

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 16px);
  background: var(--green-d);
  color: var(--paper);
  padding: 13px 20px;
  border-radius: var(--r-md);
  font-size: 14px;
  font-weight: 500;
  box-shadow: var(--sh-3);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  z-index: 50;
  max-width: calc(100vw - 32px);
}
.toast.is-show { opacity: 1; transform: translate(-50%, 0); }
.toast__check {
  display: inline-block;
  margin-right: 8px;
  color: var(--brass);
  font-weight: 700;
}

/* ---------- Responsive ---------- */
@media (max-width: 980px) {
  .editor { grid-template-columns: 1fr; }
  .preview__sticky { position: static; }
  .preview { order: -1; }
}

@media (max-width: 520px) {
  .page { padding: 18px 14px 56px; }
  .masthead { gap: 12px; }
  .masthead__actions { width: 100%; }
  .masthead__actions .btn { flex: 1 1 auto; }
  .status-pill { order: -1; }
  .brand__title { font-size: 28px; }
  .panel { padding: 18px 15px 20px; border-radius: var(--r-md); }
  .grid--2 { grid-template-columns: 1fr; }
  .features { grid-template-columns: 1fr; }
  .photo-grid { grid-template-columns: repeat(auto-fill, minmax(110px, 1fr)); }
  .listing-card__price { font-size: 23px; }
  .listing-card__title { font-size: 22px; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}

