/* ── Design tokens ── */
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  background: radial-gradient(circle at 22% 18%, rgba(201, 166, 73, 0.2), transparent 55%),
    linear-gradient(160deg, #14213b 0%, #0f1d36 100%);
  display: grid;
  place-items: center;
  min-height: 100vh;
  padding: 32px;
}

/* ── Widget shell ── */
.bg {
  width: 100%;
  display: grid;
  place-items: center;
}
.sheet {
  width: min(520px, 100%);
  background: var(--bone);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: 0 40px 100px rgba(15, 29, 54, 0.55);
  display: flex;
  flex-direction: column;
}

/* ── Header ── */
.sheet-head {
  padding: 22px 26px 18px;
  border-bottom: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
}
.kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold-d);
  font-weight: 700;
}
.sheet-head h2 {
  font-family: var(--font-display);
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.005em;
  color: var(--navy-d);
  margin-top: 2px;
}
.badge {
  background: rgba(201, 166, 73, 0.14);
  color: var(--gold-d);
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 5px 12px;
  border-radius: 999px;
}

/* ── Segmented control ── */
.seg-wrap {
  padding: 14px 26px 0;
}
.seg {
  display: flex;
  background: var(--cream-2);
  border-radius: var(--r-md);
  padding: 3px;
  gap: 3px;
}
.seg-btn {
  flex: 1;
  background: transparent;
  border: none;
  font-family: var(--font-body);
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--warm-gray);
  padding: 8px 10px;
  border-radius: 7px;
  cursor: pointer;
  transition: background 0.16s, color 0.16s;
}
.seg-btn:hover {
  color: var(--ink);
}
.seg-btn.is-active {
  background: var(--bone);
  color: var(--navy-d);
  box-shadow: var(--shadow-1);
}

/* ── Body ── */
.sheet-body {
  padding: 16px 26px;
  overflow-y: auto;
}
.block {
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
}
.block:last-child {
  border-bottom: none;
}
.block h3 {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--gold-d);
  font-weight: 700;
  margin-bottom: 10px;
}
.sub-note {
  font-size: 0.78rem;
  color: var(--warm-gray);
  margin-top: 2px;
}

/* ── Option grid ── */
.option-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.opt-card {
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 11px 13px;
  text-align: left;
  font-family: inherit;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.opt-card:hover {
  border-color: var(--gold);
}
.opt-card.is-active {
  background: var(--bone);
  border-color: var(--gold);
  outline: 1.5px solid var(--gold);
}
.opt-card .opt-name {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--navy-d);
}
.opt-card .opt-dur {
  font-size: 0.74rem;
  color: var(--warm-gray);
}
.opt-card .opt-price {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--gold-d);
  margin-top: 4px;
}

/* ── Date pills ── */
.date-pills {
  display: flex;
  gap: 7px;
  flex-wrap: wrap;
}
.dpill {
  background: var(--cream);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-md);
  padding: 7px 14px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--ink-2);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
}
.dpill .dday {
  font-size: 0.7rem;
  color: var(--warm-gray);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 700;
}
.dpill:hover {
  border-color: var(--gold);
}
.dpill.is-active {
  background: var(--navy);
  border-color: var(--navy);
  color: var(--bone);
}
.dpill.is-active .dday {
  color: rgba(251, 248, 242, 0.7);
}

/* ── Slot grid ── */
.slot-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}
.slot-pill {
  background: var(--bone);
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--navy-d);
  padding: 7px 14px;
  cursor: pointer;
}
.slot-pill:hover:not(.is-booked) {
  border-color: var(--gold);
}
.slot-pill.is-active {
  background: var(--gold);
  border-color: var(--gold);
  color: var(--navy-d);
}
.slot-pill.is-booked {
  color: var(--warm-gray);
  background: transparent;
  border-style: dashed;
  cursor: not-allowed;
  text-decoration: line-through;
}

/* ── Party stepper ── */
.party-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}
.stepper {
  display: inline-flex;
  align-items: stretch;
  background: var(--cream);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-md);
  padding: 4px;
  gap: 4px;
}
.stepper button {
  width: 34px;
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 700;
  cursor: pointer;
  color: var(--navy-d);
}
.stepper button:hover {
  background: var(--cream-2);
}
.step-val {
  padding: 4px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 60px;
}
.step-val strong {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--navy-d);
  line-height: 1;
}
.step-val span {
  font-size: 0.72rem;
  color: var(--warm-gray);
  font-weight: 600;
}

/* ── Footer ── */
.sheet-foot {
  padding: 14px 26px 22px;
  background: var(--cream);
  border-top: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.quote {
  display: flex;
  flex-direction: column;
}
.q-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  font-weight: 700;
}
.q-val {
  font-family: var(--font-display);
  font-size: 1.7rem;
  font-weight: 700;
  color: var(--gold-d);
  line-height: 1.1;
}
.q-meta {
  font-size: 0.74rem;
  color: var(--warm-gray);
  margin-top: 2px;
}

/* ── Buttons ── */
.primary {
  font-family: inherit;
  font-weight: 600;
  font-size: 0.86rem;
  padding: 11px 20px;
  border-radius: 999px;
  cursor: pointer;
  background: var(--navy);
  color: var(--bone);
  border: none;
}
.primary:hover {
  background: var(--navy-d);
}
.primary:disabled {
  background: var(--cream-2);
  color: var(--warm-gray);
  cursor: not-allowed;
}

/* ── Confirmation panel ── */
.confirm-panel {
  padding: 40px 26px 36px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 12px;
}
.confirm-icon {
  font-size: 2.4rem;
  color: var(--gold);
}
.confirm-title {
  font-family: var(--font-display);
  font-size: 1.9rem;
  font-weight: 700;
  color: var(--navy-d);
}
.confirm-ref {
  font-family: var(--font-mono);
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--gold-d);
  background: rgba(201, 166, 73, 0.1);
  padding: 7px 16px;
  border-radius: var(--r-md);
  letter-spacing: 0.08em;
}
.confirm-detail {
  font-size: 0.88rem;
  color: var(--ink-2);
  line-height: 1.55;
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 22px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: 0 10px 30px rgba(22, 30, 44, 0.18);
  z-index: 100;
  white-space: nowrap;
}

/* ── Responsive ── */
@media (max-width: 560px) {
  body {
    padding: 16px;
  }
  .option-grid {
    grid-template-columns: 1fr;
  }
  .sheet-foot {
    flex-direction: column;
    align-items: stretch;
  }
  .sheet-foot .primary {
    text-align: center;
  }
}

/* ── Honor [hidden] over display (overlay/panel toggle fix) ── */
.confirm-panel[hidden] {
  display: none;
}

