(function () {
  "use strict";

  /* ---------------- DATA ---------------- */
  var CATALOG = {
    services: [
      { id: "s1", name: "Signature Cut & Style", price: 95, tag: "Hair", desc: "Consultation, cut, blow-dry finish." },
      { id: "s2", name: "Lumière Balayage", price: 220, tag: "Color", desc: "Hand-painted, freehand highlights." },
      { id: "s3", name: "Gloss & Tone", price: 65, tag: "Color", desc: "Shine-boosting demi-permanent glaze." },
      { id: "s4", name: "Keratin Smoothing", price: 180, tag: "Treatment", desc: "Frizz-taming, 12-week result." },
      { id: "s5", name: "Bridal Updo", price: 140, tag: "Styling", desc: "Pinned, lacquered, photo-ready." },
      { id: "s6", name: "Scalp Ritual Facial", price: 78, tag: "Spa", desc: "Detox massage & serum infusion." },
      { id: "s7", name: "Gel Manicure", price: 52, tag: "Nails", desc: "Shaped, cuticle care, gel polish." },
      { id: "s8", name: "Brow Architecture", price: 38, tag: "Brows", desc: "Map, wax, tint & set." }
    ],
    retail: [
      { id: "r1", name: "Ritual Repair Mask", price: 46, tag: "Hair", desc: "Bond-building weekly treatment." },
      { id: "r2", name: "Argan Gloss Oil", price: 34, tag: "Hair", desc: "Weightless finishing shine." },
      { id: "r3", name: "Velvet Hold Spray", price: 28, tag: "Styling", desc: "Flexible, brushable hold." },
      { id: "r4", name: "Rose Quartz Comb", price: 22, tag: "Tools", desc: "Static-free wide-tooth comb." },
      { id: "r5", name: "Cuticle Elixir", price: 19, tag: "Nails", desc: "Nourishing nail & cuticle oil." },
      { id: "r6", name: "Silk Pillow Wrap", price: 58, tag: "Home", desc: "Mulberry silk, frizz-saving." }
    ]
  };

  var PROMOS = {
    LUMIERE10: { type: "pct", value: 0.1, label: "10% off" },
    WELCOME20: { type: "pct", value: 0.2, label: "20% off" },
    ROSE15: { type: "flat", value: 15, label: "$15 off" }
  };

  var TAX_RATE = 0.085;

  /* ---------------- STATE ---------------- */
  var state = {
    tab: "services",
    query: "",
    cart: {}, // id -> { item, qty }
    tipMode: "pct", // "pct" | "custom"
    tipPct: 18,
    tipCustom: 0,
    promo: null, // { code, ...promoDef }
    pay: "card",
    tendered: 0
  };

  /* ---------------- HELPERS ---------------- */
  function $(sel, ctx) { return (ctx || document).querySelector(sel); }
  function $all(sel, ctx) { return Array.prototype.slice.call((ctx || document).querySelectorAll(sel)); }
  function money(n) {
    var neg = n < 0;
    var v = Math.abs(n).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    return (neg ? "−$" : "$") + v;
  }

  var toastTimer;
  function toast(msg) {
    var el = $("#toast");
    el.textContent = msg;
    el.classList.add("is-show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { el.classList.remove("is-show"); }, 2600);
  }

  function findItem(id) {
    var all = CATALOG.services.concat(CATALOG.retail);
    for (var i = 0; i < all.length; i++) if (all[i].id === id) return all[i];
    return null;
  }

  /* ---------------- RENDER GRID ---------------- */
  function renderGrid() {
    var grid = $("#grid");
    var q = state.query.trim().toLowerCase();
    var list = CATALOG[state.tab].filter(function (it) {
      if (!q) return true;
      return (it.name + " " + it.tag + " " + it.desc).toLowerCase().indexOf(q) !== -1;
    });

    $("#gridEmpty").hidden = list.length !== 0;

    grid.innerHTML = list.map(function (it) {
      var inCart = state.cart[it.id];
      return (
        '<button class="item' + (inCart ? " is-in" : "") + '" type="button" data-id="' + it.id + '" aria-label="Add ' + it.name + ', ' + money(it.price) + '">' +
        '<span class="item__inCart" aria-hidden="true">' + (inCart ? inCart.qty : "") + "</span>" +
        '<span class="item__top">' +
        '<span class="item__name">' + it.name + "</span>" +
        '<span class="item__price">' + money(it.price) + "</span>" +
        "</span>" +
        '<span class="item__desc">' + it.desc + "</span>" +
        '<span class="item__tag">' + it.tag + "</span>" +
        "</button>"
      );
    }).join("");
  }

  /* ---------------- CART OPS ---------------- */
  function addToCart(id) {
    var item = findItem(id);
    if (!item) return;
    if (state.cart[id]) state.cart[id].qty += 1;
    else state.cart[id] = { item: item, qty: 1 };
    renderCart();
    renderGrid();
    flashItem(id);
  }

  function setQty(id, delta) {
    var entry = state.cart[id];
    if (!entry) return;
    entry.qty += delta;
    if (entry.qty <= 0) delete state.cart[id];
    renderCart();
    renderGrid();
  }

  function removeFromCart(id) {
    delete state.cart[id];
    renderCart();
    renderGrid();
  }

  function flashItem(id) {
    var el = $('.item[data-id="' + id + '"]');
    if (!el) return;
    el.classList.remove("is-flash");
    void el.offsetWidth;
    el.classList.add("is-flash");
  }

  /* ---------------- TOTALS ---------------- */
  function calc() {
    var subtotal = 0;
    Object.keys(state.cart).forEach(function (id) {
      var e = state.cart[id];
      subtotal += e.item.price * e.qty;
    });

    var discount = 0;
    if (state.promo) {
      discount = state.promo.type === "pct" ? subtotal * state.promo.value : Math.min(state.promo.value, subtotal);
    }

    var taxable = Math.max(0, subtotal - discount);

    var tip = 0;
    if (state.tipMode === "custom") tip = state.tipCustom;
    else tip = taxable * (state.tipPct / 100);

    var tax = taxable * TAX_RATE;
    var grand = taxable + tax + tip;

    return {
      subtotal: subtotal,
      discount: discount,
      tip: tip,
      tax: tax,
      grand: grand
    };
  }

  /* ---------------- RENDER CART ---------------- */
  function renderCart() {
    var cartEl = $("#cart");
    var ids = Object.keys(state.cart);
    var empty = ids.length === 0;

    $("#cartEmpty").hidden = !empty;
    $("#tillBody").hidden = empty;

    cartEl.innerHTML = ids.map(function (id) {
      var e = state.cart[id];
      var lineTotal = e.item.price * e.qty;
      return (
        '<li class="line">' +
        '<span class="line__name">' + e.item.name + "</span>" +
        '<span class="line__total">' + money(lineTotal) + "</span>" +
        '<span class="line__unit">' + money(e.item.price) + " each</span>" +
        '<span></span>' +
        '<span class="line__ctrl">' +
        '<span class="stepper">' +
        '<button type="button" data-act="dec" data-id="' + id + '" aria-label="Decrease quantity of ' + e.item.name + '">−</button>' +
        '<span class="stepper__qty" aria-live="polite">' + e.qty + "</span>" +
        '<button type="button" data-act="inc" data-id="' + id + '" aria-label="Increase quantity of ' + e.item.name + '">+</button>' +
        "</span>" +
        '<button class="line__remove" type="button" data-act="rm" data-id="' + id + '">Remove</button>' +
        "</span>" +
        "</li>"
      );
    }).join("");

    renderTotals();
  }

  function renderTotals() {
    var t = calc();
    $("#subtotal").textContent = money(t.subtotal);

    var discRow = $("#discRow");
    if (t.discount > 0) {
      discRow.hidden = false;
      $("#discount").textContent = money(-t.discount);
      $("#discLabel").textContent = state.promo ? "· " + state.promo.code : "";
    } else {
      discRow.hidden = true;
    }

    $("#tax").textContent = money(t.tax);
    $("#tipLine").textContent = money(t.tip);
    $("#tipAmt").textContent = money(t.tip);
    $("#grand").textContent = money(t.grand);
    $("#chargeAmt").textContent = money(t.grand);

    var charge = $("#charge");
    charge.disabled = t.grand <= 0;
  }

  /* ---------------- TIP ---------------- */
  function setTipPct(pct) {
    state.tipMode = "pct";
    state.tipPct = pct;
    state.tipCustom = 0;
    $("#tipCustom").value = "";
    $all(".tip__chip").forEach(function (c) {
      var on = Number(c.dataset.tip) === pct;
      c.classList.toggle("is-active", on);
      c.setAttribute("aria-pressed", String(on));
    });
    renderTotals();
  }

  function setTipCustom(val) {
    var n = parseFloat(val);
    state.tipMode = "custom";
    state.tipCustom = isNaN(n) || n < 0 ? 0 : n;
    $all(".tip__chip").forEach(function (c) {
      c.classList.remove("is-active");
      c.setAttribute("aria-pressed", "false");
    });
    renderTotals();
  }

  /* ---------------- PROMO ---------------- */
  function applyPromo() {
    var input = $("#promo");
    var msg = $("#promoMsg");
    var code = input.value.trim().toUpperCase();
    msg.className = "promo__msg";

    if (!code) {
      msg.textContent = "Enter a promo code to apply.";
      msg.classList.add("is-err");
      return;
    }
    if (state.promo && state.promo.code === code) {
      msg.textContent = "That code is already applied.";
      msg.classList.add("is-ok");
      return;
    }
    var def = PROMOS[code];
    if (!def) {
      state.promo = null;
      msg.textContent = "Code “" + code + "” is not valid.";
      msg.classList.add("is-err");
      renderTotals();
      return;
    }
    state.promo = { code: code, type: def.type, value: def.value, label: def.label };
    msg.textContent = def.label + " applied.";
    msg.classList.add("is-ok");
    renderTotals();
    toast(def.label + " applied");
  }

  /* ---------------- PAYMENT ---------------- */
  function setPay(method) {
    state.pay = method;
    $all(".pay__chip").forEach(function (c) {
      var on = c.dataset.pay === method;
      c.classList.toggle("is-active", on);
      c.setAttribute("aria-pressed", String(on));
    });
    $("#cashPanel").hidden = method !== "cash";
  }

  /* ---------------- CHARGE ---------------- */
  function charge() {
    var t = calc();
    if (t.grand <= 0) return;

    if (state.pay === "cash") {
      var tendered = parseFloat($("#tendered").value);
      if (isNaN(tendered) || tendered < t.grand) {
        toast("Cash tendered must cover " + money(t.grand));
        $("#tendered").focus();
        return;
      }
    }

    var btn = $("#charge");
    btn.classList.add("is-loading");
    btn.disabled = true;

    setTimeout(function () {
      btn.classList.remove("is-loading");
      showSuccess(t);
    }, 750);
  }

  function showSuccess(t) {
    var methodLabel = { card: "Visa •••• 4471", cash: "Cash", gift: "Gift card •••• 8820" }[state.pay];
    $("#paidTitle").textContent = money(t.grand);
    $("#paidMethod").textContent = "Paid with " + methodLabel + " · Ticket #ML-2048";

    var changeWrap = $("#paidChange");
    if (state.pay === "cash") {
      var tendered = parseFloat($("#tendered").value) || 0;
      $("#changeDue").textContent = money(tendered - t.grand);
      changeWrap.hidden = false;
    } else {
      changeWrap.hidden = true;
    }

    $("#paid").hidden = false;
    toast("Payment approved · " + money(t.grand));
  }

  function newSale() {
    state.cart = {};
    state.promo = null;
    state.tendered = 0;
    $("#promo").value = "";
    $("#promoMsg").textContent = "";
    $("#promoMsg").className = "promo__msg";
    $("#tendered").value = "";
    setTipPct(18);
    setPay("card");
    $("#paid").hidden = true;
    $("#charge").disabled = false;
    renderCart();
    renderGrid();
    toast("Ready for the next guest");
  }

  /* ---------------- EVENTS ---------------- */
  function bind() {
    // tabs
    $all(".tab").forEach(function (tab) {
      tab.addEventListener("click", function () {
        state.tab = tab.dataset.tab;
        $all(".tab").forEach(function (t) {
          var on = t === tab;
          t.classList.toggle("is-active", on);
          t.setAttribute("aria-selected", String(on));
        });
        $("#grid").setAttribute("aria-labelledby", tab.id);
        renderGrid();
      });
    });

    // search
    $("#search").addEventListener("input", function (e) {
      state.query = e.target.value;
      renderGrid();
    });

    // grid delegation
    $("#grid").addEventListener("click", function (e) {
      var card = e.target.closest(".item");
      if (card) addToCart(card.dataset.id);
    });

    // cart delegation
    $("#cart").addEventListener("click", function (e) {
      var btn = e.target.closest("button[data-act]");
      if (!btn) return;
      var id = btn.dataset.id;
      if (btn.dataset.act === "inc") setQty(id, 1);
      else if (btn.dataset.act === "dec") setQty(id, -1);
      else if (btn.dataset.act === "rm") removeFromCart(id);
    });

    // tip presets
    $all(".tip__chip").forEach(function (chip) {
      chip.addEventListener("click", function () { setTipPct(Number(chip.dataset.tip)); });
    });
    $("#tipCustom").addEventListener("input", function (e) { setTipCustom(e.target.value); });

    // promo
    $("#applyPromo").addEventListener("click", applyPromo);
    $("#promo").addEventListener("keydown", function (e) {
      if (e.key === "Enter") { e.preventDefault(); applyPromo(); }
    });

    // payment chips
    $all(".pay__chip").forEach(function (chip) {
      chip.addEventListener("click", function () { setPay(chip.dataset.pay); });
    });

    // cash quick
    $all(".btn-quick").forEach(function (b) {
      b.addEventListener("click", function () {
        var t = calc();
        var val = b.dataset.cash === "exact" ? t.grand : Number(b.dataset.cash);
        $("#tendered").value = val.toFixed(2);
        $("#tendered").focus();
      });
    });

    // charge + new sale
    $("#charge").addEventListener("click", charge);
    $("#newSale").addEventListener("click", newSale);

    // close overlay on backdrop / escape
    $("#paid").addEventListener("click", function (e) {
      if (e.target === $("#paid")) newSale();
    });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && !$("#paid").hidden) newSale();
    });
  }

  /* ---------------- INIT ---------------- */
  function init() {
    bind();
    setTipPct(18);
    setPay("card");
    renderGrid();
    renderCart();
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
  else init();
})();

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --pending: #6b7280;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

/* ── Room shell ── */
.room {
  height: 100vh;
  display: grid;
  grid-template-columns: 1fr 340px;
  grid-template-rows: auto 1fr;
  grid-template-areas:
    "bar  bar"
    "main side";
}

/* ── Call bar ── */
.callbar {
  grid-area: bar;
  background: var(--ink);
  color: #fff;
  padding: 12px 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  z-index: 5;
}
.cb-left {
  display: flex;
  align-items: center;
  gap: 12px;
}
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: linear-gradient(150deg, var(--teal), var(--teal-d));
  color: #fff;
  font-size: 1.1rem;
  font-weight: 700;
  flex-shrink: 0;
}
.cb-meta {
  line-height: 1.25;
}
.cb-title {
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.cb-sub {
  font-size: 0.78rem;
  color: rgba(255, 255, 255, 0.6);
}
.cb-center {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 999px;
  padding: 6px 14px;
}
.live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 0 3px rgba(255, 122, 102, 0.25);
  animation: pulse 2s ease-in-out infinite;
}
@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}
.cb-timer {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: 0.02em;
}
.cb-right {
  display: flex;
  align-items: center;
}
.enc-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.76rem;
  font-weight: 600;
  color: #9be8c6;
  background: rgba(47, 158, 111, 0.18);
  border: 1px solid rgba(47, 158, 111, 0.3);
  border-radius: 999px;
  padding: 5px 11px;
}

/* ── Stage ── */
.stage-wrap {
  grid-area: main;
  background: var(--ink);
  display: flex;
  flex-direction: column;
  padding: 18px 18px 22px;
  min-height: 0;
}
.stage {
  position: relative;
  flex: 1;
  border-radius: var(--r-lg);
  overflow: hidden;
  min-height: 0;
}
.stage-tile {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 30% 25%, rgba(18, 156, 147, 0.45), transparent 55%),
    linear-gradient(150deg, #123c39, #0a2724 70%);
}
.big-avatar {
  width: 132px;
  height: 132px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(150deg, var(--teal), var(--teal-700));
  color: #fff;
  font-size: 2.8rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  box-shadow: 0 0 0 6px rgba(255, 255, 255, 0.06), var(--shadow-2);
}
.remote-label {
  position: absolute;
  left: 18px;
  bottom: 18px;
  display: flex;
  flex-direction: column;
  background: rgba(10, 39, 36, 0.6);
  backdrop-filter: blur(6px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--r-sm);
  padding: 8px 14px;
}
.rl-name {
  color: #fff;
  font-weight: 700;
  font-size: 0.95rem;
}
.rl-role {
  color: rgba(255, 255, 255, 0.65);
  font-size: 0.76rem;
}
.quality {
  position: absolute;
  top: 16px;
  right: 16px;
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 22px;
  background: rgba(10, 39, 36, 0.55);
  border-radius: var(--r-sm);
  padding: 5px 8px;
}
.q-bar {
  width: 4px;
  border-radius: 2px;
  background: var(--ok);
}
.q-bar:nth-child(1) {
  height: 6px;
}
.q-bar:nth-child(2) {
  height: 10px;
}
.q-bar:nth-child(3) {
  height: 14px;
}
.q-bar:nth-child(4) {
  height: 18px;
}
.q-dim {
  background: rgba(255, 255, 255, 0.22);
}
.quality.is-weak .q-bar {
  background: var(--warn);
}
.quality.is-weak .q-bar:nth-child(3),
.quality.is-weak .q-bar:nth-child(4) {
  background: rgba(255, 255, 255, 0.22);
}

/* ── Self-view PiP ── */
.selfview {
  position: absolute;
  right: 18px;
  bottom: 18px;
  width: 168px;
  height: 116px;
  border-radius: var(--r-md);
  overflow: hidden;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 70% 30%, rgba(255, 122, 102, 0.4), transparent 55%),
    linear-gradient(150deg, #1c4a45, #0d322e);
  border: 2px solid rgba(255, 255, 255, 0.14);
  box-shadow: var(--shadow-2);
}
.sv-avatar {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--coral);
  color: #fff;
  font-weight: 800;
  font-size: 1.1rem;
}
.sv-label {
  position: absolute;
  left: 8px;
  bottom: 7px;
  color: #fff;
  font-size: 0.72rem;
  font-weight: 600;
  background: rgba(10, 39, 36, 0.55);
  border-radius: 6px;
  padding: 2px 7px;
}
.sv-mute {
  position: absolute;
  right: 8px;
  bottom: 7px;
  font-size: 0.9rem;
  background: rgba(212, 80, 62, 0.9);
  border-radius: 6px;
  padding: 2px 6px;
}
.sv-camoff {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: #0d322e;
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.74rem;
  font-weight: 600;
}
.sv-camoff span:first-child {
  font-size: 1.4rem;
  opacity: 0.7;
}

/* ── Ended overlay ── */
.ended-overlay {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(10, 39, 36, 0.82);
  backdrop-filter: blur(4px);
  z-index: 3;
}
.eo-card {
  text-align: center;
  color: #fff;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}
.eo-icon {
  width: 64px;
  height: 64px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(47, 158, 111, 0.22);
  border: 1px solid rgba(47, 158, 111, 0.45);
  color: #9be8c6;
  font-size: 1.7rem;
  margin-bottom: 6px;
}
.eo-title {
  font-size: 1.25rem;
  font-weight: 800;
}
.eo-dur {
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.9rem;
}
.eo-btn {
  margin-top: 14px;
  border: none;
  background: var(--teal);
  color: #fff;
  font: inherit;
  font-weight: 600;
  font-size: 0.9rem;
  border-radius: 11px;
  padding: 11px 22px;
  cursor: pointer;
  transition: background 0.15s;
}
.eo-btn:hover {
  background: var(--teal-d);
}

/* ── Controls ── */
.controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding-top: 18px;
}
.ctl {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  border: none;
  background: transparent;
  color: rgba(255, 255, 255, 0.78);
  font: inherit;
  cursor: pointer;
}
.ctl-ic {
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.14);
  font-size: 1.3rem;
  transition: background 0.15s, transform 0.12s, border-color 0.15s;
}
.ctl:hover .ctl-ic {
  background: rgba(255, 255, 255, 0.18);
}
.ctl:active .ctl-ic {
  transform: translateY(1px);
}
.ctl-lbl {
  font-size: 0.74rem;
  font-weight: 600;
}
.ctl.is-off .ctl-ic {
  background: rgba(212, 80, 62, 0.92);
  border-color: rgba(212, 80, 62, 0.92);
  color: #fff;
}
.ctl.is-active .ctl-ic {
  background: var(--teal);
  border-color: var(--teal);
  color: #fff;
}
.ctl-end .ctl-ic {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
  width: 64px;
  height: 64px;
  transform: rotate(135deg);
}
.ctl-end .ctl-lbl {
  color: #ff9f93;
}
.ctl-end:hover .ctl-ic {
  background: #c0432f;
}

/* ── Side panel ── */
.side {
  grid-area: side;
  background: var(--white);
  border-left: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.tabs {
  display: flex;
  border-bottom: 1px solid var(--line);
  padding: 0 10px;
}
.tab {
  flex: 1;
  border: none;
  background: transparent;
  font: inherit;
  font-weight: 600;
  font-size: 0.88rem;
  color: var(--muted);
  padding: 14px 0;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  transition: color 0.15s, border-color 0.15s;
}
.tab:hover {
  color: var(--ink-2);
}
.tab.is-active {
  color: var(--teal-d);
  border-bottom-color: var(--teal);
}
.tabpanel {
  display: none;
  flex: 1;
  min-height: 0;
  flex-direction: column;
}
.tabpanel.is-active {
  display: flex;
}

/* ── Chat ── */
.thread {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.msg {
  display: flex;
  flex-direction: column;
  max-width: 84%;
}
.msg.in {
  align-self: flex-start;
}
.msg.out {
  align-self: flex-end;
  align-items: flex-end;
}
.msg-who {
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--muted);
  margin: 0 4px 3px;
}
.bubble {
  padding: 9px 13px;
  border-radius: 14px;
  font-size: 0.88rem;
  line-height: 1.4;
}
.msg.in .bubble {
  background: var(--teal-50);
  color: var(--ink);
  border-bottom-left-radius: 4px;
}
.msg.out .bubble {
  background: var(--teal-d);
  color: #fff;
  border-bottom-right-radius: 4px;
}
.typing {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 16px 8px;
  font-size: 0.76rem;
  color: var(--muted);
}
.t-dots {
  display: inline-flex;
  gap: 3px;
}
.t-dots i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--muted);
  animation: blink 1.2s infinite ease-in-out;
}
.t-dots i:nth-child(2) {
  animation-delay: 0.2s;
}
.t-dots i:nth-child(3) {
  animation-delay: 0.4s;
}
@keyframes blink {
  0%,
  60%,
  100% {
    opacity: 0.25;
  }
  30% {
    opacity: 1;
  }
}
.composer {
  display: flex;
  gap: 8px;
  padding: 12px 14px;
  border-top: 1px solid var(--line);
}
.composer-input {
  flex: 1;
  border: 1px solid var(--line-2);
  border-radius: 11px;
  padding: 10px 13px;
  font: inherit;
  font-size: 0.88rem;
  color: var(--ink);
  outline: none;
  transition: border-color 0.15s;
}
.composer-input:focus {
  border-color: var(--teal);
}
.send-btn {
  width: 42px;
  border: none;
  border-radius: 11px;
  background: var(--teal);
  color: #fff;
  font-size: 1rem;
  cursor: pointer;
  transition: background 0.15s;
}
.send-btn:hover {
  background: var(--teal-d);
}

/* ── Notes ── */
#panel-notes {
  padding: 16px;
  gap: 8px;
}
.notes-label {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--ink-2);
}
.notes-area {
  flex: 1;
  resize: none;
  border: 1px solid var(--line-2);
  border-radius: var(--r-md);
  padding: 12px;
  font: inherit;
  font-size: 0.88rem;
  color: var(--ink);
  outline: none;
  line-height: 1.5;
  transition: border-color 0.15s;
}
.notes-area:focus {
  border-color: var(--teal);
}
.notes-hint {
  font-size: 0.74rem;
  color: var(--muted);
}

/* ── Info ── */
#panel-info {
  padding: 16px;
  gap: 16px;
  overflow-y: auto;
}
.info-head {
  display: flex;
  align-items: center;
  gap: 12px;
}
.info-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--coral);
  color: #fff;
  font-weight: 800;
  font-size: 1rem;
}
.info-name {
  font-size: 1rem;
  font-weight: 700;
}
.info-meta {
  font-size: 0.8rem;
  color: var(--muted);
}
.info-list {
  display: flex;
  flex-direction: column;
}
.info-row {
  padding: 11px 0;
  border-bottom: 1px solid var(--line);
}
.info-row:last-child {
  border-bottom: none;
}
.info-row dt {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
  color: var(--muted);
  margin-bottom: 3px;
}
.info-row dd {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--ink);
}
.chip {
  display: inline-block;
  font-size: 0.76rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 999px;
}
.chip.danger {
  background: rgba(212, 80, 62, 0.14);
  color: var(--danger);
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}

@media (max-width: 820px) {
  .room {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr 300px;
    grid-template-areas:
      "bar"
      "main"
      "side";
  }
  .side {
    border-left: none;
    border-top: 1px solid var(--line);
  }
  .selfview {
    width: 128px;
    height: 90px;
  }
}

