/* ============================================================
   Maison Lumière — Modern Hair Salon Landing
   Palette: rose-gold + cream + matte black, subtle gold
   Fonts: Cormorant Garamond (display) + Inter (UI)
   ============================================================ */

:root {
  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --sh-sm: 0 1px 2px rgba(28, 24, 20, 0.06), 0 4px 14px rgba(28, 24, 20, 0.05);
  --sh-md: 0 6px 22px rgba(28, 24, 20, 0.08), 0 18px 50px rgba(28, 24, 20, 0.07);
  --sh-lg: 0 18px 60px rgba(28, 24, 20, 0.14);

  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --nav-h: 74px;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4 {
  font-family: var(--serif);
  font-weight: 600;
  line-height: 1.08;
  margin: 0;
  color: var(--ink);
}

p { margin: 0; }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }

.skip {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--ink);
  color: var(--cream);
  padding: 10px 16px;
  border-radius: var(--r-sm);
  z-index: 200;
}
.skip:focus { left: 12px; top: 12px; }

:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
  border-radius: 4px;
}

.eyebrow {
  font-family: var(--sans);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold-d);
  margin: 0 0 14px;
}
.eyebrow--light { color: var(--rose); }

/* ---------- Buttons ---------- */
.btn {
  font-family: var(--sans);
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0.01em;
  padding: 11px 20px;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: transform 0.18s ease, background 0.2s ease, color 0.2s ease,
    border-color 0.2s ease, box-shadow 0.2s ease;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px) scale(0.99); }

.btn--solid {
  background: var(--ink);
  color: var(--cream);
}
.btn--solid:hover {
  background: var(--gold-d);
  color: var(--white);
  box-shadow: var(--sh-md);
}
.btn--ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--line-2);
}
.btn--ghost:hover { border-color: var(--gold); color: var(--gold-d); }

.btn--line {
  background: var(--white);
  color: var(--ink);
  border-color: var(--line-2);
}
.btn--line:hover { border-color: var(--gold); box-shadow: var(--sh-sm); }

.btn--lg { padding: 15px 28px; font-size: 15px; }
.btn--block { width: 100%; padding: 15px; }

/* ---------- Nav ---------- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(250, 246, 239, 0.82);
  backdrop-filter: saturate(150%) blur(14px);
  -webkit-backdrop-filter: saturate(150%) blur(14px);
  border-bottom: 1px solid var(--line);
  transition: box-shadow 0.3s ease, background 0.3s ease;
}
.nav.is-scrolled { box-shadow: var(--sh-sm); }

.nav__inner {
  max-width: 1200px;
  margin: 0 auto;
  height: var(--nav-h);
  padding: 0 28px;
  display: flex;
  align-items: center;
  gap: 26px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-right: auto;
}
.brand__mark {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--gold), var(--gold-d));
  color: var(--white);
  font-family: var(--serif);
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 0.02em;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.25);
}
.brand__name {
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.nav__links {
  display: flex;
  gap: 26px;
}
.nav__links a {
  font-size: 14px;
  font-weight: 500;
  color: var(--ink-2);
  position: relative;
  padding: 6px 0;
}
.nav__links a::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  height: 1.5px;
  width: 0;
  background: var(--gold);
  transition: width 0.25s ease;
}
.nav__links a:hover { color: var(--ink); }
.nav__links a:hover::after { width: 100%; }

.nav__cta { display: flex; gap: 10px; }

.nav__toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 44px;
  height: 44px;
  background: transparent;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  cursor: pointer;
}
.nav__toggle span {
  height: 1.6px;
  width: 20px;
  margin: 0 auto;
  background: var(--ink);
  transition: transform 0.28s ease, opacity 0.2s ease;
}
.nav__toggle[aria-expanded="true"] span:nth-child(1) { transform: translateY(6.6px) rotate(45deg); }
.nav__toggle[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
.nav__toggle[aria-expanded="true"] span:nth-child(3) { transform: translateY(-6.6px) rotate(-45deg); }

.mobileNav {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px 22px 22px;
  border-top: 1px solid var(--line);
  background: var(--bg);
}
.mobileNav a {
  font-size: 16px;
  font-weight: 500;
  padding: 12px 4px;
  border-bottom: 1px solid var(--line);
}
.mobileNav .btn { margin-top: 12px; }

/* ---------- Hero ---------- */
.hero {
  max-width: 1200px;
  margin: 0 auto;
  padding: 56px 28px 0;
  position: relative;
}
.hero__grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 48px;
  align-items: center;
  min-height: 64vh;
}
.hero__title {
  font-size: clamp(56px, 9vw, 116px);
  font-weight: 600;
  letter-spacing: -0.01em;
  margin: 4px 0 22px;
}
.hero__title em {
  font-style: italic;
  font-weight: 500;
  color: var(--gold-d);
}
.hero__lead {
  font-size: 18px;
  color: var(--ink-2);
  max-width: 46ch;
  margin-bottom: 30px;
}
.hero__actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 42px;
}
.hero__stats {
  display: flex;
  gap: 38px;
  margin: 0;
  flex-wrap: wrap;
}
.hero__stats dt {
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 6px;
}
.hero__stats dd {
  margin: 0;
  font-family: var(--serif);
  font-size: 30px;
  font-weight: 600;
  color: var(--ink);
}

.hero__art { margin: 0; }
.hero__frame {
  position: relative;
  border-radius: var(--r-lg);
  aspect-ratio: 4 / 5;
  overflow: hidden;
  background:
    radial-gradient(120% 90% at 70% 10%, rgba(255, 255, 255, 0.5), transparent 55%),
    linear-gradient(160deg, var(--rose-soft) 0%, var(--rose) 42%, var(--gold) 78%, var(--gold-d) 100%);
  box-shadow: var(--sh-lg), inset 0 0 0 1px rgba(255, 255, 255, 0.3);
}
.hero__frame::before {
  content: "";
  position: absolute;
  inset: 14px;
  border: 1px solid rgba(255, 255, 255, 0.45);
  border-radius: calc(var(--r-lg) - 8px);
  pointer-events: none;
}
.hero__shine {
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, transparent 30%, rgba(255, 255, 255, 0.55) 48%, transparent 62%);
  transform: translateX(-30%);
  animation: shine 5.5s ease-in-out infinite;
}
@keyframes shine {
  0%, 60% { transform: translateX(-60%); }
  85%, 100% { transform: translateX(120%); }
}
.hero__tag {
  position: absolute;
  left: 22px;
  bottom: 22px;
  background: rgba(28, 24, 20, 0.7);
  color: var(--cream);
  font-size: 12px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 9px 16px;
  border-radius: 999px;
  backdrop-filter: blur(6px);
}

/* ---------- Marquee ---------- */
.marquee {
  margin-top: 56px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  overflow: hidden;
  padding: 18px 0;
}
.marquee__track {
  display: flex;
  gap: 26px;
  width: max-content;
  animation: scroll 30s linear infinite;
  font-family: var(--serif);
  font-size: 22px;
  color: var(--ink-2);
  white-space: nowrap;
}
.marquee__track span { color: var(--ink-2); }
.marquee:hover .marquee__track { animation-play-state: paused; }
@keyframes scroll {
  to { transform: translateX(-50%); }
}

/* ---------- Sections ---------- */
.section {
  max-width: 1200px;
  margin: 0 auto;
  padding: 96px 28px;
}
.section--tint {
  max-width: none;
  background: linear-gradient(180deg, var(--cream), var(--bg));
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.section--tint > * {
  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
}
.section--dark {
  max-width: none;
  background: var(--ink);
  color: var(--cream);
}
.section--dark > * {
  max-width: 1000px;
  margin-left: auto;
  margin-right: auto;
}
.section--dark .section__title { color: var(--cream); }

.section__head { max-width: 640px; margin-bottom: 44px; }
.section--dark .section__head,
.section--tint .section__head { margin-left: auto; margin-right: auto; text-align: center; }
.section__title {
  font-size: clamp(34px, 5vw, 54px);
  margin-bottom: 16px;
}
.section__sub {
  font-size: 16px;
  color: var(--muted);
  max-width: 56ch;
}
.section--tint .section__sub,
.section--dark .section__head .section__sub { margin: 0 auto; }
.section--dark .section__sub { color: var(--rose); }

/* ---------- Services ---------- */
.services {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.svc {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 26px 24px 22px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}
.svc:hover {
  transform: translateY(-4px);
  box-shadow: var(--sh-md);
  border-color: var(--gold-soft);
}
.svc--feature {
  background: linear-gradient(165deg, var(--ink) 0%, var(--ink-2) 100%);
  color: var(--cream);
  border-color: transparent;
}
.svc--feature h3,
.svc--feature .svc__price { color: var(--white); }
.svc--feature p { color: var(--rose-soft); }
.svc--feature .svc__meta { color: var(--rose); }
.svc--feature .svc__add { border-color: rgba(255, 255, 255, 0.3); color: var(--cream); }
.svc--feature .svc__add:hover { background: var(--gold); border-color: var(--gold); color: var(--white); }

.svc__top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
}
.svc__top h3 { font-size: 24px; }
.svc__price {
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 600;
  color: var(--gold-d);
  white-space: nowrap;
}
.svc p { font-size: 14.5px; color: var(--ink-2); flex: 1; }
.svc__meta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  letter-spacing: 0.04em;
  color: var(--muted);
  text-transform: uppercase;
}
.dot { width: 4px; height: 4px; border-radius: 50%; background: currentColor; opacity: 0.5; }
.svc__add {
  align-self: flex-start;
  margin-top: 6px;
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 600;
  padding: 9px 16px;
  border-radius: 999px;
  border: 1px solid var(--line-2);
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: all 0.18s ease;
}
.svc__add:hover { background: var(--ink); color: var(--cream); border-color: var(--ink); }
.svc__add.is-added { background: var(--gold-soft); border-color: var(--gold); color: var(--gold-d); }

/* ---------- Stylists ---------- */
.stylists {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 22px;
}
.stylist {
  text-align: center;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 24px 18px 22px;
  transition: transform 0.22s ease, box-shadow 0.22s ease;
}
.stylist:hover { transform: translateY(-4px); box-shadow: var(--sh-md); }
.stylist__photo {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  margin: 0 auto 16px;
  background: linear-gradient(140deg, var(--c1), var(--c2));
  position: relative;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.3), var(--sh-sm);
}
.stylist__photo::after {
  content: attr(data-initials);
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-family: var(--serif);
  font-size: 30px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.92);
}
.stylist h3 { font-size: 22px; }
.stylist__role {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-d);
  margin: 6px 0 10px;
}
.stylist__bio { font-size: 13.5px; color: var(--ink-2); margin-bottom: 16px; min-height: 38px; }
.link-pill {
  font-family: var(--sans);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
  padding: 8px 18px;
  border-radius: 999px;
  border: 1px solid var(--line-2);
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: all 0.18s ease;
}
.link-pill:hover { background: var(--gold); border-color: var(--gold); color: var(--white); }

/* ---------- Before / After ---------- */
.ba {
  position: relative;
  width: 100%;
  aspect-ratio: 21 / 9;
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--sh-md);
  margin-bottom: 28px;
  user-select: none;
  touch-action: none;
}
.ba__pane {
  position: absolute;
  inset: 0;
}
.ba__pane--after {
  background:
    radial-gradient(80% 120% at 80% 10%, rgba(255, 255, 255, 0.35), transparent 50%),
    linear-gradient(120deg, var(--gold-soft), var(--rose) 55%, var(--gold-d));
}
.ba__pane--before {
  background:
    radial-gradient(80% 120% at 20% 90%, rgba(255, 255, 255, 0.12), transparent 50%),
    linear-gradient(120deg, #6f655a, var(--ink-2) 60%, var(--ink));
  clip-path: inset(0 50% 0 0);
}
.ba__lbl {
  position: absolute;
  top: 18px;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  padding: 7px 14px;
  border-radius: 999px;
  background: rgba(28, 24, 20, 0.55);
  color: var(--cream);
  backdrop-filter: blur(4px);
}
.ba__pane--after .ba__lbl { right: 18px; }
.ba__pane--before .ba__lbl { left: 18px; }
.ba__range {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  opacity: 0;
  cursor: ew-resize;
}
.ba__handle {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 50%;
  width: 2px;
  background: rgba(255, 255, 255, 0.9);
  transform: translateX(-1px);
  pointer-events: none;
  box-shadow: 0 0 0 1px rgba(28, 24, 20, 0.1);
}
.ba__handle span {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 44px;
  height: 44px;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: var(--white);
  box-shadow: var(--sh-md);
  display: grid;
  place-items: center;
}
.ba__handle span::before {
  content: "‹ ›";
  font-size: 16px;
  letter-spacing: 2px;
  color: var(--gold-d);
  font-weight: 700;
}

/* ---------- Lookbook ---------- */
.lookbook {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.look {
  margin: 0;
  position: relative;
  aspect-ratio: 3 / 4;
  border-radius: var(--r-md);
  overflow: hidden;
  background: linear-gradient(160deg, var(--a), var(--b));
  box-shadow: var(--sh-sm);
  transition: transform 0.3s ease;
}
.look::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(28, 24, 20, 0.55), transparent 50%);
}
.look:hover { transform: scale(1.02); }
.look figcaption {
  position: absolute;
  left: 16px;
  bottom: 14px;
  z-index: 1;
  font-family: var(--serif);
  font-size: 19px;
  color: var(--white);
}

/* ---------- Testimonials ---------- */
.quotes { position: relative; min-height: 200px; }
.quote {
  margin: 0;
  text-align: center;
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 22px;
  opacity: 0;
  transform: translateY(14px);
  transition: opacity 0.5s ease, transform 0.5s ease;
  pointer-events: none;
}
.quote.is-active { opacity: 1; transform: none; pointer-events: auto; }
.quote p {
  font-family: var(--serif);
  font-size: clamp(22px, 3.4vw, 34px);
  font-weight: 500;
  line-height: 1.32;
  color: var(--cream);
  max-width: 22ch;
}
.quote footer {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: 14px;
}
.quote__name { color: var(--rose-soft); font-weight: 500; }
.quote__stars { color: var(--gold); letter-spacing: 2px; }
.quotes__dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 34px;
}
.quotes__dots button {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: none;
  background: rgba(247, 241, 232, 0.3);
  cursor: pointer;
  padding: 0;
  transition: background 0.2s ease, transform 0.2s ease;
}
.quotes__dots button:hover { background: rgba(247, 241, 232, 0.6); }
.quotes__dots button.is-active { background: var(--gold); transform: scale(1.2); }

/* ---------- Visit + Book ---------- */
.visit {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 56px;
  align-items: start;
}
.hours {
  list-style: none;
  margin: 22px 0 26px;
  padding: 0;
  border-top: 1px solid var(--line);
}
.hours li {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 14px 2px;
  border-bottom: 1px solid var(--line);
  font-size: 15px;
}
.hours li span:first-child { color: var(--ink-2); font-weight: 500; }
.hours li span:last-child { color: var(--ink); font-variant-numeric: tabular-nums; }
.hours--off span:last-child { color: var(--muted); }

.visit__addr {
  font-style: normal;
  font-size: 15px;
  line-height: 1.8;
  color: var(--ink-2);
}
.visit__addr a { color: var(--gold-d); font-weight: 500; }
.visit__addr a:hover { text-decoration: underline; }

.status {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-top: 20px;
  font-size: 13px;
  font-weight: 600;
  padding: 8px 16px;
  border-radius: 999px;
  background: var(--white);
  border: 1px solid var(--line);
}
.status::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--muted);
}
.status.is-open { color: var(--ok); }
.status.is-open::before { background: var(--ok); box-shadow: 0 0 0 3px rgba(95, 138, 107, 0.18); }
.status.is-closed { color: var(--danger); }
.status.is-closed::before { background: var(--danger); }

/* Booking form */
.book {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 32px 30px;
  box-shadow: var(--sh-md);
  position: sticky;
  top: calc(var(--nav-h) + 16px);
}
.book__title { font-size: 30px; margin-bottom: 6px; }
.book__note { font-size: 13.5px; color: var(--muted); margin-bottom: 22px; }

.field { margin-bottom: 16px; }
.field label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-2);
  margin-bottom: 7px;
}
.field input,
.field select {
  width: 100%;
  font-family: var(--sans);
  font-size: 15px;
  color: var(--ink);
  padding: 12px 14px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  background: var(--bg);
  transition: border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
}
.field input:focus,
.field select:focus {
  outline: none;
  border-color: var(--gold);
  background: var(--white);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.16);
}
.field input.is-invalid,
.field select.is-invalid {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(179, 80, 62, 0.14);
}
.field--row { display: grid; grid-template-columns: 1fr 0.8fr; gap: 14px; }

.book__summary {
  margin: 4px 0 18px;
  padding: 16px 18px;
  border-radius: var(--r-md);
  background: var(--cream);
  border: 1px dashed var(--gold-soft);
}
.book__summary-label {
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gold-d);
  font-weight: 600;
}
.book__summary ul {
  list-style: none;
  margin: 12px 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.book__summary li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 14px;
  color: var(--ink-2);
}
.book__summary li button {
  border: none;
  background: transparent;
  color: var(--danger);
  cursor: pointer;
  font-size: 13px;
  padding: 0 2px;
}
.book__summary li button:hover { text-decoration: underline; }
.book__total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-top: 12px;
  border-top: 1px solid var(--gold-soft);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}
.book__total strong {
  font-family: var(--serif);
  font-size: 26px;
  color: var(--ink);
  letter-spacing: 0;
  text-transform: none;
}
.book__fine { font-size: 11.5px; color: var(--muted); text-align: center; margin-top: 12px; }

/* ---------- Footer ---------- */
.foot {
  background: var(--ink);
  color: var(--rose-soft);
  padding: 64px 28px 28px;
}
.foot__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.2fr 2fr;
  gap: 48px;
  padding-bottom: 44px;
  border-bottom: 1px solid rgba(247, 241, 232, 0.12);
}
.foot__brand { display: flex; flex-direction: column; gap: 16px; }
.foot__tag {
  font-family: var(--serif);
  font-size: 22px;
  color: var(--cream);
  max-width: 16ch;
}
.foot__cols {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}
.foot__cols h4 {
  font-family: var(--sans);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--rose);
  margin-bottom: 16px;
}
.foot__cols a {
  display: block;
  font-size: 14px;
  color: var(--rose-soft);
  padding: 5px 0;
  transition: color 0.18s ease;
}
.foot__cols a:hover { color: var(--gold); }
.foot__base {
  max-width: 1200px;
  margin: 24px auto 0;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  font-size: 12.5px;
  color: var(--muted);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 130%);
  background: var(--ink);
  color: var(--cream);
  padding: 13px 22px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 500;
  box-shadow: var(--sh-lg);
  z-index: 300;
  opacity: 0;
  transition: transform 0.4s cubic-bezier(0.2, 0.9, 0.3, 1), opacity 0.3s ease;
  max-width: calc(100vw - 40px);
  text-align: center;
}
.toast.is-show { transform: translate(-50%, 0); opacity: 1; }
.toast::before { content: "✦ "; color: var(--gold); }

/* ---------- Reveal-on-scroll ---------- */
.reveal {
  opacity: 0;
  transform: translateY(26px);
  transition: opacity 0.7s ease, transform 0.7s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.reveal.is-in { opacity: 1; transform: none; }

/* ---------- Responsive ---------- */
@media (max-width: 960px) {
  .hero__grid { grid-template-columns: 1fr; gap: 32px; min-height: auto; }
  .hero__art { order: -1; max-width: 420px; }
  .services { grid-template-columns: repeat(2, 1fr); }
  .stylists { grid-template-columns: repeat(2, 1fr); }
  .lookbook { grid-template-columns: repeat(2, 1fr); }
  .visit { grid-template-columns: 1fr; gap: 40px; }
  .book { position: static; }
  .foot__inner { grid-template-columns: 1fr; gap: 32px; }
}

@media (max-width: 860px) {
  .nav__links { display: none; }
  .nav__cta { display: none; }
  .nav__toggle { display: flex; }
}

@media (max-width: 520px) {
  .nav__inner { padding: 0 18px; gap: 14px; }
  .brand__name { font-size: 19px; }
  .hero { padding: 36px 18px 0; }
  .hero__title { margin-bottom: 18px; }
  .hero__lead { font-size: 16px; }
  .hero__actions { gap: 10px; }
  .hero__actions .btn { flex: 1; }
  .hero__stats { gap: 26px; }
  .hero__stats dd { font-size: 24px; }
  .marquee__track { font-size: 18px; }
  .section { padding: 64px 18px; }
  .section--tint, .section--dark { padding-left: 18px; padding-right: 18px; }
  .services { grid-template-columns: 1fr; }
  .stylists { grid-template-columns: 1fr; }
  .lookbook { grid-template-columns: 1fr 1fr; }
  .ba { aspect-ratio: 4 / 5; }
  .book { padding: 24px 20px; }
  .field--row { grid-template-columns: 1fr; }
  .foot__cols { grid-template-columns: 1fr 1fr; }
  .foot__base { flex-direction: column; gap: 6px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
  .reveal { opacity: 1; transform: none; }
}

snippets.js:
/* ============================================================
   Maison Lumière — landing interactions (vanilla JS)
   - mobile nav + sticky shadow
   - reveal-on-scroll
   - animated stat counter
   - service "plan" builder with live total
   - before/after slider (pointer + range)
   - testimonial carousel
   - live open/closed status
   - booking form validation + toast
   ============================================================ */
(function () {
  "use strict";

  /* ---------- Toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("is-show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("is-show");
    }, 2800);
  }

  /* ---------- Mobile nav ---------- */
  var toggle = document.getElementById("navToggle");
  var mobileNav = document.getElementById("mobileNav");
  function closeMobile() {
    if (!toggle || !mobileNav) return;
    toggle.setAttribute("aria-expanded", "false");
    toggle.setAttribute("aria-label", "Open menu");
    mobileNav.hidden = true;
  }
  if (toggle && mobileNav) {
    toggle.addEventListener("click", function () {
      var open = toggle.getAttribute("aria-expanded") === "true";
      toggle.setAttribute("aria-expanded", String(!open));
      toggle.setAttribute("aria-label", open ? "Open menu" : "Close menu");
      mobileNav.hidden = open;
    });
    mobileNav.querySelectorAll("a").forEach(function (a) {
      a.addEventListener("click", closeMobile);
    });
  }

  /* ---------- Sticky nav shadow ---------- */
  var nav = document.querySelector(".nav");
  function onScroll() {
    if (nav) nav.classList.toggle("is-scrolled", window.scrollY > 8);
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  /* ---------- Reveal on scroll ---------- */
  var reveals = document.querySelectorAll(".reveal");
  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (e) {
          if (e.isIntersecting) {
            e.target.classList.add("is-in");
            io.unobserve(e.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -8% 0px" }
    );
    reveals.forEach(function (el) { io.observe(el); });
  } else {
    reveals.forEach(function (el) { el.classList.add("is-in"); });
  }

  /* ---------- Animated counters ---------- */
  function animateCount(el) {
    var target = parseInt(el.getAttribute("data-count"), 10) || 0;
    var dur = 1400;
    var start = performance.now();
    function tick(now) {
      var p = Math.min((now - start) / dur, 1);
      var eased = 1 - Math.pow(1 - p, 3);
      el.textContent = Math.round(target * eased).toLocaleString("en-US") + (p === 1 ? "+" : "");
      if (p < 1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }
  var counters = document.querySelectorAll("[data-count]");
  if ("IntersectionObserver" in window) {
    var cio = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (e) {
          if (e.isIntersecting) {
            animateCount(e.target);
            cio.unobserve(e.target);
          }
        });
      },
      { threshold: 0.6 }
    );
    counters.forEach(function (el) { cio.observe(el); });
  } else {
    counters.forEach(function (el) {
      el.textContent = (parseInt(el.getAttribute("data-count"), 10) || 0).toLocaleString("en-US") + "+";
    });
  }

  /* ---------- Service plan builder ---------- */
  var plan = []; // { name, price }
  var planSummary = document.getElementById("planSummary");
  var planList = document.getElementById("planList");
  var planTotal = document.getElementById("planTotal");

  function renderPlan() {
    if (!planList) return;
    if (plan.length === 0) {
      if (planSummary) planSummary.hidden = true;
      return;
    }
    if (planSummary) planSummary.hidden = false;
    planList.innerHTML = "";
    var total = 0;
    plan.forEach(function (item, idx) {
      total += item.price;
      var li = document.createElement("li");
      var label = document.createElement("span");
      label.textContent = item.name + " · from $" + item.price;
      var rm = document.createElement("button");
      rm.type = "button";
      rm.textContent = "remove";
      rm.setAttribute("aria-label", "Remove " + item.name + " from plan");
      rm.addEventListener("click", function () {
        plan.splice(idx, 1);
        // reset matching service button
        cards.forEach(function (c) {
          if (c.getAttribute("data-name") === item.name) resetCardBtn(c);
        });
        renderPlan();
      });
      li.appendChild(label);
      li.appendChild(rm);
      planList.appendChild(li);
    });
    if (planTotal) planTotal.textContent = "$" + total.toLocaleString("en-US");
  }

  function resetCardBtn(card) {
    var btn = card.querySelector(".svc__add");
    if (btn) {
      btn.classList.remove("is-added");
      btn.textContent = "Add to plan";
    }
  }

  var cards = Array.prototype.slice.call(document.querySelectorAll(".svc"));
  cards.forEach(function (card) {
    var btn = card.querySelector(".svc__add");
    if (!btn) return;
    var name = card.getAttribute("data-name");
    var price = parseInt(card.getAttribute("data-price"), 10) || 0;
    btn.addEventListener("click", function () {
      var existing = plan.findIndex(function (p) { return p.name === name; });
      if (existing > -1) {
        plan.splice(existing, 1);
        resetCardBtn(card);
        toast(name + " removed from your plan");
      } else {
        plan.push({ name: name, price: price });
        btn.classList.add("is-added");
        btn.textContent = "Added ✓";
        toast(name + " added — from $" + price);
        // preselect in booking dropdown if it's the only one
        var sel = document.getElementById("bService");
        if (sel && !sel.value) {
          for (var i = 0; i < sel.options.length; i++) {
            if (sel.options[i].textContent.replace(/&amp;/g, "&").trim() === name) {
              sel.selectedIndex = i;
              break;
            }
          }
        }
      }
      renderPlan();
    });
  });

  /* ---------- Stylist quick-book ---------- */
  document.querySelectorAll("[data-stylist]").forEach(function (b) {
    b.addEventListener("click", function () {
      var who = b.getAttribute("data-stylist");
      var sel = document.getElementById("bStylist");
      if (sel) {
        for (var i = 0; i < sel.options.length; i++) {
          if (sel.options[i].text === who) { sel.selectedIndex = i; break; }
        }
      }
      toast("Booking with " + who + " — fill in your details");
      var book = document.getElementById("book");
      if (book) book.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });

  /* ---------- Before / After slider ---------- */
  var baRange = document.getElementById("baRange");
  var baBefore = document.getElementById("baBefore");
  var baHandle = document.getElementById("baHandle");
  function setBA(val) {
    var v = Math.max(0, Math.min(100, val));
    if (baBefore) baBefore.style.clipPath = "inset(0 " + (100 - v) + "% 0 0)";
    if (baHandle) baHandle.style.left = v + "%";
  }
  if (baRange) {
    baRange.addEventListener("input", function () { setBA(parseFloat(baRange.value)); });
    setBA(parseFloat(baRange.value));
  }

  /* ---------- Testimonials carousel ---------- */
  var quotes = document.querySelectorAll("#quotes .quote");
  var dots = document.querySelectorAll("#quoteDots button");
  var qIndex = 0;
  var qTimer;
  function showQuote(i) {
    qIndex = (i + quotes.length) % quotes.length;
    quotes.forEach(function (q, n) { q.classList.toggle("is-active", n === qIndex); });
    dots.forEach(function (d, n) {
      d.classList.toggle("is-active", n === qIndex);
      d.setAttribute("aria-selected", String(n === qIndex));
    });
  }
  function startQuotes() {
    clearInterval(qTimer);
    qTimer = setInterval(function () { showQuote(qIndex + 1); }, 5500);
  }
  dots.forEach(function (d, n) {
    d.addEventListener("click", function () { showQuote(n); startQuotes(); });
  });
  if (quotes.length) { showQuote(0); startQuotes(); }

  /* ---------- Live open / closed status ---------- */
  // Tue–Thu 10–19, Fri 9–20, Sat 9–18, Sun/Mon closed. Day: 0=Sun..6=Sat
  var SCHEDULE = {
    0: null, 1: null,
    2: [10, 19], 3: [10, 19], 4: [10, 19],
    5: [9, 20], 6: [9, 18]
  };
  function updateStatus() {
    var el = document.getElementById("openStatus");
    if (!el) return;
    var now = new Date();
    var day = now.getDay();
    var hour = now.getHours() + now.getMinutes() / 60;
    var hrs = SCHEDULE[day];
    el.classList.remove("is-open", "is-closed");
    if (hrs && hour >= hrs[0] && hour < hrs[1]) {
      el.classList.add("is-open");
      el.textContent = "Open now · closes at " + hrs[1] + ":00";
    } else {
      el.classList.add("is-closed");
      // find next opening
      for (var add = 0; add < 8; add++) {
        var d = (day + add) % 7;
        var h = SCHEDULE[d];
        if (h && !(add === 0 && hour < h[0] ? false : add === 0)) {
          if (add === 0 && hour < h[0]) {
            el.textContent = "Closed · opens today at " + h[0] + ":00";
            return;
          }
          if (add > 0) {
            var names = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
            var label = add === 1 ? "tomorrow" : names[d];
            el.textContent = "Closed · opens " + label + " at " + h[0] + ":00";
            return;
          }
        }
      }
      el.textContent = "Closed · see hours above";
    }
  }
  updateStatus();
  setInterval(updateStatus, 60000);

  /* ---------- Booking form ---------- */
  var form = document.getElementById("book");
  var dateInput = document.getElementById("bDate");
  if (dateInput) {
    var today = new Date();
    dateInput.min = today.toISOString().split("T")[0];
  }
  if (form) {
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var required = form.querySelectorAll("[required]");
      var firstBad = null;
      required.forEach(function (f) {
        var bad = !f.value.trim();
        f.classList.toggle("is-invalid", bad);
        if (bad && !firstBad) firstBad = f;
      });
      if (firstBad) {
        firstBad.focus();
        toast("Please complete the highlighted fields");
        return;
      }
      var name = form.querySelector("#bName").value.trim().split(" ")[0];
      var service = form.querySelector("#bService").value.replace(/&amp;/g, "&");
      var date = form.querySelector("#bDate").value;
      var time = form.querySelector("#bTime").value;
      toast("Thank you, " + name + " — your " + service + " request for " + date + " at " + time + " is in. We will text to confirm.");
      form.reset();
      plan = [];
      cards.forEach(resetCardBtn);
      renderPlan();
      if (dateInput) dateInput.min = new Date().toISOString().split("T")[0];
    });
    form.querySelectorAll("input, select").forEach(function (f) {
      f.addEventListener("input", function () { f.classList.remove("is-invalid"); });
      f.addEventListener("change", function () { f.classList.remove("is-invalid"); });
    });
  }

  /* ---------- Footer social stubs ---------- */
  document.querySelectorAll("[data-soc]").forEach(function (a) {
    a.addEventListener("click", function (e) {
      e.preventDefault();
      toast("Follow @maisonlumiere — link coming soon");
    });
  });
})();

snippets.css:
:root {
  /* Palette override — Blush + lavender + chrome */
  --blush: #f7c8d6;
  --blush-d: #e58aa6;
  --lav: #cdbdf0;
  --lav-d: #a98fe0;
  --chrome: #d8dde6;
  --ink: #2a2233;
  --ink-2: #4a3f57;
  --muted: #8a8095;
  --bg: #fdf6f9;
  --white: #ffffff;
  --line: rgba(42, 34, 51, 0.1);
  --line-2: rgba(42, 34, 51, 0.16);
  --ok: #5f8a6b;

  --sans: "Poppins", "Inter", system-ui, -apple-system, sans-serif;

  --r-sm: 14px;
  --r-md: 22px;
  --r-lg: 34px;
  --r-pill: 999px;

  --sh-sm: 0 4px 16px rgba(42, 34, 51, 0.07);
  --sh-md: 0 14px 40px rgba(165, 120, 170, 0.16);
  --sh-lg: 0 28px 70px rgba(165, 120, 170, 0.22);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-weight: 400;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
}

h1, h2, h3 {
  margin: 0;
  font-weight: 700;
  line-height: 1.08;
  letter-spacing: -0.02em;
}

p {
  margin: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
}

.wrap {
  width: min(1140px, 92vw);
  margin-inline: auto;
}

.skip-link {
  position: absolute;
  left: -999px;
  top: 8px;
  z-index: 200;
  background: var(--ink);
  color: #fff;
  padding: 10px 16px;
  border-radius: var(--r-pill);
}
.skip-link:focus {
  left: 16px;
}

.eyebrow {
  display: inline-block;
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--blush-d);
  margin-bottom: 0.7rem;
}
.eyebrow--light {
  color: rgba(255, 255, 255, 0.9);
}

/* ============ BUTTONS ============ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border: 0;
  border-radius: var(--r-pill);
  padding: 0.7rem 1.35rem;
  font-weight: 600;
  font-size: 0.95rem;
  transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
  white-space: nowrap;
}
.btn:active {
  transform: translateY(1px) scale(0.99);
}
.btn--solid {
  background: linear-gradient(135deg, var(--blush-d), var(--lav-d));
  color: #fff;
  box-shadow: 0 8px 22px rgba(229, 138, 166, 0.4);
}
.btn--solid:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 30px rgba(169, 143, 224, 0.45);
}
.btn--ghost {
  background: var(--white);
  color: var(--ink);
  border: 1.5px solid var(--line-2);
}
.btn--ghost:hover {
  border-color: var(--lav-d);
  color: var(--lav-d);
  transform: translateY(-2px);
}
.btn--lg {
  padding: 0.92rem 1.7rem;
  font-size: 1rem;
}
.btn:focus-visible {
  outline: 3px solid var(--lav-d);
  outline-offset: 2px;
}

/* ============ NAV ============ */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(253, 246, 249, 0.78);
  backdrop-filter: saturate(160%) blur(14px);
  transition: box-shadow 0.25s ease, border-color 0.25s ease;
  border-bottom: 1px solid transparent;
}
.nav.is-stuck {
  box-shadow: var(--sh-sm);
  border-bottom-color: var(--line);
}
.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-weight: 800;
  font-size: 1.18rem;
  letter-spacing: -0.02em;
}
.brand__name em {
  font-style: normal;
  color: var(--blush-d);
}
.brand__dot {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--blush), var(--lav));
  box-shadow: 0 0 0 4px rgba(205, 189, 240, 0.3);
}
.nav__links {
  display: flex;
  align-items: center;
  gap: 1.7rem;
}
.nav__links a[data-link] {
  font-weight: 500;
  font-size: 0.96rem;
  color: var(--ink-2);
  position: relative;
  transition: color 0.18s;
}
.nav__links a[data-link]::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -6px;
  width: 0;
  height: 2px;
  border-radius: 2px;
  background: linear-gradient(90deg, var(--blush-d), var(--lav-d));
  transition: width 0.22s ease;
}
.nav__links a[data-link]:hover,
.nav__links a[data-link].is-active {
  color: var(--ink);
}
.nav__links a[data-link]:hover::after,
.nav__links a[data-link].is-active::after {
  width: 100%;
}
.nav__toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: var(--white);
  border: 1.5px solid var(--line-2);
  border-radius: 12px;
  padding: 11px 10px;
}
.nav__toggle span {
  width: 22px;
  height: 2.4px;
  border-radius: 2px;
  background: var(--ink);
  transition: transform 0.25s ease, opacity 0.2s ease;
}
.nav__toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7.4px) rotate(45deg);
}
.nav__toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}
.nav__toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7.4px) rotate(-45deg);
}

/* ============ HERO ============ */
.hero {
  position: relative;
  padding: 4.5rem 0 5.5rem;
  overflow: hidden;
}
.hero__grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 3rem;
  align-items: center;
}
.hero__copy {
  max-width: 36ch;
}
.hero__title {
  font-size: clamp(2.6rem, 6vw, 4.4rem);
  margin: 0.2rem 0 1.1rem;
}
.grad {
  background: linear-gradient(120deg, var(--blush-d), var(--lav-d) 70%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero__lead {
  font-size: 1.1rem;
  color: var(--ink-2);
  margin-bottom: 1.8rem;
}
.hero__cta {
  display: flex;
  gap: 0.8rem;
  flex-wrap: wrap;
}
.hero__stats {
  list-style: none;
  margin: 2.4rem 0 0;
  padding: 0;
  display: flex;
  gap: 2.2rem;
}
.hero__stats b {
  display: block;
  font-size: 1.9rem;
  font-weight: 800;
  color: var(--ink);
  letter-spacing: -0.03em;
}
.hero__stats small {
  font-size: 0.78rem;
  color: var(--muted);
  font-weight: 500;
}

/* Blobs */
.blob {
  position: absolute;
  border-radius: 48% 52% 60% 40% / 55% 45% 55% 45%;
  filter: blur(8px);
  opacity: 0.85;
  z-index: 1;
  animation: float 9s ease-in-out infinite;
}
.blob--1 {
  width: 340px;
  height: 340px;
  background: radial-gradient(circle at 30% 30%, var(--blush), transparent 70%);
  top: -90px;
  right: -60px;
}
.blob--2 {
  width: 300px;
  height: 300px;
  background: radial-gradient(circle at 40% 40%, var(--lav), transparent 70%);
  bottom: -120px;
  left: -90px;
  animation-delay: -3s;
}
.blob--3 {
  width: 180px;
  height: 180px;
  background: radial-gradient(circle at 50% 50%, var(--chrome), transparent 72%);
  top: 40%;
  left: 44%;
  animation-delay: -5s;
  opacity: 0.6;
}
@keyframes float {
  0%, 100% { transform: translate(0, 0) rotate(0deg); }
  50% { transform: translate(14px, -22px) rotate(8deg); }
}

/* Booking card */
.bookcard {
  position: relative;
  z-index: 2;
  background: var(--white);
  border-radius: var(--r-lg);
  padding: 1.8rem;
  box-shadow: var(--sh-md);
  border: 1px solid var(--line);
}
.bookcard__title {
  font-size: 1.4rem;
}
.bookcard__sub {
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0.3rem 0 1.3rem;
}
.field {
  display: block;
  margin-bottom: 1rem;
}
.field > span {
  display: block;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--ink-2);
  margin-bottom: 0.4rem;
}
.field input,
.field select {
  width: 100%;
  font-family: inherit;
  font-size: 0.95rem;
  color: var(--ink);
  background: var(--bg);
  border: 1.5px solid var(--line);
  border-radius: var(--r-sm);
  padding: 0.7rem 0.85rem;
  transition: border-color 0.18s, box-shadow 0.18s;
}
.field input:focus,
.field select:focus {
  outline: none;
  border-color: var(--lav-d);
  box-shadow: 0 0 0 4px rgba(205, 189, 240, 0.3);
}
.field.is-invalid input,
.field.is-invalid select {
  border-color: var(--blush-d);
  box-shadow: 0 0 0 4px rgba(229, 138, 166, 0.22);
}
.field-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.8rem;
}
.bookcard__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-top: 0.5rem;
}
.bookcard__price {
  font-size: 0.82rem;
  color: var(--muted);
  font-weight: 500;
}
.bookcard__price b {
  display: block;
  font-size: 1.3rem;
  color: var(--ink);
  font-weight: 800;
}

/* ============ SECTIONS ============ */
.section {
  padding: 5rem 0;
}
.section--tint {
  background: linear-gradient(180deg, rgba(247, 200, 214, 0.16), rgba(205, 189, 240, 0.14));
}
.sec-head {
  text-align: center;
  max-width: 44ch;
  margin: 0 auto 2.8rem;
}
.sec-title {
  font-size: clamp(1.8rem, 4vw, 2.7rem);
}
.sec-sub {
  color: var(--muted);
  margin-top: 0.7rem;
  font-size: 1rem;
}

.grid {
  display: grid;
  gap: 1.2rem;
}
.grid--svc {
  grid-template-columns: repeat(3, 1fr);
}
.card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  box-shadow: var(--sh-sm);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--sh-md);
  border-color: rgba(169, 143, 224, 0.4);
}

/* Service card */
.svc {
  text-align: left;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.svc__emoji {
  font-size: 1.8rem;
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  border-radius: 18px;
  background: linear-gradient(135deg, rgba(247, 200, 214, 0.5), rgba(205, 189, 240, 0.5));
  margin-bottom: 0.5rem;
}
.svc h3 {
  font-size: 1.18rem;
}
.svc p {
  color: var(--ink-2);
  font-size: 0.92rem;
  flex: 1;
}
.svc__price {
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--blush-d);
  margin-top: 0.5rem;
}
.svc.is-picked {
  border-color: var(--lav-d);
  box-shadow: 0 0 0 3px rgba(205, 189, 240, 0.45), var(--sh-md);
}

/* ============ GALLERY ============ */
.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  justify-content: center;
  margin-bottom: 2rem;
}
.chip {
  border: 1.5px solid var(--line-2);
  background: var(--white);
  color: var(--ink-2);
  border-radius: var(--r-pill);
  padding: 0.5rem 1.1rem;
  font-weight: 600;
  font-size: 0.88rem;
  transition: all 0.18s ease;
}
.chip:hover {
  border-color: var(--lav-d);
  color: var(--lav-d);
}
.chip.is-active {
  background: linear-gradient(135deg, var(--blush-d), var(--lav-d));
  border-color: transparent;
  color: #fff;
}
.gallery {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}
.tile {
  position: relative;
  aspect-ratio: 1;
  border-radius: var(--r-md);
  overflow: hidden;
  box-shadow: var(--sh-sm);
  transition: transform 0.25s ease, box-shadow 0.25s ease, opacity 0.3s ease;
  cursor: pointer;
  border: 0;
}
.tile:hover {
  transform: translateY(-4px) rotate(-1deg);
  box-shadow: var(--sh-md);
}
.tile.is-hidden {
  display: none;
}
.tile__meta {
  position: absolute;
  inset: auto 0 0 0;
  padding: 0.7rem 0.9rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(transparent, rgba(42, 34, 51, 0.55));
  color: #fff;
}
.tile__name {
  font-weight: 600;
  font-size: 0.82rem;
}
.tile__like {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.8rem;
  font-weight: 600;
}
.tile.is-liked .tile__like {
  color: var(--blush);
}
.tile__like .heart {
  font-size: 0.95rem;
  transition: transform 0.2s;
}
.tile.is-liked .tile__like .heart {
  transform: scale(1.3);
}

/* ============ OFFERS ============ */
.offers {
  padding: 3.5rem 0;
}
.offers__inner {
  background: linear-gradient(120deg, var(--blush-d), var(--lav-d));
  border-radius: var(--r-lg);
  padding: 2.6rem 2.8rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
  color: #fff;
  box-shadow: var(--sh-md);
}
.offers__title {
  font-size: clamp(1.6rem, 3.4vw, 2.3rem);
  margin: 0.3rem 0 0.7rem;
}
.offers__copy {
  max-width: 46ch;
}
.offers__copy p {
  color: rgba(255, 255, 255, 0.92);
}
.offers__codebox {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.6rem;
  background: rgba(255, 255, 255, 0.16);
  border: 1px dashed rgba(255, 255, 255, 0.55);
  border-radius: var(--r-md);
  padding: 1.4rem 1.6rem;
}
.offers__label {
  font-size: 0.74rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 700;
  opacity: 0.85;
}
.offers__code {
  font-size: 1.7rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  font-family: var(--sans);
}
.offers__codebox .btn--solid {
  background: #fff;
  color: var(--ink);
  box-shadow: none;
}

/* ============ TEAM ============ */
.team {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.2rem;
}
.artist {
  padding: 1.6rem 1.4rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.3rem;
}
.artist__avatar {
  width: 76px;
  height: 76px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--av, linear-gradient(135deg, var(--blush), var(--lav)));
  color: #fff;
  font-weight: 800;
  font-size: 1.4rem;
  letter-spacing: 0.02em;
  margin-bottom: 0.6rem;
  box-shadow: 0 6px 18px rgba(169, 143, 224, 0.35);
}
.artist h3 {
  font-size: 1.1rem;
}
.artist p {
  color: var(--muted);
  font-size: 0.86rem;
}
.artist.is-picked {
  border-color: var(--lav-d);
  box-shadow: 0 0 0 3px rgba(205, 189, 240, 0.45), var(--sh-md);
}

/* ============ FOOTER ============ */
.footer {
  background: var(--ink);
  color: #fff;
  padding: 3rem 0 2rem;
}
.footer__inner {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 1.6rem;
  align-items: start;
}
.footer__brand {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}
.footer .brand__name {
  font-size: 1.3rem;
  display: inline-flex;
  align-items: center;
}
.footer .brand__name em {
  color: var(--blush);
}
.footer__brand p {
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.86rem;
}
.footer__links {
  display: flex;
  gap: 1.4rem;
  flex-wrap: wrap;
  justify-content: flex-end;
}
.footer__links a {
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.92rem;
  font-weight: 500;
}
.footer__links a:hover {
  color: var(--blush);
}
.footer__fine {
  grid-column: 1 / -1;
  margin-top: 1.6rem;
  padding-top: 1.4rem;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  color: rgba(255, 255, 255, 0.5);
  font-size: 0.8rem;
}

/* ============ TOASTS ============ */
.toast-wrap {
  position: fixed;
  bottom: 1.4rem;
  left: 50%;
  transform: translateX(-50%);
  z-index: 300;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  width: max-content;
  max-width: 90vw;
}
.toast {
  background: var(--ink);
  color: #fff;
  padding: 0.85rem 1.3rem;
  border-radius: var(--r-pill);
  box-shadow: var(--sh-lg);
  font-size: 0.92rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  animation: toast-in 0.3s cubic-bezier(0.2, 0.9, 0.3, 1.3);
}
.toast.is-out {
  animation: toast-out 0.3s ease forwards;
}
.toast .dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--blush);
}
@keyframes toast-in {
  from { opacity: 0; transform: translateY(14px) scale(0.95); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes toast-out {
  to { opacity: 0; transform: translateY(14px) scale(0.95); }
}

/* ============ REVEAL ============ */
.reveal {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.reveal.is-in {
  opacity: 1;
  transform: none;
}

/* ============ RESPONSIVE ============ */
@media (max-width: 920px) {
  .hero__grid {
    grid-template-columns: 1fr;
    gap: 2.4rem;
  }
  .grid--svc,
  .gallery,
  .team {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer__inner {
    grid-template-columns: 1fr;
  }
  .footer__links {
    justify-content: flex-start;
  }
}

@media (max-width: 520px) {
  .nav__links {
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    flex-direction: column;
    align-items: stretch;
    gap: 0.4rem;
    padding: 1rem 4vw 1.4rem;
    background: rgba(253, 246, 249, 0.97);
    backdrop-filter: blur(14px);
    border-bottom: 1px solid var(--line);
    box-shadow: var(--sh-md);
    transform: translateY(-12px);
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.2s ease, transform 0.2s ease;
  }
  .nav__links.is-open {
    transform: none;
    opacity: 1;
    pointer-events: auto;
  }
  .nav__links a[data-link] {
    padding: 0.7rem 0.4rem;
    border-bottom: 1px solid var(--line);
  }
  .nav__links a[data-link]::after {
    display: none;
  }
  .nav__cta {
    margin-top: 0.4rem;
    text-align: center;
  }
  .nav__toggle {
    display: flex;
  }
  .hero {
    padding: 2.6rem 0 3.4rem;
  }
  .hero__stats {
    gap: 1.4rem;
  }
  .hero__stats b {
    font-size: 1.5rem;
  }
  .grid--svc,
  .gallery,
  .team {
    grid-template-columns: 1fr;
  }
  .gallery {
    grid-template-columns: 1fr 1fr;
  }
  .offers__inner {
    padding: 1.8rem;
  }
  .field-row {
    grid-template-columns: 1fr;
  }
  .section {
    padding: 3.4rem 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    scroll-behavior: auto !important;
  }
  .reveal {
    opacity: 1;
    transform: none;
  }
}

