:root {
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --shadow-sm: 0 1px 2px rgba(28, 24, 20, 0.06),
    0 4px 14px rgba(28, 24, 20, 0.05);
  --shadow-md: 0 6px 24px rgba(28, 24, 20, 0.09),
    0 24px 60px rgba(28, 24, 20, 0.08);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.5;
  color: var(--ink);
  background:
    radial-gradient(900px 520px at 88% -10%, var(--rose-soft), transparent 60%),
    radial-gradient(760px 460px at -10% 110%, var(--gold-soft), transparent 55%),
    var(--bg);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.shell {
  max-width: 900px;
  margin: 0 auto;
  padding: clamp(20px, 5vw, 56px) clamp(16px, 4vw, 32px);
}

.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-md);
  padding: clamp(20px, 4vw, 38px);
}

/* ---------- Profile header ---------- */
.profile {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 22px;
  padding-bottom: 26px;
  border-bottom: 1px solid var(--line);
}

.profile__id {
  display: flex;
  align-items: center;
  gap: 18px;
}

.avatar {
  flex: none;
  display: grid;
  place-items: center;
  width: 66px;
  height: 66px;
  border-radius: 50%;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 24px;
  letter-spacing: 0.03em;
  color: var(--white);
  background: linear-gradient(150deg, var(--rose), var(--gold-d));
  box-shadow: var(--shadow-sm);
  border: 2px solid var(--white);
  outline: 1px solid var(--gold-soft);
}

.eyebrow {
  margin: 0 0 4px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold-d);
}

#client-name {
  margin: 0;
  font-family: var(--serif);
  font-weight: 600;
  font-size: clamp(28px, 5vw, 38px);
  line-height: 1.05;
  color: var(--ink);
}

.profile__sub {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--muted);
}

.profile__sub strong {
  color: var(--ink-2);
  font-weight: 600;
}

.dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 6px;
  border-radius: 50%;
  background: var(--ok);
  vertical-align: middle;
}

.profile__stats {
  display: flex;
  gap: 10px;
  margin: 0;
}

.stat {
  text-align: center;
  padding: 10px 16px;
  border-radius: var(--r-md);
  background: var(--cream);
  border: 1px solid var(--line);
  min-width: 72px;
}

.stat dt {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}

.stat dd {
  margin: 3px 0 0;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 22px;
  color: var(--ink);
}

/* ---------- Allergy callout ---------- */
.callout {
  display: flex;
  gap: 14px;
  margin: 26px 0 0;
  padding: 16px 18px;
  border-radius: var(--r-md);
  background: linear-gradient(180deg, #fdf3ef, #fbeae4);
  border: 1px solid rgba(179, 80, 62, 0.28);
  border-left: 3px solid var(--danger);
}

.callout__icon {
  flex: none;
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: var(--danger);
  color: var(--white);
  font-weight: 700;
  font-size: 15px;
}

.callout__title {
  margin: 1px 0 8px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--danger);
}

.callout__list {
  margin: 0;
  padding-left: 18px;
  color: var(--ink-2);
  font-size: 13.5px;
}

.callout__list li + li {
  margin-top: 4px;
}

/* ---------- Grid of cards ---------- */
.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin-top: 22px;
}

.card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 20px;
  box-shadow: var(--shadow-sm);
}

.card--notes {
  margin-top: 18px;
}

.card__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.card__head h2 {
  margin: 0;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 22px;
  color: var(--ink);
}

.count {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gold-d);
  background: var(--gold-soft);
  padding: 3px 9px;
  border-radius: 999px;
}

.card__hint {
  margin: 8px 0 14px;
  font-size: 12.5px;
  color: var(--muted);
}

/* ---------- Chips ---------- */
.chips {
  list-style: none;
  margin: 0 0 14px;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  min-height: 30px;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 8px 6px 13px;
  font-size: 13px;
  font-weight: 500;
  color: var(--ink-2);
  background: var(--rose-soft);
  border: 1px solid rgba(201, 167, 143, 0.5);
  border-radius: 999px;
  animation: pop 0.2s ease;
}

.chip__x {
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: rgba(28, 24, 20, 0.08);
  color: var(--ink-2);
  font-size: 13px;
  line-height: 1;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.chip__x:hover,
.chip__x:focus-visible {
  background: var(--danger);
  color: var(--white);
  outline: none;
}

.chip-empty {
  font-size: 13px;
  color: var(--muted);
  font-style: italic;
}

.chip-form {
  display: flex;
  gap: 8px;
}

.chip-form input {
  flex: 1;
  min-width: 0;
}

/* ---------- Inputs ---------- */
input[type="text"],
textarea {
  width: 100%;
  font-family: var(--sans);
  font-size: 14px;
  color: var(--ink);
  background: var(--cream);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 10px 12px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease,
    background 0.15s ease;
}

input[type="text"]:focus,
textarea:focus {
  outline: none;
  background: var(--white);
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.18);
}

textarea {
  resize: vertical;
  min-height: 64px;
}

::placeholder {
  color: var(--muted);
}

/* ---------- Buttons ---------- */
.btn {
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.01em;
  padding: 10px 16px;
  border-radius: var(--r-sm);
  border: 1px solid transparent;
  cursor: pointer;
  white-space: nowrap;
  transition: transform 0.12s ease, box-shadow 0.15s ease,
    background 0.15s ease, color 0.15s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn--gold {
  color: var(--white);
  background: linear-gradient(160deg, var(--gold), var(--gold-d));
  box-shadow: var(--shadow-sm);
}

.btn--gold:hover {
  box-shadow: 0 6px 18px rgba(140, 109, 63, 0.32);
}

.btn--ghost {
  color: var(--gold-d);
  background: var(--white);
  border-color: var(--line-2);
}

.btn--ghost:hover {
  border-color: var(--gold);
  background: var(--cream);
}

.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.3);
}

/* ---------- Product history ---------- */
.products {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.product {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 11px 4px;
  border-top: 1px solid var(--line);
}

.product:first-child {
  border-top: none;
}

.product__swatch {
  flex: none;
  width: 12px;
  height: 12px;
  margin-top: 4px;
  border-radius: 3px;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.12);
}

.product__name {
  font-weight: 600;
  font-size: 14px;
  color: var(--ink);
}

.product__detail {
  font-size: 12.5px;
  color: var(--muted);
}

.product__tag {
  margin-left: auto;
  flex: none;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gold-d);
  background: var(--gold-soft);
  padding: 3px 8px;
  border-radius: 999px;
  align-self: center;
}

/* ---------- Notes timeline ---------- */
.note-form__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 10px;
}

.note-form__hint {
  font-size: 12px;
  color: var(--muted);
}

.timeline {
  list-style: none;
  margin: 20px 0 0;
  padding: 0;
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  left: 5px;
  top: 6px;
  bottom: 6px;
  width: 1px;
  background: var(--line-2);
}

.entry {
  position: relative;
  padding: 0 0 18px 26px;
  animation: rise 0.28s ease;
}

.entry:last-child {
  padding-bottom: 0;
}

.entry::before {
  content: "";
  position: absolute;
  left: 1px;
  top: 4px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 0 3px var(--gold-soft);
}

.entry__time {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--gold-d);
}

.entry__text {
  margin: 4px 0 0;
  font-size: 14px;
  color: var(--ink-2);
  white-space: pre-wrap;
  word-break: break-word;
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 16px);
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px 20px;
  font-size: 13.5px;
  font-weight: 500;
  color: var(--white);
  background: var(--ink);
  border-radius: 999px;
  box-shadow: var(--shadow-md);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.toast::before {
  content: "✓";
  color: var(--gold);
  font-weight: 700;
}

.toast[hidden] {
  display: flex;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Animations ---------- */
@keyframes pop {
  from {
    transform: scale(0.92);
    opacity: 0;
  }
}

@keyframes rise {
  from {
    transform: translateY(6px);
    opacity: 0;
  }
}

/* ---------- Responsive ---------- */
@media (max-width: 520px) {
  body {
    font-size: 14.5px;
  }

  .panel {
    border-radius: var(--r-md);
  }

  .profile {
    gap: 16px;
  }

  .profile__id {
    gap: 14px;
  }

  .avatar {
    width: 54px;
    height: 54px;
    font-size: 20px;
  }

  .profile__stats {
    width: 100%;
    justify-content: space-between;
  }

  .stat {
    flex: 1;
    min-width: 0;
    padding: 9px 8px;
  }

  .grid {
    grid-template-columns: 1fr;
  }

  .note-form__row {
    flex-direction: column;
    align-items: stretch;
  }

  .note-form__row .btn {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

