:root {
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --sh-sm: 0 1px 2px rgba(28, 24, 20, 0.05), 0 1px 3px rgba(28, 24, 20, 0.05);
  --sh-md: 0 6px 18px -8px rgba(28, 24, 20, 0.18), 0 2px 6px rgba(28, 24, 20, 0.05);
  --sh-lg: 0 22px 48px -18px rgba(28, 24, 20, 0.28), 0 6px 14px rgba(28, 24, 20, 0.06);
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3 {
  font-family: var(--serif);
  font-weight: 600;
  margin: 0;
  letter-spacing: 0.01em;
}

.page {
  max-width: 1140px;
  margin: 0 auto;
  padding: clamp(40px, 7vw, 84px) clamp(20px, 5vw, 48px) 0;
}

/* ---------- Hero ---------- */
.hero {
  text-align: center;
  max-width: 720px;
  margin: 0 auto;
}

.eyebrow {
  font-size: 0.72rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--gold-d);
  font-weight: 600;
  margin: 0 0 18px;
}

.eyebrow--light {
  color: var(--gold-soft);
}

.display {
  font-size: clamp(2.5rem, 6.2vw, 4rem);
  line-height: 1.04;
  color: var(--ink);
}

.lede {
  margin: 22px auto 0;
  max-width: 560px;
  color: var(--ink-2);
  font-size: 1.04rem;
}

.hero-meta {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 30px;
}

.hairline {
  display: block;
  width: clamp(28px, 8vw, 64px);
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold) 50%, transparent);
}

.hero-meta-text {
  font-size: 0.7rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- Controls ---------- */
.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: clamp(44px, 6vw, 68px);
  padding-bottom: 22px;
  border-bottom: 1px solid var(--line);
}

.search {
  position: relative;
  flex: 0 1 280px;
}

.search-ico {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  width: 17px;
  height: 17px;
  color: var(--muted);
  pointer-events: none;
}

.search input {
  width: 100%;
  font-family: var(--sans);
  font-size: 0.92rem;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: 999px;
  padding: 11px 16px 11px 40px;
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}

.search input::placeholder {
  color: var(--muted);
}

.search input:focus-visible {
  outline: none;
  border-color: var(--gold);
  box-shadow: 0 0 0 3px var(--gold-soft);
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  font-family: var(--sans);
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--ink-2);
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: 999px;
  padding: 8px 15px;
  cursor: pointer;
  transition: all 0.16s ease;
  white-space: nowrap;
}

.chip:hover {
  border-color: var(--gold);
  color: var(--ink);
}

.chip[aria-pressed="true"] {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--cream);
}

.chip:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--gold-soft);
  border-color: var(--gold);
}

.result-line {
  margin: 22px 0 0;
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

.result-line span:first-child {
  color: var(--gold-d);
  font-weight: 600;
}

/* ---------- Grid ---------- */
.grid {
  list-style: none;
  margin: 26px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(255px, 1fr));
  gap: clamp(18px, 2.4vw, 26px);
}

.card {
  position: relative;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 26px 24px 24px;
  box-shadow: var(--sh-sm);
  display: flex;
  flex-direction: column;
  text-align: center;
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}

.card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  border: 1px solid transparent;
  background: linear-gradient(180deg, var(--gold-soft), transparent 60%) border-box;
  -webkit-mask: linear-gradient(#fff 0 0) padding-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0;
  transition: opacity 0.22s ease;
  pointer-events: none;
}

.card:hover {
  transform: translateY(-6px);
  box-shadow: var(--sh-lg);
  border-color: transparent;
}

.card:hover::before {
  opacity: 1;
}

.avatar {
  width: 78px;
  height: 78px;
  border-radius: 50%;
  margin: 0 auto 16px;
  display: grid;
  place-items: center;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.6rem;
  color: var(--white);
  letter-spacing: 0.02em;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.35), var(--sh-md);
  position: relative;
}

.avatar::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px solid var(--gold-soft);
}

.name {
  font-size: 1.5rem;
  line-height: 1.1;
  color: var(--ink);
}

.role {
  margin: 4px 0 0;
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gold-d);
  font-weight: 600;
}

.rating {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin: 13px auto 0;
  font-size: 0.8rem;
  color: var(--muted);
}

.stars {
  display: inline-flex;
  gap: 1px;
  color: var(--gold);
}

.stars svg {
  width: 14px;
  height: 14px;
}

.star-empty {
  color: var(--line-2);
}

.rating b {
  color: var(--ink);
  font-weight: 600;
}

.tagline {
  margin: 14px 0 0;
  font-family: var(--serif);
  font-size: 1.06rem;
  font-style: italic;
  color: var(--ink-2);
  line-height: 1.35;
}

.specs {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  margin: 16px 0 0;
}

.spec {
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: var(--gold-d);
  background: var(--rose-soft);
  border-radius: 999px;
  padding: 5px 11px;
}

.divider {
  height: 1px;
  background: var(--line);
  margin: 20px -4px 18px;
}

.btn {
  font-family: var(--sans);
  font-size: 0.86rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  border-radius: var(--r-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.18s ease, background 0.18s ease,
    color 0.18s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--gold-soft);
}

.book {
  margin-top: auto;
  width: 100%;
  padding: 12px 16px;
  color: var(--white);
  background: linear-gradient(135deg, var(--gold), var(--gold-d));
  box-shadow: var(--sh-sm);
}

.book:hover {
  box-shadow: 0 8px 18px -8px rgba(140, 109, 63, 0.7);
}

.book.is-booked {
  background: var(--ink);
  cursor: default;
}

/* ---------- Empty ---------- */
.empty {
  text-align: center;
  padding: 64px 20px;
}

.empty-title {
  font-family: var(--serif);
  font-size: 1.5rem;
  color: var(--ink-2);
  margin: 0 0 10px;
}

.link-btn {
  font-family: var(--sans);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--gold-d);
  background: none;
  border: none;
  border-bottom: 1px solid var(--gold);
  padding: 2px 0;
  cursor: pointer;
}

.link-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--gold-soft);
}

/* ---------- CTA ---------- */
.cta {
  position: relative;
  overflow: hidden;
  margin: clamp(64px, 9vw, 110px) calc(50% - 50vw) 0;
  padding: clamp(56px, 8vw, 88px) 24px;
  background: var(--ink);
  color: var(--cream);
  text-align: center;
}

.cta::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
      120% 100% at 50% -20%,
      rgba(176, 141, 87, 0.28),
      transparent 60%
    );
  pointer-events: none;
}

.cta > * {
  position: relative;
}

.cta-title {
  font-size: clamp(2rem, 4.6vw, 3rem);
  max-width: 640px;
  margin: 16px auto 0;
  color: var(--white);
}

.cta-copy {
  max-width: 480px;
  margin: 18px auto 30px;
  color: rgba(247, 241, 232, 0.8);
  font-size: 1rem;
}

.btn--ghost-gold {
  padding: 13px 28px;
  color: var(--cream);
  background: transparent;
  border: 1px solid var(--gold);
}

.btn--ghost-gold:hover {
  background: var(--gold);
  color: var(--ink);
}

/* ---------- Toast ---------- */
.toast-wrap {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  z-index: 50;
  pointer-events: none;
}

.toast {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  background: var(--ink);
  color: var(--cream);
  font-size: 0.84rem;
  font-weight: 500;
  padding: 11px 18px;
  border-radius: 999px;
  box-shadow: var(--sh-lg);
  border: 1px solid rgba(176, 141, 87, 0.4);
  opacity: 0;
  transform: translateY(12px) scale(0.96);
  transition: opacity 0.26s ease, transform 0.26s ease;
}

.toast.show {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.toast .dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--gold);
}

/* ---------- Responsive ---------- */
@media (max-width: 520px) {
  .controls {
    flex-direction: column;
    align-items: stretch;
  }

  .search {
    flex: 1 1 auto;
  }

  .filters {
    overflow-x: auto;
    flex-wrap: nowrap;
    margin: 0 -20px;
    padding: 2px 20px 4px;
    scrollbar-width: none;
  }

  .filters::-webkit-scrollbar {
    display: none;
  }

  .grid {
    grid-template-columns: 1fr;
  }

  .display {
    font-size: clamp(2.2rem, 11vw, 3rem);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition-duration: 0.01ms !important;
  }
}

