(function () {
  "use strict";

  /* ---------- Data ---------- */
  var TEAM = [
    {
      name: "Aria Vance",
      role: "Creative Director",
      specs: ["Balayage", "Lived-in Color", "Editorial"],
      tagline: "Color should look like it was always yours.",
      rating: 4.9,
      reviews: 312,
      g: ["#b08d57", "#8c6d3f"]
    },
    {
      name: "Léo Marchand",
      role: "Master Barber",
      specs: ["Fades", "Beard Sculpt", "Hot Towel"],
      tagline: "Sharp lines, soft confidence.",
      rating: 4.8,
      reviews: 248,
      g: ["#3d362f", "#1c1814"]
    },
    {
      name: "Mireille Soto",
      role: "Senior Colorist",
      specs: ["Blonding", "Toning", "Gloss"],
      tagline: "I chase light through every strand.",
      rating: 5.0,
      reviews: 401,
      g: ["#c9a78f", "#b08d57"]
    },
    {
      name: "Dario Klein",
      role: "Texture Specialist",
      specs: ["Curls", "Perms", "Treatments"],
      tagline: "Your natural pattern, only better.",
      rating: 4.7,
      reviews: 176,
      g: ["#8c6d3f", "#c9a78f"]
    },
    {
      name: "Noémie Carr",
      role: "Bridal & Updos",
      specs: ["Updos", "Bridal", "Styling"],
      tagline: "For the days you will not forget.",
      rating: 4.9,
      reviews: 289,
      g: ["#c08a3e", "#8c6d3f"]
    },
    {
      name: "Theo Nakamura",
      role: "Precision Cutting",
      specs: ["Cuts", "Fringe", "Bobs"],
      tagline: "The cut is the architecture.",
      rating: 4.8,
      reviews: 221,
      g: ["#5f8a6b", "#3d362f"]
    },
    {
      name: "Ingrid Solène",
      role: "Color Correction",
      specs: ["Color Correction", "Blonding", "Treatments"],
      tagline: "There is no mistake I cannot rewrite.",
      rating: 5.0,
      reviews: 358,
      g: ["#b3503e", "#8c6d3f"]
    },
    {
      name: "Mateo Rivas",
      role: "Stylist & Barber",
      specs: ["Cuts", "Fades", "Styling"],
      tagline: "Walk in tired, walk out new.",
      rating: 4.7,
      reviews: 194,
      g: ["#1c1814", "#b08d57"]
    }
  ];

  /* ---------- Refs ---------- */
  var grid = document.getElementById("grid");
  var filtersEl = document.getElementById("filters");
  var searchEl = document.getElementById("search");
  var countEl = document.getElementById("count");
  var countLabel = document.getElementById("count-label");
  var emptyEl = document.getElementById("empty");
  var resetEl = document.getElementById("reset");
  var joinEl = document.getElementById("join");
  var toastWrap = document.getElementById("toast-wrap");

  var state = { spec: "All", query: "" };

  /* ---------- Toast ---------- */
  function toast(msg) {
    var t = document.createElement("div");
    t.className = "toast";
    t.setAttribute("role", "status");
    t.innerHTML = '<span class="dot"></span><span></span>';
    t.lastChild.textContent = msg;
    toastWrap.appendChild(t);
    requestAnimationFrame(function () {
      t.classList.add("show");
    });
    setTimeout(function () {
      t.classList.remove("show");
      setTimeout(function () {
        t.remove();
      }, 320);
    }, 2600);
  }

  /* ---------- Helpers ---------- */
  function initials(name) {
    return name
      .split(/\s+/)
      .slice(0, 2)
      .map(function (p) {
        return p.charAt(0);
      })
      .join("")
      .toUpperCase();
  }

  function starSvg(filled) {
    return (
      '<svg viewBox="0 0 24 24" aria-hidden="true" class="' +
      (filled ? "" : "star-empty") +
      '"><path fill="currentColor" d="M12 2.5l2.9 5.9 6.5.95-4.7 4.58 1.1 6.47L12 17.4l-5.8 3.05 1.1-6.47L2.6 9.35l6.5-.95L12 2.5z"/></svg>'
    );
  }

  function starsFor(rating) {
    var rounded = Math.round(rating);
    var out = "";
    for (var i = 1; i <= 5; i++) out += starSvg(i <= rounded);
    return out;
  }

  /* ---------- Build filter chips ---------- */
  function buildFilters() {
    var set = {};
    TEAM.forEach(function (m) {
      m.specs.forEach(function (s) {
        set[s] = true;
      });
    });
    var specs = ["All"].concat(Object.keys(set).sort());

    specs.forEach(function (s) {
      var b = document.createElement("button");
      b.type = "button";
      b.className = "chip";
      b.textContent = s;
      b.setAttribute("aria-pressed", s === "All" ? "true" : "false");
      b.addEventListener("click", function () {
        state.spec = s;
        Array.prototype.forEach.call(filtersEl.children, function (c) {
          c.setAttribute("aria-pressed", c === b ? "true" : "false");
        });
        render();
      });
      filtersEl.appendChild(b);
    });
  }

  /* ---------- Render grid ---------- */
  function matches(m) {
    var bySpec = state.spec === "All" || m.specs.indexOf(state.spec) !== -1;
    var q = state.query.trim().toLowerCase();
    var byName =
      !q ||
      m.name.toLowerCase().indexOf(q) !== -1 ||
      m.role.toLowerCase().indexOf(q) !== -1;
    return bySpec && byName;
  }

  function makeCard(m) {
    var li = document.createElement("li");
    li.className = "card";

    var specChips = m.specs
      .map(function (s) {
        return '<span class="spec">' + s + "</span>";
      })
      .join("");

    li.innerHTML =
      '<div class="avatar" style="background:linear-gradient(135deg,' +
      m.g[0] +
      "," +
      m.g[1] +
      ')" aria-hidden="true">' +
      initials(m.name) +
      "</div>" +
      '<h3 class="name">' +
      m.name +
      "</h3>" +
      '<p class="role">' +
      m.role +
      "</p>" +
      '<div class="rating"><span class="stars" role="img" aria-label="' +
      m.rating +
      ' out of 5 stars">' +
      starsFor(m.rating) +
      "</span><span><b>" +
      m.rating.toFixed(1) +
      "</b> · " +
      m.reviews +
      " reviews</span></div>" +
      '<p class="tagline">&ldquo;' +
      m.tagline +
      "&rdquo;</p>" +
      '<div class="specs">' +
      specChips +
      "</div>" +
      '<div class="divider" aria-hidden="true"></div>' +
      '<button class="btn book" type="button">Book with ' +
      m.name.split(" ")[0] +
      "</button>";

    var book = li.querySelector(".book");
    book.addEventListener("click", function () {
      if (book.classList.contains("is-booked")) return;
      book.classList.add("is-booked");
      book.textContent = "Requested ✓";
      toast("Booking request sent to " + m.name + ".");
      setTimeout(function () {
        book.classList.remove("is-booked");
        book.textContent = "Book with " + m.name.split(" ")[0];
      }, 3200);
    });

    return li;
  }

  function render() {
    var list = TEAM.filter(matches);
    grid.innerHTML = "";
    list.forEach(function (m) {
      grid.appendChild(makeCard(m));
    });

    countEl.textContent = list.length;
    countLabel.textContent = list.length === 1 ? "artist" : "artists";

    var none = list.length === 0;
    emptyEl.hidden = !none;
    grid.hidden = none;
  }

  /* ---------- Events ---------- */
  var debounce;
  searchEl.addEventListener("input", function () {
    clearTimeout(debounce);
    debounce = setTimeout(function () {
      state.query = searchEl.value;
      render();
    }, 120);
  });

  resetEl.addEventListener("click", function () {
    state.spec = "All";
    state.query = "";
    searchEl.value = "";
    Array.prototype.forEach.call(filtersEl.children, function (c, i) {
      c.setAttribute("aria-pressed", i === 0 ? "true" : "false");
    });
    render();
    searchEl.focus();
  });

  joinEl.addEventListener("click", function () {
    toast("Thank you — our director will be in touch soon.");
  });

  /* ---------- Init ---------- */
  buildFilters();
  render();
})();

snippets.css:
:root {
  --bg: #140a24;
  --surface: #1e1036;
  --surface-2: #271447;
  --elevated: #2f1a55;
  --ink: #fdf7ff;
  --ink-2: #d3c4e8;
  --muted: #9a8bb5;
  --pink: #ff2fb0;
  --pink-d: #e0179a;
  --violet: #8b5cf6;
  --cyan: #22d3ee;
  --glow: rgba(255, 47, 176, 0.4);
  --line: rgba(255, 255, 255, 0.12);
  --line-2: rgba(255, 255, 255, 0.2);
  --ok: #34d399;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.55);
  --shadow-glow: 0 0 40px -8px var(--glow);
}

*,
*::before,
*::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
}

/* subtle club ambience */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  background:
    radial-gradient(60% 50% at 80% -5%, rgba(139, 92, 246, 0.18), transparent 70%),
    radial-gradient(50% 40% at 0% 100%, rgba(255, 47, 176, 0.14), transparent 70%);
  pointer-events: none;
  z-index: 0;
}

img { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }

h1, h2, h3 { margin: 0; line-height: 1.05; }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0);
  white-space: nowrap; border: 0;
}

.grad {
  background: linear-gradient(100deg, var(--pink), var(--violet) 55%, var(--cyan));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.22em;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--pink);
  margin: 0 0 0.9rem;
}

/* ===== BUTTONS ===== */
.btn {
  --b-bg: transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 0.62rem 1.15rem;
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease,
    border-color 0.2s ease, color 0.2s ease;
  white-space: nowrap;
}
.btn:focus-visible {
  outline: 3px solid var(--cyan);
  outline-offset: 2px;
}
.btn:active { transform: translateY(1px) scale(0.99); }

.btn-primary {
  background: linear-gradient(100deg, var(--pink), var(--pink-d));
  color: #190826;
  box-shadow: 0 8px 24px -6px var(--glow);
}
.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 34px -6px var(--glow), 0 0 0 1px rgba(255, 255, 255, 0.1) inset;
}
.btn-outline {
  border-color: var(--line-2);
  color: var(--ink);
  background: rgba(255, 255, 255, 0.03);
}
.btn-outline:hover {
  border-color: var(--pink);
  color: var(--ink);
  box-shadow: 0 0 22px -10px var(--glow);
  transform: translateY(-2px);
}
.btn-ghost { color: var(--ink-2); }
.btn-ghost:hover { color: var(--ink); }
.btn-lg { padding: 0.9rem 1.6rem; font-size: 1.02rem; }

/* ===== NAV ===== */
.nav {
  position: sticky;
  top: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding: 1rem clamp(1rem, 4vw, 3rem);
  background: rgba(20, 10, 36, 0.55);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid transparent;
  transition: background 0.25s ease, border-color 0.25s ease;
}
.nav.scrolled {
  background: rgba(20, 10, 36, 0.88);
  border-bottom-color: var(--line);
}
.brand {
  font-family: "Anton", "Inter", sans-serif;
  font-size: 1.5rem;
  letter-spacing: 0.04em;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}
.brand-sub { color: var(--pink); }
.brand-dot {
  width: 11px; height: 11px;
  border-radius: 50%;
  background: var(--pink);
  box-shadow: 0 0 14px 2px var(--glow);
  animation: pulse 1.8s ease-in-out infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.45; transform: scale(0.78); }
}
.nav-links {
  display: flex;
  gap: 1.4rem;
  margin-left: auto;
  font-weight: 600;
  font-size: 0.95rem;
}
.nav-links a { color: var(--ink-2); position: relative; padding: 0.25rem 0; }
.nav-links a::after {
  content: "";
  position: absolute;
  left: 0; bottom: -2px;
  height: 2px; width: 0;
  background: var(--pink);
  transition: width 0.2s ease;
}
.nav-links a:hover { color: var(--ink); }
.nav-links a:hover::after { width: 100%; }
.nav-cta { display: flex; gap: 0.6rem; align-items: center; }

.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: 0;
  cursor: pointer;
  padding: 6px;
  margin-left: auto;
}
.nav-toggle span {
  width: 26px; height: 2px;
  background: var(--ink);
  border-radius: 2px;
  transition: transform 0.25s ease, opacity 0.25s ease;
}
.nav-toggle[aria-expanded="true"] span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.nav-toggle[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
.nav-toggle[aria-expanded="true"] span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.mobile-menu {
  position: sticky;
  top: 64px;
  z-index: 49;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  padding: 1rem clamp(1rem, 4vw, 3rem) 1.4rem;
  background: rgba(30, 16, 54, 0.97);
  border-bottom: 1px solid var(--line);
}
.mobile-menu[hidden] { display: none; }
.mobile-menu a {
  padding: 0.7rem 0.2rem;
  font-weight: 600;
  color: var(--ink-2);
  border-bottom: 1px solid var(--line);
}
.mobile-menu a.btn { border-bottom: 0; margin-top: 0.6rem; }

/* ===== HERO ===== */
.hero {
  position: relative;
  z-index: 1;
  padding: clamp(3.5rem, 9vw, 7rem) clamp(1rem, 4vw, 3rem) clamp(3rem, 7vw, 5rem);
  max-width: 1180px;
  margin: 0 auto;
  overflow: hidden;
}
.hero-glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(90px);
  pointer-events: none;
  z-index: -1;
  animation: drift 9s ease-in-out infinite alternate;
}
.hero-glow-a {
  width: 460px; height: 460px;
  background: radial-gradient(circle, rgba(255, 47, 176, 0.55), transparent 65%);
  top: -120px; right: -60px;
}
.hero-glow-b {
  width: 420px; height: 420px;
  background: radial-gradient(circle, rgba(139, 92, 246, 0.5), transparent 65%);
  bottom: -160px; left: -80px;
  animation-delay: -3s;
}
@keyframes drift {
  from { transform: translate(0, 0) scale(1); }
  to { transform: translate(28px, -24px) scale(1.08); }
}
.hero-inner { max-width: 720px; }
.hero-title {
  font-family: "Anton", "Inter", sans-serif;
  font-weight: 400;
  font-size: clamp(2.9rem, 11vw, 6.2rem);
  letter-spacing: 0.01em;
  text-transform: uppercase;
  margin-bottom: 1.2rem;
  text-shadow: 0 0 60px rgba(255, 47, 176, 0.25);
}
.hero-lead {
  font-size: clamp(1.02rem, 2.4vw, 1.22rem);
  color: var(--ink-2);
  max-width: 560px;
  margin: 0 0 1.8rem;
}
.hero-actions { display: flex; gap: 0.8rem; flex-wrap: wrap; margin-bottom: 2.6rem; }
.hero-stats {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  gap: clamp(1.4rem, 5vw, 3rem);
}
.hero-stats li { display: flex; flex-direction: column; }
.hero-stats strong {
  font-family: "Anton", "Inter", sans-serif;
  font-size: clamp(1.5rem, 4vw, 2.1rem);
  background: linear-gradient(120deg, var(--pink), var(--violet));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero-stats span {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.next-ride {
  margin-top: 2.6rem;
  display: flex;
  align-items: center;
  gap: 1.1rem;
  padding: 0.9rem 1.1rem;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: linear-gradient(120deg, rgba(255, 47, 176, 0.08), rgba(139, 92, 246, 0.06));
  max-width: 560px;
  box-shadow: var(--shadow-glow);
}
.next-ride-label {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-weight: 700;
  color: var(--pink);
  white-space: nowrap;
}
.next-ride-body { display: flex; flex-direction: column; flex: 1; transition: opacity 0.3s ease; }
.next-ride-body.swap { opacity: 0; }
.next-ride-name { font-size: 1.02rem; }
.next-ride-meta { font-size: 0.85rem; color: var(--ink-2); }
.next-ride-spots {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--bg);
  background: var(--ok);
  padding: 0.3rem 0.6rem;
  border-radius: 999px;
  white-space: nowrap;
}

/* ===== SECTIONS ===== */
.section {
  position: relative;
  z-index: 1;
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(3.5rem, 8vw, 6rem) clamp(1rem, 4vw, 3rem);
}
.section--tight { padding-top: clamp(2rem, 5vw, 3rem); }
.section-head { max-width: 640px; margin: 0 auto clamp(2.2rem, 5vw, 3.4rem); text-align: center; }
.section-title {
  font-family: "Anton", "Inter", sans-serif;
  font-weight: 400;
  font-size: clamp(2rem, 6vw, 3.4rem);
  text-transform: uppercase;
  letter-spacing: 0.01em;
  margin-bottom: 0.7rem;
}
.section-sub { color: var(--ink-2); font-size: 1.02rem; margin: 0; }

/* ===== CLASS CARDS ===== */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 1.2rem;
}
.card {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 1.6rem 1.5rem;
  overflow: hidden;
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}
.card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(160deg, var(--card-tint, rgba(255, 47, 176, 0.14)), transparent 55%);
  opacity: 0.9;
  pointer-events: none;
}
.card--ride { --card-tint: rgba(255, 47, 176, 0.18); }
.card--rhythm { --card-tint: rgba(139, 92, 246, 0.18); }
.card--hiit { --card-tint: rgba(34, 211, 238, 0.16); }
.card:hover {
  transform: translateY(-6px);
  border-color: var(--line-2);
  box-shadow: var(--shadow), var(--shadow-glow);
}
.card > * { position: relative; }
.card-badge {
  display: inline-block;
  font-size: 0.68rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: #190826;
  background: var(--pink);
  padding: 0.28rem 0.6rem;
  border-radius: 999px;
  margin-bottom: 1rem;
}
.card-badge--alt { background: var(--violet); color: var(--ink); }
.card-name {
  font-family: "Anton", "Inter", sans-serif;
  font-weight: 400;
  font-size: 2rem;
  text-transform: uppercase;
}
.card-tag {
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.74rem;
  font-weight: 700;
  color: var(--muted);
  margin: 0.2rem 0 0.9rem;
}
.card-desc { color: var(--ink-2); margin: 0 0 1.1rem; font-size: 0.96rem; }
.card-meta {
  list-style: none;
  margin: 0 0 1.4rem;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  font-size: 0.9rem;
  color: var(--ink);
}
.card-btn { width: 100%; }

/* ===== CREW ===== */
.crew-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 1.1rem;
}
.crew {
  text-align: center;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 1.6rem 1.1rem;
  transition: transform 0.2s ease, border-color 0.2s ease;
}
.crew:hover { transform: translateY(-5px); border-color: var(--line-2); }
.crew-photo {
  width: 84px; height: 84px;
  margin: 0 auto 1rem;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: "Anton", "Inter", sans-serif;
  font-size: 1.6rem;
  color: var(--ink);
  background: linear-gradient(135deg, var(--c1), var(--c2));
  box-shadow: 0 0 26px -6px var(--c1);
}
.crew h3 { font-size: 1.1rem; }
.crew-role {
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--pink);
  margin: 0.3rem 0 0.5rem;
}
.crew-note { color: var(--ink-2); font-size: 0.88rem; margin: 0; }

/* ===== EXPERIENCE ===== */
.experience { position: relative; overflow: hidden; }
.exp-glow {
  position: absolute;
  width: 540px; height: 540px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(139, 92, 246, 0.35), transparent 65%);
  filter: blur(100px);
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  z-index: -1;
  pointer-events: none;
}
.exp-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 1.1rem;
}
.exp-item {
  background: rgba(30, 16, 54, 0.6);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 1.5rem;
  backdrop-filter: blur(6px);
  transition: transform 0.2s ease, border-color 0.2s ease;
}
.exp-item:hover { transform: translateY(-5px); border-color: var(--pink); }
.exp-icon {
  font-size: 1.8rem;
  width: 52px; height: 52px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: linear-gradient(135deg, rgba(255, 47, 176, 0.18), rgba(139, 92, 246, 0.18));
  margin-bottom: 1rem;
}
.exp-item h3 { font-size: 1.15rem; margin-bottom: 0.4rem; }
.exp-item p { color: var(--ink-2); font-size: 0.92rem; margin: 0; }

/* ===== PACKS ===== */
.packs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.2rem;
  align-items: stretch;
}
.pack {
  position: relative;
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 1.8rem 1.6rem;
  transition: transform 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease;
}
.pack:hover { transform: translateY(-5px); border-color: var(--line-2); }
.pack--featured {
  border-color: var(--pink);
  background: linear-gradient(165deg, rgba(255, 47, 176, 0.12), var(--surface) 60%);
  box-shadow: var(--shadow-glow);
}
.pack-flag {
  position: absolute;
  top: -0.7rem; left: 50%;
  transform: translateX(-50%);
  font-size: 0.66rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: #190826;
  background: var(--pink);
  padding: 0.3rem 0.8rem;
  border-radius: 999px;
}
.pack-name {
  font-family: "Anton", "Inter", sans-serif;
  font-weight: 400;
  font-size: 1.5rem;
  text-transform: uppercase;
  margin-bottom: 0.6rem;
}
.pack-price {
  font-family: "Anton", "Inter", sans-serif;
  font-size: 2.8rem;
  margin: 0 0 1.2rem;
  display: flex;
  align-items: baseline;
  gap: 0.1rem;
}
.pack-cur { font-size: 1.3rem; color: var(--pink); }
.pack-per { font-size: 0.85rem; font-family: "Inter", sans-serif; color: var(--muted); margin-left: 0.3rem; }
.pack-list {
  list-style: none;
  margin: 0 0 1.6rem;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  flex: 1;
  font-size: 0.94rem;
  color: var(--ink-2);
}
.pack-list li { position: relative; padding-left: 1.5rem; }
.pack-list li::before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--pink);
  font-weight: 800;
}
.pack-btn { width: 100%; }

/* ===== QUOTES ===== */
.quotes {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.2rem;
}
.quote {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 1.6rem;
  margin: 0;
  transition: transform 0.2s ease, border-color 0.2s ease;
}
.quote:hover { transform: translateY(-4px); border-color: var(--violet); }
.quote blockquote {
  margin: 0 0 1rem;
  font-size: 1.02rem;
  color: var(--ink);
  position: relative;
  padding-top: 1.4rem;
}
.quote blockquote::before {
  content: "“";
  position: absolute;
  top: -0.5rem; left: -0.2rem;
  font-family: "Anton", sans-serif;
  font-size: 3rem;
  color: var(--pink);
  opacity: 0.5;
}
.quote figcaption { font-size: 0.88rem; color: var(--muted); }
.quote figcaption strong { color: var(--ink); }

/* ===== CTA ===== */
.cta {
  position: relative;
  z-index: 1;
  overflow: hidden;
  margin: clamp(2rem, 6vw, 4rem) clamp(1rem, 4vw, 3rem) 0;
  border-radius: var(--r-lg);
  max-width: 1180px;
  margin-inline: auto;
  background: linear-gradient(150deg, rgba(255, 47, 176, 0.16), rgba(139, 92, 246, 0.14));
  border: 1px solid var(--line);
}
.cta-glow {
  position: absolute;
  width: 600px; height: 600px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 47, 176, 0.4), transparent 65%);
  filter: blur(90px);
  top: -200px; right: -120px;
  z-index: -1;
}
.cta-inner {
  text-align: center;
  max-width: 580px;
  margin: 0 auto;
  padding: clamp(2.6rem, 7vw, 4.5rem) clamp(1.2rem, 4vw, 2rem);
}
.cta-title {
  font-family: "Anton", "Inter", sans-serif;
  font-weight: 400;
  font-size: clamp(2.2rem, 7vw, 4rem);
  text-transform: uppercase;
  margin-bottom: 0.7rem;
}
.cta-sub { color: var(--ink-2); margin: 0 0 1.8rem; }
.cta-form {
  display: flex;
  gap: 0.6rem;
  max-width: 460px;
  margin: 0 auto 1rem;
}
.cta-form input {
  flex: 1;
  font: inherit;
  padding: 0.9rem 1rem;
  border-radius: 999px;
  border: 1px solid var(--line-2);
  background: rgba(0, 0, 0, 0.25);
  color: var(--ink);
}
.cta-form input::placeholder { color: var(--muted); }
.cta-form input:focus-visible {
  outline: none;
  border-color: var(--pink);
  box-shadow: 0 0 0 3px var(--glow);
}
.cta-form input.invalid {
  border-color: var(--pink);
  animation: shake 0.32s ease;
}
@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-6px); }
  75% { transform: translateX(6px); }
}
.cta-fine { font-size: 0.8rem; color: var(--muted); margin: 0; }

/* ===== FOOTER ===== */
.footer {
  position: relative;
  z-index: 1;
  text-align: center;
  padding: clamp(2.5rem, 6vw, 4rem) 1rem 3rem;
  color: var(--ink-2);
  font-size: 0.9rem;
}
.footer-brand {
  font-family: "Anton", "Inter", sans-serif;
  font-size: 1.3rem;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.6rem;
}
.footer p { margin: 0.2rem 0; }
.footer-fine { color: var(--muted); font-size: 0.8rem; margin-top: 0.8rem; }

/* ===== TOAST ===== */
.toast {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translate(-50%, 130%);
  background: var(--elevated);
  color: var(--ink);
  border: 1px solid var(--pink);
  border-radius: var(--r-md);
  padding: 0.85rem 1.3rem;
  font-weight: 600;
  font-size: 0.94rem;
  box-shadow: var(--shadow), 0 0 26px -10px var(--glow);
  z-index: 100;
  transition: transform 0.35s cubic-bezier(0.2, 0.9, 0.3, 1.2);
  pointer-events: none;
  max-width: calc(100vw - 32px);
}
.toast.show { transform: translate(-50%, 0); }

/* ===== REVEAL ===== */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.reveal.in { opacity: 1; transform: none; }

/* ===== RESPONSIVE ===== */
@media (max-width: 880px) {
  .nav-links, .nav-cta { display: none; }
  .nav-toggle { display: flex; }
}

@media (max-width: 520px) {
  .hero-stats { gap: 1.2rem; flex-wrap: wrap; }
  .hero-actions .btn { flex: 1; }
  .next-ride { flex-wrap: wrap; }
  .next-ride-spots { order: 3; }
  .cta-form { flex-direction: column; }
  .cta-form .btn { width: 100%; }
  .card, .pack { padding: 1.4rem 1.2rem; }
  .section-head { text-align: left; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
  .reveal { opacity: 1; transform: none; }
}

