(function () {
  "use strict";

  /* ---------- Toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2800);
  }

  /* ---------- Sticky nav shadow ---------- */
  var nav = document.getElementById("nav");
  function onScroll() {
    if (!nav) return;
    nav.classList.toggle("scrolled", window.scrollY > 20);
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  /* ---------- Mobile menu ---------- */
  var toggle = document.getElementById("navToggle");
  var menu = document.getElementById("mobileMenu");
  function closeMenu() {
    if (!menu || !toggle) return;
    menu.hidden = true;
    toggle.setAttribute("aria-expanded", "false");
  }
  if (toggle && menu) {
    toggle.addEventListener("click", function () {
      var open = toggle.getAttribute("aria-expanded") === "true";
      toggle.setAttribute("aria-expanded", String(!open));
      menu.hidden = open;
    });
    menu.querySelectorAll("a").forEach(function (a) {
      a.addEventListener("click", closeMenu);
    });
  }
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") closeMenu();
  });

  /* ---------- Smooth-scroll for in-page anchors ---------- */
  document.querySelectorAll('a[href^="#"]').forEach(function (link) {
    link.addEventListener("click", function (e) {
      var id = link.getAttribute("href");
      if (id === "#" || id.length < 2) return;
      var target = document.querySelector(id);
      if (!target) return;
      e.preventDefault();
      target.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });

  /* ---------- Reveal on scroll ---------- */
  var reveals = document.querySelectorAll(".reveal");
  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -8% 0px" }
    );
    reveals.forEach(function (el) {
      io.observe(el);
    });
  } else {
    reveals.forEach(function (el) {
      el.classList.add("in");
    });
  }

  /* ---------- Class-time rotator ---------- */
  var rides = [
    { name: "Ride45 · Neon Hour", meta: "6:30 PM · Studio A · with Mara V.", spots: 7 },
    { name: "Rhythm · Sunset Set", meta: "7:15 PM · Studio B · with Deon K.", spots: 12 },
    { name: "HIIT Sculpt · Burn", meta: "8:00 PM · Floor 2 · with Sasha L.", spots: 4 },
    { name: "Ride45 · Bass Drop", meta: "8:45 PM · Studio A · with Rio O.", spots: 9 },
  ];
  var rideName = document.getElementById("rideName");
  var rideMeta = document.getElementById("rideMeta");
  var rideSpots = document.getElementById("rideSpots");
  var rideBody = rideName ? rideName.closest(".next-ride-body") : null;
  var ri = 0;

  function spotColor(n) {
    if (n <= 4) return "var(--danger, #f87171)";
    if (n <= 8) return "var(--warn, #fbbf24)";
    return "var(--ok, #34d399)";
  }

  function renderRide() {
    var r = rides[ri];
    if (rideName) rideName.textContent = r.name;
    if (rideMeta) rideMeta.textContent = r.meta;
    if (rideSpots) {
      rideSpots.textContent = r.spots + " bikes left";
      rideSpots.style.background = spotColor(r.spots);
    }
  }
  renderRide();

  if (rideBody) {
    setInterval(function () {
      rideBody.classList.add("swap");
      setTimeout(function () {
        ri = (ri + 1) % rides.length;
        renderRide();
        rideBody.classList.remove("swap");
      }, 320);
    }, 3600);
  }

  /* ---------- Book buttons ---------- */
  document.querySelectorAll(".card-btn, .pack-btn").forEach(function (btn) {
    btn.addEventListener("click", function (e) {
      e.preventDefault();
      var card = btn.closest(".card, .pack");
      var label = card ? card.querySelector(".card-name, .pack-name") : null;
      toast(label ? "🎟️ " + label.textContent.trim() + " added — see you on the floor!" : "Added!");
    });
  });

  /* ---------- Claim form ---------- */
  var form = document.getElementById("claimForm");
  if (form) {
    var input = document.getElementById("email");
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var val = (input.value || "").trim();
      var ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val);
      if (!ok) {
        input.classList.add("invalid");
        input.focus();
        toast("Enter a valid email to claim your ride.");
        setTimeout(function () {
          input.classList.remove("invalid");
        }, 500);
        return;
      }
      input.value = "";
      toast("🔥 Free ride locked in — check your inbox for the code!");
    });
  }
})();

snippets.css:
:root {
  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;
  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;
  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;
  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);
  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;
  --shadow-sm: 0 1px 2px rgba(28, 24, 20, 0.05), 0 4px 14px rgba(28, 24, 20, 0.05);
  --shadow-md: 0 18px 48px -18px rgba(28, 24, 20, 0.32);
  --shadow-card: 0 28px 60px -24px rgba(60, 44, 22, 0.55);
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--sans);
  line-height: 1.5;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1,
h2,
h3 {
  font-family: var(--serif);
  font-weight: 600;
  line-height: 1.1;
  margin: 0;
}

button {
  font-family: inherit;
  cursor: pointer;
}

input,
textarea {
  font-family: inherit;
}

.gc {
  max-width: 980px;
  margin: 0 auto;
  padding: clamp(28px, 5vw, 64px) clamp(18px, 4vw, 40px) 72px;
}

/* ---------- header ---------- */
.gc-head {
  text-align: center;
  max-width: 560px;
  margin: 0 auto clamp(28px, 4vw, 44px);
}

.kicker {
  margin: 0 0 14px;
  font-size: 0.72rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--gold-d);
  font-weight: 600;
}

.gc-head h1 {
  font-size: clamp(2.6rem, 7vw, 4rem);
  font-weight: 600;
  letter-spacing: -0.01em;
}

.lede {
  margin: 16px auto 0;
  color: var(--ink-2);
  font-size: 1.02rem;
  max-width: 44ch;
}

/* ---------- tabs ---------- */
.tabs {
  position: relative;
  display: flex;
  gap: 4px;
  width: max-content;
  max-width: 100%;
  margin: 0 auto clamp(26px, 4vw, 40px);
  padding: 5px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  box-shadow: var(--shadow-sm);
}

.tab {
  position: relative;
  z-index: 1;
  border: 0;
  background: transparent;
  padding: 11px 28px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--muted);
  transition: color 0.25s ease;
}

.tab.is-active {
  color: var(--ink);
}

.tab:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.tab-ink {
  position: absolute;
  z-index: 0;
  top: 5px;
  bottom: 5px;
  left: 5px;
  width: calc(50% - 5px);
  border-radius: 999px;
  background: linear-gradient(135deg, var(--gold-soft), var(--rose-soft));
  border: 1px solid var(--gold-soft);
  box-shadow: 0 2px 8px rgba(176, 141, 87, 0.25);
  transition: transform 0.32s cubic-bezier(0.65, 0, 0.35, 1);
}

.tabs[data-active="redeem"] .tab-ink {
  transform: translateX(100%);
}

/* ---------- layout ---------- */
.grid {
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  gap: clamp(22px, 3.5vw, 40px);
  align-items: start;
}

.panel {
  display: none;
}

.panel.is-active {
  display: block;
  animation: fade 0.4s ease both;
}

@keyframes fade {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

/* ---------- preview card ---------- */
.preview {
  position: sticky;
  top: 28px;
}

.preview-label,
.preview-note {
  font-size: 0.74rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
  margin: 0 0 14px;
}

.preview-note {
  text-transform: none;
  letter-spacing: 0;
  font-weight: 400;
  font-size: 0.82rem;
  line-height: 1.55;
  color: var(--muted);
  margin: 18px 2px 0;
}

.card {
  position: relative;
  overflow: hidden;
  aspect-ratio: 1.62 / 1;
  padding: clamp(20px, 3.5vw, 28px);
  border-radius: var(--r-lg);
  color: #fff8ee;
  background:
    radial-gradient(120% 140% at 0% 0%, #4a3a28 0%, transparent 55%),
    linear-gradient(135deg, #2a221a 0%, #3d2f20 42%, #6b5235 100%);
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  isolation: isolate;
}

.card::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  border: 1px solid rgba(239, 226, 207, 0.35);
  pointer-events: none;
}

.card-sheen {
  position: absolute;
  inset: -40% -10%;
  z-index: -1;
  background: linear-gradient(
    115deg,
    transparent 35%,
    rgba(239, 226, 207, 0.22) 48%,
    rgba(255, 248, 238, 0.45) 51%,
    rgba(239, 226, 207, 0.22) 54%,
    transparent 67%
  );
  transform: translateX(-30%);
  animation: sheen 6.5s ease-in-out infinite;
}

@keyframes sheen {
  0%,
  62%,
  100% {
    transform: translateX(-60%);
  }
  78% {
    transform: translateX(60%);
  }
}

.card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-brand {
  font-family: var(--serif);
  font-size: 1.28rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--gold-soft);
}

.card-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid rgba(239, 226, 207, 0.5);
  font-family: var(--serif);
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--gold-soft);
}

.card-kicker {
  margin: auto 0 2px;
  font-size: 0.66rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: rgba(239, 226, 207, 0.72);
}

.card-amount {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(2.6rem, 7vw, 3.4rem);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.01em;
  transition: transform 0.18s ease;
}

.card-amount.bump {
  transform: scale(1.06);
}

.card-foot {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  margin-top: 16px;
}

.card-meta {
  display: block;
  font-size: 0.62rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(239, 226, 207, 0.6);
  margin-bottom: 3px;
}

.card-foot strong {
  font-weight: 500;
  font-size: 0.92rem;
}

.card-from {
  text-align: right;
}

.card-message {
  margin: 12px 0 0;
  font-family: var(--serif);
  font-style: italic;
  font-size: 0.98rem;
  line-height: 1.35;
  color: rgba(255, 248, 238, 0.88);
  min-height: 1.3em;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

/* ---------- fields ---------- */
form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: 0;
  padding: 0;
  margin: 0;
  min-width: 0;
}

.field legend,
.lbl {
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: var(--ink-2);
  padding: 0;
}

.lbl em {
  font-style: normal;
  font-weight: 400;
  color: var(--muted);
  text-transform: none;
  letter-spacing: 0;
  margin-left: 4px;
}

.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

input[type="text"],
input[type="email"],
input[type="number"],
input[type="date"],
textarea {
  width: 100%;
  padding: 12px 14px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  background: var(--white);
  color: var(--ink);
  font-size: 0.92rem;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

input::placeholder,
textarea::placeholder {
  color: var(--muted);
}

input:focus,
textarea:focus {
  outline: none;
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.16);
}

textarea {
  resize: vertical;
  min-height: 72px;
}

.counter {
  font-size: 0.74rem;
  color: var(--muted);
  align-self: flex-end;
}

.hint {
  margin: 0;
  font-size: 0.76rem;
  color: var(--muted);
}

/* ---------- amounts ---------- */
.amounts {
  display: grid;
  grid-template-columns: repeat(2, 1fr) 1.3fr;
  gap: 10px;
}

.amount {
  border: 1px solid var(--line-2);
  background: var(--white);
  border-radius: var(--r-sm);
  padding: 13px 8px;
  font-size: 0.98rem;
  font-weight: 600;
  color: var(--ink-2);
  transition: all 0.2s ease;
}

.amount:hover {
  border-color: var(--gold);
  color: var(--ink);
}

.amount.is-active {
  border-color: var(--gold);
  background: linear-gradient(135deg, var(--gold-soft), var(--rose-soft));
  color: var(--gold-d);
  box-shadow: 0 4px 14px -6px rgba(176, 141, 87, 0.5);
}

.amount:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.amount-custom {
  grid-column: 3;
  grid-row: 1 / span 2;
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 0 12px;
  cursor: text;
}

.amount-custom .cur {
  color: var(--muted);
  font-weight: 600;
}

.amount-custom input {
  border: 0;
  padding: 0;
  background: transparent;
  box-shadow: none;
  font-weight: 600;
  font-size: 0.98rem;
}

.amount-custom input:focus {
  box-shadow: none;
}

.amount-custom:focus-within {
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.16);
}

/* ---------- summary ---------- */
.summary {
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 18px;
  background: var(--cream);
}

.summary-line {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 0.88rem;
  color: var(--ink-2);
  padding: 5px 0;
}

.summary-line strong {
  font-weight: 600;
}

.summary-total {
  margin-top: 6px;
  padding-top: 12px;
  border-top: 1px solid var(--line-2);
  font-size: 1rem;
}

.summary-total strong {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--gold-d);
}

/* ---------- buttons ---------- */
.actions {
  display: flex;
  gap: 12px;
}

.btn {
  flex: 1;
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 14px 20px;
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  transition: transform 0.15s ease, box-shadow 0.25s ease, background 0.25s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.btn-primary {
  background: linear-gradient(135deg, var(--gold) 0%, var(--gold-d) 100%);
  color: #fff8ee;
  box-shadow: 0 12px 26px -12px rgba(140, 109, 63, 0.7);
}

.btn-primary:hover {
  box-shadow: 0 16px 32px -12px rgba(140, 109, 63, 0.85);
}

.btn-ghost {
  background: var(--white);
  border-color: var(--line-2);
  color: var(--ink);
}

.btn-ghost:hover {
  border-color: var(--gold);
  color: var(--gold-d);
}

.btn-block {
  width: 100%;
  flex: none;
}

/* ---------- redeem ---------- */
.code-input {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-weight: 600;
  text-align: center;
  font-size: 1.04rem;
}

.seed {
  border: 0;
  background: none;
  padding: 0;
  color: var(--gold-d);
  font-weight: 600;
  font-size: inherit;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.code-msg {
  margin: -8px 0 0;
  font-size: 0.82rem;
  min-height: 1.2em;
  font-weight: 500;
}

.code-msg.is-error {
  color: var(--danger);
}

.code-msg.is-ok {
  color: var(--ok);
}

.code-input.shake {
  animation: shake 0.4s ease;
  border-color: var(--danger);
}

@keyframes shake {
  10%,
  90% {
    transform: translateX(-2px);
  }
  20%,
  80% {
    transform: translateX(4px);
  }
  30%,
  50%,
  70% {
    transform: translateX(-7px);
  }
  40%,
  60% {
    transform: translateX(7px);
  }
}

.balance {
  margin-top: 4px;
  border: 1px solid var(--gold-soft);
  border-radius: var(--r-lg);
  padding: 26px 24px;
  background:
    radial-gradient(120% 130% at 100% 0%, var(--rose-soft) 0%, transparent 60%),
    var(--cream);
  text-align: center;
  animation: reveal 0.6s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes reveal {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.97);
  }
}

.balance-kicker {
  margin: 0;
  font-size: 0.7rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold-d);
  font-weight: 600;
}

.balance-amount {
  margin: 6px 0 18px;
  font-family: var(--serif);
  font-size: clamp(3rem, 9vw, 4rem);
  font-weight: 600;
  line-height: 1;
  color: var(--ink);
  letter-spacing: -0.01em;
}

.balance-meta {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin: 0 0 20px;
  padding: 16px 0 0;
  border-top: 1px solid var(--line);
}

.balance-meta div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.balance-meta dt {
  font-size: 0.64rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}

.balance-meta dd {
  margin: 0;
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--ink);
}

.pill {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 0.74rem;
  font-weight: 600;
  background: rgba(95, 138, 107, 0.14);
  color: var(--ok);
}

.pill.is-low {
  background: rgba(192, 138, 62, 0.16);
  color: var(--warn);
}

/* ---------- toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 140%);
  z-index: 60;
  max-width: 90vw;
  padding: 13px 22px;
  border-radius: 999px;
  background: var(--ink);
  color: var(--cream);
  font-size: 0.88rem;
  font-weight: 500;
  box-shadow: var(--shadow-md);
  opacity: 0;
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.3s ease;
  pointer-events: none;
}

.toast.show {
  transform: translate(-50%, 0);
  opacity: 1;
}

/* ---------- responsive ---------- */
@media (max-width: 820px) {
  .grid {
    grid-template-columns: 1fr;
  }
  .preview {
    position: static;
    max-width: 420px;
    margin: 0 auto;
  }
}

@media (max-width: 520px) {
  .gc {
    padding: 26px 16px 64px;
  }
  .tabs {
    width: 100%;
  }
  .tab {
    flex: 1;
    padding: 11px 12px;
  }
  .row {
    grid-template-columns: 1fr;
  }
  .amounts {
    grid-template-columns: 1fr 1fr;
  }
  .amount-custom {
    grid-column: 1 / -1;
    grid-row: auto;
    padding: 12px;
  }
  .actions {
    flex-direction: column;
  }
  .balance-meta {
    grid-template-columns: 1fr;
    text-align: left;
  }
  .balance-meta div {
    flex-direction: row;
    justify-content: space-between;
    align-items: baseline;
  }
}

@media (prefers-reduced-motion: reduce) {
  .card-sheen,
  .card-amount,
  .panel.is-active,
  .balance {
    animation: none !important;
    transition: none !important;
  }
}

