(function () {
  "use strict";

  /* ---------- toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2600);
  }

  function money(n) {
    return "$" + Number(n).toLocaleString("en-US");
  }

  /* ============================================================
     TABS
  ============================================================ */
  var tabs = document.getElementById("tabs");
  var tabButtons = Array.prototype.slice.call(tabs.querySelectorAll(".tab"));
  var panels = {
    buy: document.getElementById("panel-buy"),
    redeem: document.getElementById("panel-redeem"),
  };

  function activateTab(name) {
    tabs.setAttribute("data-active", name);
    tabButtons.forEach(function (btn) {
      var on = btn.dataset.tab === name;
      btn.classList.toggle("is-active", on);
      btn.setAttribute("aria-selected", on ? "true" : "false");
      btn.tabIndex = on ? 0 : -1;
    });
    Object.keys(panels).forEach(function (key) {
      var p = panels[key];
      var on = key === name;
      p.classList.toggle("is-active", on);
      p.hidden = !on;
    });
  }

  tabButtons.forEach(function (btn, i) {
    btn.addEventListener("click", function () {
      activateTab(btn.dataset.tab);
    });
    btn.addEventListener("keydown", function (e) {
      if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
      e.preventDefault();
      var dir = e.key === "ArrowRight" ? 1 : -1;
      var next = (i + dir + tabButtons.length) % tabButtons.length;
      tabButtons[next].focus();
      activateTab(tabButtons[next].dataset.tab);
    });
  });

  /* ============================================================
     BUY — live preview + summary
  ============================================================ */
  var state = { amount: 75 };

  var cardAmount = document.getElementById("cardAmount");
  var cardTo = document.getElementById("cardTo");
  var cardMessage = document.getElementById("cardMessage");
  var cardExpiry = document.getElementById("cardExpiry");
  var sumValue = document.getElementById("sumValue");
  var sumTotal = document.getElementById("sumTotal");

  var amountsWrap = document.getElementById("amounts");
  var presetBtns = Array.prototype.slice.call(
    amountsWrap.querySelectorAll(".amount[data-amount]")
  );
  var customInput = document.getElementById("customAmount");
  var amountHint = document.getElementById("amountHint");

  var recipient = document.getElementById("recipient");
  var deliveryDate = document.getElementById("deliveryDate");
  var message = document.getElementById("message");
  var msgCount = document.getElementById("msgCount");
  var email = document.getElementById("email");

  function bumpCard() {
    cardAmount.classList.remove("bump");
    void cardAmount.offsetWidth;
    cardAmount.classList.add("bump");
  }

  function renderAmount() {
    var valid = state.amount >= 25 && state.amount <= 2000;
    cardAmount.textContent = money(state.amount || 0);
    sumValue.textContent = money(valid ? state.amount : 0);
    sumTotal.textContent = money(valid ? state.amount : 0);
    bumpCard();
  }

  presetBtns.forEach(function (btn) {
    btn.addEventListener("click", function () {
      presetBtns.forEach(function (b) {
        b.classList.remove("is-active");
        b.setAttribute("aria-checked", "false");
      });
      btn.classList.add("is-active");
      btn.setAttribute("aria-checked", "true");
      customInput.value = "";
      state.amount = Number(btn.dataset.amount);
      amountHint.textContent = "Between $25 and $2,000.";
      renderAmount();
    });
  });

  customInput.addEventListener("input", function () {
    var v = Number(customInput.value);
    presetBtns.forEach(function (b) {
      b.classList.remove("is-active");
      b.setAttribute("aria-checked", "false");
    });
    if (!customInput.value) {
      state.amount = 0;
      amountHint.textContent = "Between $25 and $2,000.";
    } else if (v < 25 || v > 2000) {
      state.amount = 0;
      amountHint.textContent = "Please enter an amount between $25 and $2,000.";
    } else {
      state.amount = v;
      amountHint.textContent = "Lovely — " + money(v) + " gift card.";
    }
    renderAmount();
  });

  recipient.addEventListener("input", function () {
    var name = recipient.value.trim();
    cardTo.textContent = name || "A dear friend";
  });

  message.addEventListener("input", function () {
    var txt = message.value.trim();
    msgCount.textContent = String(message.value.length);
    cardMessage.textContent =
      txt || "Wishing you an afternoon of pure indulgence.";
  });

  // delivery date — default to today, set on the card as "valid until +1 year"
  function fmtDate(d) {
    return d.toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    });
  }
  (function initDate() {
    var today = new Date();
    var iso = today.toISOString().slice(0, 10);
    deliveryDate.min = iso;
    deliveryDate.value = iso;
  })();

  function renderExpiry() {
    var base = deliveryDate.value ? new Date(deliveryDate.value) : new Date();
    var exp = new Date(base.getFullYear() + 2, base.getMonth(), base.getDate());
    cardExpiry.textContent = fmtDate(exp);
  }
  deliveryDate.addEventListener("change", renderExpiry);

  // initial paint
  renderAmount();
  renderExpiry();

  /* ---------- buy actions ---------- */
  function validateBuy() {
    if (!state.amount || state.amount < 25 || state.amount > 2000) {
      amountHint.textContent = "Choose an amount between $25 and $2,000.";
      amountsWrap.scrollIntoView({ behavior: "smooth", block: "center" });
      return false;
    }
    var em = email.value.trim();
    if (!em || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em)) {
      email.focus();
      toast("Add a valid recipient email to continue.");
      return false;
    }
    return true;
  }

  document.getElementById("addCart").addEventListener("click", function () {
    if (!validateBuy()) return;
    toast(money(state.amount) + " gift card added to cart.");
  });

  document.getElementById("buyForm").addEventListener("submit", function (e) {
    e.preventDefault();
    if (!validateBuy()) return;
    var to = recipient.value.trim() || "your recipient";
    toast(money(state.amount) + " gift card on its way to " + to + ".");
  });

  /* ============================================================
     REDEEM
  ============================================================ */
  var DEMO_CARDS = {
    "ML-2026-AURA": {
      balance: 180,
      issued: "Aria Vance",
      used: "May 2, 2026",
      status: "Active",
    },
    "ML-GLOW-7781": {
      balance: 42.5,
      issued: "Noor Haddad",
      used: "Apr 18, 2026",
      status: "Low balance",
    },
    "ML-LUXE-0099": {
      balance: 500,
      issued: "Celeste Moreau",
      used: "Never",
      status: "Active",
    },
  };

  var redeemForm = document.getElementById("redeemForm");
  var codeInput = document.getElementById("code");
  var codeMsg = document.getElementById("codeMsg");
  var balanceBox = document.getElementById("balance");
  var balanceAmount = document.getElementById("balanceAmount");
  var balIssued = document.getElementById("balIssued");
  var balUsed = document.getElementById("balUsed");
  var balStatus = document.getElementById("balStatus");

  document.querySelectorAll(".seed").forEach(function (s) {
    s.addEventListener("click", function () {
      codeInput.value = s.dataset.seed;
      codeInput.focus();
      codeMsg.textContent = "";
      codeMsg.className = "code-msg";
    });
  });

  codeInput.addEventListener("input", function () {
    codeInput.value = codeInput.value.toUpperCase();
  });

  function hideBalance() {
    balanceBox.hidden = true;
    balanceBox.setAttribute("aria-hidden", "true");
  }

  function showError(text) {
    codeMsg.textContent = text;
    codeMsg.className = "code-msg is-error";
    codeInput.classList.remove("shake");
    void codeInput.offsetWidth;
    codeInput.classList.add("shake");
    hideBalance();
  }

  function showBalance(card) {
    codeMsg.textContent = "Card verified.";
    codeMsg.className = "code-msg is-ok";
    balIssued.textContent = card.issued;
    balUsed.textContent = card.used;
    balStatus.textContent = card.status;
    balStatus.className = "pill" + (card.balance < 50 ? " is-low" : "");

    balanceBox.hidden = false;
    balanceBox.setAttribute("aria-hidden", "false");

    // count-up reveal
    var target = card.balance;
    var start = performance.now();
    var dur = 900;
    function tick(now) {
      var t = Math.min(1, (now - start) / dur);
      var eased = 1 - Math.pow(1 - t, 3);
      var val = target * eased;
      balanceAmount.textContent =
        "$" + (target % 1 ? val.toFixed(2) : Math.round(val).toLocaleString("en-US"));
      if (t < 1) requestAnimationFrame(tick);
      else
        balanceAmount.textContent =
          "$" +
          (target % 1
            ? target.toFixed(2)
            : target.toLocaleString("en-US"));
    }
    requestAnimationFrame(tick);
  }

  redeemForm.addEventListener("submit", function (e) {
    e.preventDefault();
    var code = codeInput.value.trim().toUpperCase();
    if (!code) {
      showError("Please enter your gift card code.");
      return;
    }
    if (!/^ML-[A-Z0-9]{3,5}-[A-Z0-9]{3,5}$/.test(code)) {
      showError("That doesn't look like a Maison Lumière code (ML-XXXX-XXXX).");
      return;
    }
    var card = DEMO_CARDS[code];
    if (!card) {
      showError("We couldn't find a card with that code. Please check and retry.");
      return;
    }
    showBalance(card);
    toast("Balance retrieved · " + money(card.balance));
  });

  document.getElementById("applyBalance").addEventListener("click", function () {
    toast("Balance linked to your profile for your next visit.");
  });
})();

snippets.css:
:root {
  --bg: #f6f3ec;
  --surface: #ffffff;
  --surface-2: #fbf9f4;
  --ink: #2e2a24;
  --ink-2: #5b554b;
  --muted: #8c8579;
  --sage: #8a9a7b;
  --sage-d: #6f8061;
  --rose: #c98b86;
  --rose-soft: #f0dedb;
  --line: rgba(46, 42, 36, 0.1);
  --line-2: rgba(46, 42, 36, 0.18);

  --r-sm: 10px;
  --r-md: 18px;
  --r-lg: 28px;
  --r-pill: 999px;

  --shadow-sm: 0 2px 10px rgba(46, 42, 36, 0.05);
  --shadow-md: 0 14px 40px rgba(46, 42, 36, 0.08);
  --shadow-lg: 0 30px 70px rgba(46, 42, 36, 0.12);

  --serif: "Cormorant Garamond", Georgia, "Times New Roman", serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --maxw: 1120px;
  --ease: cubic-bezier(0.22, 0.61, 0.36, 1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

* {
  margin: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--sans);
  background: var(--bg);
  color: var(--ink);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font: inherit;
  cursor: pointer;
}

.wrap {
  width: 100%;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 24px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: -999px;
  top: 0;
  z-index: 200;
  background: var(--ink);
  color: var(--bg);
  padding: 10px 16px;
  border-radius: 0 0 var(--r-sm) 0;
}
.skip-link:focus {
  left: 0;
}

:focus-visible {
  outline: 3px solid var(--sage);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ---------- Typography helpers ---------- */
.eyebrow {
  font-family: var(--sans);
  text-transform: uppercase;
  letter-spacing: 0.22em;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--sage-d);
  margin-bottom: 0.9rem;
}

.section-title {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(1.9rem, 4vw, 3rem);
  line-height: 1.08;
  letter-spacing: -0.01em;
}

.section-sub {
  color: var(--ink-2);
  max-width: 46ch;
  margin: 0.9rem auto 0;
  font-size: 1.02rem;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border: 1px solid transparent;
  border-radius: var(--r-pill);
  padding: 0.7rem 1.4rem;
  font-weight: 600;
  font-size: 0.95rem;
  transition: transform 0.2s var(--ease), background 0.2s var(--ease),
    box-shadow 0.2s var(--ease), border-color 0.2s var(--ease);
}
.btn:hover {
  transform: translateY(-2px);
}
.btn:active {
  transform: translateY(0);
}
.btn-lg {
  padding: 0.95rem 1.9rem;
  font-size: 1.02rem;
}
.btn-block {
  width: 100%;
}

.btn-primary {
  background: var(--sage);
  color: #fff;
  box-shadow: var(--shadow-sm);
}
.btn-primary:hover {
  background: var(--sage-d);
  box-shadow: var(--shadow-md);
}

.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--line-2);
}
.btn-ghost:hover {
  background: var(--surface);
  border-color: var(--ink);
}

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(246, 243, 236, 0.78);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid transparent;
  transition: border-color 0.3s var(--ease), background 0.3s var(--ease);
}
.site-header.scrolled {
  border-bottom-color: var(--line);
  background: rgba(246, 243, 236, 0.92);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 74px;
  gap: 1rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
}
.brand-mark {
  width: 26px;
  height: 26px;
  border-radius: 50% 50% 50% 0;
  background: linear-gradient(135deg, var(--sage), var(--rose));
  transform: rotate(-20deg);
  flex: none;
  box-shadow: var(--shadow-sm);
}
.brand-name {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.nav {
  display: flex;
  gap: 1.8rem;
  font-size: 0.95rem;
  font-weight: 500;
}
.nav a {
  position: relative;
  color: var(--ink-2);
  padding: 0.25rem 0;
  transition: color 0.2s var(--ease);
}
.nav a::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -2px;
  width: 0;
  height: 2px;
  background: var(--sage);
  border-radius: 2px;
  transition: width 0.25s var(--ease);
}
.nav a:hover {
  color: var(--ink);
}
.nav a:hover::after {
  width: 100%;
}

.header-actions {
  display: flex;
  gap: 0.7rem;
  align-items: center;
}

.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: transparent;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 10px;
}
.nav-toggle span {
  width: 22px;
  height: 2px;
  background: var(--ink);
  border-radius: 2px;
  transition: transform 0.25s var(--ease), opacity 0.25s var(--ease);
}
.nav-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.nav-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}
.nav-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ---------- Hero ---------- */
.hero {
  position: relative;
  overflow: hidden;
  padding: clamp(4rem, 9vw, 8rem) 0 clamp(3.5rem, 7vw, 6rem);
  background: radial-gradient(
      120% 90% at 80% -10%,
      var(--rose-soft) 0%,
      transparent 55%
    ),
    radial-gradient(90% 80% at 0% 110%, rgba(138, 154, 123, 0.18) 0%, transparent 55%);
}
.hero-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(50px);
  opacity: 0.6;
  z-index: 0;
  animation: float 13s ease-in-out infinite;
}
.hero-orb--1 {
  width: 320px;
  height: 320px;
  background: rgba(201, 139, 134, 0.4);
  top: -60px;
  right: -40px;
}
.hero-orb--2 {
  width: 260px;
  height: 260px;
  background: rgba(138, 154, 123, 0.4);
  bottom: -80px;
  left: -30px;
  animation-delay: -5s;
}
@keyframes float {
  0%,
  100% {
    transform: translateY(0) translateX(0);
  }
  50% {
    transform: translateY(-26px) translateX(14px);
  }
}

.hero-inner {
  position: relative;
  z-index: 1;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.hero-title {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(2.6rem, 7vw, 5rem);
  line-height: 1.04;
  letter-spacing: -0.015em;
}
.hero-title em {
  font-style: italic;
  color: var(--sage-d);
}
.hero-lede {
  margin-top: 1.3rem;
  max-width: 54ch;
  color: var(--ink-2);
  font-size: clamp(1rem, 2vw, 1.18rem);
}
.hero-cta {
  display: flex;
  gap: 0.9rem;
  margin-top: 2rem;
  flex-wrap: wrap;
  justify-content: center;
}

.hero-stats {
  list-style: none;
  padding: 0;
  margin: 3rem 0 0;
  display: flex;
  gap: clamp(1.5rem, 5vw, 3.5rem);
  flex-wrap: wrap;
  justify-content: center;
}
.hero-stats li {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}
.hero-stats strong {
  font-family: var(--serif);
  font-size: 2rem;
  font-weight: 600;
  color: var(--ink);
}
.hero-stats span {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
}

/* ---------- Sections ---------- */
.section {
  padding: clamp(4rem, 8vw, 7rem) 0;
}
.section--alt {
  background: var(--surface-2);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.section-head {
  text-align: center;
  max-width: 640px;
  margin: 0 auto clamp(2.5rem, 5vw, 3.5rem);
}

/* ---------- Class cards ---------- */
.class-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1.4rem;
}
.class-card {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 2rem 1.7rem 1.8rem;
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s var(--ease), box-shadow 0.3s var(--ease),
    border-color 0.3s var(--ease);
  overflow: hidden;
}
.class-card::before {
  content: "";
  position: absolute;
  inset: 0 auto auto 0;
  width: 100%;
  height: 4px;
  background: linear-gradient(90deg, var(--sage), var(--rose));
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.4s var(--ease);
}
.class-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}
.class-card:hover::before {
  transform: scaleX(1);
}
.class-badge {
  display: inline-block;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 600;
  color: var(--sage-d);
  background: rgba(138, 154, 123, 0.14);
  padding: 0.3rem 0.7rem;
  border-radius: var(--r-pill);
  margin-bottom: 1rem;
}
.class-card h3 {
  font-family: var(--serif);
  font-size: 1.65rem;
  font-weight: 600;
  margin-bottom: 0.6rem;
}
.class-card p {
  color: var(--ink-2);
  font-size: 0.95rem;
}
.class-meta {
  margin-top: 1.1rem;
  font-size: 0.82rem !important;
  color: var(--muted) !important;
  font-weight: 500;
}

/* ---------- Teachers ---------- */
.teacher-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 1.4rem;
}
.teacher {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 1rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 2rem 1.4rem;
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s var(--ease), box-shadow 0.3s var(--ease);
}
.teacher:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
}
.teacher-avatar {
  width: 78px;
  height: 78px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: var(--serif);
  font-size: 1.6rem;
  font-weight: 600;
  color: #fff;
  background: linear-gradient(135deg, var(--sage), var(--sage-d));
  box-shadow: var(--shadow-sm);
}
.teacher:nth-child(2n) .teacher-avatar {
  background: linear-gradient(135deg, var(--rose), #b1726d);
}
.teacher figcaption {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}
.teacher figcaption strong {
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 600;
}
.teacher figcaption span {
  font-size: 0.82rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

/* ---------- Schedule ---------- */
.schedule-list {
  list-style: none;
  padding: 0;
  margin: 0;
  max-width: 760px;
  margin-inline: auto;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}
.schedule-item {
  display: grid;
  grid-template-columns: 56px 64px 1fr auto auto;
  align-items: center;
  gap: 1rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 1rem 1.3rem;
  box-shadow: var(--shadow-sm);
  transition: transform 0.25s var(--ease), box-shadow 0.25s var(--ease);
}
.schedule-item:hover {
  transform: translateX(4px);
  box-shadow: var(--shadow-md);
}
.sch-day {
  font-weight: 700;
  text-transform: uppercase;
  font-size: 0.8rem;
  letter-spacing: 0.08em;
  color: var(--sage-d);
}
.sch-time {
  font-family: var(--serif);
  font-size: 1.3rem;
  font-weight: 600;
}
.sch-class {
  font-weight: 600;
}
.sch-teacher {
  color: var(--muted);
  font-size: 0.9rem;
}
.sch-status {
  font-size: 0.76rem;
  font-weight: 600;
  padding: 0.3rem 0.75rem;
  border-radius: var(--r-pill);
  white-space: nowrap;
}
.sch-status.open {
  color: var(--sage-d);
  background: rgba(138, 154, 123, 0.16);
}
.sch-status.full {
  color: #b1726d;
  background: var(--rose-soft);
}

/* ---------- Pricing ---------- */
.price-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.4rem;
  align-items: stretch;
}
.price-card {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 2.2rem 1.9rem;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s var(--ease), box-shadow 0.3s var(--ease);
}
.price-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
}
.price-card--featured {
  border-color: var(--sage);
  box-shadow: 0 20px 50px rgba(138, 154, 123, 0.22);
  background: linear-gradient(180deg, #fff, #fbfaf6);
}
.price-card--featured:hover {
  box-shadow: 0 30px 70px rgba(138, 154, 123, 0.28);
}
.price-flag {
  position: absolute;
  top: -13px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--sage);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 0.35rem 0.9rem;
  border-radius: var(--r-pill);
  box-shadow: var(--shadow-sm);
}
.price-card h3 {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 600;
}
.price {
  margin: 0.9rem 0 1.4rem;
  display: flex;
  align-items: baseline;
  gap: 0.4rem;
}
.price .amount {
  font-family: var(--serif);
  font-size: 2.7rem;
  font-weight: 600;
  color: var(--ink);
}
.price .per {
  color: var(--muted);
  font-size: 0.95rem;
}
.price-feat {
  list-style: none;
  padding: 0;
  margin: 0 0 1.8rem;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  flex: 1;
}
.price-feat li {
  position: relative;
  padding-left: 1.6rem;
  color: var(--ink-2);
  font-size: 0.95rem;
}
.price-feat li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.45em;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--sage);
}

/* ---------- Testimonial ---------- */
.testimonial {
  background: linear-gradient(
    160deg,
    rgba(138, 154, 123, 0.1),
    rgba(201, 139, 134, 0.1)
  );
}
.testimonial-inner {
  position: relative;
  text-align: center;
  max-width: 760px;
}
.quote-mark {
  font-family: var(--serif);
  font-size: 6rem;
  line-height: 0.6;
  color: var(--sage);
  opacity: 0.4;
  display: block;
  margin-bottom: 0.4rem;
}
.quote {
  margin: 0;
  transition: opacity 0.45s var(--ease), transform 0.45s var(--ease);
}
.quote.fading {
  opacity: 0;
  transform: translateY(8px);
}
.quote-text {
  font-family: var(--serif);
  font-size: clamp(1.4rem, 3.4vw, 2.1rem);
  font-weight: 500;
  font-style: italic;
  line-height: 1.3;
  color: var(--ink);
}
.quote-cite {
  margin-top: 1.6rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}
.quote-name {
  font-weight: 600;
}
.quote-role {
  font-size: 0.85rem;
  color: var(--muted);
}
.quote-dots {
  display: flex;
  gap: 0.55rem;
  justify-content: center;
  margin-top: 2rem;
}
.quote-dots button {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: none;
  background: var(--line-2);
  transition: background 0.25s var(--ease), transform 0.25s var(--ease);
}
.quote-dots button[aria-selected="true"] {
  background: var(--sage);
  transform: scale(1.35);
}

/* ---------- CTA / newsletter ---------- */
.cta-inner {
  text-align: center;
  max-width: 620px;
  margin: 0 auto;
}
.cta-title {
  font-family: var(--serif);
  font-weight: 500;
  font-size: clamp(2rem, 5vw, 3.2rem);
  line-height: 1.08;
}
.cta-sub {
  margin: 1rem auto 0;
  color: var(--ink-2);
  max-width: 48ch;
}
.newsletter {
  margin: 2rem auto 0;
  display: flex;
  gap: 0.6rem;
  max-width: 460px;
}
.newsletter input {
  flex: 1;
  font: inherit;
  padding: 0.85rem 1.1rem;
  border: 1px solid var(--line-2);
  border-radius: var(--r-pill);
  background: var(--surface);
  color: var(--ink);
  transition: border-color 0.2s var(--ease), box-shadow 0.2s var(--ease);
}
.newsletter input::placeholder {
  color: var(--muted);
}
.newsletter input:focus {
  outline: none;
  border-color: var(--sage);
  box-shadow: 0 0 0 4px rgba(138, 154, 123, 0.18);
}
.newsletter input.invalid {
  border-color: var(--rose);
  box-shadow: 0 0 0 4px var(--rose-soft);
}
.newsletter-note {
  margin-top: 0.9rem;
  font-size: 0.8rem;
  color: var(--muted);
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--surface);
  border-top: 1px solid var(--line);
  padding: 3rem 0 2rem;
}
.footer-inner {
  display: flex;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
  align-items: flex-start;
}
.footer-brand {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.footer-brand .brand-mark {
  margin-bottom: 0.2rem;
}
.footer-brand p {
  color: var(--muted);
  font-size: 0.88rem;
  margin-top: 0.3rem;
}
.footer-nav {
  display: flex;
  gap: 1.6rem;
  flex-wrap: wrap;
  font-size: 0.95rem;
}
.footer-nav a {
  color: var(--ink-2);
  transition: color 0.2s var(--ease);
}
.footer-nav a:hover {
  color: var(--ink);
}
.footer-bottom {
  margin-top: 2.2rem;
  padding-top: 1.4rem;
  border-top: 1px solid var(--line);
  color: var(--muted);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 140%);
  background: var(--ink);
  color: var(--bg);
  padding: 0.85rem 1.4rem;
  border-radius: var(--r-pill);
  font-size: 0.92rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  z-index: 300;
  transition: transform 0.4s var(--ease), opacity 0.4s var(--ease);
  opacity: 0;
  pointer-events: none;
  max-width: calc(100% - 40px);
  text-align: center;
}
.toast.show {
  transform: translate(-50%, 0);
  opacity: 1;
}

/* ---------- Reveal ---------- */
.reveal {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 0.7s var(--ease), transform 0.7s var(--ease);
}
.reveal.in {
  opacity: 1;
  transform: none;
}

/* ---------- Responsive ---------- */
@media (max-width: 860px) {
  .nav,
  .header-actions {
    display: none;
  }
  .nav-toggle {
    display: inline-flex;
  }
  .nav.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 74px;
    left: 0;
    right: 0;
    background: var(--surface);
    border-bottom: 1px solid var(--line);
    padding: 1rem 24px 1.4rem;
    gap: 0.4rem;
    box-shadow: var(--shadow-md);
  }
  .nav.open a {
    padding: 0.7rem 0;
    border-bottom: 1px solid var(--line);
  }
}

@media (max-width: 520px) {
  .wrap {
    padding: 0 18px;
  }
  .hero-stats {
    gap: 1.6rem;
  }
  .schedule-item {
    grid-template-columns: 48px 1fr auto;
    grid-template-areas:
      "day class status"
      "time teacher status";
    row-gap: 0.3rem;
  }
  .sch-day {
    grid-area: day;
  }
  .sch-time {
    grid-area: time;
    font-size: 1.05rem;
  }
  .sch-class {
    grid-area: class;
  }
  .sch-teacher {
    grid-area: teacher;
  }
  .sch-status {
    grid-area: status;
    justify-self: end;
  }
  .newsletter {
    flex-direction: column;
  }
  .newsletter .btn {
    width: 100%;
  }
  .footer-inner {
    flex-direction: column;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
  .reveal {
    opacity: 1;
    transform: none;
  }
}

