(function () {
  "use strict";

  /* ---------- Toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2800);
  }

  /* ---------- Sticky header shadow ---------- */
  var header = document.querySelector(".site-header");
  function onScroll() {
    if (!header) return;
    header.classList.toggle("scrolled", window.scrollY > 8);
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  /* ---------- Mobile nav toggle ---------- */
  var navToggle = document.getElementById("navToggle");
  var nav = document.getElementById("nav");
  if (navToggle && nav) {
    navToggle.addEventListener("click", function () {
      var open = nav.classList.toggle("open");
      navToggle.setAttribute("aria-expanded", String(open));
    });
    nav.addEventListener("click", function (e) {
      if (e.target.tagName === "A") {
        nav.classList.remove("open");
        navToggle.setAttribute("aria-expanded", "false");
      }
    });
  }

  /* ---------- Scroll reveal ---------- */
  var reveals = Array.prototype.slice.call(document.querySelectorAll(".reveal"));
  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry, i) {
          if (entry.isIntersecting) {
            var el = entry.target;
            // gentle stagger within the same viewport batch
            setTimeout(function () {
              el.classList.add("in");
            }, Math.min(i * 70, 280));
            io.unobserve(el);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -8% 0px" }
    );
    reveals.forEach(function (el) {
      io.observe(el);
    });
  } else {
    reveals.forEach(function (el) {
      el.classList.add("in");
    });
  }

  /* ---------- Quote rotator ---------- */
  var quoteEl = document.getElementById("quote");
  var dotsEl = document.getElementById("quoteDots");
  if (quoteEl && dotsEl) {
    var quotes = [];
    try {
      quotes = JSON.parse(quoteEl.getAttribute("data-quotes")) || [];
    } catch (e) {
      quotes = [];
    }

    if (quotes.length) {
      var current = 0;
      var autoTimer;
      var textEl = quoteEl.querySelector(".quote-text");
      var nameEl = quoteEl.querySelector(".quote-name");
      var roleEl = quoteEl.querySelector(".quote-role");

      // build dots
      quotes.forEach(function (_, idx) {
        var b = document.createElement("button");
        b.type = "button";
        b.setAttribute("role", "tab");
        b.setAttribute("aria-label", "Testimonial " + (idx + 1));
        b.addEventListener("click", function () {
          show(idx);
          restartAuto();
        });
        dotsEl.appendChild(b);
      });
      var dots = Array.prototype.slice.call(dotsEl.children);

      function render(idx) {
        var q = quotes[idx];
        textEl.textContent = q.text;
        nameEl.textContent = q.name;
        roleEl.textContent = q.role;
        dots.forEach(function (d, i) {
          d.setAttribute("aria-selected", String(i === idx));
        });
      }

      function show(idx) {
        if (idx === current) return;
        current = idx;
        quoteEl.classList.add("fading");
        setTimeout(function () {
          render(current);
          quoteEl.classList.remove("fading");
        }, 300);
      }

      function next() {
        show((current + 1) % quotes.length);
      }

      function startAuto() {
        autoTimer = setInterval(next, 6000);
      }
      function restartAuto() {
        clearInterval(autoTimer);
        startAuto();
      }

      render(0);
      startAuto();

      // pause on hover for accessibility
      quoteEl.addEventListener("mouseenter", function () {
        clearInterval(autoTimer);
      });
      quoteEl.addEventListener("mouseleave", restartAuto);
    }
  }

  /* ---------- Pricing buttons ---------- */
  document.querySelectorAll("[data-plan]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      toast("Nice choice — " + btn.getAttribute("data-plan") + " selected. First class is free!");
    });
  });

  /* ---------- Newsletter ---------- */
  var form = document.getElementById("newsletter");
  if (form) {
    var input = document.getElementById("email");
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var value = (input.value || "").trim();
      var valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
      if (!valid) {
        input.classList.add("invalid");
        input.focus();
        toast("Please enter a valid email address.");
        return;
      }
      input.classList.remove("invalid");
      input.value = "";
      toast("Welcome to the practice — check your inbox to confirm.");
    });
    input.addEventListener("input", function () {
      input.classList.remove("invalid");
    });
  }

  /* ---------- Smooth-scroll active focus for in-page links ---------- */
  document.querySelectorAll('a[href^="#"]').forEach(function (a) {
    a.addEventListener("click", function (e) {
      var id = a.getAttribute("href");
      if (id.length < 2) return;
      var target = document.querySelector(id);
      if (target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: "smooth", block: "start" });
        target.setAttribute("tabindex", "-1");
        target.focus({ preventScroll: true });
      }
    });
  });
})();

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --pending: #6b7280;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

/* ── App bar ── */
.appbar {
  background: var(--white);
  border-bottom: 1px solid var(--line);
  padding: 12px 28px;
  display: flex;
  align-items: center;
  gap: 28px;
  position: sticky;
  top: 0;
  z-index: 20;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--ink);
}
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: linear-gradient(150deg, var(--teal), var(--teal-d));
  color: #fff;
  font-size: 1.1rem;
  font-weight: 700;
}
.brand-name {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.brand-name em {
  font-style: normal;
  color: var(--teal-d);
}
.appbar-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-right: auto;
}
.nav-link {
  text-decoration: none;
  color: var(--ink-2);
  font-size: 0.88rem;
  font-weight: 600;
  padding: 8px 12px;
  border-radius: 9px;
  transition: background 0.15s, color 0.15s;
}
.nav-link:hover {
  background: var(--teal-50);
  color: var(--teal-d);
}
.nav-link.is-active {
  background: var(--teal-50);
  color: var(--teal-d);
}
.appbar-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.icon-btn {
  position: relative;
  width: 40px;
  height: 40px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--white);
  color: var(--ink-2);
  font-size: 1.05rem;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.icon-btn:hover {
  background: var(--teal-50);
  border-color: var(--teal);
}
.icon-btn .dot {
  position: absolute;
  top: 8px;
  right: 9px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--coral);
}
.avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: none;
  background: var(--teal-d);
  color: #fff;
  font-weight: 700;
  font-size: 0.82rem;
  cursor: pointer;
}

/* ── Layout ── */
.board {
  max-width: 1140px;
  margin: 0 auto;
  padding: 26px 28px 56px;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.greeting {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}
.eyebrow {
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--teal-d);
}
.greeting h1 {
  font-size: 1.7rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin: 2px 0;
}
.sub {
  color: var(--muted);
  font-size: 0.95rem;
}
.clock-pill {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 9px 16px;
  font-size: 0.95rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
  box-shadow: var(--shadow-1);
}
.hp-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 3px rgba(47, 158, 111, 0.18);
}

/* ── Stat cards ── */
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
}
.stat {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 18px 18px;
  box-shadow: var(--shadow-1);
}
.stat-accent {
  background: linear-gradient(135deg, var(--teal-d), var(--teal-700));
  border-color: transparent;
  color: #fff;
}
.stat-num {
  font-size: 1.9rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}
.stat-label {
  margin-top: 2px;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--muted);
}
.stat-accent .stat-label {
  color: rgba(255, 255, 255, 0.82);
}

/* ── Columns ── */
.columns {
  display: grid;
  grid-template-columns: 1.45fr 1fr;
  gap: 18px;
  align-items: start;
}
.side {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 18px 20px;
}
.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}
.section-h {
  font-size: 1.02rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.see-all {
  font-size: 0.82rem;
  color: var(--teal-d);
  text-decoration: none;
  font-weight: 600;
}
.see-all:hover {
  text-decoration: underline;
}
.count-tag {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 4px 11px;
}
.badge-count {
  min-width: 24px;
  height: 24px;
  display: inline-grid;
  place-items: center;
  padding: 0 7px;
  border-radius: 999px;
  background: var(--coral);
  color: #fff;
  font-size: 0.78rem;
  font-weight: 700;
}
.badge-count.is-zero {
  background: rgba(47, 158, 111, 0.16);
  color: var(--ok);
}

/* ── Filter chips ── */
.chips {
  display: flex;
  gap: 8px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}
.chip {
  border: 1px solid var(--line);
  background: var(--white);
  color: var(--ink-2);
  border-radius: 999px;
  padding: 6px 14px;
  font: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}
.chip:hover {
  background: var(--teal-50);
  border-color: var(--teal);
}
.chip.is-active {
  background: var(--teal-d);
  border-color: var(--teal-d);
  color: #fff;
}

/* ── Schedule timeline ── */
.timeline {
  list-style: none;
  position: relative;
  display: flex;
  flex-direction: column;
}
.appt {
  position: relative;
  display: flex;
  gap: 14px;
  padding: 14px 0 14px 4px;
  border-bottom: 1px solid var(--line);
}
.appt:last-child {
  border-bottom: none;
}
.appt-time {
  width: 62px;
  flex-shrink: 0;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--teal-d);
  font-variant-numeric: tabular-nums;
  padding-top: 1px;
}
.appt-rail {
  position: relative;
  width: 14px;
  flex-shrink: 0;
}
.appt-dot {
  position: absolute;
  top: 4px;
  left: 3px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--white);
  border: 3px solid var(--pending);
  z-index: 1;
}
.appt-rail::before {
  content: "";
  position: absolute;
  top: 4px;
  bottom: -18px;
  left: 8px;
  width: 2px;
  background: var(--line);
}
.appt:last-child .appt-rail::before {
  display: none;
}
.appt[data-status="waiting"] .appt-dot {
  border-color: var(--warn);
}
.appt[data-status="inroom"] .appt-dot {
  border-color: var(--teal);
  background: var(--teal);
}
.appt[data-status="done"] .appt-dot {
  border-color: var(--ok);
  background: var(--ok);
}
.appt[data-status="noshow"] .appt-dot {
  border-color: var(--danger);
}
.appt-body {
  flex: 1;
  min-width: 0;
}
.appt-name {
  font-weight: 600;
  font-size: 0.94rem;
}
.appt-name span {
  color: var(--muted);
  font-weight: 500;
  font-size: 0.82rem;
}
.appt-reason {
  font-size: 0.82rem;
  color: var(--muted);
  margin-top: 2px;
}
.appt-side {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  flex-shrink: 0;
}
.pill {
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  white-space: nowrap;
}
.pill.waiting {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.pill.inroom {
  background: rgba(18, 156, 147, 0.14);
  color: var(--teal-d);
}
.pill.done {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}
.pill.noshow {
  background: rgba(212, 80, 62, 0.14);
  color: var(--danger);
}
.appt-btn {
  border: 1px solid var(--teal);
  background: var(--white);
  color: var(--teal-d);
  border-radius: 9px;
  padding: 6px 12px;
  font: inherit;
  font-weight: 600;
  font-size: 0.78rem;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s;
}
.appt-btn:hover {
  background: var(--teal-50);
}
.appt-btn.is-final {
  border-color: var(--line);
  background: var(--bg);
  color: var(--muted);
  cursor: default;
}
.empty {
  text-align: center;
  color: var(--muted);
  font-size: 0.88rem;
  padding: 28px 0;
}

/* ── Tasks & alerts ── */
.tasks {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.task {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid var(--line);
}
.task:last-child {
  border-bottom: none;
}
.task-ic {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: var(--teal-50);
  color: var(--teal-d);
  font-size: 0.95rem;
}
.task-ic.flag {
  background: rgba(212, 80, 62, 0.12);
  color: var(--danger);
}
.task-ic.refill {
  background: var(--coral-soft);
  color: var(--coral);
}
.task-body {
  flex: 1;
  min-width: 0;
}
.task-title {
  font-weight: 600;
  font-size: 0.9rem;
}
.task-meta {
  font-size: 0.8rem;
  color: var(--muted);
  margin-top: 2px;
}
.task-done {
  border: 1px solid var(--teal);
  background: var(--white);
  color: var(--teal-d);
  border-radius: 8px;
  padding: 6px 11px;
  font: inherit;
  font-weight: 600;
  font-size: 0.76rem;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s;
}
.task-done:hover {
  background: var(--teal-50);
}
.task.is-done .task-title,
.task.is-done .task-meta {
  text-decoration: line-through;
  color: var(--muted);
}
.task.is-done .task-ic {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}
.task.is-done .task-done {
  border-color: var(--ok);
  background: rgba(47, 158, 111, 0.12);
  color: var(--ok);
  cursor: default;
}

/* ── Messages ── */
.messages {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.msg {
  display: flex;
  gap: 11px;
  padding: 11px 0;
  border-bottom: 1px solid var(--line);
  align-items: center;
}
.msg:last-child {
  border-bottom: none;
}
.msg-avatar {
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  font-weight: 700;
  font-size: 0.76rem;
  background: var(--teal-d);
}
.msg-avatar.c {
  background: var(--coral);
}
.msg-avatar.b {
  background: #4f7cac;
}
.msg-body {
  flex: 1;
  min-width: 0;
}
.msg-from {
  font-weight: 600;
  font-size: 0.88rem;
}
.msg-text {
  font-size: 0.8rem;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.msg-unread {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--coral);
  flex-shrink: 0;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}

@media (max-width: 900px) {
  .stats {
    grid-template-columns: repeat(2, 1fr);
  }
  .columns {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 620px) {
  .appbar-nav {
    display: none;
  }
}

