// ── Toast ──────────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2600);
}

// ── Live clock ───────────────────────────────────────────────────────────────
// Illustrative: starts from a fixed 08:42:00 and ticks via a seconds counter.
const clockEl = document.getElementById("clock");
let elapsed = 8 * 3600 + 42 * 60; // seconds since midnight
function renderClock() {
  const h = Math.floor(elapsed / 3600) % 24;
  const m = Math.floor((elapsed % 3600) / 60);
  const s = elapsed % 60;
  const pad = (n) => String(n).padStart(2, "0");
  clockEl.textContent = `${pad(h)}:${pad(m)}:${pad(s)}`;
  elapsed += 1;
}
renderClock();
setInterval(renderClock, 1000);

// ── Data ─────────────────────────────────────────────────────────────────────
const FLOW = ["waiting", "inroom", "done"];
const PILL = { waiting: "Waiting", inroom: "In room", done: "Completed", noshow: "No-show" };
const NEXT_LABEL = { waiting: "Room in", inroom: "Complete" };

const appointments = [
  {
    id: 1,
    time: "9:00",
    name: "Marcus Reed",
    who: "58 M",
    reason: "Post-MI follow-up",
    status: "done",
  },
  {
    id: 2,
    time: "9:20",
    name: "Priya Anand",
    who: "44 F",
    reason: "Palpitations review",
    status: "inroom",
  },
  {
    id: 3,
    time: "9:40",
    name: "Tom Whitfield",
    who: "67 M",
    reason: "Hypertension check",
    status: "waiting",
  },
  {
    id: 4,
    time: "10:00",
    name: "Grace Lim",
    who: "39 F",
    reason: "Echo results",
    status: "waiting",
  },
  {
    id: 5,
    time: "10:20",
    name: "Daniel Cruz",
    who: "52 M",
    reason: "Chest pain triage",
    status: "waiting",
  },
  {
    id: 6,
    time: "10:40",
    name: "Aisha Bello",
    who: "61 F",
    reason: "Med titration",
    status: "noshow",
  },
];

const tasks = [
  {
    id: "t1",
    kind: "lab",
    title: "Troponin panel — M. Reed",
    meta: "Result ready · review",
    done: false,
  },
  {
    id: "t2",
    kind: "flag",
    title: "Abnormal K+ 5.9 — D. Cruz",
    meta: "Critical flag",
    done: false,
  },
  {
    id: "t3",
    kind: "refill",
    title: "Bisoprolol refill — T. Whitfield",
    meta: "Pharmacy request",
    done: false,
  },
  {
    id: "t4",
    kind: "lab",
    title: "Lipid panel — G. Lim",
    meta: "Result ready · review",
    done: false,
  },
];

const messages = [
  { from: "Sara Nguyen, RN", text: "Room 3 vitals charted for Anand.", cls: "", unread: true },
  { from: "Dr. Ravi Patel", text: "Can you review Cruz's ECG?", cls: "b", unread: true },
  { from: "Front desk", text: "Bello called — running late.", cls: "c", unread: false },
];

// ── KPI sync ─────────────────────────────────────────────────────────────────
const kpi = {
  today: document.getElementById("kpiToday"),
  waiting: document.getElementById("kpiWaiting"),
  done: document.getElementById("kpiDone"),
  msgs: document.getElementById("kpiMsgs"),
};
const schedCount = document.getElementById("schedCount");
function syncKpis() {
  kpi.today.textContent = appointments.length;
  kpi.waiting.textContent = appointments.filter((a) => a.status === "waiting").length;
  kpi.done.textContent = appointments.filter((a) => a.status === "done").length;
  kpi.msgs.textContent = messages.filter((m) => m.unread).length;
  schedCount.textContent = `${appointments.length} visits`;
}

// ── Schedule render ──────────────────────────────────────────────────────────
const timeline = document.getElementById("timeline");
let activeFilter = "all";

function renderSchedule() {
  const visible = appointments.filter((a) => activeFilter === "all" || a.status === activeFilter);
  timeline.innerHTML = visible.length
    ? visible
        .map((a) => {
          const isFinal = a.status === "done" || a.status === "noshow";
          const btn = isFinal
            ? `<button class="appt-btn is-final" disabled>${a.status === "done" ? "Done ✓" : "No-show"}</button>`
            : `<button class="appt-btn" data-id="${a.id}">${NEXT_LABEL[a.status]} →</button>`;
          return `<li class="appt" data-status="${a.status}">
            <span class="appt-time">${a.time}</span>
            <span class="appt-rail"><span class="appt-dot"></span></span>
            <div class="appt-body">
              <p class="appt-name">${a.name} <span>· ${a.who}</span></p>
              <p class="appt-reason">${a.reason}</p>
            </div>
            <div class="appt-side">
              <span class="pill ${a.status}">${PILL[a.status]}</span>
              ${btn}
            </div>
          </li>`;
        })
        .join("")
    : `<p class="empty">No patients in this view.</p>`;
}

timeline.addEventListener("click", (e) => {
  const btn = e.target.closest(".appt-btn[data-id]");
  if (!btn) return;
  const appt = appointments.find((a) => a.id === Number(btn.dataset.id));
  const next = FLOW[FLOW.indexOf(appt.status) + 1];
  if (!next) return;
  appt.status = next;
  syncKpis();
  renderSchedule();
  showToast(`${appt.name} → ${PILL[next]}`);
});

// ── Filter chips ─────────────────────────────────────────────────────────────
document.getElementById("chips").addEventListener("click", (e) => {
  const chip = e.target.closest(".chip");
  if (!chip) return;
  activeFilter = chip.dataset.filter;
  document.querySelectorAll(".chip").forEach((c) => {
    const on = c === chip;
    c.classList.toggle("is-active", on);
    c.setAttribute("aria-selected", String(on));
  });
  renderSchedule();
});

// ── Tasks & alerts ───────────────────────────────────────────────────────────
const ICON = { lab: "⌗", flag: "⚠", refill: "℞" };
const tasksEl = document.getElementById("tasks");
const taskBadge = document.getElementById("taskBadge");

function renderTasks() {
  tasksEl.innerHTML = tasks
    .map(
      (t) => `<li class="task ${t.done ? "is-done" : ""}" data-id="${t.id}">
        <span class="task-ic ${t.kind}">${ICON[t.kind]}</span>
        <div class="task-body">
          <p class="task-title">${t.title}</p>
          <p class="task-meta">${t.meta}</p>
        </div>
        <button class="task-done" ${t.done ? "disabled" : ""}>${t.done ? "Done ✓" : "Done"}</button>
      </li>`
    )
    .join("");
  const open = tasks.filter((t) => !t.done).length;
  taskBadge.textContent = open;
  taskBadge.classList.toggle("is-zero", open === 0);
}

tasksEl.addEventListener("click", (e) => {
  const btn = e.target.closest(".task-done");
  if (!btn) return;
  const li = btn.closest(".task");
  const task = tasks.find((t) => t.id === li.dataset.id);
  if (!task || task.done) return;
  task.done = true;
  renderTasks();
  showToast(`Task cleared: ${task.title}`);
});

// ── Messages ─────────────────────────────────────────────────────────────────
const messagesEl = document.getElementById("messages");
function renderMessages() {
  messagesEl.innerHTML = messages
    .map((m) => {
      const initials = m.from
        .split(" ")
        .slice(0, 2)
        .map((w) => w[0])
        .join("");
      return `<li class="msg">
        <span class="msg-avatar ${m.cls}">${initials}</span>
        <div class="msg-body">
          <p class="msg-from">${m.from}</p>
          <p class="msg-text">${m.text}</p>
        </div>
        ${m.unread ? '<span class="msg-unread"></span>' : ""}
      </li>`;
    })
    .join("");
}

// ── Init ─────────────────────────────────────────────────────────────────────
document.getElementById("todayDate").textContent = "Monday, 8 June";
syncKpis();
renderSchedule();
renderTasks();
renderMessages();

snippets.css:
:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 2px 8px rgba(0, 0, 0, 0.4);
  --shadow-2: 0 18px 50px rgba(0, 0, 0, 0.55);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background:
    radial-gradient(900px 600px at 80% -10%, rgba(198, 255, 58, 0.08), transparent 60%),
    radial-gradient(800px 500px at 0% 110%, rgba(255, 106, 43, 0.08), transparent 55%),
    var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

.wrap {
  max-width: 540px;
  margin: 0 auto;
  padding: 28px 20px 56px;
}

/* ---------- topbar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 26px;
}

.brandmark {
  display: flex;
  align-items: center;
  gap: 9px;
}

.bolt,
.brand__bolt {
  width: 16px;
  height: 16px;
  background: var(--neon);
  clip-path: polygon(45% 0, 100% 0, 55% 45%, 100% 45%, 20% 100%, 45% 55%, 0 55%);
  box-shadow: 0 0 14px var(--neon-50);
}

.brandmark__txt {
  font-weight: 900;
  letter-spacing: 0.14em;
  font-size: 15px;
}

.eyebrow {
  margin: 0;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--muted);
}

/* ---------- stage ---------- */
.stage {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.card-scene {
  width: 100%;
  perspective: 1600px;
}

/* ---------- card ---------- */
.card {
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: 1.586 / 1;
  border: none;
  padding: 0;
  margin: 0;
  background: transparent;
  cursor: pointer;
  transform-style: preserve-3d;
  transition: transform 0.7s cubic-bezier(0.2, 0.8, 0.2, 1);
  border-radius: var(--r-lg);
  outline: none;
}

.card.is-flipped {
  transform: rotateY(180deg);
}

.card:focus-visible {
  box-shadow: 0 0 0 3px var(--neon), 0 0 0 6px rgba(198, 255, 58, 0.25);
}

.card__face {
  position: absolute;
  inset: 0;
  border-radius: var(--r-lg);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  overflow: hidden;
  border: 1px solid var(--line-2);
  box-shadow: var(--shadow-2);
}

/* FRONT */
.card__front {
  display: flex;
  flex-direction: column;
  padding: 22px 22px 20px;
  background:
    linear-gradient(135deg, var(--elevated) 0%, var(--surface-2) 55%, #0f1216 100%);
}

.card__front::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(420px 220px at 110% -20%, rgba(198, 255, 58, 0.16), transparent 60%),
    radial-gradient(360px 200px at -10% 120%, rgba(255, 106, 43, 0.12), transparent 60%);
  pointer-events: none;
}

.card__sheen {
  position: absolute;
  top: 0;
  left: -60%;
  width: 50%;
  height: 100%;
  background: linear-gradient(
    100deg,
    transparent,
    rgba(255, 255, 255, 0.14),
    transparent
  );
  transform: skewX(-18deg);
  pointer-events: none;
}

.card.sheen-run .card__sheen {
  animation: sheen 0.9s ease-out;
}

@keyframes sheen {
  from { left: -60%; }
  to { left: 130%; }
}

.card__top {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

.brand {
  display: flex;
  align-items: center;
  gap: 8px;
}

.brand__name {
  font-weight: 900;
  letter-spacing: 0.12em;
  font-size: 15px;
}

.tier {
  position: relative;
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tier__label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--muted);
}

.tier__name {
  font-size: clamp(22px, 6.4vw, 30px);
  font-weight: 900;
  letter-spacing: -0.01em;
  line-height: 1.05;
  background: linear-gradient(92deg, var(--ink), var(--neon));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.card__chip {
  position: relative;
  margin: 14px 0 16px;
  width: 44px;
  height: 32px;
  border-radius: 7px;
  background: linear-gradient(135deg, #d8c98e, #a9914f);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  padding: 5px;
}

.card__chip span {
  border: 1px solid rgba(0, 0, 0, 0.25);
  border-radius: 2px;
}

.card__chip span:first-child {
  grid-column: 1 / -1;
}

.card__bottom {
  position: relative;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.field__k {
  font-size: 9.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--muted);
}

.field__v {
  font-size: 16px;
  font-weight: 700;
  color: var(--ink);
}

.field--name .field__v {
  font-size: 19px;
}

.meta-row {
  display: flex;
  justify-content: space-between;
  margin-top: 12px;
  gap: 16px;
}

.field--right {
  text-align: right;
  align-items: flex-end;
}

.mono {
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
}

.flip-hint {
  position: absolute;
  right: 18px;
  bottom: 14px;
  font-size: 10.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
  opacity: 0.85;
}

.card__front .flip-hint {
  right: auto;
  left: 22px;
  bottom: 8px;
}

/* BACK */
.card__back {
  transform: rotateY(180deg);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 18px 18px 24px;
  background: linear-gradient(160deg, #f6f8fa 0%, #e7ebef 100%);
  color: #0d0f12;
}

.back__top {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.back__title {
  font-size: 13px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: #1b1f25;
}

.qr-frame {
  position: relative;
  padding: 12px;
  background: #fff;
  border-radius: var(--r-md);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.06);
}

.qr-frame canvas {
  display: block;
  width: clamp(150px, 42vw, 200px);
  height: clamp(150px, 42vw, 200px);
  image-rendering: pixelated;
}

.qr-corner {
  position: absolute;
  width: 16px;
  height: 16px;
  border: 3px solid #0d0f12;
}

.qr-corner--tl { top: 4px; left: 4px; border-right: none; border-bottom: none; }
.qr-corner--tr { top: 4px; right: 4px; border-left: none; border-bottom: none; }
.qr-corner--bl { bottom: 4px; left: 4px; border-right: none; border-top: none; }
.qr-corner--br { bottom: 4px; right: 4px; border-left: none; border-top: none; }

.barcode {
  margin-top: 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.barcode canvas {
  display: block;
  width: clamp(220px, 70%, 300px);
  height: 52px;
}

.barcode__id {
  font-size: 12px;
  font-weight: 700;
  color: #2a2f36;
}

.card__back .flip-hint {
  color: #4a525c;
  opacity: 1;
}

/* ---------- pills ---------- */
.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  white-space: nowrap;
}

.pill--ok {
  background: rgba(52, 211, 153, 0.16);
  color: var(--ok);
  border: 1px solid rgba(52, 211, 153, 0.35);
}

.pill--ghost {
  background: rgba(13, 15, 18, 0.06);
  color: #3a414a;
  border: 1px solid rgba(13, 15, 18, 0.12);
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.6);
  animation: live 2s infinite;
}

@keyframes live {
  0% { box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.5); }
  70% { box-shadow: 0 0 0 7px rgba(52, 211, 153, 0); }
  100% { box-shadow: 0 0 0 0 rgba(52, 211, 153, 0); }
}

/* ---------- front-desk pulse ---------- */
.card.pulsing {
  animation: deskpulse 1.1s ease-in-out infinite;
}

@keyframes deskpulse {
  0%, 100% {
    box-shadow: var(--shadow-2), 0 0 0 0 rgba(198, 255, 58, 0);
    transform: scale(1);
  }
  50% {
    box-shadow: var(--shadow-2), 0 0 38px 6px rgba(198, 255, 58, 0.45);
    transform: scale(1.012);
  }
}

.card.is-flipped.pulsing {
  animation: deskpulse-back 1.1s ease-in-out infinite;
}

@keyframes deskpulse-back {
  0%, 100% {
    box-shadow: var(--shadow-2), 0 0 0 0 rgba(198, 255, 58, 0);
    transform: rotateY(180deg) scale(1);
  }
  50% {
    box-shadow: var(--shadow-2), 0 0 38px 6px rgba(198, 255, 58, 0.45);
    transform: rotateY(180deg) scale(1.012);
  }
}

/* ---------- controls ---------- */
.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  width: 100%;
  margin-top: 24px;
}

.btn {
  flex: 1 1 auto;
  min-height: 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 18px;
  border-radius: var(--r-md);
  font-family: inherit;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.02em;
  cursor: pointer;
  border: 1px solid transparent;
  transition: transform 0.12s ease, background 0.18s ease, border-color 0.18s ease;
}

.btn:active {
  transform: translateY(1px) scale(0.99);
}

.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(198, 255, 58, 0.4);
}

.btn--neon {
  flex-basis: 100%;
  background: var(--neon);
  color: #10130a;
}

.btn--neon:hover {
  background: var(--neon-d);
}

.btn--ghost {
  background: var(--surface-2);
  color: var(--ink);
  border-color: var(--line-2);
}

.btn--ghost:hover {
  background: var(--elevated);
  border-color: var(--neon);
}

.btn--ghost[aria-pressed="true"] {
  background: var(--neon-50);
  border-color: var(--neon);
  color: var(--neon);
}

.boost-icon {
  font-size: 16px;
  line-height: 1;
}

/* ---------- tier switch ---------- */
.hint-text {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin: 22px 0 0;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--muted);
}

.tier-switch {
  display: inline-flex;
  gap: 6px;
}

.chip {
  font-family: inherit;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: none;
  padding: 6px 12px;
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--ink-2);
  border: 1px solid var(--line);
  cursor: pointer;
  transition: all 0.16s ease;
}

.chip:hover {
  border-color: var(--line-2);
  color: var(--ink);
}

.chip[aria-pressed="true"] {
  background: var(--neon-50);
  border-color: var(--neon);
  color: var(--neon);
}

.chip:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(198, 255, 58, 0.35);
}

/* ---------- brightness boost ---------- */
.boost-overlay {
  position: fixed;
  inset: 0;
  background: #fff;
  opacity: 0;
  pointer-events: none;
  z-index: 40;
  transition: opacity 0.3s ease;
}

body.boosted .boost-overlay {
  opacity: 0.96;
}

body.boosted {
  --surface-2: #ffffff;
}

body.boosted .stage {
  position: relative;
  z-index: 60;
}

body.boosted .card__face {
  border-color: rgba(0, 0, 0, 0.4);
}

body.boosted .card__back {
  background: #ffffff;
  filter: contrast(1.25);
}

body.boosted .qr-frame {
  box-shadow: inset 0 0 0 2px #000;
}

/* ---------- toast ---------- */
.toast-host {
  position: fixed;
  left: 50%;
  bottom: 22px;
  transform: translateX(-50%);
  z-index: 80;
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
  width: max-content;
  max-width: calc(100vw - 32px);
}

.toast {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 11px 16px;
  border-radius: var(--r-md);
  background: var(--elevated);
  color: var(--ink);
  border: 1px solid var(--line-2);
  box-shadow: var(--shadow-2);
  font-size: 13.5px;
  font-weight: 600;
  opacity: 0;
  transform: translateY(12px) scale(0.97);
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.toast.show {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.toast::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--neon);
  box-shadow: 0 0 10px var(--neon);
}

/* ---------- responsive ---------- */
@media (max-width: 520px) {
  .wrap {
    padding: 22px 16px 48px;
  }

  .controls {
    gap: 8px;
  }

  .btn--ghost {
    flex: 1 1 calc(50% - 4px);
    font-size: 13px;
    padding: 0 10px;
  }

  .flip-hint {
    font-size: 9.5px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .card,
  .card.is-flipped {
    transition: none;
  }
  .dot,
  .card.pulsing,
  .card.is-flipped.pulsing,
  .card.sheen-run .card__sheen {
    animation: none;
  }
}

