(function () {
  "use strict";

  /* ---------- member data (fictional) ---------- */
  var member = {
    name: "Marcus Delgado",
    id: "IP-4827-0193",
    joined: "Mar 2022",
  };

  var TIERS = {
    black: { name: "Black Unlimited", id: "IP-4827-0193" },
    pro: { name: "Pro", id: "IP-3391-7740" },
    flex: { name: "Flex", id: "IP-8052-2218" },
  };

  /* ---------- elements ---------- */
  var card = document.getElementById("card");
  var flipBtn = document.getElementById("flipBtn");
  var frontDeskBtn = document.getElementById("frontDeskBtn");
  var boostBtn = document.getElementById("boostBtn");
  var boostLabel = document.getElementById("boostLabel");
  var tierName = document.querySelector(".tier__name");
  var memberIdEl = document.getElementById("memberId");
  var barcodeIdEl = document.querySelector(".barcode__id");
  var toastHost = document.getElementById("toastHost");
  var chips = Array.prototype.slice.call(document.querySelectorAll(".chip[data-tier]"));

  var flipped = false;
  var boosted = false;
  var pulseTimer = null;

  /* ---------- toast ---------- */
  function toast(msg) {
    var el = document.createElement("div");
    el.className = "toast";
    el.textContent = msg;
    toastHost.appendChild(el);
    requestAnimationFrame(function () {
      el.classList.add("show");
    });
    setTimeout(function () {
      el.classList.remove("show");
      setTimeout(function () {
        if (el.parentNode) el.parentNode.removeChild(el);
      }, 280);
    }, 2200);
  }

  /* ---------- deterministic pseudo-random from a seed ---------- */
  function seededRand(seed) {
    var s = 0;
    for (var i = 0; i < seed.length; i++) {
      s = (s * 31 + seed.charCodeAt(i)) >>> 0;
    }
    return function () {
      s = (s * 1664525 + 1013904223) >>> 0;
      return s / 4294967296;
    };
  }

  /* ---------- fake-but-realistic QR matrix ---------- */
  function drawQR(seedStr) {
    var canvas = document.getElementById("qr");
    var ctx = canvas.getContext("2d");
    var N = 25; // modules per side
    var size = canvas.width;
    var cell = Math.floor(size / N);
    var pad = Math.floor((size - cell * N) / 2);
    var rand = seededRand(seedStr);

    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, size, size);
    ctx.fillStyle = "#0d0f12";

    // build matrix
    var grid = [];
    var r, c;
    for (r = 0; r < N; r++) {
      grid[r] = [];
      for (c = 0; c < N; c++) {
        grid[r][c] = rand() > 0.5 ? 1 : 0;
      }
    }

    // finder pattern (7x7) drawn at a corner
    function finder(or_, oc) {
      for (var i = -1; i <= 7; i++) {
        for (var j = -1; j <= 7; j++) {
          var rr = or_ + i;
          var cc = oc + j;
          if (rr < 0 || cc < 0 || rr >= N || cc >= N) continue;
          var ring = i >= 0 && i <= 6 && j >= 0 && j <= 6;
          var border = i === 0 || i === 6 || j === 0 || j === 6;
          var core = i >= 2 && i <= 4 && j >= 2 && j <= 4;
          grid[rr][cc] = ring && (border || core) ? 1 : 0;
        }
      }
    }
    finder(0, 0);
    finder(0, N - 7);
    finder(N - 7, 0);

    // timing patterns
    for (var k = 8; k < N - 8; k++) {
      grid[6][k] = k % 2 === 0 ? 1 : 0;
      grid[k][6] = k % 2 === 0 ? 1 : 0;
    }

    // render
    for (r = 0; r < N; r++) {
      for (c = 0; c < N; c++) {
        if (grid[r][c]) {
          ctx.fillRect(pad + c * cell, pad + r * cell, cell, cell);
        }
      }
    }
  }

  /* ---------- barcode (Code 128-ish look) ---------- */
  function drawBarcode(seedStr) {
    var canvas = document.getElementById("barcode");
    var ctx = canvas.getContext("2d");
    var w = canvas.width;
    var h = canvas.height;
    var rand = seededRand(seedStr + "::bar");

    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = "#0d0f12";

    var x = 6;
    while (x < w - 6) {
      var barW = 1 + Math.floor(rand() * 4);
      var draw = rand() > 0.42;
      if (draw) ctx.fillRect(x, 4, barW, h - 8);
      x += barW + (1 + Math.floor(rand() * 2));
    }
  }

  /* ---------- flip ---------- */
  function setFlipped(state) {
    flipped = state;
    card.classList.toggle("is-flipped", flipped);
    card.setAttribute("aria-pressed", String(flipped));
    card.setAttribute(
      "aria-label",
      flipped
        ? "Membership card. Showing back with door check-in QR code. Activate to flip back."
        : "Membership card. Showing front. Activate to flip and reveal check-in QR code."
    );
    if (!flipped) {
      // re-run sheen on the front when returning
      card.classList.remove("sheen-run");
      void card.offsetWidth;
      card.classList.add("sheen-run");
    }
  }

  function toggleFlip() {
    setFlipped(!flipped);
  }

  card.addEventListener("click", toggleFlip);
  flipBtn.addEventListener("click", function () {
    toggleFlip();
  });

  /* ---------- front desk pulse ---------- */
  frontDeskBtn.addEventListener("click", function (e) {
    e.stopPropagation();
    if (!flipped) setFlipped(true);
    card.classList.add("pulsing");
    toast("Showing check-in code at front desk");
    if (pulseTimer) clearTimeout(pulseTimer);
    pulseTimer = setTimeout(function () {
      card.classList.remove("pulsing");
    }, 6000);
  });

  /* ---------- brightness boost ---------- */
  boostBtn.addEventListener("click", function (e) {
    e.stopPropagation();
    boosted = !boosted;
    document.body.classList.toggle("boosted", boosted);
    boostBtn.setAttribute("aria-pressed", String(boosted));
    boostLabel.textContent = boosted ? "Boost on" : "Brightness boost";
    if (boosted && !flipped) setFlipped(true);
    toast(boosted ? "Max brightness for scanning" : "Brightness restored");
  });

  /* ---------- tier switch ---------- */
  function applyTier(key) {
    var t = TIERS[key];
    if (!t) return;
    tierName.textContent = t.name;
    memberIdEl.textContent = t.id;
    barcodeIdEl.textContent = t.id;
    member.id = t.id;
    chips.forEach(function (chip) {
      chip.setAttribute("aria-pressed", String(chip.getAttribute("data-tier") === key));
    });
    renderCodes();
    toast("Tier set to " + t.name);
  }

  chips.forEach(function (chip) {
    chip.addEventListener("click", function () {
      applyTier(chip.getAttribute("data-tier"));
    });
  });

  /* ---------- render codes from current member ---------- */
  function renderCodes() {
    var payload = "IRONPULSE|" + member.id + "|CHECKIN";
    drawQR(payload);
    drawBarcode(member.id);
  }

  /* ---------- init ---------- */
  chips.forEach(function (chip) {
    chip.setAttribute("aria-pressed", String(chip.getAttribute("data-tier") === "black"));
  });
  renderCodes();

  // entrance sheen
  setTimeout(function () {
    card.classList.add("sheen-run");
  }, 300);
})();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;

  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;

  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;

  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;

  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);

  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --sh-1: 0 1px 2px rgba(22, 48, 42, 0.06), 0 1px 1px rgba(22, 48, 42, 0.04);
  --sh-2: 0 12px 30px -16px rgba(22, 48, 42, 0.28), 0 4px 10px -6px rgba(22, 48, 42, 0.16);
  --sh-3: 0 26px 60px -28px rgba(22, 48, 42, 0.42);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background:
    radial-gradient(1200px 700px at 84% -8%, rgba(176, 141, 87, 0.1), transparent 60%),
    radial-gradient(900px 600px at -10% 4%, rgba(31, 61, 52, 0.07), transparent 55%),
    var(--ivory);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.shell {
  max-width: 560px;
  margin: 0 auto;
  padding: 48px 24px 80px;
}

/* ---------- Masthead ---------- */
.masthead { margin-bottom: 30px; }

.eyebrow {
  margin: 0 0 10px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--brass-d);
}

.eyebrow::before {
  content: "";
  display: inline-block;
  width: 26px;
  height: 1px;
  margin-right: 10px;
  vertical-align: middle;
  background: var(--brass);
}

.masthead h1 {
  margin: 0 0 8px;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
  font-size: clamp(2.4rem, 6vw, 3.1rem);
  line-height: 1.05;
  letter-spacing: -0.01em;
  color: var(--green-d);
}

.masthead .sub {
  margin: 0;
  max-width: 44ch;
  color: var(--muted);
  font-size: 0.95rem;
}

/* ---------- List ---------- */
.lead-list {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

/* ---------- Card ---------- */
.lead {
  position: relative;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-2);
  transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.28s ease, border-color 0.28s ease;
}

.lead::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: var(--line-2);
  transition: background 0.3s ease;
}

.lead:hover {
  transform: translateY(-3px);
  box-shadow: var(--sh-3);
  border-color: var(--line-2);
}

.lead:focus-within { outline: none; }

/* ---------- Media / faux photography ---------- */
.lead__media {
  position: relative;
  aspect-ratio: 16 / 6;
  display: flex;
  align-items: flex-end;
  padding: 12px 14px;
}

.lead__media::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0, 0, 0, 0) 36%, rgba(20, 30, 26, 0.42));
  pointer-events: none;
}

.lead__shot-label {
  position: relative;
  z-index: 1;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: rgba(255, 255, 255, 0.96);
  background: rgba(22, 48, 42, 0.34);
  backdrop-filter: blur(3px);
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.28);
}

/* Distinct architectural "photos" per card */
.lead__media[data-shot="a"] {
  background:
    radial-gradient(120% 90% at 80% 10%, rgba(255, 240, 214, 0.6), transparent 55%),
    linear-gradient(115deg, #2c4a5e 0%, #3f6f7a 42%, #7fa7a0 100%),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.06) 0 2px, transparent 2px 26px);
}
.lead__media[data-shot="b"] {
  background:
    radial-gradient(110% 120% at 18% 0%, rgba(255, 246, 220, 0.7), transparent 50%),
    linear-gradient(120deg, #8a5a35 0%, #b9824c 45%, #e0b97e 100%),
    repeating-linear-gradient(85deg, rgba(60, 36, 18, 0.12) 0 3px, transparent 3px 30px);
}
.lead__media[data-shot="c"] {
  background:
    radial-gradient(120% 110% at 75% 0%, rgba(255, 232, 198, 0.55), transparent 55%),
    linear-gradient(125deg, #3a3550 0%, #6b5d7e 48%, #b39fb0 100%),
    repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.05) 0 1px, transparent 1px 22px);
}
.lead__media[data-shot="d"] {
  background:
    radial-gradient(130% 100% at 30% 6%, rgba(232, 245, 234, 0.55), transparent 55%),
    linear-gradient(120deg, #1f3d34 0%, #34614f 46%, #84a98c 100%),
    repeating-linear-gradient(70deg, rgba(255, 255, 255, 0.05) 0 2px, transparent 2px 28px);
}

/* ---------- Body ---------- */
.lead__body { padding: 18px 20px 20px; }

.lead__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.lead__who {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
}

.avatar {
  flex: none;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: 0.02em;
  color: var(--white);
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.4), var(--sh-1);
}
.avatar[data-tone="1"] { background: linear-gradient(140deg, #2f6f5b, #1f3d34); }
.avatar[data-tone="2"] { background: linear-gradient(140deg, #b9824c, #94733f); }
.avatar[data-tone="3"] { background: linear-gradient(140deg, #6b5d7e, #443a5a); }
.avatar[data-tone="4"] { background: linear-gradient(140deg, #3a7a6a, #26493e); }

.lead__id { min-width: 0; }

.lead__name {
  margin: 0 0 3px;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
  font-size: 1.5rem;
  line-height: 1.1;
  color: var(--green-d);
}

.lead__contact {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
}

.contact {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 0.8rem;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s ease;
}
.contact svg { width: 13px; height: 13px; fill: var(--brass); flex: none; }
.contact:hover { color: var(--green-700); }

/* ---------- Star ---------- */
.star {
  flex: none;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--white);
  cursor: pointer;
  transition: transform 0.18s ease, border-color 0.2s ease, background 0.2s ease;
}
.star svg { width: 18px; height: 18px; fill: none; stroke: var(--muted); stroke-width: 1.6; }
.star:hover { transform: scale(1.08); border-color: var(--brass); }
.star:active { transform: scale(0.94); }
.star.is-on { background: var(--brass-50); border-color: var(--brass); }
.star.is-on svg { fill: var(--brass); stroke: var(--brass-d); }
.star.bump { animation: starPop 0.32s cubic-bezier(0.34, 1.56, 0.64, 1); }

@keyframes starPop {
  0% { transform: scale(1); }
  45% { transform: scale(1.32) rotate(8deg); }
  100% { transform: scale(1); }
}

/* ---------- Facts / chips ---------- */
.lead__facts {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin: 15px 0 14px;
}

.chip {
  font-size: 0.74rem;
  font-weight: 500;
  color: var(--ink-2);
  background: var(--green-50);
  border: 1px solid var(--line);
  padding: 4px 10px;
  border-radius: 999px;
  white-space: nowrap;
}
.chip--brass {
  color: var(--brass-d);
  background: var(--brass-50);
  border-color: rgba(176, 141, 87, 0.34);
}

/* ---------- Meta row: status pill + activity ---------- */
.lead__meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font: inherit;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  padding: 6px 13px;
  border-radius: 999px;
  border: 1px solid currentColor;
  background: var(--white);
  cursor: pointer;
  transition: transform 0.16s ease, box-shadow 0.2s ease, background 0.2s ease;
}
.pill__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 22%, transparent);
}
.pill:hover { transform: translateY(-1px); box-shadow: var(--sh-1); }
.pill:active { transform: translateY(0); }
.pill.flash { animation: pillFlash 0.4s ease; }

@keyframes pillFlash {
  0% { box-shadow: 0 0 0 0 color-mix(in srgb, currentColor 38%, transparent); }
  100% { box-shadow: 0 0 0 12px transparent; }
}

/* status colour mapping (drives pill + left accent) */
.lead[data-status="new"] .pill { color: #2563a8; background: #eaf2fb; }
.lead[data-status="new"]::before { background: #2563a8; }
.lead[data-status="contacted"] .pill { color: var(--warn); background: #fbf1e2; }
.lead[data-status="contacted"]::before { background: var(--warn); }
.lead[data-status="touring"] .pill { color: var(--green-700); background: var(--green-50); }
.lead[data-status="touring"]::before { background: var(--green-700); }
.lead[data-status="offer"] .pill { color: var(--brass-d); background: var(--brass-50); }
.lead[data-status="offer"]::before { background: var(--brass-d); }

.activity {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 0.76rem;
  color: var(--muted);
}
.activity svg { width: 14px; height: 14px; fill: var(--muted); flex: none; }

/* ---------- Notes ---------- */
.notes {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 14px;
}
.note {
  font-size: 0.82rem;
  color: var(--ink-2);
  background: var(--ivory);
  border: 1px solid var(--line);
  border-left: 3px solid var(--brass);
  border-radius: var(--r-sm);
  padding: 9px 12px;
  animation: noteIn 0.3s ease;
}
.note__time {
  display: block;
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--brass-d);
  margin-bottom: 2px;
}

@keyframes noteIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: none; }
}

/* note composer */
.note-form {
  display: flex;
  gap: 8px;
  margin-top: 12px;
  animation: noteIn 0.24s ease;
}
.note-form input {
  flex: 1;
  min-width: 0;
  font: inherit;
  font-size: 0.85rem;
  padding: 9px 12px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  background: var(--white);
  color: var(--ink);
}
.note-form input:focus {
  outline: none;
  border-color: var(--brass);
  box-shadow: 0 0 0 3px var(--brass-50);
}
.note-form button {
  flex: none;
  font: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  padding: 9px 16px;
  border: none;
  border-radius: var(--r-sm);
  background: var(--green);
  color: var(--white);
  cursor: pointer;
  transition: background 0.2s ease;
}
.note-form button:hover { background: var(--green-d); }

/* ---------- Quick actions ---------- */
.lead__actions {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}

.act {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  text-decoration: none;
  color: var(--green-d);
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: var(--r-md);
  padding: 9px 10px;
  cursor: pointer;
  transition: transform 0.16s ease, background 0.2s ease, color 0.2s ease,
    border-color 0.2s ease, box-shadow 0.2s ease;
}
.act svg { width: 15px; height: 15px; fill: currentColor; }
.act:hover {
  background: var(--green);
  color: var(--white);
  border-color: var(--green);
  box-shadow: var(--sh-1);
}
.act:active { transform: translateY(1px); }
.act--ghost { color: var(--brass-d); }
.act--ghost:hover { background: var(--brass); border-color: var(--brass); color: var(--white); }

/* keyboard focus visibility */
.star:focus-visible,
.pill:focus-visible,
.act:focus-visible,
.contact:focus-visible,
.note-form input:focus-visible,
.note-form button:focus-visible {
  outline: 2px solid var(--green-700);
  outline-offset: 2px;
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 18px);
  background: var(--green-d);
  color: var(--paper);
  font-size: 0.85rem;
  font-weight: 500;
  padding: 11px 18px;
  border-radius: 999px;
  box-shadow: var(--sh-3);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.28s ease, transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);
  z-index: 50;
  max-width: calc(100vw - 32px);
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* ---------- Responsive ---------- */
@media (max-width: 520px) {
  .shell { padding: 34px 16px 70px; }
  .lead__body { padding: 16px 15px 17px; }
  .lead__name { font-size: 1.32rem; }
  .lead__media { aspect-ratio: 16 / 7; }
  .lead__actions { flex-wrap: wrap; }
  .act { flex: 1 1 30%; padding: 9px 6px; }
  .lead__meta { gap: 8px; }
  .contact span { font-size: 0.76rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

