(function () {
  "use strict";

  /* ---- Status cycle definition ---- */
  var STATUS_ORDER = ["new", "contacted", "touring", "offer"];
  var STATUS_LABEL = {
    new: "New",
    contacted: "Contacted",
    touring: "Touring",
    offer: "Offer",
  };

  /* ---- Toast helper ---- */
  var toastEl = document.getElementById("toast");
  var toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    window.clearTimeout(toastTimer);
    toastTimer = window.setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2400);
  }

  function leadName(card) {
    var n = card.querySelector(".lead__name");
    return n ? n.textContent.trim() : "Lead";
  }

  /* ---- Status cycling ---- */
  function cycleStatus(card) {
    var current = card.getAttribute("data-status") || "new";
    var idx = STATUS_ORDER.indexOf(current);
    var next = STATUS_ORDER[(idx + 1) % STATUS_ORDER.length];
    card.setAttribute("data-status", next);

    var pill = card.querySelector(".pill");
    var text = card.querySelector(".pill__text");
    if (text) text.textContent = STATUS_LABEL[next];
    if (pill) {
      pill.classList.remove("flash");
      // reflow to restart animation
      void pill.offsetWidth;
      pill.classList.add("flash");
    }
    toast(leadName(card) + " moved to " + STATUS_LABEL[next]);
  }

  /* ---- Star / priority toggle ---- */
  function toggleStar(btn, card) {
    var on = btn.classList.toggle("is-on");
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    card.setAttribute("data-priority", on ? "true" : "false");
    btn.classList.remove("bump");
    void btn.offsetWidth;
    btn.classList.add("bump");
    toast(
      on
        ? leadName(card) + " flagged as priority"
        : "Priority removed for " + leadName(card)
    );
  }

  /* ---- Add note inline ---- */
  function nowStamp() {
    var d = new Date();
    var days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    var h = d.getHours();
    var ampm = h >= 12 ? "PM" : "AM";
    var hr = h % 12 || 12;
    var min = ("0" + d.getMinutes()).slice(-2);
    return days[d.getDay()] + " · " + hr + ":" + min + " " + ampm;
  }

  function appendNote(notesEl, value) {
    var note = document.createElement("div");
    note.className = "note";
    var time = document.createElement("span");
    time.className = "note__time";
    time.textContent = nowStamp();
    note.appendChild(time);
    note.appendChild(document.createTextNode(value));
    notesEl.appendChild(note);
  }

  function openNoteForm(card) {
    var notesEl = card.querySelector("[data-notes]");
    if (!notesEl) return;
    notesEl.hidden = false;

    // avoid duplicate composer
    if (card.querySelector(".note-form")) {
      var existing = card.querySelector(".note-form input");
      if (existing) existing.focus();
      return;
    }

    var form = document.createElement("form");
    form.className = "note-form";

    var input = document.createElement("input");
    input.type = "text";
    input.placeholder = "Quick note about this lead…";
    input.setAttribute("aria-label", "Note for " + leadName(card));
    input.maxLength = 160;

    var submit = document.createElement("button");
    submit.type = "submit";
    submit.textContent = "Save";

    form.appendChild(input);
    form.appendChild(submit);
    notesEl.insertAdjacentElement("afterend", form);
    input.focus();

    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var v = input.value.trim();
      if (!v) {
        input.focus();
        return;
      }
      appendNote(notesEl, v);
      form.remove();
      toast("Note added to " + leadName(card));
    });

    input.addEventListener("keydown", function (e) {
      if (e.key === "Escape") {
        form.remove();
      }
    });
  }

  /* ---- Event delegation ---- */
  var list = document.getElementById("leadList");
  if (!list) return;

  list.addEventListener("click", function (e) {
    var card = e.target.closest(".lead");
    if (!card) return;

    var star = e.target.closest(".star");
    if (star) {
      e.preventDefault();
      toggleStar(star, card);
      return;
    }

    var statusBtn = e.target.closest('[data-action="status"]');
    if (statusBtn) {
      e.preventDefault();
      cycleStatus(card);
      return;
    }

    var noteBtn = e.target.closest('[data-action="note"]');
    if (noteBtn) {
      e.preventDefault();
      openNoteForm(card);
      return;
    }

    // Let real tel:/mailto: links and contact rows behave naturally,
    // but surface a toast for the in-card quick actions.
    var act = e.target.closest("a.act");
    if (act) {
      var label = act.textContent.trim();
      toast(label + " · " + leadName(card));
    }
  });
})();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --sh-1: 0 1px 2px rgba(28, 42, 37, 0.05), 0 4px 14px rgba(28, 42, 37, 0.06);
  --sh-2: 0 2px 6px rgba(28, 42, 37, 0.08), 0 18px 44px rgba(28, 42, 37, 0.12);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: "Inter", system-ui, sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--ivory);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3 {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
  margin: 0;
  color: var(--ink);
  letter-spacing: 0.2px;
}

p { margin: 0 0 0.8em; }
a { color: inherit; }

.wrap { width: min(1180px, 92vw); margin-inline: auto; }

/* ---------- Topbar ---------- */
.topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  background: rgba(247, 244, 236, 0.86);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
}
.topbar__inner {
  display: flex;
  align-items: center;
  gap: 22px;
  height: 64px;
}
.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; }
.brand__mark {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: var(--r-sm);
  background: var(--green);
  color: var(--brass-50);
  font-family: "Cormorant Garamond", serif;
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.5px;
}
.brand__name {
  font-family: "Cormorant Garamond", serif;
  font-size: 19px;
  font-weight: 600;
  color: var(--green);
  line-height: 1.1;
}
.brand__name em { color: var(--brass-d); font-style: italic; }
.topnav { margin-left: auto; display: flex; gap: 22px; }
.topnav a {
  text-decoration: none;
  font-size: 13.5px;
  font-weight: 500;
  color: var(--ink-2);
  padding-bottom: 2px;
  border-bottom: 1.5px solid transparent;
  transition: color 0.18s, border-color 0.18s;
}
.topnav a:hover { color: var(--green); border-color: var(--brass); }

/* ---------- Buttons ---------- */
.btn {
  --bg: var(--white);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-size: 14px;
  font-weight: 600;
  border-radius: var(--r-md);
  padding: 11px 18px;
  border: 1px solid var(--line-2);
  background: var(--bg);
  color: var(--ink);
  cursor: pointer;
  text-decoration: none;
  transition: transform 0.12s ease, box-shadow 0.18s, background 0.18s, border-color 0.18s;
}
.btn:hover { box-shadow: var(--sh-1); }
.btn:active { transform: translateY(1px); }
.btn:focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }
.btn--sm { padding: 8px 14px; font-size: 13px; }
.btn--block { width: 100%; }
.btn--primary {
  background: var(--green);
  border-color: var(--green-d);
  color: var(--paper);
}
.btn--primary:hover { background: var(--green-700); }
.btn--ghost { background: transparent; }
.btn--ghost:hover { background: var(--white); border-color: var(--brass); }

/* ---------- Page ---------- */
.page { padding: 26px 0 60px; }
.crumbs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  font-size: 12.5px;
  color: var(--muted);
  margin-bottom: 18px;
}
.crumbs a { text-decoration: none; }
.crumbs a:hover { color: var(--green); }
.crumbs [aria-current] { color: var(--ink-2); font-weight: 600; }

/* ---------- Photo simulation ---------- */
.ph {
  display: block;
  width: 100%;
  height: 100%;
  background-size: cover;
}
.ph--living {
  background:
    radial-gradient(120% 90% at 78% 10%, rgba(255, 248, 232, 0.95) 0%, rgba(255, 248, 232, 0) 42%),
    radial-gradient(90% 70% at 20% 100%, rgba(176, 141, 87, 0.5) 0%, rgba(176, 141, 87, 0) 55%),
    linear-gradient(160deg, #d9c8a8 0%, #c2a87f 38%, #8a6f4c 100%);
}
.ph--kitchen {
  background:
    radial-gradient(80% 60% at 70% 20%, rgba(255, 252, 244, 0.9) 0%, rgba(255, 252, 244, 0) 45%),
    linear-gradient(155deg, #efe7d6 0%, #cfc0a4 45%, #6f7a6d 100%);
}
.ph--bedroom {
  background:
    radial-gradient(90% 70% at 30% 18%, rgba(255, 246, 230, 0.92) 0%, rgba(255, 246, 230, 0) 48%),
    linear-gradient(165deg, #e7d8c0 0%, #b89a74 55%, #5b4a39 100%);
}
.ph--bath {
  background:
    radial-gradient(70% 60% at 75% 25%, rgba(255, 255, 255, 0.85) 0%, rgba(255, 255, 255, 0) 50%),
    linear-gradient(150deg, #dfe6e2 0%, #a9bcb3 50%, #355247 100%);
}
.ph--garden {
  background:
    radial-gradient(100% 80% at 50% 0%, rgba(245, 240, 215, 0.85) 0%, rgba(245, 240, 215, 0) 45%),
    linear-gradient(170deg, #b7c39a 0%, #6f8a5d 45%, #2f4a34 100%);
}
.ph--facade {
  background:
    radial-gradient(110% 80% at 50% 110%, rgba(176, 141, 87, 0.55) 0%, rgba(176, 141, 87, 0) 50%),
    linear-gradient(200deg, #6b5b86 0%, #b07a63 45%, #e0a86a 100%);
}

/* ---------- Gallery ---------- */
.gallery {
  display: grid;
  grid-template-columns: 1fr 116px;
  gap: 14px;
  margin-bottom: 28px;
}
.gallery__main {
  position: relative;
  margin: 0;
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--sh-2);
  aspect-ratio: 16 / 10;
}
.gallery__mainbtn {
  display: block;
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  background: none;
  cursor: zoom-in;
  position: relative;
}
.gallery__mainbtn:focus-visible { outline: 3px solid var(--brass); outline-offset: -3px; }
.gallery__mainbtn .ph { transition: transform 0.5s ease; }
.gallery__mainbtn:hover .ph { transform: scale(1.03); }
.gallery__caption {
  position: absolute;
  left: 16px;
  bottom: 14px;
  font-size: 12.5px;
  font-weight: 500;
  color: #fff;
  background: rgba(22, 48, 42, 0.55);
  backdrop-filter: blur(4px);
  padding: 6px 12px;
  border-radius: 999px;
  letter-spacing: 0.3px;
}
.gallery__count {
  position: absolute;
  right: 14px;
  bottom: 14px;
  font-size: 12px;
  font-weight: 600;
  color: #fff;
  background: rgba(22, 48, 42, 0.55);
  padding: 5px 11px;
  border-radius: 999px;
}
.gallery__thumbs {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.thumb {
  position: relative;
  flex: 1;
  min-height: 0;
  border: 2px solid transparent;
  border-radius: var(--r-md);
  overflow: hidden;
  padding: 0;
  cursor: pointer;
  background: none;
  box-shadow: var(--sh-1);
  transition: border-color 0.18s, transform 0.18s;
}
.thumb:hover { transform: translateY(-2px); }
.thumb.is-active { border-color: var(--brass); }
.thumb.is-active::after {
  content: "";
  position: absolute;
  inset: 0;
  box-shadow: inset 0 0 0 2px var(--paper);
  border-radius: 10px;
}
.thumb:focus-visible { outline: 2px solid var(--green); outline-offset: 2px; }

/* ---------- Badges ---------- */
.badge {
  position: absolute;
  top: 16px;
  left: 16px;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  padding: 6px 12px;
  border-radius: 999px;
}
.badge--status {
  background: var(--green);
  color: var(--brass-50);
  box-shadow: 0 4px 14px rgba(22, 48, 42, 0.3);
}

/* ---------- Layout ---------- */
.layout {
  display: grid;
  grid-template-columns: 1fr 360px;
  gap: 34px;
  align-items: start;
}

/* ---------- Price header ---------- */
.head {
  padding-bottom: 24px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 8px;
}
.head__top {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: flex-end;
  flex-wrap: wrap;
}
.head__price {
  font-family: "Cormorant Garamond", serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1;
  color: var(--green);
  margin: 0 0 6px;
}
.head__addr { font-size: 27px; line-height: 1.1; margin-bottom: 2px; }
.head__sub { color: var(--muted); margin: 0; font-size: 14px; }
.head__actions { display: flex; gap: 10px; }
.heart { font-size: 16px; line-height: 1; }
.btn[aria-pressed="true"] .heart { color: var(--danger); }
.btn[aria-pressed="true"] { border-color: var(--brass); }

.facts {
  list-style: none;
  margin: 22px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
}
.facts li {
  background: var(--paper);
  padding: 14px 10px;
  text-align: center;
}
.facts strong {
  display: block;
  font-family: "Cormorant Garamond", serif;
  font-size: 22px;
  font-weight: 600;
  color: var(--ink);
}
.facts span {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  color: var(--muted);
}

/* ---------- Content blocks ---------- */
.block { padding: 26px 0; border-bottom: 1px solid var(--line); }
.block__title {
  font-size: 25px;
  margin-bottom: 12px;
  position: relative;
  padding-left: 16px;
}
.block__title::before {
  content: "";
  position: absolute;
  left: 0;
  top: 6px;
  bottom: 6px;
  width: 3px;
  border-radius: 3px;
  background: linear-gradient(var(--brass), var(--brass-d));
}
.block p { color: var(--ink-2); max-width: 64ch; }
.block__lead { font-size: 15.5px; }
.readmore {
  background: none;
  border: 0;
  color: var(--brass-d);
  font-weight: 600;
  font-family: inherit;
  font-size: 14px;
  cursor: pointer;
  padding: 0;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.readmore:hover { color: var(--green); }

/* ---------- Features ---------- */
.feat {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 6px;
}
.feat__cell {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 13px 14px;
  font-size: 13.5px;
  font-weight: 500;
  color: var(--ink-2);
  transition: border-color 0.18s, transform 0.18s, box-shadow 0.18s;
}
.feat__cell:hover {
  border-color: var(--brass);
  transform: translateY(-2px);
  box-shadow: var(--sh-1);
}
.feat__ico { color: var(--brass-d); font-size: 13px; }

/* ---------- Map ---------- */
.map {
  position: relative;
  margin-top: 8px;
  aspect-ratio: 16 / 7;
  border-radius: var(--r-lg);
  overflow: hidden;
  border: 1px solid var(--line);
  background:
    radial-gradient(60% 50% at 85% 20%, rgba(176, 141, 87, 0.12), transparent 60%),
    linear-gradient(135deg, #eef0e8 0%, #e7ece2 60%, #dfe6da 100%);
  box-shadow: var(--sh-1);
}
.map__road { position: absolute; background: var(--white); box-shadow: 0 0 0 1px var(--line); }
.map__road--h { left: 0; right: 0; height: 9px; }
.map__road--v { top: 0; bottom: 0; width: 9px; }
.map__park {
  position: absolute;
  width: 100px;
  height: 70px;
  border-radius: 14px;
  background: linear-gradient(160deg, #cdd9b8, #9fb586);
  opacity: 0.85;
}
.map__water {
  position: absolute;
  right: -30px;
  top: -20px;
  width: 150px;
  height: 120px;
  border-radius: 50%;
  background: linear-gradient(160deg, #bcd2d4, #8fb2b3);
  opacity: 0.7;
}
.map__pin { position: absolute; transform: translate(-50%, -50%); }
.map__dot {
  display: block;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--green);
  border: 3px solid var(--paper);
  box-shadow: 0 4px 12px rgba(22, 48, 42, 0.4);
}
.map__pin--home .map__dot {
  width: 22px;
  height: 22px;
  background: var(--brass);
  animation: pulse 2.4s infinite;
}
@keyframes pulse {
  0% { box-shadow: 0 0 0 0 rgba(176, 141, 87, 0.45); }
  70% { box-shadow: 0 0 0 14px rgba(176, 141, 87, 0); }
  100% { box-shadow: 0 0 0 0 rgba(176, 141, 87, 0); }
}
.map__plabel {
  position: absolute;
  left: 50%;
  top: -10px;
  transform: translate(-50%, -100%);
  white-space: nowrap;
  font-size: 11px;
  font-weight: 600;
  background: var(--green);
  color: var(--brass-50);
  padding: 4px 9px;
  border-radius: 999px;
}
.map__poi {
  position: absolute;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--paper);
  border: 3px solid var(--brass-d);
  transform: translate(-50%, -50%);
  cursor: help;
}
.map__poi::after {
  content: attr(data-poi);
  position: absolute;
  left: 50%;
  bottom: 140%;
  transform: translateX(-50%) scale(0.9);
  white-space: nowrap;
  font-size: 11px;
  font-weight: 600;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line);
  padding: 3px 8px;
  border-radius: 6px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s, transform 0.15s;
}
.map__poi:hover::after { opacity: 1; transform: translateX(-50%) scale(1); }
.walk {
  list-style: none;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  padding: 0;
  margin: 16px 0 0;
}
.walk li {
  font-size: 12.5px;
  color: var(--muted);
  background: var(--green-50);
  border-radius: 999px;
  padding: 7px 14px;
}
.walk strong { color: var(--green); font-size: 14px; }

/* ---------- Schools ---------- */
.schools { list-style: none; padding: 0; margin: 8px 0 12px; display: grid; gap: 10px; }
.school {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 14px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 13px 16px;
  transition: box-shadow 0.18s, transform 0.18s;
}
.school:hover { box-shadow: var(--sh-1); transform: translateY(-1px); }
.school__rating {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 10px;
  font-family: "Cormorant Garamond", serif;
  font-weight: 700;
  font-size: 19px;
  color: #fff;
}
.school__rating[data-score="9"] { background: var(--ok); }
.school__rating[data-score="8"] { background: #4a9e6f; }
.school__rating[data-score="7"] { background: var(--warn); }
.school__name { font-weight: 600; margin: 0; font-size: 14.5px; }
.school__meta { margin: 0; font-size: 12.5px; color: var(--muted); }
.school__bar {
  display: block;
  width: 80px;
  height: 6px;
  border-radius: 999px;
  background: var(--green-50);
  overflow: hidden;
}
.school__bar span { display: block; height: 100%; background: var(--brass); border-radius: 999px; }
.fineprint { font-size: 11.5px; color: var(--muted); margin: 8px 0 0; font-style: italic; }

/* ---------- Cards (sidebar) ---------- */
.col-side { position: sticky; top: 84px; display: grid; gap: 20px; }
.card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 22px;
  box-shadow: var(--sh-1);
}
.card__title { font-size: 21px; margin-bottom: 6px; }

/* ---------- Payment ---------- */
.pay__total {
  font-family: "Cormorant Garamond", serif;
  font-size: 36px;
  font-weight: 700;
  color: var(--green);
  margin: 0 0 16px;
  line-height: 1;
}
.pay__per { font-family: "Inter", sans-serif; font-size: 13px; font-weight: 500; color: var(--muted); margin-left: 6px; }
.field { margin-bottom: 14px; }
.field label {
  display: flex;
  justify-content: space-between;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--ink-2);
  margin-bottom: 6px;
}
.field label span { color: var(--brass-d); }
.field__money {
  display: flex;
  align-items: center;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  background: var(--white);
  overflow: hidden;
}
.field__money span { padding: 0 4px 0 12px; color: var(--muted); font-weight: 600; }
.field__money input { border: 0; }
.field input[type="text"],
.field input[type="email"],
.field input[type="date"],
.field input[type="number"],
.field select,
.field textarea {
  width: 100%;
  font-family: inherit;
  font-size: 14px;
  color: var(--ink);
  padding: 10px 12px;
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  background: var(--white);
  transition: border-color 0.16s, box-shadow 0.16s;
}
.field__money input { padding-left: 4px; }
.field input:focus,
.field select:focus,
.field textarea:focus {
  outline: none;
  border-color: var(--brass);
  box-shadow: 0 0 0 3px var(--brass-50);
}
.field textarea { resize: vertical; }
.field input[type="range"] {
  width: 100%;
  margin: 4px 0 2px;
  accent-color: var(--green);
}
.field__hint { font-size: 12px; color: var(--muted); }
.pay__break {
  margin: 4px 0 0;
  padding: 14px 0 4px;
  border-top: 1px solid var(--line);
}
.pay__break div { display: flex; justify-content: space-between; padding: 4px 0; }
.pay__break dt { font-size: 13px; color: var(--ink-2); margin: 0; }
.pay__break dd { font-size: 13.5px; font-weight: 600; margin: 0; }

/* ---------- Agent ---------- */
.agent__top { display: flex; gap: 14px; align-items: center; margin-bottom: 18px; }
.agent__avatar {
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  flex: 0 0 56px;
  border-radius: 50%;
  background: linear-gradient(155deg, var(--green-700), var(--green-d));
  color: var(--brass-50);
  font-family: "Cormorant Garamond", serif;
  font-weight: 700;
  font-size: 19px;
  letter-spacing: 0.5px;
}
.agent__name { font-family: "Cormorant Garamond", serif; font-size: 20px; font-weight: 600; margin: 0; }
.agent__role { margin: 0; font-size: 12px; color: var(--muted); }
.agent__rating { margin: 4px 0 0; font-size: 13px; color: var(--brass); }
.agent__rating span { color: var(--muted); font-size: 12px; }
.tour__title { font-family: "Cormorant Garamond", serif; font-size: 18px; font-weight: 600; margin: 0 0 12px; color: var(--ink); }
.tour .btn--block + .btn--block { margin-top: 8px; }

/* ---------- Footer ---------- */
.foot {
  border-top: 1px solid var(--line);
  background: var(--paper);
  margin-top: 30px;
}
.foot__inner { padding: 26px 0; }
.foot p { margin: 0; font-size: 13px; color: var(--ink-2); }
.foot__sm { color: var(--muted); font-size: 12px; margin-top: 4px; }

/* ---------- Lightbox ---------- */
.lightbox {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 24px;
  background: rgba(18, 30, 26, 0.86);
  backdrop-filter: blur(6px);
  animation: fade 0.2s ease;
}
.lightbox[hidden] { display: none; }
@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
.lightbox__fig { margin: 0; width: min(960px, 80vw); max-width: 80vw; }
.lightbox__img {
  display: block;
  width: 100%;
  aspect-ratio: 16 / 10;
  border-radius: var(--r-lg);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.5);
}
.lightbox__cap { text-align: center; color: var(--brass-50); font-size: 13px; margin-top: 14px; }
.lightbox__close {
  position: absolute;
  top: 20px;
  right: 24px;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.25);
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  font-size: 18px;
  cursor: pointer;
  transition: background 0.16s;
}
.lightbox__close:hover { background: rgba(255, 255, 255, 0.2); }
.lightbox__nav {
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.25);
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  font-size: 26px;
  line-height: 1;
  cursor: pointer;
  transition: background 0.16s, transform 0.12s;
}
.lightbox__nav:hover { background: rgba(255, 255, 255, 0.2); }
.lightbox__nav:active { transform: scale(0.94); }
.lightbox :focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 24px);
  z-index: 80;
  background: var(--green-d);
  color: var(--paper);
  font-size: 14px;
  font-weight: 500;
  padding: 13px 22px;
  border-radius: var(--r-md);
  box-shadow: var(--sh-2);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s, transform 0.25s;
  max-width: min(90vw, 420px);
}
.toast.is-show { opacity: 1; transform: translate(-50%, 0); }
.toast::before { content: "✦ "; color: var(--brass); }

/* ---------- Responsive ---------- */
@media (max-width: 980px) {
  .layout { grid-template-columns: 1fr; }
  .col-side { position: static; }
  .topnav { display: none; }
}

@media (max-width: 720px) {
  .feat { grid-template-columns: repeat(2, 1fr); }
  .facts { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 520px) {
  body { font-size: 14.5px; }
  .gallery { grid-template-columns: 1fr; }
  .gallery__thumbs {
    flex-direction: row;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    padding-bottom: 4px;
  }
  .thumb { flex: 0 0 84px; height: 64px; }
  .head__top { flex-direction: column; align-items: flex-start; }
  .head__actions { width: 100%; }
  .head__actions .btn { flex: 1; }
  .head__price { font-size: 34px; }
  .head__addr { font-size: 23px; }
  .facts { grid-template-columns: repeat(2, 1fr); }
  .feat { grid-template-columns: 1fr; }
  .block__title { font-size: 22px; }
  .lightbox__nav { width: 40px; height: 40px; flex-basis: 40px; }
  .lightbox__fig { width: 86vw; }
}

