/* ── Design tokens ── */
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 12px 36px rgba(15, 29, 54, 0.16);
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Topbar ── */
.topbar {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--navy-d);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 32px;
  height: 56px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--bone);
}
.brand-mark {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}
.brand-name em {
  font-style: normal;
  color: var(--gold-light);
}
.topnav {
  display: flex;
  gap: 24px;
}
.topnav a {
  font-size: 0.86rem;
  font-weight: 500;
  color: rgba(251, 248, 242, 0.7);
  text-decoration: none;
}
.topnav a:hover {
  color: var(--bone);
}

/* ── Page ── */
.page {
  max-width: 1000px;
  margin: 0 auto;
  padding: 40px 24px 60px;
}

/* ── Hero ── */
.hero {
  text-align: center;
  padding: 40px 20px 36px;
  background: linear-gradient(160deg, var(--navy) 0%, var(--navy-d) 100%);
  border-radius: var(--r-lg);
  margin-bottom: 32px;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 0%, rgba(201, 166, 73, 0.22), transparent 65%);
  pointer-events: none;
}
.hero-icon {
  width: 64px;
  height: 64px;
  background: var(--success);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  font-size: 1.8rem;
  color: #fff;
  font-weight: 700;
  box-shadow: 0 0 0 8px rgba(74, 119, 82, 0.18);
}
.hero h1 {
  font-family: var(--font-display);
  font-size: 2.8rem;
  font-weight: 700;
  color: var(--bone);
  letter-spacing: -0.01em;
  margin-bottom: 8px;
}
.hero-sub {
  font-size: 1rem;
  color: rgba(251, 248, 242, 0.75);
  margin-bottom: 24px;
}
.ref-row {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  margin-bottom: 16px;
}
.ref-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  font-weight: 700;
  color: var(--gold-light);
}
.ref-box {
  display: flex;
  align-items: center;
  gap: 10px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(201, 166, 73, 0.3);
  border-radius: var(--r-md);
  padding: 10px 18px;
}
.ref-code {
  font-family: var(--font-mono);
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--gold-light);
  font-variant-numeric: tabular-nums;
}
.btn-copy {
  background: rgba(201, 166, 73, 0.18);
  border: 1px solid rgba(201, 166, 73, 0.3);
  border-radius: var(--r-sm);
  color: var(--gold-light);
  font-size: 1rem;
  padding: 4px 10px;
  cursor: pointer;
  transition: background 0.15s;
}
.btn-copy:hover {
  background: rgba(201, 166, 73, 0.32);
}
.btn-copy.copied {
  background: rgba(74, 119, 82, 0.3);
  color: #9ecfa8;
  border-color: rgba(74, 119, 82, 0.4);
}
.hero-note {
  font-size: 0.84rem;
  color: rgba(251, 248, 242, 0.6);
}
.hero-note strong {
  color: rgba(251, 248, 242, 0.85);
}

/* ── Content grid ── */
.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  align-items: start;
  margin-bottom: 28px;
}

/* ── Card ── */
.card {
  background: var(--bone);
  border-radius: var(--r-lg);
  border: 1px solid var(--line-strong);
  overflow: hidden;
  box-shadow: var(--shadow-1);
}
.card-title {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-weight: 700;
  color: var(--gold-d);
  padding: 16px 20px 12px;
  border-bottom: 1px solid var(--line);
}

/* ── Stay card ── */
.stay-hero-img {
  height: 130px;
  background: linear-gradient(135deg, var(--navy-2), var(--navy-d));
  position: relative;
  overflow: hidden;
}
.stay-hero-img::after {
  content: "302 · Deluxe Double";
  position: absolute;
  bottom: 10px;
  left: 14px;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: rgba(251, 248, 242, 0.6);
  font-weight: 600;
}
.stay-rows {
  padding: 4px 0;
}
.stay-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 9px 20px;
  border-bottom: 1px solid var(--line);
  gap: 12px;
}
.stay-row:last-child {
  border-bottom: none;
}
.s-label {
  font-size: 0.8rem;
  color: var(--warm-gray);
  font-weight: 500;
  flex-shrink: 0;
}
.s-val {
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--ink);
  text-align: right;
}
.s-val.mono {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-variant-numeric: tabular-nums;
}
.s-val.strong {
  font-weight: 700;
  color: var(--navy-d);
  font-size: 1rem;
}
.stay-row--total {
  background: var(--cream);
}

/* ── Right column ── */
.right-col {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* ── Checklist ── */
.checklist {
  list-style: none;
  padding: 8px 0;
}
.check-item {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 12px 20px;
  border-bottom: 1px solid var(--line);
}
.check-item:last-child {
  border-bottom: none;
}
.ci-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--success);
  color: #fff;
  font-size: 0.8rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 1px;
}
.ci-icon.ci-pending {
  background: var(--cream-2);
  color: var(--warm-gray);
  border: 2px solid var(--line-strong);
}
.ci-body {
  flex: 1;
  min-width: 0;
}
.ci-body strong {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ink);
  display: block;
  margin-bottom: 2px;
}
.ci-body p {
  font-size: 0.8rem;
  color: var(--warm-gray);
  line-height: 1.4;
}
.btn-toggle-cal {
  font-family: inherit;
  font-size: 0.78rem;
  font-weight: 600;
  padding: 5px 14px;
  background: var(--navy);
  color: var(--bone);
  border: none;
  border-radius: 999px;
  cursor: pointer;
  flex-shrink: 0;
  margin-top: 2px;
}
.btn-toggle-cal:hover {
  background: var(--navy-2);
}
.btn-toggle-cal.is-open {
  background: var(--cream-2);
  color: var(--ink-2);
}
.cal-actions {
  margin-top: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.btn-cal {
  font-family: inherit;
  font-size: 0.78rem;
  font-weight: 600;
  padding: 6px 12px;
  background: var(--cream);
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  cursor: pointer;
  color: var(--ink-2);
}
.btn-cal:hover {
  background: var(--cream-2);
  border-color: var(--navy-2);
  color: var(--navy-d);
}

/* ── Address card ── */
.map-placeholder {
  height: 120px;
  background: radial-gradient(circle at 35% 45%, rgba(201, 166, 73, 0.18), transparent 40%),
    linear-gradient(160deg, #c8d4e8, #a8bcda);
  display: flex;
  align-items: center;
  justify-content: center;
}
.map-pin {
  text-align: center;
  font-size: 1.6rem;
  line-height: 1;
  color: var(--navy-d);
  filter: drop-shadow(0 2px 4px rgba(15, 29, 54, 0.2));
}
.map-pin span {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--navy-2);
  text-transform: uppercase;
}
address {
  font-style: normal;
  font-size: 0.88rem;
  line-height: 1.7;
  color: var(--ink-2);
  padding: 14px 20px;
}
address strong {
  font-weight: 700;
  color: var(--ink);
  display: block;
  margin-bottom: 2px;
}
address a {
  color: var(--navy-2);
  font-weight: 600;
  text-decoration: none;
}
address a:hover {
  text-decoration: underline;
}

/* ── Policy ── */
.policy-preview {
  font-size: 0.86rem;
  color: var(--ink-2);
  padding: 12px 20px 4px;
}
.btn-policy {
  display: flex;
  align-items: center;
  gap: 6px;
  background: none;
  border: none;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--navy-2);
  padding: 8px 20px 14px;
  cursor: pointer;
  text-align: left;
}
.btn-policy:hover {
  color: var(--navy-d);
}
.policy-detail {
  background: var(--cream);
  border-top: 1px solid var(--line);
  padding: 14px 20px 16px;
  font-size: 0.84rem;
  color: var(--ink-2);
  line-height: 1.6;
}
.policy-detail p {
  margin-bottom: 10px;
}
.policy-detail ul {
  padding-left: 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* ── CTA bar ── */
.cta-bar {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}
.btn-manage,
.btn-primary {
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  padding: 13px 28px;
  border-radius: 999px;
  cursor: pointer;
}
.btn-manage {
  background: transparent;
  border: 1px solid var(--line-strong);
  color: var(--ink-2);
}
.btn-manage:hover {
  background: var(--bone);
  border-color: var(--navy-2);
  color: var(--navy-d);
}
.btn-primary {
  background: var(--navy);
  color: var(--bone);
  border: none;
}
.btn-primary:hover {
  background: var(--navy-d);
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 22px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: 0 10px 30px rgba(22, 30, 44, 0.25);
  z-index: 200;
  white-space: nowrap;
}

/* ── Responsive ── */
@media (max-width: 960px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 560px) {
  .page {
    padding: 24px 12px 40px;
  }
  .hero {
    padding: 28px 16px 24px;
  }
  .hero h1 {
    font-size: 2rem;
  }
  .ref-code {
    font-size: 1.1rem;
  }
  .topbar {
    padding: 0 16px;
  }
  .topnav {
    display: none;
  }
}

/* ── Honor [hidden] over display (overlay/panel toggle fix) ── */
.cal-actions[hidden] {
  display: none;
}

