(function () {
  "use strict";

  /* ---------- toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2400);
  }

  /* ---------- animated KPI counters ---------- */
  function animateCount(el) {
    var target = parseFloat(el.getAttribute("data-count")) || 0;
    var prefix = el.getAttribute("data-prefix") || "";
    var isMoney = el.getAttribute("data-money") === "1";
    var duration = 1100;
    var start = performance.now();

    function fmt(n) {
      if (isMoney) return prefix + Math.round(n).toLocaleString("en-US");
      return prefix + Math.round(n).toLocaleString("en-US");
    }

    function frame(now) {
      var p = Math.min((now - start) / duration, 1);
      // easeOutExpo
      var eased = p === 1 ? 1 : 1 - Math.pow(2, -10 * p);
      el.textContent = fmt(target * eased);
      if (p < 1) requestAnimationFrame(frame);
      else el.textContent = fmt(target);
    }
    requestAnimationFrame(frame);
  }

  var kpiVals = document.querySelectorAll(".kpi-value");
  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(
      function (entries, obs) {
        entries.forEach(function (e) {
          if (e.isIntersecting) {
            animateCount(e.target);
            obs.unobserve(e.target);
          }
        });
      },
      { threshold: 0.4 }
    );
    kpiVals.forEach(function (el) { io.observe(el); });
  } else {
    kpiVals.forEach(animateCount);
  }

  /* ---------- listing filters ---------- */
  var chips = document.querySelectorAll(".chip");
  var listings = document.querySelectorAll("#listings .listing");
  var emptyState = document.getElementById("emptyState");

  function applyFilter(filter) {
    var shown = 0;
    listings.forEach(function (li) {
      var match = filter === "all" || li.getAttribute("data-status") === filter;
      li.style.display = match ? "" : "none";
      if (match) shown++;
    });
    if (emptyState) emptyState.hidden = shown !== 0;
  }

  chips.forEach(function (chip) {
    chip.addEventListener("click", function () {
      chips.forEach(function (c) {
        c.classList.remove("is-on");
        c.setAttribute("aria-selected", "false");
      });
      chip.classList.add("is-on");
      chip.setAttribute("aria-selected", "true");
      var f = chip.getAttribute("data-filter");
      applyFilter(f);
      toast(
        f === "all"
          ? "Showing all listings"
          : "Filtered to " + f + " listings"
      );
    });
  });

  /* ---------- tasks: toggle completion ---------- */
  var taskList = document.getElementById("tasks");
  var taskCountEl = document.getElementById("taskCount");

  function syncTask(input) {
    var li = input.closest(".task");
    if (!li) return;
    var due = li.querySelector(".due");
    if (input.checked) {
      li.classList.add("is-done");
      if (due) {
        if (due.getAttribute("data-orig") === null)
          due.setAttribute("data-orig", due.textContent);
        due.textContent = "Done";
      }
    } else {
      li.classList.remove("is-done");
      if (due && due.getAttribute("data-orig"))
        due.textContent = due.getAttribute("data-orig");
    }
  }

  function updateTaskCount() {
    var inputs = taskList.querySelectorAll('input[type="checkbox"]');
    var done = 0;
    inputs.forEach(function (i) { if (i.checked) done++; });
    if (taskCountEl) taskCountEl.textContent = done + "/" + inputs.length + " done";
  }

  if (taskList) {
    // initialise data-orig + state
    taskList.querySelectorAll(".task").forEach(function (li) {
      var due = li.querySelector(".due");
      var input = li.querySelector('input[type="checkbox"]');
      if (due && due.getAttribute("data-orig") === null) {
        due.setAttribute("data-orig", input && input.checked ? "Done" : due.textContent);
      }
      if (input && input.checked) li.classList.add("is-done");
    });

    taskList.addEventListener("change", function (e) {
      var input = e.target;
      if (input && input.type === "checkbox") {
        syncTask(input);
        updateTaskCount();
        if (input.checked) {
          var label = input.closest(".task").querySelector(".task-text strong");
          toast("Completed: " + (label ? label.textContent : "task"));
        }
      }
    });
    updateTaskCount();
  }

  /* ---------- new listing button ---------- */
  var newBtn = document.getElementById("newListingBtn");
  if (newBtn) {
    newBtn.addEventListener("click", function () {
      toast("New listing draft started");
    });
  }
})();

snippets.css:
:root {
  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;

  --gold: #b08d57;
  --gold-d: #8c6d3f;
  --gold-soft: #efe2cf;
  --rose: #c9a78f;
  --rose-soft: #f3e6dc;

  --ink: #1c1814;
  --ink-2: #3d362f;
  --muted: #8a7d70;

  --cream: #f7f1e8;
  --bg: #faf6ef;
  --white: #ffffff;

  --line: rgba(28, 24, 20, 0.1);
  --line-2: rgba(28, 24, 20, 0.18);

  --ok: #5f8a6b;
  --warn: #c08a3e;
  --danger: #b3503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --shadow-sm: 0 1px 2px rgba(28, 24, 20, 0.05), 0 6px 18px rgba(28, 24, 20, 0.06);
  --shadow-md: 0 10px 30px rgba(28, 24, 20, 0.1);
  --shadow-lg: 0 24px 60px rgba(28, 24, 20, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 84px;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1,
h2,
h3 {
  font-family: var(--serif);
  font-weight: 600;
  margin: 0;
}

em {
  font-style: italic;
}

.page {
  max-width: 920px;
  margin: 0 auto;
  padding: 0 24px 64px;
}

.eyebrow {
  font-size: 0.72rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--gold-d);
  font-weight: 600;
  margin: 0;
}

.eyebrow--light {
  color: var(--gold-soft);
}

.dot {
  color: var(--muted);
  margin: 0 0.25rem;
}

/* ── Buttons ───────────────────────────── */
.btn {
  font-family: var(--sans);
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 0.62rem 1.25rem;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  transition: transform 0.18s ease, background 0.18s ease, color 0.18s ease,
    border-color 0.18s ease, box-shadow 0.18s ease;
  white-space: nowrap;
}

.btn:active {
  transform: translateY(1px);
}

.btn--ghost {
  background: transparent;
  border-color: var(--line-2);
  color: var(--ink);
}

.btn--ghost:hover {
  border-color: var(--gold);
  color: var(--gold-d);
  background: var(--white);
}

.btn--solid {
  background: var(--ink);
  color: var(--cream);
}

.btn--solid:hover {
  background: var(--gold-d);
  box-shadow: var(--shadow-md);
}

.btn--lg {
  padding: 0.85rem 1.8rem;
  font-size: 0.9rem;
}

.btn--on-dark {
  color: var(--cream);
  border-color: rgba(247, 241, 232, 0.3);
}

.btn--on-dark:hover {
  background: rgba(247, 241, 232, 0.08);
  border-color: var(--gold);
  color: var(--white);
}

:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ── Masthead ──────────────────────────── */
.masthead {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 26px 0 22px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin-right: auto;
}

.brand__mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid var(--gold);
  color: var(--gold-d);
  font-family: var(--serif);
  font-weight: 700;
  font-size: 0.95rem;
  letter-spacing: 0.04em;
}

.brand__name {
  font-family: var(--serif);
  font-size: 1.4rem;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.masthead__nav {
  display: flex;
  gap: 1.4rem;
}

.masthead__nav a {
  color: var(--ink-2);
  text-decoration: none;
  font-size: 0.86rem;
  font-weight: 500;
  position: relative;
  padding-bottom: 2px;
}

.masthead__nav a::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 0;
  height: 1px;
  background: var(--gold);
  transition: width 0.2s ease;
}

.masthead__nav a:hover {
  color: var(--ink);
}

.masthead__nav a:hover::after {
  width: 100%;
}

/* ── Hero ──────────────────────────────── */
.hero {
  text-align: center;
  padding: 30px 0 36px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  position: relative;
}

.hero::before,
.hero::after {
  content: "";
  position: absolute;
  left: 50%;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--gold);
  transform: translateX(-50%) rotate(45deg);
}

.hero::before {
  top: -3px;
}

.hero::after {
  bottom: -3px;
}

.hero__title {
  font-size: clamp(2.6rem, 7vw, 4rem);
  line-height: 1.04;
  margin: 0.5rem 0 0.7rem;
  letter-spacing: -0.01em;
}

.hero__lede {
  max-width: 540px;
  margin: 0 auto;
  color: var(--ink-2);
  font-size: 1rem;
}

.hero__lede em {
  color: var(--gold-d);
  font-weight: 500;
}

.hero__meta {
  margin-top: 1.1rem;
  font-size: 0.82rem;
  color: var(--muted);
  letter-spacing: 0.02em;
}

.hero__meta strong {
  color: var(--ink-2);
  font-weight: 600;
}

/* ── Section nav (sticky) ──────────────── */
.sectionnav {
  position: sticky;
  top: 0;
  z-index: 20;
  background: color-mix(in srgb, var(--bg) 88%, transparent);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  margin: 0 -24px 8px;
  padding: 10px 24px;
  border-bottom: 1px solid var(--line);
}

.sectionnav__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 0.5rem;
  justify-content: center;
  flex-wrap: wrap;
}

.sectionnav__btn {
  font-family: var(--sans);
  background: transparent;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  padding: 0.42rem 1rem;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--ink-2);
  cursor: pointer;
  transition: all 0.18s ease;
}

.sectionnav__btn:hover {
  border-color: var(--gold);
  color: var(--gold-d);
}

.sectionnav__btn.is-active {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--cream);
}

/* ── Menu groups ───────────────────────── */
.menu {
  padding-top: 18px;
}

.group {
  padding: 30px 0;
  border-bottom: 1px solid var(--line);
  scroll-margin-top: 80px;
}

.group:last-child {
  border-bottom: none;
}

.group__head {
  display: flex;
  align-items: baseline;
  gap: 1rem;
  margin-bottom: 1.1rem;
}

.group__title {
  font-size: clamp(1.7rem, 4vw, 2.2rem);
  letter-spacing: 0.01em;
  position: relative;
  padding-left: 1.1rem;
}

.group__title::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 4px;
  height: 1.2em;
  border-radius: 2px;
  background: linear-gradient(var(--gold), var(--gold-d));
}

.group__note {
  margin: 0;
  font-size: 0.8rem;
  color: var(--muted);
  font-style: italic;
}

.rows {
  list-style: none;
  margin: 0;
  padding: 0;
}

/* ── Service row ───────────────────────── */
.row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  grid-template-areas: "main time price";
  align-items: baseline;
  column-gap: 0.9rem;
  padding: 0.85rem 0.7rem 0.85rem 0.7rem;
  border-radius: var(--r-sm);
  cursor: pointer;
  transition: background 0.16s ease, box-shadow 0.16s ease;
  position: relative;
}

.row:hover {
  background: var(--white);
  box-shadow: var(--shadow-sm);
}

.row.is-selected {
  background: var(--rose-soft);
}

.row.is-selected::before {
  content: "✓";
  position: absolute;
  left: -10px;
  top: 50%;
  transform: translateY(-50%);
  width: 20px;
  height: 20px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--gold-d);
  color: var(--white);
  font-size: 0.7rem;
  font-weight: 700;
}

.row__main {
  grid-area: main;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
}

.row__name {
  font-family: var(--serif);
  font-size: 1.32rem;
  font-weight: 600;
  color: var(--ink);
  line-height: 1.15;
}

.row__desc {
  font-size: 0.82rem;
  color: var(--muted);
  line-height: 1.35;
}

/* dotted leader between name block and price */
.row__leader {
  grid-area: main;
  align-self: flex-end;
  height: 0;
  margin: 0 0.5rem 0.35rem 0.5rem;
  border-bottom: 1.5px dotted var(--line-2);
  flex: 1;
  display: none;
}

.row__time {
  grid-area: time;
  font-size: 0.74rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
  white-space: nowrap;
}

.row__price {
  grid-area: price;
  font-family: var(--serif);
  font-size: 1.3rem;
  font-weight: 600;
  color: var(--gold-d);
  white-space: nowrap;
  min-width: 78px;
  text-align: right;
}

.row__price em {
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  font-family: var(--sans);
  font-weight: 600;
  margin-right: 0.2rem;
}

/* leader line via pseudo on the name row, full-width version */
.row__main {
  position: relative;
}

.row__name {
  display: inline;
  position: relative;
}

/* ── Estimate bar ──────────────────────── */
.estimate {
  position: sticky;
  bottom: 16px;
  z-index: 25;
  margin: 24px 0 0;
}

.estimate__inner {
  display: flex;
  align-items: center;
  gap: 1rem;
  background: var(--ink);
  color: var(--cream);
  border-radius: var(--r-lg);
  padding: 0.85rem 0.85rem 0.85rem 1.4rem;
  box-shadow: var(--shadow-lg);
  border: 1px solid rgba(247, 241, 232, 0.08);
}

.estimate__copy {
  display: flex;
  flex-direction: column;
  margin-right: auto;
  min-width: 0;
}

.estimate__label {
  font-size: 0.68rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold-soft);
  font-weight: 600;
}

.estimate__count {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--white);
}

.estimate__total {
  font-family: var(--serif);
  font-size: 1.8rem;
  font-weight: 600;
  color: var(--gold-soft);
  white-space: nowrap;
}

.estimate__total .from {
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rose);
  font-family: var(--sans);
  margin-right: 0.25rem;
}

.estimate__clear {
  background: transparent;
  border: none;
  color: var(--rose);
  font-family: var(--sans);
  font-size: 0.78rem;
  font-weight: 600;
  cursor: pointer;
  padding: 0.4rem 0.3rem;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.estimate__clear:hover {
  color: var(--gold-soft);
}

/* ── CTA band ──────────────────────────── */
.cta {
  margin: 48px -24px 0;
  padding: 56px 24px;
  background: radial-gradient(
      120% 100% at 50% 0%,
      #2a231b 0%,
      var(--ink) 60%
    );
  color: var(--cream);
  text-align: center;
  border-radius: var(--r-lg);
  position: relative;
  overflow: hidden;
}

.cta__rule {
  width: 64px;
  height: 1px;
  background: var(--gold);
  margin: 0 auto 1.4rem;
}

.cta__title {
  font-size: clamp(2rem, 6vw, 3rem);
  margin: 0.5rem 0 0.7rem;
  color: var(--white);
}

.cta__lede {
  max-width: 460px;
  margin: 0 auto 1.8rem;
  color: var(--gold-soft);
  font-size: 0.95rem;
}

.cta__actions {
  display: flex;
  gap: 0.8rem;
  justify-content: center;
  flex-wrap: wrap;
}

/* ── Footer ────────────────────────────── */
.footer {
  margin-top: 32px;
  text-align: center;
  font-size: 0.78rem;
  color: var(--muted);
  letter-spacing: 0.03em;
}

/* ── Toast ─────────────────────────────── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 16px);
  background: var(--ink);
  color: var(--cream);
  padding: 0.85rem 1.3rem;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 500;
  box-shadow: var(--shadow-lg);
  border: 1px solid rgba(176, 141, 87, 0.4);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  z-index: 60;
  max-width: calc(100vw - 32px);
  text-align: center;
}

.toast::before {
  content: "✦";
  color: var(--gold);
  margin-right: 0.5rem;
}

.toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
  pointer-events: auto;
}

/* ── Responsive ────────────────────────── */
@media (max-width: 520px) {
  .page {
    padding: 0 16px 48px;
  }

  .masthead {
    flex-wrap: wrap;
    gap: 0.7rem;
  }

  .masthead__nav {
    order: 3;
    width: 100%;
    justify-content: space-between;
    gap: 0.6rem;
    overflow-x: auto;
  }

  .sectionnav {
    margin: 0 -16px 8px;
    padding: 10px 16px;
  }

  .sectionnav__list {
    justify-content: flex-start;
    flex-wrap: nowrap;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .sectionnav__list::-webkit-scrollbar {
    display: none;
  }

  .group__head {
    flex-direction: column;
    gap: 0.2rem;
  }

  .row {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      "main price"
      "time price";
    column-gap: 0.7rem;
    row-gap: 0.1rem;
    padding-left: 0.4rem;
    padding-right: 0.4rem;
  }

  .row__name {
    font-size: 1.18rem;
  }

  .row__price {
    font-size: 1.15rem;
    min-width: 64px;
  }

  .estimate__inner {
    flex-wrap: wrap;
    padding: 0.9rem 1rem;
    gap: 0.7rem;
  }

  .estimate__total {
    order: 2;
  }

  .estimate__copy {
    order: 1;
  }

  #estimate-book {
    order: 3;
    flex: 1;
  }

  .estimate__clear {
    order: 4;
  }

  .cta {
    margin: 36px -16px 0;
    padding: 44px 18px;
  }

  .btn--lg {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

