(function () {
  "use strict";

  const groups = Array.from(document.querySelectorAll(".group"));
  const rows = Array.from(document.querySelectorAll(".row"));
  const navList = document.getElementById("section-nav");
  const estimate = document.getElementById("estimate");
  const estCount = document.getElementById("estimate-count");
  const estTotal = document.getElementById("estimate-total");
  const estBook = document.getElementById("estimate-book");
  const estClear = document.getElementById("estimate-clear");

  /* ── Toast helper ──────────────────────────── */
  const toastEl = document.getElementById("toast");
  let toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("is-visible");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => {
      toastEl.classList.remove("is-visible");
    }, 2600);
  }

  /* ── Build sticky section nav from groups ──── */
  groups.forEach((g) => {
    const li = document.createElement("li");
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "sectionnav__btn";
    btn.textContent = g.dataset.group;
    btn.dataset.target = g.id;
    btn.addEventListener("click", () => {
      const target = document.getElementById(g.id);
      target.scrollIntoView({ behavior: "smooth", block: "start" });
      target.focus({ preventScroll: true });
    });
    li.appendChild(btn);
    navList.appendChild(li);
  });
  const navBtns = Array.from(navList.querySelectorAll(".sectionnav__btn"));

  /* ── Scroll-spy: highlight active section ──── */
  const spy = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          const id = entry.target.id;
          navBtns.forEach((b) =>
            b.classList.toggle("is-active", b.dataset.target === id)
          );
        }
      });
    },
    { rootMargin: "-45% 0px -50% 0px", threshold: 0 }
  );
  groups.forEach((g) => spy.observe(g));

  /* ── Selection / running estimate ──────────── */
  const selected = new Map(); // name -> { price, from }

  function fmt(n) {
    return "$" + n.toLocaleString("en-US");
  }

  function renderEstimate() {
    const count = selected.size;
    if (count === 0) {
      estimate.hidden = true;
      return;
    }
    estimate.hidden = false;

    let total = 0;
    let hasFrom = false;
    selected.forEach((v) => {
      total += v.price;
      if (v.from) hasFrom = true;
    });

    estCount.textContent =
      count + (count === 1 ? " service selected" : " services selected");
    estTotal.innerHTML = hasFrom
      ? '<span class="from">from</span>' + fmt(total)
      : fmt(total);
  }

  function toggleRow(row) {
    const name = row.dataset.name.replace(/&amp;/g, "&");
    const price = parseInt(row.dataset.price, 10) || 0;
    const from = row.dataset.from === "true";

    if (selected.has(name)) {
      selected.delete(name);
      row.classList.remove("is-selected");
      row.setAttribute("aria-pressed", "false");
    } else {
      selected.set(name, { price, from });
      row.classList.add("is-selected");
      row.setAttribute("aria-pressed", "true");
      toast(name + " added to your visit");
    }
    renderEstimate();
  }

  rows.forEach((row) => {
    row.setAttribute("role", "button");
    row.setAttribute("tabindex", "0");
    row.setAttribute("aria-pressed", "false");
    const label = row.querySelector(".row__name").textContent.trim();
    const price = row.querySelector(".row__price").textContent.trim();
    row.setAttribute("aria-label", label + ", " + price + ". Add to visit.");

    row.addEventListener("click", () => toggleRow(row));
    row.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        toggleRow(row);
      }
    });
  });

  estClear.addEventListener("click", () => {
    selected.clear();
    rows.forEach((r) => {
      r.classList.remove("is-selected");
      r.setAttribute("aria-pressed", "false");
    });
    renderEstimate();
    toast("Selection cleared");
  });

  estBook.addEventListener("click", () => {
    const count = selected.size;
    if (!count) return;
    toast(
      "Reserved " +
        count +
        (count === 1 ? " service" : " services") +
        " with Aria Vance — see you soon"
    );
    selected.clear();
    rows.forEach((r) => {
      r.classList.remove("is-selected");
      r.setAttribute("aria-pressed", "false");
    });
    renderEstimate();
  });

  /* ── Generic booking buttons ───────────────── */
  document.querySelectorAll("[data-book]").forEach((el) => {
    el.addEventListener("click", () => {
      toast("Booking request sent for " + el.dataset.book + " — we'll confirm shortly");
    });
  });

  renderEstimate();
})();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;

  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;

  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;

  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;

  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);

  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;

  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;

  --sh-sm: 0 1px 2px rgba(22, 48, 42, 0.06), 0 1px 1px rgba(22, 48, 42, 0.04);
  --sh-md: 0 10px 24px -12px rgba(22, 48, 42, 0.22), 0 2px 6px rgba(22, 48, 42, 0.06);
  --sh-lg: 0 28px 60px -28px rgba(22, 48, 42, 0.34), 0 6px 16px rgba(22, 48, 42, 0.08);

  --serif: "Cormorant Garamond", Georgia, serif;
  --sans: "Inter", system-ui, sans-serif;
}

* {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--sans);
  line-height: 1.55;
  color: var(--ink);
  background:
    radial-gradient(120% 80% at 100% 0%, rgba(176, 141, 87, 0.08), transparent 60%),
    radial-gradient(120% 80% at 0% 100%, rgba(31, 61, 52, 0.06), transparent 55%),
    var(--ivory);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.shell {
  max-width: 1140px;
  margin: 0 auto;
  padding: 28px 24px 64px;
}

/* ===== Masthead ===== */
.masthead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: var(--r-sm);
  background: linear-gradient(150deg, var(--green-700), var(--green-d));
  color: var(--brass-50);
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: 0.02em;
  border: 1px solid rgba(176, 141, 87, 0.4);
  box-shadow: var(--sh-sm);
}

.brand-kicker {
  margin: 0;
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--green-d);
  letter-spacing: 0.01em;
}

.brand-sub {
  margin: 0;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--muted);
}

.masthead-tag {
  margin: 0;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--brass-d);
  padding: 6px 12px;
  border: 1px solid var(--line-2);
  border-radius: 999px;
  background: var(--brass-50);
}

/* ===== Hero ===== */
.hero {
  padding: 38px 0 30px;
  max-width: 640px;
}

.hero-eyebrow {
  margin: 0 0 8px;
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--brass-d);
}

.hero-title {
  margin: 0 0 14px;
  font-family: var(--serif);
  font-weight: 700;
  font-size: clamp(2.4rem, 6vw, 3.6rem);
  line-height: 1.04;
  color: var(--green-d);
}

.hero-lede {
  margin: 0;
  font-size: 1.02rem;
  color: var(--ink-2);
}

/* ===== Layout grid ===== */
.layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
  align-items: start;
}

.listing {
  grid-column: 1 / 2;
}

.inputs {
  grid-column: 2 / 3;
  grid-row: 1 / 3;
}

.results {
  grid-column: 1 / 2;
}

/* ===== Card base ===== */
.card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-md);
}

.card-title {
  margin: 0;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.5rem;
  color: var(--green-d);
}

/* ===== Listing / photo ===== */
.listing {
  overflow: hidden;
}

.photo {
  position: relative;
  aspect-ratio: 16 / 10;
  background:
    radial-gradient(140% 120% at 78% 18%, rgba(255, 244, 222, 0.85), transparent 45%),
    linear-gradient(165deg, #3a5b4f 0%, #2a463c 38%, #1f3d34 70%, #16302a 100%);
}

.photo::before {
  /* sky / glazing reflection */
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(120deg, rgba(176, 141, 87, 0.28) 0%, transparent 34%),
    repeating-linear-gradient(
      105deg,
      rgba(255, 255, 255, 0.05) 0 2px,
      transparent 2px 16px
    );
}

.photo::after {
  /* architectural massing silhouette */
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 58%;
  background:
    linear-gradient(180deg, transparent, rgba(15, 33, 28, 0.55)),
    linear-gradient(90deg, #243f36 0 38%, #1c352d 38% 64%, #2a473c 64% 100%);
  clip-path: polygon(0 36%, 22% 30%, 22% 10%, 46% 10%, 46% 30%, 70% 22%, 100% 40%, 100% 100%, 0 100%);
}

.photo-badge {
  position: absolute;
  top: 14px;
  z-index: 2;
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  padding: 6px 11px;
  border-radius: 999px;
  box-shadow: var(--sh-sm);
}

.photo-badge--status {
  left: 14px;
  background: var(--brass);
  color: #2a1e0c;
  border: 1px solid var(--brass-d);
}

.photo-badge--price {
  right: 14px;
  background: rgba(255, 253, 248, 0.94);
  color: var(--green-d);
  border: 1px solid var(--line-2);
}

.photo-caption {
  position: absolute;
  left: 16px;
  bottom: 14px;
  z-index: 2;
  color: var(--paper);
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.4);
}

.photo-caption-line {
  display: block;
  font-family: var(--serif);
  font-weight: 600;
  font-size: 1.35rem;
  line-height: 1.1;
}

.photo-caption-sub {
  display: block;
  font-size: 0.78rem;
  letter-spacing: 0.06em;
  opacity: 0.9;
}

.listing-body {
  padding: 18px 20px 20px;
}

.spec-row {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  margin: 0 0 14px;
  padding: 0 0 14px;
  list-style: none;
  border-bottom: 1px solid var(--line);
}

.spec-row li {
  font-size: 0.82rem;
  color: var(--muted);
}

.spec-row strong {
  display: block;
  font-family: var(--serif);
  font-size: 1.3rem;
  color: var(--green-d);
  font-weight: 600;
}

.listing-blurb {
  margin: 0 0 16px;
  font-size: 0.92rem;
  color: var(--ink-2);
}

.agent {
  display: flex;
  align-items: center;
  gap: 12px;
}

.agent-avatar {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--green-50);
  color: var(--green-d);
  font-weight: 600;
  font-size: 0.82rem;
  border: 1px solid var(--line-2);
}

.agent-name {
  display: block;
  font-weight: 600;
  font-size: 0.88rem;
  color: var(--ink);
}

.agent-role {
  display: block;
  font-size: 0.74rem;
  color: var(--muted);
}

/* ===== Inputs ===== */
.inputs {
  padding: 24px 22px 22px;
}

.inputs .card-title {
  margin-bottom: 18px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.field {
  margin-bottom: 16px;
}

.field-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.field label {
  display: block;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 7px;
}

.field-aside {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--brass-d);
}

.control {
  position: relative;
  display: flex;
  align-items: center;
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: var(--r-md);
  box-shadow: var(--sh-sm);
  transition: border-color 0.16s ease, box-shadow 0.16s ease;
}

.control:focus-within {
  border-color: var(--green-700);
  box-shadow: 0 0 0 3px rgba(38, 73, 62, 0.14);
}

.control input,
.control select {
  width: 100%;
  border: 0;
  background: transparent;
  font-family: var(--sans);
  font-size: 1rem;
  font-weight: 600;
  color: var(--ink);
  padding: 11px 12px;
  outline: none;
  appearance: none;
}

.control select {
  cursor: pointer;
  background-image:
    linear-gradient(45deg, transparent 50%, var(--green-700) 50%),
    linear-gradient(135deg, var(--green-700) 50%, transparent 50%);
  background-position: calc(100% - 18px) 50%, calc(100% - 13px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 34px;
}

.control .prefix,
.control .suffix {
  font-weight: 600;
  color: var(--muted);
  font-size: 0.95rem;
}

.control .prefix {
  padding-left: 12px;
}

.control.money input {
  padding-left: 6px;
}

.control .suffix {
  padding-right: 12px;
}

.control.percent input {
  padding-right: 4px;
}

/* hide number spinners */
.control input[type="number"]::-webkit-outer-spin-button,
.control input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}
.control input[type="number"] {
  -moz-appearance: textfield;
}

.dual {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 10px;
}

.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

/* range slider */
.range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  margin: 12px 0 2px;
  border-radius: 999px;
  background: var(--green-50);
  outline: none;
  cursor: pointer;
}

.range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: linear-gradient(150deg, var(--brass), var(--brass-d));
  border: 2px solid var(--paper);
  box-shadow: var(--sh-sm);
  cursor: pointer;
}

.range::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: linear-gradient(150deg, var(--brass), var(--brass-d));
  border: 2px solid var(--paper);
  box-shadow: var(--sh-sm);
  cursor: pointer;
}

.range:focus-visible {
  box-shadow: 0 0 0 3px rgba(176, 141, 87, 0.3);
}

.reset-btn {
  margin-top: 6px;
  width: 100%;
  padding: 11px 14px;
  font-family: var(--sans);
  font-size: 0.84rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--green-d);
  background: var(--green-50);
  border: 1px solid var(--line-2);
  border-radius: var(--r-md);
  cursor: pointer;
  transition: background 0.16s ease, transform 0.08s ease;
}

.reset-btn:hover {
  background: #dde8e0;
}

.reset-btn:active {
  transform: translateY(1px);
}

.reset-btn:focus-visible {
  outline: 2px solid var(--green-700);
  outline-offset: 2px;
}

/* ===== Results ===== */
.results {
  padding: 24px 22px 22px;
  background:
    linear-gradient(180deg, rgba(38, 73, 62, 0.04), transparent 30%),
    var(--paper);
}

.results-head {
  text-align: center;
  padding-bottom: 8px;
}

.results-label {
  margin: 0;
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--muted);
}

.results-total {
  margin: 4px 0 0;
  font-family: var(--serif);
  font-weight: 700;
  font-size: clamp(2.6rem, 7vw, 3.4rem);
  line-height: 1;
  color: var(--green-d);
  font-variant-numeric: tabular-nums;
}

.donut-wrap {
  position: relative;
  width: 200px;
  margin: 14px auto 18px;
}

.donut {
  width: 200px;
  height: 200px;
  transform: rotate(-90deg);
}

.donut-track {
  fill: none;
  stroke: var(--green-50);
  stroke-width: 13;
}

.donut-seg {
  fill: none;
  stroke-width: 13;
  stroke-linecap: butt;
  transition: stroke-dasharray 0.55s cubic-bezier(0.22, 1, 0.36, 1),
    stroke-dashoffset 0.55s cubic-bezier(0.22, 1, 0.36, 1);
}

.seg-pi  { stroke: var(--green); }
.seg-tax { stroke: var(--brass); }
.seg-ins { stroke: var(--green-700); }
.seg-hoa { stroke: var(--warn); }

.donut-center {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  text-align: center;
  pointer-events: none;
}

.donut-center-num {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.6rem;
  color: var(--green-d);
  font-variant-numeric: tabular-nums;
}

.donut-center-cap {
  display: block;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--muted);
}

.legend {
  list-style: none;
  margin: 0 0 18px;
  padding: 0;
  display: grid;
  gap: 2px;
}

.legend li {
  display: grid;
  grid-template-columns: 14px 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 9px 4px;
  border-bottom: 1px solid var(--line);
}

.legend li:last-child {
  border-bottom: 0;
}

.swatch {
  width: 12px;
  height: 12px;
  border-radius: 3px;
}

.sw-pi  { background: var(--green); }
.sw-tax { background: var(--brass); }
.sw-ins { background: var(--green-700); }
.sw-hoa { background: var(--warn); }

.legend-label {
  font-size: 0.88rem;
  color: var(--ink-2);
}

.legend-val {
  font-weight: 600;
  font-size: 0.92rem;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.summary {
  margin: 0;
  padding: 16px;
  display: grid;
  gap: 10px;
  background: var(--green-50);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
}

.summary > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.summary dt {
  margin: 0;
  font-size: 0.84rem;
  color: var(--green-700);
}

.summary dd {
  margin: 0;
  font-weight: 600;
  font-size: 0.96rem;
  color: var(--green-d);
  font-variant-numeric: tabular-nums;
}

.results-note {
  margin: 14px 0 0;
  font-size: 0.74rem;
  color: var(--muted);
  text-align: center;
}

/* ===== Toast ===== */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 16px);
  background: var(--green-d);
  color: var(--brass-50);
  font-size: 0.86rem;
  font-weight: 500;
  padding: 11px 18px;
  border-radius: 999px;
  border: 1px solid rgba(176, 141, 87, 0.4);
  box-shadow: var(--sh-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  z-index: 50;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ===== Responsive ===== */
@media (max-width: 880px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .listing,
  .inputs,
  .results {
    grid-column: 1 / -1;
    grid-row: auto;
  }
}

@media (max-width: 520px) {
  .shell {
    padding: 20px 16px 48px;
  }
  .masthead {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }
  .hero {
    padding: 26px 0 22px;
  }
  .grid-2 {
    grid-template-columns: 1fr;
  }
  .dual {
    grid-template-columns: 1fr 1fr;
  }
  .inputs,
  .results,
  .listing-body {
    padding-left: 16px;
    padding-right: 16px;
  }
  .spec-row {
    gap: 14px;
  }
}

