/* Mortgage Calculator — Aldercrest & Vine
   Vanilla JS. Recomputes an amortized monthly payment on every input change. */
(function () {
  "use strict";

  var $ = function (id) { return document.getElementById(id); };

  var els = {
    price: $("price"),
    downAmt: $("downAmt"),
    downPct: $("downPct"),
    downRange: $("downRange"),
    downHint: $("downHint"),
    rate: $("rate"),
    term: $("term"),
    tax: $("tax"),
    ins: $("ins"),
    hoa: $("hoa"),

    photoPrice: $("photoPrice"),
    monthlyTotal: $("monthlyTotal"),
    donutCenter: $("donutCenter"),
    rowPI: $("rowPI"),
    rowTax: $("rowTax"),
    rowIns: $("rowIns"),
    rowHOA: $("rowHOA"),
    loanAmt: $("loanAmt"),
    totalInterest: $("totalInterest"),
    totalPaid: $("totalPaid"),

    reset: $("reset")
  };

  var DEFAULTS = {
    price: 845000,
    downPct: 20,
    rate: 6.45,
    term: 30,
    tax: 9200,
    ins: 1740,
    hoa: 145
  };

  var R = 52; // donut radius (matches SVG)
  var CIRC = 2 * Math.PI * R;
  var segEls = Array.prototype.slice.call(document.querySelectorAll(".donut-seg"));

  /* ---------- formatting ---------- */
  var fmt0 = new Intl.NumberFormat("en-US", {
    style: "currency", currency: "USD", maximumFractionDigits: 0
  });

  function money(n) {
    if (!isFinite(n) || n < 0) n = 0;
    return fmt0.format(Math.round(n));
  }

  function num(el) {
    var v = parseFloat(el.value);
    return isFinite(v) ? v : 0;
  }

  /* ---------- toast helper ---------- */
  var toastEl = $("toast");
  var toastTimer = null;
  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2200);
  }

  /* ---------- core math ---------- */
  function clamp(n, lo, hi) {
    return Math.min(hi, Math.max(lo, n));
  }

  // Standard amortized monthly principal + interest.
  function monthlyPI(principal, annualRate, years) {
    if (principal <= 0) return 0;
    var n = years * 12;
    var r = annualRate / 100 / 12;
    if (r === 0) return principal / n;
    var f = Math.pow(1 + r, n);
    return (principal * r * f) / (f - 1);
  }

  function compute() {
    var price = clamp(num(els.price), 0, 1e9);
    var downPct = clamp(num(els.downPct), 0, 100);
    var down = price * (downPct / 100);

    var rate = clamp(num(els.rate), 0, 25);
    var years = parseInt(els.term.value, 10) || 30;
    var taxYr = Math.max(0, num(els.tax));
    var insYr = Math.max(0, num(els.ins));
    var hoaMo = Math.max(0, num(els.hoa));

    var loan = Math.max(0, price - down);
    var pi = monthlyPI(loan, rate, years);
    var taxMo = taxYr / 12;
    var insMo = insYr / 12;

    var total = pi + taxMo + insMo + hoaMo;
    var n = years * 12;
    var totalInterest = pi * n - loan;
    var totalPaid = total * n + down;

    return {
      price: price, down: down, loan: loan,
      pi: pi, taxMo: taxMo, insMo: insMo, hoaMo: hoaMo,
      total: total,
      totalInterest: Math.max(0, totalInterest),
      totalPaid: totalPaid
    };
  }

  /* ---------- donut rendering ---------- */
  function paintDonut(d) {
    var parts = [
      { el: segEls[0], v: d.pi },
      { el: segEls[1], v: d.taxMo },
      { el: segEls[2], v: d.insMo },
      { el: segEls[3], v: d.hoaMo }
    ];
    var sum = d.total || 1;
    var offset = 0;
    parts.forEach(function (p) {
      var frac = p.v / sum;
      var len = frac * CIRC;
      // tiny gap between visible segments for definition
      var gap = len > 1.5 ? 1.2 : 0;
      p.el.setAttribute("stroke-dasharray", Math.max(0, len - gap) + " " + (CIRC - Math.max(0, len - gap)));
      p.el.setAttribute("stroke-dashoffset", -offset);
      offset += len;
    });
  }

  /* ---------- render ---------- */
  function render() {
    var d = compute();

    els.photoPrice.textContent = money(d.price);
    els.monthlyTotal.textContent = money(d.total);
    els.donutCenter.textContent = money(d.total);

    els.rowPI.textContent = money(d.pi);
    els.rowTax.textContent = money(d.taxMo);
    els.rowIns.textContent = money(d.insMo);
    els.rowHOA.textContent = money(d.hoaMo);

    els.loanAmt.textContent = money(d.loan);
    els.totalInterest.textContent = money(d.totalInterest);
    els.totalPaid.textContent = money(d.totalPaid);

    paintDonut(d);
  }

  /* ---------- down-payment sync (amount <-> percent <-> slider) ---------- */
  function setDownPct(pct, source) {
    pct = clamp(pct, 0, 100);
    var price = Math.max(0, num(els.price));
    var rounded = Math.round(pct * 10) / 10;

    if (source !== "pct") els.downPct.value = rounded;
    if (source !== "range") els.downRange.value = Math.round(pct);
    if (source !== "amt") els.downAmt.value = Math.round(price * (pct / 100));

    els.downHint.textContent = rounded + "% down";
  }

  function syncFromAmount() {
    var price = Math.max(0, num(els.price));
    var amt = clamp(num(els.downAmt), 0, price);
    var pct = price > 0 ? (amt / price) * 100 : 0;
    setDownPct(pct, "amt");
    render();
  }

  function syncFromPct() {
    setDownPct(num(els.downPct), "pct");
    render();
  }

  function syncFromRange() {
    setDownPct(num(els.downRange), "range");
    render();
  }

  function syncFromPrice() {
    // keep the percentage fixed, recompute the dollar amount
    setDownPct(num(els.downPct), "price");
    render();
  }

  /* ---------- wiring ---------- */
  els.price.addEventListener("input", syncFromPrice);
  els.downAmt.addEventListener("input", syncFromAmount);
  els.downPct.addEventListener("input", syncFromPct);
  els.downRange.addEventListener("input", syncFromRange);

  [els.rate, els.term, els.tax, els.ins, els.hoa].forEach(function (el) {
    el.addEventListener("input", render);
    el.addEventListener("change", render);
  });

  els.reset.addEventListener("click", function () {
    els.price.value = DEFAULTS.price;
    els.rate.value = DEFAULTS.rate;
    els.term.value = String(DEFAULTS.term);
    els.tax.value = DEFAULTS.tax;
    els.ins.value = DEFAULTS.ins;
    els.hoa.value = DEFAULTS.hoa;
    setDownPct(DEFAULTS.downPct, null);
    render();
    toast("Restored listing defaults");
  });

  /* ---------- init ---------- */
  setDownPct(DEFAULTS.downPct, null); // populate amount, percent and slider together
  render();
})();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --sh-1: 0 1px 2px rgba(22, 48, 42, 0.06), 0 1px 1px rgba(22, 48, 42, 0.04);
  --sh-2: 0 6px 18px rgba(22, 48, 42, 0.08), 0 2px 6px rgba(22, 48, 42, 0.06);
  --sh-3: 0 22px 48px rgba(22, 48, 42, 0.16), 0 8px 18px rgba(22, 48, 42, 0.08);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--ivory);
  color: var(--ink);
  font-family: "Inter", system-ui, sans-serif;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  padding: 40px 20px;
}

h1, h2, h3 {
  font-family: "Cormorant Garamond", Georgia, serif;
  color: var(--green-d);
  margin: 0;
  letter-spacing: 0.01em;
}

.shell {
  max-width: 980px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-areas:
    "listing booker"
    "open    booker";
  gap: 22px;
  align-items: start;
}

/* ---------- Listing ---------- */
.listing {
  grid-area: listing;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--sh-2);
}

.photo {
  position: relative;
  aspect-ratio: 16 / 10;
  background:
    radial-gradient(120% 80% at 78% 18%, rgba(255, 233, 188, 0.55), transparent 55%),
    radial-gradient(90% 70% at 12% 90%, rgba(31, 61, 52, 0.55), transparent 60%),
    linear-gradient(160deg, #2b4f43 0%, #3c6450 32%, #b89466 70%, #d8b27e 100%);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 16px;
}
.photo::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(115deg, transparent 38%, rgba(255, 255, 255, 0.12) 40%, transparent 43%),
    repeating-linear-gradient(90deg, rgba(0, 0, 0, 0.05) 0 2px, transparent 2px 56px);
  mix-blend-mode: soft-light;
  pointer-events: none;
}
.photo__label {
  position: absolute;
  top: 14px;
  left: 16px;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 0.78rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.92);
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.4);
}
.photo__price {
  position: relative;
  z-index: 1;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 700;
  font-size: 1.7rem;
  color: var(--white);
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.45);
}

.badge {
  display: inline-flex;
  align-items: center;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 999px;
}
.badge--status {
  position: absolute;
  top: 14px;
  right: 14px;
  z-index: 1;
  background: var(--brass);
  color: var(--white);
  box-shadow: var(--sh-1);
}

.listing__body { padding: 20px 22px 24px; }
.eyebrow {
  margin: 0 0 6px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--brass-d);
}
.listing__title { font-size: 2rem; line-height: 1.1; }
.listing__addr { margin: 4px 0 0; color: var(--muted); font-size: 0.92rem; }

.specs {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 18px 0;
  padding: 0;
}
.specs li {
  flex: 1 1 0;
  min-width: 64px;
  text-align: center;
  background: var(--green-50);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  padding: 9px 4px;
}
.specs strong {
  display: block;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 1.35rem;
  color: var(--green-d);
  line-height: 1;
}
.specs span {
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.agent {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
}
.agent__avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--green);
  color: var(--brass-50);
  font-weight: 600;
  font-size: 0.85rem;
  letter-spacing: 0.04em;
}
.agent__meta { display: flex; flex-direction: column; line-height: 1.3; }
.agent__meta strong { font-size: 0.95rem; }
.agent__meta em { font-style: normal; font-size: 0.8rem; color: var(--muted); }

/* ---------- Booker ---------- */
.booker {
  grid-area: booker;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-3);
  padding: 26px;
  position: sticky;
  top: 24px;
}
.booker__head h2 { font-size: 1.85rem; line-height: 1.05; }
.booker__head p { margin: 4px 0 0; color: var(--muted); font-size: 0.9rem; }

.field { margin-top: 20px; }
.field__label {
  display: block;
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-2);
  margin-bottom: 9px;
}
.field__hint {
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
  color: var(--muted);
  font-size: 0.78rem;
}

/* Toggle */
.toggle {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  background: var(--ivory);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 5px;
}
.toggle__opt {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ink-2);
  background: transparent;
  border: 0;
  border-radius: 10px;
  padding: 10px 8px;
  cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease, box-shadow 0.18s ease;
}
.toggle__opt .ico { width: 17px; height: 17px; fill: currentColor; }
.toggle__opt:hover { color: var(--green-d); }
.toggle__opt.is-active {
  background: var(--green);
  color: var(--white);
  box-shadow: var(--sh-1);
}

/* Date strip */
.dates {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(0, 1fr);
  gap: 7px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: thin;
}
.date {
  flex: 0 0 auto;
  text-align: center;
  border: 1px solid var(--line);
  background: var(--paper);
  border-radius: var(--r-md);
  padding: 9px 4px;
  cursor: pointer;
  transition: transform 0.14s ease, border-color 0.18s ease, background 0.18s ease;
  min-width: 52px;
}
.date:hover { transform: translateY(-2px); border-color: var(--line-2); }
.date .dow {
  font-size: 0.65rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}
.date .dnum {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 1.35rem;
  font-weight: 600;
  color: var(--green-d);
  line-height: 1.1;
}
.date .mon {
  font-size: 0.62rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--brass-d);
}
.date.is-active {
  background: var(--green);
  border-color: var(--green);
}
.date.is-active .dow,
.date.is-active .mon { color: var(--brass-50); }
.date.is-active .dnum { color: var(--white); }

/* Slots */
.slots {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.slot {
  font-family: inherit;
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--green-700);
  background: var(--green-50);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  padding: 10px 6px;
  cursor: pointer;
  transition: transform 0.14s ease, background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
}
.slot:hover:not(:disabled) { transform: translateY(-2px); border-color: var(--brass); }
.slot.is-active {
  background: var(--brass);
  border-color: var(--brass);
  color: var(--white);
  box-shadow: var(--sh-1);
}
.slot:disabled {
  cursor: not-allowed;
  color: var(--muted);
  background: var(--ivory);
  border-style: dashed;
  text-decoration: line-through;
  opacity: 0.7;
}
.slots__empty {
  grid-column: 1 / -1;
  color: var(--muted);
  font-size: 0.88rem;
  padding: 6px 0;
}

/* Inputs */
.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.ifield { display: flex; flex-direction: column; gap: 6px; }
.ifield > span {
  font-size: 0.74rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-2);
}
.ifield input {
  font-family: inherit;
  font-size: 0.95rem;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 11px 13px;
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}
.ifield input::placeholder { color: var(--muted); }
.ifield input:focus {
  outline: none;
  border-color: var(--green);
  box-shadow: 0 0 0 3px var(--green-50);
}

/* Summary + CTA */
.summary {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 22px;
  padding: 12px 14px;
  background: var(--ivory);
  border: 1px solid var(--line);
  border-left: 3px solid var(--brass);
  border-radius: var(--r-sm);
  font-size: 0.9rem;
  color: var(--ink-2);
}
.summary__dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--muted);
  flex: 0 0 auto;
  transition: background 0.2s ease;
}
.summary.is-ready { border-left-color: var(--ok); color: var(--ink); }
.summary.is-ready .summary__dot { background: var(--ok); box-shadow: 0 0 0 3px rgba(47, 158, 111, 0.18); }

.cta {
  width: 100%;
  margin-top: 14px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--white);
  background: linear-gradient(180deg, var(--green-700), var(--green-d));
  border: 1px solid var(--green-d);
  border-radius: var(--r-md);
  padding: 14px;
  cursor: pointer;
  transition: transform 0.14s ease, box-shadow 0.18s ease, filter 0.18s ease;
  box-shadow: var(--sh-2);
}
.cta:hover:not(:disabled) { transform: translateY(-2px); box-shadow: var(--sh-3); }
.cta:active:not(:disabled) { transform: translateY(0); }
.cta:disabled {
  cursor: not-allowed;
  filter: grayscale(0.5);
  opacity: 0.55;
  box-shadow: none;
}

/* ---------- Open houses ---------- */
.open {
  grid-area: open;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-2);
  padding: 22px;
}
.open__head h2 { font-size: 1.6rem; }
.open__head p { margin: 3px 0 0; color: var(--muted); font-size: 0.88rem; }

.open__list { list-style: none; margin: 16px 0 0; padding: 0; display: grid; gap: 11px; }
.oh {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 13px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 12px 14px;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.14s ease;
}
.oh:hover { border-color: var(--line-2); box-shadow: var(--sh-1); transform: translateY(-1px); }
.oh__cal {
  width: 50px;
  text-align: center;
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  overflow: hidden;
  flex: 0 0 auto;
}
.oh__cal .m {
  display: block;
  background: var(--green);
  color: var(--brass-50);
  font-size: 0.6rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 2px 0;
}
.oh__cal .d {
  display: block;
  font-family: "Cormorant Garamond", Georgia, serif;
  font-size: 1.4rem;
  font-weight: 600;
  color: var(--green-d);
  padding: 2px 0;
}
.oh__info { min-width: 0; }
.oh__info b { font-size: 0.95rem; color: var(--ink); display: block; }
.oh__info span { font-size: 0.82rem; color: var(--muted); }
.oh__count {
  display: inline-block;
  margin-top: 3px;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--brass-d);
}
.oh__btn {
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--green-d);
  background: var(--brass-50);
  border: 1px solid var(--brass);
  border-radius: 999px;
  padding: 8px 15px;
  cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease, transform 0.14s ease;
  flex: 0 0 auto;
}
.oh__btn:hover:not(:disabled) { transform: translateY(-1px); }
.oh__btn.is-going {
  background: var(--green);
  border-color: var(--green);
  color: var(--white);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 140%);
  background: var(--green-d);
  color: var(--paper);
  padding: 13px 20px;
  border-radius: 999px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--sh-3);
  border: 1px solid var(--green-700);
  max-width: calc(100vw - 40px);
  opacity: 0;
  transition: transform 0.32s cubic-bezier(0.2, 0.9, 0.3, 1.2), opacity 0.32s ease;
  z-index: 50;
}
.toast.show { transform: translate(-50%, 0); opacity: 1; }
.toast b { color: var(--brass-50); }

/* ---------- Responsive ---------- */
@media (max-width: 880px) {
  .shell {
    grid-template-columns: 1fr;
    grid-template-areas:
      "listing"
      "booker"
      "open";
  }
  .booker { position: static; }
}

@media (max-width: 520px) {
  body { padding: 22px 14px; }
  .listing__title { font-size: 1.6rem; }
  .booker { padding: 20px; }
  .booker__head h2 { font-size: 1.55rem; }
  .photo__price { font-size: 1.4rem; }
  .grid2 { grid-template-columns: 1fr; }
  .slots { grid-template-columns: repeat(2, 1fr); }
  .specs li { min-width: 0; flex-basis: 22%; }
  .oh { grid-template-columns: auto 1fr; }
  .oh__btn { grid-column: 2; justify-self: start; margin-top: 4px; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}

