}
.brand-prop {
  font-size: 0.68rem;
  color: var(--gold-light);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-top: 2px;
}

.nav {
  margin-top: 18px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}
.nav-item {
  font-size: 0.84rem;
  font-weight: 500;
  color: rgba(251, 248, 242, 0.72);
  text-decoration: none;
  padding: 9px 12px;
  border-radius: var(--r-md);
