}
.nav-item:hover {
  background: rgba(255, 255, 255, 0.06);
  color: var(--bone);
}
.nav-item.is-active {
  background: rgba(201, 166, 73, 0.16);
  color: var(--gold-light);
  font-weight: 600;
}
.nav-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--gold);
  flex-shrink: 0;
}

/* ── Legend ─────────────────────────────────────────────────────────────── */
.rail-legend {
  margin-top: 20px;
  padding: 14px 12px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: var(--r-md);
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.legend-title {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--gold-light);
  margin-bottom: 8px;
}
.legend-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.76rem;
  color: rgba(251, 248, 242, 0.72);
  margin-bottom: 5px;
}
.swatch {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  flex-shrink: 0;
}
.demand-low {
  background: rgba(74, 119, 82, 0.5);
  border: 1px solid rgba(74, 119, 82, 0.7);
}
.demand-med {
  background: rgba(201, 166, 73, 0.5);
  border: 1px solid rgba(201, 166, 73, 0.7);
}
.demand-high {
  background: rgba(217, 144, 32, 0.5);
  border: 1px solid rgba(217, 144, 32, 0.7);
}
.demand-peak {
  background: rgba(179, 66, 50, 0.5);
  border: 1px solid rgba(179, 66, 50, 0.7);
}
.demand-closed {
  background: rgba(22, 30, 44, 0.4);
  border: 1px solid rgba(22, 30, 44, 0.5);
}

.rail-foot {
  margin-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.clock {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 0.84rem;
