  font-weight: 600;
  color: var(--warm-gray);
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.ctrl-select {
  font-family: var(--font-body);
  font-size: 0.84rem;
  font-weight: 500;
  color: var(--ink);
  background: var(--bone);
  border: 1px solid var(--line-strong);
