}

/* ── Bulk bar ───────────────────────────────────────────────────────────── */
.bulk-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 28px;
  background: var(--navy);
  flex-shrink: 0;
  flex-wrap: wrap;
}
.bulk-count {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--gold-light);
  min-width: 140px;
}
.bulk-controls {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.bulk-input {
  font-family: var(--font-mono);
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--ink);
  background: var(--bone);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-sm);
  padding: 7px 10px;
  width: 80px;
  outline: none;
}
.bulk-input:focus {
  border-color: var(--gold);
}

/* ── Buttons ────────────────────────────────────────────────────────────── */
.action {
  background: rgba(251, 248, 242, 0.12);
  border: 1px solid rgba(251, 248, 242, 0.22);
  font-family: inherit;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--bone);
  padding: 7px 14px;
  border-radius: var(--r-sm);
  cursor: pointer;
  white-space: nowrap;
}
.action:hover {
  background: rgba(251, 248, 242, 0.2);
}
.action.primary {
  background: var(--gold);
  color: var(--navy-d);
  border-color: var(--gold);
}
.action.primary:hover {
  background: var(--gold-light);
}

/* ── Grid wrap ──────────────────────────────────────────────────────────── */
.grid-wrap {
  flex: 1;
  overflow: auto;
  padding: 0 0 4px;
}

/* ── Rate grid ──────────────────────────────────────────────────────────── */
.rate-grid {
  border-collapse: collapse;
  width: max-content;
  min-width: 100%;
  font-size: 0.82rem;
}

.rate-grid thead th {
  position: sticky;
  top: 0;
  z-index: 10;
  background: var(--bone);
  border-bottom: 2px solid var(--line-strong);
  padding: 0;
}
.rate-grid thead th:first-child {
  position: sticky;
  left: 0;
  z-index: 20;
  min-width: 170px;
}
.th-inner {
  padding: 10px 12px;
  text-align: center;
  min-width: 108px;
}
.th-date {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.78rem;
  color: var(--navy-d);
  display: block;
}
.th-dow {
  font-size: 0.68rem;
  font-weight: 600;
  color: var(--warm-gray);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  display: block;
  margin-top: 2px;
}
.th-dow.weekend {
  color: var(--gold-d);
}
.th-room {
  text-align: left;
  padding: 10px 16px;
}
.th-room-inner {
  display: flex;
  align-items: center;
  gap: 10px;
}
.th-room-cb {
  cursor: pointer;
  accent-color: var(--gold);
  width: 15px;
  height: 15px;
}
.room-label {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
}

/* ── Row header ─────────────────────────────────────────────────────────── */
.rate-grid tbody td.row-head {
  position: sticky;
  left: 0;
  z-index: 5;
  background: var(--bone);
  border-right: 2px solid var(--line-strong);
  padding: 0;
}
.row-head-inner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 14px;
  min-height: 64px;
}
.row-cb {
  cursor: pointer;
  accent-color: var(--gold);
  width: 15px;
  height: 15px;
  flex-shrink: 0;
}
.row-type-name {
  font-weight: 700;
  font-size: 0.88rem;
  color: var(--navy-d);
  letter-spacing: -0.005em;
}
.row-type-code {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  color: var(--warm-gray);
  letter-spacing: 0.08em;
  margin-top: 1px;
}

/* ── Rate cell ──────────────────────────────────────────────────────────── */
.rate-grid tbody td.rate-cell {
  padding: 0;
  border: 1px solid var(--line);
  vertical-align: top;
  position: relative;
  cursor: pointer;
  min-width: 108px;
  height: 64px;
}
.rate-grid tbody tr:hover td.rate-cell {
  background: rgba(201, 166, 73, 0.04);
}
.cell-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 6px 8px;
  position: relative;
  gap: 2px;
  transition: background 0.12s;
}

/* demand colouring via data-demand */
.rate-cell[data-demand="low"] .cell-inner {
  background: rgba(74, 119, 82, 0.1);
}
.rate-cell[data-demand="med"] .cell-inner {
  background: rgba(201, 166, 73, 0.14);
}
.rate-cell[data-demand="high"] .cell-inner {
  background: rgba(217, 144, 32, 0.18);
}
.rate-cell[data-demand="peak"] .cell-inner {
  background: rgba(179, 66, 50, 0.16);
}
.rate-cell[data-demand="closed"] .cell-inner {
  background: rgba(22, 30, 44, 0.07);
}
.rate-cell[data-demand="closed"] .cell-rate {
  text-decoration: line-through;
  color: var(--warm-gray);
}

/* selected state */
.rate-cell.is-selected .cell-inner {
  outline: 2px solid var(--gold);
  outline-offset: -2px;
}
/* dirty (changed) state */
.rate-cell.is-dirty::after {
  content: "";
  position: absolute;
  top: 4px;
  right: 4px;
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--gold);
}

.cell-rate {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--navy-d);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.cell-occ {
  font-size: 0.64rem;
  font-weight: 600;
  color: var(--warm-gray);
  letter-spacing: 0.06em;
}
.cell-flags {
  display: flex;
  gap: 3px;
  margin-top: 1px;
}
.cell-flag {
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  padding: 1px 4px;
  border-radius: 3px;
  text-transform: uppercase;
}
.cell-flag.min {
  background: rgba(74, 109, 160, 0.16);
  color: var(--info);
}
.cell-flag.cls {
  background: rgba(22, 30, 44, 0.1);
  color: var(--warm-gray);
}

/* cell hover controls */
.cell-controls {
  display: none;
  position: absolute;
  bottom: 3px;
  right: 3px;
  gap: 2px;
}
.rate-cell:hover .cell-controls,
.rate-cell:focus-within .cell-controls {
  display: flex;
}
.cc-btn {
  width: 18px;
  height: 18px;
  border-radius: 3px;
  border: 1px solid var(--line-strong);
  background: var(--bone);
  font-size: 0.6rem;
  font-weight: 700;
  color: var(--ink-2);
  cursor: pointer;
  display: grid;
  place-items: center;
  line-height: 1;
}
.cc-btn:hover {
  background: var(--cream-2);
}
.cc-btn.active {
  background: var(--navy);
  color: var(--bone);
  border-color: var(--navy);
}

/* inline edit input */
.cell-edit-input {
  font-family: var(--font-mono);
  font-size: 0.88rem;
  font-weight: 700;
  color: var(--navy-d);
  background: var(--bone);
  border: 2px solid var(--gold);
  border-radius: var(--r-sm);
  width: 76px;
  padding: 4px 6px;
  text-align: center;
  outline: none;
  font-variant-numeric: tabular-nums;
}

/* ── Save bar ───────────────────────────────────────────────────────────── */
.save-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 28px;
  background: var(--navy-d);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  flex-shrink: 0;
}
#saveMsg {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--gold-light);
}
.save-actions {
  display: flex;
  gap: 8px;
}

/* ── Toast ──────────────────────────────────────────────────────────────── */
.toast {
  position: fixed;
  bottom: 60px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 20px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  white-space: nowrap;
  pointer-events: none;
}

/* ── Responsive ─────────────────────────────────────────────────────────── */
@media (max-width: 960px) {
  .rms {
    grid-template-columns: 1fr;
  }
  .rail {
    display: none;
  }
  .topbar {
    flex-direction: column;
    align-items: flex-start;
    padding: 14px 16px 10px;
  }
  .topbar-controls {
    flex-wrap: wrap;
  }
  .bulk-bar {
    padding: 8px 16px;
  }
}
@media (max-width: 560px) {
  .topbar h1 {
    font-size: 1.3rem;
  }
  .bulk-controls {
    gap: 6px;
  }
  .save-bar {
    flex-direction: column;
    gap: 8px;
    align-items: flex-start;
    padding: 10px 16px;
  }
}

