// ── Config ───────────────────────────────────────────────────────────────────
const START_DATE = new Date("2026-06-09T00:00:00");
const NUM_DAYS = 14;

// ── Room types ───────────────────────────────────────────────────────────────
const ROOM_TYPES = [
  { code: "STD", name: "Standard Double", base: 145 },
  { code: "STD", name: "Standard Twin", base: 140 },
  { code: "DLX", name: "Deluxe Double", base: 185 },
  { code: "DLX", name: "Deluxe Sea View", base: 210 },
  { code: "JNR", name: "Junior Suite", base: 285 },
  { code: "STE", name: "Grand Suite", base: 420 },
  { code: "STE", name: "Penthouse Suite", base: 595 },
];

// ── Occupancy seeds (per date index, 0–13) ───────────────────────────────────
const OCC_SEEDS = [58, 62, 74, 81, 88, 95, 96, 70, 65, 72, 84, 90, 93, 78];

// ── State ────────────────────────────────────────────────────────────────────
// cells[rtIdx][dayIdx] = { rate, occ, minStay, closed }
const cells = [];
let dirtySet = new Set(); // "rtIdx-dayIdx" keys
let selectedSet = new Set(); // same key format

// ── Initialise cell state ────────────────────────────────────────────────────
function initCells() {
  ROOM_TYPES.forEach((rt, ri) => {
    cells[ri] = [];
    for (let di = 0; di < NUM_DAYS; di++) {
      const occ = Math.min(
        100,
        OCC_SEEDS[di] + Math.round((rt.base / 145 - 1) * -8) + Math.round(Math.random() * 6 - 3)
      );
      const rate = rt.base + Math.round((occ - 65) * (rt.base * 0.004));
      // weekend uplift
      const dayOfWeek = new Date(START_DATE.getTime() + di * 86400000).getDay();
      const wkuplift = dayOfWeek === 5 || dayOfWeek === 6 ? Math.round(rt.base * 0.12) : 0;
      cells[ri][di] = {
        rate: Math.round(rate + wkuplift),
        occ: Math.max(20, Math.min(100, occ)),
        minStay: di === 5 || di === 6 || di === 12 || di === 13,
        closed: false,
      };
    }
  });
}

// ── Demand tier from occupancy ────────────────────────────────────────────────
function demandTier(c) {
  if (c.closed) return "closed";
  if (c.occ >= 95) return "peak";
  if (c.occ >= 80) return "high";
  if (c.occ >= 50) return "med";
  return "low";
}

// ── Date helpers ─────────────────────────────────────────────────────────────
function addDays(d, n) {
  return new Date(d.getTime() + n * 86400000);
}
function fmtDate(d) {
  return d.toLocaleDateString("en-GB", { day: "2-digit", month: "short" });
}
function fmtDow(d) {
  return d.toLocaleDateString("en-GB", { weekday: "short" });
}

// ── Render helpers ───────────────────────────────────────────────────────────
const gridHead = document.getElementById("gridHead");
const gridBody = document.getElementById("gridBody");
const bulkCount = document.getElementById("bulkCount");
const saveMsg = document.getElementById("saveMsg");
const toast = document.getElementById("toast");

function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2200);
}

function updateSaveBar() {
  saveMsg.textContent =
    dirtySet.size === 0
      ? "No unsaved changes"
      : `${dirtySet.size} unsaved change${dirtySet.size !== 1 ? "s" : ""}`;
}

function updateBulkBar() {
  bulkCount.textContent = `${selectedSet.size} cell${selectedSet.size !== 1 ? "s" : ""} selected`;
}

// ── Build thead ──────────────────────────────────────────────────────────────
function buildHead() {
  const tr = document.createElement("tr");
  // corner cell
  const thCorner = document.createElement("th");
  thCorner.className = "th-room";
  thCorner.innerHTML = `<div class="th-room-inner">
    <input type="checkbox" class="th-room-cb" id="cbAll" title="Select all" />
    <span class="room-label">Room Type</span>
  </div>`;
  tr.appendChild(thCorner);

  for (let di = 0; di < NUM_DAYS; di++) {
    const d = addDays(START_DATE, di);
    const dow = fmtDow(d);
    const isWk = d.getDay() === 0 || d.getDay() === 6;
    const th = document.createElement("th");
    th.innerHTML = `<div class="th-inner">
      <span class="th-date">${fmtDate(d)}</span>
      <span class="th-dow${isWk ? " weekend" : ""}">${dow}</span>
    </div>`;
    tr.appendChild(th);
  }
  gridHead.innerHTML = "";
  gridHead.appendChild(tr);

  // select-all checkbox
  document.getElementById("cbAll").addEventListener("change", (e) => {
    const visRt = getVisibleRtIndices();
    if (e.target.checked) {
      visRt.forEach((ri) => {
        for (let di = 0; di < NUM_DAYS; di++) {
          const key = `${ri}-${di}`;
          if (!cells[ri][di].closed) selectedSet.add(key);
        }
      });
    } else {
      selectedSet.clear();
    }
    renderSelected();
    updateBulkBar();
  });
}

// ── Build tbody ──────────────────────────────────────────────────────────────
function buildBody() {
  gridBody.innerHTML = "";
  ROOM_TYPES.forEach((rt, ri) => {
    const tr = document.createElement("tr");
    tr.dataset.ri = ri;

    // row header
    const tdHead = document.createElement("td");
    tdHead.className = "row-head";
    tdHead.innerHTML = `<div class="row-head-inner">
      <input type="checkbox" class="row-cb" data-ri="${ri}" title="Select row" />
      <div>
        <div class="row-type-name">${rt.name}</div>
        <div class="row-type-code">${rt.code}</div>
      </div>
    </div>`;
    tr.appendChild(tdHead);

    // rate cells
    for (let di = 0; di < NUM_DAYS; di++) {
      const td = buildCell(ri, di);
      tr.appendChild(td);
    }
    gridBody.appendChild(tr);
  });

  // row checkboxes
  gridBody.querySelectorAll(".row-cb").forEach((cb) => {
    cb.addEventListener("change", (e) => {
      const ri = parseInt(e.target.dataset.ri);
      for (let di = 0; di < NUM_DAYS; di++) {
        const key = `${ri}-${di}`;
        if (e.target.checked && !cells[ri][di].closed) selectedSet.add(key);
        else selectedSet.delete(key);
      }
      renderSelected();
      updateBulkBar();
    });
  });
}

// ── Build a single rate cell ──────────────────────────────────────────────────
function buildCell(ri, di) {
  const c = cells[ri][di];
  const key = `${ri}-${di}`;
  const td = document.createElement("td");
  td.className = "rate-cell";
  td.dataset.ri = ri;
  td.dataset.di = di;
  td.dataset.demand = demandTier(c);
  if (dirtySet.has(key)) td.classList.add("is-dirty");
  if (selectedSet.has(key)) td.classList.add("is-selected");

  td.innerHTML = `<div class="cell-inner">
    <span class="cell-rate">${c.closed ? "Closed" : "€" + c.rate}</span>
    <span class="cell-occ">${c.occ}% occ</span>
    <div class="cell-flags">
      ${c.minStay ? `<span class="cell-flag min">2N min</span>` : ""}
      ${c.closed ? `<span class="cell-flag cls">Closed</span>` : ""}
    </div>
    <div class="cell-controls">
      <button class="cc-btn min-btn${c.minStay ? " active" : ""}" title="Toggle min-stay">M</button>
      <button class="cc-btn cls-btn${c.closed ? " active" : ""}" title="Toggle closed">X</button>
    </div>
  </div>`;

  // click to select / edit
  td.addEventListener("click", (e) => {
    if (e.target.closest(".cc-btn")) return; // handled separately
    if (e.target.closest(".cell-edit-input")) return;
    if (c.closed) return;
    startEdit(td, ri, di);
  });

  // min-stay toggle
  td.querySelector(".min-btn").addEventListener("click", (e) => {
    e.stopPropagation();
    cells[ri][di].minStay = !cells[ri][di].minStay;
    dirtySet.add(key);
    refreshCell(td, ri, di);
    updateSaveBar();
    showToast(cells[ri][di].minStay ? "Min-stay set to 2 nights" : "Min-stay removed");
  });

  // closed toggle
  td.querySelector(".cls-btn").addEventListener("click", (e) => {
    e.stopPropagation();
    cells[ri][di].closed = !cells[ri][di].closed;
    dirtySet.add(key);
    refreshCell(td, ri, di);
    updateSaveBar();
    showToast(cells[ri][di].closed ? "Cell marked closed" : "Cell reopened");
  });

  return td;
}

// ── Refresh a single cell in place ───────────────────────────────────────────
function refreshCell(td, ri, di) {
  const c = cells[ri][di];
  const key = `${ri}-${di}`;
  td.dataset.demand = demandTier(c);
  td.classList.toggle("is-dirty", dirtySet.has(key));
  td.classList.toggle("is-selected", selectedSet.has(key));

  const inner = td.querySelector(".cell-inner");
  inner.innerHTML = `
    <span class="cell-rate">${c.closed ? "Closed" : "€" + c.rate}</span>
    <span class="cell-occ">${c.occ}% occ</span>
    <div class="cell-flags">
      ${c.minStay ? `<span class="cell-flag min">2N min</span>` : ""}
      ${c.closed ? `<span class="cell-flag cls">Closed</span>` : ""}
    </div>
    <div class="cell-controls">
      <button class="cc-btn min-btn${c.minStay ? " active" : ""}" title="Toggle min-stay">M</button>
      <button class="cc-btn cls-btn${c.closed ? " active" : ""}" title="Toggle closed">X</button>
    </div>`;

  // rebind toggle buttons
  inner.querySelector(".min-btn").addEventListener("click", (e) => {
    e.stopPropagation();
    cells[ri][di].minStay = !cells[ri][di].minStay;
    dirtySet.add(key);
    refreshCell(td, ri, di);
    updateSaveBar();
    showToast(cells[ri][di].minStay ? "Min-stay set to 2 nights" : "Min-stay removed");
  });
  inner.querySelector(".cls-btn").addEventListener("click", (e) => {
    e.stopPropagation();
    cells[ri][di].closed = !cells[ri][di].closed;
    dirtySet.add(key);
    refreshCell(td, ri, di);
    updateSaveBar();
    showToast(cells[ri][di].closed ? "Cell marked closed" : "Cell reopened");
  });
}

// ── Inline edit ──────────────────────────────────────────────────────────────
function startEdit(td, ri, di) {
  if (td.querySelector(".cell-edit-input")) return; // already editing
  const c = cells[ri][di];
  const key = `${ri}-${di}`;
  const inner = td.querySelector(".cell-inner");
  const rateEl = inner.querySelector(".cell-rate");

  const input = document.createElement("input");
  input.className = "cell-edit-input";
  input.type = "number";
  input.value = c.rate;
  input.min = 1;
  input.step = 1;

  rateEl.replaceWith(input);
  input.focus();
  input.select();

  function commit() {
    const val = Math.max(1, Math.round(parseFloat(input.value) || c.rate));
    const changed = val !== c.rate;
    cells[ri][di].rate = val;
    if (changed) dirtySet.add(key);
    input.replaceWith(rateEl);
    rateEl.textContent = "€" + val;
    td.dataset.demand = demandTier(cells[ri][di]);
    td.classList.toggle("is-dirty", dirtySet.has(key));
    updateSaveBar();
    if (changed) showToast(`Rate updated → €${val}`);
  }

  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      commit();
    }
    if (e.key === "Escape") {
      input.replaceWith(rateEl);
    }
  });
  input.addEventListener("blur", commit);
}

// ── Render selected state ─────────────────────────────────────────────────────
function renderSelected() {
  gridBody.querySelectorAll(".rate-cell").forEach((td) => {
    const key = `${td.dataset.ri}-${td.dataset.di}`;
    td.classList.toggle("is-selected", selectedSet.has(key));
  });
}

// ── Bulk apply ───────────────────────────────────────────────────────────────
document.getElementById("bulkApply").addEventListener("click", () => {
  const op = document.getElementById("bulkOp").value;
  const val = parseFloat(document.getElementById("bulkVal").value);
  if (isNaN(val) || val <= 0) {
    showToast("Enter a positive value first");
    return;
  }
  if (selectedSet.size === 0) {
    showToast("Select at least one cell first");
    return;
  }

  selectedSet.forEach((key) => {
    const [ri, di] = key.split("-").map(Number);
    const c = cells[ri][di];
    if (c.closed) return;
    let newRate = c.rate;
    if (op === "raise-pct") newRate = Math.round(c.rate * (1 + val / 100));
    if (op === "lower-pct") newRate = Math.round(c.rate * (1 - val / 100));
    if (op === "raise-amt") newRate = c.rate + Math.round(val);
    if (op === "lower-amt") newRate = c.rate - Math.round(val);
    if (op === "set-amt") newRate = Math.round(val);
    cells[ri][di].rate = Math.max(1, newRate);
    dirtySet.add(key);
  });

  // re-render affected cells
  gridBody.querySelectorAll(".rate-cell").forEach((td) => {
    const key = `${td.dataset.ri}-${td.dataset.di}`;
    if (selectedSet.has(key)) refreshCell(td, parseInt(td.dataset.ri), parseInt(td.dataset.di));
  });
  updateSaveBar();
  showToast(`Bulk applied to ${selectedSet.size} cell${selectedSet.size !== 1 ? "s" : ""}`);
});

// ── Clear selection ──────────────────────────────────────────────────────────
document.getElementById("bulkClear").addEventListener("click", () => {
  selectedSet.clear();
  renderSelected();
  updateBulkBar();
  document.getElementById("cbAll").checked = false;
  gridBody.querySelectorAll(".row-cb").forEach((cb) => (cb.checked = false));
});

// ── Save / discard ───────────────────────────────────────────────────────────
document.getElementById("saveBtn").addEventListener("click", () => {
  const n = dirtySet.size;
  if (n === 0) {
    showToast("Nothing to save");
    return;
  }
  dirtySet.clear();
  gridBody.querySelectorAll(".rate-cell.is-dirty").forEach((td) => td.classList.remove("is-dirty"));
  updateSaveBar();
  showToast(`${n} rate${n !== 1 ? "s" : ""} saved successfully`);
});
document.getElementById("discardBtn").addEventListener("click", () => {
  if (dirtySet.size === 0) {
    showToast("Nothing to discard");
    return;
  }
  initCells();
  dirtySet.clear();
  selectedSet.clear();
  buildBody();
  updateSaveBar();
  updateBulkBar();
  showToast("Changes discarded");
});

// ── Room type filter ──────────────────────────────────────────────────────────
function getVisibleRtIndices() {
  const f = document.getElementById("filterType").value;
  return ROOM_TYPES.reduce((acc, rt, i) => {
    if (f === "all" || rt.code === f) acc.push(i);
    return acc;
  }, []);
}
function applyRtFilter() {
  const vis = new Set(getVisibleRtIndices());
  gridBody.querySelectorAll("tr[data-ri]").forEach((tr) => {
    tr.style.display = vis.has(parseInt(tr.dataset.ri)) ? "" : "none";
  });
}
document.getElementById("filterType").addEventListener("change", applyRtFilter);
document.getElementById("filterPlan").addEventListener("change", () => {
  showToast("Rate plan switched — reloading rates…");
});

// ── Date range label ─────────────────────────────────────────────────────────
function setDateRange() {
  const end = addDays(START_DATE, NUM_DAYS - 1);
  document.getElementById("dateRange").textContent = `${fmtDate(START_DATE)} – ${fmtDate(end)}`;
}

// ── Clock ────────────────────────────────────────────────────────────────────
function tick() {
  const now = new Date();
  const hhmm = now.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
  const wk = now.toLocaleDateString("en-GB", { weekday: "short" });
  document.getElementById("clock").textContent = `${hhmm} · ${wk}`;
}
tick();
setInterval(tick, 1000);

// ── Boot ─────────────────────────────────────────────────────────────────────
initCells();
buildHead();
buildBody();
setDateRange();
updateSaveBar();
updateBulkBar();

snippets.css:
:root {
  --teal: #129c93;
  --teal-d: #0c7a73;
  --teal-700: #0a655f;
  --teal-50: #e7f5f3;
  --coral: #ff7a66;
  --coral-soft: #ffe6df;
  --ink: #16322f;
  --ink-2: #3a534f;
  --muted: #6b827e;
  --bg: #f1f7f6;
  --white: #ffffff;
  --line: rgba(16, 50, 47, 0.1);
  --line-2: rgba(16, 50, 47, 0.18);
  --ok: #2f9e6f;
  --warn: #d98a2b;
  --pending: #6b7280;
  --danger: #d4503e;
  --font: "Inter", system-ui, -apple-system, sans-serif;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-1: 0 1px 2px rgba(16, 50, 47, 0.05), 0 4px 14px rgba(16, 50, 47, 0.06);
  --shadow-2: 0 16px 40px rgba(12, 122, 115, 0.16);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  line-height: 1.5;
}

:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 2px;
  border-radius: 6px;
}

.vh {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

/* ── Layout ── */
.billing {
  max-width: 1040px;
  margin: 0 auto;
  padding: 36px 24px 64px;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

/* ── Header ── */
.bill-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
  flex-wrap: wrap;
}
.eyebrow {
  font-size: 0.76rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--teal-d);
}
.bill-head h1 {
  font-size: 1.85rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  margin-top: 4px;
}
.bill-head .sub {
  color: var(--muted);
  font-size: 0.92rem;
  margin-top: 4px;
}
.period {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 14px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ink-2);
  box-shadow: var(--shadow-1);
}
.period .dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ok);
  box-shadow: 0 0 0 3px rgba(47, 158, 111, 0.18);
}

/* ── KPI cards ── */
.kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.kpi {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 18px 18px 16px;
  box-shadow: var(--shadow-1);
  position: relative;
  overflow: hidden;
  transition: transform 0.15s, box-shadow 0.15s;
}
.kpi::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: var(--teal);
  opacity: 0.85;
}
.kpi:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-2);
}
.kpi-label {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.kpi-value {
  font-size: 1.6rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-top: 8px;
  color: var(--ink);
}
.kpi-delta {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 10px;
  font-size: 0.8rem;
  font-weight: 700;
  padding: 3px 9px;
  border-radius: 999px;
}
.kpi-delta.up {
  background: rgba(47, 158, 111, 0.12);
  color: var(--ok);
}
.kpi-delta.down {
  background: rgba(212, 80, 62, 0.1);
  color: var(--danger);
}
.kpi-delta.up.bad {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.kpi-delta .arrow {
  font-size: 0.62rem;
}
.kpi-note {
  font-weight: 500;
  color: var(--muted);
  margin-left: 2px;
}

/* ── Panels ── */
.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-1);
  padding: 22px;
}
.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 18px;
}
.panel h2 {
  font-size: 1.04rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.panel-tag {
  font-size: 0.76rem;
  font-weight: 700;
  color: var(--teal-d);
  background: var(--teal-50);
  padding: 4px 10px;
  border-radius: 999px;
}

.grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 16px;
}

/* ── Chart ── */
.chart {
  display: flex;
  align-items: flex-end;
  gap: 14px;
  height: 200px;
  padding-top: 8px;
}
.bar {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  height: 100%;
  position: relative;
}
.bar-fill {
  width: 100%;
  max-width: 46px;
  height: var(--h);
  border-radius: 8px 8px 4px 4px;
  background: linear-gradient(180deg, var(--teal), var(--teal-d));
  transition: filter 0.15s, transform 0.15s;
  transform-origin: bottom;
  animation: grow 0.6s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
.bar.is-peak .bar-fill {
  background: linear-gradient(180deg, #18b3a8, var(--teal-700));
  box-shadow: 0 6px 16px rgba(12, 122, 115, 0.28);
}
.bar:hover .bar-fill {
  filter: brightness(1.06);
  transform: scaleY(1.015);
}
@keyframes grow {
  from {
    transform: scaleY(0);
  }
  to {
    transform: scaleY(1);
  }
}
.bar-val {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--ink-2);
  margin-bottom: 7px;
  opacity: 0;
  transition: opacity 0.15s;
}
.bar:hover .bar-val,
.bar.is-peak .bar-val {
  opacity: 1;
}
.bar.is-peak .bar-val {
  color: var(--teal-700);
}
.bar-month {
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--muted);
  margin-top: 9px;
}
.bar.is-peak .bar-month {
  color: var(--teal-d);
  font-weight: 700;
}

/* ── Aging ── */
.aging-bar {
  display: flex;
  height: 16px;
  border-radius: 999px;
  overflow: hidden;
  background: var(--bg);
  gap: 2px;
}
.seg {
  width: var(--w);
  height: 100%;
}
.seg.s0 {
  background: var(--teal);
}
.seg.s1 {
  background: #5cc2b9;
}
.seg.s2 {
  background: var(--warn);
}
.seg.s3 {
  background: var(--danger);
}
.aging-legend {
  list-style: none;
  margin-top: 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.aging-legend li {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 0.85rem;
  color: var(--ink-2);
}
.aging-legend strong {
  margin-left: auto;
  font-weight: 700;
  color: var(--ink);
}
.swatch {
  width: 11px;
  height: 11px;
  border-radius: 3px;
  flex-shrink: 0;
}
.swatch.s0 {
  background: var(--teal);
}
.swatch.s1 {
  background: #5cc2b9;
}
.swatch.s2 {
  background: var(--warn);
}
.swatch.s3 {
  background: var(--danger);
}

/* ── Claims ── */
.claims-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}
.search {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 9px 16px;
  min-width: 280px;
  transition: border-color 0.15s, background 0.15s;
}
.search:focus-within {
  border-color: var(--teal);
  background: var(--white);
}
.search-ico {
  color: var(--muted);
  font-size: 1.05rem;
}
.search input {
  border: none;
  background: transparent;
  font: inherit;
  font-size: 0.88rem;
  color: var(--ink);
  width: 100%;
  outline: none;
}
.search input::placeholder {
  color: var(--muted);
}

.filters {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}
.filter {
  border: 1px solid var(--line);
  background: var(--white);
  border-radius: 999px;
  padding: 7px 14px;
  font: inherit;
  font-weight: 600;
  font-size: 0.84rem;
  color: var(--ink-2);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.filter:hover {
  border-color: var(--teal);
  color: var(--teal-d);
}
.filter.is-active {
  background: var(--teal-d);
  border-color: var(--teal-d);
  color: #fff;
}
.fcount {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--teal-50);
  color: var(--teal-d);
  font-size: 0.7rem;
  font-weight: 700;
}
.filter.is-active .fcount {
  background: rgba(255, 255, 255, 0.22);
  color: #fff;
}

.table-wrap {
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
}
table.claims {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
  min-width: 680px;
}
table.claims thead th {
  text-align: left;
  font-size: 0.73rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
  padding: 12px 16px;
  background: #f7fbfa;
  border-bottom: 1px solid var(--line);
  white-space: nowrap;
}
table.claims th.num,
table.claims td.num {
  text-align: right;
}
table.claims tbody td {
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
  color: var(--ink-2);
  vertical-align: middle;
}
table.claims tbody tr:last-child td {
  border-bottom: none;
}
table.claims tbody tr {
  transition: background 0.12s;
}
table.claims tbody tr:hover {
  background: var(--teal-50);
}
table.claims tbody tr[data-status="denied"]:hover {
  background: rgba(212, 80, 62, 0.06);
}
td.mono {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--ink);
  letter-spacing: -0.01em;
}
td.num {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--ink);
}
td.date {
  color: var(--muted);
  white-space: nowrap;
}

/* ── Status pills ── */
.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.74rem;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  white-space: nowrap;
}
.pill::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.pill.paid {
  background: rgba(47, 158, 111, 0.14);
  color: var(--ok);
}
.pill.submitted {
  background: var(--teal-50);
  color: var(--teal-d);
}
.pill.pending {
  background: rgba(217, 138, 43, 0.16);
  color: var(--warn);
}
.pill.denied {
  background: rgba(212, 80, 62, 0.14);
  color: var(--danger);
}

/* ── Resubmit action ── */
td.act {
  text-align: right;
  white-space: nowrap;
}
.btn-resubmit {
  border: 1px solid rgba(212, 80, 62, 0.4);
  background: var(--white);
  color: var(--danger);
  border-radius: 8px;
  padding: 6px 12px;
  font: inherit;
  font-weight: 600;
  font-size: 0.8rem;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.12s;
}
.btn-resubmit:hover {
  background: rgba(212, 80, 62, 0.08);
  border-color: var(--danger);
}
.btn-resubmit:active {
  transform: translateY(1px);
}
.btn-resubmit:disabled {
  opacity: 0.55;
  cursor: default;
}

.empty {
  padding: 32px 16px;
  text-align: center;
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 500;
}

.claims-foot {
  margin-top: 14px;
  font-size: 0.8rem;
  color: var(--muted);
  font-weight: 500;
}

/* ── Toast ── */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  padding: 13px 20px;
  border-radius: 12px;
  font-size: 0.9rem;
  font-weight: 500;
  box-shadow: var(--shadow-2);
  z-index: 50;
  max-width: 90vw;
}

/* ── Responsive ── */
@media (max-width: 860px) {
  .kpis {
    grid-template-columns: repeat(2, 1fr);
  }
  .grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .billing {
    padding: 24px 14px 48px;
  }
  .bill-head h1 {
    font-size: 1.5rem;
  }
  .kpis {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }
  .kpi-value {
    font-size: 1.35rem;
  }
  .panel {
    padding: 18px 16px;
  }
  .chart {
    gap: 8px;
    height: 170px;
  }
  .search {
    min-width: 0;
    width: 100%;
  }
  .claims-head {
    flex-direction: column;
    align-items: stretch;
  }
}

