(function () {
  "use strict";

  /* ---------- Room data ---------- */
  var ROOMS = [
    {
      id: "living",
      name: "Living Room",
      dim: "21 × 18 ft",
      desc: "Sun-drenched great room with double-height ceilings, white-oak floors, and a limestone fireplace anchoring the lounge.",
      feat: ["Gas fireplace", "12 ft ceilings", "South-facing windows"],
      // floor-plan marker position (svg viewBox coords)
      here: { cx: 56, cy: 49 },
      // hotspots: x/y are % across the panoramic image
      hotspots: [
        { x: 30, y: 58, label: "Step into Kitchen", to: "kitchen" },
        { x: 72, y: 50, label: "Fireplace detail", info: "Honed limestone surround." }
      ]
    },
    {
      id: "kitchen",
      name: "Chef's Kitchen",
      dim: "16 × 14 ft",
      desc: "Bespoke walnut cabinetry, a marble waterfall island, and integrated appliances open to the dining terrace.",
      feat: ["Marble island", "Walk-in pantry", "Pro range"],
      here: { cx: 150, cy: 38 },
      hotspots: [
        { x: 24, y: 56, label: "Back to Living", to: "living" },
        { x: 70, y: 60, label: "To Primary Suite", to: "primary" }
      ]
    },
    {
      id: "primary",
      name: "Primary Suite",
      dim: "19 × 16 ft",
      desc: "A private retreat with a sitting nook, custom dressing room, and a spa bath behind pocket doors.",
      feat: ["Walk-in closet", "Private balcony", "Spa ensuite"],
      here: { cx: 150, cy: 107 },
      hotspots: [
        { x: 32, y: 54, label: "Back to Kitchen", to: "kitchen" },
        { x: 74, y: 64, label: "Into Bath", to: "bath" }
      ]
    },
    {
      id: "bath",
      name: "Spa Bath",
      dim: "12 × 10 ft",
      desc: "Floor-to-ceiling porcelain, a freestanding soaking tub, and a glass rain shower with brass fixtures.",
      feat: ["Soaking tub", "Heated floors", "Double vanity"],
      here: { cx: 56, cy: 118 },
      hotspots: [{ x: 36, y: 56, label: "Back to Primary", to: "primary" }]
    }
  ];

  var byId = {};
  ROOMS.forEach(function (r) {
    byId[r.id] = r;
  });

  /* ---------- Refs ---------- */
  var stage = document.getElementById("stage");
  var pano = document.getElementById("pano");
  var hotspotsEl = document.getElementById("hotspots");
  var rail = document.getElementById("rail");
  var roomTag = document.getElementById("roomTag");
  var mapLabel = document.getElementById("mapLabel");
  var dragHint = document.getElementById("dragHint");
  var fpHere = document.getElementById("fpHere");
  var detailName = document.getElementById("detailName");
  var detailDim = document.getElementById("detailDim");
  var detailDesc = document.getElementById("detailDesc");
  var detailFeat = document.getElementById("detailFeat");
  var toastEl = document.getElementById("toast");

  var prevBtn = document.getElementById("prevBtn");
  var nextBtn = document.getElementById("nextBtn");
  var autoBtn = document.getElementById("autoBtn");
  var fsBtn = document.getElementById("fsBtn");
  var bookBtn = document.getElementById("bookBtn");

  var current = 0;
  var panX = 0; // current pan offset in px
  var maxPan = 0; // how far we can pan each side
  var autoTimer = null;
  var autoPanRAF = null;

  /* ---------- Toast helper ---------- */
  var toastTimer = null;
  function toast(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2200);
  }

  /* ---------- Build thumbnail rail ---------- */
  ROOMS.forEach(function (r, i) {
    var btn = document.createElement("button");
    btn.className = "thumb";
    btn.type = "button";
    btn.setAttribute("role", "tab");
    btn.dataset.index = String(i);
    btn.setAttribute("aria-label", "View " + r.name);
    btn.innerHTML =
      '<span class="thumb__img" data-room="' +
      r.id +
      '"></span><span class="thumb__label">' +
      r.name +
      "</span>";
    btn.addEventListener("click", function () {
      goTo(i, true);
    });
    rail.appendChild(btn);
  });
  var thumbs = Array.prototype.slice.call(rail.children);

  /* ---------- Floor-plan rooms ---------- */
  var fpRooms = Array.prototype.slice.call(
    document.querySelectorAll(".fp-room")
  );
  fpRooms.forEach(function (rect) {
    rect.addEventListener("click", function () {
      var idx = ROOMS.findIndex(function (r) {
        return r.id === rect.dataset.room;
      });
      if (idx >= 0) goTo(idx, true);
    });
  });

  /* ---------- Pan helpers ---------- */
  function computeMaxPan() {
    // pano is 230% wide; overflow each side = (230-100)/2 = 65% of stage width
    maxPan = stage.clientWidth * 0.6;
  }

  function applyPan() {
    pano.style.transform = "translateX(" + panX + "px)";
  }

  function clampPan(v) {
    if (v > maxPan) return maxPan;
    if (v < -maxPan) return -maxPan;
    return v;
  }

  /* ---------- Render hotspots for current room ---------- */
  function renderHotspots(room) {
    hotspotsEl.innerHTML = "";
    room.hotspots.forEach(function (h) {
      var b = document.createElement("button");
      b.className = "hotspot";
      b.type = "button";
      b.style.left = h.x + "%";
      b.style.top = h.y + "%";
      b.setAttribute("aria-label", h.label);
      b.innerHTML = '<span class="tip">' + h.label + "</span>";
      b.addEventListener("click", function (e) {
        e.stopPropagation();
        if (h.to && byId[h.to]) {
          var idx = ROOMS.findIndex(function (r) {
            return r.id === h.to;
          });
          goTo(idx, true);
        } else if (h.info) {
          toast(h.info);
        }
      });
      hotspotsEl.appendChild(b);
    });
  }

  /* ---------- Go to a room ---------- */
  function goTo(index, userInitiated) {
    if (index < 0) index = ROOMS.length - 1;
    if (index >= ROOMS.length) index = 0;
    current = index;
    var room = ROOMS[index];

    pano.dataset.room = room.id;
    roomTag.textContent = room.name;
    mapLabel.textContent = room.name;
    detailName.textContent = room.name;
    detailDim.textContent = room.dim;
    detailDesc.textContent = room.desc;

    detailFeat.innerHTML = "";
    room.feat.forEach(function (f) {
      var li = document.createElement("li");
      li.textContent = f;
      detailFeat.appendChild(li);
    });

    // reset pan to centre on room change
    panX = 0;
    applyPan();
    renderHotspots(room);

    // active states
    thumbs.forEach(function (t, i) {
      t.classList.toggle("is-active", i === index);
      t.setAttribute("aria-selected", i === index ? "true" : "false");
    });
    fpRooms.forEach(function (rect) {
      rect.classList.toggle("is-active", rect.dataset.room === room.id);
    });

    // move you-are-here marker
    fpHere.setAttribute("cx", room.here.cx);
    fpHere.setAttribute("cy", room.here.cy);

    if (userInitiated) toast("Now viewing · " + room.name);
  }

  /* ---------- Drag to pan ---------- */
  var dragging = false;
  var startX = 0;
  var startPan = 0;
  var hintDismissed = false;

  function dismissHint() {
    if (hintDismissed) return;
    hintDismissed = true;
    dragHint.classList.add("hide");
  }

  function pointerDown(e) {
    if (e.target.closest(".hotspot")) return;
    dragging = true;
    startX = e.clientX;
    startPan = panX;
    stage.classList.add("dragging", "no-anim");
    stage.setPointerCapture && stage.setPointerCapture(e.pointerId);
    dismissHint();
    stopAuto();
  }

  function pointerMove(e) {
    if (!dragging) return;
    var dx = e.clientX - startX;
    panX = clampPan(startPan + dx);
    applyPan();
  }

  function pointerUp() {
    if (!dragging) return;
    dragging = false;
    stage.classList.remove("dragging", "no-anim");
  }

  stage.addEventListener("pointerdown", pointerDown);
  window.addEventListener("pointermove", pointerMove);
  window.addEventListener("pointerup", pointerUp);
  window.addEventListener("pointercancel", pointerUp);

  /* ---------- Keyboard pan + nav ---------- */
  stage.addEventListener("keydown", function (e) {
    if (e.key === "ArrowLeft") {
      e.preventDefault();
      panX = clampPan(panX + 60);
      applyPan();
      dismissHint();
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      panX = clampPan(panX - 60);
      applyPan();
      dismissHint();
    } else if (e.key === "[" || e.key === "PageUp") {
      goTo(current - 1, true);
    } else if (e.key === "]" || e.key === "PageDown") {
      goTo(current + 1, true);
    }
  });

  /* ---------- Prev / next ---------- */
  prevBtn.addEventListener("click", function () {
    goTo(current - 1, true);
  });
  nextBtn.addEventListener("click", function () {
    goTo(current + 1, true);
  });

  /* ---------- Auto tour ---------- */
  function isPlaying() {
    return stage.classList.contains("is-playing");
  }

  function startAuto() {
    stage.classList.add("is-playing");
    autoBtn.setAttribute("aria-pressed", "true");
    autoBtn.setAttribute("aria-label", "Pause auto tour");
    toast("Auto tour started");
    runAutoStep();
  }

  function runAutoStep() {
    // gently sweep the pan, then advance to next room
    var dir = 1;
    var t0 = null;
    cancelAnimationFrame(autoPanRAF);

    function sweep(ts) {
      if (!isPlaying()) return;
      if (t0 === null) t0 = ts;
      // sweep across over ~3.4s using a sine ease
      var p = (ts - t0) / 3400;
      var eased = Math.sin(Math.min(p, 1) * Math.PI - Math.PI / 2);
      panX = eased * maxPan * dir;
      applyPan();
      if (p < 1) {
        autoPanRAF = requestAnimationFrame(sweep);
      }
    }
    autoPanRAF = requestAnimationFrame(sweep);

    autoTimer = setTimeout(function () {
      if (!isPlaying()) return;
      goTo(current + 1, false);
      runAutoStep();
    }, 3800);
  }

  function stopAuto() {
    if (!isPlaying()) return;
    stage.classList.remove("is-playing");
    autoBtn.setAttribute("aria-pressed", "false");
    autoBtn.setAttribute("aria-label", "Play auto tour");
    clearTimeout(autoTimer);
    cancelAnimationFrame(autoPanRAF);
  }

  autoBtn.addEventListener("click", function () {
    if (isPlaying()) {
      stopAuto();
      toast("Auto tour paused");
    } else {
      dismissHint();
      startAuto();
    }
  });

  /* ---------- Fullscreen ---------- */
  fsBtn.addEventListener("click", function () {
    if (!document.fullscreenElement) {
      if (stage.requestFullscreen) {
        stage.requestFullscreen().catch(function () {
          toast("Fullscreen unavailable here");
        });
      } else {
        toast("Fullscreen unavailable here");
      }
    } else {
      document.exitFullscreen && document.exitFullscreen();
    }
  });

  document.addEventListener("fullscreenchange", function () {
    var on = document.fullscreenElement === stage;
    stage.classList.toggle("is-fs", on);
    computeMaxPan();
  });

  /* ---------- Book showing ---------- */
  bookBtn.addEventListener("click", function () {
    toast("Showing request sent to Delphine — she'll confirm shortly.");
  });

  /* ---------- Resize ---------- */
  window.addEventListener("resize", function () {
    computeMaxPan();
    panX = clampPan(panX);
    applyPan();
  });

  /* ---------- Init ---------- */
  computeMaxPan();
  goTo(0, false);

  // auto-dismiss the drag hint after a few seconds
  setTimeout(dismissHint, 5200);
})();

snippets.css:
:root {
  --bg: #16161a;
  --surface: #1f1f24;
  --surface-2: #26262d;
  --elevated: #2d2d35;
  --ink: #f3efe7;
  --ink-2: #c4bdb0;
  --muted: #8a8479;
  --crimson: #b3122b;
  --crimson-d: #8e0e22;
  --crimson-soft: rgba(179, 18, 43, 0.14);
  --cream: #efe7d6;
  --line: rgba(255, 255, 255, 0.1);
  --line-2: rgba(255, 255, 255, 0.18);
  --ok: #34d399;
  --warn: #fbbf24;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow: 0 1px 0 rgba(255, 255, 255, 0.04), 0 14px 40px -18px rgba(0, 0, 0, 0.8);
  --shadow-lg: 0 30px 70px -30px rgba(0, 0, 0, 0.9);
  --serif: "Roboto Slab", Georgia, serif;
  --sans: "Inter", system-ui, -apple-system, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 84px;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

h1, h2, h3 {
  font-family: var(--serif);
  font-weight: 800;
  letter-spacing: -0.01em;
  margin: 0;
  line-height: 1.08;
}

p { margin: 0; }
ul, ol { margin: 0; padding: 0; list-style: none; }
a { color: inherit; text-decoration: none; }

img { max-width: 100%; display: block; }

.container {
  width: min(1140px, 100% - 40px);
  margin-inline: auto;
}

.skip-link {
  position: absolute;
  left: -999px;
  top: 0;
  background: var(--crimson);
  color: #fff;
  padding: 10px 16px;
  border-radius: var(--r-sm);
  z-index: 200;
}
.skip-link:focus { left: 12px; top: 12px; }

:focus-visible {
  outline: 2px solid var(--crimson);
  outline-offset: 3px;
  border-radius: 4px;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--crimson);
}
.eyebrow--light { color: var(--cream); opacity: 0.85; }
.eyebrow__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--crimson);
  box-shadow: 0 0 0 4px var(--crimson-soft);
}

/* ===== BUTTONS ===== */
.btn {
  --pad-y: 11px;
  --pad-x: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: var(--pad-y) var(--pad-x);
  font-family: var(--sans);
  font-weight: 700;
  font-size: 0.9rem;
  letter-spacing: 0.02em;
  border: 1px solid transparent;
  border-radius: var(--r-sm);
  cursor: pointer;
  transition: transform 0.12s ease, background 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }
.btn--lg { --pad-y: 15px; --pad-x: 26px; font-size: 0.98rem; }
.btn--block { width: 100%; }

.btn--primary {
  background: var(--crimson);
  color: #fff;
  box-shadow: 0 10px 24px -12px var(--crimson);
}
.btn--primary:hover { background: var(--crimson-d); box-shadow: 0 14px 30px -12px var(--crimson); }

.btn--ghost {
  background: transparent;
  color: var(--ink-2);
}
.btn--ghost:hover { color: var(--ink); background: var(--surface-2); }

.btn--outline {
  background: transparent;
  color: var(--ink);
  border-color: var(--line-2);
}
.btn--outline:hover { border-color: var(--cream); background: rgba(239, 231, 214, 0.06); }

.tag {
  display: inline-flex;
  align-items: center;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-2);
  background: var(--surface-2);
  border: 1px solid var(--line);
  padding: 4px 10px;
  border-radius: 999px;
}
.tag--live {
  color: #fff;
  background: var(--crimson);
  border-color: transparent;
}
.tag--live::before {
  content: "";
  width: 7px; height: 7px;
  border-radius: 50%;
  background: #fff;
  margin-right: 7px;
  animation: pulse 1.6s ease-in-out infinite;
}
@keyframes pulse { 0%,100% { opacity: 1; } 50% { opacity: 0.3; } }

/* ===== NAV ===== */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(22, 22, 26, 0.72);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s ease, background 0.2s ease;
}
.nav.is-scrolled {
  border-bottom-color: var(--line);
  background: rgba(22, 22, 26, 0.92);
}
.nav__inner {
  display: flex;
  align-items: center;
  gap: 18px;
  height: 72px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--serif);
  font-weight: 800;
  font-size: 1.18rem;
  letter-spacing: 0.01em;
}
.brand__mark {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 9px;
  background: var(--crimson);
  color: var(--cream);
  font-size: 1.1rem;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,0.15);
}
.brand__name span { color: var(--crimson); }

.nav__links {
  display: flex;
  gap: 26px;
  margin-left: auto;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ink-2);
}
.nav__links a { position: relative; transition: color 0.18s ease; }
.nav__links a::after {
  content: "";
  position: absolute;
  left: 0; bottom: -6px;
  width: 0; height: 2px;
  background: var(--crimson);
  transition: width 0.22s ease;
}
.nav__links a:hover { color: var(--ink); }
.nav__links a:hover::after { width: 100%; }

.nav__cta {
  display: flex;
  align-items: center;
  gap: 10px;
}

.nav__toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 44px;
  height: 44px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  cursor: pointer;
  margin-left: auto;
}
.nav__toggle span {
  display: block;
  width: 20px;
  height: 2px;
  margin-inline: auto;
  background: var(--ink);
  transition: transform 0.2s ease, opacity 0.2s ease;
}
.nav__toggle[aria-expanded="true"] span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.nav__toggle[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
.nav__toggle[aria-expanded="true"] span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

.nav__mobile {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px 20px 20px;
  border-top: 1px solid var(--line);
  background: var(--surface);
}
.nav__mobile a {
  padding: 12px 10px;
  font-weight: 600;
  color: var(--ink-2);
  border-radius: var(--r-sm);
}
.nav__mobile a:hover { background: var(--surface-2); color: var(--ink); }
.nav__mobile .btn { margin-top: 8px; }

/* ===== HERO ===== */
.hero {
  position: relative;
  padding: clamp(48px, 8vw, 96px) 0 clamp(56px, 8vw, 104px);
  background:
    radial-gradient(120% 90% at 85% -10%, var(--crimson-soft), transparent 55%),
    radial-gradient(90% 70% at -10% 110%, rgba(239,231,214,0.05), transparent 60%),
    var(--bg);
  overflow: hidden;
}
.hero__grain {
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(
    115deg,
    rgba(255,255,255,0.02) 0 2px,
    transparent 2px 8px
  );
  opacity: 0.6;
  pointer-events: none;
}
.hero__inner {
  position: relative;
  display: grid;
  grid-template-columns: 1.25fr 0.85fr;
  gap: clamp(28px, 4vw, 56px);
  align-items: center;
}
.hero__title {
  font-size: clamp(2.5rem, 6vw, 4.4rem);
  font-weight: 900;
  margin: 16px 0 18px;
}
.hero__title em {
  font-style: normal;
  color: var(--crimson);
  -webkit-text-stroke: 1px var(--crimson);
}
.hero__lead {
  color: var(--ink-2);
  font-size: 1.06rem;
  max-width: 52ch;
}
.hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin: 26px 0 34px;
}
.hero__stats {
  display: flex;
  flex-wrap: wrap;
  gap: clamp(20px, 4vw, 46px);
  padding-top: 26px;
  border-top: 1px solid var(--line);
}
.hero__stats strong {
  display: block;
  font-family: var(--serif);
  font-size: 2.1rem;
  font-weight: 800;
  color: var(--ink);
}
.hero__stats span {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
}

.hero__card {
  background: linear-gradient(180deg, var(--surface) 0%, var(--surface-2) 100%);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 24px;
  box-shadow: var(--shadow-lg);
  position: relative;
}
.hero__card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(160deg, rgba(179,18,43,0.6), transparent 40%);
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}
.hero__card-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}
.hero__card-time {
  font-family: var(--serif);
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--cream);
}
.hero__card-title { font-size: 1.5rem; margin-bottom: 4px; }
.hero__card-sub { color: var(--muted); font-size: 0.9rem; }
.hero__card-meta {
  display: grid;
  gap: 10px;
  margin: 18px 0;
  padding: 16px 0;
  border-block: 1px solid var(--line);
}
.hero__card-meta > div {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}
.hero__card-meta .k { color: var(--muted); font-size: 0.85rem; }
.hero__card-meta .v { font-weight: 600; font-size: 0.92rem; }
.hero__spots { color: var(--warn); }
.hero__card-fine {
  margin-top: 12px;
  font-size: 0.78rem;
  color: var(--muted);
  text-align: center;
}

/* ===== SECTIONS ===== */
.section {
  padding: clamp(56px, 8vw, 100px) 0;
  border-top: 1px solid var(--line);
}
.section__head {
  max-width: 640px;
  margin-bottom: 40px;
}
.section__title {
  font-size: clamp(1.9rem, 4vw, 2.8rem);
  margin: 14px 0 14px;
}
.section__lead {
  color: var(--ink-2);
  font-size: 1.02rem;
}

/* ===== FILTERS / CHIPS ===== */
.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 28px;
}
.chip {
  font-family: var(--sans);
  font-size: 0.84rem;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: var(--ink-2);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 9px 18px;
  cursor: pointer;
  transition: all 0.16s ease;
}
.chip:hover { color: var(--ink); border-color: var(--line-2); }
.chip.is-active {
  color: #fff;
  background: var(--crimson);
  border-color: var(--crimson);
}

/* ===== DISCIPLINE CARDS ===== */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 18px;
}
.d-card {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 24px 22px 22px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
  overflow: hidden;
}
.d-card::after {
  content: "";
  position: absolute;
  left: 0; top: 0;
  width: 100%; height: 3px;
  background: var(--crimson);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.25s ease;
}
.d-card:hover {
  transform: translateY(-4px);
  border-color: var(--line-2);
  box-shadow: var(--shadow);
}
.d-card:hover::after { transform: scaleX(1); }
.d-card.is-hidden { display: none; }
.d-card__badge {
  position: absolute;
  top: 18px;
  right: 18px;
  font-family: var(--serif);
  font-size: 2.4rem;
  font-weight: 800;
  color: rgba(239, 231, 214, 0.08);
  line-height: 1;
}
.d-card .tag { align-self: flex-start; }
.d-card h3 { font-size: 1.45rem; }
.d-card p { color: var(--ink-2); font-size: 0.94rem; }
.d-card__list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 4px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.d-card__list li {
  position: relative;
  padding-left: 20px;
  font-size: 0.86rem;
  color: var(--ink-2);
}
.d-card__list li::before {
  content: "›";
  position: absolute;
  left: 2px;
  color: var(--crimson);
  font-weight: 700;
}
.d-card__cta {
  margin-top: 12px;
  align-self: flex-start;
  background: transparent;
  border: none;
  color: var(--cream);
  font-family: var(--sans);
  font-weight: 700;
  font-size: 0.88rem;
  letter-spacing: 0.03em;
  cursor: pointer;
  padding: 6px 0;
}
.d-card__cta::after { content: " →"; transition: margin 0.18s ease; }
.d-card__cta:hover { color: var(--crimson); }
.d-card__cta:hover::after { margin-left: 4px; }

/* ===== COACHES ===== */
.coach-row {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 18px;
}
.coach {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 24px 22px;
  text-align: center;
  transition: transform 0.2s ease, border-color 0.2s ease;
}
.coach:hover { transform: translateY(-4px); border-color: var(--line-2); }
.coach__avatar {
  width: 78px;
  height: 78px;
  margin: 0 auto 16px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at 30% 30%, var(--surface-2), var(--bg));
  border: 1px solid var(--line-2);
  position: relative;
}
.coach__avatar::after {
  content: attr(data-initials);
  font-family: var(--serif);
  font-weight: 800;
  font-size: 1.5rem;
  color: var(--cream);
}
.coach__avatar::before {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px dashed rgba(179, 18, 43, 0.5);
}
.coach__name { font-size: 1.1rem; }
.coach__role {
  color: var(--crimson);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin: 4px 0 14px;
}
.coach__creds {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.coach__creds li { font-size: 0.84rem; color: var(--ink-2); }

/* ===== PATH ===== */
.path-list {
  display: grid;
  gap: 0;
}
.path-step {
  display: grid;
  grid-template-columns: 56px 8px 1fr;
  gap: 20px;
  align-items: start;
  padding: 22px 0;
  border-top: 1px solid var(--line);
}
.path-step:last-child { border-bottom: 1px solid var(--line); }
.path-step__rank {
  font-family: var(--serif);
  font-weight: 800;
  font-size: 1.4rem;
  color: var(--muted);
}
.path-step__belt {
  width: 8px;
  align-self: stretch;
  border-radius: 4px;
  background: var(--belt, var(--cream));
  box-shadow: 0 0 0 1px rgba(0,0,0,0.4) inset;
  min-height: 44px;
}
.path-step__body h3 { font-size: 1.3rem; margin-bottom: 6px; }
.path-step__body p { color: var(--ink-2); font-size: 0.96rem; max-width: 62ch; }

/* ===== SCHEDULE ===== */
.sched {
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
  background: var(--surface);
}
.sched__row {
  display: grid;
  grid-template-columns: 88px 1fr 160px 130px;
  gap: 16px;
  align-items: center;
  padding: 16px 22px;
  border-top: 1px solid var(--line);
  transition: background 0.16s ease;
}
.sched__row:first-child { border-top: none; }
.sched__row:not(.sched__row--head):hover { background: var(--surface-2); }
.sched__row--head {
  background: var(--bg);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}
.sched__time {
  font-family: var(--serif);
  font-weight: 700;
  color: var(--cream);
}
.sched__class { font-weight: 600; }
.sched__coach { color: var(--ink-2); font-size: 0.92rem; }
.lvl {
  font-style: normal;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid var(--line);
}
.lvl--all { color: var(--ink-2); }
.lvl--begin { color: var(--ok); border-color: rgba(52, 211, 153, 0.4); }
.lvl--inter { color: var(--warn); border-color: rgba(251, 191, 36, 0.4); }

/* ===== STORIES ===== */
.quotes {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 18px;
}
.quote {
  margin: 0;
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 3px solid var(--crimson);
  border-radius: var(--r-md);
  padding: 26px 24px;
}
.quote blockquote {
  margin: 0 0 18px;
  font-size: 1.02rem;
  color: var(--ink);
  line-height: 1.55;
}
.quote figcaption {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.quote__name { font-weight: 700; font-family: var(--serif); }
.quote__meta { font-size: 0.8rem; color: var(--muted); }

/* ===== CTA BAND ===== */
.cta-band {
  padding: clamp(48px, 7vw, 88px) 0;
  background:
    radial-gradient(100% 140% at 20% 0%, var(--crimson-d), transparent 60%),
    linear-gradient(180deg, var(--crimson), var(--crimson-d));
  border-top: 1px solid var(--line);
}
.cta-band__inner {
  display: grid;
  grid-template-columns: 1fr 0.95fr;
  gap: clamp(28px, 5vw, 64px);
  align-items: center;
}
.cta-band__copy h2 {
  color: #fff;
  font-size: clamp(2rem, 4vw, 3rem);
  margin: 12px 0 12px;
}
.cta-band__copy p {
  color: rgba(255, 255, 255, 0.85);
  font-size: 1.04rem;
  max-width: 42ch;
}
.trial-form {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 26px;
  display: grid;
  gap: 14px;
  box-shadow: var(--shadow-lg);
}
.field { display: grid; gap: 6px; }
.field label {
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}
.field input,
.field select {
  font-family: var(--sans);
  font-size: 0.96rem;
  color: var(--ink);
  background: var(--bg);
  border: 1px solid var(--line-2);
  border-radius: var(--r-sm);
  padding: 12px 14px;
  transition: border-color 0.16s ease, box-shadow 0.16s ease;
}
.field input::placeholder { color: var(--muted); }
.field input:focus,
.field select:focus {
  outline: none;
  border-color: var(--crimson);
  box-shadow: 0 0 0 3px var(--crimson-soft);
}
.field input.is-invalid { border-color: var(--crimson); }
.field select { appearance: none; cursor: pointer; }

/* ===== FOOTER ===== */
.footer {
  background: var(--bg);
  border-top: 1px solid var(--line);
  padding: 44px 0 36px;
}
.footer__inner {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 24px;
  align-items: start;
}
.footer__brand {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}
.footer__brand p { color: var(--ink-2); font-size: 0.9rem; }
.footer__links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 22px;
  justify-content: flex-end;
}
.footer__links a {
  color: var(--ink-2);
  font-weight: 600;
  font-size: 0.9rem;
  transition: color 0.16s ease;
}
.footer__links a:hover { color: var(--crimson); }
.footer__fine {
  grid-column: 1 / -1;
  margin-top: 22px;
  padding-top: 22px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.82rem;
}

/* ===== TOAST ===== */
.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 140%);
  background: var(--elevated);
  color: var(--ink);
  border: 1px solid var(--line-2);
  border-left: 3px solid var(--crimson);
  border-radius: var(--r-md);
  padding: 14px 20px;
  font-weight: 600;
  font-size: 0.92rem;
  box-shadow: var(--shadow-lg);
  z-index: 300;
  opacity: 0;
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.3s ease;
  max-width: calc(100% - 32px);
}
.toast.is-visible { transform: translate(-50%, 0); opacity: 1; }

/* ===== REVEAL ===== */
.reveal {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 0.6s ease, transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}
.reveal.is-in { opacity: 1; transform: none; }

/* ===== RESPONSIVE ===== */
@media (max-width: 900px) {
  .hero__inner { grid-template-columns: 1fr; }
  .hero__card { max-width: 460px; }
  .cta-band__inner { grid-template-columns: 1fr; }
  .footer__inner { grid-template-columns: 1fr; }
  .footer__links { justify-content: flex-start; }
}

@media (max-width: 760px) {
  .nav__links, .nav__cta { display: none; }
  .nav__toggle { display: flex; }
  .sched__row {
    grid-template-columns: 70px 1fr;
    grid-template-areas:
      "time class"
      "time meta";
    row-gap: 6px;
  }
  .sched__row--head { display: none; }
  .sched__time { grid-area: time; align-self: start; }
  .sched__class { grid-area: class; }
  .sched__coach { grid-area: meta; }
  .sched__row span:last-child { grid-area: meta; justify-self: end; }
}

@media (max-width: 520px) {
  .container { width: min(1140px, 100% - 28px); }
  .hero__stats { gap: 18px 28px; }
  .hero__stats strong { font-size: 1.7rem; }
  .hero__actions .btn { flex: 1 1 100%; }
  .section { padding: 52px 0; }
  .d-card__badge { font-size: 2rem; }
  .path-step {
    grid-template-columns: 40px 6px 1fr;
    gap: 14px;
  }
  .coach-row { grid-template-columns: 1fr 1fr; }
  .coach { padding: 20px 14px; }
  .trial-form { padding: 20px; }
  .toast { bottom: 16px; }
}

@media (max-width: 380px) {
  .coach-row { grid-template-columns: 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  * { scroll-behavior: auto !important; }
  .reveal { opacity: 1; transform: none; transition: none; }
  .tag--live::before { animation: none; }
}

