(function () {
  "use strict";

  /* ---------- Toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("is-visible");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("is-visible");
    }, 3200);
  }

  /* ---------- Sticky nav shadow ---------- */
  var nav = document.getElementById("nav");
  function onScroll() {
    if (!nav) return;
    nav.classList.toggle("is-scrolled", window.scrollY > 8);
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  /* ---------- Mobile menu ---------- */
  var toggle = document.getElementById("navToggle");
  var menu = document.getElementById("mobileMenu");
  function closeMenu() {
    if (!toggle || !menu) return;
    toggle.setAttribute("aria-expanded", "false");
    toggle.setAttribute("aria-label", "Open menu");
    menu.hidden = true;
  }
  if (toggle && menu) {
    toggle.addEventListener("click", function () {
      var open = toggle.getAttribute("aria-expanded") === "true";
      if (open) {
        closeMenu();
      } else {
        toggle.setAttribute("aria-expanded", "true");
        toggle.setAttribute("aria-label", "Close menu");
        menu.hidden = false;
      }
    });
    menu.querySelectorAll("a").forEach(function (a) {
      a.addEventListener("click", closeMenu);
    });
    window.addEventListener("keydown", function (e) {
      if (e.key === "Escape") closeMenu();
    });
  }

  /* ---------- Smooth-scroll to trial form ---------- */
  document.querySelectorAll("[data-trial]").forEach(function (el) {
    el.addEventListener("click", function (e) {
      var target = document.getElementById("trial");
      if (!target) return;
      e.preventDefault();
      target.scrollIntoView({ behavior: "smooth", block: "start" });
      var name = document.getElementById("tName");
      if (name) setTimeout(function () { name.focus({ preventScroll: true }); }, 500);
    });
  });

  /* ---------- Discipline filter (tabs) ---------- */
  var chips = Array.prototype.slice.call(document.querySelectorAll(".chip[data-filter]"));
  var dCards = Array.prototype.slice.call(document.querySelectorAll(".d-card[data-tags]"));
  chips.forEach(function (chip) {
    chip.addEventListener("click", function () {
      var filter = chip.getAttribute("data-filter");
      chips.forEach(function (c) {
        var active = c === chip;
        c.classList.toggle("is-active", active);
        c.setAttribute("aria-selected", active ? "true" : "false");
      });
      var shown = 0;
      dCards.forEach(function (card) {
        var tags = card.getAttribute("data-tags") || "";
        var match = filter === "all" || tags.indexOf(filter) !== -1;
        card.classList.toggle("is-hidden", !match);
        if (match) shown++;
      });
      toast(
        filter === "all"
          ? "Showing all disciplines"
          : shown + " " + filter + " discipline" + (shown === 1 ? "" : "s")
      );
    });
  });

  /* ---------- Discipline "view program" CTAs ---------- */
  document.querySelectorAll(".d-card__cta[data-discipline]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      var name = btn.getAttribute("data-discipline");
      toast(name + " program details sent to your inbox — check soon.");
    });
  });

  /* ---------- Reveal on scroll ---------- */
  var revealEls = Array.prototype.slice.call(document.querySelectorAll(".reveal"));
  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-in");
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -40px 0px" }
    );
    revealEls.forEach(function (el) { io.observe(el); });
  } else {
    revealEls.forEach(function (el) { el.classList.add("is-in"); });
  }

  /* ---------- Animated stat counters ---------- */
  var counters = Array.prototype.slice.call(document.querySelectorAll("[data-count]"));
  function animateCount(el) {
    var target = parseInt(el.getAttribute("data-count"), 10) || 0;
    var start = performance.now();
    var dur = 1100;
    function tick(now) {
      var p = Math.min((now - start) / dur, 1);
      var eased = 1 - Math.pow(1 - p, 3);
      el.textContent = Math.round(target * eased) + "+";
      if (p < 1) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }
  if ("IntersectionObserver" in window) {
    var co = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            animateCount(entry.target);
            co.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.6 }
    );
    counters.forEach(function (el) { co.observe(el); });
  } else {
    counters.forEach(function (el) {
      el.textContent = el.getAttribute("data-count") + "+";
    });
  }

  /* ---------- Trial form validation ---------- */
  var form = document.getElementById("trialForm");
  if (form) {
    var nameInput = document.getElementById("tName");
    var emailInput = document.getElementById("tEmail");
    var emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    [nameInput, emailInput].forEach(function (inp) {
      if (!inp) return;
      inp.addEventListener("input", function () {
        inp.classList.remove("is-invalid");
      });
    });

    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var ok = true;
      if (!nameInput.value.trim()) {
        nameInput.classList.add("is-invalid");
        ok = false;
      }
      if (!emailRe.test(emailInput.value.trim())) {
        emailInput.classList.add("is-invalid");
        ok = false;
      }
      if (!ok) {
        toast("Please add your name and a valid email.");
        (nameInput.classList.contains("is-invalid") ? nameInput : emailInput).focus();
        return;
      }
      var discipline = document.getElementById("tDiscipline").value;
      toast("Trial booked! We'll email " + nameInput.value.trim() + " about " + discipline + ".");
      form.reset();
    });
  }
})();

snippets.css:
:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.4);
  --shadow-md: 0 12px 30px rgba(0, 0, 0, 0.45);
  --shadow-lg: 0 28px 60px rgba(0, 0, 0, 0.55);
  --maxw: 1160px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
  padding: 0;
}

.container {
  width: 100%;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 22px;
}

.sr-only,
.skip-link {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip-link:focus {
  position: fixed;
  top: 12px;
  left: 12px;
  width: auto;
  height: auto;
  clip: auto;
  z-index: 200;
  background: var(--neon);
  color: #0b0d10;
  padding: 10px 16px;
  border-radius: var(--r-sm);
  font-weight: 700;
}

:focus-visible {
  outline: 3px solid var(--neon);
  outline-offset: 2px;
  border-radius: 4px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-size: 0.72rem;
  font-weight: 800;
  color: var(--neon);
}

/* ===== Buttons ===== */
.btn {
  --btn-bg: transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-weight: 700;
  font-size: 0.95rem;
  line-height: 1;
  padding: 13px 20px;
  border-radius: var(--r-md);
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.2s ease,
    background 0.2s ease, border-color 0.2s ease, color 0.2s ease;
  white-space: nowrap;
}

.btn:active {
  transform: translateY(1px) scale(0.99);
}

.btn-neon {
  background: var(--neon);
  color: #0b0d10;
  box-shadow: 0 8px 22px var(--neon-50);
}

.btn-neon:hover {
  background: var(--neon-d);
  box-shadow: 0 12px 30px rgba(198, 255, 58, 0.28);
  transform: translateY(-2px);
}

.btn-outline {
  border-color: var(--line-2);
  color: var(--ink);
  background: rgba(255, 255, 255, 0.02);
}

.btn-outline:hover {
  border-color: var(--neon);
  color: var(--neon);
  transform: translateY(-2px);
}

.btn-ghost {
  color: var(--ink-2);
  padding: 13px 14px;
}

.btn-ghost:hover {
  color: var(--ink);
}

.btn-lg {
  padding: 16px 28px;
  font-size: 1.02rem;
}

.btn-sm {
  padding: 10px 16px;
  font-size: 0.85rem;
}

.btn-block {
  width: 100%;
}

/* ===== Header ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13, 15, 18, 0.72);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid transparent;
  transition: border-color 0.25s ease, background 0.25s ease;
}

.site-header.scrolled {
  border-bottom-color: var(--line);
  background: rgba(13, 15, 18, 0.92);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 18px;
  height: 70px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 900;
}

.brand-mark {
  color: var(--neon);
  font-size: 1.25rem;
  letter-spacing: -2px;
  transform: skewX(-8deg);
}

.brand-name {
  font-weight: 900;
  letter-spacing: 0.08em;
  font-size: 1.1rem;
}

.nav {
  display: flex;
  gap: 26px;
  margin-left: 28px;
}

.nav a {
  color: var(--ink-2);
  font-weight: 600;
  font-size: 0.95rem;
  position: relative;
  padding: 4px 0;
  transition: color 0.18s ease;
}

.nav a::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -2px;
  height: 2px;
  width: 0;
  background: var(--neon);
  transition: width 0.22s ease;
}

.nav a:hover {
  color: var(--ink);
}

.nav a:hover::after {
  width: 100%;
}

.header-cta {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
}

.nav-toggle {
  display: none;
  margin-left: auto;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: 0;
  padding: 8px;
  cursor: pointer;
}

.nav-toggle span {
  width: 24px;
  height: 2px;
  background: var(--ink);
  border-radius: 2px;
  transition: transform 0.25s ease, opacity 0.2s ease;
}

.nav-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.nav-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}
.nav-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* ===== Hero ===== */
.hero {
  position: relative;
  padding: clamp(56px, 11vw, 130px) 0 clamp(50px, 8vw, 96px);
  overflow: hidden;
}

.hero-glow {
  position: absolute;
  inset: -20% -10% auto -10%;
  height: 620px;
  background: radial-gradient(
      60% 70% at 22% 18%,
      rgba(198, 255, 58, 0.16),
      transparent 62%
    ),
    radial-gradient(
      55% 65% at 88% 8%,
      rgba(255, 106, 43, 0.14),
      transparent 60%
    );
  filter: blur(8px);
  pointer-events: none;
}

.hero-inner {
  position: relative;
  max-width: 760px;
}

.hero-title {
  font-size: clamp(2.8rem, 9vw, 5.6rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 0.96;
  margin: 16px 0 0;
  text-transform: uppercase;
}

.hero-title .accent {
  color: var(--neon);
  position: relative;
}

.hero-sub {
  color: var(--ink-2);
  font-size: clamp(1.02rem, 2.4vw, 1.25rem);
  max-width: 540px;
  margin: 22px 0 0;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 32px;
}

.hero-trust {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 30px;
  color: var(--muted);
  font-size: 0.92rem;
}

.hero-trust strong {
  color: var(--ink);
}

.avatars {
  display: flex;
}

.avatars span {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 0.7rem;
  font-weight: 800;
  color: #0b0d10;
  background: linear-gradient(135deg, var(--neon), var(--neon-d));
  border: 2px solid var(--bg);
  margin-left: -10px;
}

.avatars span:first-child {
  margin-left: 0;
}

.avatars span:nth-child(2) {
  background: linear-gradient(135deg, var(--orange), #ff8a5b);
}
.avatars span:nth-child(3) {
  background: linear-gradient(135deg, #6ea8ff, #3d7bff);
  color: #fff;
}
.avatars span:nth-child(4) {
  background: linear-gradient(135deg, #f0f3f6, #c2c8d0);
}

/* ===== Stats ===== */
.stats {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
}

.stat {
  padding: 30px 14px;
  text-align: center;
  position: relative;
}

.stat:not(:last-child)::after {
  content: "";
  position: absolute;
  right: 0;
  top: 22%;
  height: 56%;
  width: 1px;
  background: var(--line);
}

.stat-num {
  display: block;
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 900;
  letter-spacing: -0.02em;
  color: var(--neon);
  line-height: 1;
}

.stat-label {
  display: block;
  margin-top: 8px;
  color: var(--muted);
  font-size: 0.82rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 600;
}

/* ===== Sections ===== */
.section {
  padding: clamp(56px, 9vw, 100px) 0;
}

.section-alt {
  background: var(--surface);
}

.section-head {
  max-width: 620px;
  margin: 0 auto 44px;
  text-align: center;
}

.section-title {
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 900;
  letter-spacing: -0.02em;
  margin-top: 12px;
  text-transform: uppercase;
}

.section-lead {
  color: var(--ink-2);
  margin-top: 14px;
  font-size: 1.02rem;
}

/* ===== Class grid ===== */
.class-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.class-card {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.22s ease, border-color 0.22s ease,
    box-shadow 0.22s ease;
}

.class-card:hover {
  transform: translateY(-6px);
  border-color: var(--line-2);
  box-shadow: var(--shadow-md);
}

.class-media {
  position: relative;
  aspect-ratio: 5 / 4;
  background-size: cover;
  background-position: center;
}

.media-1 {
  background: linear-gradient(140deg, #1f2a12, #3a5c12),
    radial-gradient(80% 60% at 70% 20%, rgba(198, 255, 58, 0.35), transparent);
}
.media-2 {
  background: linear-gradient(140deg, #25180f, #5c2c12),
    radial-gradient(80% 60% at 30% 20%, rgba(255, 106, 43, 0.4), transparent);
}
.media-3 {
  background: linear-gradient(140deg, #11212a, #18465c),
    radial-gradient(80% 60% at 70% 30%, rgba(110, 168, 255, 0.35), transparent);
}
.media-4 {
  background: linear-gradient(140deg, #221230, #4a1a5c),
    radial-gradient(80% 60% at 30% 25%, rgba(200, 110, 255, 0.35), transparent);
}

.tag {
  position: absolute;
  top: 12px;
  left: 12px;
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 800;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(13, 15, 18, 0.7);
  color: var(--ink);
  backdrop-filter: blur(6px);
}

.tag-hot {
  background: var(--neon);
  color: #0b0d10;
}

.tag-new {
  background: var(--orange);
  color: #0b0d10;
}

.class-body {
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}

.class-body h3 {
  font-size: 1.15rem;
  font-weight: 800;
}

.class-body p {
  color: var(--ink-2);
  font-size: 0.9rem;
}

.meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 600;
  margin-top: 2px;
}

.class-body .btn {
  margin-top: auto;
}

/* ===== Trainers ===== */
.trainer-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.trainer {
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  transition: transform 0.22s ease, border-color 0.22s ease;
}

.trainer:hover {
  transform: translateY(-6px);
  border-color: var(--neon);
}

.trainer-photo {
  aspect-ratio: 1 / 1;
  position: relative;
}

.t-1 {
  background: linear-gradient(160deg, #3a5c12, #1f2a12);
}
.t-2 {
  background: linear-gradient(160deg, #5c2c12, #25180f);
}
.t-3 {
  background: linear-gradient(160deg, #18465c, #11212a);
}
.t-4 {
  background: linear-gradient(160deg, #4a1a5c, #221230);
}

.trainer-photo::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    60% 60% at 50% 30%,
    rgba(255, 255, 255, 0.12),
    transparent 70%
  );
}

.trainer figcaption {
  padding: 16px 18px 20px;
}

.trainer figcaption h3 {
  font-size: 1.05rem;
  font-weight: 800;
}

.trainer figcaption p {
  color: var(--muted);
  font-size: 0.85rem;
  margin-top: 3px;
}

/* ===== Pricing ===== */
.tier-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
  align-items: start;
}

.tier {
  position: relative;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 28px 24px;
  transition: transform 0.22s ease, border-color 0.22s ease;
}

.tier:hover {
  transform: translateY(-4px);
  border-color: var(--line-2);
}

.tier-feat {
  border-color: var(--neon);
  background: linear-gradient(
    180deg,
    rgba(198, 255, 58, 0.06),
    var(--surface-2) 40%
  );
  box-shadow: var(--shadow-md);
}

.tier-badge {
  position: absolute;
  top: -12px;
  left: 24px;
  background: var(--neon);
  color: #0b0d10;
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 800;
  padding: 6px 12px;
  border-radius: 999px;
}

.tier-name {
  font-size: 1.05rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ink-2);
}

.tier-price {
  margin: 12px 0 20px;
  color: var(--muted);
  font-weight: 600;
}

.tier-price span {
  font-size: 2.6rem;
  font-weight: 900;
  color: var(--ink);
  letter-spacing: -0.02em;
}

.tier-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.tier-list li {
  position: relative;
  padding-left: 28px;
  color: var(--ink-2);
  font-size: 0.92rem;
}

.tier-list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 2px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--neon-50);
  background-image: linear-gradient(var(--neon), var(--neon));
  background-size: 9px 2px, 2px 9px;
  background-position: center;
  background-repeat: no-repeat;
}

/* ===== Rotator / testimonials ===== */
.rotator {
  max-width: 760px;
  margin: 0 auto;
  text-align: center;
}

.rotator-track {
  position: relative;
  min-height: 220px;
}

.quote {
  position: absolute;
  inset: 0;
  opacity: 0;
  transform: translateY(14px);
  transition: opacity 0.5s ease, transform 0.5s ease;
  pointer-events: none;
}

.quote.is-active {
  opacity: 1;
  transform: translateY(0);
  position: relative;
  pointer-events: auto;
}

.quote blockquote {
  font-size: clamp(1.15rem, 3vw, 1.6rem);
  font-weight: 600;
  line-height: 1.4;
  color: var(--ink);
}

.quote-by {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-top: 26px;
  text-align: left;
}

.q-avatar {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 800;
  font-size: 0.85rem;
  color: #0b0d10;
  background: linear-gradient(135deg, var(--neon), var(--neon-d));
}

.quote-by strong {
  font-weight: 800;
}

.quote-by p {
  color: var(--muted);
  font-size: 0.85rem;
}

.rotator-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 34px;
}

.rotator-dots button {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  border: 0;
  background: var(--line-2);
  cursor: pointer;
  padding: 0;
  transition: width 0.25s ease, background 0.25s ease;
}

.rotator-dots button[aria-selected="true"] {
  width: 28px;
  background: var(--neon);
}

/* ===== CTA band ===== */
.cta-band {
  position: relative;
  padding: clamp(60px, 10vw, 110px) 0;
  background: var(--surface-2);
  overflow: hidden;
  border-top: 1px solid var(--line);
}

.cta-glow {
  position: absolute;
  inset: auto -10% -50% -10%;
  height: 520px;
  background: radial-gradient(
    50% 70% at 50% 100%,
    rgba(198, 255, 58, 0.18),
    transparent 65%
  );
  pointer-events: none;
}

.cta-inner {
  position: relative;
  max-width: 640px;
  margin: 0 auto;
  text-align: center;
}

.cta-inner h2 {
  font-size: clamp(2rem, 6vw, 3.4rem);
  font-weight: 900;
  letter-spacing: -0.02em;
  text-transform: uppercase;
}

.cta-inner > p {
  color: var(--ink-2);
  margin-top: 14px;
  font-size: 1.05rem;
}

.cta-form {
  display: flex;
  gap: 10px;
  margin: 30px auto 0;
  max-width: 480px;
}

.cta-form input {
  flex: 1;
  background: var(--bg);
  border: 1px solid var(--line-2);
  border-radius: var(--r-md);
  color: var(--ink);
  font: inherit;
  padding: 16px 18px;
  transition: border-color 0.2s ease;
}

.cta-form input::placeholder {
  color: var(--muted);
}

.cta-form input:focus {
  border-color: var(--neon);
  outline: none;
}

.cta-form input.invalid {
  border-color: var(--danger);
}

.cta-fine {
  color: var(--muted);
  font-size: 0.85rem;
  margin-top: 18px;
}

/* ===== Footer ===== */
.site-footer {
  border-top: 1px solid var(--line);
  background: var(--surface);
  padding: 56px 0 28px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr 1.2fr;
  gap: 30px;
}

.footer-brand p {
  color: var(--muted);
  font-size: 0.9rem;
  margin-top: 12px;
  max-width: 260px;
}

.site-footer h4 {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--ink-2);
  margin-bottom: 14px;
}

.site-footer nav {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.site-footer nav a {
  color: var(--muted);
  font-size: 0.92rem;
  transition: color 0.18s ease;
}

.site-footer nav a:hover {
  color: var(--neon);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 44px;
  padding-top: 22px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.82rem;
}

/* ===== Toast ===== */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 140%);
  background: var(--elevated);
  color: var(--ink);
  border: 1px solid var(--line-2);
  border-left: 3px solid var(--neon);
  padding: 14px 20px;
  border-radius: var(--r-md);
  font-weight: 600;
  font-size: 0.92rem;
  box-shadow: var(--shadow-lg);
  z-index: 300;
  opacity: 0;
  transition: transform 0.35s cubic-bezier(0.2, 0.9, 0.3, 1), opacity 0.3s ease;
  max-width: calc(100% - 32px);
}

.toast.show {
  transform: translate(-50%, 0);
  opacity: 1;
}

/* ===== Reveal animation ===== */
.reveal {
  opacity: 0;
  transform: translateY(22px);
  transition: opacity 0.6s ease, transform 0.6s ease;
  will-change: opacity, transform;
}

.reveal.in {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
  html {
    scroll-behavior: auto;
  }
}

/* ===== Responsive ===== */
@media (max-width: 980px) {
  .class-grid,
  .trainer-row {
    grid-template-columns: repeat(2, 1fr);
  }
  .tier-grid {
    grid-template-columns: 1fr;
    max-width: 460px;
    margin: 0 auto;
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 760px) {
  .nav,
  .header-cta {
    display: none;
  }
  .nav-toggle {
    display: flex;
  }
  .site-header.nav-open .nav {
    display: flex;
    position: absolute;
    top: 70px;
    left: 0;
    right: 0;
    flex-direction: column;
    gap: 0;
    margin: 0;
    background: var(--surface);
    border-bottom: 1px solid var(--line);
    padding: 8px 0;
  }
  .site-header.nav-open .nav a {
    padding: 14px 22px;
  }
  .site-header.nav-open .header-cta {
    display: flex;
    position: absolute;
    top: calc(70px + 4 * 50px);
    left: 0;
    right: 0;
    flex-direction: column;
    gap: 8px;
    padding: 14px 22px 18px;
    background: var(--surface);
    border-bottom: 1px solid var(--line);
  }
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .stat:nth-child(2)::after {
    display: none;
  }
}

@media (max-width: 520px) {
  .container {
    padding: 0 16px;
  }
  .class-grid,
  .trainer-row,
  .footer-grid {
    grid-template-columns: 1fr;
  }
  .footer-brand p {
    max-width: none;
  }
  .hero-actions .btn,
  .cta-form .btn {
    width: 100%;
  }
  .cta-form {
    flex-direction: column;
  }
  .hero-trust {
    align-items: flex-start;
    flex-direction: column;
    gap: 10px;
  }
  .footer-bottom {
    flex-direction: column;
  }
}

