(function () {
  "use strict";

  /* ---------- Toast helper ---------- */
  const toastEl = document.querySelector("[data-toast]");
  let toastTimer;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("is-visible");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toastEl.classList.remove("is-visible"), 3200);
  }

  /* ---------- Sticky topbar shadow ---------- */
  const topbar = document.querySelector(".topbar");
  const onScroll = () => {
    if (!topbar) return;
    topbar.classList.toggle("is-scrolled", window.scrollY > 24);
  };
  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  /* ---------- Smooth scroll for data-scroll buttons ---------- */
  document.querySelectorAll("[data-scroll]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const target = document.querySelector(btn.getAttribute("data-scroll"));
      if (target) target.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });

  /* ---------- Reveal on scroll ---------- */
  const reveals = document.querySelectorAll(".reveal");
  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-in");
            io.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.14, rootMargin: "0px 0px -40px 0px" }
    );
    reveals.forEach((el) => io.observe(el));
  } else {
    reveals.forEach((el) => el.classList.add("is-in"));
  }

  /* ---------- Featured estate switcher ---------- */
  const heroData = [
    {
      title: "Estates composed<br /><em>for a quieter life.</em>",
      lede: "A discreet portfolio of architecturally significant residences across coast, canyon and old-world capitals — represented by invitation.",
    },
    {
      title: "A mountain house,<br /><em>carved into light.</em>",
      lede: "Eight bedrooms above the Highlands, glass to the tree line, and thirty-five private acres an hour from the slopes.",
    },
    {
      title: "Lake water,<br /><em>framed in stone.</em>",
      lede: "A restored lakeside villa on Como — terraced gardens, a private dock, and frescoes returned to their original hand.",
    },
  ];
  const heroPhoto = document.querySelector("[data-hero-photo]");
  const heroTitle = document.querySelector(".hero__title");
  const heroLede = document.querySelector(".hero__lede");
  const switches = Array.from(document.querySelectorAll(".hswitch"));

  function setHero(idx) {
    const data = heroData[idx];
    if (!data) return;
    switches.forEach((s, i) => {
      const active = i === idx;
      s.classList.toggle("is-active", active);
      s.setAttribute("aria-selected", active ? "true" : "false");
    });
    if (heroPhoto) {
      heroPhoto.style.opacity = "0";
      setTimeout(() => {
        heroPhoto.setAttribute("data-variant", String(idx));
        heroPhoto.style.opacity = "1";
      }, 260);
    }
    if (heroTitle) heroTitle.innerHTML = data.title;
    if (heroLede) heroLede.textContent = data.lede;
  }
  if (heroPhoto) heroPhoto.setAttribute("data-variant", "0");
  switches.forEach((s, i) => {
    s.addEventListener("click", () => setHero(i));
  });

  // auto-rotate hero, pause on interaction
  let autoIdx = 0;
  let autoTimer = setInterval(rotate, 6500);
  function rotate() {
    autoIdx = (autoIdx + 1) % heroData.length;
    setHero(autoIdx);
  }
  switches.forEach((s, i) => {
    s.addEventListener("click", () => {
      autoIdx = i;
      clearInterval(autoTimer);
      autoTimer = setInterval(rotate, 9000);
    });
  });

  /* ---------- Listing filters ---------- */
  const chips = Array.from(document.querySelectorAll(".chip"));
  const cards = Array.from(document.querySelectorAll(".card"));
  chips.forEach((chip) => {
    chip.addEventListener("click", () => {
      chips.forEach((c) => c.classList.remove("is-active"));
      chip.classList.add("is-active");
      const filter = chip.getAttribute("data-filter");
      let shown = 0;
      cards.forEach((card) => {
        const match = filter === "all" || card.getAttribute("data-kind") === filter;
        card.classList.toggle("is-hidden", !match);
        if (match) shown++;
      });
      toast(
        shown +
          (shown === 1 ? " residence" : " residences") +
          (filter === "all" ? " in the collection" : " · " + chip.textContent.trim())
      );
    });
  });

  /* ---------- Card activation (keyboard + click) ---------- */
  cards.forEach((card) => {
    const open = () => {
      const title = card.querySelector(".card__title");
      toast("Requesting details — " + (title ? title.textContent : "residence"));
    };
    card.addEventListener("click", open);
    card.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        open();
      }
    });
  });

  /* ---------- Inquiry bar ---------- */
  const inquiry = document.querySelector("[data-inquiry]");
  if (inquiry) {
    inquiry.addEventListener("submit", (e) => {
      e.preventDefault();
      const loc = inquiry.querySelector("#loc").value;
      const kind = inquiry.querySelector("#kind").value;
      toast("Portfolio en route — " + kind + " · " + loc);
    });
  }

  /* ---------- CTA form ---------- */
  const ctaForm = document.querySelector("[data-cta]");
  if (ctaForm) {
    ctaForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const name = (ctaForm.querySelector('[name="name"]').value || "").trim();
      const first = name.split(" ")[0] || "there";
      toast("Thank you, " + first + " — an advisor will be in touch within one business day.");
      ctaForm.reset();
    });
  }
})();

snippets.css:
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 18px 50px rgba(15, 29, 54, 0.22);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* ── Nav ── */
.nav {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 20px 40px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
  color: var(--bone);
}
.brand-mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.4rem;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 700;
  letter-spacing: 0.01em;
}
.brand-name em {
  font-style: normal;
  color: var(--gold-light);
}
.nav-links {
  display: flex;
  gap: 26px;
  margin-left: auto;
}
.nav-links a {
  color: rgba(251, 248, 242, 0.86);
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 500;
}
.nav-links a:hover {
  color: var(--bone);
}
.nav-actions {
  display: flex;
  align-items: center;
  gap: 18px;
}
.nav-link {
  color: rgba(251, 248, 242, 0.86);
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 500;
}
.nav-link:hover {
  color: var(--bone);
}
.nav-cta {
  background: rgba(251, 248, 242, 0.12);
  border: 1px solid rgba(251, 248, 242, 0.3);
  color: var(--bone);
  font-family: inherit;
  font-size: 0.86rem;
  font-weight: 600;
  padding: 9px 16px;
  border-radius: 999px;
  cursor: pointer;
}
.nav-cta:hover {
  background: rgba(251, 248, 242, 0.2);
}

/* ── Hero ── */
.hero {
  position: relative;
  min-height: 620px;
  padding: 150px 40px 90px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  color: var(--bone);
  background: linear-gradient(135deg, var(--navy-d) 0%, var(--navy) 55%, var(--navy-2) 100%);
  overflow: hidden;
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(120% 90% at 80% 10%, rgba(201, 166, 73, 0.22), transparent 55%),
    radial-gradient(80% 80% at 0% 100%, rgba(45, 69, 112, 0.5), transparent 60%);
  pointer-events: none;
}
.hero-copy {
  position: relative;
  max-width: 640px;
  margin-bottom: 34px;
}
.eyebrow {
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--gold-light);
  font-weight: 600;
}
.hero h1 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(2.6rem, 6vw, 4.4rem);
  line-height: 1.02;
  letter-spacing: -0.01em;
  margin: 10px 0 16px;
}
.lede {
  font-size: 1.05rem;
  line-height: 1.6;
  color: rgba(251, 248, 242, 0.82);
  max-width: 520px;
}

/* ── Search card ── */
.search {
  position: relative;
  background: var(--bone);
  color: var(--ink);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-2);
  padding: 16px;
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1.2fr auto;
  gap: 10px;
  align-items: end;
  max-width: 1040px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  position: relative;
  padding: 4px 6px;
}
.field + .field {
  border-left: 1px solid var(--line);
}
.field label {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 700;
  color: var(--gold-d);
}
.field select,
.field input {
  font-family: inherit;
  font-size: 0.96rem;
  font-weight: 600;
  color: var(--navy-d);
  border: none;
  background: transparent;
  outline: none;
  padding: 4px 0;
  width: 100%;
}
.field select {
  cursor: pointer;
  appearance: none;
}
.guests-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  background: transparent;
  border: none;
  font-family: inherit;
  font-size: 0.96rem;
  font-weight: 600;
  color: var(--navy-d);
  cursor: pointer;
  padding: 4px 0;
}
.caret {
  color: var(--warm-gray);
  font-size: 0.8rem;
}
.guests-pop {
  position: absolute;
  top: calc(100% + 12px);
  left: 0;
  width: 300px;
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  box-shadow: var(--shadow-2);
  padding: 8px 16px 16px;
  z-index: 20;
}
.stepper {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 0;
  border-bottom: 1px solid var(--line);
}
.stepper strong {
  display: block;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ink);
}
.stepper small {
  font-size: 0.74rem;
  color: var(--warm-gray);
}
.step-ctrl {
  display: flex;
  align-items: center;
  gap: 12px;
}
.step {
  width: 32px;
  height: 32px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  background: transparent;
  color: var(--navy-d);
  font-size: 1.2rem;
  line-height: 1;
  cursor: pointer;
  display: grid;
  place-items: center;
}
.step:hover:not(:disabled) {
  border-color: var(--navy-2);
  background: var(--cream);
}
.step:disabled {
  opacity: 0.35;
  cursor: default;
}
.step-val {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.95rem;
  min-width: 18px;
  text-align: center;
  color: var(--navy-d);
}
.guests-done {
  width: 100%;
  margin-top: 14px;
  background: var(--navy);
  color: var(--bone);
  border: none;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.86rem;
  padding: 10px;
  border-radius: var(--r-sm);
  cursor: pointer;
}
.guests-done:hover {
  background: var(--navy-d);
}

.search-btn {
  background: var(--gold);
  color: var(--navy-d);
  border: none;
  font-family: inherit;
  font-weight: 700;
  font-size: 0.96rem;
  padding: 15px 26px;
  border-radius: var(--r-md);
  cursor: pointer;
  white-space: nowrap;
  align-self: stretch;
}
.search-btn:hover {
  background: var(--gold-light);
}
.search-summary {
  grid-column: 1 / -1;
  font-size: 0.84rem;
  color: var(--warm-gray);
  padding: 4px 6px 2px;
  min-height: 1.2em;
}
.search-summary strong {
  color: var(--navy-d);
  font-weight: 700;
}
.search-summary.error {
  color: var(--danger);
  font-weight: 600;
}

/* ── Perks ── */
.perks {
  max-width: 1100px;
  margin: -42px auto 0;
  position: relative;
  z-index: 5;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  padding: 0 40px;
}
.perk {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 18px;
  display: flex;
  align-items: center;
  gap: 14px;
  box-shadow: var(--shadow-1);
}
.perk-ic {
  width: 42px;
  height: 42px;
  flex-shrink: 0;
  border-radius: var(--r-md);
  display: grid;
  place-items: center;
  background: rgba(201, 166, 73, 0.16);
  color: var(--gold-d);
  font-size: 1.2rem;
  font-weight: 700;
}
.perk strong {
  display: block;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--ink);
}
.perk small {
  font-size: 0.78rem;
  color: var(--warm-gray);
}

/* ── Featured ── */
.featured {
  max-width: 1100px;
  margin: 72px auto 90px;
  padding: 0 40px;
}
.featured-head {
  text-align: center;
  margin-bottom: 28px;
}
.featured-head h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 2.4rem;
  color: var(--navy-d);
  margin-top: 4px;
}
.featured-head .eyebrow {
  color: var(--gold-d);
}
.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 22px;
}
.stay {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  overflow: hidden;
  box-shadow: var(--shadow-1);
  transition: transform 0.18s, box-shadow 0.18s;
}
.stay:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-2);
}
.stay-img {
  height: 180px;
  background: linear-gradient(135deg, var(--navy-2), var(--navy-d));
  position: relative;
}
.stay-img[data-room="deluxe"] {
  background: linear-gradient(135deg, #3a5180, #1a2b4a);
}
.stay-img[data-room="junior"] {
  background: linear-gradient(135deg, #6c7280, #2e3a52);
}
.stay-img[data-room="signature"] {
  background: linear-gradient(135deg, var(--gold-d), #5a4a1e);
}
.stay-img::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(60% 80% at 70% 20%, rgba(255, 255, 255, 0.12), transparent 60%);
}
.stay-body {
  padding: 18px 20px 22px;
}
.stay-body h3 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.5rem;
  color: var(--navy-d);
}
.stay-body p {
  font-size: 0.84rem;
  color: var(--warm-gray);
  margin-top: 4px;
}
.stay-price {
  margin-top: 12px !important;
  font-size: 0.86rem;
  color: var(--ink-2) !important;
}
.stay-price strong {
  font-family: var(--font-display);
  font-size: 1.4rem;
  color: var(--gold-d);
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 12px 22px;
  border-radius: 999px;
  font-size: 0.88rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 50;
}

/* ── Responsive ── */
@media (max-width: 1080px) {
  .search {
    grid-template-columns: 1fr 1fr;
  }
  .field + .field {
    border-left: none;
  }
  .search-btn {
    grid-column: 1 / -1;
  }
  .perks {
    grid-template-columns: repeat(2, 1fr);
  }
  .cards {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 720px) {
  .nav-links {
    display: none;
  }
  .nav {
    padding: 16px 20px;
  }
  .hero {
    padding: 120px 20px 80px;
  }
  .search {
    grid-template-columns: 1fr;
  }
  .perks,
  .featured {
    padding: 0 20px;
  }
  .perks {
    grid-template-columns: 1fr;
  }
  .guests-pop {
    width: 100%;
  }
}

