// ── Date defaults: check-in tomorrow, check-out +2 nights ─────────────────────
const checkin = document.getElementById("checkin");
const checkout = document.getElementById("checkout");

function iso(d) {
  return d.toISOString().slice(0, 10);
}
function addDays(date, n) {
  const d = new Date(date);
  d.setDate(d.getDate() + n);
  return d;
}

const today = new Date();
today.setHours(0, 0, 0, 0);
const defIn = addDays(today, 1);
const defOut = addDays(today, 3);

checkin.value = iso(defIn);
checkout.value = iso(defOut);
checkin.min = iso(today);
checkout.min = iso(addDays(today, 1));

// Keep check-out strictly after check-in.
checkin.addEventListener("change", () => {
  const inD = new Date(checkin.value);
  const minOut = iso(addDays(inD, 1));
  checkout.min = minOut;
  if (new Date(checkout.value) <= inD) checkout.value = minOut;
  renderSummary();
});
checkout.addEventListener("change", renderSummary);
document.getElementById("dest").addEventListener("change", renderSummary);

// ── Guests & rooms popover ────────────────────────────────────────────────────
const guests = { adults: 2, children: 0, rooms: 1 };
const trigger = document.getElementById("guestsTrigger");
const pop = document.getElementById("guestsPop");
const guestsLabel = document.getElementById("guestsLabel");

function openPop(open) {
  pop.hidden = !open;
  trigger.setAttribute("aria-expanded", String(open));
}
trigger.addEventListener("click", (e) => {
  e.stopPropagation();
  openPop(pop.hidden);
});
document.getElementById("guestsDone").addEventListener("click", () => openPop(false));
document.addEventListener("click", (e) => {
  if (!pop.hidden && !pop.contains(e.target) && e.target !== trigger) openPop(false);
});

document.querySelectorAll(".stepper").forEach((row) => {
  const key = row.dataset.key;
  const min = Number(row.dataset.min);
  const max = Number(row.dataset.max);
  const valEl = row.querySelector("[data-val]");
  const [minus, plus] = row.querySelectorAll(".step");

  function sync() {
    valEl.textContent = guests[key];
    minus.disabled = guests[key] <= min;
    plus.disabled = guests[key] >= max;
  }
  row.querySelectorAll(".step").forEach((btn) =>
    btn.addEventListener("click", () => {
      const next = guests[key] + Number(btn.dataset.dir);
      if (next < min || next > max) return;
      guests[key] = next;
      sync();
      renderGuestsLabel();
      renderSummary();
    })
  );
  sync();
});

function renderGuestsLabel() {
  const ppl = guests.adults + guests.children;
  const g = `${ppl} ${ppl === 1 ? "guest" : "guests"}`;
  const r = `${guests.rooms} ${guests.rooms === 1 ? "room" : "rooms"}`;
  guestsLabel.textContent = `${g} · ${r}`;
}

// ── Summary line ──────────────────────────────────────────────────────────────
const summary = document.getElementById("summary");

function nights() {
  const ms = new Date(checkout.value) - new Date(checkin.value);
  return Math.round(ms / 86400000);
}
function fmt(isoStr) {
  return new Date(isoStr + "T00:00").toLocaleDateString("en-GB", {
    weekday: "short",
    day: "numeric",
    month: "short",
  });
}

function renderSummary() {
  const n = nights();
  if (!checkin.value || !checkout.value || n <= 0) {
    summary.classList.add("error");
    summary.textContent = "Please choose a check-out date after your check-in date.";
    return;
  }
  summary.classList.remove("error");
  const ppl = guests.adults + guests.children;
  summary.innerHTML =
    `<strong>${n}</strong> ${n === 1 ? "night" : "nights"} · ` +
    `${fmt(checkin.value)} → ${fmt(checkout.value)} · ` +
    `<strong>${ppl}</strong> ${ppl === 1 ? "guest" : "guests"}, ` +
    `<strong>${guests.rooms}</strong> ${guests.rooms === 1 ? "room" : "rooms"}`;
}

// ── Toast + submit ────────────────────────────────────────────────────────────
const toast = document.getElementById("toast");
function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2400);
}

document.getElementById("search").addEventListener("submit", (e) => {
  e.preventDefault();
  if (nights() <= 0) {
    renderSummary();
    return;
  }
  const dest = document.getElementById("dest");
  const city = dest.options[dest.selectedIndex].text;
  showToast(`Searching ${city} · ${nights()} nights · ${guests.rooms} room(s)…`);
});

renderGuestsLabel();
renderSummary();

snippets.css:
:root {
  --bg: #0d0f12;
  --surface: #15181d;
  --surface-2: #1d2127;
  --elevated: #23282f;
  --ink: #f4f6f8;
  --ink-2: #c2c8d0;
  --muted: #8b929c;
  --neon: #c6ff3a;
  --neon-d: #a6e016;
  --neon-50: rgba(198, 255, 58, 0.12);
  --orange: #ff6a2b;
  --orange-soft: rgba(255, 106, 43, 0.14);
  --line: rgba(255, 255, 255, 0.08);
  --line-2: rgba(255, 255, 255, 0.16);
  --ok: #34d399;
  --warn: #fbbf24;
  --danger: #f87171;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 20px;
  --sh-1: 0 1px 2px rgba(0, 0, 0, 0.4);
  --sh-2: 0 8px 24px rgba(0, 0, 0, 0.45);
  --sh-3: 0 18px 48px rgba(0, 0, 0, 0.55);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(1100px 600px at 88% -8%, rgba(198, 255, 58, 0.07), transparent 60%),
    radial-gradient(900px 500px at -5% 6%, rgba(255, 106, 43, 0.07), transparent 55%),
    var(--bg);
  color: var(--ink);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

button {
  font-family: inherit;
  cursor: pointer;
}

:focus-visible {
  outline: 3px solid var(--neon);
  outline-offset: 2px;
  border-radius: var(--r-sm);
}

.app {
  width: min(1080px, 100%);
  margin: 0 auto;
  padding: 28px 22px 56px;
}

/* ---------- Topbar ---------- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 22px;
}

.greet {
  display: flex;
  align-items: center;
  gap: 16px;
  min-width: 0;
}

.avatar {
  flex: none;
  width: 58px;
  height: 58px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-weight: 800;
  font-size: 20px;
  letter-spacing: 0.5px;
  color: #0d0f12;
  background: linear-gradient(140deg, var(--neon), var(--neon-d));
  box-shadow: 0 0 0 3px var(--bg), 0 0 0 5px var(--neon-50);
}

.eyebrow {
  margin: 0;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}

.greet-text h1 {
  margin: 2px 0 1px;
  font-size: clamp(22px, 5vw, 30px);
  font-weight: 900;
  letter-spacing: -0.02em;
}

.greet-text .sub {
  margin: 0;
  font-size: 13px;
  color: var(--ink-2);
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: none;
}

.icon-btn {
  position: relative;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  border: 1px solid var(--line);
  background: var(--surface);
  color: var(--ink-2);
  transition: background 0.18s, color 0.18s, transform 0.1s;
}

.icon-btn:hover {
  background: var(--surface-2);
  color: var(--ink);
}

.icon-btn:active {
  transform: scale(0.94);
}

.icon-btn .dot {
  position: absolute;
  top: 9px;
  right: 10px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--orange);
  box-shadow: 0 0 0 2px var(--surface);
}

.rank {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 14px;
  border-radius: 999px;
  font-weight: 800;
  font-size: 13px;
  letter-spacing: 0.02em;
  color: var(--warn);
  background: rgba(251, 191, 36, 0.12);
  border: 1px solid rgba(251, 191, 36, 0.28);
}

.rank-icon {
  font-size: 14px;
}

/* ---------- Quick action bar ---------- */
.quickbar {
  display: flex;
  gap: 12px;
  margin-bottom: 22px;
  flex-wrap: wrap;
}

.qa {
  flex: 1 1 0;
  min-width: 140px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 15px 18px;
  border-radius: var(--r-md);
  border: 1px solid var(--line);
  background: var(--surface);
  color: var(--ink);
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 0.01em;
  transition: transform 0.12s, background 0.18s, border-color 0.18s, box-shadow 0.18s;
}

.qa:hover {
  background: var(--surface-2);
  border-color: var(--line-2);
}

.qa:active {
  transform: translateY(1px) scale(0.99);
}

.qa-ic {
  font-size: 17px;
  line-height: 1;
}

.qa-primary {
  background: linear-gradient(140deg, var(--neon), var(--neon-d));
  color: #0d0f12;
  border-color: transparent;
  box-shadow: 0 8px 22px rgba(198, 255, 58, 0.22);
}

.qa-primary:hover {
  background: linear-gradient(140deg, #d2ff5e, var(--neon));
}

.qa-orange {
  background: var(--orange-soft);
  border-color: rgba(255, 106, 43, 0.35);
  color: #ffcaaf;
}

.qa-orange:hover {
  background: rgba(255, 106, 43, 0.22);
}

/* ---------- Grid + cards ---------- */
.grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.card {
  background: linear-gradient(180deg, var(--surface), var(--surface-2));
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 20px;
  box-shadow: var(--sh-2);
}

.card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 14px;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--ink-2);
  background: var(--elevated);
  border: 1px solid var(--line);
}

.badge-live {
  color: var(--neon);
  background: var(--neon-50);
  border-color: rgba(198, 255, 58, 0.3);
}

.badge-fire {
  color: #ffcaaf;
  background: var(--orange-soft);
  border-color: rgba(255, 106, 43, 0.32);
}

.link-btn {
  border: 0;
  background: none;
  color: var(--neon);
  font-weight: 700;
  font-size: 13px;
  padding: 2px 2px;
}

.link-btn:hover {
  color: var(--neon-d);
  text-decoration: underline;
}

/* spans */
.next-class { grid-column: span 3; }
.streak { grid-column: span 3; }
.stats { grid-column: span 3; }
.goals { grid-column: span 3; }
.achievements { grid-column: span 3; }
.bookings { grid-column: span 3; }

/* ---------- Next class ---------- */
.next-class {
  position: relative;
  overflow: hidden;
}

.next-class::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(420px 200px at 110% -10%, rgba(198, 255, 58, 0.1), transparent 70%);
  pointer-events: none;
}

.next-class h2 {
  margin: 0 0 4px;
  font-size: 26px;
  font-weight: 900;
  letter-spacing: -0.02em;
}

.nc-meta {
  margin: 0 0 16px;
  color: var(--ink-2);
  font-size: 14px;
}

.nc-meta strong {
  color: var(--ink);
}

.countdown {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  margin-bottom: 18px;
}

.cd-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 10px 14px;
  min-width: 64px;
}

.cd-num {
  font-size: 30px;
  font-weight: 900;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--neon);
}

.cd-lbl {
  margin-top: 5px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

.cd-sep {
  font-size: 26px;
  font-weight: 900;
  color: var(--muted);
  padding-bottom: 18px;
}

.checkin-btn {
  position: relative;
  width: 100%;
  padding: 15px;
  border: 0;
  border-radius: var(--r-md);
  background: linear-gradient(140deg, var(--neon), var(--neon-d));
  color: #0d0f12;
  font-weight: 800;
  font-size: 16px;
  letter-spacing: 0.02em;
  overflow: hidden;
  transition: transform 0.12s, box-shadow 0.2s;
  box-shadow: 0 10px 26px rgba(198, 255, 58, 0.24);
}

.checkin-btn:hover {
  box-shadow: 0 12px 32px rgba(198, 255, 58, 0.34);
}

.checkin-btn:active {
  transform: translateY(1px) scale(0.995);
}

.checkin-btn.checked {
  background: rgba(52, 211, 153, 0.16);
  color: var(--ok);
  box-shadow: none;
  cursor: default;
}

.checkin-btn.pulse::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: rgba(255, 255, 255, 0.55);
  animation: pulse 0.55s ease-out;
}

@keyframes pulse {
  from { transform: scale(0.2); opacity: 0.8; }
  to { transform: scale(1.8); opacity: 0; }
}

/* ---------- Streak ---------- */
.streak-num {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 16px;
}

.streak-num .big {
  font-size: 52px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.03em;
  background: linear-gradient(140deg, var(--orange), #ffb088);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.streak-num .unit {
  font-size: 14px;
  font-weight: 700;
  color: var(--ink-2);
}

.dots {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  list-style: none;
  margin: 0 0 14px;
  padding: 0;
}

.day {
  display: flex;
  flex-direction: column-reverse;
  align-items: center;
  gap: 7px;
  flex: 1;
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
}

.dot-pill {
  width: 100%;
  max-width: 30px;
  height: 30px;
  border-radius: 9px;
  background: var(--elevated);
  border: 1px solid var(--line);
}

.day.done .dot-pill {
  background: linear-gradient(140deg, var(--neon), var(--neon-d));
  border-color: transparent;
  box-shadow: 0 0 14px rgba(198, 255, 58, 0.3);
}

.day.done {
  color: var(--ink);
}

.day.today .dot-pill {
  background: transparent;
  border: 2px dashed var(--orange);
}

.day.today {
  color: var(--orange);
}

.day.rest .dot-pill {
  background: var(--surface-2);
}

.streak-hint {
  margin: 0;
  font-size: 13px;
  color: var(--muted);
}

.streak-hint strong {
  color: var(--ink-2);
}

/* ---------- Stats ---------- */
.stat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 14px;
  border-radius: var(--r-md);
  background: var(--bg);
  border: 1px solid var(--line);
  transition: border-color 0.18s, transform 0.12s;
}

.stat:hover {
  border-color: var(--line-2);
  transform: translateY(-2px);
}

.stat-ic {
  font-size: 18px;
  margin-bottom: 4px;
}

.stat-val {
  font-size: 26px;
  font-weight: 900;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.stat-lbl {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ---------- Goals / ring ---------- */
.goals-body {
  display: flex;
  align-items: center;
  gap: 20px;
}

.ring-wrap {
  position: relative;
  flex: none;
  width: 120px;
  height: 120px;
}

.ring {
  transform: rotate(-90deg);
}

.ring-track {
  fill: none;
  stroke: var(--elevated);
  stroke-width: 12;
}

.ring-fill {
  fill: none;
  stroke: var(--neon);
  stroke-width: 12;
  stroke-linecap: round;
  stroke-dasharray: 326.7;
  stroke-dashoffset: 326.7;
  transition: stroke-dashoffset 0.6s cubic-bezier(0.22, 1, 0.36, 1), stroke 0.4s;
  filter: drop-shadow(0 0 6px rgba(198, 255, 58, 0.4));
}

.ring-fill.complete {
  stroke: var(--ok);
  filter: drop-shadow(0 0 8px rgba(52, 211, 153, 0.45));
}

.ring-center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.ring-num {
  font-size: 34px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.03em;
}

.ring-sub {
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
}

.goal-list {
  flex: 1;
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.goal-toggle {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 9px 11px;
  border-radius: var(--r-sm);
  background: var(--bg);
  border: 1px solid var(--line);
  font-size: 14px;
  font-weight: 600;
  color: var(--ink-2);
  transition: border-color 0.16s, background 0.16s;
}

.goal-toggle:hover {
  border-color: var(--line-2);
}

.goal-toggle input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.check {
  flex: none;
  width: 22px;
  height: 22px;
  border-radius: 7px;
  border: 2px solid var(--line-2);
  display: grid;
  place-items: center;
  transition: background 0.16s, border-color 0.16s;
}

.check::after {
  content: "";
  width: 6px;
  height: 11px;
  border: solid #0d0f12;
  border-width: 0 3px 3px 0;
  transform: rotate(45deg) scale(0);
  margin-top: -2px;
  transition: transform 0.16s;
}

.goal-toggle input:checked ~ .check {
  background: var(--neon);
  border-color: var(--neon);
}

.goal-toggle input:checked ~ .check::after {
  transform: rotate(45deg) scale(1);
}

.goal-toggle input:focus-visible ~ .check {
  outline: 3px solid var(--neon);
  outline-offset: 2px;
}

.goal-toggle input:checked ~ .goal-text {
  color: var(--ink);
}

/* ---------- Achievements ---------- */
.badge-row {
  display: flex;
  gap: 12px;
  list-style: none;
  margin: 0;
  padding: 2px;
  overflow-x: auto;
  scrollbar-width: thin;
}

.ach {
  flex: 1 0 auto;
  min-width: 92px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 16px 12px;
  border-radius: var(--r-md);
  background: var(--bg);
  border: 1px solid var(--line);
  text-align: center;
  transition: transform 0.14s, border-color 0.16s;
}

.ach:hover {
  transform: translateY(-3px);
  border-color: var(--line-2);
}

.ach-ic {
  font-size: 26px;
}

.ach-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--ink-2);
}

.ach.locked {
  opacity: 0.5;
  filter: grayscale(0.4);
}

/* ---------- Bookings ---------- */
.booking-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.booking {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 14px;
  border-radius: var(--r-md);
  background: var(--bg);
  border: 1px solid var(--line);
  transition: border-color 0.16s, opacity 0.3s, transform 0.3s;
}

.booking:hover {
  border-color: var(--line-2);
}

.booking.removing {
  opacity: 0;
  transform: translateX(20px);
}

.bk-when {
  flex: none;
  width: 50px;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 6px 0;
  border-radius: var(--r-sm);
  background: var(--neon-50);
  border: 1px solid rgba(198, 255, 58, 0.22);
}

.bk-day {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: var(--neon);
}

.bk-date {
  font-size: 20px;
  font-weight: 900;
  line-height: 1;
  color: var(--ink);
}

.bk-info {
  flex: 1;
  min-width: 0;
}

.bk-name {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
}

.bk-sub {
  margin: 1px 0 0;
  font-size: 12px;
  color: var(--muted);
}

.bk-cancel {
  flex: none;
  padding: 7px 12px;
  border-radius: var(--r-sm);
  border: 1px solid var(--line-2);
  background: transparent;
  color: var(--ink-2);
  font-size: 12px;
  font-weight: 700;
  transition: color 0.16s, border-color 0.16s, background 0.16s;
}

.bk-cancel:hover {
  color: var(--danger);
  border-color: var(--danger);
  background: rgba(248, 113, 113, 0.1);
}

/* ---------- Toast ---------- */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 24px);
  background: var(--elevated);
  color: var(--ink);
  border: 1px solid var(--line-2);
  border-left: 3px solid var(--neon);
  padding: 13px 18px;
  border-radius: var(--r-md);
  font-weight: 600;
  font-size: 14px;
  box-shadow: var(--sh-3);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s, transform 0.25s;
  z-index: 50;
  max-width: calc(100vw - 32px);
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Responsive ---------- */
@media (max-width: 860px) {
  .grid {
    grid-template-columns: 1fr 1fr;
  }
  .next-class,
  .streak,
  .stats,
  .goals,
  .achievements,
  .bookings {
    grid-column: span 2;
  }
}

@media (max-width: 520px) {
  .app {
    padding: 20px 14px 48px;
  }
  .grid {
    grid-template-columns: 1fr;
  }
  .next-class,
  .streak,
  .stats,
  .goals,
  .achievements,
  .bookings {
    grid-column: span 1;
  }
  .avatar {
    width: 50px;
    height: 50px;
    font-size: 17px;
  }
  .rank {
    display: none;
  }
  .quickbar {
    gap: 8px;
  }
  .qa {
    min-width: 0;
    padding: 13px 10px;
    font-size: 13px;
  }
  .cd-unit {
    min-width: 0;
    flex: 1;
    padding: 9px 6px;
  }
  .cd-num {
    font-size: 24px;
  }
  .goals-body {
    flex-direction: column;
    align-items: stretch;
  }
  .ring-wrap {
    align-self: center;
  }
  .stat-val {
    font-size: 22px;
  }
}

