(function () {
  "use strict";

  /* ---------- Toast helper ---------- */
  var toastEl = document.getElementById("toast");
  var toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2400);
  }

  /* ---------- Time-aware greeting ---------- */
  (function () {
    var el = document.getElementById("time-greeting");
    if (!el) return;
    var h = new Date().getHours();
    var g = h < 12 ? "Good morning" : h < 18 ? "Good afternoon" : "Good evening";
    el.textContent = g;
  })();

  /* ---------- Next-class countdown ---------- */
  (function () {
    var cd = document.getElementById("countdown");
    if (!cd) return;
    var hEl = cd.querySelector('[data-cd="h"]');
    var mEl = cd.querySelector('[data-cd="m"]');
    var sEl = cd.querySelector('[data-cd="s"]');

    // Target: ~1h 47m 30s from load (deterministic feel, still ticks).
    var target = Date.now() + (1 * 3600 + 47 * 60 + 30) * 1000;

    function pad(n) {
      return String(n).padStart(2, "0");
    }

    function tick() {
      var diff = Math.max(0, target - Date.now());
      var total = Math.floor(diff / 1000);
      var h = Math.floor(total / 3600);
      var m = Math.floor((total % 3600) / 60);
      var s = total % 60;
      hEl.textContent = pad(h);
      mEl.textContent = pad(m);
      sEl.textContent = pad(s);
      if (diff <= 0) {
        clearInterval(timer);
        var badge = document.querySelector(".badge-live");
        if (badge) badge.textContent = "Class started";
      }
    }
    tick();
    var timer = setInterval(tick, 1000);
  })();

  /* ---------- Check-in button ---------- */
  (function () {
    var btn = document.getElementById("checkin-btn");
    if (!btn) return;
    var label = btn.querySelector(".ci-label");
    btn.addEventListener("click", function () {
      if (btn.classList.contains("checked")) return;
      btn.classList.add("pulse");
      setTimeout(function () {
        btn.classList.remove("pulse");
      }, 600);
      btn.classList.add("checked");
      label.textContent = "✓ Checked in — see you in Studio 2";
      var streak = document.getElementById("streak-count");
      if (streak) {
        streak.textContent = String((parseInt(streak.textContent, 10) || 0) + 1);
      }
      var today = document.querySelector(".day.today");
      if (today) {
        today.classList.remove("today");
        today.classList.add("done");
      }
      toast("Checked in to HIIT Inferno 🔥");
    });
  })();

  /* ---------- Goals ring ---------- */
  (function () {
    var list = document.getElementById("goal-list");
    var ring = document.getElementById("ring-fill");
    var ringNum = document.getElementById("ring-num");
    var totalEl = document.getElementById("goal-total");
    var pctBadge = document.getElementById("goal-pct-badge");
    if (!list || !ring) return;

    var boxes = Array.prototype.slice.call(list.querySelectorAll("[data-goal]"));
    var total = boxes.length;
    var CIRC = 2 * Math.PI * 52; // r = 52
    ring.style.strokeDasharray = CIRC.toFixed(1);
    if (totalEl) totalEl.textContent = String(total);

    function update(announce) {
      var done = boxes.filter(function (b) {
        return b.checked;
      }).length;
      var frac = total ? done / total : 0;
      ring.style.strokeDashoffset = (CIRC * (1 - frac)).toFixed(1);
      ring.classList.toggle("complete", done === total && total > 0);
      if (ringNum) ringNum.textContent = String(done);
      var pct = Math.round(frac * 100);
      if (pctBadge) pctBadge.textContent = pct + "%";
      if (announce) {
        if (done === total) {
          toast("All weekly goals complete! 💪");
        } else {
          toast(done + " of " + total + " goals done");
        }
      }
    }

    boxes.forEach(function (b) {
      b.addEventListener("change", function () {
        update(true);
      });
    });

    update(false);
  })();

  /* ---------- Quick actions ---------- */
  (function () {
    var labels = {
      book: "Opening class schedule…",
      log: "Log a workout — pick a routine",
      scan: "Hold your QR to the reader to scan in",
      badges: "Showing all 18 achievements"
    };
    document.querySelectorAll("[data-action]").forEach(function (el) {
      el.addEventListener("click", function () {
        var a = el.getAttribute("data-action");
        toast(labels[a] || "Done");
      });
    });
  })();

  /* ---------- Cancel bookings ---------- */
  (function () {
    document.querySelectorAll(".bk-cancel").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var row = btn.closest(".booking");
        if (!row) return;
        var name = row.querySelector(".bk-name");
        var nm = name ? name.textContent : "Booking";
        row.classList.add("removing");
        setTimeout(function () {
          row.remove();
          toast("Cancelled: " + nm);
        }, 300);
      });
    });
  })();

  /* ---------- Bell ---------- */
  (function () {
    var bell = document.getElementById("bell-btn");
    if (!bell) return;
    bell.addEventListener("click", function () {
      var dot = bell.querySelector(".dot");
      if (dot) dot.style.display = "none";
      toast("2 new: class reminder · new PR logged");
    });
  })();
})();

snippets.css:
:root {
  --ivory: #f7f4ec;
  --paper: #fffdf8;
  --white: #ffffff;
  --green: #1f3d34;
  --green-d: #16302a;
  --green-700: #26493e;
  --green-50: #e8efea;
  --brass: #b08d57;
  --brass-d: #94733f;
  --brass-50: #f3ead9;
  --ink: #1c2a25;
  --ink-2: #33433d;
  --muted: #6b7a72;
  --line: rgba(31, 61, 52, 0.12);
  --line-2: rgba(31, 61, 52, 0.22);
  --ok: #2f9e6f;
  --warn: #c98a2b;
  --danger: #c4503e;
  --r-sm: 8px;
  --r-md: 14px;
  --r-lg: 22px;
  --shadow-sm: 0 1px 2px rgba(22, 48, 42, 0.06), 0 2px 8px rgba(22, 48, 42, 0.05);
  --shadow-md: 0 4px 14px rgba(22, 48, 42, 0.08), 0 18px 40px rgba(22, 48, 42, 0.08);
  --shadow-lg: 0 10px 30px rgba(22, 48, 42, 0.10), 0 30px 70px rgba(22, 48, 42, 0.12);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: "Inter", system-ui, sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: var(--ink);
  background:
    radial-gradient(1200px 600px at 85% -10%, rgba(176, 141, 87, 0.10), transparent 60%),
    radial-gradient(900px 500px at -10% 110%, rgba(31, 61, 52, 0.08), transparent 60%),
    var(--ivory);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  padding: clamp(16px, 4vw, 48px);
}

h1, h2, h3 {
  font-family: "Cormorant Garamond", Georgia, serif;
  font-weight: 600;
  letter-spacing: 0.2px;
  margin: 0;
  color: var(--green-d);
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0);
  white-space: nowrap; border: 0;
}

/* ===== Sheet ===== */
.sheet {
  max-width: 980px;
  margin: 0 auto;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-lg);
  padding: clamp(22px, 4.5vw, 54px);
  position: relative;
  overflow: hidden;
}
.sheet::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 5px;
  background: linear-gradient(90deg, var(--green), var(--brass) 55%, var(--brass-d));
}

/* ===== Masthead ===== */
.masthead {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  flex-wrap: wrap;
}
.brand { display: flex; align-items: center; gap: 14px; }
.brand-mark {
  width: 46px; height: 46px;
  border-radius: 12px;
  background: linear-gradient(150deg, var(--green-700), var(--green-d));
  color: var(--brass-50);
  display: grid; place-items: center;
  font-family: "Cormorant Garamond", serif;
  font-weight: 700;
  font-size: 20px;
  letter-spacing: 1px;
  box-shadow: inset 0 0 0 1px rgba(176, 141, 87, 0.4), var(--shadow-sm);
}
.brand-name {
  margin: 0;
  font-family: "Cormorant Garamond", serif;
  font-size: 22px;
  font-weight: 700;
  color: var(--green-d);
  line-height: 1.1;
}
.brand-sub {
  margin: 2px 0 0;
  font-size: 11.5px;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: var(--muted);
}
.masthead-meta { text-align: right; display: flex; flex-direction: column; gap: 4px; }
.doc-kind {
  font-size: 11px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--brass-d);
  font-weight: 600;
}
.doc-ref { font-size: 12.5px; color: var(--muted); font-variant-numeric: tabular-nums; }

.rule-brass {
  height: 1px;
  margin: 20px 0 26px;
  background: linear-gradient(90deg, transparent, var(--brass) 8%, var(--brass) 92%, transparent);
  opacity: 0.6;
}

/* ===== Subject ===== */
.subject {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 28px;
  align-items: stretch;
}
.subject-photo {
  position: relative;
  border-radius: var(--r-md);
  min-height: 230px;
  overflow: hidden;
  box-shadow: var(--shadow-md), inset 0 0 0 1px rgba(255, 255, 255, 0.25);
  background:
    linear-gradient(180deg, rgba(28, 42, 37, 0) 40%, rgba(22, 48, 42, 0.55) 100%),
    radial-gradient(120% 80% at 75% 18%, rgba(255, 226, 170, 0.55), transparent 55%),
    linear-gradient(115deg, #c98a4e 0%, #a86a3c 30%, #5d4a3a 60%, #2c3a33 100%);
}
.subject-photo::after {
  content: "";
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: 46%;
  background:
    linear-gradient(0deg, rgba(20, 30, 26, 0.7), transparent),
    repeating-linear-gradient(90deg, rgba(0,0,0,0.18) 0 2px, transparent 2px 22px);
  -webkit-mask: linear-gradient(180deg, transparent, #000 60%);
          mask: linear-gradient(180deg, transparent, #000 60%);
  opacity: 0.5;
}
.photo-tag {
  position: absolute;
  top: 12px; left: 12px;
  background: rgba(22, 48, 42, 0.82);
  color: var(--brass-50);
  font-size: 10.5px;
  letter-spacing: 1.6px;
  text-transform: uppercase;
  font-weight: 600;
  padding: 5px 11px;
  border-radius: 999px;
  backdrop-filter: blur(2px);
  z-index: 2;
}
.photo-credit {
  position: absolute;
  bottom: 10px; left: 14px;
  color: rgba(255, 253, 248, 0.82);
  font-size: 11px;
  letter-spacing: 0.4px;
  z-index: 2;
}

.eyebrow {
  margin: 0 0 4px;
  font-size: 11px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--brass-d);
  font-weight: 600;
}
.subject-address {
  font-size: clamp(30px, 5vw, 42px);
  line-height: 1.02;
  font-weight: 700;
}
.subject-loc { margin: 6px 0 0; color: var(--muted); font-size: 14px; }

.spec-row {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  margin: 20px 0 0;
  padding: 14px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.spec-row li {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 0 22px;
  border-right: 1px solid var(--line);
}
.spec-row li:first-child { padding-left: 0; }
.spec-row li:last-child { border-right: 0; }
.spec-n {
  font-family: "Cormorant Garamond", serif;
  font-size: 24px;
  font-weight: 700;
  color: var(--green-d);
  line-height: 1;
}
.spec-l {
  font-size: 10.5px;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: var(--muted);
  margin-top: 4px;
}

.subject-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-top: 18px;
  flex-wrap: wrap;
}
.agent-chip { display: flex; align-items: center; gap: 11px; }
.agent-avatar {
  width: 40px; height: 40px;
  border-radius: 50%;
  background: linear-gradient(150deg, var(--brass), var(--brass-d));
  color: var(--white);
  display: grid; place-items: center;
  font-weight: 600;
  font-size: 13px;
  letter-spacing: 0.5px;
  box-shadow: var(--shadow-sm);
}
.agent-name { margin: 0; font-weight: 600; font-size: 14px; color: var(--ink); }
.agent-role { margin: 1px 0 0; font-size: 12px; color: var(--muted); }
.prep-date { margin: 0; font-size: 12.5px; color: var(--muted); font-variant-numeric: tabular-nums; }

/* ===== Section shared ===== */
.section-title { font-size: clamp(22px, 3.4vw, 28px); }
.section-note { margin: 4px 0 0; font-size: 13px; color: var(--muted); max-width: 60ch; }
.summary, .comps, .dist { margin-top: 34px; }
.summary-head, .comps-head { margin-bottom: 16px; }

/* ===== Suggested range ===== */
.range-card {
  background: linear-gradient(160deg, var(--white), var(--green-50));
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: clamp(18px, 3vw, 28px);
  box-shadow: var(--shadow-md);
  position: relative;
}
.range-numbers {
  display: grid;
  grid-template-columns: 1fr 1.3fr 1fr;
  gap: 12px;
  align-items: end;
}
.range-cell { display: flex; flex-direction: column; gap: 4px; }
.range-cell--mid {
  align-items: center;
  text-align: center;
  padding: 0 16px;
  border-left: 1px solid var(--line);
  border-right: 1px solid var(--line);
}
.range-cell--end { align-items: flex-end; text-align: right; }
.range-label {
  font-size: 10.5px;
  letter-spacing: 1.6px;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 600;
}
.range-value {
  font-family: "Cormorant Garamond", serif;
  font-size: clamp(26px, 4.2vw, 36px);
  font-weight: 700;
  color: var(--green-d);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.range-value--mid {
  font-size: clamp(34px, 6vw, 52px);
  color: var(--brass-d);
}
.range-ppsf { font-size: 12px; color: var(--muted); margin-top: 2px; }

.range-bar { margin-top: 24px; }
.range-bar-track {
  position: relative;
  height: 14px;
  border-radius: 999px;
  background: var(--green-50);
  box-shadow: inset 0 0 0 1px var(--line);
}
.range-bar-fill {
  position: absolute;
  top: 0; bottom: 0;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--green-700), var(--brass));
  box-shadow: 0 1px 4px rgba(148, 115, 63, 0.4);
  transition: left 0.5s cubic-bezier(.22,.61,.36,1), width 0.5s cubic-bezier(.22,.61,.36,1);
}
.range-bar-marker {
  position: absolute;
  top: 50%;
  width: 2px;
  height: 26px;
  background: var(--green-d);
  transform: translate(-50%, -50%);
  transition: left 0.5s cubic-bezier(.22,.61,.36,1);
}
.range-bar-marker span {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%);
  font-size: 10px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--green-d);
  font-weight: 600;
  white-space: nowrap;
}
.range-bar-scale {
  display: flex;
  justify-content: space-between;
  margin-top: 8px;
  font-size: 11.5px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

/* ===== Comps table ===== */
.comps-table-wrap {
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: auto;
  box-shadow: var(--shadow-sm);
  background: var(--white);
}
.comps-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13.5px;
  min-width: 720px;
}
.comps-table thead th {
  text-align: left;
  font-size: 10.5px;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--green-d);
  background: var(--brass-50);
  padding: 12px 14px;
  border-bottom: 1px solid var(--line-2);
  white-space: nowrap;
}
.comps-table th.num, .comps-table td.num { text-align: right; font-variant-numeric: tabular-nums; }
.comps-table tbody td {
  padding: 13px 14px;
  border-bottom: 1px solid var(--line);
  vertical-align: middle;
}
.comps-table tbody tr { transition: background 0.18s ease; }
.comps-table tbody tr:hover { background: var(--green-50); }
.comps-table tbody tr.is-excluded {
  color: var(--muted);
  background: repeating-linear-gradient(135deg, rgba(31,61,52,0.025) 0 8px, transparent 8px 16px);
}
.comps-table tbody tr.is-excluded .comp-addr,
.comps-table tbody tr.is-excluded .num { opacity: 0.55; text-decoration: line-through; text-decoration-color: var(--line-2); }

.col-toggle { width: 44px; }
.col-addr { min-width: 190px; }
.comp-addr { font-weight: 600; color: var(--ink); }
.comp-area { display: block; font-size: 11.5px; color: var(--muted); font-weight: 400; margin-top: 1px; }

.cb {
  appearance: none;
  -webkit-appearance: none;
  width: 20px; height: 20px;
  border: 1.5px solid var(--line-2);
  border-radius: 6px;
  background: var(--white);
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background 0.15s ease, border-color 0.15s ease;
}
.cb:hover { border-color: var(--brass); }
.cb:checked {
  background: var(--green-700);
  border-color: var(--green-700);
}
.cb:checked::after {
  content: "";
  width: 5px; height: 9px;
  border: solid var(--brass-50);
  border-width: 0 2px 2px 0;
  transform: rotate(40deg) translateY(-1px);
}
.cb:focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }

.adj-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.adj-pill--up { background: rgba(47,158,111,0.12); color: var(--ok); }
.adj-pill--down { background: rgba(196,80,62,0.12); color: var(--danger); }
.adj-pill--zero { background: var(--green-50); color: var(--muted); }

.comps-foot td {
  padding: 13px 14px;
  border-top: 2px solid var(--line-2);
  font-weight: 700;
  color: var(--green-d);
  background: var(--brass-50);
}
.comps-foot .col-addr {
  font-family: "Cormorant Garamond", serif;
  font-size: 16px;
}
.foot-count { font-family: "Inter", sans-serif; font-size: 11px; color: var(--muted); font-weight: 500; }

.adj-legend {
  margin: 12px 2px 0;
  font-size: 11.5px;
  color: var(--muted);
  display: flex;
  flex-wrap: wrap;
  gap: 6px 18px;
  align-items: center;
}
.legend-dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }
.legend-dot--up { background: var(--ok); }
.legend-dot--down { background: var(--danger); }

/* ===== Distribution chart ===== */
.chart {
  position: relative;
  display: flex;
  align-items: flex-end;
  gap: clamp(8px, 2vw, 20px);
  height: 240px;
  padding: 16px 6px 0;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background:
    linear-gradient(0deg, var(--white), var(--white)),
    var(--paper);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}
.chart-band {
  position: absolute;
  top: 0; bottom: 0;
  background: linear-gradient(180deg, rgba(176,141,87,0.14), rgba(176,141,87,0.05));
  border-left: 1px dashed var(--brass);
  border-right: 1px dashed var(--brass);
  z-index: 0;
  pointer-events: none;
}
.chart-band-label {
  position: absolute;
  top: 8px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 9.5px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--brass-d);
  font-weight: 600;
  white-space: nowrap;
}
.bar {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  height: 100%;
  z-index: 1;
}
.bar-col {
  width: 100%;
  max-width: 56px;
  border-radius: 8px 8px 3px 3px;
  background: linear-gradient(180deg, var(--green-700), var(--green-d));
  box-shadow: inset 0 0 0 1px rgba(176,141,87,0.3);
  transition: height 0.55s cubic-bezier(.22,.61,.36,1), opacity 0.3s ease, background 0.3s ease;
  position: relative;
}
.bar.is-subject .bar-col {
  background: linear-gradient(180deg, var(--brass), var(--brass-d));
}
.bar.is-excluded .bar-col {
  background: var(--line-2);
  opacity: 0.5;
}
.bar-value {
  font-size: 11px;
  font-weight: 600;
  color: var(--green-d);
  margin-bottom: 6px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.bar.is-subject .bar-value { color: var(--brass-d); }
.bar.is-excluded .bar-value { color: var(--muted); }
.bar-label {
  font-size: 10px;
  color: var(--muted);
  margin-top: 8px;
  text-align: center;
  line-height: 1.25;
  max-width: 100%;
}
.bar.is-subject .bar-label { color: var(--brass-d); font-weight: 600; }

/* ===== Footer ===== */
.report-foot {
  margin-top: 38px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  flex-wrap: wrap;
}
.report-foot p { margin: 0; font-size: 11.5px; color: var(--muted); max-width: 62ch; }
.btn-print {
  font-family: inherit;
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.3px;
  color: var(--green-d);
  background: var(--white);
  border: 1px solid var(--line-2);
  border-radius: 999px;
  padding: 9px 20px;
  cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease, border-color 0.18s ease, transform 0.1s ease;
  white-space: nowrap;
}
.btn-print:hover { background: var(--green-700); color: var(--brass-50); border-color: var(--green-700); }
.btn-print:active { transform: translateY(1px); }
.btn-print:focus-visible { outline: 2px solid var(--brass); outline-offset: 2px; }

/* ===== Toast ===== */
.toast {
  position: fixed;
  left: 50%;
  bottom: 26px;
  transform: translate(-50%, 18px);
  background: var(--green-d);
  color: var(--brass-50);
  font-size: 13px;
  font-weight: 500;
  padding: 11px 20px;
  border-radius: 999px;
  box-shadow: var(--shadow-md);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
  z-index: 50;
  max-width: calc(100vw - 40px);
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* ===== Responsive ===== */
@media (max-width: 760px) {
  .subject { grid-template-columns: 1fr; gap: 18px; }
  .subject-photo { min-height: 190px; }
}

@media (max-width: 520px) {
  body { padding: 12px; }
  .sheet { padding: 20px 16px; border-radius: var(--r-md); }
  .masthead-meta { text-align: left; align-items: flex-start; }
  .spec-row { gap: 10px 0; }
  .spec-row li { padding: 0 14px; }
  .range-numbers { grid-template-columns: 1fr; gap: 14px; }
  .range-cell, .range-cell--mid, .range-cell--end { align-items: flex-start; text-align: left; }
  .range-cell--mid { border: 0; padding: 14px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
  .chart { height: 200px; gap: 5px; }
  .bar-value { font-size: 9.5px; }
  .bar-label { font-size: 9px; }
  .report-foot { flex-direction: column; align-items: flex-start; }
}

@media print {
  body { background: #fff; padding: 0; }
  .sheet { box-shadow: none; border: 0; max-width: none; }
  .btn-print { display: none; }
  .toast { display: none; }
  .comps-table-wrap { overflow: visible; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}

