:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.2);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
}
body {
  font-family: var(--font-body);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  background: radial-gradient(circle at 18% 14%, rgba(201, 166, 73, 0.18), transparent 55%),
    radial-gradient(circle at 84% 78%, rgba(74, 109, 160, 0.16), transparent 60%),
    linear-gradient(180deg, #14213b 0%, #0f1d36 100%);
}

.bg {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 28px;
}

/* ── Dialog ── */
.dialog {
  width: min(960px, 100%);
  background: var(--bone);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 40px 100px rgba(15, 29, 54, 0.55);
  display: flex;
  flex-direction: column;
  max-height: 92vh;
}
.d-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding: 22px 28px 18px;
  border-bottom: 1px solid var(--line);
}
.kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold-d);
  font-weight: 700;
  font-family: var(--font-mono);
}
.d-head h2 {
  font-family: var(--font-display);
  font-size: 1.65rem;
  font-weight: 700;
  letter-spacing: -0.005em;
  margin-top: 2px;
  color: var(--navy-d);
}
.d-head h2 span {
  color: var(--gold-d);
}
.d-close {
  background: transparent;
  border: 1px solid var(--line-strong);
  width: 36px;
  height: 36px;
  border-radius: 999px;
  font-size: 1.4rem;
  cursor: pointer;
  color: var(--ink-2);
  line-height: 1;
}
.d-close:hover {
  border-color: var(--danger);
  color: var(--danger);
}

.d-body {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 24px;
  padding: 24px 28px;
  overflow-y: auto;
}

/* ── Form ── */
.form fieldset {
  border: none;
  margin-bottom: 18px;
  padding: 14px 16px;
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
}
.form legend {
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--gold-d);
  font-weight: 700;
  padding: 0 6px;
  background: var(--cream);
}
.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.field {
