}
.field input:focus,
.field select:focus,
.form textarea:focus {
  border-color: var(--gold);
}

.nights {
  margin-top: 10px;
  font-size: 0.86rem;
  color: var(--ink-2);
}
.nights strong {
  font-family: var(--font-display);
  font-size: 1.4rem;
