  resize: vertical;
  font-family: inherit;
  margin-top: 10px;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.chip {
  background: var(--bone);
  border: 1px solid var(--line-strong);
  font-family: inherit;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--ink-2);
  padding: 7px 12px;
