.chip:hover {
  border-color: var(--gold);
  color: var(--gold-d);
}
.chip.is-on {
  background: var(--gold);
  color: var(--navy-d);
  border-color: var(--gold);
}

/* ── Summary ── */
.summary {
  background: var(--navy);
  color: var(--bone);
  border-radius: var(--r-md);
  padding: 22px;
