  margin-bottom: 14px;
  color: var(--gold-light);
}
.lines {
  list-style: none;
}
.lines li {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 7px 0;
  font-size: 0.82rem;
  color: rgba(251, 248, 242, 0.78);
  border-bottom: 1px dashed rgba(255, 255, 255, 0.1);
