/* ── Footer ── */
.d-foot {
  border-top: 1px solid var(--line);
  background: var(--cream);
  padding: 14px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}
.d-foot-right {
  display: flex;
  gap: 8px;
}
.ghost,
.primary {
  font-family: inherit;
  font-weight: 600;
  font-size: 0.86rem;
  padding: 10px 18px;
  border-radius: 999px;
