}
.ghost {
  background: transparent;
  border: 1px solid var(--line-strong);
  color: var(--ink-2);
}
.ghost:hover {
  border-color: var(--navy-2);
  color: var(--navy-d);
}
.primary {
  background: var(--navy);
  color: var(--bone);
