:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 10px 30px rgba(22, 30, 44, 0.14);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
  overflow: hidden;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

.pms {
  height: 100vh;
  display: grid;
  grid-template-columns: 230px 1fr 320px;
}

/* ── Rail ── */
.rail {
  background: var(--navy);
  color: var(--bone);
  display: flex;
  flex-direction: column;
  padding: 22px 16px 14px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 4px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.brand-mark {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  background: var(--gold);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.35rem;
}
.brand-name {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.01em;
}
.brand-prop {
  font-size: 0.7rem;
  color: var(--gold-light);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-top: 2px;
}

.nav {
  margin-top: 18px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}
.nav-item {
  font-size: 0.86rem;
  font-weight: 500;
  color: rgba(251, 248, 242, 0.78);
  text-decoration: none;
  padding: 10px 12px;
  border-radius: var(--r-md);
  display: flex;
  align-items: center;
  gap: 10px;
}
.nav-item:hover {
  background: rgba(255, 255, 255, 0.06);
  color: var(--bone);
}
.nav-item.is-active {
  background: rgba(201, 166, 73, 0.16);
  color: var(--gold-light);
  font-weight: 600;
}
.nav-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: var(--gold);
}
.nav-item:not(.is-active) .nav-dot {
  display: none;
}

.rail-actions {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}
.quick-btn {
  background: var(--gold);
  color: var(--navy-d);
  border: none;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.84rem;
  padding: 10px 12px;
  border-radius: var(--r-md);
  cursor: pointer;
  text-align: left;
}
.quick-btn:hover {
  background: var(--gold-light);
}
.quick-btn.ghost {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.18);
  color: var(--bone);
}
.quick-btn.ghost:hover {
  background: rgba(255, 255, 255, 0.06);
}

.rail-foot {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.clock {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 0.88rem;
  color: var(--gold-light);
}
.agent {
  font-size: 0.72rem;
  color: rgba(251, 248, 242, 0.6);
  letter-spacing: 0.04em;
}

/* ── Main ── */
.main {
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  padding: 22px 28px 28px;
  background: var(--cream);
}
.topbar {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  margin-bottom: 18px;
}
.kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold-d);
  font-weight: 600;
}
.topbar h1 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.95rem;
  letter-spacing: -0.005em;
  margin-top: 2px;
}
.topbar h1 span {
  color: var(--navy-2);
  font-weight: 500;
}
.topbar-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bone);
  border: 1px solid var(--line);
  padding: 9px 14px;
  border-radius: 999px;
  color: var(--warm-gray);
  width: 320px;
}
.search input {
  background: transparent;
  border: none;
  outline: none;
  font-family: inherit;
  font-size: 0.86rem;
  color: var(--ink);
  width: 100%;
}
.icon-btn {
  position: relative;
  background: var(--bone);
  border: 1px solid var(--line);
  width: 38px;
  height: 38px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  cursor: pointer;
  color: var(--ink-2);
}
.icon-btn:hover {
  background: var(--cream-2);
}
.badge-num {
  position: absolute;
  top: -3px;
  right: -3px;
  background: var(--danger);
  color: white;
  font-size: 0.6rem;
  font-weight: 700;
  border-radius: 999px;
  min-width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
  padding: 0 4px;
}

/* ── KPI band ── */
.kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 20px;
}
.kpi {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 16px;
  position: relative;
  overflow: hidden;
}
.kpi::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: var(--gold);
}
.kpi-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  font-weight: 600;
}
.kpi-value {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.95rem;
  color: var(--navy-d);
  margin-top: 4px;
  letter-spacing: -0.01em;
  font-variant-numeric: tabular-nums;
}
.kpi-value small {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--warm-gray);
  margin-left: 1px;
}
.kpi-trend {
  font-size: 0.74rem;
  font-weight: 600;
  margin-top: 2px;
  letter-spacing: 0.02em;
}
.kpi-trend.up {
  color: var(--success);
}
.kpi-trend.down {
  color: var(--danger);
}

/* ── Panel ── */
.panel {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.panel-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
  gap: 14px;
}
.tabs {
  display: flex;
  gap: 4px;
}
.tab {
  background: transparent;
  border: none;
  font-family: inherit;
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--warm-gray);
  padding: 9px 14px;
  border-radius: 999px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.tab:hover {
  color: var(--ink);
}
.tab.is-active {
  background: var(--navy);
  color: var(--bone);
}
.tab-count {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  background: rgba(22, 30, 44, 0.08);
  color: inherit;
  padding: 2px 8px;
  border-radius: 999px;
  font-weight: 700;
}
.tab.is-active .tab-count {
  background: rgba(251, 248, 242, 0.2);
  color: var(--bone);
}
.filter {
  display: flex;
  gap: 4px;
}
.chip {
  background: transparent;
  border: 1px solid var(--line-strong);
  font-family: inherit;
  font-size: 0.76rem;
  font-weight: 600;
  color: var(--ink-2);
  padding: 6px 11px;
  border-radius: 999px;
  cursor: pointer;
}
.chip:hover {
  background: var(--cream-2);
}
.chip.is-active {
  background: var(--gold);
  color: var(--navy-d);
  border-color: var(--gold);
}

.rows {
  flex: 1;
  overflow-y: auto;
  padding: 4px 0 8px;
}
.row {
  display: grid;
  grid-template-columns: 80px 1fr 120px 100px 110px auto;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
  transition: background 0.12s;
}
.row:hover {
  background: var(--cream);
}
.row:last-child {
  border-bottom: none;
}
.row.is-vip .guest-name::after {
  content: "VIP";
  background: var(--gold);
  color: var(--navy-d);
  font-size: 0.6rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 999px;
  letter-spacing: 0.08em;
  margin-left: 8px;
  vertical-align: middle;
}
.room {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.94rem;
  color: var(--navy-d);
}
.guest {
  min-width: 0;
}
.guest-name {
  font-weight: 600;
  font-size: 0.94rem;
  color: var(--ink);
  letter-spacing: -0.005em;
}
.guest-meta {
  font-size: 0.74rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.dates {
  font-size: 0.78rem;
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
}
.dates strong {
  display: block;
  font-weight: 600;
  color: var(--navy-d);
}
.amount {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--ink);
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.status {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
  display: inline-block;
}
.status.expected {
  background: rgba(74, 109, 160, 0.14);
  color: var(--info);
}
.status.checked-in {
  background: rgba(74, 119, 82, 0.14);
  color: var(--success);
}
.status.due-out {
  background: rgba(217, 144, 32, 0.16);
  color: var(--warning);
}
.status.late {
  background: rgba(179, 66, 50, 0.14);
  color: var(--danger);
}
.row-actions {
  display: flex;
  gap: 6px;
  justify-content: flex-end;
}
.action {
  background: var(--cream);
  border: 1px solid var(--line);
  font-family: inherit;
  font-size: 0.76rem;
  font-weight: 600;
  color: var(--ink-2);
  padding: 7px 11px;
  border-radius: var(--r-sm);
  cursor: pointer;
  white-space: nowrap;
}
.action:hover {
  border-color: var(--navy-2);
  color: var(--navy-d);
}
.action.primary {
  background: var(--navy);
  color: var(--bone);
  border-color: var(--navy);
}
.action.primary:hover {
  background: var(--navy-d);
  color: var(--bone);
}

.empty {
  padding: 60px 24px;
  text-align: center;
  color: var(--warm-gray);
  font-style: italic;
  font-size: 0.9rem;
}

/* ── Activity rail ── */
.activity {
  background: var(--bone);
  border-left: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.act-head {
  padding: 22px 20px 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--line);
}
.act-head h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.2rem;
  letter-spacing: -0.005em;
}
.link-btn {
  background: transparent;
  border: none;
  font-family: inherit;
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--navy-2);
  cursor: pointer;
  letter-spacing: 0.04em;
}
.link-btn:hover {
  color: var(--gold-d);
}
.act-list {
  list-style: none;
  flex: 1;
  overflow-y: auto;
  padding: 8px 16px;
}
.act {
  display: grid;
  grid-template-columns: 32px 1fr auto;
  gap: 10px;
  padding: 12px 4px;
  border-bottom: 1px dashed var(--line);
}
.act:last-child {
  border-bottom: none;
}
.act-icon {
  width: 32px;
  height: 32px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-size: 0.9rem;
  font-weight: 700;
  background: var(--cream);
  color: var(--navy-d);
}
.act.checkin .act-icon {
  background: rgba(74, 119, 82, 0.16);
  color: var(--success);
}
.act.payment .act-icon {
  background: rgba(201, 166, 73, 0.2);
  color: var(--gold-d);
}
.act.housekeeping .act-icon {
  background: rgba(74, 109, 160, 0.16);
  color: var(--info);
}
.act.alert .act-icon {
  background: rgba(179, 66, 50, 0.16);
  color: var(--danger);
}
.act-body p {
  font-size: 0.84rem;
  color: var(--ink);
  line-height: 1.4;
}
.act-body small {
  font-size: 0.72rem;
  color: var(--warm-gray);
}
.act-time {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--warm-gray);
  white-space: nowrap;
}

.act-foot {
  border-top: 1px solid var(--line);
  padding: 16px 20px 22px;
  background: var(--cream);
}
.act-label {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gold-d);
  margin-bottom: 8px;
}
.ghost-btn {
  width: 100%;
  background: transparent;
  border: 1px solid var(--line-strong);
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ink-2);
  padding: 9px 12px;
  border-radius: var(--r-sm);
  cursor: pointer;
  text-align: left;
  margin-bottom: 6px;
}
.ghost-btn:hover {
  border-color: var(--navy-2);
  color: var(--navy-d);
  background: var(--bone);
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 20px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
}

/* ── Responsive ── */
@media (max-width: 1300px) {
  .pms {
    grid-template-columns: 200px 1fr 280px;
  }
  .search {
    width: 220px;
  }
  .row {
    grid-template-columns: 70px 1fr 110px 90px 100px auto;
  }
}
@media (max-width: 1024px) {
  .pms {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
    height: auto;
  }
  html,
  body {
    overflow: auto;
  }
  .activity {
    border-left: none;
    border-top: 1px solid var(--line);
  }
  .kpis {
    grid-template-columns: repeat(2, 1fr);
  }
}

