    due: true,
  },
];

const ACTS = [
  {
    type: "checkin",
    icon: "✓",
    title: "Mariana Sosa checked in",
    sub: "Room 204 · key issued",
    time: "08:42",
  },
  {
    type: "payment",
    icon: "€",
    title: "Folio payment posted",
    sub: "€612.00 · card · 204",
    time: "08:41",
  },
  {
    type: "housekeeping",
    icon: "✦",
    title: "Room 117 reported clean",
    sub: "Ines · housekeeping",
    time: "08:36",
  },
  {
    type: "alert",
    icon: "!",
    title: "Late check-in flagged",
    sub: "Olivier Banks · room 121",
    time: "08:21",
  },
  {
    type: "checkin",
    icon: "✓",
    title: "Pre-check-in completed",
    sub: "Aiko Tanaka · room 302",
    time: "08:18",
  },
  {
    type: "payment",
    icon: "€",
    title: "Deposit captured",
    sub: "€184.00 · 118 · hold",
    time: "08:11",
  },
  {
    type: "housekeeping",
    icon: "✦",
    title: "Room 207 inspected",
    sub: "Departure clean",
    time: "08:02",
  },
];

// ── Render ──────────────────────────────────────────────────────────────────
const rows = document.getElementById("rows");
const acts = document.getElementById("acts");
const toast = document.getElementById("toast");
let activeTab = "arrivals";
let activeFilter = "all";

function getList() {
  if (activeTab === "arrivals") return ARRIVALS;
  if (activeTab === "inhouse") return INHOUSE;
  return DEPARTURES;
}

function getPrimaryAction() {
  if (activeTab === "arrivals") return "Check in";
  if (activeTab === "inhouse") return "Open folio";
  return "Check out";
}

function renderRows() {
  const query = (document.getElementById("search").value || "").toLowerCase().trim();
  const list = getList().filter((r) => {
    if (activeFilter === "vip" && !r.vip) return false;
    if (activeFilter === "due" && !r.due) return false;
    if (query) {
      return (
        r.name.toLowerCase().includes(query) ||
        r.room.includes(query) ||
        r.meta.toLowerCase().includes(query)
      );
    }
    return true;
  });

  if (!list.length) {
    rows.innerHTML = `<p class="empty">No reservations match the current filter.</p>`;
    return;
  }

  rows.innerHTML = list
    .map(
      (r) => `
      <article class="row ${r.vip ? "is-vip" : ""}">
        <div class="room">${r.room}</div>
        <div class="guest">
          <div class="guest-name">${r.name}</div>
          <div class="guest-meta">${r.meta}</div>
        </div>
        <div class="dates">
          <strong>${fmtShort(r.in)}</strong>
          <span>→ ${fmtShort(r.out)}</span>
        </div>
        <div class="amount">${r.amount}</div>
        <div><span class="status ${r.status}">${r.status.replace("-", " ")}</span></div>
        <div class="row-actions">
          <button class="action">Folio</button>
          <button class="action primary">${getPrimaryAction()}</button>
        </div>
      </article>`
    )
    .join("");
}

function renderActs() {
  acts.innerHTML = ACTS.map(
    (a) => `
    <li class="act ${a.type}">
      <span class="act-icon">${a.icon}</span>
      <div class="act-body">
        <p>${a.title}</p>
        <small>${a.sub}</small>
      </div>
      <span class="act-time">${a.time}</span>
    </li>`
  ).join("");
}

function fmtShort(iso) {
  const d = new Date(iso + "T00:00");
  return d.toLocaleDateString("en-GB", { day: "2-digit", month: "short" });
}

function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 1800);
}

// ── Wiring ──────────────────────────────────────────────────────────────────
document.querySelectorAll(".tab").forEach((t) => {
  t.addEventListener("click", () => {
    document.querySelectorAll(".tab").forEach((x) => x.classList.remove("is-active"));
    t.classList.add("is-active");
    activeTab = t.dataset.tab;
    renderRows();
  });
});
document.querySelectorAll(".chip").forEach((c) => {
  c.addEventListener("click", () => {
    document.querySelectorAll(".chip").forEach((x) => x.classList.remove("is-active"));
    c.classList.add("is-active");
    activeFilter = c.dataset.filter;
    renderRows();
  });
});
document.getElementById("search").addEventListener("input", renderRows);

rows.addEventListener("click", (e) => {
  const btn = e.target.closest("button.action");
  if (!btn) return;
  const name = btn.closest(".row").querySelector(".guest-name").textContent;
  showToast(`${btn.textContent} · ${name}`);
});

document
  .querySelectorAll(".ghost-btn, .quick-btn")
  .forEach((b) => b.addEventListener("click", () => showToast(b.textContent.trim())));

// ── Clock + label ───────────────────────────────────────────────────────────
const clock = document.getElementById("clock");
const todayLabel = document.getElementById("todayLabel");

function tick() {
  const now = new Date();
  const hhmm = now.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
  const wk = now.toLocaleDateString("en-GB", { weekday: "short" });
  clock.textContent = `${hhmm} · ${wk}`;
  todayLabel.textContent = now.toLocaleDateString("en-GB", {
    weekday: "long",
    day: "numeric",
    month: "long",
  });
}
tick();
setInterval(tick, 1000);

renderRows();
renderActs();

snippets.css:
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.2);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

.co {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}
.topbar {
  background: var(--bone);
  border-bottom: 1px solid var(--line);
  padding: 22px 32px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 24px;
}
.kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold-d);
  font-weight: 600;
}
.topbar h1 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 2rem;
  letter-spacing: -0.005em;
  margin-top: 2px;
}
.topbar h1 span {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--navy-2);
  font-size: 1.7rem;
  letter-spacing: 0;
}
.topsub {
  font-size: 0.92rem;
  color: var(--warm-gray);
  margin-top: 4px;
}
.top-actions {
  display: flex;
  gap: 8px;
}
.ghost {
  background: transparent;
  border: 1px solid var(--line-strong);
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ink-2);
  padding: 9px 16px;
  border-radius: 999px;
  cursor: pointer;
}
.ghost:hover {
  background: var(--cream-2);
  border-color: var(--navy-2);
  color: var(--navy-d);
}

.layout {
  display: grid;
  grid-template-columns: 1fr 360px;
  gap: 24px;
  padding: 24px 32px;
  align-items: start;
  flex: 1;
}

/* ── Folio ── */
.folio {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  overflow: hidden;
}
.folio-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 20px;
  border-bottom: 1px solid var(--line);
  gap: 16px;
}
.seg {
  display: inline-flex;
  background: var(--cream-2);
  padding: 4px;
  border-radius: 999px;
  gap: 4px;
}
.seg.full {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  width: 100%;
  margin-bottom: 14px;
}
.seg-btn {
  background: transparent;
  border: none;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.82rem;
  padding: 8px 14px;
  border-radius: 999px;
  cursor: pointer;
  color: var(--ink-2);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}
.seg-btn.is-active {
  background: var(--bone);
  color: var(--navy-d);
  box-shadow: 0 1px 2px rgba(22, 30, 44, 0.08);
}
.pill {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 700;
  background: rgba(22, 30, 44, 0.08);
  padding: 2px 8px;
  border-radius: 999px;
}
.seg-btn.is-active .pill {
  background: rgba(22, 30, 44, 0.12);
}

.bulk {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.82rem;
  color: var(--ink-2);
  font-weight: 600;
}
.bulk-btn {
  background: var(--cream);
  border: 1px solid var(--line-strong);
  font-family: inherit;
  font-size: 0.78rem;
  font-weight: 600;
  padding: 6px 12px;
  border-radius: var(--r-sm);
  cursor: pointer;
  color: var(--ink-2);
}
.bulk-btn:hover {
  border-color: var(--gold);
  color: var(--gold-d);
}

.lines {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}
.lines thead {
  background: var(--cream);
}
.lines th {
  text-align: left;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--warm-gray);
  font-weight: 700;
  padding: 11px 14px;
  border-bottom: 1px solid var(--line);
}
.lines th.num {
  text-align: right;
}
.lines th.ck {
  width: 36px;
  padding-right: 0;
}
.lines td {
  padding: 12px 14px;
  border-bottom: 1px solid var(--line);
  color: var(--ink-2);
}
.lines td.num {
  text-align: right;
  font-family: var(--font-mono);
  font-weight: 600;
  color: var(--ink);
}
.lines tbody tr:last-child td {
  border-bottom: none;
}
.lines tbody tr.is-section td {
  background: var(--cream);
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--navy-d);
  font-size: 1rem;
  padding-top: 10px;
  padding-bottom: 10px;
}
.lines tbody tr.is-voided td:not(.actions) {
  text-decoration: line-through;
  color: var(--warm-gray);
}
.lines tbody tr.is-transferred td:not(.actions) {
  opacity: 0.6;
  font-style: italic;
}
.cat-pill {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 3px 8px;
  border-radius: 999px;
  background: rgba(22, 30, 44, 0.06);
  color: var(--ink-2);
}
.cat-pill.acc {
  background: rgba(74, 109, 160, 0.14);
  color: var(--info);
}
.cat-pill.fb {
  background: rgba(217, 144, 32, 0.16);
  color: var(--warning);
}
.cat-pill.mini {
  background: rgba(193, 113, 74, 0.16);
  color: #a05a38;
}
.cat-pill.spa {
  background: rgba(74, 119, 82, 0.14);
  color: var(--success);
}
.cat-pill.tax {
  background: rgba(22, 30, 44, 0.06);
  color: var(--warm-gray);
}

.row-act {
  background: transparent;
  border: none;
  font-family: inherit;
  font-size: 0.78rem;
  color: var(--warm-gray);
  cursor: pointer;
  padding: 4px 6px;
  border-radius: var(--r-sm);
}
.row-act:hover {
  color: var(--danger);
  background: var(--cream);
}

.lines input[type="checkbox"] {
  accent-color: var(--navy);
  width: 14px;
  height: 14px;
}

/* ── Settle rail ── */
.settle {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 22px;
  position: sticky;
  top: 24px;
}
.settle h3 {
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--gold-d);
  font-weight: 700;
  margin-bottom: 12px;
}
.t-row {
  display: flex;
  justify-content: space-between;
  padding: 8px 0;
  font-size: 0.86rem;
  color: var(--ink-2);
  border-bottom: 1px dashed var(--line);
}
.t-row:last-of-type {
  border-bottom: none;
}
.t-row span:last-child {
  font-family: var(--font-mono);
  font-weight: 600;
  color: var(--ink);
}
.t-row.paid span:last-child {
  color: var(--success);
}
.t-row.balance {
  border-top: 1px solid var(--line-strong);
  border-bottom: none;
  margin-top: 4px;
  padding-top: 12px;
  font-weight: 700;
  font-size: 1rem;
  color: var(--navy-d);
}
.t-row.balance span:last-child {
  font-size: 1.3rem;
  color: var(--gold-d);
  font-family: var(--font-display);
}
.totals {
  margin-bottom: 22px;
}
.pay {
  padding-top: 18px;
  border-top: 1px solid var(--line);
}
.pay-body {
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 14px 16px;
  font-size: 0.86rem;
  color: var(--ink-2);
  line-height: 1.55;
  margin-bottom: 16px;
}
.pay-body strong {
  color: var(--navy-d);
}
.pay-body .split-row {
  display: flex;
  justify-content: space-between;
  padding: 4px 0;
  font-family: var(--font-mono);
}
.settle-btn {
  width: 100%;
  background: var(--gold);
  color: var(--navy-d);
  border: none;
  font-family: inherit;
  font-weight: 700;
  font-size: 0.95rem;
  padding: 14px 18px;
  border-radius: 999px;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  letter-spacing: 0.01em;
}
.settle-btn:hover:not(:disabled) {
  background: var(--gold-light);
}
.settle-btn:disabled {
  background: var(--warm-gray);
  color: var(--cream);
  cursor: not-allowed;
  opacity: 0.7;
}
.settle-amt {
  font-family: var(--font-mono);
  font-weight: 700;
  background: rgba(15, 29, 54, 0.16);
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 0.86rem;
}

.result {
  margin-top: 16px;
  background: rgba(74, 119, 82, 0.1);
  border: 1px solid rgba(74, 119, 82, 0.3);
  border-radius: var(--r-md);
  padding: 14px 18px;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 14px;
  align-items: center;
}
.result-mark {
  width: 36px;
  height: 36px;
  border-radius: 999px;
  background: var(--success);
  color: var(--bone);
  display: grid;
  place-items: center;
  font-weight: 700;
  font-size: 1.2rem;
}
.result strong {
  font-size: 0.92rem;
  color: var(--success);
  font-family: var(--font-display);
  font-weight: 700;
  display: block;
}
.result strong span {
  font-family: var(--font-mono);
}
.result small {
  font-size: 0.78rem;
  color: var(--ink-2);
  display: block;
  margin-top: 2px;
}
.result small em {
  color: var(--success);
  font-style: normal;
  font-weight: 600;
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 22px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: 0 10px 30px rgba(22, 30, 44, 0.18);
}

@media (max-width: 1024px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .settle {
    position: static;
  }
}

/* ── Honor [hidden] over display (overlay/panel toggle fix) ── */
.bulk[hidden] {
  display: none;
}
.result[hidden] {
  display: none;
}

