  },

  { id: 9, section: "Mini-bar" },
  {
    id: 10,
    date: "21 May",
    desc: "Mini-bar · 2 × water · 1 × nuts",
    cat: "mini",
    catLabel: "Mini",
    qty: 1,
    amount: 14,
  },
  {
    id: 11,
    date: "23 May",
    desc: "Mini-bar · 1 × whisky",
    cat: "mini",
    catLabel: "Mini",
    qty: 1,
    amount: 18,
  },

  { id: 12, section: "Spa & Wellness" },
  {
    id: 13,
    date: "22 May",
    desc: "Spa · couples massage 60'",
    cat: "spa",
    catLabel: "Spa",
    qty: 1,
    amount: 145,
  },
];

// state per line: { folio: "A"|"B", void: bool }
const state = new Map();
LINES.forEach((l) => {
  if (!l.section) state.set(l.id, { folio: "A", void: false, qty: l.qty });
});
// Put one mini-bar item already on folio B (€18 + tax) to match the pill in mock.
state.get(11).folio = "B";

const PAID_DEPOSIT = 482;
const VAT_RATE = 0.1;
const CITY_TAX = 16.5;

let activeFolio = "A";
let payMethod = "card";
let settled = false;

const tbody = document.getElementById("rows");
const checkAll = document.getElementById("checkAll");
const bulk = document.getElementById("bulk");
const bulkN = document.getElementById("bulkN");
const subEl = document.getElementById("subtotal");
const taxEl = document.getElementById("tax");
const balEl = document.getElementById("balance");
const payBody = document.getElementById("payBody");
const settleAmt = document.getElementById("settleAmt");
const settleBtn = document.getElementById("settle");
const result = document.getElementById("result");
const toast = document.getElementById("toast");

const fmt = (n) =>
  `€${n.toLocaleString("en-GB", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

function visibleLines() {
  return LINES.filter((l) => l.section || state.get(l.id).folio === activeFolio);
}

function lineAmount(l) {
  const s = state.get(l.id);
  return s.qty * l.amount;
}

function renderRows() {
  tbody.innerHTML = visibleLines()
    .map((l) => {
      if (l.section) {
        return `<tr class="is-section"><td colspan="7">${l.section}</td></tr>`;
      }
      const s = state.get(l.id);
      const cls = s.void ? "is-voided" : "";
      return `
        <tr class="${cls}" data-id="${l.id}">
          <td class="ck"><input type="checkbox" class="line-ck" /></td>
          <td>${l.date}</td>
          <td>${l.desc}</td>
          <td><span class="cat-pill ${l.cat}">${l.catLabel}</span></td>
          <td class="num">${s.qty}</td>
          <td class="num">${fmt(lineAmount(l))}</td>
          <td class="actions"><button class="row-act" title="Void">✕</button></td>
        </tr>`;
    })
    .join("");
  // Restore check state on visible rows (we re-render, so reset)
  checkAll.checked = false;
  updateBulk();
}

function activeLines() {
  return LINES.filter(
    (l) => !l.section && state.get(l.id).folio === activeFolio && !state.get(l.id).void
  );
}

function totals() {
  const subtotal = activeLines().reduce((sum, l) => sum + lineAmount(l), 0);
  // City tax line (id 3) already in subtotal; here we model VAT as 10% of non-tax categories.
  const taxable = activeLines()
    .filter((l) => l.cat !== "tax")
    .reduce((sum, l) => sum + lineAmount(l), 0);
  const tax = taxable * VAT_RATE;
  const grand = subtotal + tax; // city tax separate display
  return { subtotal, tax, grand };
}

function renderTotals() {
  const { subtotal, tax, grand } = totals();
  subEl.textContent = fmt(subtotal);
  taxEl.textContent = fmt(tax);
  let balance =
    subtotal + tax + (activeFolio === "A" ? 0 : 0) - (activeFolio === "A" ? PAID_DEPOSIT : 0);
  if (balance < 0) balance = 0;
  balEl.textContent = fmt(balance);
  settleAmt.textContent = fmt(balance);
  settleBtn.disabled = balance < 0.01 || settled;
}

function updateBulk() {
  const checked = tbody.querySelectorAll(".line-ck:checked");
  if (checked.length) {
    bulk.hidden = false;
    bulkN.textContent = checked.length;
  } else {
    bulk.hidden = true;
  }
}

tbody.addEventListener("change", (e) => {
  if (e.target.matches(".line-ck")) updateBulk();
});
tbody.addEventListener("click", (e) => {
  if (e.target.matches(".row-act")) {
    const tr = e.target.closest("tr");
    const id = parseInt(tr.dataset.id, 10);
    state.get(id).void = !state.get(id).void;
    renderRows();
    renderTotals();
    showToast("Line voided");
  }
});
checkAll.addEventListener("change", () => {
  tbody.querySelectorAll(".line-ck").forEach((c) => (c.checked = checkAll.checked));
  updateBulk();
});

document.getElementById("bulk").addEventListener("click", (e) => {
  const btn = e.target.closest(".bulk-btn");
  if (!btn) return;
  const action = btn.dataset.bulk;
  const checked = [...tbody.querySelectorAll(".line-ck:checked")].map((c) =>
    parseInt(c.closest("tr").dataset.id, 10)
  );
  checked.forEach((id) => {
    if (action === "void") state.get(id).void = true;
    if (action === "transfer") state.get(id).folio = activeFolio === "A" ? "B" : "A";
  });
  showToast(`${checked.length} line(s) ${action === "void" ? "voided" : "transferred"}`);
  renderRows();
  renderTotals();
});

// Folio tabs
document.querySelectorAll(".folio-head .seg-btn").forEach((b) =>
  b.addEventListener("click", () => {
    if (b.dataset.fol === "C") {
      showToast("New folio created (mock)");
      return;
    }
    document
      .querySelectorAll(".folio-head .seg-btn")
      .forEach((x) => x.classList.remove("is-active"));
    b.classList.add("is-active");
    activeFolio = b.dataset.fol;
    renderRows();
    renderTotals();
  })
);

// Payment seg
const PAY_TEXT = {
  card: `Charge balance to card on file <strong>Visa •••• 4421</strong>. Authorisation typically clears in 4–10 seconds.`,
  cash: `Collect balance in cash. Cash drawer opens after confirmation. Change calculated automatically.`,
  split: `<div class="split-row"><span>Card · Visa •••• 4421</span><span><strong>€350.00</strong></span></div>
         <div class="split-row"><span>Cash</span><span><strong>€68.00</strong></span></div>
         <p style="margin-top:6px;font-size:.78rem;color:var(--warm-gray);">Adjust amounts before settling.</p>`,
  company: `Direct bill to <strong>Innovo Travel S.L.</strong> (NIF B-3382041). Folio transferred to AR · invoice issued.`,
};
function renderPay() {
  payBody.innerHTML = PAY_TEXT[payMethod];
}
renderPay();
document.getElementById("paySeg").addEventListener("click", (e) => {
  const b = e.target.closest(".seg-btn");
  if (!b) return;
  document.querySelectorAll("#paySeg .seg-btn").forEach((x) => x.classList.remove("is-active"));
  b.classList.add("is-active");
  payMethod = b.dataset.pay;
  renderPay();
});

settleBtn.addEventListener("click", () => {
  settled = true;
  settleBtn.disabled = true;
  result.hidden = false;
  result.scrollIntoView({ behavior: "smooth", block: "nearest" });
  showToast("Folio settled · room released");
});

function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 1600);
}

renderRows();
renderTotals();

snippets.css:
:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.2);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --cell-w: 64px;
  --row-h: 40px;
  --label-w: 110px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
  overflow: hidden;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

.rack-app {
  height: 100vh;
  display: grid;
  grid-template-rows: auto 1fr auto;
}

/* ── Topbar / Toolbar ── */
.topbar {
  background: var(--bone);
  border-bottom: 1px solid var(--line);
  padding: 18px 24px 14px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 24px;
}
.kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold-d);
  font-weight: 600;
}
.topbar h1 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.85rem;
  letter-spacing: -0.005em;
  margin-top: 2px;
}
.toolbar {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  justify-content: flex-end;
}
.nav {
  display: inline-flex;
  gap: 4px;
  align-items: center;
}
.ico-btn {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  background: var(--cream);
  border: 1px solid var(--line);
  color: var(--navy-d);
  font-family: var(--font-display);
  font-size: 1.2rem;
  cursor: pointer;
  display: grid;
  place-items: center;
}
.ico-btn:hover {
  background: var(--cream-2);
}
.today-btn {
  background: var(--navy);
  color: var(--bone);
  border: none;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.78rem;
  padding: 8px 14px;
  border-radius: 999px;
  cursor: pointer;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.today-btn:hover {
  background: var(--navy-d);
}

.range-label {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1.05rem;
  color: var(--navy-d);
  min-width: 220px;
  text-align: center;
}
.filter {
  display: flex;
  gap: 6px;
}
.filter select {
  font-family: inherit;
  font-size: 0.8rem;
  padding: 7px 24px 7px 12px;
  border-radius: var(--r-md, 8px);
  border: 1px solid var(--line-strong);
  background: var(--cream);
  color: var(--ink-2);
  font-weight: 500;
  cursor: pointer;
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--navy-2) 50%),
    linear-gradient(135deg, var(--navy-2) 50%, transparent 50%);
  background-position: right 11px center, right 6px center;
  background-size: 5px 5px;
  background-repeat: no-repeat;
}
.legend {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.74rem;
  color: var(--warm-gray);
  font-weight: 500;
}
.lg {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 3px;
  margin-left: 10px;
}
.lg.confirmed {
  background: var(--info);
}
.lg.checked-in {
  background: var(--success);
}
.lg.due-out {
  background: var(--warning);
}
.lg.maintenance {
  background: var(--warm-gray);
}

/* ── Rack grid ── */
.rack {
  overflow: auto;
  background: var(--cream);
  display: grid;
  grid-template-columns: var(--label-w) 1fr;
  grid-template-rows: 36px 1fr;
}
.rack-corner {
  position: sticky;
  top: 0;
  left: 0;
  z-index: 4;
  background: var(--navy);
  color: var(--bone);
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 12px 14px;
  border-right: 1px solid var(--navy-d);
  border-bottom: 1px solid var(--navy-d);
}
.rack-days {
  position: sticky;
  top: 0;
  z-index: 3;
  background: var(--bone);
  border-bottom: 1px solid var(--line-strong);
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: var(--cell-w);
  height: 36px;
}
.day {
  border-right: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 0.72rem;
  color: var(--warm-gray);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
  padding: 4px 0;
}
.day strong {
  font-size: 0.95rem;
  color: var(--navy-d);
  font-family: var(--font-display);
}
.day.is-today {
  background: rgba(201, 166, 73, 0.16);
  color: var(--gold-d);
}
.day.is-today strong {
  color: var(--gold-d);
}
.day.is-weekend {
  background: rgba(22, 30, 44, 0.03);
}

.rack-rooms {
  position: sticky;
  left: 0;
  z-index: 2;
  background: var(--bone);
  border-right: 1px solid var(--line-strong);
  display: grid;
  grid-auto-rows: var(--row-h);
}
.rm-label {
  border-bottom: 1px solid var(--line);
  padding: 0 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--ink-2);
}
.rm-label .rm-no {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--navy-d);
}
.rm-label .rm-type {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--warm-gray);
}
.rm-group {
  background: var(--cream-2);
  color: var(--gold-d);
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 700;
  padding: 6px 12px;
  border-bottom: 1px solid var(--line);
}

.rack-grid {
  position: relative;
  display: grid;
  grid-auto-columns: var(--cell-w);
  grid-auto-rows: var(--row-h);
}
.cell {
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.cell.is-weekend {
  background: rgba(22, 30, 44, 0.03);
}
.cell.is-today {
  background: rgba(201, 166, 73, 0.08);
}
.cell-group {
  background: var(--cream-2);
  border-bottom: 1px solid var(--line);
  grid-column: 1 / -1;
}

.stay {
  margin: 4px 2px;
  padding: 4px 9px;
  border-radius: 999px;
  font-size: 0.74rem;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  border: 1px solid transparent;
  transition: transform 0.1s, box-shadow 0.1s;
}
.stay:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(22, 30, 44, 0.18);
}
.stay.is-selected {
  outline: 2px solid var(--gold);
  outline-offset: 1px;
}
.stay.confirmed {
  background: rgba(74, 109, 160, 0.18);
  color: var(--info);
  border-color: rgba(74, 109, 160, 0.4);
}
.stay.checked-in {
  background: rgba(74, 119, 82, 0.2);
  color: var(--success);
  border-color: rgba(74, 119, 82, 0.4);
}
.stay.due-out {
  background: rgba(217, 144, 32, 0.22);
  color: var(--warning);
  border-color: rgba(217, 144, 32, 0.42);
}
.stay.maintenance {
  background: rgba(22, 30, 44, 0.1);
  color: var(--warm-gray);
  border-color: var(--line-strong);
  font-style: italic;
}
.stay-dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: currentColor;
  flex-shrink: 0;
}

/* ── Detail strip ── */
.detail {
  background: var(--bone);
  border-top: 1px solid var(--line);
  padding: 14px 24px;
  min-height: 86px;
  display: flex;
  align-items: center;
}
.empty-detail {
  font-size: 0.86rem;
  color: var(--warm-gray);
  font-style: italic;
}
.detail-card {
  display: grid;
  grid-template-columns: auto 1fr auto auto auto auto;
  align-items: center;
  gap: 24px;
  width: 100%;
}
.dc-room {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 2.1rem;
  color: var(--navy-d);
  letter-spacing: -0.01em;
}
.dc-guest p {
  font-size: 0.94rem;
  font-weight: 600;
  color: var(--ink);
}
.dc-guest small {
  font-size: 0.74rem;
  color: var(--warm-gray);
}
.dc-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.dc-block strong {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gold-d);
}
.dc-block span {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 0.86rem;
  color: var(--ink);
}
.dc-status {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 5px 11px;
  border-radius: 999px;
  font-weight: 700;
}
.dc-status.confirmed {
  background: rgba(74, 109, 160, 0.16);
  color: var(--info);
}
.dc-status.checked-in {
  background: rgba(74, 119, 82, 0.16);
  color: var(--success);
}
.dc-status.due-out {
  background: rgba(217, 144, 32, 0.18);
  color: var(--warning);
}
.dc-action {
  background: var(--navy);
  color: var(--bone);
  border: none;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.8rem;
  padding: 9px 16px;
  border-radius: 999px;
  cursor: pointer;
}
.dc-action:hover {
  background: var(--navy-d);
}

@media (max-width: 1024px) {
  .toolbar {
    flex-direction: column;
    align-items: flex-end;
    gap: 10px;
  }
  .topbar {
    flex-direction: column;
    align-items: flex-start;
  }
  .legend {
    display: none;
  }
}

