  font-size: 0.74rem;
  color: var(--warm-gray);
  font-weight: 600;
  letter-spacing: 0.02em;
}
.field input,
.field select {
  font-family: inherit;
  font-size: 0.92rem;
  background: var(--cream);
  border: 1px solid var(--line-strong);
  border-radius: var(--r-sm);
  padding: 9px 12px;
  color: var(--ink);
  outline: none;
}
.field input:focus,
.field select:focus {
  border-color: var(--gold);
}
.check {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.86rem;
  color: var(--ink-2);
  margin-top: 12px;
  cursor: pointer;
}
.check input {
  accent-color: var(--navy);
  width: 16px;
  height: 16px;
}
.sig {
  margin-top: 16px;
  display: grid;
  gap: 6px;
}
.sig span {
  font-size: 0.74rem;
  color: var(--warm-gray);
  font-weight: 600;
}
.sig-pad {
  height: 80px;
  background: repeating-linear-gradient(
    0deg,
    var(--cream) 0,
    var(--cream) 18px,
    var(--cream-2) 19px
  );
  border: 1px dashed var(--line-strong);
  border-radius: var(--r-sm);
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-style: italic;
  color: var(--warm-gray);
  cursor: pointer;
}
.rooms {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 8px;
}
.room-pick {
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 12px 14px;
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  color: inherit;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.room-pick:hover {
  border-color: var(--gold);
}
.room-pick.is-selected {
  background: var(--bone);
  border-color: var(--gold);
  outline: 1px solid var(--gold);
}
.room-pick strong {
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 700;
  color: var(--navy-d);
}
.room-pick small {
  font-size: 0.76rem;
  color: var(--warm-gray);
}
.room-pick em {
  font-size: 0.7rem;
  color: var(--success);
  font-style: normal;
  font-weight: 600;
  margin-top: 4px;
}

.keys {
  display: grid;
  gap: 8px;
}
.key {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  cursor: pointer;
}
.key input {
  accent-color: var(--navy);
  width: 16px;
  height: 16px;
}
.key strong {
  font-size: 0.9rem;
}
.key small {
  display: block;
  font-size: 0.74rem;
  color: var(--warm-gray);
}

/* ── Step 3 ── */
.folio {
  margin-bottom: 18px;
}
.folio h3 {
  font-size: 0.82rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--gold-d);
  font-weight: 700;
  margin-bottom: 10px;
}
.folio-list {
  list-style: none;
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 8px 18px;
}
.folio-list li {
  display: flex;
  justify-content: space-between;
  padding: 12px 0;
  border-bottom: 1px dashed var(--line);
  font-size: 0.9rem;
  color: var(--ink-2);
}
.folio-list li:last-child {
  border-bottom: none;
}
.folio-list li span:last-child {
  font-family: var(--font-mono);
  font-weight: 600;
  color: var(--ink);
}
.folio-list li.total {
  font-weight: 700;
  color: var(--navy-d);
  font-size: 1rem;
}
.folio-list li.total span:last-child {
  font-size: 1.15rem;
  color: var(--navy-d);
}
.folio-list .incl {
  color: var(--success);
  font-style: italic;
  font-weight: 500;
}

.seg {
  display: inline-flex;
  background: var(--cream-2);
  padding: 4px;
  border-radius: 999px;
  gap: 4px;
  margin-bottom: 14px;
}
.seg-btn {
  background: transparent;
  border: none;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.82rem;
  padding: 8px 16px;
  border-radius: 999px;
  cursor: pointer;
  color: var(--ink-2);
}
.seg-btn.is-active {
  background: var(--bone);
  color: var(--navy-d);
  box-shadow: 0 1px 2px rgba(22, 30, 44, 0.08);
}
.pay-body {
  background: var(--cream);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 18px;
  font-size: 0.9rem;
  color: var(--ink-2);
  line-height: 1.55;
}
.pay-body strong {
  color: var(--navy-d);
}
.welcome {
  display: grid;
  gap: 6px;
}

/* ── Summary rail ── */
.summary {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 22px;
  position: sticky;
  top: 24px;
}
.summary h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.2rem;
  letter-spacing: -0.005em;
  color: var(--navy-d);
  margin-bottom: 16px;
}
.summary-empty {
  font-size: 0.86rem;
  color: var(--warm-gray);
  font-style: italic;
}
.sum-row {
  display: flex;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px dashed var(--line);
  font-size: 0.82rem;
}
.sum-row:last-of-type {
  border-bottom: none;
}
.sum-row span:first-child {
  color: var(--warm-gray);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 0.7rem;
  font-weight: 700;
}
.sum-row span:last-child {
  font-weight: 600;
  color: var(--ink);
  text-align: right;
}
.sum-block {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}
.sum-block strong {
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--gold-d);
  font-weight: 700;
  display: block;
}
.sum-block small {
  font-size: 0.74rem;
  color: var(--warm-gray);
  margin-top: 2px;
  display: block;
}

/* ── Footer ── */
.footer {
  background: var(--bone);
  border-top: 1px solid var(--line);
  padding: 14px 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.back,
.next {
  font-family: inherit;
  font-weight: 600;
  font-size: 0.92rem;
  padding: 11px 22px;
  border-radius: 999px;
  cursor: pointer;
  border: 1px solid var(--line-strong);
  background: var(--cream);
  color: var(--ink-2);
}
.back:hover:not(:disabled) {
  background: var(--cream-2);
}
.back:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.next {
  background: var(--navy);
  color: var(--bone);
  border-color: var(--navy);
}
.next:hover:not(:disabled) {
  background: var(--navy-d);
}
.next:disabled {
  background: var(--warm-gray);
  border-color: var(--warm-gray);
  cursor: not-allowed;
  opacity: 0.7;
}
.next.is-final {
  background: var(--gold);
  color: var(--navy-d);
  border-color: var(--gold);
}
.next.is-final:hover:not(:disabled) {
  background: var(--gold-light);
}
.footer-meta {
  font-size: 0.78rem;
  color: var(--warm-gray);
  font-weight: 600;
  letter-spacing: 0.04em;
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 90px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 22px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: 0 10px 30px rgba(22, 30, 44, 0.18);
}

@media (max-width: 1024px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .summary {
    position: static;
  }
  .step-line {
    width: 24px;
  }
  .step .lbl {
    display: none;
  }
}

