:root {
  --navy: #1a2b4a;
  --navy-d: #0f1d36;
  --navy-2: #2d4570;
  --cream: #f7f3eb;
  --cream-2: #ece5d4;
  --bone: #fbf8f2;
  --gold: #c9a649;
  --gold-light: #e0c378;
  --gold-d: #a88a2e;
  --ink: #161e2c;
  --ink-2: #2e3a52;
  --warm-gray: #6c7280;
  --line: rgba(22, 30, 44, 0.1);
  --line-strong: rgba(22, 30, 44, 0.18);
  --success: #4a7752;
  --danger: #b34232;
  --warning: #d99020;
  --info: #4a6da0;
  --font-display: "Cormorant Garamond", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(22, 30, 44, 0.06), 0 2px 8px rgba(22, 30, 44, 0.06);
  --shadow-2: 0 10px 30px rgba(22, 30, 44, 0.14);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

.audit {
  max-width: 1140px;
  margin: 0 auto;
  padding: 28px 28px 64px;
}

/* ── Topbar ── */
.topbar {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  padding-bottom: 18px;
  margin-bottom: 22px;
  border-bottom: 1px solid var(--line);
}
.kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--gold-d);
  font-weight: 600;
}
.topbar h1 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 2.1rem;
  letter-spacing: -0.005em;
  margin-top: 2px;
}
.topbar h1 span {
  color: var(--navy-2);
  font-variant-numeric: tabular-nums;
}
.topbar .sub {
  font-size: 0.84rem;
  color: var(--warm-gray);
  margin-top: 6px;
}
.topbar .sub strong {
  color: var(--ink-2);
  font-weight: 600;
}
.topactions {
  display: flex;
  gap: 10px;
}
.ghost {
  background: var(--bone);
  border: 1px solid var(--line-strong);
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ink-2);
  padding: 9px 14px;
  border-radius: var(--r-sm);
  cursor: pointer;
}
.ghost:hover {
  border-color: var(--navy-2);
  color: var(--navy-d);
  background: var(--cream-2);
}

/* ── KPI band ── */
.kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 22px;
}
.kpi {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 16px 18px;
  position: relative;
  overflow: hidden;
}
.kpi::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: var(--gold);
}
.kpi-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  font-weight: 600;
}
.kpi-val {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 2rem;
  color: var(--navy-d);
  margin: 4px 0 2px;
  letter-spacing: -0.01em;
  font-variant-numeric: tabular-nums;
}
.kpi-val small {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--warm-gray);
  margin-left: 1px;
}
.kpi-meta {
  font-size: 0.74rem;
  color: var(--warm-gray);
}

/* ── Grid of cards ── */
.grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  margin-bottom: 22px;
}
.card {
  background: var(--bone);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  padding: 4px 0 8px;
  display: flex;
  flex-direction: column;
}
.card-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 18px 12px;
  border-bottom: 1px solid var(--line);
  gap: 12px;
}
.card-head h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.3rem;
  letter-spacing: -0.005em;
}
.card-meta {
  font-size: 0.74rem;
  color: var(--warm-gray);
  font-weight: 600;
}
.pill {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
}
.pill.warn {
  background: rgba(217, 144, 32, 0.16);
  color: var(--warning);
}
.pill.ok {
  background: rgba(74, 119, 82, 0.14);
  color: var(--success);
}

/* ── Revenue by department ── */
.dept {
  list-style: none;
  padding: 8px 18px 6px;
}
.dept li {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 10px 14px;
  padding: 9px 0;
  border-bottom: 1px dashed var(--line);
}
.dept li:last-child {
  border-bottom: none;
}
.dept .d-name {
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--ink);
}
.dept .d-amt {
  font-family: var(--font-mono);
  font-size: 0.84rem;
  font-weight: 700;
  color: var(--navy-d);
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.dept .d-bar {
  grid-column: 1 / -1;
  height: 5px;
  background: var(--cream-2);
  border-radius: 999px;
  overflow: hidden;
}
.dept .d-bar span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--gold-d), var(--gold-light));
  border-radius: 999px;
  width: 0;
  transition: width 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}

/* ── Postings list ── */
.posts {
  list-style: none;
  padding: 8px 18px 6px;
}
.posts li {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2px 14px;
  padding: 11px 0;
  border-bottom: 1px dashed var(--line);
}
.posts li:last-child {
  border-bottom: none;
}
.posts strong {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--ink);
}
.posts .num {
  font-family: var(--font-mono);
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--navy-d);
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.posts small {
  font-size: 0.72rem;
  color: var(--warm-gray);
  grid-column: 1 / -1;
}

/* ── Discrepancies ── */
.discr {
  list-style: none;
  padding: 8px 18px 6px;
}
.discr li {
  display: grid;
  grid-template-columns: 6px 1fr auto;
  align-items: center;
  gap: 4px 12px;
  padding: 12px 0 12px 0;
  border-bottom: 1px dashed var(--line);
  position: relative;
}
.discr li::before {
  content: "";
  width: 6px;
  align-self: stretch;
  border-radius: 999px;
  background: var(--warm-gray);
}
.discr li.warn::before {
  background: var(--warning);
}
.discr li.info::before {
  background: var(--info);
}
.discr li.ok::before {
  background: var(--success);
}
.discr li:last-child {
  border-bottom: none;
}
.discr strong {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--ink);
}
.discr small {
  grid-column: 2 / 3;
  font-size: 0.74rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.discr li.is-resolved {
  opacity: 0.55;
}
.discr li.is-resolved strong {
  text-decoration: line-through;
  text-decoration-color: var(--line-strong);
}
.mini {
  background: var(--navy);
  color: var(--bone);
  border: 1px solid var(--navy);
  font-family: inherit;
  font-size: 0.74rem;
  font-weight: 600;
  padding: 6px 12px;
  border-radius: var(--r-sm);
  cursor: pointer;
  grid-row: 1 / 3;
  grid-column: 3;
  white-space: nowrap;
}
.mini:hover {
  background: var(--navy-d);
}
.mini:disabled {
  background: var(--cream-2);
  color: var(--warm-gray);
  border-color: var(--line);
  cursor: default;
}

/* ── System checks ── */
.checks {
  list-style: none;
  padding: 8px 18px 6px;
}
.checks li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
  font-size: 0.86rem;
  color: var(--ink-2);
  border-bottom: 1px dashed var(--line);
}
.checks li:last-child {
  border-bottom: none;
}
.dot {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  flex-shrink: 0;
  background: var(--warm-gray);
}
.dot.ok {
  background: var(--success);
  box-shadow: 0 0 0 3px rgba(74, 119, 82, 0.16);
}
.dot.warn {
  background: var(--warning);
  box-shadow: 0 0 0 3px rgba(217, 144, 32, 0.18);
}

/* ── Run box ── */
.runbox {
  background: var(--navy);
  color: var(--bone);
  border-radius: var(--r-lg);
  padding: 22px 24px 24px;
  box-shadow: var(--shadow-2);
}
.runbox > header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  padding-bottom: 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  margin-bottom: 16px;
}
.runbox .kicker {
  color: var(--gold-light);
}
.runbox h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.7rem;
  margin-top: 2px;
}
.runbox .sub {
  font-size: 0.84rem;
  color: rgba(251, 248, 242, 0.72);
  margin-top: 6px;
}
.runbox .sub strong {
  color: var(--gold-light);
  font-weight: 600;
}
.run {
  background: var(--gold);
  color: var(--navy-d);
  border: none;
  font-family: inherit;
  font-weight: 700;
  font-size: 0.95rem;
  padding: 13px 22px;
  border-radius: var(--r-md);
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
}
.run:hover:not(:disabled) {
  background: var(--gold-light);
}
.run:disabled {
  opacity: 0.55;
  cursor: default;
}

.pipeline {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.pipeline li {
  display: grid;
  grid-template-columns: 36px 1fr auto;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border-radius: var(--r-md);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  transition: background 0.2s, border-color 0.2s;
}
.pipeline .stg {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--gold-light);
  font-weight: 700;
  font-size: 1rem;
}
.pipeline strong {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--bone);
}
.pipeline small {
  display: block;
  font-size: 0.74rem;
  color: rgba(251, 248, 242, 0.6);
  margin-top: 2px;
}
.pipeline .state {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(251, 248, 242, 0.55);
  white-space: nowrap;
}
.pipeline li.is-running {
  background: rgba(201, 166, 73, 0.12);
  border-color: rgba(201, 166, 73, 0.4);
}
.pipeline li.is-running .stg {
  background: var(--gold);
  color: var(--navy-d);
  animation: pulse 1s ease-in-out infinite;
}
.pipeline li.is-running .state {
  color: var(--gold-light);
}
.pipeline li.is-done {
  background: rgba(74, 119, 82, 0.14);
  border-color: rgba(74, 119, 82, 0.34);
}
.pipeline li.is-done .stg {
  background: var(--success);
  color: var(--bone);
  font-size: 1.05rem;
}
.pipeline li.is-done .state {
  color: #8fc99a;
}
@keyframes pulse {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.08);
  }
}

/* ── Toast ── */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-d);
  color: var(--bone);
  padding: 11px 20px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
  z-index: 20;
}

/* ── Responsive ── */
@media (max-width: 900px) {
  .kpis {
    grid-template-columns: repeat(2, 1fr);
  }
  .grid {
    grid-template-columns: 1fr;
  }
  .runbox > header {
    flex-direction: column;
    align-items: flex-start;
  }
  .run {
    width: 100%;
  }
}
@media (max-width: 520px) {
  .kpis {
    grid-template-columns: 1fr;
  }
  .topbar {
    flex-direction: column;
    align-items: flex-start;
  }
}

