/* ────────────────────────────────────────────
   SAGE & STONE — Farm-to-table palette
   Sage · bone · clay · moss · ink
────────────────────────────────────────────── */
:root {
  --bone: #f1ece1;
  --bone-2: #e6dfd0;
  --paper: #f8f4ea;
  --sage: #7b8a6a;
  --sage-d: #4f5f3f;
  --moss: #3d4a32;
  --moss-d: #2b3624;
  --clay: #a85a3a;
  --clay-d: #823f25;
  --honey: #c9a04c;
  --ink: #2a261f;
  --ink-2: #4a4338;
  --mute: #8a8170;
  --rule: rgba(42, 38, 31, 0.12);
  --font-display: "Fraunces", "Playfair Display", Georgia, serif;
  --font-body: "Inter Tight", "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-pill: 22px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html {
  scroll-behavior: smooth;
}
body {
  font-family: var(--font-body);
  background: var(--bone);
  color: var(--ink);
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
}

/* ── Nav ── */
.nav {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 16px 32px;
  background: rgba(241, 236, 225, 0.84);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--rule);
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--moss);
}
.brand-leaf {
  color: var(--sage);
}
.brand-name {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 1.1rem;
  letter-spacing: 0.04em;
  color: var(--ink);
}
.nav-links {
  display: flex;
  gap: 22px;
  margin-left: auto;
}
.nav-links a {
  color: var(--ink-2);
  text-decoration: none;
  font-size: 0.86rem;
  font-weight: 500;
}
.nav-links a:hover {
  color: var(--moss);
}
.nav-cta {
  background: var(--moss);
  color: var(--bone);
  border-radius: var(--r-pill);
  padding: 10px 18px;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-decoration: none;
}
.nav-cta:hover {
  background: var(--moss-d);
}
@media (max-width: 720px) {
  .nav-links {
    display: none;
  }
}

/* ── Hero ── */
.hero {
  position: relative;
  max-width: 1180px;
  margin: 0 auto;
  padding: 96px 32px 64px;
  overflow: hidden;
}
.blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(40px);
  z-index: 0;
  opacity: 0.5;
  pointer-events: none;
}
.blob-1 {
  width: 360px;
  height: 360px;
  background: var(--sage);
  top: -80px;
  right: -100px;
}
.blob-2 {
  width: 240px;
  height: 240px;
  background: var(--clay);
  bottom: -60px;
  left: -50px;
  opacity: 0.32;
}
.blob-3 {
  width: 160px;
  height: 160px;
  background: var(--honey);
  top: 60%;
  right: 30%;
  opacity: 0.28;
}
.hero-inner {
  position: relative;
  z-index: 1;
  max-width: 720px;
}
.kicker {
  font-size: 0.74rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--moss);
  font-weight: 600;
  margin-bottom: 14px;
}
.hero h1 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(2.8rem, 7vw, 5rem);
  line-height: 1.02;
  letter-spacing: -0.02em;
  color: var(--ink);
}
.em {
  font-style: italic;
  color: var(--clay);
}
.em-2 {
  font-style: italic;
  color: var(--moss);
}
.sub {
  margin-top: 22px;
  font-size: 1.06rem;
  color: var(--ink-2);
  max-width: 600px;
}
.actions {
  margin-top: 26px;
  display: flex;
  gap: 10px;
}
.btn {
  padding: 13px 22px;
  font-family: var(--font-body);
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  border-radius: var(--r-pill);
  cursor: pointer;
  border: 1px solid transparent;
  text-decoration: none;
  display: inline-block;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.btn-moss {
  background: var(--moss);
  color: var(--bone);
}
.btn-moss:hover {
  background: var(--moss-d);
}
.btn-clay {
  background: transparent;
  color: var(--clay);
  border-color: var(--clay);
}
.btn-clay:hover {
  background: var(--clay);
  color: var(--bone);
}

.hero-stats {
  margin-top: 36px;
  display: grid;
  grid-template-columns: repeat(3, auto);
  gap: 14px 36px;
  border-top: 1px solid var(--rule);
  padding-top: 22px;
  max-width: 600px;
}
.hero-stats div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.hero-stats dt {
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--mute);
  font-weight: 600;
}
.hero-stats dd {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 1.15rem;
  color: var(--moss);
}

/* ── Harvest ── */
.harvest {
  max-width: 1180px;
  margin: 0 auto;
  padding: 80px 32px 56px;
  scroll-margin-top: 80px;
}
.section-head {
  text-align: center;
  margin-bottom: 32px;
}
.section-head h2 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(2rem, 5vw, 3rem);
  letter-spacing: -0.015em;
  line-height: 1.05;
  margin-top: 4px;
}
.section-head h2 em {
  font-style: italic;
  color: var(--clay);
}

.harvest-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
}
.h-item {
  background: var(--paper);
  border: 1px solid var(--rule);
  border-radius: var(--r-pill);
  padding: 18px 22px 16px;
  display: flex;
  align-items: center;
  gap: 14px;
  transition: border-color 0.15s, transform 0.15s;
}
.h-item:hover {
  border-color: var(--sage);
  transform: translateY(-2px);
}
.h-icon {
  font-size: 1.6rem;
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: var(--bone-2);
}
.h-name {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 1.02rem;
}
.h-kg {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  color: var(--moss);
  font-weight: 600;
}
.harvest-foot {
  margin-top: 24px;
  text-align: center;
  font-size: 0.84rem;
  color: var(--mute);
  font-style: italic;
}
.harvest-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  background: var(--sage);
  border-radius: 999px;
  margin-right: 4px;
  vertical-align: middle;
  animation: pulse 1.6s ease-in-out infinite;
}
@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

/* ── No menu ── */
.no-menu {
  background: var(--moss);
  color: var(--bone);
  padding: 96px 32px;
  scroll-margin-top: 80px;
  position: relative;
  overflow: hidden;
}
.no-menu::before {
  content: "";
  position: absolute;
  width: 600px;
  height: 600px;
  border-radius: 999px;
  background: rgba(168, 90, 58, 0.15);
  top: -200px;
  right: -200px;
  filter: blur(60px);
}
.no-menu-inner {
  max-width: 920px;
  margin: 0 auto;
  position: relative;
}
.no-menu .kicker {
  color: var(--honey);
}
.no-menu h2 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(2.2rem, 5vw, 3.4rem);
  line-height: 1.05;
  letter-spacing: -0.015em;
  margin-top: 6px;
}
.no-menu h2 .em {
  color: var(--honey);
}
.no-menu > .no-menu-inner > p {
  margin-top: 24px;
  font-size: 1.08rem;
  color: rgba(241, 236, 225, 0.78);
  max-width: 640px;
}

.reveal {
  margin-top: 40px;
  background: rgba(241, 236, 225, 0.06);
  border: 1px solid rgba(241, 236, 225, 0.12);
  border-radius: 18px;
  padding: 30px 32px 26px;
}
.reveal-label {
  font-size: 0.72rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--honey);
  font-weight: 700;
  margin-bottom: 14px;
}
.reveal-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.reveal-list li {
  display: grid;
  grid-template-columns: 28px 1fr;
  align-items: baseline;
  gap: 14px;
  padding-bottom: 14px;
  border-bottom: 1px dashed rgba(241, 236, 225, 0.12);
}
.reveal-list li:last-child {
  border-bottom: none;
  padding-bottom: 0;
}
.r-no {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 1.05rem;
  color: var(--honey);
}
.r-name {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 1.2rem;
  color: var(--bone);
}
.r-mod {
  grid-column: 2;
  font-size: 0.86rem;
  font-style: italic;
  color: rgba(241, 236, 225, 0.65);
  margin-top: 2px;
}

/* ── Garden ── */
.garden {
