}
.contact-card address {
  font-style: normal;
  line-height: 1.8;
  font-size: 0.96rem;
  color: var(--ink-2);
}
.note {
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px dashed var(--rule);
  font-size: 0.84rem;
