  color: var(--mute);
}

/* ── Reserve ── */
.reserve {
  padding: 96px 32px;
  scroll-margin-top: 80px;
}
.reserve-inner {
  max-width: 1080px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
