  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(44, 26, 14, 0.08), 0 2px 6px rgba(44, 26, 14, 0.06);
  --shadow-2: 0 8px 24px rgba(44, 26, 14, 0.12);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: linear-gradient(180deg, var(--cream-2) 0%, var(--cream) 100%);
  color: var(--ink);
  min-height: 100vh;
  padding: 36px 16px 56px;
  display: flex;
  justify-content: center;
  -webkit-font-smoothing: antialiased;
}

.card {
  width: 100%;
  max-width: 560px;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-2);
  padding: 32px 30px 28px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ── Head ── */
.card-head {
  text-align: center;
}
.kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--terracotta);
  font-weight: 600;
  margin-bottom: 6px;
}
.card-head h1 {
  font-family: var(--font-display);
  font-size: clamp(1.7rem, 4vw, 2.1rem);
  font-weight: 700;
  letter-spacing: -0.015em;
}
.sub {
  margin-top: 4px;
  font-size: 0.86rem;
  color: var(--warm-gray);
  font-style: italic;
}

/* ── Form base ── */
.form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.field-label {
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--ink-2);
  font-weight: 700;
}
.optional {
  font-weight: 500;
  color: var(--warm-gray);
  letter-spacing: 0;
  text-transform: none;
  font-size: 0.7rem;
}
.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
input,
textarea {
  border: 1px solid rgba(44, 26, 14, 0.12);
  background: var(--cream);
  border-radius: var(--r-md);
  padding: 11px 14px;
  font-family: inherit;
  font-size: 0.92rem;
  color: var(--ink);
  outline: none;
  transition: border-color 0.15s;
  resize: vertical;
}
input:focus,
textarea:focus {
  border-color: var(--terracotta);
}
input:invalid:not(:placeholder-shown) {
  border-color: var(--danger);
}

/* ── Party size ── */
.party {
  display: flex;
  align-items: center;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: 999px;
  padding: 4px;
  gap: 4px;
}
.party-btn {
  width: 40px;
  height: 40px;
  border-radius: 999px;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.12);
  color: var(--ink);
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: 700;
  cursor: pointer;
  display: grid;
  place-items: center;
  line-height: 1;
  transition: background 0.15s;
}
.party-btn:hover {
  background: var(--cream-2);
  color: var(--terracotta-d);
}
.party-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.party-display {
  flex: 1;
  text-align: center;
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 6px;
}
.party-num {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 1.4rem;
  color: var(--ink);
}
.party-word {
  font-size: 0.85rem;
  color: var(--warm-gray);
}
.party-hint {
  font-size: 0.8rem;
  color: var(--warning);
  background: rgba(217, 144, 32, 0.12);
  padding: 8px 12px;
  border-radius: var(--r-md);
  border-left: 3px solid var(--warning);
  margin-top: 4px;
}

/* ── Dates scroller ── */
.dates {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding: 2px 2px 8px;
  scrollbar-width: thin;
}
.date {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: var(--r-md);
  padding: 8px 10px;
  font-family: inherit;
  cursor: pointer;
  min-width: 60px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 2px;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.date:hover {
  border-color: var(--terracotta);
}
.date-dow {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-weight: 700;
  color: var(--warm-gray);
}
.date-day {
  font-family: var(--font-mono);
  font-size: 1.05rem;
  font-weight: 700;
}
.date-month {
  font-size: 0.66rem;
  color: var(--warm-gray);
}
.date.is-active {
  background: var(--forest);
  border-color: var(--forest-d);
  color: var(--bone);
}
.date.is-active .date-dow,
.date.is-active .date-month {
  color: var(--gold-light);
}

/* ── Time slots ── */
.slots {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(80px, 1fr));
  gap: 6px;
}
.slot {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: var(--r-sm);
  font-family: var(--font-mono);
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--ink);
  padding: 10px 4px;
  cursor: pointer;
  position: relative;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.slot:hover:not(:disabled) {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}
.slot.is-recommended::after {
  content: "";
  position: absolute;
  top: 4px;
  right: 4px;
  width: 6px;
  height: 6px;
  background: var(--gold);
  border-radius: 999px;
}
.slot.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.slot:disabled {
  background: var(--cream-2);
  color: var(--warm-gray);
  cursor: not-allowed;
  text-decoration: line-through;
  text-decoration-thickness: 1.5px;
  opacity: 0.7;
}
.slot-hint {
  font-size: 0.72rem;
  color: var(--warm-gray);
  display: flex;
  gap: 12px;
  margin-top: 4px;
}
.dot-rec,
.dot-disabled {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  margin-right: 4px;
  vertical-align: middle;
}
.dot-rec {
  background: var(--gold);
}
.dot-disabled {
  background: rgba(44, 26, 14, 0.2);
}

/* ── Occasions ── */
.occasions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.occ {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: 999px;
  padding: 7px 14px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--ink-2);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.occ:hover {
  border-color: var(--terracotta);
}
.occ.is-active {
  background: var(--terracotta);
  color: var(--bone);
  border-color: var(--terracotta-d);
}

/* ── CTA ── */
.cta {
  margin-top: 4px;
  background: var(--forest);
  color: var(--bone);
  border: none;
  border-radius: 999px;
  padding: 14px 22px;
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  transition: background 0.15s, transform 0.05s;
}
.cta:hover {
  background: var(--forest-d);
}
.cta:active {
  transform: scale(0.99);
}
.cta-meta {
  font-family: var(--font-mono);
  font-weight: 700;
  background: rgba(250, 247, 241, 0.18);
  padding: 5px 12px;
  border-radius: 999px;
  font-size: 0.78rem;
}

/* ── Confirm ── */
.confirm {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding: 4px 0 0;
  animation: pop 0.4s cubic-bezier(0.2, 0.8, 0.2, 1);
}
@keyframes pop {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.mark {
  width: 84px;
  height: 84px;
  border-radius: 999px;
  background: rgba(79, 122, 58, 0.14);
  color: var(--success);
  display: grid;
  place-items: center;
}
.confirm h2 {
  font-family: var(--font-display);
  font-size: 1.6rem;
  font-weight: 700;
}
.confirm-sub {
  font-size: 0.95rem;
  color: var(--ink-2);
  line-height: 1.5;
  max-width: 380px;
}
.confirm-meta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  width: 100%;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 14px 18px;
}
.confirm-meta div {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}
.confirm-meta dt {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  font-weight: 700;
}
.confirm-meta dd {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--ink);
}
.confirm-fineprint {
  font-size: 0.78rem;
  color: var(--warm-gray);
}
.confirm-actions {
  display: flex;
  gap: 10px;
  margin-top: 4px;
}
.ghost,
.primary {
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.86rem;
  font-weight: 700;
  padding: 10px 18px;
  cursor: pointer;
  transition: background 0.15s;
}
.ghost {
  background: transparent;
  border: 1px solid rgba(44, 26, 14, 0.18);
  color: var(--ink-2);
}
.ghost:hover {
  background: var(--cream-2);
  color: var(--ink);
}
.primary {
  background: var(--forest);
  color: var(--bone);
  border: none;
}
.primary:hover {
  background: var(--forest-d);
}

