  border-radius: 30px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

/* ── Header ── */
.qr-head {
  padding: 46px 20px 14px;
  background: var(--bone);
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  flex-shrink: 0;
}
.qr-kicker {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--terracotta);
  font-weight: 600;
  margin-bottom: 4px;
}
.qr-head h1 {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.qr-glyph {
  font-size: 1.4rem;
  color: var(--gold);
}

/* ── Tabs (sticky) ── */
.qr-tabs {
  position: sticky;
  top: 0;
  z-index: 10;
  background: var(--bone);
  display: flex;
  gap: 4px;
  padding: 10px 18px 10px 12px;
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
  overflow-x: auto;
  scroll-padding-right: 18px;
  scrollbar-width: none;
  flex-shrink: 0;
}
.qr-tabs::-webkit-scrollbar {
  display: none;
}
.qr-tab {
  flex: 0 0 auto;
  background: transparent;
  border: 1px solid transparent;
  color: var(--ink-2);
  font-family: inherit;
  font-size: 0.8rem;
  font-weight: 600;
  padding: 7px 14px;
  border-radius: 999px;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s, color 0.15s;
}
.qr-tab:hover {
  background: var(--cream-2);
}
.qr-tab.is-active {
  background: var(--forest);
  color: var(--bone);
}

/* ── Scrollable list ── */
.qr-list {
  flex: 1;
  overflow-y: auto;
  padding: 8px 16px 96px;
}
.qr-section {
  margin-top: 18px;
  scroll-margin-top: 60px;
}
.qr-section:first-child {
  margin-top: 8px;
}
.qr-section-title {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
  margin: 12px 0 8px;
}

.dish {
  display: grid;
  grid-template-columns: 1fr 36px;
  gap: 12px;
  padding: 14px 4px;
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
  align-items: start;
}
.dish:last-child {
  border-bottom: none;
}
.dish-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 4px;
}
.dish-name {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.005em;
}
.dish-price {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.85rem;
  color: var(--terracotta-d);
  white-space: nowrap;
}
.dish-desc {
  font-size: 0.78rem;
  color: var(--ink-2);
  line-height: 1.45;
}
.dish-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}
.chip {
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 999px;
  background: var(--cream-2);
  color: var(--ink-2);
}
.chip[data-tone="veg"] {
  background: rgba(79, 122, 58, 0.16);
  color: var(--success);
}
.chip[data-tone="gf"] {
  background: rgba(201, 168, 76, 0.2);
  color: #8a7325;
}
.chip[data-tone="hot"] {
  background: rgba(179, 67, 42, 0.16);
  color: var(--danger);
}
.add-btn {
  align-self: center;
  width: 36px;
  height: 36px;
  border-radius: 999px;
  border: 1.5px solid var(--forest);
  background: transparent;
  color: var(--forest);
  font-family: inherit;
  font-size: 1.3rem;
  font-weight: 700;
  cursor: pointer;
  display: grid;
  place-items: center;
  line-height: 1;
  transition: background 0.15s, color 0.15s, transform 0.1s;
}
.add-btn:hover {
  background: var(--forest);
  color: var(--bone);
}
.add-btn:active {
  transform: scale(0.92);
}
.add-btn.is-flash {
  background: var(--gold);
  border-color: var(--gold);
  color: var(--ink);
  animation: addFlash 0.45s ease;
}
@keyframes addFlash {
  0% {
    transform: scale(1.1);
  }
  100% {
    transform: scale(1);
  }
}

/* ── Cart pill ── */
.cart-pill {
  position: absolute;
  bottom: 18px;
  left: 16px;
  right: 16px;
  background: var(--forest);
  color: var(--bone);
  border: none;
  border-radius: 999px;
  padding: 13px 18px;
  display: grid;
  grid-template-columns: 28px 1fr auto;
  align-items: center;
  gap: 12px;
  font-family: inherit;
  font-size: 0.92rem;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 12px 30px rgba(44, 26, 14, 0.32);
  z-index: 12;
  animation: pillIn 0.25s ease;
}
@keyframes pillIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.cart-pill-count {
  background: var(--gold);
  color: var(--ink);
  width: 28px;
  height: 28px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-family: var(--font-mono);
  font-size: 0.86rem;
  font-weight: 700;
}
.cart-pill-label {
  text-align: left;
}
.cart-pill-total {
  font-family: var(--font-mono);
  background: rgba(250, 247, 241, 0.16);
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 0.82rem;
}

/* ── Sheet ── */
.sheet-overlay {
  position: absolute;
  inset: 0;
  background: rgba(44, 26, 14, 0.45);
  z-index: 14;
  animation: fadeIn 0.2s ease;
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.sheet {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bone);
  border-radius: 24px 24px 0 0;
  z-index: 15;
  padding: 8px 18px 28px;
  max-height: min(80%, calc(100% - 160px));
  display: flex;
  flex-direction: column;
  animation: sheetIn 0.28s cubic-bezier(0.2, 0.8, 0.2, 1);
  box-shadow: 0 -16px 40px rgba(44, 26, 14, 0.18);
}
@keyframes sheetIn {
  from {
    transform: translateY(100%);
  }
  to {
    transform: translateY(0);
  }
}
.sheet-grip {
  width: 36px;
  height: 4px;
  background: rgba(44, 26, 14, 0.2);
  border-radius: 999px;
  margin: 0 auto 8px;
}
.sheet-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}
.sheet-head h2 {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 700;
}
.sheet-x {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.1);
  border-radius: 999px;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  color: var(--ink-2);
  cursor: pointer;
}
.sheet-lines {
  list-style: none;
  flex: 1;
  overflow-y: auto;
  padding-bottom: 6px;
}
.sheet-line {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(44, 26, 14, 0.06);
}
.sheet-line-name {
  font-size: 0.88rem;
  font-weight: 600;
}
.sheet-line-meta {
  font-size: 0.7rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.sheet-line-qty {
  display: inline-flex;
  align-items: center;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.1);
  border-radius: 999px;
  padding: 2px;
  gap: 2px;
}
.sheet-line-qty button {
  width: 22px;
  height: 22px;
  border-radius: 999px;
  border: none;
  background: transparent;
  color: var(--ink-2);
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 700;
  cursor: pointer;
  display: grid;
  place-items: center;
}
.sheet-line-qty button:hover {
  background: var(--cream-2);
}
.sheet-line-qty span {
  min-width: 18px;
  text-align: center;
  font-weight: 700;
  font-size: 0.78rem;
}
.sheet-line-price {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.86rem;
  min-width: 56px;
  text-align: right;
}
.sheet-totals {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px 0 8px;
  border-top: 1px dashed rgba(44, 26, 14, 0.18);
  margin-top: 8px;
}
.sheet-totals div {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  color: var(--ink-2);
}
.sheet-totals dd {
  font-family: var(--font-mono);
  font-weight: 600;
}
.sheet-totals .big {
  margin-top: 4px;
  padding-top: 8px;
  border-top: 1px solid rgba(44, 26, 14, 0.16);
  font-size: 1rem;
  font-weight: 700;
  color: var(--ink);
}
.sheet-totals .big dd {
  font-size: 1.15rem;
}
.sheet-cta {
  margin-top: 12px;
  background: var(--forest);
  color: var(--bone);
  border: none;
  border-radius: 999px;
  padding: 13px;
  font-family: inherit;
  font-size: 0.94rem;
  font-weight: 700;
  cursor: pointer;
}
.sheet-cta:hover {
  background: var(--forest-d);
}

