        name: "Pollo carbón",
        desc: "Half free-range chicken, garlic confit.",
        price: 28,
        chips: [{ label: "GF", tone: "gf" }],
      },
      {
        id: "pappardelle",
        name: "Pappardelle ragú",
        desc: "Hand-cut pasta, slow lamb shoulder.",
