:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(44, 26, 14, 0.08), 0 2px 6px rgba(44, 26, 14, 0.06);
  --shadow-2: 0 8px 24px rgba(44, 26, 14, 0.12);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: linear-gradient(180deg, var(--cream) 0%, var(--cream-2) 100%);
  color: var(--ink);
  min-height: 100vh;
  padding: 32px 16px 48px;
  display: flex;
  justify-content: center;
  -webkit-font-smoothing: antialiased;
}

.pay {
  width: 100%;
  max-width: 520px;
  background: var(--bone);
  border-radius: var(--r-lg);
  border: 1px solid rgba(44, 26, 14, 0.1);
  box-shadow: var(--shadow-2);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* ── Head ── */
.pay-head {
  padding: 18px 22px;
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--terracotta);
  font-weight: 600;
  margin-bottom: 2px;
}
.pay-head h1 {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.x {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.1);
  color: var(--ink-2);
  border-radius: 999px;
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.x:hover {
  background: var(--cream-2);
}

/* ── Body ── */
.pay-body {
  padding: 16px 22px 8px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* ── Bill summary ── */
.bill {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.bill div {
  display: flex;
  justify-content: space-between;
  font-size: 0.86rem;
  color: var(--ink-2);
}
.bill dd {
  font-family: var(--font-mono);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.bill-total {
  margin-top: 6px;
  padding-top: 10px;
  border-top: 1px solid rgba(44, 26, 14, 0.16);
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--ink);
}
.bill-total dd {
  font-size: 1.2rem;
}
.tip-tag {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  background: var(--cream-2);
  color: var(--ink-2);
  padding: 2px 7px;
  border-radius: 999px;
  margin-left: 4px;
  font-weight: 700;
}

/* ── Tip presets ── */
.tip-presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.tip-btn {
  flex: 1;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  color: var(--ink-2);
  border-radius: 999px;
  padding: 9px 10px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.tip-btn:hover {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}
.tip-btn.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}

/* ── Methods ── */
.methods {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.m-btn {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  color: var(--ink-2);
  border-radius: var(--r-md);
  padding: 14px 8px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.m-btn .m-icon {
  font-size: 1.3rem;
}
.m-btn:hover {
  border-color: var(--terracotta);
}
.m-btn.is-active {
  background: var(--gold);
  color: var(--ink);
  border-color: var(--gold);
}

/* ── Panels ── */
.panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* Cash */
.cash-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
.cash-field {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.1);
  border-radius: var(--r-md);
  padding: 10px 14px;
}
.cash-field label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  font-weight: 700;
  display: block;
  margin-bottom: 4px;
}
.amount {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 1.5rem;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.amount-change.is-positive {
  color: var(--success);
}
.amount-change.is-short {
  color: var(--danger);
}
.cash-change {
  background: var(--bone);
}

.quick {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
}
.q-btn {
  background: var(--cream-2);
  border: 1px solid rgba(44, 26, 14, 0.1);
  border-radius: var(--r-sm);
  padding: 8px 4px;
  font-family: inherit;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--ink-2);
  cursor: pointer;
}
.q-btn:hover {
  background: var(--gold);
  color: var(--ink);
}

.keypad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}
.keypad button {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: var(--r-md);
  padding: 14px 0;
  font-family: var(--font-mono);
  font-size: 1.05rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
}
.keypad button:hover {
  background: var(--cream-2);
}
.keypad button:active {
  transform: scale(0.95);
}
.keypad .del {
  color: var(--danger);
}

/* Card */
.card-prompt {
  text-align: center;
  padding: 18px 12px 12px;
  background: var(--forest);
  color: var(--bone);
  border-radius: var(--r-md);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}
.card-reader {
  width: 120px;
  height: 78px;
  background: linear-gradient(180deg, #34564a 0%, #1e3329 100%);
  border-radius: 8px;
  position: relative;
  border: 1px solid rgba(250, 247, 241, 0.18);
  box-shadow: inset 0 1px 0 rgba(250, 247, 241, 0.1);
  overflow: hidden;
}
.card-reader::before {
  content: "";
  position: absolute;
  left: 12%;
  right: 12%;
  top: 22%;
  height: 22%;
  background: rgba(201, 168, 76, 0.85);
  border-radius: 2px;
}
.card-reader::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -2px;
  height: 4px;
  background: var(--gold);
  animation: scan 1.4s ease-in-out infinite;
}
@keyframes scan {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-78px);
  }
}
.card-status {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--gold-light);
  letter-spacing: 0.04em;
}
.card-amount {
  font-family: var(--font-mono);
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.card-prompt.is-paid {
  background: var(--success);
}
.card-prompt.is-paid .card-status {
  color: var(--bone);
}

/* Split */
.split-config {
  display: flex;
  align-items: center;
  gap: 12px;
}
.split-config label {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--ink-2);
}
.split-ways {
  display: flex;
  gap: 4px;
  background: var(--cream-2);
  padding: 3px;
  border-radius: 999px;
  margin-left: auto;
}
.split-ways button {
  background: transparent;
  border: none;
  color: var(--ink-2);
  font-family: var(--font-mono);
  font-size: 0.86rem;
  font-weight: 700;
  width: 30px;
  height: 30px;
  border-radius: 999px;
  cursor: pointer;
}
.split-ways button.is-active {
  background: var(--forest);
  color: var(--bone);
}
.split-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 220px;
  overflow-y: auto;
}
.split-row {
  display: grid;
  grid-template-columns: 24px 1fr auto auto;
  align-items: center;
  gap: 10px;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 10px 12px;
}
.split-row.is-paid {
  background: rgba(79, 122, 58, 0.08);
  border-color: rgba(79, 122, 58, 0.3);
}
.split-num {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--warm-gray);
}
.split-name {
  background: transparent;
  border: none;
  font-family: inherit;
  font-size: 0.88rem;
  color: var(--ink);
  outline: none;
}
.split-amount {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--ink);
}
.split-paid {
  background: var(--cream-2);
  border: 1px solid rgba(44, 26, 14, 0.1);
  border-radius: 999px;
  padding: 4px 10px;
  font-family: inherit;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--ink-2);
  cursor: pointer;
}
.split-row.is-paid .split-paid {
  background: var(--success);
  color: var(--bone);
  border-color: var(--success);
}

/* ── Foot ── */
.pay-foot {
  padding: 14px 22px 20px;
  border-top: 1px solid rgba(44, 26, 14, 0.08);
  display: flex;
  gap: 10px;
  background: var(--cream);
}
.ghost,
.primary {
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 700;
  padding: 12px 18px;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
}
.ghost {
  background: transparent;
  border: 1px solid rgba(44, 26, 14, 0.18);
  color: var(--ink-2);
}
.ghost:hover {
  background: var(--cream-2);
  color: var(--ink);
}
.primary {
  flex: 1;
  background: var(--forest);
  color: var(--bone);
  border: none;
}
.primary:hover:not(:disabled) {
  background: var(--forest-d);
}
.primary:active:not(:disabled) {
  transform: scale(0.99);
}
.primary:disabled {
  background: var(--warm-gray);
  cursor: not-allowed;
  opacity: 0.7;
}

@media (max-width: 480px) {
  .quick {
    grid-template-columns: repeat(3, 1fr);
  }
}

