const SUBTOTAL = 184.0;
const TAX_RATE = 0.0825;
const SERVICE_RATE = 0.1;

let tipMode = "18";
let customTip = 22;
let method = "cash";
let tendered = 0;
let tenderedRaw = ""; // string accumulator for the keypad
let ways = 2;
let splitPaid = new Set();

const subtotalEl = document.getElementById("subtotal");
const taxEl = document.getElementById("tax");
const serviceEl = document.getElementById("service");
const tipEl = document.getElementById("tip");
const totalEl = document.getElementById("total");
const tipTagEl = document.getElementById("tipTag");
const amountEl = document.getElementById("amount");
const changeEl = document.getElementById("change");
const cardAmount = document.getElementById("cardAmount");
const cardStatus = document.getElementById("cardStatus");
const cardPrompt = document.getElementById("cardPrompt");
const confirmLabel = document.getElementById("confirmLabel");
const confirmBtn = document.getElementById("confirm");
const splitList = document.getElementById("splitList");

function money(v) {
  return `$${v.toFixed(2)}`;
}

function tipPercent() {
  if (tipMode === "custom") return Math.max(0, Math.min(100, customTip)) / 100;
  return Number(tipMode) / 100;
}

function total() {
  return SUBTOTAL + SUBTOTAL * TAX_RATE + SUBTOTAL * SERVICE_RATE + SUBTOTAL * tipPercent();
}

function tenderedNum() {
  if (tenderedRaw === "") return 0;
  return Number(tenderedRaw) / 100;
}

function renderBill() {
  const tax = SUBTOTAL * TAX_RATE;
  const service = SUBTOTAL * SERVICE_RATE;
  const tip = SUBTOTAL * tipPercent();
  subtotalEl.textContent = money(SUBTOTAL);
  taxEl.textContent = money(tax);
  serviceEl.textContent = money(service);
  tipEl.textContent = money(tip);
  totalEl.textContent = money(total());
  tipTagEl.textContent = `${Math.round(tipPercent() * 100)}%`;
  cardAmount.textContent = money(total());
}

function renderTendered() {
  const t = tenderedNum();
  amountEl.textContent = money(t);
  const change = t - total();
  if (t === 0) {
    changeEl.textContent = "$0.00";
    changeEl.className = "amount amount-change";
  } else if (change >= 0) {
    changeEl.textContent = money(change);
    changeEl.className = "amount amount-change is-positive";
  } else {
    changeEl.textContent = `-${money(Math.abs(change))}`;
    changeEl.className = "amount amount-change is-short";
  }
}

function renderConfirm() {
  if (method === "cash") {
    confirmLabel.textContent =
      tenderedNum() >= total() ? `Confirm · ${money(total())}` : "Tender first";
    confirmBtn.disabled = tenderedNum() < total();
  } else if (method === "card") {
    confirmLabel.textContent = cardPrompt.classList.contains("is-paid")
      ? "Done"
      : `Charge ${money(total())}`;
    confirmBtn.disabled = false;
  } else {
    const allPaid = splitPaid.size === ways;
    confirmLabel.textContent = allPaid
      ? "Close ticket"
      : `Split ${ways} ways · ${money(total() / ways)}/each`;
    confirmBtn.disabled = false;
  }
}

function renderSplit() {
  splitList.innerHTML = Array.from({ length: ways }, (_, i) => i)
    .map(
      (i) => `
    <li class="split-row ${splitPaid.has(i) ? "is-paid" : ""}" data-split="${i}">
      <span class="split-num">#${i + 1}</span>
      <input class="split-name" placeholder="Guest name" value="${i === 0 ? "Lina" : ""}" />
      <span class="split-amount">${money(total() / ways)}</span>
      <button class="split-paid" data-paid="${i}">${splitPaid.has(i) ? "Paid ✓" : "Mark paid"}</button>
    </li>`
    )
    .join("");
}

function setMethod(next) {
  method = next;
  document
    .querySelectorAll("[data-method]")
    .forEach((b) => b.classList.toggle("is-active", b.dataset.method === next));
  document.querySelectorAll(".panel").forEach((p) => (p.hidden = p.dataset.panel !== next));
  if (next === "card") {
    cardPrompt.classList.remove("is-paid");
    cardStatus.textContent = "Insert or tap card on reader";
  }
  renderConfirm();
  if (next === "split") renderSplit();
}

document.querySelectorAll("[data-tip]").forEach((btn) =>
  btn.addEventListener("click", () => {
    document.querySelectorAll("[data-tip]").forEach((b) => b.classList.remove("is-active"));
    btn.classList.add("is-active");
    if (btn.dataset.tip === "custom") {
      const val = prompt("Custom tip %", String(customTip));
      const n = Number(val);
      if (!Number.isNaN(n)) {
        customTip = Math.max(0, Math.min(100, n));
        tipMode = "custom";
      }
    } else {
      tipMode = btn.dataset.tip;
    }
    renderBill();
    if (method === "split") renderSplit();
    renderConfirm();
  })
);

document
  .querySelectorAll("[data-method]")
  .forEach((b) => b.addEventListener("click", () => setMethod(b.dataset.method)));

const keypad = document.getElementById("keypad");
keypad.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-key]");
  if (!btn) return;
  const key = btn.dataset.key;
  if (key === "del") tenderedRaw = tenderedRaw.slice(0, -1);
  else tenderedRaw = (tenderedRaw + key).slice(0, 8);
  renderTendered();
  renderConfirm();
});

document.querySelectorAll("[data-quick]").forEach((b) =>
  b.addEventListener("click", () => {
    const q = b.dataset.quick;
    const t = total();
    let next;
    if (q === "exact") next = t;
    else if (q === "next-50") next = Math.ceil(t / 50) * 50;
    else next = Number(q);
    tenderedRaw = String(Math.round(next * 100));
    renderTendered();
    renderConfirm();
  })
);

document.querySelectorAll("[data-ways]").forEach((b) =>
  b.addEventListener("click", () => {
    document.querySelectorAll("[data-ways]").forEach((x) => x.classList.remove("is-active"));
    b.classList.add("is-active");
    ways = Number(b.dataset.ways);
    splitPaid = new Set();
    renderSplit();
    renderConfirm();
  })
);

splitList.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-paid]");
  if (!btn) return;
  const i = Number(btn.dataset.paid);
  if (splitPaid.has(i)) splitPaid.delete(i);
  else splitPaid.add(i);
  renderSplit();
  renderConfirm();
});

confirmBtn.addEventListener("click", () => {
  if (method === "card") {
    cardStatus.textContent = "Approved · receipt printing";
    cardPrompt.classList.add("is-paid");
    renderConfirm();
  } else if (method === "cash") {
    cardStatus.textContent = "Drawer opened";
    confirmLabel.textContent = "Closed ✓";
    confirmBtn.disabled = true;
  } else if (method === "split" && splitPaid.size === ways) {
    confirmLabel.textContent = "Closed ✓";
    confirmBtn.disabled = true;
  }
});

renderBill();
renderTendered();
renderConfirm();

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

.page {
  max-width: 760px;
  margin: 0 auto;
  padding: 36px 24px 64px;
}
.hidden-h {
  position: absolute;
  left: -9999px;
}

.head {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 24px;
  align-items: center;
  padding-bottom: 24px;
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
}
.kicker {
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
  margin-bottom: 6px;
}
.head h1 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 2rem;
  letter-spacing: -0.015em;
}
.agg {
  text-align: right;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}
.agg-score {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 3rem;
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--ink);
}
.agg-stars {
  font-family: var(--font-display);
  font-size: 1.4rem;
  color: var(--gold);
  letter-spacing: 0.04em;
}
.agg-count {
  font-size: 0.82rem;
  color: var(--warm-gray);
  font-weight: 600;
}

/* Distribution */
.distro {
  margin: 22px 0 18px;
}
.distro ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.d-row {
  display: grid;
  grid-template-columns: 60px 1fr 56px;
  align-items: center;
  gap: 12px;
}
.d-star {
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--ink-2);
  font-family: var(--font-mono);
}
.d-bar {
  height: 8px;
  background: var(--cream-2);
  border-radius: 999px;
  overflow: hidden;
}
.d-fill {
  height: 100%;
  background: var(--gold);
  border-radius: 999px;
  transition: width 0.4s ease;
}
.d-row[data-s="4"] .d-fill {
  background: var(--gold-light);
}
.d-row[data-s="3"] .d-fill {
  background: var(--cream-2);
}
.d-row[data-s="2"] .d-fill,
.d-row[data-s="1"] .d-fill {
  background: var(--warm-gray);
}
.d-pct {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  color: var(--warm-gray);
  text-align: right;
  font-weight: 600;
}

/* Chips */
.chips {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}
.chip {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.1);
  color: var(--ink-2);
  padding: 7px 14px;
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  gap: 6px;
}
.chip span {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  background: var(--cream-2);
  padding: 2px 7px;
  border-radius: 999px;
  color: var(--warm-gray);
  font-weight: 700;
}
.chip:hover {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}
.chip.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.chip.is-active span {
  background: rgba(250, 247, 241, 0.18);
  color: var(--gold-light);
}

/* Reviews */
.reviews {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.review {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 14px;
  padding: 18px 20px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: opacity 0.18s, transform 0.18s;
}
.review.is-hidden {
  display: none !important;
}
.r-head {
  display: flex;
  align-items: center;
  gap: 12px;
}
.r-avatar {
  width: 44px;
  height: 44px;
  border-radius: 999px;
  background: var(--cream-2);
  color: var(--ink);
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1rem;
}
.r-name {
  font-weight: 700;
}
.r-meta {
  font-size: 0.76rem;
  color: var(--warm-gray);
}
.r-stars {
  margin-left: auto;
  font-family: var(--font-display);
  color: var(--gold);
  font-size: 1.1rem;
  letter-spacing: 0.04em;
}
.r-stars .dim {
  color: rgba(44, 26, 14, 0.18);
}

.r-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}
.r-tag {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: var(--cream-2);
  color: var(--ink-2);
  padding: 3px 9px;
  border-radius: 999px;
}
.r-tag[data-tone="dish"] {
  background: rgba(193, 113, 74, 0.15);
  color: var(--terracotta-d);
}
