  { s: 3, pct: 5 },
  { s: 2, pct: 2 },
  { s: 1, pct: 1 },
];

const REVIEWS = [
  {
    id: 1,
    name: "Maite H.",
    date: "2 days ago",
    rating: 5,
    tags: [
      { label: "Ribeye 14oz", tone: "dish" },
      { label: "Cosy vibe", tone: "vibe" },
    ],
    body: "Best ribeye I've had in Madrid. The dry-age comes through, and the bone marrow butter is dangerous. Marco the server was attentive without hovering — the kind of place you go for a quiet anniversary.",
    helpful: 18,
    photos: 2,
    reply: "Maite — thank you for the kind words, see you both again next year. ✦ Aitor",
    recent: true,
  },
  {
    id: 2,
    name: "Park S.",
    date: "1 week ago",
    rating: 5,
    tags: [
      { label: "Pulpo brasa", tone: "dish" },
      { label: "Service", tone: "vibe" },
    ],
    body: "Pulpo was perfectly charred and the salsa verde was bright — paired with Sasha's natural-wine recommendation it was the best meal of our trip.",
    helpful: 9,
    photos: 1,
    reply: null,
    recent: true,
  },
  {
    id: 3,
    name: "Davies L.",
    date: "2 weeks ago",
    rating: 4,
    tags: [{ label: "Pappardelle ragú", tone: "dish" }],
    body: "Loved everything except the wait between courses (close to 25 min before mains). Pappardelle ragú was excellent — the lamb is slow-cooked long enough to fall apart but still has texture.",
    helpful: 4,
    photos: 0,
    reply:
      "Thanks for the feedback Davies — we tightened up second-course timing this weekend after several similar notes. Hope you'll give us another try. — Iria",
    recent: false,
  },
  {
    id: 4,
    name: "Khoury R.",
    date: "3 weeks ago",
    rating: 5,
    tags: [
      { label: "Tarta de queso", tone: "dish" },
      { label: "Birthday", tone: "vibe" },
    ],
    body: "They surprised my partner with a candle in the burnt cheesecake without us asking — small thing that meant a lot. Cake itself is a top-3 burnt cheesecake in Madrid.",
    helpful: 12,
    photos: 1,
    reply: null,
    recent: false,
  },
  {
    id: 5,
    name: "Iyengar V.",
    date: "1 month ago",
    rating: 5,
    tags: [
      { label: "Risotto hongos", tone: "dish" },
      { label: "Veg", tone: "vibe" },
    ],
    body: "As a vegetarian I'm used to getting the leftover salad. Here the risotto was the dish of the night. The kitchen treats vegetables like the main event.",
    helpful: 21,
    photos: 0,
    reply: null,
    recent: false,
  },
  {
    id: 6,
    name: "Tanaka M.",
    date: "5 weeks ago",
    rating: 3,
    tags: [{ label: "Loud at peak", tone: "vibe" }],
    body: "Food is great, but the room gets loud at 21:00 — you basically have to shout. If you're going for a quiet date, try the 19:00 seating instead.",
    helpful: 6,
    photos: 0,
    reply:
      "Thanks Tanaka — we're working on acoustic panels in the centre section, expect by August. — Iria",
    recent: false,
  },
];

const distroEl = document.getElementById("distro");
const reviewsEl = document.getElementById("reviews");
const chips = document.getElementById("chips");
const moreBtn = document.getElementById("more");

distroEl.innerHTML = DISTRO.map(
  (d) => `<li class="d-row" data-s="${d.s}">
    <span class="d-star">${d.s} ★</span>
    <span class="d-bar"><span class="d-fill" style="width:${d.pct}%"></span></span>
    <span class="d-pct">${d.pct}%</span>
  </li>`
).join("");

function stars(n) {
  return Array.from({ length: 5 }, (_, i) =>
    i < n ? `<span>★</span>` : `<span class="dim">★</span>`
  ).join("");
}

function photos(n) {
  if (!n) return "";
  return `<div class="r-photos">${Array.from({ length: n }, (_, i) => `<span class="r-photo p-${(i % 4) + 1}"></span>`).join("")}</div>`;
}

function render() {
  reviewsEl.innerHTML = REVIEWS.map(
    (
      r
    ) => `<li class="review" data-id="${r.id}" data-recent="${r.recent}" data-rating="${r.rating}" data-photos="${r.photos > 0}">
      <div class="r-head">
        <span class="r-avatar">${r.name[0]}</span>
        <div>
          <p class="r-name">${r.name}</p>
          <p class="r-meta">${r.date} · verified diner</p>
        </div>
        <p class="r-stars" aria-label="${r.rating} of 5 stars">${stars(r.rating)}</p>
      </div>
      ${
        r.tags.length
          ? `<div class="r-tags">${r.tags.map((t) => `<span class="r-tag" data-tone="${t.tone}">${t.label}</span>`).join("")}</div>`
          : ""
      }
      <p class="r-body">${r.body}</p>
      ${photos(r.photos)}
      <div class="r-foot">
        <button class="helpful" type="button" data-action="helpful" data-id="${r.id}">👍 Helpful · <b>${r.helpful}</b></button>
        <button class="report" type="button">Report</button>
      </div>
      ${
        r.reply
          ? `<div class="r-reply">
              <p class="r-reply-head">Casa Olivar · owner reply</p>
              <p class="r-reply-body">${r.reply}</p>
            </div>`
          : ""
      }
    </li>`
  ).join("");
}

function filter(kind) {
  reviewsEl.querySelectorAll(".review").forEach((el) => {
    let show = true;
    if (kind === "recent") show = el.dataset.recent === "true";
    if (kind === "5") show = el.dataset.rating === "5";
    if (kind === "photos") show = el.dataset.photos === "true";
    el.classList.toggle("is-hidden", !show);
  });
}

chips.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-filter]");
  if (!btn) return;
  chips.querySelectorAll(".chip").forEach((c) => c.classList.toggle("is-active", c === btn));
  filter(btn.dataset.filter);
});

reviewsEl.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action='helpful']");
  if (!btn) return;
  const r = REVIEWS.find((x) => x.id === Number(btn.dataset.id));
  if (!r) return;
  btn.classList.toggle("is-on");
  r.helpful += btn.classList.contains("is-on") ? 1 : -1;
  btn.querySelector("b").textContent = r.helpful;
});

moreBtn.addEventListener("click", () => {
  moreBtn.textContent = "All loaded · 824 reviews in total";
  moreBtn.disabled = true;
});

render();

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(44, 26, 14, 0.08), 0 2px 6px rgba(44, 26, 14, 0.06);
  --shadow-2: 0 8px 24px rgba(44, 26, 14, 0.12);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

.page {
  max-width: 1080px;
  margin: 0 auto;
  padding: 32px 24px 64px;
}
.page-head {
  text-align: center;
  margin-bottom: 28px;
}
.kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--terracotta);
  font-weight: 600;
  margin-bottom: 6px;
}
.page-head h1 {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 4vw, 2.4rem);
  font-weight: 700;
  letter-spacing: -0.015em;
  margin-bottom: 22px;
}
.steps {
  display: inline-flex;
  gap: 8px;
  list-style: none;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  padding: 6px;
  border-radius: 999px;
}
.step {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px 6px 8px;
  border-radius: 999px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--warm-gray);
}
.step span {
  width: 22px;
  height: 22px;
  border-radius: 999px;
  background: var(--cream-2);
  color: var(--ink-2);
  display: grid;
  place-items: center;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
}
.step.is-active {
  background: var(--forest);
  color: var(--bone);
}
.step.is-active span {
  background: var(--gold);
  color: var(--ink);
}
.step.is-done span {
  background: var(--success);
  color: var(--bone);
}

/* ── Layout ── */
.layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 24px;
  align-items: start;
}
@media (max-width: 840px) {
  .layout {
    grid-template-columns: 1fr;
  }
}

.card {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-lg);
  padding: 28px;
  box-shadow: var(--shadow-1);
}
.panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.panel h2 {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.panel h2.h2-sub {
  margin-top: 8px;
}

/* ── Choices ── */
.choices {
  display: grid;
  gap: 10px;
}
.choice {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: var(--r-md);
  background: var(--cream);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}
.choice:hover {
  border-color: var(--terracotta);
}
.choice input {
  accent-color: var(--forest);
  width: 18px;
  height: 18px;
}
.choice:has(input:checked) {
  border-color: var(--forest);
  background: rgba(45, 74, 62, 0.06);
}
.choice-name {
  font-weight: 700;
  font-size: 0.95rem;
}
.choice-desc {
  font-size: 0.8rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.choice-tag {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--ink-2);
  background: var(--cream-2);
  padding: 4px 10px;
  border-radius: 999px;
}

/* ── Fields ── */
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.field label,
.field-label {
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--ink-2);
  font-weight: 700;
}
.field input,
.field textarea,
textarea {
  border: 1px solid rgba(44, 26, 14, 0.12);
  background: var(--cream);
  border-radius: var(--r-md);
  padding: 11px 14px;
  font-family: inherit;
  font-size: 0.92rem;
  color: var(--ink);
  outline: none;
  transition: border-color 0.15s;
  resize: vertical;
}
.field input:focus,
.field textarea:focus,
textarea:focus {
  border-color: var(--terracotta);
}
.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

/* ── Slots ── */
.slots {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(86px, 1fr));
  gap: 6px;
}
.slot {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: var(--r-sm);
  font-family: var(--font-mono);
  font-size: 0.84rem;
  font-weight: 600;
  color: var(--ink);
  padding: 10px 4px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.slot:hover:not(:disabled) {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}
.slot.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.slot:disabled {
  background: var(--cream-2);
  color: var(--warm-gray);
  cursor: not-allowed;
  text-decoration: line-through;
  text-decoration-thickness: 1.5px;
  opacity: 0.7;
}

/* ── Methods ── */
.methods {
  display: grid;
  gap: 8px;
}
.m-choice {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: var(--r-md);
  background: var(--cream);
  cursor: pointer;
}
.m-choice input {
  accent-color: var(--forest);
  width: 16px;
  height: 16px;
}
.m-icon {
  font-size: 1.15rem;
  width: 22px;
  text-align: center;
}
.m-name {
  font-weight: 600;
  font-size: 0.9rem;
}
.m-choice:has(input:checked) {
  border-color: var(--forest);
  background: rgba(45, 74, 62, 0.06);
}

/* ── Tips ── */
.tips {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}
.tip-btn {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: 999px;
  padding: 10px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 700;
  color: var(--ink-2);
  cursor: pointer;
}
.tip-btn:hover {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}
.tip-btn.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}

/* ── Panel foot ── */
.panel-foot {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 8px;
}
.panel-foot.center {
  justify-content: center;
}
.ghost,
.primary {
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 700;
  padding: 12px 22px;
  cursor: pointer;
  transition: background 0.15s;
}
.ghost {
  background: transparent;
  border: 1px solid rgba(44, 26, 14, 0.18);
  color: var(--ink-2);
}
.ghost:hover:not(:disabled) {
  background: var(--cream-2);
  color: var(--ink);
}
.ghost:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.primary {
  background: var(--forest);
  color: var(--bone);
  border: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.primary:hover {
  background: var(--forest-d);
}

/* ── Success ── */
.panel-success {
  align-items: center;
  text-align: center;
  padding: 8px 0;
}
.success-mark {
  width: 72px;
  height: 72px;
  border-radius: 999px;
  background: rgba(79, 122, 58, 0.15);
  color: var(--success);
  display: grid;
  place-items: center;
  margin: 8px auto 4px;
  animation: pop 0.4s cubic-bezier(0.2, 0.8, 0.2, 1);
}
@keyframes pop {
  from {
    transform: scale(0.4);
    opacity: 0;
  }
  to {
    transform: scale(1);
    opacity: 1;
  }
}
.success-desc {
  font-size: 0.95rem;
  color: var(--ink-2);
  max-width: 420px;
  line-height: 1.55;
}
.success-meta {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px 18px;
  width: 100%;
  margin: 18px 0 6px;
  padding: 16px 18px;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
}
.success-meta div {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}
.success-meta dt {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--warm-gray);
  font-weight: 700;
}
.success-meta dd {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--ink);
}

/* ── Sidebar summary ── */
.summary {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-lg);
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: sticky;
  top: 16px;
  box-shadow: var(--shadow-1);
}
.summary header h3 {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.summary-meta {
  font-size: 0.78rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.summary-lines {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.summary-lines li {
  display: flex;
  justify-content: space-between;
  font-size: 0.86rem;
  color: var(--ink-2);
}
.summary-lines .m {
  font-family: var(--font-mono);
  font-weight: 600;
}
.summary-lines li.sub {
  display: block;
  padding-left: 16px;
  font-size: 0.74rem;
  font-style: italic;
  color: var(--warm-gray);
  margin-top: -2px;
}
.summary-totals {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-top: 12px;
  border-top: 1px dashed rgba(44, 26, 14, 0.18);
}
.summary-totals div {
  display: flex;
  justify-content: space-between;
  font-size: 0.86rem;
  color: var(--ink-2);
}
.summary-totals dd {
  font-family: var(--font-mono);
  font-weight: 600;
}
.summary-totals .big {
  margin-top: 6px;
  padding-top: 10px;
  border-top: 1px solid rgba(44, 26, 14, 0.16);
  font-size: 1rem;
  color: var(--ink);
  font-weight: 700;
}
.summary-totals .big dd {
  font-size: 1.2rem;
}
.tip-tag {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  background: var(--cream-2);
  color: var(--ink-2);
  padding: 2px 7px;
  border-radius: 999px;
  margin-left: 4px;
  font-weight: 700;
}

