}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
}

/* Nav */
.nav {
  padding: 18px 28px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
  background: var(--bone);
}
.nav-brand {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--ink);
  text-decoration: none;
}
.nav-back {
  font-size: 0.84rem;
  color: var(--ink-2);
  text-decoration: none;
  font-weight: 600;
}
.nav-back:hover {
  color: var(--terracotta-d);
}

/* Intro pull-quote */
.intro {
  max-width: 920px;
  margin: 0 auto;
  padding: 84px 28px 56px;
  text-align: center;
}
.kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--terracotta);
  font-weight: 600;
  margin-bottom: 12px;
}
.intro h1 {
  font-family: var(--font-display);
  font-size: clamp(2.2rem, 5.5vw, 3.6rem);
  font-weight: 500;
  letter-spacing: -0.015em;
  line-height: 1.15;
}
.intro h1 em {
  font-style: italic;
  color: var(--terracotta-d);
}
.byline {
  margin-top: 28px;
  font-size: 0.86rem;
  color: var(--warm-gray);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-weight: 700;
}

/* Chef */
.chef {
  max-width: 1080px;
  margin: 0 auto;
  padding: 40px 28px 80px;
  display: grid;
  grid-template-columns: 1fr 1.3fr;
  gap: 56px;
  align-items: center;
}
@media (max-width: 720px) {
  .chef {
    grid-template-columns: 1fr;
    gap: 28px;
  }
}
.chef-portrait {
  position: relative;
  aspect-ratio: 3 / 4;
  border-radius: var(--r-lg);
  overflow: hidden;
  display: grid;
  place-items: center;
}
.portrait-bg {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 30%, rgba(193, 113, 74, 0.5), transparent 50%),
    radial-gradient(circle at 70% 70%, rgba(45, 74, 62, 0.4), transparent 55%),
    linear-gradient(135deg, var(--cream-2) 0%, var(--gold-light) 100%);
}
.portrait-glyph {
  position: relative;
  font-size: 6rem;
  filter: drop-shadow(0 8px 16px rgba(44, 26, 14, 0.25));
}
.chef-portrait figcaption {
