}
.section-head h2 {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 4vw, 2.6rem);
  font-weight: 700;
  letter-spacing: -0.015em;
}

/* Timeline */
.timeline {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  position: relative;
}
.timeline::before {
  content: "";
  position: absolute;
  top: 32px;
  left: 5%;
  right: 5%;
  height: 2px;
  background: linear-gradient(90deg, var(--terracotta), var(--gold), var(--forest));
  border-radius: 999px;
  opacity: 0.4;
}
.timeline li {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 22px 18px 18px;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.timeline li::before {
  content: "";
  position: absolute;
  top: -8px;
  left: 22px;
  width: 14px;
  height: 14px;
  border-radius: 999px;
  background: var(--terracotta);
  border: 3px solid var(--bone);
  box-shadow: 0 0 0 1px var(--terracotta);
}
.timeline li:nth-child(2)::before {
  background: var(--gold);
  box-shadow: 0 0 0 1px var(--gold);
}
.timeline li:nth-child(3)::before {
  background: var(--success);
  box-shadow: 0 0 0 1px var(--success);
}
.timeline li:nth-child(4)::before {
  background: var(--forest);
  box-shadow: 0 0 0 1px var(--forest);
}
.year {
  font-family: var(--font-mono);
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--warm-gray);
  letter-spacing: 0.06em;
}
.timeline h3 {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 700;
}
.timeline p {
  font-size: 0.88rem;
  color: var(--ink-2);
}
@media (max-width: 880px) {
  .timeline {
    grid-template-columns: 1fr;
  }
  .timeline::before {
    display: none;
  }
}

/* Team */
.team {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
}
.member {
  text-align: center;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 22px 16px 18px;
}
.avatar {
  width: 88px;
  height: 88px;
  border-radius: 999px;
  margin: 0 auto 14px;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 2rem;
  color: var(--bone);
}
.avatar-a {
  background: linear-gradient(135deg, var(--terracotta), var(--terracotta-d));
}
.avatar-b {
  background: linear-gradient(135deg, var(--forest), var(--forest-d));
}
.avatar-c {
  background: linear-gradient(135deg, var(--gold), var(--gold-light));
  color: var(--ink);
}
.avatar-d {
  background: linear-gradient(135deg, var(--warm-gray), var(--ink-2));
}
.member h3 {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
}
.member p {
  font-size: 0.82rem;
  color: var(--warm-gray);
  margin-top: 2px;
}

/* Values */
.values {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}
.value {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 24px 22px 22px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.value-icon {
  font-size: 1.8rem;
}
.value h3 {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 700;
}
.value p {
  font-size: 0.92rem;
  color: var(--ink-2);
}

/* Press */
.press {
  text-align: center;
  border-top: 1px solid rgba(44, 26, 14, 0.08);
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
  background: var(--bone);
  max-width: none;
}
.press-grid {
  max-width: 1080px;
  margin: 24px auto 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
}
.press-card {
  background: var(--cream);
  border-radius: var(--r-md);
  padding: 22px 22px 20px;
  text-align: left;
}
.press-pub {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--terracotta);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  margin-bottom: 10px;
}
.press-quote {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-style: italic;
  color: var(--ink);
  line-height: 1.45;
}

/* CTA strip */
.cta-strip {
  text-align: center;
  padding: 60px 28px 80px;
}
.cta-strip h2 {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 4vw, 2.6rem);
  font-weight: 700;
  margin-bottom: 18px;
}
.btn-primary {
  display: inline-block;
  background: var(--forest);
  color: var(--bone);
  text-decoration: none;
  border-radius: 999px;
  padding: 13px 26px;
  font-weight: 700;
}
.btn-primary:hover {
  background: var(--forest-d);
}

/* Footer */
.footer {
  border-top: 1px solid rgba(44, 26, 14, 0.08);
  background: var(--bone);
  text-align: center;
  padding: 32px 28px;
}
.footer-brand {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: -0.005em;
}
.footer-meta {
  font-size: 0.84rem;
  color: var(--warm-gray);
  margin-top: 4px;
}

/* Reveal on scroll */
.timeline li,
.member,
.value,
.press-card {
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}
.timeline li.is-in,
.member.is-in,
.value.is-in,
.press-card.is-in {
  opacity: 1;
  transform: none;
}

