@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

/* Agave SVG */
.agave {
  text-align: center;
}
.agave-svg {
  width: 100%;
  max-width: 240px;
  height: auto;
  filter: drop-shadow(0 12px 30px rgba(31, 78, 160, 0.32));
}
.agave-cap {
  margin-top: 12px;
  font-family: var(--font-display);
  font-style: italic;
  font-size: 0.9rem;
  color: var(--mute);
}
@media (max-width: 880px) {
  .hero {
    grid-template-columns: 1fr;
    padding: 48px 24px;
  }
}

/* ── Carta ── */
.carta {
  max-width: 1180px;
  margin: 0 auto;
  padding: 88px 28px;
  scroll-margin-top: 80px;
}
.section-head {
  text-align: center;
  margin-bottom: 40px;
}
.section-head h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(2rem, 5vw, 3rem);
  letter-spacing: -0.015em;
  line-height: 1.05;
  margin-top: 6px;
}
.section-head h2 em {
  font-style: italic;
  color: var(--terra);
}

.taco-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
@media (max-width: 880px) {
  .taco-grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 540px) {
  .taco-grid {
    grid-template-columns: 1fr;
  }
}
.taco {
  background: var(--paper);
  border: 2px solid var(--ink);
  padding: 22px 22px 20px;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow: 4px 4px 0 var(--cobalt);
  transition: transform 0.2s, box-shadow 0.2s;
}
.taco:hover {
  transform: translate(-2px, -2px);
  box-shadow: 8px 8px 0 var(--cobalt);
}
.taco-feat {
  background: var(--mustard);
  box-shadow: 4px 4px 0 var(--terra-d);
}
.taco-feat:hover {
  box-shadow: 8px 8px 0 var(--terra-d);
}
.taco-glyph {
  font-size: 2rem;
}
.taco-badge {
  position: absolute;
  top: -10px;
  right: 16px;
  background: var(--terra);
  color: var(--bone);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 5px 10px;
  border: 2px solid var(--ink);
  transform: rotate(-2deg);
}
.taco h3 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.3rem;
  margin-top: 4px;
}
.taco p {
  color: var(--ink-2);
  font-size: 0.92rem;
  flex: 1;
}
.taco-price {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--terra-d);
  margin-top: 4px;
  font-size: 0.95rem;
}
.taco-feat .taco-price {
  color: var(--ink);
}

/* ── Mezcalería ── */
.mezcal {
  background: var(--cobalt);
  color: var(--bone);
  padding: 88px 28px;
  scroll-margin-top: 80px;
}
.mezcal-inner {
  max-width: 1080px;
  margin: 0 auto;
}
.mezcal .kicker {
  color: var(--mustard);
}
.mezcal h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(2rem, 4.5vw, 3rem);
  line-height: 1.05;
  letter-spacing: -0.015em;
  margin-top: 6px;
}
.mezcal h2 em {
  font-style: italic;
  color: var(--mustard);
}
.mezcal-desc {
  margin-top: 16px;
  font-size: 1.02rem;
  color: rgba(244, 231, 207, 0.78);
  max-width: 560px;
}
.mezcal-list {
  margin-top: 32px;
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  border-top: 1px solid rgba(244, 231, 207, 0.18);
}
.mezcal-list li {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: baseline;
  gap: 8px 18px;
  padding: 18px 20px;
  border-bottom: 1px solid rgba(244, 231, 207, 0.18);
}
.mezcal-list li:nth-child(odd) {
  border-right: 1px solid rgba(244, 231, 207, 0.18);
}
@media (max-width: 720px) {
  .mezcal-list {
    grid-template-columns: 1fr;
  }
  .mezcal-list li:nth-child(odd) {
    border-right: none;
  }
}
.m-name {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.2rem;
}
.m-where {
  grid-column: 1;
  font-size: 0.78rem;
  color: rgba(244, 231, 207, 0.6);
  letter-spacing: 0.04em;
}
.m-abv {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 0.82rem;
  color: var(--mustard);
}
.m-price {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--bone);
  font-size: 1.05rem;
}
.mezcal-foot {
  margin-top: 26px;
  padding: 18px 22px;
  background: rgba(244, 231, 207, 0.08);
  border-left: 4px solid var(--mustard);
  font-size: 0.96rem;
}
.mezcal-foot strong {
  color: var(--mustard);
}

/* ── Barrio ── */
.barrio {
  padding: 88px 28px;
  scroll-margin-top: 80px;
}
.barrio .section-head h2 em {
  color: var(--cobalt);
}
.barrio-grid {
  max-width: 1080px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
@media (max-width: 880px) {
  .barrio-grid {
    grid-template-columns: 1fr;
  }
}
.info {
  background: var(--paper);
  border: 2px solid var(--ink);
  padding: 24px 26px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.info-vibrant {
  background: var(--terra);
  color: var(--bone);
  border-color: var(--ink);
}
.info h3 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.35rem;
}
.info ul {
  list-style: none;
}
.info li {
  display: flex;
  justify-content: space-between;
  padding: 7px 0;
  border-bottom: 1px dotted var(--rule);
  font-size: 0.9rem;
}
.info li:last-child {
  border-bottom: none;
}
.info li span:last-child {
  font-family: var(--font-mono);
  font-weight: 600;
}
.info li.closed span:last-child {
  color: var(--mute);
}
.info address {
  font-style: normal;
  line-height: 1.75;
  font-size: 0.95rem;
}
.info-note {
  margin-top: 8px;
  font-size: 0.84rem;
  font-style: italic;
  color: var(--mute);
}
.info-vibrant .info-note {
  color: rgba(244, 231, 207, 0.8);
}

/* ── Reservar ── */
.reservar {
  background: var(--mustard);
  padding: 88px 28px;
  scroll-margin-top: 80px;
}
.reservar-inner {
  max-width: 1080px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 56px;
  align-items: center;
}
.reservar .kicker {
  color: var(--ink);
}
.reservar h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(2rem, 4.5vw, 3rem);
  line-height: 1.05;
  letter-spacing: -0.015em;
  margin-top: 6px;
}
.reservar h2 em {
  font-style: italic;
  color: var(--cobalt);
}
.reservar-sub {
  margin-top: 18px;
  color: var(--ink-2);
  font-size: 1.02rem;
  max-width: 460px;
}
.reservar-bullets {
  list-style: none;
  margin-top: 22px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 18px;
}
.reservar-bullets li {
  font-size: 0.92rem;
  color: var(--ink);
  font-weight: 500;
}

.reservar-form {
  background: var(--ink);
  color: var(--bone);
  border-radius: 6px;
  padding: 28px 28px 26px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.form-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}
.reservar-form label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--mustard);
  font-weight: 700;
}
.reservar-form input,
.reservar-form select {
  background: rgba(244, 231, 207, 0.08);
  border: 1px solid rgba(244, 231, 207, 0.18);
  color: var(--bone);
  padding: 11px 14px;
  font-family: inherit;
  font-size: 0.94rem;
  outline: none;
  border-radius: 4px;
}
.reservar-form input:focus,
.reservar-form select:focus {
  border-color: var(--mustard);
}
.full {
  width: 100%;
}
.reservar-form .btn {
  align-self: flex-start;
  margin-top: 4px;
}
.ok {
  color: var(--mustard);
  font-weight: 700;
  letter-spacing: 0.04em;
}
@media (max-width: 880px) {
  .reservar-inner {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .reservar-bullets {
    grid-template-columns: 1fr;
  }
}

/* ── Footer ── */
.footer {
  background: var(--ink);
  color: var(--bone);
  text-align: center;
  padding: 48px 28px;
}
.foot-brand {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.4rem;
  color: var(--mustard);
}
.foot-meta {
  color: rgba(244, 231, 207, 0.6);
  font-size: 0.86rem;
  margin-top: 6px;
}
.foot-meta:last-child {
  font-style: italic;
  color: var(--terra);
}

snippets.js:
// Default reservation date to upcoming Saturday
const di = document.querySelector('input[name="d"]');
if (di) {
  const t = new Date();
  const day = t.getDay();
  const delta = (6 - day + 7) % 7 || 7;
  t.setDate(t.getDate() + delta);
  di.value = t.toISOString().slice(0, 10);
}

const form = document.getElementById("form");
const ok = document.getElementById("ok");
form.addEventListener("submit", (e) => {
  e.preventDefault();
  ok.hidden = false;
  const btn = form.querySelector("button");
  btn.disabled = true;
  setTimeout(() => {
    ok.hidden = true;
    btn.disabled = false;
  }, 3000);
});

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

.app {
  height: 100vh;
  display: grid;
  grid-template-columns: 248px 1fr;
}

/* ─── Sidebar ─── */
.rail {
  background: var(--forest);
  color: var(--bone);
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--forest-d);
  overflow-y: auto;
}
.rail-brand {
  padding: 22px 22px 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid rgba(250, 247, 241, 0.1);
}
.brand-mark {
  width: 36px;
  height: 36px;
  background: var(--gold);
  color: var(--ink);
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 0.92rem;
  border-radius: 8px;
  display: grid;
  place-items: center;
  letter-spacing: 0.04em;
}
.brand-name {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.05rem;
}
.rail-nav {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 12px 12px 18px;
  gap: 2px;
}
.r-section {
  margin: 16px 14px 6px;
  font-size: 0.66rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gold-light);
  font-weight: 700;
}
.r-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: 8px;
  text-decoration: none;
  color: rgba(250, 247, 241, 0.78);
  font-size: 0.92rem;
  font-weight: 500;
  transition: background 0.15s, color 0.15s;
}
.r-link:hover {
  background: rgba(250, 247, 241, 0.06);
  color: var(--bone);
}
.r-link.is-active {
  background: var(--bone);
  color: var(--forest-d);
  font-weight: 700;
}
.r-link.is-active .r-icon {
  filter: none;
}
.r-icon {
  font-size: 1rem;
  width: 22px;
  text-align: center;
}
.r-badge {
  margin-left: auto;
  background: var(--gold);
  color: var(--ink);
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 999px;
  min-width: 24px;
  text-align: center;
}
.r-badge-warn {
  background: var(--warning);
  color: var(--ink);
}
.r-link-quiet {
  color: rgba(250, 247, 241, 0.55);
  font-size: 0.84rem;
}
.r-dot {
  margin-left: auto;
  width: 8px;
  height: 8px;
  background: #6ec78a;
  border-radius: 999px;
  box-shadow: 0 0 0 4px rgba(110, 199, 138, 0.18);
}
.rail-foot {
  padding: 14px 16px;
  border-top: 1px solid rgba(250, 247, 241, 0.1);
}
.rail-user {
  display: flex;
  align-items: center;
  gap: 10px;
}
.user-avatar {
  width: 38px;
  height: 38px;
  background: var(--gold);
  color: var(--ink);
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-weight: 800;
}
.user-name {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--bone);
}
.user-role {
  font-size: 0.74rem;
  color: rgba(250, 247, 241, 0.5);
}

/* ─── Main ─── */
.main {
  overflow-y: auto;
  padding: 28px 36px 56px;
}

.top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
  gap: 14px;
}
.kicker {
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.top h1 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 2rem;
  letter-spacing: -0.015em;
}
.top-tools {
  display: flex;
  align-items: center;
  gap: 8px;
}
.seg {
  display: inline-flex;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.1);
  padding: 3px;
  border-radius: 999px;
}
.seg-btn {
  background: transparent;
  border: none;
  color: var(--ink-2);
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  padding: 7px 14px;
  border-radius: 999px;
  cursor: pointer;
}
.seg-btn.is-active {
  background: var(--forest);
  color: var(--bone);
}
.ghost,
.primary {
  border-radius: 999px;
  padding: 9px 16px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid transparent;
}
.ghost {
  background: var(--bone);
  border-color: rgba(44, 26, 14, 0.12);
  color: var(--ink-2);
}
.ghost:hover {
  background: var(--cream-2);
  color: var(--ink);
}
.primary {
  background: var(--forest);
  color: var(--bone);
}
.primary:hover {
  background: var(--forest-d);
}

/* KPI grid */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 12px;
  margin-bottom: 24px;
}
@media (max-width: 1180px) {
  .kpi-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}
@media (max-width: 720px) {
  .kpi-grid {
    grid-template-columns: 1fr 1fr;
  }
}
.kpi {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 16px 18px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.kpi-feat {
  background: linear-gradient(180deg, var(--forest) 0%, var(--forest-d) 100%);
  color: var(--bone);
  border-color: var(--forest-d);
}
.kpi-label {
  font-size: 0.74rem;
  letter-spacing: 0.06em;
  color: var(--warm-gray);
  font-weight: 600;
}
.kpi-feat .kpi-label {
  color: var(--gold-light);
}
.kpi-value {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.7rem;
  letter-spacing: -0.01em;
}
.kpi-sub {
  font-size: 0.92rem;
  color: var(--warm-gray);
  font-weight: 600;
}
.kpi-feat .kpi-sub {
  color: rgba(250, 247, 241, 0.6);
}
.kpi-delta {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--warm-gray);
}
.is-up {
  color: var(--success);
}
.is-down {
  color: var(--danger);
}
.is-flat {
  color: var(--warm-gray);
}
.kpi-feat .kpi-delta {
  color: var(--gold-light);
}

/* Rows */
.row {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 16px;
  margin-bottom: 16px;
}
@media (max-width: 980px) {
  .row {
    grid-template-columns: 1fr;
  }
}

.card {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-lg);
  padding: 20px 22px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.card-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}
.card-kicker {
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.card h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.4rem;
  letter-spacing: -0.005em;
  margin-top: 2px;
}

/* Chart */
.legend {
  font-size: 0.78rem;
  color: var(--warm-gray);
  display: flex;
  align-items: center;
  gap: 8px;
}
.legend-pip {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 999px;
  margin-right: 4px;
  margin-left: 12px;
}
.legend-pip:first-of-type {
  margin-left: 0;
}
.legend-this {
  background: var(--terracotta);
}
.legend-prev {
  background: rgba(44, 26, 14, 0.22);
}
.chart {
  width: 100%;
  height: auto;
  display: block;
}
.grid line {
  stroke: rgba(44, 26, 14, 0.08);
  stroke-width: 1;
  stroke-dasharray: 2 4;
}
.y-labels,
.x-labels {
  font-family: var(--font-mono);
  font-size: 10px;
  fill: var(--warm-gray);
  font-weight: 600;
}
.line {
  fill: none;
  stroke-width: 2.5;
  stroke-linejoin: round;
  stroke-linecap: round;
}
.line-curr {
  stroke: var(--terracotta);
}
.line-prev {
  stroke: rgba(44, 26, 14, 0.22);
  stroke-dasharray: 4 4;
  stroke-width: 2;
}
.area {
  fill: rgba(193, 113, 74, 0.12);
  stroke: none;
}
.dot {
  fill: var(--terracotta);
  stroke: var(--bone);
  stroke-width: 2;
  cursor: pointer;
}

/* Top items */
.ti-list {
  list-style: none;
  display: flex;
  flex-direction: column;
}
.ti-list li {
  display: grid;
  grid-template-columns: 20px 1fr auto;
  gap: 10px;
  align-items: baseline;
  padding: 10px 0;
  border-bottom: 1px dashed rgba(44, 26, 14, 0.1);
  font-size: 0.92rem;
}
.ti-list li:last-child {
  border-bottom: none;
}
.ti-no {
  font-family: var(--font-mono);
  color: var(--warm-gray);
  font-weight: 700;
  font-size: 0.78rem;
}
.ti-name {
  font-weight: 600;
}
.ti-name small {
  display: block;
  color: var(--warm-gray);
  font-weight: 500;
  font-size: 0.74rem;
  margin-top: 2px;
}
.ti-amt {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--terracotta-d);
}

/* Heatmap */
.heatmap {
  display: grid;
  grid-template-columns: 60px repeat(7, 1fr);
  gap: 4px;
}
.h-label {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--warm-gray);
  display: grid;
  place-items: center;
  font-weight: 600;
}
.h-cell {
  aspect-ratio: 1.6 / 1;
  border-radius: 4px;
  background: var(--cream-2);
}
.h-cell[data-h="0"] {
  background: var(--cream-2);
}
.h-cell[data-h="1"] {
  background: #e7d4b3;
}
.h-cell[data-h="2"] {
  background: #d4a87b;
}
.h-cell[data-h="3"] {
  background: var(--terracotta);
}
.h-cell[data-h="4"] {
  background: var(--terracotta-d);
}
.h-cell[data-h="5"] {
  background: var(--forest);
}
.heat-legend {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
  font-size: 0.74rem;
  color: var(--warm-gray);
  font-weight: 600;
}
.h-scale {
  display: inline-flex;
  gap: 2px;
}
.h-s {
  width: 18px;
  height: 12px;
  border-radius: 3px;
}
.s-1 {
  background: var(--cream-2);
}
.s-2 {
  background: #e7d4b3;
}
.s-3 {
  background: #d4a87b;
}
.s-4 {
  background: var(--terracotta);
}
.s-5 {
  background: var(--forest);
}

/* Reservation preview */
.res-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.res-row {
  display: grid;
  grid-template-columns: 56px 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 10px;
  background: var(--cream);
}
.res-time {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--ink);
}
.res-name {
  font-weight: 700;
  font-size: 0.94rem;
}
.res-meta {
  font-size: 0.76rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.res-tag {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 4px 9px;
  border-radius: 999px;
  background: var(--cream-2);
  color: var(--ink-2);
}
.res-tag[data-t="vip"] {
  background: var(--gold);
  color: var(--ink);
}
.res-tag[data-t="party"] {
  background: var(--terracotta);
  color: var(--bone);
}
.res-tag[data-t="window"] {
  background: var(--success);
  color: var(--bone);
}
.card-cta {
  margin-top: 2px;
  text-decoration: none;
  color: var(--terracotta-d);
  font-weight: 700;
  font-size: 0.86rem;
  letter-spacing: 0.02em;
  align-self: flex-start;
}
.card-cta:hover {
  color: var(--ink);
}

/* ── Responsive ── */
@media (max-width: 880px) {
  .app {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr;
  }
  .rail {
    flex-direction: row;
    overflow-x: auto;
    padding: 8px 12px;
    border-right: none;
    border-bottom: 1px solid var(--forest-d);
  }
  .rail-brand,
  .rail-foot,
  .r-section {
    display: none;
  }
  .rail-nav {
    flex-direction: row;
    padding: 0;
    gap: 6px;
  }
}

