// ─── Revenue chart ───
const DAYS = ["Tue", "Wed", "Thu", "Fri", "Sat", "Sun", "Mon"];
const CURR = [3200, 3450, 3980, 5320, 6850, 5840, 3540]; // $
const PREV = [2900, 3210, 3650, 4920, 6120, 5430, 3380];

const W = 600;
const H = 220;
const PX = 40;
const PY = 30;
const innerW = W - PX - 20;
const innerH = H - PY - 30;

const maxY = 8000;
function px(i, n) {
  return PX + (i / (n - 1)) * innerW;
}
function py(v) {
  return PY + innerH - (v / maxY) * innerH;
}

function pathFor(arr) {
  return arr.map((v, i) => `${i === 0 ? "M" : "L"}${px(i, arr.length)} ${py(v)}`).join(" ");
}
function areaFor(arr) {
  const top = pathFor(arr);
  const last = arr.length - 1;
  return `${top} L ${px(last, arr.length)} ${py(0)} L ${px(0, arr.length)} ${py(0)} Z`;
}

document.getElementById("currLine").setAttribute("d", pathFor(CURR));
document.getElementById("prevLine").setAttribute("d", pathFor(PREV));
document.getElementById("currArea").setAttribute("d", areaFor(CURR));

const xLabels = document.getElementById("xLabels");
xLabels.innerHTML = DAYS.map(
  (d, i) => `<text x="${px(i, DAYS.length)}" y="${H - 8}" text-anchor="middle">${d}</text>`
).join("");

const dots = document.getElementById("dots");
dots.innerHTML = CURR.map(
  (v, i) => `<circle class="dot" cx="${px(i, CURR.length)}" cy="${py(v)}" r="4">
    <title>${DAYS[i]} · $${v.toLocaleString()}</title>
  </circle>`
).join("");

// ─── Top items ───
const TOP = [
  { name: "Ribeye 14oz", sub: "Mains · dry-aged 28 d", amt: 4264 },
  { name: "Burrata huerta", sub: "Apps", amt: 2880 },
  { name: "Pappardelle ragú", sub: "Pasta", amt: 2496 },
  { name: "Branzino entero", sub: "Mains · whole sea bass", amt: 2280 },
  { name: "Tarta de queso", sub: "Dessert · burnt cheesecake", amt: 1958 },
  { name: "Risotto hongos", sub: "Pasta · vegetarian", amt: 1768 },
  { name: "Pulpo brasa", sub: "Apps", amt: 1672 },
  { name: "Negroni sbagliato", sub: "Drinks", amt: 1568 },
];
document.getElementById("topItems").innerHTML = TOP.map(
  (t, i) => `<li>
    <span class="ti-no">${String(i + 1).padStart(2, "0")}</span>
    <span class="ti-name">${t.name}<small>${t.sub}</small></span>
    <span class="ti-amt">$${t.amt.toLocaleString()}</span>
  </li>`
).join("");

// ─── Heatmap (rows = days, cols = service hours) ───
const HEAT_DAYS = ["Tue", "Wed", "Thu", "Fri", "Sat", "Sun", "Mon"];
const HEAT_HOURS = ["18", "19", "20", "21", "22"];
// values 0..5 (low → high)
const HEAT = [
  [1, 3, 4, 3, 1],
  [1, 3, 4, 3, 1],
  [2, 4, 5, 4, 2],
  [2, 4, 5, 5, 3],
  [3, 5, 5, 5, 3],
  [2, 4, 4, 2, 0],
  [0, 0, 0, 0, 0],
];
const heatmap = document.getElementById("heatmap");
// Header row (empty corner + hour labels turned per-row — we use a per-col header here)
let html = `<span class="h-label"></span>`;
HEAT_HOURS.forEach((h) => (html += `<span class="h-label">${h}h</span>`));
HEAT_DAYS.forEach((day, r) => {
  html += `<span class="h-label">${day}</span>`;
  HEAT[r].forEach((v) => {
    html += `<span class="h-cell" data-h="${v}" title="${day} ${HEAT_HOURS[0]}h · ${v}/5"></span>`;
  });
});
heatmap.innerHTML = html;
heatmap.style.gridTemplateColumns = `60px repeat(${HEAT_HOURS.length}, 1fr)`;

// ─── Reservation preview ───
const RES = [
  { time: "19:00", name: "Reyes", meta: "×2 · table 4", tag: "Window", t: "window" },
  {
    time: "19:15",
    name: "García-Tan",
    meta: "×4 · table 11 · birthday",
    tag: "Birthday",
    t: "party",
  },
  { time: "19:30", name: "Khoury", meta: "×2 · bar · regular", tag: "VIP", t: "vip" },
  { time: "20:00", name: "Marquez", meta: "×2 · table 3", tag: "—", t: "" },
  { time: "20:15", name: "Loredo", meta: "×4 · table 5", tag: "—", t: "" },
  {
    time: "20:30",
    name: "Mendoza",
    meta: "×6 · long table · catering enquiry",
    tag: "Large",
    t: "party",
  },
  { time: "20:45", name: "Tanaka", meta: "×3 · table 12", tag: "—", t: "" },
  { time: "21:00", name: "Singh", meta: "×2 · patio", tag: "—", t: "" },
];
document.getElementById("resList").innerHTML = RES.map(
  (r) => `<li class="res-row">
    <span class="res-time">${r.time}</span>
    <span>
      <p class="res-name">${r.name}</p>
      <p class="res-meta">${r.meta}</p>
    </span>
    ${r.t ? `<span class="res-tag" data-t="${r.t}">${r.tag}</span>` : ""}
  </li>`
).join("");

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(44, 26, 14, 0.08), 0 2px 6px rgba(44, 26, 14, 0.06);
  --shadow-2: 0 8px 24px rgba(44, 26, 14, 0.12);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
  overflow: hidden;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

.pos {
  height: 100vh;
  display: grid;
  grid-template-columns: 220px 1fr 380px;
}

/* ── Rail (left sidebar) ── */
.rail {
  background: var(--forest);
  color: var(--bone);
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--forest-d);
  overflow-y: auto;
}
.rail-head {
  padding: 18px 18px 12px;
  border-bottom: 1px solid rgba(250, 247, 241, 0.1);
}
.brand {
  display: block;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.15rem;
  letter-spacing: -0.005em;
}
.term {
  display: block;
  font-size: 0.7rem;
  color: var(--gold-light);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  margin-top: 2px;
}
.rail-section {
  padding: 14px 14px 10px;
  border-bottom: 1px solid rgba(250, 247, 241, 0.08);
}
.rail-label {
  font-size: 0.66rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--gold-light);
  font-weight: 600;
  margin-bottom: 8px;
}
.seg {
  display: flex;
  gap: 4px;
  background: rgba(0, 0, 0, 0.18);
  padding: 3px;
  border-radius: 999px;
}
.seg-btn {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--bone);
  font-family: inherit;
  font-size: 0.74rem;
  font-weight: 600;
  padding: 7px 8px;
  border-radius: 999px;
  cursor: pointer;
}
.seg-btn.is-active {
  background: var(--bone);
  color: var(--forest-d);
}
.tables {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 4px;
}
.table-btn {
  background: rgba(250, 247, 241, 0.08);
  border: 1px solid rgba(250, 247, 241, 0.12);
  color: var(--bone);
  font-family: inherit;
  font-size: 0.78rem;
  font-weight: 600;
  padding: 8px 0;
  border-radius: var(--r-sm);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.table-btn:hover {
  background: rgba(250, 247, 241, 0.16);
}
.table-btn.is-active {
  background: var(--gold);
  color: var(--ink);
  border-color: var(--gold);
}
.cats {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}
.cat-btn {
  background: transparent;
  border: none;
  color: var(--bone);
  font-family: inherit;
  font-size: 0.88rem;
  font-weight: 600;
  text-align: left;
  padding: 11px 14px;
  border-radius: var(--r-md);
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 10px;
}
.cat-btn:hover {
  background: rgba(250, 247, 241, 0.08);
}
.cat-btn.is-active {
  background: var(--bone);
  color: var(--forest-d);
}
.cat-icon {
  font-size: 1.05rem;
  width: 22px;
  text-align: center;
}
.rail-foot {
  margin-top: auto;
  padding: 12px 14px;
  border-top: 1px solid rgba(250, 247, 241, 0.1);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.clock {
  font-family: var(--font-mono);
  font-weight: 600;
  font-size: 0.85rem;
  color: var(--gold-light);
}
.util-btn {
  background: rgba(250, 247, 241, 0.08);
  border: 1px solid rgba(250, 247, 241, 0.16);
  color: var(--bone);
  font-family: inherit;
  font-size: 0.74rem;
  font-weight: 600;
  padding: 6px 10px;
  border-radius: var(--r-sm);
  cursor: pointer;
}

/* ── Menu (centre) ── */
.menu {
  background: var(--cream);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.menu-head {
  padding: 18px 22px 14px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 16px;
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
}
.menu-kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--terracotta);
  font-weight: 600;
  margin-bottom: 2px;
}
.menu-head h1 {
  font-family: var(--font-display);
  font-size: 1.55rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.menu-search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.1);
  padding: 8px 14px;
  border-radius: 999px;
  color: var(--warm-gray);
}
.menu-search input {
  background: transparent;
  border: none;
  outline: none;
  font-family: inherit;
  font-size: 0.86rem;
  color: var(--ink);
  width: 200px;
}

.grid {
  flex: 1;
  overflow-y: auto;
  padding: 18px 22px 28px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 12px;
  align-content: start;
}
.tile {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 14px 12px 12px;
  cursor: pointer;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-height: 100px;
  font-family: inherit;
  color: var(--ink);
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}
.tile:hover {
  border-color: var(--terracotta);
}
.tile:active {
  transform: scale(0.97);
  background: var(--cream-2);
}
.tile.is-flash {
  animation: flash 0.45s ease;
}
@keyframes flash {
  0% {
    background: var(--gold);
    border-color: var(--gold);
  }
  100% {
    background: var(--bone);
    border-color: rgba(44, 26, 14, 0.08);
  }
}
.tile-name {
  font-size: 0.9rem;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.005em;
}
.tile-desc {
  font-size: 0.72rem;
  color: var(--warm-gray);
  line-height: 1.35;
  flex: 1;
}
.tile-price {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--terracotta-d);
  margin-top: 4px;
}
.tile-86 {
  position: relative;
  opacity: 0.55;
  cursor: not-allowed;
}
.tile-86::after {
  content: "86";
  position: absolute;
  top: 8px;
  right: 8px;
  background: var(--danger);
  color: var(--bone);
  font-family: var(--font-mono);
  font-size: 0.66rem;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 999px;
}

/* ── Ticket (right) ── */
.ticket {
  background: var(--bone);
  border-left: 1px solid rgba(44, 26, 14, 0.1);
  display: flex;
  flex-direction: column;
}
.ticket-head {
  padding: 18px 18px 14px;
  border-bottom: 1px dashed rgba(44, 26, 14, 0.18);
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}
.ticket-table {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.25rem;
}
.ticket-meta {
  font-size: 0.74rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.course-btn {
  background: transparent;
  border: 1px solid rgba(44, 26, 14, 0.16);
  border-radius: 999px;
  padding: 6px 12px;
  font-family: inherit;
  font-size: 0.74rem;
  font-weight: 600;
  color: var(--ink-2);
  cursor: pointer;
}
.course-btn:hover {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}

.ticket-body {
  flex: 1;
  overflow-y: auto;
  padding: 8px 18px;
}
.course {
  margin-bottom: 6px;
}
.course-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--terracotta);
  font-weight: 700;
  padding: 14px 0 6px;
  border-bottom: 1px solid rgba(193, 113, 74, 0.2);
}
.course-label .dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--terracotta);
}
.course-label.is-sent .dot {
  background: var(--success);
}
.course-label.is-sent {
  color: var(--success);
}
.course-sent-tag {
  margin-left: auto;
  font-size: 0.62rem;
  background: var(--success);
  color: var(--bone);
  padding: 2px 7px;
  border-radius: 999px;
  letter-spacing: 0.08em;
  font-weight: 700;
}
.line {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid rgba(44, 26, 14, 0.06);
}
.line:last-child {
  border-bottom: none;
}
.line-qty {
  display: inline-flex;
  align-items: center;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: 999px;
  padding: 2px;
  gap: 2px;
}
.line-qty button {
  width: 26px;
  height: 26px;
  border-radius: 999px;
  border: none;
  background: transparent;
  color: var(--ink-2);
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  display: grid;
  place-items: center;
  line-height: 1;
}
.line-qty button:hover {
  background: var(--cream-2);
  color: var(--terracotta-d);
}
.line-qty span {
  min-width: 22px;
  text-align: center;
  font-weight: 700;
  font-size: 0.86rem;
  font-variant-numeric: tabular-nums;
}
.line-body {
  flex: 1;
  min-width: 0;
}
.line-name {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--ink);
}
.line-mods {
  font-size: 0.7rem;
  color: var(--warm-gray);
}
.line-price {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.88rem;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.line.is-sent .line-name,
.line.is-sent .line-price {
  color: var(--warm-gray);
  text-decoration: line-through;
  text-decoration-thickness: 1px;
}
.line.is-sent .line-qty {
  opacity: 0.5;
}

.empty-course {
  font-style: italic;
  color: var(--warm-gray);
  font-size: 0.78rem;
  padding: 8px 0 16px;
}

.ticket-foot {
  padding: 14px 18px 18px;
  border-top: 1px solid rgba(44, 26, 14, 0.1);
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--cream);
}
.totals {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px 18px;
}
.totals div {
  display: flex;
  justify-content: space-between;
  font-size: 0.78rem;
  color: var(--ink-2);
}
.totals dd {
  font-family: var(--font-mono);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.total-big {
  grid-column: 1 / -1;
  margin-top: 4px;
  padding-top: 8px;
  border-top: 1px solid rgba(44, 26, 14, 0.16);
  font-size: 1rem;
  font-weight: 700;
  color: var(--ink);
}
.total-big dd {
  font-size: 1.15rem;
}

.actions {
  display: grid;
  grid-template-columns: auto auto 1fr auto;
  gap: 8px;
}
.ghost,
.primary,
.gold {
  border: none;
  border-radius: 999px;
  padding: 11px 14px;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
}
.ghost {
  background: transparent;
  border: 1px solid rgba(44, 26, 14, 0.18);
  color: var(--ink-2);
}
.ghost:hover {
  background: var(--cream-2);
  color: var(--ink);
}
.primary {
  background: var(--forest);
  color: var(--bone);
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-left: 16px;
  padding-right: 8px;
}
.primary:hover:not(:disabled) {
  background: var(--forest-d);
}
.primary:disabled {
  background: var(--warm-gray);
  cursor: not-allowed;
  opacity: 0.7;
}
.total-pill {
  font-family: var(--font-mono);
  font-weight: 700;
  background: rgba(250, 247, 241, 0.18);
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 0.78rem;
}
.gold {
  background: var(--gold);
  color: var(--ink);
}
.gold:hover:not(:disabled) {
  background: var(--gold-light);
}
.gold:disabled {
  background: rgba(201, 168, 76, 0.4);
  cursor: not-allowed;
  color: var(--warm-gray);
}

.toast {
  position: fixed;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--forest-d);
  color: var(--bone);
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: var(--shadow-2);
}

/* ── Responsive (tablets) ── */
@media (max-width: 1100px) {
  .pos {
    grid-template-columns: 200px 1fr 340px;
  }
  .menu-search input {
    width: 140px;
  }
}
@media (max-width: 880px) {
  .pos {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
    height: auto;
  }
  html,
  body {
    overflow: auto;
  }
  .rail {
    flex-direction: row;
    align-items: stretch;
    overflow-x: auto;
  }
  .rail-foot {
    display: none;
  }
  .ticket {
    border-left: none;
    border-top: 1px solid rgba(44, 26, 14, 0.1);
  }
}

snippets.js:
const TAX_RATE = 0.0825;
const SERVICE_RATE = 0.1;

const MENU = {
  entradas: {
    title: "Entradas",
    icon: "🥖",
    items: [
      { id: "pan", name: "Pan masa madre", desc: "Smoked oil, sea salt", price: 8 },
      { id: "burrata", name: "Burrata huerta", desc: "Heirloom tomato, basil", price: 16 },
      { id: "pulpo", name: "Pulpo brasa", desc: "Smoked paprika potato", price: 19 },
      { id: "croquetas", name: "Croquetas jamón", desc: "6 pcs, lemon aioli", price: 14 },
      {
        id: "anchoas",
        name: "Anchoas Cantábrico",
        desc: "Boquerones, butter, baguette",
        price: 17,
      },
      { id: "ensalada", name: "Ensalada huerta", desc: "Garden greens, vinaigrette", price: 13 },
    ],
  },
  principales: {
    title: "Principales",
    icon: "🥩",
    items: [
      { id: "ribeye", name: "Ribeye 14oz", desc: "Marrow butter, chimichurri", price: 48 },
      { id: "branzino", name: "Branzino entero", desc: "Fennel, preserved lemon", price: 38 },
      { id: "risotto", name: "Risotto hongos", desc: "Wild mushroom, parmesan", price: 26 },
      { id: "pollo", name: "Pollo carbón", desc: "Half chicken, garlic confit", price: 28 },
      { id: "pappardelle", name: "Pappardelle ragú", desc: "Slow lamb shoulder", price: 24 },
      { id: "salmon", name: "Salmón plancha", desc: "Citrus glaze", price: 32, soldOut: true },
      { id: "cordero", name: "Costilla cordero", desc: "Honey-mint glaze", price: 42 },
      { id: "huerto", name: "Plato huerto", desc: "Seasonal vegetables", price: 22 },
    ],
  },
  postres: {
    title: "Postres",
    icon: "🍰",
    items: [
      { id: "tarta", name: "Tarta de queso", desc: "Basque burnt, salted caramel", price: 11 },
      { id: "olive", name: "Olive oil cake", desc: "Crème fraîche, candied orange", price: 10 },
      { id: "ganache", name: "Chocolate ganache", desc: "Hazelnut praline", price: 12 },
      { id: "sorbete", name: "Sorbete cítrico", desc: "Citrus, mint", price: 9 },
    ],
  },
  bebidas: {
    title: "Bebidas",
    icon: "🍷",
    items: [
      { id: "vermut", name: "Vermut casa", price: 9 },
      { id: "negroni", name: "Negroni sbagliato", price: 14 },
      { id: "spritz", name: "Spritz", price: 13 },
      { id: "tinto", name: "Tinto natural (copa)", price: 12 },
      { id: "blanco", name: "Blanco copa", price: 11 },
      { id: "agua", name: "Agua mineral", price: 5 },
      { id: "cafe", name: "Espresso", price: 4 },
      { id: "tonica", name: "Tónica", price: 6 },
    ],
  },
};

const COURSE_NAMES = ["1st course", "2nd course", "3rd course", "4th course"];

const catsEl = document.getElementById("cats");
const tablesEl = document.getElementById("tables");
const gridEl = document.getElementById("grid");
const catName = document.getElementById("catName");
const catCount = document.getElementById("catCount");
const searchEl = document.getElementById("search");
const ticketBody = document.getElementById("ticketBody");
const ticketTable = document.getElementById("ticketTable");
const ticketMeta = document.getElementById("ticketMeta");
const subtotalEl = document.getElementById("subtotal");
const taxEl = document.getElementById("tax");
const serviceEl = document.getElementById("service");
const totalEl = document.getElementById("total");
const sendTotalEl = document.getElementById("sendTotal");
const sendBtn = document.getElementById("send");
const payBtn = document.getElementById("pay");
const holdBtn = document.getElementById("hold");
const printBtn = document.getElementById("print");
const courseBtn = document.getElementById("course");
const clockEl = document.getElementById("clock");
const toast = document.getElementById("toast");

let activeCat = "entradas";
let activeTable = 7;
let courses = [{ id: 1, name: COURSE_NAMES[0], sent: false, lines: [] }];

function money(v) {
  return `$${v.toFixed(2)}`;
}

function renderTables() {
  tablesEl.innerHTML = Array.from({ length: 12 }, (_, i) => i + 1)
    .map(
      (n) =>
        `<button class="table-btn ${n === activeTable ? "is-active" : ""}" data-table="${n}">${n}</button>`
    )
    .join("");
}

function renderCats() {
  catsEl.innerHTML = Object.entries(MENU)
    .map(
      ([key, c]) => `
      <button class="cat-btn ${key === activeCat ? "is-active" : ""}" data-cat="${key}">
        <span class="cat-icon">${c.icon}</span>
        <span>${c.title}</span>
      </button>`
    )
    .join("");
}

function renderGrid() {
  const cat = MENU[activeCat];
  const q = searchEl.value.trim().toLowerCase();
  const filtered = cat.items.filter(
    (i) => !q || i.name.toLowerCase().includes(q) || (i.desc || "").toLowerCase().includes(q)
  );
  catName.textContent = cat.title;
  catCount.textContent = `${filtered.length} ${filtered.length === 1 ? "item" : "items"}`;
  gridEl.innerHTML = filtered
    .map(
      (item) => `
      <button class="tile ${item.soldOut ? "tile-86" : ""}" ${item.soldOut ? "disabled" : ""}
        data-item="${item.id}" data-name="${item.name}" data-price="${item.price}">
        <span class="tile-name">${item.name}</span>
        ${item.desc ? `<span class="tile-desc">${item.desc}</span>` : ""}
        <span class="tile-price">$${item.price.toFixed(2)}</span>
      </button>`
    )
    .join("");
}

function activeCourse() {
  return courses.find((c) => !c.sent) || courses[courses.length - 1];
}

function renderTicket() {
  ticketTable.textContent = `Table ${activeTable}`;
  const totalItems = courses.reduce((n, c) => n + c.lines.reduce((m, l) => m + l.qty, 0), 0);
  ticketMeta.textContent = `${totalItems} ${totalItems === 1 ? "item" : "items"} · 2 guests`;

  ticketBody.innerHTML = courses
    .map(
      (course) => `
      <div class="course" data-course="${course.id}">
        <p class="course-label ${course.sent ? "is-sent" : ""}">
          <span class="dot"></span>
          <span>${course.name}</span>
          ${course.sent ? `<span class="course-sent-tag">Sent</span>` : ""}
        </p>
        ${
          course.lines.length === 0
            ? `<p class="empty-course">Add an item.</p>`
            : course.lines
                .map(
                  (l) => `
            <div class="line ${course.sent ? "is-sent" : ""}" data-id="${l.uid}">
              ${
                course.sent
                  ? `<span class="line-qty"><span>${l.qty}</span></span>`
                  : `<div class="line-qty">
                    <button data-action="dec" aria-label="Decrease">−</button>
                    <span>${l.qty}</span>
                    <button data-action="inc" aria-label="Increase">+</button>
                  </div>`
              }
              <div class="line-body">
                <p class="line-name">${l.name}</p>
                ${l.mods ? `<p class="line-mods">${l.mods}</p>` : ""}
              </div>
              <span class="line-price">${money(l.price * l.qty)}</span>
            </div>`
                )
                .join("")
        }
      </div>`
    )
    .join("");

  const subtotal = courses.reduce(
    (s, c) => s + c.lines.reduce((m, l) => m + l.price * l.qty, 0),
    0
  );
  const tax = subtotal * TAX_RATE;
  const service = subtotal * SERVICE_RATE;
  const total = subtotal + tax + service;
  subtotalEl.textContent = money(subtotal);
  taxEl.textContent = money(tax);
  serviceEl.textContent = money(service);
  totalEl.textContent = money(total);
  sendTotalEl.textContent = money(total);

  const hasUnsentItems = courses.some((c) => !c.sent && c.lines.length > 0);
  const hasAnyItems = courses.some((c) => c.lines.length > 0);
  sendBtn.disabled = !hasUnsentItems;
  payBtn.disabled = !hasAnyItems;
}

function addItem(id, name, price, tile) {
  const course = activeCourse();
  let existing = course.lines.find((l) => l.id === id);
  if (existing) existing.qty += 1;
  else
    course.lines.push({
      uid: `${id}-${Date.now()}`,
      id,
      name,
      price,
      qty: 1,
      mods: "",
    });
  renderTicket();
  if (tile) {
    tile.classList.remove("is-flash");
    void tile.offsetWidth;
    tile.classList.add("is-flash");
  }
}

function showToast(message) {
  toast.textContent = message;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2200);
}

catsEl.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-cat]");
  if (!btn) return;
  activeCat = btn.dataset.cat;
  renderCats();
  renderGrid();
});
tablesEl.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-table]");
  if (!btn) return;
  activeTable = Number(btn.dataset.table);
  renderTables();
  renderTicket();
});
gridEl.addEventListener("click", (e) => {
  const tile = e.target.closest("[data-item]");
  if (!tile || tile.classList.contains("tile-86")) return;
  addItem(tile.dataset.item, tile.dataset.name, Number(tile.dataset.price), tile);
});
ticketBody.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action]");
  if (!btn) return;
  const line = btn.closest("[data-id]");
  const courseEl = btn.closest("[data-course]");
  if (!line || !courseEl) return;
  const course = courses.find((c) => String(c.id) === courseEl.dataset.course);
  if (!course || course.sent) return;
  const l = course.lines.find((x) => x.uid === line.dataset.id);
  if (!l) return;
  if (btn.dataset.action === "inc") l.qty += 1;
  if (btn.dataset.action === "dec") {
    l.qty -= 1;
    if (l.qty <= 0) course.lines = course.lines.filter((x) => x.uid !== l.uid);
  }
  renderTicket();
});

searchEl.addEventListener("input", renderGrid);

courseBtn.addEventListener("click", () => {
  if (courses.length >= COURSE_NAMES.length) return;
  courses.push({
    id: Date.now(),
    name: COURSE_NAMES[courses.length],
    sent: false,
    lines: [],
  });
  renderTicket();
});

sendBtn.addEventListener("click", () => {
  let sentCount = 0;
  courses.forEach((c) => {
    if (!c.sent && c.lines.length > 0) {
      c.sent = true;
      sentCount += c.lines.reduce((n, l) => n + l.qty, 0);
    }
  });
  // Auto-open a new course for the next round if all current are sent.
  if (courses.every((c) => c.sent) && courses.length < COURSE_NAMES.length) {
    courses.push({
      id: Date.now(),
      name: COURSE_NAMES[courses.length],
      sent: false,
      lines: [],
    });
  }
  renderTicket();
  showToast(`Sent ${sentCount} items to kitchen`);
});

holdBtn.addEventListener("click", () => showToast("Order held"));
printBtn.addEventListener("click", () => showToast("Printing pre-bill…"));
payBtn.addEventListener("click", () => {
  showToast(`Closing table ${activeTable}`);
  setTimeout(() => {
    courses = [{ id: 1, name: COURSE_NAMES[0], sent: false, lines: [] }];
    renderTicket();
  }, 800);
});

function tick() {
  const d = new Date();
  clockEl.textContent = `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}
tick();
setInterval(tick, 30000);

renderTables();
renderCats();
renderGrid();
renderTicket();

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(44, 26, 14, 0.08), 0 2px 6px rgba(44, 26, 14, 0.06);
  --shadow-2: 0 8px 24px rgba(44, 26, 14, 0.12);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  min-height: 100vh;
  padding: 32px 16px 48px;
  display: flex;
  justify-content: center;
  -webkit-font-smoothing: antialiased;
}

.ticket {
  width: 100%;
  max-width: 460px;
  background: var(--bone);
  border-radius: var(--r-lg);
  border: 1px solid rgba(44, 26, 14, 0.08);
  box-shadow: var(--shadow-2);
  padding: 22px 22px 18px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

/* ── Head ── */
.ticket-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  padding-bottom: 14px;
  border-bottom: 1px dashed rgba(44, 26, 14, 0.18);
}
.ticket-kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--terracotta);
  font-weight: 600;
  margin-bottom: 4px;
}
.ticket-title {
  font-family: var(--font-display);
  font-size: 1.55rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.ticket-count {
  font-size: 0.78rem;
  color: var(--warm-gray);
  font-weight: 500;
  padding-top: 4px;
  white-space: nowrap;
}

/* ── Lines ── */
.lines {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.line {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 10px 0;
  border-bottom: 1px solid rgba(44, 26, 14, 0.06);
  animation: lineIn 0.18s ease;
}
.line:last-child {
  border-bottom: none;
}
@keyframes lineIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.line-body {
  flex: 1;
  min-width: 0;
}
.line-name {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--ink);
  letter-spacing: -0.005em;
  margin-bottom: 2px;
}
.line-mods {
  font-size: 0.78rem;
  color: var(--warm-gray);
  line-height: 1.45;
}
.line-mods span + span::before {
  content: " · ";
  color: rgba(44, 26, 14, 0.3);
}
.line-controls {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
}
.qty {
  display: inline-flex;
  align-items: center;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: 999px;
  padding: 2px;
  gap: 2px;
}
.qty-btn {
  width: 24px;
  height: 24px;
  border-radius: 999px;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.1);
  color: var(--ink);
  font-size: 0.95rem;
  font-weight: 700;
  cursor: pointer;
  display: grid;
  place-items: center;
  line-height: 1;
  font-family: inherit;
  transition: background 0.15s, color 0.15s;
}
.qty-btn:hover {
  background: var(--cream-2);
  color: var(--terracotta-d);
}
.qty-num {
  min-width: 22px;
  text-align: center;
  font-size: 0.82rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.line-remove {
  background: none;
  border: none;
  color: var(--warm-gray);
  font-size: 0.78rem;
  font-family: inherit;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
  transition: color 0.15s, background 0.15s;
}
.line-remove:hover {
  color: var(--danger);
  background: rgba(179, 67, 42, 0.08);
}
.line-price {
  font-family: var(--font-mono);
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--ink);
  white-space: nowrap;
  padding-top: 2px;
}

.empty {
  text-align: center;
  font-style: italic;
  color: var(--warm-gray);
  padding: 24px 12px;
}

/* ── Tip ── */
.tip {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.tip-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ink-2);
  font-weight: 700;
}
.tip-presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.tip-btn {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.12);
  color: var(--ink-2);
  border-radius: 999px;
  padding: 6px 12px;
  font-family: inherit;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.tip-btn:hover {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}
.tip-btn.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.tip-custom {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.8rem;
  color: var(--ink-2);
}
.tip-custom input {
  width: 80px;
  padding: 6px 10px;
  border: 1px solid rgba(44, 26, 14, 0.12);
  background: var(--bone);
  border-radius: var(--r-sm);
  font-family: var(--font-mono);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--ink);
  outline: none;
  text-align: center;
}
.tip-custom input:focus {
  border-color: var(--terracotta);
}

/* ── Summary ── */
.summary {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-top: 4px;
}
.summary-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 0.88rem;
  color: var(--ink-2);
}
.summary-row dd {
  font-family: var(--font-mono);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.summary-row--total {
  margin-top: 6px;
  padding-top: 12px;
  border-top: 1px solid rgba(44, 26, 14, 0.18);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--ink);
}
.summary-row--total dd {
  font-size: 1.2rem;
  color: var(--ink);
}
.tip-tag {
  display: inline-block;
  background: var(--cream-2);
  color: var(--ink-2);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 2px 7px;
  border-radius: 999px;
