}
.print-btn:hover {
  background: var(--forest-d);
}

/* Paper */
.paper {
  padding: 36px 24px 64px;
  display: flex;
  justify-content: center;
}
.menu {
  width: 100%;
  max-width: 880px;
  background: var(--bone);
  padding: 56px 64px;
  border: 1px solid rgba(44, 26, 14, 0.1);
  box-shadow: var(--shadow-2);
  position: relative;
  color: var(--ink);
}
.menu::before,
.menu::after {
  content: "";
  position: absolute;
  left: 50%;
  width: 80px;
  height: 1px;
  background: var(--gold);
}
.menu::before {
  top: 36px;
  transform: translateX(-50%);
}
.menu::after {
  bottom: 36px;
  transform: translateX(-50%);
}

/* Header */
.menu-head {
  text-align: center;
  margin-bottom: 36px;
  padding-bottom: 16px;
  border-bottom: 1px solid rgba(44, 26, 14, 0.12);
}
.kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.24em;
  color: var(--terracotta);
  font-weight: 700;
  margin-bottom: 8px;
}
.menu-head h1 {
  font-family: var(--font-display);
  font-size: clamp(2.2rem, 5vw, 3.2rem);
  font-weight: 500;
  letter-spacing: -0.005em;
  line-height: 1.05;
}
.menu-head h1 em {
  font-style: italic;
  color: var(--terracotta-d);
  font-weight: 400;
}
.hours {
  margin-top: 14px;
  font-size: 0.86rem;
  color: var(--warm-gray);
  font-style: italic;
}

/* Two-column grid */
.menu-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
}
@media (max-width: 720px) {
  .menu-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .menu {
    padding: 36px 30px;
  }
}

/* Course */
.course {
  margin-bottom: 32px;
}
.course-title {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 700;
  margin-bottom: 14px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--terracotta);
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.course-sub {
  font-size: 0.74rem;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--warm-gray);
  font-weight: 600;
  font-family: var(--font-body);
}

/* Dishes (dotted leaders) */
.dishes {
  list-style: none;
}
.dishes > li {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 6px;
  align-items: baseline;
  font-size: 0.98rem;
  padding-top: 8px;
}
.dishes > li.dish-desc {
  display: block;
  font-size: 0.84rem;
  font-style: italic;
  color: var(--warm-gray);
  padding-top: 2px;
  padding-bottom: 6px;
  border-bottom: 1px dashed rgba(44, 26, 14, 0.1);
  margin-bottom: 4px;
}
.dish-name {
  font-weight: 600;
  color: var(--ink);
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
}
.dish-leader {
  border-bottom: 1px dotted rgba(44, 26, 14, 0.4);
  min-width: 24px;
  margin: 0 4px 4px;
  height: 0;
}
.dish-price {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.94rem;
  color: var(--terracotta-d);
}
.dish-price::before {
  content: "$";
  color: var(--warm-gray);
  margin-right: 1px;
  font-weight: 500;
}

/* Tags */
.tags {
  display: inline-flex;
  gap: 3px;
}
.tag {
  display: inline-grid;
  place-items: center;
  font-family: var(--font-mono);
  font-size: 0.6rem;
  font-weight: 700;
  width: 18px;
  height: 18px;
  border-radius: 999px;
  background: var(--cream-2);
  color: var(--ink-2);
  letter-spacing: -0.02em;
}
.tag-star {
  background: var(--gold);
  color: var(--ink);
}

/* Tasting pull-out */
.tasting {
  margin-top: 12px;
  margin-bottom: 36px;
  background: var(--forest);
  color: var(--bone);
  border-radius: var(--r-md);
  padding: 26px 28px;
}
.tasting-kicker {
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--gold-light);
  margin-bottom: 8px;
}
.tasting h3 {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 500;
  letter-spacing: -0.005em;
  line-height: 1.2;
}
.tasting-desc {
  margin-top: 10px;
  font-size: 0.92rem;
  color: rgba(250, 247, 241, 0.85);
}
.tasting-meta {
  margin-top: 14px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}
.tasting-meta div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.tasting-meta dt {
  font-size: 0.66rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gold-light);
  font-weight: 700;
}
.tasting-meta dd {
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--bone);
}
.tasting-meta dd.m {
  font-family: var(--font-mono);
}
@media (max-width: 720px) {
  .tasting-meta {
    grid-template-columns: 1fr;
  }
}

/* Bottom: wine + legend */
.bottom {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 32px;
  padding-top: 16px;
  border-top: 1px solid rgba(44, 26, 14, 0.12);
}
.bottom h2 {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: 12px;
  border-bottom: 1px solid var(--terracotta);
  padding-bottom: 6px;
}
.wine .dishes > li {
  font-size: 0.9rem;
}
.wine-note,
.legend-note {
  margin-top: 12px;
  font-size: 0.78rem;
  color: var(--warm-gray);
  font-style: italic;
}
.legend ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.legend li {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.88rem;
  color: var(--ink-2);
}
@media (max-width: 720px) {
  .bottom {
    grid-template-columns: 1fr;
    gap: 20px;
  }
}

/* Foot */
.menu-foot {
  margin-top: 36px;
  text-align: center;
  font-size: 0.76rem;
  color: var(--warm-gray);
  border-top: 1px solid rgba(44, 26, 14, 0.12);
  padding-top: 18px;
}
.foot-brand {
  margin-top: 6px;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.88rem;
  color: var(--ink-2);
  letter-spacing: 0.04em;
}

/* Print */
@media print {
  body {
    background: white;
  }
  .no-print {
    display: none !important;
  }
  .paper {
    padding: 0;
  }
  .menu {
    box-shadow: none;
    border: none;
    max-width: 100%;
    padding: 18mm 14mm;
  }
  .tasting {
    page-break-inside: avoid;
  }
  .course {
    page-break-inside: avoid;
  }
}

