  catsEl.innerHTML = Object.entries(MENU)
    .map(
      ([key, c]) => `
      <button class="cat-btn ${key === activeCat ? "is-active" : ""}" data-cat="${key}">
        <span class="cat-icon">${c.icon}</span>
        <span>${c.title}</span>
      </button>`
    )
    .join("");
}

function renderGrid() {
  const cat = MENU[activeCat];
  catTitle.textContent = cat.title;
  gridEl.innerHTML = cat.items
    .map(
      (item) => `
      <button class="tile" data-item="${item.id}" data-name="${item.name}" data-price="${item.price}">
        <span class="tile-name">${item.name}</span>
        <span class="tile-price">$${item.price.toFixed(2)}</span>
      </button>`
    )
    .join("");
}

function renderTicket() {
  const itemCount = ticket.reduce((n, l) => n + l.qty, 0);
  ticketMeta.textContent = `${itemCount} ${itemCount === 1 ? "item" : "items"}`;

  if (ticket.length === 0) {
    linesEl.innerHTML = "";
    emptyEl.style.display = "";
  } else {
    emptyEl.style.display = "none";
    linesEl.innerHTML = ticket
      .map(
        (l) => `
        <li class="line" data-id="${l.id}">
          <div class="line-qty">
            <button data-action="dec" aria-label="Decrease">−</button>
            <span>${l.qty}</span>
            <button data-action="inc" aria-label="Increase">+</button>
          </div>
          <span class="line-name">${l.name}</span>
          <span class="line-price">${money(l.price * l.qty)}</span>
        </li>`
      )
      .join("");
  }

  const subtotal = ticket.reduce((s, l) => s + l.price * l.qty, 0);
  const tax = subtotal * TAX_RATE;
  const total = subtotal + tax;

  subtotalEl.textContent = money(subtotal);
  taxEl.textContent = money(tax);
  totalEl.textContent = money(total);
  payTotalEl.textContent = money(total);
  payBtn.disabled = ticket.length === 0;
}

function addItem(id, name, price, tile) {
  const existing = ticket.find((l) => l.id === id);
  if (existing) existing.qty += 1;
  else ticket.push({ id, name, price, qty: 1 });
  renderTicket();
  if (tile) {
    tile.classList.remove("is-flash");
    void tile.offsetWidth; // restart animation
    tile.classList.add("is-flash");
  }
}

catsEl.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-cat]");
  if (!btn) return;
  activeCat = btn.dataset.cat;
  renderCats();
  renderGrid();
});

gridEl.addEventListener("click", (e) => {
  const tile = e.target.closest("[data-item]");
  if (!tile) return;
  addItem(tile.dataset.item, tile.dataset.name, Number(tile.dataset.price), tile);
});

linesEl.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action]");
  if (!btn) return;
  const li = btn.closest("[data-id]");
  if (!li) return;
  const line = ticket.find((l) => l.id === li.dataset.id);
  if (!line) return;
  if (btn.dataset.action === "inc") line.qty += 1;
  if (btn.dataset.action === "dec") {
    line.qty -= 1;
    if (line.qty <= 0) ticket = ticket.filter((l) => l.id !== line.id);
  }
  renderTicket();
});

clearBtn.addEventListener("click", () => {
  if (ticket.length === 0) return;
  ticket = [];
  renderTicket();
});

holdBtn.addEventListener("click", () => {
  holdBtn.textContent = "Held ✓";
  setTimeout(() => (holdBtn.textContent = "Hold"), 1400);
});

payBtn.addEventListener("click", () => {
  const txt = payBtn.querySelector("span").textContent;
  payBtn.querySelector("span").textContent = "Sent ✓";
  setTimeout(() => {
    payBtn.querySelector("span").textContent = txt;
    ticket = [];
    renderTicket();
  }, 900);
});

renderCats();
renderGrid();
renderTicket();

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
}
body {
  font-family: var(--font-body);
  background: linear-gradient(180deg, var(--ink) 0%, #1a0f06 100%);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
  user-select: none;
  display: grid;
  place-items: center;
  padding: 24px;
}

.kiosk {
  position: relative;
  width: 100%;
  max-width: 720px;
  height: min(96vh, 1080px);
  background: var(--ink);
  border-radius: 36px;
  padding: 18px;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6), inset 0 0 0 1px rgba(250, 247, 241, 0.04);
}
.frame {
  position: relative;
  height: 100%;
  background: var(--cream);
  border-radius: 26px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

/* Topbar */
.bar {
  height: 64px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 22px;
  background: var(--bone);
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
  position: relative;
  z-index: 5;
}
.bar-left {
  display: flex;
  align-items: baseline;
  gap: 14px;
}
.brand {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.15rem;
}
.bar-step {
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
  padding-left: 14px;
  border-left: 1px solid rgba(44, 26, 14, 0.16);
}
.bar-right {
  display: flex;
  align-items: center;
  gap: 8px;
}
.lang {
  width: 44px;
  height: 36px;
  border: 1px solid rgba(44, 26, 14, 0.16);
  background: transparent;
  color: var(--ink-2);
  font-family: inherit;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  border-radius: 8px;
  cursor: pointer;
}
.lang.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.cart-btn {
  position: relative;
  width: 56px;
  height: 48px;
  background: var(--forest);
  color: var(--bone);
  border: none;
  border-radius: 12px;
  font-family: inherit;
  font-size: 1.2rem;
  cursor: pointer;
  display: grid;
  place-items: center;
}
.cart-icon {
  font-size: 1.4rem;
}
.cart-count {
  position: absolute;
  top: -8px;
  right: -8px;
  background: var(--gold);
  color: var(--ink);
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  border-radius: 999px;
  min-width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  border: 2px solid var(--bone);
  padding: 0 6px;
}

/* Screens */
.screen {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  animation: fade 0.25s ease;
}
.screen[hidden] {
  display: none !important;
}
@keyframes fade {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* Welcome */
.screen-welcome {
  text-align: center;
  padding: 32px 36px 32px;
  justify-content: center;
  gap: 16px;
}
.welcome-art {
  position: relative;
  height: 200px;
  display: grid;
  place-items: center;
}
.welcome-art .glyph {
  position: absolute;
  font-size: 5rem;
  filter: drop-shadow(0 12px 28px rgba(44, 26, 14, 0.25));
  animation: floatY 5s ease-in-out infinite;
}
.welcome-art .g-1 {
  left: 18%;
  top: 30px;
  animation-delay: 0s;
}
.welcome-art .g-2 {
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  animation-delay: 1.2s;
}
.welcome-art .g-3 {
  right: 18%;
  top: 40px;
  animation-delay: 2.2s;
}
@keyframes floatY {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-14px);
  }
}
.welcome-art .g-2 {
  /* keep horizontal centre */
}
@keyframes floatYCentre {
  0%,
  100% {
    transform: translate(-50%, 0);
  }
  50% {
    transform: translate(-50%, -14px);
  }
}
.welcome-art .g-2 {
  animation-name: floatYCentre;
}
.welcome-kicker {
  font-size: 0.78rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.screen-welcome h1 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(2.4rem, 7vw, 3.6rem);
  line-height: 1.05;
  letter-spacing: -0.015em;
}
.screen-welcome h1 .em {
  font-style: italic;
  color: var(--terracotta);
}
.welcome-sub {
  font-size: 1.05rem;
  color: var(--warm-gray);
  margin-top: -4px;
}

.tap-cta {
  margin: 22px auto 0;
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 76px;
  min-width: 320px;
  background: var(--forest);
  color: var(--bone);
  border: none;
  border-radius: 999px;
  padding: 0 28px;
  font-family: inherit;
  font-size: 1.15rem;
  font-weight: 700;
  cursor: pointer;
  letter-spacing: 0.04em;
  transition: background 0.15s, transform 0.05s;
  box-shadow: 0 12px 30px rgba(45, 74, 62, 0.35);
}
.tap-cta:hover {
  background: var(--forest-d);
}
.tap-cta:active {
  transform: scale(0.98);
}
.tap-arrow {
  font-family: var(--font-mono);
  font-size: 1.5rem;
  background: rgba(250, 247, 241, 0.18);
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 999px;
}
.quiet-cta {
  background: transparent;
  border: 1px solid rgba(44, 26, 14, 0.18);
  color: var(--ink-2);
  font-family: inherit;
  font-size: 0.94rem;
  font-weight: 600;
  border-radius: 999px;
  padding: 12px 22px;
  cursor: pointer;
  min-height: 48px;
  margin-top: 4px;
}
.quiet-cta:hover {
  background: var(--cream-2);
  color: var(--ink);
}

/* Screen head shared */
.screen-head {
  padding: 20px 28px 12px;
  position: relative;
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
}
.screen-head h2 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(1.8rem, 5vw, 2.4rem);
  letter-spacing: -0.015em;
}
.screen-head p {
  margin-top: 4px;
  font-size: 0.96rem;
  color: var(--warm-gray);
}
.back {
  position: absolute;
  top: 18px;
  left: 18px;
  background: var(--cream-2);
  border: none;
  font-family: inherit;
  font-size: 0.86rem;
  font-weight: 700;
  color: var(--ink-2);
  padding: 8px 14px;
  border-radius: 999px;
  cursor: pointer;
}
.back:hover {
  background: var(--cream);
}
.screen-head:has(.back) h2 {
  margin-top: 30px;
}

/* Categories */
.cat-grid {
  flex: 1;
  overflow-y: auto;
  padding: 20px 28px 12px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  align-content: start;
}
.cat-tile {
  background: var(--bone);
  border: 2px solid rgba(44, 26, 14, 0.08);
  border-radius: 18px;
  min-height: 132px;
  padding: 20px 22px;
  text-align: left;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 8px;
  font-family: inherit;
  color: var(--ink);
  transition: border-color 0.15s, background 0.15s, transform 0.05s;
}
.cat-tile:hover {
  border-color: var(--terracotta);
}
.cat-tile:active {
  transform: scale(0.98);
}
.cat-tile.is-picked {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.cat-tile-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.cat-glyph {
  font-size: 2.2rem;
}
.cat-pick-count {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  background: var(--gold);
  color: var(--ink);
  border-radius: 999px;
  min-width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  padding: 0 9px;
}
.cat-name {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.3rem;
  letter-spacing: -0.005em;
}
.cat-desc {
  font-size: 0.84rem;
  color: var(--warm-gray);
}
.cat-tile.is-picked .cat-desc {
  color: var(--gold-light);
}

/* Items */
.item-grid {
  flex: 1;
  overflow-y: auto;
  padding: 18px 24px 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.item-row {
  display: grid;
  grid-template-columns: 64px 1fr auto;
  gap: 16px;
  align-items: center;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 16px;
  padding: 14px 18px;
}
.item-art {
  width: 64px;
  height: 64px;
  border-radius: 12px;
  background: var(--cream-2);
  display: grid;
  place-items: center;
  font-size: 1.8rem;
}
.item-body {
  min-width: 0;
}
.item-name {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.15rem;
  line-height: 1.2;
}
.item-desc {
  font-size: 0.82rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.item-price {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--terracotta-d);
  margin-top: 4px;
  font-size: 0.95rem;
}
.item-qty {
  display: flex;
  align-items: center;
  background: var(--cream-2);
  border-radius: 999px;
  gap: 4px;
  padding: 4px;
}
.item-qty button {
  width: 44px;
  height: 44px;
  border: none;
  background: var(--bone);
  border-radius: 999px;
  font-family: inherit;
  font-size: 1.4rem;
  font-weight: 700;
  cursor: pointer;
  display: grid;
  place-items: center;
}
.item-qty button.add {
  background: var(--forest);
  color: var(--bone);
}
.item-qty button.add:hover {
  background: var(--forest-d);
}
.item-qty button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}
.item-qty span {
  min-width: 28px;
  text-align: center;
  font-weight: 700;
  font-family: var(--font-mono);
  font-size: 1.05rem;
}

/* Cart */
.cart-lines {
  flex: 1;
  overflow-y: auto;
  padding: 16px 24px;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.cart-empty {
  flex: 1;
  display: grid;
  place-items: center;
  color: var(--warm-gray);
  font-style: italic;
  padding: 24px;
  text-align: center;
}
.cart-row {
  display: grid;
  grid-template-columns: 40px 1fr auto auto;
  gap: 14px;
  align-items: center;
  padding: 12px 16px;
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 12px;
  background: var(--bone);
}
.cart-row .item-art {
  width: 40px;
  height: 40px;
  font-size: 1.3rem;
  border-radius: 8px;
}
.cart-name {
  font-weight: 700;
  font-size: 0.98rem;
}
.cart-qty {
  display: flex;
  align-items: center;
  background: var(--cream-2);
  border-radius: 999px;
  padding: 3px;
  gap: 2px;
}
.cart-qty button {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  border: none;
  background: var(--bone);
  font-family: inherit;
  font-size: 1.15rem;
  font-weight: 700;
  cursor: pointer;
  display: grid;
  place-items: center;
}
.cart-qty span {
  min-width: 22px;
  text-align: center;
  font-family: var(--font-mono);
  font-weight: 700;
}
.cart-row-price {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.98rem;
  color: var(--terracotta-d);
  min-width: 64px;
  text-align: right;
}

.cart-totals {
  padding: 12px 24px 4px;
  border-top: 1px dashed rgba(44, 26, 14, 0.18);
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.cart-totals div {
  display: flex;
  justify-content: space-between;
  font-size: 0.94rem;
  color: var(--ink-2);
}
.cart-totals dd {
  font-family: var(--font-mono);
  font-weight: 700;
}
.cart-totals .big {
  margin-top: 4px;
  padding-top: 8px;
  border-top: 1px solid rgba(44, 26, 14, 0.16);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--ink);
}
.cart-totals .big dd {
  font-size: 1.3rem;
  color: var(--ink);
}

/* Pay */
.pay-options {
  flex: 1;
  overflow-y: auto;
  padding: 22px 24px 12px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.pay-card {
  position: relative;
  background: var(--bone);
  border: 2px solid rgba(44, 26, 14, 0.1);
  border-radius: 18px;
  padding: 22px 24px;
  text-align: left;
  cursor: pointer;
  display: grid;
  grid-template-columns: 64px 1fr;
  gap: 16px;
  font-family: inherit;
  color: var(--ink);
  transition: border-color 0.15s, background 0.15s, transform 0.05s;
}
.pay-card:hover {
  border-color: var(--forest);
}
.pay-card:active {
  transform: scale(0.99);
}
.pay-icon {
  width: 64px;
  height: 64px;
  background: var(--cream-2);
  border-radius: 16px;
  display: grid;
  place-items: center;
  font-size: 2rem;
}
.pay-card h3 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.4rem;
}
.pay-card p {
  color: var(--warm-gray);
  font-size: 0.92rem;
  margin-top: 2px;
}
.pay-tag {
  position: absolute;
  top: 16px;
  right: 18px;
  background: var(--gold);
  color: var(--ink);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
}

/* Footer (per screen) */
.screen-foot {
  padding: 16px 24px 22px;
  border-top: 1px solid rgba(44, 26, 14, 0.08);
  background: var(--bone);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}
.ghost-cta,
.primary-cta {
  min-height: 64px;
  border-radius: 999px;
  padding: 0 26px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.ghost-cta {
  background: transparent;
  border-color: rgba(44, 26, 14, 0.2);
  color: var(--ink-2);
}
.ghost-cta:hover {
  background: var(--cream-2);
  color: var(--ink);
}
.primary-cta {
  background: var(--forest);
  color: var(--bone);
  flex: 1;
}
.primary-cta:hover:not(:disabled) {
  background: var(--forest-d);
}
.primary-cta:disabled {
  background: var(--warm-gray);
  cursor: not-allowed;
  opacity: 0.7;
}
.pay-total {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.5rem;
  color: var(--ink);
}

/* Reveal */
.screen-reveal {
  text-align: center;
  padding: 40px 32px;
  justify-content: center;
  gap: 16px;
}
.reveal-eyebrow {
  font-size: 0.78rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.reveal-no {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(4rem, 14vw, 7rem);
  color: var(--forest);
  line-height: 1;
  letter-spacing: -0.02em;
}
.screen-reveal h2 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(1.8rem, 5vw, 2.4rem);
  letter-spacing: -0.015em;
  margin-top: -8px;
}
.reveal-sub {
  font-size: 1rem;
  color: var(--warm-gray);
  max-width: 480px;
  margin: 0 auto;
}
.reveal-meta {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 16px;
  padding: 20px 26px;
  max-width: 460px;
  margin: 12px auto 0;
}
.reveal-meta dl {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px 18px;
}
.reveal-meta dt {
  font-size: 0.68rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--warm-gray);
  font-weight: 700;
}
.reveal-meta dd {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--ink);
  margin-top: 2px;
}

