const TAX_RATE = 0.0825;

const CATS = [
  { id: "bowls", name: "Grain bowls", glyph: "🥗", desc: "Build your own · 6 bases" },
  { id: "tacos", name: "Tacos", glyph: "🌮", desc: "3 per order · 8 fillings" },
