      glyph: "🫘",
    },
  ],
  tacos: [
    {
      id: "taco-1",
      name: "Al pastor · 3 pcs",
      desc: "Achiote pork, pineapple, cilantro.",
      price: 12,
      glyph: "🌮",
    },
    {
      id: "taco-2",
      name: "Baja fish · 3 pcs",
      desc: "Crispy cod, chipotle slaw, lime.",
      price: 14,
      glyph: "🐟",
    },
    {
      id: "taco-3",
      name: "Carnitas · 3 pcs",
      desc: "Slow pork, salsa verde, queso fresco.",
      price: 13,
      glyph: "🐖",
    },
    {
      id: "taco-4",
      name: "Hongos · 3 pcs",
      desc: "Wild mushroom, garlic, jalapeño.",
      price: 12,
      glyph: "🍄",
    },
  ],
  sandwiches: [
    {
      id: "s-1",
      name: "Roasted veg ciabatta",
      desc: "Aubergine, pepper, pesto.",
      price: 11,
      glyph: "🥪",
    },
    {
      id: "s-2",
      name: "Pulled pork bun",
      desc: "Slow shoulder, pickled onion.",
      price: 13,
      glyph: "🍔",
    },
    {
      id: "s-3",
      name: "Chicken focaccia",
      desc: "Aioli, rocket, sun tomato.",
      price: 12,
      glyph: "🥖",
    },
  ],
  sides: [
    { id: "side-1", name: "Truffle fries", desc: "Parmesan, parsley.", price: 8, glyph: "🍟" },
    { id: "side-2", name: "Charred broccoli", desc: "Lemon, chilli oil.", price: 7, glyph: "🥦" },
    { id: "side-3", name: "Tomato soup", desc: "Basil, crème fraîche.", price: 7, glyph: "🍅" },
    {
      id: "side-4",
      name: "House salad",
      desc: "Leaves, herbs, vinaigrette.",
      price: 8,
      glyph: "🥬",
    },
  ],
  drinks: [
    { id: "d-1", name: "Hibiscus agua fresca", desc: "Sweetened lightly.", price: 5, glyph: "🌺" },
    { id: "d-2", name: "Tamarind agua fresca", desc: "Salt-rim available.", price: 5, glyph: "🥤" },
    { id: "d-3", name: "Sparkling water", desc: "Local, on tap.", price: 3, glyph: "💧" },
    {
      id: "d-4",
      name: "Cold brew coffee",
      desc: "From Tuesday-fresh beans.",
      price: 4,
      glyph: "☕",
    },
  ],
  sweets: [
    { id: "sw-1", name: "Tres leches cake", desc: "Cinnamon dust.", price: 7, glyph: "🍰" },
    {
      id: "sw-2",
      name: "Sorbete cítrico",
      desc: "Citrus, mint, today's batch.",
      price: 6,
      glyph: "🍧",
    },
    { id: "sw-3", name: "Olive oil cookie", desc: "Sea salt, two pieces.", price: 4, glyph: "🍪" },
  ],
};

const STEP_LABELS = {
  welcome: "Welcome",
  categories: "Step 1 of 3 · Categories",
  items: "Step 2 of 3 · Choose dishes",
  cart: "Step 3 of 3 · Review",
  pay: "Pay",
  reveal: "Order placed",
};

let currentScreen = "welcome";
let currentCat = null;
let cart = []; // { id, name, price, qty, glyph }

const stepLabel = document.getElementById("stepLabel");
const catGrid = document.getElementById("catGrid");
const itemGrid = document.getElementById("itemGrid");
const catTitle = document.getElementById("catTitle");
const catSub = document.getElementById("catSub");
const cartLines = document.getElementById("cartLines");
const cartEmpty = document.getElementById("cartEmpty");
const cartCountSub = document.getElementById("cartCountSub");
const cartCount = document.getElementById("cartCount");
const cartBtn = document.getElementById("cartBtn");
const subtotalEl = document.getElementById("subtotal");
const taxEl = document.getElementById("tax");
const totalEl = document.getElementById("total");
const payTotalEl = document.getElementById("payTotal");
const goPayBtn = document.getElementById("goPay");
const goCart = document.getElementById("goCart");
const goCart2 = document.getElementById("goCart2");
const clearBtn = document.getElementById("clear");

function money(v) {
  return `$${v.toFixed(2)}`;
}

function go(screen) {
  if (screen === currentScreen) return;
  currentScreen = screen;
  document.querySelectorAll("[data-screen]").forEach((el) => {
    el.hidden = el.dataset.screen !== screen;
  });
  stepLabel.textContent = STEP_LABELS[screen] || screen;
  // Cart icon only visible after at least one item is added.
  cartBtn.hidden = cart.length === 0 || screen === "welcome" || screen === "reveal";
  if (screen === "categories") renderCats();
  if (screen === "items") renderItems();
  if (screen === "cart") renderCart();
}

function totals() {
  const subtotal = cart.reduce((s, l) => s + l.price * l.qty, 0);
  const tax = subtotal * TAX_RATE;
  return { subtotal, tax, total: subtotal + tax };
}

function renderCats() {
  catGrid.innerHTML = CATS.map((c) => {
    const picks = cart
      .filter((line) => ITEMS[c.id]?.some((i) => i.id === line.id))
      .reduce((n, l) => n + l.qty, 0);
    return `<button class="cat-tile ${picks > 0 ? "is-picked" : ""}" data-cat="${c.id}">
      <div class="cat-tile-row">
        <span class="cat-glyph">${c.glyph}</span>
        ${picks > 0 ? `<span class="cat-pick-count">${picks}</span>` : ""}
      </div>
      <div>
        <p class="cat-name">${c.name}</p>
        <p class="cat-desc">${c.desc}</p>
      </div>
    </button>`;
  }).join("");
  const count = cart.reduce((n, l) => n + l.qty, 0);
  goCart.disabled = count === 0;
  goCart.textContent = count === 0 ? "Pick a dish to continue" : `Review order →  ${count}`;
}

function renderItems() {
  const cat = CATS.find((c) => c.id === currentCat);
  if (!cat) return;
  catTitle.textContent = cat.name;
  catSub.textContent = cat.desc;
  itemGrid.innerHTML = ITEMS[currentCat]
    .map((i) => {
      const line = cart.find((l) => l.id === i.id);
      const qty = line ? line.qty : 0;
      return `<article class="item-row">
        <div class="item-art">${i.glyph}</div>
        <div class="item-body">
          <p class="item-name">${i.name}</p>
          <p class="item-desc">${i.desc}</p>
          <p class="item-price">${money(i.price)}</p>
        </div>
        <div class="item-qty" data-id="${i.id}" data-name="${i.name}" data-price="${i.price}" data-glyph="${i.glyph}">
          <button data-action="dec" aria-label="One fewer" ${qty === 0 ? "disabled" : ""}>−</button>
          <span>${qty}</span>
          <button class="add" data-action="inc" aria-label="One more">+</button>
        </div>
      </article>`;
    })
    .join("");
}

function renderCart() {
  const count = cart.reduce((n, l) => n + l.qty, 0);
  cartCountSub.textContent = count === 0 ? "0 items" : `${count} ${count === 1 ? "item" : "items"}`;
  cartCount.textContent = count;
  cartEmpty.hidden = cart.length > 0;
  cartLines.innerHTML = cart
    .map(
      (l) => `<li class="cart-row" data-id="${l.id}">
      <div class="item-art">${l.glyph}</div>
      <div>
        <p class="cart-name">${l.name}</p>
      </div>
      <div class="cart-qty">
        <button data-action="dec">−</button>
        <span>${l.qty}</span>
        <button data-action="inc">+</button>
      </div>
      <span class="cart-row-price">${money(l.price * l.qty)}</span>
    </li>`
    )
    .join("");
  const t = totals();
  subtotalEl.textContent = money(t.subtotal);
  taxEl.textContent = money(t.tax);
  totalEl.textContent = money(t.total);
  payTotalEl.textContent = money(t.total);
  goPayBtn.disabled = cart.length === 0;
}

function changeQty(id, delta, src) {
  const existing = cart.find((l) => l.id === id);
  if (delta > 0) {
    if (existing) existing.qty += 1;
    else if (src)
      cart.push({
        id,
        name: src.name,
        price: Number(src.price),
        glyph: src.glyph,
        qty: 1,
      });
  } else if (existing) {
    existing.qty -= 1;
    if (existing.qty <= 0) cart = cart.filter((l) => l.id !== id);
  }
  // Reflect cart count in topbar
  const count = cart.reduce((n, l) => n + l.qty, 0);
  cartCount.textContent = count;
  cartBtn.hidden = count === 0 || currentScreen === "welcome" || currentScreen === "reveal";
  if (currentScreen === "items") renderItems();
  if (currentScreen === "cart") renderCart();
  if (currentScreen === "categories") renderCats();
}

// Click delegation for screen navigation
document.body.addEventListener("click", (e) => {
  const goBtn = e.target.closest("[data-go]");
  if (goBtn) {
    if (goBtn.dataset.go === "welcome") {
      cart = [];
      cartCount.textContent = 0;
    }
    go(goBtn.dataset.go);
    return;
  }
  // Cart button in topbar
  if (e.target.closest("#cartBtn")) {
    go("cart");
    return;
  }
});

catGrid.addEventListener("click", (e) => {
  const tile = e.target.closest("[data-cat]");
  if (!tile) return;
  currentCat = tile.dataset.cat;
  go("items");
});

itemGrid.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action]");
  if (!btn) return;
  const wrap = btn.closest("[data-id]");
  const id = wrap.dataset.id;
  changeQty(id, btn.dataset.action === "inc" ? 1 : -1, {
    name: wrap.dataset.name,
    price: wrap.dataset.price,
    glyph: wrap.dataset.glyph,
  });
});

cartLines.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action]");
  if (!btn) return;
  const row = btn.closest("[data-id]");
  if (!row) return;
  changeQty(row.dataset.id, btn.dataset.action === "inc" ? 1 : -1);
});

clearBtn.addEventListener("click", () => {
  if (cart.length === 0) return;
  cart = [];
  renderCart();
  cartCount.textContent = 0;
  cartBtn.hidden = true;
});

[goCart, goCart2].forEach((btn) =>
  btn.addEventListener("click", () => {
    if (cart.length === 0) return;
    go("cart");
  })
);
goPayBtn.addEventListener("click", () => {
  if (cart.length === 0) return;
  go("pay");
});

// Pay choices
document.querySelectorAll("[data-pay]").forEach((card) =>
  card.addEventListener("click", () => {
    const t = totals();
    const orderNo = `#${String(Math.floor(100 + Math.random() * 900))}`;
    document.getElementById("orderNo").textContent = orderNo;
    document.getElementById("revealItems").textContent = cart.reduce((n, l) => n + l.qty, 0);
    document.getElementById("revealTotal").textContent = money(t.total);
    const eta = new Date();
    eta.setMinutes(eta.getMinutes() + 9);
    document.getElementById("revealEta").textContent =
      `${String(eta.getHours()).padStart(2, "0")}:${String(eta.getMinutes()).padStart(2, "0")}`;
    const method = card.dataset.pay;
    document.getElementById("revealSub").textContent =
      method === "counter"
        ? "Take your number to the counter to pay · we'll plate while you do."
        : method === "apple"
          ? "Payment approved · pickup at the counter when called."
          : "Payment approved · enjoy.";
    go("reveal");
  })
);

// Language switcher (visual only)
document.querySelectorAll(".lang").forEach((b) =>
  b.addEventListener("click", () => {
    document.querySelectorAll(".lang").forEach((x) => x.classList.remove("is-active"));
    b.classList.add("is-active");
  })
);

renderCats();

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}
.app {
  height: 100vh;
  display: grid;
  grid-template-columns: 248px 1fr;
}

/* Rail (shared) */
.rail {
  background: var(--forest);
  color: var(--bone);
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--forest-d);
  overflow-y: auto;
}
.rail-brand {
  padding: 22px 22px 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid rgba(250, 247, 241, 0.1);
}
.brand-mark {
  width: 36px;
  height: 36px;
  background: var(--gold);
  color: var(--ink);
  font-family: var(--font-display);
  font-weight: 800;
  border-radius: 8px;
  display: grid;
  place-items: center;
}
.brand-name {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.05rem;
}
.rail-nav {
  flex: 1;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.r-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: 8px;
  text-decoration: none;
  color: rgba(250, 247, 241, 0.78);
  font-size: 0.92rem;
  font-weight: 500;
}
.r-link:hover {
  background: rgba(250, 247, 241, 0.06);
  color: var(--bone);
}
.r-link.is-active {
  background: var(--bone);
  color: var(--forest-d);
  font-weight: 700;
}
.r-icon {
  width: 22px;
  text-align: center;
}
.rail-foot {
  padding: 14px 16px;
  border-top: 1px solid rgba(250, 247, 241, 0.1);
}
.rail-user {
  display: flex;
  align-items: center;
  gap: 10px;
}
.user-avatar {
  width: 38px;
  height: 38px;
  background: var(--gold);
  color: var(--ink);
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-weight: 800;
}
.user-name {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--bone);
}
.user-role {
  font-size: 0.74rem;
  color: rgba(250, 247, 241, 0.5);
}

/* Main */
.main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.top {
  padding: 22px 28px 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  flex-shrink: 0;
}
.kicker {
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.top h1 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.8rem;
  letter-spacing: -0.01em;
}
.top-tools {
  display: flex;
  gap: 8px;
}
.ghost,
.primary {
  border-radius: 999px;
  padding: 9px 16px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid transparent;
}
.ghost {
  background: var(--bone);
  border-color: rgba(44, 26, 14, 0.12);
  color: var(--ink-2);
}
.ghost:hover {
  background: var(--cream-2);
  color: var(--ink);
}
.primary {
  background: var(--forest);
  color: var(--bone);
}
.primary:hover:not(:disabled) {
  background: var(--forest-d);
}
.primary:disabled,
.ghost:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.btn-quiet {
  background: transparent;
  border: 1px dashed rgba(44, 26, 14, 0.2);
  color: var(--ink-2);
  padding: 8px 16px;
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
}
.btn-quiet:hover {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}

/* Editor three-col */
.editor {
  flex: 1;
  display: grid;
  grid-template-columns: 220px 1fr 380px;
  min-height: 0;
  padding: 0 28px 28px;
  gap: 14px;
}

/* Categories */
.cats {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 14px;
  padding: 14px 14px 10px;
  overflow-y: auto;
}
.cats-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}
.cats-title {
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--warm-gray);
  font-weight: 700;
}
.add-btn {
  width: 28px;
  height: 28px;
  background: var(--cream-2);
  border: none;
  border-radius: 8px;
  font-family: var(--font-mono);
  font-size: 1.05rem;
  cursor: pointer;
  color: var(--ink);
}
.add-btn:hover {
  background: var(--terracotta);
  color: var(--bone);
}
.cat-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.cat-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.9rem;
  color: var(--ink-2);
}
.cat-list li:hover {
  background: var(--cream-2);
}
.cat-list li.is-active {
  background: var(--forest);
  color: var(--bone);
  font-weight: 700;
}
.cat-list .count {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--warm-gray);
  background: var(--cream);
  padding: 2px 7px;
  border-radius: 999px;
  font-weight: 700;
}
.cat-list li.is-active .count {
  background: rgba(250, 247, 241, 0.16);
  color: var(--gold-light);
}

/* Items */
.items {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 14px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.items-head {
  padding: 16px 18px 12px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 12px;
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
  flex-shrink: 0;
}
.items-head h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.2rem;
  margin-top: 2px;
}
.items-tools {
  display: flex;
  gap: 6px;
  align-items: center;
}
.items-tools input {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.1);
  padding: 8px 14px;
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.82rem;
  color: var(--ink);
  outline: none;
  width: 160px;
}
.items-tools input:focus {
  border-color: var(--terracotta);
}
.items-tools .primary {
  padding: 8px 14px;
  font-size: 0.8rem;
}

.item-list {
  list-style: none;
  flex: 1;
  overflow-y: auto;
  padding: 10px 14px;
}
.item-row {
  display: grid;
  grid-template-columns: 34px 1fr auto auto;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid transparent;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.item-row:hover {
  background: var(--cream-2);
}
.item-row.is-active {
  background: var(--cream);
  border-color: var(--terracotta);
}
.item-grip {
  color: var(--warm-gray);
  font-family: var(--font-mono);
  font-size: 0.94rem;
  cursor: grab;
  user-select: none;
  text-align: center;
}
.item-grip::before {
  content: "⋮⋮";
  letter-spacing: -2px;
}
.item-info {
  min-width: 0;
}
.item-name {
  font-weight: 700;
}
.item-meta {
  font-size: 0.74rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.item-price {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--terracotta-d);
}
.item-vis {
  width: 36px;
  height: 22px;
  border-radius: 999px;
  background: var(--cream-2);
  position: relative;
  border: none;
  cursor: pointer;
}
.item-vis::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 18px;
  height: 18px;
  background: var(--bone);
  border-radius: 999px;
  transition: transform 0.18s;
}
.item-vis.is-on {
  background: var(--forest);
}
.item-vis.is-on::after {
  transform: translateX(14px);
  background: var(--gold);
}
.empty {
  flex: 1;
  display: grid;
  place-items: center;
  padding: 24px;
  color: var(--warm-gray);
  font-style: italic;
}

/* Edit panel */
.edit {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 14px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}
.edit-empty {
  flex: 1;
  display: grid;
  place-items: center;
  padding: 36px 24px;
  color: var(--warm-gray);
  font-style: italic;
  text-align: center;
}
.edit-form {
  display: flex;
  flex-direction: column;
}
.edit-head {
  padding: 18px 20px 14px;
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
}
.edit-eyebrow {
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.head-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 6px;
}
.title-input {
  flex: 1;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.35rem;
  border: none;
  background: transparent;
  color: var(--ink);
  outline: none;
  padding: 0;
}
.title-input:focus {
  outline: 1px dashed var(--terracotta);
  outline-offset: 4px;
}
.vis-toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--cream-2);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: 999px;
  padding: 5px 12px;
  font-family: inherit;
  font-size: 0.76rem;
  font-weight: 700;
  color: var(--ink-2);
  cursor: pointer;
}
.vis-toggle .dot {
  width: 8px;
  height: 8px;
  background: var(--success);
  border-radius: 999px;
}
.vis-toggle[aria-pressed="false"] .dot {
  background: var(--warm-gray);
}
.vis-toggle[aria-pressed="false"] .vis-label::before {
  content: "Hidden";
}
.vis-toggle[aria-pressed="false"] .vis-label {
  visibility: hidden;
}
.vis-toggle[aria-pressed="false"] .vis-label::before {
  visibility: visible;
  position: absolute;
}
/* Cleaner: just swap text via data-attr in JS */
.vis-toggle .vis-label {
  position: relative;
}

.grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  padding: 14px 20px 0;
}
.f {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 12px 20px 0;
}
.f span {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-2);
  font-weight: 700;
}
.f input,
.f textarea,
.f select {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: 8px;
  padding: 10px 12px;
  font-family: inherit;
  font-size: 0.94rem;
  color: var(--ink);
  outline: none;
  resize: vertical;
}
.f input:focus,
.f textarea:focus,
.f select:focus {
  border-color: var(--terracotta);
}
.grid-2 .f {
  padding: 0;
}
.prefix {
  display: inline-flex;
  align-items: stretch;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: 8px;
  overflow: hidden;
}
.prefix span {
  padding: 0 12px;
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--warm-gray);
  display: grid;
  place-items: center;
  background: var(--cream-2);
}
.prefix input {
  border: none;
  background: transparent;
  padding: 10px 12px;
  font-family: var(--font-mono);
  font-size: 0.94rem;
  font-weight: 700;
  width: 100%;
  outline: none;
  color: var(--ink);
}

.chips-field {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 14px 20px 0;
  border: none;
}
.chips-field legend {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-2);
  font-weight: 700;
  margin-bottom: 8px;
  width: 100%;
}
.ch {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  padding: 6px 12px;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  user-select: none;
}
.ch input {
  margin: 0;
  accent-color: var(--forest);
}
.ch:has(input:checked) {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}

/* Mods */
.mods {
  margin: 14px 20px 0;
  border: 1px solid rgba(44, 26, 14, 0.1);
  border-radius: 10px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.mods legend {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-2);
  font-weight: 700;
  padding: 0 6px;
}
.mod-group {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 8px;
  padding: 10px 12px;
}
.mod-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 6px;
}
.mod-head strong {
  font-weight: 700;
}
.mod-meta {
  font-size: 0.7rem;
  color: var(--warm-gray);
  font-style: italic;
}
.mod-group ul {
  list-style: none;
}
.mod-group li {
  display: flex;
  justify-content: space-between;
  padding: 5px 0;
  font-size: 0.86rem;
  border-bottom: 1px dashed rgba(44, 26, 14, 0.08);
}
.mod-group li:last-child {
  border-bottom: none;
}
.mod-group .m {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--terracotta-d);
}

/* Edit foot */
.edit-foot {
  position: sticky;
  bottom: 0;
  background: var(--bone);
  border-top: 1px solid rgba(44, 26, 14, 0.08);
  padding: 12px 20px;
  margin-top: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}
.save-meta {
  font-size: 0.78rem;
  color: var(--warm-gray);
}
.save-meta.is-dirty {
  color: var(--warning);
  font-weight: 700;
}
.foot-tools {
  display: flex;
  gap: 8px;
}

/* Toast */
.toast {
  position: fixed;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--forest-d);
  color: var(--bone);
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.18);
  z-index: 10;
}

/* Responsive */
@media (max-width: 1180px) {
  .editor {
    grid-template-columns: 200px 1fr 340px;
  }
}
@media (max-width: 980px) {
  .editor {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto 1fr;
    overflow: auto;
  }
  .cats {
    max-height: 240px;
  }
  .items {
    max-height: 380px;
  }
}
@media (max-width: 720px) {
  .app {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr;
  }
  .rail {
    flex-direction: row;
    overflow-x: auto;
    padding: 8px 12px;
    border-right: none;
    border-bottom: 1px solid var(--forest-d);
  }
  .rail-brand,
  .rail-foot {
    display: none;
  }
  .rail-nav {
    flex-direction: row;
    padding: 0;
  }
}

