:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: linear-gradient(180deg, var(--cream) 0%, var(--cream-2) 100%);
  color: var(--ink);
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 32px 16px 40px;
  -webkit-font-smoothing: antialiased;
}
.page {
  width: 100%;
  max-width: 520px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.card {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 18px;
  padding: 24px 24px 20px;
  box-shadow: 0 12px 36px rgba(44, 26, 14, 0.12);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 14px;
}
.kicker {
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.head h1 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.7rem;
  letter-spacing: -0.015em;
  margin-top: 2px;
}
.status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.78rem;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.1);
  padding: 6px 12px;
  border-radius: 999px;
  color: var(--ink-2);
  font-weight: 600;
  white-space: nowrap;
}
.status .dot {
  width: 8px;
  height: 8px;
  background: var(--warm-gray);
  border-radius: 999px;
}
.status[data-s="sent"] .dot {
  background: var(--warning);
  animation: pulse 1.2s ease-in-out infinite;
}
.status[data-s="ontheway"] .dot {
  background: var(--terracotta);
  animation: pulse 1.2s ease-in-out infinite;
}
.status[data-s="done"] .dot {
  background: var(--success);
}
@keyframes pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 currentColor;
    opacity: 1;
  }
  50% {
    box-shadow: 0 0 0 4px transparent;
    opacity: 0.45;
  }
}

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
@media (max-width: 480px) {
  .grid {
    grid-template-columns: 1fr;
  }
}
.action {
  background: var(--cream);
  border: 1.5px solid rgba(44, 26, 14, 0.1);
  border-radius: 12px;
  padding: 16px 18px 14px;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 4px;
  cursor: pointer;
  font-family: inherit;
  color: var(--ink);
  transition: border-color 0.15s, background 0.15s, transform 0.05s;
  min-height: 88px;
}
.action:hover:not(:disabled) {
  border-color: var(--terracotta);
}
.action:active:not(:disabled) {
  transform: scale(0.98);
}
.action:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.action.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.action.is-active .a-sub {
  color: rgba(250, 247, 241, 0.65);
}
.a-warn {
  border-color: rgba(217, 144, 32, 0.4);
  background: rgba(217, 144, 32, 0.07);
}
.a-warn .a-name {
  color: #8a5a1a;
}
.a-gold {
  border-color: var(--gold);
  background: rgba(201, 168, 76, 0.12);
}
.a-icon {
  font-size: 1.6rem;
}
.a-name {
  font-weight: 700;
  font-size: 1rem;
}
.a-sub {
  font-size: 0.78rem;
  color: var(--warm-gray);
}

.note {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.note > span {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-2);
  font-weight: 700;
}
.note input {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: 10px;
  padding: 10px 14px;
  font-family: inherit;
  font-size: 0.92rem;
  color: var(--ink);
  outline: none;
}
.note input:focus {
  border-color: var(--terracotta);
}

.state {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 12px;
  padding: 12px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}
.state-line {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 0.92rem;
}
.state-line strong {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--ink);
  font-size: 1.05rem;
}
.state-line span {
  color: var(--warm-gray);
  font-size: 0.78rem;
}
.cancel {
  background: transparent;
  border: 1px solid rgba(44, 26, 14, 0.16);
  border-radius: 999px;
  padding: 7px 14px;
  font-family: inherit;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--danger);
  cursor: pointer;
}
.cancel:hover {
  background: rgba(179, 67, 42, 0.06);
  border-color: var(--danger);
}

.footer-note {
  font-size: 0.78rem;
  color: var(--warm-gray);
  text-align: center;
  font-style: italic;
}

.last {
  text-align: center;
  font-size: 0.8rem;
  color: var(--warm-gray);
}
.last b {
  color: var(--ink-2);
}

