:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 14px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}
.app {
  height: 100vh;
  display: grid;
  grid-template-columns: 248px 1fr;
}

/* Rail (same as dashboard) */
.rail {
  background: var(--forest);
  color: var(--bone);
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--forest-d);
}
.rail-brand {
  padding: 22px 22px 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid rgba(250, 247, 241, 0.1);
}
.brand-mark {
  width: 36px;
  height: 36px;
  background: var(--gold);
  color: var(--ink);
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 0.92rem;
  border-radius: 8px;
  display: grid;
  place-items: center;
}
.brand-name {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.05rem;
}
.rail-nav {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 12px 12px 18px;
  gap: 2px;
}
.r-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: 8px;
  text-decoration: none;
  color: rgba(250, 247, 241, 0.78);
  font-size: 0.92rem;
  font-weight: 500;
}
.r-link:hover {
  background: rgba(250, 247, 241, 0.06);
  color: var(--bone);
}
.r-link.is-active {
  background: var(--bone);
  color: var(--forest-d);
  font-weight: 700;
}
.r-icon {
  font-size: 1rem;
  width: 22px;
  text-align: center;
}
.r-badge {
  margin-left: auto;
  background: var(--gold);
  color: var(--ink);
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 999px;
  min-width: 24px;
  text-align: center;
}
.r-badge-warn {
  background: var(--warning);
}
.rail-foot {
  padding: 14px 16px;
  border-top: 1px solid rgba(250, 247, 241, 0.1);
}
.rail-user {
  display: flex;
  align-items: center;
  gap: 10px;
}
.user-avatar {
  width: 38px;
  height: 38px;
  background: var(--terracotta);
  color: var(--bone);
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-weight: 800;
}
.user-name {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--bone);
}
.user-role {
  font-size: 0.74rem;
  color: rgba(250, 247, 241, 0.5);
}

/* Main */
.main {
  overflow-y: auto;
  padding: 28px 36px 56px;
}
.top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 22px;
  gap: 14px;
  flex-wrap: wrap;
}
.kicker {
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.top h1 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 2rem;
  letter-spacing: -0.015em;
}
.top-tools {
  display: flex;
  gap: 8px;
}
.ghost,
.primary {
  border-radius: 999px;
  padding: 9px 16px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid transparent;
}
.ghost {
  background: var(--bone);
  border-color: rgba(44, 26, 14, 0.12);
  color: var(--ink-2);
}
.ghost:hover {
  background: var(--cream-2);
  color: var(--ink);
}
.primary {
  background: var(--forest);
  color: var(--bone);
}
.primary:hover {
  background: var(--forest-d);
}

/* Status strip */
.status {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 22px;
}
@media (max-width: 980px) {
  .status {
    grid-template-columns: 1fr 1fr;
  }
}
.stat {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 16px 18px 14px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.stat-warn {
  border-left: 3px solid var(--warning);
}
.stat-danger {
  border-left: 3px solid var(--danger);
}
.stat-label {
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  color: var(--warm-gray);
  font-weight: 600;
}
.stat-value {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.7rem;
  letter-spacing: -0.005em;
}
.stat-value small {
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.84rem;
  color: var(--warm-gray);
}
.stat-meta {
  font-size: 0.72rem;
  color: var(--warm-gray);
  font-weight: 600;
}
.is-up {
  color: var(--success);
}

/* Toolbar */
.toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}
.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.chip {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.1);
  color: var(--ink-2);
  padding: 7px 14px;
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.chip span {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  background: var(--cream-2);
  color: var(--warm-gray);
  padding: 2px 7px;
  border-radius: 999px;
  font-weight: 700;
}
.chip:hover {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}
.chip.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.chip.is-active span {
  background: rgba(250, 247, 241, 0.18);
  color: var(--gold-light);
}
.search {
  display: inline-flex;
  align-items: center;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.1);
  padding: 7px 14px;
  border-radius: 999px;
  gap: 8px;
  color: var(--warm-gray);
}
.search input {
  background: transparent;
  border: none;
  outline: none;
  font-family: inherit;
  font-size: 0.86rem;
  color: var(--ink);
  width: 240px;
}

/* Table */
.table-wrap {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-lg);
  overflow: hidden;
}
.t {
  width: 100%;
  border-collapse: collapse;
}
.t thead {
  background: var(--cream-2);
}
.t th {
  text-align: left;
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--warm-gray);
  font-weight: 700;
  padding: 12px 16px;
}
.t td {
  padding: 14px 16px;
  border-top: 1px solid rgba(44, 26, 14, 0.06);
  font-size: 0.92rem;
  vertical-align: middle;
}
.col-stock {
  width: 220px;
}
.col-action {
  width: 140px;
  text-align: right;
}
.row-hidden {
  display: none !important;
}
.ing {
  display: flex;
  align-items: center;
  gap: 12px;
}
.ing-glyph {
  width: 34px;
  height: 34px;
  background: var(--cream-2);
  border-radius: 8px;
  display: grid;
  place-items: center;
  font-size: 1.15rem;
  flex-shrink: 0;
}
.ing-info {
  min-width: 0;
}
.ing-name {
  font-weight: 700;
}
.ing-code {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--warm-gray);
}
.supplier {
  font-weight: 600;
}
.supplier small {
  display: block;
  font-weight: 500;
  font-size: 0.74rem;
  color: var(--warm-gray);
}
.delivery {
  font-family: var(--font-mono);
  font-weight: 600;
}
.delivery small {
  display: block;
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 0.74rem;
  color: var(--warm-gray);
}

/* Par bar */
.par {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.par-text {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--ink-2);
}
.par-text strong {
  color: var(--ink);
}
.par-bar {
  height: 7px;
  background: var(--cream-2);
  border-radius: 999px;
  overflow: hidden;
}
.par-fill {
  height: 100%;
  background: var(--success);
  border-radius: 999px;
  transition: width 0.4s ease;
}
.par.is-warn .par-fill {
  background: var(--warning);
}
.par.is-danger .par-fill {
  background: var(--danger);
}
.par.is-warn .par-text strong {
  color: var(--warning);
}
.par.is-danger .par-text strong {
  color: var(--danger);
}

/* Actions */
.tag-86 {
  display: inline-block;
  background: var(--danger);
  color: var(--bone);
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.7rem;
  padding: 4px 8px;
  border-radius: 999px;
  letter-spacing: 0.06em;
}
.btn-reorder {
  background: var(--terracotta);
  color: var(--bone);
  border: none;
  font-family: inherit;
  font-size: 0.78rem;
  font-weight: 700;
  border-radius: 999px;
  padding: 7px 14px;
  cursor: pointer;
}
.btn-reorder:hover {
  background: var(--terracotta-d);
}
.btn-quiet {
  background: transparent;
  border: 1px solid rgba(44, 26, 14, 0.16);
  color: var(--warm-gray);
  font-family: inherit;
  font-size: 0.78rem;
  font-weight: 600;
  border-radius: 999px;
  padding: 7px 12px;
  cursor: pointer;
}
.btn-quiet:hover {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}

.empty-msg {
  text-align: center;
  padding: 36px 24px;
  color: var(--warm-gray);
  font-style: italic;
}

/* Toast */
.toast {
  position: fixed;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--forest-d);
  color: var(--bone);
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.18);
  z-index: 10;
}

@media (max-width: 880px) {
  .app {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr;
  }
  .rail {
    flex-direction: row;
    border-right: none;
    border-bottom: 1px solid var(--forest-d);
    overflow-x: auto;
    padding: 8px 12px;
  }
  .rail-brand,
  .rail-foot {
    display: none;
  }
  .rail-nav {
    flex-direction: row;
    padding: 0;
  }
  .t thead {
    display: none;
  }
  .t tr {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid rgba(44, 26, 14, 0.06);
  }
  .t td {
    padding: 0;
    border: none;
  }
  .t td.col-stock,
  .t td.col-action {
    grid-column: 1 / -1;
  }
}

