const CAT_LABEL = {
  produce: "Produce",
  meat: "Meat & fish",
  dairy: "Dairy",
  dry: "Dry goods",
  bev: "Beverages",
  misc: "Misc",
};

const rowsEl = document.getElementById("rows");
const emptyEl = document.getElementById("empty");
const chips = document.getElementById("chips");
const searchEl = document.getElementById("search");
const lowCountEl = document.getElementById("lowCount");
const outCountEl = document.getElementById("outCount");
const toast = document.getElementById("toast");

let cat = "all";
let q = "";

function relDate(dDays) {
  const d = new Date();
  d.setDate(d.getDate() + dDays);
  const iso = d.toISOString().slice(0, 10);
  let txt = "—";
  if (dDays === 0) txt = "today";
  else if (dDays === -1) txt = "yesterday";
  else if (dDays > -30) txt = `${Math.abs(dDays)} days ago`;
  else txt = `${Math.round(Math.abs(dDays) / 7)} weeks ago`;
  return { iso, txt };
}

function tone(item) {
  if (item.oos || item.stock === 0) return "is-danger";
  const ratio = item.stock / item.par;
  if (ratio <= 0.4) return "is-warn";
  return "";
}

function visible(item) {
  if (cat !== "all" && item.cat !== cat) return false;
  if (!q) return true;
  const haystack = `${item.name} ${item.supplier} ${item.code} ${item.region}`.toLowerCase();
  return haystack.includes(q);
}

function render() {
  let visibleCount = 0;
  let low = 0;
  let out = 0;
  rowsEl.innerHTML = ITEMS.map((item) => {
    const hidden = !visible(item);
    if (!hidden) visibleCount += 1;
    const t = tone(item);
    if (t === "is-warn") low += 1;
    if (t === "is-danger") out += 1;
    const pct = Math.min(100, Math.round((item.stock / Math.max(1, item.par)) * 100));
    const d = relDate(item.lastIso);
    return `<tr class="${hidden ? "row-hidden" : ""}" data-id="${item.id}">
      <td class="col-name">
        <div class="ing">
          <div class="ing-glyph">${item.glyph}</div>
          <div class="ing-info">
            <p class="ing-name">${item.name}</p>
            <p class="ing-code">${item.code} · ${CAT_LABEL[item.cat]}</p>
          </div>
        </div>
      </td>
      <td>
        <p class="supplier">${item.supplier}<small>${item.region}</small></p>
      </td>
      <td class="col-stock">
        <div class="par ${t}">
          <p class="par-text">
            <strong>${item.stock}</strong>
            <span>par ${item.par} · ${pct}%</span>
          </p>
          <div class="par-bar"><div class="par-fill" style="width:${pct}%"></div></div>
        </div>
      </td>
      <td>
        <p class="delivery">${d.txt}<small>${d.iso}${item.lastWeight ? ` · ${item.lastWeight}` : ""}</small></p>
      </td>
      <td class="col-action">
        ${
          item.oos
            ? `<span class="tag-86">86'd</span>`
            : t === ""
              ? `<button class="btn-quiet" data-action="adjust">Adjust</button>`
              : `<button class="btn-reorder" data-action="reorder" data-id="${item.id}">Reorder</button>`
        }
      </td>
    </tr>`;
  }).join("");

  lowCountEl.firstChild.textContent = String(low) + " ";
  outCountEl.firstChild.textContent = String(out) + " ";
  emptyEl.hidden = visibleCount > 0;
}

chips.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-cat]");
  if (!btn) return;
  cat = btn.dataset.cat;
  chips.querySelectorAll(".chip").forEach((c) => c.classList.toggle("is-active", c === btn));
  render();
});
searchEl.addEventListener("input", (e) => {
  q = e.target.value.trim().toLowerCase();
  render();
});

rowsEl.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action]");
  if (!btn) return;
  const action = btn.dataset.action;
  const id = btn.dataset.id;
  if (action === "reorder") {
    const item = ITEMS.find((i) => i.id === id);
    if (item) {
      item.stock = item.par;
      item.lastIso = 0;
      item.oos = false;
      render();
      showToast(`Reordered · ${item.name} to par`);
    }
  } else {
    showToast("Adjust panel would open here.");
  }
});

function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2400);
}

render();

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}
.app {
  height: 100vh;
  display: grid;
  grid-template-columns: 248px 1fr;
}

/* Rail (shared) */
.rail {
  background: var(--forest);
  color: var(--bone);
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--forest-d);
  overflow-y: auto;
}
.rail-brand {
  padding: 22px 22px 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid rgba(250, 247, 241, 0.1);
}
.brand-mark {
  width: 36px;
  height: 36px;
  background: var(--gold);
  color: var(--ink);
  border-radius: 8px;
  font-family: var(--font-display);
  font-weight: 800;
  display: grid;
  place-items: center;
}
.brand-name {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.05rem;
}
.rail-nav {
  flex: 1;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.r-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: 8px;
  text-decoration: none;
  color: rgba(250, 247, 241, 0.78);
  font-size: 0.92rem;
  font-weight: 500;
}
.r-link:hover {
  background: rgba(250, 247, 241, 0.06);
  color: var(--bone);
}
.r-link.is-active {
  background: var(--bone);
  color: var(--forest-d);
  font-weight: 700;
}
.r-icon {
  width: 22px;
  text-align: center;
}
.rail-foot {
  padding: 14px 16px;
  border-top: 1px solid rgba(250, 247, 241, 0.1);
}
.rail-user {
  display: flex;
  align-items: center;
  gap: 10px;
}
.user-avatar {
  width: 38px;
  height: 38px;
  background: var(--terracotta);
  color: var(--bone);
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-weight: 800;
}
.user-name {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--bone);
}
.user-role {
  font-size: 0.74rem;
  color: rgba(250, 247, 241, 0.5);
}

/* Main */
.main {
  overflow-y: auto;
  padding: 28px 32px 48px;
}
.top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 22px;
  gap: 14px;
  flex-wrap: wrap;
}
.kicker {
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.top h1 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 2rem;
  letter-spacing: -0.015em;
}
.top-tools {
  display: flex;
  gap: 6px;
}
.ghost,
.primary {
  border-radius: 999px;
  padding: 9px 16px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid transparent;
}
.ghost {
  background: var(--bone);
  border-color: rgba(44, 26, 14, 0.12);
  color: var(--ink-2);
}
.ghost:hover {
  background: var(--cream-2);
  color: var(--ink);
}
.primary {
  background: var(--forest);
  color: var(--bone);
}
.primary:hover {
  background: var(--forest-d);
}

/* Status */
.status {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 18px;
}
@media (max-width: 980px) {
  .status {
    grid-template-columns: 1fr 1fr;
  }
}
.stat {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 10px;
  padding: 14px 16px;
}
.stat-warn {
  border-left: 3px solid var(--warning);
}
.stat-label {
  font-size: 0.72rem;
  color: var(--warm-gray);
  font-weight: 600;
}
.stat-value {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.55rem;
  margin-top: 2px;
}
.stat-value small {
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.82rem;
  color: var(--warm-gray);
}
.stat-meta {
  font-size: 0.72rem;
  color: var(--warm-gray);
  margin-top: 2px;
  font-weight: 600;
}
.is-up {
  color: var(--success);
}

/* Chips */
.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 14px;
}
.chip {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.1);
  color: var(--ink-2);
  padding: 7px 14px;
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  gap: 6px;
}
.chip span {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  background: var(--cream-2);
  color: var(--warm-gray);
  padding: 2px 7px;
  border-radius: 999px;
}
.chip:hover {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}
.chip.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.chip.is-active span {
  background: rgba(250, 247, 241, 0.18);
  color: var(--gold-light);
}

/* Schedule grid */
.schedule {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 14px;
  overflow: hidden;
}
.sched-head,
.row {
  display: grid;
  grid-template-columns: 200px repeat(7, 1fr) 90px;
  align-items: stretch;
}
.sched-head {
  background: var(--cream-2);
}
.sched-head > div {
  padding: 12px 12px;
  border-right: 1px solid rgba(44, 26, 14, 0.08);
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--warm-gray);
  font-weight: 700;
}
.sched-head > div:last-child {
  border-right: none;
  text-align: right;
}
.sched-head .h-day {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.sched-head .h-num {
  font-family: var(--font-mono);
  font-size: 0.86rem;
  color: var(--ink);
  font-weight: 700;
  letter-spacing: 0;
}
.sched-head .is-today {
  background: var(--terracotta);
  color: var(--bone);
}
.sched-head .is-today .h-num {
  color: var(--bone);
}

.rows {
  list-style: none;
}
.row {
  border-top: 1px solid rgba(44, 26, 14, 0.06);
}
.row-hidden {
  display: none !important;
}
.r-cell {
  border-right: 1px solid rgba(44, 26, 14, 0.06);
  padding: 8px 8px;
  min-height: 86px;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.r-cell:last-child {
  border-right: none;
}
.r-person {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-right: 1px solid rgba(44, 26, 14, 0.06);
}
.r-avatar {
  width: 30px;
  height: 30px;
  border-radius: 999px;
  background: var(--cream-2);
  color: var(--ink);
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 0.82rem;
}
.r-name {
  font-weight: 700;
  font-size: 0.9rem;
}
.r-role {
  font-size: 0.7rem;
  color: var(--warm-gray);
}
.r-total {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 14px;
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--ink);
}

/* Shift pills */
.shift {
  border-radius: 4px;
  padding: 4px 6px;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 1px;
  line-height: 1.15;
  border: 1px solid transparent;
}
.shift .s-when {
  font-family: var(--font-mono);
  font-size: 0.66rem;
  font-weight: 700;
  opacity: 0.85;
}
.shift-kitchen {
  background: rgba(193, 113, 74, 0.18);
  color: var(--terracotta-d);
  border-color: rgba(193, 113, 74, 0.3);
}
.shift-floor {
  background: rgba(45, 74, 62, 0.16);
  color: var(--forest-d);
  border-color: rgba(45, 74, 62, 0.3);
}
.shift-bar {
  background: rgba(201, 168, 76, 0.22);
  color: #8a7325;
  border-color: rgba(201, 168, 76, 0.4);
}
.shift-open {
  background: var(--cream);
  color: var(--warm-gray);
  border: 1px dashed rgba(44, 26, 14, 0.32);
  text-align: center;
}
.shift-off {
  font-size: 0.72rem;
  color: var(--warm-gray);
  font-style: italic;
  font-weight: 500;
  align-self: center;
  letter-spacing: 0.04em;
}

/* Legend */
.legend-row {
  margin-top: 16px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  font-size: 0.78rem;
  color: var(--warm-gray);
}
.lg {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  padding: 5px 12px;
  border-radius: 999px;
  font-weight: 600;
}
.lg::before {
  content: "";
  width: 10px;
  height: 10px;
  border-radius: 3px;
}
.lg-kitchen::before {
  background: var(--terracotta);
}
.lg-floor::before {
  background: var(--forest);
}
.lg-bar::before {
  background: var(--gold);
}
.lg-off::before {
  background: var(--cream-2);
  border: 1px solid rgba(44, 26, 14, 0.16);
}
.lg-open::before {
  background: transparent;
  border: 1px dashed var(--warm-gray);
}

/* Toast */
.toast {
  position: fixed;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--forest-d);
  color: var(--bone);
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.18);
  z-index: 10;
}

/* Responsive */
@media (max-width: 1180px) {
  .sched-head,
  .row {
    grid-template-columns: 160px repeat(7, 1fr) 70px;
  }
}
@media (max-width: 880px) {
  .app {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr;
  }
  .rail {
    flex-direction: row;
    border-right: none;
    border-bottom: 1px solid var(--forest-d);
    overflow-x: auto;
    padding: 8px 12px;
  }
  .rail-brand,
  .rail-foot {
    display: none;
  }
  .rail-nav {
    flex-direction: row;
    padding: 0;
  }
  .schedule {
    overflow-x: auto;
  }
  .sched-head,
  .row {
    min-width: 880px;
  }
}

