  -webkit-font-smoothing: antialiased;
}
.page {
  max-width: 1080px;
  margin: 0 auto;
  padding: 36px 28px 56px;
}
.head {
  text-align: center;
  margin-bottom: 28px;
}
.kicker {
  font-size: 0.72rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.head h1 {
  margin-top: 6px;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(1.8rem, 4.5vw, 2.6rem);
  letter-spacing: -0.015em;
}
.head h1 .ital {
  font-style: italic;
  color: var(--terracotta);
  font-weight: 500;
}
.sub {
  margin-top: 10px;
  font-size: 0.94rem;
  color: var(--warm-gray);
  max-width: 580px;
  margin-left: auto;
  margin-right: auto;
}

/* Layout */
.layout {
  display: grid;
  grid-template-columns: 240px 1fr;
  gap: 18px;
  align-items: start;
}
@media (max-width: 760px) {
  .layout {
    grid-template-columns: 1fr;
  }
}

/* Dish list */
.dishes {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 14px;
  padding: 16px 14px;
  position: sticky;
  top: 16px;
}
.block-kicker {
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink-2);
  font-weight: 700;
  padding: 0 8px 8px;
  margin-bottom: 6px;
  border-bottom: 1px dashed rgba(44, 26, 14, 0.18);
}
.dishes ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.dishes li {
  padding: 9px 10px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.92rem;
  color: var(--ink-2);
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}
.dishes li:hover {
  background: var(--cream-2);
}
.dishes li.is-active {
  background: var(--forest);
  color: var(--bone);
  font-weight: 700;
}
.dishes .d-section {
  margin-top: 8px;
  padding: 6px 10px 4px;
  font-size: 0.66rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
  cursor: default;
  background: transparent;
}
.dishes li.is-active .d-price {
  color: var(--gold-light);
}
.d-price {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  color: var(--warm-gray);
  font-weight: 700;
}

/* Panel */
.panel {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 14px;
  padding: 22px 24px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.panel-head {
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
}
.panel-kicker {
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.panel-head h2 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.6rem;
  margin-top: 4px;
  letter-spacing: -0.01em;
}
.dish-meta {
  margin-top: 4px;
  font-size: 0.86rem;
  color: var(--warm-gray);
  font-style: italic;
}

/* Pairings */
.pairings {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.pair {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 12px;
  padding: 16px 18px;
  display: grid;
  grid-template-columns: 36px 1fr;
  gap: 14px;
  align-items: start;
}
.bottle {
  width: 36px;
  height: 60px;
  position: relative;
  margin-top: 6px;
}
.bottle::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, var(--burgundy) 0%, var(--ink) 100%);
  border-radius: 6px 6px 4px 4px;
  box-shadow: inset 1px 0 0 rgba(255, 255, 255, 0.08);
}
.bottle::after {
  /* neck */
  content: "";
  position: absolute;
  top: -14px;
  left: 50%;
  width: 14px;
  height: 16px;
  background: linear-gradient(180deg, var(--burgundy) 0%, var(--ink) 100%);
  border-radius: 3px 3px 0 0;
  transform: translateX(-50%);
}
.bottle.white::before,
.bottle.white::after {
  background: linear-gradient(180deg, #5d6a3a 0%, #3a4423 100%);
}
.bottle.rose::before,
.bottle.rose::after {
  background: linear-gradient(180deg, #c97a6a 0%, #8e3a2c 100%);
}
.bottle.spark::before,
.bottle.spark::after {
  background: linear-gradient(180deg, #4d6f7a 0%, #1f3236 100%);
}
.bottle .label {
  position: absolute;
  left: 4px;
  right: 4px;
  top: 16px;
  height: 28px;
  background: var(--bone);
  border-radius: 2px;
  display: grid;
  place-items: center;
  font-family: var(--font-mono);
  font-size: 6.5px;
  color: var(--ink);
  font-weight: 700;
  letter-spacing: 0.04em;
  z-index: 2;
  text-align: center;
  line-height: 1;
}

.p-body {
  min-width: 0;
}
.p-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 14px;
  flex-wrap: wrap;
}
.p-name {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.15rem;
  letter-spacing: -0.005em;
}
.p-region {
  font-size: 0.78rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.p-region span {
  margin: 0 4px;
}
.p-price {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}
.p-price .p-glass {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--terracotta-d);
  font-size: 0.92rem;
}
.p-price small {
  font-size: 0.7rem;
  color: var(--warm-gray);
}
.p-conf {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--warm-gray);
  font-weight: 700;
  margin-top: 4px;
}
.p-pip {
  display: inline-flex;
  gap: 3px;
}
.p-pip span {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: rgba(44, 26, 14, 0.18);
}
.p-pip span.on {
  background: var(--terracotta);
}
.p-notes {
  margin-top: 8px;
  font-size: 0.9rem;
  color: var(--ink-2);
  line-height: 1.55;
}
.p-actions {
  display: flex;
  gap: 6px;
  margin-top: 10px;
}
.p-actions button {
  border-radius: 999px;
  padding: 8px 14px;
  font-family: inherit;
  font-size: 0.8rem;
  font-weight: 700;
  cursor: pointer;
}
.p-add {
  background: var(--forest);
  color: var(--bone);
  border: none;
}
.p-add:hover {
  background: var(--forest-d);
}
.p-why {
  background: transparent;
  border: 1px solid rgba(44, 26, 14, 0.18);
  color: var(--ink-2);
}
.p-why:hover {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}
.p-why-body {
  margin-top: 8px;
  background: var(--bone);
  border-left: 3px solid var(--terracotta);
  padding: 10px 14px;
  border-radius: 0 8px 8px 0;
  font-size: 0.86rem;
  color: var(--ink-2);
  font-style: italic;
}

.cta-line {
  text-align: center;
  padding-top: 10px;
  border-top: 1px dashed rgba(44, 26, 14, 0.18);
}
.cta-line .note {
  font-size: 0.8rem;
  color: var(--warm-gray);
}

/* Toast */
.toast {
  position: fixed;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--forest-d);
  color: var(--bone);
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.18);
  z-index: 10;
}

