/* ────────────────────────────────────────────
   VAULT & EMBER — Steakhouse palette
   Dark charcoal · leather · gold · rust accent
────────────────────────────────────────────── */
:root {
  --bg: #141210;
  --paper: #1c1916;
  --paper-2: #221e1a;
  --leather: #2b211a;
  --gold: #c9a14c;
  --gold-light: #e8c469;
  --rust: #8a3a1f;
  --bone: #e9e3d6;
  --ink: #0a0907;
  --mute: #8a7e6d;
  --rule: rgba(233, 227, 214, 0.1);
  --font-display: "Cormorant Garamond", "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 4px;
  --r-md: 8px;
  --r-lg: 14px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html {
  scroll-behavior: smooth;
}
body {
  font-family: var(--font-body);
  background: var(--bg);
  color: var(--bone);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  /* Subtle film grain */
  background-image: radial-gradient(circle at 20% 10%, rgba(201, 161, 76, 0.06), transparent 60%),
    radial-gradient(circle at 80% 90%, rgba(138, 58, 31, 0.08), transparent 50%);
}

/* ── Nav ── */
.nav {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 16px 28px;
  background: rgba(20, 18, 16, 0.78);
  backdrop-filter: blur(12px) saturate(140%);
  border-bottom: 1px solid var(--rule);
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  color: var(--bone);
}
.brand-mark {
  width: 32px;
  height: 32px;
  border: 1px solid var(--gold);
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.86rem;
  color: var(--gold);
  letter-spacing: 0.04em;
}
.brand-name {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1.1rem;
  letter-spacing: 0.04em;
}
.nav-links {
  display: flex;
  gap: 22px;
  margin-left: auto;
}
.nav-links a {
  color: var(--mute);
  text-decoration: none;
  font-size: 0.76rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  transition: color 0.15s;
}
.nav-links a:hover {
  color: var(--gold);
}
.nav-cta {
  background: var(--gold);
  color: var(--ink);
  border-radius: 0;
  padding: 10px 18px;
  font-size: 0.74rem;
  font-weight: 700;
  text-decoration: none;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  transition: background 0.15s;
}
.nav-cta:hover {
  background: var(--gold-light);
}
@media (max-width: 720px) {
  .nav-links {
    display: none;
  }
}

/* ── Hero ── */
.hero {
  position: relative;
  display: grid;
  grid-template-columns: 1.35fr 1fr;
  gap: 48px;
  max-width: 1280px;
  margin: 0 auto;
  padding: 80px 36px 100px;
  align-items: center;
  overflow: hidden;
}
.smoke {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(
      ellipse 60% 40% at 30% 100%,
      rgba(201, 161, 76, 0.16),
      transparent 60%
    ), radial-gradient(ellipse 70% 50% at 70% 0%, rgba(138, 58, 31, 0.14), transparent 55%);
}
.hero-inner {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 22px;
}
.kicker {
  font-size: 0.72rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--gold);
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 14px;
}
.pip {
  display: inline-block;
  width: 24px;
  height: 1px;
  background: var(--gold);
}
.hero-title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(3.4rem, 9vw, 6.2rem);
  line-height: 0.95;
  letter-spacing: -0.015em;
}
.hero-title .line {
  display: block;
}
.hero-title .line-em {
  font-style: italic;
  color: var(--gold);
}
.hero-sub {
  font-size: 1.05rem;
  color: var(--mute);
  max-width: 460px;
}
.hero-actions {
  display: flex;
  gap: 10px;
  margin-top: 4px;
}
.btn {
  padding: 14px 22px;
  font-family: var(--font-body);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  cursor: pointer;
  border: 1px solid transparent;
  text-decoration: none;
  display: inline-block;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.btn-gold {
  background: var(--gold);
  color: var(--ink);
}
.btn-gold:hover {
  background: var(--gold-light);
}
.btn-ghost {
  background: transparent;
  color: var(--bone);
  border-color: var(--rule);
}
.btn-ghost:hover {
  border-color: var(--gold);
  color: var(--gold);
}

.hero-stats {
  margin-top: 12px;
  display: grid;
  grid-template-columns: repeat(3, auto);
  gap: 16px 32px;
  padding-top: 22px;
  border-top: 1px solid var(--rule);
}
.hero-stats div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.hero-stats dt {
  font-size: 0.68rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--mute);
  font-weight: 700;
}
.hero-stats dd.m {
  font-family: var(--font-mono);
  font-size: 0.92rem;
  font-weight: 600;
  color: var(--bone);
}
.hero-stats dd.m span {
  color: var(--gold);
  font-weight: 700;
}

/* Cut chart aside */
.cut-chart {
  position: relative;
  background: var(--paper);
  border: 1px solid var(--rule);
  border-left: 2px solid var(--gold);
  padding: 26px 26px 22px;
}
.cut-chart-label {
  font-size: 0.66rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--gold);
  font-weight: 700;
  margin-bottom: 14px;
}
.cut-chart ul {
  list-style: none;
  display: flex;
  flex-direction: column;
}
.cut-chart li {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 500;
  padding: 9px 0;
  border-bottom: 1px dashed var(--rule);
  color: var(--bone);
}
.cut-chart li:last-child {
  border-bottom: none;
}
.cut-chart .age {
  font-family: var(--font-mono);
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--mute);
  letter-spacing: 0.04em;
}
.cut-chart li.featured {
  color: var(--gold);
}
.cut-chart li.featured .age {
  color: var(--gold);
}

@media (max-width: 880px) {
  .hero {
    grid-template-columns: 1fr;
    padding: 56px 28px 64px;
  }
}

/* ── Cuts section ── */
.cuts {
  max-width: 1280px;
  margin: 0 auto;
  padding: 96px 36px;
  scroll-margin-top: 70px;
}
.section-head {
  text-align: center;
  margin-bottom: 48px;
}
.section-head h2 {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(2.4rem, 5vw, 3.6rem);
  letter-spacing: -0.015em;
  line-height: 1.05;
}
.ital {
  font-style: italic;
  color: var(--gold);
}

.cut-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: var(--rule);
}
@media (max-width: 880px) {
  .cut-grid {
    grid-template-columns: 1fr;
  }
}
.cut {
  position: relative;
  background: var(--paper);
  padding: 32px 28px 28px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: background 0.2s;
}
.cut:hover {
  background: var(--paper-2);
}
.cut-feat {
  background: var(--leather);
}
.cut-feat:hover {
  background: #382b22;
}
.cut-badge {
  position: absolute;
  top: 18px;
  right: 18px;
  background: var(--gold);
  color: var(--ink);
  font-size: 0.62rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  font-weight: 700;
  padding: 4px 10px;
}
.cut-no {
  font-family: var(--font-mono);
  font-size: 0.74rem;
  color: var(--gold);
  letter-spacing: 0.14em;
  font-weight: 700;
}
.cut h3 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1.7rem;
  letter-spacing: -0.005em;
  line-height: 1.15;
}
.cut-desc {
  color: var(--mute);
  font-size: 0.92rem;
  flex: 1;
}
.cut-spec {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 0;
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
}
.cut-spec div {
  display: flex;
  justify-content: space-between;
  font-size: 0.82rem;
}
.cut-spec dt {
  color: var(--mute);
  letter-spacing: 0.06em;
}
.cut-spec dd {
  color: var(--bone);
  font-weight: 600;
}
.cut-price {
  font-family: var(--font-display);
  font-size: 1.8rem;
