  color: var(--ink);
  text-decoration: none;
}
.back {
  font-size: 0.84rem;
  color: var(--ink-2);
  text-decoration: none;
  font-weight: 600;
}
.back:hover {
  color: var(--terracotta-d);
}

/* Head */
.head {
  text-align: center;
  padding: 64px 28px 36px;
  max-width: 760px;
  margin: 0 auto;
}
.kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--terracotta);
  font-weight: 700;
  margin-bottom: 8px;
}
.head h1 {
  font-family: var(--font-display);
  font-size: clamp(2rem, 5vw, 3.2rem);
  font-weight: 700;
  letter-spacing: -0.015em;
}
.sub {
  margin-top: 10px;
  font-size: 0.98rem;
  color: var(--ink-2);
}
.status {
  margin-top: 18px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--bone);
  padding: 8px 14px;
  border-radius: 999px;
  border: 1px solid rgba(44, 26, 14, 0.08);
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ink-2);
}
.status .dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--warm-gray);
}
.status.is-open .dot {
  background: var(--success);
  box-shadow: 0 0 0 4px rgba(79, 122, 58, 0.18);
}
.status.is-closed .dot {
  background: var(--danger);
}

/* Map row */
.map-row {
  max-width: 1080px;
  margin: 0 auto;
  padding: 24px 28px;
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 18px;
  align-items: stretch;
}
@media (max-width: 880px) {
  .map-row {
    grid-template-columns: 1fr;
  }
}
.map {
  border-radius: var(--r-lg);
  overflow: hidden;
  background: var(--cream-2);
  border: 1px solid rgba(44, 26, 14, 0.08);
  position: relative;
  display: flex;
  flex-direction: column;
}
.map-svg {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 280px;
}
.map-cap {
  position: absolute;
  bottom: 10px;
  left: 12px;
  background: rgba(250, 247, 241, 0.92);
  padding: 5px 10px;
  border-radius: var(--r-sm);
  font-size: 0.7rem;
  color: var(--warm-gray);
  backdrop-filter: blur(6px);
}

/* Address card */
.address-card {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-lg);
  padding: 24px 26px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.address-card address {
  font-style: normal;
  font-size: 1rem;
  color: var(--ink-2);
  line-height: 1.7;
}
.address-card strong {
  font-family: var(--font-display);
  font-size: 1.3rem;
  color: var(--ink);
}
.address-meta {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 10px;
  border-top: 1px dashed rgba(44, 26, 14, 0.18);
}
.address-meta div {
  display: flex;
  justify-content: space-between;
  font-size: 0.86rem;
}
.address-meta dt {
  color: var(--warm-gray);
  letter-spacing: 0.04em;
}
.address-meta dd {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--ink);
}
.card-actions {
  display: flex;
  gap: 8px;
  margin-top: auto;
  padding-top: 8px;
}
.ghost,
.primary {
  flex: 1;
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 700;
  padding: 11px 14px;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background 0.15s, color 0.15s;
}
.ghost {
  background: transparent;
  border-color: rgba(44, 26, 14, 0.2);
  color: var(--ink-2);
}
.ghost:hover {
  background: var(--cream-2);
  color: var(--ink);
}
.primary {
  background: var(--forest);
  color: var(--bone);
}
.primary:hover {
  background: var(--forest-d);
}

/* Grid: hours + info */
.grid {
  max-width: 1080px;
  margin: 16px auto 0;
  padding: 8px 28px 32px;
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  gap: 16px;
  align-items: start;
}
@media (max-width: 880px) {
  .grid {
    grid-template-columns: 1fr;
  }
}

.hours-card {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 22px 24px 20px;
}
.hours-card h2 {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 700;
  margin-bottom: 12px;
}
.hours-table {
  width: 100%;
  border-collapse: collapse;
}
.hours-table tr {
  border-bottom: 1px dashed rgba(44, 26, 14, 0.12);
}
.hours-table tr:last-child {
  border-bottom: none;
}
.hours-table td {
  padding: 7px 0;
  font-size: 0.9rem;
}
.hours-table td:first-child {
  color: var(--ink-2);
  font-weight: 600;
}
.hours-table td:last-child {
  color: var(--ink);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  text-align: right;
}
.hours-table tr.is-today td {
  color: var(--terracotta-d);
}
.hours-table tr.is-today td:first-child::after {
  content: " · today";
  font-size: 0.66rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--terracotta);
}
.hours-table tr.is-closed td:last-child {
  color: var(--warm-gray);
  font-weight: 500;
}
.hours-note {
  margin-top: 14px;
  font-size: 0.78rem;
  color: var(--warm-gray);
  font-style: italic;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
}
.info {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 20px 18px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.info-icon {
  font-size: 1.6rem;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: var(--cream-2);
  color: var(--forest);
}
.info h3 {
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 700;
}
.info ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.84rem;
  color: var(--ink-2);
}
.info ul li strong {
  color: var(--ink);
  margin-right: 4px;
}

/* Contact */
.contact {
  max-width: 760px;
  margin: 0 auto;
  padding: 56px 28px 80px;
}
.section-head {
  text-align: center;
  margin-bottom: 24px;
}
.section-head h2 {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 4vw, 2.2rem);
  font-weight: 700;
  letter-spacing: -0.015em;
}
.contact-sub {
  margin-top: 6px;
  font-size: 0.92rem;
  color: var(--warm-gray);
}
.contact-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 22px 24px;
}
.contact-form .row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.contact-form label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 0.74rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-2);
  font-weight: 700;
}
.contact-form input,
.contact-form select,
.contact-form textarea {
  border: 1px solid rgba(44, 26, 14, 0.12);
  background: var(--cream);
  border-radius: var(--r-md);
  padding: 10px 12px;
  font-family: inherit;
  font-size: 0.92rem;
  color: var(--ink);
  outline: none;
  transition: border-color 0.15s;
  resize: vertical;
}
.contact-form input:focus,
.contact-form select:focus,
.contact-form textarea:focus {
  border-color: var(--terracotta);
}
.contact-form .primary {
  align-self: flex-start;
  flex: 0 0 auto;
  padding: 12px 22px;
}
.contact-ok {
  color: var(--success);
  font-weight: 700;
  font-size: 0.88rem;
}

/* Footer */
.footer {
  border-top: 1px solid rgba(44, 26, 14, 0.08);
  background: var(--bone);
  text-align: center;
  padding: 28px;
}
.footer-brand {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 800;
}
.footer-meta {
  font-size: 0.82rem;
  color: var(--warm-gray);
  margin-top: 4px;
}

/* Print */
@media print {
  body {
    background: white;
  }
  .no-print {
    display: none !important;
  }
  .map,
  .grid,
  .contact {
    display: none !important;
  }
  .head {
    padding: 16px 0 0;
    text-align: left;
  }
  .map-row {
    grid-template-columns: 1fr;
    padding: 16px 0;
  }
  .address-card {
    box-shadow: none;
    border: 1px solid #999;
  }
}

