// shape: [open] in minutes, [close] in minutes; null = closed
const HOURS = [
  { day: "Monday", windows: null },
  { day: "Tuesday", windows: [[19 * 60, 23 * 60]] },
  {
    day: "Wednesday",
    windows: [[19 * 60, 23 * 60 + 30]],
  },
  {
    day: "Thursday",
    windows: [[19 * 60, 23 * 60 + 30]],
  },
  {
    day: "Friday",
    windows: [[19 * 60, 23 * 60 + 30]],
  },
  {
    day: "Saturday",
    windows: [
      [13 * 60, 16 * 60],
      [19 * 60, 23 * 60 + 30],
    ],
  },
  {
    day: "Sunday",
    windows: [[13 * 60, 16 * 60]],
  },
];

const JS_DOW_TO_INDEX = [6, 0, 1, 2, 3, 4, 5]; // Sunday → 6 (last row), Mon → 0
const tbody = document.getElementById("hoursBody");
const status = document.getElementById("status");
const statusText = document.getElementById("statusText");

function fmt(mins) {
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

function describeWindows(windows) {
  if (!windows) return "Closed";
  return windows.map(([a, b]) => `${fmt(a)} – ${fmt(b)}`).join(" · ");
}

function buildHours() {
  const todayIdx = JS_DOW_TO_INDEX[new Date().getDay()];
  tbody.innerHTML = HOURS.map((row, idx) => {
    const cls = [idx === todayIdx ? "is-today" : "", !row.windows ? "is-closed" : ""]
      .filter(Boolean)
      .join(" ");
    return `<tr class="${cls}">
      <td>${row.day}</td>
      <td>${describeWindows(row.windows)}</td>
    </tr>`;
  }).join("");
}

function statusNow() {
  const now = new Date();
  const todayIdx = JS_DOW_TO_INDEX[now.getDay()];
  const minutesNow = now.getHours() * 60 + now.getMinutes();
  const today = HOURS[todayIdx];

  if (today.windows) {
    const open = today.windows.find(([a, b]) => minutesNow >= a && minutesNow < b);
    if (open) {
      status.classList.remove("is-closed");
      status.classList.add("is-open");
      statusText.textContent = `Open now · closes ${fmt(open[1])}`;
      return;
    }
    const upcoming = today.windows.find(([a]) => minutesNow < a);
    if (upcoming) {
      status.classList.remove("is-open");
      status.classList.add("is-closed");
      statusText.textContent = `Closed · opens today ${fmt(upcoming[0])}`;
      return;
    }
  }
  // Find the next day that has hours
  for (let i = 1; i <= 7; i++) {
    const next = HOURS[(todayIdx + i) % 7];
    if (next.windows) {
      status.classList.remove("is-open");
      status.classList.add("is-closed");
      statusText.textContent = `Closed · opens ${next.day.slice(0, 3)} ${fmt(next.windows[0][0])}`;
      return;
    }
  }
}

document.getElementById("copyAddr").addEventListener("click", async (e) => {
  const btn = e.currentTarget;
  const text = "Casa Olivar, 42 Calle del Olivar, 28012 Madrid, Spain";
  try {
    await navigator.clipboard.writeText(text);
    btn.textContent = "Copied ✓";
  } catch {
    btn.textContent = "Copy failed";
  }
  setTimeout(() => (btn.textContent = "Copy address"), 1600);
});

document.getElementById("printDir").addEventListener("click", () => {
  window.print();
});

const form = document.getElementById("contactForm");
const ok = document.getElementById("contactOk");
form.addEventListener("submit", (e) => {
  e.preventDefault();
  ok.hidden = false;
  form.querySelector("button").disabled = true;
  setTimeout(() => {
    ok.hidden = true;
    form.querySelector("button").disabled = false;
    form.reset();
  }, 3000);
});

buildHours();
statusNow();

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(44, 26, 14, 0.08), 0 2px 6px rgba(44, 26, 14, 0.06);
  --shadow-2: 0 8px 24px rgba(44, 26, 14, 0.12);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
}
body {
  font-family: var(--font-body);
  background: var(--ink);
  color: var(--bone);
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
  display: flex;
  flex-direction: column;
}

/* ── Topbar ── */
.topbar {
  background: var(--forest-d);
  padding: 14px 22px;
  display: flex;
  align-items: center;
  gap: 24px;
  border-bottom: 1px solid rgba(250, 247, 241, 0.08);
}
.brand {
  display: flex;
  flex-direction: column;
}
.brand-name {
  font-weight: 800;
  font-size: 1.1rem;
  letter-spacing: -0.01em;
}
.brand-tag {
  font-size: 0.66rem;
  letter-spacing: 0.16em;
  color: var(--gold-light);
  text-transform: uppercase;
  font-weight: 700;
}
.stats {
  display: flex;
  gap: 18px;
}
.stat {
  font-size: 0.8rem;
  color: rgba(250, 247, 241, 0.7);
}
.stat b {
  font-family: var(--font-mono);
  font-size: 1rem;
  font-weight: 700;
  color: var(--bone);
  margin-right: 4px;
}
.topbar-right {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 14px;
}
.util-btn {
  background: var(--gold);
  color: var(--ink);
  border: none;
  border-radius: 999px;
  padding: 8px 14px;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 700;
  cursor: pointer;
}
.util-btn:hover {
  background: var(--gold-light);
}
.clock {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 1rem;
  color: var(--gold-light);
}

/* ── Board ── */
.board {
  flex: 1;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  padding: 18px;
  overflow: hidden;
  background: var(--ink);
}
.col {
  background: rgba(250, 247, 241, 0.04);
  border: 1px solid rgba(250, 247, 241, 0.08);
  border-radius: var(--r-md);
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.col-head {
  padding: 12px 14px;
  border-bottom: 1px solid rgba(250, 247, 241, 0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}
.col-title {
  font-size: 0.86rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
}
.col-count {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  background: rgba(250, 247, 241, 0.1);
  padding: 2px 8px;
  border-radius: 999px;
  font-weight: 700;
}
.col[data-status="new"] .col-title {
  color: var(--gold-light);
}
.col[data-status="cook"] .col-title {
  color: var(--terracotta);
}
.col[data-status="ready"] .col-title {
  color: #6ec78a;
}
.col[data-status="served"] .col-title {
  color: rgba(250, 247, 241, 0.5);
}

.col-body {
  flex: 1;
  padding: 10px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* ── Tickets ── */
.ticket {
  background: var(--bone);
  color: var(--ink);
  border-radius: var(--r-md);
  padding: 10px 12px 12px;
  box-shadow: var(--shadow-1);
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-left: 4px solid var(--forest);
  animation: tIn 0.2s ease;
}
@keyframes tIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.ticket.is-warm {
  border-left-color: var(--warning);
}
.ticket.is-hot {
  border-left-color: var(--danger);
  animation: pulse 1.2s ease-in-out infinite;
}
.ticket.is-served {
  opacity: 0.55;
  border-left-color: var(--warm-gray);
}
@keyframes pulse {
  0%,
  100% {
    box-shadow: var(--shadow-1);
  }
  50% {
    box-shadow: 0 0 0 3px rgba(179, 67, 42, 0.2);
  }
}

.t-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 8px;
}
.t-table {
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: -0.005em;
}
.t-course {
  font-size: 0.7rem;
  color: var(--warm-gray);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 600;
}
.t-age {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.95rem;
  background: var(--cream-2);
  color: var(--ink);
  padding: 4px 10px;
  border-radius: 999px;
}
.ticket.is-warm .t-age {
  background: rgba(217, 144, 32, 0.18);
  color: #8a5a1a;
}
.ticket.is-hot .t-age {
  background: rgba(179, 67, 42, 0.18);
  color: var(--danger);
}

.t-lines {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.t-line {
  display: grid;
  grid-template-columns: 22px 1fr auto;
  align-items: baseline;
  gap: 8px;
  padding: 4px 0;
  cursor: pointer;
  border-bottom: 1px dashed rgba(44, 26, 14, 0.08);
  font-size: 0.86rem;
  line-height: 1.35;
}
.t-line:last-child {
  border-bottom: none;
}
.t-line-qty {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--terracotta-d);
  font-size: 0.85rem;
}
.t-line-name {
  color: var(--ink);
  font-weight: 600;
}
.t-line-mod {
  font-size: 0.72rem;
  color: var(--warm-gray);
  display: block;
  margin-top: 2px;
}
.t-line-tag {
  font-size: 0.62rem;
  background: var(--cream-2);
  color: var(--ink-2);
  padding: 2px 7px;
  border-radius: 999px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.t-line.is-done .t-line-name {
  text-decoration: line-through;
  color: var(--warm-gray);
}
.t-line.is-done .t-line-qty {
  color: var(--warm-gray);
}

.t-foot {
  display: flex;
  gap: 6px;
  margin-top: 4px;
}
.t-btn {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  color: var(--ink);
  font-family: inherit;
  font-size: 0.78rem;
  font-weight: 700;
  padding: 7px 12px;
  border-radius: var(--r-sm);
  cursor: pointer;
  transition: background 0.15s;
}
.t-btn:hover {
  background: var(--cream-2);
}
.t-btn-back {
  flex: 0 0 auto;
}
.t-btn-next {
  flex: 1;
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.t-btn-next:hover {
  background: var(--forest-d);
}
.ticket.is-served .t-btn-next {
  display: none;
}
.ticket[data-status="new"] .t-btn-back {
  visibility: hidden;
}

.col-empty {
  text-align: center;
  font-size: 0.78rem;
  color: rgba(250, 247, 241, 0.4);
  padding: 24px 12px;
  font-style: italic;
}

@media (max-width: 1100px) {
  .board {
    grid-template-columns: repeat(2, 1fr);
    overflow: auto;
  }
}
@media (max-width: 640px) {
  .board {
    grid-template-columns: 1fr;
  }
  .topbar {
    flex-wrap: wrap;
    gap: 12px;
  }
}

snippets.js:
const COLUMNS = [
  { id: "new", title: "New" },
  { id: "cook", title: "Cooking" },
  { id: "ready", title: "Ready" },
  { id: "served", title: "Served" },
];

const SEED = [
  {
    id: "t-401",
    table: "Table 4",
    course: "2nd · Mains",
    status: "cook",
    age: 9 * 60,
    lines: [
      { qty: 1, name: "Ribeye 14oz", mod: "Medium rare · Truffle fries", tag: "Hot" },
      { qty: 1, name: "Branzino entero", mod: "No fennel" },
      { qty: 1, name: "Risotto hongos", mod: "Veg" },
    ],
  },
  {
    id: "t-402",
    table: "Table 9",
    course: "1st · Apps",
    status: "ready",
    age: 4 * 60,
    lines: [
      { qty: 2, name: "Burrata huerta" },
      { qty: 1, name: "Pulpo brasa", tag: "GF" },
    ],
  },
  {
    id: "t-403",
    table: "Bar 2",
    course: "Drinks",
    status: "new",
    age: 22,
    lines: [
      { qty: 2, name: "Negroni sbagliato" },
      { qty: 1, name: "Spritz", mod: "Less ice" },
    ],
  },
  {
    id: "t-404",
    table: "Table 12",
    course: "2nd · Mains",
    status: "cook",
    age: 15 * 60 + 20,
    lines: [
      { qty: 1, name: "Costilla cordero", tag: "Hot" },
      { qty: 1, name: "Pollo carbón" },
      { qty: 1, name: "Plato huerto", mod: "Allergy: nuts" },
    ],
  },
  {
    id: "t-405",
    table: "Take-out",
    course: "Pickup",
    status: "new",
    age: 90,
    lines: [
      { qty: 1, name: "Pappardelle ragú" },
      { qty: 2, name: "Pan masa madre" },
      { qty: 1, name: "Tarta de queso" },
    ],
  },
  {
    id: "t-406",
    table: "Table 7",
    course: "Dessert",
    status: "ready",
    age: 2 * 60,
    lines: [
      { qty: 1, name: "Olive oil cake" },
      { qty: 1, name: "Chocolate ganache" },
    ],
  },
];

const RANDOM_LINES = [
  { qty: 1, name: "Burrata huerta", mod: "Add focaccia" },
  { qty: 2, name: "Croquetas jamón" },
  { qty: 1, name: "Ensalada huerta", tag: "Veg" },
  { qty: 1, name: "Ribeye 14oz", mod: "Medium" },
  { qty: 1, name: "Salmón plancha" },
  { qty: 2, name: "Tinto natural" },
];
const RANDOM_TABLES = ["Table 3", "Table 5", "Table 11", "Bar 1", "Take-out"];
const RANDOM_COURSES = ["1st · Apps", "2nd · Mains", "Drinks", "Dessert"];

let tickets = SEED.map((t) => ({
  ...t,
  doneLines: new Set(),
  createdAt: Date.now() - t.age * 1000,
}));

const board = document.getElementById("board");
const tpl = document.getElementById("ticketTpl");
const statActive = document.getElementById("statActive");
const statAvg = document.getElementById("statAvg");
const statOver = document.getElementById("statOver");
const clockEl = document.getElementById("clock");

function buildBoard() {
  board.innerHTML = COLUMNS.map(
    (col) => `
    <section class="col" data-status="${col.id}">
      <header class="col-head">
        <span class="col-title">${col.title}</span>
        <span class="col-count" data-count="${col.id}">0</span>
      </header>
      <div class="col-body" data-col="${col.id}"></div>
    </section>`
  ).join("");
}

function ageString(seconds) {
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  return `${m}:${String(s).padStart(2, "0")}`;
}

function ageBucket(seconds) {
  if (seconds >= 14 * 60) return "is-hot";
  if (seconds >= 8 * 60) return "is-warm";
  return "";
}

function renderTickets() {
  COLUMNS.forEach((col) => {
    const wrap = board.querySelector(`[data-col="${col.id}"]`);
    wrap.innerHTML = "";
  });

  tickets.forEach((t) => {
    const wrap = board.querySelector(`[data-col="${t.status}"]`);
    if (!wrap) return;
    const node = tpl.content.cloneNode(true);
    const article = node.querySelector("[data-ticket]");
    article.dataset.id = t.id;
    article.dataset.status = t.status;
    const seconds = (Date.now() - t.createdAt) / 1000;
    const bucket = t.status === "served" ? "is-served" : ageBucket(seconds);
    if (bucket) article.classList.add(bucket);

    node.querySelector(".t-table").textContent = t.table;
    node.querySelector(".t-course").textContent = t.course;
    node.querySelector("[data-age]").textContent = ageString(seconds);

    const linesEl = node.querySelector("[data-lines]");
    linesEl.innerHTML = t.lines
      .map(
        (l, idx) => `
        <li class="t-line ${t.doneLines.has(idx) ? "is-done" : ""}" data-line="${idx}">
          <span class="t-line-qty">${l.qty}×</span>
          <div>
            <span class="t-line-name">${l.name}</span>
            ${l.mod ? `<span class="t-line-mod">${l.mod}</span>` : ""}
          </div>
          ${l.tag ? `<span class="t-line-tag">${l.tag}</span>` : ""}
        </li>`
      )
      .join("");

    wrap.appendChild(node);
  });

  // Counts & header stats
  let activeCount = 0;
  let overCount = 0;
  let totalAge = 0;
  let ageSamples = 0;

  COLUMNS.forEach((col) => {
    const inCol = tickets.filter((t) => t.status === col.id);
    board.querySelector(`[data-count="${col.id}"]`).textContent = inCol.length;
    if (col.id !== "served") activeCount += inCol.length;
    inCol.forEach((t) => {
      const sec = (Date.now() - t.createdAt) / 1000;
      if (col.id !== "served") {
        totalAge += sec;
        ageSamples += 1;
        if (sec >= 14 * 60) overCount += 1;
      }
    });
    if (inCol.length === 0) {
      const empty = document.createElement("p");
      empty.className = "col-empty";
      empty.textContent = "No tickets.";
      board.querySelector(`[data-col="${col.id}"]`).appendChild(empty);
    }
  });
  statActive.textContent = activeCount;
  statAvg.textContent = ageSamples ? Math.round(totalAge / ageSamples / 60) : 0;
  statOver.textContent = overCount;
}

function refreshAgesAndStats() {
  let activeCount = 0;
  let overCount = 0;
  let totalAge = 0;
  let ageSamples = 0;

  tickets.forEach((t) => {
    const ticketEl = board.querySelector(`[data-ticket][data-id="${t.id}"]`);
    const sec = (Date.now() - t.createdAt) / 1000;

    if (ticketEl) {
      const ageEl = ticketEl.querySelector("[data-age]");
      if (ageEl) ageEl.textContent = ageString(sec);

      ticketEl.classList.remove("is-warm", "is-hot", "is-served");
      const bucket = t.status === "served" ? "is-served" : ageBucket(sec);
      if (bucket) ticketEl.classList.add(bucket);
    }

    if (t.status !== "served") {
      activeCount += 1;
      totalAge += sec;
      ageSamples += 1;
      if (sec >= 14 * 60) overCount += 1;
    }
  });

  statActive.textContent = activeCount;
  statAvg.textContent = ageSamples ? Math.round(totalAge / ageSamples / 60) : 0;
  statOver.textContent = overCount;
}

board.addEventListener("click", (e) => {
  const ticketEl = e.target.closest("[data-ticket]");
  if (!ticketEl) return;
  const t = tickets.find((x) => x.id === ticketEl.dataset.id);
  if (!t) return;

  const lineEl = e.target.closest("[data-line]");
  if (lineEl) {
    const idx = Number(lineEl.dataset.line);
    if (t.doneLines.has(idx)) t.doneLines.delete(idx);
    else t.doneLines.add(idx);
    renderTickets();
    return;
  }
  const actionBtn = e.target.closest("[data-action]");
  if (actionBtn) {
    const order = ["new", "cook", "ready", "served"];
    const i = order.indexOf(t.status);
    if (actionBtn.dataset.action === "next" && i < order.length - 1) t.status = order[i + 1];
    if (actionBtn.dataset.action === "back" && i > 0) t.status = order[i - 1];
    renderTickets();
  }
});

document.getElementById("add").addEventListener("click", () => {
  const lines = [];
  const count = 2 + Math.floor(Math.random() * 2);
  for (let i = 0; i < count; i++) {
    const pick = RANDOM_LINES[Math.floor(Math.random() * RANDOM_LINES.length)];
    lines.push({ ...pick });
  }
  tickets.unshift({
    id: `t-${Date.now()}`,
    table: RANDOM_TABLES[Math.floor(Math.random() * RANDOM_TABLES.length)],
    course: RANDOM_COURSES[Math.floor(Math.random() * RANDOM_COURSES.length)],
    status: "new",
    age: 0,
    createdAt: Date.now(),
    lines,
    doneLines: new Set(),
  });
  renderTickets();
});

function tickClock() {
  const d = new Date();
  clockEl.textContent = `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}
tickClock();
setInterval(tickClock, 30000);
setInterval(refreshAgesAndStats, 1000);

buildBoard();
renderTickets();

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}
.app {
  height: 100vh;
  display: grid;
  grid-template-columns: 248px 1fr;
}

/* Rail (shared) */
.rail {
  background: var(--forest);
  color: var(--bone);
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--forest-d);
  overflow-y: auto;
}
.rail-brand {
  padding: 22px 22px 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid rgba(250, 247, 241, 0.1);
}
.brand-mark {
  width: 36px;
  height: 36px;
  background: var(--gold);
  color: var(--ink);
  border-radius: 8px;
  font-family: var(--font-display);
  font-weight: 800;
  display: grid;
  place-items: center;
}
.brand-name {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.05rem;
}
.rail-nav {
  flex: 1;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.r-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: 8px;
  text-decoration: none;
  color: rgba(250, 247, 241, 0.78);
  font-size: 0.92rem;
  font-weight: 500;
}
.r-link:hover {
  background: rgba(250, 247, 241, 0.06);
  color: var(--bone);
}
.r-link.is-active {
  background: var(--bone);
  color: var(--forest-d);
  font-weight: 700;
}
.r-icon {
  width: 22px;
  text-align: center;
}
.r-badge {
  margin-left: auto;
  background: var(--gold);
  color: var(--ink);
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 999px;
}
.rail-foot {
  padding: 14px 16px;
  border-top: 1px solid rgba(250, 247, 241, 0.1);
}
.rail-user {
  display: flex;
  align-items: center;
  gap: 10px;
}
.user-avatar {
  width: 38px;
  height: 38px;
  background: var(--terracotta);
  color: var(--bone);
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-weight: 800;
}
.user-name {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--bone);
}
.user-role {
  font-size: 0.74rem;
  color: rgba(250, 247, 241, 0.5);
}

/* Main */
.main {
  overflow-y: auto;
  padding: 28px 32px 48px;
}
.top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.kicker {
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.top h1 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 2rem;
  letter-spacing: -0.015em;
}
.top-tools {
  display: flex;
  gap: 6px;
  align-items: center;
}
.date-pick {
  display: inline-flex;
  align-items: center;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.1);
  padding: 3px 6px;
  border-radius: 999px;
  font-size: 0.84rem;
  font-weight: 700;
  color: var(--ink);
  gap: 6px;
}
.btn-sq {
  padding: 6px 10px !important;
  font-size: 0.94rem !important;
  background: transparent !important;
  border: none !important;
  color: var(--ink-2);
}
.btn-sq:hover {
  color: var(--terracotta) !important;
  background: transparent !important;
}

.ghost,
.primary {
  border-radius: 999px;
  padding: 9px 16px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid transparent;
}
.ghost {
  background: var(--bone);
  border-color: rgba(44, 26, 14, 0.12);
  color: var(--ink-2);
}
.ghost:hover {
  background: var(--cream-2);
  color: var(--ink);
}
.primary {
  background: var(--forest);
  color: var(--bone);
}
.primary:hover {
  background: var(--forest-d);
}

/* Status */
.status {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 18px;
}
@media (max-width: 980px) {
  .status {
    grid-template-columns: 1fr 1fr;
  }
}
.stat {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 10px;
  padding: 14px 16px;
}
.stat-warn {
  border-left: 3px solid var(--warning);
}
.stat-label {
  font-size: 0.72rem;
  color: var(--warm-gray);
  font-weight: 600;
}
.stat-value {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.55rem;
  margin-top: 2px;
}
.stat-value small {
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.82rem;
  color: var(--warm-gray);
}
.stat-meta {
  font-size: 0.72rem;
  color: var(--warm-gray);
  margin-top: 2px;
  font-weight: 600;
}
.is-up {
  color: var(--success);
}

/* Tabs */
.tabs {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid rgba(44, 26, 14, 0.12);
  margin-bottom: 16px;
}
.tab {
  background: transparent;
  border: none;
  color: var(--ink-2);
  font-family: inherit;
  font-size: 0.94rem;
  font-weight: 700;
  padding: 12px 18px;
  cursor: pointer;
  position: relative;
}
.tab:hover {
  color: var(--terracotta-d);
}
.tab.is-active {
  color: var(--terracotta);
}
.tab.is-active::after {
  content: "";
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: -1px;
  height: 3px;
  background: var(--terracotta);
  border-radius: 999px;
}
.tab-count {
  margin-left: 6px;
  background: var(--cream-2);
  color: var(--ink-2);
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 999px;
}
.tab.is-active .tab-count {
  background: var(--terracotta);
  color: var(--bone);
}

/* Board */
.board {
  display: grid;
}

/* View shared bits */
.view-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}
.filters {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.seg-label {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--warm-gray);
  font-weight: 700;
}
.seg {
  display: inline-flex;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.1);
  padding: 3px;
  border-radius: 999px;
}
.seg-btn {
  background: transparent;
  border: none;
  color: var(--ink-2);
  font-family: inherit;
  font-size: 0.8rem;
  font-weight: 600;
  padding: 6px 12px;
  border-radius: 999px;
  cursor: pointer;
}
.seg-btn.is-active {
  background: var(--forest);
  color: var(--bone);
}
.search {
  display: inline-flex;
  align-items: center;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.1);
  padding: 7px 14px;
  border-radius: 999px;
  gap: 8px;
  color: var(--warm-gray);
}
.search input {
  background: transparent;
  border: none;
  outline: none;
  font-family: inherit;
  font-size: 0.86rem;
  color: var(--ink);
  width: 240px;
}

/* List view */
.res-rows {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.res-row {
  display: grid;
  grid-template-columns: 64px 1fr auto auto;
  gap: 16px;
  align-items: center;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 12px;
  padding: 12px 18px;
}
.res-row.row-hidden {
  display: none !important;
}
.r-time {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--ink);
}
.r-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.r-name {
  font-weight: 700;
  font-size: 0.96rem;
}
.r-meta {
  font-size: 0.78rem;
  color: var(--warm-gray);
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
}
.r-meta strong {
  color: var(--ink-2);
}
.r-note {
  font-size: 0.74rem;
  color: var(--terracotta);
  font-style: italic;
  margin-top: 2px;
}
.r-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--cream-2);
  color: var(--ink-2);
}
.r-status[data-s="confirmed"] {
  background: var(--cream-2);
  color: var(--ink-2);
}
.r-status[data-s="arrived"] {
  background: rgba(201, 168, 76, 0.22);
  color: #8a7325;
}
.r-status[data-s="seated"] {
  background: rgba(45, 74, 62, 0.16);
  color: var(--forest-d);
}
.r-status[data-s="no-show"] {
  background: rgba(179, 67, 42, 0.18);
  color: var(--danger);
}
.r-status[data-s="cancelled"] {
  background: var(--cream-2);
  color: var(--warm-gray);
  text-decoration: line-through;
}
.r-actions {
  display: flex;
  gap: 6px;
  align-items: center;
}
.act {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.1);
  padding: 6px 12px;
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.74rem;
  font-weight: 700;
  color: var(--ink-2);
  cursor: pointer;
}
.act:hover {
  background: var(--cream-2);
}
.act-primary {
  background: var(--forest);
  color: var(--bone);
  border: none;
}
.act-primary:hover {
  background: var(--forest-d);
}
.act-danger {
  background: transparent;
  color: var(--danger);
  border-color: rgba(179, 67, 42, 0.3);
}
.act-danger:hover {
  background: rgba(179, 67, 42, 0.08);
}

/* Calendar */
.cal-head {
  display: grid;
  grid-template-columns: 60px repeat(7, 1fr);
  gap: 4px;
  margin-bottom: 8px;
  font-size: 0.74rem;
  color: var(--warm-gray);
  font-weight: 700;
}
.cal-head > div {
  text-align: center;
  padding: 8px 6px;
}
.cal-head .is-today {
  background: var(--terracotta);
  color: var(--bone);
  border-radius: 8px;
}
.cal-grid {
  display: grid;
  grid-template-columns: 60px repeat(7, 1fr);
  gap: 4px;
}
.cal-time {
  display: grid;
  place-items: center;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  color: var(--warm-gray);
  font-weight: 700;
}
.cal-cell {
  height: 56px;
  border-radius: 6px;
  background: var(--cream-2);
  position: relative;
  display: grid;
  place-items: center;
  font-family: var(--font-mono);
  font-size: 0.74rem;
  color: var(--ink-2);
  cursor: pointer;
}
.cal-cell[data-h="0"] {
  background: var(--cream-2);
}
.cal-cell[data-h="1"] {
  background: rgba(201, 168, 76, 0.25);
  color: #8a7325;
}
.cal-cell[data-h="2"] {
  background: rgba(193, 113, 74, 0.28);
  color: var(--terracotta-d);
}
.cal-cell[data-h="3"] {
  background: var(--terracotta);
  color: var(--bone);
}
.cal-cell[data-h="4"] {
  background: var(--forest);
  color: var(--bone);
}
.cal-legend {
  margin-top: 12px;
  display: flex;
  gap: 10px;
  font-size: 0.78rem;
  color: var(--warm-gray);
  font-weight: 600;
}
.cl {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: 999px;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
}
.cl::before {
  content: "";
  width: 10px;
  height: 10px;
  border-radius: 3px;
}
.cl-low::before {
  background: rgba(201, 168, 76, 0.4);
}
.cl-mid::before {
  background: var(--terracotta);
}
.cl-high::before {
  background: var(--forest);
}

/* Waitlist */
.wait-rows {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.wait-row {
  display: grid;
  grid-template-columns: 64px 1fr auto auto;
  gap: 16px;
  align-items: center;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 12px;
  padding: 14px 18px;
}
.w-when {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.92rem;
  color: var(--ink-2);
}
.w-name {
  font-weight: 700;
}
.w-note {
  font-size: 0.78rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.w-tag {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--gold);
  color: var(--ink);
}
.w-tag-quiet {
  background: var(--cream-2);
  color: var(--ink-2);
}

/* Toast */
.toast {
  position: fixed;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--forest-d);
  color: var(--bone);
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 0.86rem;
  font-weight: 600;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.18);
  z-index: 10;
}

@media (max-width: 880px) {
  .app {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr;
  }
  .rail {
    flex-direction: row;
    border-right: none;
    border-bottom: 1px solid var(--forest-d);
    overflow-x: auto;
    padding: 8px 12px;
  }
  .rail-brand,
  .rail-foot {
    display: none;
  }
  .rail-nav {
    flex-direction: row;
    padding: 0;
  }
  .res-row,
  .wait-row {
    grid-template-columns: 1fr auto;
    grid-template-rows: auto auto;
  }
  .r-time,
  .w-when {
    grid-row: 1;
    grid-column: 1;
  }
  .r-status,
  .w-tag {
    grid-row: 1;
    grid-column: 2;
    justify-self: end;
  }
  .r-body {
    grid-row: 2;
    grid-column: 1 / -1;
  }
  .r-actions {
    grid-row: 3;
    grid-column: 1 / -1;
    justify-content: flex-end;
  }
}

