  },
  {
    id: "w3",
    when: "Sat 20:30",
    name: "Bechtel",
    note: "×2 · birthday · happy with any table",
    tag: "On list",
    quiet: true,
  },
];

const STATUS_LABEL = {
  confirmed: "Confirmed",
  arrived: "Arrived",
  seated: "Seated",
  "no-show": "No-show",
  cancelled: "Cancelled",
};

let activeView = "list";
let partyFilter = "all";
let query = "";

const resList = document.getElementById("resList");
const waitList = document.getElementById("waitList");
const toast = document.getElementById("toast");

function partyMatches(p) {
  if (partyFilter === "all") return true;
  if (partyFilter === "more") return p >= 7;
  if (partyFilter === "2") return p <= 2;
  if (partyFilter === "4") return p >= 3 && p <= 4;
  if (partyFilter === "6") return p >= 5 && p <= 6;
  return true;
}

function renderList() {
  const q = query.toLowerCase();
  resList.innerHTML = BOOKINGS.map((b) => {
    const hide =
      !partyMatches(b.party) ||
      (q && !`${b.name} ${b.phone} ${b.table} ${b.note}`.toLowerCase().includes(q));
    const actions =
      b.status === "cancelled"
        ? `<button class="act" data-action="reinstate" data-id="${b.id}">Reinstate</button>`
        : b.status === "seated"
          ? `<button class="act" data-action="check" data-id="${b.id}">Mark check</button>
             <button class="act act-danger" data-action="cancel" data-id="${b.id}">Cancel</button>`
          : `<button class="act act-primary" data-action="seat" data-id="${b.id}">Seat now</button>
             <button class="act" data-action="noshow" data-id="${b.id}">No-show</button>
             <button class="act act-danger" data-action="cancel" data-id="${b.id}">Cancel</button>`;
    return `<li class="res-row ${hide ? "row-hidden" : ""}" data-id="${b.id}">
      <span class="r-time">${b.time}</span>
      <div class="r-body">
        <p class="r-name">${b.name}</p>
        <p class="r-meta">
          <strong>×${b.party}</strong>
          · <span>${b.table}</span>
          · <span>${b.phone}</span>
        </p>
        ${b.note ? `<p class="r-note">${b.note}</p>` : ""}
      </div>
      <span class="r-status" data-s="${b.status}">${STATUS_LABEL[b.status]}</span>
      <div class="r-actions">${actions}</div>
    </li>`;
  }).join("");
}

function renderWaitlist() {
  waitList.innerHTML = WAITLIST.map(
    (w) => `<li class="wait-row" data-id="${w.id}">
      <span class="w-when">${w.when}</span>
      <div>
        <p class="w-name">${w.name}</p>
        <p class="w-note">${w.note}</p>
      </div>
      <span class="w-tag ${w.quiet ? "w-tag-quiet" : ""}">${w.tag}</span>
      <button class="act act-primary" data-action="promote" data-id="${w.id}">${w.quiet ? "Offer slot" : "Promote ↗"}</button>
    </li>`
  ).join("");
}

function renderCalendar() {
  const calHead = document.getElementById("calHead");
  const calGrid = document.getElementById("cal");
  if (!calHead || !calGrid) return;
  const days = ["Tue", "Wed", "Thu", "Fri", "Sat", "Sun", "Mon"];
  const today = 0; // demo: today = Tue (offset 0)
  calHead.innerHTML =
    `<div></div>` +
    days.map((d, i) => `<div class="${i === today ? "is-today" : ""}">${d}</div>`).join("");
  const HOURS = ["18", "19", "20", "21", "22"];
  // Density 0..4 per cell — heat varies by time and day
  const DENSITY = [
    [1, 1, 2, 2, 3, 4, 1],
    [3, 3, 3, 4, 4, 4, 2],
    [4, 4, 4, 4, 4, 3, 2],
    [3, 3, 4, 4, 4, 1, 0],
    [1, 1, 2, 3, 3, 0, 0],
  ];
  let html = "";
  HOURS.forEach((h, r) => {
    html += `<div class="cal-time">${h}h</div>`;
    DENSITY[r].forEach((v, c) => {
      const count = v === 0 ? 0 : v + 1;
      html += `<div class="cal-cell" data-h="${v}" data-day="${days[c]}" data-hour="${h}">${count ? `${count}×` : ""}</div>`;
    });
  });
  calGrid.innerHTML = html;
}

// View switching
document.querySelectorAll("[data-view]").forEach((el) => {
  if (el.tagName === "BUTTON") {
    el.addEventListener("click", () => {
      activeView = el.dataset.view;
      document.querySelectorAll(".tab").forEach((t) => t.classList.toggle("is-active", t === el));
      document.querySelectorAll(".view").forEach((v) => (v.hidden = v.dataset.view !== activeView));
      if (activeView === "cal") renderCalendar();
    });
  }
});

document.querySelectorAll(".seg-btn").forEach((btn) =>
  btn.addEventListener("click", () => {
    partyFilter = btn.dataset.party;
    document
      .querySelectorAll(".seg-btn")
      .forEach((b) => b.classList.toggle("is-active", b === btn));
    renderList();
  })
);

document.getElementById("search").addEventListener("input", (e) => {
  query = e.target.value.trim();
  renderList();
});

resList.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action]");
  if (!btn) return;
  const id = btn.dataset.id;
  const b = BOOKINGS.find((x) => x.id === id);
  if (!b) return;
  switch (btn.dataset.action) {
    case "seat":
      b.status = "seated";
      showToast(`${b.name} seated at ${b.table}`);
      break;
    case "noshow":
      b.status = "no-show";
      showToast(`${b.name} marked no-show`);
      break;
    case "cancel":
      b.status = "cancelled";
      showToast(`${b.name} cancelled`);
      break;
    case "reinstate":
      b.status = "confirmed";
      showToast(`${b.name} back on the list`);
      break;
    case "check":
      showToast(`Bill brought to ${b.name}`);
      break;
  }
  renderList();
});

waitList.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action]");
  if (!btn) return;
  showToast("Sent an offer · waiting for confirmation");
});

function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2400);
}

renderList();
renderWaitlist();

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(44, 26, 14, 0.08), 0 2px 6px rgba(44, 26, 14, 0.06);
  --shadow-2: 0 8px 24px rgba(44, 26, 14, 0.12);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html {
  scroll-behavior: smooth;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* ── Nav ── */
.nav {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 14px 28px;
  background: rgba(245, 240, 232, 0.85);
  backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid rgba(44, 26, 14, 0.06);
}
.nav-brand {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.1rem;
  letter-spacing: -0.005em;
  color: var(--ink);
  text-decoration: none;
}
.nav-links {
  display: flex;
  gap: 18px;
  margin-left: auto;
}
.nav-links a {
  color: var(--ink-2);
  text-decoration: none;
  font-size: 0.86rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  transition: color 0.15s;
}
.nav-links a:hover {
  color: var(--terracotta);
}
.nav-cta {
  background: var(--forest);
  color: var(--bone);
  border-radius: 999px;
  padding: 9px 16px;
  font-size: 0.84rem;
  font-weight: 700;
  text-decoration: none;
  transition: background 0.15s;
}
.nav-cta:hover {
  background: var(--forest-d);
}
@media (max-width: 720px) {
  .nav-links {
    display: none;
  }
}

/* ── Hero ── */
.hero {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 40px;
  align-items: center;
  padding: 56px 28px 80px;
  max-width: 1180px;
  margin: 0 auto;
}
.hero-inner {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 540px;
}
.kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--terracotta);
  font-weight: 600;
}
.hero-title {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(2.6rem, 6vw, 4.4rem);
  line-height: 1.02;
  letter-spacing: -0.02em;
  color: var(--ink);
}
.hero-title em {
  font-style: italic;
  color: var(--terracotta-d);
  font-weight: 500;
}
.hero-sub {
  font-size: 1.05rem;
  color: var(--ink-2);
  max-width: 460px;
}
.hero-cta {
  display: flex;
  gap: 10px;
  margin-top: 8px;
  flex-wrap: wrap;
}
.btn-primary,
.btn-ghost {
  border-radius: 999px;
  padding: 13px 22px;
  font-size: 0.92rem;
  font-weight: 700;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  cursor: pointer;
  font-family: inherit;
  border: 1px solid transparent;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.btn-primary {
  background: var(--forest);
  color: var(--bone);
}
.btn-primary:hover {
  background: var(--forest-d);
}
.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: rgba(44, 26, 14, 0.2);
}
.btn-ghost:hover {
  background: var(--bone);
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}
.hero-meta {
  display: grid;
  grid-template-columns: repeat(3, auto);
  gap: 18px;
  margin-top: 18px;
}
.hero-meta div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.hero-meta dt {
  font-size: 0.66rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--warm-gray);
  font-weight: 700;
}
.hero-meta dd {
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--ink);
}
@media (max-width: 720px) {
  .hero {
    grid-template-columns: 1fr;
  }
  .hero-meta {
    grid-template-columns: 1fr;
    gap: 8px;
  }
}

.hero-art {
  position: relative;
  height: 420px;
}
.plate {
  position: absolute;
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-size: 4rem;
  box-shadow: var(--shadow-2);
  border: 1px solid rgba(44, 26, 14, 0.08);
}
.plate-1 {
  width: 240px;
  height: 240px;
  top: 20px;
  left: 14%;
  background: radial-gradient(circle at 30% 30%, var(--bone), var(--cream-2));
  animation: float 6s ease-in-out infinite;
}
.plate-2 {
  width: 160px;
  height: 160px;
  bottom: 30px;
  right: 12%;
  background: radial-gradient(circle at 70% 30%, var(--cream-2), var(--gold-light));
  animation: float 7s ease-in-out infinite reverse;
}
.plate-3 {
  width: 120px;
  height: 120px;
  top: 60px;
  right: 30%;
  background: radial-gradient(circle at 50% 30%, var(--bone), var(--cream));
  animation: float 8s ease-in-out infinite;
}
@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-12px);
  }
}
@media (max-width: 720px) {
  .hero-art {
    display: none;
  }
}

/* ── Strip ── */
.strip {
  background: var(--forest);
  color: var(--bone);
  text-align: center;
  padding: 12px 16px;
  font-size: 0.86rem;
  letter-spacing: 0.06em;
}
.strip em {
  color: var(--gold-light);
  font-style: normal;
  font-weight: 700;
  margin: 0 6px;
}
.strip-star {
  color: var(--gold);
  margin: 0 12px;
}

/* ── Section base ── */
.section,
.story,
.visit,
.reserve {
  max-width: 1080px;
  margin: 0 auto;
  padding: 80px 28px;
  scroll-margin-top: 70px;
}
.section-head {
  text-align: center;
  margin-bottom: 36px;
}
.section-head h2 {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  font-weight: 700;
  letter-spacing: -0.015em;
  margin-top: 6px;
}

/* ── Dishes ── */
.dishes {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}
.dish {
  position: relative;
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-lg);
  padding: 22px 20px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: transform 0.18s, box-shadow 0.18s;
}
.dish:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-2);
}
.dish-glyph {
  font-size: 2rem;
  filter: drop-shadow(0 4px 8px rgba(44, 26, 14, 0.18));
}
.dish h3 {
  font-family: var(--font-display);
  font-size: 1.15rem;
