// Default reservation date to tomorrow
const dateInput = document.querySelector('input[name="date"]');
if (dateInput) {
  const t = new Date();
  t.setDate(t.getDate() + 1);
  dateInput.value = t.toISOString().slice(0, 10);
}

// Reserve form: faux submit + confirmation pill
const form = document.getElementById("reserveForm");
const confirmEl = document.getElementById("reserveConfirm");
form.addEventListener("submit", (e) => {
  e.preventDefault();
  confirmEl.hidden = false;
  const btn = form.querySelector("button");
  const originalText = btn.textContent;
  btn.textContent = "Reserved ✓";
  btn.disabled = true;
  setTimeout(() => {
    btn.textContent = originalText;
    btn.disabled = false;
    confirmEl.hidden = true;
  }, 3000);
});

// Sticky nav: shadow on scroll
const nav = document.getElementById("nav");
const onScroll = () => {
  if (window.scrollY > 8) nav.style.boxShadow = "0 2px 14px rgba(44, 26, 14, 0.08)";
  else nav.style.boxShadow = "";
};
window.addEventListener("scroll", onScroll, { passive: true });
onScroll();

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: linear-gradient(180deg, var(--cream-2) 0%, var(--cream) 100%);
  color: var(--ink);
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 32px 16px;
  -webkit-font-smoothing: antialiased;
}
.page {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
}
.actions {
  display: flex;
  align-items: center;
  gap: 14px;
}
.hint {
  font-size: 0.84rem;
  color: var(--warm-gray);
  font-style: italic;
}
.quiet {
  background: transparent;
  border: 1px solid rgba(44, 26, 14, 0.18);
  color: var(--ink-2);
  border-radius: 999px;
  padding: 8px 16px;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
