  align-items: center;
  text-align: center;
  justify-content: center;
  gap: 16px;
}

.card[data-flipped="true"] .front {
  transform: rotateY(180deg);
}
.card[data-flipped="true"] .back {
  transform: rotateY(360deg);
}

/* Front */
.head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 14px;
}
.kicker {
