  font-weight: 800;
  font-size: 1.7rem;
  letter-spacing: -0.015em;
  margin-top: 2px;
}
.tier {
  background: var(--gold);
  color: var(--ink);
  font-weight: 800;
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  padding: 5px 12px;
  border-radius: 999px;
  align-self: flex-start;
}
.tier[data-t="bronze"] {
  background: #b6724c;
  color: var(--bone);
}
.tier[data-t="gold"] {
  background: var(--gold);
}
.tier[data-t="silver"] {
  background: linear-gradient(135deg, #d9d3c4, #b9b1a0);
  color: var(--ink);
}

.member {
  display: grid;
  grid-template-columns: 56px 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-top: 1px dashed rgba(44, 26, 14, 0.18);
  border-bottom: 1px dashed rgba(44, 26, 14, 0.18);
}
.m-avatar {
  width: 56px;
  height: 56px;
  border-radius: 999px;
  background: var(--forest);
  color: var(--bone);
