const ROTATE_MS = 9000;
const panels = document.querySelectorAll(".panel");
const dots = document.querySelectorAll(".dot-pip");
const pickName = document.getElementById("pickName");

const PICKS = ["Ribeye 14oz", "Carnitas bowl", "Tarta de queso quemada"];

let i = 0;
function rotate() {
  panels.forEach((p, idx) => p.classList.toggle("is-active", idx === i));
  dots.forEach((d, idx) => d.classList.toggle("is-on", idx === i));
  pickName.textContent = PICKS[i];
  i = (i + 1) % panels.length;
}
rotate();
setInterval(rotate, ROTATE_MS);

// Clock + faux order number ticker
const clock = document.getElementById("clock");
const orderNo = document.getElementById("orderNo");
function tick() {
  const d = new Date();
  clock.textContent = `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}
tick();
setInterval(tick, 15000);

let order = 184;
setInterval(() => {
  order = (order % 999) + 1;
  orderNo.textContent = String(order).padStart(4, "0");
}, 7800);

snippets.css:
/* ────────────────────────────────────────────
   KURO 黒 — Omakase palette
   Bone · ink · vermillion · jade
────────────────────────────────────────────── */
:root {
  --bone: #f3efe6;
  --bone-2: #e9e2d2;
  --paper: #fbf8f1;
  --ink: #0c0c0c;
  --ink-2: #3a3a3a;
  --mute: #8a857c;
  --vermillion: #b8362a;
  --jade: #3a6a5a;
  --rule: rgba(12, 12, 12, 0.08);
  --font-display: "Noto Serif JP", "Cormorant Garamond", Georgia, serif;
  --font-body: "Noto Sans JP", "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html {
  scroll-behavior: smooth;
}
body {
  font-family: var(--font-body);
  background: var(--bone);
  color: var(--ink);
  line-height: 1.75;
  font-weight: 300;
  -webkit-font-smoothing: antialiased;
}

/* ── Nav ── */
.nav {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 18px 32px;
  background: rgba(243, 239, 230, 0.84);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--rule);
}
.brand {
  display: inline-flex;
  align-items: baseline;
  gap: 10px;
  text-decoration: none;
  color: var(--ink);
}
.brand-jp {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.45rem;
  color: var(--vermillion);
}
.brand-en {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 1.05rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.nav-links {
  display: flex;
  gap: 26px;
  margin-left: auto;
}
.nav-links a {
  color: var(--ink-2);
  text-decoration: none;
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 500;
  transition: color 0.15s;
}
.nav-links a:hover {
  color: var(--vermillion);
}
.nav-cta {
  border: 1px solid var(--ink);
  color: var(--ink);
  text-decoration: none;
  padding: 9px 18px;
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  transition: background 0.15s, color 0.15s;
}
.nav-cta:hover {
  background: var(--ink);
  color: var(--bone);
}
@media (max-width: 720px) {
  .nav-links {
    display: none;
  }
}

/* ── Hero ── */
.hero {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  max-width: 1200px;
  margin: 0 auto;
  padding: 96px 36px 80px;
  gap: 64px;
  align-items: center;
}
.hero-inner {
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.kicker {
  font-size: 0.7rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--ink-2);
  font-weight: 700;
  font-family: var(--font-body);
  display: inline-flex;
  align-items: center;
  gap: 12px;
}
.vm {
  color: var(--vermillion);
}
.hero-jp {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(5rem, 14vw, 9rem);
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--ink);
}
.hero-en {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(1.3rem, 2.6vw, 1.7rem);
  color: var(--vermillion);
}
.hero-en em {
  font-style: italic;
}
.hero-sub {
  font-size: 1.04rem;
  color: var(--ink-2);
  max-width: 480px;
  margin-top: 2px;
}
.hero-actions {
  display: flex;
  gap: 10px;
  margin-top: 6px;
}
.btn {
  padding: 14px 24px;
  font-family: var(--font-body);
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  cursor: pointer;
  text-decoration: none;
  border: 1px solid transparent;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
  display: inline-block;
}
.btn-ink {
  background: var(--ink);
  color: var(--bone);
}
.btn-ink:hover {
  background: var(--vermillion);
}
.btn-quiet {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn-quiet:hover {
  background: var(--ink);
  color: var(--bone);
}

.seat-status {
  margin-top: 14px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.84rem;
  color: var(--ink-2);
}
.seat-status .dot {
  width: 8px;
  height: 8px;
  background: var(--jade);
  border-radius: 999px;
  box-shadow: 0 0 0 4px rgba(58, 106, 90, 0.18);
}

/* Enso (circle) */
.hero-art {
  position: relative;
  height: 360px;
  display: grid;
  place-items: center;
}
.ensō {
  width: 280px;
  height: 280px;
  border-radius: 999px;
  border: 12px solid var(--ink);
  /* Brush-end illusion */
  border-image: radial-gradient(circle, var(--ink) 70%, transparent 100%) 1;
  position: relative;
  /* Slight open gap on the right */
  -webkit-mask: conic-gradient(from 60deg, black 350deg, transparent 360deg);
  mask: conic-gradient(from 60deg, black 350deg, transparent 360deg);
}
.ensō::after {
  content: "";
  position: absolute;
  inset: -8px;
  border-radius: 999px;
  background: radial-gradient(circle at 30% 30%, rgba(184, 54, 42, 0.12), transparent 50%);
}
.hero-art-cap {
  position: absolute;
  bottom: -6px;
  font-family: var(--font-display);
  font-size: 0.9rem;
  color: var(--mute);
}

@media (max-width: 880px) {
  .hero {
    grid-template-columns: 1fr;
    padding: 64px 28px;
  }
  .hero-art {
    height: 240px;
  }
  .ensō {
    width: 200px;
    height: 200px;
    border-width: 9px;
  }
}

/* ── Brush divider ── */
.brush {
  display: flex;
  justify-content: center;
  gap: 4px;
  padding: 36px 28px 12px;
}
.brush span {
  width: 12px;
  height: 3px;
  background: var(--ink);
  border-radius: 4px;
  opacity: 0.65;
}
.brush span:nth-child(2) {
  width: 26px;
  height: 6px;
  opacity: 0.85;
}
.brush span:nth-child(3) {
  width: 42px;
  height: 7px;
  opacity: 1;
  background: var(--vermillion);
  border-radius: 6px;
}
.brush span:nth-child(4) {
  width: 26px;
  height: 6px;
  opacity: 0.85;
}
.brush span:nth-child(5) {
  width: 12px;
  height: 3px;
  opacity: 0.65;
}

/* ── About ── */
.about {
  max-width: 1080px;
  margin: 0 auto;
  padding: 64px 36px;
  text-align: center;
  scroll-margin-top: 80px;
}
.kicker-jp {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 500;
  color: var(--vermillion);
}
.about h2 {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(2.2rem, 5vw, 3.4rem);
  letter-spacing: -0.015em;
  line-height: 1.1;
  margin-top: 4px;
}
.about h2 em {
  font-style: italic;
  color: var(--vermillion);
}
.about-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 48px;
  margin-top: 36px;
  text-align: left;
  align-items: start;
}
@media (max-width: 720px) {
  .about-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
}
.about-grid p {
  font-size: 1.05rem;
  color: var(--ink-2);
  font-weight: 300;
}
.about-meta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px 28px;
  border-left: 1px solid var(--rule);
  padding-left: 24px;
}
.about-meta div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.about-meta dt {
  font-size: 0.7rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--mute);
  font-weight: 700;
}
.about-meta dd {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 500;
  color: var(--ink);
}

/* ── Omakase ── */
.omakase {
  max-width: 1180px;
  margin: 0 auto;
  padding: 96px 36px;
  scroll-margin-top: 80px;
}
.section-head {
  text-align: center;
  margin-bottom: 56px;
}
.section-head h2 {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(2.2rem, 5vw, 3.4rem);
  letter-spacing: -0.015em;
  line-height: 1.1;
  margin-top: 4px;
}

.course-list {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(13, 1fr);
  gap: 0;
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
  background: var(--paper);
}
@media (max-width: 980px) {
  .course-list {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (max-width: 480px) {
  .course-list {
    grid-template-columns: 1fr;
  }
}

.course {
  padding: 22px 14px;
  border-right: 1px solid var(--rule);
  display: flex;
  flex-direction: column;
  gap: 6px;
  cursor: default;
  transition: background 0.18s;
  position: relative;
}
.course:last-child {
  border-right: none;
}
.course:hover {
  background: var(--bone-2);
}
.course-no {
  font-family: var(--font-mono);
  font-size: 0.74rem;
  color: var(--vermillion);
  font-weight: 700;
  letter-spacing: 0.06em;
}
.course-jp {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 1.05rem;
  line-height: 1.2;
  color: var(--ink);
}
.course-en {
  font-size: 0.74rem;
  color: var(--mute);
  font-weight: 400;
  letter-spacing: 0.02em;
}
.course.is-feat .course-jp {
  color: var(--vermillion);
}

.course-note {
  text-align: center;
  font-size: 0.8rem;
  color: var(--mute);
  margin-top: 18px;
  font-style: italic;
}

/* ── Sake ── */
.sake {
  background: var(--ink);
  color: var(--bone);
  padding: 96px 36px;
}
.sake-inner {
  max-width: 1180px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.sake .kicker {
  color: var(--bone);
}
.sake .kicker-jp {
  color: var(--vermillion);
}
.sake h2 {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: clamp(2rem, 4.5vw, 3rem);
  margin-top: 4px;
  line-height: 1.05;
}
.sake-desc {
  color: rgba(243, 239, 230, 0.7);
  margin-top: 14px;
  font-size: 1rem;
  max-width: 480px;
}
.sake-list {
  list-style: none;
  display: flex;
  flex-direction: column;
}
.sake-list li {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: baseline;
  gap: 8px 18px;
  padding: 18px 0;
  border-bottom: 1px solid rgba(243, 239, 230, 0.12);
}
.sake-list li:last-child {
  border-bottom: none;
}
.sake-name {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: 1.2rem;
}
.sake-name em {
  color: var(--vermillion);
  font-style: italic;
  font-weight: 400;
}
.sake-region {
  grid-column: 1;
  font-size: 0.78rem;
  color: rgba(243, 239, 230, 0.55);
  letter-spacing: 0.04em;
}
.sake-price {
  grid-row: 1 / span 2;
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--bone);
  align-self: center;
}
@media (max-width: 880px) {
  .sake-inner {
    grid-template-columns: 1fr;
    gap: 36px;
  }
}

/* ── Seats ── */
.seats {
  max-width: 1080px;
  margin: 0 auto;
  padding: 96px 36px;
  text-align: center;
  scroll-margin-top: 80px;
}
.counter-art {
  margin: 48px auto 32px;
  max-width: 680px;
  display: grid;
  grid-template-columns: repeat(9, 1fr);
  gap: 8px;
  align-items: center;
}
.seat {
  height: 56px;
  background: var(--paper);
  border: 1px solid var(--rule);
  border-radius: 4px;
  position: relative;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--mute);
  display: grid;
  place-items: center;
}
.seat::before {
  content: attr(data-no);
}
.chef-area {
  height: 76px;
  background: var(--ink);
  color: var(--bone);
  border-radius: 4px;
  display: grid;
  place-items: center;
  font-family: var(--font-display);
  font-size: 0.86rem;
  font-weight: 500;
}
@media (max-width: 720px) {
  .counter-art {
    grid-template-columns: repeat(4, 1fr);
  }
  .chef-area {
    grid-column: 1 / -1;
  }
}

.hours {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 24px auto 0;
  max-width: 480px;
}
.hours div {
  display: flex;
  justify-content: space-between;
  padding: 11px 0;
  border-bottom: 1px solid var(--rule);
  font-size: 0.92rem;
}
.hours dt {
  font-family: var(--font-display);
  font-weight: 500;
}
.hours dd {
  font-family: var(--font-mono);
  font-weight: 600;
}
.hours .closed dd {
  color: var(--mute);
}

/* ── Reserve ── */
.reserve {
  background: var(--paper);
