  font-weight: 400;
  font-size: clamp(1.8rem, 4vw, 2.4rem);
  margin-top: 4px;
  line-height: 1.15;
}
.reserve-note {
  color: var(--ink-2);
  margin-top: 18px;
  font-size: 0.95rem;
  max-width: 380px;
}
.reserve-form {
  background: var(--bone);
  border: 1px solid var(--ink);
  padding: 28px 28px 26px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.form-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.reserve-form label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 0.68rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ink-2);
  font-weight: 700;
}
.reserve-form input,
.reserve-form select {
  background: var(--paper);
  border: 1px solid var(--rule);
  color: var(--ink);
  padding: 11px 14px;
  font-family: inherit;
  font-size: 0.94rem;
  outline: none;
}
.reserve-form input:focus,
.reserve-form select:focus {
  border-color: var(--ink);
}
.full {
  width: 100%;
}
.check {
  flex-direction: row !important;
  align-items: center;
  gap: 10px !important;
  font-size: 0.88rem !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
  color: var(--ink) !important;
  font-weight: 500 !important;
}
.check input {
  width: 16px;
  height: 16px;
  margin: 0;
  accent-color: var(--ink);
}
.btn-ink {
  align-self: flex-start;
  margin-top: 4px;
}
.form-ok {
  color: var(--jade);
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: 0.04em;
}
@media (max-width: 880px) {
  .reserve-inner {
    grid-template-columns: 1fr;
    gap: 36px;
