  text-align: center;
  padding: 48px 28px;
}
.foot-jp {
  font-family: var(--font-display);
  font-size: 2rem;
  color: var(--vermillion);
}
.foot-brand {
  font-family: var(--font-display);
  font-size: 1.2rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  margin-top: 4px;
}
.foot-meta {
  color: rgba(243, 239, 230, 0.55);
  font-size: 0.82rem;
  margin-top: 6px;
}

