const COURSES = [
  { jp: "先付", en: "Amuse" },
  { jp: "汁物", en: "Soup" },
  { jp: "刺身", en: "Sashimi" },
  { jp: "椀盛", en: "Wanmono" },
  { jp: "焼物", en: "Yakimono" },
  { jp: "強肴", en: "Shiizakana", feat: true },
  { jp: "握り", en: "Nigiri 1" },
  { jp: "握り", en: "Nigiri 2" },
  { jp: "握り", en: "Nigiri 3" },
  { jp: "巻物", en: "Maki" },
  { jp: "玉子", en: "Tamago" },
  { jp: "椀", en: "Miso" },
  { jp: "甘味", en: "Dessert" },
];

const list = document.getElementById("courseList");
list.innerHTML = COURSES.map(
  (c, i) => `
  <li class="course ${c.feat ? "is-feat" : ""}">
    <span class="course-no">— ${String(i + 1).padStart(2, "0")}</span>
    <span class="course-jp">${c.jp}</span>
    <span class="course-en">${c.en}</span>
  </li>`
).join("");

// "Seats remaining tonight" — tick down occasionally so the demo feels alive
const seatText = document.getElementById("seatText");
let remaining = 3;
function paint() {
  if (remaining <= 0) seatText.textContent = "Tonight is fully booked · joining the waitlist?";
  else if (remaining === 1) seatText.textContent = "1 seat remaining tonight";
  else seatText.textContent = `${remaining} seats remaining tonight`;
}
paint();
setInterval(() => {
  remaining = Math.max(0, remaining - (Math.random() < 0.3 ? 1 : 0));
  paint();
  if (remaining === 0) {
    setTimeout(() => {
      remaining = 4;
      paint();
    }, 4000);
  }
}, 5200);

// Date default
const di = document.querySelector('input[name="d"]');
if (di) {
  const t = new Date();
  t.setDate(t.getDate() + 3);
  di.value = t.toISOString().slice(0, 10);
}

// Form
const form = document.getElementById("form");
const ok = document.getElementById("ok");
form.addEventListener("submit", (e) => {
  e.preventDefault();
  ok.hidden = false;
  const btn = form.querySelector("button");
  btn.disabled = true;
  setTimeout(() => {
    ok.hidden = true;
    btn.disabled = false;
  }, 2800);
});

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html,
body {
  height: 100%;
}
[hidden] {
  display: none !important;
}
body {
  font-family: var(--font-body);
  background: #1a0f06;
  -webkit-font-smoothing: antialiased;
  display: grid;
  place-items: center;
  padding: 16px;
  user-select: none;
}

.tablet {
  width: 100%;
  max-width: 1180px;
  height: min(96vh, 760px);
  background: #2a2017;
  border-radius: 26px;
  padding: 14px;
  box-shadow: 0 26px 70px rgba(0, 0, 0, 0.55);
}
.screen {
  position: relative;
  height: 100%;
  background: var(--cream);
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  color: var(--ink);
}

/* Top */
.top {
  display: grid;
  grid-template-columns: auto auto 1fr;
  align-items: center;
  gap: 24px;
  padding: 14px 22px;
  background: var(--bone);
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
}
.brand {
  display: flex;
  flex-direction: column;
}
.brand-name {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.05rem;
}
.brand-tag {
  font-size: 0.66rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.table-info {
  border-left: 1px solid rgba(44, 26, 14, 0.16);
  padding-left: 18px;
}
.ti-table {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.1rem;
}
.ti-server {
  font-size: 0.78rem;
  color: var(--warm-gray);
  margin-top: 2px;
}

.progress {
  justify-self: end;
}
.progress ol {
  list-style: none;
  display: flex;
  gap: 8px;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 999px;
  padding: 4px;
}
.progress li {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px 4px 4px;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--warm-gray);
  border-radius: 999px;
}
.progress li.is-done {
  color: var(--success);
}
.progress li.is-current {
  background: var(--forest);
  color: var(--bone);
}
.progress .pill {
  width: 22px;
  height: 22px;
  border-radius: 999px;
  background: var(--cream-2);
  color: var(--ink-2);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  display: grid;
  place-items: center;
  font-weight: 700;
}
.progress li.is-done .pill {
  background: var(--success);
  color: var(--bone);
}
.progress li.is-current .pill {
  background: var(--gold);
  color: var(--ink);
}

/* Catbar */
.catbar {
  display: flex;
  gap: 6px;
  padding: 10px 22px;
  background: var(--bone);
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
  overflow-x: auto;
  flex-shrink: 0;
}
.cat-chip {
  background: transparent;
  border: 1px solid transparent;
  font-family: inherit;
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--ink-2);
  padding: 9px 16px;
  border-radius: 999px;
  cursor: pointer;
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.cat-chip:hover {
  background: var(--cream-2);
}
.cat-chip.is-active {
  background: var(--forest);
  color: var(--bone);
}
.cat-chip-icon {
  font-size: 1rem;
}

/* Board */
.board {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 340px;
  min-height: 0;
}
@media (max-width: 880px) {
  .board {
    grid-template-columns: 1fr;
    grid-template-rows: 1fr auto;
  }
}

/* Menu */
.menu {
  display: flex;
  flex-direction: column;
  min-height: 0;
  border-right: 1px solid rgba(44, 26, 14, 0.08);
}
.menu-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 16px 22px 8px;
}
.menu-head h1 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.5rem;
  letter-spacing: -0.01em;
}
.menu-hint {
  font-size: 0.78rem;
  color: var(--warm-gray);
  font-style: italic;
}
.grid {
  flex: 1;
  overflow-y: auto;
  padding: 8px 22px 22px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 10px;
  align-content: start;
}
.tile {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: 12px;
  padding: 14px 14px 12px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 4px;
  text-align: left;
  font-family: inherit;
  color: var(--ink);
  min-height: 110px;
  transition: border-color 0.15s, background 0.15s, transform 0.05s;
}
.tile:hover {
  border-color: var(--terracotta);
}
.tile:active {
  transform: scale(0.97);
  background: var(--cream-2);
}
.tile.is-flash {
  animation: flash 0.5s ease;
}
@keyframes flash {
  0% {
    background: var(--gold);
    border-color: var(--gold);
  }
  100% {
    background: var(--bone);
    border-color: rgba(44, 26, 14, 0.08);
  }
}
.tile-glyph {
  font-size: 1.5rem;
}
.tile-name {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1rem;
  line-height: 1.15;
}
.tile-desc {
  font-size: 0.74rem;
  color: var(--warm-gray);
  flex: 1;
}
.tile-price {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.86rem;
  color: var(--terracotta-d);
  margin-top: 2px;
}

/* Ticket */
.ticket {
  background: var(--bone);
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.ticket-head {
  padding: 16px 22px 10px;
  border-bottom: 1px dashed rgba(44, 26, 14, 0.18);
}
.ticket-eyebrow {
  font-size: 0.66rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.ticket-meta {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 1.1rem;
  margin-top: 4px;
}

.lines {
  list-style: none;
  flex: 1;
  overflow-y: auto;
  padding: 8px 22px;
}
.lines li {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px dashed rgba(44, 26, 14, 0.1);
  font-size: 0.92rem;
}
.lines li:last-child {
  border-bottom: none;
}
.l-name {
  font-weight: 600;
}
.l-name small {
  display: block;
  color: var(--warm-gray);
  font-weight: 500;
  font-size: 0.74rem;
  font-style: italic;
  margin-top: 2px;
}
.l-qty {
  display: inline-flex;
  align-items: center;
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: 999px;
  padding: 2px;
  gap: 2px;
}
.l-qty button {
  width: 26px;
  height: 26px;
  border-radius: 999px;
  border: none;
  background: transparent;
  color: var(--ink-2);
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  display: grid;
  place-items: center;
}
.l-qty button:hover {
  background: var(--cream-2);
  color: var(--terracotta-d);
}
.l-qty span {
  min-width: 22px;
  text-align: center;
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.82rem;
}
.l-price {
  font-family: var(--font-mono);
  font-weight: 700;
  font-size: 0.92rem;
}

.empty {
  flex: 1;
  display: grid;
  place-items: center;
  padding: 22px;
  color: var(--warm-gray);
  font-style: italic;
  font-size: 0.86rem;
  text-align: center;
}

.totals {
  padding: 12px 22px 8px;
  border-top: 1px dashed rgba(44, 26, 14, 0.18);
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.totals div {
  display: flex;
  justify-content: space-between;
  font-size: 0.86rem;
  color: var(--ink-2);
}
.totals dd {
  font-family: var(--font-mono);
  font-weight: 700;
}
.totals .big {
  margin-top: 4px;
  padding-top: 8px;
  border-top: 1px solid rgba(44, 26, 14, 0.16);
  font-size: 1rem;
  color: var(--ink);
  font-weight: 700;
}
.totals .big dd {
  font-size: 1.15rem;
}

.ticket-actions {
  display: flex;
  gap: 8px;
  padding: 8px 22px;
}
.ghost,
.primary,
.bill-btn,
.bill-confirm {
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.88rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
  padding: 11px 16px;
  border: 1px solid transparent;
}
.ghost {
  background: transparent;
  border-color: rgba(44, 26, 14, 0.2);
  color: var(--ink-2);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.ghost .dot {
  width: 8px;
  height: 8px;
  background: var(--terracotta);
  border-radius: 999px;
}
.ghost.is-called {
  background: var(--terracotta);
  color: var(--bone);
  border-color: var(--terracotta-d);
}
.ghost.is-called .dot {
  background: var(--bone);
  animation: blink 1s ease-in-out infinite;
}
@keyframes blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}
.primary {
  background: var(--forest);
  color: var(--bone);
  flex: 1;
}
.primary:hover:not(:disabled) {
  background: var(--forest-d);
}
.primary:disabled {
  background: var(--warm-gray);
  cursor: not-allowed;
  opacity: 0.7;
}

.bill-btn {
  margin: 4px 22px 18px;
  background: var(--gold);
  color: var(--ink);
  border: none;
  border-radius: 999px;
  padding: 13px 16px;
  font-size: 0.92rem;
}
.bill-btn:hover {
  background: var(--gold-light);
}

/* Toast */
.toast {
  position: absolute;
  bottom: 26px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--forest-d);
  color: var(--bone);
  padding: 10px 18px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.86rem;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35);
  z-index: 6;
}

/* Bill overlay */
.bill-overlay {
  position: absolute;
  inset: 0;
  background: rgba(44, 26, 14, 0.55);
  display: grid;
  place-items: center;
  z-index: 8;
  padding: 24px;
}
.bill-card {
  width: 100%;
  max-width: 480px;
  background: var(--bone);
  border-radius: 16px;
  padding: 28px 30px 22px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.4);
}
.kicker {
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--terracotta);
  font-weight: 700;
}
.bill-card h2 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.5rem;
  margin-top: 2px;
  letter-spacing: -0.01em;
}
.bill-options {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.bill-opt {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: 12px;
  padding: 14px 18px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: inherit;
  font-size: 0.96rem;
  font-weight: 600;
  cursor: pointer;
  color: var(--ink);
}
.bill-opt:hover {
  border-color: var(--terracotta);
}
.bill-opt.is-picked {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.bill-opt .m {
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--terracotta-d);
}
.bill-opt.is-picked .m {
  color: var(--gold);
}
.tip-row {
  display: flex;
  align-items: center;
  gap: 6px;
}
.tip-label {
  font-size: 0.78rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-2);
  font-weight: 700;
  margin-right: 8px;
}
.tip-btn {
  background: var(--cream);
  border: 1px solid rgba(44, 26, 14, 0.12);
  border-radius: 999px;
  padding: 7px 13px;
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--ink-2);
  cursor: pointer;
}
.tip-btn.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.bill-confirm {
  background: var(--gold);
  color: var(--ink);
  display: inline-flex;
  justify-content: center;
  gap: 8px;
  padding: 14px 16px;
}
.bill-confirm:hover {
  background: var(--gold-light);
}
.ghost-link {
  background: transparent;
  border: none;
  font-family: inherit;
  font-size: 0.84rem;
  color: var(--warm-gray);
  cursor: pointer;
  text-decoration: underline;
}

