      { id: "vermut", name: "Vermut casa", desc: "On tap", price: 9, glyph: "🥃" },
      {
        id: "negroni",
        name: "Negroni sbagliato",
        desc: "Campari, prosecco",
        price: 14,
        glyph: "🍸",
      },
      {
        id: "tinto",
        name: "Tinto natural",
        desc: "Glass, ask your server",
        price: 12,
        glyph: "🍷",
      },
      { id: "agua", name: "Agua mineral", desc: "Still or sparkling", price: 5, glyph: "💧" },
      { id: "cafe", name: "Espresso", desc: "Single shot", price: 4, glyph: "☕" },
    ],
  },
  dessert: {
    title: "Postres",
    icon: "🍰",
    items: [
      {
        id: "tarta",
        name: "Tarta de queso",
        desc: "Basque burnt, salted caramel",
        price: 11,
        glyph: "🍰",
      },
      {
        id: "olive",
        name: "Olive oil cake",
        desc: "Crème fraîche, citrus",
        price: 10,
        glyph: "🍋",
      },
      {
        id: "ganache",
        name: "Chocolate ganache",
        desc: "Hazelnut praline",
        price: 12,
        glyph: "🍫",
      },
      { id: "sorbete", name: "Sorbete cítrico", desc: "Citrus, mint", price: 9, glyph: "🍧" },
    ],
  },
  extras: {
    title: "Extras",
    icon: "🌿",
    items: [
      { id: "fries", name: "Patatas truffle", desc: "Parmesan, parsley", price: 8, glyph: "🍟" },
      {
        id: "verduras",
        name: "Verduras a la brasa",
        desc: "Charred, lemon oil",
        price: 9,
        glyph: "🥦",
      },
      { id: "pan-extra", name: "Pan extra", desc: "Plus butter", price: 4, glyph: "🥯" },
    ],
  },
};

const CAT_ORDER = ["apps", "mains", "drinks", "dessert", "extras"];

let activeCat = "mains";
let ticket = []; // { id, name, price, qty, glyph }

const catBar = document.getElementById("catBar");
const menuGrid = document.getElementById("menuGrid");
const catTitle = document.getElementById("catTitle");
const ticketLines = document.getElementById("ticketLines");
const ticketEmpty = document.getElementById("ticketEmpty");
const ticketMeta = document.getElementById("ticketMeta");
const subtotalEl = document.getElementById("subtotal");
const taxEl = document.getElementById("tax");
const totalEl = document.getElementById("total");
const sendBtn = document.getElementById("sendBtn");
const callBtn = document.getElementById("callBtn");
const billBtn = document.getElementById("billBtn");
const toast = document.getElementById("toast");
const billOverlay = document.getElementById("billOverlay");
const billCancel = document.getElementById("billCancel");
const billConfirm = document.getElementById("billConfirm");
const billTotal = document.getElementById("billTotal");
const splitEven = document.getElementById("splitEven");
const splitOne = document.getElementById("splitOne");

function money(v) {
  return `$${v.toFixed(2)}`;
}

function renderCatBar() {
  catBar.innerHTML = CAT_ORDER.map(
    (id) => `<button class="cat-chip ${id === activeCat ? "is-active" : ""}" data-cat="${id}">
      <span class="cat-chip-icon">${CATS[id].icon}</span><span>${CATS[id].title}</span>
    </button>`
  ).join("");
}

function renderMenu() {
  const cat = CATS[activeCat];
  catTitle.textContent = cat.title;
  menuGrid.innerHTML = cat.items
    .map(
      (
        i
      ) => `<button class="tile" data-id="${i.id}" data-name="${i.name}" data-price="${i.price}" data-glyph="${i.glyph}">
        <span class="tile-glyph">${i.glyph}</span>
        <span class="tile-name">${i.name}</span>
        <span class="tile-desc">${i.desc}</span>
        <span class="tile-price">${money(i.price)}</span>
      </button>`
    )
    .join("");
}

function renderTicket() {
  const count = ticket.reduce((n, l) => n + l.qty, 0);
  ticketMeta.textContent = count === 0 ? "0 items" : `${count} ${count === 1 ? "item" : "items"}`;
  ticketEmpty.hidden = ticket.length > 0;
  ticketLines.innerHTML = ticket
    .map(
      (l) => `<li data-id="${l.id}">
        <div class="l-name">${l.name}</div>
        <div class="l-qty">
          <button data-action="dec">−</button>
          <span>${l.qty}</span>
          <button data-action="inc">+</button>
        </div>
        <span class="l-price">${money(l.price * l.qty)}</span>
      </li>`
    )
    .join("");
  const subtotal = ticket.reduce((s, l) => s + l.price * l.qty, 0);
  const tax = subtotal * TAX_RATE;
  const total = subtotal + tax;
  subtotalEl.textContent = money(subtotal);
  taxEl.textContent = money(tax);
  totalEl.textContent = money(total);
  sendBtn.disabled = ticket.length === 0;
  billTotal.textContent = money(total * 1.18);
  splitEven.textContent = `${money((total * 1.18) / 2)} each`;
  splitOne.textContent = money(total * 1.18);
}

function addItem(id, name, price, glyph, tile) {
  const existing = ticket.find((l) => l.id === id);
  if (existing) existing.qty += 1;
  else ticket.push({ id, name, price: Number(price), glyph, qty: 1 });
  renderTicket();
  if (tile) {
    tile.classList.remove("is-flash");
    void tile.offsetWidth;
    tile.classList.add("is-flash");
  }
}

function showToast(msg) {
  toast.textContent = msg;
  toast.hidden = false;
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => (toast.hidden = true), 2200);
}

catBar.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-cat]");
  if (!btn) return;
  activeCat = btn.dataset.cat;
  renderCatBar();
  renderMenu();
});

menuGrid.addEventListener("click", (e) => {
  const tile = e.target.closest("[data-id]");
  if (!tile) return;
  addItem(tile.dataset.id, tile.dataset.name, tile.dataset.price, tile.dataset.glyph, tile);
});

ticketLines.addEventListener("click", (e) => {
  const btn = e.target.closest("[data-action]");
  if (!btn) return;
  const li = btn.closest("[data-id]");
  if (!li) return;
  const line = ticket.find((l) => l.id === li.dataset.id);
  if (!line) return;
  if (btn.dataset.action === "inc") line.qty += 1;
  if (btn.dataset.action === "dec") {
    line.qty -= 1;
    if (line.qty <= 0) ticket = ticket.filter((l) => l.id !== line.id);
  }
  renderTicket();
});

sendBtn.addEventListener("click", () => {
  if (ticket.length === 0) return;
  const items = ticket.reduce((n, l) => n + l.qty, 0);
  showToast(`Sent ${items} item${items > 1 ? "s" : ""} to the kitchen.`);
  // Visually mark mains complete after second send for the demo
  document.querySelector(".progress .is-current")?.classList.remove("is-current");
});

callBtn.addEventListener("click", () => {
  callBtn.classList.add("is-called");
  showToast("We let your server know — they're on their way.");
  setTimeout(() => callBtn.classList.remove("is-called"), 4000);
});

billBtn.addEventListener("click", () => {
  billOverlay.hidden = false;
});
billCancel.addEventListener("click", () => {
  billOverlay.hidden = true;
});
billOverlay.addEventListener("click", (e) => {
  if (e.target === billOverlay) billOverlay.hidden = true;
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") billOverlay.hidden = true;
});
document.querySelectorAll(".bill-opt").forEach((b) =>
  b.addEventListener("click", () => {
    document.querySelectorAll(".bill-opt").forEach((x) => x.classList.remove("is-picked"));
    b.classList.add("is-picked");
  })
);
document.querySelectorAll(".tip-btn").forEach((b) =>
  b.addEventListener("click", () => {
    document.querySelectorAll(".tip-btn").forEach((x) => x.classList.remove("is-active"));
    b.classList.add("is-active");
    const tip = Number(b.dataset.tip) / 100;
    const subtotal = ticket.reduce((s, l) => s + l.price * l.qty, 0);
    const tax = subtotal * TAX_RATE;
    const total = subtotal + tax + subtotal * tip;
    billTotal.textContent = money(total);
    splitEven.textContent = `${money(total / 2)} each`;
    splitOne.textContent = money(total);
  })
);
billConfirm.addEventListener("click", () => {
  billOverlay.hidden = true;
  showToast("Your server is bringing the bill.");
});

// Seed an in-progress order so the ticket has something
ticket = [
  { id: "burrata", name: "Burrata huerta", price: 16, qty: 1, glyph: "🍅" },
  { id: "pulpo", name: "Pulpo brasa", price: 19, qty: 1, glyph: "🐙" },
  { id: "ribeye", name: "Ribeye 14oz", price: 48, qty: 1, glyph: "🥩" },
  { id: "tinto", name: "Tinto natural", price: 12, qty: 2, glyph: "🍷" },
];

renderCatBar();
renderMenu();
renderTicket();

snippets.css:
:root {
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(44, 26, 14, 0.08), 0 2px 6px rgba(44, 26, 14, 0.06);
  --shadow-2: 0 8px 24px rgba(44, 26, 14, 0.12);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

/* Nav */
.nav {
  padding: 16px 28px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
  background: var(--bone);
}
.brand {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 800;
  color: var(--ink);
  text-decoration: none;
}
.back {
  font-size: 0.84rem;
  color: var(--ink-2);
  text-decoration: none;
  font-weight: 600;
}
.back:hover {
  color: var(--terracotta-d);
}

/* Head */
.head {
  text-align: center;
  padding: 56px 28px 28px;
  max-width: 760px;
  margin: 0 auto;
}
.kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--terracotta);
  font-weight: 700;
  margin-bottom: 6px;
}
.head h1 {
  font-family: var(--font-display);
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 700;
  letter-spacing: -0.015em;
}
.sub {
  margin-top: 10px;
  font-size: 0.95rem;
  color: var(--ink-2);
}

/* Chips */
.chips {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
  padding: 12px 28px 32px;
  max-width: 1080px;
  margin: 0 auto;
}
.chip {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.12);
  color: var(--ink-2);
  border-radius: 999px;
  padding: 8px 14px;
  font-family: inherit;
  font-size: 0.84rem;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.chip span {
  font-family: ui-monospace, monospace;
  font-size: 0.66rem;
  font-weight: 700;
  background: var(--cream-2);
  color: var(--warm-gray);
  padding: 2px 7px;
  border-radius: 999px;
}
.chip:hover {
  border-color: var(--terracotta);
  color: var(--terracotta-d);
}
.chip.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.chip.is-active span {
  background: rgba(250, 247, 241, 0.18);
  color: var(--gold-light);
}

/* Masonry — CSS columns */
.masonry {
  max-width: 1080px;
  margin: 0 auto;
  padding: 0 28px 64px;
  column-count: 3;
  column-gap: 14px;
}
@media (max-width: 880px) {
  .masonry {
    column-count: 2;
  }
}
@media (max-width: 540px) {
  .masonry {
    column-count: 1;
  }
}
.tile {
  break-inside: avoid;
  margin-bottom: 14px;
  position: relative;
  overflow: hidden;
  border-radius: var(--r-md);
  cursor: pointer;
  box-shadow: var(--shadow-1);
  border: 1px solid rgba(44, 26, 14, 0.08);
  background: var(--bone);
  display: flex;
  flex-direction: column;
}
.tile.is-hidden {
  display: none;
}
.tile-art {
  position: relative;
  display: grid;
  place-items: center;
  font-size: 4rem;
}
.tile-art::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(44, 26, 14, 0.32) 100%);
  pointer-events: none;
}
.tile-art > .glyph {
  position: relative;
  filter: drop-shadow(0 6px 12px rgba(44, 26, 14, 0.32));
}
.tile-cap {
  padding: 12px 14px 14px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
}
.tile-name {
  font-family: var(--font-display);
  font-size: 0.98rem;
  font-weight: 700;
}
.tile-meta {
  font-size: 0.7rem;
  color: var(--warm-gray);
  margin-top: 2px;
}
.tile-tag {
  font-size: 0.62rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--terracotta);
  background: var(--cream-2);
  padding: 3px 8px;
  border-radius: 999px;
  white-space: nowrap;
}

/* Tile colour variants */
.tile.h-1 .tile-art {
  height: 220px;
  background: linear-gradient(135deg, #c1714a, #a05a38);
}
.tile.h-2 .tile-art {
  height: 300px;
  background: linear-gradient(135deg, #2d4a3e, #1e3329);
}
.tile.h-3 .tile-art {
  height: 260px;
  background: linear-gradient(135deg, #c9a84c, #e6c97a);
}
.tile.h-4 .tile-art {
  height: 200px;
  background: linear-gradient(135deg, #5e7a4a, #3d4a32);
}
.tile.h-5 .tile-art {
  height: 280px;
  background: linear-gradient(135deg, #b3432a, #c1714a);
}
.tile.h-6 .tile-art {
  height: 240px;
  background: linear-gradient(135deg, #4a3828, #2c1a0e);
}
.tile.h-7 .tile-art {
  height: 320px;
  background: linear-gradient(135deg, #d99020, #c9a84c);
}
.tile.h-8 .tile-art {
  height: 220px;
  background: linear-gradient(135deg, #7a6a58, #4a3828);
}

.tile:hover .tile-cap {
  background: var(--bone);
}
.tile:hover .tile-art {
  transform: scale(1.02);
}
.tile-art {
  transition: transform 0.4s ease;
}

/* Lightbox */
.lb {
  position: fixed;
  inset: 0;
  background: rgba(44, 26, 14, 0.92);
  display: grid;
  place-items: center;
  z-index: 80;
  animation: fadeIn 0.18s ease;
}

.lb[hidden] {
  display: none;
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.lb-x,
.lb-nav {
  position: absolute;
  background: rgba(250, 247, 241, 0.12);
  border: 1px solid rgba(250, 247, 241, 0.18);
  color: var(--bone);
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s;
  display: grid;
  place-items: center;
}
.lb-x {
  top: 18px;
  right: 18px;
  width: 38px;
  height: 38px;
  border-radius: 999px;
}
.lb-nav {
  top: 50%;
  width: 46px;
  height: 46px;
  border-radius: 999px;
  font-size: 1.5rem;
  transform: translateY(-50%);
}
.lb-prev {
  left: 18px;
}
.lb-next {
  right: 18px;
}
.lb-x:hover,
.lb-nav:hover {
  background: rgba(250, 247, 241, 0.22);
}

.lb-figure {
  max-width: min(900px, 92vw);
  max-height: 80vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}
.lb-tile {
  width: 100%;
  height: min(560px, 72vh);
  border-radius: var(--r-md);
  display: grid;
  place-items: center;
  font-size: 8rem;
  box-shadow: 0 16px 50px rgba(0, 0, 0, 0.5);
}
.lb-cap {
  color: var(--bone);
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 500;
  text-align: center;
}
.lb-cap em {
  color: var(--gold-light);
  font-style: italic;
  font-weight: 500;
}

/* Footer */
.footer {
  border-top: 1px solid rgba(44, 26, 14, 0.08);
  background: var(--bone);
  text-align: center;
  padding: 28px;
}
.footer-brand {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 800;
}
.footer-meta {
  font-size: 0.82rem;
  color: var(--warm-gray);
  margin-top: 4px;
}

