/* ─────────────────────────────────────────────
   Restaurant theme — shared warm palette
   Used across ops + customer + marketing surfaces.
   Per-resource: copy this :root block verbatim.
───────────────────────────────────────────── */
:root {
  /* Surface */
  --cream: #f5f0e8;
  --cream-2: #ece4d4;
  --bone: #faf7f1;
  /* Brand */
  --terracotta: #c1714a;
  --terracotta-d: #a05a38;
  --forest: #2d4a3e;
  --forest-d: #1e3329;
  --gold: #c9a84c;
  --gold-light: #e6c97a;
  /* Ink */
  --ink: #2c1a0e;
  --ink-2: #4a3828;
  --warm-gray: #7a6a58;
  /* State */
  --success: #4f7a3a;
  --danger: #b3432a;
  --warning: #d99020;
  /* Type */
  --font-display: "Playfair Display", Georgia, serif;
  --font-body: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  /* Radius / shadow */
  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 16px;
  --shadow-1: 0 1px 2px rgba(44, 26, 14, 0.08), 0 2px 6px rgba(44, 26, 14, 0.06);
  --shadow-2: 0 8px 24px rgba(44, 26, 14, 0.12);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background: var(--cream);
  color: var(--ink);
  min-height: 100vh;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
}

/* ── Hero ── */
.hero {
  padding: 56px 24px 32px;
  text-align: center;
  background: linear-gradient(180deg, var(--bone) 0%, var(--cream) 100%);
  border-bottom: 1px solid rgba(44, 26, 14, 0.08);
}
.hero-inner {
  max-width: 720px;
  margin: 0 auto;
}
.kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: var(--terracotta);
  font-weight: 600;
  margin-bottom: 12px;
}
.brand {
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 5vw, 3.4rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--ink);
  margin-bottom: 8px;
}
.tagline {
  font-size: 1rem;
  color: var(--warm-gray);
  font-style: italic;
}

/* ── Sticky category nav ── */
.catnav {
  position: sticky;
  top: 0;
  z-index: 30;
  background: var(--bone);
  border-bottom: 1px solid rgba(44, 26, 14, 0.1);
  box-shadow: var(--shadow-1);
}
.catnav-inner {
  max-width: 980px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 12px 16px;
  flex-wrap: wrap;
}
.cat-tab {
  background: transparent;
  border: 1px solid transparent;
  color: var(--ink-2);
  font-family: var(--font-body);
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  padding: 8px 14px;
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.cat-tab:hover {
  background: var(--cream-2);
  color: var(--ink);
}
.cat-tab.is-active {
  background: var(--forest);
  color: var(--bone);
  border-color: var(--forest-d);
}
.search {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--cream-2);
  border-radius: 999px;
  padding: 6px 12px;
  color: var(--warm-gray);
}
.search input {
  background: transparent;
  border: none;
  outline: none;
  font-family: var(--font-body);
  font-size: 0.85rem;
  color: var(--ink);
  width: 180px;
}
.search input::placeholder {
  color: var(--warm-gray);
}

/* ── Sections ── */
.carta {
  max-width: 980px;
  margin: 0 auto;
  padding: 32px 24px 80px;
}
.section {
  margin-top: 48px;
  scroll-margin-top: 72px;
}
.section:first-child {
  margin-top: 8px;
}
.section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 24px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(44, 26, 14, 0.12);
}
.section-title {
  font-family: var(--font-display);
  font-size: 1.7rem;
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.01em;
}
.section-note {
  font-size: 0.78rem;
  color: var(--warm-gray);
  font-style: italic;
}

/* ── Grid + item cards ── */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 18px;
}
.dish {
  background: var(--bone);
  border: 1px solid rgba(44, 26, 14, 0.08);
  border-radius: var(--r-md);
  padding: 18px 18px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: transform 0.18s, box-shadow 0.18s, border-color 0.18s;
  cursor: pointer;
}
.dish:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-2);
  border-color: rgba(193, 113, 74, 0.4);
}
.dish.is-featured {
  background: linear-gradient(180deg, var(--bone) 0%, var(--cream) 100%);
  border-color: var(--gold);
}
.dish-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: baseline;
}
.dish-name {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 600;
  color: var(--ink);
  line-height: 1.25;
}
.dish-price {
  font-family: var(--font-mono);
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--terracotta-d);
  white-space: nowrap;
}
.dish-desc {
  font-size: 0.88rem;
  color: var(--ink-2);
  line-height: 1.5;
}
.dish-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}
.chip {
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--cream-2);
  color: var(--ink-2);
}
.chip[data-tone="veg"] {
  background: rgba(79, 122, 58, 0.15);
  color: var(--success);
}
.chip[data-tone="hot"] {
  background: rgba(179, 67, 42, 0.15);
  color: var(--danger);
}
.chip[data-tone="gf"] {
  background: rgba(201, 168, 76, 0.18);
  color: #8a7325;
}
.chip[data-tone="signature"] {
  background: var(--gold);
  color: var(--ink);
}

/* ── Empty / footer ── */
.empty {
  text-align: center;
  padding: 32px 24px;
  color: var(--warm-gray);
  font-style: italic;
}
.footer {
  border-top: 1px solid rgba(44, 26, 14, 0.1);
  text-align: center;
  padding: 24px;
  font-size: 0.78rem;
  color: var(--warm-gray);
}

/* ── Hidden state for filter ── */
.dish[hidden],
.section[hidden] {
  display: none !important;
}

/* ── Small screens ── */
@media (max-width: 640px) {
  .catnav-inner {
    padding: 10px 12px;
  }
  .cat-tab {
    padding: 6px 10px;
    font-size: 0.78rem;
  }
  .search {
    margin-left: 0;
    width: 100%;
  }
  .search input {
    width: 100%;
  }
}

