html,
body {
  height: 100%;
  overflow-x: hidden;
}

body {
  background: #030712;
  color: #e2e8f0;
}

/* ─── 3D perspective stage ─── */
.space-bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  perspective: 800px;
  perspective-origin: 50% 50%;
  overflow: hidden;
  pointer-events: none;
}

/* ─── Individual code panels ─── */
.space-panel {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 200px;
  transform: translate(-50%, -50%);
  transform-style: preserve-3d;
  border: 1px solid color-mix(in srgb, var(--color) 35%, transparent);
  border-radius: 8px;
  background: rgba(3, 7, 18, 0.85);
  padding: 10px 12px;
  will-change: transform, opacity;
  transition: opacity 0.1s linear;
}

.space-panel::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 8px;
  background: color-mix(in srgb, var(--color) 6%, transparent);
}

/* ─── Code text inside panels ─── */
.space-code {
  position: relative;
  font-family: "Fira Code", "Cascadia Code", "Consolas", ui-monospace, monospace;
  font-size: 0.625rem;
  line-height: 1.6;
  color: color-mix(in srgb, var(--color) 80%, #e2e8f0 20%);
  white-space: pre;
  overflow: hidden;
  pointer-events: none;
  user-select: none;
}

/* ─── Hero content (on top of the background) ─── */
.hero-content {
  position: relative;
  z-index: 10;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  text-align: center;
  padding: 2rem;
}

.hero-title {
  font-size: clamp(3rem, 10vw, 7rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  color: #f8fafc;
  line-height: 1;
}

.hero-sub {
  font-size: clamp(1rem, 3vw, 1.5rem);
  color: rgba(255, 255, 255, 0.4);
  letter-spacing: 0.05em;
}

@media (prefers-reduced-motion: reduce) {
  .space-panel {
    display: none;
  }
}

