/* Trigger button */
.menu-wrapper {
  position: relative;
  display: inline-flex;
}

.menu-trigger {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.5);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.menu-trigger:hover,
.menu-trigger[aria-expanded="true"] {
  background: rgba(255, 255, 255, 0.1);
  color: #f8fafc;
  border-color: rgba(255, 255, 255, 0.14);
}

/* Dropdown panel */
.action-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 50;
  min-width: 200px;
  padding: 6px;
  border-radius: 10px;
  background: #161616;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.6);
  opacity: 0;
  transform: scale(0.95) translateY(-4px);
  transform-origin: top right;
  pointer-events: none;
  transition: opacity 0.15s, transform 0.15s;
}

.action-menu.open {
  opacity: 1;
  transform: scale(1) translateY(0);
  pointer-events: auto;
}

/* Groups */
.menu-group {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.menu-group-label {
  font-size: 0.65rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255, 255, 255, 0.28);
  padding: 4px 10px 2px;
}

/* Items */
.menu-item {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  padding: 7px 10px;
  border-radius: 6px;
  background: none;
  border: none;
  color: rgba(255, 255, 255, 0.65);
  font-size: 0.8125rem;
  font-family: inherit;
  cursor: pointer;
  text-align: left;
  transition: background 0.12s, color 0.12s;
}

.menu-item:hover {
  background: rgba(255, 255, 255, 0.07);
  color: #f8fafc;
}

.menu-item--danger:hover {
  background: rgba(248, 113, 113, 0.1);
  color: #f87171;
}

/* Divider */
.menu-divider {
  border: none;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  margin: 4px 0;
}

/* Snackbar */
.snackbar {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(12px);
  padding: 8px 18px;
  border-radius: 8px;
  background: #f8fafc;
  color: #0a0a0a;
  font-size: 0.8125rem;
  font-weight: 500;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
  white-space: nowrap;
  z-index: 200;
}

.snackbar.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

