/* ── Reset & Base ── */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg-primary: #0a0a0a;
  --bg-card: #111111;
  --bg-row-alt: #0e0e0e;
  --bg-hover: #181818;
  --bg-input: #181818;
  --border: #222222;
  --border-light: #333333;
  --text-primary: #f0f0f0;
  --text-secondary: #999999;
  --text-muted: #666666;
  --accent-blue: #3b82f6;
  --accent-green: #22c55e;
  --accent-amber: #f59e0b;
  --accent-red: #ef4444;
  --radius: 10px;
}

html {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
}

body {
  min-height: 100vh;
  padding-block: 40px;
  padding-inline: 24px;
}

button {
  font: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

/* ── Page ── */
.page {
  max-inline-size: 1100px;
  margin-inline: auto;
}

/* ── Toolbar ── */
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-block-end: 24px;
  flex-wrap: wrap;
  gap: 12px;
}

.toolbar-start {
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.page-title {
  font-size: 1.5rem;
  font-weight: 700;
}

.record-count {
  font-size: 0.82rem;
  color: var(--text-muted);
}

.dir-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-block: 6px;
  padding-inline: 14px;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--accent-blue);
  transition: background 0.2s;
}

.dir-toggle:hover {
  background: var(--bg-card);
}

/* ── Table shell ── */
.table-shell {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

/* Table toolbar */
.table-toolbar {
  padding-block: 16px;
  padding-inline: 20px;
  border-block-end: 1px solid var(--border);
}

.search-wrap {
  position: relative;
  max-inline-size: 320px;
}

.search-icon {
  position: absolute;
  inset-inline-start: 12px;
  inset-block-start: 50%;
  transform: translateY(-50%);
  font-size: 0.9rem;
  color: var(--text-muted);
  pointer-events: none;
}

.search-input {
  inline-size: 100%;
  padding-block: 8px;
  padding-inline-start: 36px;
  padding-inline-end: 12px;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--text-primary);
  font: inherit;
  font-size: 0.85rem;
  outline: none;
  transition: border-color 0.2s;
}

.search-input:focus {
  border-color: var(--accent-blue);
}

.search-input::placeholder {
  color: var(--text-muted);
}

/* ── Table ── */
.table-scroll {
  overflow-x: auto;
}

.data-table {
  inline-size: 100%;
  border-collapse: collapse;
  white-space: nowrap;
}

.data-table thead {
  position: sticky;
  inset-block-start: 0;
  z-index: 5;
}

.data-table th {
  padding-block: 12px;
  padding-inline: 20px;
  background: var(--bg-primary);
  border-block-end: 1px solid var(--border);
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  text-align: start;
  user-select: none;
}

.th-content {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sortable {
  cursor: pointer;
  transition: color 0.2s;
}

.sortable:hover {
  color: var(--text-secondary);
}

.sortable.asc .sort-icon::after,
.sortable.desc .sort-icon::after {
  font-size: 0.7rem;
  margin-inline-start: 2px;
}

.sortable.asc .sort-icon::after {
  content: "\25B2";
}
.sortable.desc .sort-icon::after {
  content: "\25BC";
}

.sortable.asc,
.sortable.desc {
  color: var(--accent-blue);
}

.data-table td {
  padding-block: 14px;
  padding-inline: 20px;
  border-block-end: 1px solid var(--border);
  font-size: 0.88rem;
  text-align: start;
}

/* Zebra striping */
.data-table tbody tr:nth-child(even) {
  background: var(--bg-row-alt);
}

.data-table tbody tr:hover {
  background: var(--bg-hover);
}

/* Name cell */
.name-cell {
  display: flex;
  align-items: center;
  gap: 12px;
}

.name-avatar {
  inline-size: 32px;
  block-size: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.72rem;
  font-weight: 600;
  color: #fff;
  flex-shrink: 0;
}

.name-text {
  font-weight: 500;
}

/* Status badge */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding-block: 3px;
  padding-inline: 10px;
  border-radius: 20px;
  font-size: 0.76rem;
  font-weight: 500;
}

.status-badge .dot {
  inline-size: 6px;
  block-size: 6px;
  border-radius: 50%;
}

.status-badge.active {
  background: rgba(34, 197, 94, 0.12);
  color: var(--accent-green);
}
.status-badge.active .dot {
  background: var(--accent-green);
}
.status-badge.away {
  background: rgba(245, 158, 11, 0.12);
  color: var(--accent-amber);
}
.status-badge.away .dot {
  background: var(--accent-amber);
}
.status-badge.offline {
  background: rgba(102, 102, 102, 0.15);
  color: var(--text-muted);
}
.status-badge.offline .dot {
  background: var(--text-muted);
}

/* ── Pagination ── */
.pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-block: 14px;
  padding-inline: 20px;
  border-block-start: 1px solid var(--border);
  flex-wrap: wrap;
  gap: 12px;
}

.page-info {
  font-size: 0.82rem;
  color: var(--text-muted);
}

.page-controls {
  display: flex;
  align-items: center;
  gap: 4px;
}

.page-btn {
  padding-block: 6px;
  padding-inline: 12px;
  background: var(--bg-primary);
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 0.82rem;
  color: var(--text-secondary);
  transition: all 0.2s;
}

.page-btn:hover:not(:disabled) {
  background: var(--bg-hover);
  border-color: var(--border-light);
  color: var(--text-primary);
}

.page-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.page-btn.active {
  background: var(--accent-blue);
  border-color: var(--accent-blue);
  color: #fff;
}

/* Flip pagination chevrons in RTL */
[dir="rtl"] .page-btn.prev,
[dir="rtl"] .page-btn.next {
  transform: scaleX(-1);
}

/* ── Responsive ── */
@media (max-width: 640px) {
  body {
    padding-inline: 16px;
  }

  .data-table th,
  .data-table td {
    padding-inline: 14px;
  }
}

