  font-size: 1rem;
  flex-shrink: 0;
}

.status-name {
  flex: 1;
  font-size: 0.875rem;
}

.status-label {
  font-size: 0.6875rem;
  font-weight: 600;
  padding: 0.125rem 0.5rem;
  border-radius: 1rem;
}

.status-label-green {
  background: #052e16;
  color: #4ade80;
}
.status-label-yellow {
  background: #422006;
  color: #fbbf24;
}
.status-label-red {
  background: #450a0a;
  color: #f87171;
}

/* ── Bar chart ── */
.chart {
  padding: 0.5rem 0;
}

.chart-bars {
  display: flex;
  justify-content: space-around;
  align-items: flex-end;
  height: 180px;
  gap: 1.5rem;
  padding: 0 1rem;
  margin-bottom: 1rem;
}

.bar-group {
  display: flex;
  align-items: flex-end;
  gap: 0.25rem;
  flex: 1;
  height: 100%;
  position: relative;
  padding-bottom: 1.5rem;
}

.bar {
  flex: 1;
  border-radius: 0.25rem 0.25rem 0 0;
  min-height: 4px;
  position: relative;
  transition: height 0.3s;
}

.bar-val {
  position: absolute;
  top: -1.25rem;
  left: 50%;
  transform: translateX(-50%);
  font-size: 0.625rem;
  font-weight: 600;
  color: #a3a3a3;
  white-space: nowrap;
}

.bar-organic {
  background: #22c55e;
}
.bar-paid {
  background: #ef4444;
}
.bar-referral {
  background: #3b82f6;
}

.bar-label {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
