.legend-organic {
  background: #22c55e;
}
.legend-paid {
  background: #ef4444;
}
.legend-referral {
  background: #3b82f6;
}

/* ── Alerts ── */
.alert-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.alert {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.875rem 1rem;
  border-radius: 0.5rem;
  border: 1px solid #262626;
  font-size: 0.8125rem;
