*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  background: #0a0a0a;
  color: #e4e4e7;
  line-height: 1.6;
  min-height: 100vh;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.demo {
  max-width: 720px;
  margin: 0 auto;
  padding: 3rem 1.5rem;
}

.demo-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: #fafafa;
  letter-spacing: -0.02em;
}

.demo-sub {
  color: #a1a1aa;
  margin-top: 0.25rem;
  font-size: 0.95rem;
}

/* Carousel */
.carousel-wrapper {
  margin-top: 2rem;
}

.carousel {
  position: relative;
  background: #111113;
  border: 1px solid #27272a;
  border-radius: 14px;
  overflow: hidden;
}

.carousel-viewport {
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.4s ease;
}

.carousel-slide {
  min-width: 100%;
  flex-shrink: 0;
}

/* Slide Content */
.slide-content {
  padding: 3rem 2.5rem;
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.slide-badge {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 0.25rem 0.65rem;
  border-radius: 100px;
  width: fit-content;
  margin-bottom: 1rem;
}

.slide-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: #fafafa;
  margin-bottom: 0.75rem;
  letter-spacing: -0.02em;
}

.slide-desc {
  font-size: 0.925rem;
  color: #a1a1aa;
  max-width: 480px;
  line-height: 1.7;
}

/* Slide Color Themes */
.slide-content--blue {
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.08), rgba(59, 130, 246, 0.02));
}

.slide-content--blue .slide-badge {
