.carousel-playpause[data-playing="false"] .icon-pause {
  display: none;
}

.carousel-playpause[data-playing="false"] .icon-play {
  display: block;
}

.carousel-playpause .icon-play[hidden] {
  display: none;
}

@media (max-width: 640px) {
  .demo {
    padding: 1.5rem 0.75rem;
  }

  .demo-title {
    font-size: 1.35rem;
  }

  .demo-sub {
    font-size: 0.85rem;
  }

  .carousel-wrapper {
    margin-top: 1.25rem;
  }

  .slide-content {
    padding: 1.5rem 1.25rem;
    min-height: 200px;
  }

  .slide-badge {
    font-size: 0.65rem;
    padding: 0.2rem 0.5rem;
    margin-bottom: 0.75rem;
  }

  .slide-title {
    font-size: 1.15rem;
    margin-bottom: 0.5rem;
  }

  .slide-desc {
    font-size: 0.82rem;
    line-height: 1.6;
  }

  .carousel-controls {
    padding: 0.75rem 1rem;
    gap: 0.75rem;
  }

  .carousel-btn {
    width: 32px;
    height: 32px;
  }

  .carousel-playpause {
    top: 0.75rem;
    right: 0.75rem;
    padding: 0.3rem 0.6rem;
    font-size: 0.7rem;
  }

  .carousel-dot {
    width: 8px;
    height: 8px;
  }

  .carousel-dot--active {
    width: 20px;
  }
}

@media (max-width: 380px) {
  .slide-content {
    padding: 1.25rem 1rem;
    min-height: 180px;
  }

  .slide-title {
    font-size: 1.05rem;
  }

  .slide-desc {
    font-size: 0.78rem;
  }
}

