*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #0a0a0a;
  color: #e4e4e7;
  line-height: 1.7;
  min-height: 100vh;
}

.container {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 2rem;
  max-width: 1100px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

/* ── Drawer toggle (hidden on desktop) ── */
.drawer-toggle {
  display: none;
}

.drawer-backdrop {
  display: none;
}

/* ── Mobile: drawer pattern ── */
@media (max-width: 768px) {
  .container {
    grid-template-columns: 1fr;
    gap: 0;
    padding: 1rem 0.75rem;
  }

  /* Hide controls as inline block, convert to drawer */
  .controls {
    position: fixed;
    inset-inline-start: 0;
    inset-inline-end: 0;
    bottom: 0;
    top: auto;
    z-index: 1000;
    border-radius: 16px 16px 0 0;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-bottom: none;
    background: #111113;
    padding: 1.25rem 1.25rem 2rem;
    transform: translateY(100%);
    transition: transform 0.3s ease;
    max-height: 70vh;
    overflow-y: auto;
  }

  .controls.drawer-open {
    transform: translateY(0);
  }

  /* Drawer handle */
  .controls::before {
    content: "";
    display: block;
    width: 36px;
    height: 4px;
    background: rgba(255, 255, 255, 0.2);
    border-radius: 2px;
    margin: 0 auto 1rem;
  }

  .controls__title {
    font-size: 0.85rem;
    margin-bottom: 1rem;
  }

  .controls__group {
    margin-bottom: 1rem;
  }

  .controls__modes {
    gap: 0.25rem;
  }

  .mode-btn {
    padding: 0.5rem 0.25rem;
    font-size: 0.7rem;
  }

  /* FAB toggle */
  .drawer-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    position: fixed;
    bottom: 1.25rem;
    right: 1.25rem;
    z-index: 999;
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: #8b5cf6;
    color: #fff;
    border: none;
    cursor: pointer;
    box-shadow: 0 4px 16px rgba(139, 92, 246, 0.4);
    transition: transform 0.2s, background 0.2s;
  }

  .drawer-toggle:hover {
    transform: scale(1.05);
  }

  .drawer-toggle.active {
    background: #6d28d9;
    transform: rotate(90deg);
  }

  /* Backdrop */
  .drawer-backdrop {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: 999;
  }

  .drawer-backdrop.active {
    display: block;
  }

  /* Article adjustments */
  .article__title {
    font-size: 1.3rem;
    margin-bottom: 1rem;
  }

  .article__subtitle {
    font-size: 1.05rem;
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
  }

  .article__text {
    font-size: 0.9rem;
    margin-bottom: 1rem;
  }
}

/* ---- Controls panel ---- */
.controls {
  position: sticky;
  top: 2rem;
  align-self: start;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  padding: 1.25rem;
}

.controls__title {
  font-size: 0.875rem;
  font-weight: 600;
  color: #a1a1aa;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 1.25rem;
}

.controls__group {
  margin-bottom: 1.25rem;
}

.controls__group:last-child {
  margin-bottom: 0;
}

.controls__label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  color: #e4e4e7;
  cursor: pointer;
  user-select: none;
}

.controls__checkbox {
  display: none;
}

.controls__check-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border: 2px solid rgba(255, 255, 255, 0.2);
  border-radius: 5px;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.controls__checkbox:checked + .controls__check-icon {
  background: #8b5cf6;
  border-color: #8b5cf6;
}

.controls__checkbox:checked + .controls__check-icon::after {
  content: "";
  width: 5px;
  height: 9px;
  border: solid #fff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg) translateY(-1px);
}

.controls__label-text {
  display: block;
  font-size: 0.75rem;
  font-weight: 500;
  color: #71717a;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.5rem;
}

/* Modes */
.controls__modes {
  display: flex;
  gap: 0.375rem;
}

.mode-btn {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  padding: 0.5rem 0.25rem;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  background: transparent;
  color: #71717a;
  font-size: 0.6875rem;
  cursor: pointer;
  transition: all 0.2s ease;
}

.mode-btn:hover {
  background: rgba(255, 255, 255, 0.04);
  color: #a1a1aa;
}

.mode-btn.active {
  background: rgba(139, 92, 246, 0.1);
  border-color: rgba(139, 92, 246, 0.3);
  color: #c4b5fd;
}

/* Slider */
.controls__slider-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.controls__range {
  flex: 1;
  appearance: none;
  height: 4px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
  outline: none;
}

.controls__range::-webkit-slider-thumb {
  appearance: none;
  width: 16px;
  height: 16px;
  background: #8b5cf6;
  border-radius: 50%;
  cursor: pointer;
}

.controls__value {
  font-size: 0.75rem;
  color: #71717a;
  min-width: 36px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

/* Color swatches */
.controls__color-row {
  display: flex;
  gap: 0.5rem;
}

.color-swatch {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid transparent;
  cursor: pointer;
  transition: all 0.2s ease;
}

.color-swatch:hover {
  transform: scale(1.15);
}

.color-swatch.active {
  border-color: #fff;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.2);
}

/* ---- Article ---- */
.article__title {
  font-size: 1.75rem;
  font-weight: 700;
  color: #f4f4f5;
  margin-bottom: 1.5rem;
  letter-spacing: -0.02em;
  line-height: 1.3;
}

.article__subtitle {
  font-size: 1.25rem;
  font-weight: 600;
  color: #e4e4e7;
  margin-top: 2rem;
  margin-bottom: 1rem;
}

.article__text {
  font-size: 1rem;
  color: #a1a1aa;
  margin-bottom: 1.25rem;
  max-width: 65ch;
}

/* ---- Guide overlays ---- */
.guide {
  position: fixed;
  left: 0;
  width: 100%;
  pointer-events: none;
  z-index: 9999;
  opacity: 0;
  transition: opacity 0.2s ease;
}

.guide.visible {
  opacity: 1;
}

.guide--line {
  height: 2px;
  background: var(--guide-color, #8b5cf6);
  box-shadow: 0 0 8px var(--guide-color, #8b5cf6);
}

.guide--band {
  height: var(--guide-height, 40px);
  background: var(--guide-color, #8b5cf6);
  opacity: 0;
  border-radius: 2px;
