(() => {
  const groups = document.querySelectorAll("[data-roving-group]");
  const tabindexDisplay = document.getElementById("tabindexDisplay");
  const colorSelected = document.getElementById("colorSelected");

  /* ── Roving Tabindex Core ───────────────────────── */

  function getItems(group) {
    // For grid, get all gridcells; for toolbar, get buttons; for radiogroup, get radios
    if (group.hasAttribute("data-grid")) {
      return [...group.querySelectorAll('[role="gridcell"]')];
    }
    if (group.getAttribute("role") === "radiogroup") {
      return [...group.querySelectorAll('[role="radio"]')];
    }
    // Toolbar: skip separators
    return [...group.querySelectorAll('button:not([role="separator"])')];
  }

  function setRovingFocus(group, targetItem) {
    const items = getItems(group);
    items.forEach((item) => item.setAttribute("tabindex", "-1"));
    targetItem.setAttribute("tabindex", "0");
    targetItem.focus();
    updateDisplay();
  }

  function getCurrentIndex(group) {
    const items = getItems(group);
    return items.findIndex((item) => item.getAttribute("tabindex") === "0");
  }

  /* ── Toolbar navigation (horizontal) ────────────── */

  function handleLinearNav(group, e) {
    const items = getItems(group);
    const current = getCurrentIndex(group);
    let next;

    switch (e.key) {
      case "ArrowRight":
      case "ArrowDown":
        e.preventDefault();
        next = (current + 1) % items.length;
        setRovingFocus(group, items[next]);
        break;
      case "ArrowLeft":
      case "ArrowUp":
        e.preventDefault();
        next = (current - 1 + items.length) % items.length;
        setRovingFocus(group, items[next]);
        break;
      case "Home":
        e.preventDefault();
        setRovingFocus(group, items[0]);
        break;
      case "End":
        e.preventDefault();
        setRovingFocus(group, items[items.length - 1]);
        break;
    }
  }

  /* ── Grid navigation (2D) ───────────────────────── */

  function handleGridNav(group, e) {
    const items = getItems(group);
    const cols = parseInt(group.dataset.cols) || 5;
    const current = getCurrentIndex(group);
    const row = Math.floor(current / cols);
    const col = current % cols;
    let next;

    switch (e.key) {
      case "ArrowRight":
        e.preventDefault();
        next = col + 1 < cols && current + 1 < items.length ? current + 1 : row * cols;
        setRovingFocus(group, items[next]);
        break;
      case "ArrowLeft":
        e.preventDefault();
        next = col - 1 >= 0 ? current - 1 : Math.min(row * cols + cols - 1, items.length - 1);
        setRovingFocus(group, items[next]);
        break;
      case "ArrowDown": {
        e.preventDefault();
        const nextRow = current + cols;
        next = nextRow < items.length ? nextRow : col;
        setRovingFocus(group, items[next]);
        break;
      }
      case "ArrowUp": {
        e.preventDefault();
        const prevRow = current - cols;
        const totalRows = Math.ceil(items.length / cols);
        next = prevRow >= 0 ? prevRow : Math.min((totalRows - 1) * cols + col, items.length - 1);
        setRovingFocus(group, items[next]);
        break;
      }
      case "Home":
        e.preventDefault();
        setRovingFocus(group, items[0]);
        break;
      case "End":
        e.preventDefault();
        setRovingFocus(group, items[items.length - 1]);
        break;
      case "Enter":
      case " ":
        e.preventDefault();
        selectColor(items[current]);
        break;
    }
  }

  /* ── Radio group selection ──────────────────────── */

  function handleRadioNav(group, e) {
    const items = getItems(group);
    const current = getCurrentIndex(group);
    let next;

    switch (e.key) {
      case "ArrowRight":
      case "ArrowDown":
        e.preventDefault();
        next = (current + 1) % items.length;
        selectRadio(group, items[next]);
        break;
      case "ArrowLeft":
      case "ArrowUp":
        e.preventDefault();
        next = (current - 1 + items.length) % items.length;
        selectRadio(group, items[next]);
        break;
      case "Home":
        e.preventDefault();
        selectRadio(group, items[0]);
        break;
      case "End":
        e.preventDefault();
        selectRadio(group, items[items.length - 1]);
        break;
    }
  }

  function selectRadio(group, item) {
    getItems(group).forEach((el) => el.setAttribute("aria-checked", "false"));
    item.setAttribute("aria-checked", "true");
    setRovingFocus(group, item);
  }

  /* ── Color swatch selection ─────────────────────── */

  function selectColor(swatch) {
    document
      .querySelectorAll(".color-swatch")
      .forEach((s) => s.setAttribute("aria-selected", "false"));
    swatch.setAttribute("aria-selected", "true");
    const color = swatch.dataset.color;
    const name = swatch.getAttribute("aria-label");
    colorSelected.innerHTML = `Selected: <span style="color: ${color}; font-weight: 600;">${name} (${color})</span>`;
  }

  /* ── Toolbar button toggle ──────────────────────── */

  function handleToolbarAction(button) {
    const pressed = button.getAttribute("aria-pressed");
    if (pressed !== null) {
      button.setAttribute("aria-pressed", pressed === "true" ? "false" : "true");
    }
  }

  /* ── Bind events ────────────────────────────────── */

  groups.forEach((group) => {
    const isGrid = group.hasAttribute("data-grid");
    const isRadio = group.getAttribute("role") === "radiogroup";

    group.addEventListener("keydown", (e) => {
      if (isGrid) {
        handleGridNav(group, e);
      } else if (isRadio) {
        handleRadioNav(group, e);
      } else {
        handleLinearNav(group, e);
        // Toggle on Enter/Space for toolbar
        if ((e.key === "Enter" || e.key === " ") && !isGrid && !isRadio) {
          e.preventDefault();
          const items = getItems(group);
          const current = getCurrentIndex(group);
          if (current >= 0) handleToolbarAction(items[current]);
        }
      }
    });

    // Click handlers
    getItems(group).forEach((item) => {
      item.addEventListener("click", () => {
        setRovingFocus(group, item);
        if (isRadio) {
          selectRadio(group, item);
        } else if (isGrid) {
          selectColor(item);
        } else {
          handleToolbarAction(item);
        }
      });
    });

    // Radio items also select on click
    if (isRadio) {
      getItems(group).forEach((item) => {
        item.addEventListener("click", () => selectRadio(group, item));
      });
    }
  });

  /* ── Tabindex Display ───────────────────────────── */

  function updateDisplay() {
    if (!tabindexDisplay) return;

    let html = "";
    const labels = ["Toolbar", "Radio Group", "Color Grid"];

    groups.forEach((group, gi) => {
      const items = getItems(group);
      html += `<span class="group-label">${labels[gi]}:</span> `;
      html += items
        .map((item) => {
          const val = item.getAttribute("tabindex");
          const cls = val === "0" ? "active-tab" : "inactive-tab";
          const label =
            item.getAttribute("aria-label") || item.textContent.trim() || item.dataset.color || "?";
          const short = label.length > 8 ? label.slice(0, 8) : label;
          return `<span class="${cls}">[${val}] ${short}</span>`;
        })
        .join("  ");
      html += "\n";
    });

    tabindexDisplay.innerHTML = html;
  }

  // Update display on any focus change
  document.addEventListener("focusin", () => {
    requestAnimationFrame(updateDisplay);
  });

  // Initial display
  updateDisplay();
})();

snippets.css:
/* ── Reset & Base ── */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg-primary: #0a0a0a;
  --bg-secondary: #111111;
  --bg-tertiary: #1a1a1a;
  --bg-card: #141414;
  --border: #252525;
  --border-light: #333333;
  --text-primary: #f0f0f0;
  --text-secondary: #999999;
  --text-muted: #666666;
  --accent-blue: #3b82f6;
  --accent-green: #22c55e;
  --accent-amber: #f59e0b;
  --accent-red: #ef4444;
  --radius: 10px;
  --sidebar-width: 260px;
  --topbar-height: 60px;
}

html {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
}

body {
  min-height: 100vh;
}

button {
  font: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

a {
  color: inherit;
  text-decoration: none;
}

ul {
  list-style: none;
}

/* ── App shell ── */
.app-shell {
  display: flex;
  min-height: 100vh;
}

/* ── Sidebar ── */
.sidebar {
  position: fixed;
  inset-block-start: 0;
  inset-inline-start: 0;
  inline-size: var(--sidebar-width);
  block-size: 100vh;
  background: var(--bg-secondary);
  border-inline-end: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  z-index: 100;
  transition: transform 0.3s ease;
}

.sidebar.collapsed {
  transform: translateX(-100%);
}

[dir="rtl"] .sidebar.collapsed {
  transform: translateX(100%);
}

.sidebar-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-block: 20px;
  padding-inline: 20px;
  border-block-end: 1px solid var(--border);
}

.sidebar-logo {
  font-size: 1.5rem;
  color: var(--accent-blue);
}

.sidebar-brand {
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.sidebar-nav {
  flex: 1;
  padding-block: 16px;
  padding-inline: 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-block: 10px;
  padding-inline: 14px;
  border-radius: 8px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  transition: all 0.2s;
}

.nav-link:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.nav-link.active {
  background: rgba(59, 130, 246, 0.12);
  color: var(--accent-blue);
}

.nav-icon {
  font-size: 1.1rem;
  inline-size: 24px;
  text-align: center;
}

.sidebar-footer {
  padding-block: 16px;
  padding-inline: 16px;
  border-block-start: 1px solid var(--border);
}

.user-badge {
  display: flex;
  align-items: center;
  gap: 12px;
}

.user-avatar {
  inline-size: 36px;
  block-size: 36px;
  border-radius: 50%;
  background: var(--accent-blue);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 600;
}

.user-info {
  display: flex;
  flex-direction: column;
}

.user-name {
  font-size: 0.85rem;
  font-weight: 500;
}

.user-role {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* ── Main area ── */
.main-area {
  flex: 1;
  margin-inline-start: var(--sidebar-width);
  transition: margin-inline-start 0.3s ease;
}

.main-area.expanded {
  margin-inline-start: 0;
}

/* ── Topbar ── */
.topbar {
  position: sticky;
  inset-block-start: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  block-size: var(--topbar-height);
  padding-inline: 24px;
  background: var(--bg-primary);
  border-block-end: 1px solid var(--border);
  z-index: 50;
}

.topbar-start,
.topbar-end {
  display: flex;
  align-items: center;
  gap: 12px;
}

.sidebar-toggle {
  font-size: 1.2rem;
  padding: 6px;
  border-radius: 6px;
  color: var(--text-secondary);
}

.sidebar-toggle:hover {
  background: var(--bg-tertiary);
}

.page-title {
  font-size: 1.1rem;
  font-weight: 600;
}

.dir-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-block: 6px;
  padding-inline: 14px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--accent-blue);
  transition: background 0.2s;
}

.dir-toggle:hover {
  background: var(--bg-card);
}

.icon-btn {
  padding: 8px;
  border-radius: 8px;
  font-size: 1.1rem;
  color: var(--text-secondary);
}

.icon-btn:hover {
  background: var(--bg-tertiary);
}

/* ── Content ── */
.content {
  padding-block: 24px;
  padding-inline: 24px;
}

/* Stats row */
.stats-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-block-end: 24px;
}

.stat-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding-block: 20px;
  padding-inline: 20px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.stat-icon {
  inline-size: 48px;
  block-size: 48px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  flex-shrink: 0;
}

.stat-icon.blue {
  background: rgba(59, 130, 246, 0.15);
}
.stat-icon.green {
  background: rgba(34, 197, 94, 0.15);
}
.stat-icon.amber {
  background: rgba(245, 158, 11, 0.15);
}
.stat-icon.red {
  background: rgba(239, 68, 68, 0.15);
}

.stat-body {
  display: flex;
  flex-direction: column;
}

.stat-value {
  font-size: 1.4rem;
  font-weight: 700;
}

.stat-label {
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* Card grid */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 16px;
}

.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding-block: 20px;
  padding-inline: 20px;
}

.card-wide {
  grid-column: 1 / -1;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-block-end: 16px;
}

.card-title {
  font-size: 1rem;
  font-weight: 600;
}

.card-action {
  font-size: 0.8rem;
  color: var(--accent-blue);
}

.card-action:hover {
  text-decoration: underline;
}

/* Activity list */
.activity-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.activity-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-block: 10px;
  padding-inline: 12px;
  background: var(--bg-tertiary);
  border-radius: 8px;
}

.activity-dot {
  inline-size: 8px;
  block-size: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.activity-dot.green {
  background: var(--accent-green);
}
.activity-dot.blue {
  background: var(--accent-blue);
}
.activity-dot.amber {
  background: var(--accent-amber);
}
.activity-dot.red {
  background: var(--accent-red);
}

.activity-text {
  flex: 1;
  font-size: 0.85rem;
  color: var(--text-secondary);
}

.activity-time {
  font-size: 0.75rem;
  color: var(--text-muted);
  white-space: nowrap;
}

/* Quick actions */
.quick-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.qa-btn {
  padding-block: 12px;
  padding-inline: 16px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.85rem;
  text-align: start;
  transition: all 0.2s;
}

.qa-btn:hover {
  border-color: var(--accent-blue);
  background: rgba(59, 130, 246, 0.08);
}

/* Team list */
.team-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.team-member {
  display: flex;
  align-items: center;
  gap: 12px;
}

.member-avatar {
  inline-size: 40px;
  block-size: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 600;
  flex-shrink: 0;
}

.member-info {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.member-name {
  font-size: 0.85rem;
  font-weight: 500;
}

.member-role {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.member-status {
  inline-size: 10px;
  block-size: 10px;
  border-radius: 50%;
}

.member-status.online {
  background: var(--accent-green);
}
.member-status.offline {
  background: var(--text-muted);
}

/* ── Sidebar backdrop (mobile) ── */
.sidebar-backdrop {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 99;
}

.sidebar-backdrop.active {
  display: block;
}

/* ── Responsive — tablet ── */
@media (max-width: 768px) {
  .sidebar {
    transform: translateX(-100%);
  }

  [dir="rtl"] .sidebar {
    transform: translateX(100%);
  }

  .sidebar.mobile-open {
    transform: translateX(0);
  }

  .main-area {
    margin-inline-start: 0;
  }

  .content {
    padding-block: 16px;
    padding-inline: 16px;
  }

  .stats-row {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }

  .card-grid {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .topbar {
    padding-inline: 12px;
  }

  .page-title {
    font-size: 1rem;
  }
}

/* ── Responsive — small phone ── */
@media (max-width: 480px) {
  .stats-row {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .stat-card {
    padding-block: 14px;
    padding-inline: 14px;
    gap: 12px;
  }

  .stat-icon {
    inline-size: 40px;
    block-size: 40px;
    border-radius: 10px;
    font-size: 1.2rem;
  }

  .stat-value {
    font-size: 1.15rem;
  }

  .stat-label {
    font-size: 0.75rem;
  }

  .content {
    padding-block: 12px;
    padding-inline: 12px;
  }

  .card {
    padding-block: 16px;
    padding-inline: 16px;
  }

  .quick-actions {
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }

  .qa-btn {
    padding-block: 10px;
    padding-inline: 12px;
    font-size: 0.8rem;
  }

  .topbar {
    padding-inline: 10px;
    gap: 8px;
  }

  .topbar-end {
    gap: 4px;
  }

  .dir-toggle {
    padding-block: 5px;
    padding-inline: 10px;
    font-size: 0.78rem;
  }

  .icon-btn {
    padding: 6px;
    font-size: 1rem;
  }

  .activity-item {
    padding-block: 8px;
    padding-inline: 10px;
  }

  .activity-text {
    font-size: 0.8rem;
  }

  .activity-time {
    font-size: 0.7rem;
  }

  .member-avatar {
    inline-size: 34px;
    block-size: 34px;
    font-size: 0.75rem;
  }

  .member-name {
    font-size: 0.8rem;
  }

  .card-title {
    font-size: 0.9rem;
  }
}

