*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: #0a0a0a;
  color: #e5e5e5;
  min-height: 100vh;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* ── Focus Tracker ────────────────────────────────── */

.focus-tracker {
  position: fixed;
  bottom: 20px;
  right: 20px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: #111;
  border: 1px solid #2a2a2a;
  border-radius: 10px;
  font-size: 0.78rem;
  z-index: 500;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  max-width: 360px;
}

.tracker-label {
  color: #666;
  font-weight: 600;
  flex-shrink: 0;
}

.tracker-element {
  color: #22c55e;
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 0.72rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── SPA Navigation ───────────────────────────────── */

.spa-wrapper {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.spa-nav {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 0 28px;
  height: 56px;
  background: #111;
  border-bottom: 1px solid #1e1e1e;
}

.nav-brand {
  font-size: 0.95rem;
  font-weight: 700;
  color: #f5f5f5;
  flex-shrink: 0;
}

.nav-links {
  display: flex;
  gap: 4px;
  list-style: none;
}

.spa-link {
  padding: 6px 14px;
  border-radius: 7px;
  font-size: 0.82rem;
  font-weight: 500;
  color: #777;
  text-decoration: none;
  transition: background 0.15s, color 0.15s;
  white-space: nowrap;
}

.spa-link:hover {
  background: #1a1a1a;
  color: #ccc;
}

.spa-link.active {
  background: #1e1e2e;
  color: #e5e5e5;
}

.spa-link:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: -2px;
}

/* ── SPA Main ─────────────────────────────────────── */

.spa-main {
  flex: 1;
  padding: 32px 40px;
  max-width: 780px;
  margin: 0 auto;
  width: 100%;
}

.spa-page {
  display: none;
}

.spa-page.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ── Pattern Info ─────────────────────────────────── */

.pattern-info {
  background: #111827;
  border: 1px solid #1e3a5f;
  border-radius: 10px;
  padding: 20px 24px;
  margin-bottom: 24px;
}

.pattern-badge {
  display: inline-block;
  padding: 3px 10px;
  background: #1e1e2e;
  border: 1px solid #3730a3;
  border-radius: 20px;
  font-size: 0.7rem;
  font-weight: 600;
  color: #a5b4fc;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 10px;
}

.pattern-info h2 {
  font-size: 1rem;
  font-weight: 600;
  color: #93c5fd;
  margin-bottom: 6px;
}

.pattern-info p {
  font-size: 0.85rem;
  color: #94a3b8;
  line-height: 1.6;
}

/* ── Page Heading ─────────────────────────────────── */

.page-heading {
  font-size: 1.5rem;
  font-weight: 700;
  color: #f5f5f5;
  margin-bottom: 12px;
}

.page-heading:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 4px;
  border-radius: 4px;
}

.page-content {
  font-size: 0.9rem;
  color: #888;
  line-height: 1.6;
  margin-bottom: 24px;
}

/* ── Content Cards (Route Change) ─────────────────── */

.page-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.content-card {
  background: #111;
  border: 1px solid #222;
  border-radius: 12px;
  padding: 20px;
}

.content-card h3 {
  font-size: 0.95rem;
  font-weight: 600;
  color: #d4d4d4;
  margin-bottom: 6px;
}

.content-card p {
  font-size: 0.82rem;
  color: #777;
  line-height: 1.5;
  margin-bottom: 12px;
}

.card-link {
  font-size: 0.82rem;
  color: #6366f1;
  text-decoration: none;
  font-weight: 500;
}

.card-link:hover {
  text-decoration: underline;
}

/* ── List Items (Dynamic Content) ─────────────────── */

.items-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}

.list-item {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  background: #111;
  border: 1px solid #222;
  border-radius: 8px;
  font-size: 0.85rem;
  color: #ccc;
  transition: border-color 0.15s;
}

.list-item:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: -2px;
}

.list-item.new-item {
  border-color: #22c55e;
  animation: slideIn 0.3s ease;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateY(-8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ── Task Items (Delete Recovery) ─────────────────── */

.task-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 16px;
}

.task-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: #111;
  border: 1px solid #222;
  border-radius: 8px;
  transition: border-color 0.15s, opacity 0.2s;
}

.task-item:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: -2px;
}

.task-text {
  font-size: 0.85rem;
  color: #ccc;
}

.delete-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 6px;
  color: #555;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.delete-btn:hover {
  background: #1e1e1e;
  border-color: #333;
  color: #ef4444;
}

.delete-btn:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: -2px;
}

/* ── Settings Grid (Modal Restore) ────────────────── */

.settings-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}

.setting-card {
  background: #111;
  border: 1px solid #222;
  border-radius: 12px;
  padding: 20px;
}

.setting-card h3 {
  font-size: 0.95rem;
  font-weight: 600;
  color: #d4d4d4;
  margin-bottom: 6px;
}

.setting-card p {
  font-size: 0.82rem;
  color: #777;
  line-height: 1.5;
  margin-bottom: 16px;
}

/* ── Buttons ──────────────────────────────────────── */

.action-btn {
  padding: 10px 20px;
  background: #1e1e2e;
  border: 1px solid #3730a3;
  border-radius: 8px;
  font-size: 0.85rem;
  font-weight: 500;
  color: #a5b4fc;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}

.action-btn:hover {
  background: #2d2d5e;
  border-color: #6366f1;
}

.action-btn:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 2px;
}

.hint-text {
  margin-top: 10px;
  font-size: 0.8rem;
  color: #555;
  font-style: italic;
}

/* ── Modal ────────────────────────────────────────── */

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s, visibility 0.2s;
}

.modal-backdrop.open {
  opacity: 1;
  visibility: visible;
}

.modal {
  width: 90%;
  max-width: 440px;
  background: #141414;
  border: 1px solid #2a2a2a;
  border-radius: 14px;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.6);
  transform: scale(0.96) translateY(8px);
  transition: transform 0.2s;
}

.modal-backdrop.open .modal {
  transform: scale(1) translateY(0);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px 16px;
  border-bottom: 1px solid #222;
}

.modal-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: #f5f5f5;
}

.modal-close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  background: transparent;
  border: none;
  border-radius: 6px;
  color: #666;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}

.modal-close:hover {
  background: #222;
  color: #ccc;
}

.modal-close:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: -2px;
}

.modal-body {
  padding: 20px 24px;
  font-size: 0.88rem;
  color: #aaa;
  line-height: 1.6;
}

.modal-body label {
  display: block;
  font-size: 0.82rem;
  font-weight: 500;
  color: #999;
  margin-bottom: 6px;
  margin-top: 14px;
}

.modal-body label:first-child {
  margin-top: 0;
}

.modal-body input {
  width: 100%;
  padding: 9px 14px;
  background: #0a0a0a;
  border: 1px solid #262626;
  border-radius: 8px;
  font-size: 0.85rem;
  color: #e5e5e5;
}

.modal-body input:focus {
  outline: none;
  border-color: #6366f1;
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 16px 24px 20px;
  border-top: 1px solid #222;
}

.btn-secondary {
  padding: 8px 18px;
  background: #1a1a1a;
  border: 1px solid #333;
  border-radius: 8px;
  font-size: 0.82rem;
  font-weight: 500;
  color: #aaa;
  cursor: pointer;
  transition: background 0.15s;
}

.btn-secondary:hover {
  background: #222;
}

.btn-secondary:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 2px;
}

.btn-primary {
  padding: 8px 18px;
  background: #4f46e5;
  border: none;
  border-radius: 8px;
  font-size: 0.82rem;
  font-weight: 600;
  color: #fff;
  cursor: pointer;
  transition: background 0.15s;
}

.btn-primary:hover {
  background: #6366f1;
}

.btn-primary:focus-visible {
  outline: 2px solid #6366f1;
  outline-offset: 2px;
}

/* ── Responsive ───────────────────────────────────── */

@media (max-width: 640px) {
  .spa-main {
    padding: 24px 20px;
  }

  .page-cards {
    grid-template-columns: 1fr;
  }

  .settings-grid {
    grid-template-columns: 1fr;
  }

  .spa-nav {
    padding: 0 16px;
    gap: 12px;
  }

  .nav-links {
    overflow-x: auto;
  }
}

