*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: #0a0a0a;
  color: #e5e5e5;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  padding: 2rem 1rem;
}

@media (min-width: 480px) {
  body {
    padding: 3rem 1.5rem;
  }
}

.demo-wrapper {
  width: 100%;
  max-width: 720px;
}

.demo-title {
  font-size: clamp(1.25rem, 5vw, 1.75rem);
  font-weight: 700;
  color: #f5f5f5;
  margin-bottom: 0.375rem;
}

.demo-subtitle {
  font-size: 0.9rem;
  color: #888;
  margin-bottom: 2.5rem;
  line-height: 1.5;
}

/* ── Menubar ──────────────────────────────────────── */

.menubar-container {
  position: relative;
  margin-bottom: 2rem;
  overflow-x: auto;
  /* smooth scrolling on iOS */
  -webkit-overflow-scrolling: touch;
  /* hide scrollbar but keep functionality */
  scrollbar-width: none;
}

.menubar-container::-webkit-scrollbar {
  display: none;
}

.menubar {
  display: flex;
  list-style: none;
  background: #161616;
  border: 1px solid #262626;
  border-radius: 10px;
  padding: 4px;
  gap: 2px;
  width: max-content;
  min-width: 100%;
}

.menubar-item {
  position: relative;
}

.menubar-button {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  background: transparent;
  border: none;
  border-radius: 7px;
  color: #b0b0b0;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  white-space: nowrap;
