  outline-offset: -2px;
  background: #1e1e2e;
  color: #f5f5f5;
}

.menubar-button[aria-expanded="true"] {
  background: #1e1e2e;
  color: #f5f5f5;
}

.menubar-button[aria-expanded="true"] .chevron {
  transform: rotate(180deg);
}

.chevron {
  transition: transform 0.2s ease;
  flex-shrink: 0;
}

/* ── Submenu ─────────────────────────────────────── */

.submenu {
