  border: 1px solid #2a2a2a;
  border-radius: 10px;
  padding: 4px;
  min-width: 200px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-4px);
  transition: opacity 0.15s, transform 0.15s, visibility 0.15s;
  z-index: 100;
}

.submenu.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.submenu-item {
  padding: 8px 14px;
  border-radius: 7px;
  font-size: 0.85rem;
  color: #c0c0c0;
  cursor: pointer;
  transition: background 0.12s, color 0.12s;
  white-space: nowrap;
}

.submenu-item:hover {
  background: #222;
  color: #f5f5f5;
}

.submenu-item:focus-visible,
.submenu-item.focused {
  outline: none;
  background: #2d2d5e;
  color: #f5f5f5;
}

.submenu-separator {
  height: 1px;
  background: #262626;
  margin: 4px 8px;
}

/* ── Action Log ──────────────────────────────────── */

.action-log {
  background: #111;
  border: 1px solid #222;
  border-radius: 10px;
  padding: 16px 20px;
  min-height: 60px;
  margin-bottom: 2.5rem;
  font-size: 0.85rem;
  color: #888;
}

.action-log .log-entry {
  color: #a5b4fc;
  padding: 2px 0;
}

.action-log .log-entry::before {
  content: "\25B8  ";
  color: #6366f1;
}

.log-placeholder {
  color: #555;
  font-style: italic;
}

/* ── Keyboard Guide ──────────────────────────────── */

.keyboard-guide {
  background: #111;
  border: 1px solid #222;
  border-radius: 12px;
  padding: 16px;
}

@media (min-width: 480px) {
  .keyboard-guide {
    padding: 24px;
  }
}

.guide-title {
  font-size: 1rem;
  font-weight: 600;
  color: #d4d4d4;
  margin-bottom: 16px;
}

.guide-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 10px;
}

@media (min-width: 500px) {
  .guide-grid {
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 12px;
  }
}

.guide-item {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  font-size: 0.85rem;
  color: #999;
}

.guide-item span {
  flex: 1;
  min-width: 0;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 26px;
  height: 26px;
  padding: 0 7px;
  background: #1a1a1a;
  border: 1px solid #333;
  border-bottom-width: 2px;
  border-radius: 5px;
  font-family: inherit;
  font-size: 0.75rem;
  font-weight: 600;
  color: #ccc;
  line-height: 1;
}

