*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #0a0a0a;
  color: #e4e4e7;
  line-height: 1.5;
  min-height: 100vh;
}

.layout {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 2rem;
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

@media (max-width: 768px) {
  .layout {
    grid-template-columns: 1fr;
  }
}

/* ---- Panel ---- */
.panel {
  position: sticky;
  top: 2rem;
  align-self: start;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  padding: 1.5rem;
}

.panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.5rem;
}

.panel__title {
  font-size: 1rem;
  font-weight: 600;
  color: #f4f4f5;
}

.panel__badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.625rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #8b5cf6;
  background: rgba(139, 92, 246, 0.12);
  padding: 0.25rem 0.5rem;
  border-radius: 6px;
  text-decoration: none;
  transition: background 0.15s, color 0.15s;
}

.panel__badge:hover {
  background: rgba(139, 92, 246, 0.22);
  color: #a78bfa;
}

/* ---- Controls ---- */
.panel__controls {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  margin-bottom: 1.5rem;
}

.control__header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 0.5rem;
}

.control__label {
  font-size: 0.8125rem;
  font-weight: 500;
  color: #a1a1aa;
}

.control__output {
  font-size: 0.8125rem;
  font-weight: 600;
  color: #c4b5fd;
  font-variant-numeric: tabular-nums;
  min-width: 52px;
  text-align: right;
}

.control__range {
  width: 100%;
  appearance: none;
  height: 6px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 3px;
  outline: none;
  cursor: pointer;
}

.control__range::-webkit-slider-thumb {
  appearance: none;
  width: 18px;
  height: 18px;
  background: #8b5cf6;
  border-radius: 50%;
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(139, 92, 246, 0.35);
  transition: transform 0.15s ease;
}

.control__range::-webkit-slider-thumb:hover {
  transform: scale(1.15);
}

.control__range::-moz-range-thumb {
  width: 18px;
  height: 18px;
  background: #8b5cf6;
  border: none;
  border-radius: 50%;
  cursor: pointer;
}

.control__ticks {
  display: flex;
  justify-content: space-between;
  margin-top: 0.25rem;
  font-size: 0.625rem;
  color: #52525b;
}

/* ---- Buttons ---- */
.panel__actions {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.btn {
  flex: 1;
  padding: 0.5rem 0.75rem;
  border: none;
  border-radius: 8px;
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.btn--preset {
  background: rgba(139, 92, 246, 0.15);
  color: #c4b5fd;
  border: 1px solid rgba(139, 92, 246, 0.25);
}

.btn--preset:hover {
  background: rgba(139, 92, 246, 0.25);
}

.btn--reset {
  background: rgba(255, 255, 255, 0.05);
  color: #a1a1aa;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.btn--reset:hover {
  background: rgba(255, 255, 255, 0.1);
}

/* ---- Status ---- */
.panel__info {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 0.75rem;
  background: rgba(255, 255, 255, 0.03);
  border-radius: 8px;
  font-size: 0.75rem;
  color: #71717a;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #52525b;
  flex-shrink: 0;
  transition: background 0.3s ease;
}

.status-dot.passing {
  background: #10b981;
  box-shadow: 0 0 6px rgba(16, 185, 129, 0.5);
}

.status-dot.partial {
  background: #f59e0b;
  box-shadow: 0 0 6px rgba(245, 158, 11, 0.4);
}

/* ---- Article Content ---- */
.content {
  --text-letter-spacing: 0em;
  --text-word-spacing: 0em;
  --text-line-height: 1.5;
  --text-paragraph-spacing: 0em;
}

.article {
  max-width: 680px;
}

.article__title {
  font-size: 1.75rem;
  font-weight: 700;
  color: #f4f4f5;
  margin-bottom: 1.5rem;
  letter-spacing: -0.02em;
  line-height: 1.3;
}

.article h2 {
  font-size: 1.25rem;
  font-weight: 600;
  color: #e4e4e7;
  margin-top: 2rem;
  margin-bottom: 0.75rem;
}

.article p {
  font-size: 1rem;
  color: #a1a1aa;
  margin-bottom: var(--text-paragraph-spacing, 1rem);
  letter-spacing: var(--text-letter-spacing, normal);
  word-spacing: var(--text-word-spacing, normal);
  line-height: var(--text-line-height, 1.5);
}

.article p + p {
  margin-top: 0.25rem;
}

.article__list {
  list-style: none;
  margin: 1rem 0 1.5rem;
  padding: 0;
}

.article__list li {
  position: relative;
  padding-left: 1.5rem;
  margin-bottom: 0.5rem;
  font-size: 0.9375rem;
  color: #a1a1aa;
  letter-spacing: var(--text-letter-spacing, normal);
  word-spacing: var(--text-word-spacing, normal);
  line-height: var(--text-line-height, 1.5);
}

.article__list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #8b5cf6;
}

.article__quote {
  border-left: 3px solid #8b5cf6;
  padding: 1rem 1.25rem;
  margin: 1.5rem 0;
  background: rgba(139, 92, 246, 0.06);
  border-radius: 0 8px 8px 0;
  font-style: italic;
  color: #c4b5fd;
  font-size: 1rem;
  letter-spacing: var(--text-letter-spacing, normal);
  word-spacing: var(--text-word-spacing, normal);
  line-height: var(--text-line-height, 1.5);
}

.article__quote cite {
  display: block;
  margin-top: 0.5rem;
  font-style: normal;
  font-size: 0.8125rem;
  color: #71717a;
}

