*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #0a0a0a;
  color: #e4e4e7;
  line-height: 1.5;
  min-height: 100vh;
}

.shell {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 1rem 2rem;
}

/* ---- Top bar ---- */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  margin-bottom: 0;
}

.topbar__logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: #f4f4f5;
  background: linear-gradient(135deg, #8b5cf6, #6366f1);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.topbar__right {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

/* Simplify button */
.simplify-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
  color: #a1a1aa;
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
}

.simplify-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #e4e4e7;
}

.simplify-btn[aria-pressed="true"] {
  background: rgba(16, 185, 129, 0.12);
  border-color: rgba(16, 185, 129, 0.3);
  color: #6ee7b7;
}

/* Notification bell */
.notification-bell {
  position: relative;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #a1a1aa;
}

.notification-bell__badge {
  position: absolute;
  top: 2px;
  right: 2px;
  width: 16px;
  height: 16px;
  background: #ef4444;
  color: #fff;
  font-size: 0.625rem;
  font-weight: 700;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.notification-bell__badge.pulse {
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.4);
  }
  50% {
    box-shadow: 0 0 0 8px rgba(239, 68, 68, 0);
  }
}

/* ---- Marquee banner ---- */
.marquee-banner {
  overflow: hidden;
  background: linear-gradient(90deg, rgba(139, 92, 246, 0.08), rgba(99, 102, 241, 0.08));
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  padding: 0.5rem 0;
}

.marquee-banner__track {
  display: flex;
  width: max-content;
  animation: marquee 30s linear infinite;
}

.marquee-banner__text {
  font-size: 0.8125rem;
  color: #a1a1aa;
  white-space: nowrap;
  padding-right: 2rem;
}

@keyframes marquee {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-50%);
  }
}

/* ---- Dashboard ---- */
.dashboard {
  padding-top: 1.5rem;
}

.section-title {
  font-size: 1rem;
  font-weight: 600;
  color: #e4e4e7;
  margin-bottom: 1rem;
}

.decorative-title {
  position: relative;
  display: inline-block;
}

.decorative-title::after {
  content: "";
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 2px;
  background: linear-gradient(90deg, #8b5cf6, transparent);
  border-radius: 1px;
}

/* Stat cards */
.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  margin-bottom: 1.5rem;
}

@media (max-width: 768px) {
  .stats {
    grid-template-columns: repeat(2, 1fr);
  }
}

.stat-card {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  padding: 1rem;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 0.75rem;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.stat-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

.stat-card__icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.stat-card__icon--blue {
  background: rgba(59, 130, 246, 0.15);
  color: #60a5fa;
}
.stat-card__icon--green {
  background: rgba(16, 185, 129, 0.15);
  color: #34d399;
}
.stat-card__icon--purple {
  background: rgba(139, 92, 246, 0.15);
  color: #a78bfa;
}
.stat-card__icon--amber {
  background: rgba(245, 158, 11, 0.15);
  color: #fbbf24;
}

.stat-card__body {
  flex: 1;
  min-width: 0;
}

.stat-card__value {
  display: block;
  font-size: 1.25rem;
  font-weight: 700;
  color: #f4f4f5;
  font-variant-numeric: tabular-nums;
}

