  background: rgba(255, 255, 255, 0.2);
  cursor: pointer;
  transition: all 0.3s ease;
}

.carousel__dot.active {
  background: #8b5cf6;
  width: 24px;
  border-radius: 4px;
}

/* Activity feed */
.activity__list {
  list-style: none;
}

.activity__item {
  display: flex;
  gap: 0.75rem;
  padding: 0.75rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.activity__item:last-child {
  border-bottom: none;
}

.activity__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-top: 0.375rem;
  flex-shrink: 0;
}

.activity__dot--blue {
  background: #3b82f6;
}
.activity__dot--green {
  background: #10b981;
}
.activity__dot--amber {
  background: #f59e0b;
}
.activity__dot--purple {
  background: #8b5cf6;
}

.activity__content {
  flex: 1;
}

.activity__text {
  font-size: 0.8125rem;
  color: #a1a1aa;
  line-height: 1.5;
}

.activity__text strong {
  color: #e4e4e7;
  font-weight: 600;
}

.activity__time {
  display: block;
  font-size: 0.6875rem;
  color: #52525b;
  margin-top: 0.125rem;
}

/* ====================================
   SIMPLIFIED MODE
   ==================================== */

body.simplified {
  background: #111111;
}

/* Kill all animations */
.simplified * {
  animation: none !important;
  transition: none !important;
  transform: none !important;
}

.simplified .topbar__logo {
  background: none;
  -webkit-background-clip: initial;
  background-clip: initial;
  -webkit-text-fill-color: #f4f4f5;
}

/* Hide marquee */
.simplified .marquee-banner {
  display: none;
}

/* Hide notification pulse and badge animation */
.simplified .notification-bell__badge {
  box-shadow: none;
}

/* Remove gradients from stat cards */
.simplified .stat-card {
  box-shadow: none;
  border-color: rgba(255, 255, 255, 0.1);
}

.simplified .stat-card__icon--blue,
.simplified .stat-card__icon--green,
.simplified .stat-card__icon--purple,
.simplified .stat-card__icon--amber {
  background: rgba(255, 255, 255, 0.06);
  color: #a1a1aa;
}

.simplified .stat-card__trend {
  background: none;
  color: #71717a;
}

/* Single column layout */
.simplified .stats {
  grid-template-columns: repeat(2, 1fr);
}

.simplified .main-grid {
  grid-template-columns: 1fr;
}

/* Simplify carousel to static card */
.simplified .carousel__slide {
  position: relative;
  opacity: 1;
  background: rgba(255, 255, 255, 0.04) !important;
  border: 1px solid rgba(255, 255, 255, 0.1);
  margin-bottom: 0.75rem;
}

.simplified .carousel__slide h3 {
