  flex-direction: column;
}

.dd-title {
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--text-primary);
}

.dd-desc {
  font-size: 0.76rem;
  color: var(--text-muted);
}

/* Nav actions */
.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-inline-start: auto;
}

.dir-toggle {
  display: flex;
  align-items: center;
  gap: 6px;
  padding-block: 6px;
  padding-inline: 12px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--accent-blue);
  transition: background 0.2s;
}

.dir-toggle:hover {
  background: var(--bg-primary);
}

.nav-cta {
  padding-block: 8px;
  padding-inline: 18px;
  background: var(--accent-blue);
  color: #fff;
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 600;
  transition: background 0.2s;
  white-space: nowrap;
}

.nav-cta:hover {
  background: #2563eb;
}

[dir="rtl"] .nav-cta {
  direction: ltr;
  unicode-bidi: bidi-override;
}

/* Mobile */
.mobile-toggle {
  display: none;
  padding: 8px;
}

.hamburger {
  display: block;
  inline-size: 20px;
  block-size: 2px;
  background: var(--text-primary);
  position: relative;
}

.hamburger::before,
.hamburger::after {
  content: "";
  position: absolute;
  inline-size: 100%;
  block-size: 2px;
  background: var(--text-primary);
  inset-inline-start: 0;
}

.hamburger::before {
  inset-block-start: -6px;
}
.hamburger::after {
  inset-block-start: 6px;
}

/* ── Breadcrumb ── */
.breadcrumb-container {
  border-block-end: 1px solid var(--border);
  background: var(--bg-primary);
}

.breadcrumb {
  max-inline-size: 1200px;
  margin-inline: auto;
  padding-block: 12px;
  padding-inline: 24px;
}

.breadcrumb-list {
  display: flex;
  align-items: center;
  gap: 0;
  flex-wrap: wrap;
}

.breadcrumb-item {
  display: inline-flex;
  align-items: center;
}

.breadcrumb-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  color: var(--text-secondary);
  padding-block: 4px;
  padding-inline: 6px;
  border-radius: 4px;
  transition: color 0.2s, background 0.2s;
}

.breadcrumb-link:hover {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.bc-home {
  font-size: 0.9rem;
}

.breadcrumb-text {
  font-size: 0.82rem;
  color: var(--text-primary);
  font-weight: 500;
  padding-inline: 6px;
}

.breadcrumb-sep {
  display: inline-flex;
  align-items: center;
  padding-inline: 4px;
}

.sep-arrow {
  font-size: 1rem;
  color: var(--text-muted);
  line-height: 1;
  display: inline-block;
  transition: transform 0.2s;
}

/* Flip breadcrumb arrows in RTL */
[dir="rtl"] .sep-arrow {
  transform: scaleX(-1);
}

/* ── Demo content ── */
.demo-content {
  max-inline-size: 1200px;
  margin-inline: auto;
  padding-block: 48px;
  padding-inline: 24px;
}

.demo-title {
  font-size: 2rem;
  font-weight: 700;
  margin-block-end: 16px;
}

.demo-text {
  font-size: 1rem;
  color: var(--text-secondary);
  max-inline-size: 640px;
  margin-block-end: 32px;
  line-height: 1.7;
}

.feature-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.feature {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-block: 12px;
  padding-inline: 16px;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 8px;
  max-inline-size: 480px;
}

.feature-icon {
  inline-size: 28px;
  block-size: 28px;
  border-radius: 50%;
  background: rgba(34, 197, 94, 0.15);
  color: var(--accent-green);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  flex-shrink: 0;
}

.feature-text {
  font-size: 0.9rem;
  color: var(--text-secondary);
}

/* ── Mobile backdrop ── */
.mobile-backdrop {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 90;
}

.mobile-backdrop.active {
  display: block;
}

/* ── Responsive ── */
@media (max-width: 768px) {
  .nav-container {
    padding-inline: 16px;
    position: relative;
  }

  .nav-menu {
    position: fixed;
    inset-block-start: 64px;
    inset-inline-start: 0;
    inset-inline-end: 0;
    inset-block-end: 0;
    background: var(--bg-secondary);
    border-block-start: 1px solid var(--border);
    flex-direction: column;
    align-items: stretch;
    gap: 2px;
    padding-block: 12px;
    padding-inline: 16px;
    overflow-y: auto;
    z-index: 95;
    transform: translateY(-110%);
    opacity: 0;
    transition: transform 0.3s ease, opacity 0.25s ease;
  }

  .nav-menu.open {
    transform: translateY(0);
    opacity: 1;
  }

  .nav-link {
    display: flex;
    width: 100%;
    padding-block: 12px;
    padding-inline: 16px;
    font-size: 0.95rem;
    border-radius: 8px;
  }

  .nav-link:hover,
  .nav-link.active {
    background: var(--bg-tertiary);
  }

  .dropdown-trigger {
    justify-content: space-between;
  }

  /* Dropdown inside mobile menu */
  .nav-menu .dropdown-menu {
    position: static;
    inline-size: 100%;
    box-shadow: none;
    border: none;
    background: transparent;
    padding-block: 4px;
    padding-inline: 0;
    margin-inline-start: 12px;
    opacity: 1;
    visibility: visible;
    transform: none;
    display: none;
    border-inline-start: 2px solid var(--border-light);
  }

  .nav-menu .dropdown-menu.open {
    display: block;
  }

  .nav-menu .dropdown-link {
    padding-block: 10px;
    padding-inline: 14px;
  }

  /* Nav actions in mobile */
  .nav-actions {
    margin-inline-start: auto;
  }

  .nav-cta {
    display: none;
  }

  .mobile-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-inline-start: 8px;
    width: 40px;
    height: 40px;
    border-radius: 8px;
  }

  .mobile-toggle:hover {
    background: var(--bg-tertiary);
  }

  /* Hamburger animation */
  .mobile-toggle.active .hamburger {
    background: transparent;
  }

  .mobile-toggle.active .hamburger::before {
    inset-block-start: 0;
    transform: rotate(45deg);
  }

  .mobile-toggle.active .hamburger::after {
    inset-block-start: 0;
    transform: rotate(-45deg);
  }

  .hamburger,
  .hamburger::before,
  .hamburger::after {
    transition: all 0.25s ease;
  }

  /* Breadcrumb */
  .breadcrumb {
    padding-inline: 16px;
  }

  /* Content */
  .demo-content {
    padding-block: 32px;
    padding-inline: 16px;
  }

  .demo-title {
    font-size: 1.5rem;
  }

  .feature {
    max-inline-size: 100%;
  }
}

