}

/* Toggle Bar */
.toggle-bar {
  margin-top: 1.5rem;
  display: flex;
  justify-content: center;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 1rem;
  font-size: 0.825rem;
  font-weight: 500;
  font-family: inherit;
  border: 1px solid #27272a;
  border-radius: 8px;
