.modal-icon--danger {
  background: rgba(239, 68, 68, 0.12);
  color: #f87171;
}

.modal-icon--info {
  background: rgba(59, 130, 246, 0.12);
  color: #60a5fa;
}

.modal-title {
  font-size: 1.05rem;
  font-weight: 600;
  color: #fafafa;
  flex: 1;
}

.modal-close {
  width: 32px;
  height: 32px;
  display: flex;
