  outline-offset: 2px;
}

.modal-body {
  padding: 1rem 1.25rem;
}

.modal-desc {
  font-size: 0.875rem;
  color: #a1a1aa;
  line-height: 1.6;
}

.modal-desc strong {
  color: #e4e4e7;
}

.changes-list {
  margin-top: 0.75rem;
