  flex-direction: column;
  gap: 0.3rem;
}

.change-item {
  font-size: 0.8rem;
  color: #d4d4d8;
  padding: 0.4rem 0.65rem;
  background: #09090b;
  border: 1px solid #1e1e22;
  border-radius: 6px;
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  padding: 0 1.25rem 1.25rem;
}

/* Form inside modal */
.modal-form {
  margin-top: 0.75rem;
}

.form-group {
  margin-bottom: 1rem;
}

.form-label {
  display: block;
  font-size: 0.8rem;
  font-weight: 500;
  color: #a1a1aa;
  margin-bottom: 0.35rem;
