*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: Inter, system-ui, -apple-system, sans-serif;
  background: #0a0a0a;
  color: #e5e5e5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

.checker {
  width: 100%;
  max-width: 560px;
}

.checker-title {
  font-size: 1.75rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 0.375rem;
}

.checker-sub {
  color: #737373;
  font-size: 0.875rem;
  margin-bottom: 2rem;
  line-height: 1.5;
}

/* ── Color inputs ── */
.color-inputs {
  display: flex;
  align-items: flex-end;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.color-field {
  flex: 1;
}

.color-field label {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #a3a3a3;
  margin-bottom: 0.5rem;
}

.input-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: #171717;
  border: 1px solid #262626;
  border-radius: 0.5rem;
  padding: 0.375rem 0.625rem;
}

.input-row input[type="color"] {
  width: 28px;
  height: 28px;
  border: none;
  border-radius: 0.25rem;
  cursor: pointer;
  padding: 0;
  background: none;
  -webkit-appearance: none;
}

.input-row input[type="color"]::-webkit-color-swatch-wrapper {
  padding: 0;
}
.input-row input[type="color"]::-webkit-color-swatch {
  border: 1px solid #404040;
  border-radius: 0.25rem;
}

.input-row input[type="text"] {
  flex: 1;
  background: none;
  border: none;
  color: #e5e5e5;
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 0.875rem;
  outline: none;
  width: 80px;
}

.swap-btn {
  background: #171717;
  border: 1px solid #262626;
  border-radius: 0.5rem;
  color: #a3a3a3;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  flex-shrink: 0;
}

.swap-btn:hover {
  background: #262626;
  color: #e5e5e5;
}

/* ── Icon buttons (copy/paste) ── */
.icon-btn {
  background: none;
  border: none;
  color: #525252;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  border-radius: 0.25rem;
  transition: color 0.15s, background 0.15s;
  flex-shrink: 0;
  position: relative;
}

.icon-btn:hover {
  color: #e5e5e5;
  background: #262626;
}

.icon-btn.copied {
  color: #22c55e;
}

.icon-btn .tooltip {
  position: absolute;
  bottom: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%);
  background: #262626;
  color: #e5e5e5;
  font-size: 0.6875rem;
  padding: 0.25rem 0.5rem;
  border-radius: 0.25rem;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.15s;
}

.icon-btn .tooltip.show {
  opacity: 1;
}

/* ── Preview ── */
.preview {
  border-radius: 0.75rem;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  border: 1px solid #262626;
  transition: background-color 0.2s, color 0.2s;
}

.preview-normal {
  font-size: 1rem;
  line-height: 1.6;
  margin-bottom: 0.75rem;
}
.preview-large {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}
.preview-link {
  text-decoration: underline;
  font-size: 0.9375rem;
}

/* ── Ratio display ── */
.ratio-display {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #171717;
  border: 1px solid #262626;
  border-radius: 0.75rem;
  padding: 1rem 1.25rem;
  margin-bottom: 1.5rem;
}

.ratio-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: #a3a3a3;
}

.ratio-value {
  font-size: 1.75rem;
  font-weight: 800;
  font-family: "SF Mono", "Fira Code", monospace;
}

/* ── Results grid ── */
.results-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
  margin-bottom: 2rem;
}

.result-card {
  background: #171717;
  border: 1px solid #262626;
  border-radius: 0.75rem;
  padding: 1rem;
  transition: border-color 0.2s;
}

.result-card.pass {
  border-color: #22c55e;
}
.result-card.fail {
  border-color: #ef4444;
}

.result-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.25rem;
}

.result-level {
  font-size: 0.75rem;
  font-weight: 700;
  background: #262626;
  padding: 0.125rem 0.5rem;
  border-radius: 0.25rem;
  letter-spacing: 0.04em;
}

.result-type {
  font-size: 0.8125rem;
  color: #a3a3a3;
}

.result-req {
  font-size: 0.75rem;
  color: #525252;
  margin-bottom: 0.625rem;
}

.result-badge {
  font-size: 0.875rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 0.375rem;
}

.result-badge.pass {
  color: #22c55e;
}
.result-badge.fail {
  color: #ef4444;
}

/* ── Presets ── */
.presets-title {
  font-size: 0.875rem;
  font-weight: 700;
  color: #a3a3a3;
  margin-bottom: 0.75rem;
}

.preset-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 0.5rem;
}

.preset-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: #171717;
  border: 1px solid #262626;
  border-radius: 0.5rem;
  padding: 0.5rem 0.75rem;
  cursor: pointer;
  color: #e5e5e5;
  font-size: 0.75rem;
  font-weight: 500;
  transition: background 0.15s, border-color 0.15s;
}

.preset-btn:hover {
  background: #1f1f1f;
  border-color: #404040;
}

.preset-swatch {
  width: 20px;
  height: 20px;
  border-radius: 0.25rem;
  border: 1px solid #404040;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}

.preset-swatch-inner {
  position: absolute;
  inset: 0;
  display: flex;
}

.preset-swatch-fg,
.preset-swatch-bg {
  flex: 1;
}

@media (max-width: 480px) {
  .color-inputs {
    flex-direction: column;
    align-items: stretch;
  }
  .swap-btn {
    align-self: center;
    transform: rotate(90deg);
  }
  .results-grid {
    grid-template-columns: 1fr;
  }
}

