*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ── Dark theme (default) ── */
:root {
  color-scheme: dark;
  --bg: #0a0a0a;
  --surface: #141414;
  --elevated: #1a1a1a;
  --border: #262626;
  --text: #e5e5e5;
  --text-secondary: #a3a3a3;
  --text-muted: #737373;
  --link: #60a5fa;
  --accent: #3b82f6;
  --accent-text: #ffffff;
  --input-bg: #171717;
  --input-border: #333333;
  --input-text: #e5e5e5;
  --btn-outline-border: #404040;
  --transition-speed: 0.3s;
}

/* ── Light theme ── */
.light {
  color-scheme: light;
  --bg: #ffffff;
  --surface: #f5f5f5;
  --elevated: #fafafa;
  --border: #e5e5e5;
  --text: #111111;
  --text-secondary: #525252;
  --text-muted: #737373;
  --link: #2563eb;
  --accent: #2563eb;
  --accent-text: #ffffff;
  --input-bg: #ffffff;
  --input-border: #d4d4d4;
  --input-text: #111111;
  --btn-outline-border: #d4d4d4;
}

body {
  font-family: Inter, system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  padding: 0;
  transition: background var(--transition-speed), color var(--transition-speed);
}

.page {
  width: 100%;
  max-width: 760px;
  padding: 1.5rem 2rem;
}

/* ── Header ── */
.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--border);
  margin-bottom: 2rem;
  transition: border-color var(--transition-speed);
}

.header-left {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.logo {
  font-size: 1.125rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  white-space: nowrap;
}

.nav {
  display: flex;
  gap: 0.25rem;
}

.nav-link {
  color: var(--text-secondary);
  text-decoration: none;
  padding: 0.375rem 0.75rem;
  border-radius: 0.375rem;
  font-size: 0.8125rem;
  font-weight: 500;
  transition: background 0.15s, color 0.15s;
}

.nav-link:hover {
  background: var(--surface);
  color: var(--text);
}
.nav-link.active {
  color: var(--text);
  font-weight: 600;
}

/* ── Theme toggle button ── */
.theme-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  color: var(--text);
  padding: 0.5rem 0.875rem;
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}

.theme-btn:hover {
  border-color: var(--text-muted);
}

/* Show/hide sun/moon icons */
.icon-sun {
  display: none;
}
.icon-moon {
  display: block;
}
.light .icon-sun {
  display: block;
}
.light .icon-moon {
  display: none;
}

/* ── Hero ── */
.hero {
  margin-bottom: 2rem;
  padding: 2rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  transition: background var(--transition-speed), border-color var(--transition-speed);
}

.hero-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}
.hero-text {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ── Cards ── */
.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin-bottom: 2rem;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  padding: 1.25rem;
  transition: background var(--transition-speed), border-color var(--transition-speed);
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 0.75rem;
}

.card-title {
  font-size: 0.875rem;
  font-weight: 700;
}

.card-body {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.card-body.secondary {
  color: var(--text-secondary);
}

/* ── Ratio badges ── */
.ratio-badge {
  font-size: 0.625rem;
  font-weight: 700;
  font-family: "SF Mono", "Fira Code", monospace;
  padding: 0.125rem 0.375rem;
  border-radius: 0.25rem;
  background: var(--elevated);
  border: 1px solid var(--border);
  white-space: nowrap;
  transition: background var(--transition-speed), border-color var(--transition-speed);
}

.ratio-badge.small {
  font-size: 0.5625rem;
  margin-top: 0.25rem;
  display: inline-block;
}
.ratio-badge.inline {
  vertical-align: baseline;
}

/* ── Form ── */
.form-section {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  padding: 1.5rem;
  margin-bottom: 2rem;
  transition: background var(--transition-speed), border-color var(--transition-speed);
}

.section-title {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 0.375rem;
}

.form-group input {
  width: 100%;
  background: var(--input-bg);
  border: 1px solid var(--input-border);
  border-radius: 0.5rem;
  color: var(--input-text);
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
  outline: none;
  transition: border-color 0.15s, background var(--transition-speed);
}

.form-group input:focus {
  border-color: var(--accent);
}

.form-actions {
  display: flex;
  gap: 0.5rem;
}

.btn {
  padding: 0.5rem 1rem;
  border-radius: 0.5rem;
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background 0.15s, border-color 0.15s;
}

.btn-primary {
  background: var(--accent);
  color: var(--accent-text);
}
.btn-primary:hover {
  opacity: 0.9;
}
.btn-outline {
  background: transparent;
  color: var(--text);
  border-color: var(--btn-outline-border);
}
.btn-outline:hover {
  background: var(--surface);
}

/* ── Text section ── */
.text-section {
  margin-bottom: 2rem;
}

.body-text {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

.body-text a {
  color: var(--link);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.body-text a:hover {
  opacity: 0.8;
}

/* ── Contrast table ── */
.contrast-table-section {
  margin-bottom: 2rem;
}

.contrast-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8125rem;
}

.contrast-table th {
  text-align: left;
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  padding: 0.625rem 0.75rem;
  border-bottom: 1px solid var(--border);
}

.contrast-table td {
  padding: 0.625rem 0.75rem;
  border-bottom: 1px solid var(--border);
  transition: border-color var(--transition-speed);
}

.contrast-table .swatch-cell {
  width: 24px;
  height: 24px;
  border-radius: 0.25rem;
  border: 1px solid var(--border);
  display: inline-block;
  vertical-align: middle;
}

.pass-cell {
  color: #22c55e;
  font-weight: 700;
}
.fail-cell {
  color: #ef4444;
  font-weight: 700;
}

@media (max-width: 640px) {
  .header {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.75rem;
  }
  .header-left {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;
  }
  .cards {
    grid-template-columns: 1fr;
  }
  .form-grid {
    grid-template-columns: 1fr;
  }
}

