(() => {
  const backdrop = document.getElementById("overlayBackdrop");
  const overlay = document.getElementById("overlay");
  const overlayBody = document.getElementById("overlayBody");
  const overlayClose = document.getElementById("overlayClose");
  const hintBadge = document.getElementById("hintBadge");

  /* ── Shortcuts Data ─────────────────────────────── */

  const shortcuts = [
    {
      category: "Navigation",
      items: [
        { keys: ["g", "h"], desc: "Go to Home" },
        { keys: ["g", "p"], desc: "Go to Projects" },
        { keys: ["g", "s"], desc: "Go to Settings" },
        { keys: ["g", "n"], desc: "Go to Notifications" },
      ],
    },
    {
      category: "Actions",
      items: [
        { keys: ["c"], desc: "Create new item" },
        { keys: ["e"], desc: "Edit selected" },
        { keys: ["Ctrl", "Enter"], desc: "Submit form" },
        { keys: ["Ctrl", "s"], desc: "Save changes" },
        { keys: ["d"], desc: "Delete selected" },
      ],
    },
    {
      category: "Search",
      items: [
        { keys: ["/"], desc: "Focus search bar" },
        { keys: ["Ctrl", "k"], desc: "Command palette" },
        { keys: ["Esc"], desc: "Clear search / Close" },
      ],
    },
    {
      category: "Help",
      items: [
        { keys: ["?"], desc: "Show this overlay" },
        { keys: ["Ctrl", "/"], desc: "Toggle sidebar" },
        { keys: ["Ctrl", "."], desc: "Toggle dark mode" },
      ],
    },
  ];

  /* ── Render Shortcuts ───────────────────────────── */

  function renderShortcuts() {
    overlayBody.innerHTML = "";

    shortcuts.forEach((cat) => {
      const section = document.createElement("div");
      section.className = "shortcut-category";

      const title = document.createElement("h3");
      title.className = "category-title";
      title.textContent = cat.category;
      section.appendChild(title);

      cat.items.forEach((item) => {
        const row = document.createElement("div");
        row.className = "shortcut-row";

        const keysDiv = document.createElement("div");
        keysDiv.className = "shortcut-keys";

        item.keys.forEach((key, i) => {
          const kbd = document.createElement("kbd");
          kbd.textContent = key;
          keysDiv.appendChild(kbd);

          if (i < item.keys.length - 1) {
            const plus = document.createElement("span");
            plus.className = "key-plus";
            plus.textContent = "+";
            keysDiv.appendChild(plus);
          }
        });

        const desc = document.createElement("span");
        desc.className = "shortcut-desc";
        desc.textContent = item.desc;

        row.appendChild(keysDiv);
        row.appendChild(desc);
        section.appendChild(row);
      });

      overlayBody.appendChild(section);
    });
  }

  renderShortcuts();

  /* ── Open / Close ───────────────────────────────── */

  let triggerElement = null;

  function openOverlay() {
    triggerElement = document.activeElement;
    backdrop.classList.add("open");
    backdrop.setAttribute("aria-hidden", "false");
    // Focus the close button
    requestAnimationFrame(() => overlayClose.focus());
  }

  function closeOverlay() {
    backdrop.classList.remove("open");
    backdrop.setAttribute("aria-hidden", "true");
    // Restore focus
    if (triggerElement && triggerElement.focus) {
      triggerElement.focus();
    }
  }

  function isOverlayOpen() {
    return backdrop.classList.contains("open");
  }

  /* ── Event Listeners ────────────────────────────── */

  // Global "?" key listener
  document.addEventListener("keydown", (e) => {
    // Ignore if inside input/textarea/contenteditable
    const tag = e.target.tagName.toLowerCase();
    const isEditable = tag === "input" || tag === "textarea" || e.target.isContentEditable;

    if (e.key === "?" && !isEditable) {
      e.preventDefault();
      if (isOverlayOpen()) {
        closeOverlay();
      } else {
        openOverlay();
      }
      return;
    }

    if (e.key === "Escape" && isOverlayOpen()) {
      e.preventDefault();
      closeOverlay();
    }
  });

  // Close button
  overlayClose.addEventListener("click", closeOverlay);

  // Hint badge
  hintBadge.addEventListener("click", () => {
    if (isOverlayOpen()) {
      closeOverlay();
    } else {
      openOverlay();
    }
  });

  // Click backdrop to close
  backdrop.addEventListener("click", (e) => {
    if (e.target === backdrop) {
      closeOverlay();
    }
  });

  // Trap focus inside overlay when open
  overlay.addEventListener("keydown", (e) => {
    if (e.key !== "Tab") return;

    const focusable = overlay.querySelectorAll(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );
    const first = focusable[0];
    const last = focusable[focusable.length - 1];

    if (e.shiftKey) {
      if (document.activeElement === first) {
        e.preventDefault();
        last.focus();
      }
    } else {
      if (document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  });
})();

snippets.css:
/* ── Reset & Base ── */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg-primary: #0a0a0a;
  --bg-card: #111111;
  --bg-input: #181818;
  --border: #252525;
  --border-focus: #3b82f6;
  --border-error: #ef4444;
  --border-success: #22c55e;
  --text-primary: #f0f0f0;
  --text-secondary: #999999;
  --text-muted: #666666;
  --accent-blue: #3b82f6;
  --accent-green: #22c55e;
  --accent-amber: #f59e0b;
  --accent-red: #ef4444;
  --radius: 10px;
}

html {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-block: 40px;
  padding-inline: 20px;
}

button {
  font: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
}

a {
  color: var(--accent-blue);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* ── Page ── */
.page {
  inline-size: 100%;
  max-inline-size: 560px;
}

/* ── Toolbar ── */
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-block-end: 32px;
}

.toolbar-title {
  font-size: 1.5rem;
  font-weight: 700;
}

.dir-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-block: 6px;
  padding-inline: 14px;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--accent-blue);
  transition: background 0.2s;
}

.dir-toggle:hover {
  background: var(--bg-card);
}

/* ── Form ── */
.form {
  display: flex;
  flex-direction: column;
  gap: 20px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding-block: 32px;
  padding-inline: 32px;
}

.form-row {
  display: flex;
  gap: 16px;
}

.form-row.two-col > .field {
  flex: 1;
}

/* ── Field ── */
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.label {
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.input-icon {
  position: absolute;
  inset-inline-start: 12px;
  font-size: 1rem;
  color: var(--text-muted);
  pointer-events: none;
  z-index: 1;
}

.input {
  inline-size: 100%;
  padding-block: 10px;
  padding-inline-start: 40px;
  padding-inline-end: 14px;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text-primary);
  font: inherit;
  font-size: 0.9rem;
  transition: border-color 0.2s;
  outline: none;
}

.input:focus {
  border-color: var(--border-focus);
}

.input.error {
  border-color: var(--border-error);
}

.input.valid {
  border-color: var(--border-success);
}

.input::placeholder {
  color: var(--text-muted);
}

/* Select */
.select-wrap {
  position: relative;
}

.select {
  appearance: none;
  cursor: pointer;
}

.select-arrow {
  position: absolute;
  inset-inline-end: 14px;
  font-size: 0.8rem;
  color: var(--text-muted);
  pointer-events: none;
}

/* Textarea */
.textarea {
  padding-inline-start: 14px;
  resize: vertical;
  min-block-size: 80px;
}

.char-count {
  font-size: 0.75rem;
  color: var(--text-muted);
  text-align: end;
}

/* Password toggle */
.toggle-pass {
  position: absolute;
  inset-inline-end: 10px;
  font-size: 1rem;
  padding: 4px;
  color: var(--text-muted);
}

.toggle-pass:hover {
  color: var(--text-secondary);
}

/* Password strength */
.password-strength {
  block-size: 4px;
  background: var(--border);
  border-radius: 2px;
  overflow: hidden;
}

.strength-bar {
  block-size: 100%;
  inline-size: 0;
  border-radius: 2px;
  transition: inline-size 0.3s, background 0.3s;
}

/* Error message */
.error-msg {
  font-size: 0.78rem;
  color: var(--accent-red);
  min-block-size: 1.2em;
}

/* Checkbox */
.checkbox-field {
  margin-block-start: 4px;
}

.checkbox-label {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
  font-size: 0.85rem;
  color: var(--text-secondary);
}

.checkbox {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.checkmark {
  flex-shrink: 0;
  inline-size: 20px;
  block-size: 20px;
  border: 2px solid var(--border);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
  margin-block-start: 1px;
}

.checkbox:checked + .checkmark {
  background: var(--accent-blue);
  border-color: var(--accent-blue);
}

.checkbox:checked + .checkmark::after {
  content: "\2713";
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
}

.checkbox:focus-visible + .checkmark {
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.4);
}

.link {
  color: var(--accent-blue);
}

/* Submit */
.submit-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding-block: 12px;
  padding-inline: 24px;
  background: var(--accent-blue);
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  transition: background 0.2s;
  margin-block-start: 8px;
}

.submit-btn:hover {
  background: #2563eb;
}

.submit-btn:active {
  transform: scale(0.98);
}

[dir="rtl"] .btn-arrow {
  transform: scaleX(-1);
}

/* Success */
.success-msg {
  text-align: center;
  padding-block: 48px;
  padding-inline: 32px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-block-start: 24px;
}

.success-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: 56px;
  block-size: 56px;
  border-radius: 50%;
  background: rgba(34, 197, 94, 0.15);
  color: var(--accent-green);
  font-size: 1.6rem;
  margin-block-end: 16px;
}

.success-title {
  font-size: 1.2rem;
  font-weight: 600;
  margin-block-end: 8px;
}

.success-text {
  font-size: 0.9rem;
  color: var(--text-secondary);
}

/* ── Responsive ── */
@media (max-width: 600px) {
  .form-row.two-col {
    flex-direction: column;
  }

  .form {
    padding-block: 24px;
    padding-inline: 20px;
  }
}

