  border-radius: 1rem;
  position: relative;
  overflow: hidden;
  cursor: default;
}

.spring-origin {
  position: absolute;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: rgba(109, 40, 217, 0.3);
  border: 2px solid rgba(109, 40, 217, 0.5);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

.spring-line {
  position: absolute;
  top: 50%;
  left: 50%;
  transform-origin: 0 0;
  height: 2px;
  background: linear-gradient(90deg, rgba(109, 40, 217, 0.4), rgba(109, 40, 217, 0.1));
  pointer-events: none;
  border-radius: 1px;
}

.spring-ball {
  position: absolute;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #a78bfa, #6d28d9);
  box-shadow: 0 0 30px rgba(109, 40, 217, 0.4), 0 0 60px rgba(109, 40, 217, 0.15);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  cursor: grab;
  user-select: none;
  touch-action: none;
  display: grid;
  place-items: center;
  font-size: 0.65rem;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.7);
  letter-spacing: 0.05em;
}

.spring-ball.dragging {
  cursor: grabbing;
  box-shadow: 0 0 40px rgba(109, 40, 217, 0.6), 0 0 80px rgba(109, 40, 217, 0.25);
}

/* ── Controls ── */
.controls {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.control-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.control-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: #71717a;
  min-width: 80px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.control-slider {
  flex: 1;
  -webkit-appearance: none;
  appearance: none;
  height: 4px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 2px;
  outline: none;
}

.control-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #6d28d9;
  border: 2px solid #a78bfa;
  cursor: pointer;
}

.control-slider::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #6d28d9;
  border: 2px solid #a78bfa;
  cursor: pointer;
}

.control-value {
  font-size: 0.75rem;
  font-weight: 600;
  color: #a78bfa;
  min-width: 40px;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

/* ── Velocity indicator ── */
.velocity-bar {
  width: 100%;
  height: 4px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 2px;
  overflow: hidden;
}

.velocity-fill {
  height: 100%;
  background: linear-gradient(90deg, #6d28d9, #a78bfa);
  border-radius: 2px;
  width: 0%;
  transition: width 0.05s;
}

