import { type CSSProperties, type ReactNode } from "react";

interface GridPatternProps {
  /** Grid cell size in pixels */
  size?: number;
  /** SVG stroke color */
  color?: string;
  /** SVG stroke width */
  strokeWidth?: number;
  /** Extra CSS class names */
  className?: string;
  /** Overlay children on top of the grid */
  children?: ReactNode;
}

export function GridPattern({
  size = 40,
  color = "rgba(255,255,255,0.08)",
  strokeWidth = 1,
  className = "",
  children,
}: GridPatternProps) {
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='${size}' height='${size}'><path d='M ${size} 0 L 0 0 0 ${size}' fill='none' stroke='${color}' stroke-width='${strokeWidth}'/></svg>`;
  const encoded = encodeURIComponent(svg).replace(/'/g, "%27");

  const containerStyle: CSSProperties = {
    position: "relative",
    width: "100%",
    minHeight: "100vh",
    display: "grid",
    placeItems: "center",
    backgroundColor: "#0a0a0a",
    backgroundImage: `url("data:image/svg+xml,${encoded}")`,
    backgroundSize: `${size}px ${size}px`,
    overflow: "hidden",
  };

  const fadeStyle: CSSProperties = {
    position: "absolute",
    inset: 0,
    background: "radial-gradient(ellipse 80% 60% at 50% 50%, transparent 30%, #0a0a0a 100%)",
    pointerEvents: "none",
  };

  const contentStyle: CSSProperties = {
    position: "relative",
    zIndex: 1,
  };

  return (
    <div className={className} style={containerStyle}>
      <div style={fadeStyle} />
      <div style={contentStyle}>{children}</div>
    </div>
  );
}

