*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  min-height: 100vh;
  background: #0a0a0a;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  color: #f1f5f9;
}

.orbit-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}

.orbit-container {
  position: relative;
  width: 420px;
  height: 420px;
}

/* Central element */
.orbit-center {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%);
  display: grid;
  place-items: center;
  color: white;
  box-shadow: 0 0 30px rgba(99, 102, 241, 0.4), 0 0 60px rgba(99, 102, 241, 0.2);
  z-index: 10;
}

/* Orbit ring guides */
.orbit-ring {
  position: absolute;
  top: 50%;
  left: 50%;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.06);
  pointer-events: none;
}

.orbit-ring--1 {
  width: 160px;
  height: 160px;
  transform: translate(-50%, -50%);
}

.orbit-ring--2 {
  width: 260px;
  height: 260px;
  transform: translate(-50%, -50%);
}

.orbit-ring--3 {
  width: 380px;
  height: 380px;
  transform: translate(-50%, -50%);
}

/* Orbiting circles base */
.orbiting-circle {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 36px;
  height: 36px;
  margin-left: -18px;
  margin-top: -18px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(8px);
}

.circle-icon {
  font-size: 14px;
  color: rgba(199, 210, 254, 0.9);
  line-height: 1;
}

.circle-icon--lg {
  font-size: 16px;
}

/* Orbit 1 — Inner, fast, clockwise */
.orbit--1 {
  animation: orbit-spin 8s linear infinite;
}
.orbit--1 .circle-icon {
  animation: counter-spin 8s linear infinite;
}
.orbit--1.orbit--delay-0 {
  --orbit-radius: 80px;
  --start-angle: 0deg;
}
.orbit--1.orbit--delay-1 {
  --orbit-radius: 80px;
  --start-angle: 180deg;
}

/* Orbit 2 — Middle, medium, counter-clockwise */
.orbit--2 {
  animation: orbit-spin 15s linear infinite reverse;
}
.orbit--2 .circle-icon {
  animation: counter-spin 15s linear infinite reverse;
}
.orbit--2.orbit--delay-0 {
  --orbit-radius: 130px;
  --start-angle: 0deg;
}
.orbit--2.orbit--delay-1 {
  --orbit-radius: 130px;
  --start-angle: 120deg;
}
.orbit--2.orbit--delay-2 {
  --orbit-radius: 130px;
  --start-angle: 240deg;
}

/* Orbit 3 — Outer, slow, clockwise */
.orbit--3 {
  width: 42px;
  height: 42px;
  margin-left: -21px;
  margin-top: -21px;
  animation: orbit-spin 22s linear infinite;
}
.orbit--3 .circle-icon {
  animation: counter-spin 22s linear infinite;
}
.orbit--3.orbit--delay-0 {
  --orbit-radius: 190px;
  --start-angle: 0deg;
}
.orbit--3.orbit--delay-1 {
  --orbit-radius: 190px;
  --start-angle: 90deg;
}
.orbit--3.orbit--delay-2 {
  --orbit-radius: 190px;
  --start-angle: 180deg;
}
.orbit--3.orbit--delay-3 {
  --orbit-radius: 190px;
  --start-angle: 270deg;
}

/* Apply radius and starting angle via custom properties */
.orbiting-circle {
  transform: rotate(var(--start-angle, 0deg)) translateX(var(--orbit-radius, 100px));
}

@keyframes orbit-spin {
  from {
    transform: rotate(var(--start-angle, 0deg)) translateX(var(--orbit-radius, 100px));
  }
  to {
    transform: rotate(calc(var(--start-angle, 0deg) + 360deg))
      translateX(var(--orbit-radius, 100px));
  }
}

@keyframes counter-spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(-360deg);
  }
}

/* Title */
.orbit-title {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  background: linear-gradient(135deg, #e0e7ff 0%, #a78bfa 50%, #8b5cf6 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  text-align: center;
}

.orbit-subtitle {
  font-size: clamp(0.8rem, 1.8vw, 1rem);
  color: rgba(148, 163, 184, 0.7);
  text-align: center;
}

