        />

        <BeamNode>
          <div ref={fromRef} style={iconBoxStyle("#22d3ee")}>
            &#9670;
          </div>
          <span style={{ fontSize: "0.8125rem", fontWeight: 500, color: "#94a3b8" }}>Source</span>
        </BeamNode>

        <BeamNode>
          <div ref={midRef} style={iconBoxStyle("#a855f7")}>
            &#9733;
          </div>
          <span style={{ fontSize: "0.8125rem", fontWeight: 500, color: "#94a3b8" }}>Process</span>
        </BeamNode>

        <BeamNode>
          <div ref={toRef} style={iconBoxStyle("#34d399")}>
            &#9679;
          </div>
          <span style={{ fontSize: "0.8125rem", fontWeight: 500, color: "#94a3b8" }}>Output</span>
        </BeamNode>
      </div>
    </div>
  );
}

snippets.css:
/* ═══════════════════════════════════════════════════════════════════════
   Tesla UHD Electric Vehicle Landing Page — Styles
   ═══════════════════════════════════════════════════════════════════════ */

:root {
  --ts-black: #000000;
  --ts-dark: #0a0a0a;
  --ts-surface: #1a1a1a;
  --ts-border: rgba(255, 255, 255, 0.08);
  --ts-red: #e82127;
  --ts-red-glow: rgba(232, 33, 39, 0.25);
  --ts-red-subtle: rgba(232, 33, 39, 0.08);
  --ts-blue: #3e68ff;
  --ts-blue-glow: rgba(62, 104, 255, 0.25);
  --ts-text: #ffffff;
  --ts-muted: #999999;
  --ts-dim: #555555;
  --glass-bg: rgba(255, 255, 255, 0.04);
  --glass-border: rgba(255, 255, 255, 0.08);
  --glass-hover: rgba(255, 255, 255, 0.07);
  --radius: 16px;
  --radius-lg: 24px;
  --font: "SF Pro Display", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--ts-black);
  color: var(--ts-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

/* ── Canvas background ── */
#mesh-bg {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}

main {
  position: relative;
  z-index: 1;
}

/* ── Shared ── */
section {
  position: relative;
  padding: 120px 1.5rem;
}

.section-container {
  max-width: 1100px;
  margin: 0 auto;
}

.section-header {
  margin-bottom: 3.5rem;
}

.section-title {
  font-size: clamp(2.5rem, 7vw, 4.5rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.04em;
  margin-bottom: 1rem;
}

.text-muted {
  color: var(--ts-muted);
  font-size: 1.05rem;
  line-height: 1.6;
}

.text-sm {
  font-size: 0.875rem;
}

.tag {
  display: inline-block;
  padding: 6px 16px;
  background: var(--ts-red);
  color: #fff;
  border-radius: 100px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 1.25rem;
}

.reveal {
  opacity: 0;
  transform: translateY(30px);
}

/* ── Buttons ── */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 16px 40px;
  background: var(--ts-red);
  color: #fff;
  border: none;
  border-radius: 100px;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.btn-primary:hover {
  transform: scale(1.04);
  box-shadow: 0 0 40px var(--ts-red-glow);
}

.btn-glow {
  box-shadow: 0 0 30px var(--ts-red-glow), 0 0 60px rgba(232, 33, 39, 0.1);
}

.btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 16px 40px;
  background: transparent;
  color: var(--ts-text);
  border: 1px solid var(--glass-border);
  border-radius: 100px;
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  transition: border-color 0.3s ease, background 0.3s ease;
}

.btn-outline:hover {
  border-color: rgba(255, 255, 255, 0.2);
  background: var(--glass-bg);
}

/* ── Glass card ── */
.glass-card {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

/* ═══════════════════════════════════════════════════════════════════════
   HERO
   ═══════════════════════════════════════════════════════════════════════ */

.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 80px 1.5rem 60px;
  gap: 2rem;
}

.hero-content {
  position: relative;
  z-index: 2;
}

.hero-eyebrow {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.35em;
  color: var(--ts-red);
  margin-bottom: 1.5rem;
  opacity: 0;
}

.hero-title {
  font-size: clamp(4rem, 14vw, 10rem);
  font-weight: 300;
  letter-spacing: -0.05em;
  line-height: 0.9;
  background: linear-gradient(180deg, #fff 30%, #555 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  opacity: 0;
}

.hero-subtitle {
  font-size: clamp(1rem, 2.5vw, 1.3rem);
  color: var(--ts-muted);
  font-weight: 400;
  margin-top: 1.5rem;
  letter-spacing: 0.01em;
  opacity: 0;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 2.5rem;
  opacity: 0;
}

/* ── Scroll indicator ── */
.scroll-indicator {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  opacity: 0;
  position: absolute;
  bottom: 40px;
  left: 50%;
  transform: translateX(-50%);
}

.scroll-indicator span {
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--ts-dim);
  font-weight: 500;
}

.scroll-line {
  width: 1px;
  height: 40px;
  background: linear-gradient(180deg, var(--ts-red), transparent);
  animation: scrollPulse 2s ease-in-out infinite;
}

@keyframes scrollPulse {
  0%,
  100% {
    opacity: 0.3;
    transform: scaleY(0.6);
  }
  50% {
    opacity: 1;
    transform: scaleY(1);
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   MODEL LINEUP
   ═══════════════════════════════════════════════════════════════════════ */

.models-section {
  padding: 140px 1.5rem;
}

.models-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
}

.model-card {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius);
  padding: 2rem 1.5rem 1.5rem;
  text-align: center;
  position: relative;
  transition: transform 0.4s ease, border-color 0.4s ease, box-shadow 0.4s ease;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  opacity: 0;
  transform: translateY(30px) scale(0.96);
}

.model-card:hover {
  transform: translateY(-4px) scale(1.02);
  border-color: rgba(232, 33, 39, 0.2);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4), 0 0 40px var(--ts-red-subtle);
}

.model-card-featured {
  border-color: rgba(232, 33, 39, 0.15);
  background: linear-gradient(135deg, rgba(232, 33, 39, 0.06), var(--glass-bg));
}

.model-silhouette {
  height: 80px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--ts-text);
}

.model-silhouette svg {
  width: 100%;
  max-width: 180px;
  height: auto;
  opacity: 0.7;
  transition: opacity 0.3s ease;
}

.model-card:hover .model-silhouette svg {
  opacity: 1;
}

.model-name {
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin-bottom: 0.25rem;
}

.model-spec {
  font-size: 0.8rem;
  color: var(--ts-muted);
  margin-bottom: 1rem;
}

.model-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 0.75rem;
  border-top: 1px solid var(--glass-border);
}

.model-stat {
  font-size: 0.7rem;
  color: var(--ts-red);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.model-price {
  font-size: 0.75rem;
  color: var(--ts-dim);
  font-weight: 500;
}

.new-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  padding: 3px 10px;
  background: var(--ts-red);
  color: #fff;
  border-radius: 100px;
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

/* ═══════════════════════════════════════════════════════════════════════
   TECHNOLOGY (pinned scroll)
   ═══════════════════════════════════════════════════════════════════════ */

.how-track {
  height: 300vh;
  padding: 0;
}

.how-sticky {
  position: sticky;
  top: 0;
  height: 100vh;
  display: flex;
  align-items: center;
  padding: 0 1.5rem;
  max-width: 1100px;
  margin: 0 auto;
  gap: 4rem;
}

.how-content {
  flex: 1;
  position: relative;
  padding-left: 3rem;
}

.step-dots {
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.step-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ts-dim);
  transition: background 0.4s ease, box-shadow 0.4s ease, transform 0.4s ease;
  cursor: pointer;
}

.step-dot.active {
  background: var(--ts-red);
  box-shadow: 0 0 12px var(--ts-red-glow);
  transform: scale(1.3);
}

.step-card {
  display: none;
}

.step-card.active {
  display: block;
  animation: fadeUp 0.5s ease forwards;
}

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.step-heading {
  font-size: clamp(2rem, 5vw, 3.2rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.1;
  margin-bottom: 1rem;
}

.step-desc {
  color: var(--ts-muted);
  font-size: 1rem;
  line-height: 1.7;
  max-width: 420px;
}

.how-visuals {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.how-visual {
  display: none;
  width: 100%;
  justify-content: center;
}

.how-visual.active {
  display: flex;
  animation: fadeUp 0.5s ease forwards;
}

.tech-visual-card {
  width: 240px;
  height: 280px;
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem;
  gap: 1.5rem;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.tech-icon-svg {
  width: 140px;
  height: 140px;
  color: var(--ts-text);
}

.tech-visual-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--ts-dim);
  font-weight: 500;
  text-align: center;
}

/* Pulse ring animation */
.pulse-ring {
  animation: pulseRing 3s ease-in-out infinite;
}

@keyframes pulseRing {
  0%,
  100% {
    opacity: 0.1;
  }
  50% {
    opacity: 0.3;
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   STATS
   ═══════════════════════════════════════════════════════════════════════ */

.stats-section {
  padding: 140px 1.5rem;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-item {
  padding: 2.5rem 1.5rem;
}

.stat-number {
  font-size: clamp(3rem, 8vw, 5rem);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1;
  background: linear-gradient(135deg, #fff 40%, var(--ts-red) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--ts-text);
  margin-bottom: 0.5rem;
}

.stat-desc {
  font-size: 0.85rem;
  color: var(--ts-dim);
  line-height: 1.5;
}

/* ═══════════════════════════════════════════════════════════════════════
   SAFETY
   ═══════════════════════════════════════════════════════════════════════ */

.safety-section {
  padding: 100px 1.5rem;
}

.safety-card {
  padding: 3.5rem;
}

.safety-header {
  text-align: center;
  margin-bottom: 2.5rem;
}

.safety-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 1.5rem;
  color: var(--ts-text);
}

.safety-icon svg {
  width: 100%;
  height: 100%;
}

.safety-stars {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-bottom: 3rem;
}

.safety-features {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.safety-feature {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.25rem;
  border-radius: var(--radius);
  border: 1px solid transparent;
  transition: background 0.3s ease, border-color 0.3s ease;
}

.safety-feature:hover {
  background: var(--glass-bg);
  border-color: var(--glass-border);
}

.sf-icon {
  width: 40px;
  height: 40px;
  min-width: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: var(--ts-red-subtle);
  color: var(--ts-red);
}

.sf-title {
  font-size: 0.95rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

/* ═══════════════════════════════════════════════════════════════════════
   DASHBOARD SHOWCASE
   ═══════════════════════════════════════════════════════════════════════ */

.dashboard-section {
  padding: 140px 1.5rem;
}

.dash-grid {
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  align-items: center;
  gap: 4rem;
}

.dash-device {
  position: relative;
  perspective: 800px;
}

.dashboard-screen {
  width: 100%;
  max-width: 480px;
  aspect-ratio: 16 / 10;
  background: linear-gradient(145deg, rgba(20, 20, 20, 0.95), rgba(10, 10, 10, 0.98));
  border: 1px solid var(--glass-border);
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  padding: 10px 14px;
  box-shadow: 0 20px 80px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  transform-style: preserve-3d;
  transition: transform 0.1s ease;
}

.device-glow {
  position: absolute;
  inset: -20%;
  background: radial-gradient(ellipse at center, var(--ts-red-glow), transparent 70%);
  opacity: 0.15;
  pointer-events: none;
  z-index: -1;
}

/* Dashboard top bar */
.dash-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 6px 8px;
  font-size: 9px;
  color: var(--ts-muted);
  font-weight: 500;
}

.dash-time {
  font-variant-numeric: tabular-nums;
}

.dash-temp-ambient {
  color: var(--ts-dim);
}

.dash-signal-bars {
  display: flex;
  gap: 1.5px;
  align-items: flex-end;
}

.dash-signal-bars span {
  display: block;
  width: 3px;
  background: var(--ts-muted);
  border-radius: 1px;
}

.dash-signal-bars span:nth-child(1) {
  height: 4px;
}
.dash-signal-bars span:nth-child(2) {
  height: 6px;
}
.dash-signal-bars span:nth-child(3) {
  height: 8px;
}
.dash-signal-bars span:nth-child(4) {
  height: 10px;
  opacity: 0.3;
}

/* Dashboard main layout */
.dash-main {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Speedometer */
.dash-speedo {
  flex: 0 0 90px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.speedo-arc {
  width: 80px;
  height: 55px;
  position: relative;
}

.speedo-svg {
  width: 100%;
  height: 100%;
}

.speedo-value {
  font-size: 26px;
  font-weight: 300;
  letter-spacing: -0.03em;
  line-height: 1;
  margin-top: -6px;
}

.speedo-unit {
  font-size: 8px;
  color: var(--ts-dim);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.speedo-gear {
  font-size: 10px;
  font-weight: 600;
  color: var(--ts-red);
  margin-top: 4px;
}

/* Center car view */
.dash-center {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  min-height: 140px;
}

.dash-car-topview {
  width: 60px;
  color: var(--ts-text);
}

.dash-car-topview svg {
  width: 100%;
  height: auto;
}

/* Route visualization */
.dash-route {
  position: absolute;
  top: 10%;
  left: 50%;
  transform: translateX(-50%);
  width: 2px;
  height: 80%;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.route-line {
  width: 1px;
  flex: 1;
  background: linear-gradient(180deg, transparent, var(--ts-blue), transparent);
  opacity: 0.2;
}

.route-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
}

.route-dot-start {
  background: var(--ts-blue);
  box-shadow: 0 0 6px var(--ts-blue-glow);
}

.route-dot-end {
  background: var(--ts-red);
  box-shadow: 0 0 6px var(--ts-red-glow);
}

/* Right info panel */
.dash-info {
  flex: 0 0 90px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* Battery */
.dash-battery {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.battery-label {
  font-size: 7px;
  color: var(--ts-dim);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 500;
}

.battery-bar {
  width: 100%;
  height: 6px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 3px;
  overflow: hidden;
}

.battery-fill {
  width: 78%;
  height: 100%;
  background: linear-gradient(90deg, var(--ts-blue), #4ade80);
  border-radius: 3px;
}

.battery-pct {
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.battery-range {
  font-size: 8px;
  color: var(--ts-dim);
}

/* Climate */
.dash-climate {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.climate-label {
  font-size: 7px;
  color: var(--ts-dim);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 500;
}

.climate-temps {
  display: flex;
  align-items: center;
  gap: 6px;
}

.climate-driver,
.climate-passenger {
  display: flex;
  align-items: baseline;
  gap: 2px;
}

.climate-val {
  font-size: 14px;
  font-weight: 500;
}

.climate-side {
  font-size: 7px;
  color: var(--ts-dim);
}

.climate-divider {
  width: 1px;
  height: 16px;
  background: var(--glass-border);
}

/* Dashboard bottom nav */
.dash-bottom {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 8px 0 4px;
  border-top: 1px solid rgba(255, 255, 255, 0.04);
}

.dash-nav-btn {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: var(--ts-dim);
  transition: color 0.3s ease, background 0.3s ease;
}

.dash-nav-btn.active {
  color: var(--ts-red);
  background: var(--ts-red-subtle);
}

/* ═══════════════════════════════════════════════════════════════════════
   FINAL CTA
   ═══════════════════════════════════════════════════════════════════════ */

.cta-section {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
