import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";

interface BlurFadeProps {
  children: ReactNode;
  blurAmount?: number;
  duration?: number;
  delay?: number;
  yOffset?: number;
  threshold?: number;
  className?: string;
  style?: CSSProperties;
}

export function BlurFade({
  children,
  blurAmount = 10,
  duration = 800,
  delay = 0,
  yOffset = 20,
  threshold = 0.15,
  className = "",
  style = {},
}: BlurFadeProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(el);
        }
      },
      { threshold, rootMargin: "0px 0px -40px 0px" }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [threshold]);

  const baseStyle: CSSProperties = {
    filter: isVisible ? "blur(0px)" : `blur(${blurAmount}px)`,
    opacity: isVisible ? 1 : 0,
    transform: isVisible ? "translateY(0)" : `translateY(${yOffset}px)`,
    transition: `filter ${duration}ms cubic-bezier(0.16, 1, 0.3, 1) ${delay}ms, opacity ${duration}ms cubic-bezier(0.16, 1, 0.3, 1) ${delay}ms, transform ${duration}ms cubic-bezier(0.16, 1, 0.3, 1) ${delay}ms`,
    willChange: "filter, opacity, transform",
    ...style,
  };

  return (
    <div ref={ref} className={className} style={baseStyle}>
