import { useState, type CSSProperties, type ReactNode, type MouseEvent } from "react";

type Variant =
  | "default"
  | "blue"
  | "purple"
  | "emerald"
  | "rose"
  | "slide-right"
  | "curtain"
  | "glow";

interface InteractiveHoverButtonProps {
  children: ReactNode;
  onClick?: (e: MouseEvent<HTMLButtonElement>) => void;
  variant?: Variant;
  size?: "sm" | "md" | "lg";
  className?: string;
}

const variantConfig: Record<
  Variant,
  { fill: string; text: string; textHover: string; border: string; borderHover: string }
> = {
  default: {
    fill: "#f1f5f9",
    text: "#e2e8f0",
    textHover: "#0a0a0a",
    border: "#475569",
    borderHover: "#f1f5f9",
  },
  blue: {
    fill: "#3b82f6",
    text: "#93c5fd",
    textHover: "#fff",
    border: "#3b82f6",
    borderHover: "#60a5fa",
  },
  purple: {
    fill: "#8b5cf6",
    text: "#c4b5fd",
    textHover: "#fff",
    border: "#8b5cf6",
    borderHover: "#a78bfa",
  },
  emerald: {
    fill: "#10b981",
    text: "#6ee7b7",
    textHover: "#fff",
    border: "#10b981",
    borderHover: "#34d399",
  },
  rose: {
    fill: "#f43f5e",
    text: "#fda4af",
    textHover: "#fff",
    border: "#f43f5e",
    borderHover: "#fb7185",
  },
  "slide-right": {
    fill: "#f1f5f9",
    text: "#e2e8f0",
    textHover: "#0a0a0a",
    border: "#475569",
    borderHover: "#f1f5f9",
  },
  curtain: {
    fill: "#8b5cf6",
    text: "#c4b5fd",
    textHover: "#fff",
    border: "#8b5cf6",
    borderHover: "#a78bfa",
  },
  glow: {
    fill: "#3b82f6",
    text: "#93c5fd",
    textHover: "#fff",
    border: "#3b82f6",
    borderHover: "#60a5fa",
  },
};

const sizeStyles: Record<string, CSSProperties> = {
  sm: { padding: "0.625rem 1.5rem", fontSize: "0.8125rem" },
  md: { padding: "0.875rem 2rem", fontSize: "0.9375rem" },
  lg: { padding: "1.125rem 2.75rem", fontSize: "1.0625rem" },
};

export function InteractiveHoverButton({
  children,
  onClick,
  variant = "default",
  size = "md",
  className = "",
}: InteractiveHoverButtonProps) {
  const [hovered, setHovered] = useState(false);
  const config = variantConfig[variant];

  const isSlideRight = variant === "slide-right";
  const isCurtain = variant === "curtain";
  const isGlow = variant === "glow";

  const btnStyle: CSSProperties = {
    position: "relative",
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    borderRadius: "10px",
    fontWeight: 600,
    letterSpacing: "0.01em",
    cursor: "pointer",
    background: "transparent",
    border: `1.5px solid ${hovered ? config.borderHover : config.border}`,
    outline: "none",
    overflow: "hidden",
    transition: "border-color 0.35s ease, box-shadow 0.35s ease",
    boxShadow:
      isGlow && hovered ? "0 0 20px rgba(59,130,246,0.4), 0 0 40px rgba(59,130,246,0.2)" : "none",
    ...sizeStyles[size],
  };

  const fillStyle: CSSProperties = isSlideRight
    ? {
        position: "absolute",
        top: 0,
        left: 0,
        width: hovered ? "100%" : "0",
        height: "100%",
        background: config.fill,
        transition: "width 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94)",
        zIndex: 0,
      }
    : isCurtain
      ? {
          position: "absolute",
          top: "50%",
          left: 0,
          width: "100%",
          height: hovered ? "100%" : "0",
          transform: "translateY(-50%)",
          background: config.fill,
          transition: "height 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94)",
          zIndex: 0,
        }
      : {
          position: "absolute",
          bottom: 0,
          left: 0,
          width: "100%",
          height: hovered ? "100%" : "0",
          background: config.fill,
          transition: "height 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94)",
          zIndex: 0,
        };

  const labelStyle: CSSProperties = {
    position: "relative",
    zIndex: 1,
    color: hovered ? config.textHover : config.text,
    transition: "color 0.35s ease",
  };

  return (
    <button
      onClick={onClick}
      className={className}
      style={btnStyle}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      <span style={fillStyle} />
      <span style={labelStyle}>{children}</span>
    </button>
  );
}

export default function InteractiveHoverButtonDemo() {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "#0a0a0a",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        gap: "2rem",
        padding: "2rem",
        fontFamily: "system-ui, -apple-system, sans-serif",
      }}
    >
      <h2 style={{ fontSize: "1.5rem", fontWeight: 700, color: "#e2e8f0" }}>
        Interactive Hover Buttons
      </h2>
      <p style={{ color: "#525252", fontSize: "0.875rem" }}>
        Hover over the buttons to see the fill effect
      </p>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "2rem", justifyContent: "center" }}>
        <InteractiveHoverButton variant="default">Explore</InteractiveHoverButton>
        <InteractiveHoverButton variant="blue">Get Started</InteractiveHoverButton>
        <InteractiveHoverButton variant="purple">Learn More</InteractiveHoverButton>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "2rem", justifyContent: "center" }}>
        <InteractiveHoverButton variant="emerald" size="lg">
          Download Now
        </InteractiveHoverButton>
        <InteractiveHoverButton variant="rose" size="sm">
          Sign Up
        </InteractiveHoverButton>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "2rem", justifyContent: "center" }}>
        <InteractiveHoverButton variant="slide-right">Slide Right</InteractiveHoverButton>
        <InteractiveHoverButton variant="curtain">Curtain Reveal</InteractiveHoverButton>
        <InteractiveHoverButton variant="glow">Glow Effect</InteractiveHoverButton>
      </div>
    </div>
  );
}

snippets.css:
/* ═══════════════════════════════════════════════════════════════════════
   Uber UHD Ride-Share Landing Page — Styles
   ═══════════════════════════════════════════════════════════════════════ */

:root {
  --uber-black: #000000;
  --uber-dark: #0a0a0a;
  --uber-surface: #141414;
  --uber-border: rgba(255, 255, 255, 0.08);
  --uber-green: #06c167;
  --uber-green-glow: rgba(6, 193, 103, 0.25);
  --uber-green-subtle: rgba(6, 193, 103, 0.08);
  --uber-text: #ffffff;
  --uber-muted: #999999;
  --uber-dim: #666666;
  --glass-bg: rgba(255, 255, 255, 0.04);
  --glass-border: rgba(255, 255, 255, 0.08);
  --glass-hover: rgba(255, 255, 255, 0.07);
  --radius: 16px;
  --radius-lg: 24px;
  --font: "SF Pro Display", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--uber-black);
  color: var(--uber-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

/* ── Canvas background ── */
#mesh-bg {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}

main {
  position: relative;
  z-index: 1;
}

/* ── Shared ── */
section {
  position: relative;
  padding: 120px 1.5rem;
}

.section-container {
  max-width: 1100px;
  margin: 0 auto;
}

.section-header {
  margin-bottom: 3.5rem;
}

.section-title {
  font-size: clamp(2.5rem, 7vw, 4.5rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.04em;
  margin-bottom: 1rem;
}

.text-muted {
  color: var(--uber-muted);
  font-size: 1.05rem;
  line-height: 1.6;
}

.text-sm {
  font-size: 0.875rem;
}

.tag {
  display: inline-block;
  padding: 6px 16px;
  background: var(--uber-green);
  color: #000;
  border-radius: 100px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 1.25rem;
}

.reveal {
  opacity: 0;
  transform: translateY(30px);
}

/* ═══════════════════════════════════════════════════════════════════════
   HERO
   ═══════════════════════════════════════════════════════════════════════ */

.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 80px 1.5rem 60px;
  gap: 2.5rem;
}

.hero-content {
  position: relative;
  z-index: 2;
}

.hero-title {
  font-size: clamp(4rem, 14vw, 11rem);
  font-weight: 800;
  letter-spacing: -0.05em;
  line-height: 0.9;
  background: linear-gradient(180deg, #fff 30%, #666 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  opacity: 0;
}

.hero-subtitle {
  font-size: clamp(1rem, 2.5vw, 1.35rem);
  color: var(--uber-muted);
  font-weight: 400;
  margin-top: 1.25rem;
  letter-spacing: 0.01em;
  opacity: 0;
}

/* ── Booking card ── */
.hero-booking {
  width: 100%;
  max-width: 440px;
  z-index: 2;
}

.booking-card {
  background: var(--glass-bg);
  backdrop-filter: blur(24px) saturate(180%);
  -webkit-backdrop-filter: blur(24px) saturate(180%);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.booking-input-group {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.booking-input {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  transition: background 0.2s ease;
}

.booking-input:first-child {
  border-radius: 12px 12px 0 0;
}

.booking-input:last-child {
  border-radius: 0 0 12px 12px;
}

.booking-input:hover {
  background: rgba(255, 255, 255, 0.09);
}

.input-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

.dot-green {
  background: var(--uber-green);
  box-shadow: 0 0 8px var(--uber-green-glow);
}

.dot-dark {
  background: var(--uber-dim);
}

.input-placeholder {
  font-size: 0.95rem;
  color: var(--uber-muted);
  font-weight: 400;
}

.booking-divider {
  height: 1px;
  background: rgba(255, 255, 255, 0.06);
  margin-left: 38px;
}

.booking-btn {
  width: 100%;
  padding: 14px;
  background: var(--uber-text);
  color: var(--uber-black);
  border: none;
  border-radius: 12px;
  font-family: var(--font);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.booking-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 24px rgba(255, 255, 255, 0.15);
}

/* ── Scroll indicator ── */
.scroll-indicator {
  position: absolute;
  bottom: 40px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  color: var(--uber-dim);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.3em;
  font-weight: 700;
  opacity: 0;
}

.scroll-line {
  width: 1px;
  height: 50px;
  background: linear-gradient(to bottom, var(--uber-green), transparent);
}

/* ═══════════════════════════════════════════════════════════════════════
   RIDE TYPES
   ═══════════════════════════════════════════════════════════════════════ */

.rides-section {
  padding: 100px 1.5rem 120px;
}

.rides-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
}

.ride-card {
  background: var(--glass-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  position: relative;
  opacity: 0;
  transform: translateY(30px);
  transition: border-color 0.3s ease, background 0.3s ease, transform 0.3s ease;
}

.ride-card:hover {
  background: var(--glass-hover);
  border-color: rgba(255, 255, 255, 0.15);
  transform: translateY(-4px);
}

.ride-card-featured {
  border-color: rgba(6, 193, 103, 0.25);
}

.ride-card-featured:hover {
  border-color: rgba(6, 193, 103, 0.45);
  box-shadow: 0 0 40px rgba(6, 193, 103, 0.08);
}

.ride-icon {
  width: 80px;
  height: 40px;
  color: var(--uber-text);
  margin-bottom: 1.25rem;
  opacity: 0.85;
}

.ride-name {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 0.4rem;
}

.ride-desc {
  font-size: 0.8rem;
  color: var(--uber-muted);
  margin-bottom: 1.25rem;
  line-height: 1.5;
}

.ride-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.ride-time {
  font-size: 0.8rem;
  color: var(--uber-dim);
  font-weight: 500;
}

.ride-price {
  font-size: 1rem;
  font-weight: 700;
  color: var(--uber-text);
}

.eco-badge {
  position: absolute;
  top: 16px;
  right: 16px;
  padding: 4px 10px;
  background: var(--uber-green);
  color: #000;
  border-radius: 100px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

/* ═══════════════════════════════════════════════════════════════════════
   HOW IT WORKS (pinned)
   ═══════════════════════════════════════════════════════════════════════ */

.how-track {
  position: relative;
  height: 300vh;
  padding: 0;
}

.how-sticky {
  position: sticky;
  top: 0;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 8%;
  gap: 4rem;
}

.how-content {
  max-width: 400px;
  position: relative;
  flex-shrink: 0;
}

/* Step dots */
.step-dots {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 2rem;
}

.step-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  transition: background 0.4s ease, transform 0.4s ease;
}

.step-dot.active {
  background: var(--uber-green);
  transform: scale(1.3);
  box-shadow: 0 0 10px var(--uber-green-glow);
}

/* Step cards */
.step-card {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  opacity: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.step-card.active {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
  position: relative;
}

.step-heading {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 1rem;
  line-height: 1.1;
}

.step-desc {
  font-size: 0.95rem;
  color: var(--uber-muted);
  line-height: 1.7;
}

/* How visuals */
.how-visuals {
  position: relative;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
