            color: "#71717a",
            letterSpacing: "0.08em",
            textTransform: "uppercase",
            fontFamily: "system-ui, -apple-system, sans-serif",
          }}
        >
          Perspective grid with vanishing-point effect
        </p>
        <div
          style={{
            width: 80,
