*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: Inter, system-ui, sans-serif;
  background: #0a0a0a;
  color: #f2f6ff;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

.demo {
  width: 100%;
  max-width: 520px;
}

.demo-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.375rem;
}

.demo-sub {
  color: #475569;
  font-size: 0.875rem;
  margin-bottom: 2rem;
}

.demo-section {
  margin-bottom: 2rem;
}

.demo-label {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.75rem;
}

.demo-row {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Base ── */
.spinner {
  --spinner-color: #38bdf8;
  --spinner-size: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.spinner--sm {
  --spinner-size: 16px;
}
.spinner--lg {
  --spinner-size: 36px;
}

/* ── Circle ── */
.spinner--circle {
  width: var(--spinner-size);
  height: var(--spinner-size);
  border: 2.5px solid rgba(255, 255, 255, 0.08);
  border-top-color: var(--spinner-color);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}

.spinner--sm.spinner--circle {
  border-width: 2px;
}
.spinner--lg.spinner--circle {
  border-width: 3px;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* ── Dots ── */
.spinner--dots {
  gap: calc(var(--spinner-size) * 0.25);
}

.spinner--dots .dot {
  width: calc(var(--spinner-size) * 0.35);
  height: calc(var(--spinner-size) * 0.35);
  background: var(--spinner-color);
  border-radius: 50%;
  animation: bounce 1.4s ease-in-out infinite both;
}

.spinner--dots .dot:nth-child(1) {
  animation-delay: -0.32s;
}
.spinner--dots .dot:nth-child(2) {
  animation-delay: -0.16s;
}
.spinner--dots .dot:nth-child(3) {
  animation-delay: 0s;
}

@keyframes bounce {
  0%,
  80%,
  100% {
    transform: scale(0.4);
    opacity: 0.4;
  }
  40% {
    transform: scale(1);
    opacity: 1;
  }
}

/* ── Bars ── */
.spinner--bars {
  gap: calc(var(--spinner-size) * 0.1);
  height: var(--spinner-size);
}

.spinner--bars .bar {
  width: calc(var(--spinner-size) * 0.15);
  height: 100%;
  background: var(--spinner-color);
  border-radius: 2px;
  animation: bars 1.2s ease-in-out infinite;
}

.spinner--bars .bar:nth-child(1) {
  animation-delay: -0.36s;
}
.spinner--bars .bar:nth-child(2) {
  animation-delay: -0.24s;
}
.spinner--bars .bar:nth-child(3) {
  animation-delay: -0.12s;
}
.spinner--bars .bar:nth-child(4) {
  animation-delay: 0s;
}

@keyframes bars {
  0%,
  40%,
  100% {
    transform: scaleY(0.4);
    opacity: 0.4;
  }
  20% {
    transform: scaleY(1);
    opacity: 1;
  }
}

/* ── Pulse ── */
.spinner--pulse {
  width: var(--spinner-size);
  height: var(--spinner-size);
  position: relative;
}

.spinner--pulse::before,
.spinner--pulse::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: var(--spinner-color);
}

.spinner--pulse::before {
  animation: pulse-ring 1.5s ease-out infinite;
}

.spinner--pulse::after {
  animation: pulse-dot 1.5s ease-out infinite;
}

@keyframes pulse-ring {
  0% {
    transform: scale(0.5);
    opacity: 0.6;
  }
  100% {
    transform: scale(1.8);
    opacity: 0;
  }
}

@keyframes pulse-dot {
  0%,
  100% {
    transform: scale(0.5);
    opacity: 1;
  }
  50% {
    transform: scale(0.7);
    opacity: 0.8;
  }
}

