import { ReactNode, CSSProperties } from "react";

interface LevelProps {
  left?: ReactNode;
  center?: ReactNode;
  right?: ReactNode;
  children?: ReactNode;
  style?: CSSProperties;
  variant?: "default" | "card" | "footer";
}

export function Level({ left, center, right, children, style, variant = "default" }: LevelProps) {
  const bg = variant === "footer" ? "transparent" : "#141414";
  const border = variant === "footer" ? "1px solid #1a1a1a" : "1px solid #1e1e1e";

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: children ? "space-around" : "space-between",
        gap: "1rem",
        padding: variant === "footer" ? "0.625rem 1rem" : "0.75rem 1rem",
        background: bg,
        border,
        borderRadius: "0.75rem",
        ...style,
      }}
    >
      {children ? (
        children
      ) : (
        <>
          {left && (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: "0.75rem",
                justifyContent: "flex-start",
              }}
            >
              {left}
            </div>
          )}
          {center && (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: "0.75rem",
                justifyContent: "center",
              }}
            >
              {center}
            </div>
          )}
          {right && (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: "0.75rem",
                justifyContent: "flex-end",
              }}
            >
              {right}
            </div>
          )}
        </>
      )}
    </div>
  );
}

interface LevelItemProps {
  value: string;
  label: string;
}

export function LevelItem({ value, label }: LevelItemProps) {
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: "0.125rem",
      }}
    >
      <span style={{ fontSize: "1.25rem", fontWeight: 800, color: "#f2f6ff" }}>{value}</span>
      <span
        style={{
          fontSize: "0.6875rem",
          fontWeight: 500,
          color: "#4a4a4a",
          textTransform: "uppercase",
          letterSpacing: "0.05em",
        }}
      >
        {label}
      </span>
    </div>
  );
}

/* Demo */
export default function LevelLayoutDemo() {
  const linkStyle: CSSProperties = {
    fontSize: "0.8125rem",
    color: "#94a3b8",
    textDecoration: "none",
    cursor: "pointer",
  };

  const btnStyle: CSSProperties = {
    background: "rgba(56,189,248,0.1)",
    color: "#38bdf8",
    border: "1px solid rgba(56,189,248,0.2)",
    padding: "0.4rem 0.875rem",
    fontSize: "0.8125rem",
    fontWeight: 600,
    fontFamily: "inherit",
    borderRadius: "0.5rem",
    cursor: "pointer",
  };

  const btnSmStyle: CSSProperties = {
    ...btnStyle,
    padding: "0.25rem 0.625rem",
