              textTransform: "uppercase",
              letterSpacing: "0.04em",
            }}
          >
            Total Count
          </span>

          <div style={{ display: "flex", alignItems: "baseline" }}>
            {prefix && (
              <span style={{ fontSize: "2rem", fontWeight: 700, color: "#e2e8f0" }}>{prefix}</span>
            )}

            <div
              style={{
                display: "flex",
                alignItems: "baseline",
                overflow: "hidden",
                height: "1em",
                fontSize: "2.5rem",
                fontWeight: 700,
                lineHeight: 1,
                color: "#f8fafc",
              }}
            >
              {digits.map((digit, i) => {
                const needsSep = separator && i > 0 && (digits.length - i) % 3 === 0;

                return (
                  <span key={i} style={{ display: "contents" }}>
                    {needsSep && (
                      <span
                        style={{
                          height: "1em",
                          display: "flex",
                          alignItems: "center",
                          color: "#475569",
                          fontSize: "0.85em",
                        }}
                      >
                        {separator}
                      </span>
                    )}
                    <DigitColumn
                      digit={digit}
                      index={i}
                      totalDigits={digits.length}
                      animate={animate}
                      duration={duration}
                    />
                  </span>
                );
              })}
            </div>

            {suffix && (
              <span style={{ fontSize: "1.25rem", color: "#64748b", marginLeft: "0.1rem" }}>
                {suffix}
              </span>
            )}
          </div>
        </div>

        <button
          onClick={replay}
          style={{
            background: "rgba(99,102,241,0.1)",
