            color: "#a5b4fc",
            fontSize: "0.85rem",
            fontWeight: 500,
            padding: "0.5rem 1.25rem",
            borderRadius: "0.5rem",
            cursor: "pointer",
          }}
        >
          Replay Animation
        </button>
      </div>
    </div>
  );
}

