body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #0a0a0a;
  color: #f1f5f9;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 2rem;
}

/* ── Hero ── */
.hero-wrapper {
  width: min(700px, 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2.5rem;
}

.hero-content {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
}

.hero-badge {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #a78bfa;
  background: rgba(167, 139, 250, 0.1);
  padding: 0.25rem 0.75rem;
  border-radius: 999px;
  border: 1px solid rgba(167, 139, 250, 0.2);
}

.hero-heading {
  font-size: 2.5rem;
  font-weight: 800;
  color: #f8fafc;
  line-height: 1.1;
}

.hero-subheading {
  font-size: 1rem;
  color: #94a3b8;
  max-width: 440px;
  line-height: 1.6;
}

/* ── Thumbnail ── */
.video-thumbnail {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: 1rem;
  overflow: hidden;
  cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.video-thumbnail:hover {
  transform: scale(1.01);
  box-shadow: 0 20px 60px rgba(99, 102, 241, 0.15);
}

.thumbnail-image {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #1e1b4b, #312e81, #4c1d95);
  position: relative;
}

.thumbnail-image::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, transparent 30%, rgba(0, 0, 0, 0.4));
}

/* ── Play button ── */
.play-button {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 72px;
  height: 72px;
  border-radius: 50%;
  border: none;
  background: rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: #fff;
  cursor: pointer;
  display: grid;
  place-items: center;
  z-index: 2;
  transition: background 0.2s ease, transform 0.2s ease;
}

.play-button:hover {
  background: rgba(255, 255, 255, 0.25);
  transform: translate(-50%, -50%) scale(1.08);
}

.play-pulse {
  position: absolute;
  inset: -6px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.3);
  animation: pulse-ring 2s ease-out infinite;
}

@keyframes pulse-ring {
  0% {
    transform: scale(1);
    opacity: 1;
  }
  100% {
    transform: scale(1.4);
    opacity: 0;
  }
}

/* ── Modal ── */
.video-modal {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 2rem;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0.3s ease;
}

.video-modal.open {
  opacity: 1;
  visibility: visible;
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.8);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.modal-content {
  position: relative;
  width: min(900px, 100%);
  z-index: 1;
  transform: scale(0.9);
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}

.video-modal.open .modal-content {
  transform: scale(1);
}

.modal-close {
  position: absolute;
  top: -2.5rem;
  right: 0;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 0.5rem;
  color: #f1f5f9;
  cursor: pointer;
  padding: 0.35rem;
  display: grid;
  place-items: center;
  transition: background 0.15s ease;
}

.modal-close:hover {
  background: rgba(255, 255, 255, 0.2);
}

.modal-video-container {
  border-radius: 0.875rem;
  overflow: hidden;
  background: #000;
  box-shadow: 0 25px 80px rgba(0, 0, 0, 0.6);
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  .play-pulse {
    animation: none;
  }
  .video-modal,
  .modal-content,
  .video-thumbnail {
    transition: none;
  }
}

