    setIsOpen(true);
  }, []);

  const close = useCallback(() => {
    setIsOpen(false);
    videoRef.current?.pause();
  }, []);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
      videoRef.current?.play().catch(() => {});
