*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #0a0a0a;
}

/* --- Border Beam Card --- */
.border-beam-card {
  --beam-color: #22d3ee;
  --beam-speed: 4s;
  --border-width: 2px;

  position: relative;
  width: min(400px, calc(100vw - 2rem));
  border-radius: 1.25rem;
  overflow: hidden;
}

/* Rotating beam pseudo-element */
.border-beam-card__beam {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: conic-gradient(
    from 0deg,
    transparent 0%,
    transparent 70%,
    var(--beam-color) 76%,
    rgba(34, 211, 238, 0.6) 78%,
    transparent 82%,
    transparent 100%
  );
  animation: border-beam-rotate var(--beam-speed) linear infinite;
  z-index: 0;
}

/* Expand the gradient beyond card bounds to cover corners */
.border-beam-card__beam::before {
  content: "";
  position: absolute;
  inset: -50%;
  border-radius: inherit;
  background: inherit;
  animation: inherit;
}

@keyframes border-beam-rotate {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

/* Inner content overlaying the beam */
.border-beam-card__content {
  position: relative;
  z-index: 1;
  margin: var(--border-width);
  padding: 2.5rem;
  border-radius: calc(1.25rem - var(--border-width));
  background: #0a0a0a;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  color: #f1f5f9;
}

.card-icon {
  font-size: 1.75rem;
  line-height: 1;
}

.card-title {
  font-size: 1.375rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.card-body {
  font-size: 0.9375rem;
  line-height: 1.65;
  color: #94a3b8;
}

.card-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.tag {
  font-size: 0.75rem;
  font-weight: 500;
  padding: 0.25rem 0.75rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #cbd5e1;
}

.card-btn {
  margin-top: 0.5rem;
  align-self: flex-start;
  font-size: 0.875rem;
  font-weight: 600;
  padding: 0.625rem 1.25rem;
  border-radius: 0.75rem;
  border: 1px solid rgba(34, 211, 238, 0.4);
  background: rgba(34, 211, 238, 0.1);
  color: #22d3ee;
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease, transform 0.15s ease;
}

.card-btn:hover {
  background: rgba(34, 211, 238, 0.2);
  border-color: rgba(34, 211, 238, 0.6);
  transform: translateY(-1px);
}

.card-btn:active {
  transform: translateY(0);
}

