snippets.css:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #0a0a0a;
  color: #f1f5f9;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 2rem;
}

.collapsible-wrapper {
  width: min(560px, 100%);
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.collapsible-heading {
  font-size: 1.375rem;
  font-weight: 700;
  color: #f1f5f9;
}

.collapsible-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

/* ── Collapsible item ── */
.collapsible {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 0.875rem;
  overflow: hidden;
  transition: border-color 0.2s ease;
}

.collapsible.open {
  border-color: rgba(99, 102, 241, 0.2);
}

/* ── Trigger ── */
.collapsible-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.25rem;
  background: transparent;
  border: none;
  color: inherit;
  cursor: pointer;
  text-align: left;
  transition: background 0.15s ease;
}

.collapsible-trigger:hover {
  background: rgba(255, 255, 255, 0.02);
}

.trigger-left {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  min-width: 0;
}

.trigger-icon {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  border-radius: 0.5rem;
  display: grid;
  place-items: center;
}

.trigger-icon--blue {
  background: rgba(59, 130, 246, 0.12);
  color: #60a5fa;
}

.trigger-icon--purple {
  background: rgba(168, 85, 247, 0.12);
  color: #c084fc;
}

.trigger-icon--green {
  background: rgba(34, 197, 94, 0.12);
  color: #4ade80;
}

.trigger-left div:last-child {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}

.trigger-left strong {
  font-size: 0.9rem;
  font-weight: 600;
  color: #e2e8f0;
}

.trigger-left span {
  font-size: 0.78rem;
  color: #64748b;
}

/* ── Chevron ── */
.collapsible-chevron {
  flex-shrink: 0;
  color: #475569;
  transition: transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1), color 0.15s ease;
}

.collapsible.open .collapsible-chevron {
  transform: rotate(180deg);
  color: #6366f1;
}

/* ── Panel — grid-template-rows trick ── */
.collapsible-panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.collapsible.open .collapsible-panel {
  grid-template-rows: 1fr;
}

.collapsible-panel-inner {
  overflow: hidden;
}

/* ── Panel content ── */
.panel-content {
  padding: 0 1.25rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding-top: 1rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.form-field label {
  font-size: 0.78rem;
  font-weight: 500;
  color: #94a3b8;
}

.fake-input {
  font-size: 0.85rem;
  color: #e2e8f0;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.5rem;
  padding: 0.5rem 0.75rem;
}

.fake-input--tall {
  min-height: 4rem;
  line-height: 1.5;
}

.toggle-row {
  display: flex;
  align-items: center;
  gap: 0.625rem;
}

.toggle-row span {
  font-size: 0.85rem;
  color: #94a3b8;
}

.fake-toggle {
  width: 36px;
  height: 20px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  position: relative;
  transition: background 0.2s ease;
}

.fake-toggle::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #64748b;
  transition: transform 0.2s ease, background 0.2s ease;
}

.fake-toggle.active {
  background: rgba(99, 102, 241, 0.3);
}

.fake-toggle.active::after {
  transform: translateX(16px);
  background: #818cf8;
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  .collapsible-panel,
  .collapsible-chevron {
    transition: none;
  }
}

