import { useState, ReactNode, useCallback } from "react";

interface CollapsibleProps {
  trigger: ReactNode;
  children: ReactNode;
  defaultOpen?: boolean;
  icon?: ReactNode;
  iconBg?: string;
  iconColor?: string;
  title?: string;
  subtitle?: string;
}

function Collapsible({
  children,
  defaultOpen = false,
  icon,
  iconBg = "rgba(59,130,246,0.12)",
  iconColor = "#60a5fa",
  title = "Section",
  subtitle,
}: CollapsibleProps) {
  const [open, setOpen] = useState(defaultOpen);

  const toggle = useCallback(() => setOpen((prev) => !prev), []);

  return (
    <div
      style={{
        background: "rgba(255,255,255,0.03)",
        border: `1px solid ${open ? "rgba(99,102,241,0.2)" : "rgba(255,255,255,0.07)"}`,
        borderRadius: "0.875rem",
        overflow: "hidden",
        transition: "border-color 0.2s ease",
      }}
    >
      {/* Trigger */}
      <button
        onClick={toggle}
        aria-expanded={open}
        style={{
          width: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          gap: "1rem",
          padding: "1rem 1.25rem",
          background: "transparent",
          border: "none",
          color: "inherit",
          cursor: "pointer",
          textAlign: "left",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: "0.875rem", minWidth: 0 }}>
          {icon && (
            <div
              style={{
                flexShrink: 0,
                width: 36,
                height: 36,
                borderRadius: "0.5rem",
                display: "grid",
                placeItems: "center",
                background: iconBg,
                color: iconColor,
              }}
            >
              {icon}
            </div>
          )}
          <div style={{ display: "flex", flexDirection: "column", gap: "0.1rem" }}>
            <strong style={{ fontSize: "0.9rem", fontWeight: 600, color: "#e2e8f0" }}>
              {title}
            </strong>
            {subtitle && <span style={{ fontSize: "0.78rem", color: "#64748b" }}>{subtitle}</span>}
          </div>
        </div>

        <svg
          width="18"
          height="18"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth={2.5}
          style={{
            flexShrink: 0,
            color: open ? "#6366f1" : "#475569",
            transform: open ? "rotate(180deg)" : "rotate(0)",
            transition: "transform 0.35s cubic-bezier(0.34,1.56,0.64,1), color 0.15s ease",
          }}
        >
          <path d="m6 9 6 6 6-6" />
        </svg>
      </button>

      {/* Panel */}
      <div
        aria-hidden={!open}
        style={{
          display: "grid",
          gridTemplateRows: open ? "1fr" : "0fr",
          transition: "grid-template-rows 0.35s cubic-bezier(0.34,1.56,0.64,1)",
        }}
      >
        <div style={{ overflow: "hidden" }}>
          <div
            style={{
              padding: "0 1.25rem 1.25rem",
              borderTop: "1px solid rgba(255,255,255,0.05)",
              paddingTop: "1rem",
            }}
