@import url("https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap");

/* =============================================
   SPOTIFY UHD — Custom Properties
   ============================================= */
:root {
  --sp-black: #121212;
  --sp-dark: #191414;
  --sp-surface: #1a1a1a;
  --sp-surface-hover: #282828;
  --sp-border: rgba(255, 255, 255, 0.08);
  --sp-green: #1db954;
  --sp-green-dark: #1aa34a;
  --sp-green-glow: rgba(29, 185, 84, 0.25);
  --sp-green-subtle: rgba(29, 185, 84, 0.08);
  --sp-purple: #8b5cf6;
  --sp-purple-glow: rgba(139, 92, 246, 0.2);
  --sp-text: #ffffff;
  --sp-muted: #b3b3b3;
  --sp-dim: #535353;
  --glass-bg: rgba(255, 255, 255, 0.04);
  --glass-border: rgba(255, 255, 255, 0.08);
  --glass-hover: rgba(255, 255, 255, 0.07);
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 36px;
}

/* =============================================
   RESET & BASE
   ============================================= */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: auto;
}

body {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background-color: var(--sp-black);
  color: var(--sp-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
  line-height: 1.6;
}

/* =============================================
   CANVAS BACKGROUND
   ============================================= */
#mesh-bg {
  position: fixed;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

/* =============================================
   UTILITY CLASSES
   ============================================= */
.reveal {
  opacity: 0;
  transform: translateY(30px);
}

section {
  position: relative;
  z-index: 1;
  padding: 120px 1.5rem;
}

.section-container {
  max-width: 72rem;
  margin: 0 auto;
}

.section-header {
  margin-bottom: 3.5rem;
}

.section-title {
  font-size: clamp(2.5rem, 7vw, 5rem);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.04em;
  margin-bottom: 1.25rem;
  background: linear-gradient(180deg, #ffffff 0%, #a0a0a0 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.section-desc {
  font-size: 1.15rem;
  color: var(--sp-muted);
  max-width: 520px;
  line-height: 1.6;
}

/* =============================================
   TAGS
   ============================================= */
.tag {
  display: inline-block;
  padding: 6px 18px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  margin-bottom: 1.5rem;
}

.tag-green {
  background: var(--sp-green-subtle);
  color: var(--sp-green);
  border: 1px solid rgba(29, 185, 84, 0.15);
}

/* =============================================
   BUTTONS
   ============================================= */
.btn-primary {
  display: inline-block;
  padding: 16px 40px;
  border-radius: 500px;
  font-weight: 700;
  font-size: 1rem;
  font-family: inherit;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.23, 1, 0.32, 1);
  letter-spacing: 0.01em;
}

.btn-green {
  background: var(--sp-green);
  color: #000;
}

.btn-green:hover {
  background: #1ed760;
  transform: scale(1.04);
  box-shadow: 0 8px 30px var(--sp-green-glow);
}

.btn-secondary {
  display: inline-block;
  padding: 16px 40px;
  border-radius: 500px;
  font-weight: 700;
  font-size: 1rem;
  font-family: inherit;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.23, 1, 0.32, 1);
  background: transparent;
  color: var(--sp-text);
  border: 2px solid rgba(255, 255, 255, 0.3);
  letter-spacing: 0.01em;
}

.btn-secondary:hover {
  border-color: #fff;
  transform: scale(1.04);
}

.btn-glow {
  box-shadow: 0 0 40px var(--sp-green-glow), 0 0 80px rgba(29, 185, 84, 0.1);
}

/* =============================================
   GLASS CARD
   ============================================= */
.glass-card {
  background: var(--glass-bg);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-xl);
  padding: 48px;
  transition: all 0.5s cubic-bezier(0.23, 1, 0.32, 1);
}

.glass-card:hover {
  background: var(--glass-hover);
  border-color: rgba(255, 255, 255, 0.14);
}

/* =============================================
   SECTION 1: HERO
   ============================================= */
.hero-section {
  height: 100vh;
  min-height: 700px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
  padding: 0 1.5rem;
}

.hero-content {
  text-align: center;
  position: relative;
  z-index: 2;
}

.hero-logo {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-bottom: 2.5rem;
  opacity: 0;
}

.hero-brand {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.hero-title {
  font-size: clamp(3.5rem, 12vw, 9rem);
  font-weight: 900;
  line-height: 0.95;
  letter-spacing: -0.05em;
  background: linear-gradient(180deg, #ffffff 20%, rgba(255, 255, 255, 0.6) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 1.5rem;
  opacity: 0;
  transform: scale(0.9);
  filter: blur(10px);
}

.hero-subtitle {
  font-size: clamp(1rem, 2.5vw, 1.35rem);
  color: var(--sp-muted);
  font-weight: 400;
  margin-bottom: 2.5rem;
  opacity: 0;
}

.hero-buttons {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  opacity: 0;
}

.scroll-indicator {
  position: absolute;
  bottom: 40px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  color: var(--sp-dim);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.3em;
  font-weight: 700;
  opacity: 0;
  z-index: 2;
}

.scroll-line {
  width: 1px;
  height: 50px;
  background: linear-gradient(to bottom, var(--sp-green), transparent);
}

/* =============================================
   SECTION 2: PLAYLIST SHOWCASE
   ============================================= */
.playlist-section {
  padding: 140px 1.5rem;
}

.playlist-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 24px;
}

.playlist-card {
  background: var(--glass-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  transition: all 0.4s cubic-bezier(0.23, 1, 0.32, 1);
  position: relative;
  overflow: hidden;
  opacity: 0;
  transform: translateY(30px);
}

.playlist-card:hover {
  background: var(--glass-hover);
  border-color: rgba(255, 255, 255, 0.14);
  transform: translateY(-6px);
}

.playlist-card:hover .play-btn {
  opacity: 1;
  transform: translateY(0);
}

/* CSS-only album art */
.playlist-art {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-md);
  margin-bottom: 16px;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.art-icon {
  position: relative;
  z-index: 2;
  opacity: 0.5;
}

.art-shape {
  position: absolute;
  pointer-events: none;
}

/* Card 1 — Chill: teal/blue gradient */
.art-chill {
  background: linear-gradient(135deg, #0d4f3c 0%, #1a6b5a 30%, #2d9f90 60%, #1db954 100%);
}

.art-chill .art-shape-circle {
  width: 60%;
  height: 60%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(29, 185, 84, 0.4), transparent 70%);
  top: 20%;
  left: 20%;
}

.art-chill .art-shape-wave {
  width: 120%;
  height: 40%;
  bottom: -5%;
  left: -10%;
  background: linear-gradient(180deg, transparent, rgba(0, 0, 0, 0.3));
  border-radius: 50% 50% 0 0;
}

/* Card 2 — Hip Hop: orange/red gradient */
.art-hiphop {
  background: linear-gradient(135deg, #3d1c02 0%, #8b3a0f 30%, #d4651e 60%, #ff8c42 100%);
}

.art-hiphop .art-shape-diamond {
  width: 50%;
  height: 50%;
  background: rgba(255, 255, 255, 0.08);
  top: 25%;
  left: 25%;
  transform: rotate(45deg);
}

.art-hiphop .art-shape-bars {
  width: 100%;
  height: 30%;
  bottom: 0;
  left: 0;
  background: repeating-linear-gradient(
    90deg,
    rgba(255, 255, 255, 0.06) 0px,
    rgba(255, 255, 255, 0.06) 4px,
    transparent 4px,
    transparent 12px
  );
}

/* Card 3 — Electronic: purple/blue gradient */
.art-electronic {
  background: linear-gradient(135deg, #1a0533 0%, #4c1d95 30%, #7c3aed 60%, #a78bfa 100%);
}

.art-electronic .art-shape-rings {
  width: 70%;
  height: 70%;
  top: 15%;
  left: 15%;
  border: 2px solid rgba(255, 255, 255, 0.1);
  border-radius: 50%;
  box-shadow: inset 0 0 0 12px transparent, inset 0 0 0 14px rgba(255, 255, 255, 0.06), inset 0 0 0
    26px transparent, inset 0 0 0 28px rgba(255, 255, 255, 0.04);
}

.art-electronic .art-shape-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.3);
  top: 48%;
  left: 48%;
}

/* Card 4 — Indie: pink/coral gradient */
.art-indie {
  background: linear-gradient(135deg, #4a1942 0%, #893168 30%, #c2527a 60%, #e87ea1 100%);
}

.art-indie .art-shape-triangle {
  width: 0;
  height: 0;
  border-left: 40px solid transparent;
  border-right: 40px solid transparent;
  border-bottom: 70px solid rgba(255, 255, 255, 0.08);
  top: 20%;
  left: calc(50% - 40px);
}

.art-indie .art-shape-cross {
  width: 60%;
  height: 2px;
  background: rgba(255, 255, 255, 0.1);
  top: 50%;
  left: 20%;
}

.art-indie .art-shape-cross::after {
  content: "";
  position: absolute;
  width: 2px;
  height: 60px;
  background: rgba(255, 255, 255, 0.1);
  top: -30px;
  left: 50%;
}

/* Card 5 — Jazz: amber/gold gradient */
.art-jazz {
  background: linear-gradient(135deg, #3b2506 0%, #78500f 30%, #b8860b 60%, #daa520 100%);
}

.art-jazz .art-shape-arc {
  width: 80%;
  height: 80%;
  top: 10%;
  left: 10%;
  border: 2px solid rgba(255, 255, 255, 0.1);
  border-radius: 50%;
  border-bottom-color: transparent;
  border-left-color: transparent;
  transform: rotate(-20deg);
}

.art-jazz .art-shape-lines {
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  background: repeating-linear-gradient(
    45deg,
    transparent 0px,
    transparent 14px,
    rgba(255, 255, 255, 0.03) 14px,
    rgba(255, 255, 255, 0.03) 15px
  );
}

/* Card 6 — Workout: red/orange gradient */
.art-workout {
  background: linear-gradient(135deg, #3b0a0a 0%, #8b1a1a 30%, #dc2626 60%, #f87171 100%);
}

.art-workout .art-shape-bolt {
  width: 40px;
  height: 60px;
  top: 20%;
  left: calc(50% - 20px);
  background: rgba(255, 255, 255, 0.1);
  clip-path: polygon(50% 0%, 0% 50%, 35% 50%, 15% 100%, 100% 40%, 60% 40%);
}

.art-workout .art-shape-stripe {
  width: 200%;
  height: 30%;
  bottom: 10%;
  left: -50%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.05), transparent);
  transform: rotate(-15deg);
}

/* Playlist info */
.playlist-info {
  margin-bottom: 4px;
}

.playlist-name {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 4px;
  color: var(--sp-text);
}

.playlist-meta {
  font-size: 0.8rem;
  color: var(--sp-dim);
}

.play-btn {
  position: absolute;
  bottom: 92px;
  right: 28px;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--sp-green);
  color: #000;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transform: translateY(8px);
  transition: all 0.3s cubic-bezier(0.23, 1, 0.32, 1);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
}

.play-btn:hover {
  transform: scale(1.08) translateY(0);
  background: #1ed760;
}

.play-btn svg {
  margin-left: 2px;
}

/* =============================================
   SECTION 3: HOW IT WORKS (PINNED)
   ============================================= */
.how-section {
  padding: 0;
  position: relative;
}

.how-track {
  height: 300vh;
  position: relative;
}

.how-inner {
  position: sticky;
  top: 0;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 80px;
  padding: 0 2rem;
  max-width: 72rem;
  margin: 0 auto;
}

.how-text {
  flex: 1;
  max-width: 480px;
}

.steps-container {
  position: relative;
  min-height: 200px;
}

.step-card {
  opacity: 0;
  transform: translateY(20px);
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  transition: opacity 0.5s ease, transform 0.5s ease;
  pointer-events: none;
}

.step-card.active {
  opacity: 1;
  transform: translateY(0);
  position: relative;
  pointer-events: auto;
}

.step-number {
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--sp-green);
  letter-spacing: 0.1em;
  margin-bottom: 0.75rem;
}

.step-title {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 800;
  margin-bottom: 0.75rem;
  letter-spacing: -0.02em;
}

.step-desc {
  font-size: 1.05rem;
  color: var(--sp-muted);
  line-height: 1.6;
}

.step-dots {
  display: flex;
  gap: 10px;
  margin-top: 2rem;
}

.step-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--sp-dim);
  transition: all 0.4s ease;
  cursor: pointer;
}

.step-dot.active {
  background: var(--sp-green);
  box-shadow: 0 0 12px var(--sp-green-glow);
  transform: scale(1.2);
}

/* How visual — mini phones */
.how-visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  max-width: 320px;
  height: 500px;
}

.mini-phone {
  position: absolute;
  width: 220px;
  height: 440px;
  background: var(--sp-dark);
  border-radius: 30px;
  border: 2px solid rgba(255, 255, 255, 0.1);
  padding: 40px 14px 20px;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.6);
  opacity: 0;
  transform: scale(0.9);
  transition: opacity 0.6s ease, transform 0.6s ease;
  overflow: hidden;
}

.mini-phone.active {
  opacity: 1;
  transform: scale(1);
}

.mini-phone-notch {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  width: 80px;
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.15);
}

.mini-phone-screen {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* Mini phone 1: Browse */
.mini-search-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 10px;
  color: var(--sp-muted);
}

.mini-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  flex: 1;
}

.mini-tile {
  border-radius: 8px;
  min-height: 60px;
}

.mini-tile-1 {
  background: linear-gradient(135deg, #1db954, #064e2b);
}
.mini-tile-2 {
  background: linear-gradient(135deg, #8b5cf6, #3b1f7a);
}
.mini-tile-3 {
  background: linear-gradient(135deg, #e74c3c, #6b1d1d);
}
.mini-tile-4 {
  background: linear-gradient(135deg, #f39c12, #6b4406);
}
.mini-tile-5 {
  background: linear-gradient(135deg, #3498db, #153d5e);
}
.mini-tile-6 {
  background: linear-gradient(135deg, #e91e63, #601230);
}

/* Mini phone 2: Play */
.mini-now-playing {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding-top: 20px;
}

.mini-album-art {
  width: 140px;
  height: 140px;
  border-radius: 12px;
  background: linear-gradient(135deg, #1db954, #191414, #8b5cf6);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5);
}

.mini-song-info {
  text-align: center;
}

.mini-song-title {
  width: 100px;
  height: 10px;
  background: rgba(255, 255, 255, 0.7);
  border-radius: 5px;
  margin: 0 auto 6px;
}

.mini-song-artist {
  width: 70px;
  height: 8px;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 4px;
  margin: 0 auto;
}

.mini-progress {
  width: 85%;
  height: 3px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 2px;
  overflow: hidden;
}

.mini-progress::after {
  content: "";
  display: block;
  width: 40%;
  height: 100%;
  background: var(--sp-green);
  border-radius: 2px;
}

.mini-controls {
  display: flex;
  align-items: center;
  gap: 20px;
}

.mini-ctrl-dot {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.3);
}

.mini-ctrl-play {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: #fff;
  color: #000;
  display: flex;
  align-items: center;
  justify-content: center;
}

.mini-ctrl-play svg {
  margin-left: 2px;
}

/* Mini phone 3: Discover */
.mini-discover {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-top: 10px;
}

.mini-discover-title {
  width: 70%;
  height: 10px;
  background: rgba(255, 255, 255, 0.5);
  border-radius: 5px;
}

.mini-discover-row {
  display: flex;
  gap: 8px;
}

.mini-disc-card {
  flex: 1;
  height: 80px;
  border-radius: 8px;
}

.mini-disc-1 {
  background: linear-gradient(135deg, #ff6b6b, #ee5a24);
}
.mini-disc-2 {
  background: linear-gradient(135deg, #1db954, #0a8f3f);
}
.mini-disc-3 {
  background: linear-gradient(135deg, #a29bfe, #6c5ce7);
}
.mini-disc-4 {
  background: linear-gradient(135deg, #fdcb6e, #e17055);
}

/* Equalizer bars */
.equalizer {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 4px;
  height: 40px;
  margin-top: auto;
  padding-bottom: 10px;
}

.eq-bar {
  width: 4px;
  background: var(--sp-green);
  border-radius: 2px;
  animation: eq-bounce 1.2s ease-in-out infinite;
}

.eq-bar:nth-child(1) {
  height: 16px;
  animation-delay: 0s;
}
.eq-bar:nth-child(2) {
  height: 28px;
  animation-delay: 0.15s;
}
.eq-bar:nth-child(3) {
  height: 20px;
  animation-delay: 0.3s;
}
.eq-bar:nth-child(4) {
  height: 32px;
  animation-delay: 0.45s;
}
.eq-bar:nth-child(5) {
  height: 12px;
  animation-delay: 0.6s;
}

@keyframes eq-bounce {
  0%,
  100% {
    transform: scaleY(0.4);
  }
  50% {
    transform: scaleY(1);
  }
}

/* =============================================
   SECTION 4: STATS COUNTER
   ============================================= */
.stats-section {
  padding: 160px 1.5rem;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 48px;
  text-align: center;
  margin-top: 3rem;
}

.stat-item {
  padding: 40px 20px;
}

.stat-number {
  font-size: clamp(3rem, 8vw, 5rem);
  font-weight: 900;
  letter-spacing: -0.04em;
  background: linear-gradient(180deg, #ffffff 0%, var(--sp-green) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 0.5rem;
  line-height: 1;
}

.stat-label {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--sp-text);
}

.stat-desc {
  font-size: 0.9rem;
  color: var(--sp-dim);
  max-width: 260px;
  margin: 0 auto;
  line-height: 1.5;
}

/* =============================================
   SECTION 5: PREMIUM FEATURES
   ============================================= */
.premium-section {
  padding: 140px 1.5rem;
}

.premium-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
  margin-top: 3.5rem;
}

.premium-card {
  background: var(--glass-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  padding: 40px 32px;
  transition: all 0.4s cubic-bezier(0.23, 1, 0.32, 1);
  opacity: 0;
  transform: translateY(30px);
}

.premium-card:hover {
  background: var(--glass-hover);
  border-color: rgba(29, 185, 84, 0.2);
  transform: translateY(-6px);
}

.premium-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  background: var(--sp-green-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  color: var(--sp-green);
}

.premium-title {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
}

.premium-desc {
  font-size: 0.95rem;
  color: var(--sp-muted);
  line-height: 1.6;
}

/* =============================================
   SECTION 6: APP SHOWCASE (PHONE MOCKUP)
   ============================================= */
.app-section {
  padding: 140px 1.5rem;
}

.app-layout {
  display: flex;
  align-items: center;
  gap: 80px;
  flex-wrap: wrap;
  justify-content: center;
}

.app-text {
  flex: 1;
  min-width: 300px;
  max-width: 480px;
}

.app-features {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-top: 2rem;
}

.app-feature {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.95rem;
  color: var(--sp-muted);
}

/* Phone Mockup */
.phone-container {
  perspective: 1200px;
}

.phone-mockup {
  width: 300px;
  height: 620px;
  background: var(--sp-dark);
  border-radius: var(--radius-xl);
  border: 3px solid rgba(255, 255, 255, 0.1);
  padding: 50px 18px 24px;
  position: relative;
  box-shadow: 0 40px 100px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255, 255, 255, 0.05), inset 0 1px 0
    rgba(255, 255, 255, 0.06);
  transform-style: preserve-3d;
  transition: transform 0.3s ease;
}

.phone-notch {
  position: absolute;
  top: 16px;
  left: 50%;
  transform: translateX(-50%);
  width: 100px;
  height: 8px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.12);
}

.phone-screen {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Now Playing UI */
.np-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
  color: var(--sp-muted);
}

.np-playlist-name {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.np-album-art {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-md);
  overflow: hidden;
  margin-bottom: 24px;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.5);
}

.np-art-inner {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #0d3320, #1db954, #064e2b, #8b5cf6, #2d1b69);
  background-size: 200% 200%;
  animation: art-shift 8s ease-in-out infinite;
  position: relative;
  overflow: hidden;
}

@keyframes art-shift {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}

.np-art-shape {
  position: absolute;
  border-radius: 50%;
}

.np-art-shape-1 {
  width: 60%;
  height: 60%;
  top: 20%;
  left: 20%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.1), transparent 70%);
}

.np-art-shape-2 {
  width: 30%;
  height: 30%;
  bottom: 10%;
  right: 10%;
  background: radial-gradient(circle, rgba(29, 185, 84, 0.3), transparent 70%);
}

.np-art-shape-3 {
  width: 40%;
  height: 40%;
  top: 5%;
  left: 5%;
  background: radial-gradient(circle, rgba(139, 92, 246, 0.2), transparent 70%);
}

.np-song-details {
  margin-bottom: 16px;
}

.np-song-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.np-song-title {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 2px;
}

.np-song-artist {
  font-size: 0.85rem;
  color: var(--sp-muted);
}

.np-heart {
  cursor: pointer;
  transition: transform 0.2s ease;
}

.np-heart:hover {
  transform: scale(1.2);
}

/* Progress bar */
.np-progress {
  margin-bottom: 16px;
}

.np-progress-bar {
  width: 100%;
  height: 4px;
  background: rgba(255, 255, 255, 0.12);
  border-radius: 2px;
  position: relative;
  margin-bottom: 8px;
}

.np-progress-fill {
  width: 38%;
  height: 100%;
  background: var(--sp-green);
  border-radius: 2px;
  transition: width 0.3s ease;
}

.np-progress-dot {
  position: absolute;
  top: 50%;
  left: 38%;
  transform: translate(-50%, -50%);
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #fff;
  opacity: 0;
  transition: opacity 0.2s ease;
}

.np-progress:hover .np-progress-dot {
  opacity: 1;
}

.np-times {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--sp-dim);
}

/* Controls */
.np-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  margin-top: auto;
}

.np-ctrl {
  background: none;
  border: none;
  color: var(--sp-muted);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color 0.2s ease, transform 0.2s ease;
  padding: 0;
}

.np-ctrl:hover {
  color: var(--sp-text);
  transform: scale(1.1);
}

.np-play {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: #fff;
  color: #000;
}

.np-play:hover {
  transform: scale(1.06);
  color: #000;
}

.np-play svg {
  margin-left: 3px;
}

.np-shuffle,
.np-repeat {
  color: var(--sp-dim);
}

/* =============================================
   SECTION 7: FINAL CTA
   ============================================= */
.cta-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  min-height: 90vh;
  overflow: hidden;
  position: relative;
  padding: 120px 1.5rem;
}

.cta-content {
  position: relative;
  z-index: 2;
}

.cta-title {
  margin-bottom: 1rem;
}

.cta-subtitle {
  font-size: 1.15rem;
  color: var(--sp-muted);
  margin-bottom: 2.5rem;
}

.cta-buttons {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.cta-rings {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(29, 185, 84, 0.06);
}

.ring-1 {
  width: 300px;
  height: 300px;
}
.ring-2 {
  width: 520px;
  height: 520px;
}
.ring-3 {
  width: 740px;
  height: 740px;
}

.cta-orbs {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.cta-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(100px);
  opacity: 0.15;
}

.cta-orb-1 {
  width: 500px;
  height: 500px;
  background: var(--sp-green);
  top: 10%;
  left: -10%;
}

.cta-orb-2 {
  width: 400px;
  height: 400px;
  background: var(--sp-purple);
  bottom: 10%;
  right: -10%;
}

/* =============================================
   REDUCED MOTION
   ============================================= */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  .hero-title {
    opacity: 1;
    transform: none;
    filter: none;
  }

  .hero-subtitle,
  .hero-logo,
  .hero-buttons,
  .scroll-indicator {
    opacity: 1;
  }

  .reveal {
    opacity: 1;
    transform: none;
  }

  .playlist-card,
  .premium-card {
    opacity: 1;
    transform: none;
  }

  .step-card {
    position: relative;
    opacity: 1;
    transform: none;
  }

  .mini-phone {
    opacity: 1;
    transform: none;
  }

  .eq-bar {
    animation: none;
    transform: none;
  }

  .np-art-inner {
    animation: none;
  }
}

/* =============================================
   RESPONSIVE: 1024px
   ============================================= */
@media (max-width: 1024px) {
  .how-inner {
    gap: 40px;
    padding: 0 1.5rem;
  }

  .app-layout {
    gap: 48px;
  }

  .phone-mockup {
    width: 270px;
    height: 560px;
  }

  .premium-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* =============================================
   RESPONSIVE: 768px
   ============================================= */
@media (max-width: 768px) {
  section {
    padding: 80px 1rem;
  }

  .how-inner {
    flex-direction: column;
    gap: 40px;
    text-align: center;
    padding: 0 1rem;
  }

  .how-text {
    max-width: 100%;
  }

  .how-visual {
    max-width: 200px;
    height: 360px;
  }

  .mini-phone {
    width: 170px;
    height: 340px;
    padding: 32px 10px 16px;
    border-radius: 22px;
  }

  .step-dots {
    justify-content: center;
  }

  .app-layout {
    flex-direction: column;
    gap: 40px;
    text-align: center;
  }

  .app-text {
    min-width: 0;
  }

  .app-features {
    align-items: center;
  }

  .section-desc {
    margin-left: auto;
    margin-right: auto;
  }

  .phone-mockup {
    width: 260px;
    height: 540px;
    padding: 44px 16px 20px;
  }

  .playlist-grid {
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 16px;
  }

  .playlist-card {
    padding: 14px;
  }

  .play-btn {
    width: 40px;
    height: 40px;
    bottom: 76px;
    right: 22px;
  }

  .premium-grid {
    grid-template-columns: 1fr;
  }

  .premium-card {
    padding: 28px 24px;
  }

  .glass-card {
    padding: 28px;
    border-radius: var(--radius-lg);
  }

  .stats-grid {
    gap: 24px;
  }

  .stat-item {
    padding: 24px 12px;
  }

  .ring-1 {
    width: 200px;
    height: 200px;
  }
  .ring-2 {
    width: 360px;
    height: 360px;
  }
  .ring-3 {
    width: 520px;
    height: 520px;
  }
}

/* =============================================
   RESPONSIVE: 480px
   ============================================= */
@media (max-width: 480px) {
  .hero-title {
    font-size: clamp(2.8rem, 14vw, 5rem);
  }

  .hero-buttons {
    flex-direction: column;
    width: 100%;
    padding: 0 1rem;
  }

  .hero-buttons .btn-primary,
  .hero-buttons .btn-secondary {
    width: 100%;
    text-align: center;
  }

  .section-title {
    font-size: clamp(2rem, 9vw, 3.5rem);
  }

  .playlist-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
  }

  .playlist-card {
    padding: 10px;
    border-radius: var(--radius-md);
  }

  .playlist-name {
    font-size: 0.85rem;
  }

  .play-btn {
    width: 36px;
    height: 36px;
    bottom: 64px;
    right: 16px;
  }

  .phone-mockup {
    width: 240px;
    height: 500px;
    padding: 40px 14px 18px;
  }

  .np-album-art {
    margin-bottom: 16px;
  }

  .np-controls {
    gap: 16px;
  }

  .np-play {
    width: 48px;
    height: 48px;
  }

  .stat-number {
    font-size: clamp(2.5rem, 12vw, 4rem);
  }

  .how-track {
    height: 250vh;
  }

  .how-visual {
    max-width: 160px;
    height: 300px;
  }

  .mini-phone {
    width: 140px;
    height: 280px;
    padding: 28px 8px 12px;
    border-radius: 18px;
  }

  .mini-album-art {
    width: 100px;
    height: 100px;
  }

  .cta-section {
    min-height: 70vh;
  }
}

