  gap: 1rem;
  justify-content: center;
  margin-top: 2.5rem;
  opacity: 0;
}

/* ── Buttons ── */
.btn-primary {
  display: inline-block;
  padding: 16px 40px;
  background: var(--nk-text);
  color: var(--nk-black);
  border-radius: 30px;
  font-family: var(--font);
  font-weight: 800;
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  text-decoration: none;
  transition: all 0.3s ease;
  border: none;
  cursor: pointer;
  position: relative;
  z-index: 2;
}

.btn-primary:hover {
  transform: scale(1.05);
  box-shadow: 0 10px 30px rgba(255, 255, 255, 0.15);
}

.btn-volt {
  background: var(--nk-volt);
  color: var(--nk-black);
  box-shadow: 0 0 30px rgba(205, 255, 0, 0.15);
}

.btn-volt:hover {
  box-shadow: 0 0 50px rgba(205, 255, 0, 0.25);
}

.btn-secondary {
  display: inline-block;
  padding: 16px 40px;
  background: transparent;
  color: var(--nk-text);
  border: 2px solid rgba(255, 255, 255, 0.2);
  border-radius: 30px;
  font-family: var(--font);
  font-weight: 800;
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  text-decoration: none;
  transition: all 0.3s ease;
  cursor: pointer;
}

.btn-secondary:hover {
  border-color: var(--nk-volt);
  color: var(--nk-volt);
  box-shadow: 0 0 20px rgba(205, 255, 0, 0.1);
}

/* ── Scroll indicator ── */
.scroll-indicator {
  position: absolute;
  bottom: 40px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  color: var(--nk-dim);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.3em;
  font-weight: 700;
  opacity: 0;
}

.scroll-line {
  width: 1px;
  height: 50px;
  background: linear-gradient(to bottom, var(--nk-volt), transparent);
}

/* ═══════════════════════════════════════════════════════════════════════
   PRODUCTS
   ═══════════════════════════════════════════════════════════════════════ */

.products-section {
  padding: 100px 1.5rem 120px;
}

.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
}

.product-card {
  background: var(--glass-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  position: relative;
  opacity: 0;
  transform: translateY(30px);
  transition: border-color 0.3s ease, background 0.3s ease, transform 0.3s ease;
}

.product-card:hover {
  background: var(--glass-hover);
  border-color: rgba(255, 255, 255, 0.15);
  transform: translateY(-4px);
}

.product-card-featured {
  border-color: rgba(205, 255, 0, 0.25);
}

.product-card-featured:hover {
  border-color: rgba(205, 255, 0, 0.45);
  box-shadow: 0 0 40px rgba(205, 255, 0, 0.08);
}

.shoe-visual {
  width: 100%;
  height: 100px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  opacity: 0.85;
}

.shoe-svg {
  width: 100%;
  max-width: 180px;
  height: auto;
}

.product-name {
  font-size: 1.15rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  margin-bottom: 0.25rem;
}

.product-category {
  font-size: 0.8rem;
  color: var(--nk-muted);
  margin-bottom: 1.25rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-weight: 500;
}

.product-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.product-price {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--nk-text);
}

.shop-tag {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--nk-volt);
  padding: 4px 12px;
  border: 1px solid rgba(205, 255, 0, 0.2);
  border-radius: 100px;
  transition: background 0.3s ease, border-color 0.3s ease;
  cursor: pointer;
}

.shop-tag:hover {
  background: rgba(205, 255, 0, 0.1);
  border-color: rgba(205, 255, 0, 0.4);
}

.featured-badge {
  position: absolute;
  top: 16px;
  right: 16px;
  padding: 4px 10px;
  background: var(--nk-volt);
  color: #000;
  border-radius: 100px;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

/* ═══════════════════════════════════════════════════════════════════════
   INNOVATION (pinned)
   ═══════════════════════════════════════════════════════════════════════ */

.how-track {
  position: relative;
  height: 300vh;
  padding: 0;
}

.how-sticky {
  position: sticky;
  top: 0;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 8%;
  gap: 4rem;
}

.how-content {
  max-width: 400px;
  position: relative;
  flex-shrink: 0;
}

/* Step dots */
.step-dots {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 2rem;
}

.step-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
  transition: background 0.4s ease, transform 0.4s ease;
}

.step-dot.active {
  background: var(--nk-volt);
  transform: scale(1.3);
  box-shadow: 0 0 10px var(--nk-volt-glow);
}

/* Step cards */
.step-card {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  opacity: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.step-card.active {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
  position: relative;
}

.step-heading {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  margin-bottom: 1rem;
  line-height: 1.0;
  text-transform: uppercase;
}

.step-desc {
  font-size: 0.95rem;
  color: var(--nk-muted);
  line-height: 1.7;
}

/* How visuals */
.how-visuals {
  position: relative;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 400px;
}

.how-visual {
  position: absolute;
  opacity: 0;
  transform: translateY(20px) scale(0.95);
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.how-visual.active {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.innovation-visual {
  background: var(--glass-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--glass-border);
  border-radius: 28px;
  padding: 30px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4);
}

.react-bubble {
  animation: reactFloat 4s ease-in-out infinite alternate;
}

.react-bubble:nth-child(2n) {
  animation-delay: -1s;
  animation-duration: 3.5s;
}

.react-bubble:nth-child(3n) {
  animation-delay: -2s;
  animation-duration: 4.5s;
}

@keyframes reactFloat {
  0% {
    transform: translate(0, 0);
  }
  100% {
    transform: translate(2px, -4px);
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   STATS
   ═══════════════════════════════════════════════════════════════════════ */

.stats-section {
  padding: 100px 1.5rem;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-item {
  padding: 3rem 1.5rem;
}

.stat-number {
  font-size: clamp(3rem, 8vw, 5rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1;
  background: linear-gradient(180deg, #fff 0%, var(--nk-volt) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 1rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 0.75rem;
}

.stat-desc {
  font-size: 0.85rem;
  color: var(--nk-dim);
  max-width: 200px;
  margin: 0 auto;
  line-height: 1.5;
}

/* ═══════════════════════════════════════════════════════════════════════
   ATHLETE SPOTLIGHT
   ═══════════════════════════════════════════════════════════════════════ */

.athlete-section {
  padding: 100px 1.5rem;
}

.glass-card {
  background: var(--glass-bg);
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  border: 1px solid var(--glass-border);
  border-radius: 40px;
  padding: 60px;
  transition: border-color 0.4s ease;
}

.glass-card:hover {
  border-color: rgba(255, 255, 255, 0.14);
}

.athlete-layout {
  display: flex;
  gap: 4rem;
  align-items: center;
}

.athlete-figure {
  flex-shrink: 0;
  opacity: 0.9;
}

.athlete-figure svg {
  display: block;
}

.athlete-content {
  flex: 1;
}

.athlete-features {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  margin-bottom: 2.5rem;
}

.athlete-feature {
  display: flex;
  align-items: flex-start;
  gap: 1.25rem;
  padding: 1.25rem;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: var(--radius);
  transition: background 0.3s ease, transform 0.3s ease;
  opacity: 0;
  transform: translateX(-20px);
}

.athlete-feature:hover {
  background: rgba(255, 255, 255, 0.06);
  transform: translateX(4px);
}

.af-icon {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--nk-volt-subtle);
  border-radius: 10px;
  flex-shrink: 0;
}

.af-title {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 0.35rem;
}

.athlete-quote {
  font-size: clamp(1.1rem, 2.5vw, 1.4rem);
  font-style: italic;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.75);
  border-left: 3px solid var(--nk-volt);
  padding-left: 1.5rem;
  margin-bottom: 1.5rem;
}

.athlete-info {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.athlete-name {
  font-size: 1.15rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.athlete-sport {
  font-size: 0.85rem;
  color: var(--nk-volt);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

/* ═══════════════════════════════════════════════════════════════════════
   APP SHOWCASE — Nike Run Club
   ═══════════════════════════════════════════════════════════════════════ */

.app-section {
  padding: 120px 1.5rem;
}

.app-grid {
  display: flex;
  align-items: center;
  gap: 5rem;
}

.app-text {
  flex: 1;
}

.app-badges {
  display: flex;
  gap: 0.75rem;
  margin-top: 2.5rem;
  flex-wrap: wrap;
}

.store-badge {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 18px;
  background: var(--nk-text);
  color: var(--nk-black);
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.store-badge:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(255, 255, 255, 0.15);
}

.store-text {
  display: flex;
  flex-direction: column;
}

.store-small {
  font-size: 9px;
  font-weight: 500;
  opacity: 0.6;
  line-height: 1;
}

.store-name {
  font-size: 14px;
  font-weight: 700;
  line-height: 1.2;
}

/* ── Phone mockup ── */
.app-device {
  position: relative;
  perspective: 1000px;
}

.device-phone {
  position: relative;
  width: 280px;
  aspect-ratio: 9 / 19;
  background: var(--nk-surface);
  border: 3px solid rgba(255, 255, 255, 0.1);
  border-radius: 36px;
  overflow: hidden;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.04), 0 30px 80px rgba(0, 0, 0, 0.6);
  transform-style: preserve-3d;
}

.phone-notch {
  position: absolute;
  top: 8px;
  left: 50%;
  transform: translateX(-50%);
  width: 80px;
  height: 24px;
  background: var(--nk-black);
  border-radius: 12px;
  z-index: 3;
}

.phone-screen {
  width: 100%;
  height: 100%;
  padding: 0;
  background: var(--nk-dark);
}

/* NRC UI */
.nrc-ui {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.nrc-status {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 20px 6px;
  z-index: 2;
}

.nrc-time-display {
  font-size: 12px;
  font-weight: 600;
  color: var(--nk-text);
}

.nrc-status-icons {
  display: flex;
  gap: 3px;
  align-items: flex-end;
}

.status-bar-icon {
  width: 3px;
  height: 10px;
  background: var(--nk-text);
  border-radius: 1px;
  opacity: 0.6;
}

.status-bar-icon.short {
  height: 6px;
}

/* NRC Map */
.nrc-map {
  flex: 1;
  position: relative;
  background: linear-gradient(180deg, #0a1a0a 0%, #0d1f0a 50%, #111 100%);
  overflow: hidden;
  min-height: 0;
}

.nrc-route-svg {
  width: 100%;
  height: 100%;
  display: block;
}

.nrc-pulse {
  animation: nrcPulse 2s ease-in-out infinite;
}

@keyframes nrcPulse {
  0%,
  100% {
    r: 10;
    opacity: 0.4;
  }
  50% {
    r: 14;
    opacity: 0.15;
  }
}

/* NRC Stats */
.nrc-stats {
  display: flex;
  background: var(--nk-surface);
  border-top: 1px solid rgba(205, 255, 0, 0.1);
  padding: 14px 10px;
  gap: 4px;
}

.nrc-stat {
  flex: 1;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.nrc-stat-value {
  font-size: 18px;
  font-weight: 800;
  color: var(--nk-text);
  letter-spacing: -0.02em;
}

.nrc-stat-main .nrc-stat-value {
  font-size: 26px;
  color: var(--nk-volt);
}

.nrc-stat-label {
  font-size: 8px;
  color: var(--nk-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 600;
}

/* NRC Controls */
.nrc-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  padding: 14px 16px 20px;
  background: var(--nk-surface);
}

.nrc-btn-pause {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--nk-volt);
  color: var(--nk-black);
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 0 20px rgba(205, 255, 0, 0.3);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.nrc-btn-pause:hover {
  transform: scale(1.08);
  box-shadow: 0 0 30px rgba(205, 255, 0, 0.45);
}

.nrc-btn-secondary {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  color: var(--nk-muted);
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.2s ease;
}

.nrc-btn-secondary:hover {
  background: rgba(255, 255, 255, 0.14);
}

.device-glow {
  position: absolute;
  inset: -60px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(205, 255, 0, 0.1) 0%, transparent 70%);
  pointer-events: none;
  animation: glowPulse 6s ease-in-out infinite;
}

@keyframes glowPulse {
  0%,
  100% {
    opacity: 0.5;
    transform: scale(1);
  }
  50% {
    opacity: 1;
    transform: scale(1.08);
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   CTA
   ═══════════════════════════════════════════════════════════════════════ */

.cta-section {
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
  position: relative;
}

.cta-title {
  position: relative;
  z-index: 2;
}

.cta-subtitle {
  position: relative;
  z-index: 2;
  max-width: 440px;
  margin-bottom: 2.5rem;
}

.cta-rings {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(205, 255, 0, 0.06);
}

.ring-1 {
  width: 300px;
  height: 300px;
}
.ring-2 {
  width: 500px;
  height: 500px;
}
.ring-3 {
  width: 700px;
  height: 700px;
}

.cta-orbs {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.cta-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(100px);
}

.cta-orb-1 {
  width: 400px;
  height: 400px;
  background: rgba(205, 255, 0, 0.08);
  bottom: -100px;
  left: -80px;
}

.cta-orb-2 {
  width: 350px;
  height: 350px;
  background: rgba(205, 255, 0, 0.05);
  top: -60px;
  right: -80px;
}

/* ═══════════════════════════════════════════════════════════════════════
   REDUCED MOTION
   ═══════════════════════════════════════════════════════════════════════ */

@media (prefers-reduced-motion: reduce) {
  .reveal {
    opacity: 1;
    transform: none;
  }

  .product-card {
    opacity: 1;
    transform: none;
  }

  .athlete-feature {
    opacity: 1;
    transform: none;
  }

  .step-card {
    transition: none;
  }

  .how-visual {
    transition: none;
  }

  .step-dot {
    transition: none;
  }

  .react-bubble {
    animation: none;
  }

  .nrc-pulse {
    animation: none;
  }

  .device-glow {
    animation: none;
    opacity: 0.5;
  }

  .hero-title,
  .hero-subtitle,
  .hero-ctas,
  .hero-swoosh,
  .scroll-indicator {
    opacity: 1;
  }
}

/* ═══════════════════════════════════════════════════════════════════════
   RESPONSIVE
   ═══════════════════════════════════════════════════════════════════════ */

@media (max-width: 1024px) {
  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .app-grid {
    flex-direction: column;
    text-align: center;
    gap: 3rem;
  }

  .app-badges {
    justify-content: center;
  }

  .athlete-layout {
    flex-direction: column;
    text-align: center;
    gap: 2.5rem;
  }

  .athlete-quote {
    border-left: none;
    padding-left: 0;
    border-top: 3px solid var(--nk-volt);
    padding-top: 1.5rem;
  }

  .athlete-info {
    justify-content: center;
  }
}

@media (max-width: 768px) {
  section {
    padding: 80px 1.25rem;
  }

  .products-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin: 0 auto;
  }

  .stats-grid {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .stat-item {
    padding: 2rem 1rem;
  }

  .how-sticky {
    flex-direction: column;
    justify-content: center;
    padding: 0 1.5rem;
    gap: 2rem;
  }

  .how-content {
    max-width: 100%;
  }

  .how-visuals {
    display: none;
  }

  .glass-card {
    padding: 32px;
    border-radius: 24px;
  }

  .device-phone {
    width: 240px;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
    gap: 0.75rem;
  }

  .athlete-feature {
    flex-direction: column;
    gap: 0.75rem;
  }

  .athlete-figure svg {
    width: 100px;
    height: auto;
  }
}

@media (max-width: 480px) {
  .hero-title {
    font-size: clamp(3.5rem, 18vw, 6rem);
  }

  .stat-number {
    font-size: 3rem;
  }

  .glass-card {
    padding: 24px;
    border-radius: 20px;
  }

  .device-phone {
    width: 200px;
  }

  .section-title {
    font-size: clamp(2rem, 10vw, 3rem);
  }

  .step-heading {
    font-size: clamp(1.8rem, 8vw, 2.5rem);
  }

  .nrc-stat-value {
    font-size: 15px;
  }

