*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --accent: #818cf8;
  --accent-glow: rgba(129, 140, 248, 0.3);
  --surface: rgba(255, 255, 255, 0.04);
  --border: rgba(255, 255, 255, 0.08);
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #0a0a0a;
  color: #e2e8f0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem;
  gap: 3rem;
}

h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  background: linear-gradient(135deg, #e0e7ff 0%, #818cf8 50%, #6366f1 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  text-align: center;
}

.subtitle {
  text-align: center;
  color: rgba(148, 163, 184, 0.8);
  font-size: 1.125rem;
  margin-top: -1.5rem;
}

/* Scratch Card Container */
.scratch-card {
  position: relative;
  width: 380px;
  height: 240px;
  border-radius: 20px;
  overflow: hidden;
  cursor: crosshair;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
  box-shadow: 0 0 0 1px var(--border), 0 20px 60px -15px rgba(0, 0, 0, 0.5);
}

.scratch-card canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 2;
  border-radius: 20px;
}

.scratch-card.revealed canvas {
  opacity: 0;
  transition: opacity 0.6s ease;
  pointer-events: none;
}

/* Hidden content underneath */
.scratch-content {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  padding: 2rem;
  background: linear-gradient(135deg, #1e1b4b 0%, #312e81 50%, #3730a3 100%);
  z-index: 1;
}

.scratch-content .prize-icon {
  font-size: 3rem;
  line-height: 1;
}

.scratch-content .prize-text {
  font-size: 1.5rem;
  font-weight: 800;
  color: #e0e7ff;
  text-align: center;
}

.scratch-content .prize-sub {
  font-size: 0.9rem;
  color: rgba(196, 181, 253, 0.8);
  text-align: center;
}

.scratch-content .prize-code {
  background: rgba(255, 255, 255, 0.1);
  border: 1px dashed rgba(255, 255, 255, 0.3);
  border-radius: 8px;
  padding: 0.5rem 1.5rem;
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 1.25rem;
  font-weight: 700;
  color: #fbbf24;
  letter-spacing: 0.15em;
}

/* Overlay texture hint */
.scratch-overlay-text {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  z-index: 3;
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.3s ease;
}

.scratch-card.scratching .scratch-overlay-text {
  opacity: 0;
}

.scratch-overlay-text .hint-icon {
  font-size: 2rem;
  color: rgba(255, 255, 255, 0.5);
}

.scratch-overlay-text .hint-text {
  font-size: 0.85rem;
  color: rgba(255, 255, 255, 0.4);
  font-weight: 500;
}

/* Progress bar */
.progress-bar {
  width: 380px;
  height: 4px;
  background: var(--surface);
  border-radius: 2px;
  overflow: hidden;
  margin-top: -1.5rem;
}

.progress-bar-fill {
  height: 100%;
  background: var(--accent);
  border-radius: 2px;
  width: 0%;
  transition: width 0.1s ease;
}

.progress-label {
  width: 380px;
  display: flex;
  justify-content: space-between;
  font-size: 0.75rem;
  color: rgba(148, 163, 184, 0.5);
  margin-top: 0.25rem;
}

/* Cards row */
.cards-row {
  display: flex;
  gap: 2rem;
  flex-wrap: wrap;
  justify-content: center;
}

/* Reset button */
.reset-btn {
  background: var(--surface);
  border: 1px solid var(--border);
  color: rgba(148, 163, 184, 0.8);
  padding: 0.6rem 1.5rem;
  border-radius: 10px;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  font-family: inherit;
}

.reset-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #f1f5f9;
  border-color: rgba(255, 255, 255, 0.15);
}

