  sm: { padding: "0.625rem 1.5rem", fontSize: "0.8125rem" },
  md: { padding: "0.875rem 2rem", fontSize: "0.9375rem" },
  lg: { padding: "1.125rem 2.75rem", fontSize: "1.0625rem" },
};

export function ShinyButton({
  children,
  onClick,
  variant = "blue",
  size = "md",
  className = "",
}: ShinyButtonProps) {
  const [hovered, setHovered] = useState(false);

  const btnStyle: CSSProperties = {
    position: "relative",
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    borderRadius: "10px",
    fontWeight: 600,
    letterSpacing: "0.01em",
    cursor: "pointer",
    border: "none",
    outline: "none",
    overflow: "hidden",
    transition: "transform 0.2s ease, box-shadow 0.2s ease",
    transform: hovered ? "translateY(-2px)" : "translateY(0)",
    ...sizeStyles[size],
    ...variantStyles[variant],
  };

  const shineStyle: CSSProperties = {
    position: "absolute",
    top: 0,
    left: hovered ? "125%" : "-75%",
    width: "50%",
    height: "100%",
    background:
      "linear-gradient(120deg, transparent 0%, rgba(255,255,255,0.05) 20%, rgba(255,255,255,0.3) 45%, rgba(255,255,255,0.5) 50%, rgba(255,255,255,0.3) 55%, rgba(255,255,255,0.05) 80%, transparent 100%)",
    transition: "left 0.5s ease",
    pointerEvents: "none",
  };

  return (
    <button
      onClick={onClick}
      className={className}
      style={btnStyle}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      <span style={shineStyle} />
      <span style={{ position: "relative", zIndex: 1 }}>{children}</span>
    </button>
  );
}

