    circle,
    rgba(251, 191, 36, 0.3) 0%,
    rgba(251, 191, 36, 0.1) 30%,
    transparent 70%
  );
  filter: blur(40px);
  z-index: 2;
}

.rays-overlay {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 60% 60% at 50% 30%, transparent 20%, #0a0a0a 80%);
  pointer-events: none;
  z-index: 3;
}

.rays-content {
  position: relative;
  z-index: 10;
  text-align: center;
  color: #f1f5f9;
  pointer-events: none;
}

.rays-title {
