import { type CSSProperties, type ReactNode } from "react";

interface NeonGradientCardProps {
  children: ReactNode;
  neonSpeed?: string;
  glowSize?: number;
  borderWidth?: number;
  borderRadius?: string;
  className?: string;
}

export function NeonGradientCard({
  children,
  neonSpeed = "4s",
  glowSize = 30,
  borderWidth = 2,
  borderRadius = "1.25rem",
  className = "",
}: NeonGradientCardProps) {
  const gradientColors = "#ff0080, #ff8c00, #40e0d0, #7b68ee, #ff0080";

  const outerStyle: CSSProperties = {
    position: "relative",
    borderRadius,
    overflow: "visible",
  };

  const glowStyle: CSSProperties = {
    position: "absolute",
    inset: -borderWidth,
    borderRadius,
    background: `conic-gradient(from 0deg, ${gradientColors})`,
    animation: `neon-hue-shift ${neonSpeed} linear infinite`,
    zIndex: 0,
  };

  const outerGlowStyle: CSSProperties = {
    position: "absolute",
    inset: -glowSize,
    borderRadius: `calc(${borderRadius} + ${glowSize}px)`,
    background: `conic-gradient(from 0deg, ${gradientColors})`,
    filter: `blur(${glowSize}px)`,
    opacity: 0.4,
    animation: `neon-hue-shift ${neonSpeed} linear infinite`,
    zIndex: -1,
  };

  const contentStyle: CSSProperties = {
    position: "relative",
    zIndex: 1,
    margin: borderWidth,
    borderRadius: `calc(${borderRadius} - ${borderWidth}px)`,
    background: "#0a0a0a",
  };

  return (
    <>
      <style>{`
        @keyframes neon-hue-shift {
          0% { filter: hue-rotate(0deg); }
          100% { filter: hue-rotate(360deg); }
        }
      `}</style>
      <div style={outerStyle} className={className}>
        <div style={glowStyle}>
          <div style={outerGlowStyle} />
        </div>
        <div style={contentStyle}>{children}</div>
      </div>
    </>
  );
}

