            width: "min(400px, calc(100vw - 2rem))",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <span style={{ fontSize: "1.5rem" }}>&#x26A1;</span>
            <span
              style={{
                fontSize: "0.6875rem",
