                background: "rgba(255,0,128,0.15)",
                border: "1px solid rgba(255,0,128,0.4)",
                color: "#ff0080",
                textTransform: "uppercase",
                letterSpacing: "0.08em",
              }}
            >
              NEW
            </span>
          </div>
          <h2
            style={{
              fontSize: "1.375rem",
              fontWeight: 700,
              letterSpacing: "-0.02em",
              margin: 0,
            }}
          >
            Neon Gradient Card
          </h2>
          <p
            style={{
              fontSize: "0.9375rem",
