import { useState, useRef, useEffect } from "react";

interface VideoTextProps {
  text?: string;
  videoSrc?: string;
}

export default function VideoText({ text = "STEAL\nTHIS", videoSrc }: VideoTextProps) {
  const [useFallback, setUseFallback] = useState(!videoSrc);
  const videoRef = useRef<HTMLVideoElement>(null);

  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.play().catch(() => setUseFallback(true));
    }
  }, [videoSrc]);

  const lines = text.split("\n");

  return (
    <div
      style={{
        position: "relative",
        width: "100%",
        height: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        background: "#0a0a0a",
      }}
    >
      {/* Media layer */}
      {useFallback ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            zIndex: 1,
            background:
              "linear-gradient(135deg, #a78bfa 0%, #ec4899 25%, #f59e0b 50%, #10b981 75%, #3b82f6 100%)",
            backgroundSize: "400% 400%",
            animation: "videoTextGradient 8s ease infinite",
          }}
        />
      ) : (
        <video
          ref={videoRef}
          src={videoSrc}
          autoPlay
          loop
          muted
          playsInline
          onError={() => setUseFallback(true)}
          style={{
            position: "absolute",
            inset: 0,
            width: "100%",
            height: "100%",
            objectFit: "cover",
            zIndex: 1,
          }}
        />
      )}

