  border: 1px solid rgba(255, 255, 255, 0.04);
  margin-bottom: 1.2rem;
}

/* Generation code details */
.gen-details {
  margin-top: 0.4rem;
  margin-bottom: 1.2rem;
}
.gen-details summary {
  cursor: pointer;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--accent);
  padding: 0.4rem 0;
  user-select: none;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  list-style: none;
}
.gen-details summary::-webkit-details-marker {
  display: none;
}
.gen-details summary::before {
  content: "\25B6";
  font-size: 0.6rem;
  transition: transform 0.2s ease;
  display: inline-block;
}
.gen-details[open] summary::before {
  transform: rotate(90deg);
}
.gen-details summary:hover {
  color: var(--text);
}
.gen-code {
  background: var(--surface);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: var(--radius);
  padding: 1rem 1.2rem;
  margin-top: 0.5rem;
  overflow-x: auto;
}
.gen-code pre {
  font-family: "SF Mono", "Fira Mono", "Consolas", monospace;
  font-size: 0.75rem;
  line-height: 1.6;
  color: var(--text);
  white-space: pre-wrap;
  word-wrap: break-word;
}
.gen-code .comment {
  color: var(--muted);
}
.gen-code .key {
  color: #7dd3fc;
}
.gen-code .val {
  color: #a5f3c4;
}
.gen-code .str {
  color: #fcd34d;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(7px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

