  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

const CODE_LINES = [
  {
    text: "import { serve } from 'bun';",
    colors: ["#c586c0", "#9cdcfe", "#d4d4d4", "#ce9178"],
  },
  { text: "", colors: [] },
  {
    text: "const app = serve({",
