import {
  AbsoluteFill,
  Composition,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from "remotion";

const EVENT_NAME = "Product Launch";
const EVENT_DATE = "March 30, 2026";
const ACCENT = "#ef4444";
const TOTAL_SECONDS = 7;

const Digit: React.FC<{
  value: number;
  label: string;
  frame: number;
  fps: number;
  delay: number;
}> = ({ value, label, frame, fps, delay }) => {
  const f = Math.max(0, frame - delay);
  const scale = spring({ frame: f, fps, from: 0, to: 1, config: { damping: 12, stiffness: 100 } });
  const display = String(value).padStart(2, "0");

  // Pulse when value changes
  const pulseFrame = frame % 30;
  const pulse =
    pulseFrame < 5
      ? interpolate(pulseFrame, [0, 3, 5], [1, 1.05, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        })
      : 1;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 12,
        transform: `scale(${scale})`,
      }}
    >
      <div
        style={{
          position: "relative",
          width: 140,
          height: 140,
          borderRadius: 16,
          background: "rgba(255,255,255,0.04)",
          border: "1px solid rgba(255,255,255,0.08)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${pulse})`,
        }}
      >
        <span
          style={{
            fontFamily: "ui-monospace, monospace",
            fontWeight: 800,
            fontSize: 64,
            color: "#ffffff",
            letterSpacing: -2,
          }}
        >
          {display}
        </span>
        {/* Divider line */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: "50%",
            height: 1,
            backgroundColor: "rgba(255,255,255,0.06)",
          }}
        />
      </div>
      <span
        style={{
          fontFamily: "system-ui, sans-serif",
          fontWeight: 500,
          fontSize: 14,
          color: "rgba(255,255,255,0.4)",
          textTransform: "uppercase",
          letterSpacing: 2,
        }}
      >
        {label}
      </span>
    </div>
  );
};

const Separator: React.FC<{ frame: number; delay: number }> = ({ frame, delay }) => {
  const opacity = interpolate(Math.max(0, frame - delay), [0, 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const blink = frame % 30 < 15 ? 1 : 0.3;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 16,
        alignItems: "center",
        opacity: opacity * blink,
        paddingTop: 20,
      }}
    >
      <div style={{ width: 8, height: 8, borderRadius: "50%", backgroundColor: ACCENT }} />
      <div style={{ width: 8, height: 8, borderRadius: "50%", backgroundColor: ACCENT }} />
    </div>
  );
};

