(() => {
  const grid = document.getElementById("productGrid");
  const sortSelect = document.getElementById("sortSelect");
  const priceMin = document.getElementById("priceMin");
  const priceMax = document.getElementById("priceMax");
  const priceSlider = document.getElementById("priceSlider");
  const stockToggle = document.getElementById("stockToggle");
  const clearBtn = document.getElementById("clearFilters");
  const activeFiltersEl = document.getElementById("activeFilters");
  const showingCount = document.getElementById("showingCount");
  const productTotal = document.getElementById("productTotal");
  const pagination = document.getElementById("pagination");
  const sidebar = document.getElementById("shopSidebar");
  const mobileToggle = document.getElementById("mobileFilterToggle");
  const sidebarClose = document.getElementById("sidebarClose");

  let ratingFilter = 0;
  let currentPage = 1;

  function getCards() {
    return Array.from(grid.querySelectorAll(".product-card"));
  }

  /* ── Price Filter ──────────────────────────── */

  priceSlider.addEventListener("input", () => {
    priceMax.value = priceSlider.value;
    applyFilters();
  });

  priceMin.addEventListener("change", () => applyFilters());
  priceMax.addEventListener("change", () => {
    priceSlider.value = priceMax.value;
    applyFilters();
  });

  /* ── Brand Filter ──────────────────────────── */

  sidebar.querySelectorAll('.check-label input[type="checkbox"]').forEach((cb) => {
    cb.addEventListener("change", () => applyFilters());
  });

  /* ── Rating Filter ─────────────────────────── */

  sidebar.querySelectorAll(".star-label").forEach((label) => {
    label.addEventListener("click", () => {
      const min = parseInt(label.getAttribute("data-min"), 10);
      if (ratingFilter === min) {
        ratingFilter = 0;
        label.classList.remove("active");
      } else {
        sidebar.querySelectorAll(".star-label").forEach((l) => l.classList.remove("active"));
        ratingFilter = min;
        label.classList.add("active");
      }
      applyFilters();
    });
  });

  /* ── Stock Toggle ──────────────────────────── */

  stockToggle.addEventListener("click", () => {
    const current = stockToggle.getAttribute("aria-checked") === "true";
    stockToggle.setAttribute("aria-checked", !current);
    applyFilters();
  });

  /* ── Sort ───────────────────────────────────── */

  sortSelect.addEventListener("change", () => applyFilters());

  /* ── View Toggle ───────────────────────────── */

  document.querySelectorAll(".view-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      document.querySelectorAll(".view-btn").forEach((b) => b.classList.remove("active"));
      btn.classList.add("active");
      const view = btn.getAttribute("data-view");
      grid.classList.toggle("list-view", view === "list");
    });
  });

  /* ── Collapsible Sections ──────────────────── */

  sidebar.querySelectorAll(".filter-heading").forEach((heading) => {
    heading.addEventListener("click", () => {
      heading.closest(".filter-section").classList.toggle("collapsed");
    });
  });

  /* ── Clear All ─────────────────────────────── */

  clearBtn.addEventListener("click", () => {
    priceMin.value = 0;
    priceMax.value = 500;
    priceSlider.value = 500;
    sidebar.querySelectorAll('.check-label input[type="checkbox"]').forEach((cb) => {
      cb.checked = false;
    });
    ratingFilter = 0;
    sidebar.querySelectorAll(".star-label").forEach((l) => l.classList.remove("active"));
    stockToggle.setAttribute("aria-checked", "false");
    sortSelect.value = "featured";
    applyFilters();
  });

  /* ── Mobile Sidebar ────────────────────────── */

  mobileToggle.addEventListener("click", () => {
    sidebar.classList.add("open");
    document.body.style.overflow = "hidden";
  });

  sidebarClose.addEventListener("click", () => {
    sidebar.classList.remove("open");
    document.body.style.overflow = "";
  });

  /* ── Apply Filters ─────────────────────────── */

  function applyFilters() {
    const cards = getCards();
    const minPrice = parseInt(priceMin.value, 10) || 0;
    const maxPrice = parseInt(priceMax.value, 10) || 500;
    const stockOnly = stockToggle.getAttribute("aria-checked") === "true";

    const selectedBrands = Array.from(sidebar.querySelectorAll(".check-label input:checked")).map(
      (cb) => cb.value
    );

    let visibleCount = 0;

    cards.forEach((card) => {
      const price = parseInt(card.getAttribute("data-price"), 10);
      const brand = card.getAttribute("data-brand");
      const rating = parseFloat(card.getAttribute("data-rating"));
      const inStock = card.getAttribute("data-stock") === "true";

      let show = true;

      if (price < minPrice || price > maxPrice) show = false;
      if (selectedBrands.length > 0 && !selectedBrands.includes(brand)) show = false;
      if (ratingFilter > 0 && rating < ratingFilter) show = false;
      if (stockOnly && !inStock) show = false;

      card.style.display = show ? "" : "none";
      if (show) visibleCount++;
    });

    /* Sort visible cards */
    sortCards();

    /* Update counts */
    showingCount.textContent = `Showing ${visibleCount} of 48 products`;
    productTotal.textContent = `${visibleCount} products`;

    /* Update active filter pills */
    updateFilterPills(minPrice, maxPrice, selectedBrands, stockOnly);
  }

  function sortCards() {
    const val = sortSelect.value;
    const cards = getCards();

    cards.sort((a, b) => {
      const pa = parseInt(a.getAttribute("data-price"), 10);
      const pb = parseInt(b.getAttribute("data-price"), 10);
      const ra = parseFloat(a.getAttribute("data-rating"));
      const rb = parseFloat(b.getAttribute("data-rating"));
      const da = new Date(a.getAttribute("data-date"));
      const db = new Date(b.getAttribute("data-date"));

      switch (val) {
        case "price-asc":
          return pa - pb;
        case "price-desc":
          return pb - pa;
        case "newest":
          return db - da;
        case "rating":
          return rb - ra;
        default:
          return 0;
      }
    });

    cards.forEach((card) => grid.appendChild(card));
  }

  /* ── Active Filter Pills ───────────────────── */

  function updateFilterPills(minPrice, maxPrice, brands, stockOnly) {
    activeFiltersEl.innerHTML = "";

    if (minPrice > 0 || maxPrice < 500) {
      addPill(`$${minPrice} – $${maxPrice}`, () => {
        priceMin.value = 0;
        priceMax.value = 500;
        priceSlider.value = 500;
        applyFilters();
      });
    }

    brands.forEach((brand) => {
      addPill(capitalize(brand), () => {
        const cb = sidebar.querySelector(`.check-label input[value="${brand}"]`);
        if (cb) cb.checked = false;
        applyFilters();
      });
    });

    if (ratingFilter > 0) {
      addPill(`${ratingFilter}★ & up`, () => {
        ratingFilter = 0;
        sidebar.querySelectorAll(".star-label").forEach((l) => l.classList.remove("active"));
        applyFilters();
      });
    }

    if (stockOnly) {
      addPill("In Stock", () => {
        stockToggle.setAttribute("aria-checked", "false");
        applyFilters();
      });
    }
  }

  function addPill(text, onRemove) {
    const pill = document.createElement("span");
    pill.className = "filter-pill";
    pill.innerHTML = `${escapeHtml(text)} <button aria-label="Remove">&times;</button>`;
    pill.querySelector("button").addEventListener("click", onRemove);
    activeFiltersEl.appendChild(pill);
  }

  function capitalize(str) {
    return str.charAt(0).toUpperCase() + str.slice(1);
  }

  function escapeHtml(str) {
    const div = document.createElement("div");
    div.textContent = str;
    return div.innerHTML;
  }

  /* ── Pagination ────────────────────────────── */

  pagination.addEventListener("click", (e) => {
    const btn = e.target.closest(".page-btn");
    if (!btn || btn.disabled) return;

    if (btn.classList.contains("prev")) {
      if (currentPage > 1) currentPage--;
    } else if (btn.classList.contains("next")) {
      currentPage++;
    } else {
      currentPage = parseInt(btn.getAttribute("data-page"), 10);
    }

    pagination.querySelectorAll(".page-btn[data-page]").forEach((p) => {
      p.classList.toggle("active", parseInt(p.getAttribute("data-page"), 10) === currentPage);
    });

    pagination.querySelector(".prev").disabled = currentPage <= 1;
    pagination.querySelector(".next").disabled = currentPage >= 4;

    window.scrollTo({ top: 0, behavior: "smooth" });
  });

  /* ── Render Stars ──────────────────────────── */

  document.querySelectorAll(".stars-display").forEach((el) => {
    const rating = parseFloat(el.getAttribute("data-rating"));
    const full = Math.floor(rating);
    const half = rating % 1 >= 0.5 ? 1 : 0;
    const empty = 5 - full - half;
    el.textContent =
      "\u2605".repeat(full) + (half ? "\u2605" : "") + "\u2606".repeat(empty - (half ? 0 : 0));
    /* Re-render with proper full/empty */
    let stars = "";
    for (let i = 0; i < full; i++) stars += "\u2605";
    for (let i = 0; i < 5 - full; i++) stars += "\u2606";
    el.textContent = stars;
  });

  /* ── Init ──────────────────────────────────── */
  applyFilters();
})();

snippets.css:
/* ===== Reset & Base ===== */
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --sidebar-width: 260px;
  --sidebar-collapsed: 72px;
  --topbar-height: 64px;
  --bg: #f1f5f9;
  --surface: #ffffff;
  --sidebar-bg: #1e293b;
  --sidebar-text: #94a3b8;
  --sidebar-active: #6366f1;
  --text-primary: #0f172a;
  --text-secondary: #64748b;
  --border: #e2e8f0;
  --green: #22c55e;
  --red: #ef4444;
  --yellow: #f59e0b;
  --radius: 12px;
  --shadow: 0 1px 3px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.06), 0 2px 4px rgba(0, 0, 0, 0.04);
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial,
    sans-serif;
  background: var(--bg);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
}

/* ===== Sidebar ===== */
.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: var(--sidebar-width);
  background: var(--sidebar-bg);
  color: var(--sidebar-text);
  z-index: 100;
  display: flex;
  flex-direction: column;
  transition: width 0.25s ease, transform 0.25s ease;
  overflow: hidden;
}

.sidebar-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px 20px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.sidebar-logo-icon {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  color: var(--sidebar-active);
}

.sidebar-logo-text {
  font-size: 1.125rem;
  font-weight: 700;
  color: #ffffff;
  white-space: nowrap;
  overflow: hidden;
  transition: opacity 0.2s ease;
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 16px 12px;
  flex: 1;
}

.sidebar-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 8px;
  color: var(--sidebar-text);
  text-decoration: none;
  font-size: 0.9rem;
  font-weight: 500;
  transition: background 0.15s ease, color 0.15s ease;
  white-space: nowrap;
}

.sidebar-link svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

.sidebar-link:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #e2e8f0;
}

.sidebar-link.active {
  background: var(--sidebar-active);
  color: #ffffff;
}

/* Collapsed sidebar */
.sidebar.collapsed {
  width: var(--sidebar-collapsed);
}

.sidebar.collapsed .sidebar-logo-text,
.sidebar.collapsed .link-label {
  opacity: 0;
  pointer-events: none;
}

.sidebar.collapsed .sidebar-link {
  justify-content: center;
  padding: 10px;
}

.sidebar.collapsed .sidebar-header {
  justify-content: center;
  padding: 20px 12px 16px;
}

/* ===== Sidebar overlay (mobile) ===== */
.sidebar-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 99;
}

.sidebar-overlay.visible {
  display: block;
}

/* ===== Main wrapper ===== */
.main-wrapper {
  margin-left: var(--sidebar-width);
  min-height: 100vh;
  transition: margin-left 0.25s ease;
}

.sidebar.collapsed ~ .main-wrapper {
  margin-left: var(--sidebar-collapsed);
}

/* ===== Top bar ===== */
.topbar {
  position: sticky;
  top: 0;
  height: var(--topbar-height);
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 24px;
  z-index: 50;
}

.hamburger {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 6px;
  color: var(--text-primary);
}

.hamburger svg {
  width: 24px;
  height: 24px;
}

.sidebar-collapse-btn {
  background: none;
  border: 1px solid var(--border);
  border-radius: 6px;
  cursor: pointer;
  padding: 6px;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease;
}

.sidebar-collapse-btn:hover {
  background: var(--bg);
}

.sidebar-collapse-btn svg {
  width: 18px;
  height: 18px;
  transition: transform 0.25s ease;
}

.sidebar.collapsed ~ .main-wrapper .sidebar-collapse-btn svg {
  transform: rotate(180deg);
}

.topbar-search {
  position: relative;
  flex: 1;
  max-width: 400px;
}

.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  color: var(--text-secondary);
  pointer-events: none;
}

.search-input {
  width: 100%;
  padding: 8px 12px 8px 40px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.875rem;
  background: var(--bg);
  color: var(--text-primary);
  outline: none;
  transition: border-color 0.15s ease;
}

.search-input:focus {
  border-color: var(--sidebar-active);
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-left: auto;
}

.topbar-icon-btn {
  position: relative;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  color: var(--text-secondary);
  border-radius: 8px;
  transition: background 0.15s ease;
}

.topbar-icon-btn:hover {
  background: var(--bg);
}

.topbar-icon-btn svg {
  width: 20px;
  height: 20px;
}

.notification-dot {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 8px;
  height: 8px;
  background: var(--red);
  border-radius: 50%;
  border: 2px solid var(--surface);
}

.avatar-circle {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--sidebar-active);
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 600;
}

/* ===== Content area ===== */
.content {
  padding: 24px;
  max-width: 1400px;
}

.content-header {
  margin-bottom: 24px;
}

.content-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
}

.content-subtitle {
  color: var(--text-secondary);
  font-size: 0.9rem;
  margin-top: 4px;
}

/* ===== KPI Cards ===== */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 24px;
}

.kpi-card {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: var(--shadow);
}

.kpi-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
}

.kpi-label {
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.kpi-trend {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.8rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 20px;
}

.kpi-trend svg {
  width: 14px;
  height: 14px;
}

.kpi-trend.up {
  color: var(--green);
  background: rgba(34, 197, 94, 0.1);
}

.kpi-trend.down {
  color: var(--red);
  background: rgba(239, 68, 68, 0.1);
}

.kpi-value {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 4px;
}

.kpi-footer {
  font-size: 0.78rem;
  color: var(--text-secondary);
}

/* ===== Chart cards ===== */
.charts-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-bottom: 24px;
}

.chart-card,
.activity-card,
.table-card {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: var(--shadow);
}

.chart-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.chart-card-header h3 {
  font-size: 1rem;
  font-weight: 600;
}

.chart-period {
  font-size: 0.8rem;
  color: var(--text-secondary);
}

.chart-card canvas {
  width: 100%;
  height: auto;
  display: block;
}

.chart-card-small {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.chart-card-small .chart-card-header {
  width: 100%;
}

.chart-card-small canvas {
  max-width: 220px;
  max-height: 220px;
}

/* Donut legend */
.donut-legend {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 16px;
  justify-content: center;
}

.donut-legend li {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8rem;
  color: var(--text-secondary);
}

.donut-legend .legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

/* ===== Activity feed ===== */
.activity-feed {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.activity-item {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.activity-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  font-size: 0.8rem;
  font-weight: 600;
  flex-shrink: 0;
}

.activity-body p {
  font-size: 0.85rem;
  color: var(--text-primary);
  line-height: 1.4;
}

.activity-time {
  font-size: 0.75rem;
  color: var(--text-secondary);
}

/* ===== Data table ===== */
.table-card {
  margin-bottom: 24px;
}

.table-wrapper {
  overflow-x: auto;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
}

.data-table th {
  text-align: left;
  padding: 12px 16px;
  font-weight: 600;
  color: var(--text-secondary);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-bottom: 2px solid var(--border);
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
}

.data-table th:hover {
  color: var(--text-primary);
}

.data-table th::after {
  content: "";
  display: inline-block;
  margin-left: 6px;
  width: 0;
  height: 0;
  vertical-align: middle;
}

.data-table th.sort-asc::after {
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-bottom: 5px solid var(--sidebar-active);
}

.data-table th.sort-desc::after {
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-top: 5px solid var(--sidebar-active);
}

.data-table td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  color: var(--text-primary);
}

.data-table tbody tr:nth-child(even) {
  background: rgba(241, 245, 249, 0.5);
}

.data-table tbody tr:hover {
  background: rgba(99, 102, 241, 0.04);
}

/* Status badges */
.badge {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: capitalize;
}

.badge-completed {
  background: rgba(34, 197, 94, 0.1);
  color: var(--green);
}

.badge-pending {
  background: rgba(245, 158, 11, 0.1);
  color: var(--yellow);
}

.badge-cancelled {
  background: rgba(239, 68, 68, 0.1);
  color: var(--red);
}

/* ===== Canvas tooltip ===== */
.chart-tooltip {
  position: fixed;
  padding: 6px 12px;
  background: var(--sidebar-bg);
  color: #ffffff;
  font-size: 0.78rem;
  border-radius: 6px;
  pointer-events: none;
  z-index: 200;
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.15s ease;
}

.chart-tooltip.visible {
  opacity: 1;
}

/* ===== Responsive ===== */
@media (max-width: 1200px) {
  .kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 1024px) {
  .sidebar {
    width: var(--sidebar-collapsed);
  }

  .sidebar .sidebar-logo-text,
  .sidebar .link-label {
    opacity: 0;
    pointer-events: none;
  }

  .sidebar .sidebar-link {
    justify-content: center;
    padding: 10px;
  }

  .sidebar .sidebar-header {
    justify-content: center;
    padding: 20px 12px 16px;
  }

  .main-wrapper {
    margin-left: var(--sidebar-collapsed);
  }

  .sidebar-collapse-btn {
    display: none;
  }

  .charts-row {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .sidebar {
    width: var(--sidebar-width);
    transform: translateX(-100%);
  }

  .sidebar.open {
    transform: translateX(0);
  }

  .sidebar.open .sidebar-logo-text,
  .sidebar.open .link-label {
    opacity: 1;
    pointer-events: auto;
  }

  .sidebar.open .sidebar-link {
    justify-content: flex-start;
    padding: 10px 12px;
  }

  .sidebar.open .sidebar-header {
    justify-content: flex-start;
    padding: 20px 20px 16px;
  }

  .main-wrapper {
    margin-left: 0;
  }

  .hamburger {
    display: flex;
  }

  .sidebar-collapse-btn {
    display: none;
  }

  .kpi-grid {
    grid-template-columns: 1fr;
  }

  .content {
    padding: 16px;
  }

  .topbar {
    padding: 0 16px;
  }
}

