*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial,
    sans-serif;
  background: #f8fafc;
  color: #1e293b;
  line-height: 1.6;
  min-height: 100vh;
}

.team-page {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px 80px;
}

/* Hero */
.team-hero {
  text-align: center;
  padding: 64px 0 24px;
}

.team-hero h1 {
  font-size: 2.75rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: #0f172a;
}

.team-subtitle {
  font-size: 1.125rem;
  color: #64748b;
  margin-top: 8px;
}

/* Stats */
.team-stats {
  text-align: center;
  padding: 16px 0 32px;
}

.stats-text {
  font-size: 0.9375rem;
  color: #94a3b8;
}

.stats-text strong {
  color: #475569;
}

.member-count {
  font-variant-numeric: tabular-nums;
}

/* Department Filters */
.department-filters {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 40px;
}

.dept-tab {
  padding: 8px 20px;
  border-radius: 9999px;
  border: 1.5px solid #e2e8f0;
  background: #fff;
  color: #64748b;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
}

.dept-tab:hover {
  border-color: #94a3b8;
  color: #334155;
}

.dept-tab.active {
  background: #0f172a;
  border-color: #0f172a;
  color: #fff;
}

.dept-count {
  opacity: 0.7;
  margin-left: 2px;
}

/* Team Grid */
.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
}

/* Team Card */
.team-card {
  background: #fff;
  border-radius: 16px;
  border: 1px solid #e2e8f0;
  padding: 32px 24px 28px;
  text-align: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  position: relative;
}

.team-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.08);
}

.team-card.card-hidden {
  display: none;
}

.team-card.card-fade-in {
  animation: cardFadeIn 0.3s ease forwards;
}

@keyframes cardFadeIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Avatar */
.avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.initials {
  color: #fff;
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  user-select: none;
}

/* Name & Role */
.member-name {
  font-size: 1.0625rem;
  font-weight: 700;
  color: #0f172a;
  margin-bottom: 2px;
}

.member-role {
  font-size: 0.8125rem;
  color: #94a3b8;
  font-weight: 500;
  margin-bottom: 12px;
}

/* Bio */
.member-bio {
  font-size: 0.8125rem;
  color: #64748b;
  line-height: 1.6;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 16px;
}

/* Social Links */
.social-links {
  display: flex;
  gap: 12px;
  justify-content: center;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.team-card:hover .social-links {
  opacity: 1;
  transform: translateY(0);
}

.social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  color: #94a3b8;
  transition: color 0.15s ease, background 0.15s ease;
}

.social-link:hover {
  color: #1e293b;
  background: #f1f5f9;
}

/* Responsive */
@media (max-width: 1024px) {
  .team-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .team-hero h1 {
    font-size: 2rem;
  }

  .team-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
  }

  .team-card {
    padding: 24px 18px 22px;
  }

  .social-links {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 480px) {
  .team-page {
    padding: 0 16px 60px;
  }

  .team-hero {
    padding: 40px 0 16px;
  }

  .team-grid {
    grid-template-columns: 1fr;
  }
}

