(function () {
  "use strict";

  /* ── State ── */
  const fileSystem = {
    "My Files": {
      type: "folder",
      children: {
        Documents: {
          type: "folder",
          children: {
            Projects: { type: "folder", children: {} },
            Reports: { type: "folder", children: {} },
          },
        },
        Images: { type: "folder", children: {} },
        Videos: { type: "folder", children: {} },
      },
    },
    "Shared with me": { type: "folder", children: {} },
    Starred: { type: "folder", children: {} },
    Trash: { type: "folder", children: {} },
  };

  let currentPath = ["My Files", "Documents"];
  let currentView = "grid";
  let selectedItems = new Set();
  let contextTarget = null;
  let lastClickedIndex = -1;

  /* ── DOM refs ── */
  const content = document.getElementById("fm-content");
  const contextMenu = document.getElementById("fm-context-menu");
  const uploadOverlay = document.getElementById("fm-upload-overlay");
  const fileInput = document.getElementById("fm-file-input");
  const renameModal = document.getElementById("fm-rename-modal");
  const renameInput = document.getElementById("fm-rename-input");
  const selectAllCheck = document.querySelector(".fm-select-all-check");
  const itemCountEl = document.querySelector(".fm-item-count");
  const sortSelect = document.getElementById("fm-sort-select");
  const breadcrumbEl = document.querySelector(".fm-breadcrumb");
  const sidebar = document.querySelector(".fm-sidebar");
  const sidebarToggle = document.querySelector(".fm-sidebar-toggle");

  /* ── View Toggle ── */
  document.querySelectorAll(".fm-view-btn").forEach(function (btn) {
    btn.addEventListener("click", function () {
      document.querySelectorAll(".fm-view-btn").forEach(function (b) {
        b.classList.remove("active");
      });
      btn.classList.add("active");
      currentView = btn.dataset.view;
      content.classList.remove("fm-grid", "fm-list");
      content.classList.add(currentView === "grid" ? "fm-grid" : "fm-list");
    });
  });

  /* ── Sidebar Toggle (Mobile) ── */
  sidebarToggle.addEventListener("click", function () {
    sidebar.classList.toggle("open");
  });

  /* ── Folder Tree ── */
  document.querySelectorAll(".fm-tree-item").forEach(function (item) {
    var row = item.querySelector(":scope > .fm-tree-row");
    var arrow = row.querySelector(".fm-tree-arrow");
    var children = item.querySelector(":scope > .fm-tree-list");

    row.addEventListener("click", function (e) {
      e.stopPropagation();

      // Toggle expand/collapse if has children
      if (arrow && children) {
        if (e.target.closest(".fm-tree-arrow")) {
          arrow.classList.toggle("expanded");
          item.classList.toggle("collapsed");
          return;
        }
        // Clicking the row also expands
        if (item.classList.contains("collapsed")) {
          arrow.classList.add("expanded");
          item.classList.remove("collapsed");
        }
      }

      // Navigate to folder
      var path = item.dataset.path;
      if (path) {
        currentPath = path.split("/");
        updateBreadcrumb();
        updateTreeActive(path);
        sidebar.classList.remove("open");
      }
    });
  });

  function updateTreeActive(path) {
    document.querySelectorAll(".fm-tree-row").forEach(function (r) {
      r.classList.remove("active");
    });
    var target = document.querySelector('.fm-tree-item[data-path="' + path + '"] > .fm-tree-row');
    if (target) target.classList.add("active");
  }

  /* ── Breadcrumb ── */
  function updateBreadcrumb() {
    breadcrumbEl.innerHTML = "";
    currentPath.forEach(function (segment, i) {
      if (i > 0) {
        var sep = document.createElement("span");
        sep.className = "fm-breadcrumb-sep";
        sep.innerHTML =
          '<svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2"><polyline points="4,2 8,6 4,10"/></svg>';
        breadcrumbEl.appendChild(sep);
      }
      var isLast = i === currentPath.length - 1;
      var el = document.createElement(isLast ? "span" : "button");
      el.className = "fm-breadcrumb-item" + (isLast ? " current" : "");
      el.textContent = segment;
      if (!isLast) {
        el.dataset.path = currentPath.slice(0, i + 1).join("/");
        el.addEventListener("click", function () {
          currentPath = this.dataset.path.split("/");
          updateBreadcrumb();
          updateTreeActive(currentPath.join("/"));
        });
      }
      breadcrumbEl.appendChild(el);
    });
  }

  /* ── Selection ── */
  function getItems() {
    return Array.from(content.querySelectorAll(".fm-item"));
  }

  content.addEventListener("click", function (e) {
    var item = e.target.closest(".fm-item");
    if (!item) return;

    // Ignore checkbox direct clicks — handled below
    if (e.target.tagName === "INPUT") return;

    var items = getItems();
    var index = items.indexOf(item);

    if (e.shiftKey && lastClickedIndex >= 0) {
      var start = Math.min(lastClickedIndex, index);
      var end = Math.max(lastClickedIndex, index);
      for (var i = start; i <= end; i++) {
        selectItem(items[i], true);
      }
    } else if (e.ctrlKey || e.metaKey) {
      toggleSelect(item);
    } else {
      clearSelection();
      selectItem(item, true);
    }
    lastClickedIndex = index;
    syncSelectAll();
  });

  content.addEventListener("change", function (e) {
    if (e.target.type === "checkbox") {
      var item = e.target.closest(".fm-item");
      if (item) {
        selectItem(item, e.target.checked);
        syncSelectAll();
      }
    }
  });

  selectAllCheck.addEventListener("change", function () {
    var items = getItems();
    var checked = selectAllCheck.checked;
    items.forEach(function (item) {
      selectItem(item, checked);
    });
  });

  function selectItem(item, selected) {
    var name = item.dataset.name;
    var check = item.querySelector('input[type="checkbox"]');
    if (selected) {
      item.classList.add("selected");
      selectedItems.add(name);
      if (check) check.checked = true;
    } else {
      item.classList.remove("selected");
      selectedItems.delete(name);
      if (check) check.checked = false;
    }
  }

  function toggleSelect(item) {
    selectItem(item, !item.classList.contains("selected"));
  }

  function clearSelection() {
    getItems().forEach(function (item) {
      selectItem(item, false);
    });
    selectedItems.clear();
  }

  function syncSelectAll() {
    var items = getItems();
    var allChecked =
      items.length > 0 &&
      items.every(function (i) {
        return i.classList.contains("selected");
      });
    selectAllCheck.checked = allChecked;
    selectAllCheck.indeterminate = !allChecked && selectedItems.size > 0;
    itemCountEl.textContent =
      selectedItems.size > 0 ? selectedItems.size + " selected" : items.length + " items";
  }

  /* ── Double-click folder ── */
  content.addEventListener("dblclick", function (e) {
    var item = e.target.closest(".fm-item");
    if (!item || item.dataset.type !== "folder") return;
    currentPath.push(item.dataset.name);
    updateBreadcrumb();
    updateTreeActive(currentPath.join("/"));
  });

  /* ── Context Menu ── */
  content.addEventListener("contextmenu", function (e) {
    var item = e.target.closest(".fm-item");
    if (!item) return;
    e.preventDefault();
    contextTarget = item;

    // Position
    var x = e.clientX;
    var y = e.clientY;
    contextMenu.style.left = x + "px";
    contextMenu.style.top = y + "px";
    contextMenu.classList.add("visible");

    // Adjust if off-screen
    requestAnimationFrame(function () {
      var rect = contextMenu.getBoundingClientRect();
      if (rect.right > window.innerWidth) {
        contextMenu.style.left = x - rect.width + "px";
      }
      if (rect.bottom > window.innerHeight) {
        contextMenu.style.top = y - rect.height + "px";
      }
    });
  });

  document.addEventListener("click", function () {
    contextMenu.classList.remove("visible");
  });

  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") {
      contextMenu.classList.remove("visible");
      renameModal.classList.remove("visible");
    }
  });

  contextMenu.addEventListener("click", function (e) {
    var btn = e.target.closest(".fm-context-item");
    if (!btn || !contextTarget) return;
    var action = btn.dataset.action;

    switch (action) {
      case "open":
        if (contextTarget.dataset.type === "folder") {
          currentPath.push(contextTarget.dataset.name);
          updateBreadcrumb();
          updateTreeActive(currentPath.join("/"));
        }
        break;

      case "rename":
        renameInput.value = contextTarget.dataset.name;
        renameModal.classList.add("visible");
        setTimeout(function () {
          renameInput.focus();
          var dotIndex = renameInput.value.lastIndexOf(".");
          renameInput.setSelectionRange(0, dotIndex > 0 ? dotIndex : renameInput.value.length);
        }, 50);
        break;

      case "delete":
        if (confirm('Delete "' + contextTarget.dataset.name + '"?')) {
          contextTarget.classList.add("removing");
          var target = contextTarget;
          setTimeout(function () {
            target.remove();
            syncSelectAll();
          }, 250);
        }
        break;

      case "download":
        // Simulate download
        var link = document.createElement("a");
        link.href = "#";
        link.download = contextTarget.dataset.name;
        break;

      case "copy":
      case "move":
        // Visual feedback only
        break;
    }
    contextMenu.classList.remove("visible");
  });

  /* ── Rename Modal ── */
  renameModal.querySelector(".fm-modal-cancel").addEventListener("click", function () {
    renameModal.classList.remove("visible");
  });

  renameModal.querySelector(".fm-modal-confirm").addEventListener("click", doRename);
  renameInput.addEventListener("keydown", function (e) {
    if (e.key === "Enter") doRename();
  });

  function doRename() {
    var newName = renameInput.value.trim();
    if (!newName || !contextTarget) return;
    contextTarget.dataset.name = newName;
    contextTarget.querySelector(".fm-item-name").textContent = newName;
    renameModal.classList.remove("visible");
  }

  renameModal.addEventListener("click", function (e) {
    if (e.target === renameModal) renameModal.classList.remove("visible");
  });

  /* ── Upload Drag & Drop ── */
  var dragCounter = 0;

  document.addEventListener("dragenter", function (e) {
    e.preventDefault();
    dragCounter++;
    if (dragCounter === 1) uploadOverlay.classList.add("visible");
  });

  document.addEventListener("dragleave", function (e) {
    e.preventDefault();
    dragCounter--;
    if (dragCounter <= 0) {
      dragCounter = 0;
      uploadOverlay.classList.remove("visible");
    }
  });

  document.addEventListener("dragover", function (e) {
    e.preventDefault();
  });

  document.addEventListener("drop", function (e) {
    e.preventDefault();
    dragCounter = 0;
    uploadOverlay.classList.remove("visible");
    // Files would be in e.dataTransfer.files
  });

  /* ── Upload Button ── */
  document.querySelector(".fm-upload-btn").addEventListener("click", function () {
    fileInput.click();
  });

  fileInput.addEventListener("change", function () {
    // Files added — no-op for demo
    fileInput.value = "";
  });

  /* ── New Folder ── */
  document.querySelector(".fm-new-folder-btn").addEventListener("click", function () {
    var name = prompt("New folder name:");
    if (!name || !name.trim()) return;
    name = name.trim();

    var html =
      '<div class="fm-item-check"><input type="checkbox" /></div>' +
      '<div class="fm-item-icon fm-icon-folder">' +
      '<svg width="48" height="48" viewBox="0 0 48 48" fill="#3b82f6"><path d="M4 12h16l4-4h20v32H4z"/></svg>' +
      "</div>" +
      '<div class="fm-item-info">' +
      '<span class="fm-item-name">' +
      name +
      "</span>" +
      '<span class="fm-item-meta">0 items</span>' +
      "</div>" +
      '<span class="fm-item-size">\u2014</span>' +
      '<span class="fm-item-date">Just now</span>' +
      '<span class="fm-item-type-col">Folder</span>';

    var el = document.createElement("div");
    el.className = "fm-item";
    el.dataset.name = name;
    el.dataset.type = "folder";
    el.dataset.size = "0";
    el.dataset.date = new Date().toISOString().slice(0, 10);
    el.dataset.items = "0 items";
    el.innerHTML = html;

    // Insert before first non-folder or at end
    var items = getItems();
    var firstFile = items.find(function (i) {
      return i.dataset.type !== "folder";
    });
    if (firstFile) {
      content.insertBefore(el, firstFile);
    } else {
      content.appendChild(el);
    }
    syncSelectAll();
  });

  /* ── Sort ── */
  sortSelect.addEventListener("change", function () {
    var key = sortSelect.value;
    var items = getItems();
    var folders = items.filter(function (i) {
      return i.dataset.type === "folder";
    });
    var files = items.filter(function (i) {
      return i.dataset.type !== "folder";
    });

    var comparator;
    switch (key) {
      case "name":
        comparator = function (a, b) {
          return a.dataset.name.localeCompare(b.dataset.name);
        };
        break;
      case "size":
        comparator = function (a, b) {
          return parseInt(a.dataset.size || "0") - parseInt(b.dataset.size || "0");
        };
        break;
      case "date":
        comparator = function (a, b) {
          return (b.dataset.date || "").localeCompare(a.dataset.date || "");
        };
        break;
      case "type":
        comparator = function (a, b) {
          return (a.dataset.type || "").localeCompare(b.dataset.type || "");
        };
        break;
      default:
        comparator = function () {
          return 0;
        };
    }

    folders.sort(comparator);
    files.sort(comparator);

    folders.concat(files).forEach(function (item) {
      content.appendChild(item);
    });
  });

  /* ── Search ── */
  document.querySelector(".fm-search-input").addEventListener("input", function (e) {
    var query = e.target.value.toLowerCase();
    getItems().forEach(function (item) {
      var name = (item.dataset.name || "").toLowerCase();
      item.style.display = name.includes(query) ? "" : "none";
    });
  });
})();

snippets.css:
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --ob-primary: #6366f1;
  --ob-primary-dark: #4f46e5;
  --ob-primary-light: #eef2ff;
  --ob-green: #22c55e;
  --ob-green-light: #dcfce7;
  --ob-gray-50: #f9fafb;
  --ob-gray-100: #f3f4f6;
  --ob-gray-200: #e5e7eb;
  --ob-gray-300: #d1d5db;
  --ob-gray-400: #9ca3af;
  --ob-gray-500: #6b7280;
  --ob-gray-600: #4b5563;
  --ob-gray-700: #374151;
  --ob-gray-800: #1f2937;
  --ob-gray-900: #111827;
  --ob-red: #ef4444;
  --ob-radius: 8px;
  --ob-radius-lg: 16px;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial,
    sans-serif;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #eef2ff 0%, #e0e7ff 30%, #dbeafe 60%, #ede9fe 100%);
  padding: 24px;
  line-height: 1.5;
  color: var(--ob-gray-800);
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font: inherit;
  color: inherit;
}

input,
select {
  font: inherit;
}

/* Card */
.ob-card {
  width: 100%;
  max-width: 640px;
  background: #fff;
  border-radius: var(--ob-radius-lg);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.08), 0 4px 16px rgba(0, 0, 0, 0.04);
  padding: 48px;
  position: relative;
  overflow: hidden;
}

/* Progress Steps */
.ob-progress {
  margin-bottom: 40px;
}

.ob-step-row {
  display: flex;
  align-items: flex-start;
  justify-content: center;
}

.ob-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  position: relative;
  z-index: 1;
}

.ob-step-circle {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  border: 2px solid var(--ob-gray-300);
  color: var(--ob-gray-400);
  background: #fff;
  transition: all .3s ease;
}

.ob-step.active .ob-step-circle {
  border-color: var(--ob-primary);
  background: var(--ob-primary);
  color: #fff;
}

.ob-step.completed .ob-step-circle {
  border-color: var(--ob-green);
  background: var(--ob-green);
  color: #fff;
}

.ob-step-label {
  font-size: 12px;
  font-weight: 500;
  color: var(--ob-gray-400);
  white-space: nowrap;
  transition: color .3s;
}

.ob-step.active .ob-step-label {
  color: var(--ob-primary);
}

.ob-step.completed .ob-step-label {
  color: var(--ob-green);
}

.ob-step-line {
  flex: 1;
  height: 2px;
  background: var(--ob-gray-200);
  margin-top: 18px;
  min-width: 32px;
  position: relative;
  overflow: hidden;
}

.ob-step-line-fill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 0%;
  background: var(--ob-green);
  transition: width .4s ease;
}

.ob-step-line.filled .ob-step-line-fill {
  width: 100%;
}

/* Panels */
.ob-panel {
  display: none;
}

.ob-panel.active {
  display: block;
  animation: obFadeIn .35s ease;
}

@keyframes obFadeIn {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Headings */
.ob-heading {
  font-size: 22px;
  font-weight: 700;
  color: var(--ob-gray-900);
  margin-bottom: 8px;
  text-align: center;
}

.ob-subtext {
  font-size: 14px;
  color: var(--ob-gray-500);
  text-align: center;
  margin-bottom: 32px;
}

/* Avatar */
.ob-avatar-wrap {
  display: flex;
  justify-content: center;
  margin-bottom: 28px;
}

.ob-avatar {
  width: 96px;
  height: 96px;
  border-radius: 50%;
  border: 2px dashed var(--ob-gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  overflow: hidden;
  position: relative;
  transition: border-color .2s, background .2s;
}

.ob-avatar:hover {
  border-color: var(--ob-primary);
  background: var(--ob-primary-light);
}

.ob-avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: none;
}

.ob-avatar-img.visible {
  display: block;
}

.ob-avatar-img.visible + .ob-avatar-placeholder {
  display: none;
}

.ob-avatar-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  color: var(--ob-gray-400);
  font-size: 11px;
  pointer-events: none;
}

/* Form Fields */
.ob-field {
  margin-bottom: 20px;
}

.ob-label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--ob-gray-700);
  margin-bottom: 6px;
}

.ob-required {
  color: var(--ob-red);
}

.ob-optional {
  color: var(--ob-gray-400);
  font-weight: 400;
}

.ob-input {
  width: 100%;
  padding: 10px 14px;
  border: 1px solid var(--ob-gray-300);
  border-radius: var(--ob-radius);
  font-size: 14px;
  color: var(--ob-gray-800);
  outline: none;
  transition: border-color .15s, box-shadow .15s;
  background: #fff;
}

.ob-input:focus {
  border-color: var(--ob-primary);
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.15);
}

.ob-input.error {
  border-color: var(--ob-red);
}

.ob-select {
  appearance: none;
  background-image: url("data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.5L6 6.5L11 1.5' stroke='%236B7280' stroke-width='2' stroke-linecap='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right 12px center;
  padding-right: 36px;
}

.ob-error {
  display: none;
  font-size: 12px;
  color: var(--ob-red);
  margin-top: 6px;
}

.ob-error.visible {
  display: block;
}

/* Topics Grid */
.ob-topics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-bottom: 4px;
}

.ob-topic {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 16px 8px;
  border: 2px solid var(--ob-gray-200);
  border-radius: 12px;
  background: #fff;
  position: relative;
  transition: border-color .15s, background .15s, transform .1s;
}

.ob-topic:hover {
  border-color: var(--ob-primary);
  background: var(--ob-primary-light);
}

.ob-topic.selected {
  border-color: var(--ob-primary);
  background: var(--ob-primary-light);
}

.ob-topic:active {
  transform: scale(0.97);
}

.ob-topic-icon {
  color: var(--ob-gray-500);
  transition: color .15s;
}

.ob-topic.selected .ob-topic-icon {
  color: var(--ob-primary);
}

.ob-topic-label {
  font-size: 12px;
  font-weight: 500;
  color: var(--ob-gray-600);
  text-align: center;
}

.ob-topic.selected .ob-topic-label {
  color: var(--ob-primary-dark);
}

.ob-topic-check {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--ob-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transform: scale(0.5);
  transition: opacity .15s, transform .15s;
  color: #fff;
}

.ob-topic.selected .ob-topic-check {
  opacity: 1;
  transform: scale(1);
}

/* Invite */
.ob-invite-input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 4px;
}

.ob-invite-input-row .ob-input {
  flex: 1;
}

.ob-invite-input-row .ob-btn {
  flex-shrink: 0;
}

.ob-invite-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
  min-height: 20px;
}

.ob-invite-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  background: var(--ob-primary-light);
  color: var(--ob-primary-dark);
  border-radius: 9999px;
  font-size: 13px;
  font-weight: 500;
  animation: obFadeIn .2s ease;
}

.ob-invite-remove {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  line-height: 1;
  color: var(--ob-primary);
  transition: background .12s, color .12s;
}

.ob-invite-remove:hover {
  background: var(--ob-primary);
  color: #fff;
}

/* Navigation */
.ob-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 32px;
  gap: 12px;
}

.ob-nav-right {
  display: flex;
  align-items: center;
  gap: 16px;
}

.ob-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 24px;
  border-radius: var(--ob-radius);
  font-size: 14px;
  font-weight: 600;
  transition: background .15s, border-color .15s, transform .1s;
}

.ob-btn:active {
  transform: scale(0.98);
}

.ob-btn-primary {
  background: var(--ob-primary);
  color: #fff;
}

.ob-btn-primary:hover {
  background: var(--ob-primary-dark);
}

.ob-btn-outline {
  border: 1px solid var(--ob-gray-300);
  color: var(--ob-gray-700);
  background: #fff;
}

.ob-btn-outline:hover {
  background: var(--ob-gray-50);
  border-color: var(--ob-gray-400);
}

.ob-skip {
  font-size: 13px;
  color: var(--ob-gray-500);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.ob-skip:hover {
  color: var(--ob-primary);
}

/* Step 4: Complete */
.ob-confetti-area {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.ob-confetti-piece {
  position: absolute;
  width: 8px;
  height: 8px;
  border-radius: 2px;
  top: -10px;
  animation: obConfettiFall linear forwards;
}

@keyframes obConfettiFall {
  0% {
    transform: translateY(0) rotate(0deg);
    opacity: 1;
  }
  100% {
    transform: translateY(600px) rotate(720deg);
    opacity: 0;
  }
}

.ob-complete-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px 0;
  position: relative;
  z-index: 1;
}

.ob-check-circle {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--ob-green);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
  animation: obPop .4s cubic-bezier(0.34, 1.56, 0.64, 1) .1s both;
}

@keyframes obPop {
  from {
    transform: scale(0);
  }
  to {
    transform: scale(1);
  }
}

.ob-heading-complete {
  font-size: 26px;
  margin-bottom: 8px;
}

.ob-welcome-msg {
  font-size: 15px;
  color: var(--ob-gray-500);
  margin-bottom: 24px;
  text-align: center;
}

.ob-summary {
  width: 100%;
  max-width: 360px;
  margin-bottom: 32px;
  font-size: 13px;
  color: var(--ob-gray-600);
}

.ob-summary-item {
  display: flex;
  justify-content: space-between;
  padding: 8px 0;
  border-bottom: 1px solid var(--ob-gray-100);
}

.ob-summary-label {
  color: var(--ob-gray-500);
}

.ob-summary-value {
  font-weight: 500;
  color: var(--ob-gray-800);
}

.ob-btn-cta {
  width: 100%;
  max-width: 320px;
  padding: 14px 32px;
  font-size: 16px;
  font-weight: 700;
  color: #fff;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  border-radius: 12px;
  box-shadow: 0 4px 14px rgba(99, 102, 241, 0.35);
  transition: box-shadow .2s, transform .15s;
}

.ob-btn-cta:hover {
  box-shadow: 0 6px 20px rgba(99, 102, 241, 0.45);
  transform: translateY(-1px);
}

.ob-btn-cta:active {
  transform: translateY(0);
}

/* Responsive */
@media (max-width: 640px) {
  .ob-card {
    padding: 28px 20px;
  }

  .ob-topics {
    grid-template-columns: repeat(2, 1fr);
  }

  .ob-step-label {
    display: none;
  }

  .ob-heading {
    font-size: 20px;
  }

  .ob-nav-right {
    flex-direction: column;
    align-items: flex-end;
    gap: 8px;
  }
}

