/* ── Analytics Dashboard – script.js ───────── */
(function () {
  "use strict";

  /* ── Date Range Selector ──────────────────── */
  const pills = document.querySelectorAll(".date-pill");
  pills.forEach(function (pill) {
    pill.addEventListener("click", function () {
      pills.forEach(function (p) {
        p.classList.remove("active");
      });
      pill.classList.add("active");
    });
  });

  /* ── Metric Card Number Animation ─────────── */
  function animateMetrics() {
    var cards = document.querySelectorAll(".metric-card");
    cards.forEach(function (card) {
      var target = parseFloat(card.dataset.target);
      var suffix = card.dataset.suffix || "";
      var format = card.dataset.format || "";
      var valueEl = card.querySelector(".metric-value");
      var duration = 1200;
      var start = performance.now();

      function tick(now) {
        var elapsed = now - start;
        var progress = Math.min(elapsed / duration, 1);
        var eased = 1 - Math.pow(1 - progress, 3);
        var current = eased * target;

        if (format === "duration") {
          var mins = Math.floor(current / 60);
          var secs = Math.floor(current % 60);
          valueEl.textContent = mins + "m " + (secs < 10 ? "0" : "") + secs + "s";
        } else if (suffix === "%") {
          valueEl.textContent = current.toFixed(1) + "%";
        } else {
          valueEl.textContent = Math.floor(current).toLocaleString("en-US");
        }

        if (progress < 1) {
          requestAnimationFrame(tick);
        }
      }

      requestAnimationFrame(tick);
    });
  }

  /* ── Area Chart ───────────────────────────── */
  function drawAreaChart() {
    var canvas = document.getElementById("areaChart");
    if (!canvas) return;

    var dpr = window.devicePixelRatio || 1;
    var rect = canvas.parentElement.getBoundingClientRect();
    var w = rect.width;
    var h = 300;
    canvas.width = w * dpr;
    canvas.height = h * dpr;
    canvas.style.width = w + "px";
    canvas.style.height = h + "px";

    var ctx = canvas.getContext("2d");
    ctx.scale(dpr, dpr);

    var data = [
      3200, 4100, 3800, 4600, 5200, 4900, 5800, 6100, 5400, 6800, 7200, 6500, 7800, 8100, 7400,
      8600, 7900, 8200, 9100, 8400, 9600, 10200, 9800, 10800, 11200, 10400, 11800, 12400, 11600,
      12800,
    ];
    var labels = [];
    var today = new Date();
    for (var i = 29; i >= 0; i--) {
      var d = new Date(today);
      d.setDate(d.getDate() - i);
      labels.push(d.getMonth() + 1 + "/" + d.getDate());
    }

    var padLeft = 50;
    var padRight = 20;
    var padTop = 20;
    var padBottom = 40;
    var chartW = w - padLeft - padRight;
    var chartH = h - padTop - padBottom;
    var maxVal = Math.max.apply(null, data) * 1.1;
    var stepX = chartW / (data.length - 1);

    function xPos(i) {
      return padLeft + i * stepX;
    }
    function yPos(v) {
      return padTop + chartH - (v / maxVal) * chartH;
    }

    // Grid lines
    ctx.strokeStyle = "#f3f4f6";
    ctx.lineWidth = 1;
    var gridLines = 5;
    for (var g = 0; g <= gridLines; g++) {
      var gy = padTop + (chartH / gridLines) * g;
      ctx.beginPath();
      ctx.moveTo(padLeft, gy);
      ctx.lineTo(w - padRight, gy);
      ctx.stroke();

      // Y-axis labels
      var gridVal = Math.round(maxVal - (maxVal / gridLines) * g);
      ctx.fillStyle = "#9ca3af";
      ctx.font = "11px -apple-system, sans-serif";
      ctx.textAlign = "right";
      ctx.fillText(
        gridVal >= 1000 ? (gridVal / 1000).toFixed(1) + "k" : gridVal.toString(),
        padLeft - 8,
        gy + 4
      );
    }

    // Gradient fill
    var gradient = ctx.createLinearGradient(0, padTop, 0, padTop + chartH);
    gradient.addColorStop(0, "rgba(99, 102, 241, 0.25)");
    gradient.addColorStop(1, "rgba(99, 102, 241, 0.02)");

    ctx.beginPath();
    ctx.moveTo(xPos(0), yPos(data[0]));
    for (var j = 1; j < data.length; j++) {
      ctx.lineTo(xPos(j), yPos(data[j]));
    }
    ctx.lineTo(xPos(data.length - 1), padTop + chartH);
    ctx.lineTo(xPos(0), padTop + chartH);
    ctx.closePath();
    ctx.fillStyle = gradient;
    ctx.fill();

    // Line
    ctx.beginPath();
    ctx.moveTo(xPos(0), yPos(data[0]));
    for (var k = 1; k < data.length; k++) {
      ctx.lineTo(xPos(k), yPos(data[k]));
    }
    ctx.strokeStyle = "#6366f1";
    ctx.lineWidth = 2;
    ctx.lineJoin = "round";
    ctx.stroke();

    // Dots
    for (var m = 0; m < data.length; m++) {
      ctx.beginPath();
      ctx.arc(xPos(m), yPos(data[m]), 3, 0, Math.PI * 2);
      ctx.fillStyle = "#6366f1";
      ctx.fill();
      ctx.strokeStyle = "#fff";
      ctx.lineWidth = 1.5;
      ctx.stroke();
    }

    // X-axis labels (show every 5th)
    ctx.fillStyle = "#9ca3af";
    ctx.font = "11px -apple-system, sans-serif";
    ctx.textAlign = "center";
    for (var n = 0; n < labels.length; n++) {
      if (n % 5 === 0 || n === labels.length - 1) {
        ctx.fillText(labels[n], xPos(n), h - 10);
      }
    }
  }

  /* ── Heatmap ──────────────────────────────── */
  function buildHeatmap() {
    var grid = document.getElementById("heatmapGrid");
    if (!grid) return;

    var weeks = 52;
    var daysPerWeek = 7;
    var today = new Date();
    var startDate = new Date(today);
    startDate.setDate(startDate.getDate() - (weeks * daysPerWeek - 1));

    // Seed a deterministic-looking random
    function seededRandom(seed) {
      var x = Math.sin(seed) * 10000;
      return x - Math.floor(x);
    }

    for (var w = 0; w < weeks; w++) {
      for (var d = 0; d < daysPerWeek; d++) {
        var dayIndex = w * daysPerWeek + d;
        var cellDate = new Date(startDate);
        cellDate.setDate(cellDate.getDate() + dayIndex);

        var rand = seededRandom(dayIndex * 31 + 7);
        var count = Math.floor(rand * 20);
        var level;
        if (count === 0) level = 0;
        else if (count <= 5) level = 1;
        else if (count <= 12) level = 2;
        else level = 3;

        var cell = document.createElement("div");
        cell.className = "heatmap-cell level-" + level;

        var dateStr = cellDate.toLocaleDateString("en-US", {
          month: "short",
          day: "numeric",
          year: "numeric",
        });

        var tooltip = document.createElement("span");
        tooltip.className = "tooltip";
        tooltip.textContent = count + " contributions on " + dateStr;
        cell.appendChild(tooltip);

        grid.appendChild(cell);
      }
    }
  }

  /* ── Funnel Animation ─────────────────────── */
  function animateFunnel() {
    var bars = document.querySelectorAll(".funnel-bar");
    bars.forEach(function (bar, index) {
      setTimeout(function () {
        bar.style.width = bar.style.getPropertyValue("--target-width");
      }, index * 150);
    });
  }

  /* ── CSV Export ────────────────────────────── */
  function setupExport() {
    var btn = document.getElementById("exportCsv");
    if (!btn) return;

    btn.addEventListener("click", function () {
      var table = document.getElementById("pagesTable");
      if (!table) return;

      var rows = table.querySelectorAll("tr");
      var csvContent = "";

      rows.forEach(function (row) {
        var cols = row.querySelectorAll("th, td");
        var rowData = [];
        cols.forEach(function (col) {
          var text = col.textContent.replace(/"/g, '""');
          rowData.push('"' + text + '"');
        });
        csvContent += rowData.join(",") + "\n";
      });

      var blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      var url = URL.createObjectURL(blob);
      var link = document.createElement("a");
      link.href = url;
      link.download = "analytics-top-pages.csv";
      link.style.display = "none";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    });
  }

  /* ── Resize Handler ───────────────────────── */
  var resizeTimer;
  window.addEventListener("resize", function () {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(drawAreaChart, 200);
  });

  /* ── Init ──────────────────────────────────── */
  function init() {
    animateMetrics();
    drawAreaChart();
    buildHeatmap();
    animateFunnel();
    setupExport();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

snippets.css:
*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: #fff;
  color: #1a1a2e;
  line-height: 1.6;
  min-height: 100vh;
}

a {
  text-decoration: none;
}

/* ── Header / Search Bar ─────────────────────── */

.search-header {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 16px 24px;
  border-bottom: 1px solid #e5e7eb;
  background: #fff;
  position: sticky;
  top: 0;
  z-index: 50;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 18px;
  font-weight: 700;
  color: #4f46e5;
  flex-shrink: 0;
}

.search-bar {
  display: flex;
  flex: 1;
  max-width: 640px;
}

.search-input {
  flex: 1;
  padding: 10px 16px;
  border: 1px solid #d1d5db;
  border-right: none;
  border-radius: 8px 0 0 8px;
  font-size: 15px;
  color: #1a1a2e;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.search-input:focus {
  border-color: #4f46e5;
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

.search-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 16px;
  border: 1px solid #4f46e5;
  border-radius: 0 8px 8px 0;
  background: #4f46e5;
  color: #fff;
  cursor: pointer;
  transition: background 0.15s ease;
}

.search-btn:hover {
  background: #4338ca;
}

/* ── Type Tabs ───────────────────────────────── */

.type-tabs {
  display: flex;
  gap: 4px;
  padding: 0 24px;
  border-bottom: 1px solid #e5e7eb;
  overflow-x: auto;
}

.type-tab {
  padding: 10px 16px;
  border: none;
  border-bottom: 2px solid transparent;
  background: none;
  color: #6b7280;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.type-tab:hover {
  color: #1a1a2e;
}

.type-tab.active {
  color: #4f46e5;
  border-bottom-color: #4f46e5;
}

/* ── Layout ──────────────────────────────────── */

.search-layout {
  display: flex;
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ── Filter Sidebar ──────────────────────────── */

.filter-sidebar {
  width: 240px;
  flex-shrink: 0;
  padding: 24px 20px 24px 0;
  border-right: 1px solid #f0f1f3;
}

.filter-group {
  margin-bottom: 24px;
}

.filter-title {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #6b7280;
  margin-bottom: 10px;
}

.filter-radio,
.filter-check {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 0;
  font-size: 14px;
  color: #374151;
  cursor: pointer;
}

.filter-radio input,
.filter-check input {
  accent-color: #4f46e5;
  width: 15px;
  height: 15px;
}

.filter-select {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  font-size: 14px;
  color: #374151;
  background: #fff;
  cursor: pointer;
  outline: none;
}

.filter-select:focus {
  border-color: #4f46e5;
}

#mobileFilterClose {
  display: none;
}

/* ── Results Main ────────────────────────────── */

.results-main {
  flex: 1;
  min-width: 0;
  padding: 24px 0 40px 32px;
}

.results-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.results-count {
  font-size: 13px;
  color: #6b7280;
}

.results-count strong {
  color: #1a1a2e;
}

.mobile-filter-btn {
  display: none;
}

.filter-toggle-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  background: #fff;
  color: #374151;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
}

.filter-toggle-btn:hover {
  background: #f9fafb;
}

/* ── Result Cards ────────────────────────────── */

.result-card {
  padding: 20px 0;
  border-bottom: 1px solid #f0f1f3;
}

.result-card:last-child {
  border-bottom: none;
}

.result-title {
  font-size: 18px;
  font-weight: 500;
  line-height: 1.3;
  margin-bottom: 4px;
}

.result-title a {
  color: #1a0dab;
  transition: color 0.1s ease;
}

.result-title a:hover {
  text-decoration: underline;
}

.result-title a:visited {
  color: #681da8;
}

.result-url {
  font-size: 13px;
  color: #188038;
  margin-bottom: 6px;
}

.result-url mark {
  background: none;
  color: #188038;
  font-weight: 600;
}

.result-desc {
  font-size: 14px;
  color: #4d5156;
  line-height: 1.5;
}

.result-desc mark {
  background: #fef3c7;
  color: #1a1a2e;
  padding: 1px 2px;
  border-radius: 2px;
  font-weight: 600;
}

.result-tags {
  display: flex;
  gap: 6px;
  margin-top: 8px;
}

.tag {
  display: inline-block;
  padding: 2px 8px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  font-size: 11px;
  color: #6b7280;
  background: #f9fafb;
}

/* ── Pagination ──────────────────────────────── */

.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  margin-top: 32px;
  padding-top: 24px;
  border-top: 1px solid #f0f1f3;
}

.page-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 36px;
  height: 36px;
  padding: 0 8px;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  background: #fff;
  color: #374151;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.page-btn:hover:not(:disabled):not(.active) {
  background: #f3f4f6;
  border-color: #d1d5db;
}

.page-btn.active {
  background: #4f46e5;
  border-color: #4f46e5;
  color: #fff;
  font-weight: 600;
}

.page-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.page-ellipsis {
  padding: 0 6px;
  color: #9ca3af;
  font-size: 14px;
}

/* ── Empty State ─────────────────────────────── */

.empty-results {
  text-align: center;
  padding: 60px 20px;
}

.empty-icon {
  margin-bottom: 16px;
}

.empty-results h3 {
  font-size: 18px;
  font-weight: 600;
  color: #1a1a2e;
  margin-bottom: 8px;
}

.empty-results p {
  font-size: 14px;
  color: #6b7280;
  margin-bottom: 16px;
}

.empty-results ul {
  list-style: none;
  font-size: 14px;
  color: #6b7280;
}

.empty-results li {
  padding: 3px 0;
}

.empty-results li::before {
  content: "\2022";
  color: #9ca3af;
  margin-right: 8px;
}

/* ── Responsive ──────────────────────────────── */

@media (max-width: 768px) {
  .search-header {
    padding: 12px 16px;
    gap: 12px;
  }

  .logo span {
    display: none;
  }

  .type-tabs {
    padding: 0 16px;
  }

  .search-layout {
    flex-direction: column;
    padding: 0 16px;
  }

  .filter-sidebar {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 100;
    width: 100%;
    background: #fff;
    padding: 24px;
    border-right: none;
    overflow-y: auto;
  }

  .filter-sidebar.open {
    display: block;
  }

  #mobileFilterClose {
    display: block;
    width: 100%;
    margin-top: 16px;
    text-align: center;
  }

  .mobile-filter-btn {
    display: inline-flex;
  }

  .results-main {
    padding: 16px 0 40px;
  }

  .result-title {
    font-size: 16px;
  }

  .page-btn {
    min-width: 32px;
    height: 32px;
    font-size: 13px;
  }
}

