  .theme-cards {
    grid-template-columns: 1fr;
  }

  .avatar-section {
    flex-direction: column;
    text-align: center;
  }

  .session-item {
    flex-wrap: wrap;
  }

  .tfa-row {
    flex-direction: column;
  }
}

