*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #050910;
  --nav-bg: #0d1117;
  --card-bg: #3b82f6;
  --card-hover: #2563eb;
  --accent: #38bdf8;
  --text: #e2e8f0;
  --text-muted: #94a3b8;
  --muted: #475569;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  background: var(--bg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--text);
  padding: 2rem;
}

/* ── Demo wrapper ── */
.demo {
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}
.demo-title {
  font-size: 1.5rem;
  font-weight: 800;
  text-align: center;
}
.demo-sub {
  color: var(--muted);
  font-size: 0.875rem;
  text-align: center;
}

/* ── Phone frame ── */
.phone-frame {
  width: 320px;
  height: 520px;
  background: var(--nav-bg);
  border-radius: 32px;
  border: 1.5px solid rgba(255, 255, 255, 0.08);
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.04);
  overflow: hidden;
  position: relative;
}

/* ── Screens ── */
.screen {
  position: absolute;
  inset: 0;
  padding: 36px 20px 20px;
  display: flex;
  flex-direction: column;
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.grid-screen {
  transform: translateX(-100%);
}
.grid-screen.active {
  transform: translateX(0);
}
.detail-screen {
  transform: translateX(100%);
}
.detail-screen.active {
  transform: translateX(0);
}

/* ── Grid screen title ── */
.screen-title {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 20px;
}

/* ── Card grid ── */
.card-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

.nav-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  aspect-ratio: 1;
  background: var(--card-bg);
  border: none;
  border-radius: 16px;
  cursor: pointer;
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  transition: background 0.2s, transform 0.15s;
  -webkit-tap-highlight-color: transparent;
}

.nav-card:hover {
  background: var(--card-hover);
}
.nav-card:active {
  transform: scale(0.95);
}
.nav-card svg {
  width: 26px;
  height: 26px;
}

/* ── Detail screens ── */
.detail-screen h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 6px;
}
.detail-screen p {
  font-size: 0.8rem;
  color: var(--text-muted);
  line-height: 1.5;
  margin-bottom: 14px;
}

/* ── Back button ── */
.back-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: none;
  border: none;
  color: var(--accent);
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  padding: 4px 0;
  margin-bottom: 14px;
  align-self: flex-start;
}

.back-btn:hover {
  opacity: 0.8;
}
.back-btn svg {
  width: 16px;
  height: 16px;
}

/* ── Placeholder content ── */
.placeholder-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.placeholder-bar {
  height: 40px;
  background: #1e293b;
  border-radius: 8px;
}
.placeholder-bar.short {
  height: 32px;
  width: 75%;
}

.search-input {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: #1e293b;
  border-radius: 10px;
  color: var(--text-muted);
  font-size: 13px;
}

.search-input svg {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}

.photo-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}
.photo-tile {
  aspect-ratio: 1;
  background: #1e293b;
  border-radius: 8px;
}

.profile-circle {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--card-bg), var(--accent));
}

.profile-label {
  font-size: 1rem;
  font-weight: 600;
  margin-top: 8px;
}

