/* ============================================================
   TERMINAL / CLI — Style Showcase
   Font: Courier New / Lucida Console / monospace only
   Palette: #33FF33 (phosphor green) on #0A0F0A (near-black)
   ============================================================ */

/* --- Root variables --- */
:root {
  --green: #33ff33;
  --green-dim: #1a8c1a;
  --green-mute: rgba(51, 255, 51, 0.4);
  --green-faint: rgba(51, 255, 51, 0.12);
  --warn: #ffd700;
  --error: #ff3333;
  --bg: #0a0f0a;
  --panel: #0d150d;
  --border: rgba(51, 255, 51, 0.35);
  --font: "Courier New", "Lucida Console", Courier, monospace;
}

/* --- Reset & base --- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
}

body {
  background: var(--bg);
  color: var(--green);
  font-family: var(--font);
  font-size: 13px;
  line-height: 1.7;
  min-height: 100vh;
  overflow-x: hidden;
}

/* Subtle green CRT noise texture via gradient */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9998;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0px,
    transparent 3px,
    rgba(0, 0, 0, 0.08) 4px
  );
}

/* --- Scrollbar --- */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-track {
  background: var(--bg);
}
::-webkit-scrollbar-thumb {
  background: var(--green-dim);
}
::-webkit-scrollbar-thumb:hover {
  background: var(--green);
}

/* --- Blink animation --- */
@keyframes blink {
  0%,
  49% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0;
  }
}

/* --- Header --- */
.site-header {
  background: var(--panel);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: 900px;
  margin: 0 auto;
  padding: 10px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.header-logo {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  color: var(--green);
}

.prompt-sym {
  color: var(--green-dim);
}

.logo-text {
  font-weight: bold;
}

.cursor-blink {
  animation: blink 0.8s step-end infinite;
}

.header-nav {
  display: flex;
  gap: 20px;
}

.nav-link {
  color: var(--green-dim);
  text-decoration: none;
  font-size: 12px;
  transition: color 0.15s;
}

.nav-link:hover,
.nav-active {
  color: var(--green);
}

.nav-active {
  text-decoration: underline;
}

.header-uptime {
  font-size: 11px;
  color: var(--green-dim);
  letter-spacing: 0.05em;
}

/* --- Hero --- */
.hero {
  padding: 32px 20px 16px;
  border-bottom: 1px solid var(--border);
  max-width: 900px;
  margin: 0 auto;
}

.ascii-art {
  font-size: clamp(7px, 1.3vw, 13px);
  color: var(--green);
  line-height: 1.25;
  margin-bottom: 20px;
  overflow-x: auto;
  white-space: pre;
}

.hero-tagline {
  font-size: 12px;
  color: var(--green);
  margin-bottom: 6px;
}

.hero-sub {
  font-size: 11px;
  color: var(--green-dim);
}

/* --- Status bar --- */
.status-bar {
  background: rgba(51, 255, 51, 0.06);
  border-bottom: 1px solid var(--border);
  padding: 6px 20px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 11px;
  flex-wrap: wrap;
}

.status-item {
  color: var(--green-dim);
}
.status-ok {
  color: var(--green);
}
.status-sep {
  color: var(--border);
  user-select: none;
}

/* --- Main content --- */
.main-content {
  max-width: 900px;
  margin: 0 auto;
  padding: 28px 20px 60px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* --- Terminal window --- */
.terminal-window {
  background: var(--panel);
  border: 1px solid var(--border);
}

.term-titlebar {
  background: rgba(51, 255, 51, 0.08);
  border-bottom: 1px solid var(--border);
  padding: 7px 12px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.term-dots {
  display: flex;
  gap: 5px;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
}

.dot-red {
  background: #ff5f57;
}
.dot-yellow {
  background: #febc2e;
}
.dot-green {
  background: #28c840;
}

.term-title {
  font-size: 11px;
  color: var(--green-dim);
  flex: 1;
  text-align: center;
  letter-spacing: 0.05em;
}

.term-body {
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* Output lines */
.output-line {
  font-size: 12px;
  color: var(--green);
  display: flex;
  gap: 8px;
  align-items: baseline;
}

.output-line.muted {
  color: var(--green-dim);
}

.prompt {
  color: var(--green);
  flex-shrink: 0;
  font-weight: bold;
}

/* --- Profile content --- */
.profile-content {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
  padding: 8px 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  margin: 4px 0;
}

.avatar-art {
  font-size: 11px;
  line-height: 1.3;
  color: var(--green-dim);
  white-space: pre;
}

.profile-data {
  flex: 1;
  min-width: 180px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.data-row {
  font-size: 12px;
}

.data-key {
  color: var(--green-dim);
}

.data-val {
  color: var(--green);
}

.profile-stats {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px dashed var(--border);
}

.stat-block {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.stat-num {
  font-size: 15px;
  font-weight: bold;
  color: var(--green);
}

.stat-lbl {
  font-size: 10px;
  color: var(--green-dim);
  letter-spacing: 0.08em;
}

.stat-sep {
  color: var(--border);
  font-size: 18px;
  line-height: 1;
  user-select: none;
}

/* --- Buttons --- */
.button-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
}

.btn {
  font-family: var(--font);
  font-size: 12px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 8px 16px;
  letter-spacing: 0.04em;
  transition: background 0.1s, color 0.1s;
  outline: none;
}

.btn:focus-visible {
  outline: 1px dashed var(--green);
  outline-offset: 2px;
}

/* Primary — [EXECUTE] */
.btn-primary {
  color: var(--bg);
  background: var(--green);
  border: 1px solid var(--green);
  font-weight: bold;
}

.btn-primary:hover {
  background: #50ff50;
  border-color: #50ff50;
}

.btn-primary:active {
  background: var(--green-dim);
  border-color: var(--green-dim);
  color: var(--bg);
}

/* Secondary — [STATUS] */
.btn-secondary {
  color: rgba(51, 255, 51, 0.7);
  background: transparent;
  border: 1px solid rgba(51, 255, 51, 0.5);
}

.btn-secondary:hover {
  color: var(--green);
  border-color: var(--green);
  background: var(--green-faint);
}

.btn-secondary:active {
  background: rgba(51, 255, 51, 0.2);
}

/* Ghost — text only, looks like a command */
.btn-ghost {
  color: var(--green-dim);
  background: transparent;
  border: none;
  padding-left: 0;
}

.btn-ghost::before {
  content: "$ ";
  color: var(--green);
}

.btn-ghost:hover {
  color: var(--green);
  text-decoration: underline;
}

/* Command output area */
.cmd-output-area {
  font-size: 11px;
  color: var(--green-dim);
  min-height: 0;
  max-height: 120px;
  overflow-y: auto;
  white-space: pre-wrap;
  border-top: 0;
  padding-top: 0;
}

.cmd-output-area:not(:empty) {
  border-top: 1px solid var(--border);
  padding-top: 10px;
  margin-top: 4px;
}

.cmd-output-line {
  display: block;
  padding: 1px 0;
}

.cmd-output-line.cmd-line {
  color: var(--green);
}

.cmd-output-line.out-line {
  color: var(--green-dim);
}

/* --- Input --- */
.input-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-label {
  font-size: 11px;
  color: var(--green-dim);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.term-input-wrap {
  display: flex;
  align-items: center;
  gap: 0;
  background: var(--bg);
  border: 1px solid var(--border);
  padding: 8px 12px;
  max-width: 480px;
}

.input-prompt {
  color: var(--green);
  font-weight: bold;
  flex-shrink: 0;
  white-space: pre;
}

.term-input {
  font-family: var(--font);
  font-size: 13px;
  background: transparent;
  color: var(--green);
  border: none;
  outline: none;
  flex: 1;
  caret-color: var(--green);
}

.term-input::placeholder {
  color: var(--green-mute);
}

.term-input-wrap:focus-within {
  border-color: var(--green);
  box-shadow: 0 0 0 1px var(--green-mute);
}

/* --- Badges --- */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 4px 0;
}

.badge {
  font-family: var(--font);
  font-size: 11px;
  padding: 3px 8px;
  color: var(--green-dim);
  border: 1px solid var(--border);
  background: var(--bg);
  letter-spacing: 0.03em;
}

.badge-on {
  color: var(--green);
  border-color: rgba(51, 255, 51, 0.6);
  background: var(--green-faint);
}

.badge-warn {
  color: var(--warn);
  border-color: rgba(255, 215, 0, 0.4);
  background: rgba(255, 215, 0, 0.06);
}

.badge-off {
  color: var(--error);
  border-color: rgba(255, 51, 51, 0.4);
  background: rgba(255, 51, 51, 0.05);
  text-decoration: line-through;
}

/* --- Responsive --- */
@media (max-width: 600px) {
  .header-inner {
    flex-direction: column;
    align-items: flex-start;
  }
  .hero {
    padding: 20px 14px 12px;
  }
  .ascii-art {
    font-size: 6px;
  }
  .btn {
    width: 100%;
  }
  .profile-content {
    flex-direction: column;
  }
}

