  border: 1px solid rgba(139, 92, 246, 0.45);
  box-shadow: 0 0 10px rgba(139, 92, 246, 0.2);
}

.badge-outline {
  background: transparent;
  color: var(--text-muted);
  border: 1px solid rgba(167, 139, 250, 0.35);
}

.badge-subtle {
  background: rgba(139, 92, 246, 0.08);
  color: var(--text-dim);
  border: 1px solid rgba(139, 92, 246, 0.15);
  font-family: "Space Grotesk", monospace;
  font-size: 12px;
  letter-spacing: 0;
}

/* ---- Responsive ---- */
@media (max-width: 600px) {
  .header-nav {
    display: none;
  }
  .header-inner {
    padding: 0 16px;
    gap: 16px;
  }
  .container {
    padding: 0 16px;
  }
  .main {
    padding: 32px 0 48px;
  }
  .profile-card {
    flex-direction: column;
    text-align: center;
    gap: 16px;
  }
  .profile-stats {
    justify-content: center;
  }
  .profile-rank {
    margin-left: 0;
  }
  .page-title {
    font-size: clamp(24px, 7vw, 32px);
  }
  .page-eyebrow {
    font-size: 10px;
    letter-spacing: 0.12em;
  }
  .page-tagline {
    font-size: 14px;
  }
  .card {
    padding: 20px;
  }
  .profile-avatar {
    width: 64px;
    height: 64px;
    font-size: 20px;
  }
  .profile-name {
    font-size: 18px;
  }
  .stat-value {
    font-size: 18px;
  }
  .stat-label {
    font-size: 11px;
  }
  .btn {
    height: 40px;
    padding: 0 18px;
    font-size: 13px;
  }
  .btn-row {
    gap: 8px;
  }
  .input {
    height: 42px;
    font-size: 13px;
  }
  .orb-1 {
    width: 240px;
    height: 240px;
  }
  .orb-2 {
    width: 280px;
    height: 280px;
  }
  .orb-3 {
    display: none;
  }
}

@media (max-width: 380px) {
  .profile-stats {
    gap: 12px;
  }
  .logo-text {
    font-size: 14px;
    letter-spacing: 2px;
  }
}

