*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #050910;
  --nav-bg: #0d1117;
  --sheet-bg: #3b82f6;
  --sheet-item: #1e3a6e;
  --sheet-item-hover: #254a85;
  --text: #e2e8f0;
  --text-muted: #94a3b8;
  --muted: #475569;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

/* ── Demo wrapper ── */
.demo {
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}
.demo-title {
  font-size: 1.5rem;
  font-weight: 800;
  text-align: center;
}
.demo-sub {
  color: var(--muted);
  font-size: 0.875rem;
  text-align: center;
}

/* ── Phone frame ── */
.phone-frame {
  width: 320px;
  border-radius: 32px;
  border: 1.5px solid rgba(255, 255, 255, 0.08);
  background: var(--nav-bg);
  overflow: hidden;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.04);
}

.phone-screen {
  width: 100%;
  height: 520px;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

/* ── Screen content ── */
.screen-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px;
  text-align: center;
}

.screen-content h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.screen-content p {
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* ── Open button ── */
.open-btn {
  position: absolute;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  padding: 10px 28px;
  border: none;
  border-radius: 10px;
  background: var(--sheet-bg);
  color: #fff;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  z-index: 5;
  -webkit-tap-highlight-color: transparent;
}

.open-btn:active {
  transform: translateX(-50%) scale(0.96);
  opacity: 0.9;
}

/* ── Backdrop ── */
.backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
  z-index: 10;
}

.backdrop.visible {
  opacity: 1;
  pointer-events: all;
}

/* ── Bottom sheet ── */
.bottom-sheet {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 11;
  background: var(--sheet-bg);
  border-radius: 20px 20px 0 0;
  padding: 8px 16px 24px;
  transform: translateY(100%);
  transition: transform 0.35s cubic-bezier(0.32, 0.72, 0, 1);
  max-height: 65%;
}

.bottom-sheet.open {
  transform: translateY(0);
}

/* ── Drag handle ── */
.drag-handle {
  width: 40px;
  height: 4px;
  background: rgba(255, 255, 255, 0.4);
  border-radius: 2px;
  margin: 8px auto 16px;
  cursor: pointer;
}

/* ── Sheet header ── */
.sheet-header {
  font-size: 1rem;
  font-weight: 700;
  color: #fff;
  margin-bottom: 12px;
  padding: 0 4px;
}

/* ── Action rows ── */
.sheet-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.action-row {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 12px 14px;
  border: none;
  border-radius: 10px;
  background: var(--sheet-item);
  color: #fff;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s;
  -webkit-tap-highlight-color: transparent;
}

.action-row:active {
  background: var(--sheet-item-hover);
}
.action-row svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

