/* ============================================================
   Netflix Cinematic — Design Style Showcase
   ============================================================ */

:root {
  /* Core palette */
  --bg-body: #141414;
  --bg-card: #1f1f1f;
  --bg-card-alt: #2a2a2a;
  --bg-input: #333333;
  --bg-hover: #3a3a3a;

  /* Text */
  --text-primary: #ffffff;
  --text-secondary: #b3b3b3;
  --text-placeholder: #888888;

  /* Accent — Netflix red */
  --red: #e50914;
  --red-dark: #b81d24;

  /* Borders — minimal */
  --border: rgba(255, 255, 255, 0.08);

  /* Radius — cinematic small */
  --radius-sm: 2px;
  --radius: 4px;

  /* Shadows */
  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.6);
  --shadow-heavy: 0 8px 40px rgba(0, 0, 0, 0.8);
}

/* ---- Reset ---- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg-body);
  color: var(--text-primary);
  font-family: "DM Sans", system-ui, -apple-system, sans-serif;
  font-size: 15px;
  line-height: 1.5;
  min-height: 100vh;
}

a {
  color: inherit;
  text-decoration: none;
}
button {
  font-family: inherit;
  cursor: pointer;
}

/* ---- Header ---- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: linear-gradient(180deg, rgba(20, 20, 20, 0.98) 0%, rgba(20, 20, 20, 0.75) 100%);
  backdrop-filter: blur(4px);
}

.header-inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 32px;
  height: 64px;
  display: flex;
  align-items: center;
  gap: 36px;
}

.header-logo {
  font-size: 22px;
  font-weight: 800;
  color: var(--red);
  letter-spacing: 3px;
  flex-shrink: 0;
}

.header-nav {
  display: flex;
  align-items: center;
  gap: 20px;
  flex: 1;
}

.nav-link {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color 0.15s;
}

.nav-link:hover {
  color: var(--text-primary);
}
.nav-link.active {
  color: var(--text-primary);
  font-weight: 600;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.icon-btn {
  background: transparent;
  border: none;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color 0.15s;
}

.icon-btn:hover {
  color: var(--text-primary);
}

.avatar-sm {
  width: 32px;
  height: 32px;
  border-radius: var(--radius);
  font-size: 13px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  letter-spacing: 0.5px;
}

/* ---- Layout ---- */
.main {
  padding: 40px 0 80px;
}

.container {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 32px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ---- Page title ---- */
.page-title-area {
  padding: 4px 0 8px;
}

.page-eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: var(--red);
  margin-bottom: 8px;
}

.page-title {
  font-size: 36px;
  font-weight: 800;
  letter-spacing: -0.5px;
  line-height: 1.1;
}

.page-tagline {
  margin-top: 8px;
  font-size: 15px;
  color: var(--text-secondary);
}

/* ---- Card ---- */
.card {
  background: var(--bg-card);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow-card);
}

.section-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--text-secondary);
  margin-bottom: 16px;
}

/* ---- Hero card ---- */
.hero-card {
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-heavy);
}

.hero-image-placeholder {
  position: relative;
  width: 100%;
  padding-top: 42%; /* ~21:9 cinematic */
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 30%, #0f3460 60%, #1a1a2e 100%);
  overflow: hidden;
}

/* Decorative film-grain texture */
.hero-image-placeholder::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 70% 40%, rgba(229, 9, 20, 0.12) 0%, transparent 60%),
    radial-gradient(ellipse at 20% 60%, rgba(15, 52, 96, 0.4) 0%, transparent 50%);
}

.hero-gradient-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to top,
    rgba(20, 20, 20, 1) 0%,
    rgba(20, 20, 20, 0.7) 35%,
    rgba(20, 20, 20, 0.1) 70%,
    transparent 100%
  );
}

.hero-content {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 32px;
}

.hero-badges {
  display: flex;
  gap: 8px;
  margin-bottom: 12px;
}

.rating-badge {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 6px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  border: 1px solid var(--text-secondary);
  color: var(--text-secondary);
  border-radius: var(--radius-sm);
}

.new-badge {
  background: var(--red);
  border-color: var(--red);
  color: #fff;
}

.hero-title {
  font-size: 42px;
  font-weight: 800;
  letter-spacing: -1px;
  line-height: 1;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.6);
  margin-bottom: 10px;
}

.hero-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
  font-size: 14px;
}

.match-score {
  color: #46d369;
  font-weight: 700;
}

.hero-year,
.hero-seasons {
  color: var(--text-secondary);
}

.hero-desc {
  max-width: 520px;
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.55;
  margin-bottom: 20px;
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.5);
}

.hero-actions {
  display: flex;
  gap: 12px;
}

/* ---- Buttons ---- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 42px;
  padding: 0 22px;
  border-radius: var(--radius);
  font-size: 15px;
  font-weight: 700;
  border: none;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, filter 0.15s;
}

.btn:active {
  transform: scale(0.97);
}

/* Hero play button */
.btn-play {
  background: #fff;
  color: #000;
  font-size: 16px;
}

.btn-play:hover {
  background: rgba(255, 255, 255, 0.85);
}

/* Hero more-info */
.btn-moreinfo {
  background: rgba(109, 109, 110, 0.7);
  color: #fff;
}

.btn-moreinfo:hover {
  background: rgba(109, 109, 110, 0.5);
}

/* Section buttons */
.btn-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.btn-white {
  background: #fff;
  color: #000;
}

.btn-white:hover {
  background: rgba(255, 255, 255, 0.85);
}

.btn-gray {
  background: rgba(109, 109, 110, 0.7);
  color: #fff;
}

.btn-gray:hover {
  background: rgba(109, 109, 110, 0.5);
}

.btn-red {
  background: var(--red);
  color: #fff;
}

.btn-red:hover {
  background: var(--red-dark);
  filter: brightness(1.05);
}

/* ---- Profile card ---- */
.profile-card {
  display: flex;
  align-items: center;
  gap: 24px;
}

.profile-avatar-wrap {
  flex-shrink: 0;
}

.profile-avatar {
  width: 72px;
  height: 72px;
  border-radius: var(--radius);
  background: var(--red);
  color: #fff;
  font-size: 24px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
}

.profile-info {
  flex: 1;
}

.profile-name {
  font-size: 20px;
  font-weight: 700;
}

.profile-role {
  font-size: 14px;
  color: var(--text-secondary);
  margin-top: 3px;
}

.profile-stats {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-top: 16px;
}

.stat {
  text-align: center;
}

.stat-value {
  display: block;
  font-size: 20px;
  font-weight: 700;
}

.stat-label {
  display: block;
  font-size: 12px;
  color: var(--text-secondary);
  margin-top: 2px;
}

.stat-divider {
  width: 1px;
  height: 32px;
  background: var(--border);
}

/* ---- Continue watching card ---- */
.continue-thumb-wrap {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 12px;
}

.continue-thumb {
  width: 120px;
  height: 68px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, #1e1e3a, #2a1a1a);
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}

.continue-thumb::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 60% 40%, rgba(229, 9, 20, 0.15) 0%, transparent 70%);
}

.continue-info {
  flex: 1;
}

.continue-title {
  font-size: 15px;
  font-weight: 600;
}

.continue-meta {
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: 3px;
}

.btn-icon-circle {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
  border: none;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s;
  flex-shrink: 0;
}

.btn-icon-circle:hover {
  background: rgba(255, 255, 255, 0.35);
}

.progress-track {
  width: 100%;
  height: 3px;
  background: var(--bg-hover);
  border-radius: 2px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: var(--red);
  border-radius: 2px;
  transition: width 0.4s ease;
}

/* ---- Input ---- */
.input-group {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.input-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.input {
  height: 44px;
  padding: 0 14px;
  background: var(--bg-input);
  border: 1px solid transparent;
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 14px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s;
}

.input::placeholder {
  color: var(--text-placeholder);
}

.input:focus {
  border-color: var(--text-secondary);
}

.input-hint {
  font-size: 12px;
  color: var(--text-secondary);
}

/* ---- Badges ---- */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.badge {
  display: inline-flex;
  align-items: center;
  height: 24px;
  padding: 0 8px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  border-radius: var(--radius-sm);
}

.new-badge-pill {
  background: var(--red);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
}

.genre-badge {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-secondary);
  border: none;
}

/* ---- Card hover scale ---- */
.hero-card {
  transition: transform 0.25s ease;
}

/* ---- Responsive ---- */
@media (max-width: 640px) {
  .header-nav {
    display: none;
  }
  .hero-title {
    font-size: 28px;
  }
  .hero-image-placeholder {
    padding-top: 56%;
  }
  .hero-content {
    padding: 20px;
  }
  .hero-desc {
    display: none;
  }
  .profile-card {
    flex-direction: column;
  }
  .page-title {
    font-size: 28px;
  }
  .container {
    padding: 0 16px;
  }
}

