  --bg: #050910;
  --nav-bg: #0d1117;
  --accent: #3b82f6;
  --text: #e4e4e7;
  --text-muted: #71717a;
  --muted: #475569;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  background: var(--bg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--text);
  padding: 2rem;
}

/* ── Demo wrapper ── */
.demo {
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}
.demo-title {
  font-size: 1.5rem;
  font-weight: 800;
  text-align: center;
}
.demo-sub {
  color: var(--muted);
  font-size: 0.875rem;
  text-align: center;
}

/* ── Phone frame ── */
.phone-frame {
  width: 320px;
  height: 520px;
  background: #fff;
  border-radius: 32px;
  border: 1.5px solid rgba(255, 255, 255, 0.08);
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.04);
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
}

/* ── Content area ── */
.page-content {
  flex: 1;
  overflow: hidden;
  position: relative;
  background: #fff;
}

.content-screen {
  position: absolute;
  inset: 0;
  padding: 32px 20px 20px;
  display: none;
  flex-direction: column;
  gap: 12px;
  opacity: 0;
  transition: opacity 0.25s ease;
}

.content-screen.active {
  display: flex;
  opacity: 1;
}
.content-screen h2 {
  font-size: 1.25rem;
  font-weight: 700;
  color: #111;
}
.content-screen > p {
  font-size: 0.8rem;
  color: #666;
  line-height: 1.5;
}

/* ── Feed placeholders ── */
.feed-placeholder {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 4px;
}
.feed-card {
  height: 64px;
  background: #f3f4f6;
  border-radius: 10px;
}
.feed-card.short {
  height: 48px;
}

/* ── Search ── */
.search-box {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: #f3f4f6;
  border-radius: 10px;
  color: #999;
  font-size: 13px;
}

.search-box svg {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}

/* ── Create ── */
.create-options {
  display: flex;
  gap: 8px;
}
.create-option {
  flex: 1;
  padding: 20px 8px;
  background: #f3f4f6;
  border-radius: 10px;
  text-align: center;
  font-size: 12px;
  font-weight: 600;
  color: #555;
}

/* ── Likes ── */
.likes-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.likes-item {
  padding: 10px 12px;
  background: #eff6ff;
  border-radius: 8px;
  font-size: 12px;
  color: #333;
}

/* ── Profile ── */
.profile-avatar {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, #3b82f6, #60a5fa);
  margin-top: 4px;
}

.profile-name {
  font-size: 1rem;
  font-weight: 600;
  color: #111;
}

/* ── Bottom Nav ── */
.bottom-nav {
  display: flex;
  align-items: flex-end;
  height: 64px;
  background: var(--nav-bg);
  padding: 0 6px;
  flex-shrink: 0;
}

.nav-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  border: none;
  background: none;
  cursor: pointer;
  padding: 8px 4px 10px;
  color: var(--text-muted);
  transition: color 0.2s;
  -webkit-tap-highlight-color: transparent;
}

.nav-item:active {
  transform: scale(0.92);
}
.nav-item.active {
  color: var(--accent);
}

.nav-icon {
  width: 20px;
  height: 20px;
  transition: transform 0.2s;
}
.nav-item.active .nav-icon {
  transform: scale(1.1);
}

.nav-label {
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

/* ── FAB — raised center button ── */
.nav-item--fab {
  align-self: flex-end;
  padding: 0 4px 10px;
}

.fab-btn {
  width: 50px;
  height: 50px;
  background: var(--accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  box-shadow: 0 6px 20px rgba(59, 130, 246, 0.5);
  margin-bottom: 6px;
  margin-top: -28px;
  transition: transform 0.2s, box-shadow 0.2s;
}

.nav-item--fab:active .fab-btn {
  transform: scale(0.9);
}
.nav-item--fab.active .fab-btn {
  transform: rotate(45deg);
  box-shadow: 0 4px 12px rgba(59, 130, 246, 0.4);
}

.fab-icon {
  width: 22px;
  height: 22px;
}

