  padding: 10px 20px 6px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
}

.status-icons {
  font-size: 9px;
  letter-spacing: 3px;
}

/* ── Top bar ── */
.top-bar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 8px 16px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.top-bar-title {
  font-size: 18px;
