:root {
  --iso-bg: #f0f4ff;
  --iso-indigo: #5c6bc0;
  --iso-indigo-dark: #3949ab;
  --iso-indigo-light: #7986cb;
  --iso-blue: #42a5f5;
  --iso-cyan: #26c6da;
  --iso-text: #1a1f3a;
  --iso-text-muted: #5c6480;
  --iso-border: #d0d7f0;
  --iso-card-radius: 4px;
  --font: "Space Grotesk", system-ui, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background-color: var(--iso-bg);
  color: var(--iso-text);
  min-height: 100vh;
  overflow-x: hidden;
  position: relative;
}

/* ── Background dot grid ── */
.bg-grid {
  position: fixed;
  inset: 0;
  z-index: 0;
  background-image: radial-gradient(circle, #a0aac8 1px, transparent 1px);
  background-size: 28px 28px;
  opacity: 0.45;
  pointer-events: none;
}

/* ── Decorative floating cubes ── */
.deco-cubes {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.deco-cube {
  position: absolute;
  width: 40px;
  height: 40px;
  transform-style: preserve-3d;
  transform: rotateX(45deg) rotateZ(-45deg);
}

.deco-cube--a {
  top: 8%;
  left: 6%;
  opacity: 0.35;
  transform: rotateX(45deg) rotateZ(-45deg) scale(2.5);
}
.deco-cube--b {
  top: 65%;
  right: 5%;
  opacity: 0.25;
  transform: rotateX(45deg) rotateZ(-45deg) scale(3.5);
}
.deco-cube--c {
  top: 30%;
  right: 12%;
  opacity: 0.2;
  transform: rotateX(45deg) rotateZ(-45deg) scale(1.8);
}

.face {
  position: absolute;
  width: 40px;
  height: 40px;
}

.face--top {
  background: var(--iso-indigo);
  transform: rotateX(90deg) translateZ(20px);
}

.face--left {
  background: var(--iso-indigo-dark);
  transform: rotateY(-90deg) translateZ(0) translateX(-20px);
  width: 40px;
  height: 40px;
  top: 0;
}

.face--right {
  background: var(--iso-indigo-light);
  transform: translateZ(20px);
}

/* ── Page layout ── */
.page {
  position: relative;
  z-index: 1;
  max-width: 860px;
  margin: 0 auto;
  padding: 56px 24px 80px;
}

/* ── Header ── */
.header {
  text-align: center;
  margin-bottom: 64px;
}

.header__badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--iso-indigo);
  background: rgba(92, 107, 192, 0.1);
  border: 1px solid rgba(92, 107, 192, 0.25);
  padding: 4px 12px;
  margin-bottom: 20px;
  border-radius: var(--iso-card-radius);
  text-transform: uppercase;
}

.header__title {
  font-size: clamp(48px, 8vw, 88px);
  font-weight: 700;
  line-height: 1;
  color: var(--iso-text);
  letter-spacing: -0.03em;
}

.header__title span {
  color: var(--iso-indigo);
  display: block;
}

.header__tagline {
  margin-top: 20px;
  font-size: 18px;
  color: var(--iso-text-muted);
  font-weight: 400;
  max-width: 400px;
  margin-inline: auto;
}

/* ── Showcase grid ── */
.showcase {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: start;
}

@media (max-width: 640px) {
  .showcase {
    grid-template-columns: 1fr;
  }
}

/* ── Isometric card ── */
.card-section {
  display: flex;
  justify-content: center;
  padding: 40px 0;
}

.iso-card-wrap {
  position: relative;
  display: inline-block;
}

.iso-card {
  position: relative;
  z-index: 2;
  background: var(--iso-indigo);
  border-radius: var(--iso-card-radius);
  padding: 28px;
  width: 280px;
  color: white;
  /* Isometric stacked shadow gives the 3-face cube illusion */
  box-shadow: -6px 6px 0 var(--iso-indigo-dark), -12px 12px 0 #2e3a8a, -18px 18px 0
    rgba(41, 53, 120, 0.4), 0 24px 48px rgba(57, 73, 171, 0.35);
  cursor: pointer;
  transition: transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.35s ease;
  will-change: transform;
}

.iso-card:hover {
  transform: translate(4px, -4px);
  box-shadow: -10px 10px 0 var(--iso-indigo-dark), -20px 20px 0 #2e3a8a, -26px 26px 0
    rgba(41, 53, 120, 0.3), 0 32px 60px rgba(57, 73, 171, 0.45);
}

.iso-shadow-left {
  position: absolute;
  left: -18px;
  bottom: -18px;
  width: 100%;
  height: 100%;
  background: rgba(46, 58, 138, 0.15);
  border-radius: var(--iso-card-radius);
  z-index: 1;
  transform: skewY(-3deg);
}

.iso-shadow-bottom {
  position: absolute;
  left: 4px;
  bottom: -28px;
  width: 90%;
  height: 20px;
  background: rgba(57, 73, 171, 0.2);
  border-radius: 50%;
  filter: blur(8px);
  z-index: 0;
}

/* ── Card content ── */
.iso-card__top {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}

.avatar {
  flex-shrink: 0;
  border-radius: var(--iso-card-radius);
  overflow: hidden;
  border: 2px solid rgba(255, 255, 255, 0.2);
}

.profile-name {
  font-size: 18px;
  font-weight: 700;
  color: #fff;
}

.profile-role {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.7);
  margin-top: 2px;
  font-weight: 500;
}

.iso-card__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  border-top: 1px solid rgba(255, 255, 255, 0.15);
  padding-top: 20px;
}

.stat {
  text-align: center;
}

.stat__value {
  display: block;
  font-size: 22px;
  font-weight: 700;
  color: #fff;
  letter-spacing: -0.02em;
}

.stat__label {
  display: block;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.6);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 2px;
}

/* ── Controls section ── */
.controls-section {
  display: flex;
  flex-direction: column;
  gap: 32px;
  padding-top: 40px;
}

/* ── Buttons ── */
.button-group {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  font-family: var(--font);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.02em;
  border-radius: var(--iso-card-radius);
  border: none;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.btn--primary {
  background: var(--iso-indigo);
  color: white;
  box-shadow: -3px 3px 0 var(--iso-indigo-dark), -6px 6px 0 rgba(57, 73, 171, 0.4);
}

.btn--primary:hover {
  transform: translate(2px, -2px);
  box-shadow: -5px 5px 0 var(--iso-indigo-dark), -10px 10px 0 rgba(57, 73, 171, 0.35);
}

.btn--primary:active {
  transform: translate(-1px, 1px);
  box-shadow: -1px 1px 0 var(--iso-indigo-dark);
}

.btn--secondary {
  background: rgba(92, 107, 192, 0.12);
  color: var(--iso-indigo);
  border: 1px solid rgba(92, 107, 192, 0.3);
  box-shadow: -3px 3px 0 rgba(92, 107, 192, 0.2);
}

.btn--secondary:hover {
  transform: translate(2px, -2px);
  background: rgba(92, 107, 192, 0.2);
  box-shadow: -5px 5px 0 rgba(92, 107, 192, 0.3);
}

.btn--ghost {
  background: transparent;
  color: var(--iso-indigo);
  border: 2px solid var(--iso-indigo);
}

.btn--ghost:hover {
  background: var(--iso-indigo);
  color: white;
  box-shadow: -3px 3px 0 var(--iso-indigo-dark);
}

/* ── Input ── */
.input-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-label {
  font-size: 12px;
  font-weight: 700;
  color: var(--iso-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.input {
  font-family: var(--font);
  font-size: 14px;
  padding: 11px 14px;
  border: 2px solid var(--iso-border);
  border-radius: var(--iso-card-radius);
  background: white;
  color: var(--iso-text);
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  box-shadow: -3px 3px 0 var(--iso-border);
}

.input:focus {
  border-color: var(--iso-indigo);
  box-shadow: -4px 4px 0 rgba(92, 107, 192, 0.3);
}

.input::placeholder {
  color: #a0a8c0;
}

/* ── Badges ── */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: var(--iso-card-radius);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.badge--indigo {
  background: rgba(92, 107, 192, 0.15);
  color: var(--iso-indigo);
  border: 1px solid rgba(92, 107, 192, 0.3);
}

.badge--blue {
  background: rgba(66, 165, 245, 0.12);
  color: #1976d2;
  border: 1px solid rgba(66, 165, 245, 0.3);
}

.badge--cyan {
  background: rgba(38, 198, 218, 0.12);
  color: #00838f;
  border: 1px solid rgba(38, 198, 218, 0.3);
}

.badge--dark {
  background: rgba(26, 31, 58, 0.08);
  color: var(--iso-text);
  border: 1px solid rgba(26, 31, 58, 0.15);
}

