/* ============================================================
   NEUMORPHISM — Soft UI Design Showcase
   Base color: #E0E5EC — everything extrudes from this surface
   ============================================================ */

:root {
  --bg: #e0e5ec;
  --shadow-light: rgba(255, 255, 255, 0.8);
  --shadow-dark: rgba(163, 177, 198, 0.6);
  --shadow-light-strong: rgba(255, 255, 255, 0.9);
  --shadow-dark-strong: rgba(163, 177, 198, 0.75);

  /* Raised (convex) shadow */
  --neu-raised: -6px -6px 14px var(--shadow-light), 6px 6px 14px var(--shadow-dark);
  --neu-raised-sm: -3px -3px 8px var(--shadow-light), 3px 3px 8px var(--shadow-dark);
  --neu-raised-lg: -10px -10px 24px var(--shadow-light-strong), 10px 10px 24px
    var(--shadow-dark-strong);

  /* Pressed (concave / inset) shadow */
  --neu-pressed: inset -4px -4px 10px var(--shadow-light), inset 4px 4px 10px var(--shadow-dark);
  --neu-pressed-sm: inset -2px -2px 6px var(--shadow-light), inset 2px 2px 6px var(--shadow-dark);

  /* Typography */
  --text-primary: #2d4356;
  --text-muted: #6d8a96;
  --text-light: #9aabb5;

  /* Accent */
  --accent: #6c63ff;
  --accent-alt: #4a90d9;

  --radius-card: 20px;
  --radius-pill: 50px;
  --font: "Poppins", sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
}

body {
  font-family: var(--font);
  background-color: var(--bg);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 0 60px;
}

/* ── Header ── */
.neu-header {
  width: 100%;
  padding: 28px 40px 24px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 18px;
}

.logo-mark {
  width: 52px;
  height: 52px;
  border-radius: 14px;
  background: var(--bg);
  box-shadow: var(--neu-raised);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  flex-shrink: 0;
}

.header-title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.5px;
  color: var(--text-primary);
}

.header-tagline {
  font-size: 0.8rem;
  font-weight: 400;
  color: var(--text-muted);
  letter-spacing: 0.5px;
  margin-top: 1px;
}

/* ── Main layout ── */
.page-main {
  display: flex;
  flex-direction: column;
  gap: 28px;
  width: 100%;
  max-width: 460px;
  padding: 0 24px;
}

/* ── Cards ── */
.neu-card {
  background: var(--bg);
  border-radius: var(--radius-card);
  box-shadow: var(--neu-raised-lg);
  padding: 28px 28px 24px;
}

.card-label {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--text-light);
  margin-bottom: 20px;
}

/* ── Profile Card ── */
.profile-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 36px 28px 28px;
}

.avatar-wrap {
  position: relative;
  width: 88px;
  height: 88px;
}

.avatar {
  width: 88px;
  height: 88px;
  border-radius: 50%;
  background: var(--bg);
  box-shadow: var(--neu-raised-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  position: relative;
  z-index: 1;
  transition: box-shadow 0.3s ease;
}

.avatar-ring {
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  border: 2px solid transparent;
  background: linear-gradient(135deg, var(--accent), var(--accent-alt)) border-box;
  -webkit-mask: linear-gradient(#fff 0 0) padding-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: destination-out;
  mask-composite: exclude;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.avatar-wrap:hover .avatar-ring {
  opacity: 1;
}
.avatar-wrap:hover .avatar {
  box-shadow: var(--neu-pressed);
}

.profile-name {
  font-size: 1.3rem;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.3px;
}

.profile-role {
  font-size: 0.82rem;
  color: var(--text-muted);
  font-weight: 400;
  margin-top: -10px;
}

.profile-stats {
  display: flex;
  align-items: center;
  gap: 0;
  background: var(--bg);
  border-radius: 14px;
  box-shadow: var(--neu-pressed-sm);
  padding: 14px 20px;
  width: 100%;
  justify-content: space-around;
}

.stat-pill {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-value {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.5px;
}

.stat-label {
  font-size: 0.68rem;
  color: var(--text-light);
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.stat-divider {
  width: 1px;
  height: 32px;
  background: linear-gradient(to bottom, transparent, rgba(163, 177, 198, 0.5), transparent);
}

/* ── Buttons ── */
.buttons-card {
}

.button-row {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font);
  font-size: 0.82rem;
  font-weight: 500;
  padding: 12px 22px;
  border-radius: var(--radius-pill);
  border: none;
  cursor: pointer;
  background: var(--bg);
  color: var(--text-primary);
  letter-spacing: 0.3px;
  transition: box-shadow 0.2s ease, transform 0.15s ease, color 0.2s ease;
  outline: none;
}

/* Convex — raised, pops out */
.btn-convex {
  box-shadow: var(--neu-raised);
  color: var(--accent);
}

.btn-convex:hover {
  box-shadow: -4px -4px 10px var(--shadow-light), 4px 4px 10px var(--shadow-dark);
}

.btn-convex:active,
.btn-convex.active {
  box-shadow: var(--neu-pressed);
  color: var(--accent);
  transform: scale(0.98);
}

/* Concave — pressed in */
.btn-concave {
  box-shadow: var(--neu-pressed);
