/* ============================================================
   BRUTALISM — Raw Web Design Showcase
   Hard borders, offset shadows, zero radius, clashing colors
   ============================================================ */

:root {
  --black: #000000;
  --white: #ffffff;
  --yellow: #ffed00;
  --blue: #0000ff;
  --red: #ff0000;

  /* Hard shadow — zero blur, black offset */
  --shadow-sm: 4px 4px 0 var(--black);
  --shadow-md: 6px 6px 0 var(--black);
  --shadow-lg: 8px 8px 0 var(--black);
  --shadow-xl: 10px 10px 0 var(--black);

  /* Typography */
  --font-head: "Arial Black", "Impact", "Haettenschweiler", sans-serif;
  --font-mono: "Courier New", "Courier", monospace;
  --font-body: Arial, Helvetica, sans-serif;

  /* Borders */
  --border: 3px solid var(--black);
  --border-thick: 4px solid var(--black);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  background-color: var(--yellow);
  color: var(--black);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 0 60px;
  overflow-x: hidden;
}

/* ── Header ── */
.brut-header {
  width: 100%;
  max-width: 560px;
  padding-top: 20px;
}

/* Scrolling tape strip */
.header-tape {
  width: 100%;
  background: var(--black);
  color: var(--yellow);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 1px;
  padding: 6px 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: clip;
  animation: tape-scroll 18s linear infinite;
}

@keyframes tape-scroll {
  from {
    text-indent: 0;
  }
  to {
    text-indent: -600px;
  }
}

.header-content {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 24px 24px 20px;
}

.header-mark {
  width: 64px;
  height: 64px;
  background: var(--white);
  border: var(--border-thick);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-head);
  font-size: 2.2rem;
  color: var(--black);
  flex-shrink: 0;
}

.header-title {
  font-family: var(--font-head);
  font-size: 3rem;
  letter-spacing: -1px;
  color: var(--black);
  line-height: 1;
  text-transform: uppercase;
}

.header-tagline {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--black);
  opacity: 0.7;
  margin-top: 4px;
  letter-spacing: 0.3px;
}

/* ── Main layout ── */
.page-main {
  display: flex;
  flex-direction: column;
  gap: 28px;
  width: 100%;
  max-width: 560px;
  padding: 0 24px;
}

/* ── Cards ── */
.brut-card {
  background: var(--white);
  border: var(--border-thick);
  box-shadow: var(--shadow-lg);
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}

/* Slight rotations — collage feel */
#card-profile {
  transform: rotate(-0.8deg);
}
#card-buttons {
  transform: rotate(0.5deg);
}
#card-input {
  transform: rotate(-0.3deg);
}
#card-badges {
  transform: rotate(0.7deg);
}

.brut-card:hover {
  transform: rotate(0deg) translate(-3px, -3px) !important;
  box-shadow: var(--shadow-xl);
}

.card-header-strip {
  background: var(--black);
  color: var(--yellow);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 2px;
  padding: 5px 14px;
  text-transform: uppercase;
  border-bottom: var(--border-thick);
}

.card-body {
  padding: 20px 20px 18px;
}

/* ── Profile Card ── */
.profile-row {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 16px;
}

.avatar {
  width: 72px;
  height: 72px;
  background: var(--yellow);
  border: var(--border-thick);
  box-shadow: var(--shadow-sm);
