  text-transform: uppercase;
}

.profile-role {
  font-family: var(--font-mono);
  font-size: 0.76rem;
  color: var(--black);
  opacity: 0.65;
  margin-top: 5px;
}

.profile-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  border: var(--border-thick);
}

.stat-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 8px;
  border-right: var(--border);
  background: var(--white);
}

.stat-box:last-child {
  border-right: none;
}

.stat-box-yellow {
  background: var(--yellow);
}
.stat-box-blue {
  background: var(--blue);
}
.stat-box-blue .stat-value,
.stat-box-blue .stat-label {
  color: var(--white);
}

.stat-value {
  font-family: var(--font-head);
  font-size: 1.5rem;
  color: var(--black);
  line-height: 1;
}

.stat-label {
  font-family: var(--font-mono);
  font-size: 0.58rem;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--black);
  opacity: 0.65;
  margin-top: 3px;
}

/* ── Buttons ── */
.button-row {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  font-family: var(--font-head);
  font-size: 0.95rem;
  letter-spacing: 1px;
  padding: 11px 20px;
  border: var(--border-thick);
  cursor: pointer;
  text-transform: uppercase;
  box-shadow: var(--shadow-md);
  transition: transform 0.1s ease, box-shadow 0.1s ease;
  outline: none;
  position: relative;
}

.btn:hover {
  transform: translate(-3px, -3px);
  box-shadow: var(--shadow-xl);
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.btn-black {
  background: var(--black);
  color: var(--white);
}

.btn-yellow {
  background: var(--yellow);
  color: var(--black);
}

.btn-ghost {
  background: var(--white);
  color: var(--black);
}

.btn:focus-visible {
  outline: 3px solid var(--blue);
  outline-offset: 2px;
}

/* ── Input ── */
.input-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-label {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--black);
}

.input-wrap {
  display: flex;
  align-items: center;
  border: var(--border-thick);
  box-shadow: var(--shadow-sm);
  background: var(--white);
  transition: box-shadow 0.12s ease;
}

.input-wrap:focus-within {
  box-shadow: var(--shadow-md);
}

.input-prefix {
  font-family: var(--font-mono);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--black);
  padding: 0 10px 0 14px;
  flex-shrink: 0;
  user-select: none;
}

.brut-input {
  flex: 1;
  background: transparent;
  border: none;
  padding: 12px 8px 12px 0;
  font-family: var(--font-mono);
  font-size: 0.9rem;
  color: var(--black);
  outline: none;
  letter-spacing: 0.5px;
}

.brut-input::placeholder {
  color: var(--black);
  opacity: 0.35;
