  }
  .avatar-initials {
    font-size: 1.2rem;
  }
  .profile-name {
    font-size: 1.1rem;
  }
  .stat-value {
    font-size: 1.2rem;
  }
  .stat-label {
    font-size: 0.52rem;
  }
  .stat-box {
    padding: 10px 4px;
  }
  .badge {
    font-size: 0.6rem;
