/* ============================================================
   Brutalism — Interactive Effects
   Button shadow lift, badge color flip, tape glitch, cursor blink
   ============================================================ */

(function () {
  "use strict";

  // ── Button: amplified hard-shadow lift on hover ─────────────
  // CSS handles hover already, but JS adds a satisfying "thud" on click
  const buttons = document.querySelectorAll(".btn");

  buttons.forEach((btn) => {
    btn.addEventListener("click", function (e) {
      // Flash white border briefly
      btn.style.outline = "3px solid #0000FF";
      btn.style.outlineOffset = "0px";
      setTimeout(() => {
        btn.style.outline = "";
        btn.style.outlineOffset = "";
      }, 250);

      // Spawn a small "✓" confirmation text
      const confirm = document.createElement("span");
      confirm.textContent = "OK";
      confirm.style.cssText = `
        position: fixed;
        left: ${e.clientX + 10}px;
        top: ${e.clientY - 20}px;
        font-family: 'Courier New', monospace;
        font-size: 0.75rem;
        font-weight: 700;
        color: #000;
        background: #FFED00;
        border: 2px solid #000;
        padding: 2px 6px;
        pointer-events: none;
        z-index: 9999;
        animation: brut-pop 0.5s ease-out forwards;
      `;
      document.body.appendChild(confirm);
      confirm.addEventListener("animationend", () => confirm.remove());
    });
  });

  // Inject pop animation
  const style = document.createElement("style");
  style.textContent = `
    @keyframes brut-pop {
      0%   { opacity: 1; transform: translateY(0) scale(1); }
      100% { opacity: 0; transform: translateY(-20px) scale(0.8); }
    }
  `;
  document.head.appendChild(style);

  // ── Badge: click to cycle through states ───────────────────
  const badges = document.querySelectorAll(".badge");
  const badgeCycles = [null, "badge-invert", "badge-yellow", "badge-blue"];

  badges.forEach((badge) => {
    let idx = badgeCycles.findIndex((cls) => cls && badge.classList.contains(cls));
    if (idx === -1) idx = 0;

    badge.addEventListener("click", () => {
      badgeCycles.forEach((cls) => {
        if (cls) badge.classList.remove(cls);
      });
      idx = (idx + 1) % badgeCycles.length;
      if (badgeCycles[idx]) badge.classList.add(badgeCycles[idx]);
    });
  });

  // ── Header tape: pause on hover ────────────────────────────
  const tape = document.querySelector(".header-tape");
  if (tape) {
    tape.addEventListener("mouseenter", () => {
      tape.style.animationPlayState = "paused";
      tape.style.background = "#0000FF";
    });
    tape.addEventListener("mouseleave", () => {
      tape.style.animationPlayState = "running";
      tape.style.background = "#000";
    });
  }

  // ── Input: glitch effect on focus ──────────────────────────
  const input = document.getElementById("brut-input");

  if (input) {
    input.addEventListener("focus", () => {
      const wrap = input.closest(".input-wrap");
      if (!wrap) return;

      let glitchCount = 0;
      const colors = ["#FFED00", "#0000FF", "#FF0000", "#000"];
      const interval = setInterval(() => {
        wrap.style.boxShadow = `${4 + glitchCount}px ${4 + glitchCount}px 0 ${colors[glitchCount % colors.length]}`;
        glitchCount++;
        if (glitchCount >= colors.length) {
          clearInterval(interval);
          wrap.style.boxShadow = "";
        }
      }, 60);
    });
  }

  // ── Card: drag-to-wobble on mousedown ──────────────────────
  const cards = document.querySelectorAll(".brut-card");

  cards.forEach((card) => {
    card.addEventListener("mousedown", (e) => {
      const rect = card.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const isLeft = e.clientX < cx;
      const deg = isLeft ? -2 : 2;

      card.style.transition = "transform 0.08s ease";
      card.style.transform = `rotate(${deg}deg) translate(-2px, -2px)`;
      card.style.boxShadow = "10px 10px 0 #000";
    });

    card.addEventListener("mouseup", () => {
      card.style.transition = "transform 0.2s ease, box-shadow 0.2s ease";
      card.style.transform = "";
      card.style.boxShadow = "";
    });

    card.addEventListener("mouseleave", () => {
      card.style.transition = "transform 0.2s ease, box-shadow 0.2s ease";
      card.style.transform = "";
      card.style.boxShadow = "";
    });
  });
})();

snippets.css:
:root {
  --au-text: rgba(255, 255, 255, 0.95);
  --au-text-muted: rgba(255, 255, 255, 0.6);
  --au-glass-bg: rgba(255, 255, 255, 0.2);
  --au-glass-border: rgba(255, 255, 255, 0.3);
  --au-glass-hover: rgba(255, 255, 255, 0.28);
  --au-radius: 20px;
  --font: "Plus Jakarta Sans", system-ui, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  min-height: 100vh;
  overflow-x: hidden;
  position: relative;
  color: var(--au-text);
  /* Animated aurora gradient mesh */
  background: linear-gradient(135deg, #0ea5e9 0%, #8b5cf6 33%, #ec4899 66%, #f59e0b 100%);
  background-size: 400% 400%;
  animation: aurora 8s ease infinite;
}

@keyframes aurora {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}

/* ── Aurora streaks ── */
.aurora-streaks {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
}

.streak {
  position: absolute;
  border-radius: 50%;
  filter: blur(70px);
  opacity: 0.45;
  animation: streakPulse 6s ease-in-out infinite;
  will-change: transform;
}

.streak--1 {
  width: 600px;
  height: 200px;
  background: rgba(255, 255, 255, 0.25);
  top: 10%;
  left: -10%;
  transform: rotate(-20deg);
  animation-delay: 0s;
}

.streak--2 {
  width: 700px;
  height: 150px;
  background: rgba(251, 191, 36, 0.3);
  top: 35%;
  right: -15%;
  transform: rotate(15deg);
  animation-delay: 1.5s;
}

.streak--3 {
  width: 500px;
  height: 180px;
  background: rgba(167, 139, 250, 0.35);
  bottom: 25%;
  left: 5%;
  transform: rotate(-10deg);
  animation-delay: 3s;
}

.streak--4 {
  width: 400px;
  height: 120px;
  background: rgba(34, 211, 238, 0.3);
  bottom: 10%;
  right: 10%;
  transform: rotate(25deg);
  animation-delay: 2s;
}

@keyframes streakPulse {
  0%,
  100% {
    opacity: 0.4;
    transform-origin: center;
  }
  50% {
    opacity: 0.65;
  }
}

/* ── Page ── */
.page {
  position: relative;
  z-index: 1;
  max-width: 760px;
  margin: 0 auto;
  padding: 60px 24px 80px;
  display: flex;
  flex-direction: column;
  gap: 32px;
}

/* ── Header ── */
.header {
  text-align: center;
}

.header__chip {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--au-text-muted);
  background: var(--au-glass-bg);
  border: 1px solid var(--au-glass-border);
  padding: 6px 18px;
  border-radius: 100px;
  margin-bottom: 24px;
  backdrop-filter: blur(10px);
}

.header__title {
  font-size: clamp(52px, 10vw, 96px);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.04em;
  color: white;
  text-shadow: 0 2px 20px rgba(0, 0, 0, 0.15);
}

.header__title span {
  display: block;
  color: rgba(255, 255, 255, 0.75);
  font-weight: 300;
}

.header__tagline {
  margin-top: 20px;
  font-size: 17px;
  font-weight: 300;
  color: var(--au-text-muted);
  line-height: 1.6;
}

/* ── Glass card ── */
.aurora-card {
  background: var(--au-glass-bg);
  backdrop-filter: blur(16px) saturate(150%);
  -webkit-backdrop-filter: blur(16px) saturate(150%);
  border: 1px solid var(--au-glass-border);
  border-radius: var(--au-radius);
  padding: 28px;
  transition: background 0.3s ease, border-color 0.3s ease;
}

.aurora-card:hover {
  background: var(--au-glass-hover);
  border-color: rgba(255, 255, 255, 0.4);
}

/* ── Profile card ── */
.card-section {
  display: flex;
  justify-content: center;
}

.profile-card {
  width: 100%;
  max-width: 400px;
}

.card__top {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}

.avatar {
  flex-shrink: 0;
  border-radius: 18px;
  overflow: hidden;
}

.card__info {
  flex: 1;
}

.card__name {
  font-size: 18px;
  font-weight: 700;
  color: white;
  letter-spacing: -0.01em;
}

.card__role {
  font-size: 13px;
  color: var(--au-text-muted);
  margin-top: 3px;
  font-weight: 400;
}

.card__glow-badge {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: white;
  background: rgba(255, 255, 255, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.4);
  padding: 4px 10px;
  border-radius: 100px;
  backdrop-filter: blur(8px);
}

.card__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.stat {
  text-align: center;
  padding: 14px 8px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.15);
  transition: background 0.2s ease, transform 0.2s ease;
}

.stat:hover {
  background: rgba(255, 255, 255, 0.18);
  transform: translateY(-2px);
}

.stat__value {
  display: block;
  font-size: 24px;
  font-weight: 800;
  color: white;
  letter-spacing: -0.03em;
}

.stat__label {
  display: block;
  font-size: 11px;
  color: var(--au-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 3px;
  font-weight: 500;
}

/* ── Controls card ── */
.controls-card {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ── Buttons ── */
.button-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.btn {
  font-family: var(--font);
  font-size: 14px;
  font-weight: 700;
  padding: 12px 22px;
  border-radius: 10px;
  border: none;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
  letter-spacing: 0.01em;
}

.btn--white {
  background: white;
  color: #1a0a2e;
}

.btn--white:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 35px rgba(255, 255, 255, 0.35);
}

.btn--white:active {
  transform: translateY(0);
}

.btn--glass {
  background: var(--au-glass-bg);
  color: white;
  border: 1px solid var(--au-glass-border);
  backdrop-filter: blur(10px);
}

.btn--glass:hover {
  background: var(--au-glass-hover);
  border-color: rgba(255, 255, 255, 0.45);
  transform: translateY(-2px);
}

.btn--ghost {
  background: transparent;
  color: rgba(255, 255, 255, 0.75);
  border: 1.5px solid rgba(255, 255, 255, 0.35);
}

.btn--ghost:hover {
  color: white;
  border-color: white;
  transform: translateY(-2px);
  background: rgba(255, 255, 255, 0.08);
}

/* ── Input ── */
.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field__label {
  font-size: 12px;
  font-weight: 600;
  color: var(--au-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.09em;
}

.aurora-input {
  font-family: var(--font);
  font-size: 14px;
  padding: 13px 16px;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 10px;
  color: white;
  outline: none;
  backdrop-filter: blur(8px);
  transition: background 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
}

.aurora-input:focus {
  background: rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 255, 255, 0.5);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.1);
}

.aurora-input::placeholder {
  color: rgba(255, 255, 255, 0.35);
}

/* ── Badges ── */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.badge {
  display: inline-block;
  font-size: 12px;
  font-weight: 600;
  padding: 5px 14px;
  border-radius: 100px;
  background: rgba(255, 255, 255, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.3);
  color: white;
  backdrop-filter: blur(8px);
  transition: background 0.2s ease, transform 0.2s ease;
}

.badge:hover {
  background: rgba(255, 255, 255, 0.25);
  transform: translateY(-1px);
}

/* ── Responsive ── */
@media (max-width: 520px) {
  .page {
    padding: 32px 16px 48px;
    gap: 24px;
  }

  .header__title {
    font-size: clamp(36px, 12vw, 52px);
  }

  .header__chip {
    font-size: 10px;
    padding: 5px 14px;
    margin-bottom: 16px;
  }

  .header__tagline {
    font-size: 15px;
    margin-top: 14px;
  }

  .aurora-card {
    padding: 20px;
  }

  .profile-card {
    max-width: 100%;
  }

  .card__top {
    gap: 12px;
    margin-bottom: 18px;
  }

  .card__name {
    font-size: 16px;
  }

  .card__stats {
    gap: 8px;
  }

  .stat {
    padding: 10px 4px;
  }

  .stat__value {
    font-size: 20px;
  }

  .stat__label {
    font-size: 10px;
  }

  .button-row {
    gap: 8px;
  }

  .btn {
    font-size: 13px;
    padding: 10px 16px;
  }

  .streak--1 {
    width: 300px;
    height: 120px;
  }
  .streak--2 {
    width: 350px;
    height: 100px;
  }
  .streak--3 {
    width: 250px;
    height: 100px;
  }
  .streak--4 {
    width: 200px;
    height: 80px;
  }
}

