  color: var(--wb-text);
  border: 3px solid var(--wb-text);
  border-radius: 4px;
  box-shadow: 3px 3px 0 rgba(0, 0, 0, 0.12);
}

.btn--marker:hover {
  transform: translate(-1px, -1px);
  box-shadow: 5px 5px 0 rgba(0, 0, 0, 0.15);
}

.btn--blue-sticky {
  background: var(--wb-blue);
  color: #01579b;
  border: 3px solid rgba(1, 87, 155, 0.3);
  border-radius: 4px;
  box-shadow: 3px 3px 0 rgba(0, 0, 0, 0.1);
}

.btn--blue-sticky:hover {
  transform: translate(-1px, -1px);
  box-shadow: 5px 5px 0 rgba(0, 0, 0, 0.12);
}

.btn--ghost-marker {
  background: transparent;
  color: var(--wb-text-muted);
  border: none;
  font-family: var(--font-hand);
  font-size: 16px;
  text-decoration: underline;
  text-underline-offset: 3px;
  padding: 8px 4px;
}

.btn--ghost-marker:hover {
  color: var(--wb-text);
}

/* ── Textarea input ── */
.board-input {
  font-family: var(--font-hand);
  font-size: 15px;
  width: 100%;
  padding: 8px 10px;
  border: none;
  border-bottom: 2px solid rgba(0, 0, 0, 0.2);
  background: transparent;
  color: var(--wb-text);
  outline: none;
  resize: none;
  line-height: 1.5;
}

.board-input::placeholder {
  color: rgba(0, 0, 0, 0.4);
  font-style: italic;
}

.board-input:focus {
  border-bottom-color: rgba(0, 0, 0, 0.5);
}

/* ── Badges ── */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.badge {
  font-family: var(--font-hand);
  font-size: 13px;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 3px;
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.badge:hover {
  transform: rotate(-2deg) scale(1.08);
}

.badge--yellow {
  background: #fff176;
  color: #f57f17;
  border: 1.5px solid rgba(245, 127, 23, 0.3);
}
.badge--blue {
  background: #81d4fa;
  color: #01579b;
  border: 1.5px solid rgba(1, 87, 155, 0.2);
}
.badge--pink {
  background: #f48fb1;
  color: #880e4f;
  border: 1.5px solid rgba(136, 14, 79, 0.2);
}
.badge--green {
  background: #a5d6a7;
  color: #1b5e20;
  border: 1.5px solid rgba(27, 94, 32, 0.2);
}

/* ── Draggable sticky ── */
.draggable-sticky {
  position: absolute;
  top: 320px;
  right: 48px;
  width: 200px;
  cursor: grab;
  user-select: none;
  z-index: 10;
  transition: box-shadow 0.15s ease;
}

.draggable-sticky:active {
  cursor: grabbing;
  box-shadow: 8px 12px 28px rgba(0, 0, 0, 0.25), 0 2px 6px rgba(0, 0, 0, 0.12);
}

.drag-label {
  font-family: var(--font-hand);
  font-size: 18px;
  font-weight: 700;
  color: var(--wb-text);
  margin-bottom: 8px;
}

.drag-sub {
  font-family: var(--font-hand);
  font-size: 14px;
  color: var(--wb-text-muted);
  line-height: 1.4;
}

