/* ─────────────────────────────────────────────
   Flat Design — style.css
   Zero shadows. Zero gradients. Bold geometry.
   Palette: coral, teal, yellow, near-black, near-white
───────────────────────────────────────────── */

:root {
  --coral: #ff6b6b;
  --coral-dark: #e85555;
  --teal: #4ecdc4;
  --teal-dark: #3ab7af;
  --yellow: #ffe66d;
  --yellow-dark: #f5d84a;
  --dark: #292f36;
  --white: #f7fff7;
  --bg: #f7fff7;

  --text-primary: #292f36;
  --text-secondary: #555d63;
  --text-on-color: #ffffff;

  --font: "Nunito", system-ui, sans-serif;
  --radius-pill: 999px;
  --radius-md: 12px;

  --space-xs: 8px;
  --space-sm: 16px;
  --space-md: 32px;
  --space-lg: 56px;
  --space-xl: 72px;
}

/* ── Reset ── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text-primary);
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

/* ── Header ── */
.site-header {
  background: var(--dark);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: 720px;
  margin: 0 auto;
  padding: 16px var(--space-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
