/* ============================================================
   NES RETRO / PIXEL — Style Showcase
   Font: Press Start 2P (Google Fonts)
   Palette: #00FF7F | #FF4500 | #4169E1 | #FFD700 | #FFFFFF
   ============================================================ */

@import url("https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap");

/* --- Root variables --- */
:root {
  --green: #00ff7f;
  --red: #ff4500;
  --blue: #4169e1;
  --gold: #ffd700;
  --white: #ffffff;
  --bg: #0b0b0b;
  --panel: #1a1a2e;
  --text: #e8e8e8;
  --muted: #888888;
  --font: "Press Start 2P", monospace;
}

/* --- Reset & base --- */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
}

html {
  font-size: 16px;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 8px;
  line-height: 1.8;
  min-height: 100vh;
  position: relative;
  overflow-x: hidden;
}

/* CRT Scanlines overlay */
body::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9999;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0px,
    transparent 2px,
    rgba(0, 0, 0, 0.15) 3px,
    rgba(0, 0, 0, 0.15) 4px
  );
}

/* --- Scrollbar --- */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-track {
  background: var(--panel);
}
::-webkit-scrollbar-thumb {
  background: var(--green);
}

/* --- Header --- */
.site-header {
  border-bottom: 4px solid var(--green);
  background: var(--panel);
  box-shadow: 0 4px 0 var(--green);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: 900px;
  margin: 0 auto;
  padding: 12px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.header-logo {
  font-size: 10px;
  color: var(--green);
  display: flex;
  align-items: center;
  gap: 8px;
  text-shadow: 2px 2px 0 #004d30;
}

.pixel-icon {
  color: var(--gold);
  font-size: 12px;
}

.header-nav {
  display: flex;
  gap: 16px;
}

.nav-link {
  color: var(--muted);
  text-decoration: none;
  font-size: 8px;
  padding: 4px 8px;
  border: 2px solid transparent;
  transition: color 0.1s, border-color 0.1s;
}

.nav-link:hover,
.nav-active {
  color: var(--green);
  border: 2px solid var(--green);
  box-shadow: 2px 2px 0 var(--green);
}

.lives-display {
  display: flex;
  gap: 4px;
}

.heart {
  color: var(--red);
  font-size: 14px;
  text-shadow: 2px 2px 0 #7a1500;
  animation: pulse-heart 1.5s ease-in-out infinite;
}

.heart:nth-child(2) {
  animation-delay: 0.3s;
}
.heart:nth-child(3) {
  animation-delay: 0.6s;
}

@keyframes pulse-heart {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.2);
  }
}

/* --- Hero --- */
.hero {
  text-align: center;
  padding: 48px 20px 40px;
  position: relative;
  background: linear-gradient(180deg, #0b0b0b 0%, #1a1a2e 100%);
  border-bottom: 4px solid var(--green);
}

.hero-tagline {
  color: var(--gold);
  font-size: 8px;
  letter-spacing: 0.1em;
  margin-bottom: 20px;
  animation: blink 1.2s step-end infinite;
}

.hero-title {
  font-size: clamp(18px, 4vw, 36px);
  color: var(--green);
  line-height: 1.4;
  text-shadow: 4px 4px 0 #004d30, 8px 8px 0 rgba(0, 255, 127, 0.15);
  margin-bottom: 16px;
}

.hero-sub {
  color: var(--blue);
  font-size: 8px;
  margin-bottom: 20px;
  text-shadow: 2px 2px 0 #1a2e7a;
}

.blink-cursor {
  color: var(--green);
  font-size: 20px;
  animation: blink 0.8s step-end infinite;
}

@keyframes blink {
  0%,
  49% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0;
  }
}

/* --- Main content --- */
.main-content {
  max-width: 900px;
  margin: 0 auto;
  padding: 32px 20px 80px;
  display: flex;
  flex-direction: column;
  gap: 28px;
}

/* --- Card --- */
.card {
  background: var(--panel);
  border: 4px solid var(--green);
  box-shadow: 4px 4px 0 var(--green);
  padding: 0;
}

.card-title-bar {
  background: var(--green);
  color: var(--bg);
  font-size: 8px;
  padding: 8px 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  letter-spacing: 0.05em;
}

.title-bar-icon {
  font-size: 8px;
  flex-shrink: 0;
}

/* --- Profile card --- */
.profile-body {
  padding: 20px;
  display: flex;
  gap: 20px;
  align-items: flex-start;
  flex-wrap: wrap;
}

/* Pixel avatar */
.avatar-wrap {
  flex-shrink: 0;
}

.avatar {
  display: grid;
  gap: 0;
  border: 4px solid var(--green);
  box-shadow: 4px 4px 0 var(--gold);
}

.px-row {
  display: flex;
}

.px {
  width: 12px;
  height: 12px;
  display: block;
}

.px.dark {
  background: #0b0b0b;
}
.px.skin {
  background: #f4a460;
}
.px.blue {
  background: var(--blue);
}

.profile-info {
  flex: 1;
  min-width: 200px;
}

.profile-name {
  font-size: 12px;
  color: var(--green);
  text-shadow: 2px 2px 0 #004d30;
  margin-bottom: 8px;
}

.profile-role {
  font-size: 8px;
  color: var(--gold);
  margin-bottom: 16px;
}

/* HP bar */
.hp-bar-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 16px;
}

.hp-label {
  font-size: 8px;
  color: var(--red);
  flex-shrink: 0;
  text-shadow: 1px 1px 0 #7a1500;
}

.hp-track {
  flex: 1;
  height: 12px;
  background: #0b0b0b;
  border: 2px solid var(--red);
  position: relative;
  overflow: hidden;
}

.hp-fill {
  height: 100%;
  background: repeating-linear-gradient(
    90deg,
    var(--red) 0px,
    var(--red) 8px,
    #7a1500 8px,
    #7a1500 10px
  );
  transition: width 0.3s steps(10);
}

.hp-val {
  font-size: 7px;
  color: var(--muted);
  flex-shrink: 0;
}

/* Profile stats */
.profile-stats {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.stat-box {
  background: #0b0b0b;
  border: 2px solid var(--gold);
  padding: 8px 12px;
  text-align: center;
  box-shadow: 2px 2px 0 var(--gold);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-num {
  font-size: 10px;
  color: var(--gold);
  display: block;
}

.stat-lbl {
  font-size: 7px;
  color: var(--muted);
  display: block;
}

/* --- Buttons --- */
.button-row {
  padding: 20px;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
}

.btn {
  font-family: var(--font);
  font-size: 8px;
  cursor: pointer;
  border: none;
  padding: 12px 20px;
  letter-spacing: 0.04em;
  transition: transform 0.05s, box-shadow 0.05s;
  user-select: none;
  position: relative;
  outline: none;
}

.btn:focus-visible {
  outline: 2px dashed var(--gold);
  outline-offset: 4px;
}

/* Primary */
.btn-primary {
  background: var(--green);
  color: #0b0b0b;
  box-shadow: 4px 4px 0 #004d30;
}

.btn-primary:hover {
  background: #00e873;
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 #004d30;
}

.btn-primary:active,
.btn-primary.pressed {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #004d30;
}

/* Secondary */
.btn-secondary {
  background: var(--blue);
  color: var(--white);
  box-shadow: 4px 4px 0 #1a2e7a;
}

.btn-secondary:hover {
  background: #5a7de8;
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 #1a2e7a;
}

.btn-secondary:active,
.btn-secondary.pressed {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #1a2e7a;
}

/* Ghost */
.btn-ghost {
  background: transparent;
  color: var(--gold);
  border: 4px solid var(--gold);
  box-shadow: 4px 4px 0 #7a5c00;
}

.btn-ghost:hover {
  background: rgba(255, 215, 0, 0.1);
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 #7a5c00;
}

.btn-ghost:active,
.btn-ghost.pressed {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #7a5c00;
}

/* --- Input --- */
.input-group {
  padding: 20px;
}

.input-label {
  display: block;
  font-size: 8px;
  color: var(--green);
  margin-bottom: 10px;
  letter-spacing: 0.08em;
}

.input-wrap {
  position: relative;
  display: inline-block;
  width: 100%;
}

.pixel-input {
  font-family: var(--font);
  font-size: 9px;
  background: #0b0b0b;
  color: var(--green);
  border: 4px solid var(--green);
  padding: 10px 14px 10px 14px;
  width: 100%;
  max-width: 360px;
  box-shadow: inset 2px 2px 0 rgba(0, 0, 0, 0.5);
  caret-color: var(--green);
  outline: none;
}

.pixel-input::placeholder {
  color: var(--muted);
  opacity: 0.6;
}

.pixel-input:focus {
  border-color: var(--gold);
  box-shadow: 0 0 0 2px var(--gold), inset 2px 2px 0 rgba(0, 0, 0, 0.5);
  color: var(--white);
}

.input-hint {
  margin-top: 8px;
  font-size: 7px;
  color: var(--muted);
}

/* --- Badges --- */
.badge-row {
  padding: 20px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.badge {
  font-family: var(--font);
  font-size: 7px;
  padding: 6px 10px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.badge-green {
  background: #004d30;
  color: var(--green);
  border: 2px solid var(--green);
  box-shadow: 2px 2px 0 var(--green);
}

.badge-gold {
  background: #3d2e00;
  color: var(--gold);
  border: 2px solid var(--gold);
  box-shadow: 2px 2px 0 var(--gold);
}

.badge-blue {
  background: #0d1a4a;
  color: #7a9fff;
  border: 2px solid var(--blue);
  box-shadow: 2px 2px 0 var(--blue);
}

.badge-red {
  background: #3d0a00;
  color: #ff7a5a;
  border: 2px solid var(--red);
  box-shadow: 2px 2px 0 var(--red);
}

/* --- Score ticker --- */
.score-ticker {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--green);
  color: #0b0b0b;
  overflow: hidden;
  white-space: nowrap;
  height: 28px;
  display: flex;
  align-items: center;
  border-top: 4px solid #004d30;
  z-index: 50;
}

.ticker-inner {
  display: inline-block;
  font-size: 8px;
  padding-left: 100%;
  animation: ticker 18s linear infinite;
}

@keyframes ticker {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-100%);
  }
}

/* --- Responsive --- */
@media (max-width: 600px) {
  .header-inner {
    flex-wrap: wrap;
    gap: 10px;
  }

  .profile-body {
    flex-direction: column;
  }

  .hero-title {
    font-size: 18px;
  }

  .button-row {
    flex-direction: column;
    align-items: flex-start;
  }

  .btn {
    width: 100%;
    text-align: center;
  }
}

