:root {
  --gd-bg: #080808;
  --gd-blue: rgba(59, 130, 246, 0.3);
  --gd-purple: rgba(139, 92, 246, 0.25);
  --gd-cyan: rgba(6, 182, 212, 0.2);
  --gd-glass-bg: rgba(255, 255, 255, 0.05);
  --gd-glass-border: rgba(255, 255, 255, 0.1);
  --gd-glass-hover: rgba(255, 255, 255, 0.08);
  --gd-text: rgba(255, 255, 255, 0.95);
  --gd-text-muted: rgba(255, 255, 255, 0.45);
  --gd-radius: 20px;
  --font: "Inter", system-ui, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--gd-bg);
  color: var(--gd-text);
  min-height: 100vh;
  overflow-x: hidden;
  position: relative;
}

/* ── Background blobs ── */
.blob {
  position: fixed;
  border-radius: 50%;
  filter: blur(120px);
  pointer-events: none;
  z-index: 0;
  transition: transform 1.5s ease;
}

.blob--blue {
  width: 500px;
  height: 500px;
  background: var(--gd-blue);
  top: -100px;
  left: -100px;
  animation: blobDrift1 18s ease-in-out infinite;
}

.blob--purple {
  width: 600px;
  height: 600px;
  background: var(--gd-purple);
  top: 20%;
  right: -150px;
  animation: blobDrift2 22s ease-in-out infinite;
}

.blob--cyan {
  width: 400px;
  height: 400px;
  background: var(--gd-cyan);
  bottom: -100px;
  left: 30%;
  animation: blobDrift3 16s ease-in-out infinite;
}

@keyframes blobDrift1 {
  0%,
  100% {
    transform: translate(0, 0) scale(1);
  }
  33% {
    transform: translate(60px, 40px) scale(1.05);
  }
  66% {
    transform: translate(-30px, 80px) scale(0.95);
  }
}

@keyframes blobDrift2 {
  0%,
  100% {
    transform: translate(0, 0) scale(1);
  }
  40% {
    transform: translate(-80px, -60px) scale(1.08);
  }
  70% {
    transform: translate(40px, 40px) scale(0.96);
  }
}

@keyframes blobDrift3 {
  0%,
  100% {
    transform: translate(0, 0) scale(1);
  }
  30% {
    transform: translate(-40px, -30px) scale(1.1);
  }
  60% {
    transform: translate(70px, -20px) scale(0.92);
  }
}

/* ── Page ── */
.page {
  position: relative;
  z-index: 1;
  max-width: 760px;
  margin: 0 auto;
  padding: 60px 24px 80px;
  display: flex;
  flex-direction: column;
  gap: 32px;
}

/* ── Header ── */
.header {
  text-align: center;
  margin-bottom: 12px;
}

.header__pill {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gd-text-muted);
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid var(--gd-glass-border);
  padding: 6px 16px;
  border-radius: 100px;
  margin-bottom: 24px;
  backdrop-filter: blur(10px);
}

.header__title {
  font-size: clamp(52px, 10vw, 96px);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.04em;
  color: var(--gd-text);
}

.header__title span {
  color: transparent;
  background: linear-gradient(135deg, #60a5fa, #a78bfa, #22d3ee);
  -webkit-background-clip: text;
  background-clip: text;
}

.header__tagline {
  margin-top: 20px;
  font-size: 16px;
  font-weight: 300;
  color: var(--gd-text-muted);
  letter-spacing: 0.01em;
}

/* ── Glass card ── */
.glass-card {
  background: var(--gd-glass-bg);
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  border: 1px solid var(--gd-glass-border);
  border-radius: var(--gd-radius);
  padding: 28px;
  transition: border-color 0.3s ease, background 0.3s ease;
}

.glass-card:hover {
  border-color: rgba(255, 255, 255, 0.18);
  background: var(--gd-glass-hover);
}

/* ── Profile card ── */
.card-section {
  display: flex;
  justify-content: center;
}

.profile-card {
  width: 100%;
  max-width: 400px;
}

.card__top {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 20px;
}

.avatar {
  flex-shrink: 0;
  border-radius: 16px;
  overflow: hidden;
}

.card__meta {
  flex: 1;
}

.card__name {
  font-size: 18px;
  font-weight: 600;
  color: var(--gd-text);
  letter-spacing: -0.01em;
}

.card__role {
  font-size: 13px;
  color: var(--gd-text-muted);
  margin-top: 3px;
  font-weight: 400;
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 8px #22c55e, 0 0 16px rgba(34, 197, 94, 0.4);
  flex-shrink: 0;
}

.card__divider {
  height: 1px;
  background: var(--gd-glass-border);
  margin: 0 0 20px;
}

.card__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.stat {
  text-align: center;
  padding: 12px 8px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.05);
  transition: background 0.2s ease;
}

.stat:hover {
  background: rgba(255, 255, 255, 0.06);
}

.stat__value {
  display: block;
  font-size: 22px;
  font-weight: 700;
  color: var(--gd-text);
  letter-spacing: -0.02em;
}

.stat__label {
  display: block;
  font-size: 11px;
  color: var(--gd-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 3px;
  font-weight: 500;
}

/* ── Controls card ── */
.controls-card {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ── Buttons ── */
.button-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.btn {
  font-family: var(--font);
  font-size: 14px;
  font-weight: 600;
  padding: 12px 22px;
  border-radius: 10px;
  border: none;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
  letter-spacing: 0.01em;
}

.btn--white {
  background: white;
  color: #0a0a0a;
}

.btn--white:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 30px rgba(255, 255, 255, 0.2);
}

.btn--white:active {
  transform: translateY(0);
}

.btn--glass {
  background: rgba(255, 255, 255, 0.08);
  color: var(--gd-text);
  border: 1px solid var(--gd-glass-border);
  backdrop-filter: blur(10px);
}

.btn--glass:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.2);
  transform: translateY(-1px);
}

.btn--ghost {
  background: transparent;
  color: var(--gd-text-muted);
  border: 1px solid rgba(255, 255, 255, 0.15);
}

.btn--ghost:hover {
  color: var(--gd-text);
  border-color: rgba(255, 255, 255, 0.35);
  transform: translateY(-1px);
}

/* ── Input ── */
.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field__label {
  font-size: 12px;
  font-weight: 500;
  color: var(--gd-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.09em;
}

.glass-input {
  font-family: var(--font);
  font-size: 14px;
  padding: 12px 16px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 10px;
  color: var(--gd-text);
  outline: none;
  transition: border-color 0.25s ease, background 0.25s ease, box-shadow 0.25s ease;
  backdrop-filter: blur(8px);
}

.glass-input:focus {
  border-color: rgba(96, 165, 250, 0.6);
  background: rgba(255, 255, 255, 0.09);
  box-shadow: 0 0 0 3px rgba(96, 165, 250, 0.12);
}

.glass-input::placeholder {
  color: rgba(255, 255, 255, 0.2);
}

/* ── Badges ── */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.badge {
  display: inline-block;
  font-size: 12px;
  font-weight: 500;
  padding: 5px 14px;
  border-radius: 100px;
  border: 1px solid;
  backdrop-filter: blur(8px);
  transition: transform 0.2s ease;
}

.badge:hover {
  transform: translateY(-1px);
}

.badge--blue {
  background: rgba(59, 130, 246, 0.12);
  border-color: rgba(59, 130, 246, 0.3);
  color: #93c5fd;
}
.badge--purple {
  background: rgba(139, 92, 246, 0.12);
  border-color: rgba(139, 92, 246, 0.3);
  color: #c4b5fd;
}
.badge--cyan {
  background: rgba(6, 182, 212, 0.12);
  border-color: rgba(6, 182, 212, 0.3);
  color: #67e8f9;
}
.badge--white {
  background: rgba(255, 255, 255, 0.07);
  border-color: rgba(255, 255, 255, 0.15);
  color: rgba(255, 255, 255, 0.7);
}

/* ── Responsive ── */
@media (max-width: 520px) {
  .page {
    padding: 32px 16px 48px;
    gap: 24px;
  }

  .header__title {
    font-size: clamp(36px, 12vw, 52px);
  }

  .header__pill {
    font-size: 10px;
    padding: 5px 14px;
    margin-bottom: 16px;
  }

  .header__tagline {
    font-size: 14px;
    margin-top: 14px;
  }

  .glass-card {
    padding: 20px;
  }

  .profile-card {
    max-width: 100%;
  }

  .card__top {
    gap: 12px;
    margin-bottom: 16px;
  }

  .card__name {
    font-size: 16px;
  }

  .card__stats {
    gap: 6px;
  }

  .stat {
    padding: 10px 4px;
  }

  .stat__value {
    font-size: 20px;
  }

  .stat__label {
    font-size: 10px;
  }

  .button-row {
    gap: 8px;
  }

  .btn {
    font-size: 13px;
    padding: 10px 16px;
  }

  .blob--blue {
    width: 280px;
    height: 280px;
  }
  .blob--purple {
    width: 320px;
    height: 320px;
  }
  .blob--cyan {
    width: 220px;
    height: 220px;
  }
}

