  font-size: 11px;
  font-weight: 700;
  color: var(--il-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-top: 2px;
}

/* ── Controls ── */
.controls {
  display: flex;
  flex-direction: column;
  gap: 24px;
