  box-shadow: 4px 5px 0 rgba(255, 179, 71, 0.3);
  transform: rotate(0.5deg);
}

.input::placeholder {
  color: #c4a98e;
  font-style: italic;
}

/* ── Badges ── */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.badge {
  font-family: var(--font-hand);
  font-size: 15px;
