*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #f0f0f0;
  --surface: #ffffff;
  --text: #1a1a2e;
  --text-muted: #6b7280;
  --accent: #2563eb;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

/* ── Card ───────────────────────────────────────── */

.geo-card {
  background: var(--surface);
  border-radius: 16px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
  width: 100%;
  max-width: 780px;
  padding: 28px 32px 36px;
}

/* ── Header ─────────────────────────────────────── */

.geo-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 24px;
}

.geo-header__icon {
  width: 36px;
  height: 36px;
  color: #2563eb;
  flex-shrink: 0;
}

.geo-header__icon svg {
  width: 100%;
  height: 100%;
}

.geo-header__accent {
  width: 3px;
  height: 28px;
  background: var(--accent);
  border-radius: 2px;
  flex-shrink: 0;
}

.geo-header__title {
  font-size: 1.2rem;
  font-weight: 700;
  color: #2563eb;
}

/* ── Body layout ────────────────────────────────── */

.geo-body {
  display: flex;
  gap: 24px;
  align-items: flex-start;
}

/* ── Map ─────────────────────────────────────────── */

.geo-map {
  flex: 0 0 44%;
  display: flex;
  align-items: flex-start;
  justify-content: center;
}

.geo-map svg {
  width: 100%;
  height: auto;
}

.geo-map svg path {
  stroke: var(--surface);
  stroke-width: 1;
  cursor: pointer;
  transition: opacity .2s, filter .2s;
}

.geo-map svg path:hover {
  opacity: 0.8;
  filter: brightness(1.15);
}

/* ── Bars ─────────────────────────────────────────── */

.geo-bars {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-top: 4px;
}

.bar-row {
  cursor: default;
  padding: 2px 4px;
  border-radius: 4px;
  transition: background .15s;
}

.bar-row:hover {
  background: rgba(16, 185, 129, 0.06);
}

.bar-name {
  font-size: .85rem;
  font-weight: 500;
  color: var(--text);
  margin-bottom: 2px;
  line-height: 1.2;
}

.bar-fill {
  height: 16px;
  border-radius: 4px;
  transform-origin: left center;
  transform: scaleX(0);
  transition: transform .65s cubic-bezier(0.22, 1, 0.36, 1);
}

.bar-fill.show {
  transform: scaleX(1);
}

/* ── Tooltip ──────────────────────────────────────── */

.geo-tip {
  position: fixed;
  pointer-events: none;
  background: var(--text);
  color: #fff;
  font-size: .75rem;
  font-weight: 500;
  padding: 5px 10px;
  border-radius: 6px;
  white-space: nowrap;
  opacity: 0;
  transition: opacity .15s;
  z-index: 100;
}

.geo-tip.on {
  opacity: 1;
}

/* ── Responsive ───────────────────────────────────── */

@media (max-width: 560px) {
  .geo-body {
    flex-direction: column;
  }

  .geo-map {
    flex: none;
    width: 100%;
  }

  .geo-map svg {
    max-height: 260px;
  }
}

