/* ─────────────────────────────────────────────
   Minimalist UI — style.css
   Palette: white, off-white, near-black, single
   accent blue. No shadows. No gradients.
───────────────────────────────────────────── */

:root {
  --bg: #ffffff;
  --bg-subtle: #fafafa;
  --border: #e5e5e5;
  --text-primary: #111111;
  --text-secondary: #555555;
  --text-tertiary: #999999;
  --accent: #0066ff;
  --accent-hover: #0052cc;
  --badge-bg: #f5f5f5;
  --badge-text: #555555;

  --font: "Inter", system-ui, sans-serif;
  --radius-sm: 4px;
  --radius-md: 8px;

  --space-xs: 8px;
  --space-sm: 16px;
  --space-md: 32px;
  --space-lg: 56px;
  --space-xl: 80px;
}

/* ── Reset ── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text-primary);
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

/* ── Header ── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  max-width: 720px;
  margin: 0 auto;
  padding: var(--space-sm) var(--space-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.header-nav {
  display: flex;
  gap: var(--space-md);
}

.header-nav a {
  font-size: 13px;
