/* ============================================================
   BAUHAUS — Geometric Modernism Design Showcase
   Primary colors + geometric forms + asymmetric grid
   ============================================================ */

:root {
  /* Strict Bauhaus palette */
  --red: #e63329;
  --yellow: #f9c12e;
  --blue: #1b3fdc;
  --black: #1a1a1a;
  --white: #ffffff;
  --cream: #f5f2e8;
  --cream-dark: #eae6d9;

  /* Typography */
  --font-head: "Bebas Neue", "Impact", sans-serif;
  --font-body: "IBM Plex Sans", sans-serif;

  /* No border radius — Bauhaus is square */
  --radius: 0;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
}

body {
  font-family: var(--font-body);
  background-color: var(--cream);
  color: var(--black);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 0 60px;
  position: relative;
  overflow-x: hidden;
}

/* ── Decorative geometric background ── */
.geo-circle {
  position: fixed;
  border-radius: 50%;
  pointer-events: none;
  z-index: 0;
}

.geo-circle-1 {
  width: 380px;
  height: 380px;
  top: -120px;
  right: -80px;
  border: 40px solid var(--yellow);
  opacity: 0.2;
}

.geo-circle-2 {
  width: 200px;
  height: 200px;
  bottom: 80px;
  left: -60px;
  background: var(--blue);
  opacity: 0.08;
}

.geo-rect {
  position: fixed;
  pointer-events: none;
  z-index: 0;
}

.geo-rect-1 {
  width: 6px;
  height: 60vh;
  top: 20vh;
  right: 32px;
  background: var(--red);
  opacity: 0.12;
}

/* ── Header ── */
.bh-header {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 520px;
  padding: 0;
  overflow: hidden;
}

.header-band {
  height: 10px;
  background: linear-gradient(90deg, var(--red) 33.3%, var(--yellow) 33.3% 66.6%, var(--blue) 66.6%);
}

.header-content {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 28px 32px 24px;
}

.header-left {
  flex-shrink: 0;
}

.header-mark {
  position: relative;
  width: 52px;
  height: 52px;
}

.mark-circle {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--red);
}

.mark-line {
  position: absolute;
  bottom: -6px;
  left: 0;
  width: 80px;
  height: 6px;
  background: var(--black);
}

.header-title {
  font-family: var(--font-head);
  font-size: 3.4rem;
  letter-spacing: 6px;
  color: var(--black);
  line-height: 1;
}

.header-tagline {
  font-family: var(--font-body);
  font-size: 0.8rem;
  font-weight: 300;
  color: var(--black);
  letter-spacing: 1.5px;
  text-transform: uppercase;
  margin-top: 4px;
  opacity: 0.65;
}

/* ── Main layout ── */
.page-main {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 24px;
  width: 100%;
  max-width: 520px;
  padding: 24px 32px 0;
}

/* ── Cards ── */
.bh-card {
  background: var(--white);
  border: 2px solid var(--black);
  box-shadow: 5px 5px 0 var(--black);
  overflow: hidden;
}

.card-band {
  height: 10px;
}

.card-band-red {
  background: var(--red);
}
.card-band-yellow {
  background: var(--yellow);
}
.card-band-blue {
  background: var(--blue);
}

.card-body {
  padding: 22px 24px 20px;
}

.card-label {
  font-family: var(--font-body);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: var(--black);
  opacity: 0.45;
  margin-bottom: 18px;
}

/* ── Profile Card ── */
.profile-row {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-bottom: 20px;
}

.avatar {
  width: 72px;
  height: 72px;
  flex-shrink: 0;
  background: var(--cream);
  border: 2px solid var(--black);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.avatar-geo {
  position: relative;
  width: 40px;
  height: 40px;
}

.avatar-circle {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 3px solid var(--black);
}

.avatar-cross {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.avatar-cross span {
  position: absolute;
  background: var(--black);
}

.avatar-cross span:first-child {
  width: 2px;
  height: 28px;
}

.avatar-cross span:last-child {
  width: 28px;
  height: 2px;
}

.profile-name {
  font-family: var(--font-head);
  font-size: 1.5rem;
  letter-spacing: 2px;
  color: var(--black);
  line-height: 1.1;
}

.profile-role {
  font-family: var(--font-body);
  font-size: 0.78rem;
  font-weight: 400;
  color: var(--black);
  opacity: 0.6;
  margin-top: 4px;
  letter-spacing: 0.5px;
}

.profile-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  border-top: 2px solid var(--black);
}

.stat-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 14px 8px;
  border-right: 2px solid var(--black);
  background: var(--white);
}

.stat-block:last-child {
  border-right: none;
}

.stat-block-yellow {
  background: var(--yellow);
}
.stat-block-blue {
  background: var(--blue);
}
.stat-block-blue .stat-value,
.stat-block-blue .stat-label {
  color: var(--white);
}

.stat-value {
  font-family: var(--font-head);
  font-size: 1.6rem;
  letter-spacing: 1px;
  color: var(--black);
  line-height: 1;
}

.stat-label {
  font-family: var(--font-body);
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--black);
  opacity: 0.6;
  margin-top: 4px;
}

/* ── Buttons ── */
.button-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  font-family: var(--font-head);
  font-size: 1rem;
  letter-spacing: 2px;
  padding: 12px 22px;
  border-radius: 0;
  border: 2px solid var(--black);
  cursor: pointer;
  text-transform: uppercase;
  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
  box-shadow: 3px 3px 0 var(--black);
  outline: none;
}

.btn:active {
  transform: translate(3px, 3px);
  box-shadow: none;
}

.btn-black {
  background: var(--black);
  color: var(--white);
}

.btn-black:hover {
  background: var(--blue);
  border-color: var(--blue);
}

.btn-red {
  background: var(--red);
  color: var(--white);
}

.btn-red:hover {
  background: #c0271f;
}

.btn-outline {
  background: var(--white);
  color: var(--black);
}

.btn-outline:hover {
  background: var(--cream);
}

.btn:focus-visible {
  outline: 3px solid var(--blue);
  outline-offset: 2px;
}

/* ── Input ── */
.input-group {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.input-label {
  font-family: var(--font-body);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--black);
  padding-bottom: 10px;
  border-bottom: 3px solid var(--black);
  margin-bottom: 0;
}

.bh-input {
  width: 100%;
  background: transparent;
  border: none;
  border-bottom: 3px solid var(--black);
  padding: 14px 0 10px;
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 400;
  color: var(--black);
  outline: none;
  letter-spacing: 0.5px;
  transition: border-bottom-color 0.2s ease;
}

.bh-input::placeholder {
  color: var(--black);
  opacity: 0.3;
  font-style: italic;
}

.bh-input:focus {
  border-bottom-color: var(--blue);
}

/* ── Badges ── */
.badge-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.badge {
  display: inline-flex;
  align-items: center;
  padding: 5px 12px;
  border-radius: 0;
  font-family: var(--font-body);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  background: var(--cream);
  color: var(--black);
  border: 2px solid var(--black);
  cursor: default;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease, transform 0.1s ease;
}

.badge:hover {
  transform: translateY(-2px);
}

.badge-black {
  background: var(--black);
  color: var(--white);
}
.badge-red {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.badge-yellow {
  background: var(--yellow);
  color: var(--black);
  border-color: var(--black);
}
.badge-blue {
  background: var(--blue);
  color: var(--white);
  border-color: var(--blue);
}

/* ── Responsive ── */
@media (max-width: 480px) {
  .page-main {
    padding: 16px 20px 0;
  }
  .header-content {
    padding: 20px 20px 18px;
    gap: 16px;
  }
  .button-row {
    flex-direction: column;
  }
  .header-title {
    font-size: 2.6rem;
  }
}

