@import url("https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&display=swap");

:root {
  --red: #e60012;
  --blue: #0ab9e6;
  --dark: #1a1a2e;
  --darker: #12121f;
  --fg: #f0f0f5;
  --fg-muted: #9999aa;
  --card-bg: rgba(255, 255, 255, 0.05);
  --border: rgba(255, 255, 255, 0.08);
  --radius: 20px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "Nunito", -apple-system, sans-serif;
  background: var(--darker);
  color: var(--fg);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* --- Floating shapes --- */
.bg-shapes {
  position: fixed;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  pointer-events: none;
}

.shape {
  position: absolute;
  opacity: 0.06;
}

.shape-circle {
  border-radius: 50%;
}

.shape-1 {
  width: 400px;
  height: 400px;
  background: var(--red);
  top: -100px;
  left: -100px;
  filter: blur(80px);
}

.shape-2 {
  width: 350px;
  height: 350px;
  background: var(--blue);
  bottom: -50px;
  right: -50px;
  filter: blur(80px);
}

.shape-cross {
  font-size: 120px;
  font-weight: 900;
  color: var(--red);
  top: 40%;
  right: 10%;
  opacity: 0.04;
}

.shape-triangle {
  width: 0;
  height: 0;
  border-left: 60px solid transparent;
  border-right: 60px solid transparent;
  border-bottom: 100px solid var(--blue);
  top: 20%;
  left: 5%;
  opacity: 0.04;
}

.shape-5 {
  width: 200px;
  height: 200px;
  background: #f5c518;
  top: 60%;
  left: 50%;
  filter: blur(100px);
}

/* --- Hero --- */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 48px 24px;
  gap: 32px;
}

.hero-content {
  position: relative;
}

.hero-badge {
  display: inline-block;
  padding: 6px 18px;
  background: var(--red);
  color: #fff;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.15em;
  margin-bottom: 24px;
  opacity: 0;
}

.hero-title {
  font-size: clamp(2.5rem, 10vw, 5.5rem);
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.hero-word {
  display: block;
  opacity: 0;
  transform: translateY(40px) rotate(-3deg);
}

.hero-word--red {
  color: var(--red);
}
.hero-word--blue {
  color: var(--blue);
}

.hero-desc {
  font-size: 1.1rem;
  color: var(--fg-muted);
  max-width: 440px;
  margin: 0 auto 20px;
  line-height: 1.5;
  opacity: 0;
}

.hero-actions {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  opacity: 0;
}

.text-red {
  color: var(--red);
}
.text-blue {
  color: var(--blue);
}

/* --- Buttons --- */
.btn {
  padding: 14px 28px;
  border: none;
  border-radius: 50px;
  font-weight: 700;
  font-size: 15px;
  cursor: pointer;
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.2s;
  font-family: inherit;
}

.btn:hover {
  transform: scale(1.06);
}

.btn:active {
  transform: scale(0.97);
}

.btn-red {
  background: var(--red);
  color: #fff;
  box-shadow: 0 8px 25px rgba(230, 0, 18, 0.3);
}

.btn-red:hover {
  box-shadow: 0 12px 35px rgba(230, 0, 18, 0.4);
}

.btn-outline {
  background: transparent;
  color: var(--fg);
  border: 2px solid var(--border);
}

.btn-outline:hover {
  border-color: rgba(255, 255, 255, 0.25);
}

.btn-large {
  padding: 18px 36px;
  font-size: 17px;
}

/* --- CSS Console --- */
.console-wrapper {
  perspective: 800px;
  opacity: 0;
  transform: translateY(30px);
  overflow: visible;
}

.console {
  display: flex;
  align-items: stretch;
  transform-style: preserve-3d;
  background: #1e1e2a;
  border-radius: 34px;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
  overflow: hidden;
}

.joycon {
  width: 80px;
  padding: 28px 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  position: relative;
  z-index: 1;
}

.joycon-left {
  background: linear-gradient(160deg, #0ab9e6 0%, #089cc4 100%);
  border-radius: 34px 0 0 34px;
  border-right: 2px solid rgba(0, 0, 0, 0.2);
}

.joycon-right {
  background: linear-gradient(160deg, #e60012 0%, #c2000e 100%);
  border-radius: 0 34px 34px 0;
  border-left: 2px solid rgba(0, 0, 0, 0.2);
}

.stick {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, #3a3a3a, #1a1a1a);
  border: 2px solid rgba(0, 0, 0, 0.4);
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.5), 0 1px 2px rgba(255, 255, 255, 0.05);
}

.dpad {
  position: relative;
  width: 32px;
  height: 32px;
}

.dpad-h,
.dpad-v {
  position: absolute;
  background: rgba(0, 0, 0, 0.35);
  border-radius: 2px;
}

.dpad-h {
  width: 32px;
  height: 11px;
  top: 10.5px;
  left: 0;
}

.dpad-v {
  width: 11px;
  height: 32px;
  top: 0;
  left: 10.5px;
}

.minus-btn {
  width: 14px;
  height: 3px;
  background: rgba(0, 0, 0, 0.35);
  border-radius: 2px;
}

.capture-btn {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  border: 2px solid rgba(0, 0, 0, 0.3);
}

.face-buttons {
  display: grid;
  grid-template-areas: ". x ." "y . a" ". b .";
  gap: 3px;
}

.fb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, #3a3a3a, #1a1a1a);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 8px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.45);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}

.fb-y {
  grid-area: y;
}
.fb-x {
  grid-area: x;
}
.fb-b {
  grid-area: b;
}
.fb-a {
  grid-area: a;
}

.plus-btn {
  font-size: 13px;
  font-weight: 800;
  color: rgba(0, 0, 0, 0.35);
}

.home-btn {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 2px solid rgba(0, 0, 0, 0.3);
}

.screen {
  width: 240px;
  margin: 10px 0;
  background: #0a0a0f;
  border: 3px solid #2a2a35;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.screen-content {
  text-align: center;
}

.screen-logo {
  font-size: 2.5rem;
  font-weight: 900;
  color: var(--red);
  line-height: 1;
}

.screen-text {
  font-size: 0.7rem;
  font-weight: 800;
  color: var(--fg-muted);
  letter-spacing: 0.3em;
}

@media (max-width: 480px) {
  .console-wrapper {
    transform: scale(0.8) translateY(30px);
  }
}

/* --- Sections --- */
section {
  padding: 100px 24px;
  position: relative;
}

.section-container {
  max-width: 1100px;
  margin: 0 auto;
}

.section-header {
  margin-bottom: 48px;
}

.section-header--center {
  text-align: center;
}

.section-title {
  font-size: clamp(2rem, 6vw, 3.5rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1.1;
}

.section-desc {
  font-size: 1.1rem;
  color: var(--fg-muted);
  margin-top: 12px;
  line-height: 1.5;
}

/* --- Modes --- */
.modes-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 20px;
}

.mode-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 36px;
  text-align: center;
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), border-color 0.3s;
}

.mode-card:hover {
  transform: translateY(-8px);
  border-color: rgba(255, 255, 255, 0.15);
}

.mode-card--tv .mode-icon {
  color: var(--red);
}
.mode-card--tabletop .mode-icon {
  color: var(--blue);
}
.mode-card--handheld .mode-icon {
  color: #f5c518;
}

.mode-icon {
  margin-bottom: 20px;
}

.mode-card h3 {
  font-size: 1.3rem;
  font-weight: 800;
  margin-bottom: 8px;
}

.mode-card p {
  color: var(--fg-muted);
  font-size: 14px;
  line-height: 1.5;
}

/* --- Games --- */
.games-row {
  display: flex;
  gap: 20px;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: 48px;
}

.game-card {
  width: 160px;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
  text-align: center;
  transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  cursor: pointer;
}

.game-card:hover {
  transform: translateY(-10px) rotate(1deg);
}

.game-cover {
  height: 120px;
  background: var(--card-color);
  display: flex;
  align-items: center;
  justify-content: center;
}

.game-initial {
  font-size: 3rem;
  font-weight: 900;
  color: rgba(255, 255, 255, 0.9);
  text-shadow: 0 4px 12px rgba(0, 0, 0, 0.3);
}

.game-card h4 {
  font-size: 0.95rem;
  font-weight: 700;
  margin: 12px 0 4px;
}

.game-genre {
  display: block;
  font-size: 12px;
  color: var(--fg-muted);
  margin-bottom: 12px;
}

/* --- Specs --- */
.specs-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 30px;
  padding: 48px;
  text-align: center;
}

.specs-header {
  margin-bottom: 36px;
}

.specs-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 24px;
  margin-bottom: 32px;
}

.spec {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.spec-value {
  font-size: 2.2rem;
  font-weight: 900;
  letter-spacing: -0.03em;
}

.spec-label {
  font-size: 13px;
  color: var(--fg-muted);
  font-weight: 600;
}

.specs-colors {
  display: flex;
  justify-content: center;
  gap: 12px;
}

.color-dot {
