}

.cta-title {
  font-size: clamp(2.5rem, 8vw, 5rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  margin-bottom: 12px;
}

.cta-desc {
  margin: 0 auto 32px;
  max-width: 400px;
}

/* --- Animations --- */
.reveal {
  opacity: 0;
  transform: translateY(25px);
}

/* --- Responsive --- */
@media (max-width: 768px) {
  .specs-card {
    padding: 32px 20px;
    border-radius: 20px;
  }
  .games-row {
    gap: 12px;
  }
  .game-card {
    width: 130px;
  }
  .game-cover {
    height: 90px;
  }
  .game-initial {
    font-size: 2rem;
  }
}

