  )
  .to(".hero-desc", { opacity: 1, duration: 0.6, ease: "power2.out" }, "-=0.3")
  .to(".hero-actions", { opacity: 1, duration: 0.5, ease: "power2.out" }, "-=0.2")
  .to(
