snippets.css:
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap");

:root {
  --bg: #000;
  --fg: #ededed;
  --fg-muted: #888;
  --border: rgba(255, 255, 255, 0.08);
  --accent: #0070f3;
  --accent-glow: rgba(0, 112, 243, 0.25);
  --card-bg: rgba(255, 255, 255, 0.03);
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--fg);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* --- Nav --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 50;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  background: rgba(0, 0, 0, 0.7);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-wordmark {
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: 24px;
}

.nav-links a {
  color: var(--fg-muted);
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  transition: color 0.15s;
}

.nav-links a:hover {
  color: var(--fg);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-link-login {
  color: var(--fg-muted);
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
}

.btn-signup {
  padding: 6px 16px;
  background: var(--fg);
  color: var(--bg);
  border: none;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

@media (max-width: 768px) {
  .nav-links,
  .nav-link-login {
    display: none;
  }
}

/* --- Hero --- */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 120px 24px 80px;
  position: relative;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  border-radius: 20px;
  border: 1px solid var(--border);
  font-size: 13px;
  color: var(--fg-muted);
  margin-bottom: 40px;
  opacity: 0;
}

.badge-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #0070f3;
  animation: dot-pulse 2s ease-in-out infinite;
}

@keyframes dot-pulse {
  0%,
  100% {
    opacity: 0.5;
  }
  50% {
    opacity: 1;
    box-shadow: 0 0 8px var(--accent);
  }
}

.hero-title {
  font-size: clamp(3.5rem, 12vw, 8rem);
  font-weight: 800;
  letter-spacing: -0.06em;
  line-height: 0.95;
  margin-bottom: 32px;
}

.hero-line {
  display: block;
  opacity: 0;
  transform: translateY(30px);
}

.hero-line--accent {
  background: linear-gradient(135deg, #0070f3 0%, #7928ca 50%, #ff0080 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero-desc {
  font-size: 1.15rem;
  color: var(--fg-muted);
  max-width: 520px;
  line-height: 1.6;
  margin-bottom: 40px;
  opacity: 0;
}

.hero-cta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  opacity: 0;
}

.btn-primary {
  padding: 12px 24px;
  background: var(--fg);
  color: var(--bg);
  border: none;
  border-radius: 8px;
  font-weight: 600;
  font-size: 15px;
  cursor: pointer;
  transition: transform 0.15s, box-shadow 0.15s;
}

.btn-primary:hover {
  transform: scale(1.03);
  box-shadow: 0 8px 30px rgba(255, 255, 255, 0.1);
}

.btn-primary--large {
  padding: 16px 32px;
  font-size: 16px;
}

.btn-secondary {
  padding: 12px 24px;
  background: transparent;
  color: var(--fg);
  border: 1px solid var(--border);
  border-radius: 8px;
  font-weight: 600;
  font-size: 15px;
  cursor: pointer;
  transition: border-color 0.15s;
}

.btn-secondary:hover {
  border-color: rgba(255, 255, 255, 0.3);
}

/* --- Terminal --- */
.terminal {
  margin-top: 60px;
  width: min(600px, 90vw);
  background: #0a0a0a;
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  opacity: 0;
  transform: translateY(20px);
}

.terminal-bar {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  position: relative;
}

.terminal-dots {
  display: flex;
  gap: 6px;
}

.terminal-dots span {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
}

.terminal-title {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  font-size: 12px;
  color: var(--fg-muted);
}

.terminal-body {
  padding: 20px;
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 14px;
  line-height: 1.8;
}

.terminal-line {
  white-space: nowrap;
}

.terminal-output {
  color: var(--fg-muted);
}

.t-prompt {
  color: var(--fg-muted);
  margin-right: 8px;
}

.t-cmd {
  color: var(--fg);
}

.t-cursor {
  color: var(--fg);
  animation: blink 1s step-end infinite;
}

@keyframes blink {
  50% {
    opacity: 0;
  }
}

.t-success {
  color: #0070f3;
}
.t-link {
  color: #0070f3;
  text-decoration: underline;
}
.t-dim {
  color: #444;
}

/* --- Sections --- */
section {
  padding: 120px 24px;
  position: relative;
}

.section-container {
  max-width: 1200px;
  margin: 0 auto;
}

.section-header {
  margin-bottom: 48px;
}

.section-header--center {
  text-align: center;
}

.section-tag {
  display: inline-block;
  font-size: 13px;
  font-weight: 600;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 16px;
}

.section-title {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.1;
}

.section-desc {
  font-size: 1.1rem;
  color: var(--fg-muted);
  max-width: 480px;
  line-height: 1.5;
  margin-top: 16px;
}

.section-header--center .section-desc {
  margin: 16px auto 0;
}

/* --- Metrics --- */
.metrics-section {
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: var(--border);
}

.metric-card {
  background: var(--bg);
  padding: 48px 32px;
  text-align: center;
}

.metric-value {
  font-size: 3.5rem;
  font-weight: 800;
  letter-spacing: -0.04em;
}

.metric-unit {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--fg-muted);
}

.metric-label {
  display: block;
  margin-top: 8px;
  font-size: 14px;
  color: var(--fg-muted);
  font-weight: 500;
}

@media (max-width: 768px) {
  .metrics-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* --- Bento Grid --- */
.bento-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.bento-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 32px;
  transition: border-color 0.3s, background 0.3s;
  overflow: hidden;
  position: relative;
}

.bento-card:hover {
  border-color: rgba(255, 255, 255, 0.15);
  background: rgba(255, 255, 255, 0.05);
}

.bento-card--wide {
  grid-column: span 2;
}

.bento-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.06);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--fg);
}

.bento-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: -0.02em;
}

.bento-card p {
  color: var(--fg-muted);
  font-size: 14px;
  line-height: 1.5;
  max-width: 400px;
}

/* Bento visuals */
.bento-visual {
  margin-top: 24px;
  height: 100px;
  position: relative;
}

.bento-visual--edge {
  height: 100px;
}

.edge-svg {
  width: 100%;
  height: 100%;
}

.edge-path {
  stroke: var(--accent);
  stroke-width: 1;
  opacity: 0.2;
}

.edge-dot {
  fill: var(--accent);
  filter: drop-shadow(0 0 6px var(--accent-glow));
}

.edge-packet {
  fill: #fff;
  filter: drop-shadow(0 0 8px var(--accent));
}

.bento-visual--ai {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  height: 120px;
}

.ai-wave {
  width: 4px;
  height: 40px;
  border-radius: 4px;
  background: linear-gradient(180deg, var(--accent), #7928ca);
  animation: ai-wave 1.8s ease-in-out infinite;
}

.ai-wave--2 {
  animation-delay: 0.15s;
  height: 55px;
}
.ai-wave--3 {
  animation-delay: 0.3s;
  height: 70px;
}
.ai-wave--4 {
  animation-delay: 0.45s;
  height: 50px;
  background: linear-gradient(180deg, #7928ca, #ff0080);
}
.ai-wave--5 {
  animation-delay: 0.6s;
  height: 65px;
  background: linear-gradient(180deg, #7928ca, #ff0080);
}
.ai-wave--6 {
  animation-delay: 0.75s;
  height: 45px;
}
.ai-wave--7 {
  animation-delay: 0.9s;
  height: 35px;
}

@keyframes ai-wave {
  0%,
  100% {
    transform: scaleY(0.3);
    opacity: 0.4;
  }
  50% {
    transform: scaleY(1);
    opacity: 1;
  }
}

@media (max-width: 768px) {
  .bento-grid {
    grid-template-columns: 1fr;
  }
  .bento-card--wide {
    grid-column: span 1;
  }
}

/* --- Frameworks --- */
.framework-logos {
  display: flex;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
  margin-top: 48px;
}

.fw-logo {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  color: var(--fg-muted);
  transition: color 0.2s;
}

.fw-logo:hover {
  color: var(--fg);
}

.fw-logo span {
  font-size: 13px;
  font-weight: 500;
}

/* --- CTA --- */
.cta-section {
  min-height: 60vh;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.cta-gradient {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 400px;
  background: radial-gradient(ellipse, var(--accent-glow) 0%, transparent 70%);
  pointer-events: none;
  opacity: 0.5;
}

.cta-content {
  text-align: center;
  position: relative;
  z-index: 2;
}

.cta-title {
  font-size: clamp(2.5rem, 7vw, 4.5rem);
  font-weight: 800;
  letter-spacing: -0.05em;
  line-height: 1.05;
  margin-bottom: 16px;
}

.cta-desc {
  max-width: 400px;
  margin: 0 auto 32px;
}

.cta-actions {
  display: flex;
  gap: 12px;
  justify-content: center;
}

/* --- Animations --- */
.reveal {
  opacity: 0;
  transform: translateY(20px);
}

