@import url("https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;600;700;800&display=swap");

:root {
  --blue-primary: #0071e3;
  --blue-glow: rgba(0, 113, 227, 0.4);
  --glass-bg: rgba(22, 22, 23, 0.7);
  --glass-border: rgba(255, 255, 255, 0.1);
  --text-primary: #f5f5f7;
