/* --- CSS-only Vision Pro Headset --- */
.device-container {
  flex: 1;
  perspective: 1000px;
  display: flex;
  justify-content: center;
}

.device-card {
  position: relative;
  transform-style: preserve-3d;
}

.device-visual {
  position: relative;
  width: 320px;
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.headset {
  position: relative;
  width: 280px;
  height: 100px;
}

.headset-glass {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #2a2a2e 0%, #1a1a1e 40%, #0a0a0e 100%);
  border-radius: 50px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.05), inset 0 1px 0 rgba(255, 255, 255, 0.1), 0 20px
    60px rgba(0, 0, 0, 0.6);
  overflow: hidden;
}

.headset-glass::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    105deg,
    transparent 30%,
    rgba(255, 255, 255, 0.04) 45%,
    rgba(255, 255, 255, 0.08) 50%,
    rgba(255, 255, 255, 0.04) 55%,
    transparent 70%
  );
}

.headset-lens {
  position: absolute;
  width: 50px;
  height: 50px;
  top: 50%;
  transform: translateY(-50%);
  border-radius: 50%;
  background: radial-gradient(
    circle at 40% 40%,
    rgba(80, 80, 100, 0.6) 0%,
    rgba(30, 30, 45, 0.8) 60%,
    rgba(10, 10, 20, 0.95) 100%
  );
