}
.headset-lens-r {
  right: 55px;
}

.headset-eyesight {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 180px;
  height: 40px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(100, 120, 255, 0.08) 20%,
    rgba(120, 140, 255, 0.15) 50%,
    rgba(100, 120, 255, 0.08) 80%,
    transparent 100%
  );
