/* Screen styles */
body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #f0f0f0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 0 48px;
}

.screen-bar {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 24px;
  background: #fff;
  border-bottom: 1px solid #e5e7eb;
  margin-bottom: 28px;
  position: sticky;
  top: 0;
  z-index: 10;
}
.screen-bar-title {
  font-size: 14px;
  font-weight: 700;
  color: #374151;
}
.print-btn {
  background: #6366f1;
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 8px 18px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
.print-btn:hover {
  opacity: 0.85;
}

/* Invoice */
.invoice {
  width: 100%;
  max-width: 794px;
  background: #fff;
  padding: 48px 56px;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.1);
}

/* Header */
.inv-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 36px;
  gap: 24px;
}

.inv-logo {
  font-size: 22px;
  font-weight: 900;
  color: #4f46e5;
  letter-spacing: -0.04em;
  margin-bottom: 8px;
}

.inv-brand-details {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 12px;
  color: #6b7280;
  line-height: 1.6;
}

.inv-title {
  font-size: 28px;
  font-weight: 900;
  color: #111827;
  margin-bottom: 12px;
  text-align: right;
}

.inv-meta-table {
  font-size: 13px;
  border-collapse: collapse;
}
.inv-meta-table td {
  padding: 3px 0 3px 20px;
  color: #374151;
}
.inv-meta-table td:first-child {
  color: #9ca3af;
  padding-left: 0;
}

.inv-status {
  background: #fef3c7;
  color: #92400e;
  font-size: 11px;
  font-weight: 800;
  padding: 2px 8px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Parties */
.inv-parties {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
  padding: 20px 0;
  border-top: 1px solid #e5e7eb;
  border-bottom: 1px solid #e5e7eb;
}

.inv-party-label {
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #9ca3af;
  margin-bottom: 6px;
}

.inv-party-name {
  font-size: 15px;
  font-weight: 700;
  color: #111827;
  margin-bottom: 6px;
}

.inv-party-addr {
  font-size: 12px;
  color: #6b7280;
  line-height: 1.7;
}

.inv-pay-table {
  font-size: 12px;
  border-collapse: collapse;
}
.inv-pay-table td {
  padding: 3px 0 3px 16px;
  color: #374151;
}
.inv-pay-table td:first-child {
  color: #9ca3af;
  padding-left: 0;
  min-width: 70px;
}

/* Line items */
.inv-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 24px;
  font-size: 13px;
}

.inv-table thead tr {
  background: #f9fafb;
  border-bottom: 2px solid #e5e7eb;
}

.inv-table th {
  padding: 10px 12px;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #9ca3af;
  text-align: left;
}

.col-qty,
.col-rate,
.col-amount {
  text-align: right;
}

.inv-table tbody tr {
  border-bottom: 1px solid #f3f4f6;
}
.inv-table tbody tr:last-child {
  border-bottom: none;
}

.inv-table td {
  padding: 12px 12px;
  color: #374151;
  vertical-align: top;
}

.inv-table td.col-qty,
.inv-table td.col-rate,
.inv-table td.col-amount {
  text-align: right;
}

.item-name {
  font-weight: 600;
  color: #111827;
  margin-bottom: 3px;
}
.item-detail {
  font-size: 12px;
  color: #9ca3af;
}

/* Totals */
.inv-totals {
  display: flex;
  justify-content: space-between;
  gap: 32px;
  margin-bottom: 40px;
}

.inv-notes-title {
  font-size: 11px;
  font-weight: 700;
  color: #9ca3af;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 6px;
}
.inv-notes-text {
  font-size: 12px;
  color: #6b7280;
  line-height: 1.7;
  max-width: 280px;
}

.inv-totals-table {
  border-collapse: collapse;
  font-size: 13px;
  min-width: 220px;
}
.inv-totals-table td {
  padding: 6px 0 6px 20px;
  color: #374151;
}
.inv-totals-table td:first-child {
  color: #9ca3af;
  padding-left: 0;
}
.inv-totals-table td:last-child {
  text-align: right;
}
.inv-totals-table .total-row td {
  border-top: 2px solid #111827;
  padding-top: 10px;
  color: #111827;
  font-size: 15px;
}

/* Footer */
.inv-footer {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #d1d5db;
  border-top: 1px solid #f3f4f6;
  padding-top: 16px;
}

/* Print media */
@media print {
  .screen-bar {
    display: none !important;
  }
  body {
    background: #fff;
    padding: 0;
  }
  .invoice {
    box-shadow: none;
    padding: 20mm 18mm;
    max-width: 100%;
  }
  @page {
    margin: 0;
    size: A4;
  }
}

