.illustration {
  animation: float 4s ease-in-out infinite;
}

.illustration svg {
  width: 200px;
  height: auto;
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-12px);
  }
}

