/* Snackbar container */
.snackbar-container {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
  z-index: 9999;
  pointer-events: none;
}

/* Individual snackbar */
.snackbar {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #1f2937;
  color: #fff;
  padding: 12px 16px 12px 20px;
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
  font-size: 14px;
  font-weight: 500;
  min-width: 280px;
  max-width: 420px;
  pointer-events: all;
  animation: snack-in 0.3s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.snackbar.snackbar--error {
  background: #7f1d1d;
  border-left: 3px solid #ef4444;
}

.snackbar.snackbar--out {
  animation: snack-out 0.25s ease forwards;
}

@keyframes snack-in {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.95);
  }
