export default function DirectionsCardRC() {
  const [activeStep, setActiveStep] = useState<number | null>(null);
  const [mode, setMode] = useState<"driving" | "walking" | "cycling">("driving");

  const modes = [
    {
      id: "driving" as const,
      label: "Drive",
      icon: (
        <svg
          width="13"
          height="13"
