  font-family: "JetBrains Mono", "Fira Code", Cascadia, Menlo, monospace;
  font-size: 13px;
  line-height: 1.75;
}

/* Output lines */
.t-line {
  display: flex;
  gap: 8px;
}
.t-prompt {
  color: #cba6f7;
  user-select: none;
}
.t-cmd {
  color: #cdd6f4;
}
.t-stdout {
  color: #a6e3a1;
}
.t-stderr {
  color: #f38ba8;
}
.t-info {
  color: #89b4fa;
}
.t-dim {
  color: rgba(255, 255, 255, 0.3);
}

/* Cursor blink */
.cursor {
  display: inline-block;
  width: 8px;
  height: 14px;
  background: #cba6f7;
  vertical-align: middle;
  margin-left: 2px;
  animation: blink 1s step-end infinite;
}

@keyframes blink {
  0%,
