  padding: 32px 16px;
  display: flex;
  justify-content: center;
}

.demo {
  width: 100%;
  max-width: 960px;
}

.vg-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
  gap: 16px;
  flex-wrap: wrap;
}

.vg-title {
  font-size: 18px;
  font-weight: 700;
  color: #e6edf3;
}

.vg-tabs {
  display: flex;
  gap: 4px;
  background: #161b22;
  border-radius: 10px;
  padding: 4px;
}
.vg-tab {
  background: none;
  border: none;
  color: #8b949e;
  font-size: 13px;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 7px;
  cursor: pointer;
  transition: all 0.15s;
}
.vg-tab.active {
  background: #6366f1;
  color: #fff;
}
.vg-tab:not(.active):hover {
  color: #e6edf3;
  background: rgba(255, 255, 255, 0.05);
}

/* Grid */
.vg-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 16px;
}

.vg-card {
  background: #161b22;
  border: 1px solid #21262d;
  border-radius: 12px;
  overflow: hidden;
  cursor: pointer;
  transition: transform 0.2s, border-color 0.2s;
}
.vg-card:hover {
  transform: translateY(-3px);
  border-color: #30363d;
}

.vg-thumb {
  position: relative;
  aspect-ratio: 16 / 9;
  display: flex;
  align-items: center;
  justify-content: center;
}

.vg-thumb-bg {
  position: absolute;
  inset: 0;
}

.vg-play-btn {
  position: relative;
  z-index: 1;
  width: 44px;
  height: 44px;
  background: rgba(0, 0, 0, 0.6);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  color: #fff;
  backdrop-filter: blur(4px);
  transition: transform 0.15s, background 0.15s;
}
.vg-card:hover .vg-play-btn {
  transform: scale(1.1);
  background: rgba(99, 102, 241, 0.8);
}

.vg-duration {
  position: absolute;
  bottom: 8px;
  right: 8px;
  background: rgba(0, 0, 0, 0.7);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
}

.vg-info {
  padding: 12px 14px;
}
.vg-video-title {
  font-size: 14px;
  font-weight: 600;
  color: #e6edf3;
  line-height: 1.4;
  margin-bottom: 6px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.vg-meta {
  font-size: 12px;
  color: #6c7086;
  display: flex;
  gap: 8px;
  align-items: center;
}
.vg-meta-dot {
  font-size: 8px;
}

.vg-badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 4px;
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.vg-badge--tutorials {
