/* Modal */
.vp-modal {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.vp-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
}

.vp-card {
  position: relative;
  width: 100%;
  max-width: 680px;
  background: #1c2128;
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid #30363d;
  animation: modal-in 0.2s ease;
}

@keyframes modal-in {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.vp-fake-video {
  aspect-ratio: 16 / 9;
  background: #0d1117;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.vp-big-play {
  font-size: 48px;
