}

.vp-playing-indicator {
  display: flex;
  gap: 4px;
  align-items: flex-end;
  height: 32px;
}
.vp-playing-indicator span {
  width: 5px;
  background: #6366f1;
  border-radius: 2px;
  animation: vp-wave 1s ease-in-out infinite;
}
.vp-playing-indicator span:nth-child(1) {
  animation-delay: 0s;
  height: 12px;
}
.vp-playing-indicator span:nth-child(2) {
  animation-delay: 0.1s;
  height: 20px;
}
.vp-playing-indicator span:nth-child(3) {
  animation-delay: 0.2s;
  height: 32px;
}
.vp-playing-indicator span:nth-child(4) {
  animation-delay: 0.3s;
  height: 20px;
}
.vp-playing-indicator span:nth-child(5) {
  animation-delay: 0.4s;
  height: 12px;
}
@keyframes vp-wave {
  0%,
  100% {
    transform: scaleY(0.5);
    opacity: 0.5;
  }
  50% {
    transform: scaleY(1);
    opacity: 1;
  }
}

.vp-controls {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
