}

.vp-ctrl-btn {
  background: none;
  border: none;
  color: #8b949e;
  font-size: 15px;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
  transition: color 0.15s, background 0.15s;
}
.vp-ctrl-btn:hover {
  color: #e6edf3;
