}

.vp-info {
  padding: 16px 20px 20px;
}
.vp-modal-title {
  font-size: 16px;
  font-weight: 700;
  color: #e6edf3;
  margin-bottom: 6px;
}
.vp-modal-meta {
  font-size: 12px;
  color: #6c7086;
}

