*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #f9fafb;
  color: #111;
  min-height: 100vh;
}

.checkout-header {
  background: #fff;
  border-bottom: 1px solid #e5e7eb;
  padding: 16px 40px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.logo {
  font-size: 20px;
  font-weight: 800;
  text-decoration: none;
  color: #111;
}

/* Step indicator */
.step-indicator {
  display: flex;
  align-items: center;
  gap: 4px;
  justify-content: center;
}

.step {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: #aaa;
  font-weight: 500;
}

.step.active {
  color: #6366f1;
}
.step.done {
  color: #16a34a;
}

.step-num {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #e5e7eb;
  color: #888;
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

.step.active .step-num {
  background: #6366f1;
  color: #fff;
}
.step.done .step-num {
  background: #16a34a;
  color: #fff;
}

.step-label {
  display: none;
}
@media (min-width: 480px) {
  .step-label {
    display: inline;
  }
}

.step-line {
  flex: 1;
  max-width: 40px;
  height: 1px;
  background: #e5e7eb;
}

/* Layout */
.checkout-layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 32px;
  max-width: 960px;
  margin: 32px auto;
  padding: 0 24px;
  align-items: start;
}

@media (max-width: 768px) {
  .checkout-layout {
    grid-template-columns: 1fr;
  }
  .order-summary {
    order: -1;
    position: static;
  }
  .checkout-header {
    padding: 16px 20px;
  }
}

/* Step panels */
.step-panel {
  display: none;
  background: #fff;
  border-radius: 16px;
  border: 1px solid #e5e7eb;
  padding: 28px;
}

.step-panel.active {
  display: block;
}

.step-panel h2 {
  font-size: 20px;
  font-weight: 800;
  margin-bottom: 24px;
}

/* Cart */
.cart-items {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 20px;
}

.cart-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: #f9fafb;
  border-radius: 12px;
}

.cart-thumb {
  width: 56px;
  height: 56px;
  border-radius: 10px;
  flex-shrink: 0;
}
.t1 {
  background: linear-gradient(135deg, #c8b89a, #a8946e);
}
.t2 {
  background: linear-gradient(135deg, #374151, #1f2937);
}

.cart-item-info {
  flex: 1;
}
.cart-item-info strong {
  font-size: 14px;
  display: block;
}
.cart-item-info span {
  font-size: 12px;
  color: #888;
}

.cart-qty {
  display: flex;
  align-items: center;
  gap: 8px;
}
.qty-btn {
  width: 28px;
  height: 28px;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  background: #fff;
  cursor: pointer;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cart-price {
  font-size: 15px;
  font-weight: 700;
  min-width: 64px;
  text-align: right;
}

.remove-btn {
  background: none;
  border: none;
  font-size: 20px;
  color: #aaa;
  cursor: pointer;
  padding: 4px;
}
.remove-btn:hover {
  color: #ef4444;
}

.promo-row {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}
.promo-input {
  flex: 1;
  padding: 10px 14px;
  border: 1.5px solid #e5e7eb;
  border-radius: 10px;
  font-size: 14px;
  outline: none;
}
.promo-input:focus {
  border-color: #6366f1;
}
.promo-btn {
  padding: 10px 18px;
  background: #f3f4f6;
  border: none;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

/* Form grid */
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 24px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.field.full {
  grid-column: 1 / -1;
}
.field label {
  font-size: 13px;
  font-weight: 600;
  color: #555;
}
.field input {
  padding: 11px 14px;
  border: 1.5px solid #e5e7eb;
  border-radius: 10px;
  font-size: 14px;
  outline: none;
  transition: border-color 0.15s;
}
.field input:focus {
  border-color: #6366f1;
