  padding: 14px 18px;
  background: #f3f4f6;
  color: #555;
  border: none;
  border-radius: 12px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
}

.back-btn:hover {
  background: #e5e7eb;
}

