.confirm-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 16px;
  padding: 16px 0;
}

.confirm-check {
  width: 72px;
  height: 72px;
}
.confirm-content h2 {
  font-size: 24px;
  font-weight: 800;
