  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  background: #f0f2f5;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.phone-frame {
  width: 375px;
  height: 667px;
  background: #fff;
  border-radius: 40px;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.18);
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
}

/* Content area */
.page-content {
  flex: 1;
  overflow: hidden;
  position: relative;
}

.content-screen {
  position: absolute;
  inset: 0;
  padding: 40px 24px 24px;
  display: none;
  flex-direction: column;
  gap: 16px;
  opacity: 0;
  transition: opacity 0.25s ease;
}

.content-screen.active {
  display: flex;
  opacity: 1;
}

.content-screen h2 {
  font-size: 26px;
  font-weight: 700;
  color: #111;
}

.content-screen > p {
  font-size: 14px;
  color: #666;
  line-height: 1.6;
}

/* Feed placeholders */
.feed-placeholder {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 8px;
}

.feed-card {
  height: 80px;
  background: #f3f4f6;
  border-radius: 12px;
}

.feed-card.short {
  height: 56px;
}

/* Search screen */
.search-box {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  background: #f3f4f6;
  border-radius: 12px;
  color: #999;
  font-size: 14px;
}

.search-box svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

/* Create screen */
.create-options {
  display: flex;
  gap: 10px;
}

.create-option {
  flex: 1;
  padding: 24px 8px;
  background: #f3f4f6;
  border-radius: 12px;
  text-align: center;
  font-size: 13px;
  font-weight: 600;
  color: #555;
}

/* Notifications */
.notif-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.notif-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  background: #eef2ff;
  border-radius: 10px;
  font-size: 13px;
  color: #333;
}

.notif-item.read {
  background: #f9fafb;
  color: #666;
}

.notif-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #6366f1;
  flex-shrink: 0;
}

.notif-item.read .notif-dot {
  background: #d1d5db;
}

/* Profile */
.profile-avatar {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  margin-top: 8px;
}

.profile-name {
  font-size: 18px;
  font-weight: 600;
  color: #111;
}

/* Bottom Nav */
.bottom-nav {
  display: flex;
  align-items: center;
  height: 72px;
  background: #fff;
  border-top: 1px solid #e8e8e8;
  padding: 0 8px;
  position: relative;
  flex-shrink: 0;
}

.nav-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  border: none;
  background: none;
  cursor: pointer;
  padding: 8px 4px;
  border-radius: 12px;
  color: #b0b0b8;
  transition: color 0.2s ease;
  position: relative;
}

.nav-item:active {
  transform: scale(0.92);
}
.nav-item.active {
  color: #6366f1;
}

.nav-icon {
  width: 22px;
  height: 22px;
  transition: transform 0.2s ease;
}

.nav-item.active .nav-icon {
  transform: scale(1.1);
}

.nav-label {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

/* Create button */
.nav-item--create {
  color: #6366f1;
}

.create-btn {
  width: 44px;
  height: 44px;
  background: #6366f1;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  box-shadow: 0 4px 14px rgba(99, 102, 241, 0.4);
  margin-top: -12px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.nav-item--create.active .create-btn {
  transform: scale(0.9) rotate(45deg);
  box-shadow: 0 2px 6px rgba(99, 102, 241, 0.3);
}

.nav-item--create .nav-icon {
  width: 18px;
  height: 18px;
}

/* Badge */
.icon-wrap {
  position: relative;
  display: inline-flex;
}

.badge {
  position: absolute;
  top: -6px;
  right: -8px;
  background: #ef4444;
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  min-width: 16px;
  height: 16px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 3px;
  border: 2px solid #fff;
}

