*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #f9fafb;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px 16px;
}

.demo {
  width: 100%;
  max-width: 640px;
}

.loader-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.loader-card {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 14px;
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  min-height: 120px;
  justify-content: center;
}

.loader-card--wide {
  grid-column: 1 / -1;
}

.loader-label {
  font-size: 11px;
  font-weight: 700;
  color: #9ca3af;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  align-self: flex-start;
}

.loader-caption {
  font-size: 12px;
  color: #6b7280;
}

/* 1. Bouncing dots */
.thinking-dots {
  display: flex;
  gap: 6px;
  align-items: center;
  height: 24px;
}
.thinking-dots span {
  width: 8px;
  height: 8px;
  background: #6366f1;
  border-radius: 50%;
  animation: bounce-dot 1.2s ease-in-out infinite;
}
.thinking-dots span:nth-child(2) {
  animation-delay: 0.2s;
}
.thinking-dots span:nth-child(3) {
  animation-delay: 0.4s;
}
@keyframes bounce-dot {
  0%,
  80%,
  100% {
    transform: scale(0.8) translateY(0);
    opacity: 0.5;
  }
  40% {
    transform: scale(1) translateY(-8px);
    opacity: 1;
  }
}

/* 2. Pulse ring */
.thinking-pulse {
  position: relative;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.pulse-ring {
  position: absolute;
  inset: 0;
  border: 2px solid #6366f1;
  border-radius: 50%;
  animation: pulse-expand 2s ease-out infinite;
}
.pulse-ring--2 {
  animation-delay: 0.8s;
}
.pulse-core {
  width: 12px;
  height: 12px;
  background: #6366f1;
  border-radius: 50%;
}
@keyframes pulse-expand {
  0% {
    transform: scale(0.5);
    opacity: 1;
  }
  100% {
    transform: scale(1.4);
    opacity: 0;
  }
}

/* 3. Shimmer bar */
.thinking-shimmer {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.shimmer-line {
  height: 10px;
  border-radius: 5px;
  background: linear-gradient(90deg, #f3f4f6 25%, #e5e7eb 50%, #f3f4f6 75%);
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
}
.shimmer-line--full {
  width: 100%;
}
.shimmer-line--80 {
  width: 80%;
}
.shimmer-line--60 {
  width: 60%;
}
@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

/* 4. Wave bars */
.thinking-wave {
  display: flex;
  gap: 4px;
  align-items: flex-end;
  height: 28px;
}
.thinking-wave span {
  width: 4px;
  background: #6366f1;
  border-radius: 2px;
  animation: wave-bar 1s ease-in-out infinite;
}
.thinking-wave span:nth-child(1) {
  animation-delay: 0s;
  height: 14px;
}
.thinking-wave span:nth-child(2) {
  animation-delay: 0.1s;
  height: 20px;
}
.thinking-wave span:nth-child(3) {
  animation-delay: 0.2s;
  height: 28px;
}
.thinking-wave span:nth-child(4) {
  animation-delay: 0.3s;
  height: 20px;
}
.thinking-wave span:nth-child(5) {
  animation-delay: 0.4s;
  height: 14px;
}
@keyframes wave-bar {
  0%,
  100% {
    transform: scaleY(0.5);
    opacity: 0.5;
  }
  50% {
    transform: scaleY(1);
    opacity: 1;
  }
}

/* 5. Skeleton text */
.thinking-skeleton {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.skel-line {
  height: 12px;
  border-radius: 6px;
  background: linear-gradient(90deg, #f3f4f6 25%, #e5e7eb 50%, #f3f4f6 75%);
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
}
.skel-line--100 {
  width: 100%;
}
.skel-line--90 {
  width: 90%;
}
.skel-line--75 {
  width: 75%;
}
.skel-line--50 {
  width: 50%;
}

