:root {
  --game-bg: #0f172a;
  --game-surface: rgba(255, 255, 255, 0.04);
  --game-border: rgba(255, 255, 255, 0.08);
  --game-primary: #8b5cf6;
  --game-primary-glow: rgba(139, 92, 246, 0.3);
  --game-secondary: #f43f5e;
  --card-back: #1e293b;
  --card-back-border: rgba(139, 92, 246, 0.2);
  --card-front: #141d2e;
  --card-matched: rgba(139, 92, 246, 0.15);
  --text-primary: #f8fafc;
  --text-muted: #94a3b8;
}

.memory-game-container {
  max-width: 520px;
  margin: 0 auto;
  font-family: "Inter", system-ui, sans-serif;
  position: relative;
  padding: 1.5rem;
  background: var(--game-surface);
  border: 1px solid var(--game-border);
  border-radius: 24px;
  backdrop-filter: blur(16px);
}

.game-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
  background: rgba(255, 255, 255, 0.04);
  padding: 0.875rem 1.25rem;
  border-radius: 14px;
  border: 1px solid var(--game-border);
}

.meta-item {
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--text-muted);
  letter-spacing: 0.025em;
}

.meta-item span {
  color: var(--text-primary);
  font-weight: 700;
}

.reset-btn,
.play-again-btn {
  background: linear-gradient(135deg, var(--game-primary), #a78bfa);
  color: white;
  border: none;
  padding: 0.5rem 1.125rem;
  border-radius: 10px;
  font-weight: 600;
  font-size: 0.813rem;
  cursor: pointer;
  transition: all 0.2s;
  box-shadow: 0 0 16px var(--game-primary-glow);
}

.reset-btn:hover,
.play-again-btn:hover {
  opacity: 0.9;
  transform: translateY(-1px);
  box-shadow: 0 4px 24px var(--game-primary-glow);
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.75rem;
  perspective: 1000px;
}

.memory-card {
  aspect-ratio: 1;
  position: relative;
  cursor: pointer;
  transform-style: preserve-3d;
  transition: transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.memory-card.flipped {
  transform: rotateY(180deg);
}

.memory-card.matched {
  transform: rotateY(180deg);
  pointer-events: none;
}

.card-face {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.75rem;
  transition: box-shadow 0.3s;
}

.card-back {
  background: var(--card-back);
  border: 1px solid var(--card-back-border);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.card-back::after {
  content: "?";
  font-size: 1.25rem;
  font-weight: 700;
  color: rgba(139, 92, 246, 0.4);
  font-family: "Inter", sans-serif;
}

.card-back:hover {
  border-color: rgba(139, 92, 246, 0.5);
  box-shadow: 0 0 20px rgba(139, 92, 246, 0.15);
}

.card-front {
  background: var(--card-front);
  border: 2px solid var(--game-primary);
  transform: rotateY(180deg);
  box-shadow: 0 0 20px var(--game-primary-glow);
}

.memory-card.matched .card-front {
  background: var(--card-matched);
  border-color: #a78bfa;
