  top: 1rem;
  left: 1rem;
  background: rgba(0, 0, 0, 0.6);
  backdrop-filter: blur(4px);
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--zoom-primary);
  border: 1px solid rgba(var(--zoom-primary-rgb), 0.3);
}

/* ── Responsive ────────────────────────────── */
@media (max-width: 900px) {
  .zoom-grid {
    grid-template-columns: 1fr;
  }

  .zoom-target {
    max-width: 500px;
    margin: 0 auto;
  }

  .zoom-result {
    max-width: 500px;
    margin: 0 auto;
    transform: translateY(20px);
  }

  .zoom-result.active {
    transform: translateY(0);
  }
}

