}

.pwd-toggle {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 2px;
  transition: color .15s;
}

.pwd-toggle:hover {
  color: var(--text);
}

.field-error {
  font-size: 0.78rem;
  color: var(--red);
}

/* Strength meter */
.strength-meter {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 4px;
}

.strength-bar-wrap {
