.strength-bar.s1 {
  background: var(--red);
  width: 25%;
}

.strength-bar.s2 {
  background: #fb923c;
  width: 50%;
}

.strength-bar.s3 {
  background: #facc15;
  width: 75%;
}

.strength-bar.s4 {
  background: var(--green);
  width: 100%;
}

.strength-label {
  font-size: 0.72rem;
  color: var(--text-muted);
  white-space: nowrap;
}

.remember-row {
