  align-items: flex-start;
  gap: 8px;
  cursor: pointer;
  font-size: 0.82rem;
  color: var(--text-muted);
  line-height: 1.5;
}

.remember-row input {
  accent-color: var(--accent);
  width: 14px;
  height: 14px;
  margin-top: 2px;
