                    <span className="text-[#f87171]">▼</span>
                    <span className="text-[#f87171] font-semibold">-{dropPct}%</span>
                    <span>dropped ({drop.toLocaleString()})</span>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Summary row */}
        <div className="flex justify-center gap-6 mt-6 pt-4 border-t border-[#21262d]">
          {STAGES.map((s) => (
