.toggle-label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-muted);
}

.toggle-switch {
  position: relative;
  cursor: pointer;
}

.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
  position: absolute;
}

.toggle-track {
  display: block;
  width: 44px;
  height: 24px;
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 12px;
  position: relative;
  transition: border-color .2s;
}

.toggle-switch input:checked ~ .toggle-track {
