  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--text-muted);
  transition: left .2s, background .2s;
}

.toggle-switch input:checked ~ .toggle-track .toggle-thumb {
  left: 23px;
  background: var(--accent);
}

.save-badge {
