  background: linear-gradient(160deg, #1a1c30, #16181f);
  border-color: rgba(129, 140, 248, 0.35);
}

.plan-card--featured:hover {
  border-color: var(--accent);
}

.popular-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: linear-gradient(90deg, #818cf8, #a5b4fc);
  color: #0f1117;
  font-size: 0.72rem;
  font-weight: 800;
  padding: 4px 14px;
  border-radius: 999px;
