.plan-desc {
  font-size: 0.82rem;
  color: var(--text-muted);
  line-height: 1.6;
  margin-bottom: 20px;
}

.plan-cta {
  display: block;
  text-align: center;
  padding: 10px 16px;
  border-radius: 9px;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  transition: background .15s, opacity .15s;
  margin-bottom: 24px;
}

.plan-cta--filled {
  background: var(--accent);
