}

.plan-cta--filled:hover {
  background: var(--accent-hover);
}

.plan-cta--outline {
  border: 1px solid var(--border);
  color: var(--text);
  background: transparent;
}

.plan-cta--outline:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.plan-features {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.feat {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.82rem;
  line-height: 1.5;
}

.feat::before {
  content: "✓";
  font-size: 0.78rem;
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 1px;
}

.feat--yes {
  color: var(--text-muted);
}

.feat--yes::before {
  color: var(--green);
}

.feat--no {
  color: #415168;
  text-decoration: line-through;
}

.feat--no::before {
  content: "✗";
  color: #3d4a5a;
}

@media (max-width: 760px) {
  .pricing-grid {
    grid-template-columns: 1fr;
  }
}

