import { useState, useEffect, useRef } from "react";

const SIZE = 200,
  CX = SIZE / 2,
  CY = SIZE * 0.6,
  R = 80,
  STROKE = 16;
const START_ANG = -210 * (Math.PI / 180),
  END_ANG = 30 * (Math.PI / 180);

type Zone = { from: number; to: number; color: string };
type GaugeCfg = { label: string; value: number; min: number; max: number; zones: Zone[] };

const GAUGES: GaugeCfg[] = [
  {
    label: "CPU Load",
    value: 68,
    min: 0,
    max: 100,
    zones: [
      { from: 0, to: 50, color: "#34d399" },
      { from: 50, to: 75, color: "#f59e0b" },
      { from: 75, to: 100, color: "#f87171" },
    ],
  },
  {
    label: "Memory",
    value: 42,
    min: 0,
    max: 100,
    zones: [
      { from: 0, to: 50, color: "#34d399" },
      { from: 50, to: 80, color: "#f59e0b" },
      { from: 80, to: 100, color: "#f87171" },
    ],
  },
  {
    label: "Disk Health",
    value: 87,
    min: 0,
    max: 100,
    zones: [
      { from: 0, to: 40, color: "#f87171" },
      { from: 40, to: 70, color: "#f59e0b" },
      { from: 70, to: 100, color: "#34d399" },
    ],
  },
];

function ptOnArc(r: number, ang: number): [number, number] {
  return [CX + r * Math.cos(ang), CY + r * Math.sin(ang)];
}
function arcD(r: number, a1: number, a2: number) {
  const [sx, sy] = ptOnArc(r, a1),
    [ex, ey] = ptOnArc(r, a2);
  const large = a2 - a1 > Math.PI ? 1 : 0;
  return `M${sx.toFixed(2)},${sy.toFixed(2)} A${r},${r} 0 ${large},1 ${ex.toFixed(2)},${ey.toFixed(2)}`;
}
function valToAng(v: number, min: number, max: number) {
  return START_ANG + ((v - min) / (max - min)) * (END_ANG - START_ANG);
}

function Gauge({ cfg, value }: { cfg: GaugeCfg; value: number }) {
  const [current, setCurrent] = useState(cfg.min);
  const rafRef = useRef<number>(0);
  const fromRef = useRef(cfg.min);

  useEffect(() => {
    const from = fromRef.current;
    let start: number | null = null;
    const duration = 1000;
    function step(ts: number) {
      if (!start) start = ts;
      const p = Math.min((ts - start) / duration, 1);
      const eased = 1 - Math.pow(1 - p, 3);
      const v = from + (value - from) * eased;
      setCurrent(v);
      if (p < 1) rafRef.current = requestAnimationFrame(step);
      else fromRef.current = value;
    }
    rafRef.current = requestAnimationFrame(step);
    return () => cancelAnimationFrame(rafRef.current);
  }, [value]);

  const ang = valToAng(current, cfg.min, cfg.max);
  const [nx, ny] = ptOnArc(R - STROKE / 2 - 2, ang);
  const [mlx, mly] = ptOnArc(R + 18, START_ANG);
  const [mxlx, mxly] = ptOnArc(R + 18, END_ANG);

  return (
    <div className="flex flex-col items-center">
      <svg width={SIZE} height={SIZE * 0.7} viewBox={`0 0 ${SIZE} ${SIZE * 0.7}`}>
        <path
          d={arcD(R, START_ANG, END_ANG)}
          fill="none"
          stroke="#1e2130"
          strokeWidth={STROKE}
          strokeLinecap="round"
        />
        {cfg.zones.map((z, i) => (
          <path
            key={i}
            d={arcD(R, valToAng(z.from, cfg.min, cfg.max), valToAng(z.to, cfg.min, cfg.max))}
            fill="none"
            stroke={z.color}
            strokeWidth={STROKE * 0.55}
            strokeLinecap="round"
          />
        ))}
        <text x={mlx} y={mly} textAnchor="middle" fill="#64748b" fontSize={10}>
          {cfg.min}
        </text>
        <text x={mxlx} y={mxly} textAnchor="middle" fill="#64748b" fontSize={10}>
          {cfg.max}
        </text>
        <line
          x1={CX}
          y1={CY}
          x2={nx.toFixed(2)}
          y2={ny.toFixed(2)}
          stroke="#e2e8f0"
          strokeWidth={2.5}
          strokeLinecap="round"
        />
        <circle cx={CX} cy={CY} r={6} fill="#e2e8f0" />
        <text x={CX} y={CY - 16} textAnchor="middle" fill="#e2e8f0" fontSize={22} fontWeight={800}>
          {Math.round(current)}
        </text>
      </svg>
      <div className="text-[#8b949e] text-[13px] -mt-1">{cfg.label}</div>
    </div>
  );
}

export default function GaugeMeterRC() {
  const [values, setValues] = useState(GAUGES.map((g) => g.value));
  const randomize = () => setValues(GAUGES.map(() => Math.floor(Math.random() * 91) + 5));

  return (
    <div className="min-h-screen bg-[#0d1117] p-6 flex flex-col items-center gap-8">
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-8">
        {GAUGES.map((g, i) => (
          <Gauge key={g.label} cfg={g} value={values[i]} />
        ))}
      </div>
      <button
        onClick={randomize}
        className="px-4 py-2 bg-[#818cf8]/20 border border-[#818cf8]/40 text-[#818cf8] rounded-lg text-[13px] hover:bg-[#818cf8]/30 transition-colors"
      >
        Randomize
      </button>
    </div>
  );
}

snippets.css:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --sidebar-w: 260px;
  --sidebar-w-collapsed: 64px;
  --bg: #0f1117;
  --surface: #16181f;
  --surface2: #1e2130;
  --border: #2a2d3a;
  --text: #e2e8f0;
  --text-muted: #64748b;
  --accent: #818cf8;
  --accent-bg: rgba(129, 140, 248, 0.12);
  --green: #34d399;
  --red: #f87171;
  --transition: 260ms cubic-bezier(0.4, 0, 0.2, 1);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
  display: flex;
  height: 100vh;
  overflow: hidden;
}

/* ── Overlay (mobile) ── */
.overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.55);
  z-index: 40;
}
.overlay.visible {
  display: block;
}

/* ── Sidebar ── */
.sidebar {
  width: var(--sidebar-w);
  min-height: 100vh;
  background: var(--surface);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  transition: width var(--transition);
  overflow: hidden;
  position: relative;
  flex-shrink: 0;
  z-index: 50;
}

.sidebar.collapsed {
  width: var(--sidebar-w-collapsed);
}

/* Logo */
.s-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 20px 16px 16px;
  border-bottom: 1px solid var(--border);
  overflow: hidden;
  white-space: nowrap;
}
.s-logo-icon {
  width: 36px;
  height: 36px;
  background: var(--accent-bg);
  border-radius: 10px;
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.s-logo-text {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text);
  opacity: 1;
  transition: opacity var(--transition);
}
.sidebar.collapsed .s-logo-text {
  opacity: 0;
  pointer-events: none;
}

/* Collapse button */
.s-collapse-btn {
  position: absolute;
  top: 20px;
  right: 10px;
  width: 24px;
  height: 24px;
  border: 1px solid var(--border);
  border-radius: 50%;
  background: var(--surface2);
  color: var(--text-muted);
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background .2s, color .2s;
  z-index: 2;
}
.s-collapse-btn:hover {
  background: var(--accent-bg);
  color: var(--accent);
}
.sidebar.collapsed .s-collapse-btn svg {
  transform: rotate(180deg);
}
.s-collapse-btn svg {
  transition: transform var(--transition);
}

/* Nav */
.s-nav {
  flex: 1;
  padding: 12px 10px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  overflow: hidden;
}

.s-section-label {
  font-size: 0.65rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--text-muted);
  padding: 8px 6px 4px;
  white-space: nowrap;
  overflow: hidden;
  transition: opacity var(--transition), height var(--transition);
}
.sidebar.collapsed .s-section-label {
  opacity: 0;
  height: 0;
  padding: 0;
}

.s-divider {
  height: 1px;
  background: var(--border);
  margin: 8px 0;
}

.s-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border-radius: 8px;
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.875rem;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  transition: background .15s, color .15s;
  position: relative;
}
.s-item:hover {
  background: var(--surface2);
  color: var(--text);
}
.s-item.active {
  background: var(--accent-bg);
  color: var(--accent);
}
.s-item.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 3px;
  background: var(--accent);
  border-radius: 0 3px 3px 0;
}

.s-icon {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
}
.s-label {
  flex: 1;
  opacity: 1;
  transition: opacity var(--transition);
}
.sidebar.collapsed .s-label {
  opacity: 0;
}

.s-badge {
  font-size: 0.65rem;
  font-weight: 700;
  background: var(--accent);
  color: #fff;
  padding: 1px 6px;
  border-radius: 999px;
  line-height: 1.5;
  transition: opacity var(--transition);
}
.s-badge--dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  padding: 0;
}
.sidebar.collapsed .s-badge {
  opacity: 0;
}

/* Tooltip in collapsed mode */
.sidebar.collapsed .s-item::after {
  content: attr(data-tooltip);
  position: absolute;
  left: calc(100% + 12px);
  top: 50%;
  transform: translateY(-50%);
  background: var(--surface2);
  border: 1px solid var(--border);
  color: var(--text);
  font-size: 0.8rem;
  padding: 4px 10px;
  border-radius: 6px;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity .15s;
  z-index: 100;
}
.sidebar.collapsed .s-item:hover::after {
  opacity: 1;
}

/* User */
.s-user {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 12px;
  border-top: 1px solid var(--border);
  overflow: hidden;
  cursor: pointer;
  white-space: nowrap;
  transition: background .15s;
}
.s-user:hover {
  background: var(--surface2);
}
.s-user-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), #a5b4fc);
  display: grid;
  place-items: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}
.s-user-info {
  display: flex;
  flex-direction: column;
  opacity: 1;
  transition: opacity var(--transition);
}
.sidebar.collapsed .s-user-info {
  opacity: 0;
}
.s-user-name {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text);
}
.s-user-role {
  font-size: 0.7rem;
  color: var(--text-muted);
  margin-top: 1px;
}

/* Tooltip for user */
.sidebar.collapsed .s-user::after {
  content: attr(data-tooltip);
  position: absolute;
  left: calc(100% + 12px);
  bottom: 12px;
  background: var(--surface2);
  border: 1px solid var(--border);
  color: var(--text);
  font-size: 0.8rem;
  padding: 4px 10px;
  border-radius: 6px;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity .15s;
  z-index: 100;
}
.sidebar.collapsed .s-user:hover::after {
  opacity: 1;
}

/* ── Main area ── */
.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Topbar */
.topbar {
  height: 60px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 20px;
  gap: 12px;
}
.hamburger {
  display: none;
  flex-direction: column;
  gap: 4px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
}
.hamburger span {
  display: block;
  width: 18px;
  height: 2px;
  background: var(--text-muted);
  border-radius: 2px;
  transition: background .15s;
}
.hamburger:hover span {
  background: var(--text);
}

.topbar-title {
  font-size: 1rem;
  font-weight: 600;
  flex: 1;
}
.topbar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
.topbar-icon-btn {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--surface2);
  color: var(--text-muted);
  cursor: pointer;
  display: grid;
  place-items: center;
  position: relative;
  transition: background .15s, color .15s;
}
.topbar-icon-btn:hover {
  color: var(--text);
  background: var(--border);
}
.topbar-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 16px;
  height: 16px;
  background: var(--red);
  border-radius: 50%;
  font-size: 0.6rem;
  font-weight: 700;
  color: #fff;
  display: grid;
  place-items: center;
}
.topbar-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), #a5b4fc);
  display: grid;
  place-items: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: #fff;
  cursor: pointer;
}

/* Content */
.content {
  flex: 1;
  overflow-y: auto;
  padding: 28px 24px;
}
.content-title {
  font-size: 1.4rem;
  font-weight: 700;
  margin-bottom: 4px;
}
.content-subtitle {
  color: var(--text-muted);
  margin-bottom: 28px;
  font-size: 0.875rem;
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
}
.stat-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 20px;
  transition: border-color .2s;
}
.stat-card:hover {
  border-color: var(--accent);
}
.stat-label {
  font-size: 0.78rem;
  color: var(--text-muted);
  margin-bottom: 8px;
  font-weight: 500;
}
.stat-value {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 4px;
}
.stat-delta {
  font-size: 0.78rem;
  font-weight: 600;
}
.stat-delta.up {
  color: var(--green);
}
.stat-delta.down {
  color: var(--red);
}

/* ── Mobile ── */
@media (max-width: 768px) {
  .sidebar {
    position: fixed;
    top: 0;
    left: 0;
    height: 100vh;
    transform: translateX(-100%);
    transition: transform var(--transition), width var(--transition);
    width: var(--sidebar-w) !important;
  }
  .sidebar.mobile-open {
    transform: translateX(0);
  }
  .s-collapse-btn {
    display: none;
  }
  .hamburger {
    display: flex;
  }
}

