const sidebar = document.getElementById("sidebar");
const collapseBtn = document.getElementById("collapseBtn");
const hamburger = document.getElementById("hamburger");
const overlay = document.getElementById("overlay");

// Desktop collapse toggle
collapseBtn?.addEventListener("click", () => {
  sidebar.classList.toggle("collapsed");
  const isCollapsed = sidebar.classList.contains("collapsed");
  collapseBtn.setAttribute("aria-expanded", String(!isCollapsed));
});

// Mobile open
hamburger?.addEventListener("click", () => {
  sidebar.classList.add("mobile-open");
  overlay.classList.add("visible");
});

// Mobile close
function closeMobile() {
  sidebar.classList.remove("mobile-open");
  overlay.classList.remove("visible");
}
overlay?.addEventListener("click", closeMobile);
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") closeMobile();
});

// Active nav item
document.querySelectorAll(".s-item").forEach((item) => {
  item.addEventListener("click", (e) => {
    e.preventDefault();
    document.querySelectorAll(".s-item").forEach((i) => {
      i.classList.remove("active");
      i.removeAttribute("aria-current");
    });
    item.classList.add("active");
    item.setAttribute("aria-current", "page");
    // Update topbar title
    const label = item.querySelector(".s-label")?.textContent?.trim();
    const title = document.querySelector(".topbar-title");
    if (label && title) title.textContent = label;
    // Close mobile
    closeMobile();
  });
});

// Persist collapse state
const savedCollapsed = localStorage.getItem("sidebar-collapsed") === "true";
if (savedCollapsed) {
  sidebar.classList.add("collapsed");
  collapseBtn?.setAttribute("aria-expanded", "false");
}
collapseBtn?.addEventListener("click", () => {
  localStorage.setItem("sidebar-collapsed", sidebar.classList.contains("collapsed").toString());
});

snippets.css:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #0f1117;
  --surface: #16181f;
  --surface2: #1e2130;
  --border: #2a2d3a;
  --text: #e2e8f0;
  --text-muted: #64748b;
  --accent: #818cf8;
  --accent-hover: #a5b4fc;
  --green: #34d399;
  --red: #f87171;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

/* Overlay */
.cart-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.55);
  z-index: 100;
}

.cart-overlay.visible {
  display: block;
}

/* Shop page */
.shop-page {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
}

.shop-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 60px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  z-index: 50;
}

.shop-logo {
  font-size: 1rem;
  font-weight: 700;
  color: var(--accent);
  text-decoration: none;
}

.shop-hint {
  color: var(--text-muted);
  font-size: 0.875rem;
  margin-top: 60px;
}

.cart-trigger {
  position: relative;
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: var(--surface2);
  border: 1px solid var(--border);
  color: var(--text);
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: border-color .15s;
}

.cart-trigger:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.cart-trigger-badge {
  position: absolute;
  top: -6px;
  right: -6px;
  min-width: 18px;
  height: 18px;
  background: var(--accent);
  border-radius: 999px;
  font-size: 0.62rem;
  font-weight: 700;
  color: #fff;
  display: grid;
  place-items: center;
  padding: 0 4px;
  border: 2px solid var(--bg);
}

/* Drawer */
.cart-drawer {
  position: fixed;
  top: 0;
  right: 0;
  height: 100vh;
  width: 400px;
  max-width: 95vw;
  background: var(--surface);
  border-left: 1px solid var(--border);
  z-index: 200;
  display: flex;
  flex-direction: column;
  transform: translateX(100%);
  transition: transform 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

.cart-drawer.open {
  transform: none;
}

.cart-header {
  padding: 18px 20px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}

.cart-title {
  font-size: 1rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
}

.cart-count {
  font-size: 0.72rem;
  font-weight: 700;
  background: var(--accent);
  color: #fff;
  border-radius: 999px;
  padding: 1px 7px;
}

.cart-close {
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: 4px;
  border-radius: 6px;
  display: grid;
  place-items: center;
  transition: color .15s;
}

.cart-close:hover {
  color: var(--text);
}

.cart-items {
  flex: 1;
  overflow-y: auto;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.cart-items::-webkit-scrollbar {
  width: 4px;
}

.cart-items::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 2px;
}

/* Item */
.cart-item {
  display: flex;
  gap: 12px;
  animation: itemIn .2s ease;
}

@keyframes itemIn {
  from {
    opacity: 0;
    transform: translateX(8px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

.item-thumb {
  width: 60px;
  height: 60px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  font-size: 1.6rem;
  flex-shrink: 0;
}

.item-info {
  flex: 1;
  min-width: 0;
}

.item-name {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.item-variant {
  font-size: 0.72rem;
  color: var(--text-muted);
  margin-bottom: 8px;
}

.item-controls {
  display: flex;
  align-items: center;
  gap: 10px;
}

.qty-btn {
  width: 24px;
  height: 24px;
  border-radius: 6px;
  border: 1px solid var(--border);
  background: var(--surface2);
  color: var(--text);
  font-size: 1rem;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: border-color .15s;
  line-height: 1;
}

.qty-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.qty-num {
  font-size: 0.875rem;
  font-weight: 600;
  min-width: 20px;
  text-align: center;
}

.item-remove {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 0.78rem;
  cursor: pointer;
  font-family: inherit;
  transition: color .15s;
  margin-left: auto;
}

.item-remove:hover {
  color: var(--red);
}

.item-price {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--text);
  align-self: center;
  white-space: nowrap;
}

/* Empty */
.cart-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 24px;
}

.cart-empty-icon {
  font-size: 3rem;
}

.cart-empty p {
  color: var(--text-muted);
  font-size: 0.875rem;
}

.cart-empty-btn {
  background: var(--accent);
  border: none;
  border-radius: 9px;
  color: #fff;
  font-size: 0.875rem;
  font-weight: 600;
  padding: 10px 20px;
  cursor: pointer;
  font-family: inherit;
}

/* Footer summary */
.cart-footer {
  padding: 16px 20px;
  border-top: 1px solid var(--border);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.coupon-row {
  display: flex;
  gap: 8px;
}

.coupon-input {
  flex: 1;
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.82rem;
  padding: 8px 12px;
  outline: none;
  font-family: inherit;
  transition: border-color .15s;
  text-transform: uppercase;
}

.coupon-input::placeholder {
  text-transform: none;
  color: var(--text-muted);
}

.coupon-input:focus {
  border-color: var(--accent);
}

.coupon-btn {
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.82rem;
  font-weight: 600;
  padding: 0 14px;
  cursor: pointer;
  font-family: inherit;
  white-space: nowrap;
  transition: border-color .15s;
}

.coupon-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.coupon-msg {
  font-size: 0.78rem;
  margin-top: -4px;
}

.coupon-msg.ok {
  color: var(--green);
}

.coupon-msg.err {
  color: var(--red);
}

.summary {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.summary-row {
  display: flex;
  justify-content: space-between;
  font-size: 0.82rem;
  color: var(--text-muted);
}

.summary-row--total {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text);
  margin-top: 4px;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}

.discount-label {
  color: var(--green);
}

.discount-val {
  color: var(--green);
}

.checkout-btn {
  width: 100%;
  background: var(--accent);
  border: none;
  border-radius: 9px;
  color: #fff;
  font-size: 0.9rem;
  font-weight: 700;
  padding: 12px;
  cursor: pointer;
  font-family: inherit;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: background .15s;
}

.checkout-btn:hover {
  background: var(--accent-hover);
}

/* Undo toast */
.undo-toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 10px;
