  margin: 0.35rem 0 0;
  color: var(--muted);
}

.panel {
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.02), transparent), var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1rem;
}

.form-panel h2 {
  margin-top: 0;
}

.editor {
  display: grid;
  grid-template-columns: repeat(2, minmax(140px, 1fr));
