  font-size: 0.9rem;
  text-align: left;
}

th button {
  all: unset;
  cursor: pointer;
  color: var(--muted);
  font-size: 0.75rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.status {
  display: inline-block;
  border-radius: 999px;
  padding: 0.2rem 0.6rem;
  font-size: 0.75rem;
  text-transform: capitalize;
  border: 1px solid currentColor;
}

.status.active {
  color: var(--ok);
}

.status.pending {
  color: #fbbf24;
}

.status.inactive {
  color: #94a3b8;
}

.row-actions {
  display: flex;
  gap: 0.35rem;
}

.row-actions button {
  padding: 0.35rem 0.55rem;
  font-size: 0.75rem;
}

.row-actions .danger {
  background: rgba(248, 113, 113, 0.12);
  color: #fecaca;
  border: 1px solid rgba(248, 113, 113, 0.4);
}

.table-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.8rem;
  margin-top: 0.8rem;
