#summary {
  margin: 0;
  color: var(--muted);
  font-size: 0.85rem;
}

.pager {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.pager button {
  padding: 0.35rem 0.6rem;
  font-size: 0.8rem;
}

@media (max-width: 760px) {
  .editor {
    grid-template-columns: 1fr;
  }

  .table-panel {
    overflow: auto;
  }

  table {
    min-width: 720px;
  }
}

