          );
        })}
      </div>

      {/* Song */}
      <div
        style={{
          fontFamily: "system-ui, -apple-system, sans-serif",
          fontWeight: 400,
          fontSize: 14,
          color: "rgba(255,255,255,0.7)",
          marginTop: 10,
        }}
      >
        {SONG}
      </div>
    </div>
  );
};

// ── Main composition ──────────────────────────────────────────────────
export const TiktokVideo: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  return (
    <AbsoluteFill
      style={{
        background: "linear-gradient(180deg, #1a1a2e 0%, #16213e 60%, #0f3460 100%)",
      }}
    >
      {/* Placeholder video area */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            fontFamily: "system-ui, -apple-system, sans-serif",
            fontSize: 18,
            color: "rgba(255,255,255,0.15)",
            letterSpacing: 2,
            textTransform: "uppercase",
          }}
        >
          Video Content
        </div>
      </div>

      {/* Action icons */}
      <ActionIcon frame={frame} fps={fps} emoji="❤️" count="124K" delay={20} offsetY={340} />
      <ActionIcon frame={frame} fps={fps} emoji="💬" count="3.4K" delay={30} offsetY={240} />
      <ActionIcon frame={frame} fps={fps} emoji="↗️" count="Share" delay={40} offsetY={150} />

      <BottomCaption frame={frame} fps={fps} />
      <VideoProgress frame={frame} />
    </AbsoluteFill>
  );
};

// ── Remotion Root ─────────────────────────────────────────────────────
export const RemotionRoot: React.FC = () => (
  <Composition
    id="TiktokVideo"
    component={TiktokVideo}
    durationInFrames={450}
    fps={30}
    width={1080}
    height={1920}
  />
);

snippets.css:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --sidebar-width: 240px;
  --sidebar-collapsed-width: 60px;
  --navbar-height: 60px;
  --bg: #0f172a;
  --surface: #1e293b;
  --surface-2: #263044;
  --border: rgba(255, 255, 255, 0.07);
  --text: #f1f5f9;
  --muted: #94a3b8;
  --accent: #38bdf8;
  --accent-dim: rgba(56, 189, 248, 0.12);
  --transition: 0.28s cubic-bezier(0.4, 0, 0.2, 1);
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  height: 100vh;
  overflow: hidden;
  display: flex;
}

/* ── Overlay (mobile) ── */
.sidebar-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  z-index: 40;
  opacity: 0;
  transition: opacity var(--transition);
}
.sidebar-overlay.active {
  display: block;
  opacity: 1;
}

/* ── Sidebar ── */
.sidebar {
  position: relative;
  width: var(--sidebar-width);
  height: 100vh;
  background: var(--surface);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  overflow: hidden;
  transition: width var(--transition);
  z-index: 50;
}

.sidebar.collapsed {
  width: var(--sidebar-collapsed-width);
}

/* Logo */
.sidebar-logo {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1.125rem 1rem;
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
  overflow: hidden;
  flex-shrink: 0;
}
.sidebar-logo-icon {
  width: 32px;
  height: 32px;
  background: var(--accent-dim);
  border: 1px solid rgba(56, 189, 248, 0.25);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.sidebar-logo-text {
  font-size: 0.9375rem;
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.02em;
  opacity: 1;
  transition: opacity var(--transition);
}
.sidebar.collapsed .sidebar-logo-text {
  opacity: 0;
}

/* Nav */
.sidebar-nav {
  flex: 1;
  padding: 0.75rem 0.5rem;
  display: flex;
  flex-direction: column;
  gap: 2px;
  overflow-y: auto;
  overflow-x: hidden;
}
.sidebar-nav::-webkit-scrollbar {
  width: 4px;
}
.sidebar-nav::-webkit-scrollbar-thumb {
  background: var(--border);
  border-radius: 2px;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.625rem 0.75rem;
  border-radius: 8px;
  color: var(--muted);
  text-decoration: none;
  font-size: 0.875rem;
  font-weight: 500;
  white-space: nowrap;
  transition: background 0.15s, color 0.15s;
  position: relative;
}
.nav-item:hover {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text);
}
.nav-item.active {
  background: var(--accent-dim);
  color: var(--accent);
}
.nav-icon {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
}
.nav-label {
  opacity: 1;
  max-width: 200px;
  overflow: hidden;
  transition: opacity var(--transition), max-width var(--transition);
}
.sidebar.collapsed .nav-label {
  opacity: 0;
  max-width: 0;
}

/* Tooltip on collapsed */
.sidebar.collapsed .nav-item {
  justify-content: center;
  padding: 0.625rem;
  gap: 0;
  width: calc(var(--sidebar-collapsed-width) - 1rem);
}
.sidebar.collapsed .nav-item:hover::after {
  content: attr(data-label);
  position: absolute;
  left: calc(var(--sidebar-collapsed-width) + 8px);
  background: #334155;
  color: var(--text);
  font-size: 0.8125rem;
  padding: 0.3rem 0.6rem;
  border-radius: 6px;
  white-space: nowrap;
  pointer-events: none;
  z-index: 100;
}

.nav-divider {
  height: 1px;
  background: var(--border);
  margin: 0.5rem 0.25rem;
  flex-shrink: 0;
}

/* Collapse button */
.sidebar-collapse-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 0.75rem;
  background: transparent;
  border: none;
  border-top: 1px solid var(--border);
  color: var(--muted);
  cursor: pointer;
  transition: color 0.15s, background 0.15s;
  flex-shrink: 0;
}
.sidebar-collapse-btn:hover {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}
.sidebar-collapse-btn svg {
  transition: transform var(--transition);
}
.sidebar.collapsed .sidebar-collapse-btn svg {
  transform: rotate(180deg);
}

/* User */
.sidebar-user {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.875rem 1rem;
  border-top: 1px solid var(--border);
  white-space: nowrap;
  overflow: hidden;
  flex-shrink: 0;
}
.sidebar-user-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.sidebar-user-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
  opacity: 1;
  transition: opacity var(--transition);
}
.sidebar.collapsed .sidebar-user-info {
  opacity: 0;
}
.sidebar-user-name {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text);
}
.sidebar-user-role {
  font-size: 0.6875rem;
  color: var(--muted);
}

/* ── Main Area ── */
.main-area {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-width: 0;
}

/* ── Navbar ── */
.navbar {
  height: var(--navbar-height);
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1.25rem;
  gap: 1rem;
  flex-shrink: 0;
}
.navbar-left {
  display: flex;
  align-items: center;
  gap: 0.875rem;
}
.navbar-title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
}
.navbar-right {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

/* Hamburger */
.hamburger {
  display: flex;
  flex-direction: column;
  gap: 4px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 6px;
  border-radius: 6px;
  transition: background 0.15s;
}
.hamburger:hover {
  background: rgba(255, 255, 255, 0.06);
}
.hamburger span {
  display: block;
  width: 18px;
  height: 2px;
  background: var(--muted);
  border-radius: 1px;
  transition: background 0.15s;
}
.hamburger:hover span {
  background: var(--text);
}

/* Search */
.navbar-search {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.375rem 0.75rem;
}
.navbar-search input {
  background: transparent;
  border: none;
  outline: none;
  color: var(--text);
  font-size: 0.875rem;
  width: 180px;
}
.navbar-search input::placeholder {
  color: #475569;
}

/* Icon buttons */
.navbar-icon-btn {
  position: relative;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--muted);
  cursor: pointer;
  transition: color 0.15s, background 0.15s;
}
.navbar-icon-btn:hover {
  color: var(--text);
  background: rgba(255, 255, 255, 0.08);
}
.navbar-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 17px;
  height: 17px;
  background: #ef4444;
  color: #fff;
  font-size: 0.6rem;
  font-weight: 700;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.navbar-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

/* ── Content ── */
.content {
  flex: 1;
  overflow-y: auto;
  padding: 1.75rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}
.content::-webkit-scrollbar {
  width: 6px;
}
.content::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.08);
  border-radius: 3px;
}

.content-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}
.content-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 0.25rem;
}
.content-subtitle {
  font-size: 0.875rem;
  color: var(--muted);
}

/* Stat Grid */
.stat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}
.stat-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.125rem;
  display: flex;
  align-items: flex-start;
  gap: 0.875rem;
  transition: border-color 0.2s;
}
.stat-card:hover {
  border-color: rgba(255, 255, 255, 0.14);
}
.stat-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.stat-icon--blue {
  background: rgba(56, 189, 248, 0.12);
  color: #38bdf8;
}
.stat-icon--green {
  background: rgba(52, 211, 153, 0.12);
  color: #34d399;
}
.stat-icon--purple {
  background: rgba(167, 139, 250, 0.12);
  color: #a78bfa;
}
.stat-icon--cyan {
  background: rgba(34, 211, 238, 0.12);
  color: #22d3ee;
}

.stat-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.stat-label {
  font-size: 0.75rem;
  color: var(--muted);
  font-weight: 500;
}
.stat-value {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--text);
  line-height: 1.2;
}
.stat-change {
  font-size: 0.72rem;
  font-weight: 500;
}
.stat-change--up {
  color: #34d399;
}
.stat-change--down {
  color: #f87171;
}

/* Activity */
.activity-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem;
}
.activity-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.activity-title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text);
}
.activity-view-all {
  background: transparent;
  border: none;
  color: var(--accent);
  font-size: 0.8125rem;
  cursor: pointer;
  font-weight: 500;
}
.activity-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  list-style: none;
}
.activity-item {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 0.875rem 0;
  border-bottom: 1px solid var(--border);
}
.activity-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}
.activity-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-top: 5px;
  flex-shrink: 0;
}
.activity-dot--green {
  background: #34d399;
  box-shadow: 0 0 6px rgba(52, 211, 153, 0.4);
}
.activity-dot--blue {
  background: #38bdf8;
  box-shadow: 0 0 6px rgba(56, 189, 248, 0.4);
}
.activity-dot--yellow {
  background: #fbbf24;
  box-shadow: 0 0 6px rgba(251, 191, 36, 0.4);
}
.activity-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.activity-text {
  font-size: 0.875rem;
  color: #cbd5e1;
}
.activity-text strong {
  color: var(--text);
  font-weight: 600;
}
.activity-time {
  font-size: 0.75rem;
  color: #475569;
}

/* ── Responsive ── */
@media (max-width: 1100px) {
  .stat-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (max-width: 768px) {
  .sidebar {
    position: fixed;
    left: 0;
    top: 0;
    transform: translateX(-100%);
    transition: transform var(--transition);
    width: var(--sidebar-width) !important;
    z-index: 50;
  }
  .sidebar.mobile-open {
    transform: translateX(0);
  }
  .sidebar-collapse-btn {
    display: none;
  }
  .navbar-search {
    display: none;
  }
  .stat-grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 480px) {
  .stat-grid {
    grid-template-columns: 1fr;
  }
  .content {
    padding: 1rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sidebar,
  .sidebar *,
  .sidebar-overlay {
    transition: none !important;
  }
}

/* ── Page content system ── */
.page-content {
  display: none;
  flex-direction: column;
  gap: 1.5rem;
}
.page-content.active {
  display: flex;
}

/* Content action button */
.content-action-btn {
  padding: 0.5625rem 1rem;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  color: #0f172a;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  font-family: inherit;
}
.content-action-btn:hover {
  background: #7dd3fc;
}

/* Analytics */
.analytics-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}
.analytics-card--wide {
  grid-column: 1 / -1;
}
.analytics-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem;
}
.analytics-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.analytics-card-header h3 {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--muted);
}
.analytics-badge {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 999px;
}
.analytics-badge.up {
  background: rgba(52, 211, 153, 0.12);
  color: #34d399;
}
.analytics-badge.down {
  background: rgba(248, 113, 113, 0.12);
  color: #f87171;
}
.chart-placeholder {
  height: 160px;
  display: flex;
  align-items: flex-end;
}
.chart-bars {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  height: 100%;
  width: 100%;
}
.chart-bar {
  flex: 1;
  background: rgba(56, 189, 248, 0.2);
  border-radius: 4px 4px 0 0;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  transition: background 0.15s;
  position: relative;
  min-height: 8px;
}
.chart-bar.active {
  background: #38bdf8;
}
.chart-bar span {
  position: absolute;
  bottom: -1.25rem;
  font-size: 0.65rem;
  color: #475569;
}
.big-metric {
  font-size: 2rem;
  font-weight: 800;
  color: var(--text);
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
}
.metric-delta {
  font-size: 0.8125rem;
  font-weight: 600;
}
.metric-delta.up {
  color: #34d399;
}
.metric-delta.down {
  color: #f87171;
}
.metric-desc {
  font-size: 0.8125rem;
  color: var(--muted);
  margin-top: 0.25rem;
}

/* Users */
.users-list-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
}
.users-search-bar {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border);
}
.users-row {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  align-items: center;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border);
  gap: 0.5rem;
}
.users-row:last-child {
  border-bottom: none;
}
.users-row--header {
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #475569;
  background: rgba(255, 255, 255, 0.02);
}
.users-cell-user {
  display: flex;
  align-items: center;
  gap: 0.625rem;
}
.user-av {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.625rem;
  font-weight: 700;
  color: #0f172a;
  flex-shrink: 0;
}
.user-name {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text);
}
.user-email {
  font-size: 0.75rem;
  color: var(--muted);
}
.role-chip {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 999px;
}
.role-chip--admin {
  background: rgba(167, 139, 250, 0.15);
  color: #a78bfa;
}
.role-chip--editor {
  background: rgba(56, 189, 248, 0.12);
  color: #38bdf8;
}
.role-chip--viewer {
  background: rgba(255, 255, 255, 0.06);
  color: #94a3b8;
}
.status-dot {
  font-size: 0.75rem;
  font-weight: 500;
}
.status-dot--active {
  color: #34d399;
}
.status-dot--inactive {
  color: #64748b;
}
.status-dot--pending {
  color: #fbbf24;
}
.user-date {
  font-size: 0.75rem;
  color: var(--muted);
}

/* Orders */
.orders-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
}
.orders-row {
  display: grid;
  grid-template-columns: 1fr 2fr 1fr 1.5fr 1fr;
  align-items: center;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border);
  gap: 0.5rem;
  font-size: 0.8125rem;
}
.orders-row--header {
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #475569;
  background: rgba(255, 255, 255, 0.02);
}
.orders-row:last-child {
  border-bottom: none;
}
.order-id {
  font-family: monospace;
  color: var(--accent);
  font-size: 0.8rem;
}
.order-amount {
  font-weight: 700;
  color: var(--text);
}
.order-status {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 999px;
  text-align: center;
}
.order-status--shipped {
  background: rgba(56, 189, 248, 0.12);
  color: #38bdf8;
}
.order-status--processing {
  background: rgba(251, 191, 36, 0.12);
  color: #fbbf24;
}
.order-status--delivered {
  background: rgba(52, 211, 153, 0.12);
  color: #34d399;
}
.order-status--cancelled {
  background: rgba(248, 113, 113, 0.12);
  color: #f87171;
}
.order-date {
  font-size: 0.75rem;
  color: var(--muted);
}

/* Products */
.products-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}
.product-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1rem;
  display: flex;
  gap: 0.875rem;
  align-items: center;
  transition: border-color 0.15s;
}
.product-card:hover {
  border-color: rgba(255, 255, 255, 0.14);
}
.product-img {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  font-weight: 800;
  color: rgba(255, 255, 255, 0.9);
  flex-shrink: 0;
}
.product-info {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}
.product-name {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text);
}
.product-price {
  font-size: 0.8125rem;
  color: var(--accent);
  font-weight: 600;
}
.product-stock {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 999px;
}
.in-stock {
  background: rgba(52, 211, 153, 0.1);
  color: #34d399;
}
.low-stock {
  background: rgba(251, 191, 36, 0.1);
  color: #fbbf24;
}

/* Settings */
.settings-sections {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}
.settings-section {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
}
.settings-section-title {
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 0.25rem;
}
.settings-row,
.settings-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}
.settings-label {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.settings-label span {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text);
}
.settings-label small {
  font-size: 0.75rem;
  color: var(--muted);
}
.settings-input {
  padding: 0.4375rem 0.75rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.875rem;
  font-family: inherit;
  outline: none;
  min-width: 200px;
}
.settings-input:focus {
  border-color: var(--accent);
}
.stoggle {
  position: relative;
  display: inline-block;
  cursor: pointer;
}
.stoggle input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}
.stoggle-track {
  display: block;
  width: 2.25rem;
  height: 1.25rem;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  transition: background 0.2s;
  position: relative;
}
.stoggle-track::after {
  content: "";
  position: absolute;
  width: 0.875rem;
  height: 0.875rem;
  background: #fff;
  border-radius: 50%;
  top: 3px;
  left: 3px;
  transition: transform 0.2s;
}
.stoggle input:checked + .stoggle-track {
  background: var(--accent);
}
.stoggle input:checked + .stoggle-track::after {
  transform: translateX(1rem);
}
.settings-save-btn {
  padding: 0.625rem 1.5rem;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  color: #0f172a;
  font-size: 0.9rem;
  font-weight: 700;
  cursor: pointer;
  align-self: flex-start;
  font-family: inherit;
}
.settings-save-btn:hover {
  background: #7dd3fc;
}

@media (max-width: 768px) {
  .analytics-grid {
    grid-template-columns: 1fr;
  }
  .analytics-card--wide {
    grid-column: 1;
  }
  .products-grid {
    grid-template-columns: 1fr;
  }
  .orders-row {
    grid-template-columns: 1fr 1.5fr 1fr;
  }
  .orders-row > :nth-child(4),
  .orders-row > :nth-child(5) {
    display: none;
  }
  .users-row {
    grid-template-columns: 2fr 1fr 1fr;
  }
  .users-row > :nth-child(4) {
    display: none;
  }
}

