*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #0f172a;
  color: #f1f5f9;
  min-height: 100vh;
  padding: 1.5rem;
}

/* ── Dashboard header ── */
.dashboard-header {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}
.dashboard-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: #f1f5f9;
}
.dashboard-subtitle {
  font-size: 0.8125rem;
  color: #475569;
}

/* ── Widget Grid ── */
.widget-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  align-items: start;
}

/* ── Widget Card ── */
.widget {
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 12px;
  overflow: hidden;
  transition: opacity 0.3s ease, transform 0.3s ease;
}
.widget.closing {
  opacity: 0;
  transform: scale(0.96);
  pointer-events: none;
}

/* ── Widget Header ── */
.widget-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 0.875rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.02);
  gap: 0.5rem;
}
.widget.minimized .widget-header {
  border-bottom: none;
}
.widget-header-left {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.widget-icon {
  width: 26px;
  height: 26px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.widget-icon--green {
  background: rgba(52, 211, 153, 0.12);
  color: #34d399;
}
.widget-icon--blue {
  background: rgba(56, 189, 248, 0.12);
  color: #38bdf8;
}
.widget-icon--purple {
  background: rgba(167, 139, 250, 0.12);
  color: #a78bfa;
}
.widget-icon--cyan {
  background: rgba(34, 211, 238, 0.12);
  color: #22d3ee;
}
.widget-title {
  font-size: 0.8125rem;
  font-weight: 600;
  color: #e2e8f0;
}

/* Controls */
.widget-controls {
  display: flex;
  align-items: center;
  gap: 0.375rem;
}
.widget-timestamp {
  font-size: 0.6875rem;
  color: #475569;
  white-space: nowrap;
}
.widget-btn {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  color: #64748b;
  border-radius: 5px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.widget-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #cbd5e1;
}
.widget-btn--close:hover {
  background: rgba(239, 68, 68, 0.15);
  color: #f87171;
}

/* Refresh spin */
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.widget-btn.refreshing .refresh-icon {
  animation: spin 0.8s linear infinite;
}

/* ── Widget Body ── */
.widget-body {
  padding: 1rem 0.875rem;
  display: grid;
  grid-template-rows: 1fr;
  transition: grid-template-rows 0.3s ease;
  overflow: hidden;
}
.widget.minimized .widget-body {
  grid-template-rows: 0fr;
  padding-top: 0;
  padding-bottom: 0;
}
.widget-body > * {
  overflow: hidden;
}

/* ── Bar Chart ── */
.bar-chart {
  display: flex;
  gap: 0.625rem;
  height: 140px;
}
.bar-labels {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 2px 0;
  text-align: right;
}
.bar-labels span {
  font-size: 0.65rem;
  color: #475569;
}
.bars {
  flex: 1;
  display: flex;
  align-items: flex-end;
  gap: 0.5rem;
}
.bar-col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.375rem;
  height: 100%;
  justify-content: flex-end;
}
.bar {
  position: relative;
  width: 100%;
  height: var(--h);
  background: rgba(255, 255, 255, 0.08);
  border-radius: 4px 4px 2px 2px;
  transition: background 0.2s;
}
.bar:hover {
  background: rgba(255, 255, 255, 0.14);
}
.bar--accent {
  background: rgba(56, 189, 248, 0.5);
}
.bar--accent:hover {
  background: rgba(56, 189, 248, 0.65);
}
.bar--live {
  background: rgba(52, 211, 153, 0.35);
}
.bar--live:hover {
  background: rgba(52, 211, 153, 0.5);
}
.bar-tip {
  position: absolute;
  bottom: calc(100% + 4px);
  left: 50%;
  transform: translateX(-50%);
  background: #334155;
  color: #f1f5f9;
  font-size: 0.6rem;
  padding: 2px 5px;
  border-radius: 4px;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s;
}
.bar:hover .bar-tip {
  opacity: 1;
}
.bar-name {
  font-size: 0.65rem;
  color: #64748b;
}

/* ── User List ── */
.user-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
}
.user-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}
.user-row:last-child {
  border-bottom: none;
}
.user-av {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--c, #6366f1);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  opacity: 0.9;
}
.user-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}
.user-name {
  font-size: 0.8125rem;
  font-weight: 500;
  color: #e2e8f0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.user-email {
  font-size: 0.7rem;
  color: #64748b;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.status-badge {
  font-size: 0.65rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 20px;
  white-space: nowrap;
}
.status-badge--active {
  background: rgba(52, 211, 153, 0.12);
  color: #34d399;
}
.status-badge--pending {
  background: rgba(251, 191, 36, 0.12);
  color: #fbbf24;
}
.status-badge--inactive {
  background: rgba(148, 163, 184, 0.1);
  color: #94a3b8;
}

/* ── Task List ── */
.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-bottom: 0.875rem;
}
.task-item {
  padding: 0.45rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}
.task-item:last-child {
  border-bottom: none;
}
.task-label {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  cursor: pointer;
}
.task-label input[type="checkbox"] {
  display: none;
}
.task-check {
  width: 16px;
  height: 16px;
  border: 2px solid #334155;
  border-radius: 4px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s, border-color 0.15s;
  position: relative;
}
.task-label input:checked + .task-check {
  background: #38bdf8;
  border-color: #38bdf8;
}
.task-label input:checked + .task-check::after {
  content: "";
  display: block;
  width: 4px;
  height: 7px;
  border: 2px solid #0f172a;
  border-top: none;
  border-left: none;
  transform: rotate(45deg) translate(-1px, -1px);
}
.task-text {
  font-size: 0.8125rem;
  color: #cbd5e1;
  transition: color 0.15s, text-decoration 0.15s;
}
.task-label input:checked ~ .task-text {
  color: #475569;
  text-decoration: line-through;
}

.task-progress {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}
.task-progress-bar {
  height: 4px;
  background: rgba(255, 255, 255, 0.07);
  border-radius: 2px;
  overflow: hidden;
}
.task-progress-fill {
  height: 100%;
  background: #38bdf8;
  border-radius: 2px;
  transition: width 0.4s ease;
}
.task-progress-label {
  font-size: 0.7rem;
  color: #64748b;
}

/* ── Health Bars ── */
.health-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.health-item {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}
.health-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.health-label {
  font-size: 0.8rem;
  color: #94a3b8;
}
.health-val {
  font-size: 0.8rem;
  font-weight: 600;
}
.health-val--ok {
  color: #34d399;
}
.health-val--warn {
  color: #fbbf24;
}
.health-val--crit {
  color: #f87171;
}
.health-bar {
  height: 6px;
  background: rgba(255, 255, 255, 0.07);
  border-radius: 3px;
  overflow: hidden;
}
.health-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.6s ease;
}
.health-fill--ok {
  background: linear-gradient(90deg, #059669, #34d399);
}
.health-fill--warn {
  background: linear-gradient(90deg, #d97706, #fbbf24);
}
.health-fill--crit {
  background: linear-gradient(90deg, #dc2626, #f87171);
}

/* ── Restore Bar ── */
.restore-bar {
  position: fixed;
  bottom: 1.5rem;
  left: 50%;
  transform: translateX(-50%) translateY(100px);
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  padding: 0.75rem 1rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  transition: transform 0.3s cubic-bezier(0.34, 1.2, 0.64, 1);
  z-index: 200;
  white-space: nowrap;
}
.restore-bar.visible {
  transform: translateX(-50%) translateY(0);
}
.restore-msg {
  font-size: 0.875rem;
  color: #94a3b8;
}
.restore-btn {
  background: #38bdf8;
  color: #0f172a;
  border: none;
  border-radius: 6px;
  padding: 0.3rem 0.75rem;
  font-size: 0.8125rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
}
.restore-btn:hover {
  background: #7dd3fc;
}

/* ── Responsive ── */
@media (max-width: 640px) {
  .widget-grid {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .widget,
  .widget-body,
  .restore-bar {
    transition: none !important;
  }
  .widget-btn.refreshing .refresh-icon {
    animation: none;
  }
}

