  color: #38bdf8;
}

/* ── Grid layout ── */
.es-grid-wrapper {
  display: flex;
  overflow: hidden;
  min-height: 0;
}

/* ── Employee panel ── */
.es-employee-panel {
  width: 200px;
  flex-shrink: 0;
  border-right: 1px solid rgba(255, 255, 255, 0.06);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.es-panel-header {
  display: flex;
  justify-content: space-between;
  padding: 0.625rem 1rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.02);
  font-size: 0.7rem;
  font-weight: 600;
  color: #475569;
