  align-items: center;
  justify-content: space-between;
  padding: 0.5rem 1rem;
  height: 60px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
  gap: 0.5rem;
}
.es-employee-info {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex: 1;
  min-width: 0;
}
.es-emp-avatar {
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.6rem;
  font-weight: 700;
  color: #0f172a;
  flex-shrink: 0;
}
.es-emp-meta {
  min-width: 0;
}
.es-emp-name {
  font-size: 0.8rem;
  font-weight: 600;
  color: #e2e8f0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.es-emp-role {
  font-size: 0.65rem;
  color: #64748b;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.es-emp-hours {
  font-size: 0.75rem;
  font-weight: 600;
  color: #94a3b8;
  white-space: nowrap;
}

.es-summary-label {
  height: 40px;
  display: flex;
  align-items: center;
  padding: 0 1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
