  font-size: 0.75rem;
  font-weight: 600;
  color: #475569;
}

/* ── Day grid ── */
.es-day-grid {
  flex: 1;
  overflow-x: auto;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.es-day-headers {
