  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-right: 1px solid rgba(255, 255, 255, 0.04);
  padding: 0.25rem;
}
.es-day-name {
  font-size: 0.7rem;
  font-weight: 600;
  color: #475569;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.es-day-date {
  font-size: 0.8rem;
  font-weight: 700;
  color: #94a3b8;
}
.es-day-header-cell.today .es-day-date {
  color: #38bdf8;
}
.es-day-header-cell.today .es-day-name {
  color: #38bdf8;
}

/* ── Schedule rows ── */
.es-schedule-rows {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.es-row {
  display: flex;
  height: 60px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
  flex-shrink: 0;
}

.es-cell {
  flex: 1;
  min-width: 120px;
  border-right: 1px solid rgba(255, 255, 255, 0.04);
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  padding: 0.3125rem;
  cursor: pointer;
  position: relative;
  transition: background 0.12s;
}
.es-cell:hover {
  background: rgba(255, 255, 255, 0.03);
}
.es-cell.conflict {
  box-shadow: inset 0 0 0 2px rgba(248, 113, 113, 0.5);
}

.es-cell-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  font-size: 0.7rem;
  color: #334155;
  transition: color 0.12s;
}
.es-cell:hover .es-cell-empty {
  color: #64748b;
}

/* ── Shift block ── */
.shift-block {
  border-radius: 0.35rem;
  padding: 0.25rem 0.5rem;
  font-size: 0.7rem;
  font-weight: 600;
  color: #0f172a;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  transition: opacity 0.12s;
}
.shift-block:hover {
  opacity: 0.85;
}

.shift-block .shift-type {
  font-size: 0.65rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.shift-block .shift-time {
  font-size: 0.6rem;
  opacity: 0.8;
  margin-top: 0.1rem;
}

/* ── Summary row ── */
.es-summary-row {
  display: flex;
  height: 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.02);
  flex-shrink: 0;
}
.es-summary-cell {
  flex: 1;
  min-width: 120px;
  border-right: 1px solid rgba(255, 255, 255, 0.04);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  color: #64748b;
}
.es-summary-cell .sum-count {
  font-weight: 700;
  color: #94a3b8;
  font-size: 0.8rem;
}
.es-summary-cell .sum-hours {
  font-size: 0.65rem;
}

/* ── Shift popup ── */
.popup-overlay {
  position: fixed;
  inset: 0;
  z-index: 99;
  display: none;
}
.popup-overlay.visible {
  display: block;
}

.shift-popup {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0.95);
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 0.875rem;
  width: min(340px, 90vw);
  z-index: 100;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.18s, transform 0.18s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.shift-popup.open {
  opacity: 1;
  pointer-events: all;
  transform: translate(-50%, -50%) scale(1);
}

.shift-popup-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.875rem 1.125rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  font-size: 0.9375rem;
  font-weight: 700;
  color: #f1f5f9;
}
.popup-close {
  background: transparent;
  border: none;
  color: #64748b;
  font-size: 0.9rem;
  cursor: pointer;
}
.popup-close:hover {
  color: #f1f5f9;
}

.shift-popup-body {
  padding: 1rem 1.125rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.shift-popup-footer {
  display: flex;
  align-items: center;
  padding: 0.75rem 1.125rem;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

/* ── Form ── */
.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  flex: 1;
}
.form-row {
  display: flex;
  gap: 0.5rem;
}
.form-label {
  font-size: 0.75rem;
  font-weight: 500;
  color: #64748b;
}
.form-input {
  width: 100%;
  padding: 0.4375rem 0.625rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.4375rem;
  color: #f1f5f9;
  font-size: 0.8125rem;
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s;
}
.form-input:focus {
  border-color: #38bdf8;
}
.form-input option {
  background: #1e293b;
}

/* ── Toast ── */
.es-toast {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  background: #0f172a;
  border: 1px solid rgba(56, 189, 248, 0.3);
  border-radius: 0.75rem;
  padding: 0.75rem 1.125rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: #f1f5f9;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  z-index: 500;
  transform: translateY(8px);
  opacity: 0;
  transition: opacity 0.25s, transform 0.25s;
  pointer-events: none;
}
.es-toast.show {
  opacity: 1;
  transform: translateY(0);
}

/* ── Scrollbars ── */
::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
}

.es-day-grid::-webkit-scrollbar {
  height: 5px;
  width: 5px;
}
.es-day-grid::-webkit-scrollbar-track {
  background: transparent;
}
.es-day-grid::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 3px;
}

