*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #0f172a;
  color: #f1f5f9;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
}

/* ── Header ── */
.kb-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  gap: 1rem;
  flex-wrap: wrap;
  flex-shrink: 0;
}

.kb-header-left {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.kb-title {
  font-size: 1.25rem;
  font-weight: 800;
  color: #f1f5f9;
}

.kb-sprint-badge {
  padding: 0.25rem 0.625rem;
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.2);
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 600;
  color: #38bdf8;
}

.kb-header-right {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.kb-search-wrap {
  position: relative;
  display: flex;
  align-items: center;
}
.kb-search-icon {
  position: absolute;
  left: 0.625rem;
  color: #475569;
  pointer-events: none;
}
.kb-search {
  padding: 0.4375rem 0.75rem 0.4375rem 2rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.5rem;
  color: #f1f5f9;
  font-size: 0.8125rem;
  font-family: inherit;
  outline: none;
  width: 180px;
  transition: border-color 0.15s;
}
.kb-search:focus {
  border-color: #38bdf8;
}
.kb-search::placeholder {
  color: #475569;
}

.kb-assignee-filter {
  display: flex;
  align-items: center;
