*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: #0f172a;
  color: #f1f5f9;
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 2rem 1rem;
}

/* ── Wrapper ── */
.cal-wrapper {
  width: min(960px, 100%);
  display: flex;
  flex-direction: column;
  gap: 0;
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 1.25rem;
  overflow: hidden;
}

/* ── Header ── */
.cal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  gap: 1rem;
  flex-wrap: wrap;
}

.cal-header-left,
.cal-header-right {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.cal-month-label {
  font-size: 1.125rem;
  font-weight: 700;
  color: #f1f5f9;
  min-width: 10rem;
  text-align: center;
}

/* ── Buttons ── */
.btn-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.5rem;
  color: #94a3b8;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.btn-icon:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #f1f5f9;
}

.btn-primary {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.5rem 1rem;
  background: #38bdf8;
  border: none;
  border-radius: 0.625rem;
  color: #0f172a;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
}
.btn-primary:hover {
  background: #7dd3fc;
}

.btn-secondary {
  padding: 0.5rem 0.875rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.625rem;
  color: #94a3b8;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #f1f5f9;
}

.btn-danger {
  padding: 0.5rem 0.875rem;
  background: rgba(248, 113, 113, 0.12);
  border: 1px solid rgba(248, 113, 113, 0.2);
  border-radius: 0.625rem;
  color: #f87171;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s;
}
.btn-danger:hover {
  background: rgba(248, 113, 113, 0.2);
}

/* ── View toggle ── */
.view-toggle {
  display: flex;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.5rem;
  overflow: hidden;
}
.view-btn {
  padding: 0.375rem 0.75rem;
  background: transparent;
  border: none;
  color: #64748b;
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.view-btn.active {
  background: rgba(56, 189, 248, 0.15);
  color: #38bdf8;
}

/* ── Day-of-week header ── */
.cal-dow-header {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.02);
}
.cal-dow-header > div {
  padding: 0.625rem 0.75rem;
  font-size: 0.75rem;
  font-weight: 600;
  color: #475569;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ── Calendar Grid ── */
.cal-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  grid-auto-rows: minmax(112px, 1fr);
  border-left: 1px solid rgba(255, 255, 255, 0.04);
}

.cal-cell {
  border-right: 1px solid rgba(255, 255, 255, 0.04);
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
  padding: 0.375rem;
  cursor: pointer;
  transition: background 0.12s;
  min-height: 112px;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}
.cal-cell:hover {
  background: rgba(255, 255, 255, 0.03);
}

.cal-cell.other-month {
  opacity: 0.3;
}
.cal-cell.other-month:hover {
  opacity: 0.45;
}

.cal-cell.today .cal-date-num {
  background: #38bdf8;
  color: #0f172a;
  border-radius: 50%;
  width: 1.625rem;
  height: 1.625rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cal-date-num {
  font-size: 0.8125rem;
  font-weight: 600;
  color: #64748b;
  align-self: flex-end;
  line-height: 1;
  padding: 0.2rem 0.3rem;
}
.cal-cell.today .cal-date-num {
  color: #0f172a;
  padding: 0;
}

/* ── Event pills ── */
.cal-event-pill {
  display: block;
  width: 100%;
  padding: 0.2rem 0.4rem;
  border-radius: 0.3rem;
  font-size: 0.7rem;
  font-weight: 500;
  color: #0f172a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: pointer;
  transition: opacity 0.12s;
  line-height: 1.4;
}
.cal-event-pill:hover {
  opacity: 0.85;
}

.cal-event-pill.multi-start {
  border-radius: 0.3rem 0 0 0.3rem;
}
.cal-event-pill.multi-mid {
  border-radius: 0;
  opacity: 0.75;
  font-size: 0.01px;
  color: transparent;
}
.cal-event-pill.multi-end {
  border-radius: 0 0.3rem 0.3rem 0;
}

.cal-more-link {
  font-size: 0.7rem;
  color: #64748b;
  padding: 0 0.3rem;
  cursor: pointer;
}
.cal-more-link:hover {
  color: #38bdf8;
}

/* ── Modal ── */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 1rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
}
.modal-backdrop.open {
  opacity: 1;
  pointer-events: all;
}

.modal {
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 1rem;
  width: min(520px, 100%);
  max-height: 90vh;
  overflow-y: auto;
  transform: scale(0.96) translateY(8px);
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.modal-backdrop.open .modal {
  transform: scale(1) translateY(0);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.modal-title {
  font-size: 1.0625rem;
  font-weight: 700;
  color: #f1f5f9;
}
.modal-close {
  margin-left: auto;
}

.modal-body {
  padding: 1.25rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.modal-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.5rem;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}
.modal-footer-right {
  display: flex;
  gap: 0.5rem;
}

/* ── Form ── */
.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  flex: 1;
}
.form-row {
  display: flex;
  gap: 0.75rem;
}
.form-label {
  font-size: 0.8125rem;
  font-weight: 500;
  color: #94a3b8;
}
.form-input {
  width: 100%;
  padding: 0.5rem 0.75rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.5rem;
  color: #f1f5f9;
  font-size: 0.875rem;
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s;
}
.form-input:focus {
  border-color: #38bdf8;
}
.form-input option {
  background: #1e293b;
}
.form-textarea {
  resize: vertical;
  min-height: 5rem;
}

/* ── Color swatches ── */
.color-swatches {
  display: flex;
  gap: 0.5rem;
}
.swatch {
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 50%;
  border: 2px solid transparent;
  cursor: pointer;
  transition: transform 0.12s, border-color 0.12s;
}
.swatch:hover {
  transform: scale(1.15);
}
.swatch.active {
  border-color: #f1f5f9;
  transform: scale(1.1);
}

/* ── Week View ── */
.week-grid {
  display: none; /* shown via JS */
  grid-template-columns: repeat(7, 1fr);
  gap: 1px;
  background: rgba(255, 255, 255, 0.04);
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.week-col {
  background: #0f172a;
  display: flex;
  flex-direction: column;
  min-height: 480px;
  cursor: pointer;
  transition: background 0.12s;
}
.week-col:hover {
  background: #111827;
}
.week-col--today {
  background: rgba(56, 189, 248, 0.04);
}
.week-col--today:hover {
  background: rgba(56, 189, 248, 0.07);
}

.week-day-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0.75rem 0.375rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  gap: 0.25rem;
  flex-shrink: 0;
}
.week-day-name {
  font-size: 0.6875rem;
  font-weight: 600;
  color: #475569;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.week-day-num {
  font-size: 1rem;
  font-weight: 700;
  color: #94a3b8;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
}
.today-num {
  background: #38bdf8;
  color: #0f172a;
}

.week-event-pill {
  margin: 0.25rem 0.375rem;
  padding: 0.375rem 0.5rem;
  border-radius: 0.35rem;
  border: none;
  color: #0f172a;
  font-size: 0.75rem;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 1px;
  transition: opacity 0.15s, transform 0.15s;
  width: calc(100% - 0.75rem);
}
.week-event-pill:hover {
  opacity: 0.85;
  transform: translateY(-1px);
}
.week-event-time {
  font-size: 0.65rem;
  opacity: 0.8;
  font-weight: 500;
}
.week-event-title {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── Scrollbar ── */
::-webkit-scrollbar {
  width: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
}

