.av-person {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 1.25rem 1.5rem 0;
}

.av-avatar {
  width: 3rem;
  height: 3rem;
  border-radius: 50%;
  background: linear-gradient(135deg, #38bdf8, #a78bfa);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  font-weight: 800;
  color: #0f172a;
  flex-shrink: 0;
}

.av-person-name {
  font-size: 1rem;
  font-weight: 700;
  color: #f1f5f9;
}
.av-person-meta {
  display: flex;
