*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #050910;
  --text: #f2f6ff;
  --muted: #475569;
  --accent: #38bdf8;
  --nav-bg: #0d1117;
  --border: rgba(255, 255, 255, 0.08);
  --tab-count: 5;
}

body {
  font-family: Inter, system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

/* ── Demo wrapper ── */
.demo {
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}
.demo-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.375rem;
  text-align: center;
}
.demo-sub {
  color: var(--muted);
  font-size: 0.875rem;
  text-align: center;
}

/* ── Phone frame ── */
.phone-frame {
  width: 320px;
  border-radius: 32px;
  border: 1.5px solid var(--border);
  background: var(--nav-bg);
  overflow: hidden;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.5), 0 0 0 1px rgba(255, 255, 255, 0.04);
}

.phone-screen {
  height: 280px;
  background: linear-gradient(135deg, #0d1117 0%, #0a0f1a 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  border-bottom: 1px solid var(--border);
}

.screen-content {
  text-align: center;
  transition: opacity 0.2s, transform 0.2s;
}

.screen-content.fade {
  opacity: 0;
  transform: translateY(6px);
}

.screen-icon {
  font-size: 3rem;
  margin-bottom: 0.625rem;
}
.screen-label {
  color: var(--muted);
  font-size: 0.875rem;
  font-weight: 500;
}

/* ── Bottom nav ── */
.bottom-nav {
  position: relative;
  display: flex;
  align-items: stretch;
  height: 68px;
  background: var(--nav-bg);
  padding: 0 0.25rem;
}

/* Sliding indicator */
.bottom-nav__indicator {
  position: absolute;
  top: 0;
  left: calc(var(--active-index, 0) / var(--tab-count) * 100%);
  width: calc(100% / var(--tab-count));
  height: 2px;
  background: var(--accent);
  border-radius: 0 0 3px 3px;
  transition: left 0.28s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ── Tab ── */
.tab {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--muted);
  padding: 0.5rem 0;
  transition: color 0.2s;
  position: relative;
  -webkit-tap-highlight-color: transparent;
}

.tab:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
  border-radius: 8px;
}

.tab--active {
  color: var(--accent);
}

.tab__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  width: 24px;
  height: 24px;
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.tab--active .tab__icon {
  transform: translateY(-2px);
}

.tab__label {
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 0.01em;
  transition: opacity 0.2s;
}

/* ── Add tab ── */
.tab--add {
  color: #050910;
  gap: 0;
}

.tab--add .tab__icon {
  width: 44px;
  height: 44px;
  background: var(--accent);
  border-radius: 50%;
  margin-top: -16px;
  box-shadow: 0 4px 16px rgba(56, 189, 248, 0.35);
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.2s;
}

.tab--add:hover .tab__icon,
.tab--add.tab--active .tab__icon {
  transform: scale(1.1);
  box-shadow: 0 6px 20px rgba(56, 189, 248, 0.5);
}

.tab--add svg {
  color: #050910;
}

/* ── Badge ── */
.tab__icon--badge {
  position: relative;
}

.tab__badge {
  position: absolute;
  top: -4px;
  right: -6px;
  min-width: 16px;
  height: 16px;
  background: #ef4444;
  color: #fff;
  font-size: 0.6rem;
  font-weight: 700;
  border-radius: 999px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
  border: 1.5px solid var(--nav-bg);
  line-height: 1;
}

