/* ── Reset & Base ──────────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --dark: #050910;
  --dark2: #0d1117;
  --accent: #1db954;
  --text: #f2f6ff;
  --muted: #64748b;
  --border: rgba(242, 246, 255, 0.08);
  --surface: rgba(242, 246, 255, 0.04);
  --radius: 12px;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--dark);
  color: var(--text);
  font-family: system-ui, "Inter", -apple-system, sans-serif;
  line-height: 1.6;
  overflow-x: hidden;
}

/* ── Nav ───────────────────────────────────────────────────────────────────── */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 48px;
  background: rgba(5, 9, 16, 0.8);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text);
  text-decoration: none;
}

.nav-logo-icon {
  color: var(--accent);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.nav-links a {
  color: var(--muted);
  text-decoration: none;
  font-size: 0.875rem;
  font-weight: 500;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--text);
}

.btn-subscribe {
  background: var(--accent);
  color: #000;
  border: none;
  padding: 9px 20px;
  border-radius: 50px;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.2s, transform 0.2s;
}

.btn-subscribe:hover {
  opacity: 0.85;
  transform: translateY(-1px);
}

/* ── Hero ──────────────────────────────────────────────────────────────────── */
.hero {
  min-height: 100vh;
  padding: 120px 48px 80px;
  background: radial-gradient(
    ellipse 80% 60% at 60% 50%,
    rgba(29, 185, 84, 0.06) 0%,
    transparent 70%
  );
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 32px;
}

.live-dot {
  width: 6px;
  height: 6px;
  background: var(--accent);
  border-radius: 50%;
