}

@keyframes live-pulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.35;
    transform: scale(0.6);
  }
}

.hero-content {
  display: flex;
  align-items: flex-start;
  gap: 64px;
}

.hero-text {
