:root {
  --bg: #050910;
  --card: #0d1117;
  --text: #f2f6ff;
  --muted: #475569;
  --border: rgba(255, 255, 255, 0.08);
  --accent: #38bdf8;
  --accent-dim: rgba(56, 189, 248, 0.15);
  --complete: #34d399;
  --complete-dim: rgba(52, 211, 153, 0.15);
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

body {
  font-family: Inter, system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

.demo {
  width: 100%;
  max-width: 520px;
}
.demo-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.375rem;
}
.demo-sub {
  color: var(--muted);
  font-size: 0.875rem;
  margin-bottom: 2.5rem;
}

/* ── Stepper ── */
.stepper {
  margin-bottom: 0;
}

.steps-track {
  display: flex;
  align-items: center;
  margin-bottom: 0.625rem;
}

/* ── Step ── */
.step {
  display: flex;
  align-items: center;
  flex: 1;
}

.step:last-child {
  flex: 0;
}

.step__node {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2px solid var(--border);
  background: var(--card);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  position: relative;
  transition: border-color var(--transition), background var(--transition), box-shadow
    var(--transition);
  cursor: default;
  z-index: 1;
}

.step__num {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--muted);
  transition: opacity var(--transition);
}

.step__check {
  position: absolute;
  inset: 0;
  margin: auto;
  color: var(--complete);
  opacity: 0;
  transform: scale(0.6);
  transition: opacity var(--transition), transform var(--transition);
}

/* Active */
.step.is-active .step__node {
  border-color: var(--accent);
  background: var(--accent-dim);
  box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.12);
}

.step.is-active .step__num {
  color: var(--accent);
}

/* Complete */
.step.is-complete .step__node {
  border-color: var(--complete);
  background: var(--complete-dim);
}

.step.is-complete .step__num {
  opacity: 0;
}
.step.is-complete .step__check {
  opacity: 1;
  transform: scale(1);
}

/* ── Connector ── */
.step__connector {
  flex: 1;
  height: 2px;
  background: var(--border);
  position: relative;
  overflow: hidden;
  margin: 0 4px;
  border-radius: 1px;
}

.step__fill {
  display: block;
  height: 100%;
  width: 0%;
  background: var(--complete);
  border-radius: 1px;
  transition: width 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.step.is-complete .step__fill {
  width: 100%;
}

/* ── Step labels ── */
.steps-labels {
  display: flex;
  justify-content: space-between;
  margin-bottom: 2rem;
}

.step-label {
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--muted);
  text-align: center;
  transition: color var(--transition);
  width: 36px;
  text-align: center;
}

.step-label--active {
  color: var(--accent);
  font-weight: 600;
}
.step-label--complete {
  color: var(--complete);
}

/* ── Step panel ── */
.step-panel {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  min-height: 100px;
  transition: opacity 0.2s, transform 0.2s;
}

.step-panel.fade {
  opacity: 0;
  transform: translateX(8px);
}

.panel-title {
  font-size: 1.0625rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.panel-desc {
  font-size: 0.875rem;
  color: var(--muted);
  line-height: 1.6;
}

/* ── Actions ── */
.step-actions {
  display: flex;
  gap: 0.75rem;
  justify-content: flex-end;
}

.btn {
  padding: 0.5rem 1.25rem;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: opacity 0.2s, background 0.2s, color 0.2s;
}

.btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.btn--ghost {
  background: rgba(255, 255, 255, 0.06);
  color: var(--text);
  border: 1px solid var(--border);
}

.btn--ghost:not(:disabled):hover {
  background: rgba(255, 255, 255, 0.1);
}

.btn--primary {
  background: var(--accent);
  color: #050910;
}

.btn--primary:not(:disabled):hover {
  opacity: 0.85;
}

.btn--success {
  background: var(--complete);
  color: #050910;
}

