  align-items: center;
}
.row--wrap {
  align-items: flex-start;
}

/* ── Indicator wrapper ── */
.indicator {
  position: relative;
  display: inline-flex;
}

/* ── Badge base ── */
.indicator__badge {
  position: absolute;
  top: 0;
  right: 0;
  transform: translate(35%, -35%);
  z-index: 1;
  flex-shrink: 0;
}

/* ── Online dot ── */
.indicator__badge--online,
.indicator__badge--away,
.indicator__badge--offline {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  border: 2px solid #050910;
}

.indicator__badge--online {
  background: #22c55e;
  box-shadow: 0 0 0 2px rgba(34, 197, 94, 0.3);
  animation: pulse-green 2s ease-in-out infinite;
}
.indicator__badge--away {
  background: #f59e0b;
}
.indicator__badge--offline {
  background: #475569;
}

@keyframes pulse-green {
  0%,
  100% {
    box-shadow: 0 0 0 2px rgba(34, 197, 94, 0.3);
  }
  50% {
    box-shadow: 0 0 0 5px rgba(34, 197, 94, 0.0);
  }
}

/* ── Count badge ── */
.indicator__badge--count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  border-radius: 999px;
  font-size: 0.65rem;
  font-weight: 700;
  line-height: 1;
  border: 2px solid #050910;
  color: #fff;
}

/* ── Label badge ── */
.indicator__badge--label {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.5rem;
  border-radius: 999px;
  font-size: 0.65rem;
  font-weight: 700;
  line-height: 1;
  border: 2px solid #050910;
  color: #fff;
  white-space: nowrap;
  transform: translate(25%, -40%);
}

/* ── Alert dot ── */
.indicator__badge--dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: 2px solid #050910;
}

/* ── Color modifiers ── */
.indicator__badge--red {
  background: #ef4444;
}
.indicator__badge--blue {
  background: #3b82f6;
}
.indicator__badge--green {
  background: #22c55e;
}
.indicator__badge--amber {
  background: #f59e0b;
}
.indicator__badge--purple {
  background: #a78bfa;
}

/* ── Avatar ── */
.avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, #3b82f6, #2563eb);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  font-weight: 700;
  color: #fff;
  user-select: none;
}
.avatar--purple {
  background: linear-gradient(135deg, #8b5cf6, #7c3aed);
}
.avatar--slate {
  background: linear-gradient(135deg, #475569, #334155);
}

/* ── Button ── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.55rem 1rem;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.05);
  color: #cbd5e1;
  font-family: inherit;
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.btn:hover {
  background: rgba(255, 255, 255, 0.09);
  border-color: rgba(255, 255, 255, 0.18);
}

/* ── Icon button ── */
.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.05);
  color: #94a3b8;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
.icon-btn:hover {
  background: rgba(255, 255, 255, 0.09);
  color: #f2f6ff;
}

/* ── Card ── */
.card {
  padding: 0.875rem 1rem;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: #0a1120;
  min-width: 180px;
}
.card-name {
  font-size: 0.875rem;
  font-weight: 600;
  color: #f2f6ff;
  margin-bottom: 0.25rem;
}
.card-desc {
  font-size: 0.75rem;
  color: #475569;
}

