*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: Inter, system-ui, sans-serif;
  background: #050910;
  color: #f2f6ff;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

.demo {
  width: 100%;
  max-width: 720px;
}
.demo-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.375rem;
}
.demo-sub {
  color: #475569;
  font-size: 0.875rem;
  margin-bottom: 1.75rem;
}

/* ── Browser frame ── */
.browser {
  width: 100%;
  border-radius: 0.875rem;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.4), 0 40px 80px rgba(0, 0, 0, 0.6), inset 0 1px 0
    rgba(255, 255, 255, 0.06);
}

/* ── Chrome bar (top — traffic lights + tabs) ── */
.browser-chrome {
  background: #1a1f2e;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.5rem 0.875rem 0;
  height: 2.5rem;
}

/* Traffic lights */
.traffic-lights {
  display: flex;
  gap: 0.375rem;
  align-items: center;
  flex-shrink: 0;
  padding-bottom: 0.5rem;
}

.tl {
  width: 0.75rem;
  height: 0.75rem;
  border-radius: 50%;
}
.tl--close {
  background: #ff5f57;
}
.tl--min {
  background: #febc2e;
}
.tl--max {
  background: #28c840;
}

/* Tabs */
.browser-tabs {
  display: flex;
  align-items: flex-end;
  gap: 0.25rem;
  flex: 1;
  overflow: hidden;
}

.browser-tab {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 0.75rem;
  background: #050910;
  border-radius: 0.5rem 0.5rem 0 0;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom: none;
  max-width: 200px;
  min-width: 120px;
}

.tab-favicon {
  color: #38bdf8;
  flex-shrink: 0;
  display: flex;
  align-items: center;
}

.tab-label {
  font-size: 0.72rem;
  color: #94a3b8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
}

.tab-close {
  background: none;
  border: none;
  color: #475569;
  cursor: pointer;
  padding: 0.125rem;
  border-radius: 0.25rem;
  display: flex;
  align-items: center;
  flex-shrink: 0;
  transition: background 0.15s, color 0.15s;
}
.tab-close:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #94a3b8;
}

.tab-new {
  background: none;
  border: none;
  color: #334155;
  cursor: pointer;
  padding: 0.375rem;
  border-radius: 0.375rem;
  display: flex;
  align-items: center;
  transition: color 0.15s;
  margin-bottom: 0.5rem;
}
.tab-new:hover {
  color: #64748b;
}

/* ── Toolbar ── */
.browser-toolbar {
  background: #141928;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.875rem;
}

.nav-buttons {
  display: flex;
  gap: 0.25rem;
  flex-shrink: 0;
}

.nav-btn {
  background: none;
  border: none;
  color: #475569;
  cursor: pointer;
  padding: 0.375rem;
  border-radius: 0.375rem;
  display: flex;
  align-items: center;
  transition: background 0.15s, color 0.15s;
}
.nav-btn:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.06);
  color: #94a3b8;
}
.nav-btn:disabled {
  opacity: 0.3;
  cursor: default;
}

.address-bar {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 0.5rem;
  padding: 0.35rem 0.75rem;
}

.address-lock {
  color: #22c55e;
  display: flex;
  align-items: center;
}

.address-url {
  font-size: 0.8rem;
  color: #94a3b8;
}

.browser-actions {
  flex-shrink: 0;
}

/* ── Content area ── */
.browser-content {
  background: #0f172a;
  min-height: 280px;
  overflow: hidden;
}

/* Simulated webpage skeleton */
.page-hero {
  position: relative;
  min-height: 280px;
  overflow: hidden;
}

.page-gradient {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 70% 30%, rgba(124, 58, 237, 0.25) 0%, transparent 60%),
    radial-gradient(ellipse at 20% 80%, rgba(14, 165, 233, 0.15) 0%, transparent 50%), #0f172a;
}

.page-nav {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.page-logo {
  width: 5rem;
  height: 0.75rem;
  background: rgba(255, 255, 255, 0.15);
  border-radius: 4px;
}

.page-nav-links {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.page-nav-link {
  width: 2.5rem;
  height: 0.5rem;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 4px;
}
.page-nav-cta {
  width: 4rem;
  height: 1.5rem;
  background: rgba(124, 58, 237, 0.4);
  border-radius: 6px;
}

.page-headline {
  position: relative;
  z-index: 1;
  padding: 2rem 1.5rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.page-eyebrow {
  width: 6rem;
  height: 0.5rem;
  background: rgba(56, 189, 248, 0.3);
  border-radius: 4px;
}

.page-h1 {
  width: 90%;
  height: 1.25rem;
  background: rgba(255, 255, 255, 0.18);
  border-radius: 6px;
}
.page-h1--short {
  width: 60%;
}

.page-subtext {
  width: 75%;
  height: 0.625rem;
  background: rgba(255, 255, 255, 0.07);
  border-radius: 4px;
}
.page-subtext--short {
  width: 55%;
}

.page-ctas {
  display: flex;
  gap: 0.75rem;
  margin-top: 0.5rem;
}
.page-btn {
  height: 2rem;
  border-radius: 6px;
}
.page-btn--primary {
  width: 6.5rem;
  background: rgba(124, 58, 237, 0.6);
}
.page-btn--ghost {
  width: 5rem;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.1);
