*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: Inter, system-ui, sans-serif;
  background: #050910;
  color: #f2f6ff;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

.demo {
  width: 100%;
  max-width: 880px;
}
.demo-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.375rem;
  text-align: center;
}
.demo-sub {
  color: #475569;
  font-size: 0.875rem;
  margin-bottom: 2.5rem;
  text-align: center;
}

/* ── Grid ── */
.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 1rem;
}

/* ── Card ── */
.stat-card {
  background: #0d1320;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 1.125rem;
  padding: 1.375rem 1.375rem 1.125rem;
  display: flex;
  flex-direction: column;
  gap: 0;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.stat-card:hover {
  border-color: rgba(255, 255, 255, 0.16);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
}

/* ── Header row ── */
.stat-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.875rem;
}
.stat-label {
  font-size: 0.75rem;
  font-weight: 500;
  color: #64748b;
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── Icon ── */
.stat-icon {
  width: 32px;
  height: 32px;
  border-radius: 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.stat-icon--blue {
  background: rgba(56, 189, 248, 0.12);
  color: #38bdf8;
}
.stat-icon--purple {
  background: rgba(167, 139, 250, 0.12);
  color: #a78bfa;
}
.stat-icon--green {
  background: rgba(52, 211, 153, 0.12);
  color: #34d399;
}
.stat-icon--amber {
  background: rgba(251, 191, 36, 0.12);
  color: #fbbf24;
}

/* ── Trend badge ── */
.stat-trend {
  display: inline-flex;
  align-items: center;
  gap: 0.2rem;
  padding: 0.2rem 0.5rem;
  border-radius: 999px;
  font-size: 0.6875rem;
  font-weight: 700;
  flex-shrink: 0;
}
.stat-trend--up {
  background: rgba(52, 211, 153, 0.15);
  color: #34d399;
}
.stat-trend--down {
  background: rgba(239, 68, 68, 0.15);
  color: #f87171;
}

/* ── Value ── */
.stat-value {
  font-size: 1.875rem;
  font-weight: 800;
  color: #f2f6ff;
  letter-spacing: -0.03em;
  line-height: 1.1;
  margin-bottom: 1rem;
}

/* ── Sparkline ── */
.stat-sparkline {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 36px;
  margin-bottom: 0.75rem;
}
.bar {
  flex: 1;
  height: var(--h, 50%);
  background: rgba(56, 189, 248, 0.25);
  border-radius: 3px 3px 0 0;
  transition: background 0.2s;
  min-width: 0;
}
.bar--active {
  background: #38bdf8;
}
.bar--down {
  background: #ef4444;
}
.stat-card:hover .bar:not(.bar--active):not(.bar--down) {
  background: rgba(56, 189, 248, 0.35);
}

/* ── Supporting text ── */
.stat-sub {
  font-size: 0.6875rem;
  color: #475569;
}

