    #7c3aed 0%,
    #2563eb 35%,
    #0891b2 60%,
    #059669 85%,
    #065f46 100%
  );
}

/* After layer clip — JS updates --split CSS variable */
.diff-layer--after {
  clip-path: inset(0 calc(100% - var(--split, 50%)) 0 0);
  transition: clip-path 0s;
}

/* ── Labels ── */
.diff-label {
  position: absolute;
  bottom: 0.875rem;
  font-size: 0.72rem;
  font-weight: 700;
