  --muted: #334155;
  --mid: #64748b;
  --border: rgba(242, 246, 255, 0.07);
  --surface: rgba(242, 246, 255, 0.03);
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  color: var(--accent);
  font-family: "Space Grotesk", system-ui, -apple-system, sans-serif;
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* ── Nav ───────────────────────────────────────────────────────────────────── */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 48px;
  background: rgba(5, 9, 16, 0);
}

.nav-name {
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: var(--accent);
  text-decoration: none;
}

.available-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 14px;
  border-radius: 50px;
  border: 1px solid rgba(34, 197, 94, 0.35);
  background: rgba(34, 197, 94, 0.08);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: #22c55e;
}

.avail-dot {
  width: 6px;
  height: 6px;
  background: #22c55e;
  border-radius: 50%;
  animation: avail-blink 2s ease-in-out infinite;
}

@keyframes avail-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}

/* ── Hero ──────────────────────────────────────────────────────────────────── */
.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 80px 40px;
  position: relative;
}

.hero-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.hero-index {
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 24px;
}

.hero-name {
  display: flex;
  flex-direction: column;
  font-family: "Syne", "Space Grotesk", sans-serif;
  font-size: clamp(4rem, 14vw, 11rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 0.9;
  color: var(--accent);
  margin-bottom: 24px;
}

.name-line {
  display: block;
}

.hero-roles {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: clamp(1rem, 2.5vw, 1.6rem);
  font-weight: 300;
  color: var(--muted);
  letter-spacing: 0.02em;
  margin-bottom: 32px;
  height: 2em;
  overflow: hidden;
}

.role-prefix {
  color: var(--mid);
  flex-shrink: 0;
}

.roles-ticker {
  position: relative;
  overflow: hidden;
}

.role {
  display: none;
}
.role.active {
  display: inline;
}

.hero-tagline {
  font-size: 0.95rem;
  color: var(--mid);
  max-width: 440px;
  margin-bottom: 48px;
  line-height: 1.65;
}

.hero-scroll-indicator {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  font-size: 0.68rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
}

.scroll-track {
  width: 2px;
  height: 48px;
  background: var(--border);
  border-radius: 2px;
  overflow: hidden;
}

.scroll-thumb {
  width: 100%;
  height: 40%;
  background: var(--mid);
  border-radius: 2px;
  animation: scroll-anim 2s ease-in-out infinite;
}

@keyframes scroll-anim {
  0% {
    transform: translateY(-100%);
    opacity: 0;
  }
  20% {
    opacity: 1;
  }
  80% {
    opacity: 1;
  }
  100% {
    transform: translateY(250%);
    opacity: 0;
  }
}

/* Hero deco labels */
.hero-deco {
  position: absolute;
  bottom: 40px;
  width: 100%;
  display: flex;
  justify-content: space-between;
  padding: 0 48px;
}

.deco-year,
.deco-location {
  font-size: 0.68rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ── Work ──────────────────────────────────────────────────────────────────── */
.work-section {
  padding: 96px 48px;
  border-top: 1px solid var(--border);
}

.work-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 40px;
}

.work-title {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
}

.work-count {
  font-size: 0.7rem;
  color: var(--muted);
}

.work-list {
  list-style: none;
}

.work-item {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 24px 0;
  text-decoration: none;
  color: var(--accent);
  border-top: 1px solid var(--border);
  position: relative;
  overflow: hidden;
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.5s, transform 0.5s;
}

.work-item:last-child {
  border-bottom: 1px solid var(--border);
}

.work-item.revealed {
  opacity: 1;
  transform: translateY(0);
}

.work-item::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(242, 246, 255, 0.03);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
}

.work-item:hover::before {
  transform: scaleX(1);
}

.work-thumbnail {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  flex-shrink: 0;
  background: hsl(var(--hue, 220deg), 60%, 15%);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  z-index: 1;
}

.thumb-text {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--mid);
}

.work-index {
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  width: 28px;
  flex-shrink: 0;
  position: relative;
  z-index: 1;
}

.work-details {
  flex: 1;
  position: relative;
  z-index: 1;
}

.work-name {
  font-size: clamp(1rem, 2.5vw, 1.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 2px;
}

.work-category {
  font-size: 0.75rem;
  color: var(--muted);
  font-weight: 400;
}

.work-year {
  font-size: 0.75rem;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
  position: relative;
  z-index: 1;
}

.work-arrow {
  font-size: 1rem;
  color: var(--muted);
  flex-shrink: 0;
  transform: rotate(45deg);
  transition: transform 0.2s, color 0.2s;
  position: relative;
  z-index: 1;
}

.work-item:hover .work-arrow {
  transform: rotate(0deg);
  color: var(--accent);
}

/* ── About ─────────────────────────────────────────────────────────────────── */
.about-section {
  padding: 96px 48px;
  border-top: 1px solid var(--border);
}

.about-inner {
  display: grid;
  grid-template-columns: 160px 1fr;
  gap: 48px;
}

.about-label {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
  padding-top: 4px;
}

.about-content {
  display: flex;
  flex-direction: column;
  gap: 32px;
}

.about-text {
  font-size: 1rem;
  color: var(--mid);
  line-height: 1.8;
  max-width: 560px;
}

.about-stats {
  display: flex;
  gap: 40px;
}

.about-stat {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.astat-num {
  font-size: 1.75rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--accent);
}

.astat-label {
  font-size: 0.72rem;
  color: var(--muted);
  letter-spacing: 0.08em;
}

/* ── Skills ────────────────────────────────────────────────────────────────── */
.skills-section {
  padding: 80px 48px;
  border-top: 1px solid var(--border);
}

.skills-label {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 32px;
}

.skills-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.skill-tag {
  font-family: "Space Mono", "Courier New", monospace;
  font-size: 0.8rem;
  padding: 7px 14px;
  border-radius: 4px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--mid);
  letter-spacing: 0.04em;
  transition: border-color 0.2s, color 0.2s;
}

.skill-tag:hover {
  border-color: rgba(242, 246, 255, 0.2);
  color: var(--accent);
}

/* ── Contact ───────────────────────────────────────────────────────────────── */
.contact-section {
  padding: 96px 48px;
  border-top: 1px solid var(--border);
  text-align: center;
}

.contact-inner {
  max-width: 600px;
  margin: 0 auto;
}

.contact-headline {
  font-family: "Syne", "Space Grotesk", sans-serif;
  font-size: clamp(2rem, 7vw, 5rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.1;
  margin-bottom: 32px;
}

.contact-headline em {
  font-style: italic;
  font-weight: 300;
}

.contact-links {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.contact-email {
  font-size: clamp(1rem, 2.5vw, 1.4rem);
  font-weight: 600;
  color: var(--accent);
  text-decoration: none;
  border-bottom: 1px solid var(--border);
  padding-bottom: 4px;
  transition: border-color 0.2s;
  letter-spacing: -0.01em;
}

.contact-email:hover {
  border-color: var(--accent);
}

.contact-socials {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  justify-content: center;
}

.contact-social {
  font-size: 0.82rem;
  color: var(--muted);
  text-decoration: none;
  padding-bottom: 2px;
  border-bottom: 1px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}

.contact-social:hover {
  color: var(--accent);
  border-color: var(--muted);
}

/* ── Footer ────────────────────────────────────────────────────────────────── */
.footer {
  padding: 32px 48px;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.75rem;
  color: var(--muted);
}

.footer-mono {
  font-family: "Space Mono", monospace;
}

/* ── Responsive ────────────────────────────────────────────────────────────── */
@media (max-width: 768px) {
  .nav {
    padding: 16px 20px;
  }
  .hero {
    padding: 80px 20px 60px;
  }
  .hero-deco {
    padding: 0 20px;
  }
  .hero-name {
    font-size: clamp(3.5rem, 18vw, 6rem);
  }
  .work-section,
  .about-section,
  .skills-section,
  .contact-section {
    padding: 60px 20px;
  }
  .about-inner {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .footer {
    padding: 24px 20px;
    flex-direction: column;
    gap: 8px;
  }
}

