body {
  font-family: Inter, system-ui, sans-serif;
  background: #050910;
  color: #f2f6ff;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

.demo {
  width: 100%;
  max-width: 540px;
}
.demo-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.375rem;
}
.demo-sub {
  color: #475569;
  font-size: 0.875rem;
  margin-bottom: 2.5rem;
}

.triggers {
  display: flex;
  flex-direction: column;
  gap: 2.5rem;
}
.trigger-line {
  font-size: 0.95rem;
  color: #94a3b8;
  line-height: 1.7;
  position: relative;
}

/* ── Trigger ── */
.hc-trigger {
  color: #38bdf8;
  cursor: pointer;
  font-weight: 600;
  text-decoration: none;
  border-bottom: 1px dashed rgba(56, 189, 248, 0.4);
  transition: color 0.15s;
  position: relative;
}
.hc-trigger--link {
  border-bottom-style: solid;
}

/* ── Card ── */
.hover-card {
  position: absolute;
  top: calc(100% + 14px);
  left: 0;
  z-index: 100;
  min-width: 260px;
  max-width: 300px;
  background: #0d1117;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 1rem;
  padding: 1rem;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
  opacity: 0;
  pointer-events: none;
  transform: translateY(6px) scale(0.97);
  transition: opacity 0.2s ease, transform 0.2s ease;
}
.hover-card.is-visible {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0) scale(1);
}

/* Arrow */
.hc-arrow {
  position: absolute;
  top: -6px;
  left: 20px;
  width: 12px;
  height: 12px;
  background: #0d1117;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  border-left: 1px solid rgba(255, 255, 255, 0.1);
  transform: rotate(45deg);
}

