  margin-bottom: 0.375rem;
}
.hc-link-url {
  font-size: 0.72rem;
  color: #38bdf8;
}

/* Product preview */
.hc-product-img {
  width: 100%;
  height: 120px;
  border-radius: 0.625rem;
  background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
  margin-bottom: 0.75rem;
}
.hc-product-name {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.375rem;
}
.hc-product-meta {
