  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.04);
  color: #6a7a9a;
  cursor: pointer;
  font-size: 0.83rem;
  font-weight: 500;
  font-family: inherit;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}

.tg-chip:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #c5d3f0;
  border-color: rgba(255, 255, 255, 0.16);
}

.tg-chip:focus-visible {
  outline: 2px solid #4f6ef7;
  outline-offset: 2px;
}

.tg-chip:active {
  transform: scale(0.95);
}

.tg-chip[aria-pressed="true"] {
  background: rgba(79, 110, 247, 0.18);
  color: #a0b8ff;
  border-color: rgba(79, 110, 247, 0.45);
}

.tg-chip[aria-pressed="true"]:hover {
  background: rgba(79, 110, 247, 0.26);
  border-color: rgba(79, 110, 247, 0.6);
}

/* ── Filter display ── */
.filter-display {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.82rem;
}

.filter-display__label {
  color: #4a5a7a;
}

.filter-display__value {
  color: #a0b8ff;
  font-weight: 500;
}

