}

/* ── Demo ── */
.demo {
  max-width: 640px;
  margin: 0 auto;
  padding: 3rem 1.5rem 6rem;
}

.page-header {
  margin-bottom: 3rem;
}
.demo-title {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.375rem;
}
.demo-sub {
  color: var(--muted);
  font-size: 0.875rem;
}

/* ── Articles ── */
.articles {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.article {
  padding: 1.5rem;
  border-radius: 14px;
  background: var(--card);
  border: 1px solid var(--border);
}

.article__title {
  font-size: 1.0625rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
  letter-spacing: -0.01em;
}

.article__body {
  font-size: 0.9rem;
  color: #94a3b8;
  line-height: 1.75;
}

.article__body code {
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 0.8125em;
  background: rgba(255, 255, 255, 0.07);
  padding: 0.1em 0.4em;
  border-radius: 4px;
  color: var(--accent);
}

/* ── Back-to-top button ── */
.btt-btn {
  position: fixed;
  bottom: var(--btn-offset);
  right: var(--btn-offset);
  width: var(--btn-size);
  height: var(--btn-size);
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(13, 17, 23, 0.9);
  border: 1px solid var(--border);
  border-radius: 50%;
  cursor: pointer;
  color: var(--text);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.4);

  /* Hidden by default */
  opacity: 0;
  pointer-events: none;
  transform: translateY(12px) scale(0.9);
  transition: opacity 0.3s var(--ease), transform 0.3s var(--ease), box-shadow 0.2s;

  z-index: 999;
}

.btt-btn.visible {
  opacity: 1;
  pointer-events: all;
  transform: translateY(0) scale(1);
}

.btt-btn:hover {
  box-shadow: 0 6px 32px rgba(56, 189, 248, 0.25);
  transform: translateY(-2px) scale(1.05);
}

.btt-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.btt-btn:active {
  transform: scale(0.96);
}

/* ── Progress ring ── */
.btt-ring {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
  border-radius: 50%;
  overflow: visible;
}

.btt-ring__track {
  fill: none;
  stroke: rgba(255, 255, 255, 0.06);
  stroke-width: 2.5;
}

.btt-ring__fill {
  fill: none;
  stroke: var(--accent);
  stroke-width: 2.5;
  stroke-linecap: round;
  /* set dynamically by JS: stroke-dasharray and stroke-dashoffset */
  transition: stroke-dashoffset 0.1s linear;
}

/* ── Arrow icon ── */
.btt-arrow {
  position: relative;
  z-index: 1;
  color: var(--text);
  transition: transform 0.2s var(--ease);
}

.btt-btn:hover .btt-arrow {
  transform: translateY(-1px);
}

