  height: 28px;
  border-radius: 6px;
  background: none;
  border: 1px solid var(--border);
  color: var(--text);
  font-size: 1rem;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background 0.2s, border-color 0.2s;
}

.cal-nav-btn:hover {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.2);
}

.cal-month-label {
  font-size: 0.9rem;
  font-weight: 600;
}

/* ── Weekday row ── */
.cal-weekdays {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
  margin-bottom: 4px;
}

.cal-weekday {
  font-size: 0.68rem;
  font-weight: 600;
  text-align: center;
  color: var(--muted);
  padding: 0.2rem 0;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

/* ── Days grid ── */
.cal-days {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
}

.cal-day {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  border-radius: 6px;
  background: none;
  border: none;
  color: var(--text);
  font-size: 0.82rem;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background 0.15s, color 0.15s;
  outline: none;
}

.cal-day:hover:not([disabled]):not(.cal-day--selected):not(.cal-day--selected-end) {
  background: rgba(255, 255, 255, 0.06);
}

.cal-day:focus-visible {
  box-shadow: 0 0 0 2px var(--accent);
}

/* Ghost days (prev/next month) */
.cal-day--ghost {
  color: rgba(71, 85, 105, 0.4);
  cursor: default;
  pointer-events: none;
}

/* Disabled */
.cal-day[disabled] {
  color: rgba(71, 85, 105, 0.35);
  cursor: not-allowed;
  pointer-events: none;
}

/* Today dot */
.cal-day--today::after {
  content: "";
  position: absolute;
  bottom: 3px;
  left: 50%;
  transform: translateX(-50%);
  width: 4px;
  height: 4px;
  background: var(--today-dot);
  border-radius: 50%;
}

/* Selected (single or range endpoints) */
.cal-day--selected,
.cal-day--selected-end {
  background: var(--accent);
  color: #050910;
  font-weight: 700;
}

.cal-day--selected:hover,
.cal-day--selected-end:hover {
  background: var(--accent);
}

/* In-range */
.cal-day--in-range {
  background: var(--range-bg);
  border-radius: 0;
}

/* Range start/end connectors */
.cal-day--selected.cal-day--range-start {
  border-radius: 6px 0 0 6px;
}

.cal-day--selected-end {
  border-radius: 0 6px 6px 0;
}

