  height: 16px;
  flex-shrink: 0;
  color: var(--muted);
  transition: transform 0.2s;
}

.cs-wrap.open .cs-arrow {
  transform: rotate(180deg);
}

/* ── Multi-trigger ── */
.cs-trigger--multi {
