  border: none;
  color: var(--text);
  font-size: 0.875rem;
  outline: none;
  padding: 0;
}

.cs-tag-input::placeholder {
  color: var(--muted);
}

.cs-tags {
  display: contents;
}

.cs-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  background: var(--accent-bg);
  color: var(--accent);
  border: 1px solid rgba(56, 189, 248, 0.25);
  border-radius: 6px;
  padding: 0.2rem 0.5rem;
  font-size: 0.78rem;
  font-weight: 500;
  white-space: nowrap;
