(function () {
  "use strict";

  // ── Helpers ──────────────────────────────────────────────────────────────────

  function closeAll(except) {
    document.querySelectorAll(".cs-wrap.open").forEach(function (w) {
      if (w !== except) closeWrap(w);
    });
  }

  function closeWrap(wrap) {
    wrap.classList.remove("open");
    const trigger = wrap.querySelector(".cs-trigger");
    if (trigger) trigger.setAttribute("aria-expanded", "false");
  }

  function openWrap(wrap) {
    closeAll(wrap);
    wrap.classList.add("open");
    const trigger = wrap.querySelector(".cs-trigger");
    if (trigger) trigger.setAttribute("aria-expanded", "true");
  }

  // ── Single / Grouped select ──────────────────────────────────────────────────

  function initSingle(wrap) {
    const trigger = wrap.querySelector(".cs-trigger");
    const valueEl = wrap.querySelector(".cs-value");
    const search = wrap.querySelector(".cs-search");
    const list = wrap.querySelector(".cs-list");
    const empty = wrap.querySelector(".cs-empty");
    const placeholder = wrap.dataset.placeholder || "Select…";

    valueEl.dataset.placeholder = placeholder;

    function toggle() {
      if (wrap.classList.contains("open")) {
        closeWrap(wrap);
      } else {
        openWrap(wrap);
        if (search) {
          search.value = "";
          filterOptions();
          search.focus();
        }
      }
    }

    function filterOptions() {
      const q = search ? search.value.toLowerCase() : "";
      let visible = 0;
      wrap.querySelectorAll(".cs-option").forEach(function (opt) {
        const match = opt.textContent.toLowerCase().includes(q);
        opt.hidden = !match;
        if (match) visible++;
      });
      if (empty) empty.hidden = visible > 0;
    }

    function selectOption(opt) {
      wrap.querySelectorAll(".cs-option").forEach(function (o) {
        o.classList.remove("selected");
      });
      opt.classList.add("selected");
      valueEl.textContent = opt.textContent.trim();
      closeWrap(wrap);
    }

    function moveFocus(dir) {
      const opts = Array.from(wrap.querySelectorAll(".cs-option:not([hidden])"));
      const focused = wrap.querySelector(".cs-option.focused");
      const idx = focused ? opts.indexOf(focused) : -1;
      const next = opts[Math.max(0, Math.min(opts.length - 1, idx + dir))];
      if (focused) focused.classList.remove("focused");
      if (next) {
        next.classList.add("focused");
        next.scrollIntoView({ block: "nearest" });
      }
    }

    trigger.addEventListener("click", toggle);
    trigger.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        toggle();
      }
      if (e.key === "Escape") closeWrap(wrap);
      if (e.key === "ArrowDown") {
        e.preventDefault();
        if (!wrap.classList.contains("open")) openWrap(wrap);
        moveFocus(1);
      }
      if (e.key === "ArrowUp") {
        e.preventDefault();
        moveFocus(-1);
      }
    });

    if (search) {
      search.addEventListener("input", filterOptions);
      search.addEventListener("keydown", function (e) {
        if (e.key === "ArrowDown") {
          e.preventDefault();
          moveFocus(1);
        }
        if (e.key === "ArrowUp") {
          e.preventDefault();
          moveFocus(-1);
        }
        if (e.key === "Escape") closeWrap(wrap);
        if (e.key === "Enter") {
          const focused = wrap.querySelector(".cs-option.focused");
          if (focused) selectOption(focused);
        }
      });
    }

    list.addEventListener("click", function (e) {
      const opt = e.target.closest(".cs-option");
      if (opt) selectOption(opt);
    });

    list.addEventListener("mousemove", function (e) {
      const opt = e.target.closest(".cs-option");
      if (!opt) return;
      wrap.querySelectorAll(".cs-option.focused").forEach(function (o) {
        o.classList.remove("focused");
      });
      opt.classList.add("focused");
    });
  }

  // ── Multi-select ─────────────────────────────────────────────────────────────

  function initMulti(wrap) {
    const trigger = wrap.querySelector(".cs-trigger--multi");
    const tagsEl = wrap.querySelector(".cs-tags");
    const tagInput = wrap.querySelector(".cs-tag-input");
    const list = wrap.querySelector(".cs-list");
    const empty = wrap.querySelector(".cs-empty");
    const selected = new Set();

    function toggle() {
      if (wrap.classList.contains("open")) {
        closeWrap(wrap);
      } else {
        openWrap(wrap);
        tagInput.focus();
      }
    }

    function filterOptions() {
      const q = tagInput.value.toLowerCase();
      let visible = 0;
      wrap.querySelectorAll(".cs-option").forEach(function (opt) {
        const match = opt.textContent.toLowerCase().includes(q);
        opt.hidden = !match;
        if (match) visible++;
      });
      if (empty) empty.hidden = visible > 0;
    }

    function renderTags() {
      tagsEl.innerHTML = "";
      selected.forEach(function (val) {
        const opt = wrap.querySelector('.cs-option[data-value="' + val + '"]');
        if (!opt) return;
        const tag = document.createElement("span");
        tag.className = "cs-tag";
        const label = opt.textContent.trim();
        tag.innerHTML =
          label +
          ' <button class="cs-tag-remove" data-val="' +
          val +
          '" aria-label="Remove ' +
          label +
          '">\xd7</button>';
        tagsEl.appendChild(tag);
      });
      wrap.querySelectorAll(".cs-option").forEach(function (opt) {
        opt.classList.toggle("selected", selected.has(opt.dataset.value));
      });
      tagInput.placeholder = selected.size === 0 ? wrap.dataset.placeholder || "Pick\u2026" : "";
    }

    trigger.addEventListener("click", function (e) {
      if (e.target.closest(".cs-tag-remove")) return;
      toggle();
    });

    tagsEl.addEventListener("click", function (e) {
      const btn = e.target.closest(".cs-tag-remove");
      if (!btn) return;
      selected.delete(btn.dataset.val);
      renderTags();
    });

    tagInput.addEventListener("input", filterOptions);
    tagInput.addEventListener("keydown", function (e) {
      if (e.key === "Escape") closeWrap(wrap);
      if (e.key === "Backspace" && tagInput.value === "" && selected.size > 0) {
        const last = Array.from(selected).pop();
        selected.delete(last);
        renderTags();
      }
    });

    list.addEventListener("click", function (e) {
      const opt = e.target.closest(".cs-option");
      if (!opt) return;
      const val = opt.dataset.value;
      if (selected.has(val)) {
        selected.delete(val);
      } else {
        selected.add(val);
      }
      tagInput.value = "";
      filterOptions();
      renderTags();
      tagInput.focus();
    });

    renderTags();
  }

  // ── Init ─────────────────────────────────────────────────────────────────────

  document.querySelectorAll(".cs-wrap").forEach(function (wrap) {
    if (wrap.classList.contains("cs-multi")) {
      initMulti(wrap);
    } else {
      initSingle(wrap);
    }
  });

  document.addEventListener("click", function (e) {
    if (!e.target.closest(".cs-wrap")) closeAll(null);
  });
})();

snippets.css:
/* ── Reset & Base ──────────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #080b14;
  --bg2: #0d1117;
  --accent: #7c3aed;
  --accent2: #38bdf8;
  --pink: #f472b6;
  --text: #e2e8f0;
  --muted: #64748b;
  --border: rgba(255, 255, 255, 0.07);
  --surface: rgba(255, 255, 255, 0.04);
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* ── Nav ───────────────────────────────────────────────────────────────────── */
.nav {
  position: sticky;
  top: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 14px 40px;
  background: rgba(8, 11, 20, 0.88);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: "Space Grotesk", sans-serif;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--text);
  text-decoration: none;
  flex-shrink: 0;
}

.logo-prism {
  display: flex;
  align-items: center;
}

.nav-search {
  flex: 1;
  max-width: 360px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
  border-radius: 8px;
  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--muted);
}

.search-input {
  flex: 1;
  background: none;
  border: none;
  outline: none;
  color: var(--text);
  font-size: 0.85rem;
  font-family: inherit;
}

.search-input::placeholder {
  color: var(--muted);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-left: auto;
}

.nav-link {
  font-size: 0.85rem;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
}

.nav-link:hover {
  color: var(--text);
}

.btn-wallet {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: 8px;
  background: var(--accent);
  border: none;
  color: #fff;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.2s;
}

.btn-wallet:hover {
  opacity: 0.85;
}

.btn-wallet.connected {
  background: rgba(16, 185, 129, 0.12);
  color: #10b981;
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.nav-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  flex-shrink: 0;
  background: linear-gradient(135deg, var(--accent), var(--pink));
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.72rem;
  font-weight: 700;
  color: #fff;
}

/* ── Hero ──────────────────────────────────────────────────────────────────── */
.hero {
  min-height: calc(100vh - 57px);
  display: grid;
  grid-template-columns: 1fr 276px;
  grid-template-rows: 1fr auto;
  gap: 20px;
  padding: 32px 40px;
  align-items: start;
}

.hero-featured {
  grid-column: 1;
  grid-row: 1 / 3;
  display: flex;
}

.featured-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.featured-art {
  position: relative;
  height: 340px;
  overflow: hidden;
  background: #070711;
}

.art-gradient {
  position: absolute;
  inset: 0;
}

.featured-gradient {
  background: radial-gradient(ellipse at 30% 50%, rgba(124, 58, 237, 0.45) 0%, transparent 55%),
    radial-gradient(ellipse at 72% 28%, rgba(56, 189, 248, 0.3) 0%, transparent 50%),
    radial-gradient(ellipse at 50% 78%, rgba(244, 114, 182, 0.2) 0%, transparent 50%);
}

.art-orbs {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.orb {
  position: absolute;
  left: var(--x, 50%);
  top: var(--y, 50%);
  width: var(--s, 100px);
  height: var(--s, 100px);
  border-radius: 50%;
  background: radial-gradient(circle, var(--c, #7c3aed) 0%, transparent 70%);
  transform: translate(-50%, -50%);
  opacity: 0.7;
  filter: blur(22px);
  animation: orb-float 6s ease-in-out infinite;
}

.orb:nth-child(2) {
  animation-delay: -2s;
  animation-duration: 8s;
}
.orb:nth-child(3) {
  animation-delay: -4s;
  animation-duration: 5s;
}

@keyframes orb-float {
  0%,
  100% {
    transform: translate(-50%, -50%) scale(1);
  }
  50% {
    transform: translate(-50%, calc(-50% - 14px)) scale(1.1);
  }
}

.art-grid-overlay {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255, 255, 255, 0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.025) 1px, transparent 1px);
  background-size: 40px 40px;
}

.featured-live-badge {
  position: absolute;
  top: 16px;
  left: 16px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 12px;
  border-radius: 50px;
  background: rgba(239, 68, 68, 0.15);
  border: 1px solid rgba(239, 68, 68, 0.35);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: #ef4444;
}

.live-pulse {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ef4444;
  animation: live-blink 1.4s ease-in-out infinite;
}

@keyframes live-blink {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.35;
    transform: scale(0.75);
  }
}

.featured-info {
  padding: 24px;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.featured-collection {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

.featured-title {
  font-family: "Space Grotesk", sans-serif;
  font-size: clamp(1.4rem, 2.5vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.15;
}

.featured-artist {
  font-size: 0.88rem;
  color: var(--muted);
}

.artist-highlight {
  color: var(--accent2);
  font-weight: 500;
}

.featured-auction {
  display: flex;
  gap: 32px;
  padding: 14px 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.auction-col {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.auction-label {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
}

.auction-price {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: "Space Mono", monospace;
  font-size: 1.15rem;
  font-weight: 700;
}

.auction-price svg {
  color: #627eea;
  flex-shrink: 0;
}

.auction-timer {
  font-family: "Space Mono", monospace;
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--accent2);
}

.auction-usd {
  font-size: 0.7rem;
  color: var(--muted);
}

.featured-actions {
  display: flex;
  gap: 12px;
  margin-top: auto;
}

.btn-bid {
  flex: 1;
  padding: 12px 20px;
  background: linear-gradient(135deg, var(--accent), #5b21b6);
  border: none;
  border-radius: 8px;
  color: #fff;
  font-size: 0.88rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.2s, transform 0.15s;
}

.btn-bid:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}

.btn-watch {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 20px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--muted);
  font-size: 0.88rem;
  cursor: pointer;
  font-family: inherit;
  transition: color 0.2s, border-color 0.2s;
}

.btn-watch:hover {
  color: var(--text);
  border-color: rgba(255, 255, 255, 0.18);
}

/* ── Mini cards (right column, top) ────────────────────────────────────────── */
.hero-grid-mini {
  grid-column: 2;
  grid-row: 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.mini-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  transition: border-color 0.2s;
}

.mini-card:hover {
  border-color: rgba(255, 255, 255, 0.14);
}

.mini-art {
  height: 80px;
  background: linear-gradient(135deg, var(--c1, #7c3aed), var(--c2, #06b6d4));
}

.mini-info {
  padding: 8px 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.mini-title {
  font-size: 0.77rem;
  font-weight: 500;
}

.mini-eth {
  font-family: "Space Mono", monospace;
  font-size: 0.7rem;
  color: var(--accent2);
}

/* ── Hero stats (right column, bottom) ─────────────────────────────────────── */
.hero-stats {
  grid-column: 2;
  grid-row: 2;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.hero-stat {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.hstat-val {
  font-family: "Space Grotesk", sans-serif;
  font-size: 1.1rem;
  font-weight: 700;
}

.hstat-label {
  font-size: 0.7rem;
  color: var(--muted);
}

/* ── Shared section styles ─────────────────────────────────────────────────── */
.auctions-section,
.artists-section,
.how-section {
  padding: 64px 40px;
  border-top: 1px solid var(--border);
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 32px;
}

.section-eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #ef4444;
  margin-bottom: 6px;
}

.live-dot-small {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #ef4444;
  animation: live-blink 1.4s ease-in-out infinite;
}

.section-title {
  font-family: "Space Grotesk", sans-serif;
  font-size: clamp(1.3rem, 2.5vw, 1.8rem);
  font-weight: 700;
  letter-spacing: -0.02em;
}

.see-all {
  font-size: 0.82rem;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
  white-space: nowrap;
}

.see-all:hover {
  color: var(--text);
}

/* ── Auctions Grid ─────────────────────────────────────────────────────────── */
.auctions-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 20px;
}

.nft-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  transition: transform 0.25s, border-color 0.25s, box-shadow 0.25s;
}

.nft-card:hover {
  transform: translateY(-4px);
  border-color: rgba(255, 255, 255, 0.13);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.45);
}

.nft-art {
  height: 200px;
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, var(--c1, #4f46e5), var(--c2, #7c3aed));
}

.nft-art-inner {
  position: absolute;
  inset: 0;
  background: radial-gradient(
      ellipse at 70% 30%,
      var(--c3, rgba(167, 139, 250, 0.5)) 0%,
      transparent 55%
    ), radial-gradient(ellipse at 25% 75%, rgba(0, 0, 0, 0.3) 0%, transparent 55%);
}

.nft-info {
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.nft-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.nft-title {
  font-weight: 600;
  font-size: 0.92rem;
}

.nft-edition {
  font-size: 0.66rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  flex-shrink: 0;
  padding: 3px 8px;
  border-radius: 50px;
  background: rgba(255, 255, 255, 0.07);
  color: var(--muted);
}

.nft-artist {
  font-size: 0.78rem;
  color: var(--muted);
}

.nft-bid-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}

.bid-label {
  display: block;
  font-size: 0.66rem;
  color: var(--muted);
  margin-bottom: 3px;
}

.bid-eth {
  display: flex;
  align-items: center;
  gap: 4px;
  font-family: "Space Mono", monospace;
  font-size: 0.88rem;
  font-weight: 700;
}

.bid-eth svg {
  color: #627eea;
  flex-shrink: 0;
}
.bid-eth.flash {
  color: #10b981;
  transition: color 0.2s;
}

.nft-timer {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 0.72rem;
  color: var(--muted);
}

.btn-bid-sm {
  width: 100%;
  padding: 9px;
  background: linear-gradient(135deg, var(--accent), #5b21b6);
  border: none;
  border-radius: 6px;
  color: #fff;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.2s;
}

.btn-bid-sm:hover {
  opacity: 0.85;
}

/* ── Top Artists ───────────────────────────────────────────────────────────── */
.artists-row {
  display: flex;
  flex-direction: column;
}

.artist-item {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}

.artist-item:first-child {
  border-top: 1px solid var(--border);
}

.artist-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--bg, #7c3aed);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.78rem;
  font-weight: 700;
  color: #fff;
}

.artist-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.artist-name {
  font-size: 0.9rem;
  font-weight: 500;
}

.artist-volume {
  font-family: "Space Mono", monospace;
  font-size: 0.75rem;
  color: var(--accent2);
}

.artist-rank {
  font-family: "Space Mono", monospace;
  font-size: 0.75rem;
  color: var(--muted);
  flex-shrink: 0;
}

/* ── How It Works ──────────────────────────────────────────────────────────── */
.how-title {
  font-family: "Space Grotesk", sans-serif;
  font-size: clamp(1.5rem, 3vw, 2.2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 40px;
  text-align: center;
}

.how-steps {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  gap: 16px;
}

.how-step {
  flex: 1;
  max-width: 280px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 28px 22px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.step-num {
  font-family: "Space Mono", monospace;
  font-size: 0.7rem;
  color: var(--accent2);
  font-weight: 700;
  letter-spacing: 0.1em;
}

.step-icon {
  color: var(--muted);
}
.step-title {
  font-size: 1rem;
  font-weight: 600;
}
.step-desc {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.65;
}

.how-step-arrow {
  font-size: 1.4rem;
  color: var(--muted);
  align-self: center;
  padding-top: 48px;
  flex-shrink: 0;
}

/* ── Footer ────────────────────────────────────────────────────────────────── */
.footer {
  background: var(--bg2);
  border-top: 1px solid var(--border);
  padding: 56px 40px 24px;
}

.footer-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 48px;
  margin-bottom: 48px;
  flex-wrap: wrap;
}

.footer-brand {
  max-width: 300px;
}

.footer-logo {
  font-family: "Space Grotesk", sans-serif;
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  display: block;
  margin-bottom: 10px;
  background: linear-gradient(90deg, var(--accent), var(--accent2));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.footer-tagline {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.6;
}

.newsletter-label {
  display: block;
  font-size: 0.8rem;
  font-weight: 600;
  margin-bottom: 12px;
}

.newsletter-row {
  display: flex;
  gap: 8px;
}

.newsletter-input {
  flex: 1;
  padding: 10px 14px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.85rem;
  font-family: inherit;
  outline: none;
  transition: border-color 0.2s;
}

.newsletter-input::placeholder {
  color: var(--muted);
}
.newsletter-input:focus {
  border-color: rgba(124, 58, 237, 0.5);
}

.newsletter-btn {
  padding: 10px 20px;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  color: #fff;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.2s;
  white-space: nowrap;
}

.newsletter-btn:hover {
  opacity: 0.85;
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 24px;
  border-top: 1px solid var(--border);
  font-size: 0.78rem;
  color: var(--muted);
  flex-wrap: wrap;
  gap: 12px;
}

.footer-links {
  display: flex;
  gap: 20px;
}
.footer-links a {
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
}
.footer-links a:hover {
  color: var(--text);
}

/* ── Responsive ────────────────────────────────────────────────────────────── */
@media (max-width: 900px) {
  .hero {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto auto;
    padding: 20px;
  }
  .hero-featured {
    grid-column: 1;
    grid-row: 1;
  }
  .hero-grid-mini {
    grid-column: 1;
    grid-row: 2;
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: 4px;
  }
  .mini-card {
    flex: 0 0 160px;
  }
  .hero-stats {
    grid-column: 1;
    grid-row: 3;
    flex-direction: row;
  }
  .nav {
    padding: 12px 20px;
  }
  .nav-search {
    display: none;
  }
  .auctions-section,
  .artists-section,
  .how-section {
