/* ── Reset & Base ──────────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #080c14;
  --bg2: #0d1117;
  --bg3: #161b22;
  --bg4: #1e2530;
  --accent: #6366f1;
  --green: #10b981;
  --red: #ef4444;
  --amber: #f59e0b;
  --text: #e2e8f0;
  --muted: #64748b;
  --border: rgba(255, 255, 255, 0.07);
  --surface: rgba(255, 255, 255, 0.04);
  --radius: 8px;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", system-ui, -apple-system, sans-serif;
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* ── Landing Nav ───────────────────────────────────────────────────────────── */
.landing-nav {
  position: sticky;
  top: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 48px;
  background: rgba(8, 12, 20, 0.9);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.landing-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--text);
  text-decoration: none;
}

.landing-nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.landing-nav-links a {
  font-size: 0.85rem;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
}

.landing-nav-links a:hover {
  color: var(--text);
}

.landing-nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-signin {
  font-size: 0.85rem;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
}

.nav-signin:hover {
  color: var(--text);
}

.btn-signup {
  padding: 8px 18px;
  border-radius: var(--radius);
  background: var(--accent);
  border: none;
  color: #fff;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.2s;
}

.btn-signup:hover {
  opacity: 0.85;
}

/* ── Hero Text Section ─────────────────────────────────────────────────────── */
.hero-text-section {
  padding: 80px 48px 56px;
  text-align: center;
  background: radial-gradient(
    ellipse 70% 50% at 50% 0%,
    rgba(99, 102, 241, 0.07) 0%,
    transparent 60%
  );
}

.hero-text-inner {
  max-width: 700px;
  margin: 0 auto;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  padding: 5px 14px;
  border-radius: 50px;
  border: 1px solid rgba(99, 102, 241, 0.3);
  background: rgba(99, 102, 241, 0.07);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  color: #818cf8;
  margin-bottom: 24px;
}

.hero-headline {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 1.05;
  margin-bottom: 16px;
}

.headline-gradient {
  background: linear-gradient(90deg, #818cf8, #38bdf8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-sub {
  font-size: 1rem;
  color: var(--muted);
  max-width: 540px;
  margin: 0 auto;
  line-height: 1.7;
}

/* ── Dashboard Preview Section ─────────────────────────────────────────────── */
.dashboard-preview-section {
  margin: 0 48px 80px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 32px 80px rgba(0, 0, 0, 0.65);
}

.dashboard-chrome {
  display: flex;
  flex-direction: column;
}

.chrome-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 16px;
  background: var(--bg3);
  border-bottom: 1px solid var(--border);
}

.chrome-dots {
  display: flex;
  gap: 6px;
}

.chrome-dots span {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.chrome-url {
  flex: 1;
  background: var(--surface);
  border-radius: 6px;
  padding: 5px 12px;
  font-family: "JetBrains Mono", "Courier New", monospace;
  font-size: 0.7rem;
  color: var(--muted);
}

/* ── Dashboard UI ──────────────────────────────────────────────────────────── */
.dashboard-ui {
  display: flex;
  height: 620px;
  background: var(--bg2);
  overflow: hidden;
}

/* Sidebar */
.sidebar {
  width: 192px;
  flex-shrink: 0;
  background: var(--bg3);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  padding: 16px 0;
  overflow: hidden;
}

.sidebar-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  margin-bottom: 20px;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text);
  white-space: nowrap;
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: 2px;
  padding: 0 8px;
}

.sidebar-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 6px;
  font-size: 0.8rem;
  color: var(--muted);
  text-decoration: none;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  white-space: nowrap;
}

.sidebar-item:hover {
  background: var(--surface);
  color: var(--text);
}

.sidebar-item.active {
  background: rgba(99, 102, 241, 0.1);
  color: #818cf8;
}

.sidebar-user {
  margin-top: auto;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  gap: 10px;
  border-top: 1px solid var(--border);
}

.sidebar-avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  flex-shrink: 0;
  background: linear-gradient(135deg, var(--accent), #38bdf8);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.68rem;
  font-weight: 700;
  color: #fff;
}

.sidebar-user-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.sidebar-user-name {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar-user-role {
  font-size: 0.68rem;
  color: var(--muted);
}

/* Main content */
.dash-main {
  flex: 1;
  overflow-y: auto;
  padding: 20px 24px;
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}

.dash-main::-webkit-scrollbar {
  width: 5px;
}
.dash-main::-webkit-scrollbar-thumb {
  background: var(--bg4);
  border-radius: 3px;
}

/* Top bar */
.dash-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}

.dash-greeting {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--text);
}

.dash-date {
  font-size: 0.72rem;
  color: var(--muted);
  margin-top: 2px;
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.btn-dash-action {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  border-radius: var(--radius);
  background: var(--accent);
  border: none;
  color: #fff;
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.2s;
}

.btn-dash-action:hover {
  opacity: 0.85;
}

.topbar-notif {
  position: relative;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius);
  background: var(--surface);
  border: 1px solid var(--border);
  cursor: pointer;
  color: var(--muted);
}

.notif-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--red);
  color: #fff;
  font-size: 0.6rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Metric cards */
.metric-cards {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 16px;
}

.metric-card {
  background: var(--bg4);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px;
}

.metric-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.metric-label {
  font-size: 0.7rem;
  color: var(--muted);
}

.metric-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 7px;
  border-radius: 50px;
  font-size: 0.66rem;
  font-weight: 600;
}

.metric-badge.up {
  background: rgba(16, 185, 129, 0.12);
  color: var(--green);
}
.metric-badge.down {
  background: rgba(239, 68, 68, 0.12);
  color: var(--red);
}

.metric-value {
  font-size: 1.4rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text);
  margin-bottom: 8px;
  font-variant-numeric: tabular-nums;
}

.metric-sparkline {
  margin-bottom: 6px;
}

.spark-bars {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 32px;
}

.spark-bars span {
  flex: 1;
  height: var(--h, 50%);
  background: rgba(99, 102, 241, 0.3);
  border-radius: 2px 2px 0 0;
}

.spark-bars span.spark-active {
  background: var(--accent);
}

.spark-bars.churn span {
  background: rgba(239, 68, 68, 0.2);
}
.spark-bars.churn span.spark-active {
  background: var(--red);
}

.metric-sub {
  font-size: 0.65rem;
  color: var(--muted);
}

/* Chart card */
.chart-card {
  background: var(--bg4);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  margin-bottom: 16px;
}

.chart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}

.chart-title {
  font-size: 0.82rem;
  font-weight: 600;
}

.chart-sub {
  font-size: 0.68rem;
  color: var(--muted);
  margin-top: 2px;
}

.chart-tabs {
  display: flex;
  gap: 4px;
}

.chart-tab {
  padding: 4px 10px;
  border-radius: 5px;
  background: none;
  border: 1px solid var(--border);
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  transition: all 0.15s;
}

.chart-tab:hover {
  color: var(--text);
  border-color: rgba(255, 255, 255, 0.15);
}

.chart-tab.active {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
  font-weight: 600;
}

.chart-wrap {
  position: relative;
}

.revenue-chart {
  width: 100%;
  height: 140px;
  overflow: visible;
  display: block;
}

/* Chart draw animation — JS sets strokeDasharray/Offset, then adds .drawn */
.revenue-chart path[stroke-linecap] {
  transition: stroke-dashoffset 1.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.revenue-chart path[stroke-linecap].drawn {
  stroke-dashoffset: 0;
}

.chart-x-labels {
  display: flex;
  justify-content: space-between;
  padding-top: 6px;
  font-size: 0.62rem;
  color: var(--muted);
}

/* Bottom row: transactions + activity */
.dash-bottom-row {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 16px;
}

.transactions-card,
.activity-card {
  background: var(--bg4);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  border-bottom: 1px solid var(--border);
}

.card-title {
  font-size: 0.82rem;
  font-weight: 600;
}

.card-link {
  font-size: 0.72rem;
  color: var(--accent);
  text-decoration: none;
  transition: opacity 0.2s;
}

.card-link:hover {
  opacity: 0.75;
}

/* Transactions table */
.tx-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.76rem;
}

.tx-table th {
  text-align: left;
  padding: 8px 14px;
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
  border-bottom: 1px solid var(--border);
}

.tx-table td {
  padding: 9px 14px;
  border-bottom: 1px solid var(--border);
}
.tx-table tr:last-child td {
  border-bottom: none;
}
.tx-table tr:hover td {
  background: var(--surface);
}

.tx-user {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tx-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--bg, #6366f1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.62rem;
  font-weight: 700;
  color: #fff;
}

.tx-plan {
  color: var(--muted);
  font-size: 0.74rem;
}
.tx-amount {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 50px;
  font-size: 0.66rem;
  font-weight: 600;
}

.status-badge::before {
  content: "";
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
}

.status-badge.paid {
  background: rgba(16, 185, 129, 0.1);
  color: var(--green);
}
.status-badge.pending {
  background: rgba(245, 158, 11, 0.1);
  color: var(--amber);
}
.status-badge.failed {
  background: rgba(239, 68, 68, 0.1);
  color: var(--red);
}

/* Activity feed */
.activity-card .card-header {
  border-bottom: 1px solid var(--border);
}

.activity-list {
  display: flex;
  flex-direction: column;
  padding: 4px 0;
}

.activity-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
}

.activity-item:last-child {
  border-bottom: none;
}

.activity-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--c, var(--accent));
  margin-top: 4px;
}

.activity-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.activity-text {
  font-size: 0.76rem;
  line-height: 1.45;
  color: var(--text);
}
.activity-text strong {
  color: var(--text);
}

.activity-time {
  font-size: 0.68rem;
  color: var(--muted);
}

/* ── Features Section ──────────────────────────────────────────────────────── */
.features-section {
  padding: 80px 48px;
}

.features-header {
  text-align: center;
  margin-bottom: 48px;
}

.features-eyebrow {
  display: block;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #818cf8;
  margin-bottom: 12px;
}

.features-title {
  font-size: clamp(1.5rem, 3vw, 2.2rem);
  font-weight: 800;
  letter-spacing: -0.025em;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.feature-card {
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  transition: border-color 0.25s, box-shadow 0.25s;
}

.feature-card:hover {
  border-color: rgba(99, 102, 241, 0.25);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.feature-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius);
  background: rgba(99, 102, 241, 0.1);
  border: 1px solid rgba(99, 102, 241, 0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--c, var(--accent));
  margin-bottom: 16px;
}

.feature-title {
  font-size: 0.92rem;
  font-weight: 700;
  margin-bottom: 8px;
}
.feature-desc {
  font-size: 0.8rem;
  color: var(--muted);
  line-height: 1.65;
}

/* ── Pricing Section ───────────────────────────────────────────────────────── */
.pricing-section {
  padding: 80px 48px;
  border-top: 1px solid var(--border);
}

.pricing-header {
  text-align: center;
  margin-bottom: 48px;
}

.pricing-title {
  font-size: clamp(1.5rem, 3vw, 2.2rem);
  font-weight: 800;
  letter-spacing: -0.025em;
  margin-bottom: 8px;
}

.pricing-sub {
  font-size: 0.95rem;
  color: var(--muted);
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  max-width: 700px;
  margin: 0 auto;
}

.plan-card {
  background: var(--bg3);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 28px;
  position: relative;
}

.plan-card.featured {
