*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
:root {
  --brand: #22c55e;
  --brand-light: #bbf7d0;
  --brand-dark: #15803d;
  --bg: #fafaf9;
  --dark: #1a2e1a;
  --text: #1c1917;
  --muted: #78716c;
  --radius: 1.5rem;
}
body {
  font-family: "Poppins", system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
}

/* NAV */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 2.5rem;
  background: var(--bg);
  border-bottom: 1px solid #e7e5e4;
  gap: 1.5rem;
}
.nav-logo {
  font-size: 1.1rem;
  font-weight: 800;
  text-decoration: none;
  color: var(--text);
}
.nav-links {
  list-style: none;
  display: flex;
  gap: 1.75rem;
}
.nav-links a {
  font-size: 0.875rem;
  color: var(--muted);
  text-decoration: none;
  font-weight: 500;
  transition: color 0.15s;
}
.nav-links a:hover {
  color: var(--text);
}
.btn-download {
  font-size: 0.875rem;
  font-weight: 700;
  padding: 0.6rem 1.25rem;
  background: var(--brand);
  color: #fff;
  border-radius: 0.625rem;
  text-decoration: none;
  transition: opacity 0.15s;
}
.btn-download:hover {
  opacity: 0.85;
}

/* HERO */
.hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  padding: 5rem 4rem;
  max-width: 1100px;
  margin: 0 auto;
  min-height: 85vh;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.35rem 0.875rem;
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
  color: var(--brand-dark);
  border-radius: 999px;
}
.hero-title {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
}
.brand-text {
  color: var(--brand);
}
.hero-sub {
  font-size: 0.9375rem;
  color: var(--muted);
  line-height: 1.7;
}
.hero-ctas {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}
.btn-primary {
  display: inline-flex;
  align-items: center;
  padding: 0.875rem 1.75rem;
  background: var(--brand);
  color: #fff;
  font-weight: 700;
  font-size: 0.9rem;
  border-radius: 0.875rem;
  text-decoration: none;
  transition: opacity 0.15s;
}
.btn-primary:hover {
  opacity: 0.85;
}
.btn-ghost {
  display: inline-flex;
  align-items: center;
  padding: 0.875rem 1.25rem;
  color: var(--brand-dark);
  font-weight: 600;
  font-size: 0.9rem;
  text-decoration: none;
  transition: color 0.15s;
