}
.section--green {
  background: #f0fdf4;
}
.section--cta {
  background: linear-gradient(135deg, var(--brand), var(--brand-dark));
}
.container {
  max-width: 960px;
  margin: 0 auto;
}
.section-eyebrow {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--brand);
  margin-bottom: 0.5rem;
}
.section-title {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.15;
  margin-bottom: 2.5rem;
}
.features-list {
  display: flex;
  flex-direction: column;
  gap: 5rem;
}
.feature-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}
.feature-row--reverse {
  direction: rtl;
}
.feature-row--reverse > * {
  direction: ltr;
}
.feature-num {
  font-size: 0.7rem;
  font-weight: 800;
  color: var(--brand);
  letter-spacing: 0.1em;
  display: block;
  margin-bottom: 0.5rem;
}
.feature-text h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
  letter-spacing: -0.02em;
}
.feature-text p {
  font-size: 0.9rem;
  color: var(--muted);
  line-height: 1.7;
}
.feature-visual {
  background: #fff;
  border-radius: var(--radius);
  padding: 1.5rem;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.habit-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.625rem 0.875rem;
  border-radius: 0.625rem;
  font-size: 0.8rem;
  color: var(--muted);
  background: #f0fdf4;
}
.habit-item.done {
