}
.hi-check {
  color: var(--brand);
  font-weight: 700;
}
.med-card {
  background: #f0fdf4;
  border-radius: 0.875rem;
  padding: 1rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.med-card--active {
  background: var(--brand);
  color: #fff;
}
.med-icon {
  font-size: 1.25rem;
}
.med-card h4 {
  font-size: 0.8rem;
