  height: 8px;
  border-radius: 50%;
  background: #38bdf8;
  opacity: 0;
  transition: opacity 0.15s, transform 0.15s;
  transform: scale(0.5);
}
.radio-input:checked + .radio-dot {
  border-color: #38bdf8;
}
.radio-input:checked + .radio-dot::after {
  opacity: 1;
  transform: scale(1);
}
.radio-input:focus-visible + .radio-dot {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
