  opacity: 1;
  transform: scale(1);
  animation: check-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* Error state */
.copy-btn.is-error {
  background: rgba(248, 113, 113, 0.1);
  border-color: rgba(248, 113, 113, 0.3);
  color: #f87171;
  animation: err-shake 0.4s ease;
}

@keyframes check-pop {
  0% {
    transform: scale(0.5);
  }
  60% {
    transform: scale(1.2);
  }
  100% {
    transform: scale(1);
  }
}

@keyframes err-shake {
  0%,
  100% {
    transform: translateX(0);
  }
  25% {
    transform: translateX(-3px);
  }
  75% {
    transform: translateX(3px);
  }
}

