/* ── Reset & Base ──────────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --off-white: #f5f3ee;
  --dark: #0a0a0a;
  --gold: #c9a96e;
  --muted: #6b6b6b;
  --border: rgba(10, 10, 10, 0.1);
  --font-serif: "Cormorant Garamond", "Playfair Display", Georgia, serif;
