}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--off-white);
  color: var(--dark);
  font-family: var(--font-sans);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* ── Nav ───────────────────────────────────────────────────────────────────── */
.nav {
