}

/* ── Slider track ── */
.slider-track {
  position: relative;
  height: 12px;
  border-radius: 999px;
  cursor: pointer;
  user-select: none;
}

/* hue gradient */
.hue-track {
  background: linear-gradient(
    to right,
    hsl(0, 100%, 50%),
    hsl(30, 100%, 50%),
    hsl(60, 100%, 50%),
    hsl(90, 100%, 50%),
    hsl(120, 100%, 50%),
    hsl(150, 100%, 50%),
    hsl(180, 100%, 50%),
    hsl(210, 100%, 50%),
    hsl(240, 100%, 50%),
    hsl(270, 100%, 50%),
    hsl(300, 100%, 50%),
    hsl(330, 100%, 50%),
    hsl(360, 100%, 50%)
  );
}

/* opacity track — canvas drawn by JS */
.opacity-track {
  background: none;
  overflow: hidden;
}
.opacity-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border-radius: 999px;
  pointer-events: none;
}

/* ── Slider thumb ── */
.slider-thumb {
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.5), 0 0 0 1.5px rgba(0, 0, 0, 0.2);
  pointer-events: none;
  left: 0;
}

/* ── Outputs ── */
.outputs {
  display: flex;
  gap: 0.5rem;
  padding: 0 1rem 1rem;
}

.output-group {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  flex: 1;
}
.output-group--wide {
  flex: 1.4;
}

.output-label {
  font-size: 0.65rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #475569;
}

.output-input {
  width: 100%;
  height: 2rem;
  padding: 0 0.5rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 7px;
  color: #cbd5e1;
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 0.75rem;
  cursor: text;
  outline: none;
  transition: border-color 0.15s;
}
.output-input:focus {
  border-color: rgba(99, 179, 237, 0.4);
}
.output-input:hover {
  border-color: rgba(255, 255, 255, 0.15);
}

