(function () {
  // ── Elements ──
  var canvasWrap = document.getElementById("canvas-wrap");
  var gradCanvas = document.getElementById("gradient-canvas");
  var crosshair = document.getElementById("crosshair");
  var hueTrack = document.getElementById("hue-track");
  var hueThumb = document.getElementById("hue-thumb");
  var opTrack = document.getElementById("opacity-track");
  var opThumb = document.getElementById("opacity-thumb");
  var opCanvas = document.getElementById("opacity-canvas");
  var swatch = document.getElementById("swatch");
  var outHex = document.getElementById("out-hex");
  var outRgb = document.getElementById("out-rgb");
  var outRgba = document.getElementById("out-rgba");

  // ── State ──
  var hue = 210; // 0-360
  var sat = 0.7; // 0-1 (x on gradient canvas)
  var light = 0.4; // 0-1 (y on gradient canvas, inverted)
  var alpha = 1; // 0-1

  // ── Helpers ──
  function clamp(v, lo, hi) {
    return Math.min(Math.max(v, lo), hi);
  }

  function hslToRgb(h, s, l) {
    // h: 0-360, s: 0-1, l: 0-1
    var c = (1 - Math.abs(2 * l - 1)) * s;
    var x = c * (1 - Math.abs(((h / 60) % 2) - 1));
    var m = l - c / 2;
    var r, g, b;
    if (h < 60) {
      r = c;
      g = x;
      b = 0;
    } else if (h < 120) {
      r = x;
      g = c;
      b = 0;
    } else if (h < 180) {
      r = 0;
      g = c;
      b = x;
    } else if (h < 240) {
      r = 0;
      g = x;
      b = c;
    } else if (h < 300) {
      r = x;
      g = 0;
      b = c;
    } else {
      r = c;
      g = 0;
      b = x;
    }
    return [Math.round((r + m) * 255), Math.round((g + m) * 255), Math.round((b + m) * 255)];
  }

  function toHex(r, g, b) {
    return (
      "#" +
      [r, g, b]
        .map(function (v) {
          return ("0" + v.toString(16)).slice(-2);
        })
        .join("")
    );
  }

  // ── Draw gradient canvas ──
  function drawGradient() {
    var ctx = gradCanvas.getContext("2d");
    var w = gradCanvas.width;
    var h = gradCanvas.height;

    // Base hue fill
    ctx.fillStyle = "hsl(" + hue + ", 100%, 50%)";
    ctx.fillRect(0, 0, w, h);

    // White → transparent (left→right)
    var wGrad = ctx.createLinearGradient(0, 0, w, 0);
    wGrad.addColorStop(0, "rgba(255,255,255,1)");
    wGrad.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = wGrad;
    ctx.fillRect(0, 0, w, h);

    // Transparent → black (top→bottom)
    var bGrad = ctx.createLinearGradient(0, 0, 0, h);
    bGrad.addColorStop(0, "rgba(0,0,0,0)");
    bGrad.addColorStop(1, "rgba(0,0,0,1)");
    ctx.fillStyle = bGrad;
    ctx.fillRect(0, 0, w, h);
  }

  // ── Draw opacity canvas ──
  function drawOpacity(rgb) {
    var ctx = opCanvas.getContext("2d");
    var w = opCanvas.offsetWidth || opTrack.offsetWidth;
    var h = opCanvas.offsetHeight || 12;
    opCanvas.width = w;
    opCanvas.height = h;

    // Checkerboard
    var tileSize = 6;
    for (var row = 0; row < Math.ceil(h / tileSize); row++) {
      for (var col = 0; col < Math.ceil(w / tileSize); col++) {
        ctx.fillStyle = (row + col) % 2 === 0 ? "#888" : "#555";
        ctx.fillRect(col * tileSize, row * tileSize, tileSize, tileSize);
      }
    }

    // Gradient overlay
    var grad = ctx.createLinearGradient(0, 0, w, 0);
    grad.addColorStop(0, "rgba(" + rgb[0] + "," + rgb[1] + "," + rgb[2] + ",0)");
    grad.addColorStop(1, "rgba(" + rgb[0] + "," + rgb[1] + "," + rgb[2] + ",1)");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
  }

  // ── Compute current HSL given canvas sat/light position ──
  // On the canvas: x=0 → white (s=0, l=1), x=1 → pure hue (s=1, l~0.5)
  // y=0 → bright, y=1 → black
  // We map directly: hslS = sat, hslL = 0.5 * (1 - sat) + sat * (1 - light) ... standard formula
  // Simpler: lightness from canvas coords:
  function canvasToHsl(sx, ly) {
    // sx = saturation on x axis (0-1), ly = darkness on y (0-1)
    // Convert from "canvas space" to real HSL:
    // white point at (0,0), black at (x, 1), pure hue at (1, 0)
    var s = sx;
    var l = (1 - ly) * (1 - sx / 2);
    // avoid s=0 when l=0
    return { s: s, l: clamp(l, 0, 1) };
  }

  // ── Update everything ──
  function update() {
    var hslCoords = canvasToHsl(sat, 1 - light);
    var rgb = hslToRgb(hue, hslCoords.s, hslCoords.l);
    var hex = toHex(rgb[0], rgb[1], rgb[2]);

    // Swatch
    swatch.style.background = "rgba(" + rgb[0] + "," + rgb[1] + "," + rgb[2] + "," + alpha + ")";

    // Outputs
    outHex.value = hex;
    outRgb.value = "rgb(" + rgb.join(", ") + ")";
    outRgba.value = "rgba(" + rgb.join(", ") + ", " + alpha.toFixed(2) + ")";

    // Crosshair position (sat on x, light on y, light=1 → top)
    var canvW = gradCanvas.offsetWidth || gradCanvas.width;
    var canvH = gradCanvas.offsetHeight || gradCanvas.height;
    crosshair.style.left = sat * canvW + "px";
    crosshair.style.top = (1 - light) * canvH + "px";

    // Hue thumb
    hueThumb.style.left = (hue / 360) * 100 + "%";

    // Opacity thumb
    opThumb.style.left = alpha * 100 + "%";

    // Redraw opacity strip
    drawOpacity(rgb);
  }

  // ── Canvas drag ──
  function pickFromCanvas(e) {
    var rect = gradCanvas.getBoundingClientRect();
    var x = clamp((e.clientX - rect.left) / rect.width, 0, 1);
    var y = clamp((e.clientY - rect.top) / rect.height, 0, 1);
    sat = x;
    light = 1 - y;
    update();
  }

  var draggingCanvas = false;
  canvasWrap.addEventListener("mousedown", function (e) {
    draggingCanvas = true;
    pickFromCanvas(e);
  });
  document.addEventListener("mousemove", function (e) {
    if (draggingCanvas) pickFromCanvas(e);
  });
  document.addEventListener("mouseup", function () {
    draggingCanvas = false;
  });

  // touch
  canvasWrap.addEventListener(
    "touchstart",
    function (e) {
      draggingCanvas = true;
      pickFromCanvas(e.touches[0]);
      e.preventDefault();
    },
    { passive: false }
  );
  document.addEventListener(
    "touchmove",
    function (e) {
      if (draggingCanvas) {
        pickFromCanvas(e.touches[0]);
        e.preventDefault();
      }
    },
    { passive: false }
  );
  document.addEventListener("touchend", function () {
    draggingCanvas = false;
  });

  // ── Hue slider drag ──
  function pickHue(e) {
    var rect = hueTrack.getBoundingClientRect();
    hue = clamp(((e.clientX - rect.left) / rect.width) * 360, 0, 360);
    drawGradient();
    update();
  }
  var draggingHue = false;
  hueTrack.addEventListener("mousedown", function (e) {
    draggingHue = true;
    pickHue(e);
  });
  document.addEventListener("mousemove", function (e) {
    if (draggingHue) pickHue(e);
  });
  document.addEventListener("mouseup", function () {
    draggingHue = false;
  });

  hueTrack.addEventListener(
    "touchstart",
    function (e) {
      draggingHue = true;
      pickHue(e.touches[0]);
      e.preventDefault();
    },
    { passive: false }
  );
  document.addEventListener(
    "touchmove",
    function (e) {
      if (draggingHue) {
        pickHue(e.touches[0]);
        e.preventDefault();
      }
    },
    { passive: false }
  );
  document.addEventListener("touchend", function () {
    draggingHue = false;
  });

  // ── Opacity slider drag ──
  function pickOpacity(e) {
    var rect = opTrack.getBoundingClientRect();
    alpha = clamp((e.clientX - rect.left) / rect.width, 0, 1);
    update();
  }
  var draggingOp = false;
  opTrack.addEventListener("mousedown", function (e) {
    draggingOp = true;
    pickOpacity(e);
  });
  document.addEventListener("mousemove", function (e) {
    if (draggingOp) pickOpacity(e);
  });
  document.addEventListener("mouseup", function () {
    draggingOp = false;
  });

  opTrack.addEventListener(
    "touchstart",
    function (e) {
      draggingOp = true;
      pickOpacity(e.touches[0]);
      e.preventDefault();
    },
    { passive: false }
  );
  document.addEventListener(
    "touchmove",
    function (e) {
      if (draggingOp) {
        pickOpacity(e.touches[0]);
        e.preventDefault();
      }
    },
    { passive: false }
  );
  document.addEventListener("touchend", function () {
    draggingOp = false;
  });

  // ── Click-to-copy outputs ──
  [outHex, outRgb, outRgba].forEach(function (el) {
    el.addEventListener("click", function () {
      el.select();
      document.execCommand("copy");
    });
  });

  // ── Init ──
  drawGradient();
  update();
})();

snippets.css:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #050910;
  --card: #0d1117;
  --border: rgba(255, 255, 255, 0.08);
  --text: #f2f6ff;
  --muted: #475569;
  --accent: #38bdf8;
  --danger: #f87171;
  --success: #4ade80;
  --warning: #fbbf24;
  --info: #60a5fa;
  --radius: 12px;
  --transition: 0.32s cubic-bezier(0.4, 0, 0.2, 1);
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, sans-serif;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ── Demo center ── */
.demo-center {
  text-align: center;
  max-width: 420px;
  padding: 2rem;
}

.demo-title {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  letter-spacing: -0.02em;
}

.demo-subtitle {
  color: var(--muted);
  margin-bottom: 2rem;
  font-size: 0.9rem;
}

.trigger-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
}

.trigger-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  justify-content: center;
  background: var(--card);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
}

.trigger-btn:hover {
  border-color: var(--accent);
  background: rgba(56, 189, 248, 0.06);
}

.trigger-icon {
  font-size: 1rem;
  color: var(--accent);
}

/* ── Backdrop ── */
.backdrop {
  position: fixed;
  inset: 0;
  background: rgba(5, 9, 16, 0.7);
  backdrop-filter: blur(2px);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition);
  z-index: 100;
}

.backdrop.active {
  opacity: 1;
  pointer-events: all;
}

/* ── Drawers base ── */
.drawer {
  position: fixed;
  background: var(--card);
  z-index: 200;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition);
  border-color: var(--border);
}

.drawer__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.125rem 1.25rem;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}

.drawer__title {
  font-size: 1rem;
  font-weight: 600;
}

.drawer__logo {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--accent);
}

.drawer__close {
  background: none;
  border: none;
  color: var(--muted);
  font-size: 1rem;
  cursor: pointer;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  display: grid;
  place-items: center;
  transition: color 0.2s, background 0.2s;
}

.drawer__close:hover {
  color: var(--text);
  background: rgba(255, 255, 255, 0.06);
}

.drawer__content {
  flex: 1;
  overflow-y: auto;
  padding: 1.25rem;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.1) transparent;
}

.drawer__content--horizontal {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  overflow-y: hidden;
  align-items: flex-start;
}

.drawer__desc {
  color: var(--muted);
  font-size: 0.875rem;
  line-height: 1.6;
  margin-bottom: 1.25rem;
}

.drawer__footer {
  padding: 1rem 1.25rem;
  border-top: 1px solid var(--border);
  flex-shrink: 0;
}

/* ── Bottom sheet ── */
.drawer--bottom {
  bottom: 0;
  left: 0;
  right: 0;
  border-radius: var(--radius) var(--radius) 0 0;
  border-top: 1px solid var(--border);
  max-height: 80vh;
  transform: translateY(100%);
}

.drawer--bottom.open {
  transform: translateY(0);
}

.drawer__handle-bar {
  width: 36px;
  height: 4px;
  background: rgba(255, 255, 255, 0.18);
  border-radius: 2px;
  margin: 0.625rem auto 0;
  flex-shrink: 0;
  cursor: grab;
}

/* ── Right drawer ── */
.drawer--right {
  top: 0;
  right: 0;
  bottom: 0;
  width: 320px;
  border-left: 1px solid var(--border);
  transform: translateX(100%);
}

.drawer--right.open {
  transform: translateX(0);
}

/* ── Left drawer ── */
.drawer--left {
  top: 0;
  left: 0;
  bottom: 0;
  width: 260px;
  border-right: 1px solid var(--border);
  transform: translateX(-100%);
}

.drawer--left.open {
  transform: translateX(0);
}

/* ── Top drawer ── */
.drawer--top {
  top: 0;
  left: 0;
  right: 0;
  border-bottom: 1px solid var(--border);
  transform: translateY(-100%);
}

.drawer--top.open {
  transform: translateY(0);
}

/* ── Drawer list ── */
.drawer__list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.drawer__list-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem;
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.9rem;
  transition: background 0.2s;
}

.drawer__list-item:hover {
  background: rgba(255, 255, 255, 0.04);
}

.drawer__list-item .danger {
  color: var(--danger);
}

.drawer__list-icon {
  font-size: 1.1rem;
  width: 24px;
  text-align: center;
}

/* ── Settings controls ── */
.drawer__section {
  margin-bottom: 1.5rem;
}

.drawer__label {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  margin-bottom: 0.625rem;
}

.drawer__toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.5rem 0;
  font-size: 0.875rem;
}

.toggle {
  width: 40px;
  height: 22px;
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.1);
  cursor: pointer;
  position: relative;
  transition: background 0.2s;
  flex-shrink: 0;
}

.toggle::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--muted);
  transition: transform 0.2s, background 0.2s;
}

.toggle.active {
  background: rgba(56, 189, 248, 0.25);
}

.toggle.active::after {
  transform: translateX(18px);
  background: var(--accent);
}

.drawer__select {
  width: 100%;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 0.5rem 0.75rem;
  border-radius: 8px;
  font-size: 0.875rem;
  cursor: pointer;
}

/* ── Nav items ── */
.drawer__nav {
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
}

.drawer__nav-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.625rem 0.75rem;
  border-radius: 8px;
  color: var(--muted);
  text-decoration: none;
  font-size: 0.9rem;
  transition: background 0.2s, color 0.2s;
}

.drawer__nav-item:hover,
.drawer__nav-item.active {
  background: rgba(56, 189, 248, 0.08);
  color: var(--text);
}

.drawer__nav-item.active {
  color: var(--accent);
}

.drawer__nav-icon {
  font-size: 1rem;
  width: 20px;
  text-align: center;
}

.drawer__nav-divider {
  height: 1px;
  background: var(--border);
  margin: 0.5rem 0;
}

/* ── Notifications ── */
.notification {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.875rem;
  border-radius: 8px;
  border: 1px solid var(--border);
  min-width: 220px;
  background: rgba(255, 255, 255, 0.02);
}

.notification p {
  font-size: 0.8rem;
  color: var(--muted);
  margin-top: 0.2rem;
}

.notification strong {
  font-size: 0.875rem;
}

.notification__icon {
  font-size: 1rem;
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: grid;
  place-items: center;
}

.notification--success .notification__icon {
  background: rgba(74, 222, 128, 0.12);
  color: var(--success);
}
.notification--warning .notification__icon {
  background: rgba(251, 191, 36, 0.12);
  color: var(--warning);
}
.notification--info .notification__icon {
  background: rgba(96, 165, 250, 0.12);
  color: var(--info);
}

/* ── Buttons ── */
.btn-primary {
  display: block;
  width: 100%;
  padding: 0.625rem;
  background: var(--accent);
  color: #050910;
  border: none;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.2s;
}

.btn-primary:hover {
  opacity: 0.85;
}

