/* ── Tooltip base ── */
.tooltip-wrap {
  position: relative;
  display: inline-block;
}

/* Bubble */
.tooltip-wrap::after {
  content: attr(data-tooltip);
  position: absolute;
  z-index: 100;
  white-space: nowrap;
  font-size: 0.8rem;
  font-weight: 500;
  line-height: 1;
  padding: 0.45rem 0.75rem;
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #e2e8f0;
  border-radius: 0.45rem;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.15s ease, transform 0.15s ease;
}

/* Arrow */
.tooltip-wrap::before {
  content: "";
  position: absolute;
  z-index: 101;
  width: 0;
  height: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.15s ease, transform 0.15s ease;
}

/* Show on hover / focus-within */
.tooltip-wrap:hover::before,
.tooltip-wrap:hover::after,
.tooltip-wrap:focus-within::before,
.tooltip-wrap:focus-within::after {
  opacity: 1;
}

/* ── Top ── */
.tooltip--top::after {
  bottom: calc(100% + 10px);
  left: 50%;
  transform: translateX(-50%) translateY(4px);
}
.tooltip--top:hover::after,
.tooltip--top:focus-within::after {
  transform: translateX(-50%) translateY(0);
}

.tooltip--top::before {
  bottom: calc(100% + 4px);
  left: 50%;
  transform: translateX(-50%) translateY(4px);
  border: 6px solid transparent;
  border-top-color: #1e293b;
}
.tooltip--top:hover::before,
.tooltip--top:focus-within::before {
  transform: translateX(-50%) translateY(0);
}

/* ── Right ── */
.tooltip--right::after {
  left: calc(100% + 10px);
  top: 50%;
  transform: translateY(-50%) translateX(-4px);
}
.tooltip--right:hover::after,
.tooltip--right:focus-within::after {
  transform: translateY(-50%) translateX(0);
}

.tooltip--right::before {
  left: calc(100% + 4px);
  top: 50%;
  transform: translateY(-50%) translateX(-4px);
  border: 6px solid transparent;
  border-right-color: #1e293b;
}
.tooltip--right:hover::before,
.tooltip--right:focus-within::before {
  transform: translateY(-50%) translateX(0);
}

/* ── Bottom ── */
