  }
}

@media (max-width: 480px) {
  .hero h1 {
    font-size: 2.2rem;
  }
  .cta-section h2 {
    font-size: 2.5rem;
  }
  .stats-grid {
    grid-template-columns: 1fr 1fr;
  }
}

