import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import Lenis from "lenis";

import * as THREE from "three";

gsap.registerPlugin(ScrollTrigger);

initDemoShell({
  title: "Premium Velocity Experience",
  category: "pages",
  tech: ["three.js", "lenis", "gsap", "canvas-2d", "velocity"],
});

const reduced = prefersReducedMotion();
if (reduced) document.documentElement.classList.add("reduced-motion");

// ─── Lenis Setup ──────────────────────────────────────────────────────────────
const lenis = new Lenis({ lerp: 0.08, smoothWheel: true });
lenis.on("scroll", ScrollTrigger.update);
gsap.ticker.lagSmoothing(0);

// ─── Three.js Hero ───────────────────────────────────────────────────────────
const heroCanvas = document.getElementById("hero-canvas");
const renderer = new THREE.WebGLRenderer({ canvas: heroCanvas, alpha: true, antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.z = 5;

// Icosahedron wireframe
const geo = new THREE.IcosahedronGeometry(1.8, 2);
const mat = new THREE.MeshBasicMaterial({
  color: 0x86e8ff,
  wireframe: true,
  transparent: true,
  opacity: 0.18,
});
const mesh = new THREE.Mesh(geo, mat);
scene.add(mesh);

// Inner sphere
const innerGeo = new THREE.SphereGeometry(0.9, 16, 16);
const innerMat = new THREE.MeshBasicMaterial({
  color: 0xae52ff,
  wireframe: true,
  transparent: true,
  opacity: 0.1,
});
const innerMesh = new THREE.Mesh(innerGeo, innerMat);
scene.add(innerMesh);

// Ambient particles
const particleCount = 600;
const positions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount; i++) {
  positions[i * 3] = (Math.random() - 0.5) * 20;
  positions[i * 3 + 1] = (Math.random() - 0.5) * 20;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 10;
}
const partGeo = new THREE.BufferGeometry();
partGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
const partMat = new THREE.PointsMaterial({
  color: 0x86e8ff,
  size: 0.03,
  transparent: true,
  opacity: 0.4,
});
const particles = new THREE.Points(partGeo, partMat);
scene.add(particles);

// Scroll-driven rotation
let scrollProgress = 0;
ScrollTrigger.create({
  trigger: document.body,
  start: "top top",
  end: "bottom bottom",
  onUpdate: (self) => {
    scrollProgress = self.progress;
  },
});

window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ─── Velocity Canvas (Demo 39 technique) ─────────────────────────────────────
const velCanvas = document.getElementById("velocity-canvas");
const ctx = velCanvas.getContext("2d");
let velocity = 0;
let smoothVelocity = 0;

function resizeVelCanvas() {
  velCanvas.width = window.innerWidth;
  velCanvas.height = window.innerHeight;
}
resizeVelCanvas();
window.addEventListener("resize", resizeVelCanvas);

function drawSpeedLines(vel) {
  const cx = velCanvas.width / 2;
  const cy = velCanvas.height / 2;
  const absVel = Math.abs(vel);
  const count = Math.floor(Math.min(80, absVel * 5));
  const opacity = Math.min(0.65, absVel * 0.045);
  const maxLen = Math.min(velCanvas.width, velCanvas.height) * 0.45 * Math.min(1, absVel * 0.025);

  ctx.clearRect(0, 0, velCanvas.width, velCanvas.height);
  if (count < 1 || opacity < 0.02) return;

  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    const minR = 60;
    const sx = cx + Math.cos(angle) * minR;
    const sy = cy + Math.sin(angle) * minR;
    const ex = cx + Math.cos(angle) * (minR + maxLen);
    const ey = cy + Math.sin(angle) * (minR + maxLen);

    const grad = ctx.createLinearGradient(sx, sy, ex, ey);
    grad.addColorStop(0, `rgba(134, 232, 255, ${opacity})`);
    grad.addColorStop(0.5, `rgba(174, 82, 255, ${opacity * 0.5})`);
    grad.addColorStop(1, "rgba(134, 232, 255, 0)");

    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.lineTo(ex, ey);
    ctx.strokeStyle = grad;
    ctx.lineWidth = Math.max(0.5, absVel * 0.12);
    ctx.stroke();
  }
}

// Speed indicator UI
const speedFill = document.getElementById("speed-fill");
const speedValue = document.getElementById("speed-value");

// ─── Lenis scroll event ───────────────────────────────────────────────────────
lenis.on("scroll", (e) => {
  velocity = e.velocity;

  // Update speed UI
  const absVel = Math.abs(velocity);
  const pct = Math.min(100, absVel * 6);
  if (speedFill) speedFill.style.width = pct + "%";
  if (speedValue) speedValue.textContent = absVel.toFixed(1);
});

// ─── Main Animation Loop ──────────────────────────────────────────────────────
gsap.ticker.add((time) => {
  lenis.raf(time * 1000);

  // Smooth velocity decay
  smoothVelocity += (velocity - smoothVelocity) * 0.1;
  velocity *= 0.92;

  if (!reduced) {
    // Draw speed lines
    drawSpeedLines(smoothVelocity);

    // Rotate Three.js meshes
    const t = time * 0.3;
    mesh.rotation.x = t * 0.4 + scrollProgress * Math.PI * 2;
    mesh.rotation.y = t * 0.6;
    innerMesh.rotation.x = -t * 0.5;
    innerMesh.rotation.y = t * 0.8 + scrollProgress * Math.PI;
    particles.rotation.y = t * 0.08;

    // Velocity effect on mesh scale
    const absVel = Math.abs(smoothVelocity);
    const scalePulse = 1 + absVel * 0.008;
    mesh.scale.setScalar(scalePulse);
  }

  renderer.render(scene, camera);
});

// ─── Gradient hue shift on scroll ────────────────────────────────────────────
if (!reduced) {
  ScrollTrigger.create({
    trigger: document.body,
    start: "top top",
    end: "bottom bottom",
    onUpdate: (self) => {
      document.documentElement.style.setProperty("--hue-shift", `${self.progress * 300}deg`);
    },
  });
}

// ─── Hero entrance ────────────────────────────────────────────────────────────
if (!reduced) {
  gsap.set([".hero-tag", ".hero h1", ".hero-desc", ".speed-indicator"], { opacity: 0, y: 30 });
  gsap
    .timeline({ defaults: { ease: "expo.out" } })
    .to(".hero-tag", { opacity: 1, y: 0, duration: 0.7, delay: 0.5 })
    .to(".hero h1", { opacity: 1, y: 0, duration: 1 }, "-=0.4")
    .to(".hero-desc", { opacity: 1, y: 0, duration: 0.7 }, "-=0.5")
    .to(".speed-indicator", { opacity: 1, y: 0, duration: 0.6 }, "-=0.4");
}

// ─── Depth cards entrance (Demo 38 technique) ─────────────────────────────────
document.querySelectorAll(".depth-card").forEach((card, i) => {
  const depth = parseFloat(card.style.getPropertyValue("--depth")) || 0.5;

  if (!reduced) {
    gsap.set(card, { opacity: 0, y: 60, rotationX: 15, scale: 0.85 });
    gsap.to(card, {
      opacity: 1,
      y: 0,
      rotationX: 0,
      scale: 1,
      duration: 1,
      ease: "expo.out",
      delay: depth * 0.3,
      scrollTrigger: {
        trigger: ".depth-section",
        start: "top 70%",
        toggleActions: "play none none reverse",
      },
    });

    card.addEventListener("mouseenter", () =>
      gsap.to(card, { y: -12, duration: 0.4, overwrite: "auto" })
    );
    card.addEventListener("mouseleave", () =>
      gsap.to(card, { y: 0, duration: 0.4, overwrite: "auto" })
    );
  }
});

// ─── Stats counters ───────────────────────────────────────────────────────────
document.querySelectorAll(".stat-card").forEach((card, i) => {
  const valEl = card.querySelector(".stat-value");
  const target = parseFloat(card.dataset.target);
  const suffix = card.dataset.suffix || "";

  if (!reduced) {
    gsap.set(card, { opacity: 0, y: 30 });
    gsap.to(card, {
      opacity: 1,
      y: 0,
      duration: 0.7,
      ease: "expo.out",
      delay: i * 0.08,
      scrollTrigger: {
        trigger: ".stats-grid",
        start: "top 75%",
        toggleActions: "play none none reverse",
      },
    });

    ScrollTrigger.create({
      trigger: card,
      start: "top 80%",
      end: "top 25%",
      onUpdate: (self) => {
        const val = target * self.progress;
        const display = target % 1 !== 0 ? val.toFixed(1) : Math.round(val);
        valEl.textContent = display + suffix;
      },
    });
  } else {
    valEl.textContent = target + suffix;
  }
});

// ─── Features list ────────────────────────────────────────────────────────────
document.querySelectorAll(".feature-item").forEach((item, i) => {
  if (!reduced) {
    gsap.set(item, { opacity: 0, x: -30 });
    gsap.to(item, {
      opacity: 1,
      x: 0,
      duration: 0.8,
      ease: "expo.out",
      delay: i * 0.1,
      scrollTrigger: { trigger: item, start: "top 75%", toggleActions: "play none none reverse" },
    });
  }
});

// Section headers
document.querySelectorAll(".section-header").forEach((h) => {
  if (!reduced) {
    gsap.set(h.children, { opacity: 0, y: 25 });
    gsap.to(h.children, {
      opacity: 1,
      y: 0,
      duration: 0.7,
      stagger: 0.1,
      ease: "expo.out",
      scrollTrigger: { trigger: h, start: "top 75%", toggleActions: "play none none reverse" },
    });
  }
});

// CTA
if (!reduced) {
  gsap.set(".cta-section h2, .cta-section p, .cta-section a", { opacity: 0, y: 25 });
  gsap.to(".cta-section h2, .cta-section p, .cta-section a", {
    opacity: 1,
    y: 0,
    duration: 0.8,
    stagger: 0.12,
    ease: "expo.out",
    scrollTrigger: {
      trigger: ".cta-section",
      start: "top 75%",
      toggleActions: "play none none reverse",
    },
  });
}

// ─── Motion preference ────────────────────────────────────────────────────────
window.addEventListener("motion-preference", (e) => {
  if (e.detail.reduced) {
    gsap.globalTimeline.paused(true);
    ctx.clearRect(0, 0, velCanvas.width, velCanvas.height);
  } else {
    gsap.globalTimeline.paused(false);
  }
});

snippets.css:
:root {
  color-scheme: dark;
  --bg: #05060a;
  --glass: rgba(7, 10, 20, 0.58);
  --stroke: rgba(255, 255, 255, 0.12);
  --text: #f5f5f0;
  --muted: rgba(245, 245, 240, 0.6);
  --accent: #f26b3a;
  --accent-soft: rgba(242, 107, 58, 0.2);
  --lime: #b6ff57;
  --cyan: #3de0c3;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: "Space Grotesk", sans-serif;
  color: var(--text);
  background: var(--bg);
  min-height: 100vh;
  overflow-x: hidden;
  cursor: none;
}

a {
  color: inherit;
  text-decoration: none;
}

#webGLApp {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
}

.site-header {
  position: fixed;
  top: 1.5rem;
  left: 50%;
  transform: translateX(-50%);
  z-index: 5;
  width: min(1100px, 92vw);
  display: flex;
  justify-content: center;
  pointer-events: none;
}

.nav-pill {
  width: 100%;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 2rem;
  padding: 0.9rem 1.6rem;
  border-radius: 999px;
  background: rgba(8, 12, 22, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.18);
  backdrop-filter: blur(18px);
  box-shadow: 0 20px 40px rgba(5, 6, 10, 0.45);
  pointer-events: auto;
}

.brand {
  display: flex;
  gap: 1rem;
  align-items: center;
  font-family: "Syne", sans-serif;
}

.mark {
  width: 46px;
  height: 46px;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0.02));
  border: 1px solid rgba(255, 255, 255, 0.2);
  display: grid;
  place-items: center;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.brand-title {
  text-transform: uppercase;
  font-weight: 700;
  letter-spacing: 0.12em;
  font-size: 0.85rem;
}

.brand-subtitle {
  font-size: 0.8rem;
  color: var(--muted);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 1.4rem;
  font-size: 0.9rem;
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
}

.nav-links a {
  color: var(--muted);
  transition: color 0.3s ease;
}

.nav-links a:hover {
  color: var(--text);
}

.nav-links .cta {
  padding: 0.5rem 1.1rem;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.08);
  color: var(--text);
}

.page {
  position: relative;
  z-index: 2;
  padding: 6.5rem 5vw 6rem;
}

.hero {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 3rem;
  padding: 5rem 0 3rem;
}

.hero-copy h1 {
  font-family: "Syne", sans-serif;
  font-size: clamp(2.6rem, 4vw, 4.5rem);
  line-height: 1.05;
  margin-bottom: 1.5rem;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.3em;
  font-size: 0.7rem;
  color: var(--lime);
  margin-bottom: 1rem;
}

.lead {
  color: var(--muted);
  font-size: 1.1rem;
  line-height: 1.6;
  max-width: 540px;
}

.muted {
  color: var(--muted);
}

.hero-actions {
  margin-top: 2rem;
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.primary,
.ghost {
  border: none;
  padding: 0.9rem 1.6rem;
  border-radius: 999px;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.primary {
  background: var(--accent);
  color: #120d0b;
  box-shadow: 0 20px 40px rgba(242, 107, 58, 0.3);
}

.ghost {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.3);
  color: var(--text);
}

.primary:hover,
.ghost:hover {
  transform: translateY(-2px);
}

.status {
  margin-top: 2rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 0.85rem;
  color: var(--muted);
}

.status .dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 12px rgba(182, 255, 87, 0.8);
}

.hero-panel {
  background: var(--glass);
  border: 1px solid var(--stroke);
  border-radius: 24px;
  padding: 2rem;
  backdrop-filter: blur(16px);
}

.panel-title {
  font-family: "Syne", sans-serif;
  font-weight: 600;
  margin-bottom: 1.5rem;
}

.panel-grid {
  display: grid;
  gap: 1rem;
}

.panel-card {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  padding: 1rem;
  display: grid;
  gap: 0.4rem;
}

.section {
  margin-top: 5rem;
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 2rem;
  flex-wrap: wrap;
}

.section-header h2 {
  font-family: "Syne", sans-serif;
  font-size: clamp(1.8rem, 3vw, 2.6rem);
}

.scheme-controls {
  display: flex;
  align-items: center;
  gap: 1rem;
  color: var(--muted);
  font-size: 0.85rem;
}

.scheme-buttons {
  display: flex;
  gap: 0.5rem;
}

.scheme-btn {
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.08);
  color: var(--text);
  padding: 0.4rem 0.9rem;
  font-size: 0.75rem;
  cursor: pointer;
}

.scheme-btn.active {
  background: var(--accent-soft);
  border-color: rgba(242, 107, 58, 0.5);
  color: var(--accent);
}

.projects {
  margin-top: 2.5rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1.5rem;
}

.project-card {
  background: var(--glass);
  border: 1px solid var(--stroke);
  border-radius: 24px;
  padding: 1.5rem;
  display: grid;
  gap: 1rem;
  min-height: 220px;
  backdrop-filter: blur(16px);
}

.project-meta {
  display: flex;
  justify-content: space-between;
  color: var(--muted);
  font-size: 0.75rem;
}

.project-card h3 {
  font-family: "Syne", sans-serif;
  font-size: 1.3rem;
}

.tag-list {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.tag {
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 999px;
  padding: 0.2rem 0.7rem;
  font-size: 0.7rem;
  color: var(--muted);
}

.services {
  margin-top: 2.5rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 1.5rem;
}

.services article {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 20px;
  padding: 1.5rem;
  min-height: 180px;
}

.split {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 3rem;
}

.facts {
  list-style: none;
  margin-top: 1.5rem;
  display: grid;
  gap: 0.6rem;
  color: var(--muted);
}

.timeline {
  background: var(--glass);
  border: 1px solid var(--stroke);
  border-radius: 24px;
  padding: 2rem;
  display: grid;
  gap: 1.2rem;
  backdrop-filter: blur(16px);
}

.timeline-item {
  display: grid;
  gap: 0.3rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.timeline-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.contact-card {
  background: rgba(15, 18, 32, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 24px;
  padding: 2.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 2rem;
}

.contact-actions {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.site-footer {
  position: relative;
  z-index: 2;
  padding: 2rem 5vw 3rem;
  display: flex;
  justify-content: space-between;
  color: var(--muted);
  font-size: 0.85rem;
}

.custom-cursor {
  position: fixed;
  top: 0;
  left: 0;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.35);
  background: radial-gradient(
    circle at 30% 30%,
    rgba(255, 255, 255, 0.45),
    rgba(255, 255, 255, 0.05) 55%,
    rgba(0, 0, 0, 0.2) 100%
  );
  box-shadow: 0 0 18px rgba(255, 255, 255, 0.2), inset 0 0 12px rgba(255, 255, 255, 0.2);
  mix-blend-mode: screen;
  pointer-events: none;
  z-index: 1000;
  transform: translate(-50%, -50%);
  transition: width 0.2s ease, height 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease,
    background 0.2s ease;
}

.custom-cursor.is-active {
  width: 64px;
  height: 64px;
  border-color: rgba(255, 255, 255, 0.6);
  box-shadow: 0 0 30px rgba(255, 255, 255, 0.4), inset 0 0 16px rgba(255, 255, 255, 0.35);
  background: radial-gradient(
    circle at 30% 30%,
    rgba(255, 255, 255, 0.6),
    rgba(242, 107, 58, 0.12) 55%,
    rgba(0, 0, 0, 0.2) 100%
  );
}

.custom-cursor.is-cta {
  width: 72px;
  height: 72px;
  border-color: rgba(182, 255, 87, 0.8);
  box-shadow: 0 0 36px rgba(182, 255, 87, 0.35), inset 0 0 20px rgba(255, 255, 255, 0.35);
  background: radial-gradient(
    circle at 30% 30%,
    rgba(182, 255, 87, 0.7),
    rgba(61, 224, 195, 0.2) 60%,
    rgba(0, 0, 0, 0.2) 100%
  );
}

@media (max-width: 900px) {
  .nav-pill {
    flex-direction: column;
    align-items: flex-start;
    border-radius: 28px;
    gap: 1rem;
  }

  .nav-links {
    flex-wrap: wrap;
    gap: 0.9rem;
    position: static;
    transform: none;
  }

  .contact-card {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 640px) {
  .site-header {
    top: 1rem;
  }

  .hero {
    padding-top: 3rem;
  }

  .scheme-controls {
    width: 100%;
    justify-content: space-between;
  }
}

