/* ─── Reset & Base ───────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #0a0a0a;
  --text: #f5f5f5;
  --muted: #555;
  --accent: #e8ff00;
  --border: #1c1c1c;
  --rule: 1px solid var(--border);
  --pad: clamp(1.5rem, 5vw, 4rem);
}

html {
  font-size: 16px;
  scroll-behavior: auto; /* Lenis handles smoothing */
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, "Helvetica Neue", Arial, sans-serif;
  font-weight: 400;
  line-height: 1.5;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* Reduced-motion: disable all transitions */
.reduced-motion *,
.reduced-motion *::before,
.reduced-motion *::after {
  transition-duration: 0.001ms !important;
  animation-duration: 0.001ms !important;
}

/* ─── Reusable ───────────────────────────────────────────────────────────── */
.label {
  font-family: "SF Mono", "Fira Code", "Courier New", monospace;
  font-size: 0.65rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--muted);
}

.label--right {
  margin-left: auto;
}

.section-index {
  font-family: "SF Mono", "Fira Code", "Courier New", monospace;
  font-size: 0.6rem;
  color: var(--accent);
  letter-spacing: 0.1em;
}

.section-label {
  font-family: "SF Mono", "Fira Code", "Courier New", monospace;
  font-size: 0.6rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
}

/* ─── Hero ───────────────────────────────────────────────────────────────── */
.hero {
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  border-bottom: var(--rule);
}

.hero__inner {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: var(--pad);
  padding-top: calc(var(--pad) + 3rem); /* offset for demo-shell bar */
}

.hero__meta {
  display: flex;
  align-items: center;
  margin-bottom: clamp(3rem, 8vh, 6rem);
  border-bottom: var(--rule);
  padding-bottom: 1rem;
}

.hero__name {
  font-size: clamp(4rem, 14vw, 12rem);
  font-weight: 900;
  line-height: 0.92;
  letter-spacing: -0.03em;
  text-transform: uppercase;
  flex: 1;
  /* overflow clip for char animation */
  overflow: hidden;
}

/* SplitText wraps each line; clip the parent */
.hero__name .line {
  overflow: hidden;
}
.hero__name .char {
  display: inline-block;
}

.hero__foot {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 2rem;
  border-top: var(--rule);
  gap: 2rem;
}

.hero__tagline {
  font-size: clamp(0.85rem, 1.8vw, 1.1rem);
  color: var(--muted);
  line-height: 1.7;
  font-weight: 300;
  max-width: 22ch;
}

.hero__scroll-cue {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  flex-shrink: 0;
}

.scroll-line {
  display: block;
  width: 1px;
  height: 60px;
  background: linear-gradient(to bottom, var(--accent), transparent);
  animation: scrollPulse 2s ease-in-out infinite;
}

.scroll-text {
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 0.55rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
  writing-mode: vertical-rl;
}

@keyframes scrollPulse {
  0%,
  100% {
    opacity: 0.3;
    transform: scaleY(1);
  }
  50% {
    opacity: 1;
    transform: scaleY(1.1);
  }
}

.reduced-motion .scroll-line {
  animation: none;
  opacity: 0.5;
}

/* ─── Section Shared ─────────────────────────────────────────────────────── */
.section {
  border-bottom: var(--rule);
}

.section__header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1.25rem var(--pad);
  border-bottom: var(--rule);
  opacity: 0;
  transform: translateX(-20px);
}

/* ─── About ──────────────────────────────────────────────────────────────── */
.about__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
}

@media (max-width: 700px) {
  .about__grid {
    grid-template-columns: 1fr;
  }
}

.about__bio {
  padding: clamp(2rem, 5vw, 4rem) var(--pad);
  border-right: var(--rule);
}

.about__text {
  font-size: clamp(0.9rem, 1.6vw, 1.05rem);
  line-height: 1.85;
  color: #ccc;
  font-weight: 300;
  max-width: 46ch;
}

.about__stats {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0;
}

.stat {
  padding: clamp(1.5rem, 3vw, 2.5rem) var(--pad);
  border-bottom: var(--rule);
  display: flex;
  align-items: baseline;
  gap: 0.4rem;
  flex-wrap: wrap;
}

.stat:last-child {
  border-bottom: none;
}

.stat__num {
  font-size: clamp(2.5rem, 6vw, 4rem);
  font-weight: 900;
  letter-spacing: -0.03em;
  color: var(--accent);
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.stat__unit {
  font-size: 1rem;
  color: var(--muted);
  font-weight: 300;
}

.stat__label {
  width: 100%;
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 0.58rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--muted);
  margin-top: 0.25rem;
}

/* ─── Skills ─────────────────────────────────────────────────────────────── */
.skills__list {
  padding: clamp(2rem, 4vw, 3.5rem) var(--pad);
  display: flex;
  flex-direction: column;
  gap: 0;
}

.skill-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 1.5rem;
  padding: 1.2rem 0;
  border-bottom: var(--rule);
  opacity: 0;
  transform: translateX(-24px);
}

.skill-row:last-child {
  border-bottom: none;
}

.skill-row__name {
  font-size: clamp(0.85rem, 1.6vw, 1rem);
  font-weight: 500;
  letter-spacing: 0.01em;
}

.skill-row__bar {
  width: clamp(80px, 20vw, 200px);
  height: 2px;
  background: var(--border);
  position: relative;
  overflow: hidden;
}

.skill-row__fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 0%;
  background: var(--accent);
  transition: width 1s ease;
}

.skill-row__pct {
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 0.65rem;
  color: var(--muted);
  letter-spacing: 0.05em;
  min-width: 3ch;
  text-align: right;
}

/* ─── Projects ───────────────────────────────────────────────────────────── */
.projects__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
}

@media (max-width: 900px) {
  .projects__grid {
    grid-template-columns: 1fr;
  }
}

.project-card {
  padding: clamp(2rem, 4vw, 3rem) var(--pad);
  border-right: var(--rule);
  display: flex;
  flex-direction: column;
  gap: 1rem;
  opacity: 0;
  transform: translateY(32px);
  transition: background 0.25s;
}

.project-card:hover {
  background: #111;
}

.project-card:last-child {
  border-right: none;
}

@media (max-width: 900px) {
  .project-card {
    border-right: none;
    border-bottom: var(--rule);
  }
  .project-card:last-child {
    border-bottom: none;
  }
}

.project-card__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.project-card__num {
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 0.6rem;
  color: var(--accent);
  letter-spacing: 0.1em;
}

.project-card__status {
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 0.55rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--muted);
  border: 1px solid var(--border);
  padding: 0.2em 0.5em;
}

.project-card__title {
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.project-card__desc {
