/* ── Demo 52: E-Learning Platform — Meridian ── */
/* Design: Fresh indigo/violet on white — educational, approachable, modern */
/* Fonts: Outfit (geometric sans) + JetBrains Mono (code/data) */

:root {
  --bg: #fafbff;
  --white: #ffffff;
  --surface: #f3f4ff;
  --border: #e4e6f8;
  --text: #111230;
  --muted: #6b6e8a;
  --indigo: #4f46e5;
  --indigo-light: #818cf8;
  --indigo-dim: rgba(79, 70, 229, 0.08);
  --violet: #7c3aed;
  --green: #059669;
  --amber: #d97706;
  --red: #dc2626;
}

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: "Outfit", -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  -webkit-font-smoothing: antialiased;
  line-height: 1.6;
  overflow-x: hidden;
}

/* ── Section tag ── */
.section-tag {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--indigo);
  margin-bottom: 0.75rem;
}

/* ── Buttons ── */
.btn-primary {
  display: inline-block;
  padding: 0.8rem 1.75rem;
  background: var(--indigo);
  color: white;
  font-family: "Outfit", sans-serif;
  font-size: 0.88rem;
  font-weight: 600;
  border-radius: 6px;
  text-decoration: none;
  transition: background 0.2s, transform 0.2s, box-shadow 0.2s;
  box-shadow: 0 2px 12px rgba(79, 70, 229, 0.3);
}

.btn-primary:hover {
  background: var(--violet);
  transform: translateY(-2px);
  box-shadow: 0 4px 20px rgba(79, 70, 229, 0.4);
}

.btn-primary--lg {
  padding: 1rem 2.25rem;
  font-size: 1rem;
}

.btn-text {
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
}

.btn-text:hover {
  color: var(--text);
}

.btn-ghost {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--indigo);
  text-decoration: none;
  transition: gap 0.2s;
}

.btn-ghost:hover {
  text-decoration: underline;
}

.btn-outline-dark {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text);
  font-size: 0.88rem;
  font-weight: 500;
  border-radius: 6px;
  text-decoration: none;
  transition: border-color 0.2s, background 0.2s;
}

.btn-outline-dark:hover {
  border-color: var(--indigo);
  background: var(--indigo-dim);
}

/* ── Nav ── */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 3rem;
  background: rgba(250, 251, 255, 0.9);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  text-decoration: none;
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--text);
}

.logo-mark {
  width: 24px;
  height: 24px;
  background: var(--indigo);
  border-radius: 6px;
  position: relative;
}

.logo-mark::after {
  content: "";
  position: absolute;
  top: 4px;
  left: 4px;
  width: 16px;
  height: 16px;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 3px;
}

.nav-links {
  display: flex;
  gap: 2rem;
  list-style: none;
}

.nav-links a {
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--muted);
  text-decoration: none;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--text);
}

.nav-ctas {
  display: flex;
  align-items: center;
  gap: 1rem;
}

/* ── Hero ── */
.hero {
  padding: 7rem 3rem 5rem;
  background: var(--bg);
  min-height: 100vh;
  display: flex;
  align-items: center;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 0.9rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 100px;
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--muted);
  margin-bottom: 1.5rem;
}

.hb-dot {
  width: 7px;
  height: 7px;
  background: var(--green);
  border-radius: 50%;
  animation: pulse-green 2s ease-in-out infinite;
}

@keyframes pulse-green {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

.hero-h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin-bottom: 1.25rem;
}

.h1-highlight {
  background: linear-gradient(90deg, var(--indigo), var(--violet));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-p {
  font-size: 1.05rem;
  color: var(--muted);
  line-height: 1.8;
  margin-bottom: 2rem;
  max-width: 460px;
}

.hero-actions {
  display: flex;
  gap: 1rem;
  align-items: center;
  margin-bottom: 3rem;
}

.hero-stats {
  display: flex;
  gap: 2rem;
  align-items: center;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
}

.hs-item {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.hs-num {
  font-family: "JetBrains Mono", monospace;
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text);
  line-height: 1;
}

.hs-label {
  font-size: 0.72rem;
  color: var(--muted);
  font-weight: 500;
}

.hs-div {
  width: 1px;
  height: 36px;
  background: var(--border);
}

/* ── Progress card (hero visual) ── */
.hero-visual {
  position: relative;
}

.progress-card {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 8px 40px rgba(79, 70, 229, 0.1);
  position: relative;
  z-index: 2;
}

.pc-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.pc-avatar {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--indigo), var(--violet));
  flex-shrink: 0;
}

.pc-meta {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.pc-meta strong {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--text);
}

.pc-meta span {
  font-size: 0.72rem;
  color: var(--muted);
}

.pc-pct {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--indigo);
}

.pc-progress {
  height: 6px;
  background: var(--surface);
  border-radius: 3px;
  overflow: hidden;
  margin-bottom: 1.25rem;
