}

// ── About section reveal ──────────────────────────────────────────────────────
if (!reduced) {
  gsap.set(".ab-img--main", { opacity: 0, scale: 1.03 });
  gsap.to(".ab-img--main", {
    opacity: 1,
    scale: 1,
    duration: 1.2,
