snippets.css:
/* ═══════════════════════════════════════════════════════════════════
   35-gamedev-portfolio — styles.css
   Retro pixel art aesthetic, CRT scanlines, HUD elements
═══════════════════════════════════════════════════════════════════ */

/* ── Google Font: Press Start 2P ──────────────────────────────── */
@import url("https://fonts.googleapis.com/css2?family=Press+Start+2P&display=swap");

/* ── Custom Properties ─────────────────────────────────────────── */
:root {
  --bg: #0f0f1a;
  --text: #e8e8f0;
  --accent: #ffdd57;
  --accent-2: #ff6b9d;
  --accent-3: #4ecdc4;
  --accent-4: #ff4757;
  --muted: #4a4a6a;
  --border: #1e1e3a;
  --panel: #141428;
  --panel-2: #0c0c1e;
  --scanline: rgba(0, 0, 0, 0.15);
  --pixel-font: "Press Start 2P", monospace;
  --hero-font: Impact, "Arial Black", "Haettenschweiler", sans-serif;
}

/* ── Reset & Base ──────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--pixel-font);
  font-size: 8px;
  line-height: 1.8;
  overflow-x: hidden;
}

/* ── CRT Scanlines ─────────────────────────────────────────────── */
body::after {
  content: "";
  position: fixed;
  inset: 0;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0px,
    transparent 2px,
    rgba(0, 0, 0, 0.15) 2px,
    rgba(0, 0, 0, 0.15) 4px
  );
  pointer-events: none;
  z-index: 9999;
  animation: crtFlicker 8s steps(1) infinite;
}

/* Subtle screen vignette */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  background: radial-gradient(ellipse at center, transparent 60%, rgba(0, 0, 0, 0.6) 100%);
  pointer-events: none;
  z-index: 9998;
}

@keyframes crtFlicker {
  0%,
  97%,
  100% {
    opacity: 1;
  }
  98% {
    opacity: 0.97;
  }
  99% {
    opacity: 0.99;
  }
}

/* ── Blink ─────────────────────────────────────────────────────── */
.blink {
  animation: blink 1s steps(1) infinite;
}
@keyframes blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

/* ── Loading Overlay ───────────────────────────────────────────── */
.loading-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.4s ease;
}
.loading-overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.loading-inner {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.loading-logo {
  font-family: var(--pixel-font);
  font-size: 18px;
  color: var(--accent);
  text-shadow: 3px 3px 0 rgba(255, 221, 87, 0.3);
  animation: pulse 1s ease-in-out infinite alternate;
}

.loading-text {
  font-family: var(--pixel-font);
  font-size: 10px;
  color: var(--text);
  letter-spacing: 0.2em;
}

.loading-dots::after {
  content: "";
  animation: dots 1.5s steps(4) infinite;
}
@keyframes dots {
  0% {
    content: "";
  }
  25% {
    content: ".";
  }
  50% {
    content: "..";
  }
  75% {
    content: "...";
  }
}

.loading-bar-wrap {
  width: 240px;
  height: 16px;
  border: 3px solid var(--accent);
  background: var(--panel-2);
  image-rendering: pixelated;
}
.loading-bar {
  height: 100%;
  width: 0%;
  background: var(--accent);
  transition: width 0.05s steps(1);
  box-shadow: 0 0 8px var(--accent);
}

.loading-pct {
  font-family: var(--pixel-font);
  font-size: 8px;
  color: var(--accent);
}

/* ── Pixel Nav ─────────────────────────────────────────────────── */
.pixel-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(15, 15, 26, 0.92);
  border-bottom: 2px solid var(--border);
  backdrop-filter: blur(4px);
  transform: translateY(-100%);
  transition: transform 0.3s steps(6);
}
.pixel-nav.visible {
  transform: translateY(0);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 24px;
  max-width: 1100px;
  margin: 0 auto;
}

.nav-logo {
  font-family: var(--pixel-font);
  font-size: 12px;
  color: var(--accent);
  text-shadow: 2px 2px 0 rgba(255, 221, 87, 0.4);
  letter-spacing: 0.1em;
}

.nav-links {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
}

.nav-link {
  font-family: var(--pixel-font);
  font-size: 7px;
  color: var(--muted);
  text-decoration: none;
  letter-spacing: 0.1em;
  transition: color 0.1s, text-shadow 0.1s;
  padding: 4px 6px;
}
.nav-link:hover,
.nav-link.active {
  color: var(--accent);
  text-shadow: 0 0 8px var(--accent);
}

/* ── Hero ──────────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.hero-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

/* HUD corners */
.hud-corner {
  position: absolute;
  font-family: var(--pixel-font);
  font-size: 7px;
  z-index: 10;
}
.hud-tl {
  top: 80px;
  left: 24px;
}
.hud-tr {
  top: 80px;
  right: 24px;
  text-align: right;
}

.hud-hp,
.hud-mp {
  margin-bottom: 10px;
}
.hud-label {
  color: var(--accent-4);
  display: inline-block;
  width: 24px;
  margin-right: 6px;
}
.hud-bar {
  display: inline-block;
  width: 100px;
  height: 8px;
  background: var(--border);
  border: 1px solid var(--muted);
  vertical-align: middle;
  margin-right: 6px;
}
.hud-bar-fill {
  height: 100%;
  animation: hudPulse 2s ease-in-out infinite alternate;
}
.hud-bar-hp {
  width: 100%;
  background: var(--accent-4);
}
.hud-bar-mp {
  width: 88%;
  background: var(--accent-3);
}

@keyframes hudPulse {
  from {
    filter: brightness(1);
  }
  to {
    filter: brightness(1.3);
  }
}

.hud-val {
  color: var(--text);
}

.hud-xp-label {
  color: var(--accent);
  margin-bottom: 4px;
}
.hud-xp-bar-wrap {
  width: 120px;
  height: 8px;
  background: var(--border);
  border: 1px solid var(--muted);
  margin-bottom: 4px;
}
.hud-xp-bar {
  width: 73%;
  height: 100%;
  background: var(--accent);
  box-shadow: 0 0 6px var(--accent);
}
.hud-level {
  color: var(--accent);
}
.hud-level-num {
  color: var(--accent-2);
}

/* Hero content */
.hero-content {
  position: relative;
  z-index: 10;
  text-align: center;
  padding: 24px;
}

.hero-eyebrow {
  font-family: var(--pixel-font);
  font-size: 9px;
  color: var(--accent-3);
  letter-spacing: 0.3em;
  margin-bottom: 24px;
  text-shadow: 0 0 12px var(--accent-3);
}

.hero-name {
  font-family: var(--hero-font);
  font-size: clamp(3.5rem, 10vw, 8rem);
  font-weight: 900;
  font-style: italic;
  letter-spacing: 0.05em;
  color: var(--accent);
  /* Chunky pixel shadow simulation */
  text-shadow: 3px 3px 0 #b89c00, 6px 6px 0 rgba(184, 156, 0, 0.5), 0 0 40px rgba(255, 221, 87, 0.3);
  line-height: 0.95;
  margin-bottom: 20px;
  text-transform: uppercase;
}

.hero-subtitle {
  font-family: var(--pixel-font);
  font-size: 10px;
  color: var(--text);
  letter-spacing: 0.25em;
  margin-bottom: 28px;
  opacity: 0.85;
}

.hero-tags {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 60px;
}

.hero-tag {
  font-family: var(--pixel-font);
  font-size: 7px;
  padding: 6px 10px;
  border: 2px solid var(--accent-2);
  color: var(--accent-2);
  letter-spacing: 0.1em;
  background: rgba(255, 107, 157, 0.08);
}

.hero-scroll-cue {
  font-family: var(--pixel-font);
  font-size: 8px;
  color: var(--accent);
  letter-spacing: 0.1em;
}

/* Score display */
.hud-score {
  position: absolute;
  bottom: 24px;
  right: 24px;
  font-family: var(--pixel-font);
  font-size: 8px;
  text-align: right;
  z-index: 10;
}
.score-label {
  color: var(--muted);
  margin-bottom: 4px;
}
.score-val {
  font-size: 14px;
  color: var(--accent);
  text-shadow: 0 0 10px var(--accent);
  letter-spacing: 0.1em;
}

/* ── Sections (shared) ─────────────────────────────────────────── */
.section {
  padding: 100px 24px;
  position: relative;
}

.section-inner {
  max-width: 960px;
  margin: 0 auto;
}

.section-header-pixel {
  display: flex;
  align-items: baseline;
  gap: 16px;
  margin-bottom: 56px;
  padding-bottom: 20px;
  border-bottom: 3px solid var(--border);
  flex-wrap: wrap;
}

.section-num {
  font-family: var(--pixel-font);
  font-size: 9px;
  color: var(--accent-2);
}

.section-title {
  font-family: var(--pixel-font);
  font-size: clamp(14px, 3vw, 20px);
  color: var(--text);
  text-shadow: 2px 2px 0 rgba(255, 255, 255, 0.1);
}

.section-deco {
  font-family: var(--pixel-font);
  font-size: 7px;
  color: var(--muted);
  margin-left: auto;
}

/* ── Stats Section ─────────────────────────────────────────────── */
.stats-section {
  background: var(--panel-2);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
  margin-bottom: 48px;
}

.stat-card {
  background: var(--panel);
  border: 2px solid var(--border);
  padding: 20px;
  transition: border-color 0.2s, transform 0.1s steps(2);
}
.stat-card:hover {
  border-color: var(--accent);
  transform: translate(-2px, -2px);
}

.stat-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.stat-abbr {
  font-family: var(--pixel-font);
  font-size: 10px;
  color: var(--accent);
  min-width: 36px;
  text-shadow: 0 0 8px rgba(255, 221, 87, 0.5);
}

.stat-name {
  font-family: var(--pixel-font);
  font-size: 7px;
  color: var(--text);
  flex: 1;
  letter-spacing: 0.05em;
}

.stat-num {
  font-family: var(--pixel-font);
  font-size: 10px;
  color: var(--accent-3);
  min-width: 28px;
  text-align: right;
}

.stat-bar-wrap {
  width: 100%;
  height: 12px;
  background: var(--border);
  border: 2px solid var(--muted);
  margin-bottom: 10px;
  position: relative;
  overflow: hidden;
}

.stat-bar {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, var(--accent-3), var(--accent));
  transition: none;
  position: relative;
}
/* Pixel block pattern on bar fill */
.stat-bar::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    90deg,
    transparent 0px,
    transparent 10px,
    rgba(0, 0, 0, 0.2) 10px,
    rgba(0, 0, 0, 0.2) 12px
  );
}

.stat-desc {
  font-family: var(--pixel-font);
  font-size: 6px;
  color: var(--muted);
  line-height: 1.9;
}

/* XP progress bar */
.xp-progress {
  background: var(--panel);
  border: 2px solid var(--border);
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
}
.xp-label {
  font-family: var(--pixel-font);
  font-size: 7px;
  color: var(--accent);
  min-width: 180px;
}
.xp-bar-outer {
  flex: 1;
  min-width: 200px;
  height: 16px;
  background: var(--border);
  border: 2px solid var(--muted);
  overflow: hidden;
}
.xp-bar-inner {
  height: 100%;
  width: 0%;
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent);
  position: relative;
}
.xp-bar-inner::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    90deg,
    transparent 0px,
    transparent 14px,
    rgba(0, 0, 0, 0.25) 14px,
    rgba(0, 0, 0, 0.25) 16px
  );
}
.xp-pct {
  font-family: var(--pixel-font);
  font-size: 10px;
  color: var(--accent);
  min-width: 48px;
  text-align: right;
}

/* ── Games Section ─────────────────────────────────────────────── */
.games-section {
  background: var(--bg);
}

.games-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 32px;
}

.game-card {
  display: flex;
  flex-direction: column;
  border: 3px solid var(--border);
  background: var(--panel);
  cursor: pointer;
  transition: transform 0.1s steps(2), border-color 0.15s;
  outline: none;
}
.game-card:hover,
.game-card:focus {
  transform: translate(-4px, -4px);
  border-color: var(--cart-color, var(--accent));
}
.game-card:hover .cartridge-label,
.game-card:focus .cartridge-label {
  filter: brightness(1.1);
}

/* Cartridge label */
.cartridge-label {
  position: relative;
  padding: 0;
  overflow: hidden;
  height: 160px;
  background: var(--cart-color, var(--accent));
  transition: filter 0.15s;
}

.cart-stripe {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 16px;
  background: var(--cart-color2, #b89c00);
  border-bottom: 3px solid rgba(0, 0, 0, 0.3);
}

.cart-body {
  position: absolute;
  inset: 16px 0 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 12px;
}

.cart-genre {
  font-family: var(--pixel-font);
  font-size: 7px;
  color: rgba(0, 0, 0, 0.7);
  letter-spacing: 0.1em;
  margin-bottom: 10px;
}

.cart-title {
  font-family: var(--pixel-font);
  font-size: 16px;
  color: rgba(0, 0, 0, 0.85);
  text-shadow: 2px 2px 0 rgba(255, 255, 255, 0.2);
  line-height: 1.4;
  margin-bottom: 6px;
}

.cart-sub {
  font-family: var(--pixel-font);
  font-size: 6px;
  color: rgba(0, 0, 0, 0.6);
  letter-spacing: 0.05em;
}

.cart-platforms {
  font-size: 16px;
  margin-top: 10px;
}

.cart-bottom {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 24px;
  background: var(--cart-color2, #b89c00);
  border-top: 3px solid rgba(0, 0, 0, 0.3);
  /* Cart connector notches */
  clip-path: polygon(0 0, 30% 0, 35% 100%, 65% 100%, 70% 0, 100% 0, 100% 100%, 0 100%);
}

.game-info {
  padding: 16px;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.game-meta-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.game-year,
.game-engine {
  font-family: var(--pixel-font);
  font-size: 6px;
  color: var(--muted);
}
.game-engine::before {
  content: "| ";
  color: var(--border);
}
.game-rating {
  font-size: 10px;
  margin-left: auto;
  color: var(--accent);
}

.game-desc {
  font-family: var(--pixel-font);
  font-size: 6px;
  color: var(--text);
  line-height: 2;
  opacity: 0.8;
}

.game-tags {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-top: auto;
}
.gtag {
  font-family: var(--pixel-font);
  font-size: 5px;
  padding: 4px 8px;
  border: 1px solid var(--border);
  color: var(--muted);
  background: var(--panel-2);
  letter-spacing: 0.05em;
}

/* ── Inventory Section ─────────────────────────────────────────── */
.tech-section {
  background: var(--panel-2);
}

.inventory-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 16px;
}

.inv-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  background: var(--panel);
  border: 2px solid var(--border);
  cursor: pointer;
  position: relative;
  outline: none;
  transition: transform 0.1s steps(2), border-color 0.15s;
}

.inv-item:hover,
.inv-item:focus {
  transform: translate(-2px, -2px);
}
.inv-item[data-rarity="legendary"] {
  border-color: rgba(255, 221, 87, 0.4);
}
.inv-item[data-rarity="rare"] {
  border-color: rgba(78, 205, 196, 0.4);
}
.inv-item[data-rarity="common"] {
  border-color: var(--border);
}

/* Inventory icons using CSS geometry */
.inv-icon {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  position: relative;
  image-rendering: pixelated;
}

/* C++ — crossed pillars */
.inv-icon--cpp {
  background: var(--accent-4);
  clip-path: polygon(20% 0%, 80% 0%, 100% 50%, 80% 100%, 20% 100%, 0% 50%);
}
.inv-icon--cpp::after {
  content: "++";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--pixel-font);
  font-size: 8px;
  color: white;
  font-weight: bold;
}

/* Unity — circle */
.inv-icon--unity {
  background: var(--text);
  border-radius: 50%;
}
.inv-icon--unity::after {
  content: "U";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--pixel-font);
  font-size: 10px;
  color: var(--bg);
  font-weight: bold;
}

/* Unreal — diamond */
.inv-icon--unreal {
  background: var(--accent-2);
  clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);
}
.inv-icon--unreal::after {
  content: "UE";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--pixel-font);
  font-size: 6px;
  color: white;
}

/* GLSL — triangle */
.inv-icon--glsl {
  background: var(--accent-3);
  clip-path: polygon(50% 0%, 100% 100%, 0% 100%);
}

/* Godot — robot head shape */
.inv-icon--godot {
  background: var(--accent);
  clip-path: polygon(10% 30%, 50% 0%, 90% 30%, 90% 70%, 50% 100%, 10% 70%);
}
.inv-icon--godot::after {
  content: "G";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--pixel-font);
  font-size: 10px;
  color: var(--bg);
}

/* Vulkan — flame-like */
.inv-icon--vulkan {
  background: var(--accent-4);
  clip-path: polygon(
    50% 0%,
    80% 25%,
    100% 10%,
    80% 60%,
    100% 60%,
    50% 100%,
    0% 60%,
    20% 60%,
    0% 10%,
    20% 25%
  );
}

/* Python — square */
.inv-icon--python {
  background: var(--muted);
  border: 3px solid var(--border);
}
.inv-icon--python::after {
  content: "PY";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--pixel-font);
  font-size: 7px;
  color: var(--accent-3);
}

/* Blender — rounded star */
.inv-icon--blender {
  background: var(--accent);
  clip-path: polygon(
    50% 0%,
    61% 35%,
    98% 35%,
    68% 57%,
    79% 91%,
    50% 70%,
    21% 91%,
    32% 57%,
    2% 35%,
    39% 35%
  );
}
.inv-icon--blender::after {
  content: "";
  position: absolute;
  inset: 35%;
  background: var(--bg);
  border-radius: 50%;
}

/* Git — fork */
.inv-icon--git {
  background: var(--accent-4);
  border-radius: 4px;
}
.inv-icon--git::after {
  content: "GIT";
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--pixel-font);
  font-size: 6px;
  color: white;
}

.inv-details {
  flex: 1;
  min-width: 0;
}

.inv-name {
  font-family: var(--pixel-font);
  font-size: 8px;
  color: var(--text);
  margin-bottom: 6px;
}

.inv-rarity {
  font-family: var(--pixel-font);
  font-size: 6px;
  letter-spacing: 0.05em;
}
.rarity-legendary {
  color: var(--accent);
}
.rarity-rare {
  color: var(--accent-3);
}
.rarity-common {
  color: var(--muted);
}

/* Sparkle icon */
.inv-sparkle {
  font-size: 16px;
  color: var(--accent);
  opacity: 0;
  transition: opacity 0.15s;
}
.inv-item:hover .inv-sparkle,
.inv-item:focus .inv-sparkle {
  opacity: 1;
  animation: sparkle 0.6s steps(2) infinite;
}
@keyframes sparkle {
  0%,
  100% {
    transform: scale(1) rotate(0deg);
    opacity: 1;
  }
  50% {
    transform: scale(1.3) rotate(20deg);
    opacity: 0.7;
  }
}

/* Legendary glow on hover */
.inv-item[data-rarity="legendary"]:hover,
.inv-item[data-rarity="legendary"]:focus {
  box-shadow: 0 0 12px rgba(255, 221, 87, 0.25), inset 0 0 12px rgba(255, 221, 87, 0.05);
}
.inv-item[data-rarity="rare"]:hover,
.inv-item[data-rarity="rare"]:focus {
  box-shadow: 0 0 12px rgba(78, 205, 196, 0.25), inset 0 0 12px rgba(78, 205, 196, 0.05);
}

/* ── Contact Section ───────────────────────────────────────────── */
.contact-section {
  background: var(--bg);
}

.contact-screen {
  max-width: 600px;
  margin: 0 auto;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 32px;
}

.contact-title {
  font-family: var(--pixel-font);
  font-size: clamp(18px, 4vw, 28px);
  color: var(--accent-4);
  text-shadow: 3px 3px 0 rgba(255, 71, 87, 0.5);
  letter-spacing: 0.15em;
}

.contact-sub {
  font-family: var(--pixel-font);
  font-size: clamp(12px, 2.5vw, 18px);
  color: var(--accent-3);
  letter-spacing: 0.2em;
  text-shadow: 2px 2px 0 rgba(78, 205, 196, 0.4);
  margin-top: -20px;
}

.contact-prompt {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.contact-question {
  font-family: var(--pixel-font);
  font-size: 10px;
  color: var(--text);
  letter-spacing: 0.2em;
}

.contact-buttons {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
  justify-content: center;
}

/* Pixel buttons */
.pixel-btn {
  font-family: var(--pixel-font);
  font-size: 8px;
  padding: 14px 20px;
  border: 3px solid;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  letter-spacing: 0.1em;
  background: transparent;
  transition: transform 0.1s steps(2), box-shadow 0.1s;
  position: relative;
}
.pixel-btn::after {
  content: "";
  position: absolute;
  right: -6px;
  bottom: -6px;
  width: 100%;
  height: 100%;
  border: 3px solid;
  border-color: inherit;
  opacity: 0.3;
  z-index: -1;
  transition: right 0.1s steps(2), bottom 0.1s steps(2);
}
.pixel-btn:hover {
  transform: translate(-2px, -2px);
}
.pixel-btn:hover::after {
  right: -4px;
  bottom: -4px;
}
.pixel-btn:active {
  transform: translate(0, 0);
}
.pixel-btn:active::after {
  right: -6px;
  bottom: -6px;
}

.pixel-btn--yes {
  color: var(--accent-3);
  border-color: var(--accent-3);
}
.pixel-btn--yes:hover {
  background: rgba(78, 205, 196, 0.1);
  box-shadow: 0 0 16px rgba(78, 205, 196, 0.25);
}

.pixel-btn--no {
  color: var(--accent-4);
  border-color: var(--accent-4);
}
.pixel-btn--no:hover {
  background: rgba(255, 71, 87, 0.1);
  box-shadow: 0 0 16px rgba(255, 71, 87, 0.25);
}

.btn-cursor {
  animation: blink 0.8s steps(1) infinite;
}

/* Contact links */
.contact-links {
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: 100%;
  max-width: 360px;
}

.contact-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border: 2px solid var(--border);
  color: var(--text);
  text-decoration: none;
  transition: border-color 0.15s, transform 0.1s steps(2);
}
.contact-link:hover {
  border-color: var(--accent);
  transform: translate(-2px, -2px);
}

.contact-link-icon {
  color: var(--accent);
  font-size: 10px;
}
.contact-link-label {
  font-family: var(--pixel-font);
  font-size: 7px;
  color: var(--muted);
  min-width: 80px;
}
.contact-link-val {
  font-family: var(--pixel-font);
  font-size: 7px;
  color: var(--accent-3);
}

/* Email CTA */
.contact-email {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
.contact-email-label {
  font-family: var(--pixel-font);
  font-size: 7px;
  color: var(--muted);
  letter-spacing: 0.1em;
}
.contact-email-addr {
  font-family: var(--pixel-font);
  font-size: 9px;
  color: var(--accent);
  text-decoration: none;
  text-shadow: 0 0 10px rgba(255, 221, 87, 0.5);
  letter-spacing: 0.05em;
}

/* Credits */
.credits {
  border-top: 2px solid var(--border);
  padding-top: 24px;
  width: 100%;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.credits-line {
  font-family: var(--pixel-font);
  font-size: 6px;
  color: var(--muted);
  letter-spacing: 0.1em;
}
.credits-line.muted {
  color: var(--border);
}

/* ── View Transition overlay ───────────────────────────────────── */
.vt-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 5000;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.15s steps(3);
}
.vt-overlay.active {
  opacity: 1;
}

.vt-text {
  font-family: var(--pixel-font);
  font-size: 14px;
  color: var(--accent);
  letter-spacing: 0.2em;
  text-shadow: 0 0 16px rgba(255, 221, 87, 0.6);
}

/* ── View Transition API ───────────────────────────────────────── */
@keyframes vt-slide-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes vt-slide-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
::view-transition-old(root) {
  animation: vt-slide-out 0.2s steps(4) both;
}
::view-transition-new(root) {
  animation: vt-slide-in 0.2s steps(4) 0.2s both;
}

/* ── Pulse animation ───────────────────────────────────────────── */
@keyframes pulse {
  from {
    opacity: 0.7;
    transform: scale(0.98);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* ── Reduced motion overrides ──────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .blink {
    animation: none;
  }
  body::after {
    animation: none;
  }
  .pixel-btn {
    transition: none;
  }
  .game-card,
  .inv-item,
  .stat-card {
    transition: none;
  }
}

/* ── Responsive ────────────────────────────────────────────────── */
@media (max-width: 600px) {
  .hud-corner {
    display: none;
  }
  .hud-score {
    display: none;
  }
  .nav-links {
    gap: 10px;
  }
  .nav-link {
    font-size: 6px;
  }
  .section {
    padding: 64px 16px;
  }
  .section-title {
    font-size: 11px;
  }
  .hero-eyebrow {
    font-size: 7px;
  }
  .contact-title {
    font-size: 14px;
  }
  .contact-sub {
    font-size: 11px;
  }
  .games-grid {
    grid-template-columns: 1fr;
  }
  .stats-grid {
    grid-template-columns: 1fr;
  }
  .inventory-grid {
    grid-template-columns: 1fr;
  }
}

