  inset: 0 0 auto 0;
  z-index: var(--z-ui, 40);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.7rem 1rem;
  background: rgba(5, 9, 19, 0.66);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.13);
}

.topbar a {
  color: var(--accent);
  text-decoration: none;
  font-weight: 700;
}

.controls {
  display: flex;
  gap: 0.6rem;
  align-items: center;
}

.hint {
  color: var(--muted);
  font-size: 0.84rem;
}

.toggle {
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.07);
  color: var(--text);
  padding: 0.42rem 0.78rem;
  cursor: pointer;
}

.progress-wrap {
  position: fixed;
  top: 53px;
  left: 0;
  right: 0;
  height: 2px;
  z-index: var(--z-ui, 40);
  background: rgba(255, 255, 255, 0.08);
}

.progress-bar {
  display: block;
  width: 100%;
  height: 100%;
  transform-origin: left center;
  transform: scaleX(0);
  background: linear-gradient(90deg, #72dcff, #ce7eff);
}

main {
  padding-top: 3.4rem;
}

.panel {
  width: min(1080px, 92%);
  min-height: 92vh;
  margin: 0 auto;
  border-bottom: 1px solid var(--line);
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 1rem;
  align-items: center;
  position: relative;
}

.content {
  display: grid;
  gap: 0.8rem;
}

.label {
  margin: 0;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-size: 0.8rem;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: clamp(2.2rem, 7.5vw, 4.8rem);
  line-height: 0.95;
}

h2 {
  font-size: clamp(1.8rem, 5.3vw, 3.4rem);
}

p {
