.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
}

.chips span {
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 999px;
  padding: 0.25rem 0.62rem;
  background: rgba(255, 255, 255, 0.05);
  font-size: 0.83rem;
  color: #e4ecfa;
}

.visual {
  height: min(540px, 60vh);
  position: relative;
}

.orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(6px);
  opacity: 0.58;
}

.orb-a {
  width: 46%;
  aspect-ratio: 1;
  top: 8%;
  left: 4%;
  background: rgba(103, 196, 255, 0.55);
}
.orb-b {
  width: 30%;
  aspect-ratio: 1;
  top: 52%;
  left: 22%;
  background: rgba(241, 219, 167, 0.52);
}
.orb-c {
  width: 40%;
  aspect-ratio: 1;
  top: 18%;
  right: 2%;
  background: rgba(196, 108, 255, 0.5);
}
.orb-d {
  width: 28%;
  aspect-ratio: 1;
  bottom: 10%;
  right: 18%;
  background: rgba(255, 82, 217, 0.44);
}

.metrics {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.6rem;
}

.metrics li {
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 12px;
  padding: 0.72rem;
  display: grid;
  gap: 0.2rem;
  background: rgba(255, 255, 255, 0.03);
}

.metrics li strong {
  font-size: 0.95rem;
}

.metrics li span {
  color: var(--muted);
  font-size: 0.86rem;
}

.stage {
  grid-template-columns: 1fr;
  align-content: center;
  gap: 1.3rem;
}

.stage-cards {
  height: 45vh;
  position: relative;
}

.stage-card {
  position: absolute;
  inset: 0;
  margin: auto;
  width: min(84vw, 700px);
  height: min(34vh, 250px);
  border-radius: 16px;
  display: grid;
  place-content: center;
  font-size: clamp(1.4rem, 3.8vw, 2.4rem);
  font-weight: 800;
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.card-one {
  background: linear-gradient(140deg, #223c5e, #2d6db4);
}
.card-two {
  background: linear-gradient(140deg, #3f2a61, #8d45c9);
}
.card-three {
  background: linear-gradient(140deg, #2f3d62, #6c7fca);
}

.note {
  color: #dae6f8;
  font-weight: 600;
}

body.no-motion .stage-cards {
  height: auto;
  display: grid;
  gap: 0.7rem;
}

body.no-motion .stage-card {
  position: relative;
  width: 100%;
  height: 130px;
}

@media (max-width: 900px) {
  .panel {
    grid-template-columns: 1fr;
    min-height: 86vh;
    padding-top: 0.6rem;
    padding-bottom: 0.8rem;
  }

  .visual {
    height: 32vh;
  }

  .stage-cards {
    height: 42vh;
  }
}

