heroTl
  .to(heroLabel, { opacity: 1, y: 0, duration: dur(0.6), ease: "expo.out" })
  .to(
    heroSplit.chars,
    {
      opacity: 1,
      y: 0,
      rotateX: 0,
      duration: dur(0.6),
      ease: "back.out(1.4)",
      stagger: { each: 0.03, from: "start" },
    },
    "-=0.3"
  )
  .to(heroSub, { opacity: 1, y: 0, duration: dur(0.7), ease: "expo.out" }, "-=0.4");

