/* ── Reset & Base ──────────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #0a0a0a;
  --surface: #131210;
  --text: #f2ede8;
  --muted: #8a8078;
  --rust: #c4622d;
  --amber: #d4843a;
  --border: #2a2520;
  --font-display: "Libre Baskerville", Georgia, serif;
  --font-mono: "IBM Plex Mono", "Courier New", monospace;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-display);
  line-height: 1.6;
  overflow-x: hidden;
}

/* ── Grain Canvas ──────────────────────────────────────────────────────────── */
#grain-canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 9998;
  opacity: 0.04;
  mix-blend-mode: overlay;
}

/* ── Nav ───────────────────────────────────────────────────────────────────── */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 48px;
  background: rgba(10, 10, 10, 0.9);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.nav-logo {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.2em;
  color: var(--text);
  font-weight: 500;
}

.nav-links {
  display: flex;
  gap: 36px;
  list-style: none;
}

.nav-links a {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--muted);
  text-decoration: none;
  text-transform: uppercase;
  transition: color 0.2s;
}
.nav-links a:hover {
  color: var(--text);
}

.nav-watch {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--rust);
  text-decoration: none;
  border: 1px solid var(--rust);
  padding: 7px 18px;
  transition: background 0.2s, color 0.2s;
}
.nav-watch:hover {
  background: var(--rust);
  color: var(--bg);
}

/* ── Hero ──────────────────────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 120px 48px 80px;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
}

.hero-inner {
  max-width: 900px;
}

.hero-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 32px;
}

.hero-label {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.2em;
  color: var(--muted);
  text-transform: uppercase;
}

.hero-director {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--rust);
  text-transform: uppercase;
}

.hero-h1 {
  font-size: clamp(4rem, 12vw, 10rem);
  font-weight: 700;
  line-height: 0.95;
  letter-spacing: -0.02em;
  margin-bottom: 32px;
  overflow: hidden;
}

.h1-word {
  display: block;
  clip-path: inset(0 0 0 0);
}

.h1-word--accent {
  color: var(--rust);
  font-style: italic;
}

.hero-details {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}

.hd-item {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  color: var(--muted);
}

.hd-sep {
  color: var(--border);
}

.hero-tagline {
  font-style: italic;
  font-size: 1.125rem;
  color: var(--muted);
  letter-spacing: 0.02em;
}

.hero-scroll {
  position: absolute;
  bottom: 40px;
  left: 48px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 12px;
}

.hero-scroll span {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.18em;
  color: var(--muted);
  text-transform: uppercase;
}

.scroll-line {
  width: 1px;
  height: 48px;
  background: var(--muted);
  transform-origin: top;
  animation: scroll-grow 1.5s ease-in-out infinite alternate;
}

@keyframes scroll-grow {
  from {
    transform: scaleY(0.3);
    opacity: 0.4;
  }
  to {
    transform: scaleY(1);
    opacity: 1;
  }
}

/* ── Section Labels ────────────────────────────────────────────────────────── */
.section-num {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.2em;
  color: var(--rust);
}

.section-title {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.2em;
  color: var(--muted);
  text-transform: uppercase;
  margin-left: 12px;
}

/* ── Synopsis ──────────────────────────────────────────────────────────────── */
.synopsis-section {
  padding: 120px 48px;
  border-bottom: 1px solid var(--border);
}

.synopsis-inner {
  max-width: 860px;
  margin: 0 auto;
}

.synopsis-label {
  display: flex;
  align-items: center;
  margin-bottom: 64px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.synopsis-quote {
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  font-style: italic;
  line-height: 1.3;
  color: var(--text);
  border-left: 3px solid var(--rust);
  padding-left: 32px;
  margin-bottom: 48px;
}

.synopsis-text p {
  font-size: 1rem;
  line-height: 1.8;
  color: var(--muted);
  max-width: 640px;
}
.synopsis-text p + p {
  margin-top: 20px;
}

/* ── Chapters ──────────────────────────────────────────────────────────────── */
.chapters-section {
  padding: 120px 48px;
  border-bottom: 1px solid var(--border);
}

.chapters-header {
  display: flex;
  align-items: center;
  margin-bottom: 64px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.chapter-item {
  display: grid;
  grid-template-columns: 80px 1fr;
  gap: 0 32px;
  padding: 40px 0;
  position: relative;
}

.ch-num {
  font-size: 3rem;
  font-weight: 700;
  font-style: italic;
  color: var(--border);
  line-height: 1;
  padding-top: 4px;
}

.ch-content {
  padding-bottom: 32px;
}

.ch-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 6px;
}

.ch-runtime {
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.12em;
  color: var(--rust);
  display: block;
  margin-bottom: 16px;
}

.ch-desc {
  font-size: 0.9rem;
  line-height: 1.7;
  color: var(--muted);
  max-width: 580px;
}

.ch-rule {
  grid-column: 1 / -1;
  height: 1px;
  background: var(--border);
}

/* ── Film Stills ───────────────────────────────────────────────────────────── */
.stills-section {
  padding: 120px 48px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}

.stills-header {
  display: flex;
  align-items: center;
  margin-bottom: 64px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.stills-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: 220px 220px;
  gap: 12px;
}

.still-item {
  position: relative;
  overflow: hidden;
}

.still-item--tall {
  grid-row: span 2;
}
.still-item--wide {
  grid-column: span 2;
}

.si-frame {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
}

/* Film still color treatments */
.si-frame--1 {
  background: #2a1f15;
}
.si-frame--2 {
  background: #0d0d12;
}
.si-frame--3 {
  background: #141d1f;
}
.si-frame--4 {
  background: #1a160f;
}
.si-frame--5 {
  background: #0a0d0a;
}
.si-frame--6 {
  background: #12181e;
}

/* Film scratch marks via pseudo */
.si-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    90deg,
    transparent 0%,
    transparent 48%,
    rgba(255, 255, 255, 0.015) 48%,
    rgba(255, 255, 255, 0.015) 50%,
    transparent 50%
  );
}

.si-frame::after {
  content: "";
  position: absolute;
  top: 0;
  left: 8%;
  width: 1px;
  height: 100%;
  background: rgba(255, 255, 255, 0.04);
  box-shadow: 38px 0 0 rgba(255, 255, 255, 0.025), 72px 0 0 rgba(255, 255, 255, 0.015);
}

/* Vignette on frames */
.si-frame--1::before {
  box-shadow: inset 0 0 60px rgba(0, 0, 0, 0.7);
}

.still-item figcaption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 12px 16px;
  font-family: var(--font-mono);
  font-size: 0.6rem;
  letter-spacing: 0.12em;
  color: rgba(242, 237, 232, 0.5);
  background: linear-gradient(transparent, rgba(0, 0, 0, 0.7));
  text-transform: uppercase;
}

/* ── Credits ───────────────────────────────────────────────────────────────── */
.credits-section {
  padding: 120px 48px;
  border-bottom: 1px solid var(--border);
}

.credits-inner {
  max-width: 720px;
}

.credits-label {
  display: flex;
  align-items: center;
  margin-bottom: 64px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.credits-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.credit-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 20px 0;
  border-bottom: 1px solid var(--border);
}

.cr-role {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--muted);
  text-transform: uppercase;
  flex-shrink: 0;
  width: 200px;
}

.cr-name {
  font-size: 1.05rem;
  font-style: italic;
  color: var(--text);
  text-align: right;
}

/* ── Festivals ─────────────────────────────────────────────────────────────── */
.festivals-section {
  padding: 120px 48px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}

.festivals-inner {
  max-width: 1100px;
}

.festivals-label {
  display: flex;
  align-items: center;
  margin-bottom: 64px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--border);
}

.festivals-row {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
}

.festival-badge {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 28px 32px;
  border: 1px solid var(--border);
  flex: 1;
  min-width: 140px;
}

.festival-badge--winner {
  border-color: var(--rust);
}

.fb-name {
  font-family: var(--font-mono);
  font-size: 0.9rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  color: var(--text);
}

.fb-award {
  font-size: 0.75rem;
  font-style: italic;
  color: var(--muted);
  text-align: center;
}

.festival-badge--winner .fb-award {
  color: var(--rust);
}

.fb-year {
  font-family: var(--font-mono);
  font-size: 0.6rem;
  letter-spacing: 0.1em;
  color: var(--muted);
  margin-top: 4px;
}

/* ── Watch / CTA ───────────────────────────────────────────────────────────── */
.watch-section {
  padding: 120px 48px;
  border-bottom: 1px solid var(--border);
}

.watch-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  max-width: 1100px;
  align-items: start;
}

.watch-h2 {
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  line-height: 1.05;
  font-weight: 700;
  margin-bottom: 20px;
}

.watch-h2 em {
  font-style: italic;
  color: var(--rust);
}

.watch-text > p {
  font-size: 0.9rem;
  color: var(--muted);
  margin-bottom: 40px;
  font-family: var(--font-mono);
  letter-spacing: 0.04em;
}

.watch-btns {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.btn-film {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  padding: 14px 28px;
  background: var(--rust);
  color: var(--bg);
  transition: background 0.2s, color 0.2s;
  display: inline-block;
}
.btn-film:hover {
  background: var(--amber);
}

.btn-film--outline {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--border);
}
.btn-film--outline:hover {
  border-color: var(--rust);
  color: var(--rust);
  background: transparent;
}

/* Watch Terminal */
.watch-terminal {
  background: #0d0d0d;
  border: 1px solid var(--border);
  font-family: var(--font-mono);
}

.wt-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
}

.wt-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border);
  display: inline-block;
}

.wt-title {
  font-size: 0.65rem;
  letter-spacing: 0.1em;
  color: var(--muted);
  margin-left: 8px;
}

.wt-body {
  padding: 20px 20px 24px;
}

.wt-body p {
  font-size: 0.7rem;
  line-height: 2;
  color: var(--muted);
}

.wt-loc {
  color: var(--rust);
  margin-right: 8px;
  font-weight: 500;
}

.wt-stream {
  margin-top: 12px;
  border-top: 1px solid var(--border);
  padding-top: 12px;
}

.wt-live {
  color: #5fba47;
  margin-right: 6px;
  animation: blink 1.2s ease-in-out infinite;
}

@keyframes blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}

/* ── Footer ────────────────────────────────────────────────────────────────── */
.footer {
  padding: 32px 48px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--border);
  font-family: var(--font-mono);
  font-size: 0.65rem;
  letter-spacing: 0.08em;
  color: var(--muted);
}

/* ── Reduced motion ────────────────────────────────────────────────────────── */
.reduced-motion .scroll-line {
  animation: none;
}

