    )
    .to(".hero-details", { opacity: 1, duration: 0.6 }, "-=0.4")
    .to(".hero-tagline", { opacity: 1, y: 0, duration: 0.6 }, "-=0.3")
    .to(".hero-scroll", { opacity: 1, duration: 0.6 }, "-=0.2");
