.artist-row:hover {
  background: var(--off-white);
  padding-left: 0.5rem;
}
.ar-num {
  font-family: "DM Mono", monospace;
  font-size: 0.68rem;
  color: var(--taupe);
}
.ar-name {
  font-size: 1.25rem;
  font-weight: 300;
  font-style: italic;
}
.ar-origin,
.ar-medium {
  font-family: "DM Mono", monospace;
  font-size: 0.68rem;
  color: var(--muted);
  letter-spacing: 0.05em;
}
.ar-link {
  font-family: "DM Mono", monospace;
  font-size: 0.68rem;
  color: var(--gold);
  text-decoration: none;
  text-align: right;
  transition: letter-spacing 0.2s;
}
.ar-link:hover {
  letter-spacing: 0.08em;
}

/* Visit */
.visit-section {
  padding: 5rem 3rem;
  background: var(--off-white);
  border-top: 1px solid var(--border);
}
.visit-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  max-width: 1100px;
  margin: 0 auto;
}
.visit-left h2 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 300;
  line-height: 1.2;
  margin-bottom: 2rem;
}
.visit-left h2 em {
  font-style: italic;
  color: var(--gold);
}
.visit-details {
  display: flex;
  flex-direction: column;
  margin-bottom: 2.5rem;
  border-top: 1px solid var(--border);
}
.vd-item {
  display: flex;
  justify-content: space-between;
  padding: 0.9rem 0;
  border-bottom: 1px solid var(--border);
  font-size: 0.88rem;
}
.vd-item span:first-child {
  font-family: "DM Mono", monospace;
  font-size: 0.68rem;
  color: var(--muted);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.visit-map {
  position: relative;
  height: 350px;
  background: var(--light);
  border: 1px solid var(--border);
  border-radius: 2px;
  overflow: hidden;
}
.vm-inner {
  width: 100%;
  height: 100%;
  background: repeating-linear-gradient(
      0deg,
      transparent,
      transparent 40px,
      var(--border) 40px,
      var(--border) 41px
    ),
    repeating-linear-gradient(
      90deg,
      transparent,
      transparent 40px,
      var(--border) 40px,
      var(--border) 41px
    );
}
.vm-pin {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 1.5rem;
  color: var(--gold);
}

/* Lightbox */
.lightbox {
  position: fixed;
  inset: 0;
  z-index: 500;
  display: grid;
  grid-template-columns: 1fr 360px;
  background: var(--text);
}
.lightbox[hidden] {
  display: none;
}
.lb-artwork {
  height: 100%;
}
.wi-art--1.lb-art {
  background: linear-gradient(145deg, #d8d0c8, #b0a89c, #888078);
}
.lb-panel {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 2.5rem;
  border-left: 1px solid rgba(255, 255, 255, 0.1);
  overflow: auto;
  background: var(--text);
  color: var(--white);
}
.lb-close {
  align-self: flex-end;
  background: none;
  border: none;
  color: rgba(255, 255, 255, 0.5);
  font-size: 1rem;
  cursor: pointer;
  font-family: "DM Mono", monospace;
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  padding: 0.5rem;
  transition: color 0.2s;
}
.lb-close:hover {
  color: white;
}
.lb-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.lb-num {
  font-family: "DM Mono", monospace;
  font-size: 0.6rem;
  letter-spacing: 0.15em;
  color: var(--gold);
  margin-bottom: 1rem;
  display: block;
}
.lb-title {
  font-size: 2.2rem;
  font-weight: 300;
  font-style: italic;
  line-height: 1.2;
  margin-bottom: 0.5rem;
}
.lb-artist {
  font-size: 0.85rem;
  color: rgba(255, 255, 255, 0.55);
  margin-bottom: 0.3rem;
}
.lb-medium {
  font-family: "DM Mono", monospace;
  font-size: 0.65rem;
  color: rgba(255, 255, 255, 0.3);
  letter-spacing: 0.08em;
  margin-bottom: 1.5rem;
}
.lb-desc {
  font-size: 0.92rem;
  color: rgba(255, 255, 255, 0.6);
  line-height: 1.85;
}
.lb-nav {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
}
.lb-nav button {
  flex: 1;
  padding: 0.75rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.6);
  font-family: "DM Mono", monospace;
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition: all 0.2s;
}
.lb-nav button:hover {
  background: rgba(255, 255, 255, 0.1);
  color: white;
}

/* Responsive */
@media (max-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr;
  }
  .visit-inner {
    grid-template-columns: 1fr;
  }
  .works-grid {
    grid-template-columns: 1fr 1fr;
  }
  .work-item--tall {
    grid-row: auto;
  }
  .lightbox {
    grid-template-columns: 1fr;
  }
  .lb-panel {
    max-height: 40vh;
  }
}
@media (max-width: 768px) {
  .nav {
    padding: 1.25rem 1.5rem;
  }
  .nav-links {
    display: none;
  }
  .works-section,
  .artists-section,
  .visit-section {
    padding: 4rem 1.5rem;
  }
  .artist-row {
    grid-template-columns: 1fr 1fr;
  }
  .ar-num,
  .ar-origin,
  .ar-medium {
    display: none;
  }
}
html.reduced-motion .work-item:hover .wi-art {
  transform: none;
}
html.reduced-motion * {
  transition-duration: 0.01ms !important;
}

