import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import Lenis from "lenis";

gsap.registerPlugin(ScrollTrigger);

initDemoShell({
  title: "Atelier Blanc — Art Gallery",
  category: "pages",
  tech: ["gsap", "scroll-trigger", "lenis", "clip-path", "cormorant"],
});

const reduced = prefersReducedMotion();
if (reduced) document.documentElement.classList.add("reduced-motion");

const lenis = new Lenis({ lerp: 0.08, smoothWheel: true });
lenis.on("scroll", ScrollTrigger.update);
gsap.ticker.add((time) => lenis.raf(time * 1000));
gsap.ticker.lagSmoothing(0);

// Hero entrance
if (!reduced) {
  gsap.set([".hero-season", ".hero-h1", ".hero-text p", ".btn-dark"], { opacity: 0, y: 20 });
  gsap.set([".ha-frame--main", ".ha-frame--accent"], { opacity: 0, scale: 1.03 });
  gsap.set(".ha-label", { opacity: 0 });

  gsap
    .timeline({ delay: 0.4, defaults: { ease: "expo.out" } })
    .to(".hero-season", { opacity: 1, y: 0, duration: 0.7 })
    .to(".hero-h1", { opacity: 1, y: 0, duration: 1.2 }, "-=0.4")
    .to(".hero-text p", { opacity: 1, y: 0, duration: 0.9 }, "-=0.6")
    .to(".btn-dark", { opacity: 1, y: 0, duration: 0.7 }, "-=0.5")
    .to(".ha-frame--main", { opacity: 1, scale: 1, duration: 1.4, ease: "power2.out" }, 0.5)
    .to(".ha-frame--accent", { opacity: 1, scale: 1, duration: 1.1, ease: "power2.out" }, 0.8)
    .to(".ha-label", { opacity: 1, duration: 0.8 }, 1.2);
}

// Works counter update
const worksCount = document.getElementById("works-count");
const workItems = document.querySelectorAll(".work-item");

workItems.forEach((item, i) => {
  if (!reduced) {
    gsap.set(item, { opacity: 0 });
    gsap.to(item, {
      opacity: 1,
      duration: 0.8,
      ease: "power1.out",
      delay: (i % 3) * 0.12,
      scrollTrigger: {
        trigger: ".works-grid",
        start: "top 80%",
        toggleActions: "play none none none",
      },
    });
  }
});

// Artist rows reveal
if (!reduced) {
  document.querySelectorAll(".artist-row").forEach((row, i) => {
    gsap.set(row, { opacity: 0, x: -20 });
    gsap.to(row, {
      opacity: 1,
      x: 0,
      duration: 0.7,
      ease: "expo.out",
      delay: i * 0.1,
      scrollTrigger: {
        trigger: ".artists-list",
        start: "top 75%",
        toggleActions: "play none none reverse",
      },
    });
  });
}

// Lightbox data
const artworkData = [
  {
    num: "01",
    title: "Luminous Void",
    artist: "Elias Vorne",
    medium: "Oil on canvas, 200×300cm",
    artClass: "wi-art--1",
  },
  {
    num: "02",
    title: "Still Point",
    artist: "Mara Solis",
    medium: "Photography, 80×120cm",
    artClass: "wi-art--2",
  },
  {
    num: "03",
    title: "Threshold Study",
    artist: "Jun Aoki",
    medium: "Mixed media, 150×150cm",
    artClass: "wi-art--3",
  },
  {
    num: "04",
    title: "Erosion Series I–III",
    artist: "Petra Novak",
    medium: "Sculpture (bronze), variable dimensions",
    artClass: "wi-art--4",
  },
  {
    num: "05",
    title: "Frequency",
    artist: "Yuki Tanaka",
    medium: "Digital print, 100×100cm",
    artClass: "wi-art--5",
  },
  {
    num: "06",
    title: "Residue",
    artist: "Camille Dubois",
    medium: "Watercolor, 60×80cm",
    artClass: "wi-art--6",
  },
  {
    num: "07",
    title: "Meridian",
    artist: "Elias Vorne",
    medium: "Acrylic, 180×280cm",
    artClass: "wi-art--7",
  },
  {
    num: "08",
    title: "Archive (after Borges)",
    artist: "Jun Aoki",
    medium: "Installation, site-specific",
    artClass: "wi-art--8",
  },
];

const lightbox = document.getElementById("lightbox");
const lbArtwork = document.getElementById("lb-artwork");
const lbNum = document.getElementById("lb-num");
const lbTitle = document.getElementById("lb-title");
const lbArtist = document.getElementById("lb-artist");
const lbMedium = document.getElementById("lb-medium");
let currentIdx = -1;

function openLightbox(idx) {
  const d = artworkData[idx];
  const item = workItems[idx];
  const rect = item.getBoundingClientRect();
  const vw = window.innerWidth;
  const vh = window.innerHeight;

  currentIdx = idx;
  lbNum.textContent = d.num;
  lbTitle.textContent = d.title;
  lbArtist.textContent = d.artist;
  lbMedium.textContent = d.medium;
  lbArtwork.className = "lb-artwork wi-art " + d.artClass;
  worksCount.textContent = `${d.num} / 08`;

  lightbox.removeAttribute("hidden");

  if (!reduced) {
    gsap.set(lightbox, {
      clipPath: `inset(${rect.top}px ${vw - rect.right}px ${vh - rect.bottom}px ${rect.left}px round 2px)`,
    });
    gsap.to(lightbox, {
      clipPath: "inset(0px 0px 0px 0px round 0px)",
      duration: 0.6,
      ease: "expo.out",
    });
    gsap.set([lbNum, lbTitle, lbArtist, lbMedium], { opacity: 0, y: 15 });
    gsap.to([lbNum, lbTitle, lbArtist, lbMedium], {
      opacity: 1,
      y: 0,
      duration: 0.5,
      stagger: 0.08,
      ease: "expo.out",
      delay: 0.35,
    });
  }

  document.body.style.overflow = "hidden";
  document.getElementById("lb-close").focus();
}

function closeLightbox() {
  if (!reduced) {
    const item = workItems[currentIdx];
    const rect = item.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    gsap.to(lightbox, {
      clipPath: `inset(${rect.top}px ${vw - rect.right}px ${vh - rect.bottom}px ${rect.left}px round 2px)`,
      duration: 0.4,
      ease: "expo.in",
      onComplete: () => {
        lightbox.setAttribute("hidden", "");
        gsap.set(lightbox, { clipPath: "" });
      },
    });
  } else {
    lightbox.setAttribute("hidden", "");
  }
  document.body.style.overflow = "";
  workItems[currentIdx].focus();
}

function navigate(dir) {
  const next = (currentIdx + dir + artworkData.length) % artworkData.length;
  if (!reduced) {
    gsap.to([lbNum, lbTitle, lbArtist, lbMedium], {
      opacity: 0,
      x: dir * -20,
      duration: 0.2,
      ease: "power2.in",
      onComplete: () => {
        currentIdx = next;
        const d = artworkData[next];
        lbNum.textContent = d.num;
        lbTitle.textContent = d.title;
        lbArtist.textContent = d.artist;
        lbMedium.textContent = d.medium;
        lbArtwork.className = "lb-artwork wi-art " + d.artClass;
        worksCount.textContent = `${d.num} / 08`;
        gsap.fromTo(
          [lbNum, lbTitle, lbArtist, lbMedium],
          { opacity: 0, x: dir * 20 },
          { opacity: 1, x: 0, duration: 0.35, stagger: 0.06, ease: "expo.out" }
        );
      },
    });
  } else {
    currentIdx = next;
    const d = artworkData[next];
    lbNum.textContent = d.num;
    lbTitle.textContent = d.title;
    lbArtist.textContent = d.artist;
    lbMedium.textContent = d.medium;
    lbArtwork.className = "lb-artwork wi-art " + d.artClass;
  }
}

workItems.forEach((item, i) => {
  item.addEventListener("click", () => openLightbox(i));
  item.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      openLightbox(i);
    }
  });
});

document.getElementById("lb-close").addEventListener("click", closeLightbox);
document.getElementById("lb-prev").addEventListener("click", () => navigate(-1));
document.getElementById("lb-next").addEventListener("click", () => navigate(1));
document.addEventListener("keydown", (e) => {
  if (!lightbox.hasAttribute("hidden")) {
    if (e.key === "Escape") closeLightbox();
    if (e.key === "ArrowLeft") navigate(-1);
    if (e.key === "ArrowRight") navigate(1);
  }
});

// Visit section reveal
if (!reduced) {
  gsap.set(".visit-left > *", { opacity: 0, y: 20 });
  gsap.to(".visit-left > *", {
    opacity: 1,
    y: 0,
    duration: 0.8,
    stagger: 0.12,
    ease: "expo.out",
    scrollTrigger: {
      trigger: ".visit-section",
      start: "top 75%",
      toggleActions: "play none none reverse",
    },
  });
}

window.addEventListener("motion-preference", (e) => {
  gsap.globalTimeline.paused(e.detail.reduced);
});

snippets.css:
:root {
  --bg: #070a12;
  --text: #f0f4fb;
  --panel: #121a2b;
  --border: #263249;
  --accent: #86e8ff;
  --muted: #8a95a8;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
  overflow-x: hidden;
}

/* Fixed canvas behind content */
#speed-canvas {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

section {
  position: relative;
  z-index: 1;
}

.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
  background: radial-gradient(ellipse at center, rgba(134, 232, 255, 0.06) 0%, transparent 70%);
}

.hero .content {
  max-width: 600px;
  text-align: center;
}

.eyebrow {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 1rem;
}

.hero h1 {
  font-size: 3.5rem;
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: 1.5rem;
  letter-spacing: -1px;
}

.subtitle {
  font-size: 1.1rem;
  color: var(--muted);
}

/* Content Sections */
.section {
  max-width: 760px;
  margin: 0 auto;
  padding: 5rem 2rem;
  border-bottom: 1px solid var(--border);
}

.section h2 {
  font-size: 2rem;
  margin-bottom: 1.5rem;
  color: var(--text);
}

.section p {
  font-size: 1rem;
  color: var(--muted);
  margin-bottom: 1.5rem;
  line-height: 1.8;
}

.section ul {
  margin-left: 1.5rem;
  margin-bottom: 1.5rem;
}

.section li {
  color: var(--muted);
  margin-bottom: 0.8rem;
  line-height: 1.7;
}

code {
  background: rgba(134, 232, 255, 0.1);
  color: var(--accent);
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  font-family: "Monaco", "Courier New", monospace;
  font-size: 0.9rem;
}

.btn-back {
  display: inline-block;
  margin-top: 2rem;
  padding: 0.8rem 1.5rem;
  background: var(--accent);
  color: var(--bg);
  border-radius: 4px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.3s ease;
}

.btn-back:hover {
  background: rgba(134, 232, 255, 0.8);
  transform: translateY(-2px);
}

@media (max-width: 768px) {
  .hero h1 {
    font-size: 2.5rem;
  }
  .section h2 {
    font-size: 1.5rem;
  }
  .section {
    padding: 3rem 1.5rem;
  }
}

@media (max-width: 480px) {
  .hero h1 {
    font-size: 2rem;
  }
}

html.reduced-motion #speed-canvas {
  display: none;
}
html.reduced-motion * {
  animation-duration: 0.01ms !important;
  transition-duration: 0.01ms !important;
}

