.progress-circle {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  z-index: 100;
  width: 48px;
  height: 48px;
}
.progress-circle svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}
.progress-circle .track {
  fill: none;
  stroke: var(--border);
  stroke-width: 3;
}
.progress-circle .fill {
  fill: none;
  stroke: var(--accent);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-dasharray: 125.66;
  stroke-dashoffset: 125.66;
