const cardsData = [
  {
    title: "Mountain View",
    copy: "Check out these high-altitude escapes with crisp air and cinematic horizons.",
    button: "View Trips",
    theme: "media-sky",
  },
  {
    title: "To The Beach",
    copy: "Plan your next shoreline getaway with warm sunsets and deep blue water.",
    button: "View Trips",
    theme: "media-tide",
  },
  {
    title: "Desert Destinations",
    copy: "Wind-shaped dunes and amber tones for your most surreal journey yet.",
    button: "Book Now",
    theme: "media-dune",
  },
  {
    title: "Explore The Galaxy",
    copy: "Lift off into a night-sky adventure with glowing stardust and nebula haze.",
    button: "Book Now",
    theme: "media-orbit",
  },
];

const stack = document.getElementById("card-stack");
const stage = document.getElementById("scroll-stage");

stack.innerHTML = cardsData
  .map((card, index) => {
    return `
      <article class="card" data-index="${index}" aria-hidden="true">
        <div class="media ${card.theme}"></div>
        <div class="content">
          <p class="meta">0${index + 1}</p>
          <h2 class="title">${card.title}</h2>
          <p class="copy">${card.copy}</p>
          <button class="btn" type="button">${card.button}</button>
        </div>
      </article>
    `;
  })
  .join("");

stage.style.setProperty("--card-count", cardsData.length);

const cards = Array.from(document.querySelectorAll(".card"));

const clamp = (value, min, max) => Math.min(Math.max(value, min), max);

const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
const cycleMs = prefersReducedMotion.matches ? 2800 : 3800;
const transitionMs = prefersReducedMotion.matches ? 500 : 700;

function applyProgress(scaled) {
  cards.forEach((card, index) => {
    const distance = scaled - index;
    const absDistance = Math.abs(distance);
    const clamped = clamp(absDistance, 0, 1);
    const opacity = 1 - clamped;
    const slideX = distance * 110;
    const scale = 1 - clamped * 0.06;
    const blur = clamped * 12;
    const wipe = clamp(1 - clamped, 0, 1);

    card.style.opacity = opacity.toFixed(3);
    card.style.transform = `translateX(${slideX.toFixed(2)}px) scale(${scale.toFixed(3)})`;
    card.style.filter = `blur(${blur.toFixed(2)}px)`;
    card.style.clipPath = `polygon(0 0, ${wipe * 100}% 0, ${wipe * 100}% 100%, 0 100%)`;
    card.style.zIndex = String(cards.length - Math.round(absDistance * 10));
    card.setAttribute("aria-hidden", opacity < 0.6 ? "true" : "false");

    const media = card.querySelector(".media");
    if (media) {
      const mediaShift = clamp(-distance * 24, -30, 30);
      media.style.transform = `translateX(${mediaShift.toFixed(2)}px) scale(${(1 + clamped * 0.04).toFixed(3)})`;
    }
  });
}

let rafId = 0;
let startTime = 0;

function animate(now) {
  if (!startTime) startTime = now;

  const elapsed = now - startTime;
  const segment = cycleMs + transitionMs;
  const total = segment * cards.length;
  const loopTime = elapsed % total;

  const activeIndex = Math.floor(loopTime / segment);
  const segmentTime = loopTime % segment;
  const t = clamp(segmentTime / transitionMs, 0, 1);

  const eased = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

  const scaled = activeIndex + eased;
  applyProgress(scaled);

  rafId = window.requestAnimationFrame(animate);
}

applyProgress(0);
rafId = window.requestAnimationFrame(animate);

prefersReducedMotion.addEventListener("change", () => {
  window.cancelAnimationFrame(rafId);
  startTime = 0;
  rafId = window.requestAnimationFrame(animate);
});

snippets.css:
/* ─── Reset & Base ─────────────────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #ffffff;
  --dark: #0d1b2a;
  --text: #0d1b2a;
  --muted: #6b7a8d;
  --accent: #2563eb;
  --light: #f0f4ff;
  --border: #e2e8f0;
  --radius: 12px;
  --radius-sm: 6px;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", "Inter", "Helvetica Neue", Arial,
    sans-serif;
  --font-mono: "SFMono-Regular", "Consolas", "Liberation Mono", "Menlo", monospace;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}
ul {
  list-style: none;
}
img {
  display: block;
  max-width: 100%;
}

/* ─── Shared Section Layout ────────────────────────────────────────────── */
.section {
  padding: clamp(5rem, 10vw, 9rem) clamp(1.5rem, 6vw, 7rem);
  max-width: 1240px;
  margin: 0 auto;
}

.section__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 2rem;
  margin-bottom: clamp(3rem, 6vw, 5rem);
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--border);
}

.section__label-group {
  display: flex;
  align-items: baseline;
  gap: 1rem;
}

.section-index {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent);
  font-family: var(--font-mono);
  letter-spacing: 0.05em;
}

.section-label {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

.section__summary {
  font-size: 0.9rem;
  color: var(--muted);
  max-width: 30ch;
  line-height: 1.6;
  text-align: right;
}

/* ─── Hero ──────────────────────────────────────────────────────────────── */
.hero {
  position: relative;
  min-height: 100svh;
  background: var(--dark);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.hero__canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 0;
}

.hero__inner {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  flex: 1;
  padding: clamp(2rem, 4vw, 4rem) clamp(1.5rem, 6vw, 7rem);
  padding-bottom: 5rem;
}

.hero__eyebrow {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding-top: 1rem;
}

.eyebrow-tag {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.5);
}

.eyebrow-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--accent);
  flex-shrink: 0;
}

.eyebrow-avail {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent);
  letter-spacing: 0.04em;
}

.hero__name {
  font-size: clamp(4rem, 12vw, 10rem);
  font-weight: 900;
  line-height: 0.9;
  letter-spacing: -0.04em;
  color: #ffffff;
  margin-top: auto;
  padding-top: 2rem;
  overflow: hidden;
}

.hero__name .line {
  overflow: hidden;
  display: block;
}

.hero__foot {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
  margin-top: 3rem;
}

.hero__tagline {
  font-size: clamp(1rem, 2vw, 1.2rem);
  font-weight: 400;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.55);
  max-width: 36ch;
}

.hero__ctas {
  display: flex;
  gap: 0.875rem;
  flex-shrink: 0;
}

.btn {
  display: inline-flex;
  align-items: center;
  height: 48px;
  padding: 0 1.75rem;
  border-radius: 6px;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  transition: transform 0.2s ease, opacity 0.2s ease, background 0.2s ease;
  cursor: pointer;
}

.btn--primary {
  background: var(--accent);
  color: #fff;
}

.btn--primary:hover {
  background: #1d4fd8;
  transform: translateY(-1px);
}

.btn--ghost {
  background: transparent;
  color: rgba(255, 255, 255, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.btn--ghost:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
  border-color: rgba(255, 255, 255, 0.35);
}

.hero__scroll-indicator {
  position: absolute;
  bottom: 2.5rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  z-index: 2;
}

.scroll-track {
  width: 1px;
  height: 48px;
  background: rgba(255, 255, 255, 0.12);
  border-radius: 1px;
  overflow: hidden;
  position: relative;
}

.scroll-thumb {
  position: absolute;
  top: -100%;
  left: 0;
  width: 100%;
  height: 50%;
  background: var(--accent);
  border-radius: 1px;
  animation: scrollThumb 1.8s ease-in-out infinite;
}

@keyframes scrollThumb {
  0% {
    top: -50%;
  }
  100% {
    top: 100%;
  }
}

.scroll-label {
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.3);
}

/* ─── Expertise Section ─────────────────────────────────────────────────── */
.expertise {
  background: var(--bg);
}

.expertise__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

@media (max-width: 900px) {
  .expertise__grid {
    grid-template-columns: 1fr;
  }
}

.expertise-card {
  background: var(--light);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2.5rem 2rem;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.expertise-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 16px 48px rgba(37, 99, 235, 0.08);
}

/* CSS geometric icons */
.expertise-card__icon {
  width: 48px;
  height: 48px;
  margin-bottom: 1.5rem;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.icon-backend {
  width: 36px;
  height: 36px;
  border: 2.5px solid var(--accent);
  border-radius: 6px;
  position: relative;
}

.icon-backend::before {
  content: "";
  position: absolute;
  top: 6px;
  left: 6px;
  right: 6px;
  height: 2px;
  background: var(--accent);
  border-radius: 1px;
  box-shadow: 0 6px 0 var(--accent), 0 12px 0 var(--accent);
}

.icon-platform {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 2.5px solid var(--accent);
  position: relative;
}

.icon-platform::before {
  content: "";
  position: absolute;
  inset: 6px;
  border-radius: 50%;
  border: 2.5px solid var(--accent);
}

.icon-platform::after {
  content: "";
  position: absolute;
  width: 8px;
  height: 8px;
  background: var(--accent);
  border-radius: 50%;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.icon-leadership {
  width: 36px;
  height: 36px;
  position: relative;
}

.icon-leadership::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 28px;
  height: 18px;
  border: 2.5px solid var(--accent);
  border-radius: 14px 14px 6px 6px;
  border-bottom: none;
}

.icon-leadership::after {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 14px;
  height: 14px;
  border: 2.5px solid var(--accent);
  border-radius: 50%;
}

.expertise-card__title {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 1.25rem;
  color: var(--text);
}

.expertise-card__list {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.expertise-card__list li {
  font-size: 0.875rem;
  color: var(--muted);
  line-height: 1.5;
  padding-left: 1rem;
  position: relative;
}

.expertise-card__list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--accent);
}

/* ─── Timeline Section ──────────────────────────────────────────────────── */
.timeline {
  background: var(--bg);
  padding-top: 0;
}

.timeline__track {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.timeline__line {
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--border);
  transform: translateX(-50%);
  z-index: 0;
}

.timeline-item {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 0 2.5rem;
  align-items: start;
  padding: 2.5rem 0;
  position: relative;
  z-index: 1;
}

/* Year dot on center line */
.timeline-item::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 2.9rem;
  transform: translateX(-50%);
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--accent);
  border: 2px solid var(--bg);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.2);
  z-index: 2;
}

.timeline-item__year {
  font-size: 0.8rem;
  font-weight: 700;
  font-family: var(--font-mono);
  color: var(--accent);
  letter-spacing: 0.06em;
  padding-top: 0.35rem;
}

.timeline-item__card {
  background: var(--light);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.75rem;
}

.timeline-item__meta {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-bottom: 0.875rem;
}

.timeline-item__role {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.01em;
}

.timeline-item__sep {
  color: var(--border);
  font-weight: 300;
}

.timeline-item__company {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--accent);
}

.timeline-item__desc {
  font-size: 0.875rem;
  color: var(--muted);
  line-height: 1.7;
}

/* Left-aligned: year left, empty center col, card right */
.timeline-item--left .timeline-item__year {
  text-align: right;
  grid-column: 1;
  grid-row: 1;
}

.timeline-item--left .timeline-item__card {
  grid-column: 3;
  grid-row: 1;
}

/* Right-aligned: card left, empty center col, year right */
.timeline-item--right .timeline-item__card {
  grid-column: 1;
  grid-row: 1;
}

.timeline-item--right .timeline-item__year {
  grid-column: 3;
  grid-row: 1;
  padding-top: 0.35rem;
}

@media (max-width: 768px) {
  .timeline__line {
    left: 1rem;
  }
  .timeline-item {
    grid-template-columns: 1fr;
    padding-left: 3rem;
  }
  .timeline-item::after {
    left: 1rem;
    transform: translateX(-50%);
  }
  .timeline-item--left .timeline-item__year,
  .timeline-item--right .timeline-item__year {
    grid-column: 1;
    grid-row: 1;
    text-align: left;
    font-size: 0.75rem;
    margin-bottom: 0.5rem;
  }
  .timeline-item--left .timeline-item__card,
  .timeline-item--right .timeline-item__card {
    grid-column: 1;
    grid-row: 2;
  }
}

/* ─── Open Source Section ───────────────────────────────────────────────── */
.open-source {
  background: var(--light);
  border-radius: 0;
  max-width: unset;
  padding-left: 0;
  padding-right: 0;
}

.open-source .section__header {
  max-width: 1240px;
  margin-left: auto;
  margin-right: auto;
  padding-left: clamp(1.5rem, 6vw, 7rem);
  padding-right: clamp(1.5rem, 6vw, 7rem);
}

.repos__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 clamp(1.5rem, 6vw, 7rem);
}

@media (max-width: 900px) {
  .repos__grid {
    grid-template-columns: 1fr;
  }
}

.repo-card {
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.75rem;
  cursor: pointer;
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
  color: var(--text);
}

.repo-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 36px rgba(37, 99, 235, 0.1);
  border-color: rgba(37, 99, 235, 0.3);
}

.repo-card__top {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.repo-card__icon {
  color: var(--muted);
  flex-shrink: 0;
  display: flex;
  align-items: center;
}

.repo-card__name {
  font-size: 0.9rem;
  font-weight: 700;
  font-family: var(--font-mono);
  color: var(--accent);
  flex: 1;
}

.repo-card__stars {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
  margin-left: auto;
  flex-shrink: 0;
}

.repo-card__stars svg {
  color: #f59e0b;
}

.repo-card__desc {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.65;
  flex: 1;
}

.repo-card__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-top: auto;
  padding-top: 0.75rem;
  border-top: 1px solid var(--border);
}

.lang-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.25rem 0.7rem;
  border-radius: 100px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.lang-pill::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.lang-pill--go {
  background: #e0f0ff;
  color: #0078d4;
}
.lang-pill--go::before {
  background: #0078d4;
}
.lang-pill--ts {
  background: #e0e8ff;
  color: #3178c6;
}
.lang-pill--ts::before {
  background: #3178c6;
}
.lang-pill--rust {
  background: #fbe8e0;
  color: #b7410e;
}
.lang-pill--rust::before {
  background: #b7410e;
}

.repo-card__updated {
  font-size: 0.72rem;
  color: var(--muted);
}

/* ─── Contact Section ───────────────────────────────────────────────────── */
.contact {
  background: var(--dark);
  max-width: unset;
  padding-top: clamp(5rem, 10vw, 9rem);
  padding-bottom: 0;
  padding-left: 0;
  padding-right: 0;
}

.contact__inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 clamp(1.5rem, 6vw, 7rem);
  padding-bottom: clamp(5rem, 10vw, 9rem);
}

.contact__kicker {
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 1.5rem;
}

.contact__cta {
  font-size: clamp(3rem, 8vw, 7rem);
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 0.92;
  color: #ffffff;
  margin-bottom: 3.5rem;
  overflow: hidden;
}

.contact__cta .line {
  overflow: hidden;
  display: block;
}

.contact__links {
  display: flex;
  align-items: center;
  gap: 3rem;
  flex-wrap: wrap;
}

.contact__email {
  font-size: 1.1rem;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.85);
  border-bottom: 1px solid rgba(255, 255, 255, 0.25);
  padding-bottom: 2px;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.contact__email:hover {
  color: #fff;
  border-color: var(--accent);
}

.contact__social {
  display: flex;
  gap: 1.75rem;
}

.social-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.45);
  letter-spacing: 0.03em;
  transition: color 0.2s ease;
}

.social-link:hover {
  color: rgba(255, 255, 255, 0.9);
}

.contact__foot {
  max-width: 1240px;
  margin: 0 auto;
  padding: 1.75rem clamp(1.5rem, 6vw, 7rem);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  flex-wrap: wrap;
}

.contact__foot span {
  font-size: 0.78rem;
  color: rgba(255, 255, 255, 0.28);
  font-weight: 500;
}

/* ─── Reduced Motion ────────────────────────────────────────────────────── */
.reduced-motion *,
.reduced-motion *::before,
.reduced-motion *::after {
  animation-duration: 0.01ms !important;
  transition-duration: 0.01ms !important;
}

.reduced-motion .scroll-thumb {
  animation: none !important;
}

