  flex-direction: column;
  gap: 1rem;
  margin-bottom: 3rem;
  padding: 2.5rem;
  border: 1px solid rgba(201, 168, 76, 0.2);
  border-radius: 2px;
  text-align: left;
}

.res-detail {
  display: flex;
  gap: 1rem;
  align-items: baseline;
}

.res-label {
  font-family: var(--font-ui);
  font-size: 0.65rem;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--gold);
  min-width: 80px;
}

.res-detail span:last-child {
  font-family: var(--font-body);
  font-size: 1rem;
  color: rgba(232, 221, 200, 0.75);
}

/* ── Footer ── */
.footer {
  padding: 3rem 2rem;
  background: var(--charcoal);
  text-align: center;
  border-top: 1px solid rgba(201, 168, 76, 0.1);
}

.footer-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 400;
  color: var(--gold);
  margin-bottom: 0.8rem;
}

.footer p {
  font-family: var(--font-ui);
  font-size: 0.8rem;
  color: var(--warm-muted);
  letter-spacing: 0.5px;
}

.footer-copy {
  margin-top: 1rem;
  font-size: 0.7rem !important;
  color: rgba(122, 106, 88, 0.5) !important;
}

/* ── Responsive ── */
@media (max-width: 900px) {
  .philosophy-inner {
    grid-template-columns: 1fr;
    gap: 3rem;
  }
  .philosophy-deco {
    display: none;
  }
  .menu-item,
  .menu-item--reverse {
    grid-template-columns: 1fr;
    direction: ltr;
  }
  .menu-img {
    height: 250px;
  }
  .story-grid {
    grid-template-columns: 1fr;
    gap: 3rem;
  }
  .story-img--accent {
    display: none;
  }
  .story-year {
    display: none;
  }
}

@media (max-width: 768px) {
  .nav {
    padding: 1rem 1.5rem;
  }
  .nav-links {
    display: none;
  }
  .hero-title {
    font-size: clamp(2.5rem, 10vw, 5rem);
  }
  .menu-info {
    padding: 2.5rem 2rem;
  }
  .story-awards {
    flex-direction: column;
    gap: 1.5rem;
  }
  .res-info {
    padding: 1.5rem;
  }
}

