*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* ── Theme tokens ── */
[data-theme="dark"] {
  --bg: #070a12;
  --bg-elevated: #121a2b;
  --border: #263249;
  --text: #f0f4fb;
  --text-secondary: #8a95a8;
  --accent: #86e8ff;
  --secondary: #ae52ff;
  --tertiary: #ff40d6;
  --code-bg: rgba(134, 232, 255, 0.1);
  --code-color: #86e8ff;
  --card-shadow: rgba(0, 0, 0, 0.3);
}

[data-theme="light"] {
  --bg: #f5f7fb;
  --bg-elevated: #ffffff;
