}

body {
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  transition: none; /* transitions handled by View Transitions API */
}

/* ── Page ── */
.page {
  max-width: 880px;
  margin: 0 auto;
  padding: 5rem 2rem 4rem;
}

.header {
  text-align: center;
