// Initialize Lenis smooth scroll
const lenis = new Lenis({
  duration: 1.2,
  easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
  direction: "vertical",
  gestureDirection: "vertical",
  smooth: true,
  smoothTouch: false,
  touchMultiplier: 2,
});

// Animation loop
function raf(time) {
  lenis.raf(time);
  requestAnimationFrame(raf);
}
requestAnimationFrame(raf);

// Register GSAP ScrollTrigger
gsap.registerPlugin(ScrollTrigger);

// Update ScrollTrigger on scroll
lenis.on("scroll", ScrollTrigger.update);

// Proxy scroll events to GSAP
gsap.ticker.add((time) => {
  lenis.raf(time * 1000);
});

gsap.ticker.lagSmoothing(0);

// Three.js Background Setup
let scene, camera, renderer, particles;

function initThree() {
  // Scene
  scene = new THREE.Scene();

  // Camera
  camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
  camera.position.z = 5;

  // Renderer
  const canvas = document.getElementById("canvas");
  renderer = new THREE.WebGLRenderer({
    canvas: canvas,
    alpha: true,
    antialias: true,
  });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(window.devicePixelRatio);

  // Create particles (stars)
  const particleCount = 2000;
  const geometry = new THREE.BufferGeometry();
  const positions = new Float32Array(particleCount * 3);
  const colors = new Float32Array(particleCount * 3);

  const pinkColor = new THREE.Color(0xffb6c1);
  const whiteColor = new THREE.Color(0xffffff);

  for (let i = 0; i < particleCount * 3; i += 3) {
    positions[i] = (Math.random() - 0.5) * 20;
    positions[i + 1] = (Math.random() - 0.5) * 20;
    positions[i + 2] = (Math.random() - 0.5) * 20;

    const color = Math.random() > 0.7 ? pinkColor : whiteColor;
    colors[i] = color.r;
    colors[i + 1] = color.g;
    colors[i + 2] = color.b;
  }

  geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));

  const material = new THREE.PointsMaterial({
    size: 0.05,
    vertexColors: true,
    transparent: true,
    opacity: 0.8,
    blending: THREE.AdditiveBlending,
  });

  particles = new THREE.Points(geometry, material);
  scene.add(particles);

  // Create smoke/glow effect
  const smokeGeometry = new THREE.PlaneGeometry(10, 10);
  const smokeMaterial = new THREE.MeshBasicMaterial({
    color: 0xff69b4,
    transparent: true,
    opacity: 0.1,
    side: THREE.DoubleSide,
  });

  const smokeCount = 5;
  for (let i = 0; i < smokeCount; i++) {
    const smoke = new THREE.Mesh(smokeGeometry, smokeMaterial.clone());
    smoke.position.set((Math.random() - 0.5) * 8, (Math.random() - 0.5) * 8 - 2, -2);
    smoke.rotation.z = Math.random() * Math.PI;
    smoke.scale.set(Math.random() * 2 + 1, Math.random() * 3 + 2, 1);
    scene.add(smoke);
  }

  animate();
}

function animate() {
  requestAnimationFrame(animate);

  // Rotate particles
  if (particles) {
    particles.rotation.y += 0.0005;
    particles.rotation.x += 0.0002;
  }

  renderer.render(scene, camera);
}

// Handle window resize
function onWindowResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
}
window.addEventListener("resize", onWindowResize);

// Initialize Three.js
initThree();

// GSAP Animations
gsap.utils.toArray(".section").forEach((section, index) => {
  if (index > 0) {
    gsap.from(section, {
      opacity: 0,
      y: 100,
      duration: 1,
      scrollTrigger: {
        trigger: section,
        start: "top 80%",
        end: "top 20%",
        scrub: 1,
      },
    });
  }
});

// Animate main title
gsap.from(".main-title", {
  opacity: 0,
  scale: 0.8,
  duration: 1.5,
  ease: "power3.out",
});

// Animate subtitle
gsap.from(".subtitle", {
  opacity: 0,
  x: -50,
  duration: 1,
  delay: 0.5,
  ease: "power3.out",
});

// Animate buttons
gsap.from(".btn", {
  opacity: 0,
  y: 30,
  duration: 0.8,
  delay: 1,
  stagger: 0.2,
  ease: "power3.out",
});

// Animate content items
gsap.utils.toArray(".content-item, .project-card").forEach((item, index) => {
  gsap.from(item, {
    opacity: 0,
