  width: 60px;
  height: 60px;
  border-color: var(--accent);
  background: rgba(134, 232, 255, 0.06);
}

.cursor-ring.clicking {
  width: 30px;
  height: 30px;
  border-color: var(--neon-pink);
}

.cursor-dot {
  position: fixed;
  top: 0;
  left: 0;
  width: 6px;
  height: 6px;
  background: var(--accent);
  border-radius: 50%;
  pointer-events: none;
  z-index: 99999;
  transform: translate(-50%, -50%);
  will-change: transform;
