  font: 600 0.9rem / 1 "Inter", system-ui, sans-serif;
  cursor: none;
  transition: border-color 0.3s, box-shadow 0.3s;
  will-change: transform;
}

.mag-btn span {
  pointer-events: none;
}

.mag-btn:hover {
  border-color: var(--accent);
  box-shadow: 0 0 20px rgba(134, 232, 255, 0.15);
}

.mag-btn.accent {
