}

.mag-btn.outline:hover {
  border-color: var(--neon-purple);
  color: var(--neon-purple);
}

/* ── Cards ── */
.card-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.25rem;
  margin-bottom: 3rem;
