:root {
  --page-bg: #0b1628;
  --page-surface: #101e36;
  --page-border: #1a3050;
  --page-text: #e8f0ff;
  --page-muted: #7a8da8;
  --page-accent: #00c2ff;
  --page-accent-warm: #ff8c42;
  --page-cloud: #2a4068;
  --page-sky-top: #0a1020;
  --page-sky-mid: #1a3060;
}

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: var(--page-bg);
  color: var(--page-text);
  font-family: "SF Pro Display", "Inter", system-ui, -apple-system, sans-serif;
  line-height: 1.6;
  overflow-x: hidden;
}

/* ── Canvas Container ── */
#canvas-container {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

/* ── Sections ── */
.section {
  position: relative;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 6rem 2rem;
  z-index: 1;
}

/* ══════════════════════════════════════════════════════════════════════
   HERO
   ══════════════════════════════════════════════════════════════════════ */
.hero-section {
  position: relative;
  overflow: hidden;
  background: linear-gradient(
    180deg,
    var(--page-sky-top) 0%,
    var(--page-sky-mid) 40%,
    var(--page-bg) 100%
  );
}

/* Decorative cloud layers */
.hero-clouds {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.hero-clouds::before {
  content: "";
  position: absolute;
  top: 20%;
  left: -10%;
  width: 55%;
  height: 30%;
  background: radial-gradient(ellipse at center, rgba(42, 64, 104, 0.25) 0%, transparent 70%);
  border-radius: 50%;
  filter: blur(40px);
}

.hero-clouds::after {
  content: "";
  position: absolute;
  top: 40%;
  right: -5%;
  width: 45%;
  height: 25%;
  background: radial-gradient(ellipse at center, rgba(42, 64, 104, 0.2) 0%, transparent 70%);
  border-radius: 50%;
  filter: blur(50px);
}

.hero-content {
  position: relative;
  z-index: 1;
  text-align: center;
}

.hero-title {
  font-size: clamp(2.8rem, 10vw, 7rem);
  font-weight: 700;
  color: #ffffff;
  line-height: 1;
  letter-spacing: -0.02em;
  text-shadow: 0 4px 40px rgba(0, 0, 0, 0.3);
  margin-bottom: 1.5rem;
}

.hero-subtitle {
  font-size: clamp(0.9rem, 2.5vw, 1.25rem);
  color: var(--page-muted);
  font-weight: 400;
  letter-spacing: 0.04em;
  opacity: 0;
  min-height: 1.8em;
}

.scroll-indicator {
  margin-top: 3rem;
  color: var(--page-accent);
  opacity: 0;
  animation: scroll-float 2.5s ease-in-out infinite;
}

@keyframes scroll-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(8px);
  }
}

.reduced-motion .scroll-indicator {
  animation: none;
}

/* ══════════════════════════════════════════════════════════════════════
   FLIGHT TRACK (scroll spacer)
   ══════════════════════════════════════════════════════════════════════ */
.flight-track {
  position: relative;
  height: 600vh;
  z-index: 0;
}

.flight-section {
  height: 150vh;
  position: relative;
}

/* ══════════════════════════════════════════════════════════════════════
   DESTINATION CARDS (fixed overlay)
   ══════════════════════════════════════════════════════════════════════ */
.dest-card {
  position: fixed;
  right: 4rem;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  width: 280px;
  background: rgba(16, 30, 54, 0.92);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid var(--page-border);
  border-radius: 16px;
  padding: 0;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}

.dest-card.visible {
