  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1.5rem;
  transition: border-color 0.3s ease;
}

.chart-card:hover {
  border-color: rgba(134, 232, 255, 0.3);
}

.chart-wide {
  grid-column: 1 / -1;
}

.chart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.2rem;
}

.chart-header h3 {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
}

.chart-badge {
  font-size: 0.7rem;
  font-weight: 700;
  padding: 0.25rem 0.6rem;
  border-radius: 20px;
  background: rgba(134, 232, 255, 0.1);
  color: var(--muted);
  border: 1px solid var(--border);
}

.trend-up {
  color: #4ade80;
  background: rgba(74, 222, 128, 0.1);
  border-color: rgba(74, 222, 128, 0.3);
}

canvas {
  display: block;
  width: 100%;
  height: auto;
}

.chart-legend {
  display: flex;
  gap: 1.5rem;
  margin-top: 1rem;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.8rem;
  color: var(--muted);
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.dot.accent {
  background: rgba(134, 232, 255, 0.5);
}
.dot.purple {
  background: var(--purple);
}

.donut-legend {
  margin-top: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.dl-item {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.82rem;
  color: var(--muted);
}

.dl-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.dl-item span:nth-child(2) {
  flex: 1;
}
.dl-item strong {
  color: var(--text);
}

/* ── Timeline ── */
.timeline-section {
  padding: 7rem 2rem;
  border-top: 1px solid var(--border);
}

.timeline {
  max-width: 700px;
  margin: 0 auto;
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--border);
  transform: translateX(-50%);
}

.tl-item {
  display: flex;
  align-items: flex-start;
  margin-bottom: 3rem;
  position: relative;
}

.tl-item[data-side="left"] {
  flex-direction: row;
}
.tl-item[data-side="right"] {
  flex-direction: row-reverse;
}

.tl-dot {
  position: absolute;
  left: 50%;
  top: 1.2rem;
  transform: translateX(-50%);
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--border);
  border: 2px solid var(--panel);
  z-index: 1;
}

.tl-dot--active {
  background: var(--accent);
  box-shadow: 0 0 12px rgba(134, 232, 255, 0.5);
}

.tl-card {
  width: calc(50% - 2rem);
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1.2rem 1.5rem;
}

.tl-card--active {
  border-color: var(--accent);
  background: rgba(134, 232, 255, 0.06);
}

.tl-item[data-side="left"] .tl-card {
  margin-right: auto;
}
.tl-item[data-side="right"] .tl-card {
  margin-left: auto;
}

.tl-date {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--accent);
  display: block;
  margin-bottom: 0.4rem;
}

.tl-card h4 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--text);
}

.tl-card p {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.7;
}

/* ── Team ── */
.team-section {
  padding: 7rem 2rem;
  border-top: 1px solid var(--border);
  background: rgba(18, 26, 43, 0.5);
}

.team-grid {
  max-width: 800px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 1.5rem;
}

.team-card {
  text-align: center;
  padding: 1.5rem 1rem;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  transition: all 0.3s ease;
}

.team-card:hover {
  border-color: var(--accent);
  transform: translateY(-4px);
}

.team-avatar {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  font-size: 0.85rem;
  font-weight: 800;
  letter-spacing: 1px;
  background: hsl(var(--av-hue), 70%, 15%);
  border: 2px solid hsl(var(--av-hue), 70%, 35%);
  color: hsl(var(--av-hue), 70%, 65%);
}

.team-card h4 {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 0.3rem;
}

.team-card span {
  font-size: 0.78rem;
  color: var(--muted);
}

/* ── CTA ── */
.cta-section {
  padding: 8rem 2rem;
  text-align: center;
  border-top: 1px solid var(--border);
  background: radial-gradient(ellipse at 50% 50%, rgba(134, 232, 255, 0.06) 0%, transparent 70%);
}

.cta-section h2 {
  font-size: 3rem;
  font-weight: 900;
  margin-bottom: 1rem;
  letter-spacing: -1px;
}

.cta-section p {
  font-size: 1.1rem;
  color: var(--muted);
  margin-bottom: 2rem;
}

/* ── Responsive ── */
@media (max-width: 900px) {
  .charts-grid {
    grid-template-columns: 1fr;
  }
  .chart-wide {
    grid-column: 1;
  }
}

@media (max-width: 768px) {
  .hero-title {
    font-size: 2.8rem;
  }
  .section-title {
    font-size: 2rem;
  }
  .metrics-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .timeline::before {
    left: 1.2rem;
  }
  .tl-item,
  .tl-item[data-side="right"] {
    flex-direction: row;
  }
  .tl-dot {
    left: 1.2rem;
  }
  .tl-card {
    width: calc(100% - 4rem);
    margin-left: 3rem !important;
    margin-right: 0 !important;
  }

  .team-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 480px) {
  .hero-title {
    font-size: 2.2rem;
  }
  .metrics-grid {
    grid-template-columns: 1fr;
  }
  .team-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .cta-section h2 {
    font-size: 2rem;
  }
}

html.reduced-motion .gradient-text {
  animation: none !important;
}
html.reduced-motion * {
  animation-duration: 0.01ms !important;
  transition-duration: 0.01ms !important;
}

