  display: flex;
  gap: 3rem;
}

.nav-links a {
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--gray-light);
  text-decoration: none;
  transition: color 0.15s ease;
}

.nav-links a:hover {
  color: var(--yellow);
}

.nav-cta {
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 900;
  letter-spacing: 2px;
  color: var(--black);
  background: var(--yellow);
  text-decoration: none;
  padding: 0.6rem 1.5rem;
  border: none;
  transition: background 0.15s ease, transform 0.15s ease;
  display: inline-block;
}

.nav-cta:hover {
  background: var(--yellow-d);
  transform: translateY(-1px);
}

/* ── Hero ── */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  padding: 8rem 4rem 6rem;
  overflow: hidden;
  background: var(--black);
}

.hero-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.hero-stripe {
  position: absolute;
  background: var(--yellow);
  opacity: 0.04;
}

.hero-stripe--1 {
  width: 3px;
  top: 0;
  bottom: 0;
  right: 28%;
}

.hero-stripe--2 {
  height: 3px;
  left: 0;
  right: 0;
  bottom: 30%;
  opacity: 0.03;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 900px;
}

.hero-tag {
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--gray-light);
  margin-bottom: 2rem;
  border-left: 3px solid var(--yellow);
  padding-left: 1rem;
}

.hero-title {
  display: flex;
  flex-direction: column;
  margin-bottom: 2.5rem;
  line-height: 0.92;
}

.hero-line {
  font-family: var(--font-display);
  font-size: clamp(5rem, 14vw, 12rem);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: -3px;
  color: var(--white);
  display: block;
}

.hero-line--yellow {
  color: var(--yellow);
}

.hero-line--outline {
  color: transparent;
  -webkit-text-stroke: 3px var(--white);
}

.hero-sub {
  font-family: var(--font-body);
  font-size: 1.1rem;
  font-weight: 400;
  color: var(--gray-light);
