/* Ticker */
.hero-ticker {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--yellow);
  overflow: hidden;
  padding: 0.7rem 0;
}

.ticker-track {
  display: flex;
  gap: 2rem;
  white-space: nowrap;
  animation: ticker 25s linear infinite;
  width: max-content;
}

