.ph-bg {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 60% 40%, rgba(200, 160, 48, 0.06) 0%, transparent 60%),
    linear-gradient(160deg, var(--forest-light) 0%, var(--forest) 60%, #080e08 100%);
}
.ph-content {
  position: relative;
  z-index: 1;
  width: 100%;
  display: grid;
  grid-template-rows: auto 1fr auto;
  height: 100vh;
  padding: 5rem 3rem 3rem;
}
.ph-season {
  font-family: "Lato", sans-serif;
  font-size: 0.68rem;
  font-weight: 300;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--champagne);
}
.ph-center {
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.ph-center h1 {
  font-family: "Playfair Display SC", serif;
  font-size: clamp(3rem, 7vw, 6rem);
  font-weight: 400;
  line-height: 1.1;
  letter-spacing: 0.02em;
  margin-bottom: 1.5rem;
}
.ph-center h1 em {
  font-style: italic;
  color: var(--champagne);
}
.ph-center p {
  font-size: 1rem;
  color: var(--text-light);
  line-height: 1.85;
  max-width: 450px;
  margin-bottom: 2.5rem;
  font-weight: 300;
}
.ph-bottom {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}
.ph-scroll {
  font-size: 0.65rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted-gold);
  white-space: nowrap;
}
.ph-scroll-line {
  flex: 1;
  max-width: 80px;
  height: 1px;
  background: var(--muted-gold);
  position: relative;
  overflow: hidden;
}
.ph-scroll-line::after {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 1px;
  background: var(--champagne);
  animation: line-move 2.5s ease-in-out infinite;
}
@keyframes line-move {
  0% {
    left: -100%;
  }
  100% {
    left: 100%;
  }
}

/* ── Panel Room ── */
.panel-room {
  display: grid;
  grid-template-columns: 1fr 1fr;
  background: var(--ivory);
  color: var(--text-dark);
}
.pr-image {
  height: 100%;
}
.pr-image--1 {
  background: linear-gradient(160deg, #2a2018 0%, #1a1810 50%, #281e10 100%);
}
.pr-content {
  padding: 5rem 3rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: auto;
}
.pr-content h2 {
  font-family: "Playfair Display SC", serif;
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 400;
  line-height: 1.15;
  margin-bottom: 1.5rem;
  color: var(--text-dark);
}
.pr-desc {
  font-size: 0.95rem;
  color: #5a5040;
  line-height: 1.85;
  margin-bottom: 2rem;
  font-weight: 300;
}
.pr-details {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-bottom: 2.5rem;
  border-top: 1px solid #d8d0c0;
}
.prd-item {
  display: flex;
  justify-content: space-between;
  padding: 0.75rem 0;
  border-bottom: 1px solid #d8d0c0;
}
.prd-item span:first-child {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #8a8070;
}
.prd-item span:last-child {
  font-size: 0.88rem;
  color: var(--text-dark);
}
.panel-room .panel-eyebrow {
  color: var(--gold);
}
.panel-room .btn-gold {
  color: var(--gold);
  border-color: var(--gold);
}
.panel-room .btn-gold:hover {
  background: var(--gold);
  color: var(--text-dark);
}

/* ── Panel Amenities ── */
.panel-amenities {
  background: var(--forest-mid);
  justify-content: center;
}
.pa-content {
  padding: 5rem 3rem;
  max-width: 900px;
  margin: 0 auto;
  width: 100%;
}
.pa-content h2 {
  font-family: "Playfair Display SC", serif;
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 400;
  line-height: 1.2;
  margin-bottom: 3rem;
}
.pa-content h2 em {
  font-style: italic;
  color: var(--champagne);
}
.amen-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}
.amen-item {
  padding: 1.5rem;
  border: 1px solid rgba(200, 160, 48, 0.15);
  transition: border-color 0.3s, background 0.3s;
}
.amen-item:hover {
  border-color: rgba(200, 160, 48, 0.4);
  background: rgba(200, 160, 48, 0.04);
}
.ai-icon {
  font-size: 1.2rem;
  color: var(--gold);
  margin-bottom: 0.75rem;
}
.ai-name {
  font-family: "Playfair Display SC", serif;
  font-size: 0.9rem;
  color: var(--champagne);
  margin-bottom: 0.5rem;
  letter-spacing: 0.05em;
}
.ai-desc {
  font-size: 0.78rem;
  color: var(--text-light);
  line-height: 1.65;
  font-weight: 300;
}

/* ── Panel Dining ── */
.panel-dining {
  display: grid;
  grid-template-columns: 1fr 1fr;
}
.pd-image {
  height: 100%;
}
.pd-image--1 {
  background: linear-gradient(145deg, #1a1208 0%, #100e06 50%, #1e1808 100%);
}
.pd-content {
  padding: 5rem 3rem;
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: auto;
}
.pd-content h2 {
  font-family: "Playfair Display SC", serif;
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 400;
  margin-bottom: 0.5rem;
}
.pd-stars {
  font-size: 1.5rem;
  color: var(--gold);
  margin-bottom: 1.5rem;
  letter-spacing: 0.3em;
}
.pd-content p {
  font-size: 0.95rem;
  color: var(--text-light);
  line-height: 1.85;
  margin-bottom: 1.5rem;
  font-weight: 300;
}
.pd-hours {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin-bottom: 2rem;
}
.pd-hours span {
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  color: var(--muted-gold);
}

/* ── Panel Contact ── */
.panel-contact {
  background: var(--forest-light);
  justify-content: center;
}
.pc2-content {
  padding: 5rem 3rem;
  max-width: 700px;
  margin: 0 auto;
  width: 100%;
  overflow: auto;
  max-height: 100vh;
}
.pc2-content h2 {
  font-family: "Playfair Display SC", serif;
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 400;
  line-height: 1.15;
  margin-bottom: 2rem;
}
.pc2-content h2 em {
  font-style: italic;
  color: var(--champagne);
}
.reservation-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 2.5rem;
}
.rf-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}
.rf-field {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.rf-field label {
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--muted-gold);
}
.rf-input-mock {
  height: 44px;
  background: rgba(248, 244, 236, 0.05);
  border: 1px solid rgba(200, 160, 48, 0.2);
  border-radius: 2px;
  transition: border-color 0.2s;
}
.rf-input-mock:hover {
  border-color: rgba(200, 160, 48, 0.5);
}
.rf-input-mock--tall {
  height: 100px;
}
.pc2-contact {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding-top: 2rem;
  border-top: 1px solid rgba(200, 160, 48, 0.15);
}
.pc2-contact span {
  font-size: 0.82rem;
  color: var(--muted-gold);
  font-weight: 300;
  letter-spacing: 0.04em;
}

@media (max-width: 900px) {
  .panel-room,
  .panel-dining {
    grid-template-columns: 1fr;
  }
  .pr-image,
  .pd-image {
    height: 40vh;
  }
  .amen-grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 600px) {
  .nav-links {
    display: none;
  }
  .nav {
    padding: 1rem 1.5rem;
  }
  .ph-content,
  .pr-content,
  .pa-content,
  .pd-content,
  .pc2-content {
    padding: 5rem 1.5rem 3rem;
  }
  .amen-grid {
    grid-template-columns: 1fr;
  }
  .rf-row {
    grid-template-columns: 1fr;
  }
}
html.reduced-motion .ph-scroll-line::after {
  animation: none;
}
html.reduced-motion * {
  transition-duration: 0.01ms !important;
}

